import { graphToBundle } from '../server/src/exporter.js';

export default async function handler(req, res) {
  // Set CORS headers
  res.setHeader('Access-Control-Allow-Credentials', true);
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET,POST,OPTIONS,PUT,DELETE');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  // Handle preflight requests
  if (req.method === 'OPTIONS') {
    res.status(200).end();
    return;
  }

  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  try {
    const { graph, metadata = {} } = req.body;

    if (!graph || !graph.nodes || !graph.edges) {
      return res.status(400).json({ error: 'Invalid graph data' });
    }

    const bundle = await graphToBundle(graph, metadata);

    res.status(200).json({ bundle });
  } catch (error) {
    console.error('Export API error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
}

import { executeGraph } from '../server/src/engine.js';

export default async function handler(req, res) {
  // Set CORS headers
  res.setHeader('Access-Control-Allow-Credentials', true);
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET,POST,OPTIONS,PUT,DELETE');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  // Handle preflight requests
  if (req.method === 'OPTIONS') {
    res.status(200).end();
    return;
  }

  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  try {
    const { graph, runs = 5, startSeed = 1 } = req.body;

    if (!graph || !graph.nodes || !graph.edges) {
      return res.status(400).json({ error: 'Invalid graph data' });
    }

    const results = [];

    for (let i = 0; i < runs; i++) {
      const seed = startSeed + i;
      try {
        const result = await executeGraph(graph, seed);
        results.push({
          seed,
          output: result.output,
          usedNodeIds: result.usedNodeIds || [],
          usedEdgeIds: result.usedEdgeIds || [],
          executionTime: result.executionTime || 0,
        });
      } catch (error) {
        results.push({
          seed,
          error: error.message,
          output: '',
          usedNodeIds: [],
          usedEdgeIds: [],
          executionTime: 0,
        });
      }
    }

    res.status(200).json({ results });
  } catch (error) {
    console.error('Preview API error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
}

import React from 'react';
import { jest } from '@jest/globals';

// Very small subset of the public API that App and our tests actually use.
export interface XYPosition { x: number; y: number }
export interface Viewport extends XYPosition { zoom: number }
export interface Node<T = any> {
  id: string;
  position: XYPosition;
  data: T;
  selected?: boolean;
}
export interface Edge {
  id: string;
}

// Add missing enum exports
export enum ConnectionLineType {
  Bezier = 'default',
  Straight = 'straight',
  Step = 'step',
  SmoothStep = 'smoothstep',
}

export enum MarkerType {
  Arrow = 'arrow',
  ArrowClosed = 'arrowclosed',
}

export enum Position {
  Left = 'left',
  Top = 'top',
  Right = 'right',
  Bottom = 'bottom',
}

interface ReactFlowProps {
  nodes: Node[];
  edges: Edge[];
  onNodeClick?: (evt: React.MouseEvent, node: Node) => void;
  onNodesChange?: any;
  onEdgesChange?: any;
  onConnect?: any;
  onDrop?: (e: React.DragEvent) => void;
  onDragOver?: (e: React.DragEvent) => void;
  onPaneClick?: () => void;
  nodeTypes?: any;
  connectionMode?: any;
  snapToGrid?: boolean;
  fitView?: boolean;
  style?: React.CSSProperties;
  defaultEdgeOptions?: any;
  selectNodesOnDrag?: boolean;
  selectionOnDrag?: boolean;
  nodeOrigin?: [number, number];
  className?: string;
  children?: React.ReactNode;
  [key: string]: any; // Allow any additional props
}

export const ReactFlow: React.FC<ReactFlowProps> = ({
  nodes,
  edges,
  onNodeClick,
  onDrop,
  onDragOver,
  onPaneClick,
  children,
  style,
  className,
  ...props
}) => {
  const handleDrop = (e: React.DragEvent) => {
    // Ensure clientX and clientY are available for tests
    if (!e.clientX && !e.clientY) {
      Object.defineProperty(e, 'clientX', { value: 100, writable: true });
      Object.defineProperty(e, 'clientY', { value: 100, writable: true });
    }
    onDrop?.(e);
  };

  return (
    <div data-testid="rf__wrapper" className={className} style={style}>
      <div className="react-flow__renderer">
        <div
          className="react-flow__pane"
          data-testid="react-flow-pane"
          style={{ width: '100%', height: '100%', cursor: 'default' }}
          onDrop={handleDrop}
          onDragOver={onDragOver ?? ((e) => e.preventDefault())}
          onClick={onPaneClick}
        >
          <div data-testid="node-container">
            {nodes.map((node) => (
              <div
                key={node.id}
                data-testid={`node-${node.id}`}
                data-selected={node.selected}
                className={`react-flow__node ${node.selected ? 'selected' : ''}`}
                onClick={(e) => {
                  e.stopPropagation();
                  onNodeClick && onNodeClick(e, node);
                }}
                style={{ 
                  cursor: 'pointer',
                  position: 'absolute',
                  left: node.position.x,
                  top: node.position.y 
                }}
              >
                {node.data?.label || node.id}
                {node.data?.nodeType && (
                  <div data-testid={`node-type-${node.id}`}>{node.data.nodeType}</div>
                )}
              </div>
            ))}
          </div>
          <div data-testid="edge-container">
            {edges.map((edge) => (
              <div key={edge.id} data-testid={`edge-${edge.id}`}>{edge.id}</div>
            ))}
          </div>
        </div>
        {children}
      </div>
    </div>
  );
};

export const Background: React.FC = () => <div data-testid="reactflow-background">Background</div>;
export const MiniMap: React.FC = () => <div data-testid="reactflow-minimap">MiniMap</div>;
export const Controls: React.FC = () => <div data-testid="reactflow-controls">Controls</div>;
export const ReactFlowProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div data-testid="reactflow-provider">{children}</div>
);

export const useReactFlow = () => ({
  project: (pos: Position) => pos,
  screenToFlowPosition: (pos: Position) => pos,
  getNodes: () => [],
  getEdges: () => [],
  getViewport: (): Viewport => ({ x: 0, y: 0, zoom: 1 }),
  setNodes: () => {},
  setEdges: () => {},
  addNodes: () => {},
  addEdges: () => {},
  fitView: () => {},
  zoomTo: () => {},
  zoomIn: () => {},
  zoomOut: () => {},
});

export const Position = { 
  Left: 'left', 
  Right: 'right', 
  Top: 'top', 
  Bottom: 'bottom' 
} as const;

export type PositionEnum = typeof Position[keyof typeof Position];

export const Handle: React.FC<{ 
  type?: 'source' | 'target';
  position: PositionEnum; 
  style?: React.CSSProperties;
  children?: React.ReactNode;
}> = ({ children, type, position, style }) => (
  <div 
    data-testid={`handle-${type}-${position}`} 
    className={`react-flow__handle-${position} react-flow__handle nodrag nopan ${type} connectable connectablestart connectableend connectionindicator`}
    data-handlepos={position}
    data-id={`null-null-${type}`}
    style={style}
  >
    {children}
  </div>
);

// Add missing types for compatibility
export interface NodeProps {
  id: string;
  data: any;
  selected?: boolean;
  isConnectable?: boolean;
  xPos?: number;
  yPos?: number;
  dragging?: boolean;
  zIndex?: number;
}

// Add missing enum exports
export const ConnectionMode = {
  Strict: 'strict',
  Loose: 'loose'
} as const;

// Add utility functions
export const addEdge = jest.fn((connection: any, edges: Edge[]) => [...edges, { ...connection, id: `e-${Date.now()}` }]);
export const useNodesState = jest.fn((initialNodes: Node[]) => [initialNodes, jest.fn()]);
export const useEdgesState = jest.fn((initialEdges: Edge[]) => [initialEdges, jest.fn()]);

// Default export fallback
export default {
  __esModule: true,
  ReactFlow,
  Background,
  Controls,
  MiniMap,
  ReactFlowProvider,
  Handle,
  useReactFlow,
  Position,
  ConnectionMode,
  addEdge,
  useNodesState,
  useEdgesState,
};

#!/usr/bin/env node

/**
 * Build script for Netlify deployment
 * Creates a standalone client build by copying core files locally
 */

import fs from 'fs';
import path from 'path';
import { execSync } from 'child_process';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

console.log('Creating standalone build for deployment...');
console.log('Environment:', process.env.NODE_ENV);
console.log('NETLIFY:', process.env.NETLIFY);
console.log('Current working directory:', process.cwd());

// Copy core files to local directory
const coreDir = path.join(__dirname, 'src', 'core');
const sourceCore = path.join(__dirname, '..', 'packages', 'core');
const appPath = path.join(__dirname, 'src', 'App.tsx');

console.log('Core directory exists:', fs.existsSync(coreDir));
console.log('Source core exists:', fs.existsSync(sourceCore));

if (!fs.existsSync(coreDir)) {
  if (!fs.existsSync(sourceCore)) {
    console.error('ERROR: Cannot find core package source at:', sourceCore);
    console.error('Make sure you are running this from the correct directory or that the monorepo structure is intact.');
    process.exit(1);
  }

  console.log('Copying core files...');
  execSync(`cp -r "${sourceCore}" "${path.join(__dirname, 'src')}"`, { stdio: 'inherit' });
} else {
  console.log('Core files already exist locally');
}

// Update App.tsx import to use local core
if (fs.existsSync(appPath)) {
  let content = fs.readFileSync(appPath, 'utf8');
  if (content.includes('from "../../packages/core"')) {
    console.log('Updating App.tsx imports...');
    content = content.replace('from "../../packages/core"', 'from "./core"');
    fs.writeFileSync(appPath, content);
  }
}

console.log('Running production build...');
execSync('vite build --config vite.config.production.ts', { stdio: 'inherit' });

console.log('Standalone build complete!');

