// Helper to create proper drag events with coordinates
const createDragEvent = (type, clientX, clientY, dataTransferData) => {
    const event = new MouseEvent(type, {
        bubbles: true,
        cancelable: true,
        clientX,
        clientY,
    });
    // Add dataTransfer for drag events
    event.dataTransfer = {
        getData: (format) => {
            if (format === 'application/reactflow' || format === 'application/node-type') {
                return dataTransferData;
            }
            return '';
        },
        setData: jest.fn(),
        dropEffect: 'move',
