// Epic 11.2 Account Linking Component
// Interface for linking and unlinking OAuth provider accounts

import React, { useState, useEffect } from 'react';
import { useAuth } from '../../hooks/useAuth';

interface LinkedAccount {
  provider: string;
  email: string;
  name?: string;
  picture?: string;
  createdAt: string;
  updatedAt: string;
}

interface OAuthProvider {
  name: string;
  displayName: string;
  icon: string;
  color: string;
}

interface AccountLinkingProps {
  onAccountLinked?: (provider: string) => void;
  onAccountUnlinked?: (provider: string) => void;
}

export const AccountLinking: React.FC<AccountLinkingProps> = ({
  onAccountLinked,
  onAccountUnlinked,
}) => {
  const { user } = useAuth();
  const [linkedAccounts, setLinkedAccounts] = useState<LinkedAccount[]>([]);
  const [availableProviders, setAvailableProviders] = useState<OAuthProvider[]>([]);
  const [loading, setLoading] = useState(true);
  const [linking, setLinking] = useState<string | null>(null);
  const [unlinking, setUnlinking] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (user) {
      fetchLinkedAccounts();
      fetchAvailableProviders();
    }
  }, [user]);

  const fetchLinkedAccounts = async () => {
    try {
      const response = await fetch('/api/auth/oauth/accounts', {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('access_token')}`,
        },
      });

      if (!response.ok) {
        throw new Error('Failed to fetch linked accounts');
      }

      const data = await response.json();
      setLinkedAccounts(data.accounts);
    } catch (error) {
      console.error('Error fetching linked accounts:', error);
      setError('Failed to load linked accounts');
    }
  };

  const fetchAvailableProviders = async () => {
    try {
      const response = await fetch('/api/auth/oauth/providers');

      if (!response.ok) {
        throw new Error('Failed to fetch available providers');
      }

      const data = await response.json();
      setAvailableProviders(data.providers);
    } catch (error) {
      console.error('Error fetching available providers:', error);
    } finally {
      setLoading(false);
    }
  };

  const linkAccount = async (provider: string) => {
    try {
      setLinking(provider);
      setError(null);

      // Generate OAuth authorization URL
      const authResponse = await fetch(`/api/auth/oauth/authorize?provider=${provider}`, {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('access_token')}`,
        },
      });

      if (!authResponse.ok) {
        throw new Error('Failed to initialize OAuth flow');
      }

      const authData = await authResponse.json();

      // Redirect to OAuth provider
      window.location.href = authData.url;
    } catch (error) {
      console.error('Error linking account:', error);
      setError(`Failed to link ${provider} account`);
      setLinking(null);
    }
  };

  const unlinkAccount = async (provider: string) => {
    try {
      setUnlinking(provider);
      setError(null);

      const response = await fetch('/api/auth/oauth/unlink', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('access_token')}`,
        },
        body: JSON.stringify({ provider }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || 'Failed to unlink account');
      }

      // Remove from local state
      setLinkedAccounts(prev => prev.filter(acc => acc.provider !== provider));
      onAccountUnlinked?.(provider);
    } catch (error) {
      console.error('Error unlinking account:', error);
      setError(error.message || `Failed to unlink ${provider} account`);
    } finally {
      setUnlinking(null);
    }
  };

  const getProviderIcon = (provider: string) => {
    const icons = {
      google: '🔍',
      github: '🐙',
      microsoft: '🏢',
    };
    return icons[provider as keyof typeof icons] || '🔗';
  };

  const getProviderColor = (provider: string) => {
    const colors = {
      google: 'bg-red-50 border-red-200 text-red-700',
      github: 'bg-gray-50 border-gray-200 text-gray-700',
      microsoft: 'bg-blue-50 border-blue-200 text-blue-700',
    };
    return colors[provider as keyof typeof colors] || 'bg-gray-50 border-gray-200 text-gray-700';
  };

  const isLinked = (provider: string) => {
    return linkedAccounts.some(acc => acc.provider === provider);
  };

  const getLinkedAccount = (provider: string) => {
    return linkedAccounts.find(acc => acc.provider === provider);
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center p-8">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto space-y-6">
      {/* Header */}
      <div className="bg-white rounded-lg shadow-md p-6">
        <h2 className="text-xl font-semibold text-gray-900 mb-2">Connected Accounts</h2>
        <p className="text-gray-600">
          Link your accounts from other services to enable single sign-on and sync your data.
        </p>
      </div>

      {/* Error Message */}
      {error && (
        <div className="bg-red-50 border border-red-200 rounded-lg p-4">
          <div className="flex items-center text-red-700">
            <span className="mr-2">❌</span>
            {error}
          </div>
        </div>
      )}

      {/* OAuth Providers */}
      <div className="bg-white rounded-lg shadow-md p-6">
        <h3 className="text-lg font-medium text-gray-900 mb-4">OAuth Providers</h3>

        <div className="space-y-4">
          {availableProviders.map((provider) => {
            const linked = isLinked(provider.name);
            const linkedAccount = getLinkedAccount(provider.name);

            return (
              <div
                key={provider.name}
                className={`border rounded-lg p-4 ${
                  linked 
                    ? 'border-green-200 bg-green-50' 
                    : 'border-gray-200 bg-white'
                }`}
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-3">
                    <div className={`w-10 h-10 rounded-full flex items-center justify-center ${getProviderColor(provider.name)}`}>
                      <span className="text-lg">{getProviderIcon(provider.name)}</span>
                    </div>

                    <div>
                      <h4 className="font-medium text-gray-900">{provider.displayName}</h4>
                      {linked && linkedAccount ? (
                        <div className="text-sm text-gray-600">
                          <div className="flex items-center space-x-2">
                            {linkedAccount.picture && (
                              <img
                                src={linkedAccount.picture}
                                alt={linkedAccount.name}
                                className="w-4 h-4 rounded-full"
                              />
                            )}
                            <span>{linkedAccount.name || linkedAccount.email}</span>
                          </div>
                          <div className="text-xs text-gray-500">
                            Connected {new Date(linkedAccount.createdAt).toLocaleDateString()}
                          </div>
                        </div>
                      ) : (
                        <p className="text-sm text-gray-600">
                          Link your {provider.displayName} account for easy sign-in
                        </p>
                      )}
                    </div>
                  </div>

                  <div className="flex items-center space-x-2">
                    {linked ? (
                      <>
                        <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-green-100 text-green-800">
                          Connected
                        </span>
                        <button
                          onClick={() => unlinkAccount(provider.name)}
                          disabled={unlinking === provider.name}
                          className={`px-3 py-1 text-sm font-medium rounded-md ${
                            unlinking === provider.name
                              ? 'bg-gray-100 text-gray-400 cursor-not-allowed'
                              : 'bg-red-50 text-red-700 hover:bg-red-100'
                          }`}
                        >
                          {unlinking === provider.name ? 'Unlinking...' : 'Unlink'}
                        </button>
                      </>
                    ) : (
                      <button
                        onClick={() => linkAccount(provider.name)}
                        disabled={linking === provider.name}
                        className={`px-4 py-2 text-sm font-medium rounded-md ${
                          linking === provider.name
                            ? 'bg-gray-100 text-gray-400 cursor-not-allowed'
                            : 'bg-blue-600 text-white hover:bg-blue-700'
                        }`}
                      >
                        {linking === provider.name ? 'Linking...' : 'Link Account'}
                      </button>
                    )}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Security Notice */}
      <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
        <div className="flex items-start space-x-3">
          <div className="flex-shrink-0">
            <span className="text-blue-600 text-lg">🔒</span>
          </div>
          <div>
            <h3 className="text-sm font-medium text-blue-800">Security Information</h3>
            <div className="text-sm text-blue-700 mt-1">
              <ul className="list-disc list-inside space-y-1">
                <li>Linked accounts allow you to sign in using those services</li>
                <li>We only access basic profile information from linked accounts</li>
                <li>You can unlink accounts at any time</li>
                <li>Make sure you have another authentication method before unlinking all accounts</li>
              </ul>
            </div>
          </div>
        </div>
      </div>

      {/* Account Statistics */}
      {linkedAccounts.length > 0 && (
        <div className="bg-white rounded-lg shadow-md p-6">
          <h3 className="text-lg font-medium text-gray-900 mb-4">Account Statistics</h3>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="text-center">
              <div className="text-2xl font-bold text-blue-600">{linkedAccounts.length}</div>
              <div className="text-sm text-gray-600">Connected Accounts</div>
            </div>

            <div className="text-center">
              <div className="text-2xl font-bold text-green-600">
                {availableProviders.length - linkedAccounts.length}
              </div>
              <div className="text-sm text-gray-600">Available to Link</div>
            </div>

            <div className="text-center">
              <div className="text-2xl font-bold text-purple-600">
                {linkedAccounts.length > 0 ? 
                  Math.round((linkedAccounts.length / availableProviders.length) * 100) : 0
                }%
              </div>
              <div className="text-sm text-gray-600">Integration Level</div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AccountLinking;

// Epic 11 Account Recovery Component
// Handles account unlock and password reset workflows

import React, { useState, useEffect } from 'react';
import { z } from 'zod';

// Recovery form validation schemas
const unlockAccountSchema = z.object({
  email: z.string().email('Please enter a valid email address'),
  unlockToken: z.string().min(1, 'Unlock token is required'),
});

const requestUnlockSchema = z.object({
  email: z.string().email('Please enter a valid email address'),
});

type UnlockAccountData = z.infer<typeof unlockAccountSchema>;
type RequestUnlockData = z.infer<typeof requestUnlockSchema>;

interface AccountRecoveryProps {
  onSuccess?: (message: string) => void;
  onError?: (error: string) => void;
  initialEmail?: string;
  unlockToken?: string;
}

type RecoveryMode = 'request' | 'unlock' | 'success';

export const AccountRecovery: React.FC<AccountRecoveryProps> = ({
  onSuccess,
  onError,
  initialEmail = '',
  unlockToken = '',
}) => {
  const [mode, setMode] = useState<RecoveryMode>(unlockToken ? 'unlock' : 'request');
  const [isLoading, setIsLoading] = useState(false);
  const [countdown, setCountdown] = useState(0);

  const [requestData, setRequestData] = useState<RequestUnlockData>({
    email: initialEmail,
  });

  const [unlockData, setUnlockData] = useState<UnlockAccountData>({
    email: initialEmail,
    unlockToken: unlockToken,
  });

  const [errors, setErrors] = useState<{
    request?: Partial<Record<keyof RequestUnlockData, string>>;
    unlock?: Partial<Record<keyof UnlockAccountData, string>>;
  }>({});

  // Handle countdown for resend button
  useEffect(() => {
    let timer: NodeJS.Timeout;
    if (countdown > 0) {
      timer = setTimeout(() => setCountdown(prev => prev - 1), 1000);
    }
    return () => clearTimeout(timer);
  }, [countdown]);

  const validateRequestForm = (): boolean => {
    try {
      requestUnlockSchema.parse(requestData);
      setErrors(prev => ({ ...prev, request: {} }));
      return true;
    } catch (error) {
      if (error instanceof z.ZodError) {
        const newErrors: Partial<Record<keyof RequestUnlockData, string>> = {};
        error.errors.forEach(err => {
          if (err.path[0]) {
            newErrors[err.path[0] as keyof RequestUnlockData] = err.message;
          }
        });
        setErrors(prev => ({ ...prev, request: newErrors }));
      }
      return false;
    }
  };

  const validateUnlockForm = (): boolean => {
    try {
      unlockAccountSchema.parse(unlockData);
      setErrors(prev => ({ ...prev, unlock: {} }));
      return true;
    } catch (error) {
      if (error instanceof z.ZodError) {
        const newErrors: Partial<Record<keyof UnlockAccountData, string>> = {};
        error.errors.forEach(err => {
          if (err.path[0]) {
            newErrors[err.path[0] as keyof UnlockAccountData] = err.message;
          }
        });
        setErrors(prev => ({ ...prev, unlock: newErrors }));
      }
      return false;
    }
  };

  const handleRequestUnlock = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validateRequestForm()) {
      return;
    }

    setIsLoading(true);

    try {
      const response = await fetch('/api/auth/request-unlock', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(requestData),
      });

      const result = await response.json();

      if (!response.ok) {
        throw new Error(result.message || 'Failed to request account unlock');
      }

      setCountdown(300); // 5 minutes before allowing resend
      setMode('success');
      onSuccess?.('Account unlock instructions have been sent to your email address.');

    } catch (error: any) {
      onError?.(error.message || 'Failed to request account unlock');
    } finally {
      setIsLoading(false);
    }
  };

  const handleUnlockAccount = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validateUnlockForm()) {
      return;
    }

    setIsLoading(true);

    try {
      const response = await fetch('/api/auth/unlock-account', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(unlockData),
      });

      const result = await response.json();

      if (!response.ok) {
        throw new Error(result.message || 'Failed to unlock account');
      }

      setMode('success');
      onSuccess?.('Your account has been successfully unlocked. You can now sign in.');

    } catch (error: any) {
      onError?.(error.message || 'Failed to unlock account');
    } finally {
      setIsLoading(false);
    }
  };

  const formatCountdown = (seconds: number): string => {
    const minutes = Math.floor(seconds / 60);
    const remainingSeconds = seconds % 60;
    return `${minutes}:${remainingSeconds.toString().padStart(2, '0')}`;
  };

  if (mode === 'success') {
    return (
      <div className="max-w-md mx-auto bg-white rounded-lg shadow-md p-6">
        <div className="text-center">
          <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-green-100">
            <svg className="h-6 w-6 text-green-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
            </svg>
          </div>
          <h2 className="mt-4 text-2xl font-bold text-gray-900">Request Sent</h2>
          <p className="mt-2 text-gray-600">
            We've sent account recovery instructions to your email address.
          </p>
          <p className="mt-4 text-sm text-gray-500">
            Check your email and follow the instructions to unlock your account.
            If you don't see the email, check your spam folder.
          </p>

          {countdown > 0 && (
            <div className="mt-4 p-3 bg-blue-50 border border-blue-200 rounded-md">
              <p className="text-sm text-blue-700">
                You can request another unlock email in {formatCountdown(countdown)}
              </p>
            </div>
          )}

          <div className="mt-6 space-y-3">
            {countdown === 0 && (
              <button
                onClick={() => setMode('request')}
                className="w-full py-2 px-4 border border-blue-300 rounded-md shadow-sm text-sm font-medium text-blue-700 bg-white hover:bg-blue-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
              >
                Send Another Email
              </button>
            )}

            <a
              href="/auth/login"
              className="block w-full py-2 px-4 border border-gray-300 rounded-md shadow-sm text-sm font-medium text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 text-center"
            >
              Back to Login
            </a>
          </div>
        </div>
      </div>
    );
  }

  if (mode === 'unlock') {
    return (
      <div className="max-w-md mx-auto bg-white rounded-lg shadow-md p-6">
        <div className="text-center mb-6">
          <h2 className="text-2xl font-bold text-gray-900">Unlock Account</h2>
          <p className="text-gray-600 mt-2">Enter your unlock token to restore access</p>
        </div>

        <form onSubmit={handleUnlockAccount} className="space-y-4">
          {/* Email Field */}
          <div>
            <label htmlFor="unlock-email" className="block text-sm font-medium text-gray-700 mb-1">
              Email Address
            </label>
            <input
              type="email"
              id="unlock-email"
              value={unlockData.email}
              onChange={(e) => setUnlockData(prev => ({ ...prev, email: e.target.value }))}
              className={`w-full px-3 py-2 border rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 ${
                errors.unlock?.email ? 'border-red-300 focus:border-red-500' : 'border-gray-300'
              }`}
              placeholder="Enter your email address"
              disabled={isLoading}
              required
            />
            {errors.unlock?.email && (
              <p className="mt-1 text-sm text-red-600">{errors.unlock.email}</p>
            )}
          </div>

          {/* Unlock Token Field */}
          <div>
            <label htmlFor="unlock-token" className="block text-sm font-medium text-gray-700 mb-1">
              Unlock Token
            </label>
            <input
              type="text"
              id="unlock-token"
              value={unlockData.unlockToken}
              onChange={(e) => setUnlockData(prev => ({ ...prev, unlockToken: e.target.value }))}
              className={`w-full px-3 py-2 border rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 ${
                errors.unlock?.unlockToken ? 'border-red-300 focus:border-red-500' : 'border-gray-300'
              }`}
              placeholder="Enter the unlock token from your email"
              disabled={isLoading}
              required
            />
            {errors.unlock?.unlockToken && (
              <p className="mt-1 text-sm text-red-600">{errors.unlock.unlockToken}</p>
            )}
          </div>

          {/* Submit Button */}
          <button
            type="submit"
            disabled={isLoading}
            className={`w-full py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 ${
              isLoading
                ? 'bg-gray-400 cursor-not-allowed'
                : 'bg-blue-600 hover:bg-blue-700'
            }`}
          >
            {isLoading ? (
              <div className="flex items-center justify-center">
                <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                Unlocking Account...
              </div>
            ) : (
              'Unlock Account'
            )}
          </button>
        </form>

        <div className="mt-6 text-center">
          <button
            onClick={() => setMode('request')}
            className="text-sm text-blue-600 hover:text-blue-500"
          >
            Don't have an unlock token? Request one
          </button>
        </div>
      </div>
    );
  }

  // Request unlock mode
  return (
    <div className="max-w-md mx-auto bg-white rounded-lg shadow-md p-6">
      <div className="text-center mb-6">
        <h2 className="text-2xl font-bold text-gray-900">Account Recovery</h2>
        <p className="text-gray-600 mt-2">Request an unlock token for your account</p>
      </div>

      <div className="mb-4 p-4 bg-blue-50 border border-blue-200 rounded-md">
        <div className="flex items-start">
          <div className="flex-shrink-0">
            <svg className="h-5 w-5 text-blue-400" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
            </svg>
          </div>
          <div className="ml-3">
            <h3 className="text-sm font-medium text-blue-800">Account Locked?</h3>
            <p className="text-sm text-blue-700 mt-1">
              If your account is locked due to multiple failed login attempts, 
              we can send you instructions to unlock it safely.
            </p>
          </div>
        </div>
      </div>

      <form onSubmit={handleRequestUnlock} className="space-y-4">
        {/* Email Field */}
        <div>
          <label htmlFor="request-email" className="block text-sm font-medium text-gray-700 mb-1">
            Email Address
          </label>
          <input
            type="email"
            id="request-email"
            value={requestData.email}
            onChange={(e) => setRequestData(prev => ({ ...prev, email: e.target.value }))}
            className={`w-full px-3 py-2 border rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 ${
              errors.request?.email ? 'border-red-300 focus:border-red-500' : 'border-gray-300'
            }`}
            placeholder="Enter your email address"
            disabled={isLoading}
            required
          />
          {errors.request?.email && (
            <p className="mt-1 text-sm text-red-600">{errors.request.email}</p>
          )}
        </div>

        {/* Submit Button */}
        <button
          type="submit"
          disabled={isLoading || countdown > 0}
          className={`w-full py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 ${
            isLoading || countdown > 0
              ? 'bg-gray-400 cursor-not-allowed'
              : 'bg-blue-600 hover:bg-blue-700'
          }`}
        >
          {isLoading ? (
            <div className="flex items-center justify-center">
              <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
              </svg>
              Sending Request...
            </div>
          ) : countdown > 0 ? (
            `Wait ${formatCountdown(countdown)} to resend`
          ) : (
            'Send Unlock Instructions'
          )}
        </button>
      </form>

      <div className="mt-6 text-center space-y-2">
        <div>
          <a
            href="/auth/login"
            className="text-sm text-blue-600 hover:text-blue-500"
          >
            Back to Login
          </a>
        </div>

        <div className="text-sm text-gray-600">
          Remember your password?{' '}
          <a
            href="/auth/forgot-password"
            className="text-blue-600 hover:text-blue-500"
          >
            Reset it instead
          </a>
        </div>
      </div>

      {/* Security Notice */}
      <div className="mt-4 p-3 bg-gray-50 border border-gray-200 rounded-md">
        <p className="text-xs text-gray-600 text-center">
          🔒 Account unlock requests are securely processed and logged for your protection.
        </p>
      </div>
    </div>
  );
};

export default AccountRecovery;

// Epic 11 API Token Manager Component
// React component for managing API tokens with scope-based authorization

import React, { useState, useEffect } from 'react';
import { useAuth } from '../../hooks/useAuth';

interface ApiToken {
  id: string;
  name: string;
  scopes: string[];
  expiresAt: string;
  createdAt: string;
  lastUsedAt?: string;
  revoked: boolean;
}

interface ApiTokenStats {
  totalTokens: number;
  activeTokens: number;
  revokedTokens: number;
  expiredTokens: number;
  recentlyUsed: any[];
}

interface Scope {
  name: string;
  description: string;
  category: string;
}

interface ApiTokenManagerProps {
  onTokenCreated?: (token: ApiToken) => void;
  onTokenRevoked?: (tokenId: string) => void;
}

export const ApiTokenManager: React.FC<ApiTokenManagerProps> = ({
  onTokenCreated,
  onTokenRevoked,
}) => {
  const { user } = useAuth();
  const [tokens, setTokens] = useState<ApiToken[]>([]);
  const [stats, setStats] = useState<ApiTokenStats | null>(null);
  const [availableScopes, setAvailableScopes] = useState<Scope[]>([]);
  const [loading, setLoading] = useState(true);
  const [creating, setCreating] = useState(false);
  const [revoking, setRevoking] = useState<string | null>(null);
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [newToken, setNewToken] = useState<{ token: string; tokenId: string } | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Form state
  const [tokenName, setTokenName] = useState('');
  const [selectedScopes, setSelectedScopes] = useState<string[]>([]);
  const [expiresIn, setExpiresIn] = useState('90d');

  useEffect(() => {
    if (user) {
      fetchTokens();
      fetchStats();
      fetchAvailableScopes();
    }
  }, [user]);

  const fetchTokens = async () => {
    try {
      const response = await fetch('/api/auth/api-tokens', {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('access_token')}`,
        },
      });

      if (!response.ok) {
        throw new Error('Failed to fetch tokens');
      }

      const data = await response.json();
      setTokens(data.tokens);
    } catch (error) {
      console.error('Error fetching tokens:', error);
      setError('Failed to load API tokens');
    } finally {
      setLoading(false);
    }
  };

  const fetchStats = async () => {
    try {
      const response = await fetch('/api/auth/api-tokens/stats', {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('access_token')}`,
        },
      });

      if (response.ok) {
        const data = await response.json();
        setStats(data);
      }
    } catch (error) {
      console.error('Error fetching stats:', error);
    }
  };

  const fetchAvailableScopes = async () => {
    try {
      const response = await fetch('/api/auth/api-tokens/scopes');
      if (response.ok) {
        const data = await response.json();
        setAvailableScopes(data.scopes);
      }
    } catch (error) {
      console.error('Error fetching scopes:', error);
    }
  };

  const createToken = async () => {
    if (!tokenName.trim() || selectedScopes.length === 0) {
      setError('Please provide a token name and select at least one scope');
      return;
    }

    try {
      setCreating(true);
      setError(null);

      const response = await fetch('/api/auth/api-tokens', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('access_token')}`,
        },
        body: JSON.stringify({
          name: tokenName,
          scopes: selectedScopes,
          expiresIn,
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || 'Failed to create token');
      }

      const data = await response.json();
      setNewToken({ token: data.token, tokenId: data.tokenId });

      // Refresh token list
      await fetchTokens();
      await fetchStats();

      // Reset form
      setTokenName('');
      setSelectedScopes([]);
      setExpiresIn('90d');

      onTokenCreated?.(data);
    } catch (error) {
      console.error('Error creating token:', error);
      setError(error.message || 'Failed to create token');
    } finally {
      setCreating(false);
    }
  };

  const revokeToken = async (tokenId: string) => {
    try {
      setRevoking(tokenId);

      const response = await fetch('/api/auth/api-tokens/revoke', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('access_token')}`,
        },
        body: JSON.stringify({ tokenId }),
      });

      if (!response.ok) {
        throw new Error('Failed to revoke token');
      }

      // Update local state
      setTokens(tokens.map(token => 
        token.id === tokenId ? { ...token, revoked: true } : token
      ));

      await fetchStats();
      onTokenRevoked?.(tokenId);
    } catch (error) {
      console.error('Error revoking token:', error);
      setError('Failed to revoke token');
    } finally {
      setRevoking(null);
    }
  };

  const handleScopeToggle = (scope: string) => {
    setSelectedScopes(prev => 
      prev.includes(scope) 
        ? prev.filter(s => s !== scope)
        : [...prev, scope]
    );
  };

  const formatExpiresAt = (dateString: string) => {
    const date = new Date(dateString);
    const now = new Date();
    const isExpired = date < now;

    const formatted = date.toLocaleDateString();
    return isExpired ? `${formatted} (Expired)` : formatted;
  };

  const formatLastUsed = (dateString?: string) => {
    if (!dateString) return 'Never';

    const date = new Date(dateString);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));

    if (diffDays === 0) return 'Today';
    if (diffDays === 1) return 'Yesterday';
    if (diffDays < 7) return `${diffDays} days ago`;
    return date.toLocaleDateString();
  };

  const getScopesByCategory = () => {
    const categories = availableScopes.reduce((acc, scope) => {
      if (!acc[scope.category]) {
        acc[scope.category] = [];
      }
      acc[scope.category].push(scope);
      return acc;
    }, {} as Record<string, Scope[]>);

    return categories;
  };

  const getScopeBadgeColor = (scope: string) => {
    if (scope === '*') return 'bg-red-100 text-red-800';
    if (scope.startsWith('admin:')) return 'bg-purple-100 text-purple-800';
    if (scope.startsWith('graphs:')) return 'bg-blue-100 text-blue-800';
    if (scope.startsWith('user:')) return 'bg-green-100 text-green-800';
    if (scope.startsWith('organizations:')) return 'bg-yellow-100 text-yellow-800';
    if (scope.startsWith('teams:')) return 'bg-indigo-100 text-indigo-800';
    return 'bg-gray-100 text-gray-800';
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center p-8">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex justify-between items-center">
        <h3 className="text-lg font-semibold text-gray-900">API Tokens</h3>
        <button
          onClick={() => setShowCreateForm(!showCreateForm)}
          className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 font-medium"
        >
          {showCreateForm ? 'Cancel' : 'Create Token'}
        </button>
      </div>

      {/* Statistics */}
      {stats && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="bg-blue-50 p-4 rounded-lg">
            <div className="text-2xl font-bold text-blue-600">{stats.activeTokens}</div>
            <div className="text-sm text-blue-600">Active</div>
          </div>
          <div className="bg-green-50 p-4 rounded-lg">
            <div className="text-2xl font-bold text-green-600">{stats.totalTokens}</div>
            <div className="text-sm text-green-600">Total</div>
          </div>
          <div className="bg-red-50 p-4 rounded-lg">
            <div className="text-2xl font-bold text-red-600">{stats.revokedTokens}</div>
            <div className="text-sm text-red-600">Revoked</div>
          </div>
          <div className="bg-yellow-50 p-4 rounded-lg">
            <div className="text-2xl font-bold text-yellow-600">{stats.expiredTokens}</div>
            <div className="text-sm text-yellow-600">Expired</div>
          </div>
        </div>
      )}

      {/* New Token Display */}
      {newToken && (
        <div className="bg-green-50 border border-green-200 rounded-lg p-4">
          <div className="flex items-center justify-between mb-2">
            <h4 className="font-medium text-green-800">Token Created Successfully</h4>
            <button
              onClick={() => setNewToken(null)}
              className="text-green-600 hover:text-green-800"
            >
              ✕
            </button>
          </div>
          <div className="bg-white p-3 rounded border font-mono text-sm break-all">
            {newToken.token}
          </div>
          <p className="text-sm text-green-700 mt-2">
            ⚠️ Store this token securely. It will not be shown again.
          </p>
        </div>
      )}

      {/* Create Token Form */}
      {showCreateForm && (
        <div className="border border-gray-200 rounded-lg p-6 bg-gray-50">
          <h4 className="font-medium text-gray-900 mb-4">Create New API Token</h4>

          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Token Name
              </label>
              <input
                type="text"
                value={tokenName}
                onChange={(e) => setTokenName(e.target.value)}
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                placeholder="e.g., My Integration Token"
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Expires In
              </label>
              <select
                value={expiresIn}
                onChange={(e) => setExpiresIn(e.target.value)}
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option value="30d">30 days</option>
                <option value="90d">90 days</option>
                <option value="1y">1 year</option>
                <option value="2y">2 years</option>
              </select>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Scopes
              </label>
              <div className="space-y-3">
                {Object.entries(getScopesByCategory()).map(([category, scopes]) => (
                  <div key={category} className="border border-gray-200 rounded-lg p-3">
                    <h5 className="font-medium text-gray-900 mb-2 capitalize">{category}</h5>
                    <div className="space-y-2">
                      {scopes.map((scope) => (
                        <label key={scope.name} className="flex items-start space-x-2">
                          <input
                            type="checkbox"
                            checked={selectedScopes.includes(scope.name)}
                            onChange={() => handleScopeToggle(scope.name)}
                            className="mt-1 h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300 rounded"
                          />
                          <div className="flex-1 min-w-0">
                            <div className="font-mono text-sm text-gray-900">{scope.name}</div>
                            <div className="text-xs text-gray-500">{scope.description}</div>
                          </div>
                        </label>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div className="flex justify-end space-x-3">
              <button
                onClick={() => setShowCreateForm(false)}
                className="px-4 py-2 text-gray-700 border border-gray-300 rounded-md hover:bg-gray-50"
              >
                Cancel
              </button>
              <button
                onClick={createToken}
                disabled={creating || !tokenName.trim() || selectedScopes.length === 0}
                className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 disabled:bg-gray-400"
              >
                {creating ? 'Creating...' : 'Create Token'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Error Message */}
      {error && (
        <div className="bg-red-50 border border-red-200 rounded-lg p-4">
          <div className="flex items-center text-red-700">
            <span className="mr-2">❌</span>
            {error}
          </div>
        </div>
      )}

      {/* Tokens List */}
      <div className="space-y-4">
        {tokens.map((token) => (
          <div
            key={token.id}
            className={`border rounded-lg p-4 ${
              token.revoked 
                ? 'border-red-200 bg-red-50' 
                : new Date(token.expiresAt) < new Date()
                ? 'border-yellow-200 bg-yellow-50'
                : 'border-gray-200 bg-white'
            }`}
          >
            <div className="flex items-center justify-between">
              <div className="flex-1">
                <div className="flex items-center space-x-2">
                  <h4 className="font-medium text-gray-900">{token.name}</h4>
                  {token.revoked && (
                    <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-red-100 text-red-800">
                      Revoked
                    </span>
                  )}
                  {new Date(token.expiresAt) < new Date() && !token.revoked && (
                    <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-yellow-100 text-yellow-800">
                      Expired
                    </span>
                  )}
                </div>

                <div className="text-sm text-gray-500 mt-1">
                  Created: {new Date(token.createdAt).toLocaleDateString()} • 
                  Expires: {formatExpiresAt(token.expiresAt)} • 
                  Last used: {formatLastUsed(token.lastUsedAt)}
                </div>

                <div className="flex flex-wrap gap-1 mt-2">
                  {token.scopes.map((scope) => (
                    <span
                      key={scope}
                      className={`inline-flex items-center px-2 py-1 rounded-full text-xs font-medium ${getScopeBadgeColor(scope)}`}
                    >
                      {scope}
                    </span>
                  ))}
                </div>
              </div>

              {!token.revoked && (
                <button
                  onClick={() => revokeToken(token.id)}
                  disabled={revoking === token.id}
                  className={`ml-4 px-3 py-1 text-sm font-medium rounded-md ${
                    revoking === token.id
                      ? 'bg-gray-100 text-gray-400 cursor-not-allowed'
                      : 'bg-red-50 text-red-700 hover:bg-red-100'
                  }`}
                >
                  {revoking === token.id ? 'Revoking...' : 'Revoke'}
                </button>
              )}
            </div>
          </div>
        ))}
      </div>

      {tokens.length === 0 && (
        <div className="text-center py-8">
          <div className="text-gray-400 text-lg mb-2">🔑</div>
          <div className="text-gray-600">No API tokens found</div>
          <div className="text-sm text-gray-500">Create a token to get started with the API</div>
        </div>
      )}
    </div>
  );
};

