          </div>
        )}
      </div>

      {/* Security Notice */}
      <div className="mt-4 p-3 bg-gray-50 border border-gray-200 rounded-md">
        <p className="text-xs text-gray-600 text-center">
          🔒 Your login is secured with industry-standard encryption and monitoring.
        </p>
      </div>
    </div>
  );
};

