import React, { useState, useEffect } from 'react';
import { useAuth } from '../../hooks/useAuth';

interface NotificationPreferences {
  email: {
    enabled: boolean;
    frequency: 'immediate' | 'daily' | 'weekly' | 'never';
    types: {
      security: boolean;
      system: boolean;
      updates: boolean;
      marketing: boolean;
    };
  };
  inApp: {
    enabled: boolean;
    types: {
      security: boolean;
      system: boolean;
      updates: boolean;
      mentions: boolean;
    };
  };
  push: {
    enabled: boolean;
    types: {
      security: boolean;
      system: boolean;
      updates: boolean;
      mentions: boolean;
    };
  };
  quietHours: {
    enabled: boolean;
    start: string;
    end: string;
    timezone: string;
  };
}

interface NotificationPreferencesProps {
  onPreferencesUpdate?: (preferences: NotificationPreferences) => void;
}

export const NotificationPreferences: React.FC<NotificationPreferencesProps> = ({
  onPreferencesUpdate,
}) => {
  const { user } = useAuth();
  const [preferences, setPreferences] = useState<NotificationPreferences | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const timezones = [
    'UTC',
    'America/New_York',
    'America/Los_Angeles',
    'America/Chicago',
    'Europe/London',
    'Europe/Paris',
    'Europe/Berlin',
    'Asia/Tokyo',
    'Asia/Shanghai',
    'Asia/Mumbai',
    'Australia/Sydney',
  ];

  useEffect(() => {
    if (user) {
      fetchPreferences();
    }
  }, [user]);

  const fetchPreferences = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/auth/preferences/notifications', {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('access_token')}`,
        },
      });

      if (!response.ok) {
        throw new Error('Failed to fetch notification preferences');
      }

      const data = await response.json();
      setPreferences(data.preferences);
    } catch (error) {
      console.error('Error fetching notification preferences:', error);
      setError('Failed to load notification preferences');
    } finally {
      setLoading(false);
    }
  };

  const updatePreferences = async (updates: Partial<NotificationPreferences>) => {
    if (!preferences) return;

    try {
      setSaving(true);
      setError(null);

      const newPreferences = { ...preferences, ...updates };

      const response = await fetch('/api/auth/preferences/notifications', {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('access_token')}`,
        },
        body: JSON.stringify(newPreferences),
      });

      if (!response.ok) {
        throw new Error('Failed to update notification preferences');
      }

      const data = await response.json();
      setPreferences(data.preferences);
      onPreferencesUpdate?.(data.preferences);
    } catch (error) {
      console.error('Error updating notification preferences:', error);
      setError('Failed to update notification preferences');
    } finally {
      setSaving(false);
    }
  };

  const handleChannelToggle = (channel: keyof NotificationPreferences, enabled: boolean) => {
    if (!preferences) return;

    updatePreferences({
      [channel]: {
        ...preferences[channel],
        enabled,
      },
    });
  };

  const handleTypeToggle = (
    channel: keyof NotificationPreferences,
    type: string,
    enabled: boolean
  ) => {
    if (!preferences) return;

    updatePreferences({
      [channel]: {
        ...preferences[channel],
        types: {
          ...preferences[channel].types,
          [type]: enabled,
        },
      },
    });
  };

  const handleFrequencyChange = (frequency: 'immediate' | 'daily' | 'weekly' | 'never') => {
    if (!preferences) return;

    updatePreferences({
      email: {
        ...preferences.email,
        frequency,
      },
    });
  };

  const handleQuietHoursToggle = (enabled: boolean) => {
    if (!preferences) return;

    updatePreferences({
      quietHours: {
        ...preferences.quietHours,
