// Epic 11 Password Reset Form
// React component for password reset request functionality

import React, { useState } from 'react';
import { z } from 'zod';
import { usePasswordReset } from '../../hooks/usePasswordReset';
import { PasswordStrengthIndicator } from './PasswordStrengthIndicator';

const PasswordResetRequestSchema = z.object({
  email: z.string().email('Please enter a valid email address'),
});

const PasswordResetConfirmSchema = z.object({
  newPassword: z.string()
    .min(8, 'Password must be at least 8 characters')
    .max(128, 'Password must be less than 128 characters'),
  confirmPassword: z.string(),
}).refine((data) => data.newPassword === data.confirmPassword, {
  message: "Passwords don't match",
  path: ["confirmPassword"],
});

interface PasswordResetFormProps {
  mode: 'request' | 'confirm';
  token?: string;
  onSuccess?: () => void;
  onCancel?: () => void;
}

export const PasswordResetForm: React.FC<PasswordResetFormProps> = ({
  mode,
  token,
  onSuccess,
  onCancel,
}) => {
  const [formData, setFormData] = useState({
    email: '',
    newPassword: '',
    confirmPassword: '',
  });

  const [errors, setErrors] = useState<Record<string, string>>({});
  const [showPassword, setShowPassword] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const {
    requestPasswordReset,
    confirmPasswordReset,
    validateToken,
    loading,
    error: hookError,
  } = usePasswordReset();

  // Validate token on component mount for confirm mode
  React.useEffect(() => {
    if (mode === 'confirm' && token) {
      validateToken(token);
    }
  }, [mode, token, validateToken]);

  const validateForm = () => {
    setErrors({});

    try {
      if (mode === 'request') {
        PasswordResetRequestSchema.parse({ email: formData.email });
      } else {
        PasswordResetConfirmSchema.parse({
          newPassword: formData.newPassword,
          confirmPassword: formData.confirmPassword,
        });
      }
      return true;
    } catch (error) {
      if (error instanceof z.ZodError) {
        const newErrors: Record<string, string> = {};
        error.errors.forEach((err) => {
          if (err.path[0]) {
            newErrors[err.path[0] as string] = err.message;
          }
        });
        setErrors(newErrors);
      }
      return false;
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    setIsSubmitting(true);

    try {
      if (mode === 'request') {
        await requestPasswordReset(formData.email);
      } else if (mode === 'confirm' && token) {
        await confirmPasswordReset(token, formData.newPassword, formData.confirmPassword);
      }

      onSuccess?.();
    } catch (error) {
      // Error handling is managed by the hook
      console.error('Password reset error:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleInputChange = (field: string, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }));

    // Clear field-specific error when user starts typing
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: '' }));
    }
  };

  if (mode === 'request') {
    return (
      <div className="password-reset-form">
        <div className="auth-card">
          <div className="auth-header">
            <h2>Reset Your Password</h2>
            <p>Enter your email address and we'll send you a link to reset your password.</p>
          </div>

          <form onSubmit={handleSubmit} className="auth-form">
            <div className="form-group">
              <label htmlFor="email">Email Address</label>
              <input
                id="email"
                type="email"
                value={formData.email}
                onChange={(e) => handleInputChange('email', e.target.value)}
                className={`form-input ${errors.email ? 'error' : ''}`}
                placeholder="Enter your email address"
                disabled={loading || isSubmitting}
                autoComplete="email"
                autoFocus
              />
              {errors.email && (
                <div className="error-message">{errors.email}</div>
              )}
            </div>

            {hookError && (
