// Epic 11 Password Strength Indicator
// Visual password strength indicator with real-time feedback

import React from 'react';
import { usePasswordStrength } from '../../hooks/useRegistration';

interface PasswordStrengthIndicatorProps {
  password: string;
  className?: string;
}

export const PasswordStrengthIndicator: React.FC<PasswordStrengthIndicatorProps> = ({
  password,
  className = '',
}) => {
  const { score, feedback, strength } = usePasswordStrength(password);

  const getStrengthColor = (strength: string) => {
    switch (strength) {
      case 'weak':
        return 'bg-red-500';
      case 'fair':
        return 'bg-yellow-500';
      case 'good':
        return 'bg-blue-500';
      case 'strong':
        return 'bg-green-500';
      default:
        return 'bg-gray-300';
    }
  };

  const getStrengthTextColor = (strength: string) => {
    switch (strength) {
      case 'weak':
        return 'text-red-700';
      case 'fair':
        return 'text-yellow-700';
      case 'good':
        return 'text-blue-700';
      case 'strong':
        return 'text-green-700';
      default:
        return 'text-gray-700';
    }
  };

  if (!password) {
    return null;
  }

  return (
    <div className={`${className}`}>
      {/* Strength bar */}
      <div className="flex items-center space-x-2 mb-2">
        <div className="flex-1 bg-gray-200 rounded-full h-2">
          <div
            className={`h-2 rounded-full transition-all duration-300 ${getStrengthColor(strength)}`}
            style={{ width: `${score}%` }}
          />
        </div>
        <span className={`text-xs font-medium capitalize ${getStrengthTextColor(strength)}`}>
          {strength}
        </span>
      </div>

      {/* Feedback */}
      {feedback.length > 0 && (
        <div className="space-y-1">
          {feedback.map((item, index) => (
            <div key={index} className="flex items-center text-xs text-gray-600">
              <svg className="w-3 h-3 mr-1 text-gray-400" fill="currentColor" viewBox="0 0 20 20">
                <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
              </svg>
              {item}
            </div>
          ))}
        </div>
      )}

      {/* Requirements checklist */}
      <div className="mt-3 space-y-1">
        <div className="text-xs font-medium text-gray-700 mb-1">Password requirements:</div>
        {[
          { test: password.length >= 12, label: 'At least 12 characters' },
          { test: /[a-z]/.test(password), label: 'Lowercase letter' },
          { test: /[A-Z]/.test(password), label: 'Uppercase letter' },
          { test: /\d/.test(password), label: 'Number' },
          { test: /[^A-Za-z0-9]/.test(password), label: 'Special character' },
        ].map((requirement, index) => (
          <div key={index} className="flex items-center text-xs">
            {requirement.test ? (
              <svg className="w-3 h-3 mr-2 text-green-500" fill="currentColor" viewBox="0 0 20 20">
                <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
              </svg>
            ) : (
              <svg className="w-3 h-3 mr-2 text-gray-400" fill="currentColor" viewBox="0 0 20 20">
                <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
              </svg>
            )}
            <span className={requirement.test ? 'text-green-700' : 'text-gray-500'}>
              {requirement.label}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
};

// Epic 11 Registration Form Component
// Progressive registration form with validation and analytics

import React, { useState, useEffect } from 'react';
import { z } from 'zod';
import { useRegistration } from '../../hooks/useRegistration';
import { useFormAnalytics } from '../../hooks/useFormAnalytics';
import { PasswordStrengthIndicator } from './PasswordStrengthIndicator';
import { EmailSuggestions } from './EmailSuggestions';
import { LoadingSpinner } from '../common/LoadingSpinner';
import { ValidationMessage } from '../common/ValidationMessage';

// Registration form schema
const RegistrationSchema = z.object({
  email: z.string().email('Please enter a valid email address'),
  password: z.string().min(12, 'Password must be at least 12 characters'),
  confirmPassword: z.string(),
  firstName: z.string().min(2, 'First name must be at least 2 characters').optional(),
  lastName: z.string().min(2, 'Last name must be at least 2 characters').optional(),
  displayName: z.string().min(2, 'Display name must be at least 2 characters').optional(),
  acceptTerms: z.boolean().refine(val => val === true, 'You must accept the terms and conditions'),
  marketingConsent: z.boolean().optional(),
}).refine(data => data.password === data.confirmPassword, {
  message: "Passwords don't match",
  path: ["confirmPassword"],
});

type RegistrationFormData = z.infer<typeof RegistrationSchema>;

interface RegistrationFormProps {
  invitationToken?: string;
  onSuccess?: (user: any) => void;
  onCancel?: () => void;
  className?: string;
}

export const RegistrationForm: React.FC<RegistrationFormProps> = ({
  invitationToken,
  onSuccess,
  onCancel,
  className = '',
}) => {
  const [currentStep, setCurrentStep] = useState(1);
  const [formData, setFormData] = useState<Partial<RegistrationFormData>>({
    marketingConsent: false,
  });
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [showPassword, setShowPassword] = useState(false);

  const {
    register,
    isLoading,
    error: registrationError,
    validationResult,
    validateField,
  } = useRegistration();

  const { trackFieldEvent, trackFormStep } = useFormAnalytics();

  // Track form step changes
  useEffect(() => {
    trackFormStep(currentStep, 'registration');
  }, [currentStep, trackFormStep]);

  const steps = [
    { number: 1, title: 'Account Information', description: 'Create your account' },
    { number: 2, title: 'Personal Details', description: 'Tell us about yourself' },
    { number: 3, title: 'Confirmation', description: 'Review and confirm' },
  ];

  const handleFieldChange = (field: string, value: string | boolean) => {
    setFormData(prev => ({ ...prev, [field]: value }));

    // Clear field error when user starts typing
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: '' }));
    }

    // Track field interaction
    if (typeof value === 'string') {
      trackFieldEvent(field, 'change', value.length);
    }
  };

  const handleFieldBlur = async (field: string) => {
    trackFieldEvent(field, 'blur');

    // Validate individual field
    if (formData[field as keyof RegistrationFormData]) {
      await validateField(field, formData[field as keyof RegistrationFormData]);
    }
  };

  const handleFieldFocus = (field: string) => {
    trackFieldEvent(field, 'focus');
  };

  const validateCurrentStep = (): boolean => {
    const stepErrors: Record<string, string> = {};

    if (currentStep === 1) {
      // Email validation
      if (!formData.email) {
        stepErrors.email = 'Email is required';
      } else {
        try {
          z.string().email().parse(formData.email);
        } catch {
          stepErrors.email = 'Please enter a valid email address';
        }
      }

      // Password validation
      if (!formData.password) {
        stepErrors.password = 'Password is required';
      } else if (formData.password.length < 12) {
        stepErrors.password = 'Password must be at least 12 characters';
      }

      // Confirm password validation
      if (!formData.confirmPassword) {
        stepErrors.confirmPassword = 'Please confirm your password';
      } else if (formData.password !== formData.confirmPassword) {
        stepErrors.confirmPassword = "Passwords don't match";
      }
    }

    if (currentStep === 2) {
      // Optional validation for personal details
      if (formData.firstName && formData.firstName.length < 2) {
        stepErrors.firstName = 'First name must be at least 2 characters';
      }
      if (formData.lastName && formData.lastName.length < 2) {
        stepErrors.lastName = 'Last name must be at least 2 characters';
      }
      if (formData.displayName && formData.displayName.length < 2) {
        stepErrors.displayName = 'Display name must be at least 2 characters';
      }
    }

    if (currentStep === 3) {
      // Terms acceptance validation
      if (!formData.acceptTerms) {
        stepErrors.acceptTerms = 'You must accept the terms and conditions';
      }
    }

    setErrors(stepErrors);
    return Object.keys(stepErrors).length === 0;
  };

  const handleNextStep = () => {
    if (validateCurrentStep()) {
      setCurrentStep(prev => Math.min(prev + 1, steps.length));
    }
  };

  const handlePrevStep = () => {
    setCurrentStep(prev => Math.max(prev - 1, 1));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validateCurrentStep()) {
      return;
    }

    try {
      const registrationData = {
        email: formData.email!,
        password: formData.password!,
        firstName: formData.firstName,
        lastName: formData.lastName,
        displayName: formData.displayName || `${formData.firstName || ''} ${formData.lastName || ''}`.trim(),
        invitationToken,
      };

      const result = await register(registrationData);

      if (onSuccess) {
        onSuccess(result.user);
      }
    } catch (error) {
      console.error('Registration failed:', error);
    }
  };

  const renderStepIndicator = () => (
    <div className="flex items-center justify-center mb-8">
      {steps.map((step, index) => (
        <React.Fragment key={step.number}>
          <div className="flex flex-col items-center">
            <div
              className={`w-10 h-10 rounded-full flex items-center justify-center text-sm font-medium ${
                currentStep >= step.number
                  ? 'bg-blue-600 text-white'
                  : 'bg-gray-200 text-gray-500'
              }`}
            >
              {step.number}
            </div>
            <div className="mt-2 text-center">
              <div className="text-sm font-medium text-gray-900">{step.title}</div>
              <div className="text-xs text-gray-500">{step.description}</div>
            </div>
          </div>
          {index < steps.length - 1 && (
            <div
              className={`flex-1 h-0.5 mx-4 ${
                currentStep > step.number ? 'bg-blue-600' : 'bg-gray-200'
              }`}
            />
          )}
        </React.Fragment>
      ))}
    </div>
  );

  const renderStep1 = () => (
    <div className="space-y-6">
      <h2 className="text-2xl font-bold text-gray-900 text-center">Create Your Account</h2>

      <div>
        <label htmlFor="email" className="block text-sm font-medium text-gray-700">
          Email Address *
        </label>
        <div className="mt-1">
          <input
            type="email"
            id="email"
            value={formData.email || ''}
            onChange={(e) => handleFieldChange('email', e.target.value)}
            onBlur={() => handleFieldBlur('email')}
            onFocus={() => handleFieldFocus('email')}
            className={`block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 ${
              errors.email ? 'border-red-500' : ''
            }`}
            placeholder="you@example.com"
          />
          {errors.email && <ValidationMessage message={errors.email} type="error" />}
          {validationResult?.suggestions?.find(s => s.field === 'email') && (
            <EmailSuggestions 
              suggestion={validationResult.suggestions.find(s => s.field === 'email')!.suggestion}
              onAccept={(suggestion) => handleFieldChange('email', suggestion)}
            />
          )}
        </div>
      </div>

      <div>
        <label htmlFor="password" className="block text-sm font-medium text-gray-700">
          Password *
        </label>
        <div className="mt-1 relative">
          <input
            type={showPassword ? 'text' : 'password'}
            id="password"
            value={formData.password || ''}
            onChange={(e) => handleFieldChange('password', e.target.value)}
            onBlur={() => handleFieldBlur('password')}
            onFocus={() => handleFieldFocus('password')}
            className={`block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 pr-10 ${
              errors.password ? 'border-red-500' : ''
            }`}
            placeholder="Choose a strong password"
          />
          <button
            type="button"
            className="absolute inset-y-0 right-0 pr-3 flex items-center"
            onClick={() => setShowPassword(!showPassword)}
          >
            {showPassword ? (
              <svg className="h-5 w-5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.878 9.878L3 3m6.878 6.878L21 21" />
              </svg>
            ) : (
              <svg className="h-5 w-5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
              </svg>
            )}
          </button>
        </div>
        {formData.password && (
          <PasswordStrengthIndicator 
            password={formData.password} 
            className="mt-2"
          />
        )}
        {errors.password && <ValidationMessage message={errors.password} type="error" />}
      </div>

      <div>
        <label htmlFor="confirmPassword" className="block text-sm font-medium text-gray-700">
          Confirm Password *
        </label>
        <div className="mt-1">
          <input
            type={showPassword ? 'text' : 'password'}
            id="confirmPassword"
            value={formData.confirmPassword || ''}
            onChange={(e) => handleFieldChange('confirmPassword', e.target.value)}
            onBlur={() => handleFieldBlur('confirmPassword')}
            onFocus={() => handleFieldFocus('confirmPassword')}
            className={`block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 ${
              errors.confirmPassword ? 'border-red-500' : ''
            }`}
            placeholder="Confirm your password"
          />
          {errors.confirmPassword && <ValidationMessage message={errors.confirmPassword} type="error" />}
        </div>
      </div>
    </div>
  );

  const renderStep2 = () => (
    <div className="space-y-6">
      <h2 className="text-2xl font-bold text-gray-900 text-center">Personal Information</h2>
      <p className="text-center text-gray-600">These details are optional but help personalize your experience</p>

      <div className="grid grid-cols-1 gap-6 sm:grid-cols-2">
        <div>
          <label htmlFor="firstName" className="block text-sm font-medium text-gray-700">
            First Name
          </label>
          <div className="mt-1">
            <input
              type="text"
              id="firstName"
              value={formData.firstName || ''}
              onChange={(e) => handleFieldChange('firstName', e.target.value)}
              onBlur={() => handleFieldBlur('firstName')}
              onFocus={() => handleFieldFocus('firstName')}
              className={`block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 ${
                errors.firstName ? 'border-red-500' : ''
              }`}
              placeholder="John"
            />
            {errors.firstName && <ValidationMessage message={errors.firstName} type="error" />}
          </div>
        </div>

        <div>
          <label htmlFor="lastName" className="block text-sm font-medium text-gray-700">
            Last Name
          </label>
          <div className="mt-1">
            <input
              type="text"
              id="lastName"
              value={formData.lastName || ''}
              onChange={(e) => handleFieldChange('lastName', e.target.value)}
              onBlur={() => handleFieldBlur('lastName')}
              onFocus={() => handleFieldFocus('lastName')}
              className={`block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 ${
                errors.lastName ? 'border-red-500' : ''
              }`}
              placeholder="Doe"
            />
            {errors.lastName && <ValidationMessage message={errors.lastName} type="error" />}
          </div>
        </div>
      </div>

      <div>
        <label htmlFor="displayName" className="block text-sm font-medium text-gray-700">
          Display Name
        </label>
        <div className="mt-1">
          <input
            type="text"
            id="displayName"
            value={formData.displayName || ''}
            onChange={(e) => handleFieldChange('displayName', e.target.value)}
            onBlur={() => handleFieldBlur('displayName')}
            onFocus={() => handleFieldFocus('displayName')}
            className={`block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 ${
              errors.displayName ? 'border-red-500' : ''
            }`}
            placeholder="This is how others will see your name"
          />
          {errors.displayName && <ValidationMessage message={errors.displayName} type="error" />}
          <p className="mt-1 text-sm text-gray-500">
            If not provided, we'll use your first and last name
          </p>
        </div>
      </div>
    </div>
  );

  const renderStep3 = () => (
    <div className="space-y-6">
      <h2 className="text-2xl font-bold text-gray-900 text-center">Almost Done!</h2>
      <p className="text-center text-gray-600">Review your information and accept our terms</p>

      <div className="bg-gray-50 rounded-lg p-6">
        <h3 className="text-lg font-medium text-gray-900 mb-4">Account Summary</h3>
        <dl className="space-y-3">
          <div>
            <dt className="text-sm font-medium text-gray-500">Email</dt>
            <dd className="text-sm text-gray-900">{formData.email}</dd>
          </div>
          {(formData.firstName || formData.lastName) && (
            <div>
              <dt className="text-sm font-medium text-gray-500">Name</dt>
              <dd className="text-sm text-gray-900">
                {[formData.firstName, formData.lastName].filter(Boolean).join(' ')}
              </dd>
            </div>
          )}
          {formData.displayName && (
            <div>
              <dt className="text-sm font-medium text-gray-500">Display Name</dt>
              <dd className="text-sm text-gray-900">{formData.displayName}</dd>
            </div>
          )}
        </dl>
      </div>

      <div className="space-y-4">
        <div className="flex items-start">
          <div className="flex items-center h-5">
            <input
              id="acceptTerms"
              type="checkbox"
              checked={formData.acceptTerms || false}
              onChange={(e) => handleFieldChange('acceptTerms', e.target.checked)}
              className="focus:ring-blue-500 h-4 w-4 text-blue-600 border-gray-300 rounded"
            />
          </div>
          <div className="ml-3 text-sm">
            <label htmlFor="acceptTerms" className="font-medium text-gray-700">
              I accept the{' '}
              <a href="/terms" className="text-blue-600 hover:text-blue-500" target="_blank">
                Terms and Conditions
              </a>{' '}
              and{' '}
              <a href="/privacy" className="text-blue-600 hover:text-blue-500" target="_blank">
                Privacy Policy
              </a>
              *
            </label>
            {errors.acceptTerms && <ValidationMessage message={errors.acceptTerms} type="error" />}
          </div>
        </div>

        <div className="flex items-start">
          <div className="flex items-center h-5">
            <input
              id="marketingConsent"
              type="checkbox"
              checked={formData.marketingConsent || false}
              onChange={(e) => handleFieldChange('marketingConsent', e.target.checked)}
              className="focus:ring-blue-500 h-4 w-4 text-blue-600 border-gray-300 rounded"
            />
          </div>
          <div className="ml-3 text-sm">
            <label htmlFor="marketingConsent" className="font-medium text-gray-700">
              I'd like to receive updates and marketing communications
            </label>
            <p className="text-gray-500">You can unsubscribe at any time</p>
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div className={`max-w-2xl mx-auto ${className}`}>
      <form onSubmit={handleSubmit} className="space-y-8">
        {renderStepIndicator()}

        {registrationError && (
          <div className="bg-red-50 border border-red-200 rounded-md p-4">
            <div className="flex">
              <svg className="h-5 w-5 text-red-400" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
              </svg>
              <div className="ml-3">
                <h3 className="text-sm font-medium text-red-800">Registration Failed</h3>
                <p className="text-sm text-red-700 mt-1">{registrationError}</p>
              </div>
            </div>
          </div>
        )}

        {currentStep === 1 && renderStep1()}
        {currentStep === 2 && renderStep2()}
        {currentStep === 3 && renderStep3()}

        <div className="flex justify-between pt-6">
          {currentStep > 1 && (
            <button
              type="button"
              onClick={handlePrevStep}
              className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-md shadow-sm hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
            >
              Previous
            </button>
          )}

          <div className="flex-1" />

          {currentStep < steps.length ? (
            <button
              type="button"
              onClick={handleNextStep}
              disabled={isLoading}
              className="px-4 py-2 text-sm font-medium text-white bg-blue-600 border border-transparent rounded-md shadow-sm hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:opacity-50"
            >
              Next
            </button>
          ) : (
            <button
              type="submit"
              disabled={isLoading}
              className="px-6 py-2 text-sm font-medium text-white bg-blue-600 border border-transparent rounded-md shadow-sm hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:opacity-50 flex items-center"
            >
              {isLoading && <LoadingSpinner size="sm" className="mr-2" />}
              Create Account
            </button>
          )}
        </div>

        {onCancel && (
          <div className="text-center pt-4">
            <button
              type="button"
              onClick={onCancel}
              className="text-sm text-gray-500 hover:text-gray-700"
            >
              Cancel
            </button>
          </div>
        )}
      </form>
    </div>
  );
};

// Epic 11.3 Role Manager Component
// Administrative interface for creating, editing, and managing roles and permissions

import React, { useState, useEffect } from 'react';
import { ChevronDown, ChevronRight, Edit, Trash2, Plus, Users, Shield, Settings, Filter, Search } from 'lucide-react';

interface Permission {
  id: string;
  roleId: string;
  resource: string;
  action: string;
  scope: 'global' | 'organization' | 'team' | 'own';
  conditions?: Record<string, any>;
  createdAt: string;
}

interface Role {
  id: string;
  name: string;
  description?: string;
  scope: 'global' | 'organization' | 'team';
  organizationId?: string;
  createdAt: string;
  updatedAt: string;
}

interface RoleWithDetails extends Role {
  permissions: Permission[];
  assignedUsers: any[];
}

interface CreateRoleData {
  name: string;
  description?: string;
  scope: 'global' | 'organization' | 'team';
  organizationId?: string;
  permissions: {
    resource: string;
    action: string;
    scope: 'global' | 'organization' | 'team' | 'own';
    conditions?: Record<string, any>;
  }[];
}

interface RoleStats {
  totalRoles: number;
  rolesByScope: Record<string, number>;
  totalAssignments: number;
  recentAssignments: number;
}

export const RoleManager: React.FC = () => {
  const [roles, setRoles] = useState<Role[]>([]);
  const [selectedRole, setSelectedRole] = useState<RoleWithDetails | null>(null);
  const [stats, setStats] = useState<RoleStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [creating, setCreating] = useState(false);
  const [editing, setEditing] = useState(false);
  const [expandedRoles, setExpandedRoles] = useState<Set<string>>(new Set());

  // Filters and search
  const [scopeFilter, setScopeFilter] = useState<string>('');
  const [searchQuery, setSearchQuery] = useState('');
  const [organizationFilter, setOrganizationFilter] = useState<string>('');

  // Form state
  const [formData, setFormData] = useState<CreateRoleData>({
    name: '',
    description: '',
    scope: 'global',
    permissions: [],
  });

  // Permission templates for common role types
  const permissionTemplates = {
    admin: [
      { resource: 'users', action: 'read', scope: 'global' as const },
      { resource: 'users', action: 'write', scope: 'global' as const },
      { resource: 'roles', action: 'read', scope: 'global' as const },
      { resource: 'roles', action: 'write', scope: 'global' as const },
      { resource: 'system', action: 'admin', scope: 'global' as const },
    ],
    editor: [
      { resource: 'graphs', action: 'read', scope: 'global' as const },
      { resource: 'graphs', action: 'write', scope: 'own' as const },
      { resource: 'graphs', action: 'execute', scope: 'global' as const },
    ],
    viewer: [
      { resource: 'graphs', action: 'read', scope: 'global' as const },
      { resource: 'graphs', action: 'execute', scope: 'global' as const },
    ],
  };

  useEffect(() => {
    loadData();
  }, [scopeFilter, searchQuery, organizationFilter]);

  const loadData = async () => {
    try {
      const [rolesResponse, statsResponse] = await Promise.all([
        fetch('/api/auth/rbac/roles?' + new URLSearchParams({
          ...(scopeFilter && { scope: scopeFilter }),
          ...(searchQuery && { search: searchQuery }),
          ...(organizationFilter && { organizationId: organizationFilter }),
        }), {
          credentials: 'include',
        }),
        fetch('/api/auth/rbac/stats', {
          credentials: 'include',
        }),
      ]);

      if (rolesResponse.ok) {
        const rolesData = await rolesResponse.json();
        setRoles(rolesData.roles);
      }

      if (statsResponse.ok) {
        const statsData = await statsResponse.json();
        setStats(statsData);
      }
    } catch (error) {
      console.error('Failed to load RBAC data:', error);
    } finally {
      setLoading(false);
    }
  };

  const loadRoleDetails = async (roleId: string) => {
    try {
      const response = await fetch(`/api/auth/rbac/roles/${roleId}`, {
        credentials: 'include',
      });

      if (response.ok) {
        const data = await response.json();
        setSelectedRole({
          ...data.role,
          permissions: data.permissions,
          assignedUsers: data.assignedUsers,
        });
      }
    } catch (error) {
      console.error('Failed to load role details:', error);
    }
  };

  const handleCreateRole = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const response = await fetch('/api/auth/rbac/roles', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        credentials: 'include',
        body: JSON.stringify(formData),
      });

      if (response.ok) {
        setCreating(false);
        setFormData({
          name: '',
          description: '',
          scope: 'global',
          permissions: [],
        });
        await loadData();
      } else {
        const error = await response.json();
        alert(error.message || 'Failed to create role');
      }
    } catch (error) {
      console.error('Failed to create role:', error);
      alert('Failed to create role');
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteRole = async (roleId: string) => {
    if (!confirm('Are you sure you want to delete this role? This action cannot be undone.')) {
      return;
    }

    try {
      const response = await fetch(`/api/auth/rbac/roles/${roleId}`, {
        method: 'DELETE',
        credentials: 'include',
      });

      if (response.ok) {
        await loadData();
        if (selectedRole?.id === roleId) {
          setSelectedRole(null);
        }
      } else {
        const error = await response.json();
        alert(error.message || 'Failed to delete role');
      }
    } catch (error) {
      console.error('Failed to delete role:', error);
      alert('Failed to delete role');
    }
  };

  const toggleRoleExpansion = (roleId: string) => {
    const newExpanded = new Set(expandedRoles);
    if (newExpanded.has(roleId)) {
      newExpanded.delete(roleId);
    } else {
      newExpanded.add(roleId);
      loadRoleDetails(roleId);
    }
    setExpandedRoles(newExpanded);
  };

  const applyPermissionTemplate = (template: keyof typeof permissionTemplates) => {
    setFormData({
      ...formData,
      permissions: [...permissionTemplates[template]],
    });
  };

  const addPermission = () => {
    setFormData({
      ...formData,
      permissions: [
        ...formData.permissions,
        { resource: '', action: '', scope: 'global' },
      ],
    });
  };

  const updatePermission = (index: number, field: string, value: string) => {
    const newPermissions = [...formData.permissions];
    newPermissions[index] = { ...newPermissions[index], [field]: value };
    setFormData({ ...formData, permissions: newPermissions });
  };

  const removePermission = (index: number) => {
    setFormData({
      ...formData,
      permissions: formData.permissions.filter((_, i) => i !== index),
    });
  };

  if (loading && !roles.length) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Role Management</h1>
          <p className="text-gray-600">Manage roles and permissions for your organization</p>
        </div>
        <button
          onClick={() => setCreating(true)}
          className="flex items-center space-x-2 bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition-colors"
        >
          <Plus className="w-4 h-4" />
          <span>Create Role</span>
        </button>
      </div>

      {/* Statistics */}
      {stats && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="bg-white p-4 rounded-lg border border-gray-200">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600">Total Roles</p>
                <p className="text-2xl font-bold text-gray-900">{stats.totalRoles}</p>
              </div>
              <Shield className="w-8 h-8 text-blue-600" />
            </div>
          </div>
          <div className="bg-white p-4 rounded-lg border border-gray-200">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600">Active Assignments</p>
                <p className="text-2xl font-bold text-gray-900">{stats.totalAssignments}</p>
              </div>
              <Users className="w-8 h-8 text-green-600" />
            </div>
          </div>
          <div className="bg-white p-4 rounded-lg border border-gray-200">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600">Recent Assignments</p>
                <p className="text-2xl font-bold text-gray-900">{stats.recentAssignments}</p>
              </div>
              <Settings className="w-8 h-8 text-purple-600" />
            </div>
          </div>
          <div className="bg-white p-4 rounded-lg border border-gray-200">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600">Global Roles</p>
