import React, { useState, useEffect } from 'react';
import { useAuth } from '../../hooks/useAuth';

interface UserProfile {
  id?: string;
  displayName?: string;
  firstName?: string;
  lastName?: string;
  bio?: string;
  avatarUrl?: string;
  timezone?: string;
  locale?: string;
  createdAt?: string;
  updatedAt?: string;
}

interface ProfileCompleteness {
  percentage: number;
  completedFields: string[];
  missingFields: string[];
}

interface UserProfileManagerProps {
  onProfileUpdate?: (profile: UserProfile) => void;
  showCompleteness?: boolean;
  allowImageUpload?: boolean;
}

export const UserProfileManager: React.FC<UserProfileManagerProps> = ({
  onProfileUpdate,
  showCompleteness = true,
  allowImageUpload = true,
}) => {
  const { user } = useAuth();
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [completeness, setCompleteness] = useState<ProfileCompleteness | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [uploadingImage, setUploadingImage] = useState(false);
  const [editMode, setEditMode] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [tempValues, setTempValues] = useState<Partial<UserProfile>>({});

  // Available timezones and locales
  const timezones = [
    'UTC', 'America/New_York', 'America/Los_Angeles', 'America/Chicago',
    'Europe/London', 'Europe/Paris', 'Europe/Berlin', 'Asia/Tokyo',
    'Asia/Shanghai', 'Asia/Mumbai', 'Australia/Sydney'
  ];

  const locales = [
    { code: 'en-US', name: 'English (US)' },
    { code: 'en-GB', name: 'English (UK)' },
    { code: 'es-ES', name: 'Español' },
    { code: 'fr-FR', name: 'Français' },
    { code: 'de-DE', name: 'Deutsch' },
    { code: 'ja-JP', name: '日本語' },
    { code: 'zh-CN', name: '中文' },
  ];

  useEffect(() => {
    if (user) {
      fetchProfile();
    }
  }, [user]);

  const fetchProfile = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/auth/profile', {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('access_token')}`,
        },
      });

      if (!response.ok) {
        throw new Error('Failed to fetch profile');
      }

      const data = await response.json();
      setProfile(data.profile);
      if (showCompleteness) {
        setCompleteness(data.completeness);
      }
    } catch (error) {
      console.error('Error fetching profile:', error);
      setError('Failed to load profile');
    } finally {
      setLoading(false);
    }
  };

  const updateProfile = async (updates: Partial<UserProfile>) => {
    try {
      setSaving(true);
      setError(null);

      const response = await fetch('/api/auth/profile', {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('access_token')}`,
        },
        body: JSON.stringify(updates),
      });

      if (!response.ok) {
        throw new Error('Failed to update profile');
      }

      const data = await response.json();
      setProfile(data.profile);

      // Refresh completeness if showing
      if (showCompleteness) {
        await fetchProfile();
      }

      onProfileUpdate?.(data.profile);
    } catch (error) {
      console.error('Error updating profile:', error);
      setError('Failed to update profile');
    } finally {
      setSaving(false);
    }
  };

  const handleImageUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    try {
      setUploadingImage(true);
      setError(null);

      const formData = new FormData();
      formData.append('file', file);

      const response = await fetch('/api/auth/profile/avatar', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('access_token')}`,
        },
        body: formData,
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || 'Failed to upload image');
      }

      const data = await response.json();
      setProfile(prev => prev ? { ...prev, avatarUrl: data.avatarUrl } : null);
      onProfileUpdate?.(profile ? { ...profile, avatarUrl: data.avatarUrl } : {});
    } catch (error) {
      console.error('Error uploading image:', error);
      setError(error.message || 'Failed to upload image');
    } finally {
      setUploadingImage(false);
    }
  };

  const handleDeleteImage = async () => {
    try {
      setError(null);

      const response = await fetch('/api/auth/profile/avatar', {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('access_token')}`,
        },
      });

      if (!response.ok) {
        throw new Error('Failed to delete image');
      }

      setProfile(prev => prev ? { ...prev, avatarUrl: null } : null);
      onProfileUpdate?.(profile ? { ...profile, avatarUrl: null } : {});
    } catch (error) {
      console.error('Error deleting image:', error);
      setError('Failed to delete image');
    }
  };

  const startEdit = (field: string, currentValue: any) => {
    setEditMode(field);
    setTempValues({ [field]: currentValue });
  };

  const cancelEdit = () => {
    setEditMode(null);
    setTempValues({});
  };

  const saveEdit = async (field: string) => {
    if (tempValues[field] !== undefined) {
      await updateProfile({ [field]: tempValues[field] });
    }
    setEditMode(null);
    setTempValues({});
  };

  const handleTempValueChange = (field: string, value: any) => {
    setTempValues(prev => ({ ...prev, [field]: value }));
  };

  const getCompletenessColor = (percentage: number) => {
    if (percentage >= 80) return 'text-green-600';
    if (percentage >= 60) return 'text-yellow-600';
    return 'text-red-600';
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center p-8">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto space-y-6">
      {/* Profile Header */}
      <div className="bg-white rounded-lg shadow-md p-6">
        <div className="flex items-center space-x-6">
          {/* Avatar */}
          <div className="relative">
            <div className="w-24 h-24 rounded-full bg-gray-200 flex items-center justify-center overflow-hidden">
              {profile?.avatarUrl ? (
                <img
                  src={profile.avatarUrl}
                  alt="Profile"
                  className="w-full h-full object-cover"
                />
              ) : (
                <div className="text-2xl text-gray-400">
                  {profile?.displayName?.[0]?.toUpperCase() || 
                   profile?.firstName?.[0]?.toUpperCase() || 
                   user?.email?.[0]?.toUpperCase() || '?'}
                </div>
              )}
            </div>

            {allowImageUpload && (
              <div className="absolute bottom-0 right-0">
                <label className="cursor-pointer">
                  <div className="w-8 h-8 bg-blue-600 rounded-full flex items-center justify-center text-white hover:bg-blue-700">
                    {uploadingImage ? (
                      <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white"></div>
                    ) : (
                      <span className="text-xs">📷</span>
                    )}
                  </div>
                  <input
                    type="file"
                    accept="image/*"
                    onChange={handleImageUpload}
                    className="hidden"
                    disabled={uploadingImage}
                  />
                </label>
              </div>
            )}
          </div>

          {/* Profile Info */}
          <div className="flex-1">
            <div className="flex items-center space-x-2">
              <h1 className="text-2xl font-bold text-gray-900">
                {profile?.displayName || profile?.firstName || 'Anonymous User'}
              </h1>
              {profile?.avatarUrl && (
                <button
                  onClick={handleDeleteImage}
                  className="text-red-600 hover:text-red-800 text-sm"
                >
                  Remove Photo
                </button>
              )}
            </div>
            <p className="text-gray-600">{user?.email}</p>
            {profile?.bio && (
              <p className="text-gray-700 mt-2">{profile.bio}</p>
            )}
          </div>
        </div>

        {/* Profile Completeness */}
        {showCompleteness && completeness && (
          <div className="mt-6 p-4 bg-gray-50 rounded-lg">
            <div className="flex items-center justify-between">
              <span className="text-sm font-medium text-gray-700">Profile Completeness</span>
              <span className={`text-sm font-bold ${getCompletenessColor(completeness.percentage)}`}>
                {completeness.percentage}%
              </span>
            </div>
            <div className="mt-2 w-full bg-gray-200 rounded-full h-2">
              <div
                className="bg-blue-600 h-2 rounded-full transition-all duration-300"
                style={{ width: `${completeness.percentage}%` }}
              />
            </div>
            {completeness.missingFields.length > 0 && (
              <p className="text-sm text-gray-600 mt-2">
                Missing: {completeness.missingFields.join(', ')}
              </p>
            )}
          </div>
        )}
      </div>

      {/* Error Message */}
      {error && (
        <div className="bg-red-50 border border-red-200 rounded-lg p-4">
          <div className="flex items-center text-red-700">
            <span className="mr-2">❌</span>
            {error}
          </div>
        </div>
      )}

      {/* Profile Fields */}
      <div className="bg-white rounded-lg shadow-md p-6">
        <h2 className="text-lg font-semibold text-gray-900 mb-4">Profile Information</h2>

        <div className="space-y-6">
          {/* Display Name */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Display Name
            </label>
            {editMode === 'displayName' ? (
              <div className="flex space-x-2">
                <input
                  type="text"
                  value={tempValues.displayName || ''}
                  onChange={(e) => handleTempValueChange('displayName', e.target.value)}
                  className="flex-1 px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  placeholder="Enter your display name"
                />
                <button
                  onClick={() => saveEdit('displayName')}
                  disabled={saving}
                  className="px-3 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 disabled:bg-gray-400"
                >
                  {saving ? 'Saving...' : 'Save'}
                </button>
                <button
                  onClick={cancelEdit}
                  className="px-3 py-2 bg-gray-300 text-gray-700 rounded-md hover:bg-gray-400"
                >
                  Cancel
                </button>
              </div>
            ) : (
              <div className="flex items-center justify-between">
                <span className="text-gray-900">
                  {profile?.displayName || <span className="text-gray-400">Not set</span>}
                </span>
                <button
                  onClick={() => startEdit('displayName', profile?.displayName)}
                  className="text-blue-600 hover:text-blue-800 text-sm"
                >
                  Edit
                </button>
              </div>
            )}
          </div>

          {/* First Name */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              First Name
            </label>
            {editMode === 'firstName' ? (
              <div className="flex space-x-2">
                <input
                  type="text"
                  value={tempValues.firstName || ''}
                  onChange={(e) => handleTempValueChange('firstName', e.target.value)}
                  className="flex-1 px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  placeholder="Enter your first name"
                />
                <button
                  onClick={() => saveEdit('firstName')}
                  disabled={saving}
                  className="px-3 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 disabled:bg-gray-400"
                >
                  {saving ? 'Saving...' : 'Save'}
                </button>
                <button
                  onClick={cancelEdit}
                  className="px-3 py-2 bg-gray-300 text-gray-700 rounded-md hover:bg-gray-400"
                >
                  Cancel
                </button>
              </div>
            ) : (
              <div className="flex items-center justify-between">
                <span className="text-gray-900">
                  {profile?.firstName || <span className="text-gray-400">Not set</span>}
                </span>
                <button
                  onClick={() => startEdit('firstName', profile?.firstName)}
                  className="text-blue-600 hover:text-blue-800 text-sm"
                >
                  Edit
                </button>
              </div>
            )}
          </div>

          {/* Last Name */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Last Name
            </label>
            {editMode === 'lastName' ? (
              <div className="flex space-x-2">
                <input
                  type="text"
                  value={tempValues.lastName || ''}
                  onChange={(e) => handleTempValueChange('lastName', e.target.value)}
                  className="flex-1 px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  placeholder="Enter your last name"
                />
                <button
                  onClick={() => saveEdit('lastName')}
                  disabled={saving}
                  className="px-3 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 disabled:bg-gray-400"
                >
                  {saving ? 'Saving...' : 'Save'}
                </button>
                <button
                  onClick={cancelEdit}
                  className="px-3 py-2 bg-gray-300 text-gray-700 rounded-md hover:bg-gray-400"
                >
                  Cancel
                </button>
              </div>
            ) : (
              <div className="flex items-center justify-between">
                <span className="text-gray-900">
                  {profile?.lastName || <span className="text-gray-400">Not set</span>}
                </span>
                <button
                  onClick={() => startEdit('lastName', profile?.lastName)}
                  className="text-blue-600 hover:text-blue-800 text-sm"
                >
                  Edit
                </button>
              </div>
            )}
          </div>

          {/* Bio */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Bio
            </label>
            {editMode === 'bio' ? (
              <div className="space-y-2">
                <textarea
                  value={tempValues.bio || ''}
                  onChange={(e) => handleTempValueChange('bio', e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  placeholder="Tell us about yourself"
                  rows={3}
                  maxLength={500}
                />
                <div className="text-sm text-gray-500 text-right">
                  {(tempValues.bio || '').length}/500
                </div>
                <div className="flex space-x-2">
                  <button
                    onClick={() => saveEdit('bio')}
                    disabled={saving}
                    className="px-3 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 disabled:bg-gray-400"
                  >
                    {saving ? 'Saving...' : 'Save'}
                  </button>
                  <button
                    onClick={cancelEdit}
                    className="px-3 py-2 bg-gray-300 text-gray-700 rounded-md hover:bg-gray-400"
                  >
                    Cancel
                  </button>
                </div>
              </div>
            ) : (
              <div className="flex items-start justify-between">
                <div className="flex-1">
                  {profile?.bio ? (
                    <p className="text-gray-900 whitespace-pre-wrap">{profile.bio}</p>
                  ) : (
                    <span className="text-gray-400">Not set</span>
                  )}
                </div>
                <button
                  onClick={() => startEdit('bio', profile?.bio)}
                  className="text-blue-600 hover:text-blue-800 text-sm ml-2"
                >
                  Edit
                </button>
              </div>
            )}
          </div>

          {/* Timezone */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Timezone
            </label>
            {editMode === 'timezone' ? (
              <div className="flex space-x-2">
                <select
                  value={tempValues.timezone || ''}
                  onChange={(e) => handleTempValueChange('timezone', e.target.value)}
                  className="flex-1 px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                >
                  {timezones.map(tz => (
                    <option key={tz} value={tz}>{tz}</option>
                  ))}
                </select>
                <button
                  onClick={() => saveEdit('timezone')}
                  disabled={saving}
                  className="px-3 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 disabled:bg-gray-400"
                >
                  {saving ? 'Saving...' : 'Save'}
                </button>
                <button
                  onClick={cancelEdit}
                  className="px-3 py-2 bg-gray-300 text-gray-700 rounded-md hover:bg-gray-400"
                >
                  Cancel
                </button>
              </div>
            ) : (
              <div className="flex items-center justify-between">
                <span className="text-gray-900">
                  {profile?.timezone || 'UTC'}
                </span>
                <button
                  onClick={() => startEdit('timezone', profile?.timezone)}
                  className="text-blue-600 hover:text-blue-800 text-sm"
                >
                  Edit
                </button>
              </div>
            )}
          </div>

          {/* Locale */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Language
            </label>
            {editMode === 'locale' ? (
              <div className="flex space-x-2">
                <select
                  value={tempValues.locale || ''}
                  onChange={(e) => handleTempValueChange('locale', e.target.value)}
                  className="flex-1 px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                >
                  {locales.map(locale => (
                    <option key={locale.code} value={locale.code}>{locale.name}</option>
                  ))}
                </select>
                <button
                  onClick={() => saveEdit('locale')}
                  disabled={saving}
                  className="px-3 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 disabled:bg-gray-400"
                >
                  {saving ? 'Saving...' : 'Save'}
                </button>
                <button
                  onClick={cancelEdit}
                  className="px-3 py-2 bg-gray-300 text-gray-700 rounded-md hover:bg-gray-400"
                >
                  Cancel
                </button>
              </div>
            ) : (
              <div className="flex items-center justify-between">
                <span className="text-gray-900">
                  {locales.find(l => l.code === profile?.locale)?.name || 'English (US)'}
                </span>
                <button
                  onClick={() => startEdit('locale', profile?.locale)}
                  className="text-blue-600 hover:text-blue-800 text-sm"
                >
                  Edit
                </button>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Account Info */}
      <div className="bg-white rounded-lg shadow-md p-6">
        <h2 className="text-lg font-semibold text-gray-900 mb-4">Account Information</h2>

        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Email Address
            </label>
            <div className="flex items-center space-x-2">
              <span className="text-gray-900">{user?.email}</span>
              {user?.emailVerified && (
                <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-green-100 text-green-800">
                  Verified
                </span>
              )}
            </div>
          </div>

          {profile?.createdAt && (
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Member Since
              </label>
              <span className="text-gray-900">
                {new Date(profile.createdAt).toLocaleDateString()}
              </span>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default UserProfileManager;

// Epic 11.3 User Role Assignment Component
// Interface for assigning and managing user roles with organization and team context

import React, { useState, useEffect } from 'react';
import { Search, Plus, X, Calendar, Users, Shield, AlertCircle, CheckCircle } from 'lucide-react';

interface User {
  id: string;
  email: string;
  displayName?: string;
  firstName?: string;
  lastName?: string;
  createdAt: string;
}

interface Role {
  id: string;
  name: string;
  description?: string;
  scope: 'global' | 'organization' | 'team';
  organizationId?: string;
}

interface UserRole {
  id: string;
  userId: string;
  roleId: string;
  roleName: string;
  roleScope: string;
  grantedBy: string;
  grantedAt: string;
  expiresAt?: string;
  scopeContext?: Record<string, any>;
}

interface AssignRoleData {
  userId: string;
  roleId: string;
  expiresAt?: string;
  scopeContext?: Record<string, any>;
}

export const UserRoleAssignment: React.FC = () => {
  const [users, setUsers] = useState<User[]>([]);
  const [roles, setRoles] = useState<Role[]>([]);
  const [selectedUser, setSelectedUser] = useState<User | null>(null);
  const [userRoles, setUserRoles] = useState<UserRole[]>([]);
  const [loading, setLoading] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [roleFilter, setRoleFilter] = useState('');
  const [showAssignModal, setShowAssignModal] = useState(false);

  // Assignment form state
  const [assignmentForm, setAssignmentForm] = useState<AssignRoleData>({
    userId: '',
    roleId: '',
  });
  const [assignmentExpiry, setAssignmentExpiry] = useState('');
  const [assignmentContext, setAssignmentContext] = useState('');

  useEffect(() => {
    loadUsers();
    loadRoles();
  }, []);

  const loadUsers = async () => {
    setLoading(true);
    try {
      const response = await fetch('/api/auth/users?' + new URLSearchParams({
        ...(searchQuery && { search: searchQuery }),
        limit: '50',
      }), {
        credentials: 'include',
      });

      if (response.ok) {
        const data = await response.json();
        setUsers(data.users || []);
      }
    } catch (error) {
      console.error('Failed to load users:', error);
    } finally {
      setLoading(false);
    }
  };

  const loadRoles = async () => {
    try {
      const response = await fetch('/api/auth/rbac/roles?' + new URLSearchParams({
        ...(roleFilter && { scope: roleFilter }),
      }), {
        credentials: 'include',
      });

      if (response.ok) {
        const data = await response.json();
        setRoles(data.roles || []);
      }
    } catch (error) {
      console.error('Failed to load roles:', error);
    }
  };

  const loadUserRoles = async (userId: string) => {
    try {
      const response = await fetch(`/api/auth/rbac/users/${userId}/roles`, {
        credentials: 'include',
      });

      if (response.ok) {
        const data = await response.json();
        // Transform roles to include assignment details
        const userRolesWithDetails = data.roles.map((role: any) => ({
          id: role.assignmentId || role.id,
          userId,
          roleId: role.id,
          roleName: role.name,
          roleScope: role.scope,
          grantedBy: role.grantedBy,
          grantedAt: role.grantedAt,
          expiresAt: role.expiresAt,
          scopeContext: role.scopeContext,
        }));
        setUserRoles(userRolesWithDetails);
      }
    } catch (error) {
      console.error('Failed to load user roles:', error);
    }
  };

  const handleUserSelect = (user: User) => {
    setSelectedUser(user);
    loadUserRoles(user.id);
  };

  const handleAssignRole = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedUser) return;

    setLoading(true);
    try {
      const assignmentData: AssignRoleData = {
        userId: selectedUser.id,
        roleId: assignmentForm.roleId,
      };

      if (assignmentExpiry) {
        assignmentData.expiresAt = new Date(assignmentExpiry).toISOString();
      }

      if (assignmentContext) {
        try {
          assignmentData.scopeContext = JSON.parse(assignmentContext);
        } catch (error) {
          alert('Invalid JSON in scope context');
          return;
        }
      }

      const response = await fetch('/api/auth/rbac/assign-role', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        credentials: 'include',
        body: JSON.stringify(assignmentData),
      });

      if (response.ok) {
        setShowAssignModal(false);
        setAssignmentForm({ userId: '', roleId: '' });
        setAssignmentExpiry('');
        setAssignmentContext('');
        loadUserRoles(selectedUser.id);
      } else {
        const error = await response.json();
        alert(error.message || 'Failed to assign role');
      }
    } catch (error) {
      console.error('Failed to assign role:', error);
      alert('Failed to assign role');
    } finally {
      setLoading(false);
    }
  };

  const handleRemoveRole = async (roleId: string) => {
    if (!selectedUser) return;

    if (!confirm('Are you sure you want to remove this role from the user?')) {
      return;
    }

    try {
      const response = await fetch('/api/auth/rbac/remove-role', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        credentials: 'include',
        body: JSON.stringify({
          userId: selectedUser.id,
          roleId,
        }),
      });

      if (response.ok) {
        loadUserRoles(selectedUser.id);
      } else {
        const error = await response.json();
        alert(error.message || 'Failed to remove role');
      }
    } catch (error) {
      console.error('Failed to remove role:', error);
      alert('Failed to remove role');
    }
  };

  const isRoleExpired = (expiresAt?: string) => {
    return expiresAt && new Date(expiresAt) < new Date();
  };

  const isRoleExpiringSoon = (expiresAt?: string) => {
    if (!expiresAt) return false;
    const expiry = new Date(expiresAt);
    const now = new Date();
    const sevenDaysFromNow = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);
    return expiry > now && expiry < sevenDaysFromNow;
  };

  return (
    <div className="max-w-7xl mx-auto p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">User Role Assignment</h1>
          <p className="text-gray-600">Assign and manage user roles and permissions</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* User List */}
        <div className="space-y-4">
          <div className="bg-white p-4 rounded-lg border border-gray-200">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-lg font-semibold text-gray-900">Users</h2>
              <Users className="w-5 h-5 text-gray-400" />
            </div>

            {/* Search */}
            <div className="relative mb-4">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-gray-400" />
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && loadUsers()}
                className="w-full pl-10 pr-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                placeholder="Search users..."
              />
            </div>

            <button
              onClick={loadUsers}
              className="w-full mb-4 bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition-colors"
            >
              Search Users
            </button>

            {/* User List */}
            <div className="space-y-2 max-h-96 overflow-y-auto">
              {users.map((user) => (
                <div
                  key={user.id}
                  onClick={() => handleUserSelect(user)}
                  className={`p-3 rounded-lg border cursor-pointer transition-colors ${
                    selectedUser?.id === user.id
                      ? 'border-blue-500 bg-blue-50'
                      : 'border-gray-200 hover:bg-gray-50'
                  }`}
                >
                  <div className="flex items-center space-x-3">
                    <div className="w-8 h-8 bg-gray-300 rounded-full flex items-center justify-center text-sm font-medium">
                      {user.displayName?.charAt(0) || user.email.charAt(0).toUpperCase()}
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="font-medium text-gray-900 truncate">
                        {user.displayName || `${user.firstName} ${user.lastName}`.trim() || user.email}
                      </p>
                      <p className="text-sm text-gray-600 truncate">{user.email}</p>
                    </div>
                  </div>
                </div>
              ))}
            </div>

            {loading && (
              <div className="flex justify-center py-4">
                <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-blue-600"></div>
              </div>
            )}
          </div>
        </div>

        {/* User Roles */}
        <div className="lg:col-span-2 space-y-4">
          {selectedUser ? (
            <>
              {/* User Info */}
              <div className="bg-white p-4 rounded-lg border border-gray-200">
                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-3">
                    <div className="w-12 h-12 bg-gray-300 rounded-full flex items-center justify-center text-lg font-medium">
                      {selectedUser.displayName?.charAt(0) || selectedUser.email.charAt(0).toUpperCase()}
                    </div>
                    <div>
                      <h2 className="text-lg font-semibold text-gray-900">
                        {selectedUser.displayName || `${selectedUser.firstName} ${selectedUser.lastName}`.trim() || selectedUser.email}
                      </h2>
                      <p className="text-gray-600">{selectedUser.email}</p>
                      <p className="text-sm text-gray-500">
                        Member since {new Date(selectedUser.createdAt).toLocaleDateString()}
                      </p>
                    </div>
                  </div>
                  <button
                    onClick={() => setShowAssignModal(true)}
                    className="flex items-center space-x-2 bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition-colors"
                  >
                    <Plus className="w-4 h-4" />
                    <span>Assign Role</span>
                  </button>
                </div>
              </div>

              {/* Roles */}
              <div className="bg-white rounded-lg border border-gray-200">
                <div className="p-4 border-b border-gray-200">
                  <div className="flex items-center justify-between">
                    <h3 className="text-lg font-semibold text-gray-900">Assigned Roles</h3>
                    <span className="text-sm text-gray-500">{userRoles.length} roles</span>
                  </div>
                </div>

                <div className="divide-y divide-gray-200">
                  {userRoles.map((userRole) => (
                    <div key={userRole.id} className="p-4">
                      <div className="flex items-center justify-between">
                        <div className="flex-1">
                          <div className="flex items-center space-x-3">
                            <Shield className="w-5 h-5 text-blue-600" />
                            <div>
                              <h4 className="font-medium text-gray-900">{userRole.roleName}</h4>
                              <div className="flex items-center space-x-2 mt-1">
                                <span className={`px-2 py-1 text-xs rounded-full ${
                                  userRole.roleScope === 'global' ? 'bg-blue-100 text-blue-800' :
                                  userRole.roleScope === 'organization' ? 'bg-green-100 text-green-800' :
                                  'bg-yellow-100 text-yellow-800'
                                }`}>
                                  {userRole.roleScope}
                                </span>
                                <span className="text-xs text-gray-500">
                                  Granted {new Date(userRole.grantedAt).toLocaleDateString()}
                                </span>
                                {userRole.expiresAt && (
                                  <div className="flex items-center space-x-1">
                                    {isRoleExpired(userRole.expiresAt) ? (
                                      <AlertCircle className="w-3 h-3 text-red-500" />
                                    ) : isRoleExpiringSoon(userRole.expiresAt) ? (
                                      <AlertCircle className="w-3 h-3 text-yellow-500" />
                                    ) : (
                                      <Calendar className="w-3 h-3 text-gray-400" />
                                    )}
                                    <span className={`text-xs ${
                                      isRoleExpired(userRole.expiresAt) ? 'text-red-600' :
                                      isRoleExpiringSoon(userRole.expiresAt) ? 'text-yellow-600' :
                                      'text-gray-500'
                                    }`}>
                                      {isRoleExpired(userRole.expiresAt) ? 'Expired' : 'Expires'}{' '}
                                      {new Date(userRole.expiresAt).toLocaleDateString()}
                                    </span>
                                  </div>
                                )}
                              </div>
                            </div>
                          </div>
                          {userRole.scopeContext && Object.keys(userRole.scopeContext).length > 0 && (
                            <div className="mt-2 p-2 bg-gray-50 rounded border text-xs">
                              <strong>Context:</strong> {JSON.stringify(userRole.scopeContext)}
                            </div>
                          )}
                        </div>
                        <button
                          onClick={() => handleRemoveRole(userRole.roleId)}
                          className="text-gray-400 hover:text-red-600 ml-4"
                        >
                          <X className="w-4 h-4" />
                        </button>
                      </div>
                    </div>
                  ))}

                  {userRoles.length === 0 && (
                    <div className="p-8 text-center">
                      <Shield className="w-12 h-12 text-gray-300 mx-auto mb-3" />
                      <p className="text-gray-500">No roles assigned to this user</p>
                      <button
                        onClick={() => setShowAssignModal(true)}
                        className="mt-2 text-blue-600 hover:text-blue-700"
                      >
                        Assign your first role
                      </button>
                    </div>
                  )}
                </div>
              </div>
            </>
          ) : (
            <div className="bg-white rounded-lg border border-gray-200 p-8 text-center">
              <Users className="w-12 h-12 text-gray-300 mx-auto mb-3" />
              <p className="text-gray-500">Select a user to view and manage their roles</p>
            </div>
          )}
        </div>
      </div>

      {/* Assign Role Modal */}
      {showAssignModal && selectedUser && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-full max-w-md">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-semibold text-gray-900">Assign Role</h3>
              <button
                onClick={() => setShowAssignModal(false)}
                className="text-gray-400 hover:text-gray-600"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleAssignRole} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  User
                </label>
                <div className="p-3 bg-gray-50 rounded-lg border">
                  <div className="flex items-center space-x-3">
                    <div className="w-8 h-8 bg-gray-300 rounded-full flex items-center justify-center text-sm">
                      {selectedUser.displayName?.charAt(0) || selectedUser.email.charAt(0).toUpperCase()}
                    </div>
                    <div>
                      <p className="font-medium text-gray-900">
                        {selectedUser.displayName || selectedUser.email}
                      </p>
                      <p className="text-sm text-gray-600">{selectedUser.email}</p>
                    </div>
                  </div>
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Role
                </label>
                <select
                  value={assignmentForm.roleId}
                  onChange={(e) => setAssignmentForm({ ...assignmentForm, roleId: e.target.value })}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                  required
                >
                  <option value="">Select a role</option>
                  {roles.map((role) => (
                    <option key={role.id} value={role.id}>
                      {role.name} ({role.scope})
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Expiry Date (Optional)
                </label>
                <input
                  type="datetime-local"
                  value={assignmentExpiry}
                  onChange={(e) => setAssignmentExpiry(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Scope Context (JSON, Optional)
                </label>
                <textarea
                  value={assignmentContext}
                  onChange={(e) => setAssignmentContext(e.target.value)}
                  placeholder='{"organizationId": "uuid", "teamId": "uuid"}'
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                  rows={3}
                />
              </div>

              <div className="flex space-x-3">
                <button
                  type="submit"
                  disabled={loading}
                  className="flex-1 bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 disabled:opacity-50 transition-colors"
                >
                  {loading ? 'Assigning...' : 'Assign Role'}
                </button>
                <button
                  type="button"
                  onClick={() => setShowAssignModal(false)}
                  className="px-4 py-2 text-gray-600 border border-gray-300 rounded-lg hover:bg-gray-50 transition-colors"
                >
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default UserRoleAssignment;

// Common Badge Component
import React from 'react';
import './Badge.css';

interface BadgeProps {
  children: React.ReactNode;
  variant?: 'default' | 'featured' | 'free' | 'premium' | 'ai' | 'verified' | 'new' | 'popular' | 'success' | 'warning' | 'error';
  size?: 'small' | 'medium' | 'large';
  icon?: React.ReactNode;
  className?: string;
}

export const Badge: React.FC<BadgeProps> = ({
  children,
  variant = 'default',
  size = 'medium',
  icon,
  className = ''
}) => {
  return (
    <span className={`badge ${variant} ${size} ${className}`}>
      {icon && <span className="badge-icon">{icon}</span>}
      <span className="badge-text">{children}</span>
    </span>
  );
};

// Common Loading Spinner Component
import React from 'react';
import './LoadingSpinner.css';

interface LoadingSpinnerProps {
  size?: 'small' | 'medium' | 'large';
  variant?: 'default' | 'dots' | 'pulse';
  message?: string;
  className?: string;
}

export const LoadingSpinner: React.FC<LoadingSpinnerProps> = ({
  size = 'medium',
  variant = 'default',
  message,
  className = ''
}) => {
  const renderSpinner = () => {
    switch (variant) {
      case 'dots':
        return (
          <div className="spinner-dots">
            <div className="dot"></div>
            <div className="dot"></div>
            <div className="dot"></div>
          </div>
        );

      case 'pulse':
        return (
          <div className="spinner-pulse">
            <div className="pulse-ring"></div>
            <div className="pulse-ring"></div>
            <div className="pulse-ring"></div>
          </div>
        );

      default:
        return (
          <div className="spinner-circle">
            <svg className="circular" viewBox="25 25 50 50">
              <circle
                className="path"
                cx="50"
                cy="50"
                r="20"
                fill="none"
                strokeWidth="2"
                strokeMiterlimit="10"
              />
            </svg>
          </div>
        );
    }
  };

  return (
    <div className={`loading-spinner ${size} ${variant} ${className}`} role="status" aria-live="polite">
      {renderSpinner()}
      {message && (
        <span className="loading-message" aria-label={message}>
          {message}
        </span>
      )}
      <span className="sr-only">Loading...</span>
    </div>
  );
};

export default LoadingSpinner;

import React from 'react';

interface ValidationMessageProps {
  message: string;
  type?: 'error' | 'warning' | 'success' | 'info';
  className?: string;
}

export const ValidationMessage: React.FC<ValidationMessageProps> = ({ 
  message,
  type = 'error',
  className = '' 
}) => {
  const typeClasses = {
    error: 'text-red-600 bg-red-50 border-red-200',
    warning: 'text-yellow-600 bg-yellow-50 border-yellow-200',
    success: 'text-green-600 bg-green-50 border-green-200',
    info: 'text-blue-600 bg-blue-50 border-blue-200'
  };

  if (!message) return null;

  return (
    <div className={`p-3 rounded border ${typeClasses[type]} ${className}`}>
      {message}
    </div>
  );
};

export default ValidationMessage;

// Epic 16 Marketplace - Advanced Filters Component
import React, { useState } from 'react';
import './SearchBar.css';

interface FilterOptions {
  categories: string[];
  tags: string[];
  priceRange: {
    min?: number;
    max?: number;
  };
  rating: number;
  complexity: 'beginner' | 'intermediate' | 'advanced' | 'all';
  compatibility: string[];
  isFree: boolean | null;
  isAiGenerated: boolean | null;
  sortBy: 'relevance' | 'price_asc' | 'price_desc' | 'rating' | 'popularity' | 'newest' | 'oldest';
}

interface AdvancedFiltersProps {
  filters: FilterOptions;
  onFiltersChange: (filters: FilterOptions) => void;
  availableCategories: Array<{ id: string; name: string }>;
  availableTags: string[];
  className?: string;
}

export const AdvancedFilters: React.FC<AdvancedFiltersProps> = ({
  filters,
  onFiltersChange,
  availableCategories,
  availableTags,
  className = ''
}) => {
  const [showAdvanced, setShowAdvanced] = useState(false);

  const updateFilter = (key: keyof FilterOptions, value: any) => {
    onFiltersChange({
      ...filters,
      [key]: value
    });
  };

  const toggleCategory = (categoryId: string) => {
    const newCategories = filters.categories.includes(categoryId)
      ? filters.categories.filter(id => id !== categoryId)
      : [...filters.categories, categoryId];
    updateFilter('categories', newCategories);
  };

  const toggleTag = (tag: string) => {
    const newTags = filters.tags.includes(tag)
      ? filters.tags.filter(t => t !== tag)
      : [...filters.tags, tag];
    updateFilter('tags', newTags);
  };

  const toggleCompatibility = (compat: string) => {
    const newCompat = filters.compatibility.includes(compat)
      ? filters.compatibility.filter(c => c !== compat)
      : [...filters.compatibility, compat];
    updateFilter('compatibility', newCompat);
  };

  const clearAllFilters = () => {
    onFiltersChange({
      categories: [],
      tags: [],
      priceRange: {},
      rating: 0,
      complexity: 'all',
      compatibility: [],
      isFree: null,
      isAiGenerated: null,
      sortBy: 'relevance'
    });
  };

  const hasActiveFilters = () => {
    return filters.categories.length > 0 ||
           filters.tags.length > 0 ||
           filters.priceRange.min !== undefined ||
           filters.priceRange.max !== undefined ||
           filters.rating > 0 ||
           filters.complexity !== 'all' ||
           filters.compatibility.length > 0 ||
           filters.isFree !== null ||
           filters.isAiGenerated !== null ||
           filters.sortBy !== 'relevance';
  };

  return (
    <div className={`advanced-filters-container ${className}`}>
      {/* Filter Toggle */}
      <div className="filter-toggle">
        <button
          onClick={() => setShowAdvanced(!showAdvanced)}
          className={`toggle-button ${showAdvanced ? 'active' : ''}`}
        >
          <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
            <path
              d="M3 4.5h10M3 8h6M3 11.5h4"
              stroke="currentColor"
              strokeWidth="1.5"
              strokeLinecap="round"
            />
          </svg>
          Advanced Filters
          {hasActiveFilters() && (
            <span className="filter-count">
              {[
                filters.categories.length,
                filters.tags.length,
                filters.compatibility.length,
                filters.priceRange.min !== undefined ? 1 : 0,
                filters.priceRange.max !== undefined ? 1 : 0,
                filters.rating > 0 ? 1 : 0,
                filters.complexity !== 'all' ? 1 : 0,
                filters.isFree !== null ? 1 : 0,
                filters.isAiGenerated !== null ? 1 : 0
              ].reduce((a, b) => a + b, 0)}
            </span>
          )}
        </button>

        {hasActiveFilters() && (
          <button onClick={clearAllFilters} className="clear-filters">
            Clear All
          </button>
        )}
      </div>

      {/* Advanced Filters Panel */}
      {showAdvanced && (
        <div className="advanced-filters">
          {/* Categories */}
          <div className="filter-group">
            <label className="filter-label">Categories</label>
            <div className="filter-chips">
              {availableCategories.map(category => (
                <button
                  key={category.id}
                  onClick={() => toggleCategory(category.id)}
                  className={`filter-chip ${
                    filters.categories.includes(category.id) ? 'active' : ''
                  }`}
                >
                  {category.name}
                </button>
              ))}
            </div>
          </div>

          {/* Tags */}
          <div className="filter-group">
            <label className="filter-label">Popular Tags</label>
            <div className="filter-chips">
              {availableTags.slice(0, 12).map(tag => (
                <button
                  key={tag}
                  onClick={() => toggleTag(tag)}
                  className={`filter-chip ${
                    filters.tags.includes(tag) ? 'active' : ''
                  }`}
                >
                  #{tag}
                </button>
              ))}
            </div>
          </div>

          {/* Price Range */}
          <div className="filter-group">
            <label className="filter-label">Price Range</label>
            <div className="price-range-inputs">
              <input
                type="number"
                placeholder="Min ($)"
                value={filters.priceRange.min || ''}
                onChange={(e) => updateFilter('priceRange', {
                  ...filters.priceRange,
                  min: e.target.value ? parseFloat(e.target.value) : undefined
                })}
                className="price-input"
              />
              <span className="price-separator">to</span>
              <input
                type="number"
                placeholder="Max ($)"
                value={filters.priceRange.max || ''}
                onChange={(e) => updateFilter('priceRange', {
                  ...filters.priceRange,
                  max: e.target.value ? parseFloat(e.target.value) : undefined
                })}
                className="price-input"
              />
            </div>
          </div>

          {/* Rating */}
          <div className="filter-group">
            <label className="filter-label">Minimum Rating</label>
            <div className="rating-filter">
              {[1, 2, 3, 4, 5].map(rating => (
                <button
                  key={rating}
                  onClick={() => updateFilter('rating', rating === filters.rating ? 0 : rating)}
                  className={`rating-button ${
                    filters.rating >= rating ? 'active' : ''
                  }`}
                >
                  <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
                    <path
                      d="M8 1l2.09 4.26L14 6l-3 2.96L11.64 13 8 10.64 4.36 13 5 8.96 2 6l3.91-.74L8 1z"
                      fill={filters.rating >= rating ? '#fbbf24' : 'none'}
                      stroke={filters.rating >= rating ? '#fbbf24' : 'currentColor'}
                      strokeWidth="1"
                    />
                  </svg>
                </button>
              ))}
              <span className="rating-text">
                {filters.rating > 0 ? `${filters.rating}+ stars` : 'Any rating'}
              </span>
            </div>
          </div>

          {/* Complexity */}
          <div className="filter-group">
            <label className="filter-label">Complexity Level</label>
            <div className="filter-chips">
              {[
                { value: 'all', label: 'All Levels' },
                { value: 'beginner', label: 'Beginner' },
                { value: 'intermediate', label: 'Intermediate' },
                { value: 'advanced', label: 'Advanced' }
              ].map(level => (
                <button
                  key={level.value}
                  onClick={() => updateFilter('complexity', level.value)}
                  className={`filter-chip ${
                    filters.complexity === level.value ? 'active' : ''
                  }`}
                >
                  {level.label}
                </button>
              ))}
            </div>
          </div>

          {/* Claude Compatibility */}
          <div className="filter-group">
            <label className="filter-label">Claude Compatibility</label>
            <div className="filter-chips">
              {[
                'claude-3-haiku',
                'claude-3-sonnet',
                'claude-3-opus',
                'claude-3.5-sonnet'
              ].map(model => (
                <button
                  key={model}
                  onClick={() => toggleCompatibility(model)}
                  className={`filter-chip ${
                    filters.compatibility.includes(model) ? 'active' : ''
                  }`}
                >
                  {model.replace('claude-', 'Claude ')}
                </button>
              ))}
            </div>
          </div>

          {/* Content Type */}
          <div className="filter-group">
            <label className="filter-label">Content Type</label>
            <div className="filter-chips">
              <button
                onClick={() => updateFilter('isFree', filters.isFree === true ? null : true)}
                className={`filter-chip ${filters.isFree === true ? 'active' : ''}`}
              >
                Free Only
              </button>
              <button
                onClick={() => updateFilter('isFree', filters.isFree === false ? null : false)}
                className={`filter-chip ${filters.isFree === false ? 'active' : ''}`}
              >
                Premium Only
              </button>
              <button
                onClick={() => updateFilter('isAiGenerated', filters.isAiGenerated === true ? null : true)}
                className={`filter-chip ${filters.isAiGenerated === true ? 'active' : ''}`}
              >
                AI Generated
              </button>
              <button
                onClick={() => updateFilter('isAiGenerated', filters.isAiGenerated === false ? null : false)}
                className={`filter-chip ${filters.isAiGenerated === false ? 'active' : ''}`}
              >
                Human Created
              </button>
            </div>
          </div>

          {/* Sort Options */}
          <div className="filter-group">
            <label className="filter-label">Sort By</label>
            <select
              value={filters.sortBy}
              onChange={(e) => updateFilter('sortBy', e.target.value)}
              className="sort-select"
            >
              <option value="relevance">Relevance</option>
              <option value="popularity">Most Popular</option>
              <option value="rating">Highest Rated</option>
              <option value="newest">Newest First</option>
              <option value="oldest">Oldest First</option>
              <option value="price_asc">Price: Low to High</option>
              <option value="price_desc">Price: High to Low</option>
            </select>
          </div>
        </div>
      )}
    </div>
  );
};

// Epic 16 Marketplace - Category Navigation Component
import React from 'react';
import './CategoryNav.css';

interface Category {
  id: string;
  name: string;
  description?: string;
  icon?: string;
  sort_order: number;
  parent_id?: string;
}

interface CategoryNavProps {
  categories: Category[];
  selectedCategory: string | null;
  onCategorySelect: (categoryId: string | null) => void;
  showIcons?: boolean;
  variant?: 'sidebar' | 'horizontal' | 'dropdown';
  className?: string;
}

export const CategoryNav: React.FC<CategoryNavProps> = ({
  categories,
  selectedCategory,
  onCategorySelect,
  showIcons = true,
  variant = 'sidebar',
  className = ''
}) => {
  // Group categories by parent
  const rootCategories = categories.filter(cat => !cat.parent_id);
  const subcategories = categories.filter(cat => cat.parent_id);

  const getSubcategories = (parentId: string) => {
    return subcategories.filter(cat => cat.parent_id === parentId);
  };

  const getCategoryIcon = (iconName?: string) => {
    if (!showIcons || !iconName) return null;

    const iconMap: Record<string, JSX.Element> = {
      'edit': (
        <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
          <path
            d="M11.5 2.5L13.5 4.5L5 13H3V11L11.5 2.5Z"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
      ),
      'briefcase': (
        <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
          <rect
            x="2"
            y="4"
            width="12"
            height="8"
            rx="1"
            stroke="currentColor"
            strokeWidth="1.5"
          />
          <path
            d="M6 4V3C6 2.44772 6.44772 2 7 2H9C9.55228 2 10 2.44772 10 3V4"
            stroke="currentColor"
            strokeWidth="1.5"
          />
        </svg>
      ),
      'academic-cap': (
        <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
          <path
            d="M8 1L15 4L8 7L1 4L8 1Z"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
          <path
            d="M3 6V10C3 10.5523 5.23858 11 8 11C10.7614 11 13 10.5523 13 10V6"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
      ),
      'sparkles': (
        <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
          <path
            d="M8 1L9 5L13 6L9 7L8 11L7 7L3 6L7 5L8 1Z"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
          <path
            d="M12 2L12.5 3.5L14 4L12.5 4.5L12 6L11.5 4.5L10 4L11.5 3.5L12 2Z"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
      ),
      'code': (
        <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
          <path
            d="M5 12L1 8L5 4M11 4L15 8L11 12M10 2L6 14"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
      ),
      'chart-bar': (
        <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
          <path
            d="M2 14V10H5V14H2ZM6 14V6H9V14H6ZM10 14V2H13V14H10Z"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
      )
    };

    return iconMap[iconName] || null;
  };

  const handleCategoryClick = (categoryId: string | null) => {
    onCategorySelect(categoryId);
  };

  if (variant === 'horizontal') {
    return (
      <nav className={`category-nav horizontal ${className}`}>
        <div className="category-list">
          <button
            onClick={() => handleCategoryClick(null)}
            className={`category-item ${!selectedCategory ? 'active' : ''}`}
          >
            All Templates
          </button>
          {rootCategories.map((category) => (
            <button
              key={category.id}
              onClick={() => handleCategoryClick(category.id)}
              className={`category-item ${selectedCategory === category.id ? 'active' : ''}`}
            >
              {showIcons && getCategoryIcon(category.icon)}
              <span>{category.name}</span>
            </button>
          ))}
        </div>
      </nav>
    );
  }

  if (variant === 'dropdown') {
    return (
      <div className={`category-nav dropdown ${className}`}>
        <select
          value={selectedCategory || ''}
          onChange={(e) => handleCategoryClick(e.target.value || null)}
          className="category-select"
        >
          <option value="">All Categories</option>
          {rootCategories.map((category) => (
            <option key={category.id} value={category.id}>
              {category.name}
            </option>
          ))}
        </select>
      </div>
    );
  }

  // Default sidebar variant
  return (
    <nav className={`category-nav sidebar ${className}`}>
      <div className="category-list">
        <button
          onClick={() => handleCategoryClick(null)}
          className={`category-item all ${!selectedCategory ? 'active' : ''}`}
        >
          <span className="category-name">All Templates</span>
        </button>

        {rootCategories.map((category) => {
          const subcats = getSubcategories(category.id);
          const isSelected = selectedCategory === category.id;
          const hasSelectedSubcat = subcats.some(sub => sub.id === selectedCategory);

          return (
            <div key={category.id} className="category-group">
              <button
                onClick={() => handleCategoryClick(category.id)}
                className={`category-item parent ${isSelected ? 'active' : ''} ${hasSelectedSubcat ? 'has-selected-child' : ''}`}
                title={category.description}
              >
                <div className="category-content">
                  {getCategoryIcon(category.icon)}
                  <span className="category-name">{category.name}</span>
                </div>
              </button>

              {/* Subcategories */}
              {subcats.length > 0 && (hasSelectedSubcat || isSelected) && (
                <div className="subcategory-list">
                  {subcats.map((subcategory) => (
                    <button
                      key={subcategory.id}
                      onClick={() => handleCategoryClick(subcategory.id)}
                      className={`category-item subcategory ${selectedCategory === subcategory.id ? 'active' : ''}`}
                      title={subcategory.description}
                    >
                      <span className="category-name">{subcategory.name}</span>
                    </button>
                  ))}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </nav>
  );
};

// Epic 16.1.5 - Checkout Flow Component
import React, { useState, useEffect } from 'react';
import { 
  CreditCardIcon, 
  LockClosedIcon,
  CheckCircleIcon,
  ExclamationTriangleIcon,
  ArrowLeftIcon
} from '@heroicons/react/24/outline';
import { loadStripe, StripeElementsOptions } from '@stripe/stripe-js';
import { Elements, CardElement, useStripe, useElements } from '@stripe/react-stripe-js';
import { BillingAddress, PaymentIntent } from '../../types/marketplace';
import { useMarketplace } from '../../hooks/useMarketplace';
import { PriceDisplay } from './PriceDisplay';
import './CheckoutFlow.css';

// Initialize Stripe
const stripePromise = loadStripe(process.env.REACT_APP_STRIPE_PUBLISHABLE_KEY!);

interface CheckoutFlowProps {
  onBack: () => void;
  onSuccess: (orderId: string) => void;
}

export const CheckoutFlow: React.FC<CheckoutFlowProps> = ({ onBack, onSuccess }) => {
  const [currentStep, setCurrentStep] = useState<'billing' | 'payment' | 'confirmation'>('billing');
  const [billingAddress, setBillingAddress] = useState<BillingAddress>({
    name: '',
    email: '',
    line1: '',
    line2: '',
    city: '',
    state: '',
    postal_code: '',
    country: 'US',
  });
  const [paymentIntent, setPaymentIntent] = useState<PaymentIntent | null>(null);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [processing, setProcessing] = useState(false);

  const { cart } = useMarketplace();

  const elementsOptions: StripeElementsOptions = {
    appearance: {
      theme: 'stripe',
      variables: {
        colorPrimary: '#3b82f6',
      },
    },
  };

  const steps = [
    { id: 'billing', title: 'Billing Address', completed: currentStep !== 'billing' },
    { id: 'payment', title: 'Payment', completed: currentStep === 'confirmation' },
    { id: 'confirmation', title: 'Confirmation', completed: false },
  ];

  return (
    <div className="checkout-flow">
      {/* Header */}
      <div className="checkout-header">
        <button onClick={onBack} className="back-btn">
          <ArrowLeftIcon className="w-5 h-5" />
          Back to Cart
        </button>

        <h1>Checkout</h1>

        <div className="checkout-security">
          <LockClosedIcon className="w-4 h-4" />
          <span>Secure Checkout</span>
        </div>
      </div>

      {/* Progress Steps */}
      <div className="checkout-steps">
        {steps.map((step, index) => (
          <div key={step.id} className={`step ${step.completed ? 'completed' : ''} ${currentStep === step.id ? 'active' : ''}`}>
            <div className="step-indicator">
              {step.completed ? (
                <CheckCircleIcon className="w-5 h-5" />
              ) : (
                <span>{index + 1}</span>
              )}
            </div>
            <span className="step-title">{step.title}</span>
          </div>
        ))}
      </div>

      {/* Content */}
      <div className="checkout-content">
        <div className="checkout-main">
          {currentStep === 'billing' && (
            <BillingAddressForm
              address={billingAddress}
              onChange={setBillingAddress}
              errors={errors}
              onNext={() => setCurrentStep('payment')}
            />
          )}

          {currentStep === 'payment' && (
            <Elements stripe={stripePromise} options={elementsOptions}>
              <PaymentForm
                billingAddress={billingAddress}
                paymentIntent={paymentIntent}
                onPaymentIntentCreated={setPaymentIntent}
                onBack={() => setCurrentStep('billing')}
                onNext={() => setCurrentStep('confirmation')}
                onSuccess={onSuccess}
                processing={processing}
                setProcessing={setProcessing}
              />
            </Elements>
          )}

          {currentStep === 'confirmation' && (
            <ConfirmationStep
              paymentIntent={paymentIntent}
              onBack={() => setCurrentStep('payment')}
              onSuccess={onSuccess}
            />
          )}
        </div>

        {/* Order Summary Sidebar */}
        <OrderSummary cart={cart} />
      </div>
    </div>
  );
};

// Billing Address Form Component
interface BillingAddressFormProps {
  address: BillingAddress;
  onChange: (address: BillingAddress) => void;
  errors: Record<string, string>;
  onNext: () => void;
}

const BillingAddressForm: React.FC<BillingAddressFormProps> = ({
  address,
  onChange,
  errors,
  onNext
}) => {
  const [formErrors, setFormErrors] = useState<Record<string, string>>({});

  const handleChange = (field: keyof BillingAddress, value: string) => {
    onChange({ ...address, [field]: value });

    // Clear error when user starts typing
    if (formErrors[field]) {
      setFormErrors(prev => ({ ...prev, [field]: '' }));
    }
  };

  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {};

    if (!address.name.trim()) newErrors.name = 'Name is required';
    if (!address.email.trim()) newErrors.email = 'Email is required';
    else if (!/\S+@\S+\.\S+/.test(address.email)) newErrors.email = 'Email is invalid';
    if (!address.line1.trim()) newErrors.line1 = 'Address is required';
    if (!address.city.trim()) newErrors.city = 'City is required';
    if (!address.postal_code.trim()) newErrors.postal_code = 'Postal code is required';
    if (!address.country) newErrors.country = 'Country is required';

    setFormErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (validateForm()) {
      onNext();
    }
  };

  return (
    <div className="billing-form">
      <h2>Billing Address</h2>
      <p className="form-description">
        We'll use this information for your receipt and tax calculations.
      </p>

      <form onSubmit={handleSubmit} className="form">
        <div className="form-row">
          <div className="form-group">
            <label htmlFor="name">Full Name *</label>
            <input
              type="text"
              id="name"
              value={address.name}
              onChange={(e) => handleChange('name', e.target.value)}
              className={formErrors.name ? 'error' : ''}
              placeholder="John Doe"
            />
            {formErrors.name && <div className="error-message">{formErrors.name}</div>}
          </div>

          <div className="form-group">
            <label htmlFor="email">Email Address *</label>
            <input
              type="email"
              id="email"
              value={address.email}
              onChange={(e) => handleChange('email', e.target.value)}
              className={formErrors.email ? 'error' : ''}
              placeholder="john@example.com"
            />
            {formErrors.email && <div className="error-message">{formErrors.email}</div>}
          </div>
        </div>

        <div className="form-group">
          <label htmlFor="line1">Address Line 1 *</label>
          <input
            type="text"
            id="line1"
            value={address.line1}
            onChange={(e) => handleChange('line1', e.target.value)}
            className={formErrors.line1 ? 'error' : ''}
            placeholder="123 Main Street"
          />
          {formErrors.line1 && <div className="error-message">{formErrors.line1}</div>}
        </div>

        <div className="form-group">
          <label htmlFor="line2">Address Line 2</label>
          <input
            type="text"
            id="line2"
            value={address.line2 || ''}
            onChange={(e) => handleChange('line2', e.target.value)}
            placeholder="Apartment, suite, etc. (optional)"
          />
        </div>

        <div className="form-row">
          <div className="form-group">
            <label htmlFor="city">City *</label>
            <input
              type="text"
              id="city"
              value={address.city}
              onChange={(e) => handleChange('city', e.target.value)}
              className={formErrors.city ? 'error' : ''}
              placeholder="New York"
            />
            {formErrors.city && <div className="error-message">{formErrors.city}</div>}
          </div>

          <div className="form-group">
            <label htmlFor="state">State/Province</label>
            <input
              type="text"
              id="state"
              value={address.state || ''}
              onChange={(e) => handleChange('state', e.target.value)}
              placeholder="NY"
            />
          </div>

          <div className="form-group">
            <label htmlFor="postal_code">Postal Code *</label>
            <input
              type="text"
              id="postal_code"
              value={address.postal_code}
              onChange={(e) => handleChange('postal_code', e.target.value)}
              className={formErrors.postal_code ? 'error' : ''}
              placeholder="10001"
            />
            {formErrors.postal_code && <div className="error-message">{formErrors.postal_code}</div>}
          </div>
        </div>

        <div className="form-group">
          <label htmlFor="country">Country *</label>
          <select
            id="country"
            value={address.country}
            onChange={(e) => handleChange('country', e.target.value)}
            className={formErrors.country ? 'error' : ''}
          >
            <option value="US">United States</option>
            <option value="CA">Canada</option>
            <option value="GB">United Kingdom</option>
            <option value="AU">Australia</option>
            <option value="DE">Germany</option>
            <option value="FR">France</option>
            <option value="JP">Japan</option>
            {/* Add more countries as needed */}
          </select>
          {formErrors.country && <div className="error-message">{formErrors.country}</div>}
        </div>

        <div className="form-group">
          <label htmlFor="tax_id">Tax ID (Optional)</label>
          <input
            type="text"
            id="tax_id"
            value={address.tax_id || ''}
            onChange={(e) => handleChange('tax_id', e.target.value)}
            placeholder="For business purchases"
          />
        </div>

        <button type="submit" className="btn btn-primary">
          Continue to Payment
        </button>
      </form>
    </div>
  );
};

// Payment Form Component
interface PaymentFormProps {
  billingAddress: BillingAddress;
  paymentIntent: PaymentIntent | null;
  onPaymentIntentCreated: (intent: PaymentIntent) => void;
  onBack: () => void;
  onNext: () => void;
  onSuccess: (orderId: string) => void;
  processing: boolean;
  setProcessing: (processing: boolean) => void;
}

const PaymentForm: React.FC<PaymentFormProps> = ({
  billingAddress,
  paymentIntent,
  onPaymentIntentCreated,
  onBack,
  onSuccess,
  processing,
  setProcessing
}) => {
  const stripe = useStripe();
  const elements = useElements();
  const [error, setError] = useState<string>('');
  const [savePaymentMethod, setSavePaymentMethod] = useState(false);

  const { cart, createPaymentIntent, processPayment } = useMarketplace();

  useEffect(() => {
    if (!paymentIntent && cart && billingAddress.email) {
      handleCreatePaymentIntent();
    }
  }, [cart, billingAddress.email]);

  const handleCreatePaymentIntent = async () => {
    if (!cart) return;

    try {
      setProcessing(true);
      const intent = await createPaymentIntent({
        cart_id: cart.id,
        billing_address: billingAddress,
        save_payment_method: savePaymentMethod
      });
      onPaymentIntentCreated(intent);
    } catch (err: any) {
      setError(err.message || 'Failed to prepare payment');
    } finally {
      setProcessing(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!stripe || !elements || !paymentIntent) {
      setError('Payment system not ready');
      return;
    }

    const cardElement = elements.getElement(CardElement);
    if (!cardElement) {
      setError('Card element not found');
      return;
    }

    setProcessing(true);
    setError('');

    try {
      // Confirm payment with Stripe
      const { error: stripeError } = await stripe.confirmCardPayment(
        paymentIntent.client_secret!,
        {
          payment_method: {
            card: cardElement,
            billing_details: {
              name: billingAddress.name,
              email: billingAddress.email,
              address: {
                line1: billingAddress.line1,
                line2: billingAddress.line2 || undefined,
                city: billingAddress.city,
                state: billingAddress.state || undefined,
                postal_code: billingAddress.postal_code,
                country: billingAddress.country,
              },
            },
          },
        }
      );

      if (stripeError) {
        setError(stripeError.message || 'Payment failed');
        return;
      }

      // Process payment on our backend
      const order = await processPayment({
        payment_intent_id: paymentIntent.id
      });

      onSuccess(order.id);

    } catch (err: any) {
      setError(err.message || 'Payment processing failed');
    } finally {
      setProcessing(false);
    }
  };

  return (
    <div className="payment-form">
      <h2>Payment Information</h2>
      <p className="form-description">
        Your payment is secured with 256-bit SSL encryption.
      </p>

      {error && (
        <div className="error-alert">
          <ExclamationTriangleIcon className="w-5 h-5" />
          <span>{error}</span>
        </div>
      )}

      <form onSubmit={handleSubmit} className="form">
        <div className="card-element-container">
          <label>Card Information</label>
          <div className="card-element">
            <CardElement
              options={{
                style: {
                  base: {
                    fontSize: '16px',
                    color: '#424770',
                    '::placeholder': {
                      color: '#aab7c4',
                    },
                  },
                },
                hidePostalCode: true, // We collect this separately
              }}
            />
          </div>
        </div>

        <div className="payment-options">
          <label className="checkbox-label">
            <input
              type="checkbox"
              checked={savePaymentMethod}
              onChange={(e) => setSavePaymentMethod(e.target.checked)}
            />
            <span>Save payment method for future purchases</span>
          </label>
        </div>

        <div className="form-actions">
          <button type="button" onClick={onBack} className="btn btn-secondary">
            Back
          </button>

          <button 
            type="submit" 
            className="btn btn-primary"
            disabled={!stripe || processing}
          >
            <CreditCardIcon className="w-5 h-5" />
            {processing ? 'Processing...' : `Pay ${cart ? '$' + (cart.total_cents / 100).toFixed(2) : ''}`}
          </button>
        </div>
      </form>
    </div>
  );
};

