// Order Summary Component
interface OrderSummaryProps {
  cart: any; // ShoppingCart type
}

const OrderSummary: React.FC<OrderSummaryProps> = ({ cart }) => {
  if (!cart || !cart.items || cart.items.length === 0) {
    return null;
  }

  const subtotal = cart.items.reduce((sum: number, item: any) => 
    sum + (item.unit_price_cents * item.quantity), 0
  );

  return (
    <div className="order-summary">
      <h3>Order Summary</h3>

      <div className="summary-items">
        {cart.items.map((item: any) => (
          <div key={item.id} className="summary-item">
            <div className="item-details">
              <div className="item-name">Template {item.template_id.slice(0, 8)}</div>
              <div className="item-license">{item.license_type}</div>
            </div>
            <div className="item-price">
              <PriceDisplay cents={item.unit_price_cents * item.quantity} />
            </div>
          </div>
        ))}
      </div>

      <div className="summary-totals">
        <div className="total-row">
          <span>Subtotal:</span>
          <PriceDisplay cents={subtotal} />
        </div>

        {cart.tax_cents > 0 && (
          <div className="total-row">
            <span>Tax:</span>
            <PriceDisplay cents={cart.tax_cents} />
          </div>
        )}

        <div className="total-row total-final">
          <span>Total:</span>
          <PriceDisplay cents={cart.total_cents || subtotal} />
        </div>
      </div>
    </div>
  );
};

// Epic 16 Marketplace - Enhanced Search Bar with Autocomplete
import React, { useState, useRef, useEffect, useCallback } from 'react';
import { useMarketplace } from '../../hooks/useMarketplace';
import './SearchBar.css';

interface EnhancedSearchBarProps {
  value: string;
  onChange: (value: string) => void;
  onSubmit?: () => void;
  placeholder?: string;
  className?: string;
}

export const EnhancedSearchBar: React.FC<EnhancedSearchBarProps> = ({
  value,
  onChange,
  onSubmit,
  placeholder = 'Search templates, categories, or tags...',
  className = ''
}) => {
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [selectedSuggestion, setSelectedSuggestion] = useState(-1);
  const [loading, setLoading] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);
  const suggestionsRef = useRef<HTMLDivElement>(null);
  const { getSearchSuggestions } = useMarketplace();

  // Debounced suggestion fetching
  const debouncedGetSuggestions = useCallback(
    debounce(async (query: string) => {
      if (query.length < 2) {
        setSuggestions([]);
        setShowSuggestions(false);
        return;
      }

      setLoading(true);
      try {
        const newSuggestions = await getSearchSuggestions(query);
        setSuggestions(newSuggestions);
        setShowSuggestions(newSuggestions.length > 0);
      } catch (error) {
        console.error('Failed to fetch suggestions:', error);
        setSuggestions([]);
        setShowSuggestions(false);
      } finally {
        setLoading(false);
      }
    }, 300),
    [getSearchSuggestions]
  );

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        suggestionsRef.current &&
        !suggestionsRef.current.contains(event.target as Node) &&
        !inputRef.current?.contains(event.target as Node)
      ) {
        setShowSuggestions(false);
        setSelectedSuggestion(-1);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    debouncedGetSuggestions(value);
  }, [value, debouncedGetSuggestions]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newValue = e.target.value;
    onChange(newValue);
    setSelectedSuggestion(-1);
  };

  const handleInputFocus = () => {
    if (suggestions.length > 0 && value.length >= 2) {
      setShowSuggestions(true);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (!showSuggestions) {
      if (e.key === 'Enter') {
        handleSubmit();
      }
      return;
    }

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setSelectedSuggestion(prev => 
          prev < suggestions.length - 1 ? prev + 1 : 0
        );
        break;
      case 'ArrowUp':
        e.preventDefault();
        setSelectedSuggestion(prev => 
          prev > 0 ? prev - 1 : suggestions.length - 1
        );
        break;
      case 'Enter':
        e.preventDefault();
        if (selectedSuggestion >= 0 && selectedSuggestion < suggestions.length) {
          handleSuggestionSelect(suggestions[selectedSuggestion]);
        } else {
          handleSubmit();
        }
        break;
      case 'Escape':
        setShowSuggestions(false);
        setSelectedSuggestion(-1);
        inputRef.current?.blur();
        break;
    }
  };

  const handleSuggestionSelect = (suggestion: string) => {
    onChange(suggestion);
    setShowSuggestions(false);
    setSelectedSuggestion(-1);
    handleSubmit();
  };

  const handleSubmit = () => {
    onSubmit?.();
    setShowSuggestions(false);
    setSelectedSuggestion(-1);
  };

  const handleClearSearch = () => {
    onChange('');
    setShowSuggestions(false);
    setSelectedSuggestion(-1);
    setSuggestions([]);
    inputRef.current?.focus();
  };

  return (
    <div className={`search-bar enhanced-search-bar ${className}`}>
      <div className="search-input-container">
        <div className="search-icon">
          <svg width="20" height="20" viewBox="0 0 20 20" fill="none">
            <path
              d="M17.5 17.5L13.875 13.875M15.8333 9.16667C15.8333 12.8486 12.8486 15.8333 9.16667 15.8333C5.48477 15.8333 2.5 12.8486 2.5 9.16667C2.5 5.48477 5.48477 2.5 9.16667 2.5C12.8486 2.5 15.8333 5.48477 15.8333 9.16667Z"
              stroke="currentColor"
              strokeWidth="1.66667"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </div>

        <input
          ref={inputRef}
          type="text"
          value={value}
          onChange={handleInputChange}
          onFocus={handleInputFocus}
          onKeyDown={handleKeyDown}
          placeholder={placeholder}
          className="search-input"
          aria-label="Search templates"
          autoComplete="off"
          aria-expanded={showSuggestions}
          aria-haspopup="listbox"
          role="combobox"
        />

        {value && (
          <button
            onClick={handleClearSearch}
            className="clear-button"
            aria-label="Clear search"
            type="button"
          >
            <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
              <path
                d="M12 4L4 12M4 4L12 12"
                stroke="currentColor"
                strokeWidth="1.5"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </button>
        )}

        {loading && (
          <div className="search-loading">
            <div className="spinner"></div>
          </div>
        )}

        <button
          onClick={handleSubmit}
          className="search-submit"
          aria-label="Submit search"
          type="button"
        >
          Search
        </button>
      </div>

      {/* Enhanced Suggestions with Categories */}
      {showSuggestions && suggestions.length > 0 && (
        <div 
          ref={suggestionsRef} 
          className="search-suggestions enhanced-suggestions"
          role="listbox"
        >
          {suggestions.map((suggestion, index) => (
            <button
              key={suggestion}
              onClick={() => handleSuggestionSelect(suggestion)}
              className={`suggestion-item ${
                index === selectedSuggestion ? 'selected' : ''
              }`}
              type="button"
              role="option"
              aria-selected={index === selectedSuggestion}
            >
              <div className="suggestion-icon">
                <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
                  <path
                    d="M14 14L10.5 10.5M12 6.5C12 9.26142 9.76142 11.5 7 11.5C4.23858 11.5 2 9.26142 2 6.5C2 3.73858 4.23858 1.5 7 1.5C9.76142 1.5 12 3.73858 12 6.5Z"
                    stroke="currentColor"
                    strokeWidth="1.33333"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                </svg>
              </div>
              <span className="suggestion-text">{suggestion}</span>
              <div className="suggestion-type">
                {suggestion.includes('#') ? 'Tag' : 
                 suggestion.includes('@') ? 'User' :
                 suggestion.charAt(0).toUpperCase() + suggestion.slice(1).includes(' ') ? 'Template' : 'Search'}
              </div>
            </button>
          ))}
        </div>
      )}

      {/* Recent Searches (when no active search) */}
      {!value && !showSuggestions && (
        <div className="recent-searches">
          <div className="recent-searches-header">
            <span>Recent searches</span>
          </div>
          {/* This would be populated from localStorage or user's search history */}
        </div>
      )}
    </div>
  );
};

// Debounce utility function
function debounce<T extends (...args: any[]) => any>(
  func: T,
  wait: number
): (...args: Parameters<T>) => void {
  let timeout: NodeJS.Timeout;
  return (...args: Parameters<T>) => {
    clearTimeout(timeout);
    timeout = setTimeout(() => func(...args), wait);
  };
}

// Epic 16 Marketplace - Featured Templates Component
import React, { useRef, useState, useEffect } from 'react';
import { TemplateCard } from './TemplateCard';
import './FeaturedTemplates.css';

interface Template {
  id: string;
  title: string;
  description?: string;
  tags: string[];
  price_cents: number;
  avg_rating: number;
  total_reviews: number;
  total_purchases: number;
  categories?: string[];
  owner?: {
    id: string;
    name: string;
    verified: boolean;
  };
  featured_at?: string;
  created_at: string;
  is_ai_generated?: boolean;
  claude_compat: string[];
}

interface FeaturedTemplatesProps {
  templates: Template[];
  onTemplateClick: (templateId: string) => void;
  autoPlay?: boolean;
  autoPlayInterval?: number;
  className?: string;
}

export const FeaturedTemplates: React.FC<FeaturedTemplatesProps> = ({
  templates,
  onTemplateClick,
  autoPlay = true,
  autoPlayInterval = 5000,
  className = ''
}) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(autoPlay);
  const [isDragging, setIsDragging] = useState(false);
  const carouselRef = useRef<HTMLDivElement>(null);
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);

  const totalSlides = templates.length;
  const maxVisibleSlides = Math.min(3, totalSlides); // Show up to 3 templates at once

  useEffect(() => {
    if (isPlaying && totalSlides > 1) {
      timeoutRef.current = setTimeout(() => {
        setCurrentIndex((prev) => (prev + 1) % totalSlides);
      }, autoPlayInterval);
    }

    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, [currentIndex, isPlaying, totalSlides, autoPlayInterval]);

  const handlePrevious = () => {
    setCurrentIndex((prev) => (prev - 1 + totalSlides) % totalSlides);
    setIsPlaying(false);
  };

  const handleNext = () => {
    setCurrentIndex((prev) => (prev + 1) % totalSlides);
    setIsPlaying(false);
  };

  const handleDotClick = (index: number) => {
    setCurrentIndex(index);
    setIsPlaying(false);
  };

  const handleTemplateClick = (templateId: string) => {
    onTemplateClick(templateId);
  };

  const handleMouseEnter = () => {
    setIsPlaying(false);
  };

  const handleMouseLeave = () => {
    if (autoPlay) {
      setIsPlaying(true);
    }
  };

  if (templates.length === 0) {
    return (
      <div className={`featured-templates empty ${className}`}>
        <p>No featured templates available</p>
      </div>
    );
  }

  const getVisibleTemplates = () => {
    if (totalSlides <= maxVisibleSlides) {
      return templates;
    }

    const visible = [];
    for (let i = 0; i < maxVisibleSlides; i++) {
      const index = (currentIndex + i) % totalSlides;
      visible.push(templates[index]);
    }
    return visible;
  };

  const visibleTemplates = getVisibleTemplates();

  return (
    <div 
      className={`featured-templates ${className}`}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
    >
      <div className="carousel-container">
        {/* Navigation Arrows */}
        {totalSlides > maxVisibleSlides && (
          <>
            <button
              onClick={handlePrevious}
              className="carousel-arrow prev"
              aria-label="Previous templates"
            >
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
                <path
                  d="M15 18L9 12L15 6"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
            </button>

            <button
              onClick={handleNext}
              className="carousel-arrow next"
              aria-label="Next templates"
            >
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
                <path
                  d="M9 18L15 12L9 6"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
            </button>
          </>
        )}

        {/* Templates Carousel */}
        <div 
          ref={carouselRef}
          className="carousel-track"
          style={{
            transform: totalSlides <= maxVisibleSlides ? 'translateX(0)' : undefined
          }}
        >
          {visibleTemplates.map((template, index) => (
            <div key={`${template.id}-${currentIndex}-${index}`} className="carousel-slide">
              <TemplateCard
                template={template}
                onClick={() => handleTemplateClick(template.id)}
                variant="featured"
                showStats={true}
              />
            </div>
          ))}
        </div>
      </div>

      {/* Carousel Indicators */}
      {totalSlides > 1 && (
        <div className="carousel-indicators">
          {Array.from({ length: totalSlides }, (_, index) => (
            <button
              key={index}
              onClick={() => handleDotClick(index)}
              className={`indicator ${index === currentIndex ? 'active' : ''}`}
              aria-label={`Go to slide ${index + 1}`}
            />
          ))}
        </div>
      )}

      {/* Playback Controls */}
      {totalSlides > 1 && autoPlay && (
        <div className="playback-controls">
          <button
            onClick={() => setIsPlaying(!isPlaying)}
            className="play-pause-button"
            aria-label={isPlaying ? 'Pause carousel' : 'Play carousel'}
          >
            {isPlaying ? (
              <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
                <path
                  d="M6 3V13M10 3V13"
                  stroke="currentColor"
                  strokeWidth="1.5"
                  strokeLinecap="round"
                />
              </svg>
            ) : (
              <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
                <path
                  d="M3 2L13 8L3 14V2Z"
                  fill="currentColor"
                />
              </svg>
            )}
          </button>
        </div>
      )}
    </div>
  );
};

// Epic 16.2.1 File Upload Manager Component
import React, { useState, useCallback } from 'react';
import { useDropzone } from 'react-dropzone';
import './FileUploadManager.css';

interface UploadedFile {
  id: string;
  file_type: 'graph_json' | 'prompt_yaml' | 'asset_file' | 'documentation';
  filename: string;
  file_size: number;
  mime_type: string;
  validation_status: 'pending' | 'valid' | 'invalid';
  validation_errors: string[];
  uploaded_at: string;
}

interface FileUploadManagerProps {
  submissionId: string;
  files: UploadedFile[];
  onFileUploaded: (file: UploadedFile) => void;
  onFileRemoved: (fileId: string) => void;
}

const FILE_TYPE_LABELS = {
  graph_json: 'Graph JSON',
  prompt_yaml: 'Prompt YAML',
  asset_file: 'Asset File',
  documentation: 'Documentation'
};

const FILE_TYPE_DESCRIPTIONS = {
  graph_json: 'JSON file containing your template\'s graph structure',
  prompt_yaml: 'YAML file with prompt configuration',
  asset_file: 'Images, icons, or other assets used by your template',
  documentation: 'Additional documentation files (PDF, MD, TXT)'
};

const ALLOWED_TYPES = {
  graph_json: ['application/json', 'text/json'],
  prompt_yaml: ['application/x-yaml', 'text/yaml', 'text/x-yaml'],
  asset_file: ['image/jpeg', 'image/png', 'image/gif', 'image/svg+xml', 'image/webp'],
  documentation: ['application/pdf', 'text/markdown', 'text/plain', 'application/msword']
};

const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB

export const FileUploadManager: React.FC<FileUploadManagerProps> = ({
  submissionId,
  files,
  onFileUploaded,
  onFileRemoved
}) => {
  const [uploadingFiles, setUploadingFiles] = useState<Set<string>>(new Set());
  const [errors, setErrors] = useState<string[]>([]);

  const uploadFile = async (file: File, fileType: string) => {
    const uploadKey = `${file.name}-${Date.now()}`;
    setUploadingFiles(prev => new Set(prev).add(uploadKey));
    setErrors([]);

    try {
      // Create file record
      const fileData = {
        file_type: fileType,
        filename: file.name,
        file_size: file.size,
        mime_type: file.type
      };

      const response = await fetch(`/api/marketplace/submissions/${submissionId}/files`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify(fileData)
      });

      if (!response.ok) {
        throw new Error('Failed to create file record');
      }

      const uploadedFile = await response.json();

      // TODO: Upload actual file to S3 using the provided s3_key
      // For now, we'll simulate a successful upload
      await new Promise(resolve => setTimeout(resolve, 1000));

      // Update validation status
      const validationResponse = await fetch(`/api/marketplace/submissions/${submissionId}/files/${uploadedFile.id}/validate`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });

      let finalFile = uploadedFile;
      if (validationResponse.ok) {
        finalFile = await validationResponse.json();
      }

      onFileUploaded(finalFile);
    } catch (error) {
      console.error('Upload failed:', error);
      setErrors(prev => [...prev, `Failed to upload ${file.name}: ${error instanceof Error ? error.message : 'Unknown error'}`]);
    } finally {
      setUploadingFiles(prev => {
        const newSet = new Set(prev);
        newSet.delete(uploadKey);
        return newSet;
      });
    }
  };

  const validateFile = (file: File, fileType: string): string | null => {
    if (file.size > MAX_FILE_SIZE) {
      return 'File size exceeds 10MB limit';
    }

    const allowedTypes = ALLOWED_TYPES[fileType as keyof typeof ALLOWED_TYPES];
    if (!allowedTypes.includes(file.type)) {
      return `File type ${file.type} not allowed for ${FILE_TYPE_LABELS[fileType as keyof typeof FILE_TYPE_LABELS]}`;
    }

    return null;
  };

  const handleRemoveFile = async (fileId: string) => {
    try {
      const response = await fetch(`/api/marketplace/submissions/${submissionId}/files/${fileId}`, {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });

      if (response.ok) {
        onFileRemoved(fileId);
      }
    } catch (error) {
      console.error('Failed to remove file:', error);
    }
  };

  const formatFileSize = (bytes: number): string => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const FileTypeUpload: React.FC<{ fileType: string; label: string; description: string }> = ({ 
    fileType, 
    label, 
    description 
  }) => {
    const onDrop = useCallback((acceptedFiles: File[]) => {
      acceptedFiles.forEach(file => {
        const error = validateFile(file, fileType);
        if (error) {
          setErrors(prev => [...prev, error]);
        } else {
          uploadFile(file, fileType);
        }
      });
    }, [fileType]);

    const { getRootProps, getInputProps, isDragActive } = useDropzone({
      onDrop,
      accept: ALLOWED_TYPES[fileType as keyof typeof ALLOWED_TYPES].reduce((acc, type) => {
        acc[type] = [];
        return acc;
      }, {} as Record<string, string[]>),
      maxFiles: fileType === 'asset_file' ? 10 : 1
    });

    const existingFiles = files.filter(f => f.file_type === fileType);
    const canUpload = fileType === 'asset_file' || existingFiles.length === 0;

    return (
      <div className="file-type-section">
        <h4>{label}</h4>
        <p className="file-type-description">{description}</p>

        {canUpload && (
          <div 
            {...getRootProps()} 
            className={`dropzone ${isDragActive ? 'active' : ''}`}
          >
            <input {...getInputProps()} />
            <div className="dropzone-content">
              <div className="dropzone-icon">📁</div>
              <p>
                {isDragActive 
                  ? 'Drop files here...' 
                  : 'Drag & drop files here, or click to select'
                }
              </p>
              <small>
                Max file size: {formatFileSize(MAX_FILE_SIZE)}
              </small>
            </div>
          </div>
        )}

        {existingFiles.length > 0 && (
          <div className="uploaded-files">
            {existingFiles.map(file => (
              <div key={file.id} className="uploaded-file">
                <div className="file-info">
                  <div className="file-name">{file.filename}</div>
                  <div className="file-meta">
                    <span className="file-size">{formatFileSize(file.file_size)}</span>
                    <span 
                      className={`validation-status ${file.validation_status}`}
                    >
                      {file.validation_status}
                    </span>
                  </div>
                </div>

                {file.validation_errors.length > 0 && (
                  <div className="validation-errors">
                    {file.validation_errors.map((error, index) => (
                      <div key={index} className="validation-error">
                        {error}
                      </div>
                    ))}
                  </div>
                )}

                <button 
                  className="remove-file-btn"
                  onClick={() => handleRemoveFile(file.id)}
                  aria-label="Remove file"
                >
                  ×
                </button>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="file-upload-manager">
      <h3>File Uploads</h3>
      <p className="upload-description">
        Upload additional files to support your template submission.
      </p>

      {errors.length > 0 && (
        <div className="upload-errors">
          {errors.map((error, index) => (
            <div key={index} className="upload-error">
              {error}
            </div>
          ))}
          <button 
            className="clear-errors-btn"
            onClick={() => setErrors([])}
          >
            Clear Errors
          </button>
        </div>
      )}

      {uploadingFiles.size > 0 && (
        <div className="upload-progress">
          <div className="progress-bar">
            <div className="progress-fill" />
          </div>
          <p>Uploading {uploadingFiles.size} file{uploadingFiles.size !== 1 ? 's' : ''}...</p>
        </div>
      )}

      <div className="file-types">
        <FileTypeUpload 
          fileType="graph_json"
          label={FILE_TYPE_LABELS.graph_json}
          description={FILE_TYPE_DESCRIPTIONS.graph_json}
        />

        <FileTypeUpload 
          fileType="prompt_yaml"
          label={FILE_TYPE_LABELS.prompt_yaml}
          description={FILE_TYPE_DESCRIPTIONS.prompt_yaml}
        />

        <FileTypeUpload 
          fileType="asset_file"
          label={FILE_TYPE_LABELS.asset_file}
          description={FILE_TYPE_DESCRIPTIONS.asset_file}
        />

        <FileTypeUpload 
          fileType="documentation"
          label={FILE_TYPE_LABELS.documentation}
          description={FILE_TYPE_DESCRIPTIONS.documentation}
        />
      </div>

      <div className="upload-guidelines">
        <h4>Upload Guidelines</h4>
        <ul>
          <li>Maximum file size: 10MB per file</li>
          <li>Graph JSON files should contain valid JSON structure</li>
          <li>YAML files should be properly formatted</li>
          <li>Asset files should be web-compatible formats</li>
          <li>Documentation files should be readable and well-formatted</li>
        </ul>
      </div>
    </div>
  );
};

export default FileUploadManager;

// Epic 16 Marketplace - Home Page Component
