// Epic 16 Marketplace - Price Display Component
import React from 'react';
import './PriceDisplay.css';

interface PriceDisplayProps {
  priceCents: number;
  originalPriceCents?: number; // For showing discounts
  size?: 'small' | 'medium' | 'large';
  showCurrency?: boolean;
  currency?: string;
  className?: string;
}

export const PriceDisplay: React.FC<PriceDisplayProps> = ({
  priceCents,
  originalPriceCents,
  size = 'medium',
  showCurrency = true,
  currency = 'USD',
  className = ''
}) => {
  const formatPrice = (cents: number): string => {
    if (cents === 0) return 'Free';

    const dollars = cents / 100;
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: currency,
      minimumFractionDigits: dollars % 1 === 0 ? 0 : 2,
      maximumFractionDigits: 2
    }).format(dollars);
  };

  const calculateDiscount = (): number | null => {
    if (!originalPriceCents || originalPriceCents <= priceCents) return null;
    return Math.round(((originalPriceCents - priceCents) / originalPriceCents) * 100);
  };

  const discount = calculateDiscount();
  const isFree = priceCents === 0;
  const isDiscounted = discount !== null;

  return (
    <div className={`price-display ${size} ${isFree ? 'free' : ''} ${isDiscounted ? 'discounted' : ''} ${className}`}>
      {isFree ? (
        <span className="price-free">Free</span>
      ) : (
        <div className="price-container">
          {/* Current Price */}
          <span className="price-current">
            {formatPrice(priceCents)}
          </span>

          {/* Original Price (if discounted) */}
          {isDiscounted && originalPriceCents && (
            <span className="price-original">
              {formatPrice(originalPriceCents)}
            </span>
          )}

          {/* Discount Badge */}
          {discount && (
            <span className="discount-badge">
              -{discount}%
            </span>
          )}
        </div>
      )}

      {/* Currency info for international users */}
      {showCurrency && currency !== 'USD' && !isFree && (
        <span className="currency-info">
          {currency}
        </span>
      )}
    </div>
  );
};

// Epic 16 Marketplace - Purchase Modal Component
import React, { useState, useEffect } from 'react';
import { PriceDisplay } from './PriceDisplay';
import { Badge } from '../common/Badge';
import { LoadingSpinner } from '../common/LoadingSpinner';
import './PurchaseModal.css';

interface PurchaseModalProps {
  template: any;
  onClose: () => void;
  onComplete: (success: boolean) => void;
  className?: string;
}

interface PaymentMethod {
  id: string;
  type: 'card' | 'paypal';
  last4?: string;
  brand?: string;
  is_default: boolean;
}

export const PurchaseModal: React.FC<PurchaseModalProps> = ({
  template,
  onClose,
  onComplete,
  className = ''
}) => {
  const [step, setStep] = useState<'confirm' | 'payment' | 'processing' | 'success' | 'error'>('confirm');
  const [paymentMethods, setPaymentMethods] = useState<PaymentMethod[]>([]);
  const [selectedPaymentMethod, setSelectedPaymentMethod] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [purchaseId, setPurchaseId] = useState<string | null>(null);

  useEffect(() => {
    if (template.price_cents > 0) {
      loadPaymentMethods();
    }
  }, [template.price_cents]);

  const loadPaymentMethods = async () => {
    try {
      const token = localStorage.getItem('auth_token');
      const response = await fetch('/api/payment/methods', {
        headers: {
          'Authorization': `Bearer ${token}`
        }
      });

      if (response.ok) {
        const methods = await response.json();
        setPaymentMethods(methods);

        // Auto-select default payment method
        const defaultMethod = methods.find((method: PaymentMethod) => method.is_default);
        if (defaultMethod) {
          setSelectedPaymentMethod(defaultMethod.id);
        } else if (methods.length > 0) {
          setSelectedPaymentMethod(methods[0].id);
        }
      }
    } catch (error) {
      console.error('Failed to load payment methods:', error);
    }
  };

  const handleConfirm = () => {
    if (template.price_cents === 0) {
      // Free template, proceed directly to purchase
      handlePurchase();
    } else {
      // Paid template, show payment step
      setStep('payment');
    }
  };

  const handlePurchase = async () => {
    setLoading(true);
    setError(null);
    setStep('processing');

    try {
      const token = localStorage.getItem('auth_token');
      const response = await fetch('/api/marketplace/purchases', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          template_id: template.id,
          version_id: template.current_version_id,
          payment_method_id: template.price_cents > 0 ? selectedPaymentMethod : undefined
        })
      });

      if (response.ok) {
        const purchase = await response.json();
        setPurchaseId(purchase.id);

        if (template.price_cents === 0 || purchase.status === 'succeeded') {
          setStep('success');
          setTimeout(() => {
            onComplete(true);
          }, 2000);
        } else {
          // Handle payment processing for paid templates
          await processPayment(purchase);
        }
      } else {
        const errorData = await response.json();
        setError(errorData.error || 'Purchase failed');
        setStep('error');
      }
    } catch (err) {
      setError('Purchase failed. Please try again.');
      setStep('error');
    } finally {
      setLoading(false);
    }
  };

  const processPayment = async (purchase: any) => {
    // This would integrate with Stripe or other payment processor
    // For now, we'll simulate payment processing

    try {
      await new Promise(resolve => setTimeout(resolve, 2000)); // Simulate processing time

      // In a real implementation, this would handle Stripe confirmation
      setStep('success');
      setTimeout(() => {
        onComplete(true);
      }, 2000);
    } catch (error) {
      setError('Payment processing failed');
      setStep('error');
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Escape') {
      onClose();
    }
  };

  const formatCardInfo = (method: PaymentMethod) => {
    if (method.type === 'card') {
      return `•••• •••• •••• ${method.last4} (${method.brand?.toUpperCase()})`;
    }
    return 'PayPal';
  };

  const renderConfirmStep = () => (
    <div className="purchase-step">
      <div className="step-header">
        <h3>Confirm Purchase</h3>
        <p>You're about to {template.price_cents === 0 ? 'get' : 'purchase'} this template:</p>
      </div>

      <div className="template-summary">
        <div className="template-info">
          <h4>{template.title}</h4>
          <div className="template-badges">
            {template.featured_at && <Badge variant="featured">Featured</Badge>}
            {template.price_cents === 0 && <Badge variant="free">Free</Badge>}
            {template.is_ai_generated && <Badge variant="ai">AI Generated</Badge>}
          </div>
        </div>

        <div className="price-section">
          <PriceDisplay priceCents={template.price_cents} size="large" />
        </div>
      </div>

      <div className="purchase-details">
        <div className="detail-row">
          <span>Template:</span>
          <span>{template.title}</span>
        </div>
        <div className="detail-row">
          <span>Version:</span>
          <span>Latest</span>
        </div>
        <div className="detail-row">
          <span>License:</span>
          <span>Personal & Commercial Use</span>
        </div>
        <div className="detail-row total">
          <span>Total:</span>
          <PriceDisplay priceCents={template.price_cents} />
        </div>
      </div>

      <div className="step-actions">
        <button onClick={onClose} className="cancel-button">
          Cancel
        </button>
        <button onClick={handleConfirm} className="confirm-button">
          {template.price_cents === 0 ? 'Get Template' : 'Continue to Payment'}
        </button>
      </div>
    </div>
  );

  const renderPaymentStep = () => (
    <div className="purchase-step">
      <div className="step-header">
        <h3>Payment Information</h3>
        <p>Select your payment method:</p>
      </div>

      {paymentMethods.length > 0 ? (
        <div className="payment-methods">
          {paymentMethods.map((method) => (
            <label key={method.id} className="payment-method">
              <input
                type="radio"
                name="payment-method"
                value={method.id}
                checked={selectedPaymentMethod === method.id}
                onChange={(e) => setSelectedPaymentMethod(e.target.value)}
              />
              <div className="method-info">
                <div className="method-details">
                  <span className="method-type">
                    {method.type === 'card' ? '💳' : '🟦'} {formatCardInfo(method)}
                  </span>
                  {method.is_default && <Badge variant="default">Default</Badge>}
                </div>
              </div>
            </label>
          ))}

          <button className="add-payment-method">
            <svg width="20" height="20" viewBox="0 0 20 20" fill="none">
              <path
                d="M10 4V16M4 10H16"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
              />
            </svg>
            Add New Payment Method
          </button>
        </div>
      ) : (
        <div className="no-payment-methods">
          <p>No payment methods found. Please add a payment method to continue.</p>
          <button className="add-payment-method primary">
            Add Payment Method
          </button>
        </div>
      )}

      <div className="purchase-summary">
        <div className="summary-row">
          <span>Subtotal:</span>
          <PriceDisplay priceCents={template.price_cents} />
        </div>
        <div className="summary-row">
          <span>Processing Fee:</span>
          <span>$0.00</span>
        </div>
        <div className="summary-row total">
          <span>Total:</span>
          <PriceDisplay priceCents={template.price_cents} />
        </div>
      </div>

      <div className="step-actions">
        <button onClick={() => setStep('confirm')} className="back-button">
          Back
        </button>
        <button 
          onClick={handlePurchase} 
          className="purchase-button"
          disabled={!selectedPaymentMethod}
        >
          Complete Purchase
        </button>
      </div>
    </div>
  );

  const renderProcessingStep = () => (
    <div className="purchase-step processing">
      <div className="processing-content">
        <LoadingSpinner size="large" />
        <h3>Processing Purchase</h3>
        <p>Please wait while we process your {template.price_cents === 0 ? 'request' : 'payment'}...</p>
      </div>
    </div>
  );

  const renderSuccessStep = () => (
    <div className="purchase-step success">
      <div className="success-content">
        <div className="success-icon">
          <svg width="64" height="64" viewBox="0 0 64 64" fill="none">
            <circle cx="32" cy="32" r="32" fill="#10B981"/>
            <path
              d="M20 32L28 40L44 24"
              stroke="white"
              strokeWidth="3"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </div>
        <h3>Purchase Successful!</h3>
        <p>
          {template.price_cents === 0 
            ? 'You now have access to this free template.'
            : 'Your payment has been processed and you now own this template.'
          }
        </p>
        <div className="next-steps">
          <h4>What's next?</h4>
          <ul>
            <li>Access your template in the "My Templates" section</li>
            <li>Import it into your workspace</li>
            <li>Start creating amazing content!</li>
          </ul>
        </div>
      </div>
    </div>
  );

  const renderErrorStep = () => (
    <div className="purchase-step error">
      <div className="error-content">
        <div className="error-icon">
          <svg width="64" height="64" viewBox="0 0 64 64" fill="none">
            <circle cx="32" cy="32" r="32" fill="#EF4444"/>
            <path
              d="M24 24L40 40M24 40L40 24"
              stroke="white"
              strokeWidth="3"
              strokeLinecap="round"
            />
          </svg>
        </div>
        <h3>Purchase Failed</h3>
        <p>{error}</p>
        <div className="error-actions">
          <button onClick={() => setStep('confirm')} className="retry-button">
            Try Again
          </button>
          <button onClick={onClose} className="cancel-button">
            Cancel
          </button>
        </div>
      </div>
    </div>
  );

  return (
    <div className={`purchase-modal-overlay ${className}`} onClick={onClose} onKeyDown={handleKeyPress}>
      <div className="purchase-modal" onClick={(e) => e.stopPropagation()}>
        <header className="modal-header">
          <h2>
            {step === 'confirm' && (template.price_cents === 0 ? 'Get Template' : 'Purchase Template')}
            {step === 'payment' && 'Payment'}
            {step === 'processing' && 'Processing'}
            {step === 'success' && 'Success'}
            {step === 'error' && 'Error'}
          </h2>
          {step !== 'processing' && (
            <button onClick={onClose} className="close-button" aria-label="Close">
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
                <path
                  d="M18 6L6 18M6 6L18 18"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
            </button>
          )}
        </header>

        <div className="modal-content">
          {step === 'confirm' && renderConfirmStep()}
          {step === 'payment' && renderPaymentStep()}
          {step === 'processing' && renderProcessingStep()}
          {step === 'success' && renderSuccessStep()}
          {step === 'error' && renderErrorStep()}
        </div>
      </div>
    </div>
  );
};

// Epic 16.1.6 - Enhanced Rating Stars Component
import React, { useState } from 'react';
import { StarIcon } from '@heroicons/react/24/solid';
import { StarIcon as StarOutlineIcon } from '@heroicons/react/24/outline';
import './RatingStars.css';

interface RatingStarsProps {
  rating: number;
  maxRating?: number;
  size?: 'sm' | 'md' | 'lg' | 'xl';
  interactive?: boolean;
  showCount?: boolean;
  reviewCount?: number;
  precision?: 'full' | 'half' | 'quarter';
  onChange?: (rating: number) => void;
  onHover?: (rating: number) => void;
  onLeave?: () => void;
  className?: string;
  disabled?: boolean;
  showTooltip?: boolean;
}

export const RatingStars: React.FC<RatingStarsProps> = ({
  rating,
  maxRating = 5,
  size = 'md',
  interactive = false,
  showCount = false,
  reviewCount = 0,
  precision = 'half',
  onChange,
  onHover,
  onLeave,
  className = '',
  disabled = false,
  showTooltip = false
}) => {
  const [hoverRating, setHoverRating] = useState<number | null>(null);
  const [tooltipVisible, setTooltipVisible] = useState(false);

  const displayRating = hoverRating ?? rating;

  const handleStarClick = (starIndex: number, event: React.MouseEvent) => {
    if (!interactive || disabled || !onChange) return;

    let newRating = starIndex + 1;

    if (precision === 'half') {
      const rect = event.currentTarget.getBoundingClientRect();
      const clickX = event.clientX - rect.left;
      const starWidth = rect.width;

      if (clickX < starWidth / 2) {
        newRating = starIndex + 0.5;
      }
    } else if (precision === 'quarter') {
      const rect = event.currentTarget.getBoundingClientRect();
      const clickX = event.clientX - rect.left;
      const starWidth = rect.width;
      const quarter = starWidth / 4;

      if (clickX < quarter) {
        newRating = starIndex + 0.25;
      } else if (clickX < quarter * 2) {
        newRating = starIndex + 0.5;
      } else if (clickX < quarter * 3) {
        newRating = starIndex + 0.75;
      }
    }

    onChange(newRating);
  };

  const handleStarHover = (starIndex: number, event: React.MouseEvent) => {
    if (!interactive || disabled) return;

    let hoverValue = starIndex + 1;

    if (precision === 'half') {
      const rect = event.currentTarget.getBoundingClientRect();
      const hoverX = event.clientX - rect.left;
      const starWidth = rect.width;

      if (hoverX < starWidth / 2) {
        hoverValue = starIndex + 0.5;
      }
    }

    setHoverRating(hoverValue);
    onHover?.(hoverValue);
  };

  const handleMouseLeave = () => {
    if (!interactive || disabled) return;

    setHoverRating(null);
    setTooltipVisible(false);
    onLeave?.();
  };

  const handleMouseEnter = () => {
    if (showTooltip) {
      setTooltipVisible(true);
    }
  };

  const renderStar = (index: number) => {
    const filled = displayRating > index;
    const partialFill = displayRating > index && displayRating < index + 1;
    const fillPercentage = partialFill ? (displayRating - index) * 100 : 100;

    return (
      <div
        key={index}
        className={`star-container ${size} ${interactive ? 'interactive' : ''} ${disabled ? 'disabled' : ''}`}
        onClick={(e) => handleStarClick(index, e)}
        onMouseMove={(e) => handleStarHover(index, e)}
        role={interactive ? 'button' : undefined}
        tabIndex={interactive ? 0 : undefined}
        aria-label={`${index + 1} star${index > 0 ? 's' : ''}`}
      >
        <StarOutlineIcon className="star-outline" />
        {filled && (
          <div className="star-fill" style={{ width: `${fillPercentage}%` }}>
            <StarIcon className="star-filled" />
          </div>
        )}

        {showTooltip && tooltipVisible && hoverRating === index + 1 && (
          <div className="star-tooltip">
            {getRatingLabel(index + 1)}
          </div>
        )}
      </div>
    );
  };

  const getRatingLabel = (value: number): string => {
    const labels = {
      1: 'Poor',
      2: 'Fair',
      3: 'Good',
      4: 'Very Good',
      5: 'Excellent'
    };
    return labels[value] || `${value} stars`;
  };

  const formatRating = (value: number): string => {
    if (value % 1 === 0) {
      return value.toString();
    }
    return value.toFixed(1);
  };

  return (
    <div 
      className={`rating-stars ${className}`}
      onMouseLeave={handleMouseLeave}
      onMouseEnter={handleMouseEnter}
    >
      <div className="stars-container">
        {Array.from({ length: maxRating }, (_, index) => renderStar(index))}
      </div>

      {showCount && (
        <div className="rating-info">
          <span className="rating-value">{formatRating(rating)}</span>
          {reviewCount > 0 && (
            <span className="review-count">
              ({reviewCount.toLocaleString()} review{reviewCount === 1 ? '' : 's'})
            </span>
          )}
        </div>
      )}
    </div>
  );
};

// Rating Distribution Component
interface RatingDistributionProps {
  distribution: {
    five_star: number;
    four_star: number;
    three_star: number;
    two_star: number;
    one_star: number;
  };
  totalReviews: number;
  onFilterByRating?: (rating: number) => void;
}

export const RatingDistribution: React.FC<RatingDistributionProps> = ({
  distribution,
  totalReviews,
  onFilterByRating
}) => {
  const ratings = [5, 4, 3, 2, 1];
  const ratingKeys = ['five_star', 'four_star', 'three_star', 'two_star', 'one_star'] as const;

  const handleBarClick = (rating: number) => {
    onFilterByRating?.(rating);
  };

  return (
    <div className="rating-distribution">
      <h3>Rating Breakdown</h3>

      {ratings.map((rating, index) => {
        const count = distribution[ratingKeys[index]];
        const percentage = totalReviews > 0 ? (count / totalReviews) * 100 : 0;

        return (
          <div
            key={rating}
            className={`rating-bar ${onFilterByRating ? 'clickable' : ''}`}
            onClick={() => handleBarClick(rating)}
          >
            <div className="rating-label">
              <span className="rating-stars-small">
                {rating}
                <StarIcon className="star-icon-small" />
              </span>
            </div>

            <div className="rating-progress">
              <div
                className="rating-progress-fill"
                style={{ width: `${percentage}%` }}
              />
            </div>

            <div className="rating-count">
              {count.toLocaleString()}
            </div>
          </div>
        );
      })}
    </div>
  );
};

