// Epic 16 Marketplace - Review List Component
import React, { useState } from 'react';
import { StarRating } from './StarRating';
import { LoadingSpinner } from '../common/LoadingSpinner';
import './ReviewList.css';

interface Review {
  id: string;
  buyer_id: string;
  buyer_name: string;
  stars: number;
  comment?: string;
  created_at: string;
  helpful_count: number;
  verified_purchase: boolean;
}

interface ReviewListProps {
  reviews: Review[];
  templateId: string;
  onReviewAdded?: () => void;
  className?: string;
}

interface NewReview {
  stars: number;
  comment: string;
}

export const ReviewList: React.FC<ReviewListProps> = ({
  reviews,
  templateId,
  onReviewAdded,
  className = ''
}) => {
  const [showAddReview, setShowAddReview] = useState(false);
  const [newReview, setNewReview] = useState<NewReview>({ stars: 5, comment: '' });
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [sortBy, setSortBy] = useState<'newest' | 'oldest' | 'highest' | 'lowest'>('newest');

  const handleSubmitReview = async () => {
    if (newReview.stars < 1 || newReview.stars > 5) {
      setError('Please select a rating between 1 and 5 stars');
      return;
    }

    if (newReview.comment.trim().length < 10) {
      setError('Please write a review with at least 10 characters');
      return;
    }

    setSubmitting(true);
    setError(null);

    try {
      const token = localStorage.getItem('auth_token');
      const response = await fetch('/api/marketplace/reviews', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          template_id: templateId,
          stars: newReview.stars,
          comment: newReview.comment.trim()
        })
      });

      if (response.ok) {
        setNewReview({ stars: 5, comment: '' });
        setShowAddReview(false);
        onReviewAdded?.();
      } else {
        const errorData = await response.json();
        setError(errorData.error || 'Failed to submit review');
      }
    } catch (err) {
      setError('Failed to submit review');
    } finally {
      setSubmitting(false);
    }
  };

  const sortedReviews = [...reviews].sort((a, b) => {
    switch (sortBy) {
      case 'newest':
        return new Date(b.created_at).getTime() - new Date(a.created_at).getTime();
      case 'oldest':
        return new Date(a.created_at).getTime() - new Date(b.created_at).getTime();
      case 'highest':
        return b.stars - a.stars;
      case 'lowest':
        return a.stars - b.stars;
      default:
        return 0;
    }
  });

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  };

  const calculateAverageRating = () => {
    if (reviews.length === 0) return 0;
    const total = reviews.reduce((sum, review) => sum + review.stars, 0);
    return total / reviews.length;
  };

  const getRatingDistribution = () => {
    const distribution = { 5: 0, 4: 0, 3: 0, 2: 0, 1: 0 };
    reviews.forEach(review => {
      distribution[review.stars as keyof typeof distribution]++;
    });
    return distribution;
  };

  return (
    <div className={`review-list ${className}`}>
      {/* Review Summary */}
      <div className="review-summary">
        <div className="summary-header">
          <h3>Customer Reviews</h3>
          <button
            onClick={() => setShowAddReview(!showAddReview)}
            className="add-review-button"
          >
            Write a Review
          </button>
        </div>

        {reviews.length > 0 ? (
          <div className="summary-stats">
            <div className="overall-rating">
              <div className="rating-display">
                <span className="rating-number">{calculateAverageRating().toFixed(1)}</span>
                <div className="rating-stars">
                  <StarRating rating={calculateAverageRating()} />
                </div>
              </div>
              <span className="review-count">Based on {reviews.length} reviews</span>
            </div>

            <div className="rating-breakdown">
              {Object.entries(getRatingDistribution())
                .reverse()
                .map(([stars, count]) => {
                  const percentage = reviews.length > 0 ? (count / reviews.length) * 100 : 0;
                  return (
                    <div key={stars} className="rating-bar">
                      <span className="bar-label">{stars}★</span>
                      <div className="bar-container">
                        <div 
                          className="bar-fill" 
                          style={{ width: `${percentage}%` }}
                        />
                      </div>
                      <span className="bar-count">({count})</span>
                    </div>
                  );
                })}
            </div>
          </div>
        ) : (
          <div className="no-reviews">
            <p>No reviews yet. Be the first to review this template!</p>
          </div>
        )}
      </div>

      {/* Add Review Form */}
      {showAddReview && (
        <div className="add-review-form">
          <h4>Write a Review</h4>

          {error && (
            <div className="error-message">
              <svg width="20" height="20" viewBox="0 0 20 20" fill="none">
                <path
                  d="M10 6V10M10 14H10.01M19 10C19 14.9706 14.9706 19 10 19C5.02944 19 1 14.9706 1 10C1 5.02944 5.02944 1 10 1C14.9706 1 19 5.02944 19 10Z"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
              {error}
            </div>
          )}

          <div className="form-group">
            <label>Rating</label>
            <div className="star-selector">
              {[1, 2, 3, 4, 5].map((star) => (
                <button
                  key={star}
                  onClick={() => setNewReview({ ...newReview, stars: star })}
                  className={`star-button ${star <= newReview.stars ? 'active' : ''}`}
                >
                  ★
                </button>
              ))}
            </div>
          </div>

          <div className="form-group">
            <label htmlFor="comment">Your Review</label>
            <textarea
              id="comment"
              value={newReview.comment}
              onChange={(e) => setNewReview({ ...newReview, comment: e.target.value })}
              placeholder="Share your experience with this template..."
              rows={4}
              maxLength={2000}
            />
            <div className="character-count">
              {newReview.comment.length}/2000 characters
            </div>
          </div>

          <div className="form-actions">
            <button
              onClick={() => setShowAddReview(false)}
              className="cancel-button"
              disabled={submitting}
            >
              Cancel
            </button>
            <button
              onClick={handleSubmitReview}
              className="submit-button"
              disabled={submitting || newReview.comment.trim().length < 10}
            >
              {submitting ? (
                <>
                  <LoadingSpinner size="small" />
                  Submitting...
                </>
              ) : (
                'Submit Review'
              )}
            </button>
          </div>
        </div>
      )}

      {/* Reviews List */}
      {reviews.length > 0 && (
        <div className="reviews-section">
          <div className="reviews-header">
            <h4>Reviews ({reviews.length})</h4>
            <div className="sort-controls">
              <label htmlFor="sort-select">Sort by:</label>
              <select
                id="sort-select"
                value={sortBy}
                onChange={(e) => setSortBy(e.target.value as any)}
              >
                <option value="newest">Newest First</option>
                <option value="oldest">Oldest First</option>
                <option value="highest">Highest Rating</option>
                <option value="lowest">Lowest Rating</option>
              </select>
            </div>
          </div>

          <div className="reviews-list">
            {sortedReviews.map((review) => (
              <div key={review.id} className="review-item">
                <div className="review-header">
                  <div className="reviewer-info">
                    <span className="reviewer-name">{review.buyer_name}</span>
                    {review.verified_purchase && (
                      <span className="verified-badge" title="Verified Purchase">
                        <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
                          <path
                            d="M6 8L7 9L10 6M14 8C14 11.3137 11.3137 14 8 14C4.68629 14 2 11.3137 2 8C2 4.68629 4.68629 2 8 2C11.3137 2 14 4.68629 14 8Z"
                            stroke="#10B981"
                            strokeWidth="1.33333"
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            fill="none"
                          />
                        </svg>
                        Verified Purchase
                      </span>
                    )}
                  </div>
                  <div className="review-meta">
                    <StarRating rating={review.stars} />
                    <span className="review-date">{formatDate(review.created_at)}</span>
                  </div>
                </div>

                {review.comment && (
                  <div className="review-content">
                    <p>{review.comment}</p>
                  </div>
                )}

                <div className="review-footer">
                  <button 
                    className="helpful-button"
                    title="Mark as helpful"
                  >
                    <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
                      <path
                        d="M14 6L7 13L2 8L3.5 6.5L7 10L12.5 4.5L14 6Z"
                        stroke="currentColor"
                        strokeWidth="1.5"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                      />
                    </svg>
                    Helpful ({review.helpful_count})
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

// Epic 16.1.6 - Comprehensive Review System Component
import React, { useState, useEffect } from 'react';
import { 
  HandThumbUpIcon, 
  HandThumbDownIcon,
  FlagIcon,
  PencilIcon,
  TrashIcon,
  UserIcon,
  CheckBadgeIcon,
  ChatBubbleLeftRightIcon,
  PhotoIcon,
  ExclamationTriangleIcon
} from '@heroicons/react/24/outline';
import { HandThumbUpIcon as HandThumbUpSolidIcon, HandThumbDownIcon as HandThumbDownSolidIcon } from '@heroicons/react/24/solid';
import { RatingStars, RatingSummary } from './RatingStars';
import { Badge } from './Badge';
import { Modal } from './Modal';
import './ReviewSystem.css';

// Types
interface Review {
  id: string;
  template_id: string;
  buyer_id: string;
  stars: number;
  title?: string;
  comment?: string;
  pros?: string[];
  cons?: string[];
  use_case?: string;
  difficulty_rating?: number;
  would_recommend: boolean;
  verified_purchase: boolean;
  created_at: Date;
  updated_at: Date;
  buyer?: {
    id: string;
    name: string;
    avatar_url?: string;
    verified: boolean;
    total_reviews: number;
  };
  helpfulness_votes: {
    helpful: number;
    not_helpful: number;
    user_vote?: 'helpful' | 'not_helpful';
  };
  creator_response?: {
    id: string;
    creator_id: string;
    response: string;
    created_at: Date;
  };
  attachments?: Array<{
    id: string;
    type: 'image' | 'video' | 'file';
    url: string;
    thumbnail_url?: string;
    filename: string;
  }>;
}

interface ReviewSystemProps {
  templateId: string;
  templateTitle: string;
  templateOwnerId: string;
  currentUserId?: string;
  isOwner?: boolean;
  userHasPurchased?: boolean;
}

export const ReviewSystem: React.FC<ReviewSystemProps> = ({
  templateId,
  templateTitle,
  templateOwnerId,
  currentUserId,
  isOwner = false,
  userHasPurchased = false
}) => {
  const [reviews, setReviews] = useState<Review[]>([]);
  const [metrics, setMetrics] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [sortBy, setSortBy] = useState('newest');
  const [filterBy, setFilterBy] = useState('all');
  const [showReviewModal, setShowReviewModal] = useState(false);
  const [editingReview, setEditingReview] = useState<Review | null>(null);

  useEffect(() => {
    loadReviews();
  }, [templateId, currentPage, sortBy, filterBy]);

  const loadReviews = async () => {
    try {
      setLoading(true);

      const params = new URLSearchParams({
        page: currentPage.toString(),
        sort_by: sortBy,
        filter_by: filterBy
      });

      const response = await fetch(`/api/marketplace/templates/${templateId}/reviews?${params}`);
      const data = await response.json();

      setReviews(data.reviews);
      setMetrics(data.metrics);
      setTotalPages(Math.ceil(data.total / 20));
    } catch (error) {
      console.error('Failed to load reviews:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleReviewSubmit = async (reviewData: any) => {
    try {
      const response = await fetch('/api/marketplace/reviews', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          ...reviewData,
          template_id: templateId
        })
      });

      if (response.ok) {
        setShowReviewModal(false);
        loadReviews();
      }
    } catch (error) {
      console.error('Failed to submit review:', error);
    }
  };

  const handleHelpfulnessVote = async (reviewId: string, vote: 'helpful' | 'not_helpful') => {
    try {
      const response = await fetch('/api/marketplace/reviews/helpfulness', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          review_id: reviewId,
          vote
        })
      });

      if (response.ok) {
        loadReviews();
      }
    } catch (error) {
      console.error('Failed to vote on helpfulness:', error);
    }
  };

  const handleReviewFlag = async (reviewId: string, flagType: string, reason?: string) => {
    try {
      const response = await fetch('/api/marketplace/reviews/flag', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          review_id: reviewId,
          flag_type: flagType,
          reason
        })
      });

      if (response.ok) {
        loadReviews();
      }
    } catch (error) {
      console.error('Failed to flag review:', error);
    }
  };

  const handleCreatorResponse = async (reviewId: string, response: string) => {
    try {
      const responseData = await fetch('/api/marketplace/reviews/response', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          review_id: reviewId,
          response
        })
      });

      if (responseData.ok) {
        loadReviews();
      }
    } catch (error) {
      console.error('Failed to submit creator response:', error);
    }
  };

  if (loading) {
    return <div className="reviews-loading">Loading reviews...</div>;
  }

  return (
    <div className="review-system">
      {/* Review Summary */}
      {metrics && (
        <div className="review-summary-section">
          <RatingSummary
            averageRating={metrics.average_rating}
            totalReviews={metrics.total_reviews}
            distribution={metrics.rating_distribution}
            verifiedPercentage={metrics.verified_percentage}
            onFilterByRating={(rating) => setFilterBy(`${rating}_star`)}
          />
        </div>
      )}

      {/* Review Controls */}
      <div className="review-controls">
        <div className="review-filters">
          <select 
            value={sortBy} 
            onChange={(e) => setSortBy(e.target.value)}
            className="review-sort-select"
          >
            <option value="newest">Newest</option>
            <option value="oldest">Oldest</option>
            <option value="highest_rated">Highest Rated</option>
            <option value="lowest_rated">Lowest Rated</option>
            <option value="most_helpful">Most Helpful</option>
            <option value="verified_first">Verified First</option>
          </select>

          <select 
            value={filterBy} 
            onChange={(e) => setFilterBy(e.target.value)}
            className="review-filter-select"
          >
            <option value="all">All Reviews</option>
            <option value="verified_only">Verified Only</option>
            <option value="with_comments">With Comments</option>
            <option value="five_star">5 Stars</option>
            <option value="four_star">4 Stars</option>
            <option value="three_star">3 Stars</option>
            <option value="two_star">2 Stars</option>
            <option value="one_star">1 Star</option>
          </select>
        </div>

        {userHasPurchased && currentUserId && (
          <button 
            onClick={() => setShowReviewModal(true)}
            className="btn btn-primary"
          >
            Write a Review
          </button>
        )}
      </div>

      {/* Reviews List */}
      <div className="reviews-list">
        {reviews.length === 0 ? (
          <div className="no-reviews">
            <ChatBubbleLeftRightIcon className="no-reviews-icon" />
            <h3>No reviews yet</h3>
            <p>Be the first to review this template!</p>
          </div>
        ) : (
          reviews.map((review) => (
            <ReviewCard
              key={review.id}
              review={review}
              currentUserId={currentUserId}
              isOwner={isOwner}
              onHelpfulnessVote={handleHelpfulnessVote}
              onFlag={handleReviewFlag}
              onCreatorResponse={handleCreatorResponse}
              onEdit={() => setEditingReview(review)}
            />
          ))
        )}
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="reviews-pagination">
          <button
            onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))}
            disabled={currentPage === 1}
            className="btn btn-secondary"
          >
            Previous
          </button>

          <span className="page-info">
            Page {currentPage} of {totalPages}
          </span>

          <button
            onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))}
            disabled={currentPage === totalPages}
            className="btn btn-secondary"
          >
            Next
          </button>
        </div>
      )}

      {/* Review Modal */}
      {showReviewModal && (
        <ReviewModal
          templateId={templateId}
          templateTitle={templateTitle}
          editingReview={editingReview}
          onSubmit={handleReviewSubmit}
          onClose={() => {
            setShowReviewModal(false);
            setEditingReview(null);
          }}
        />
      )}
    </div>
  );
};

// Review Card Component
interface ReviewCardProps {
  review: Review;
  currentUserId?: string;
  isOwner?: boolean;
  onHelpfulnessVote: (reviewId: string, vote: 'helpful' | 'not_helpful') => void;
  onFlag: (reviewId: string, flagType: string, reason?: string) => void;
  onCreatorResponse: (reviewId: string, response: string) => void;
  onEdit: () => void;
}

const ReviewCard: React.FC<ReviewCardProps> = ({
  review,
  currentUserId,
  isOwner,
  onHelpfulnessVote,
  onFlag,
  onCreatorResponse,
  onEdit
}) => {
  const [showResponseForm, setShowResponseForm] = useState(false);
  const [responseText, setResponseText] = useState('');
  const [showFlagModal, setShowFlagModal] = useState(false);

  const isOwnReview = currentUserId === review.buyer_id;
  const canRespond = isOwner && !review.creator_response;

  const formatDate = (date: Date) => {
    return new Intl.DateTimeFormat('en-US', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    }).format(new Date(date));
  };

  const handleResponseSubmit = () => {
    if (responseText.trim()) {
      onCreatorResponse(review.id, responseText);
      setResponseText('');
      setShowResponseForm(false);
    }
  };

  return (
    <div className="review-card">
      <div className="review-header">
        <div className="reviewer-info">
          <div className="reviewer-avatar">
            {review.buyer?.avatar_url ? (
              <img src={review.buyer.avatar_url} alt={review.buyer.name} />
            ) : (
              <UserIcon className="avatar-icon" />
            )}
          </div>

          <div className="reviewer-details">
            <div className="reviewer-name">
              {review.buyer?.name || 'Anonymous'}
              {review.buyer?.verified && <CheckBadgeIcon className="verified-icon" />}
            </div>

            <div className="review-meta">
              <span className="review-date">{formatDate(review.created_at)}</span>
              {review.verified_purchase && (
                <Badge variant="success" size="sm">Verified Purchase</Badge>
              )}
            </div>
          </div>
        </div>

        <div className="review-actions">
          {isOwnReview && (
            <button onClick={onEdit} className="action-btn" aria-label="Edit review">
              <PencilIcon className="w-4 h-4" />
            </button>
          )}

          {currentUserId && !isOwnReview && (
            <button 
              onClick={() => setShowFlagModal(true)} 
              className="action-btn"
              aria-label="Flag review"
            >
              <FlagIcon className="w-4 h-4" />
            </button>
          )}
        </div>
      </div>

      <div className="review-content">
        <div className="review-rating">
          <RatingStars rating={review.stars} size="md" />
          {review.title && <h4 className="review-title">{review.title}</h4>}
        </div>

        {review.comment && (
          <p className="review-comment">{review.comment}</p>
        )}

        {(review.pros && review.pros.length > 0) && (
          <div className="review-pros-cons">
            <div className="pros">
              <h5>Pros:</h5>
              <ul>
                {review.pros.map((pro, index) => (
                  <li key={index}>{pro}</li>
                ))}
              </ul>
            </div>
          </div>
        )}

        {(review.cons && review.cons.length > 0) && (
          <div className="review-pros-cons">
            <div className="cons">
              <h5>Cons:</h5>
              <ul>
                {review.cons.map((con, index) => (
                  <li key={index}>{con}</li>
                ))}
              </ul>
            </div>
          </div>
        )}

        {review.use_case && (
          <div className="review-use-case">
            <strong>Use case:</strong> {review.use_case}
          </div>
        )}

        {review.difficulty_rating && (
          <div className="review-difficulty">
            <strong>Difficulty:</strong>
            <RatingStars rating={review.difficulty_rating} size="sm" maxRating={5} />
          </div>
        )}

        <div className="review-recommendation">
          {review.would_recommend ? (
            <span className="recommend-yes">👍 Recommends this template</span>
          ) : (
            <span className="recommend-no">👎 Doesn't recommend this template</span>
          )}
        </div>
      </div>

      {/* Helpfulness Voting */}
      {currentUserId && !isOwnReview && (
        <div className="review-helpfulness">
          <span className="helpfulness-label">Was this review helpful?</span>

          <div className="helpfulness-buttons">
            <button
              onClick={() => onHelpfulnessVote(review.id, 'helpful')}
              className={`helpfulness-btn ${review.helpfulness_votes.user_vote === 'helpful' ? 'active' : ''}`}
            >
              {review.helpfulness_votes.user_vote === 'helpful' ? 
                <HandThumbUpSolidIcon className="w-4 h-4" /> : 
                <HandThumbUpIcon className="w-4 h-4" />
              }
              Yes ({review.helpfulness_votes.helpful})
            </button>

            <button
              onClick={() => onHelpfulnessVote(review.id, 'not_helpful')}
              className={`helpfulness-btn ${review.helpfulness_votes.user_vote === 'not_helpful' ? 'active' : ''}`}
            >
              {review.helpfulness_votes.user_vote === 'not_helpful' ? 
                <HandThumbDownSolidIcon className="w-4 h-4" /> : 
                <HandThumbDownIcon className="w-4 h-4" />
              }
              No ({review.helpfulness_votes.not_helpful})
            </button>
          </div>
        </div>
      )}

      {/* Creator Response */}
      {review.creator_response && (
        <div className="creator-response">
          <div className="response-header">
            <strong>Creator Response</strong>
            <span className="response-date">{formatDate(review.creator_response.created_at)}</span>
          </div>
          <p className="response-text">{review.creator_response.response}</p>
        </div>
      )}

      {/* Creator Response Form */}
      {canRespond && (
        <div className="creator-response-section">
          {showResponseForm ? (
            <div className="response-form">
              <textarea
                value={responseText}
                onChange={(e) => setResponseText(e.target.value)}
                placeholder="Respond to this review..."
                className="response-textarea"
                rows={3}
              />
              <div className="response-actions">
                <button onClick={handleResponseSubmit} className="btn btn-primary btn-sm">
                  Submit Response
                </button>
                <button onClick={() => setShowResponseForm(false)} className="btn btn-secondary btn-sm">
                  Cancel
                </button>
              </div>
            </div>
          ) : (
            <button onClick={() => setShowResponseForm(true)} className="btn btn-outline btn-sm">
              Respond to Review
            </button>
          )}
        </div>
      )}

      {/* Flag Modal */}
      {showFlagModal && (
        <FlagModal
          reviewId={review.id}
          onFlag={onFlag}
          onClose={() => setShowFlagModal(false)}
        />
      )}
    </div>
  );
};

// Review Modal Component
interface ReviewModalProps {
  templateId: string;
  templateTitle: string;
  editingReview?: Review | null;
  onSubmit: (reviewData: any) => void;
  onClose: () => void;
}

const ReviewModal: React.FC<ReviewModalProps> = ({
  templateId,
  templateTitle,
  editingReview,
  onSubmit,
  onClose
}) => {
  const [formData, setFormData] = useState({
    stars: editingReview?.stars || 5,
    title: editingReview?.title || '',
    comment: editingReview?.comment || '',
    pros: editingReview?.pros || [],
    cons: editingReview?.cons || [],
    use_case: editingReview?.use_case || '',
    difficulty_rating: editingReview?.difficulty_rating || 3,
    would_recommend: editingReview?.would_recommend ?? true
  });

  const [newPro, setNewPro] = useState('');
  const [newCon, setNewCon] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSubmit(formData);
  };

  const addPro = () => {
    if (newPro.trim()) {
      setFormData(prev => ({
        ...prev,
        pros: [...prev.pros, newPro.trim()]
      }));
      setNewPro('');
    }
  };

  const addCon = () => {
    if (newCon.trim()) {
      setFormData(prev => ({
        ...prev,
        cons: [...prev.cons, newCon.trim()]
      }));
      setNewCon('');
    }
  };

  const removePro = (index: number) => {
    setFormData(prev => ({
      ...prev,
      pros: prev.pros.filter((_, i) => i !== index)
    }));
  };

  const removeCon = (index: number) => {
    setFormData(prev => ({
      ...prev,
      cons: prev.cons.filter((_, i) => i !== index)
    }));
  };

  return (
    <Modal onClose={onClose} className="review-modal">
      <div className="modal-header">
        <h2>{editingReview ? 'Edit Review' : 'Write a Review'}</h2>
        <p className="modal-subtitle">for {templateTitle}</p>
      </div>

      <form onSubmit={handleSubmit} className="review-form">
        <div className="form-group">
          <label>Rating *</label>
          <RatingStars
            rating={formData.stars}
            size="lg"
            interactive
            showTooltip
            onChange={(rating) => setFormData(prev => ({ ...prev, stars: rating }))}
          />
        </div>

        <div className="form-group">
          <label htmlFor="title">Review Title (Optional)</label>
          <input
            type="text"
            id="title"
            value={formData.title}
            onChange={(e) => setFormData(prev => ({ ...prev, title: e.target.value }))}
            placeholder="Summarize your experience..."
            maxLength={200}
          />
        </div>

        <div className="form-group">
          <label htmlFor="comment">Your Review</label>
          <textarea
            id="comment"
            value={formData.comment}
            onChange={(e) => setFormData(prev => ({ ...prev, comment: e.target.value }))}
            placeholder="Share your thoughts about this template..."
            rows={6}
            maxLength={2000}
          />
          <div className="character-count">{formData.comment.length}/2000</div>
        </div>

        <div className="form-row">
          <div className="form-group">
            <label>Pros</label>
            <div className="pros-cons-input">
              <input
                type="text"
                value={newPro}
                onChange={(e) => setNewPro(e.target.value)}
                placeholder="What did you like?"
                onKeyPress={(e) => e.key === 'Enter' && (e.preventDefault(), addPro())}
              />
              <button type="button" onClick={addPro} className="btn btn-sm btn-secondary">
                Add
              </button>
            </div>
            <div className="pros-cons-list">
              {formData.pros.map((pro, index) => (
                <div key={index} className="pros-cons-item">
                  <span>+ {pro}</span>
                  <button type="button" onClick={() => removePro(index)} className="remove-btn">
                    ×
                  </button>
                </div>
              ))}
            </div>
          </div>

          <div className="form-group">
            <label>Cons</label>
            <div className="pros-cons-input">
              <input
                type="text"
                value={newCon}
                onChange={(e) => setNewCon(e.target.value)}
                placeholder="What could be improved?"
                onKeyPress={(e) => e.key === 'Enter' && (e.preventDefault(), addCon())}
              />
              <button type="button" onClick={addCon} className="btn btn-sm btn-secondary">
                Add
              </button>
            </div>
            <div className="pros-cons-list">
              {formData.cons.map((con, index) => (
                <div key={index} className="pros-cons-item">
                  <span>- {con}</span>
                  <button type="button" onClick={() => removeCon(index)} className="remove-btn">
                    ×
                  </button>
                </div>
              ))}
            </div>
          </div>
        </div>

        <div className="form-group">
          <label htmlFor="use_case">Use Case (Optional)</label>
          <input
            type="text"
            id="use_case"
            value={formData.use_case}
            onChange={(e) => setFormData(prev => ({ ...prev, use_case: e.target.value }))}
            placeholder="How did you use this template?"
            maxLength={500}
          />
        </div>

        <div className="form-group">
          <label>Difficulty Rating</label>
          <p className="form-help">How challenging was this template to use?</p>
          <RatingStars
            rating={formData.difficulty_rating}
            size="md"
            interactive
            showTooltip
            onChange={(rating) => setFormData(prev => ({ ...prev, difficulty_rating: rating }))}
          />
        </div>

        <div className="form-group">
          <label className="checkbox-label">
            <input
              type="checkbox"
              checked={formData.would_recommend}
              onChange={(e) => setFormData(prev => ({ ...prev, would_recommend: e.target.checked }))}
            />
            I would recommend this template to others
          </label>
        </div>

        <div className="modal-actions">
          <button type="button" onClick={onClose} className="btn btn-secondary">
            Cancel
          </button>
          <button type="submit" className="btn btn-primary">
            {editingReview ? 'Update Review' : 'Submit Review'}
          </button>
        </div>
      </form>
    </Modal>
  );
};

// Flag Modal Component
interface FlagModalProps {
  reviewId: string;
  onFlag: (reviewId: string, flagType: string, reason?: string) => void;
  onClose: () => void;
}

const FlagModal: React.FC<FlagModalProps> = ({ reviewId, onFlag, onClose }) => {
  const [flagType, setFlagType] = useState('inappropriate');
  const [reason, setReason] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onFlag(reviewId, flagType, reason);
    onClose();
  };

  return (
    <Modal onClose={onClose} className="flag-modal">
      <div className="modal-header">
        <ExclamationTriangleIcon className="w-6 h-6 text-red-500" />
        <h2>Flag Review</h2>
        <p className="modal-subtitle">Help us maintain quality by reporting inappropriate content</p>
      </div>

      <form onSubmit={handleSubmit} className="flag-form">
        <div className="form-group">
          <label>Reason for flagging *</label>
          <select
            value={flagType}
            onChange={(e) => setFlagType(e.target.value)}
            className="form-select"
          >
            <option value="inappropriate">Inappropriate content</option>
            <option value="spam">Spam or promotional</option>
            <option value="fake">Fake or misleading</option>
            <option value="off_topic">Off-topic</option>
            <option value="harassment">Harassment or abuse</option>
            <option value="copyright">Copyright violation</option>
            <option value="other">Other</option>
          </select>
        </div>

        <div className="form-group">
          <label htmlFor="reason">Additional details (optional)</label>
          <textarea
            id="reason"
            value={reason}
            onChange={(e) => setReason(e.target.value)}
            placeholder="Please provide more details about why you're flagging this review..."
            rows={3}
            maxLength={500}
          />
        </div>

        <div className="modal-actions">
          <button type="button" onClick={onClose} className="btn btn-secondary">
            Cancel
          </button>
          <button type="submit" className="btn btn-danger">
            Flag Review
          </button>
        </div>
      </form>
    </Modal>
  );
};

// Epic 16.2.2 Rollback Manager Component
import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import './RollbackManager.css';

interface TemplateVersion {
  id: string;
  version_number: string;
  status: 'draft' | 'published' | 'deprecated' | 'archived';
  visibility: 'public' | 'private' | 'beta';
  compatibility_level: 'breaking' | 'major' | 'minor' | 'patch';
  release_notes: string;
  created_at: string;
  published_at?: string;
  download_count: number;
  new_features: string[];
  bug_fixes: string[];
  breaking_changes: string[];
  known_issues: string[];
}

interface RollbackData {
  to_version_id: string;
  rollback_reason: string;
  rollback_type: 'emergency' | 'planned' | 'issue_resolution';
  impact_assessment: string;
  rollback_plan: string;
  verification_steps: string[];
}

interface RollbackResult {
  id: string;
  template_id: string;
  from_version_id: string;
  to_version_id: string;
  rollback_type: string;
  rollback_reason: string;
  initiated_by: string;
  status: 'pending' | 'in_progress' | 'completed' | 'failed' | 'cancelled';
  created_at: string;
  completed_at?: string;
  error_message?: string;
}

const ROLLBACK_TYPES = [
  { 
    value: 'emergency', 
    label: 'Emergency Rollback', 
    description: 'Critical issues requiring immediate rollback',
    icon: '🚨',
    color: '#ef4444'
  },
  { 
    value: 'planned', 
    label: 'Planned Rollback', 
    description: 'Scheduled rollback for testing or maintenance',
    icon: '📅',
    color: '#3b82f6'
  },
  { 
    value: 'issue_resolution', 
    label: 'Issue Resolution', 
    description: 'Rollback to resolve specific bugs or problems',
    icon: '🔧',
    color: '#f59e0b'
  }
];

const DEFAULT_ROLLBACK_DATA: RollbackData = {
  to_version_id: '',
  rollback_reason: '',
  rollback_type: 'planned',
  impact_assessment: '',
  rollback_plan: '',
  verification_steps: ['']
};

export const RollbackManager: React.FC = () => {
  const { templateId } = useParams<{ templateId: string }>();
  const navigate = useNavigate();
  const [versions, setVersions] = useState<TemplateVersion[]>([]);
  const [currentVersion, setCurrentVersion] = useState<TemplateVersion | null>(null);
  const [rollbackData, setRollbackData] = useState<RollbackData>(DEFAULT_ROLLBACK_DATA);
  const [selectedVersion, setSelectedVersion] = useState<TemplateVersion | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [currentStep, setCurrentStep] = useState(1);
  const [rollbackResult, setRollbackResult] = useState<RollbackResult | null>(null);
  const [showConfirmation, setShowConfirmation] = useState(false);

  const totalSteps = 4;

  useEffect(() => {
    if (templateId) {
      fetchVersions();
    }
  }, [templateId]);

  const fetchVersions = async () => {
    try {
      setIsLoading(true);
      const response = await fetch(`/api/marketplace/templates/${templateId}/versions?include_private=true`, {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });

      if (!response.ok) {
        throw new Error('Failed to fetch versions');
      }

      const data = await response.json();
      const publishedVersions = data.filter((v: TemplateVersion) => v.status === 'published');
      setVersions(publishedVersions);

      // Find current version (most recent published)
      if (publishedVersions.length > 0) {
        setCurrentVersion(publishedVersions[0]);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to fetch versions');
    } finally {
      setIsLoading(false);
    }
  };

  const handleInputChange = (field: keyof RollbackData, value: any) => {
    setRollbackData(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const handleVerificationStepChange = (index: number, value: string) => {
    const steps = [...rollbackData.verification_steps];
    steps[index] = value;
    setRollbackData(prev => ({
      ...prev,
      verification_steps: steps
    }));
  };

  const addVerificationStep = () => {
    setRollbackData(prev => ({
      ...prev,
      verification_steps: [...prev.verification_steps, '']
    }));
  };

  const removeVerificationStep = (index: number) => {
    const steps = [...rollbackData.verification_steps];
    steps.splice(index, 1);
    setRollbackData(prev => ({
      ...prev,
      verification_steps: steps
    }));
  };

  const handleVersionSelect = (version: TemplateVersion) => {
    setSelectedVersion(version);
    setRollbackData(prev => ({
      ...prev,
      to_version_id: version.id
    }));
  };

  const validateStep = (step: number): boolean => {
    switch (step) {
      case 1: // Version Selection
        return !!rollbackData.to_version_id;
      case 2: // Rollback Details
        return !!(rollbackData.rollback_reason && rollbackData.rollback_type);
      case 3: // Impact Assessment
        return !!(rollbackData.impact_assessment && rollbackData.rollback_plan);
      case 4: // Verification Steps
        return rollbackData.verification_steps.some(step => step.trim().length > 0);
      default:
        return true;
    }
  };

  const handleNext = () => {
    if (currentStep < totalSteps && validateStep(currentStep)) {
      setCurrentStep(currentStep + 1);
    }
  };

  const handlePrevious = () => {
    if (currentStep > 1) {
      setCurrentStep(currentStep - 1);
    }
  };

  const executeRollback = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const rollbackRequest = {
        ...rollbackData,
        verification_steps: rollbackData.verification_steps.filter(step => step.trim().length > 0)
      };

      const response = await fetch(`/api/marketplace/templates/${templateId}/rollback`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify(rollbackRequest)
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Failed to execute rollback');
      }

      const result = await response.json();
      setRollbackResult(result);
      setShowConfirmation(false);

      // Refresh versions to show updated state
      await fetchVersions();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to execute rollback');
    } finally {
      setIsLoading(false);
    }
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const getRollbackType = (type: string) => {
    return ROLLBACK_TYPES.find(t => t.value === type) || ROLLBACK_TYPES[0];
  };

  const getVersionDiff = () => {
    if (!currentVersion || !selectedVersion) return null;

    const currentParts = currentVersion.version_number.split('.').map(Number);
    const selectedParts = selectedVersion.version_number.split('.').map(Number);

    const [currentMajor, currentMinor, currentPatch] = currentParts;
    const [selectedMajor, selectedMinor, selectedPatch] = selectedParts;

    if (currentMajor > selectedMajor) return 'major-downgrade';
    if (currentMinor > selectedMinor) return 'minor-downgrade';
    if (currentPatch > selectedPatch) return 'patch-downgrade';
    return 'same-version';
  };

  const renderStep1 = () => (
    <div className="step-content">
      <h3>Select Target Version</h3>
      <p className="step-description">
        Choose the version you want to rollback to. Only published versions are available for rollback.
      </p>

      {currentVersion && (
        <div className="current-version-info">
          <h4>Current Version</h4>
          <div className="version-card current">
            <div className="version-header">
              <span className="version-number">v{currentVersion.version_number}</span>
              <span className="version-status">Current</span>
            </div>
            <div className="version-meta">
              <span>Published: {formatDate(currentVersion.published_at || currentVersion.created_at)}</span>
              <span>{currentVersion.download_count} downloads</span>
            </div>
            <p className="release-notes">{currentVersion.release_notes}</p>
          </div>
        </div>
      )}

      <div className="version-selection">
        <h4>Available Versions</h4>
        <div className="version-list">
          {versions.filter(v => v.id !== currentVersion?.id).map(version => (
            <div 
              key={version.id}
              className={`version-card selectable ${selectedVersion?.id === version.id ? 'selected' : ''}`}
              onClick={() => handleVersionSelect(version)}
            >
              <div className="version-header">
                <span className="version-number">v{version.version_number}</span>
                <span className="compatibility-badge" style={{ 
                  backgroundColor: version.compatibility_level === 'breaking' ? '#ef4444' : 
                                 version.compatibility_level === 'major' ? '#f59e0b' :
                                 version.compatibility_level === 'minor' ? '#10b981' : '#3b82f6'
                }}>
                  {version.compatibility_level}
                </span>
              </div>
              <div className="version-meta">
                <span>Published: {formatDate(version.published_at || version.created_at)}</span>
                <span>{version.download_count} downloads</span>
              </div>
              <p className="release-notes">{version.release_notes}</p>

              {version.breaking_changes.length > 0 && (
                <div className="warning-notice">
                  ⚠️ This version has {version.breaking_changes.length} breaking change(s)
                </div>
              )}
            </div>
          ))}
        </div>
      </div>

      {selectedVersion && getVersionDiff() && (
        <div className="rollback-impact">
          <h4>Rollback Impact</h4>
          <div className={`impact-warning ${getVersionDiff()}`}>
            {getVersionDiff() === 'major-downgrade' && (
              <>🔴 Major version downgrade - Significant functionality changes expected</>
            )}
            {getVersionDiff() === 'minor-downgrade' && (
              <>🟡 Minor version downgrade - Some features may be unavailable</>
            )}
            {getVersionDiff() === 'patch-downgrade' && (
              <>🟢 Patch version downgrade - Minimal impact expected</>
            )}
          </div>
        </div>
      )}
    </div>
  );

  const renderStep2 = () => (
    <div className="step-content">
      <h3>Rollback Details</h3>
      <p className="step-description">
        Provide the reason and type of rollback to help track and manage the process.
      </p>

      <div className="form-group">
        <label htmlFor="rollback_type">Rollback Type *</label>
        <div className="rollback-type-options">
          {ROLLBACK_TYPES.map(type => (
            <label key={type.value} className="rollback-type-option">
              <input
                type="radio"
                name="rollback_type"
                value={type.value}
                checked={rollbackData.rollback_type === type.value}
                onChange={(e) => handleInputChange('rollback_type', e.target.value)}
              />
              <div className="option-content">
                <div className="option-indicator" style={{ backgroundColor: type.color }}>
                  {type.icon}
                </div>
                <div className="option-text">
                  <strong>{type.label}</strong>
                  <small>{type.description}</small>
                </div>
              </div>
            </label>
          ))}
        </div>
      </div>

      <div className="form-group">
        <label htmlFor="rollback_reason">Rollback Reason *</label>
        <textarea
          id="rollback_reason"
          value={rollbackData.rollback_reason}
          onChange={(e) => handleInputChange('rollback_reason', e.target.value)}
          placeholder="Explain why this rollback is necessary..."
          rows={4}
          maxLength={1000}
        />
        <small>{rollbackData.rollback_reason.length}/1000 characters</small>
      </div>

      {selectedVersion && (
        <div className="rollback-summary">
          <h4>Rollback Summary</h4>
          <div className="summary-item">
            <strong>From:</strong> v{currentVersion?.version_number} → <strong>To:</strong> v{selectedVersion.version_number}
          </div>
          <div className="summary-item">
            <strong>Type:</strong> {getRollbackType(rollbackData.rollback_type).label}
          </div>
          <div className="summary-item">
            <strong>Impact:</strong> {getVersionDiff()?.replace('-', ' ')}
          </div>
        </div>
      )}
    </div>
  );

  const renderStep3 = () => (
    <div className="step-content">
      <h3>Impact Assessment & Plan</h3>
      <p className="step-description">
        Assess the impact of this rollback and provide a detailed plan for execution.
      </p>

      <div className="form-group">
        <label htmlFor="impact_assessment">Impact Assessment *</label>
        <textarea
          id="impact_assessment"
          value={rollbackData.impact_assessment}
          onChange={(e) => handleInputChange('impact_assessment', e.target.value)}
          placeholder="Describe the expected impact on users, systems, and workflows..."
          rows={6}
          maxLength={2000}
        />
        <small>{rollbackData.impact_assessment.length}/2000 characters</small>
      </div>

      <div className="form-group">
        <label htmlFor="rollback_plan">Rollback Plan *</label>
        <textarea
          id="rollback_plan"
          value={rollbackData.rollback_plan}
          onChange={(e) => handleInputChange('rollback_plan', e.target.value)}
          placeholder="Outline the step-by-step process for executing this rollback..."
          rows={6}
          maxLength={2000}
        />
        <small>{rollbackData.rollback_plan.length}/2000 characters</small>
      </div>

      {selectedVersion && (
        <div className="version-details">
          <h4>Target Version Details</h4>
          <div className="details-grid">
            <div className="detail-item">
              <strong>Version:</strong> v{selectedVersion.version_number}
            </div>
            <div className="detail-item">
              <strong>Published:</strong> {formatDate(selectedVersion.published_at || selectedVersion.created_at)}
            </div>
            <div className="detail-item">
              <strong>Downloads:</strong> {selectedVersion.download_count}
            </div>
            <div className="detail-item">
              <strong>Type:</strong> {selectedVersion.compatibility_level}
            </div>
          </div>

          {selectedVersion.known_issues.length > 0 && (
            <div className="known-issues-warning">
              <h5>⚠️ Known Issues in Target Version</h5>
              <ul>
                {selectedVersion.known_issues.map((issue, index) => (
                  <li key={index}>{issue}</li>
                ))}
              </ul>
            </div>
          )}
        </div>
      )}
    </div>
  );

  const renderStep4 = () => (
    <div className="step-content">
      <h3>Verification Steps</h3>
      <p className="step-description">
        Define the steps that will be used to verify the rollback was successful.
      </p>

      <div className="form-group">
        <label>Verification Steps *</label>
        {rollbackData.verification_steps.map((step, index) => (
          <div key={index} className="array-input">
            <input
              type="text"
              value={step}
              onChange={(e) => handleVerificationStepChange(index, e.target.value)}
              placeholder={`Verification step ${index + 1}...`}
            />
            {rollbackData.verification_steps.length > 1 && (
              <button type="button" onClick={() => removeVerificationStep(index)}>
                Remove
              </button>
            )}
          </div>
        ))}
        <button type="button" onClick={addVerificationStep}>
          Add Verification Step
        </button>
      </div>

      <div className="rollback-final-summary">
        <h4>Final Rollback Summary</h4>
        <div className="summary-grid">
          <div className="summary-item">
            <strong>Target Version:</strong> v{selectedVersion?.version_number}
          </div>
          <div className="summary-item">
            <strong>Rollback Type:</strong> {getRollbackType(rollbackData.rollback_type).label}
          </div>
          <div className="summary-item">
            <strong>Verification Steps:</strong> {rollbackData.verification_steps.filter(s => s.trim()).length}
          </div>
        </div>

        <div className="risk-assessment">
          <h5>Risk Assessment</h5>
          <div className={`risk-level ${rollbackData.rollback_type}`}>
            {getRollbackType(rollbackData.rollback_type).icon} {getRollbackType(rollbackData.rollback_type).label}
          </div>
        </div>
      </div>

      {error && (
        <div className="error-message">
          {error}
        </div>
      )}
    </div>
  );

  if (isLoading && !versions.length) {
    return (
      <div className="rollback-manager loading">
        <div className="loading-spinner">Loading rollback manager...</div>
      </div>
    );
  }

  if (rollbackResult) {
    return (
      <div className="rollback-manager">
        <div className="rollback-result">
          <div className="result-header">
            <h2>Rollback {rollbackResult.status === 'completed' ? 'Completed' : 'Initiated'}</h2>
          </div>

          <div className="result-content">
            <div className="result-summary">
              <div className="summary-item">
                <strong>Rollback ID:</strong> {rollbackResult.id}
              </div>
              <div className="summary-item">
                <strong>Status:</strong> 
                <span className={`status-badge ${rollbackResult.status}`}>
                  {rollbackResult.status}
                </span>
              </div>
              <div className="summary-item">
                <strong>Target Version:</strong> v{selectedVersion?.version_number}
              </div>
              <div className="summary-item">
                <strong>Type:</strong> {getRollbackType(rollbackData.rollback_type).label}
              </div>
              {rollbackResult.completed_at && (
                <div className="summary-item">
                  <strong>Completed:</strong> {formatDate(rollbackResult.completed_at)}
                </div>
              )}
            </div>

            {rollbackResult.error_message && (
              <div className="error-message">
                <strong>Error:</strong> {rollbackResult.error_message}
              </div>
            )}

            <div className="result-actions">
              <button 
                className="btn-primary"
                onClick={() => navigate(`/marketplace/templates/${templateId}/versions`)}
              >
                Return to Version History
              </button>
              <button 
                className="btn-secondary"
                onClick={() => {
                  setRollbackResult(null);
                  setRollbackData(DEFAULT_ROLLBACK_DATA);
                  setSelectedVersion(null);
                  setCurrentStep(1);
                }}
              >
                Start New Rollback
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="rollback-manager">
      <div className="rollback-header">
        <h2>Version Rollback</h2>
        <div className="step-indicator">
          Step {currentStep} of {totalSteps}
        </div>
      </div>

      <div className="progress-bar">
        <div 
          className="progress-fill"
          style={{ width: `${(currentStep / totalSteps) * 100}%` }}
        />
      </div>

      <div className="form-container">
        {currentStep === 1 && renderStep1()}
        {currentStep === 2 && renderStep2()}
        {currentStep === 3 && renderStep3()}
        {currentStep === 4 && renderStep4()}
      </div>

      <div className="form-actions">
        {currentStep > 1 && (
          <button type="button" onClick={handlePrevious} className="btn-secondary">
            Previous
          </button>
        )}

        {currentStep < totalSteps ? (
          <button 
            type="button" 
            onClick={handleNext}
            className="btn-primary"
            disabled={!validateStep(currentStep)}
          >
            Next
          </button>
        ) : (
          <button 
            type="button" 
            onClick={() => setShowConfirmation(true)}
            className="btn-primary"
            disabled={!validateStep(currentStep) || isLoading}
          >
            Execute Rollback
          </button>
        )}

        <button 
          type="button" 
          onClick={() => navigate(`/marketplace/templates/${templateId}/versions`)}
          className="btn-secondary"
        >
          Cancel
        </button>
      </div>

      {showConfirmation && (
        <div className="confirmation-modal">
          <div className="confirmation-content">
            <div className="confirmation-header">
              <h3>Confirm Rollback</h3>
            </div>

            <div className="confirmation-warning">
              ⚠️ This action will rollback the template to version v{selectedVersion?.version_number}. 
              This action cannot be undone automatically.
            </div>

            <div className="confirmation-details">
              <p><strong>Rollback Type:</strong> {getRollbackType(rollbackData.rollback_type).label}</p>
              <p><strong>Reason:</strong> {rollbackData.rollback_reason}</p>
              <p><strong>Verification Steps:</strong> {rollbackData.verification_steps.filter(s => s.trim()).length} defined</p>
            </div>

            <div className="confirmation-actions">
              <button 
                className="btn-secondary"
                onClick={() => setShowConfirmation(false)}
                disabled={isLoading}
              >
                Cancel
              </button>
              <button 
                className="btn-primary danger"
                onClick={executeRollback}
                disabled={isLoading}
              >
                {isLoading ? 'Executing...' : 'Confirm Rollback'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default RollbackManager;

// Epic 16 Marketplace - Search Bar Component
import React, { useState, useRef, useEffect } from 'react';
import './SearchBar.css';

interface SearchBarProps {
  value: string;
  onChange: (value: string) => void;
  onSubmit?: () => void;
  placeholder?: string;
  suggestions?: string[];
  loading?: boolean;
  className?: string;
}

export const SearchBar: React.FC<SearchBarProps> = ({
  value,
  onChange,
  onSubmit,
  placeholder = 'Search...',
  suggestions = [],
  loading = false,
  className = ''
}) => {
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [selectedSuggestion, setSelectedSuggestion] = useState(-1);
  const inputRef = useRef<HTMLInputElement>(null);
  const suggestionsRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        suggestionsRef.current &&
        !suggestionsRef.current.contains(event.target as Node) &&
        !inputRef.current?.contains(event.target as Node)
      ) {
        setShowSuggestions(false);
        setSelectedSuggestion(-1);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newValue = e.target.value;
    onChange(newValue);
    setShowSuggestions(newValue.length > 0 && suggestions.length > 0);
    setSelectedSuggestion(-1);
  };

  const handleInputFocus = () => {
    if (suggestions.length > 0 && value.length > 0) {
      setShowSuggestions(true);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (!showSuggestions) {
      if (e.key === 'Enter') {
        handleSubmit();
      }
      return;
    }

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setSelectedSuggestion(prev => 
          prev < suggestions.length - 1 ? prev + 1 : 0
        );
        break;
      case 'ArrowUp':
        e.preventDefault();
        setSelectedSuggestion(prev => 
          prev > 0 ? prev - 1 : suggestions.length - 1
        );
        break;
      case 'Enter':
        e.preventDefault();
        if (selectedSuggestion >= 0 && selectedSuggestion < suggestions.length) {
          handleSuggestionSelect(suggestions[selectedSuggestion]);
        } else {
          handleSubmit();
        }
        break;
      case 'Escape':
        setShowSuggestions(false);
        setSelectedSuggestion(-1);
        inputRef.current?.blur();
        break;
    }
  };

  const handleSuggestionSelect = (suggestion: string) => {
    onChange(suggestion);
    setShowSuggestions(false);
    setSelectedSuggestion(-1);
    handleSubmit();
  };

  const handleSubmit = () => {
    onSubmit?.();
    setShowSuggestions(false);
    setSelectedSuggestion(-1);
  };

  const handleClearSearch = () => {
    onChange('');
    setShowSuggestions(false);
    setSelectedSuggestion(-1);
    inputRef.current?.focus();
  };

  return (
    <div className={`search-bar ${className}`}>
      <div className="search-input-container">
        <div className="search-icon">
          <svg width="20" height="20" viewBox="0 0 20 20" fill="none">
            <path
              d="M17.5 17.5L13.875 13.875M15.8333 9.16667C15.8333 12.8486 12.8486 15.8333 9.16667 15.8333C5.48477 15.8333 2.5 12.8486 2.5 9.16667C2.5 5.48477 5.48477 2.5 9.16667 2.5C12.8486 2.5 15.8333 5.48477 15.8333 9.16667Z"
              stroke="currentColor"
              strokeWidth="1.66667"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </div>

        <input
          ref={inputRef}
          type="text"
          value={value}
          onChange={handleInputChange}
          onFocus={handleInputFocus}
          onKeyDown={handleKeyDown}
          placeholder={placeholder}
          className="search-input"
          aria-label="Search templates"
          autoComplete="off"
        />

        {value && (
          <button
            onClick={handleClearSearch}
            className="clear-button"
            aria-label="Clear search"
            type="button"
          >
            <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
              <path
                d="M12 4L4 12M4 4L12 12"
                stroke="currentColor"
                strokeWidth="1.5"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </button>
        )}

        {loading && (
          <div className="search-loading">
            <div className="spinner"></div>
          </div>
        )}

        <button
          onClick={handleSubmit}
          className="search-submit"
          aria-label="Submit search"
          type="button"
        >
          Search
        </button>
      </div>

      {/* Search Suggestions */}
      {showSuggestions && suggestions.length > 0 && (
        <div ref={suggestionsRef} className="search-suggestions">
          {suggestions.map((suggestion, index) => (
            <button
              key={suggestion}
              onClick={() => handleSuggestionSelect(suggestion)}
              className={`suggestion-item ${
                index === selectedSuggestion ? 'selected' : ''
              }`}
              type="button"
            >
              <div className="suggestion-icon">
                <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
                  <path
                    d="M14 14L10.5 10.5M12 6.5C12 9.26142 9.76142 11.5 7 11.5C4.23858 11.5 2 9.26142 2 6.5C2 3.73858 4.23858 1.5 7 1.5C9.76142 1.5 12 3.73858 12 6.5Z"
                    stroke="currentColor"
                    strokeWidth="1.33333"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                </svg>
              </div>
              <span className="suggestion-text">{suggestion}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
};

// Epic 16.1.5 - Shopping Cart Component
import React, { useState, useEffect } from 'react';
import { 
  ShoppingCartIcon, 
  TrashIcon, 
  PlusIcon, 
  MinusIcon,
  XMarkIcon
} from '@heroicons/react/24/outline';
import { CartItem, LicenseType } from '../../types/marketplace';
import { useMarketplace } from '../../hooks/useMarketplace';
import { PriceDisplay } from './PriceDisplay';
import { Badge } from './Badge';
import './ShoppingCart.css';

interface ShoppingCartProps {
  isOpen: boolean;
  onClose: () => void;
  onCheckout: () => void;
}

export const ShoppingCart: React.FC<ShoppingCartProps> = ({
  isOpen,
  onClose,
  onCheckout
}) => {
  const { cart, updateCartItem, removeFromCart, clearCart, loading } = useMarketplace();
  const [isClearing, setIsClearing] = useState(false);

  const handleQuantityChange = async (itemId: string, newQuantity: number) => {
    if (newQuantity === 0) {
      await removeFromCart(itemId);
    } else {
      await updateCartItem(itemId, { quantity: newQuantity });
    }
  };

  const handleLicenseChange = async (itemId: string, licenseType: LicenseType) => {
    await updateCartItem(itemId, { license_type: licenseType });
  };

  const handleClearCart = async () => {
    setIsClearing(true);
    try {
      await clearCart();
    } finally {
      setIsClearing(false);
    }
  };

  const formatLicenseType = (licenseType: LicenseType): string => {
    return licenseType
      .split('_')
      .map(word => word.charAt(0).toUpperCase() + word.slice(1))
      .join(' ');
  };

  const getLicenseDescription = (licenseType: LicenseType): string => {
    const descriptions = {
      [LicenseType.PERSONAL]: 'For personal use only',
      [LicenseType.COMMERCIAL]: 'For commercial projects',
      [LicenseType.ENTERPRISE]: 'For large organizations',
      [LicenseType.EDUCATIONAL]: 'For educational institutions',
      [LicenseType.UNLIMITED]: 'No usage restrictions'
    };
    return descriptions[licenseType] || '';
  };

  const subtotal = cart?.items.reduce((sum, item) => 
    sum + (item.unit_price_cents * item.quantity), 0
  ) || 0;

  if (!isOpen) return null;

  return (
    <div className="shopping-cart-overlay">
      <div className="shopping-cart-panel">
        {/* Header */}
        <div className="cart-header">
          <div className="cart-title">
            <ShoppingCartIcon className="cart-icon" />
            <h2>Shopping Cart</h2>
            {cart?.items && cart.items.length > 0 && (
              <Badge variant="primary" size="sm">
                {cart.items.reduce((sum, item) => sum + item.quantity, 0)}
              </Badge>
            )}
          </div>
          <button 
            onClick={onClose}
            className="cart-close-btn"
            aria-label="Close cart"
          >
            <XMarkIcon className="w-6 h-6" />
          </button>
        </div>

        {/* Content */}
        <div className="cart-content">
          {!cart?.items || cart.items.length === 0 ? (
            <div className="cart-empty">
              <ShoppingCartIcon className="empty-cart-icon" />
              <h3>Your cart is empty</h3>
              <p>Browse our marketplace to find templates for your projects.</p>
            </div>
          ) : (
            <>
              {/* Cart Items */}
              <div className="cart-items">
                {cart.items.map((item) => (
                  <CartItemComponent
                    key={item.id}
                    item={item}
                    onQuantityChange={handleQuantityChange}
                    onLicenseChange={handleLicenseChange}
                    onRemove={() => removeFromCart(item.id)}
                    disabled={loading}
                  />
                ))}
              </div>

              {/* Cart Summary */}
              <div className="cart-summary">
                <div className="summary-row">
                  <span>Subtotal:</span>
                  <PriceDisplay cents={subtotal} />
                </div>

                {cart.tax_cents > 0 && (
                  <div className="summary-row">
                    <span>Tax:</span>
                    <PriceDisplay cents={cart.tax_cents} />
                  </div>
                )}

                <div className="summary-row summary-total">
                  <span>Total:</span>
                  <PriceDisplay cents={cart.total_cents || subtotal} />
                </div>

                {/* Actions */}
                <div className="cart-actions">
                  <button
                    onClick={handleClearCart}
                    className="btn btn-secondary btn-sm"
                    disabled={loading || isClearing}
                  >
                    {isClearing ? 'Clearing...' : 'Clear Cart'}
                  </button>

                  <button
                    onClick={onCheckout}
                    className="btn btn-primary"
                    disabled={loading}
                  >
                    Proceed to Checkout
                  </button>
                </div>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

interface CartItemComponentProps {
  item: CartItem;
  onQuantityChange: (itemId: string, quantity: number) => void;
  onLicenseChange: (itemId: string, licenseType: LicenseType) => void;
  onRemove: () => void;
  disabled: boolean;
}

const CartItemComponent: React.FC<CartItemComponentProps> = ({
  item,
  onQuantityChange,
  onLicenseChange,
  onRemove,
  disabled
}) => {
  const [template, setTemplate] = useState<any>(null);

  useEffect(() => {
    // Fetch template details - in a real app, this would come from a context or service
    // For now, we'll use placeholder data
    setTemplate({
      id: item.template_id,
      title: `Template ${item.template_id.slice(0, 8)}`,
      description: 'A powerful prompt template for various use cases',
      owner: { name: 'Creator Name' }
    });
  }, [item.template_id]);

  const formatLicenseType = (licenseType: LicenseType): string => {
    return licenseType
      .split('_')
      .map(word => word.charAt(0).toUpperCase() + word.slice(1))
      .join(' ');
  };

  const getLicenseOptions = (): { value: LicenseType; label: string; description: string }[] => [
    { 
      value: LicenseType.PERSONAL, 
      label: 'Personal', 
      description: 'For personal use only' 
    },
    { 
      value: LicenseType.COMMERCIAL, 
      label: 'Commercial', 
      description: 'For commercial projects' 
    },
    { 
      value: LicenseType.ENTERPRISE, 
      label: 'Enterprise', 
      description: 'For large organizations' 
    },
    { 
      value: LicenseType.EDUCATIONAL, 
      label: 'Educational', 
      description: 'For educational institutions' 
    },
    { 
      value: LicenseType.UNLIMITED, 
      label: 'Unlimited', 
      description: 'No usage restrictions' 
    }
  ];

  return (
    <div className="cart-item">
      <div className="item-info">
        <h4 className="item-title">
          {template?.title || 'Loading...'}
        </h4>
        <p className="item-creator">
          by {template?.owner?.name || 'Unknown'}
        </p>

        {/* License Selection */}
        <div className="license-selection">
          <label htmlFor={`license-${item.id}`} className="license-label">
            License Type:
          </label>
          <select
            id={`license-${item.id}`}
            value={item.license_type}
            onChange={(e) => onLicenseChange(item.id, e.target.value as LicenseType)}
            className="license-select"
            disabled={disabled}
          >
            {getLicenseOptions().map((option) => (
              <option key={option.value} value={option.value}>
                {option.label} - {option.description}
              </option>
            ))}
          </select>
        </div>
      </div>

      <div className="item-controls">
        <div className="quantity-controls">
          <button
            onClick={() => onQuantityChange(item.id, item.quantity - 1)}
            className="quantity-btn"
            disabled={disabled || item.quantity <= 1}
            aria-label="Decrease quantity"
          >
            <MinusIcon className="w-4 h-4" />
          </button>

          <span className="quantity-display">
            {item.quantity}
          </span>

          <button
            onClick={() => onQuantityChange(item.id, item.quantity + 1)}
            className="quantity-btn"
            disabled={disabled}
            aria-label="Increase quantity"
          >
            <PlusIcon className="w-4 h-4" />
          </button>
        </div>

        <div className="item-price">
          <PriceDisplay cents={item.unit_price_cents * item.quantity} />
          {item.quantity > 1 && (
            <div className="unit-price">
              <PriceDisplay cents={item.unit_price_cents} /> each
            </div>
          )}
        </div>

        <button
          onClick={onRemove}
          className="remove-btn"
          disabled={disabled}
          aria-label="Remove item"
        >
          <TrashIcon className="w-5 h-5" />
        </button>
      </div>
    </div>
  );
};

// Epic 16 Marketplace - Star Rating Component
import React from 'react';
import './StarRating.css';

interface StarRatingProps {
  rating: number;
  maxRating?: number;
  size?: 'small' | 'medium' | 'large';
  interactive?: boolean;
  onRatingChange?: (rating: number) => void;
  className?: string;
}

export const StarRating: React.FC<StarRatingProps> = ({
  rating,
  maxRating = 5,
  size = 'medium',
  interactive = false,
  onRatingChange,
  className = ''
}) => {
  const [hoveredRating, setHoveredRating] = React.useState<number | null>(null);

  const handleStarClick = (starRating: number) => {
    if (interactive && onRatingChange) {
      onRatingChange(starRating);
    }
  };

  const handleStarHover = (starRating: number) => {
    if (interactive) {
      setHoveredRating(starRating);
    }
  };

  const handleMouseLeave = () => {
    if (interactive) {
      setHoveredRating(null);
    }
  };

  const getStarFill = (starIndex: number): 'empty' | 'half' | 'full' => {
    const effectiveRating = hoveredRating !== null ? hoveredRating : rating;
    const starValue = starIndex + 1;

    if (effectiveRating >= starValue) {
      return 'full';
    } else if (effectiveRating >= starValue - 0.5) {
      return 'half';
    } else {
      return 'empty';
    }
  };

  const renderStar = (index: number) => {
    const fill = getStarFill(index);
    const starValue = index + 1;

    return (
      <button
        key={index}
        type="button"
        className={`star ${fill} ${interactive ? 'interactive' : ''}`}
        onClick={() => handleStarClick(starValue)}
        onMouseEnter={() => handleStarHover(starValue)}
        disabled={!interactive}
        aria-label={`${starValue} star${starValue !== 1 ? 's' : ''}`}
      >
        <svg
          width="16"
          height="16"
          viewBox="0 0 16 16"
          fill="none"
          className="star-svg"
        >
          {fill === 'half' && (
            <defs>
              <linearGradient id={`half-fill-${index}`} x1="0%" y1="0%" x2="100%" y2="0%">
                <stop offset="50%" stopColor="var(--star-fill-color)" />
                <stop offset="50%" stopColor="var(--star-empty-color)" />
              </linearGradient>
            </defs>
          )}
          <path
            d="M8 1L10.09 5.26L15 6.09L11.5 9.47L12.18 14.37L8 12.18L3.82 14.37L4.5 9.47L1 6.09L5.91 5.26L8 1Z"
            fill={
              fill === 'full' 
                ? 'var(--star-fill-color)' 
                : fill === 'half' 
                  ? `url(#half-fill-${index})` 
                  : 'var(--star-empty-color)'
            }
            stroke="var(--star-stroke-color)"
            strokeWidth="0.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
      </button>
    );
  };

  return (
    <div 
      className={`star-rating ${size} ${interactive ? 'interactive' : ''} ${className}`}
      onMouseLeave={handleMouseLeave}
      role={interactive ? 'radiogroup' : 'img'}
      aria-label={`Rating: ${rating} out of ${maxRating} stars`}
    >
      <div className="stars">
        {Array.from({ length: maxRating }, (_, index) => renderStar(index))}
      </div>

      {!interactive && (
        <span className="rating-value" aria-hidden="true">
          {rating.toFixed(1)}
        </span>
      )}
    </div>
  );
};

// Epic 16.2.1 Submission Manager Component
import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import './SubmissionManager.css';

interface Submission {
  id: string;
  template_id: string;
  status: 'draft' | 'submitted' | 'under_review' | 'changes_requested' | 'approved' | 'rejected';
  version_number: number;
  submission_data: {
    title: string;
    description: string;
    price_cents: number;
  };
  validation_results: ValidationResult[];
  review_comments?: string;
  review_score?: number;
  submitted_at?: string;
  reviewed_at?: string;
  created_at: string;
  updated_at: string;
}

interface ValidationResult {
  severity: 'error' | 'warning' | 'info';
  message: string;
}

interface SubmissionStats {
  total_submissions: number;
  approved_submissions: number;
  rejected_submissions: number;
  pending_submissions: number;
  avg_review_score: number;
  avg_review_time_hours: number;
}

const STATUS_COLORS = {
  draft: '#6b7280',
  submitted: '#3b82f6',
  under_review: '#f59e0b',
  changes_requested: '#ef4444',
  approved: '#10b981',
  rejected: '#ef4444'
};

const STATUS_LABELS = {
  draft: 'Draft',
  submitted: 'Submitted',
  under_review: 'Under Review',
  changes_requested: 'Changes Requested',
  approved: 'Approved',
  rejected: 'Rejected'
};

export const SubmissionManager: React.FC = () => {
  const [submissions, setSubmissions] = useState<Submission[]>([]);
  const [stats, setStats] = useState<SubmissionStats | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedTab, setSelectedTab] = useState<'all' | 'drafts' | 'submitted' | 'approved' | 'rejected'>('all');

  useEffect(() => {
    fetchSubmissions();
    fetchStats();
  }, []);

  const fetchSubmissions = async () => {
    try {
      const response = await fetch('/api/marketplace/submissions', {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });

      if (!response.ok) {
        throw new Error('Failed to fetch submissions');
      }

      const data = await response.json();
      setSubmissions(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to fetch submissions');
    } finally {
      setIsLoading(false);
    }
  };

  const fetchStats = async () => {
    try {
      const response = await fetch('/api/marketplace/submissions/stats', {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });

      if (response.ok) {
        const data = await response.json();
        setStats(data);
      }
    } catch (err) {
      console.error('Failed to fetch stats:', err);
    }
  };

  const handleDeleteSubmission = async (id: string) => {
    if (!confirm('Are you sure you want to delete this submission?')) {
      return;
    }

    try {
      const response = await fetch(`/api/marketplace/submissions/${id}`, {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });

      if (response.ok) {
        setSubmissions(submissions.filter(s => s.id !== id));
      }
    } catch (err) {
      console.error('Failed to delete submission:', err);
    }
  };

  const handleResubmit = async (id: string) => {
    try {
      const response = await fetch(`/api/marketplace/submissions/${id}/submit`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });

      if (response.ok) {
        fetchSubmissions();
      }
    } catch (err) {
      console.error('Failed to resubmit:', err);
    }
  };

  const getFilteredSubmissions = () => {
    switch (selectedTab) {
      case 'drafts':
        return submissions.filter(s => s.status === 'draft');
      case 'submitted':
        return submissions.filter(s => s.status === 'submitted' || s.status === 'under_review');
      case 'approved':
        return submissions.filter(s => s.status === 'approved');
      case 'rejected':
        return submissions.filter(s => s.status === 'rejected' || s.status === 'changes_requested');
      default:
        return submissions;
    }
  };

  const getValidationSummary = (validation: ValidationResult[]) => {
    const errors = validation.filter(v => v.severity === 'error').length;
    const warnings = validation.filter(v => v.severity === 'warning').length;
    return { errors, warnings };
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const formatPrice = (cents: number) => {
    return cents === 0 ? 'Free' : `$${(cents / 100).toFixed(2)}`;
  };

  if (isLoading) {
    return (
      <div className="submission-manager loading">
        <div className="loading-spinner">Loading submissions...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="submission-manager error">
        <div className="error-message">
          <h3>Error loading submissions</h3>
          <p>{error}</p>
          <button onClick={fetchSubmissions}>Try Again</button>
        </div>
      </div>
    );
  }

  const filteredSubmissions = getFilteredSubmissions();

  return (
    <div className="submission-manager">
      <div className="manager-header">
        <h2>My Template Submissions</h2>
        <Link to="/marketplace/submit" className="btn-primary">
          Submit New Template
        </Link>
      </div>

      {stats && (
        <div className="stats-grid">
          <div className="stat-card">
            <div className="stat-value">{stats.total_submissions}</div>
            <div className="stat-label">Total Submissions</div>
          </div>
          <div className="stat-card">
            <div className="stat-value">{stats.approved_submissions}</div>
            <div className="stat-label">Approved</div>
          </div>
          <div className="stat-card">
            <div className="stat-value">{stats.pending_submissions}</div>
            <div className="stat-label">Pending</div>
          </div>
          <div className="stat-card">
            <div className="stat-value">
              {stats.avg_review_score > 0 ? Math.round(stats.avg_review_score) : 'N/A'}
            </div>
            <div className="stat-label">Avg Review Score</div>
          </div>
          <div className="stat-card">
            <div className="stat-value">
              {stats.avg_review_time_hours > 0 ? `${Math.round(stats.avg_review_time_hours)}h` : 'N/A'}
            </div>
            <div className="stat-label">Avg Review Time</div>
          </div>
        </div>
      )}

      <div className="filter-tabs">
        <button
          className={selectedTab === 'all' ? 'active' : ''}
          onClick={() => setSelectedTab('all')}
        >
          All ({submissions.length})
        </button>
        <button
          className={selectedTab === 'drafts' ? 'active' : ''}
          onClick={() => setSelectedTab('drafts')}
        >
          Drafts ({submissions.filter(s => s.status === 'draft').length})
        </button>
        <button
          className={selectedTab === 'submitted' ? 'active' : ''}
          onClick={() => setSelectedTab('submitted')}
        >
          Submitted ({submissions.filter(s => s.status === 'submitted' || s.status === 'under_review').length})
        </button>
        <button
          className={selectedTab === 'approved' ? 'active' : ''}
          onClick={() => setSelectedTab('approved')}
        >
          Approved ({submissions.filter(s => s.status === 'approved').length})
        </button>
        <button
          className={selectedTab === 'rejected' ? 'active' : ''}
          onClick={() => setSelectedTab('rejected')}
        >
          Rejected ({submissions.filter(s => s.status === 'rejected' || s.status === 'changes_requested').length})
        </button>
      </div>

      {filteredSubmissions.length === 0 ? (
        <div className="empty-state">
          <h3>No submissions found</h3>
          <p>
            {selectedTab === 'all' 
              ? "You haven't submitted any templates yet." 
              : `No ${selectedTab} submissions found.`
            }
          </p>
          <Link to="/marketplace/submit" className="btn-primary">
            Submit Your First Template
          </Link>
        </div>
      ) : (
        <div className="submissions-list">
          {filteredSubmissions.map(submission => {
            const validation = getValidationSummary(submission.validation_results);

            return (
              <div key={submission.id} className="submission-card">
                <div className="submission-header">
                  <div className="submission-info">
                    <h3 className="submission-title">
                      {submission.submission_data.title}
                    </h3>
                    <p className="submission-description">
                      {submission.submission_data.description.substring(0, 100)}
                      {submission.submission_data.description.length > 100 && '...'}
                    </p>
                  </div>
                  <div className="submission-meta">
                    <span 
                      className="status-badge"
                      style={{ backgroundColor: STATUS_COLORS[submission.status] }}
                    >
                      {STATUS_LABELS[submission.status]}
                    </span>
                    <span className="version-badge">
                      v{submission.version_number}
                    </span>
                  </div>
                </div>

                <div className="submission-details">
                  <div className="detail-item">
                    <span className="label">Price:</span>
                    <span className="value">{formatPrice(submission.submission_data.price_cents)}</span>
                  </div>
                  <div className="detail-item">
                    <span className="label">Created:</span>
                    <span className="value">{formatDate(submission.created_at)}</span>
                  </div>
                  {submission.submitted_at && (
                    <div className="detail-item">
                      <span className="label">Submitted:</span>
                      <span className="value">{formatDate(submission.submitted_at)}</span>
                    </div>
                  )}
                  {submission.reviewed_at && (
                    <div className="detail-item">
                      <span className="label">Reviewed:</span>
                      <span className="value">{formatDate(submission.reviewed_at)}</span>
                    </div>
                  )}
                </div>

                {submission.validation_results.length > 0 && (
                  <div className="validation-summary">
                    {validation.errors > 0 && (
                      <span className="validation-count errors">
                        {validation.errors} error{validation.errors !== 1 ? 's' : ''}
                      </span>
                    )}
                    {validation.warnings > 0 && (
                      <span className="validation-count warnings">
                        {validation.warnings} warning{validation.warnings !== 1 ? 's' : ''}
                      </span>
                    )}
                  </div>
                )}

                {submission.review_comments && (
                  <div className="review-feedback">
                    <h4>Review Feedback</h4>
                    <p>{submission.review_comments}</p>
                    {submission.review_score && (
                      <div className="review-score">
                        Score: {submission.review_score}/100
                      </div>
                    )}
                  </div>
                )}

                <div className="submission-actions">
                  <Link 
                    to={`/marketplace/submissions/${submission.id}/edit`}
                    className="btn-outline"
                  >
                    Edit
                  </Link>

                  {submission.status === 'draft' && (
                    <button 
                      onClick={() => handleResubmit(submission.id)}
                      className="btn-primary"
                      disabled={validation.errors > 0}
                    >
                      Submit for Review
                    </button>
                  )}

                  {submission.status === 'changes_requested' && (
                    <button 
                      onClick={() => handleResubmit(submission.id)}
                      className="btn-primary"
                      disabled={validation.errors > 0}
                    >
                      Resubmit
                    </button>
                  )}

                  {submission.status === 'draft' && (
                    <button 
                      onClick={() => handleDeleteSubmission(submission.id)}
                      className="btn-danger"
                    >
                      Delete
                    </button>
                  )}

                  {submission.status === 'approved' && (
                    <Link 
                      to={`/marketplace/templates/${submission.template_id}`}
                      className="btn-success"
                    >
                      View Live
                    </Link>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default SubmissionManager;

// Epic 16.2.1 Submission Review Component (for moderators)
import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import './SubmissionReview.css';

interface SubmissionData {
  title: string;
  description: string;
  tags: string[];
  categories: string[];
  price_cents: number;
  is_ai_generated: boolean;
  claude_compat: string[];
  claude_model: string;
  graph_json: Record<string, any>;
  prompt_yaml?: string;
  changelog_md?: string;
  token_per_run_estimate: number;
  intended_use_cases: string[];
  technical_requirements: string[];
  example_outputs: string[];
  documentation_md?: string;
  moderation_notes?: string;
  is_first_submission: boolean;
  previous_version_id?: string;
}

interface ValidationResult {
  id: string;
  rule_id: string;
  severity: 'error' | 'warning' | 'info';
  message: string;
  details?: Record<string, any>;
  suggested_fix?: string;
  auto_fixable: boolean;
  location?: {
    field?: string;
  };
}

interface SubmissionDetails {
  id: string;
  template_id: string;
  submitter_id: string;
  version_number: number;
  status: 'draft' | 'submitted' | 'under_review' | 'changes_requested' | 'approved' | 'rejected';
  submission_data: SubmissionData;
  validation_results: ValidationResult[];
  reviewer_id?: string;
  review_comments?: string;
  review_score?: number;
  submitted_at?: string;
  reviewed_at?: string;
  created_at: string;
  updated_at: string;
}

interface ReviewFeedback {
  category: 'content' | 'quality' | 'compliance' | 'usability' | 'technical';
  rating: number;
  comments: string;
  suggestions: string[];
}

const FEEDBACK_CATEGORIES = [
  { id: 'content', label: 'Content Quality', description: 'Originality, usefulness, and relevance' },
  { id: 'quality', label: 'Technical Quality', description: 'Code structure, performance, and reliability' },
  { id: 'compliance', label: 'Policy Compliance', description: 'Adherence to platform guidelines and policies' },
  { id: 'usability', label: 'User Experience', description: 'Ease of use, documentation, and examples' },
  { id: 'technical', label: 'Technical Implementation', description: 'Claude compatibility and technical accuracy' }
];

export const SubmissionReview: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [submission, setSubmission] = useState<SubmissionDetails | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [decision, setDecision] = useState<'approved' | 'rejected' | 'changes_requested' | ''>('');
  const [overallScore, setOverallScore] = useState(75);
  const [comments, setComments] = useState('');
  const [detailedFeedback, setDetailedFeedback] = useState<ReviewFeedback[]>(
    FEEDBACK_CATEGORIES.map(cat => ({
      category: cat.id as any,
      rating: 3,
      comments: '',
      suggestions: []
    }))
  );
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    if (id) {
      fetchSubmission(id);
    }
  }, [id]);

  const fetchSubmission = async (submissionId: string) => {
    try {
      setIsLoading(true);
      const response = await fetch(`/api/marketplace/submissions/${submissionId}`, {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });

      if (!response.ok) {
        throw new Error('Failed to fetch submission');
      }

      const data = await response.json();
      setSubmission(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to fetch submission');
    } finally {
      setIsLoading(false);
    }
  };

  const handleFeedbackChange = (index: number, field: keyof ReviewFeedback, value: any) => {
    const updated = [...detailedFeedback];
    updated[index] = { ...updated[index], [field]: value };
    setDetailedFeedback(updated);
  };

  const handleSuggestionChange = (feedbackIndex: number, suggestionIndex: number, value: string) => {
    const updated = [...detailedFeedback];
    updated[feedbackIndex].suggestions[suggestionIndex] = value;
    setDetailedFeedback(updated);
  };

  const addSuggestion = (feedbackIndex: number) => {
    const updated = [...detailedFeedback];
    updated[feedbackIndex].suggestions.push('');
    setDetailedFeedback(updated);
  };

  const removeSuggestion = (feedbackIndex: number, suggestionIndex: number) => {
    const updated = [...detailedFeedback];
    updated[feedbackIndex].suggestions.splice(suggestionIndex, 1);
    setDetailedFeedback(updated);
  };

  const handleSubmitReview = async () => {
    if (!decision || !comments.trim()) {
      alert('Please provide a decision and comments');
      return;
    }

    if (!submission) return;

    try {
      setIsSubmitting(true);
      const response = await fetch(`/api/marketplace/submissions/${submission.id}/review`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify({
          decision,
          score: overallScore,
          comments,
          detailed_feedback: detailedFeedback.filter(f => f.comments.trim())
        })
      });

      if (!response.ok) {
        throw new Error('Failed to submit review');
      }

      navigate('/marketplace/admin/review-queue');
    } catch (err) {
      console.error('Review submission failed:', err);
      alert('Failed to submit review. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const formatPrice = (cents: number) => {
    return cents === 0 ? 'Free' : `$${(cents / 100).toFixed(2)}`;
  };

  const getValidationSummary = (validation: ValidationResult[]) => {
    const errors = validation.filter(v => v.severity === 'error').length;
    const warnings = validation.filter(v => v.severity === 'warning').length;
    const info = validation.filter(v => v.severity === 'info').length;
    return { errors, warnings, info };
  };

  if (isLoading) {
    return (
      <div className="submission-review loading">
        <div className="loading-spinner">Loading submission...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="submission-review error">
        <div className="error-message">
          <h3>Error loading submission</h3>
          <p>{error}</p>
          <button onClick={() => navigate('/marketplace/admin/review-queue')}>
            Back to Review Queue
          </button>
        </div>
      </div>
    );
  }

  if (!submission) {
    return (
      <div className="submission-review error">
        <div className="error-message">
          <h3>Submission not found</h3>
          <button onClick={() => navigate('/marketplace/admin/review-queue')}>
            Back to Review Queue
          </button>
        </div>
      </div>
    );
  }

  const validation = getValidationSummary(submission.validation_results);
  const data = submission.submission_data;

  return (
    <div className="submission-review">
      <div className="review-header">
        <div className="submission-info">
          <h2>{data.title}</h2>
          <div className="submission-meta">
            <span className="version">Version {submission.version_number}</span>
            <span className="status">{submission.status}</span>
            <span className="submitted-date">
              Submitted: {submission.submitted_at ? formatDate(submission.submitted_at) : 'N/A'}
            </span>
          </div>
        </div>
        <div className="review-actions">
          <button 
            className="btn-secondary"
            onClick={() => navigate('/marketplace/admin/review-queue')}
          >
            Back to Queue
          </button>
        </div>
      </div>

      <div className="review-content">
        <div className="submission-details">
          <div className="detail-section">
            <h3>Basic Information</h3>
            <div className="detail-grid">
              <div className="detail-item">
                <label>Title</label>
                <div>{data.title}</div>
              </div>
              <div className="detail-item">
                <label>Price</label>
                <div>{formatPrice(data.price_cents)}</div>
              </div>
              <div className="detail-item">
                <label>AI Generated</label>
                <div>{data.is_ai_generated ? 'Yes' : 'No'}</div>
              </div>
              <div className="detail-item">
                <label>Claude Model</label>
                <div>{data.claude_model}</div>
              </div>
            </div>
            <div className="detail-item full-width">
              <label>Description</label>
              <div className="description-text">{data.description}</div>
            </div>
            <div className="detail-item">
              <label>Tags</label>
              <div className="tags-list">
                {data.tags.map(tag => (
                  <span key={tag} className="tag">{tag}</span>
                ))}
              </div>
            </div>
          </div>

          <div className="detail-section">
            <h3>Technical Details</h3>
            <div className="detail-grid">
              <div className="detail-item">
                <label>Token Estimate</label>
                <div>{data.token_per_run_estimate.toLocaleString()}</div>
              </div>
              <div className="detail-item">
                <label>Claude Compatibility</label>
                <div>{data.claude_compat.join(', ')}</div>
              </div>
            </div>
            <div className="detail-item">
              <label>Graph JSON</label>
              <div className="code-preview">
                <pre>{JSON.stringify(data.graph_json, null, 2)}</pre>
              </div>
            </div>
            {data.prompt_yaml && (
              <div className="detail-item">
                <label>Prompt YAML</label>
                <div className="code-preview">
                  <pre>{data.prompt_yaml}</pre>
                </div>
              </div>
            )}
          </div>

          <div className="detail-section">
            <h3>Content Information</h3>
            <div className="detail-item">
              <label>Intended Use Cases</label>
              <ul>
                {data.intended_use_cases.map((useCase, index) => (
                  <li key={index}>{useCase}</li>
                ))}
              </ul>
            </div>
            <div className="detail-item">
              <label>Example Outputs</label>
              {data.example_outputs.map((output, index) => (
                <div key={index} className="example-output">
                  <strong>Example {index + 1}:</strong>
                  <p>{output}</p>
                </div>
              ))}
            </div>
            {data.technical_requirements.length > 0 && (
              <div className="detail-item">
                <label>Technical Requirements</label>
                <ul>
                  {data.technical_requirements.map((req, index) => (
                    <li key={index}>{req}</li>
                  ))}
                </ul>
              </div>
            )}
            {data.documentation_md && (
              <div className="detail-item">
                <label>Documentation</label>
                <div className="documentation-preview">
                  <pre>{data.documentation_md}</pre>
                </div>
              </div>
            )}
            {data.moderation_notes && (
              <div className="detail-item">
                <label>Moderation Notes</label>
                <div className="moderation-notes">{data.moderation_notes}</div>
              </div>
            )}
          </div>

          {submission.validation_results.length > 0 && (
            <div className="detail-section">
              <h3>Validation Results</h3>
              <div className="validation-summary">
                <div className="validation-count errors">
                  {validation.errors} Error{validation.errors !== 1 ? 's' : ''}
                </div>
                <div className="validation-count warnings">
                  {validation.warnings} Warning{validation.warnings !== 1 ? 's' : ''}
                </div>
                <div className="validation-count info">
                  {validation.info} Info
                </div>
              </div>
              <div className="validation-details">
                {submission.validation_results.map(result => (
                  <div key={result.id} className={`validation-item ${result.severity}`}>
                    <div className="validation-header">
                      <span className="severity">{result.severity}</span>
                      <span className="message">{result.message}</span>
                    </div>
                    {result.suggested_fix && (
                      <div className="suggested-fix">
                        <strong>Suggested Fix:</strong> {result.suggested_fix}
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        <div className="review-form">
          <h3>Review & Decision</h3>

          <div className="form-section">
            <label>Decision *</label>
            <div className="decision-options">
              <label className="radio-option">
                <input
                  type="radio"
                  name="decision"
                  value="approved"
                  checked={decision === 'approved'}
                  onChange={(e) => setDecision(e.target.value as any)}
                />
                <span className="approve">Approve</span>
              </label>
              <label className="radio-option">
                <input
                  type="radio"
                  name="decision"
                  value="changes_requested"
                  checked={decision === 'changes_requested'}
                  onChange={(e) => setDecision(e.target.value as any)}
                />
                <span className="changes">Request Changes</span>
              </label>
              <label className="radio-option">
                <input
                  type="radio"
                  name="decision"
                  value="rejected"
                  checked={decision === 'rejected'}
                  onChange={(e) => setDecision(e.target.value as any)}
                />
                <span className="reject">Reject</span>
              </label>
            </div>
          </div>

          <div className="form-section">
            <label>Overall Score (1-100) *</label>
            <input
              type="range"
              min="1"
              max="100"
              value={overallScore}
              onChange={(e) => setOverallScore(parseInt(e.target.value))}
            />
            <div className="score-display">{overallScore}/100</div>
          </div>

          <div className="form-section">
            <label>Comments *</label>
            <textarea
              value={comments}
              onChange={(e) => setComments(e.target.value)}
              placeholder="Provide detailed feedback for the submitter..."
              rows={4}
              maxLength={2000}
            />
            <small>{comments.length}/2000 characters</small>
          </div>

          <div className="form-section">
            <label>Detailed Feedback</label>
            <div className="feedback-sections">
              {FEEDBACK_CATEGORIES.map((category, index) => (
                <div key={category.id} className="feedback-section">
                  <h4>{category.label}</h4>
                  <p className="category-description">{category.description}</p>

                  <div className="rating-input">
                    <label>Rating (1-5)</label>
                    <input
                      type="range"
                      min="1"
                      max="5"
                      value={detailedFeedback[index].rating}
                      onChange={(e) => handleFeedbackChange(index, 'rating', parseInt(e.target.value))}
                    />
                    <span className="rating-value">{detailedFeedback[index].rating}/5</span>
                  </div>

                  <div className="comments-input">
                    <textarea
                      value={detailedFeedback[index].comments}
                      onChange={(e) => handleFeedbackChange(index, 'comments', e.target.value)}
                      placeholder={`Comments on ${category.label.toLowerCase()}...`}
                      rows={2}
                      maxLength={1000}
                    />
                  </div>

                  <div className="suggestions-input">
                    <label>Suggestions</label>
                    {detailedFeedback[index].suggestions.map((suggestion, suggestionIndex) => (
                      <div key={suggestionIndex} className="suggestion-item">
                        <input
                          type="text"
                          value={suggestion}
                          onChange={(e) => handleSuggestionChange(index, suggestionIndex, e.target.value)}
                          placeholder="Suggestion for improvement..."
                        />
                        <button 
                          type="button"
                          onClick={() => removeSuggestion(index, suggestionIndex)}
                          className="remove-suggestion"
                        >
                          ×
                        </button>
                      </div>
                    ))}
                    <button 
                      type="button"
                      onClick={() => addSuggestion(index)}
                      className="add-suggestion"
                    >
                      Add Suggestion
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>

          <div className="form-actions">
            <button 
              className="btn-primary"
              onClick={handleSubmitReview}
              disabled={!decision || !comments.trim() || isSubmitting}
            >
              {isSubmitting ? 'Submitting...' : 'Submit Review'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default SubmissionReview;

// Epic 16 Marketplace - Template Card Component
import React from 'react';
import { StarRating } from './StarRating';
import { PriceDisplay } from './PriceDisplay';
import { Badge } from '../common/Badge';
import './TemplateCard.css';

interface Template {
  id: string;
  title: string;
  description?: string;
  tags: string[];
  price_cents: number;
  avg_rating: number;
  total_reviews: number;
  total_purchases: number;
  categories?: string[];
  owner?: {
    id: string;
    name: string;
    verified: boolean;
  };
  featured_at?: string;
  created_at: string;
  is_ai_generated?: boolean;
  claude_compat: string[];
}

interface TemplateCardProps {
  template: Template;
  onClick: () => void;
  variant?: 'grid' | 'list' | 'featured';
  showStats?: boolean;
  className?: string;
}

export const TemplateCard: React.FC<TemplateCardProps> = ({
  template,
  onClick,
  variant = 'grid',
  showStats = true,
  className = ''
}) => {
  const {
    title,
    description,
    tags,
    price_cents,
    avg_rating,
    total_reviews,
    total_purchases,
    categories,
    owner,
    featured_at,
    is_ai_generated,
    claude_compat
  } = template;

  const truncatedDescription = description && description.length > 120 
    ? description.substring(0, 120) + '...' 
    : description;

  const handleCardClick = (e: React.MouseEvent) => {
    e.preventDefault();
    onClick();
  };

  const handlePreviewClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    // TODO: Open preview modal
    console.log('Preview template:', template.id);
  };

  const handleOwnerClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    // TODO: Navigate to creator profile
    console.log('View creator:', owner?.id);
  };

  return (
    <div 
      className={`template-card ${variant} ${className}`}
      onClick={handleCardClick}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onClick();
        }
      }}
    >
      {/* Card Header */}
      <div className="card-header">
        <div className="template-badges">
          {featured_at && <Badge variant="featured">Featured</Badge>}
          {price_cents === 0 && <Badge variant="free">Free</Badge>}
          {is_ai_generated && <Badge variant="ai">AI Generated</Badge>}
        </div>

        <button
          onClick={handlePreviewClick}
          className="preview-button"
          aria-label="Preview template"
          title="Preview template"
        >
          <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
            <path
              d="M1 8C1 8 3.5 3 8 3C12.5 3 15 8 15 8C15 8 12.5 13 8 13C3.5 13 1 8 1 8Z"
              stroke="currentColor"
              strokeWidth="1.5"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
            <path
              d="M8 10C9.10457 10 10 9.10457 10 8C10 6.89543 9.10457 6 8 6C6.89543 6 6 6.89543 6 8C6 9.10457 6.89543 10 8 10Z"
              stroke="currentColor"
              strokeWidth="1.5"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </button>
      </div>

      {/* Card Content */}
      <div className="card-content">
        <h3 className="template-title">{title}</h3>

        {truncatedDescription && (
          <p className="template-description">{truncatedDescription}</p>
        )}

        {/* Template Tags */}
        {tags.length > 0 && (
          <div className="template-tags">
            {tags.slice(0, 3).map((tag) => (
              <span key={tag} className="tag">
                {tag}
              </span>
            ))}
            {tags.length > 3 && (
              <span className="tag more">+{tags.length - 3}</span>
            )}
          </div>
        )}

        {/* Categories */}
        {categories && categories.length > 0 && (
          <div className="template-categories">
            {categories.slice(0, 2).map((category) => (
              <span key={category} className="category">
                {category}
              </span>
            ))}
          </div>
        )}

        {/* Claude Compatibility */}
        <div className="claude-compat">
          <span className="compat-label">Compatible with:</span>
          <div className="compat-models">
            {claude_compat.slice(0, 2).map((model) => (
              <span key={model} className="compat-model">
                {model.replace('claude-', '')}
              </span>
            ))}
            {claude_compat.length > 2 && (
              <span className="compat-model more">+{claude_compat.length - 2}</span>
            )}
          </div>
        </div>
      </div>

      {/* Card Footer */}
      <div className="card-footer">
        <div className="footer-top">
          {/* Rating */}
          <div className="rating-section">
            <StarRating rating={avg_rating} />
            <span className="rating-text">
              {avg_rating.toFixed(1)} ({total_reviews})
            </span>
          </div>

          {/* Price */}
          <PriceDisplay 
            priceCents={price_cents} 
            size="medium"
          />
        </div>

        <div className="footer-bottom">
          {/* Creator Info */}
          {owner && (
            <button
              onClick={handleOwnerClick}
              className="creator-info"
              aria-label={`View ${owner.name}'s profile`}
            >
              <span className="creator-name">{owner.name}</span>
              {owner.verified && (
                <svg 
                  width="14" 
                  height="14" 
                  viewBox="0 0 14 14" 
                  fill="none"
                  className="verified-icon"
                  title="Verified creator"
                >
                  <path
                    d="M5.25 7L6.25 8L8.75 5.5M12.25 7C12.25 9.89949 9.89949 12.25 7 12.25C4.10051 12.25 1.75 9.89949 1.75 7C1.75 4.10051 4.10051 1.75 7 1.75C9.89949 1.75 12.25 4.10051 12.25 7Z"
                    stroke="#10B981"
                    strokeWidth="1.16667"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    fill="none"
                  />
                </svg>
              )}
            </button>
          )}

          {/* Stats */}
          {showStats && (
            <div className="template-stats">
              <span className="stat">
                <svg width="12" height="12" viewBox="0 0 12 12" fill="none">
                  <path
                    d="M6 1L7.545 4.13L11 4.635L8.5 7.07L9.09 10.5L6 8.885L2.91 10.5L3.5 7.07L1 4.635L4.455 4.13L6 1Z"
                    fill="currentColor"
                  />
                </svg>
                {total_purchases}
              </span>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

// Epic 16 Marketplace - Template Detail Page Component
import React, { useState, useEffect } from 'react';
import { StarRating } from './StarRating';
import { PriceDisplay } from './PriceDisplay';
import { Badge } from '../common/Badge';
import { LoadingSpinner } from '../common/LoadingSpinner';
import { TemplateCard } from './TemplateCard';
import { ReviewList } from './ReviewList';
import { PreviewModal } from './PreviewModal';
import { PurchaseModal } from './PurchaseModal';
import { useMarketplace } from '../../hooks/useMarketplace';
import './TemplateDetail.css';

interface TemplateDetailProps {
  templateId: string;
  className?: string;
}

export const TemplateDetail: React.FC<TemplateDetailProps> = ({
  templateId,
  className = ''
}) => {
  const [template, setTemplate] = useState<any>(null);
  const [similarTemplates, setSimilarTemplates] = useState<any[]>([]);
  const [reviews, setReviews] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [showPreview, setShowPreview] = useState(false);
  const [showPurchase, setShowPurchase] = useState(false);
  const [activeTab, setActiveTab] = useState<'overview' | 'reviews' | 'versions'>('overview');

  const { getTemplate, previewTemplate, purchaseTemplate } = useMarketplace();

  useEffect(() => {
    loadTemplateData();
  }, [templateId]);

  const loadTemplateData = async () => {
    setLoading(true);
    setError(null);

    try {
      // Load template details
      const templateData = await getTemplate(templateId);
      setTemplate(templateData);

      // Load similar templates
      const similarResponse = await fetch(`/api/marketplace/templates/${templateId}/similar?limit=4`);
      if (similarResponse.ok) {
        const similarData = await similarResponse.json();
        setSimilarTemplates(similarData.templates || []);
      }

      // Load reviews
      const reviewsResponse = await fetch(`/api/marketplace/templates/${templateId}/reviews`);
      if (reviewsResponse.ok) {
        const reviewsData = await reviewsResponse.json();
        setReviews(reviewsData || []);
      }

    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load template');
    } finally {
      setLoading(false);
    }
  };

  const handlePreview = () => {
    setShowPreview(true);
  };

  const handlePurchase = () => {
    setShowPurchase(true);
  };

  const handlePurchaseComplete = (success: boolean) => {
    setShowPurchase(false);
    if (success) {
      // Refresh template data to update purchase status
      loadTemplateData();
    }
  };

  const handleSimilarTemplateClick = (id: string) => {
    // Navigate to similar template
    window.location.href = `/marketplace/templates/${id}`;
  };

  if (loading) {
    return (
      <div className={`template-detail loading ${className}`}>
        <LoadingSpinner size="large" message="Loading template..." />
      </div>
    );
  }

  if (error || !template) {
    return (
      <div className={`template-detail error ${className}`}>
        <div className="error-message">
          <h2>Template not found</h2>
          <p>{error || 'The requested template could not be found.'}</p>
