// Epic 16.2.1 Template Submission Form Component
import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import './TemplateSubmissionForm.css';

interface SubmissionData {
  title: string;
  description: string;
  tags: string[];
  categories: string[];
  price_cents: number;
  is_ai_generated: boolean;
  claude_compat: string[];
  claude_model: string;
  graph_json: Record<string, any>;
  prompt_yaml?: string;
  changelog_md?: string;
  token_per_run_estimate: number;
  intended_use_cases: string[];
  technical_requirements: string[];
  example_outputs: string[];
  documentation_md?: string;
  moderation_notes?: string;
  is_first_submission: boolean;
  previous_version_id?: string;
}

interface ValidationResult {
  id: string;
  rule_id: string;
  severity: 'error' | 'warning' | 'info';
  message: string;
  details?: Record<string, any>;
  suggested_fix?: string;
  auto_fixable: boolean;
  location?: {
    field?: string;
  };
}

interface Category {
  id: string;
  name: string;
  description?: string;
  icon?: string;
}

interface TemplateSubmissionFormProps {
  templateId?: string;
  onSubmit?: (submissionId: string) => void;
  onCancel?: () => void;
}

const CLAUDE_MODELS = [
  'claude-3-sonnet',
  'claude-3-haiku',
  'claude-3-opus',
  'claude-3.5-sonnet'
];

const DEFAULT_SUBMISSION_DATA: SubmissionData = {
  title: '',
  description: '',
  tags: [],
  categories: [],
  price_cents: 0,
  is_ai_generated: false,
  claude_compat: ['claude-3-sonnet'],
  claude_model: 'claude-3-sonnet',
  graph_json: {},
  token_per_run_estimate: 0,
  intended_use_cases: [''],
  technical_requirements: [],
  example_outputs: [''],
  is_first_submission: true
};

export const TemplateSubmissionForm: React.FC<TemplateSubmissionFormProps> = ({
  templateId,
  onSubmit,
  onCancel
}) => {
  const navigate = useNavigate();
  const { id } = useParams<{ id: string }>();
  const [submissionData, setSubmissionData] = useState<SubmissionData>(DEFAULT_SUBMISSION_DATA);
  const [validationResults, setValidationResults] = useState<ValidationResult[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [currentStep, setCurrentStep] = useState(1);
  const [isDraft, setIsDraft] = useState(true);
  const [submissionId, setSubmissionId] = useState<string | null>(null);
  const [graphJsonString, setGraphJsonString] = useState('{}');
  const [tagInput, setTagInput] = useState('');

  const totalSteps = 4;

  useEffect(() => {
    fetchCategories();
    if (id) {
      fetchSubmission(id);
    }
  }, [id]);

  const fetchCategories = async () => {
    try {
      const response = await fetch('/api/marketplace/categories', {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });
      if (response.ok) {
        const data = await response.json();
        setCategories(data);
      }
    } catch (error) {
      console.error('Failed to fetch categories:', error);
    }
  };

  const fetchSubmission = async (submissionId: string) => {
    try {
      setIsLoading(true);
      const response = await fetch(`/api/marketplace/submissions/${submissionId}`, {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });
      if (response.ok) {
        const submission = await response.json();
        setSubmissionData(submission.submission_data);
        setValidationResults(submission.validation_results || []);
        setIsDraft(submission.status === 'draft');
        setSubmissionId(submission.id);
        setGraphJsonString(JSON.stringify(submission.submission_data.graph_json, null, 2));
      }
    } catch (error) {
      console.error('Failed to fetch submission:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleInputChange = (field: keyof SubmissionData, value: any) => {
    setSubmissionData(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const handleArrayInputChange = (field: keyof SubmissionData, index: number, value: string) => {
    const array = [...(submissionData[field] as string[])];
    array[index] = value;
    setSubmissionData(prev => ({
      ...prev,
      [field]: array
    }));
  };

  const addArrayItem = (field: keyof SubmissionData) => {
    const array = [...(submissionData[field] as string[])];
    array.push('');
    setSubmissionData(prev => ({
      ...prev,
      [field]: array
    }));
  };

  const removeArrayItem = (field: keyof SubmissionData, index: number) => {
    const array = [...(submissionData[field] as string[])];
    array.splice(index, 1);
    setSubmissionData(prev => ({
      ...prev,
      [field]: array
    }));
  };

  const handleTagInputKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && tagInput.trim()) {
      e.preventDefault();
      if (!submissionData.tags.includes(tagInput.trim())) {
        handleInputChange('tags', [...submissionData.tags, tagInput.trim()]);
      }
      setTagInput('');
    }
  };

  const removeTag = (tagToRemove: string) => {
    handleInputChange('tags', submissionData.tags.filter(tag => tag !== tagToRemove));
  };

  const handleGraphJsonChange = (value: string) => {
    setGraphJsonString(value);
    try {
      const parsed = JSON.parse(value);
      handleInputChange('graph_json', parsed);
    } catch (error) {
      // Invalid JSON, don't update the submission data
    }
  };

  const validateCurrentStep = (): boolean => {
    const errors = validationResults.filter(r => r.severity === 'error');

    switch (currentStep) {
      case 1: // Basic Info
        return !errors.some(e => 
          e.location?.field && ['title', 'description', 'tags', 'categories'].includes(e.location.field)
        );
      case 2: // Technical Details
        return !errors.some(e => 
          e.location?.field && ['graph_json', 'claude_model', 'token_per_run_estimate'].includes(e.location.field)
        );
      case 3: // Content Details
        return !errors.some(e => 
          e.location?.field && ['intended_use_cases', 'example_outputs'].includes(e.location.field)
        );
      case 4: // Review
        return errors.length === 0;
      default:
        return true;
    }
  };

  const handleNext = async () => {
    if (currentStep < totalSteps) {
      await saveDraft();
      setCurrentStep(currentStep + 1);
    }
  };

  const handlePrevious = () => {
    if (currentStep > 1) {
      setCurrentStep(currentStep - 1);
    }
  };

  const saveDraft = async () => {
    try {
      setIsLoading(true);
      const payload = {
        template_id: templateId,
        submission_data: submissionData
      };

      const url = submissionId 
        ? `/api/marketplace/submissions/${submissionId}`
        : '/api/marketplace/submissions';

      const method = submissionId ? 'PUT' : 'POST';

      const response = await fetch(url, {
        method,
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify(payload)
      });

      if (response.ok) {
        const result = await response.json();
        if (!submissionId) {
          setSubmissionId(result.id);
        }
        setValidationResults(result.validation_results || []);
        return true;
      }
      return false;
    } catch (error) {
      console.error('Failed to save draft:', error);
      return false;
    } finally {
      setIsLoading(false);
    }
  };

  const handleSubmitForReview = async () => {
    if (!submissionId) {
      const success = await saveDraft();
      if (!success) return;
    }

    try {
      setIsLoading(true);
      const response = await fetch(`/api/marketplace/submissions/${submissionId}/submit`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });

      if (response.ok) {
        setIsDraft(false);
        if (onSubmit) {
          onSubmit(submissionId);
        } else {
          navigate('/marketplace/submissions');
        }
      }
    } catch (error) {
      console.error('Failed to submit for review:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const renderValidationResults = () => {
    if (validationResults.length === 0) return null;

    const errors = validationResults.filter(r => r.severity === 'error');
    const warnings = validationResults.filter(r => r.severity === 'warning');

    return (
      <div className="validation-results">
        {errors.length > 0 && (
          <div className="validation-errors">
            <h4>Errors (must be fixed)</h4>
            {errors.map(error => (
              <div key={error.id} className="validation-error">
                <span className="error-icon">⚠️</span>
                <div>
                  <p>{error.message}</p>
                  {error.suggested_fix && (
                    <p className="suggested-fix">💡 {error.suggested_fix}</p>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}

        {warnings.length > 0 && (
          <div className="validation-warnings">
            <h4>Warnings (recommended to fix)</h4>
            {warnings.map(warning => (
              <div key={warning.id} className="validation-warning">
                <span className="warning-icon">⚠️</span>
                <div>
                  <p>{warning.message}</p>
                  {warning.suggested_fix && (
                    <p className="suggested-fix">💡 {warning.suggested_fix}</p>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  };

  const renderStep1 = () => (
    <div className="step-content">
      <h3>Basic Information</h3>

      <div className="form-group">
        <label htmlFor="title">Template Title *</label>
        <input
          id="title"
          type="text"
          value={submissionData.title}
          onChange={(e) => handleInputChange('title', e.target.value)}
          placeholder="Enter a descriptive title for your template"
          maxLength={255}
        />
      </div>

      <div className="form-group">
        <label htmlFor="description">Description *</label>
        <textarea
          id="description"
          value={submissionData.description}
          onChange={(e) => handleInputChange('description', e.target.value)}
          placeholder="Describe what your template does and how it can be used"
          rows={4}
          maxLength={2000}
        />
        <small>{submissionData.description.length}/2000 characters</small>
      </div>

      <div className="form-group">
        <label htmlFor="tags">Tags *</label>
        <div className="tags-container">
          <div className="tags-list">
            {submissionData.tags.map(tag => (
              <span key={tag} className="tag">
                {tag}
                <button type="button" onClick={() => removeTag(tag)}>×</button>
              </span>
            ))}
          </div>
          <input
            id="tags"
            type="text"
            value={tagInput}
            onChange={(e) => setTagInput(e.target.value)}
            onKeyDown={handleTagInputKeyDown}
            placeholder="Type a tag and press Enter"
          />
        </div>
        <small>Add relevant tags to help users find your template</small>
      </div>

      <div className="form-group">
        <label htmlFor="categories">Categories *</label>
        <div className="categories-grid">
          {categories.map(category => (
            <label key={category.id} className="category-option">
              <input
                type="checkbox"
                checked={submissionData.categories.includes(category.id)}
                onChange={(e) => {
                  if (e.target.checked) {
                    handleInputChange('categories', [...submissionData.categories, category.id]);
                  } else {
                    handleInputChange('categories', submissionData.categories.filter(c => c !== category.id));
                  }
                }}
              />
              <span className="category-name">{category.name}</span>
              {category.description && (
                <small className="category-description">{category.description}</small>
              )}
            </label>
          ))}
        </div>
      </div>

      <div className="form-group">
        <label htmlFor="price">Price (USD)</label>
        <input
          id="price"
          type="number"
          value={submissionData.price_cents / 100}
          onChange={(e) => handleInputChange('price_cents', Math.round(parseFloat(e.target.value || '0') * 100))}
          step="0.01"
          min="0"
          max="1000"
        />
        <small>Leave as 0 for free templates</small>
      </div>

      <div className="form-group">
        <label className="checkbox-label">
          <input
            type="checkbox"
            checked={submissionData.is_ai_generated}
            onChange={(e) => handleInputChange('is_ai_generated', e.target.checked)}
          />
          This template was generated using AI
        </label>
      </div>
    </div>
  );

  const renderStep2 = () => (
    <div className="step-content">
      <h3>Technical Details</h3>

      <div className="form-group">
        <label htmlFor="claude_model">Claude Model *</label>
        <select
          id="claude_model"
          value={submissionData.claude_model}
          onChange={(e) => handleInputChange('claude_model', e.target.value)}
        >
          {CLAUDE_MODELS.map(model => (
            <option key={model} value={model}>{model}</option>
          ))}
        </select>
      </div>

      <div className="form-group">
        <label htmlFor="claude_compat">Claude Compatibility *</label>
        <div className="claude-compat-options">
          {CLAUDE_MODELS.map(model => (
            <label key={model} className="checkbox-label">
              <input
                type="checkbox"
                checked={submissionData.claude_compat.includes(model)}
                onChange={(e) => {
                  if (e.target.checked) {
                    handleInputChange('claude_compat', [...submissionData.claude_compat, model]);
                  } else {
                    handleInputChange('claude_compat', submissionData.claude_compat.filter(m => m !== model));
                  }
                }}
              />
              {model}
            </label>
          ))}
        </div>
      </div>

      <div className="form-group">
        <label htmlFor="graph_json">Graph JSON *</label>
        <textarea
          id="graph_json"
          value={graphJsonString}
          onChange={(e) => handleGraphJsonChange(e.target.value)}
          placeholder="Paste your graph JSON here"
          rows={10}
          className="code-textarea"
        />
        <small>Valid JSON representing your template's graph structure</small>
      </div>

      <div className="form-group">
        <label htmlFor="prompt_yaml">Prompt YAML (Optional)</label>
        <textarea
          id="prompt_yaml"
          value={submissionData.prompt_yaml || ''}
          onChange={(e) => handleInputChange('prompt_yaml', e.target.value)}
          placeholder="Optional YAML configuration for prompts"
          rows={6}
          className="code-textarea"
        />
      </div>

      <div className="form-group">
        <label htmlFor="token_estimate">Token Per Run Estimate</label>
        <input
          id="token_estimate"
          type="number"
          value={submissionData.token_per_run_estimate}
          onChange={(e) => handleInputChange('token_per_run_estimate', parseInt(e.target.value || '0'))}
          min="0"
          placeholder="Estimated tokens per execution"
        />
        <small>Approximate number of tokens this template will use per run</small>
      </div>

      <div className="form-group">
        <label htmlFor="technical_requirements">Technical Requirements</label>
        {submissionData.technical_requirements.map((req, index) => (
          <div key={index} className="array-input">
            <input
              type="text"
              value={req}
              onChange={(e) => handleArrayInputChange('technical_requirements', index, e.target.value)}
              placeholder="e.g., Requires image upload capability"
            />
            <button type="button" onClick={() => removeArrayItem('technical_requirements', index)}>
              Remove
            </button>
          </div>
        ))}
        <button type="button" onClick={() => addArrayItem('technical_requirements')}>
          Add Requirement
        </button>
      </div>
    </div>
  );

  const renderStep3 = () => (
    <div className="step-content">
      <h3>Content Details</h3>

      <div className="form-group">
        <label htmlFor="intended_use_cases">Intended Use Cases *</label>
        {submissionData.intended_use_cases.map((useCase, index) => (
          <div key={index} className="array-input">
            <input
              type="text"
              value={useCase}
              onChange={(e) => handleArrayInputChange('intended_use_cases', index, e.target.value)}
              placeholder="e.g., Blog post generation, Marketing copy"
            />
            {submissionData.intended_use_cases.length > 1 && (
              <button type="button" onClick={() => removeArrayItem('intended_use_cases', index)}>
                Remove
              </button>
            )}
          </div>
        ))}
        <button type="button" onClick={() => addArrayItem('intended_use_cases')}>
          Add Use Case
        </button>
      </div>

      <div className="form-group">
        <label htmlFor="example_outputs">Example Outputs *</label>
        {submissionData.example_outputs.map((output, index) => (
          <div key={index} className="array-input">
            <textarea
              value={output}
              onChange={(e) => handleArrayInputChange('example_outputs', index, e.target.value)}
              placeholder="Show an example of what this template generates"
              rows={3}
            />
            {submissionData.example_outputs.length > 1 && (
              <button type="button" onClick={() => removeArrayItem('example_outputs', index)}>
                Remove
              </button>
            )}
          </div>
        ))}
        <button type="button" onClick={() => addArrayItem('example_outputs')}>
          Add Example
        </button>
      </div>

      <div className="form-group">
        <label htmlFor="documentation">Documentation (Optional)</label>
        <textarea
          id="documentation"
          value={submissionData.documentation_md || ''}
          onChange={(e) => handleInputChange('documentation_md', e.target.value)}
          placeholder="Provide detailed documentation for your template (Markdown supported)"
          rows={6}
        />
      </div>

      <div className="form-group">
        <label htmlFor="changelog">Changelog (Optional)</label>
        <textarea
          id="changelog"
          value={submissionData.changelog_md || ''}
          onChange={(e) => handleInputChange('changelog_md', e.target.value)}
          placeholder="Describe changes in this version"
          rows={4}
        />
      </div>

      <div className="form-group">
        <label htmlFor="moderation_notes">Notes for Moderators (Optional)</label>
        <textarea
          id="moderation_notes"
          value={submissionData.moderation_notes || ''}
          onChange={(e) => handleInputChange('moderation_notes', e.target.value)}
          placeholder="Any additional information for the review team"
          rows={3}
        />
      </div>
    </div>
  );

  const renderStep4 = () => (
    <div className="step-content">
      <h3>Review & Submit</h3>

      <div className="submission-summary">
        <h4>Submission Summary</h4>
        <div className="summary-item">
          <strong>Title:</strong> {submissionData.title}
        </div>
        <div className="summary-item">
          <strong>Price:</strong> ${(submissionData.price_cents / 100).toFixed(2)}
        </div>
        <div className="summary-item">
          <strong>Categories:</strong> {submissionData.categories.length} selected
        </div>
        <div className="summary-item">
          <strong>Tags:</strong> {submissionData.tags.join(', ')}
        </div>
        <div className="summary-item">
          <strong>Claude Model:</strong> {submissionData.claude_model}
        </div>
        <div className="summary-item">
          <strong>Token Estimate:</strong> {submissionData.token_per_run_estimate}
        </div>
      </div>

      {renderValidationResults()}

      {validationResults.filter(r => r.severity === 'error').length === 0 && (
        <div className="ready-to-submit">
          <h4>✅ Ready to Submit</h4>
          <p>Your template has passed all validation checks and is ready for review.</p>
        </div>
      )}
    </div>
  );

  if (isLoading) {
    return (
      <div className="submission-form loading">
        <div className="loading-spinner">Loading...</div>
      </div>
    );
  }

  return (
    <div className="submission-form">
      <div className="submission-header">
        <h2>{submissionId ? 'Edit Submission' : 'Submit New Template'}</h2>
        <div className="step-indicator">
          Step {currentStep} of {totalSteps}
        </div>
      </div>

      <div className="progress-bar">
        <div 
          className="progress-fill"
          style={{ width: `${(currentStep / totalSteps) * 100}%` }}
        />
      </div>

      <div className="form-container">
        {currentStep === 1 && renderStep1()}
        {currentStep === 2 && renderStep2()}
        {currentStep === 3 && renderStep3()}
        {currentStep === 4 && renderStep4()}
      </div>

      <div className="form-actions">
        {currentStep > 1 && (
          <button type="button" onClick={handlePrevious} className="btn-secondary">
            Previous
          </button>
        )}

        <button type="button" onClick={saveDraft} className="btn-outline" disabled={isLoading}>
          Save Draft
        </button>

        {currentStep < totalSteps ? (
          <button 
            type="button" 
            onClick={handleNext}
            className="btn-primary"
            disabled={!validateCurrentStep()}
          >
            Next
          </button>
        ) : (
          <button 
            type="button" 
            onClick={handleSubmitForReview}
            className="btn-primary"
            disabled={validationResults.some(r => r.severity === 'error') || isLoading}
          >
            Submit for Review
          </button>
        )}

        {onCancel && (
          <button type="button" onClick={onCancel} className="btn-secondary">
            Cancel
          </button>
        )}
      </div>
    </div>
  );
};

export default TemplateSubmissionForm;

// Epic 16.2.2 Version Editor Component
import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import './VersionEditor.css';

interface VersionData {
  version_number: string;
  status: 'draft' | 'published' | 'deprecated' | 'archived';
  visibility: 'public' | 'private' | 'beta';
  claude_model: string;
  graph_json: Record<string, any>;
  prompt_yaml?: string;
  release_notes: string;
  compatibility_level: 'breaking' | 'major' | 'minor' | 'patch';
  migration_guide?: string;
  deprecated_features: string[];
  new_features: string[];
  breaking_changes: string[];
  bug_fixes: string[];
  known_issues: string[];
  min_claude_version?: string;
  max_claude_version?: string;
  required_features: string[];
  optional_features: string[];
  token_per_run_estimate: number;
}

const CLAUDE_MODELS = [
  'claude-3-sonnet',
  'claude-3-haiku',
  'claude-3-opus',
  'claude-3.5-sonnet'
];

const DEFAULT_VERSION_DATA: VersionData = {
  version_number: '',
  status: 'draft',
  visibility: 'private',
  claude_model: 'claude-3-sonnet',
  graph_json: {},
  release_notes: '',
  compatibility_level: 'minor',
  deprecated_features: [],
  new_features: [],
  breaking_changes: [],
  bug_fixes: [],
  known_issues: [],
  required_features: [],
  optional_features: [],
  token_per_run_estimate: 0
};

export const VersionEditor: React.FC = () => {
  const { templateId, versionId } = useParams<{ templateId: string; versionId?: string }>();
  const navigate = useNavigate();
  const [versionData, setVersionData] = useState<VersionData>(DEFAULT_VERSION_DATA);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [graphJsonString, setGraphJsonString] = useState('{}');
  const [currentStep, setCurrentStep] = useState(1);
  const [lastVersion, setLastVersion] = useState<string>('');

  const totalSteps = 4;

  useEffect(() => {
    if (templateId) {
      fetchLastVersion();
      if (versionId) {
        fetchVersion();
      }
    }
  }, [templateId, versionId]);

  const fetchLastVersion = async () => {
    try {
      const response = await fetch(`/api/marketplace/templates/${templateId}/versions`, {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });

      if (response.ok) {
        const versions = await response.json();
        if (versions.length > 0) {
          const latest = versions[0];
          setLastVersion(latest.version_number);

          // Pre-populate with the latest version data if creating new version
          if (!versionId) {
            setVersionData(prev => ({
              ...prev,
              claude_model: latest.claude_model,
              graph_json: latest.graph_json,
              prompt_yaml: latest.prompt_yaml,
              required_features: latest.required_features,
              optional_features: latest.optional_features,
              token_per_run_estimate: latest.token_per_run_estimate
            }));
            setGraphJsonString(JSON.stringify(latest.graph_json, null, 2));
          }
        }
      }
    } catch (error) {
      console.error('Failed to fetch last version:', error);
    }
  };

  const fetchVersion = async () => {
    if (!versionId) return;

    try {
      setIsLoading(true);
      const response = await fetch(`/api/marketplace/versions/${versionId}`, {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });

      if (!response.ok) {
        throw new Error('Failed to fetch version');
      }

      const version = await response.json();
      setVersionData({
        version_number: version.version_number,
        status: version.status,
        visibility: version.visibility,
        claude_model: version.claude_model,
        graph_json: version.graph_json,
        prompt_yaml: version.prompt_yaml || '',
        release_notes: version.release_notes,
        compatibility_level: version.compatibility_level,
        migration_guide: version.migration_guide || '',
        deprecated_features: version.deprecated_features,
        new_features: version.new_features,
        breaking_changes: version.breaking_changes,
        bug_fixes: version.bug_fixes,
        known_issues: version.known_issues,
        min_claude_version: version.min_claude_version || '',
        max_claude_version: version.max_claude_version || '',
        required_features: version.required_features,
        optional_features: version.optional_features,
        token_per_run_estimate: version.token_per_run_estimate
      });
      setGraphJsonString(JSON.stringify(version.graph_json, null, 2));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to fetch version');
    } finally {
      setIsLoading(false);
    }
  };

  const handleInputChange = (field: keyof VersionData, value: any) => {
    setVersionData(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const handleArrayInputChange = (field: keyof VersionData, index: number, value: string) => {
    const array = [...(versionData[field] as string[])];
    array[index] = value;
    setVersionData(prev => ({
      ...prev,
      [field]: array
    }));
  };

  const addArrayItem = (field: keyof VersionData) => {
    const array = [...(versionData[field] as string[])];
    array.push('');
    setVersionData(prev => ({
      ...prev,
      [field]: array
    }));
  };

  const removeArrayItem = (field: keyof VersionData, index: number) => {
    const array = [...(versionData[field] as string[])];
    array.splice(index, 1);
    setVersionData(prev => ({
      ...prev,
      [field]: array
    }));
  };

  const handleGraphJsonChange = (value: string) => {
    setGraphJsonString(value);
    try {
      const parsed = JSON.parse(value);
      handleInputChange('graph_json', parsed);
    } catch (error) {
      // Invalid JSON, don't update the version data
    }
  };

  const generateNextVersion = (lastVer: string, compatibilityLevel: string): string => {
    if (!lastVer) return '1.0.0';

    const parts = lastVer.split('.').map(Number);
    const [major, minor, patch] = parts;

    switch (compatibilityLevel) {
      case 'breaking':
        return `${major + 1}.0.0`;
      case 'major':
        return `${major + 1}.0.0`;
      case 'minor':
        return `${major}.${minor + 1}.0`;
      case 'patch':
        return `${major}.${minor}.${patch + 1}`;
      default:
        return `${major}.${minor}.${patch + 1}`;
    }
  };

  const handleCompatibilityChange = (level: string) => {
    handleInputChange('compatibility_level', level);

    // Auto-suggest version number if creating new version
    if (!versionId && lastVersion) {
      const suggestedVersion = generateNextVersion(lastVersion, level);
      handleInputChange('version_number', suggestedVersion);
    }
  };

  const validateStep = (step: number): boolean => {
    switch (step) {
      case 1: // Basic Info
        return !!(versionData.version_number && versionData.release_notes && versionData.compatibility_level);
      case 2: // Technical Details
        return !!(versionData.claude_model && Object.keys(versionData.graph_json).length > 0);
      case 3: // Change Details
        return true; // Optional fields
      case 4: // Review
        return true;
      default:
        return true;
    }
  };

  const handleNext = () => {
    if (currentStep < totalSteps && validateStep(currentStep)) {
      setCurrentStep(currentStep + 1);
    }
  };

  const handlePrevious = () => {
    if (currentStep > 1) {
      setCurrentStep(currentStep - 1);
    }
  };

  const handleSave = async (publish: boolean = false) => {
    try {
      setIsLoading(true);
      setError(null);

      // Set status based on publish flag
      const dataToSave = {
        ...versionData,
        status: publish ? 'published' : versionData.status
      };

      const url = versionId 
        ? `/api/marketplace/versions/${versionId}`
        : `/api/marketplace/templates/${templateId}/versions`;

      const method = versionId ? 'PUT' : 'POST';

      const response = await fetch(url, {
        method,
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify(dataToSave)
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Failed to save version');
      }

      const result = await response.json();
      navigate(`/marketplace/templates/${templateId}/versions`);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save version');
    } finally {
      setIsLoading(false);
    }
  };

  const renderStep1 = () => (
    <div className="step-content">
      <h3>Basic Information</h3>

      <div className="form-group">
        <label htmlFor="version_number">Version Number *</label>
        <input
          id="version_number"
          type="text"
          value={versionData.version_number}
          onChange={(e) => handleInputChange('version_number', e.target.value)}
          placeholder="e.g., 1.2.3"
          pattern="^\d+\.\d+\.\d+(-[a-zA-Z0-9]+)?$"
        />
        {lastVersion && (
          <small>Last version: {lastVersion}</small>
        )}
      </div>

      <div className="form-group">
        <label htmlFor="compatibility_level">Compatibility Level *</label>
        <div className="compatibility-options">
          {[
            { value: 'patch', label: 'Patch', description: 'Bug fixes and minor improvements', color: '#3b82f6' },
            { value: 'minor', label: 'Minor', description: 'New features, backward compatible', color: '#10b981' },
            { value: 'major', label: 'Major', description: 'Significant changes, mostly compatible', color: '#f59e0b' },
            { value: 'breaking', label: 'Breaking', description: 'Breaking changes, not backward compatible', color: '#ef4444' }
          ].map(option => (
            <label key={option.value} className="compatibility-option">
              <input
                type="radio"
                name="compatibility_level"
                value={option.value}
                checked={versionData.compatibility_level === option.value}
                onChange={(e) => handleCompatibilityChange(e.target.value)}
              />
              <div className="option-content">
                <div 
                  className="option-indicator"
                  style={{ backgroundColor: option.color }}
                />
                <div className="option-text">
                  <strong>{option.label}</strong>
                  <small>{option.description}</small>
                </div>
              </div>
            </label>
          ))}
        </div>
      </div>

      <div className="form-group">
        <label htmlFor="status">Status</label>
        <select
          id="status"
          value={versionData.status}
          onChange={(e) => handleInputChange('status', e.target.value)}
        >
          <option value="draft">Draft</option>
          <option value="published">Published</option>
          <option value="deprecated">Deprecated</option>
          <option value="archived">Archived</option>
        </select>
      </div>

      <div className="form-group">
        <label htmlFor="visibility">Visibility</label>
        <select
          id="visibility"
          value={versionData.visibility}
          onChange={(e) => handleInputChange('visibility', e.target.value)}
        >
          <option value="private">Private</option>
          <option value="public">Public</option>
          <option value="beta">Beta</option>
        </select>
      </div>

      <div className="form-group">
        <label htmlFor="release_notes">Release Notes *</label>
        <textarea
          id="release_notes"
          value={versionData.release_notes}
          onChange={(e) => handleInputChange('release_notes', e.target.value)}
          placeholder="Describe what's new in this version..."
          rows={4}
          maxLength={5000}
        />
        <small>{versionData.release_notes.length}/5000 characters</small>
      </div>
    </div>
  );

  const renderStep2 = () => (
    <div className="step-content">
      <h3>Technical Details</h3>

      <div className="form-group">
        <label htmlFor="claude_model">Claude Model *</label>
        <select
          id="claude_model"
          value={versionData.claude_model}
          onChange={(e) => handleInputChange('claude_model', e.target.value)}
        >
          {CLAUDE_MODELS.map(model => (
            <option key={model} value={model}>{model}</option>
          ))}
        </select>
      </div>

      <div className="form-group">
        <label htmlFor="graph_json">Graph JSON *</label>
        <textarea
          id="graph_json"
          value={graphJsonString}
          onChange={(e) => handleGraphJsonChange(e.target.value)}
          placeholder="Paste your graph JSON here"
          rows={12}
          className="code-textarea"
        />
        <small>Valid JSON representing your template's graph structure</small>
      </div>

      <div className="form-group">
        <label htmlFor="prompt_yaml">Prompt YAML (Optional)</label>
        <textarea
          id="prompt_yaml"
          value={versionData.prompt_yaml || ''}
          onChange={(e) => handleInputChange('prompt_yaml', e.target.value)}
          placeholder="Optional YAML configuration for prompts"
          rows={6}
          className="code-textarea"
        />
      </div>

      <div className="form-group">
        <label htmlFor="token_estimate">Token Per Run Estimate</label>
        <input
          id="token_estimate"
          type="number"
          value={versionData.token_per_run_estimate}
          onChange={(e) => handleInputChange('token_per_run_estimate', parseInt(e.target.value || '0'))}
          min="0"
          placeholder="Estimated tokens per execution"
        />
      </div>

      <div className="form-group">
        <label htmlFor="min_claude_version">Minimum Claude Version</label>
        <input
          id="min_claude_version"
          type="text"
          value={versionData.min_claude_version || ''}
          onChange={(e) => handleInputChange('min_claude_version', e.target.value)}
          placeholder="e.g., 3.0"
        />
      </div>

      <div className="form-group">
        <label htmlFor="max_claude_version">Maximum Claude Version</label>
        <input
          id="max_claude_version"
          type="text"
          value={versionData.max_claude_version || ''}
          onChange={(e) => handleInputChange('max_claude_version', e.target.value)}
          placeholder="e.g., 3.5"
        />
      </div>
    </div>
  );

  const renderStep3 = () => (
    <div className="step-content">
      <h3>Change Details</h3>

      <div className="form-group">
        <label>New Features</label>
        {versionData.new_features.map((feature, index) => (
          <div key={index} className="array-input">
            <input
              type="text"
              value={feature}
              onChange={(e) => handleArrayInputChange('new_features', index, e.target.value)}
              placeholder="Describe a new feature..."
            />
            <button type="button" onClick={() => removeArrayItem('new_features', index)}>
              Remove
            </button>
          </div>
        ))}
        <button type="button" onClick={() => addArrayItem('new_features')}>
          Add New Feature
        </button>
      </div>

      <div className="form-group">
        <label>Bug Fixes</label>
        {versionData.bug_fixes.map((fix, index) => (
          <div key={index} className="array-input">
            <input
              type="text"
              value={fix}
              onChange={(e) => handleArrayInputChange('bug_fixes', index, e.target.value)}
              placeholder="Describe a bug fix..."
            />
            <button type="button" onClick={() => removeArrayItem('bug_fixes', index)}>
              Remove
            </button>
          </div>
        ))}
        <button type="button" onClick={() => addArrayItem('bug_fixes')}>
          Add Bug Fix
        </button>
      </div>

      <div className="form-group">
        <label>Breaking Changes</label>
        {versionData.breaking_changes.map((change, index) => (
          <div key={index} className="array-input">
            <input
              type="text"
              value={change}
              onChange={(e) => handleArrayInputChange('breaking_changes', index, e.target.value)}
              placeholder="Describe a breaking change..."
            />
            <button type="button" onClick={() => removeArrayItem('breaking_changes', index)}>
              Remove
            </button>
          </div>
        ))}
        <button type="button" onClick={() => addArrayItem('breaking_changes')}>
          Add Breaking Change
        </button>
      </div>

      <div className="form-group">
        <label>Deprecated Features</label>
        {versionData.deprecated_features.map((feature, index) => (
          <div key={index} className="array-input">
            <input
              type="text"
              value={feature}
              onChange={(e) => handleArrayInputChange('deprecated_features', index, e.target.value)}
              placeholder="Describe a deprecated feature..."
            />
            <button type="button" onClick={() => removeArrayItem('deprecated_features', index)}>
              Remove
            </button>
          </div>
        ))}
        <button type="button" onClick={() => addArrayItem('deprecated_features')}>
          Add Deprecated Feature
        </button>
      </div>

      <div className="form-group">
        <label>Known Issues</label>
        {versionData.known_issues.map((issue, index) => (
          <div key={index} className="array-input">
            <input
              type="text"
              value={issue}
              onChange={(e) => handleArrayInputChange('known_issues', index, e.target.value)}
              placeholder="Describe a known issue..."
            />
            <button type="button" onClick={() => removeArrayItem('known_issues', index)}>
              Remove
            </button>
          </div>
        ))}
        <button type="button" onClick={() => addArrayItem('known_issues')}>
          Add Known Issue
        </button>
      </div>

      <div className="form-group">
        <label htmlFor="migration_guide">Migration Guide</label>
        <textarea
          id="migration_guide"
          value={versionData.migration_guide || ''}
          onChange={(e) => handleInputChange('migration_guide', e.target.value)}
          placeholder="Provide guidance for migrating from previous versions..."
          rows={4}
        />
      </div>
    </div>
  );

  const renderStep4 = () => (
    <div className="step-content">
      <h3>Review & Publish</h3>

      <div className="version-summary">
        <h4>Version Summary</h4>
        <div className="summary-grid">
          <div className="summary-item">
            <strong>Version:</strong> {versionData.version_number}
          </div>
          <div className="summary-item">
            <strong>Type:</strong> {versionData.compatibility_level}
          </div>
          <div className="summary-item">
            <strong>Status:</strong> {versionData.status}
          </div>
          <div className="summary-item">
            <strong>Visibility:</strong> {versionData.visibility}
          </div>
          <div className="summary-item">
            <strong>Claude Model:</strong> {versionData.claude_model}
          </div>
          <div className="summary-item">
            <strong>Token Estimate:</strong> {versionData.token_per_run_estimate.toLocaleString()}
          </div>
        </div>

        <div className="release-notes-summary">
          <strong>Release Notes:</strong>
          <p>{versionData.release_notes}</p>
        </div>

        <div className="changes-summary">
          {versionData.new_features.length > 0 && (
            <div className="change-group">
              <strong>✨ New Features ({versionData.new_features.length})</strong>
            </div>
          )}
          {versionData.bug_fixes.length > 0 && (
            <div className="change-group">
              <strong>🔧 Bug Fixes ({versionData.bug_fixes.length})</strong>
            </div>
          )}
          {versionData.breaking_changes.length > 0 && (
            <div className="change-group breaking">
              <strong>💥 Breaking Changes ({versionData.breaking_changes.length})</strong>
            </div>
          )}
          {versionData.deprecated_features.length > 0 && (
            <div className="change-group deprecated">
              <strong>⚠️ Deprecated Features ({versionData.deprecated_features.length})</strong>
            </div>
          )}
          {versionData.known_issues.length > 0 && (
            <div className="change-group issues">
              <strong>🐛 Known Issues ({versionData.known_issues.length})</strong>
            </div>
          )}
        </div>
      </div>

      {error && (
        <div className="error-message">
          {error}
        </div>
      )}
    </div>
  );

  if (isLoading && !versionData.version_number) {
    return (
      <div className="version-editor loading">
        <div className="loading-spinner">Loading...</div>
      </div>
    );
  }

  return (
    <div className="version-editor">
      <div className="editor-header">
        <h2>{versionId ? 'Edit Version' : 'Create New Version'}</h2>
        <div className="step-indicator">
          Step {currentStep} of {totalSteps}
        </div>
      </div>

      <div className="progress-bar">
        <div 
          className="progress-fill"
          style={{ width: `${(currentStep / totalSteps) * 100}%` }}
        />
      </div>

      <div className="form-container">
        {currentStep === 1 && renderStep1()}
        {currentStep === 2 && renderStep2()}
        {currentStep === 3 && renderStep3()}
        {currentStep === 4 && renderStep4()}
      </div>

      <div className="form-actions">
        {currentStep > 1 && (
          <button type="button" onClick={handlePrevious} className="btn-secondary">
            Previous
          </button>
        )}

        {currentStep < totalSteps ? (
          <button 
            type="button" 
            onClick={handleNext}
            className="btn-primary"
            disabled={!validateStep(currentStep)}
          >
            Next
          </button>
        ) : (
          <div className="final-actions">
            <button 
              type="button" 
              onClick={() => handleSave(false)}
              className="btn-outline"
              disabled={isLoading}
            >
              Save as Draft
            </button>
            <button 
              type="button" 
              onClick={() => handleSave(true)}
              className="btn-primary"
              disabled={isLoading}
            >
              {isLoading ? 'Publishing...' : 'Publish Version'}
            </button>
          </div>
        )}

        <button 
          type="button" 
          onClick={() => navigate(`/marketplace/templates/${templateId}/versions`)}
          className="btn-secondary"
        >
          Cancel
        </button>
      </div>
    </div>
  );
};

export default VersionEditor;

// Epic 16.2.2 Version History Component
import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import './VersionHistory.css';

interface EnhancedTemplateVersion {
  id: string;
  template_id: string;
  version_number: string;
  major_version: number;
  minor_version: number;
  patch_version: number;
  status: 'draft' | 'published' | 'deprecated' | 'archived';
  visibility: 'public' | 'private' | 'beta';
  claude_model: string;
  graph_json: Record<string, any>;
  prompt_yaml?: string;
  release_notes: string;
  compatibility_level: 'breaking' | 'major' | 'minor' | 'patch';
  migration_guide?: string;
  deprecated_features: string[];
  new_features: string[];
  breaking_changes: string[];
  bug_fixes: string[];
  known_issues: string[];
  min_claude_version?: string;
  max_claude_version?: string;
  required_features: string[];
  optional_features: string[];
  created_by: string;
  published_at?: string;
  deprecated_at?: string;
  download_count: number;
  created_at: string;
  updated_at: string;
}

interface VersionComparison {
  from_version: EnhancedTemplateVersion;
  to_version: EnhancedTemplateVersion;
  differences: any[];
  compatibility_impact: {
    is_breaking: boolean;
    affected_components: string[];
    required_updates: string[];
    optional_updates: string[];
    deprecation_warnings: string[];
    risk_level: 'low' | 'medium' | 'high';
  };
  migration_complexity: 'simple' | 'moderate' | 'complex';
  estimated_migration_time: number;
}

const STATUS_COLORS = {
  draft: '#6b7280',
  published: '#10b981',
  deprecated: '#f59e0b',
  archived: '#ef4444'
};

const COMPATIBILITY_COLORS = {
  breaking: '#ef4444',
  major: '#f59e0b',
  minor: '#10b981',
  patch: '#3b82f6'
};

export const VersionHistory: React.FC = () => {
  const { templateId } = useParams<{ templateId: string }>();
  const [versions, setVersions] = useState<EnhancedTemplateVersion[]>([]);
  const [selectedVersions, setSelectedVersions] = useState<string[]>([]);
  const [comparison, setComparison] = useState<VersionComparison | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [filter, setFilter] = useState({
    status: '',
    visibility: '',
    compatibility: ''
  });
  const [showComparison, setShowComparison] = useState(false);

  useEffect(() => {
    if (templateId) {
      fetchVersions();
    }
  }, [templateId, filter]);

  const fetchVersions = async () => {
    try {
      setIsLoading(true);
      const params = new URLSearchParams();
      if (filter.status) params.append('status', filter.status);
      if (filter.visibility) params.append('visibility', filter.visibility);
      params.append('include_private', 'true');

      const response = await fetch(`/api/marketplace/templates/${templateId}/versions?${params}`, {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });

      if (!response.ok) {
        throw new Error('Failed to fetch versions');
      }

      const data = await response.json();
      let filteredVersions = data;

      if (filter.compatibility) {
        filteredVersions = data.filter((v: EnhancedTemplateVersion) => 
          v.compatibility_level === filter.compatibility
        );
      }

      setVersions(filteredVersions);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to fetch versions');
    } finally {
      setIsLoading(false);
    }
  };

  const handleVersionSelect = (versionId: string) => {
    if (selectedVersions.includes(versionId)) {
      setSelectedVersions(selectedVersions.filter(id => id !== versionId));
    } else if (selectedVersions.length < 2) {
      setSelectedVersions([...selectedVersions, versionId]);
    } else {
      // Replace the first selection with the new one
      setSelectedVersions([selectedVersions[1], versionId]);
    }
  };

  const handleCompareVersions = async () => {
    if (selectedVersions.length !== 2) return;

    try {
      setIsLoading(true);
      const response = await fetch('/api/marketplace/versions/compare', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify({
          from_version_id: selectedVersions[0],
          to_version_id: selectedVersions[1],
          include_content_diff: true,
          include_metadata_diff: true
        })
      });

      if (!response.ok) {
        throw new Error('Failed to compare versions');
      }

      const comparisonData = await response.json();
      setComparison(comparisonData);
      setShowComparison(true);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to compare versions');
    } finally {
      setIsLoading(false);
    }
  };

  const handleDeployVersion = async (versionId: string) => {
    if (!confirm('Are you sure you want to deploy this version?')) return;

    try {
      const response = await fetch(`/api/marketplace/versions/${versionId}/deploy`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify({
          deployment_type: 'immediate',
          rollout_percentage: 100
        })
      });

      if (!response.ok) {
        throw new Error('Failed to deploy version');
      }

      alert('Version deployed successfully!');
      fetchVersions();
    } catch (err) {
      alert(`Deployment failed: ${err instanceof Error ? err.message : 'Unknown error'}`);
    }
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const getVersionTypeIcon = (compatibilityLevel: string) => {
    switch (compatibilityLevel) {
      case 'breaking': return '💥';
      case 'major': return '🚀';
      case 'minor': return '✨';
      case 'patch': return '🔧';
      default: return '📦';
    }
  };

  const getRiskIcon = (riskLevel: string) => {
    switch (riskLevel) {
      case 'high': return '🔴';
      case 'medium': return '🟡';
      case 'low': return '🟢';
      default: return '⚪';
    }
  };

  if (isLoading && !versions.length) {
    return (
      <div className="version-history loading">
        <div className="loading-spinner">Loading version history...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="version-history error">
        <div className="error-message">
          <h3>Error loading versions</h3>
          <p>{error}</p>
          <button onClick={fetchVersions}>Try Again</button>
        </div>
      </div>
    );
  }

  return (
    <div className="version-history">
      <div className="version-header">
        <h2>Version History</h2>
        <div className="version-actions">
          {selectedVersions.length === 2 && (
            <button 
              className="btn-primary"
              onClick={handleCompareVersions}
              disabled={isLoading}
            >
              Compare Selected
            </button>
          )}
        </div>
      </div>

      <div className="version-filters">
        <select
          value={filter.status}
          onChange={(e) => setFilter({ ...filter, status: e.target.value })}
        >
          <option value="">All Statuses</option>
          <option value="draft">Draft</option>
          <option value="published">Published</option>
          <option value="deprecated">Deprecated</option>
          <option value="archived">Archived</option>
        </select>

        <select
          value={filter.visibility}
          onChange={(e) => setFilter({ ...filter, visibility: e.target.value })}
        >
          <option value="">All Visibility</option>
          <option value="public">Public</option>
          <option value="private">Private</option>
          <option value="beta">Beta</option>
        </select>

        <select
          value={filter.compatibility}
          onChange={(e) => setFilter({ ...filter, compatibility: e.target.value })}
        >
          <option value="">All Types</option>
          <option value="breaking">Breaking Changes</option>
          <option value="major">Major Updates</option>
          <option value="minor">Minor Updates</option>
          <option value="patch">Patches</option>
        </select>
      </div>

      {selectedVersions.length > 0 && (
        <div className="selection-info">
          <p>
            {selectedVersions.length === 1 
              ? '1 version selected. Select another to compare.' 
              : `${selectedVersions.length} versions selected.`
            }
          </p>
          {selectedVersions.length > 0 && (
            <button 
              className="btn-secondary"
              onClick={() => setSelectedVersions([])}
            >
              Clear Selection
            </button>
          )}
        </div>
      )}

      <div className="version-timeline">
        {versions.map((version, index) => (
          <div 
            key={version.id} 
            className={`version-item ${selectedVersions.includes(version.id) ? 'selected' : ''}`}
            onClick={() => handleVersionSelect(version.id)}
          >
            <div className="version-indicator">
              <div 
                className="version-dot"
                style={{ backgroundColor: STATUS_COLORS[version.status] }}
              />
              {index < versions.length - 1 && <div className="version-line" />}
            </div>

            <div className="version-content">
              <div className="version-header-item">
                <div className="version-info">
                  <div className="version-number">
                    <span className="version-icon">
                      {getVersionTypeIcon(version.compatibility_level)}
                    </span>
                    <span className="number">v{version.version_number}</span>
                    <span 
                      className="compatibility-badge"
                      style={{ backgroundColor: COMPATIBILITY_COLORS[version.compatibility_level] }}
                    >
                      {version.compatibility_level}
                    </span>
                  </div>
                  <div className="version-meta">
                    <span 
                      className="status-badge"
                      style={{ backgroundColor: STATUS_COLORS[version.status] }}
                    >
                      {version.status}
                    </span>
                    <span className="visibility-badge">{version.visibility}</span>
                    <span className="date">{formatDate(version.created_at)}</span>
                  </div>
                </div>
                <div className="version-actions-item">
                  {version.status === 'published' && (
                    <button 
                      className="btn-outline"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleDeployVersion(version.id);
                      }}
                    >
                      Deploy
                    </button>
                  )}
                  <span className="download-count">
                    {version.download_count} downloads
                  </span>
                </div>
              </div>

              <div className="version-details">
                <div className="release-notes">
                  <h4>Release Notes</h4>
                  <p>{version.release_notes}</p>
                </div>

                {version.new_features.length > 0 && (
                  <div className="feature-list">
                    <h5>✨ New Features</h5>
                    <ul>
                      {version.new_features.map((feature, idx) => (
                        <li key={idx}>{feature}</li>
                      ))}
                    </ul>
                  </div>
                )}

                {version.bug_fixes.length > 0 && (
                  <div className="feature-list">
                    <h5>🔧 Bug Fixes</h5>
                    <ul>
                      {version.bug_fixes.map((fix, idx) => (
                        <li key={idx}>{fix}</li>
                      ))}
                    </ul>
                  </div>
                )}

                {version.breaking_changes.length > 0 && (
                  <div className="feature-list breaking">
                    <h5>💥 Breaking Changes</h5>
                    <ul>
                      {version.breaking_changes.map((change, idx) => (
                        <li key={idx}>{change}</li>
                      ))}
                    </ul>
                  </div>
                )}

                {version.deprecated_features.length > 0 && (
                  <div className="feature-list deprecated">
                    <h5>⚠️ Deprecated Features</h5>
                    <ul>
                      {version.deprecated_features.map((feature, idx) => (
                        <li key={idx}>{feature}</li>
                      ))}
                    </ul>
                  </div>
                )}

                {version.known_issues.length > 0 && (
                  <div className="feature-list issues">
                    <h5>🐛 Known Issues</h5>
                    <ul>
                      {version.known_issues.map((issue, idx) => (
                        <li key={idx}>{issue}</li>
                      ))}
                    </ul>
                  </div>
                )}

                <div className="version-specs">
                  <div className="spec-item">
                    <strong>Claude Model:</strong> {version.claude_model}
                  </div>
                  <div className="spec-item">
                    <strong>Token Estimate:</strong> {version.token_per_run_estimate.toLocaleString()}
                  </div>
                  {version.min_claude_version && (
                    <div className="spec-item">
                      <strong>Min Claude Version:</strong> {version.min_claude_version}
                    </div>
                  )}
                  {version.max_claude_version && (
                    <div className="spec-item">
                      <strong>Max Claude Version:</strong> {version.max_claude_version}
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>

      {showComparison && comparison && (
        <div className="comparison-modal">
          <div className="comparison-content">
            <div className="comparison-header">
              <h3>Version Comparison</h3>
              <button 
                className="close-btn"
                onClick={() => setShowComparison(false)}
              >
                ×
              </button>
            </div>

            <div className="comparison-summary">
              <div className="version-compare-info">
                <div className="compare-version">
                  <strong>From:</strong> v{comparison.from_version.version_number}
                  <span className="date">({formatDate(comparison.from_version.created_at)})</span>
                </div>
                <div className="compare-arrow">→</div>
                <div className="compare-version">
                  <strong>To:</strong> v{comparison.to_version.version_number}
                  <span className="date">({formatDate(comparison.to_version.created_at)})</span>
                </div>
              </div>

              <div className="compatibility-summary">
                <div className="risk-indicator">
                  {getRiskIcon(comparison.compatibility_impact.risk_level)}
                  <span>Risk Level: {comparison.compatibility_impact.risk_level}</span>
                </div>
                <div className="migration-info">
                  <span>Migration: {comparison.migration_complexity}</span>
                  <span>Est. Time: {comparison.estimated_migration_time} min</span>
                </div>
                {comparison.compatibility_impact.is_breaking && (
                  <div className="breaking-warning">
                    ⚠️ Breaking changes detected
                  </div>
                )}
              </div>
            </div>

            <div className="comparison-details">
              <div className="changes-section">
                <h4>Changes ({comparison.differences.length})</h4>
                <div className="changes-list">
                  {comparison.differences.slice(0, 10).map((diff, index) => (
                    <div key={index} className={`change-item ${diff.impact}`}>
                      <span className="change-type">{diff.type}</span>
                      <span className="change-path">{diff.path}</span>
                      <span className="change-description">{diff.description}</span>
                    </div>
                  ))}
                  {comparison.differences.length > 10 && (
                    <div className="more-changes">
                      +{comparison.differences.length - 10} more changes
                    </div>
                  )}
                </div>
              </div>

              {comparison.compatibility_impact.required_updates.length > 0 && (
                <div className="updates-section">
                  <h4>Required Updates</h4>
                  <ul>
                    {comparison.compatibility_impact.required_updates.map((update, index) => (
                      <li key={index}>{update}</li>
                    ))}
                  </ul>
                </div>
              )}

              {comparison.compatibility_impact.deprecation_warnings.length > 0 && (
                <div className="deprecation-section">
                  <h4>Deprecation Warnings</h4>
                  <ul>
                    {comparison.compatibility_impact.deprecation_warnings.map((warning, index) => (
                      <li key={index}>{warning}</li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default VersionHistory;

import React, { useState, useEffect } from 'react';
