        {viewMode === 'trends' && templateMetrics && (
          <div className="trends-content">
            {/* Growth Metrics */}
            <div className="growth-metrics">
              <div className="growth-card">
                <h4>Views Growth</h4>
                <div className="growth-value">
                  {templateMetrics.trends.growth_rates.views_growth > 0 ? '+' : ''}
                  {templateMetrics.trends.growth_rates.views_growth.toFixed(1)}%
                </div>
                <div className="growth-indicator">
                  {templateMetrics.trends.growth_rates.views_growth > 0 ? '📈' : '📉'}
                </div>
              </div>

              <div className="growth-card">
                <h4>Downloads Growth</h4>
                <div className="growth-value">
                  {templateMetrics.trends.growth_rates.downloads_growth > 0 ? '+' : ''}
                  {templateMetrics.trends.growth_rates.downloads_growth.toFixed(1)}%
                </div>
                <div className="growth-indicator">
                  {templateMetrics.trends.growth_rates.downloads_growth > 0 ? '📈' : '📉'}
                </div>
              </div>

              <div className="growth-card">
                <h4>Revenue Growth</h4>
                <div className="growth-value">
                  {templateMetrics.trends.growth_rates.revenue_growth > 0 ? '+' : ''}
                  {templateMetrics.trends.growth_rates.revenue_growth.toFixed(1)}%
                </div>
                <div className="growth-indicator">
                  {templateMetrics.trends.growth_rates.revenue_growth > 0 ? '📈' : '📉'}
                </div>
              </div>
            </div>

            {/* Detailed Trends Chart */}
            <div className="detailed-trends-chart">
              <div className="chart-header">
                <h3>Daily Performance Trends</h3>
                <MetricSelector
                  availableMetrics={['views', 'downloads', 'revenue']}
                  selectedMetrics={selectedMetrics}
                  onMetricToggle={handleMetricToggle}
                />
              </div>

              <div className="chart-container large">
                <TrendChart
                  data={templateMetrics.trends.daily_metrics}
                  selectedMetrics={selectedMetrics}
                  timeRange={timeRange}
                  showGridLines
                  showTooltips
                  height={400}
                />
              </div>
            </div>

            {/* Performance Analysis */}
            <div className="performance-analysis">
              <h3>Performance Analysis</h3>
              <div className="analysis-grid">
                <div className="analysis-card">
                  <h4>Best Performing Day</h4>
                  <div className="analysis-content">
                    {(() => {
                      const bestDay = templateMetrics.trends.daily_metrics.reduce(
                        (best, current) => current.views > best.views ? current : best,
                        templateMetrics.trends.daily_metrics[0] || { date: new Date(), views: 0 }
                      );
                      return (
                        <>
                          <div className="metric-date">
                            {bestDay.date.toLocaleDateString()}
                          </div>
                          <div className="metric-values">
                            {bestDay.views} views, {bestDay.downloads} downloads
                          </div>
                        </>
                      );
                    })()}
                  </div>
                </div>

                <div className="analysis-card">
                  <h4>Average Daily Performance</h4>
                  <div className="analysis-content">
                    <div className="metric-values">
                      {Math.round(
                        templateMetrics.trends.daily_metrics.reduce(
                          (sum, day) => sum + day.views, 0
                        ) / templateMetrics.trends.daily_metrics.length
                      )} avg views/day
                    </div>
                    <div className="metric-values">
                      {Math.round(
                        templateMetrics.trends.daily_metrics.reduce(
                          (sum, day) => sum + day.downloads, 0
                        ) / templateMetrics.trends.daily_metrics.length
                      )} avg downloads/day
                    </div>
                  </div>
                </div>

                <div className="analysis-card">
                  <h4>Total Period Performance</h4>
                  <div className="analysis-content">
                    <div className="metric-values">
                      {templateMetrics.trends.daily_metrics.reduce(
                        (sum, day) => sum + day.views, 0
                      )} total views
                    </div>
                    <div className="metric-values">
                      ${templateMetrics.trends.daily_metrics.reduce(
                        (sum, day) => sum + day.revenue, 0
                      ).toFixed(2)} total revenue
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import {
  CustomReport,
  AnalyticsQuery,
  MetricType,
  TimeRange,
  AggregationType,
  DashboardLayout,
} from '../../../types/analytics';
import { QueryBuilder } from './QueryBuilder';
import { VisualizationConfig } from './VisualizationConfig';
import { ScheduleConfig } from './ScheduleConfig';
import { ReportPreview } from './ReportPreview';
import { analyticsService } from '../../../services/analyticsService';
import './ReportBuilder.css';

interface ReportBuilderProps {
  creatorId: string;
  existingReport?: CustomReport;
  onSave?: (report: CustomReport) => void;
  onCancel?: () => void;
  className?: string;
}

export const ReportBuilder: React.FC<ReportBuilderProps> = ({
  creatorId,
  existingReport,
  onSave,
  onCancel,
  className = '',
}) => {
  const [step, setStep] = useState<'query' | 'visualization' | 'schedule' | 'preview'>('query');
  const [reportName, setReportName] = useState(existingReport?.name || '');
  const [reportDescription, setReportDescription] = useState(existingReport?.description || '');
  const [query, setQuery] = useState<AnalyticsQuery>(
    existingReport?.configuration.query || {
      metric_types: [MetricType.VIEWS],
      time_range: TimeRange.LAST_30D,
      aggregation: AggregationType.COUNT,
      limit: 100,
      offset: 0,
    }
  );
  const [visualization, setVisualization] = useState(
    existingReport?.configuration.visualization || {
      chart_type: 'line',
      layout: DashboardLayout.GRID,
      show_legend: true,
      show_grid: true,
      color_scheme: 'default',
    }
  );
  const [scheduling, setScheduling] = useState({
    is_scheduled: existingReport?.is_scheduled || false,
    schedule: existingReport?.schedule || {
      frequency: 'weekly' as const,
      time: '09:00',
      recipients: [],
    },
  });
  const [previewData, setPreviewData] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);

  // Validation states
  const [validationErrors, setValidationErrors] = useState<Record<string, string>>({});

  // Load preview data when query changes
  const loadPreviewData = async () => {
    try {
      setLoading(true);
      setError(null);

      const data = await analyticsService.queryAnalytics({
        ...query,
        creator_id: creatorId,
        limit: 10, // Limit preview data
      });

      setPreviewData(data);
    } catch (err) {
      console.error('Failed to load preview data:', err);
      setError(err instanceof Error ? err.message : 'Failed to load preview data');
    } finally {
      setLoading(false);
    }
  };

  // Load preview data when entering preview step
  useEffect(() => {
    if (step === 'preview') {
      loadPreviewData();
    }
  }, [step, query]);

  // Validate current step
  const validateStep = (): boolean => {
    const errors: Record<string, string> = {};

    switch (step) {
      case 'query':
        if (!reportName.trim()) {
          errors.reportName = 'Report name is required';
        }
        if (reportName.length > 255) {
          errors.reportName = 'Report name must be less than 255 characters';
        }
        if (reportDescription && reportDescription.length > 1000) {
          errors.reportDescription = 'Description must be less than 1000 characters';
        }
        if (query.metric_types.length === 0) {
          errors.metrics = 'At least one metric must be selected';
        }
        break;

      case 'visualization':
        // Visualization validation if needed
        break;

      case 'schedule':
        if (scheduling.is_scheduled) {
          if (!scheduling.schedule.frequency) {
            errors.frequency = 'Frequency is required for scheduled reports';
          }
          if (!scheduling.schedule.time) {
            errors.time = 'Time is required for scheduled reports';
          }
          if (scheduling.schedule.recipients.length === 0) {
            errors.recipients = 'At least one recipient is required for scheduled reports';
          }
        }
        break;
    }

    setValidationErrors(errors);
    return Object.keys(errors).length === 0;
  };

  // Handle step navigation
  const handleNext = () => {
    if (!validateStep()) return;

    const steps = ['query', 'visualization', 'schedule', 'preview'] as const;
    const currentIndex = steps.indexOf(step);
    if (currentIndex < steps.length - 1) {
      setStep(steps[currentIndex + 1]);
    }
  };

  const handlePrevious = () => {
    const steps = ['query', 'visualization', 'schedule', 'preview'] as const;
    const currentIndex = steps.indexOf(step);
    if (currentIndex > 0) {
      setStep(steps[currentIndex - 1]);
    }
  };

  // Handle save report
  const handleSave = async () => {
    if (!validateStep()) return;

    try {
      setSaving(true);
      setError(null);

      const reportData: Partial<CustomReport> = {
        name: reportName,
        description: reportDescription || undefined,
        configuration: {
          query: {
            ...query,
            creator_id: creatorId,
          },
          visualization,
          refresh_interval: visualization.chart_type === 'table' ? undefined : 300, // 5 minutes
        },
        is_scheduled: scheduling.is_scheduled,
        schedule: scheduling.is_scheduled ? scheduling.schedule : undefined,
      };

      let savedReport: CustomReport;

      if (existingReport) {
        savedReport = await analyticsService.updateCustomReport(existingReport.id, reportData);
      } else {
        savedReport = await analyticsService.createCustomReport(reportData);
      }

      onSave?.(savedReport);
    } catch (err) {
      console.error('Failed to save report:', err);
      setError(err instanceof Error ? err.message : 'Failed to save report');
    } finally {
      setSaving(false);
    }
  };

  // Get step title
  const getStepTitle = () => {
    switch (step) {
      case 'query': return 'Configure Data Query';
      case 'visualization': return 'Choose Visualization';
      case 'schedule': return 'Set Schedule';
      case 'preview': return 'Preview Report';
      default: return 'Build Report';
    }
  };

  return (
    <div className={`report-builder ${className}`}>
      <div className="report-builder-header">
        <div className="header-content">
          <h2>{existingReport ? 'Edit Report' : 'Create New Report'}</h2>
          <p>{getStepTitle()}</p>
        </div>

        <div className="header-actions">
          <button
            className="cancel-button"
            onClick={onCancel}
            disabled={saving}
          >
            Cancel
          </button>

          {step === 'preview' && (
            <button
              className="save-button"
              onClick={handleSave}
              disabled={saving}
            >
              {saving ? 'Saving...' : existingReport ? 'Update Report' : 'Save Report'}
            </button>
          )}
        </div>
      </div>

      {/* Progress Steps */}
      <div className="progress-steps">
        <div className={`step ${step === 'query' ? 'active' : ''} ${['visualization', 'schedule', 'preview'].includes(step) ? 'completed' : ''}`}>
          <div className="step-number">1</div>
          <div className="step-label">Query</div>
        </div>

        <div className="step-connector"></div>

        <div className={`step ${step === 'visualization' ? 'active' : ''} ${['schedule', 'preview'].includes(step) ? 'completed' : ''}`}>
          <div className="step-number">2</div>
          <div className="step-label">Visualization</div>
        </div>

        <div className="step-connector"></div>

        <div className={`step ${step === 'schedule' ? 'active' : ''} ${step === 'preview' ? 'completed' : ''}`}>
          <div className="step-number">3</div>
          <div className="step-label">Schedule</div>
        </div>

        <div className="step-connector"></div>

        <div className={`step ${step === 'preview' ? 'active' : ''}`}>
          <div className="step-number">4</div>
          <div className="step-label">Preview</div>
        </div>
      </div>

      {error && (
        <div className="error-message">
          <span className="error-icon">⚠️</span>
          {error}
        </div>
      )}

      <div className="report-builder-content">
        {step === 'query' && (
          <div className="step-content">
            {/* Basic Information */}
            <div className="basic-info-section">
              <h3>Report Information</h3>

              <div className="form-group">
                <label htmlFor="reportName">Report Name *</label>
                <input
                  id="reportName"
                  type="text"
                  value={reportName}
                  onChange={(e) => setReportName(e.target.value)}
                  placeholder="Enter report name"
                  className={validationErrors.reportName ? 'error' : ''}
                />
                {validationErrors.reportName && (
                  <div className="field-error">{validationErrors.reportName}</div>
                )}
              </div>

              <div className="form-group">
                <label htmlFor="reportDescription">Description</label>
                <textarea
                  id="reportDescription"
                  value={reportDescription}
                  onChange={(e) => setReportDescription(e.target.value)}
                  placeholder="Optional description for this report"
                  rows={3}
                  className={validationErrors.reportDescription ? 'error' : ''}
                />
                {validationErrors.reportDescription && (
                  <div className="field-error">{validationErrors.reportDescription}</div>
                )}
              </div>
            </div>

            {/* Query Builder */}
            <QueryBuilder
              query={query}
              onChange={setQuery}
              validationErrors={validationErrors}
            />
          </div>
        )}

        {step === 'visualization' && (
          <div className="step-content">
            <VisualizationConfig
              config={visualization}
              onChange={setVisualization}
              metrics={query.metric_types}
            />
          </div>
        )}

        {step === 'schedule' && (
          <div className="step-content">
            <ScheduleConfig
              config={scheduling}
              onChange={setScheduling}
              validationErrors={validationErrors}
            />
          </div>
        )}

        {step === 'preview' && (
          <div className="step-content">
            <ReportPreview
              reportName={reportName}
              reportDescription={reportDescription}
              query={query}
              visualization={visualization}
              scheduling={scheduling}
              previewData={previewData}
              loading={loading}
              onRefreshPreview={loadPreviewData}
            />
          </div>
        )}
      </div>

      {/* Navigation */}
      <div className="report-builder-footer">
        <div className="navigation-buttons">
          <button
            className="previous-button"
            onClick={handlePrevious}
            disabled={step === 'query' || saving}
          >
            Previous
          </button>

          {step !== 'preview' && (
            <button
              className="next-button"
              onClick={handleNext}
              disabled={saving}
            >
              Next
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { CustomReport } from '../../../types/analytics';
import { ReportBuilder } from './ReportBuilder';
import { ReportCard } from './ReportCard';
import { ExportManager } from './ExportManager';
import { analyticsService } from '../../../services/analyticsService';
import './ReportsManager.css';

interface ReportsManagerProps {
  creatorId: string;
  className?: string;
}

export const ReportsManager: React.FC<ReportsManagerProps> = ({
  creatorId,
  className = '',
}) => {
  const [reports, setReports] = useState<CustomReport[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedReport, setSelectedReport] = useState<CustomReport | null>(null);
  const [showBuilder, setShowBuilder] = useState(false);
  const [showExportManager, setShowExportManager] = useState(false);
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState<'name' | 'created_at' | 'updated_at'>('updated_at');
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc');

  // Load reports
  const loadReports = async () => {
    try {
      setLoading(true);
      setError(null);

      const reportsData = await analyticsService.getCustomReports(creatorId);
      setReports(reportsData);
    } catch (err) {
      console.error('Failed to load reports:', err);
      setError(err instanceof Error ? err.message : 'Failed to load reports');
    } finally {
      setLoading(false);
    }
  };

  // Load reports on mount
  useEffect(() => {
    loadReports();
  }, [creatorId]);

  // Handle report save
  const handleReportSave = (report: CustomReport) => {
    if (selectedReport) {
      // Update existing report
      setReports(prev => 
        prev.map(r => r.id === report.id ? report : r)
      );
    } else {
      // Add new report
      setReports(prev => [report, ...prev]);
    }

    setShowBuilder(false);
    setSelectedReport(null);
  };

  // Handle report delete
  const handleReportDelete = async (reportId: string) => {
    if (!confirm('Are you sure you want to delete this report?')) {
      return;
    }

    try {
      await analyticsService.deleteCustomReport(reportId);
      setReports(prev => prev.filter(r => r.id !== reportId));
    } catch (err) {
      console.error('Failed to delete report:', err);
      alert('Failed to delete report. Please try again.');
    }
  };

  // Handle report generation
  const handleGenerateReport = async (reportId: string) => {
    try {
      const reportData = await analyticsService.generateReport(reportId);

      // Create download link
      const blob = new Blob([JSON.stringify(reportData, null, 2)], {
        type: 'application/json',
      });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `report_${reportId}_${new Date().toISOString().split('T')[0]}.json`;
      link.click();
      URL.revokeObjectURL(url);
    } catch (err) {
      console.error('Failed to generate report:', err);
      alert('Failed to generate report. Please try again.');
    }
  };

  // Filter and sort reports
  const filteredAndSortedReports = reports
    .filter(report =>
      report.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      (report.description && report.description.toLowerCase().includes(searchQuery.toLowerCase()))
    )
    .sort((a, b) => {
      let aValue: any, bValue: any;

      switch (sortBy) {
        case 'name':
          aValue = a.name.toLowerCase();
          bValue = b.name.toLowerCase();
          break;
        case 'created_at':
          aValue = new Date(a.created_at).getTime();
          bValue = new Date(b.created_at).getTime();
          break;
        case 'updated_at':
          aValue = new Date(a.updated_at).getTime();
          bValue = new Date(b.updated_at).getTime();
          break;
        default:
          return 0;
      }

      if (sortOrder === 'asc') {
        return aValue < bValue ? -1 : aValue > bValue ? 1 : 0;
      } else {
        return aValue > bValue ? -1 : aValue < bValue ? 1 : 0;
      }
    });

  if (showBuilder) {
    return (
      <ReportBuilder
        creatorId={creatorId}
        existingReport={selectedReport || undefined}
        onSave={handleReportSave}
        onCancel={() => {
          setShowBuilder(false);
          setSelectedReport(null);
        }}
        className={className}
      />
    );
  }

  if (showExportManager) {
    return (
      <ExportManager
        creatorId={creatorId}
        onClose={() => setShowExportManager(false)}
        className={className}
      />
    );
  }

  return (
    <div className={`reports-manager ${className}`}>
      <div className="reports-header">
        <div className="header-content">
          <div className="title-section">
            <h2>Custom Reports</h2>
            <p>Create, manage, and export your analytics reports</p>
          </div>

          <div className="header-actions">
            <button
              className="export-button"
              onClick={() => setShowExportManager(true)}
            >
              <span className="button-icon">📊</span>
              Export Data
            </button>

            <button
              className="create-button"
              onClick={() => setShowBuilder(true)}
            >
              <span className="button-icon">➕</span>
              Create Report
            </button>
          </div>
        </div>

        {/* Controls */}
        <div className="reports-controls">
          <div className="search-section">
            <div className="search-input-container">
              <span className="search-icon">🔍</span>
              <input
                type="text"
                placeholder="Search reports..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="search-input"
              />
            </div>
          </div>

          <div className="filter-section">
            <select
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value as any)}
              className="sort-select"
            >
              <option value="updated_at">Sort by Updated</option>
              <option value="created_at">Sort by Created</option>
              <option value="name">Sort by Name</option>
            </select>

            <button
              className={`sort-order-button ${sortOrder}`}
              onClick={() => setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc')}
              title={`Sort ${sortOrder === 'asc' ? 'Descending' : 'Ascending'}`}
            >
              {sortOrder === 'asc' ? '↑' : '↓'}
            </button>

            <div className="view-mode-buttons">
              <button
                className={`view-mode-button ${viewMode === 'grid' ? 'active' : ''}`}
                onClick={() => setViewMode('grid')}
                title="Grid View"
              >
                ⊞
              </button>
              <button
                className={`view-mode-button ${viewMode === 'list' ? 'active' : ''}`}
                onClick={() => setViewMode('list')}
                title="List View"
              >
                ☰
              </button>
            </div>
          </div>
        </div>
      </div>

      <div className="reports-content">
        {loading ? (
          <div className="loading-state">
            <div className="loading-spinner"></div>
            <p>Loading reports...</p>
          </div>
        ) : error ? (
          <div className="error-state">
            <div className="error-icon">⚠️</div>
            <h3>Failed to Load Reports</h3>
            <p>{error}</p>
            <button className="retry-button" onClick={loadReports}>
              Try Again
            </button>
          </div>
        ) : filteredAndSortedReports.length === 0 ? (
          <div className="empty-state">
            {searchQuery ? (
              <>
                <div className="empty-icon">🔍</div>
                <h3>No Reports Found</h3>
                <p>No reports match your search criteria.</p>
                <button
                  className="clear-search-button"
                  onClick={() => setSearchQuery('')}
                >
                  Clear Search
                </button>
              </>
            ) : (
              <>
                <div className="empty-icon">📊</div>
                <h3>No Reports Yet</h3>
                <p>Create your first custom report to get started.</p>
                <button
                  className="create-first-button"
                  onClick={() => setShowBuilder(true)}
                >
                  Create Your First Report
                </button>
              </>
            )}
          </div>
        ) : (
          <div className={`reports-grid ${viewMode}`}>
            {filteredAndSortedReports.map(report => (
              <ReportCard
                key={report.id}
                report={report}
                viewMode={viewMode}
                onEdit={(report) => {
                  setSelectedReport(report);
                  setShowBuilder(true);
                }}
                onDelete={() => handleReportDelete(report.id)}
                onGenerate={() => handleGenerateReport(report.id)}
              />
            ))}
          </div>
        )}
      </div>

      {/* Reports Summary */}
      {!loading && !error && reports.length > 0 && (
        <div className="reports-summary">
          <div className="summary-stats">
            <div className="stat-item">
              <span className="stat-value">{reports.length}</span>
              <span className="stat-label">Total Reports</span>
            </div>

            <div className="stat-item">
              <span className="stat-value">
                {reports.filter(r => r.is_scheduled).length}
              </span>
              <span className="stat-label">Scheduled</span>
            </div>

            <div className="stat-item">
              <span className="stat-value">
                {filteredAndSortedReports.length}
              </span>
