import React from "react";
import { EditorFieldProps } from "./BaseNodeEditor";

export interface TextAreaEditorProps extends EditorFieldProps {
  rows?: number;
  maxLength?: number;
  minLength?: number;
  autoResize?: boolean;
  showWordCount?: boolean;
}

export const TextAreaEditor: React.FC<TextAreaEditorProps> = ({
  label,
  value,
  fieldKey,
  error,
  onChange,
  placeholder,
  disabled = false,
  rows = 4,
  maxLength,
  minLength,
  autoResize = false,
  showWordCount = false,
}) => {
  const [localValue, setLocalValue] = React.useState(String(value ?? ""));
  const [isFocused, setIsFocused] = React.useState(false);
  const textareaRef = React.useRef<HTMLTextAreaElement>(null);

  // Update local value when external value changes
  React.useEffect(() => {
    setLocalValue(String(value ?? ""));
  }, [value]);

  // Auto-resize functionality
  React.useEffect(() => {
    if (autoResize && textareaRef.current) {
      const textarea = textareaRef.current;
      textarea.style.height = 'auto';
      textarea.style.height = `${textarea.scrollHeight}px`;
    }
  }, [localValue, autoResize]);

  const handleChange = (newValue: string) => {
    setLocalValue(newValue);
    onChange(newValue);
  };

  const getWordCount = (text: string): number => {
    return text.trim().split(/\s+/).filter(word => word.length > 0).length;
  };

  const inputId = `field-${fieldKey}`;

  const textareaStyle = {
    width: "100%",
    padding: 8,
    border: error 
      ? "1px solid #f56565" 
      : isFocused 
        ? "1px solid #4299e1" 
        : "1px solid #4a5568",
    borderRadius: 4,
    background: "#2d3748",
    color: "#e2e8f0",
    fontSize: 13,
    fontFamily: "system-ui, -apple-system, sans-serif",
    outline: "none",
    transition: "border-color 0.2s ease",
    resize: autoResize ? 'none' as const : 'vertical' as const,
    minHeight: autoResize ? `${rows * 1.5}em` : undefined,
  };

  const labelStyle = {
    display: "block",
    fontWeight: 500,
    marginBottom: 4,
    color: "#e2e8f0",
    fontSize: 12,
    letterSpacing: "0.025em",
  };

  const wordCount = getWordCount(localValue);
  const charCount = localValue.length;

  return (
    <div style={{ marginBottom: 16 }}>
      <label htmlFor={inputId} style={labelStyle}>
        {label}
        {error && (
          <span style={{ color: "#f56565", marginLeft: 4, fontSize: 10 }}>
            *
          </span>
        )}
      </label>

      <textarea
        ref={textareaRef}
        id={inputId}
        value={localValue}
        onChange={(e) => handleChange(e.target.value)}
        onFocus={() => setIsFocused(true)}
        onBlur={() => setIsFocused(false)}
        placeholder={placeholder || `Enter ${label.toLowerCase()}...`}
        disabled={disabled}
        rows={autoResize ? undefined : rows}
        maxLength={maxLength}
        minLength={minLength}
        style={textareaStyle}
      />

      {error && (
        <div style={{ 
          color: "#f56565", 
          fontSize: 11, 
          marginTop: 4,
          fontWeight: 400,
        }}>
          {error}
        </div>
      )}

      <div style={{
        display: "flex",
        justifyContent: "space-between",
        marginTop: 2,
        fontSize: 10,
        color: "#a0aec0",
      }}>
        {showWordCount && (
          <span>
            {wordCount} word{wordCount !== 1 ? 's' : ''}
          </span>
        )}

        {maxLength && (
          <span style={{ marginLeft: 'auto' }}>
            {charCount} / {maxLength}
          </span>
        )}
      </div>
    </div>
  );
};

