            title="Quick entry (comma-separated)"
          >
            {quickEntryMode ? "List" : "Quick"}
          </button>
        )}
      </div>

      {quickEntryMode ? (
        <div style={{ marginBottom: 12 }}>
          <textarea
            value={quickEntryText}
            onChange={(e) => setQuickEntryText(e.target.value)}
            placeholder="Enter variations separated by commas..."
            style={{
              width: "100%",
              height: 80,
              padding: "8px 12px",
              border: "1px solid #d1d5db",
              borderRadius: 6,
              fontSize: 14,
              resize: "vertical",
              fontFamily: "inherit",
            }}
          />
          <div style={{ 
            display: "flex", 
            gap: 8, 
            marginTop: 8 
          }}>
            <button
              onClick={handleQuickEntry}
              disabled={!quickEntryText.trim()}
              style={{
                background: quickEntryText.trim() ? "#3b82f6" : "#9ca3af",
                color: "#fff",
                border: "none",
                borderRadius: 4,
                padding: "6px 12px",
                fontSize: 12,
                cursor: quickEntryText.trim() ? "pointer" : "not-allowed",
              }}
            >
              Add All
            </button>
            <button
              onClick={() => {
                setQuickEntryMode(false);
                setQuickEntryText("");
              }}
              style={{
                background: "#f3f4f6",
                border: "1px solid #d1d5db",
                borderRadius: 4,
                padding: "6px 12px",
                fontSize: 12,
                cursor: "pointer",
              }}
            >
              Cancel
            </button>
          </div>
        </div>
      ) : (
        <>
          <div style={{ 
            display: "flex", 
            gap: 8, 
            marginBottom: 12 
          }}>
            <input
              ref={inputRef}
              type="text"
              value={newVariation}
              onChange={(e) => setNewVariation(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') {
                  e.preventDefault();
                  handleAdd();
                }
              }}
              placeholder={placeholder}
              disabled={variations.length >= maxVariations}
              style={{
                flex: 1,
                padding: "8px 12px",
                border: "1px solid #d1d5db",
                borderRadius: 6,
                fontSize: 14,
                outline: "none",
              }}
            />
            <button
              onClick={handleAdd}
              disabled={!newVariation.trim() || variations.length >= maxVariations}
              style={{
                background: newVariation.trim() && variations.length < maxVariations ? "#3b82f6" : "#9ca3af",
                color: "#fff",
                border: "none",
                borderRadius: 6,
                padding: "8px 16px",
                fontSize: 14,
                cursor: newVariation.trim() && variations.length < maxVariations ? "pointer" : "not-allowed",
              }}
            >
              Add
            </button>
          </div>
        </>
      )}

      <div style={{ 
        maxHeight: 200, 
        overflowY: "auto",
        border: "1px solid #e5e7eb",
        borderRadius: 6,
        background: "#fff",
      }}>
        {variations.length === 0 ? (
          <div style={{
            padding: 20,
            textAlign: "center",
            color: "#9ca3af",
            fontStyle: "italic",
            fontSize: 13,
          }}>
            No variations yet. Add some above.
          </div>
        ) : (
          variations.map((variation, index) => (
            <div
              key={index}
              draggable
              onDragStart={(e) => handleDragStart(e, index)}
              onDragOver={(e) => handleDragOver(e, index)}
              onDrop={(e) => handleDrop(e, index)}
              style={{
                display: "flex",
                alignItems: "center",
                padding: "8px 12px",
                borderBottom: index < variations.length - 1 ? "1px solid #f3f4f6" : "none",
                background: dragOverIndex === index ? "#f0f9ff" : "transparent",
                opacity: draggedIndex === index ? 0.5 : 1,
                cursor: "move",
              }}
            >
              <div
                style={{
                  width: 16,
                  height: 16,
                  marginRight: 8,
                  color: "#9ca3af",
                  cursor: "move",
                  fontSize: 12,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                ⋮⋮
              </div>
              {editingIndex === index ? (
                <input
                  ref={editInputRef}
                  type="text"
                  value={editingValue}
                  onChange={(e) => setEditingValue(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter') {
                      e.preventDefault();
                      commitEdit();
                    } else if (e.key === 'Escape') {
                      cancelEdit();
                    }
                  }}
                  onBlur={commitEdit}
                  style={{
                    flex: 1,
                    padding: "4px 8px",
                    border: "1px solid #3b82f6",
                    borderRadius: 4,
                    fontSize: 14,
                    outline: "none",
                  }}
                />
              ) : (
                <span
                  onClick={() => startEdit(index)}
                  style={{
                    flex: 1,
                    cursor: "pointer",
                    fontSize: 14,
                    color: "#374151",
                  }}
                  title="Click to edit"
                >
                  {variation}
                </span>
              )}
              <button
                onClick={() => handleRemove(index)}
                style={{
                  background: "none",
                  border: "none",
                  color: "#ef4444",
                  cursor: "pointer",
                  fontSize: 14,
                  marginLeft: 8,
                  padding: 4,
                }}
                title="Remove variation"
              >
                ×
              </button>
            </div>
          ))
        )}
      </div>

      {variations.length >= maxVariations && (
        <div style={{
          marginTop: 8,
          fontSize: 12,
          color: "#ef4444",
          textAlign: "center",
        }}>
          Maximum {maxVariations} variations reached
        </div>
      )}
    </div>
  );
};

