            }}>
              <div style={{ color: "#a0aec0", fontSize: 10, marginBottom: 4 }}>
                Available adverbs:
              </div>
              <div style={{ fontSize: 11 }}>
                {adverbVariations.slice(0, 5).join(", ")}
                {adverbVariations.length > 5 && ` ... +${adverbVariations.length - 5} more`}
              </div>
            </div>
          )}
        </div>
      </CollapsibleSection>
    </div>
  );
};

