            cursor: 'crosshair',
            zIndex: 10,
          }}
          isConnectable={true}
        />

        {/* Output Handle - React Flow connection point */}
        <Handle
          type="source"
          position={Position.Right}
          id="source"
          style={{
            width: 12,
