            cursor: 'crosshair',
            zIndex: 10,
          }}
          isConnectable={true}
        />
      </div>
    );
  } catch (error) {
    console.error('NodeRenderer error:', error, 'Props:', { id, data });
    // Fallback render for error cases
    return (
