  edges,
  intervalMs = 5000,
  storageKey = 'graphDraft',
}: UseAutosaveProps): UseAutosaveReturn => {
  const [showRestorePrompt, setShowRestorePrompt] = useState(false);
  const [restoreDraft, setRestoreDraft] = useState<{ nodes: Node[]; edges: Edge[] } | null>(null);

  // Check for existing draft on mount
  useEffect(() => {
    try {
      const saved = localStorage.getItem(storageKey);
      if (saved) {
        const draft = JSON.parse(saved);
        if (draft && draft.nodes && draft.edges) {
          setRestoreDraft(draft);
          setShowRestorePrompt(true);
        }
      }
    } catch (error) {
      console.warn('Failed to parse saved draft:', error);
      localStorage.removeItem(storageKey);
    }
  }, [storageKey]);

  // Autosave graph every intervalMs
  useEffect(() => {
    const save = () => {
      try {
        const draft = JSON.stringify({ nodes, edges });
        localStorage.setItem(storageKey, draft);
      } catch (error) {
        console.warn('Failed to save draft:', error);
      }
    };

    const interval = setInterval(save, intervalMs);
    return () => clearInterval(interval);
  }, [nodes, edges, intervalMs, storageKey]);

  // Clear localStorage on mount to prevent infinite loops (emergency fix)
  useEffect(() => {
    console.log('Clearing localStorage to prevent infinite loops');
    localStorage.removeItem(storageKey);
    localStorage.clear();
  }, [storageKey]);

  return {
    showRestorePrompt,
    restoreDraft,
    setShowRestorePrompt,
    setRestoreDraft,
  };
};

import { useMemo } from "react";
import { NodeMeta } from "../Palette";

interface UseNodeUtilsProps {
  nodeTypes: NodeMeta[];
}

interface UseNodeUtilsReturn {
  getNodeMeta: (nodeType: string) => NodeMeta;
  getCategoryColor: (category: string) => string;
}

export const useNodeUtils = ({ nodeTypes }: UseNodeUtilsProps): UseNodeUtilsReturn => {
  const getNodeMeta = useMemo(() => {
    return (nodeType: string): NodeMeta => {
      // Handle undefined/null/invalid types
      if (!nodeType || typeof nodeType !== 'string') {
        return { 
          id: 'default', 
          label: 'Unknown', 
          icon: "🔧", 
          category: "unknown",
          tooltip: "Unknown node type"
        };
      }

      return nodeTypes.find(n => n.id === nodeType) || { 
        id: nodeType, 
        label: nodeType.charAt(0).toUpperCase() + nodeType.slice(1), 
        icon: "🔧", 
        category: "unknown",
        tooltip: `${nodeType} node`
      };
    };
  }, [nodeTypes]);

  const getCategoryColor = useMemo(() => {
    return (category: string): string => {
      switch (category) {
        case 'text': return '#4f46e5'; // Indigo
        case 'logic': return '#059669'; // Emerald  
        case 'output': return '#dc2626'; // Red
        case 'variable': return '#7c3aed'; // Violet
        default: return '#6b7280'; // Gray
      }
    };
  }, []);

  return {
    getNodeMeta,
    getCategoryColor,
  };
};

import { useState, useCallback, useEffect } from "react";
import { Edge, Node } from "reactflow";
import { ValidationError, validateConnection } from "../validation";

interface UseValidationReturn {
  errors: ValidationError[];
  styledEdges: Edge[];
  styledNodes: Node[];
  runValidation: (edges: Edge[], nodes: Node[]) => void;
}

interface UseValidationProps {
  edges: Edge[];
  nodes: Node[];
  highlightNodeIds?: Set<string>;
  highlightEdgeIds?: Set<string>;
  validateConnection?: (edges: Edge[], nodes: Node[]) => ValidationError[];
}

export const useValidation = ({
  edges,
  nodes,
  highlightNodeIds = new Set(),
  highlightEdgeIds = new Set(),
  validateConnection: customValidateConnection = validateConnection,
}: UseValidationProps): UseValidationReturn => {
  const [errors, setErrors] = useState<ValidationError[]>([]);

  const runValidation = useCallback(
    (edgesToValidate: Edge[], nodesToValidate: Node[]) => {
      const errs = customValidateConnection(edgesToValidate, nodesToValidate);
      setErrors(errs);
    },
    [customValidateConnection]
  );

  // Apply highlight styles to nodes
  const styledNodes = nodes.map((n) => {
    const highlight = highlightNodeIds.has(n.id)
      ? { border: '2px solid #ffd700' }
      : {};
    return { ...n, style: { ...n.style, ...highlight } };
  });

  // Apply error and highlight styles to edges
  const styledEdges = edges.map((e) => {
    const base = errors.find((err) => err.edgeId === e.id)
      ? { stroke: 'red', strokeWidth: 2 }
      : {};
    const highlight = highlightEdgeIds.has(e.id)
      ? { stroke: '#ffd700', strokeWidth: 3 }
      : {};
    return { ...e, style: { ...e.style, ...base, ...highlight } };
  });

  // Recompute validation errors when edges or nodes change
  useEffect(() => {
    runValidation(edges, nodes);
  }, [edges, nodes, runValidation]);

  return {
    errors,
    styledEdges,
    styledNodes,
    runValidation,
  };
};

