        { weight: 0.5, value: 'A' },
        { weight: 0.5, value: 'B' }
      ]);

      const firstResult = node.run(numericSeedCtx);

      // Run again with same seed
      const numericSeedCtx2: ExecutionContext = {
        variables: {},
        seed: 42
      };
