import { useState, useCallback, useRef } from "react";
export const usePreviewSeeds = () => {
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);
    const [results, setResults] = useState([]);
    const [aggregateError, setAggregateError] = useState(null);
    const abortRef = useRef(null);
    const runPreview = useCallback(async (graph) => {
        // Cancel any existing run
        abortRef.current?.abort();
        const controller = new AbortController();
        abortRef.current = controller;
        setLoading(true);
        setError(null);
        setAggregateError(null);
        try {
            // TODO: replace with real executor call; honor controller.signal
            const seeds = Array.from({ length: 5 }, () => Math.floor(Math.random() * 100000));
            const settled = await Promise.allSettled(seeds.map((seed, i) => new Promise((resolve, reject) => {
                // Simulate async executor — 20% chance to fail
                const delay = 200 + Math.random() * 400;
                const id = setTimeout(() => {
                    if (Math.random() < 0.2) {
                        reject(new Error(`Executor failed on seed ${seed}`));
                    }
                    else {
                        resolve({ seed, output: `Mock output #${i + 1}` });
                    }
                }, delay);
                controller.signal.addEventListener("abort", () => {
                    clearTimeout(id);
                    reject(new DOMException("aborted", "AbortError"));
                });
            })));
            if (controller.signal.aborted) {
                return; // Skip state updates if cancelled
            }
            const perSeedResults = settled.map((r, idx) => r.status === "fulfilled"
                ? { seed: seeds[idx], output: r.value.output, usedNodeIds: [`node${idx}`], usedEdgeIds: [`edge${idx}`] }
                : { seed: seeds[idx], error: r.reason.message });
            setResults(perSeedResults);
            const failed = perSeedResults.filter((r) => r.error).length;
            if (failed > 0) {
                setAggregateError(`${failed} of ${perSeedResults.length} previews failed`);
            }
        }
        catch (err) {
            if (err?.name !== "AbortError") {
                setError(err?.message ?? "Unknown error");
            }
        }
        finally {
            setLoading(false);
        }
    }, []);
    const cancelPreview = useCallback(() => {
        abortRef.current?.abort();
        setLoading(false);
        setResults([]);
    }, []);
    return { loading, error, results, runPreview, cancelPreview };
};

import { useState, useCallback, useRef } from "react";

interface PreviewResult {
  seed: number;
  output?: string;
  error?: string;
  usedNodeIds?: string[];
  usedEdgeIds?: string[];
}

export const usePreviewSeeds = () => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [results, setResults] = useState<PreviewResult[]>([]);
  const [aggregateError, setAggregateError] = useState<string | null>(null);

  const abortRef = useRef<AbortController | null>(null);

  const runPreview = useCallback(async (graph: unknown) => {
    // Cancel any existing run
    abortRef.current?.abort();
    const controller = new AbortController();
    abortRef.current = controller;
    setLoading(true);
    setError(null);
    setAggregateError(null);
    try {
      // TODO: replace with real executor call; honor controller.signal
      const seeds = Array.from({ length: 5 }, () => Math.floor(Math.random() * 100000));
      const settled = await Promise.allSettled(
        seeds.map((seed, i) =>
          new Promise<{ seed: number; output: string }>((resolve, reject) => {
            // Simulate async executor — 20% chance to fail
            const delay = 200 + Math.random() * 400;
            const id = setTimeout(() => {
              if (Math.random() < 0.2) {
                reject(new Error(`Executor failed on seed ${seed}`));
              } else {
                resolve({ seed, output: `Mock output #${i + 1}` });
              }
            }, delay);
            controller.signal.addEventListener("abort", () => {
              clearTimeout(id);
              reject(new DOMException("aborted", "AbortError"));
            });
          })
        )
      );
      if (controller.signal.aborted) {
        return; // Skip state updates if cancelled
      }

      const perSeedResults: PreviewResult[] = settled.map((r, idx) =>
        r.status === "fulfilled"
          ? { seed: seeds[idx], output: r.value.output, usedNodeIds: [`node${idx}`], usedEdgeIds: [`edge${idx}`] }
          : { seed: seeds[idx], error: (r.reason as Error).message }
      );
      setResults(perSeedResults);
      const failed = perSeedResults.filter((r) => r.error).length;
      if (failed > 0) {
        setAggregateError(`${failed} of ${perSeedResults.length} previews failed`);
      }
    } catch (err: any) {
      if (err?.name !== "AbortError") {
        setError(err?.message ?? "Unknown error");
      }
    } finally {
      setLoading(false);
    }
  }, []);

  const cancelPreview = useCallback(() => {
    abortRef.current?.abort();
    setLoading(false);
    setResults([]);
  }, []);

  return { loading, error, results, runPreview, cancelPreview };
};

import { createNodeData } from "../types/NodeTypes";
// Legacy function - delegates to new factory system
export const createDefaultNodeData = (type) => {
    const id = `${type}-${Date.now()}`;
    return createNodeData(type, id);
};
// Variation management utilities
export const addVariationToNode = (nodeData, variation) => {
    const currentVariations = nodeData.variations || [];
    return {
        ...nodeData,
        variations: [...currentVariations, variation],
    };
};
export const removeVariationFromNode = (nodeData, index) => {
    const currentVariations = nodeData.variations || [];
    return {
        ...nodeData,
        variations: currentVariations.filter((_, i) => i !== index),
    };
};
export const updateVariationInNode = (nodeData, index, newValue) => {
    const currentVariations = nodeData.variations || [];
    const updatedVariations = [...currentVariations];
    updatedVariations[index] = newValue;
    return {
        ...nodeData,
        variations: updatedVariations,
    };
};
export const reorderVariationsInNode = (nodeData, fromIndex, toIndex) => {
    const currentVariations = nodeData.variations || [];
    const updatedVariations = [...currentVariations];
    const [movedItem] = updatedVariations.splice(fromIndex, 1);
    updatedVariations.splice(toIndex, 0, movedItem);
    return {
        ...nodeData,
        variations: updatedVariations,
    };
};
