// Epic 11 Login Analytics Hook
// React hook for tracking login metrics and user behavior

import { useState, useCallback, useRef } from 'react';

// Analytics event types
interface LoginAttemptEvent {
  email: string;
  success: boolean;
  duration: number;
  failureReason?: string;
  attemptNumber?: number;
  rememberMe?: boolean;
}

interface FormInteractionEvent {
  action: string;
  field?: string;
  value?: any;
  timestamp?: Date;
}

interface LoginAnalytics {
  totalAttempts: number;
  successfulLogins: number;
  failedAttempts: number;
  successRate: number;
  topFailureReasons: Array<{
    reason: string;
    count: number;
    percentage: number;
  }>;
  suspiciousActivity: Array<{
    type: string;
    description: string;
    count: number;
    severity: 'low' | 'medium' | 'high';
  }>;
  deviceAnalysis: {
    newDevices: number;
    returningDevices: number;
    suspiciousDevices: number;
  };
}

export const useLoginAnalytics = () => {
  const [isTracking, setIsTracking] = useState(true);
  const [analytics, setAnalytics] = useState<LoginAnalytics | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  // Track form interactions in memory before sending
  const formInteractions = useRef<FormInteractionEvent[]>([]);
  const sessionStartTime = useRef<Date>(new Date());

  // Enable/disable tracking
  const setTrackingEnabled = useCallback((enabled: boolean) => {
    setIsTracking(enabled);
  }, []);

  // Track form interactions (focus, blur, change events)
  const trackFormInteraction = useCallback((action: string, field?: string, value?: any) => {
    if (!isTracking) return;

    const event: FormInteractionEvent = {
      action,
      field,
      value: typeof value === 'string' ? value.substring(0, 50) : value, // Limit value length
      timestamp: new Date(),
    };

    formInteractions.current.push(event);

    // Send interactions in batches to avoid overwhelming the server
    if (formInteractions.current.length >= 10) {
      sendFormInteractions();
    }
  }, [isTracking]);

  // Track login attempts with detailed metrics
  const trackLoginAttempt = useCallback(async (event: LoginAttemptEvent) => {
    if (!isTracking) return;

    try {
      // Prepare analytics payload
      const payload = {
        ...event,
        sessionDuration: new Date().getTime() - sessionStartTime.current.getTime(),
        userAgent: navigator.userAgent,
        language: navigator.language,
        timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
        screenResolution: `${screen.width}x${screen.height}`,
        timestamp: new Date().toISOString(),
        // Include recent form interactions
        formInteractions: formInteractions.current.slice(-20), // Last 20 interactions
      };

      // Send to analytics endpoint
      await fetch('/api/auth/analytics/login-attempt', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        credentials: 'include',
        body: JSON.stringify(payload),
      });

      // Clear form interactions after successful login
      if (event.success) {
        formInteractions.current = [];
      }
    } catch (error) {
      console.error('Failed to track login attempt:', error);
    }
  }, [isTracking]);

  // Send batched form interactions
  const sendFormInteractions = useCallback(async () => {
    if (!isTracking || formInteractions.current.length === 0) return;

    try {
      const payload = {
        interactions: formInteractions.current,
        sessionId: generateSessionId(),
        timestamp: new Date().toISOString(),
      };

      await fetch('/api/auth/analytics/form-interactions', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        credentials: 'include',
        body: JSON.stringify(payload),
      });

      // Clear sent interactions
      formInteractions.current = [];
    } catch (error) {
      console.error('Failed to send form interactions:', error);
    }
  }, [isTracking]);

  // Track security events (unusual behavior, suspicious patterns)
  const trackSecurityEvent = useCallback(async (eventType: string, details: any) => {
    if (!isTracking) return;

    try {
      const payload = {
        type: eventType,
        details,
        userAgent: navigator.userAgent,
        timestamp: new Date().toISOString(),
        sessionId: generateSessionId(),
      };

      await fetch('/api/auth/analytics/security-event', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        credentials: 'include',
        body: JSON.stringify(payload),
      });
    } catch (error) {
      console.error('Failed to track security event:', error);
    }
  }, [isTracking]);

  // Fetch login analytics data
  const fetchAnalytics = useCallback(async (timeframe: 'day' | 'week' | 'month' = 'week') => {
    setIsLoading(true);
    try {
      const response = await fetch(`/api/auth/analytics?timeframe=${timeframe}`, {
        method: 'GET',
        credentials: 'include',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        throw new Error('Failed to fetch analytics');
      }

      const data = await response.json();
      setAnalytics(data);
      return data;
    } catch (error) {
      console.error('Failed to fetch analytics:', error);
      throw error;
    } finally {
      setIsLoading(false);
    }
  }, []);

  // Track page performance metrics
  const trackPageMetrics = useCallback(async () => {
    if (!isTracking) return;

    try {
      // Use Performance API if available
      if ('performance' in window && 'getEntriesByType' in performance) {
        const navigation = performance.getEntriesByType('navigation')[0] as PerformanceNavigationTiming;
        const paint = performance.getEntriesByType('paint');

        const metrics = {
          pageLoadTime: navigation.loadEventEnd - navigation.fetchStart,
          domContentLoaded: navigation.domContentLoadedEventEnd - navigation.fetchStart,
          firstPaint: paint.find(p => p.name === 'first-paint')?.startTime || 0,
          firstContentfulPaint: paint.find(p => p.name === 'first-contentful-paint')?.startTime || 0,
          connectionType: (navigator as any).connection?.effectiveType || 'unknown',
          userAgent: navigator.userAgent,
          timestamp: new Date().toISOString(),
        };

        await fetch('/api/auth/analytics/page-metrics', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          credentials: 'include',
          body: JSON.stringify(metrics),
        });
      }
    } catch (error) {
      console.error('Failed to track page metrics:', error);
    }
  }, [isTracking]);

  // Track user engagement metrics
  const trackEngagement = useCallback(async (engagementType: string, data?: any) => {
    if (!isTracking) return;

    try {
      const payload = {
        type: engagementType,
        data,
        timestamp: new Date().toISOString(),
        sessionDuration: new Date().getTime() - sessionStartTime.current.getTime(),
        pageUrl: window.location.href,
      };

      await fetch('/api/auth/analytics/engagement', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        credentials: 'include',
        body: JSON.stringify(payload),
      });
    } catch (error) {
      console.error('Failed to track engagement:', error);
    }
  }, [isTracking]);

  // Generate a session ID for tracking
  const generateSessionId = (): string => {
    // Use existing session ID if available, otherwise generate new one
    let sessionId = sessionStorage.getItem('analytics_session_id');
    if (!sessionId) {
      sessionId = `session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
      sessionStorage.setItem('analytics_session_id', sessionId);
    }
    return sessionId;
  };

  // Detect and track suspicious behavior patterns
  const detectSuspiciousBehavior = useCallback(async () => {
    if (!isTracking) return;

    try {
      const interactions = formInteractions.current;
      const recentInteractions = interactions.slice(-10);

      // Detect rapid typing (possible bot)
      const typingIntervals = recentInteractions
        .filter(i => i.action.includes('changed'))
        .map((interaction, index, arr) => {
          if (index === 0) return null;
          return interaction.timestamp!.getTime() - arr[index - 1].timestamp!.getTime();
        })
        .filter(interval => interval !== null) as number[];

      if (typingIntervals.length > 5) {
        const avgInterval = typingIntervals.reduce((a, b) => a + b, 0) / typingIntervals.length;
        if (avgInterval < 50) { // Less than 50ms between keystrokes
          await trackSecurityEvent('rapid_typing_detected', {
            averageInterval: avgInterval,
            intervalCount: typingIntervals.length,
          });
        }
      }

      // Detect copy-paste behavior
      const pasteEvents = recentInteractions.filter(i => i.action.includes('paste'));
      if (pasteEvents.length > 0) {
        await trackSecurityEvent('paste_detected', {
          pasteCount: pasteEvents.length,
          fields: pasteEvents.map(e => e.field),
        });
      }

      // Detect form abandonment patterns
      const formFocusEvents = interactions.filter(i => i.action.includes('focus'));
      const formSubmitEvents = interactions.filter(i => i.action.includes('submit'));

      if (formFocusEvents.length > 3 && formSubmitEvents.length === 0) {
        const sessionDuration = new Date().getTime() - sessionStartTime.current.getTime();
        if (sessionDuration > 30000) { // More than 30 seconds without submitting
          await trackSecurityEvent('form_abandonment', {
            focusEvents: formFocusEvents.length,
            sessionDuration,
          });
        }
      }
    } catch (error) {
      console.error('Failed to detect suspicious behavior:', error);
    }
  }, [isTracking, trackSecurityEvent]);

  // Cleanup function to send remaining data
  const cleanup = useCallback(async () => {
    await sendFormInteractions();
    await detectSuspiciousBehavior();
  }, [sendFormInteractions, detectSuspiciousBehavior]);

  return {
    isTracking,
    analytics,
    isLoading,
    setTrackingEnabled,
    trackFormInteraction,
    trackLoginAttempt,
    trackSecurityEvent,
    trackPageMetrics,
    trackEngagement,
    fetchAnalytics,
    detectSuspiciousBehavior,
    cleanup,
  };
};

// Hook for analytics dashboard components
export const useAnalyticsDashboard = () => {
  const { fetchAnalytics, analytics, isLoading } = useLoginAnalytics();
  const [timeframe, setTimeframe] = useState<'day' | 'week' | 'month'>('week');

  const refreshAnalytics = useCallback(async () => {
    await fetchAnalytics(timeframe);
  }, [fetchAnalytics, timeframe]);

  // Calculate additional metrics
  const getSecurityScore = useCallback((): number => {
    if (!analytics) return 0;

    const totalAttempts = analytics.totalAttempts;
    const suspiciousCount = analytics.suspiciousActivity.reduce((sum, activity) => sum + activity.count, 0);
    const highSeverityCount = analytics.suspiciousActivity
      .filter(activity => activity.severity === 'high')
      .reduce((sum, activity) => sum + activity.count, 0);

    // Calculate score out of 100
    const suspiciousRatio = totalAttempts > 0 ? suspiciousCount / totalAttempts : 0;
    const highSeverityRatio = totalAttempts > 0 ? highSeverityCount / totalAttempts : 0;

    const score = Math.max(0, 100 - (suspiciousRatio * 50) - (highSeverityRatio * 30));
    return Math.round(score);
  }, [analytics]);

  const getTrendData = useCallback(() => {
    if (!analytics) return null;

    return {
      successRate: analytics.successRate,
      securityScore: getSecurityScore(),
      deviceTrustRatio: analytics.deviceAnalysis.returningDevices / 
        (analytics.deviceAnalysis.newDevices + analytics.deviceAnalysis.returningDevices || 1),
    };
  }, [analytics, getSecurityScore]);

  return {
    analytics,
    isLoading,
    timeframe,
    setTimeframe,
    refreshAnalytics,
    getSecurityScore,
    getTrendData,
  };
};

export default useLoginAnalytics;

// Epic 16 Marketplace - Custom React Hook
import { useState, useCallback, useRef } from 'react';

// Types
interface SearchFilters {
  query?: string;
  categories?: string[];
  tags?: string[];
  price_min?: number;
  price_max?: number;
  rating_min?: number;
  sort_by?: 'relevance' | 'price_asc' | 'price_desc' | 'rating' | 'popularity' | 'newest' | 'oldest';
  is_free?: boolean;
  is_featured?: boolean;
  page?: number;
  limit?: number;
}

interface Template {
  id: string;
  title: string;
  description?: string;
  tags: string[];
  price_cents: number;
  avg_rating: number;
  total_reviews: number;
  total_purchases: number;
  categories?: string[];
  owner?: {
    id: string;
    name: string;
    verified: boolean;
  };
  featured_at?: string;
  created_at: string;
  is_ai_generated?: boolean;
  claude_compat: string[];
}

interface SearchResult {
  templates: Template[];
  total: number;
  page: number;
  limit: number;
  has_more: boolean;
}

interface Category {
  id: string;
  name: string;
  description?: string;
  icon?: string;
  sort_order: number;
  parent_id?: string;
}

interface MarketplaceState {
  templates: SearchResult;
  categories: Category[];
  featuredTemplates: Template[];
  loading: boolean;
  error: string | null;
}

interface MarketplaceActions {
  searchTemplates: (filters: SearchFilters, append?: boolean) => Promise<void>;
  loadCategories: () => Promise<void>;
  loadFeaturedTemplates: () => Promise<void>;
  getTemplate: (id: string) => Promise<Template | null>;
  previewTemplate: (id: string, options?: any) => Promise<any>;
  purchaseTemplate: (id: string, options?: any) => Promise<any>;
  getSearchSuggestions: (query: string) => Promise<string[]>;
  clearError: () => void;
  reset: () => void;
}

const API_BASE_URL = '/api/marketplace';

// Helper function to get auth headers
const getAuthHeaders = (): HeadersInit => {
  const token = localStorage.getItem('auth_token');
  return {
    'Content-Type': 'application/json',
    ...(token && { 'Authorization': `Bearer ${token}` })
  };
};

// Helper function to handle API responses
const handleApiResponse = async (response: Response) => {
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({ error: 'Unknown error' }));
    throw new Error(errorData.error || `HTTP ${response.status}: ${response.statusText}`);
  }
  return response.json();
};

export const useMarketplace = (): MarketplaceState & MarketplaceActions => {
  const [state, setState] = useState<MarketplaceState>({
    templates: {
      templates: [],
      total: 0,
      page: 1,
      limit: 20,
      has_more: false
    },
    categories: [],
    featuredTemplates: [],
    loading: false,
    error: null
  });

  // Keep track of ongoing requests to prevent race conditions
  const requestIdRef = useRef(0);

  const setLoading = useCallback((loading: boolean) => {
    setState(prev => ({ ...prev, loading }));
  }, []);

  const setError = useCallback((error: string | null) => {
    setState(prev => ({ ...prev, error, loading: false }));
  }, []);

  const clearError = useCallback(() => {
    setError(null);
  }, [setError]);

  const reset = useCallback(() => {
    setState({
      templates: {
        templates: [],
        total: 0,
        page: 1,
        limit: 20,
        has_more: false
      },
      categories: [],
      featuredTemplates: [],
      loading: false,
      error: null
    });
  }, []);

  const searchTemplates = useCallback(async (filters: SearchFilters, append: boolean = false) => {
    const requestId = ++requestIdRef.current;
    setLoading(true);
    clearError();

    try {
      const searchParams = new URLSearchParams();

      Object.entries(filters).forEach(([key, value]) => {
        if (value !== undefined && value !== null) {
          if (Array.isArray(value)) {
            searchParams.append(key, value.join(','));
          } else {
            searchParams.append(key, value.toString());
          }
        }
      });

      const response = await fetch(`${API_BASE_URL}/templates/search?${searchParams}`, {
        headers: getAuthHeaders()
      });

      const data = await handleApiResponse(response);

      // Check if this is still the latest request
      if (requestId === requestIdRef.current) {
        setState(prev => ({
          ...prev,
          templates: append ? {
            ...data,
            templates: [...prev.templates.templates, ...data.templates]
          } : data,
          loading: false
        }));
      }
    } catch (error) {
      if (requestId === requestIdRef.current) {
        setError(error instanceof Error ? error.message : 'Failed to search templates');
      }
    }
  }, [setLoading, clearError, setError]);

  const loadCategories = useCallback(async () => {
    try {
      const response = await fetch(`${API_BASE_URL}/categories`, {
        headers: getAuthHeaders()
      });

      const categories = await handleApiResponse(response);

      setState(prev => ({
        ...prev,
        categories: categories.sort((a: Category, b: Category) => a.sort_order - b.sort_order)
      }));
    } catch (error) {
      console.error('Failed to load categories:', error);
      // Don't set error state for categories as it's not critical
    }
  }, []);

  const loadFeaturedTemplates = useCallback(async () => {
    try {
      const response = await fetch(`${API_BASE_URL}/templates/search?is_featured=true&limit=6`, {
        headers: getAuthHeaders()
      });

      const data = await handleApiResponse(response);

      setState(prev => ({
        ...prev,
        featuredTemplates: data.templates || []
      }));
    } catch (error) {
      console.error('Failed to load featured templates:', error);
      // Don't set error state for featured templates as it's not critical
    }
  }, []);

  const getTemplate = useCallback(async (id: string): Promise<Template | null> => {
    try {
      const response = await fetch(`${API_BASE_URL}/templates/${id}`, {
        headers: getAuthHeaders()
      });

      return await handleApiResponse(response);
    } catch (error) {
      console.error('Failed to get template:', error);
      throw error;
    }
  }, []);

  const previewTemplate = useCallback(async (id: string, options: any = {}) => {
    try {
      const response = await fetch(`${API_BASE_URL}/templates/${id}/preview`, {
        method: 'POST',
        headers: getAuthHeaders(),
        body: JSON.stringify(options)
      });

      return await handleApiResponse(response);
    } catch (error) {
      console.error('Failed to preview template:', error);
      throw error;
    }
  }, []);

  const purchaseTemplate = useCallback(async (id: string, options: any = {}) => {
    try {
      const response = await fetch(`${API_BASE_URL}/purchases`, {
        method: 'POST',
        headers: getAuthHeaders(),
        body: JSON.stringify({
          template_id: id,
          ...options
        })
      });

      return await handleApiResponse(response);
    } catch (error) {
      console.error('Failed to purchase template:', error);
      throw error;
    }
  }, []);

  // Recommendation methods
  const getPersonalizedRecommendations = useCallback(async (limit: number = 10) => {
    try {
      const response = await fetch(`${API_BASE_URL}/recommendations/personalized?limit=${limit}`, {
        headers: getAuthHeaders()
      });

      const data = await handleApiResponse(response);
      return data.templates || [];
    } catch (error) {
      console.error('Failed to get personalized recommendations:', error);
      return [];
    }
  }, []);

  const getTrendingTemplates = useCallback(async (timeWindow: number = 7, limit: number = 10) => {
    try {
      const response = await fetch(`${API_BASE_URL}/recommendations/trending?timeWindow=${timeWindow}&limit=${limit}`, {
        headers: getAuthHeaders()
      });

      const data = await handleApiResponse(response);
      return data.templates || [];
    } catch (error) {
      console.error('Failed to get trending templates:', error);
      return [];
    }
  }, []);

  const getSimilarTemplates = useCallback(async (templateId: string, limit: number = 5) => {
    try {
      const response = await fetch(`${API_BASE_URL}/templates/${templateId}/similar?limit=${limit}`, {
        headers: getAuthHeaders()
      });

      const data = await handleApiResponse(response);
      return data.templates || [];
    } catch (error) {
      console.error('Failed to get similar templates:', error);
      return [];
    }
  }, []);

  const getNewUserRecommendations = useCallback(async (limit: number = 10) => {
    try {
      const response = await fetch(`${API_BASE_URL}/recommendations/new-user?limit=${limit}`, {
        headers: getAuthHeaders()
      });

      const data = await handleApiResponse(response);
      return data.templates || [];
    } catch (error) {
      console.error('Failed to get new user recommendations:', error);
      return [];
    }
  }, []);

  const getCategoryRecommendations = useCallback(async (categoryId: string, limit: number = 10, exclude: string[] = []) => {
    try {
      const excludeParam = exclude.length > 0 ? `&exclude=${exclude.join(',')}` : '';
      const response = await fetch(`${API_BASE_URL}/categories/${categoryId}/recommendations?limit=${limit}${excludeParam}`, {
        headers: getAuthHeaders()
      });

      const data = await handleApiResponse(response);
      return data.templates || [];
    } catch (error) {
      console.error('Failed to get category recommendations:', error);
      return [];
    }
  }, []);

  const getSearchSuggestions = useCallback(async (query: string): Promise<string[]> => {
    if (!query.trim() || query.length < 2) {
      return [];
    }

    try {
      const response = await fetch(`${API_BASE_URL}/search/suggestions?q=${encodeURIComponent(query)}`, {
        headers: getAuthHeaders()
      });

      const data = await handleApiResponse(response);
      return data.suggestions || [];
    } catch (error) {
      console.error('Failed to get search suggestions:', error);
      return [];
    }
  }, []);

  const getSearchBasedRecommendations = useCallback(async (limit: number = 10) => {
    try {
      const response = await fetch(`${API_BASE_URL}/recommendations/search-based?limit=${limit}`, {
        headers: getAuthHeaders()
      });

      const data = await handleApiResponse(response);
      return data.templates || [];
    } catch (error) {
      console.error('Failed to get search-based recommendations:', error);
      return [];
    }
  }, []);

  return {
    ...state,
    searchTemplates,
    loadCategories,
    loadFeaturedTemplates,
    getTemplate,
    previewTemplate,
    purchaseTemplate,
    getSearchSuggestions,
    clearError,
    reset,
    // Recommendation methods
    getPersonalizedRecommendations,
    getTrendingTemplates,
    getSimilarTemplates,
    getNewUserRecommendations,
    getCategoryRecommendations,
    getSearchBasedRecommendations
  };
};

// Epic 11 usePasswordReset Hook
// React hook for password reset functionality

import { useState, useCallback } from 'react';

interface PasswordResetRequestResponse {
  success: boolean;
  message: string;
  estimatedDelivery?: string;
}

interface PasswordResetValidationResponse {
  valid: boolean;
  error?: string;
  canRetry?: boolean;
  email?: string;
  tokenExpiresAt?: string;
}

interface PasswordResetConfirmResponse {
  success: boolean;
  message: string;
}

export const usePasswordReset = () => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [tokenValidation, setTokenValidation] = useState<PasswordResetValidationResponse | null>(null);

  const clearMessages = useCallback(() => {
    setError(null);
    setSuccess(null);
  }, []);

  const requestPasswordReset = useCallback(async (email: string): Promise<void> => {
    setLoading(true);
    setError(null);
    setSuccess(null);

    try {
      const response = await fetch('/api/auth/password-reset/request', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ email }),
      });

      const data: PasswordResetRequestResponse = await response.json();

      if (!response.ok) {
        throw new Error(data.message || 'Failed to request password reset');
      }

      setSuccess(data.message);
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'An unexpected error occurred';
      setError(errorMessage);
      throw err;
    } finally {
      setLoading(false);
    }
  }, []);

  const validateToken = useCallback(async (token: string): Promise<PasswordResetValidationResponse> => {
    setLoading(true);
    setError(null);

    try {
      const response = await fetch(`/api/auth/password-reset/validate/${encodeURIComponent(token)}`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      const data: PasswordResetValidationResponse = await response.json();

      if (!response.ok) {
        throw new Error(data.error || 'Failed to validate token');
      }

      setTokenValidation(data);

      if (!data.valid) {
        setError(data.error || 'Invalid or expired token');
      }

      return data;
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to validate token';
      setError(errorMessage);
      throw err;
    } finally {
      setLoading(false);
    }
  }, []);

  const confirmPasswordReset = useCallback(async (
    token: string,
    newPassword: string,
    confirmPassword: string
  ): Promise<void> => {
    setLoading(true);
    setError(null);
    setSuccess(null);

    try {
      const response = await fetch('/api/auth/password-reset/confirm', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          token,
          newPassword,
          confirmPassword,
        }),
      });

      const data: PasswordResetConfirmResponse = await response.json();

      if (!response.ok) {
        throw new Error(data.message || 'Failed to reset password');
      }

      setSuccess(data.message);
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to reset password';
      setError(errorMessage);
      throw err;
    } finally {
      setLoading(false);
    }
  }, []);

  const getTokenExpirationInfo = useCallback(() => {
    if (!tokenValidation?.tokenExpiresAt) {
      return null;
    }

    const expiresAt = new Date(tokenValidation.tokenExpiresAt);
    const now = new Date();
    const timeLeft = expiresAt.getTime() - now.getTime();

    if (timeLeft <= 0) {
      return { expired: true, timeLeft: 0, formatted: 'Expired' };
    }

    const hours = Math.floor(timeLeft / (1000 * 60 * 60));
    const minutes = Math.floor((timeLeft % (1000 * 60 * 60)) / (1000 * 60));

    let formatted = '';
    if (hours > 0) {
      formatted = `${hours}h ${minutes}m`;
    } else {
      formatted = `${minutes}m`;
    }

    return {
      expired: false,
      timeLeft,
      formatted,
      expiresAt,
    };
  }, [tokenValidation]);

  const retryPasswordReset = useCallback(async (email?: string): Promise<void> => {
    if (!email && !tokenValidation?.email) {
      throw new Error('Email address is required to retry password reset');
    }

    const emailToUse = email || tokenValidation!.email!;
    return requestPasswordReset(emailToUse);
  }, [requestPasswordReset, tokenValidation]);

  return {
    // State
    loading,
    error,
    success,
    tokenValidation,

    // Actions
    requestPasswordReset,
    validateToken,
    confirmPasswordReset,
    retryPasswordReset,
    clearMessages,

    // Utilities
    getTokenExpirationInfo,

    // Computed values
    isTokenValid: tokenValidation?.valid === true,
    canRetry: tokenValidation?.canRetry === true,
    userEmail: tokenValidation?.email,
  };
};

export default usePasswordReset;

// Epic 11 Registration Hook
// React hook for user registration with validation and analytics

import { useState, useCallback } from 'react';
import { useAuth } from './useAuth';

export interface RegistrationData {
  email: string;
  password: string;
  firstName?: string;
  lastName?: string;
  displayName?: string;
  invitationToken?: string;
}

export interface RegistrationResponse {
  user: {
    id: string;
    email: string;
    emailVerified: boolean;
    createdAt: string;
    roles: string[];
    permissions: string[];
  };
  emailVerificationRequired: boolean;
  nextSteps?: string[];
}

export interface ValidationResult {
  isValid: boolean;
  errors: Array<{
    field: string;
    message: string;
    code: string;
  }>;
  warnings: Array<{
    field: string;
    message: string;
    code: string;
  }>;
  suggestions: Array<{
    field: string;
    suggestion: string;
  }>;
}

export const useRegistration = () => {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [validationResult, setValidationResult] = useState<ValidationResult | null>(null);
  const { login } = useAuth();

  const register = useCallback(async (data: RegistrationData): Promise<RegistrationResponse> => {
    setIsLoading(true);
    setError(null);

    try {
      const response = await fetch('/auth/register', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(data),
        credentials: 'include',
      });

      if (!response.ok) {
        const errorData = await response.json();

        // Handle validation errors
        if (response.status === 400 && errorData.validation) {
          setValidationResult(errorData.validation);
          throw new Error('Please fix the validation errors');
        }

        throw new Error(errorData.error || 'Registration failed');
      }

      const result: RegistrationResponse = await response.json();

      // Track successful registration
      if (window.gtag) {
        window.gtag('event', 'sign_up', {
          method: 'email',
          user_id: result.user.id,
        });
      }

      return result;
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Registration failed';
      setError(errorMessage);

      // Track registration failure
      if (window.gtag) {
        window.gtag('event', 'registration_failed', {
          error: errorMessage,
        });
      }

      throw err;
    } finally {
      setIsLoading(false);
    }
  }, []);

  const validateField = useCallback(async (field: string, value: any): Promise<void> => {
    if (!value) return;

    try {
      const response = await fetch('/auth/validate-field', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ field, value }),
      });

      if (response.ok) {
        const result = await response.json();
        if (result.validation) {
          setValidationResult(result.validation);
        }
      }
    } catch (err) {
      console.error('Field validation error:', err);
    }
  }, []);

  const resendEmailVerification = useCallback(async (email: string): Promise<void> => {
    setIsLoading(true);
    setError(null);

    try {
      const response = await fetch('/auth/resend-verification', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ email }),
        credentials: 'include',
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Failed to resend verification email');
      }
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to resend verification email';
      setError(errorMessage);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, []);

  const verifyEmail = useCallback(async (token: string): Promise<void> => {
    setIsLoading(true);
    setError(null);

    try {
      const response = await fetch('/auth/verify-email', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ token }),
        credentials: 'include',
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Email verification failed');
      }

      // Track email verification
      if (window.gtag) {
        window.gtag('event', 'email_verified');
      }
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Email verification failed';
      setError(errorMessage);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, []);

  const clearError = useCallback(() => {
    setError(null);
  }, []);

  const clearValidation = useCallback(() => {
    setValidationResult(null);
  }, []);

  return {
    register,
    validateField,
    resendEmailVerification,
    verifyEmail,
    isLoading,
    error,
    validationResult,
    clearError,
    clearValidation,
  };
};

// Helper hook for password strength calculation
export const usePasswordStrength = (password: string) => {
  const calculateStrength = useCallback((password: string): {
    score: number;
    feedback: string[];
    strength: 'weak' | 'fair' | 'good' | 'strong';
  } => {
    if (!password) {
      return { score: 0, feedback: [], strength: 'weak' };
    }

    let score = 0;
    const feedback: string[] = [];

    // Length check
    if (password.length >= 12) {
      score += 25;
    } else {
      feedback.push('Use at least 12 characters');
    }

    // Character variety
    if (/[a-z]/.test(password)) score += 15;
    else feedback.push('Add lowercase letters');

    if (/[A-Z]/.test(password)) score += 15;
    else feedback.push('Add uppercase letters');

    if (/\d/.test(password)) score += 15;
    else feedback.push('Add numbers');

    if (/[^A-Za-z0-9]/.test(password)) score += 15;
    else feedback.push('Add special characters');

    // Bonus points
    if (password.length >= 16) score += 10;
    if (/[A-Z].*[A-Z]/.test(password)) score += 5;
    if (/\d.*\d/.test(password)) score += 5;
    if (/[^A-Za-z0-9].*[^A-Za-z0-9]/.test(password)) score += 5;

    // Penalties
    if (/(.)\1{2,}/.test(password)) {
      score -= 10;
      feedback.push('Avoid repeating characters');
    }

    if (/123|abc|qwe|password/i.test(password)) {
      score -= 15;
      feedback.push('Avoid common patterns');
    }

    let strength: 'weak' | 'fair' | 'good' | 'strong';
    if (score < 30) strength = 'weak';
    else if (score < 60) strength = 'fair';
    else if (score < 80) strength = 'good';
    else strength = 'strong';

    return {
      score: Math.min(100, Math.max(0, score)),
      feedback,
      strength,
    };
  }, []);

  return calculateStrength(password);
};

