// Epic 11 Password Reset Page
// Main page component for password reset functionality

import React, { useState, useEffect } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import { PasswordResetForm } from '../components/auth/PasswordResetForm';
import { usePasswordReset } from '../hooks/usePasswordReset';

const PasswordResetPage: React.FC = () => {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const token = searchParams.get('token');

  const [mode, setMode] = useState<'request' | 'confirm' | 'success' | 'error'>('request');
  const [successMessage, setSuccessMessage] = useState<string>('');
  const [errorMessage, setErrorMessage] = useState<string>('');

  const {
    loading,
    error,
    success,
    tokenValidation,
    validateToken,
    getTokenExpirationInfo,
    isTokenValid,
    canRetry,
    userEmail,
  } = usePasswordReset();

  // Determine mode based on token presence and validation
  useEffect(() => {
    if (token) {
      // Token provided - validate it
      validateToken(token);
    } else {
      // No token - show request form
      setMode('request');
    }
  }, [token, validateToken]);

  // Update mode based on token validation results
  useEffect(() => {
    if (tokenValidation) {
      if (tokenValidation.valid) {
        setMode('confirm');
      } else {
        setMode('error');
        setErrorMessage(tokenValidation.error || 'Invalid token');
      }
    }
  }, [tokenValidation]);

  // Handle success from password reset request
  useEffect(() => {
    if (success && mode === 'request') {
      setMode('success');
      setSuccessMessage(success);
    } else if (success && mode === 'confirm') {
      setMode('success');
      setSuccessMessage(success);
      // Redirect to login after 3 seconds
      setTimeout(() => {
        navigate('/auth/login');
      }, 3000);
    }
  }, [success, mode, navigate]);

  // Handle errors
  useEffect(() => {
    if (error) {
      if (mode === 'confirm') {
        // Stay in confirm mode but show error
        setErrorMessage(error);
      } else {
        setMode('error');
        setErrorMessage(error);
      }
    }
  }, [error, mode]);

  const handleSuccess = () => {
    if (mode === 'request') {
      setMode('success');
      setSuccessMessage('Password reset link sent! Check your email.');
    } else if (mode === 'confirm') {
      setMode('success');
      setSuccessMessage('Password updated successfully! Redirecting to login...');
      setTimeout(() => {
        navigate('/auth/login');
      }, 3000);
    }
  };

  const handleCancel = () => {
    navigate('/auth/login');
  };

  const handleRetryRequest = () => {
    setMode('request');
    setErrorMessage('');
  };

  const tokenExpiration = getTokenExpirationInfo();

  if (loading && !tokenValidation) {
    return (
      <div className="password-reset-page">
        <div className="loading-container">
          <div className="spinner large"></div>
          <p>Validating reset token...</p>
        </div>

        <style jsx>{`
          .password-reset-page {
            min-height: 100vh;
            display: flex;
            align-items: center;
            justify-content: center;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            padding: 1rem;
          }

          .loading-container {
            text-align: center;
            color: white;
          }

          .spinner {
            width: 2rem;
            height: 2rem;
            border: 3px solid rgba(255, 255, 255, 0.3);
            border-top: 3px solid white;
            border-radius: 50%;
            animation: spin 1s linear infinite;
            margin: 0 auto 1rem auto;
          }

          .spinner.large {
            width: 3rem;
            height: 3rem;
          }

          @keyframes spin {
            to {
              transform: rotate(360deg);
            }
          }
        `}</style>
      </div>
    );
  }

  return (
    <div className="password-reset-page">
      <div className="container">
        {mode === 'request' && (
          <PasswordResetForm
            mode="request"
            onSuccess={handleSuccess}
            onCancel={handleCancel}
          />
        )}

        {mode === 'confirm' && (
          <>
            {tokenExpiration && !tokenExpiration.expired && (
              <div className="token-info">
                <p>Reset link expires in: <strong>{tokenExpiration.formatted}</strong></p>
                {userEmail && <p>Resetting password for: <strong>{userEmail}</strong></p>}
              </div>
            )}

            <PasswordResetForm
              mode="confirm"
              token={token || undefined}
              onSuccess={handleSuccess}
              onCancel={handleCancel}
            />

            {errorMessage && (
              <div className="error-banner">
                <p>{errorMessage}</p>
              </div>
            )}
          </>
        )}

        {mode === 'success' && (
          <div className="success-container">
            <div className="success-card">
              <div className="success-icon">✅</div>
              <h2>Success!</h2>
              <p>{successMessage}</p>

              {mode === 'success' && !token && (
                <div className="success-actions">
                  <button
                    onClick={handleCancel}
                    className="btn btn-primary"
                  >
                    Back to Login
                  </button>
                </div>
              )}

              {mode === 'success' && token && (
                <div className="success-actions">
                  <p className="redirect-notice">
                    You'll be redirected to login automatically...
                  </p>
                  <button
                    onClick={() => navigate('/auth/login')}
                    className="btn btn-link"
