      }
    ];

    return pages;
  }

  handleSearch(query) {
    this.currentQuery = query.trim();

    clearTimeout(this.searchTimeout);
    this.searchTimeout = setTimeout(() => {
      this.performSearch(this.currentQuery);
    }, this.options.searchDelay);
  }

  performSearch(query) {
    if (!query || query.length < this.options.minSearchLength) {
      this.hideResults();
      return;
    }

    const results = this.searchContent(query);
    this.displayResults(results, query);
  }

  searchContent(query) {
    if (!this.searchIndex) return [];

    const queryLower = query.toLowerCase();
    const queryTerms = queryLower.split(/\s+/);

    let results = this.searchIndex.map(item => {
      let score = 0;
      let matches = [];

      // Title matches (highest weight)
      const titleScore = this.calculateTextScore(item.title, queryTerms, 10);
      score += titleScore.score;
      matches.push(...titleScore.matches);

      // Content matches
      const contentScore = this.calculateTextScore(item.content, queryTerms, 5);
      score += contentScore.score;
      matches.push(...contentScore.matches);

      // Keywords matches
      const keywordScore = this.calculateKeywordScore(item.keywords || [], queryTerms, 8);
      score += keywordScore.score;
      matches.push(...keywordScore.matches);

      // Exact phrase bonus
      if (item.title.toLowerCase().includes(queryLower)) {
        score += 15;
      }
      if (item.content.toLowerCase().includes(queryLower)) {
        score += 10;
      }

      return {
        ...item,
        score,
        matches: [...new Set(matches)],
        snippet: this.generateSnippet(item.content, queryTerms)
      };
    });

    // Filter by current filters
    results = results.filter(item => {
      if (this.filters.type !== 'all' && item.type !== this.filters.type) return false;
      if (this.filters.difficulty !== 'all' && item.difficulty !== this.filters.difficulty) return false;
      if (this.filters.part !== 'all' && item.part !== this.filters.part) return false;
      return true;
    });

    // Sort by score and return top results
    return results
      .filter(item => item.score > 0)
      .sort((a, b) => b.score - a.score)
      .slice(0, this.options.maxResults);
  }

  calculateTextScore(text, queryTerms, weight) {
    const textLower = text.toLowerCase();
    let score = 0;
    let matches = [];

    queryTerms.forEach(term => {
      const termCount = (textLower.match(new RegExp(term, 'g')) || []).length;
      if (termCount > 0) {
        score += termCount * weight;
        matches.push(term);
      }
    });

    return { score, matches };
  }

  calculateKeywordScore(keywords, queryTerms, weight) {
    let score = 0;
    let matches = [];

    keywords.forEach(keyword => {
      const keywordLower = keyword.toLowerCase();
      queryTerms.forEach(term => {
        if (keywordLower.includes(term)) {
          score += weight;
          matches.push(term);
        }
      });
    });

    return { score, matches };
  }

  generateSnippet(content, queryTerms, maxLength = 150) {
    const contentLower = content.toLowerCase();
    let bestStart = 0;
    let bestScore = 0;

    // Find the best position to start the snippet
    for (let i = 0; i < content.length - maxLength; i += 10) {
      const section = contentLower.substring(i, i + maxLength);
      let score = 0;

      queryTerms.forEach(term => {
        const matches = (section.match(new RegExp(term, 'g')) || []).length;
        score += matches;
      });

      if (score > bestScore) {
        bestScore = score;
        bestStart = i;
      }
    }

    let snippet = content.substring(bestStart, bestStart + maxLength);

    // Clean up snippet
    if (bestStart > 0) snippet = '...' + snippet;
    if (bestStart + maxLength < content.length) snippet += '...';

    // Highlight query terms
    queryTerms.forEach(term => {
      const regex = new RegExp(`(${term})`, 'gi');
      snippet = snippet.replace(regex, '<mark>$1</mark>');
    });

    return snippet;
  }

  displayResults(results, query) {
    if (results.length === 0) {
      this.resultsContainer.innerHTML = `
        <div class="search-no-results">
          <p>No results found for "${query}"</p>
          <div class="search-suggestions">
            <p>Try:</p>
            <ul>
              <li>Different keywords</li>
              <li>Removing filters</li>
              <li>Checking spelling</li>
            </ul>
          </div>
        </div>
      `;
    } else {
      const resultsHtml = results.map(result => `
        <div class="search-result">
          <a href="${result.url}" class="search-result-link">
            <h3 class="search-result-title">${this.highlightText(result.title, query)}</h3>
            <p class="search-result-snippet">${result.snippet}</p>
            <div class="search-result-meta">
              <span class="result-type">${result.type}</span>
              <span class="result-difficulty">${result.difficulty}</span>
              <span class="result-part">${result.part}</span>
            </div>
          </a>
        </div>
      `).join('');

      this.resultsContainer.innerHTML = `
        <div class="search-results-header">
          <span class="results-count">${results.length} results for "${query}"</span>
        </div>
        ${resultsHtml}
      `;
    }

    this.showResults();
  }

  highlightText(text, query) {
    const queryTerms = query.toLowerCase().split(/\s+/);
    let highlightedText = text;

    queryTerms.forEach(term => {
      const regex = new RegExp(`(${term})`, 'gi');
      highlightedText = highlightedText.replace(regex, '<mark>$1</mark>');
    });

    return highlightedText;
  }

  showResults() {
    this.resultsContainer.style.display = 'block';
    this.resultsContainer.classList.add('show');
  }

  hideResults() {
    this.resultsContainer.style.display = 'none';
    this.resultsContainer.classList.remove('show');
  }

  clearSearch() {
    this.searchInput.value = '';
    this.currentQuery = '';
    this.hideResults();
    this.searchInput.focus();
  }

  buildNavigation() {
    const navigationStructure = {
      'Part 1: Foundation': [
        { title: 'Introduction & Overview', url: 'part1-foundation/01-introduction.html' },
        { title: 'Architecture & Core Concepts', url: 'part1-foundation/02-architecture.html' },
        { title: 'Generator JSON Schema Reference', url: 'part1-foundation/03-schema-reference.html' }
      ],
      'Part 2: Content Development': [
        { title: 'Basic Generator Creation', url: 'part2-content-development/04-basic-generator.html' },
        { title: 'Advanced Rule Syntax', url: 'part2-content-development/05-advanced-rules.html' },
        { title: 'Modularization & Organization', url: 'part2-content-development/06-modularization.html' }
      ],
      'Part 3: Engine Reference': [
        { title: 'Engine API Documentation', url: 'part3-engine-reference/09-api-documentation.html' },
        { title: 'Modifier System', url: 'part3-engine-reference/10-modifier-system.html' },
        { title: 'Variable System', url: 'part3-engine-reference/11-variable-system.html' }
      ],
      'Part 4: Practical Guides': [
        { title: 'Interactive Tutorial', url: 'part4-practical-guides/14-interactive-tutorial.html' },
        { title: 'Expansion Recipes for LLMs', url: 'part4-practical-guides/15-expansion-recipes.html' },
        { title: 'Testing & Quality Assurance', url: 'part4-practical-guides/16-testing-qa.html' }
      ],
      'Part 5: Advanced Topics': [
        { title: 'Custom Extensions', url: 'part5-advanced-topics/18-custom-extensions.html' },
        { title: 'Security Best Practices', url: 'part5-advanced-topics/19-security.html' },
        { title: 'Integration Patterns', url: 'part5-advanced-topics/20-integration.html' }
      ],
      'Part 6: Reference Materials': [
        { title: 'Quick Reference Tables', url: 'part6-reference-materials/22-quick-reference.html' },
        { title: 'Templates & Boilerplates', url: 'part6-reference-materials/23-templates.html' },
        { title: 'Common Pitfalls & Solutions', url: 'part6-reference-materials/24-pitfalls.html' }
      ]
    };

    if (this.navigationContainer) {
      const navHtml = this.buildNavigationHTML(navigationStructure);
      this.navigationContainer.innerHTML = navHtml;
    }
  }

  buildNavigationHTML(structure) {
    return Object.entries(structure).map(([section, items]) => `
      <div class="nav-section">
        <h3 class="nav-section-title">${section}</h3>
        <ul class="nav-section-items">
          ${items.map(item => `
            <li class="nav-item">
              <a href="${item.url}" class="nav-link">${item.title}</a>
            </li>
          `).join('')}
        </ul>
      </div>
    `).join('');
  }

  setupKeyboardShortcuts() {
    document.addEventListener('keydown', (e) => {
      // Ctrl/Cmd + K to focus search
      if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
        e.preventDefault();
        this.searchInput.focus();
      }

      // Escape to clear search
      if (e.key === 'Escape') {
        this.clearSearch();
      }
    });
  }

  highlightCurrentPage() {
    const currentPath = window.location.pathname;
    const navLinks = document.querySelectorAll('.nav-link');

    navLinks.forEach(link => {
      if (link.getAttribute('href') === currentPath) {
        link.classList.add('current-page');
      }
    });
  }

  trackSearchClick(link) {
    // Track search result clicks for analytics
    const data = {
      query: this.currentQuery,
      url: link.href,
      title: link.querySelector('.search-result-title').textContent,
      position: Array.from(link.parentNode.parentNode.children).indexOf(link.parentNode)
    };

    // Send to analytics if available
    if (window.gtag) {
      window.gtag('event', 'search_result_click', data);
    }

    console.log('Search click tracked:', data);
  }
}

