#!/usr/bin/env node

/**
 * Content Indexing Tool for Handbook Search
 * Epic 8.3.3 - Search and Navigation System
 * 
 * This tool automatically generates a search index from markdown files
 * Usage: node build-search-index.js
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

class SearchIndexBuilder {
  constructor(options = {}) {
    this.options = {
      docsPath: path.join(__dirname, '../..'),
      outputPath: path.join(__dirname, '../data/search-index.json'),
      includePatterns: ['**/*.md', '**/*.html'],
      excludePatterns: ['**/node_modules/**', '**/assets/**', '**/_build/**'],
      minContentLength: 50,
      maxContentLength: 1000,
      ...options
    };

    this.index = [];
    this.partsMap = {
      'part1-foundation': 'part1',
      'part2-content-development': 'part2',
      'part3-engine-reference': 'part3',
      'part4-practical-guides': 'part4',
      'part5-advanced-topics': 'part5',
      'part6-reference-materials': 'part6',
      'assets/examples': 'examples'
    };

    this.difficultyMap = {
      'introduction': 'beginner',
      'basic': 'beginner',
      'getting-started': 'beginner',
      'tutorial': 'beginner',
      'advanced': 'advanced',
      'reference': 'intermediate',
      'api': 'advanced',
      'extension': 'advanced',
      'security': 'advanced',
      'performance': 'advanced'
    };

    this.typeMap = {
      'introduction': 'chapter',
      'reference': 'reference',
      'tutorial': 'example',
      'example': 'example',
      'api': 'reference',
      'guide': 'chapter'
    };
  }

  async build() {
    console.log('🔍 Building search index...');

    try {
      await this.scanFiles();
      await this.generateIndex();
      await this.writeIndex();

      console.log(`✅ Search index built successfully!`);
      console.log(`📊 Indexed ${this.index.length} pages`);
      console.log(`📝 Output: ${this.options.outputPath}`);

    } catch (error) {
      console.error('❌ Error building search index:', error);
      process.exit(1);
    }
  }

  async scanFiles() {
    const files = await this.findFiles(this.options.docsPath);

    for (const file of files) {
      if (this.shouldIncludeFile(file)) {
        await this.processFile(file);
      }
    }
  }

  async findFiles(dir) {
    const files = [];
    const entries = await fs.promises.readdir(dir, { withFileTypes: true });

    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);

      if (entry.isDirectory()) {
        if (!this.isExcluded(fullPath)) {
          files.push(...await this.findFiles(fullPath));
        }
      } else if (entry.isFile()) {
        files.push(fullPath);
      }
    }

    return files;
  }

  shouldIncludeFile(file) {
    const ext = path.extname(file);
    const isMarkdown = ext === '.md';
    const isHtml = ext === '.html';

    return (isMarkdown || isHtml) && !this.isExcluded(file);
  }

  isExcluded(file) {
    const relativePath = path.relative(this.options.docsPath, file);

    return this.options.excludePatterns.some(pattern => {
      return relativePath.includes(pattern.replace('**/', '').replace('/**', ''));
    });
  }

  async processFile(file) {
    try {
      const content = await fs.promises.readFile(file, 'utf8');
      const relativePath = path.relative(this.options.docsPath, file);

      const pageData = this.extractPageData(content, relativePath);

      if (pageData.content.length >= this.options.minContentLength) {
        this.index.push(pageData);
        console.log(`✓ Indexed: ${pageData.title}`);
      } else {
        console.log(`⚠ Skipped (too short): ${relativePath}`);
      }

    } catch (error) {
      console.error(`❌ Error processing ${file}:`, error.message);
    }
  }

  extractPageData(content, relativePath) {
    const title = this.extractTitle(content);
    const cleanContent = this.cleanContent(content);
    const url = this.generateUrl(relativePath);
    const part = this.determinePart(relativePath);
    const type = this.determineType(title, relativePath);
    const difficulty = this.determineDifficulty(title, relativePath);
    const keywords = this.extractKeywords(title, cleanContent);

    return {
      title,
      url,
      content: cleanContent.substring(0, this.options.maxContentLength),
      type,
      difficulty,
      part,
      keywords
    };
  }

  extractTitle(content) {
    // Try to find main heading
    const h1Match = content.match(/^#\s+(.+)$/m);
    if (h1Match) {
      return h1Match[1].trim();
    }

    // Try to find any heading
    const headingMatch = content.match(/^#{1,6}\s+(.+)$/m);
    if (headingMatch) {
      return headingMatch[1].trim();
    }

    // Try to find title in frontmatter
    const titleMatch = content.match(/^title:\s*(.+)$/m);
    if (titleMatch) {
      return titleMatch[1].trim().replace(/['"]/g, '');
    }

    return 'Untitled';
  }

  cleanContent(content) {
    // Remove markdown syntax
    let cleaned = content
      .replace(/^#{1,6}\s+/gm, '') // Remove headers
      .replace(/\*\*(.*?)\*\*/g, '$1') // Remove bold
      .replace(/\*(.*?)\*/g, '$1') // Remove italic
      .replace(/`([^`]+)`/g, '$1') // Remove inline code
      .replace(/```[\s\S]*?```/g, '') // Remove code blocks
      .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1') // Remove links
      .replace(/!\[([^\]]*)\]\([^)]+\)/g, '$1') // Remove images
      .replace(/^\s*[-*+]\s+/gm, '') // Remove list markers
      .replace(/^\s*\d+\.\s+/gm, '') // Remove numbered lists
      .replace(/^\s*>\s+/gm, '') // Remove blockquotes
      .replace(/\n\s*\n/g, ' ') // Collapse whitespace
      .replace(/\s+/g, ' ') // Normalize spaces
      .trim();

    // Remove HTML tags if present
    cleaned = cleaned.replace(/<[^>]*>/g, '');

    return cleaned;
  }

  generateUrl(relativePath) {
    // Convert file path to URL
    let url = relativePath.replace(/\\/g, '/');

    // Convert .md to .html
    if (url.endsWith('.md')) {
      url = url.replace('.md', '.html');
    }

    return url;
  }

  determinePart(relativePath) {
    for (const [pathPattern, part] of Object.entries(this.partsMap)) {
      if (relativePath.includes(pathPattern)) {
        return part;
      }
    }

    return 'other';
  }

  determineType(title, relativePath) {
    const titleLower = title.toLowerCase();
    const pathLower = relativePath.toLowerCase();

    // Check for explicit type indicators
    for (const [indicator, type] of Object.entries(this.typeMap)) {
      if (titleLower.includes(indicator) || pathLower.includes(indicator)) {
        return type;
      }
    }

    // Check file location patterns
    if (pathLower.includes('reference')) return 'reference';
    if (pathLower.includes('example')) return 'example';
    if (pathLower.includes('tutorial')) return 'example';
    if (pathLower.includes('guide')) return 'chapter';

    return 'chapter';
  }

  determineDifficulty(title, relativePath) {
    const titleLower = title.toLowerCase();
    const pathLower = relativePath.toLowerCase();

    // Check for explicit difficulty indicators
    for (const [indicator, difficulty] of Object.entries(this.difficultyMap)) {
      if (titleLower.includes(indicator) || pathLower.includes(indicator)) {
        return difficulty;
      }
    }

    // Default based on part
    const part = this.determinePart(relativePath);
    if (part === 'part1') return 'beginner';
    if (part === 'part2') return 'intermediate';
    if (part === 'part3') return 'advanced';
    if (part === 'part4') return 'beginner';
    if (part === 'part5') return 'advanced';
    if (part === 'part6') return 'all';

    return 'intermediate';
  }

  extractKeywords(title, content) {
    const keywords = new Set();

    // Extract from title
    const titleWords = title.toLowerCase()
      .replace(/[^\w\s]/g, '')
      .split(/\s+/)
      .filter(word => word.length > 2);

    titleWords.forEach(word => keywords.add(word));

    // Extract important terms from content
    const contentWords = content.toLowerCase()
      .replace(/[^\w\s]/g, '')
      .split(/\s+/)
      .filter(word => word.length > 3);

    // Get most frequent words
    const wordFreq = {};
    contentWords.forEach(word => {
      wordFreq[word] = (wordFreq[word] || 0) + 1;
    });

    const topWords = Object.entries(wordFreq)
      .sort(([,a], [,b]) => b - a)
      .slice(0, 10)
      .map(([word]) => word);

    topWords.forEach(word => keywords.add(word));

    // Add technical terms
    const technicalTerms = [
      'generator', 'node', 'rule', 'variable', 'schema', 'json',
      'weighted', 'conditional', 'sequential', 'markov', 'modifier',
      'api', 'engine', 'execution', 'runtime', 'performance',
      'security', 'integration', 'testing', 'debugging'
    ];

    technicalTerms.forEach(term => {
      if (title.toLowerCase().includes(term) || content.toLowerCase().includes(term)) {
        keywords.add(term);
      }
    });

    return Array.from(keywords).slice(0, 15);
  }

  async generateIndex() {
    // Sort by relevance score
    this.index.sort((a, b) => {
      const scoreA = this.calculateRelevanceScore(a);
      const scoreB = this.calculateRelevanceScore(b);
      return scoreB - scoreA;
    });

    // Add IDs
    this.index.forEach((item, index) => {
      item.id = this.generateId(item.title, item.url);
    });
  }

  calculateRelevanceScore(item) {
    let score = 0;

    // Title length bonus (not too short, not too long)
    if (item.title.length > 10 && item.title.length < 80) {
      score += 10;
    }

    // Content length bonus
    score += Math.min(item.content.length / 100, 10);

    // Type bonuses
    if (item.type === 'chapter') score += 15;
    if (item.type === 'reference') score += 10;
    if (item.type === 'example') score += 5;

    // Part bonuses (foundation and practical guides are more important)
    if (item.part === 'part1' || item.part === 'part4') score += 5;

    // Keyword count bonus
    score += item.keywords.length;

    return score;
  }

  generateId(title, url) {
    return crypto.createHash('md5')
      .update(title + url)
      .digest('hex')
      .substring(0, 8);
  }

  async writeIndex() {
    const indexData = {
      generated: new Date().toISOString(),
      version: '1.0.0',
      totalPages: this.index.length,
      pages: this.index
    };

    const jsonContent = JSON.stringify(indexData.pages, null, 2);

    // Ensure directory exists
    const dir = path.dirname(this.options.outputPath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }

    await fs.promises.writeFile(this.options.outputPath, jsonContent, 'utf8');

    // Also write metadata
    const metaPath = this.options.outputPath.replace('.json', '-meta.json');
    await fs.promises.writeFile(metaPath, JSON.stringify({
      generated: indexData.generated,
      version: indexData.version,
      totalPages: indexData.totalPages,
      stats: this.generateStats()
    }, null, 2), 'utf8');
  }

  generateStats() {
    const stats = {
      byType: {},
      byDifficulty: {},
      byPart: {}
    };

    this.index.forEach(item => {
      stats.byType[item.type] = (stats.byType[item.type] || 0) + 1;
      stats.byDifficulty[item.difficulty] = (stats.byDifficulty[item.difficulty] || 0) + 1;
      stats.byPart[item.part] = (stats.byPart[item.part] || 0) + 1;
    });

    return stats;
  }
}

// Run if called directly
if (require.main === module) {
  const builder = new SearchIndexBuilder();
  builder.build();
}

module.exports = SearchIndexBuilder;

#!/usr/bin/env node

/**
 * Content Freshness Checker - Content Authoring Handbook
 * Epic 8.3 Story 8.3.6 - Update Cycle and Maintenance
 * 
 * Analyzes content age and generates freshness reports
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

class ContentFreshnessChecker {
  constructor() {
    this.rootDir = path.join(__dirname, '../..');
    this.contentDirs = [
      'part1-foundation',
      'part2-content-development',
      'part3-engine-reference',
      'part4-practical-guides',
      'part5-advanced-topics',
      'part6-reference-materials'
    ];
    this.reportsDir = path.join(this.rootDir, 'reports');
    this.maxAge = {
      critical: 30,    // days
      warning: 60,     // days
      stale: 90        // days
    };

    this.ensureDirectoryExists(this.reportsDir);
  }

  /**
   * Get all content files with metadata
   */
  getContentFiles() {
    const files = [];

    this.contentDirs.forEach(dir => {
      const dirPath = path.join(this.rootDir, dir);
      if (fs.existsSync(dirPath)) {
        const dirFiles = this.getFilesRecursively(dirPath);
        files.push(...dirFiles);
      }
    });

    return files;
  }

  /**
   * Get files recursively from directory
   */
  getFilesRecursively(dir) {
    const files = [];
    const items = fs.readdirSync(dir);

    items.forEach(item => {
      const itemPath = path.join(dir, item);
      const stat = fs.statSync(itemPath);

      if (stat.isDirectory()) {
        files.push(...this.getFilesRecursively(itemPath));
      } else if (item.endsWith('.md') || item.endsWith('.json')) {
        files.push({
          path: itemPath,
          relativePath: path.relative(this.rootDir, itemPath),
          name: item,
          size: stat.size,
          modified: stat.mtime,
          accessed: stat.atime,
          category: this.categorizeFile(itemPath)
        });
      }
    });

    return files;
  }

  /**
   * Categorize file based on path
   */
  categorizeFile(filePath) {
    const relativePath = path.relative(this.rootDir, filePath);

    if (relativePath.includes('part1-foundation')) return 'foundation';
    if (relativePath.includes('part2-content-development')) return 'content-development';
    if (relativePath.includes('part3-engine-reference')) return 'engine-reference';
    if (relativePath.includes('part4-practical-guides')) return 'practical-guides';
    if (relativePath.includes('part5-advanced-topics')) return 'advanced-topics';
    if (relativePath.includes('part6-reference-materials')) return 'reference-materials';
    if (relativePath.includes('assets/examples')) return 'examples';

    return 'other';
  }

  /**
   * Check content age and freshness
   */
  checkContentAge() {
    const files = this.getContentFiles();
    const now = new Date();
    const analysis = {
      total: files.length,
      fresh: 0,
      aging: 0,
      stale: 0,
      critical: 0,
      files: []
    };

    files.forEach(file => {
      const ageInDays = (now - file.modified) / (1000 * 60 * 60 * 24);
      const agingStatus = this.getAgingStatus(ageInDays);

      const fileAnalysis = {
        ...file,
        ageInDays: Math.round(ageInDays),
        agingStatus: agingStatus,
        freshness: this.calculateFreshness(ageInDays, file.category),
        priority: this.getPriority(file.category),
        recommendations: this.getRecommendations(ageInDays, file.category)
      };

      analysis.files.push(fileAnalysis);
      analysis[agingStatus]++;
    });

    return analysis;
  }

  /**
   * Get aging status based on days
   */
  getAgingStatus(ageInDays) {
    if (ageInDays <= this.maxAge.critical) return 'fresh';
    if (ageInDays <= this.maxAge.warning) return 'aging';
    if (ageInDays <= this.maxAge.stale) return 'stale';
    return 'critical';
  }

  /**
   * Calculate freshness score for a file
   */
  calculateFreshness(ageInDays, category) {
    const maxAge = this.getCategoryMaxAge(category);
    const score = Math.max(0, 100 - (ageInDays / maxAge) * 100);
    return Math.round(score);
  }

  /**
   * Get maximum age threshold for category
   */
  getCategoryMaxAge(category) {
    const categoryAges = {
      'foundation': 120,           // Foundation docs change less frequently
      'content-development': 60,   // Content development needs regular updates
      'engine-reference': 90,      // Engine reference needs moderate updates
      'practical-guides': 45,      // Practical guides need frequent updates
      'advanced-topics': 90,       // Advanced topics need moderate updates
      'reference-materials': 120,  // Reference materials are more stable
      'examples': 30               // Examples should be very current
    };

    return categoryAges[category] || 90;
  }

  /**
   * Get priority based on category
   */
  getPriority(category) {
    const priorities = {
      'foundation': 'medium',
      'content-development': 'high',
      'engine-reference': 'high',
      'practical-guides': 'critical',
      'advanced-topics': 'medium',
      'reference-materials': 'low',
      'examples': 'critical'
    };

    return priorities[category] || 'medium';
  }

  /**
   * Get recommendations for file maintenance
   */
  getRecommendations(ageInDays, category) {
    const recommendations = [];

    if (ageInDays > this.maxAge.critical) {
      recommendations.push('Review content for accuracy');
      recommendations.push('Update examples and code snippets');
      recommendations.push('Verify all links are working');
    }

    if (ageInDays > this.maxAge.warning) {
      recommendations.push('Check for outdated information');
      recommendations.push('Update screenshots if applicable');
    }

    if (ageInDays > this.maxAge.stale) {
      recommendations.push('Complete content review required');
      recommendations.push('Consider restructuring or rewriting');
      recommendations.push('Update all references and dependencies');
    }

    if (category === 'examples' && ageInDays > 30) {
      recommendations.push('Test all code examples');
      recommendations.push('Update to latest API versions');
    }

    if (category === 'practical-guides' && ageInDays > 45) {
      recommendations.push('Walk through all tutorial steps');
      recommendations.push('Update with new features and best practices');
    }

    return recommendations;
  }

  /**
   * Calculate overall freshness score
   */
  calculateOverallFreshness(analysis) {
    if (analysis.total === 0) return 100;

    const weights = {
      fresh: 1.0,
      aging: 0.7,
      stale: 0.4,
      critical: 0.1
    };

    const weightedScore = (
      analysis.fresh * weights.fresh +
      analysis.aging * weights.aging +
      analysis.stale * weights.stale +
      analysis.critical * weights.critical
    ) / analysis.total;

    return Math.round(weightedScore * 100);
  }

  /**
   * Generate actionable recommendations
   */
  generateRecommendations(analysis) {
    const recommendations = [];

    if (analysis.critical > 0) {
      recommendations.push({
        priority: 'critical',
        action: `Immediately review ${analysis.critical} critical files`,
        description: 'These files are significantly outdated and may contain incorrect information'
      });
    }

    if (analysis.stale > 0) {
      recommendations.push({
        priority: 'high',
        action: `Review ${analysis.stale} stale files`,
        description: 'These files should be reviewed for accuracy and relevance'
      });
    }

    if (analysis.aging > 0) {
      recommendations.push({
        priority: 'medium',
        action: `Monitor ${analysis.aging} aging files`,
        description: 'These files are approaching staleness and should be reviewed soon'
      });
    }

    // Category-specific recommendations
    const categoryStats = this.getCategoryStatistics(analysis);
    Object.entries(categoryStats).forEach(([category, stats]) => {
      if (stats.avgAge > this.getCategoryMaxAge(category)) {
        recommendations.push({
          priority: this.getPriority(category),
          action: `Review ${category} content`,
          description: `${category} files have an average age of ${stats.avgAge} days`
        });
      }
    });

    return recommendations.sort((a, b) => {
      const priorityOrder = { critical: 4, high: 3, medium: 2, low: 1 };
      return priorityOrder[b.priority] - priorityOrder[a.priority];
    });
  }

  /**
   * Get statistics by category
   */
  getCategoryStatistics(analysis) {
    const categories = {};

    analysis.files.forEach(file => {
      if (!categories[file.category]) {
        categories[file.category] = {
          count: 0,
          totalAge: 0,
          avgAge: 0,
          freshness: 0
        };
      }

      categories[file.category].count++;
      categories[file.category].totalAge += file.ageInDays;
      categories[file.category].freshness += file.freshness;
    });

    Object.keys(categories).forEach(category => {
      const stats = categories[category];
      stats.avgAge = Math.round(stats.totalAge / stats.count);
      stats.freshness = Math.round(stats.freshness / stats.count);
    });

    return categories;
  }

  /**
   * Generate comprehensive freshness report
   */
  generateFreshnessReport() {
    const analysis = this.checkContentAge();
    const freshnessScore = this.calculateOverallFreshness(analysis);
    const recommendations = this.generateRecommendations(analysis);
    const categoryStats = this.getCategoryStatistics(analysis);

    const report = {
      timestamp: new Date().toISOString(),
      version: this.getHandbookVersion(),
      summary: {
        totalFiles: analysis.total,
        freshnessScore: freshnessScore,
        distribution: {
          fresh: analysis.fresh,
          aging: analysis.aging,
          stale: analysis.stale,
          critical: analysis.critical
        },
        percentages: {
          fresh: Math.round((analysis.fresh / analysis.total) * 100),
          aging: Math.round((analysis.aging / analysis.total) * 100),
          stale: Math.round((analysis.stale / analysis.total) * 100),
          critical: Math.round((analysis.critical / analysis.total) * 100)
        }
      },
      categoryStats: categoryStats,
      recommendations: recommendations,
      criticalFiles: analysis.files.filter(f => f.agingStatus === 'critical'),
      staleFiles: analysis.files.filter(f => f.agingStatus === 'stale'),
      agingFiles: analysis.files.filter(f => f.agingStatus === 'aging'),
      allFiles: analysis.files
    };

    return report;
  }

  /**
   * Get handbook version
   */
  getHandbookVersion() {
    try {
      const versionFile = path.join(this.rootDir, 'VERSION');
      return fs.readFileSync(versionFile, 'utf8').trim();
    } catch (error) {
      return '1.0.0';
    }
  }

  /**
   * Save report to file
   */
  saveReport(report) {
    const filename = `content-freshness-${new Date().toISOString().split('T')[0]}.json`;
    const filepath = path.join(this.reportsDir, filename);

    fs.writeFileSync(filepath, JSON.stringify(report, null, 2));
    return filepath;
  }

  /**
   * Generate HTML report
   */
  generateHTMLReport(report) {
    const html = `
<!DOCTYPE html>
<html>
<head>
    <title>Content Freshness Report</title>
    <style>
        body { font-family: system-ui, sans-serif; margin: 20px; }
        .header { background: #f8f9fa; padding: 20px; border-radius: 8px; margin-bottom: 20px; }
        .score { font-size: 48px; font-weight: bold; color: ${this.getScoreColor(report.summary.freshnessScore)}; }
        .grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 20px; }
        .card { background: white; border: 1px solid #ddd; border-radius: 8px; padding: 20px; }
        .metric { font-size: 24px; font-weight: bold; margin-bottom: 5px; }
        .critical { color: #dc3545; }
        .stale { color: #fd7e14; }
        .aging { color: #ffc107; }
        .fresh { color: #28a745; }
        .recommendation { background: #e9ecef; padding: 15px; margin: 10px 0; border-radius: 5px; }
        .file-list { max-height: 300px; overflow-y: auto; }
        .file-item { padding: 10px; border-bottom: 1px solid #eee; }
    </style>
</head>
<body>
    <div class="header">
        <h1>Content Freshness Report</h1>
        <p>Generated: ${new Date(report.timestamp).toLocaleString()}</p>
        <p>Version: ${report.version}</p>
        <div class="score">${report.summary.freshnessScore}%</div>
    </div>

    <div class="grid">
        <div class="card">
            <h2>Distribution</h2>
            <div class="metric fresh">${report.summary.distribution.fresh} Fresh (${report.summary.percentages.fresh}%)</div>
            <div class="metric aging">${report.summary.distribution.aging} Aging (${report.summary.percentages.aging}%)</div>
            <div class="metric stale">${report.summary.distribution.stale} Stale (${report.summary.percentages.stale}%)</div>
            <div class="metric critical">${report.summary.distribution.critical} Critical (${report.summary.percentages.critical}%)</div>
        </div>

        <div class="card">
            <h2>Recommendations</h2>
            ${report.recommendations.map(rec => `
                <div class="recommendation">
                    <strong>${rec.priority.toUpperCase()}:</strong> ${rec.action}<br>
                    <small>${rec.description}</small>
                </div>
            `).join('')}
        </div>

        <div class="card">
            <h2>Category Statistics</h2>
            ${Object.entries(report.categoryStats).map(([category, stats]) => `
                <div>
                    <strong>${category}:</strong> ${stats.count} files, ${stats.avgAge} days avg, ${stats.freshness}% fresh
                </div>
            `).join('')}
        </div>

        <div class="card">
            <h2>Critical Files</h2>
            <div class="file-list">
                ${report.criticalFiles.map(file => `
                    <div class="file-item">
                        <strong>${file.relativePath}</strong><br>
                        <small>${file.ageInDays} days old</small>
                    </div>
                `).join('')}
            </div>
        </div>
    </div>
</body>
</html>`;

    const filename = `content-freshness-${new Date().toISOString().split('T')[0]}.html`;
    const filepath = path.join(this.reportsDir, filename);

    fs.writeFileSync(filepath, html);
    return filepath;
  }

  /**
   * Get color for freshness score
   */
  getScoreColor(score) {
    if (score >= 85) return '#28a745';
    if (score >= 70) return '#ffc107';
    if (score >= 50) return '#fd7e14';
    return '#dc3545';
  }

  /**
   * Ensure directory exists
   */
  ensureDirectoryExists(dir) {
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
  }

  /**
   * Run complete freshness check
   */
  run() {
    console.log('🔍 Checking content freshness...');

    const report = this.generateFreshnessReport();
    const jsonPath = this.saveReport(report);
    const htmlPath = this.generateHTMLReport(report);

    console.log(`\n📊 Content Freshness Report`);
    console.log(`===============================`);
    console.log(`Overall Score: ${report.summary.freshnessScore}%`);
    console.log(`Total Files: ${report.summary.totalFiles}`);
    console.log(`Fresh: ${report.summary.distribution.fresh} (${report.summary.percentages.fresh}%)`);
    console.log(`Aging: ${report.summary.distribution.aging} (${report.summary.percentages.aging}%)`);
    console.log(`Stale: ${report.summary.distribution.stale} (${report.summary.percentages.stale}%)`);
    console.log(`Critical: ${report.summary.distribution.critical} (${report.summary.percentages.critical}%)`);
    console.log(`===============================`);

    if (report.recommendations.length > 0) {
      console.log(`\n🎯 Top Recommendations:`);
      report.recommendations.slice(0, 3).forEach((rec, i) => {
        console.log(`${i + 1}. [${rec.priority.toUpperCase()}] ${rec.action}`);
      });
    }

    console.log(`\n📄 Reports saved:`);
    console.log(`- JSON: ${jsonPath}`);
    console.log(`- HTML: ${htmlPath}`);

    return report;
  }
}

// CLI interface
if (require.main === module) {
  const checker = new ContentFreshnessChecker();
  const report = checker.run();

  // Exit with appropriate code
  if (report.summary.freshnessScore < 70) {
    process.exit(1);
  } else {
    process.exit(0);
  }
}

module.exports = ContentFreshnessChecker;

#!/usr/bin/env node

/**
 * Version Tracker - Content Authoring Handbook
 * Epic 8.3 Story 8.3.5 - Version Control and Updates
 * 
 * Tracks content changes, generates changelogs, and manages version metadata
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');
const crypto = require('crypto');

class VersionTracker {
  constructor() {
    this.rootDir = path.join(__dirname, '../..');
    this.versionFile = path.join(this.rootDir, 'VERSION');
    this.changelogFile = path.join(this.rootDir, 'CHANGELOG.md');
    this.metadataFile = path.join(this.rootDir, 'assets/data/version-metadata.json');

    this.initializeMetadata();
  }

  /**
   * Initialize version metadata file
   */
  initializeMetadata() {
    if (!fs.existsSync(this.metadataFile)) {
      const metadata = {
        version: this.getCurrentVersion(),
        lastUpdated: new Date().toISOString(),
        contentHash: this.generateContentHash(),
        buildNumber: 1,
        contributors: [],
        recentChanges: []
      };

      this.ensureDirectoryExists(path.dirname(this.metadataFile));
      fs.writeFileSync(this.metadataFile, JSON.stringify(metadata, null, 2));
    }
  }

  /**
   * Get current version from VERSION file
   */
  getCurrentVersion() {
    try {
      return fs.readFileSync(this.versionFile, 'utf8').trim();
    } catch (error) {
      return '1.0.0';
    }
  }

  /**
   * Update version number
   */
  updateVersion(type = 'patch') {
    const currentVersion = this.getCurrentVersion();
    const [major, minor, patch] = currentVersion.split('.').map(Number);

    let newVersion;
    switch (type) {
      case 'major':
        newVersion = `${major + 1}.0.0`;
        break;
      case 'minor':
        newVersion = `${major}.${minor + 1}.0`;
        break;
      case 'patch':
      default:
        newVersion = `${major}.${minor}.${patch + 1}`;
        break;
    }

    fs.writeFileSync(this.versionFile, newVersion);
    this.updateMetadata({ version: newVersion });

    console.log(`Version updated from ${currentVersion} to ${newVersion}`);
    return newVersion;
  }

  /**
   * Generate content hash for change detection
   */
  generateContentHash() {
    const contentDirs = [
      'part1-foundation',
      'part2-content-development',
      'part3-engine-reference',
      'part4-practical-guides',
      'part5-advanced-topics',
      'part6-reference-materials'
    ];

    let combinedContent = '';

    contentDirs.forEach(dir => {
      const dirPath = path.join(this.rootDir, dir);
      if (fs.existsSync(dirPath)) {
        const files = this.getMarkdownFiles(dirPath);
        files.forEach(file => {
          const content = fs.readFileSync(file, 'utf8');
          combinedContent += content;
        });
      }
    });

    return crypto.createHash('sha256').update(combinedContent).digest('hex');
  }

  /**
   * Get all markdown files in directory recursively
   */
  getMarkdownFiles(dir) {
    const files = [];
    const items = fs.readdirSync(dir);

    items.forEach(item => {
      const itemPath = path.join(dir, item);
      const stat = fs.statSync(itemPath);

      if (stat.isDirectory()) {
        files.push(...this.getMarkdownFiles(itemPath));
      } else if (item.endsWith('.md')) {
        files.push(itemPath);
      }
    });

    return files;
  }

  /**
   * Track content changes
   */
  trackChanges(filePath, changeDescription) {
    const metadata = this.getMetadata();
    const newHash = this.generateContentHash();

    if (metadata.contentHash !== newHash) {
      const change = {
        file: path.relative(this.rootDir, filePath),
        description: changeDescription,
        timestamp: new Date().toISOString(),
        author: this.getGitAuthor(),
        hash: newHash.substring(0, 8)
      };

      metadata.recentChanges.unshift(change);
      metadata.recentChanges = metadata.recentChanges.slice(0, 50); // Keep last 50 changes
      metadata.contentHash = newHash;
      metadata.lastUpdated = new Date().toISOString();

      this.updateMetadata(metadata);
      console.log(`Tracked change: ${change.file} - ${change.description}`);

      return change;
    }

    return null;
  }

  /**
   * Get Git author information
   */
  getGitAuthor() {
    try {
      const name = execSync('git config user.name', { encoding: 'utf8' }).trim();
      const email = execSync('git config user.email', { encoding: 'utf8' }).trim();
      return `${name} <${email}>`;
    } catch (error) {
      return 'Unknown Author';
    }
  }

  /**
   * Get version metadata
   */
  getMetadata() {
    try {
      return JSON.parse(fs.readFileSync(this.metadataFile, 'utf8'));
    } catch (error) {
      this.initializeMetadata();
      return JSON.parse(fs.readFileSync(this.metadataFile, 'utf8'));
    }
  }

  /**
   * Update version metadata
   */
  updateMetadata(updates) {
    const metadata = this.getMetadata();
    const updatedMetadata = { ...metadata, ...updates };

    fs.writeFileSync(this.metadataFile, JSON.stringify(updatedMetadata, null, 2));
  }

  /**
   * Add contributor to metadata
   */
  addContributor(contributor) {
    const metadata = this.getMetadata();

    if (!metadata.contributors.includes(contributor)) {
      metadata.contributors.push(contributor);
      this.updateMetadata(metadata);
      console.log(`Added contributor: ${contributor}`);
    }
  }

  /**
   * Generate changelog entry
   */
  generateChangelogEntry(version, changes) {
    const date = new Date().toISOString().split('T')[0];

    let entry = `## [${version}] - ${date}\n\n`;

    const changesByType = {
      'Added': [],
      'Changed': [],
      'Fixed': [],
      'Removed': []
    };

    changes.forEach(change => {
      const type = this.categorizeChange(change.description);
      changesByType[type].push(change);
    });

    Object.entries(changesByType).forEach(([type, typeChanges]) => {
      if (typeChanges.length > 0) {
        entry += `### ${type}\n`;
        typeChanges.forEach(change => {
          entry += `- ${change.description} (${change.file})\n`;
        });
        entry += '\n';
      }
    });

    return entry;
  }

  /**
   * Categorize change based on description
   */
  categorizeChange(description) {
    const desc = description.toLowerCase();

    if (desc.includes('add') || desc.includes('new') || desc.includes('create')) {
      return 'Added';
    } else if (desc.includes('fix') || desc.includes('bug') || desc.includes('error')) {
      return 'Fixed';
    } else if (desc.includes('remove') || desc.includes('delete')) {
      return 'Removed';
    } else {
      return 'Changed';
    }
  }

  /**
   * Update changelog with recent changes
   */
  updateChangelog() {
    const metadata = this.getMetadata();
    const recentChanges = metadata.recentChanges.slice(0, 10);

    if (recentChanges.length === 0) {
      console.log('No recent changes to add to changelog');
      return;
    }

    const version = metadata.version;
    const newEntry = this.generateChangelogEntry(version, recentChanges);

    // Read existing changelog
    let changelog = '';
    if (fs.existsSync(this.changelogFile)) {
      changelog = fs.readFileSync(this.changelogFile, 'utf8');
    }

    // Insert new entry after [Unreleased] section
    const unreleasedIndex = changelog.indexOf('## [Unreleased]');
    if (unreleasedIndex !== -1) {
      const afterUnreleased = changelog.indexOf('\n## [', unreleasedIndex + 1);
      if (afterUnreleased !== -1) {
        changelog = changelog.slice(0, afterUnreleased) + '\n' + newEntry + changelog.slice(afterUnreleased);
      } else {
        changelog += '\n' + newEntry;
      }
    } else {
      changelog = newEntry + '\n' + changelog;
    }

    fs.writeFileSync(this.changelogFile, changelog);
    console.log(`Updated changelog with ${recentChanges.length} changes`);
  }

  /**
   * Generate version info for builds
   */
  generateVersionInfo() {
    const metadata = this.getMetadata();

    return {
      version: metadata.version,
      buildNumber: metadata.buildNumber,
      buildDate: new Date().toISOString(),
      contentHash: metadata.contentHash,
      lastUpdated: metadata.lastUpdated,
      contributors: metadata.contributors.length
    };
  }

  /**
   * Increment build number
   */
  incrementBuildNumber() {
    const metadata = this.getMetadata();
    metadata.buildNumber = (metadata.buildNumber || 0) + 1;
    this.updateMetadata(metadata);

    console.log(`Build number incremented to ${metadata.buildNumber}`);
    return metadata.buildNumber;
  }

  /**
   * Ensure directory exists
   */
  ensureDirectoryExists(dir) {
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
  }

  /**
   * Get recent changes for notifications
   */
  getRecentChanges(limit = 10) {
    const metadata = this.getMetadata();
    return metadata.recentChanges.slice(0, limit);
  }

  /**
   * Check if content has changed since last build
   */
  hasContentChanged() {
    const metadata = this.getMetadata();
    const currentHash = this.generateContentHash();

    return metadata.contentHash !== currentHash;
  }
}

// CLI interface
if (require.main === module) {
  const tracker = new VersionTracker();
  const command = process.argv[2];

  switch (command) {
    case 'version':
      console.log(tracker.getCurrentVersion());
      break;

    case 'update':
      const type = process.argv[3] || 'patch';
      tracker.updateVersion(type);
      break;

    case 'track':
      const filePath = process.argv[3];
      const description = process.argv[4];
      if (filePath && description) {
        tracker.trackChanges(filePath, description);
      } else {
        console.log('Usage: node version-tracker.js track <file> <description>');
      }
      break;

    case 'changelog':
      tracker.updateChangelog();
      break;

    case 'build':
      const buildNumber = tracker.incrementBuildNumber();
      const versionInfo = tracker.generateVersionInfo();
      console.log(JSON.stringify(versionInfo, null, 2));
      break;

    case 'check':
      const hasChanged = tracker.hasContentChanged();
      console.log(hasChanged ? 'Content has changed' : 'No changes detected');
      process.exit(hasChanged ? 1 : 0);
      break;

    default:
      console.log('Usage: node version-tracker.js <command>');
      console.log('Commands:');
      console.log('  version              - Show current version');
      console.log('  update [type]        - Update version (patch/minor/major)');
      console.log('  track <file> <desc>  - Track content change');
      console.log('  changelog            - Update changelog');
      console.log('  build                - Increment build number and show version info');
      console.log('  check                - Check if content has changed');
      break;
  }
}

module.exports = VersionTracker;

/**
 * Text Processor Node - Example Extension Implementation
 * Demonstrates advanced node development patterns
 */

import { 
  AdvancedRuntimeNode, 
  IOSpecBuilder, 
  ValidationHelpers,
  ValidationResult,
  NodeState
} from '@prompt-spaghetti/core';

export interface TextProcessorOptions {
  operation: 'uppercase' | 'lowercase' | 'title' | 'reverse' | 'clean';
  preserveWhitespace: boolean;
  customPattern?: string;
  replaceWith?: string;
}

export interface TextProcessorState extends NodeState {
  processedCount: number;
  totalCharacters: number;
  operationHistory: string[];
}

export class TextProcessorNode extends AdvancedRuntimeNode {
  protected getIOSpec() {
    return new IOSpecBuilder()
      .input('text', 'string')
        .required()
        .description('Text to process')
        .constraint(ValidationHelpers.lengthConstraint(1, 10000))
      .input('operation', 'string')
        .required()
        .description('Processing operation to perform')
        .constraint(ValidationHelpers.customConstraint(
          (value) => ['uppercase', 'lowercase', 'title', 'reverse', 'clean'].includes(value)
        ))
      .input('options', 'object')
        .optional()
        .defaultValue({})
        .description('Additional processing options')
      .output('result', 'string')
        .description('Processed text')
      .output('metadata', 'object')
        .description('Processing metadata and statistics')
      .build();
  }

  protected initializeState(): TextProcessorState {
    return {
      processedCount: 0,
      totalCharacters: 0,
      operationHistory: []
    };
  }

  protected validateInputs(inputs: any): ValidationResult {
    const errors: string[] = [];

    // Validate text input
    if (!ValidationHelpers.isString(inputs.text)) {
      errors.push('Text input must be a string');
    } else if (inputs.text.length === 0) {
      errors.push('Text input cannot be empty');
    } else if (inputs.text.length > 10000) {
      errors.push('Text input is too long (max 10,000 characters)');
    }

    // Validate operation
    const validOperations = ['uppercase', 'lowercase', 'title', 'reverse', 'clean'];
    if (!validOperations.includes(inputs.operation)) {
      errors.push(`Invalid operation. Must be one of: ${validOperations.join(', ')}`);
    }

    // Validate options if provided
    if (inputs.options && !ValidationHelpers.isObject(inputs.options)) {
      errors.push('Options must be an object');
    }

    return {
      valid: errors.length === 0,
      errors
    };
  }

  protected async executeImplementation(inputs: any): Promise<any> {
    const startTime = performance.now();

    const text = inputs.text as string;
    const operation = inputs.operation as string;
    const options = inputs.options as Partial<TextProcessorOptions> || {};

    // Process text based on operation
    let result: string;

    try {
      result = await this.processText(text, operation, options);
    } catch (error) {
      throw new Error(`Text processing failed: ${error.message}`);
    }

    // Update state
    const currentState = this.getState() as TextProcessorState;
    this.updateState({
      processedCount: currentState.processedCount + 1,
      totalCharacters: currentState.totalCharacters + text.length,
      operationHistory: [...currentState.operationHistory.slice(-9), operation] // Keep last 10
    });

    // Generate metadata
    const processingTime = performance.now() - startTime;
    const metadata = {
      operation,
      originalLength: text.length,
      resultLength: result.length,
      processingTime: Math.round(processingTime * 100) / 100,
      charactersDiff: result.length - text.length,
      totalProcessed: (this.getState() as TextProcessorState).processedCount,
      operationHistory: (this.getState() as TextProcessorState).operationHistory
    };

    return { result, metadata };
  }

  private async processText(
    text: string, 
    operation: string, 
    options: Partial<TextProcessorOptions>
  ): Promise<string> {

    switch (operation) {
      case 'uppercase':
        return this.processUppercase(text, options);

      case 'lowercase':
        return this.processLowercase(text, options);

      case 'title':
        return this.processTitleCase(text, options);

      case 'reverse':
        return this.processReverse(text, options);

      case 'clean':
        return this.processClean(text, options);

      default:
        throw new Error(`Unsupported operation: ${operation}`);
    }
  }

  private processUppercase(text: string, options: Partial<TextProcessorOptions>): string {
    if (options.preserveWhitespace === false) {
      return text.replace(/\s+/g, ' ').trim().toUpperCase();
    }
    return text.toUpperCase();
  }

  private processLowercase(text: string, options: Partial<TextProcessorOptions>): string {
    if (options.preserveWhitespace === false) {
      return text.replace(/\s+/g, ' ').trim().toLowerCase();
    }
    return text.toLowerCase();
  }

  private processTitleCase(text: string, options: Partial<TextProcessorOptions>): string {
    let result = text.toLowerCase().replace(/\b\w/g, l => l.toUpperCase());

    if (options.preserveWhitespace === false) {
      result = result.replace(/\s+/g, ' ').trim();
    }

    return result;
  }

  private processReverse(text: string, options: Partial<TextProcessorOptions>): string {
    if (options.preserveWhitespace === false) {
      // Reverse words, not characters
      return text.trim().split(/\s+/).reverse().join(' ');
    }

    // Reverse characters
    return text.split('').reverse().join('');
  }

  private processClean(text: string, options: Partial<TextProcessorOptions>): string {
    let result = text;

    // Remove extra whitespace
    result = result.replace(/\s+/g, ' ').trim();

    // Apply custom pattern if provided
    if (options.customPattern && options.replaceWith !== undefined) {
      try {
        const regex = new RegExp(options.customPattern, 'g');
        result = result.replace(regex, options.replaceWith);
      } catch (error) {
        throw new Error(`Invalid regex pattern: ${options.customPattern}`);
      }
    }

    // Remove common unwanted characters
    result = result.replace(/[^\w\s\.\,\!\?\-]/g, '');

    return result;
  }

  // Override state change handler for logging
  protected onStateChange(newState: TextProcessorState, oldState: TextProcessorState): void {
    if (newState.processedCount > oldState.processedCount) {
      console.log(`TextProcessor: Processed ${newState.processedCount} texts, ${newState.totalCharacters} total characters`);
    }
  }

  // Static method for node information
  static getNodeInfo() {
    return {
      type: 'TextProcessorNode',
      displayName: 'Text Processor',
      description: 'Advanced text processing with multiple transformation options',
      category: 'Text Processing',
      icon: '📝',
      version: '1.0.0',
      author: 'PromptSpaghetti Team',
      documentation: 'https://docs.prompt-spaghetti.dev/nodes/text-processor',
      examples: [
        {
          name: 'Convert to uppercase',
          inputs: {
            text: 'hello world',
            operation: 'uppercase'
          },
          expectedOutput: {
            result: 'HELLO WORLD'
          }
        },
        {
          name: 'Title case with whitespace cleaning',
          inputs: {
            text: 'hello   world   example',
            operation: 'title',
            options: { preserveWhitespace: false }
          },
          expectedOutput: {
            result: 'Hello World Example'
          }
        }
      ],
      performance: {
        averageExecutionTime: '< 1ms',
        memoryUsage: 'Low',
        scalability: 'Excellent'
      }
    };
  }
}

