import React, { useState, useEffect, useCallback } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/Card';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../ui/Select';
import { Badge } from '../ui/Badge';
import { Button } from '../ui/Button';
import { AnalyticsClient } from '../../analytics/AnalyticsClient';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, BarChart, Bar, Area, AreaChart, Legend } from 'recharts';
import { TrendingUp, TrendingDown, Activity, Zap, Clock, AlertTriangle } from 'lucide-react';

/**
 * Time series chart props
 */
interface TimeSeriesChartProps {
  data: any[];
  title: string;
  metric: string;
  unit: string;
  color: string;
  loading: boolean;
  error?: string;
}

/**
 * Time series chart component
 */
const TimeSeriesChart: React.FC<TimeSeriesChartProps> = ({
  data,
  title,
  metric,
  unit,
  color,
  loading,
  error
}) => {
  const formatValue = (value: number) => {
    if (unit === 'ms') {
      return value < 1000 ? `${value}ms` : `${(value / 1000).toFixed(1)}s`;
    }
    if (unit === 'currency') {
      return new Intl.NumberFormat('en-US', {
        style: 'currency',
        currency: 'USD',
        minimumFractionDigits: 2
      }).format(value);
    }
    if (value >= 1000000) {
      return `${(value / 1000000).toFixed(1)}M`;
    }
    if (value >= 1000) {
      return `${(value / 1000).toFixed(1)}K`;
    }
    return value.toLocaleString();
  };

  const formatXAxis = (timestamp: number) => {
    const date = new Date(timestamp);
    return date.toLocaleDateString() + ' ' + date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  if (loading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="text-sm text-gray-600">{title}</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="h-64 flex items-center justify-center">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-500"></div>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (error) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="text-sm text-gray-600">{title}</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="h-64 flex items-center justify-center text-red-500">
            <AlertTriangle className="w-5 h-5 mr-2" />
            {error}
          </div>
        </CardContent>
      </Card>
    );
  }

  if (!data || data.length === 0) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="text-sm text-gray-600">{title}</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="h-64 flex items-center justify-center text-gray-500">
            No data available
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-sm text-gray-600">{title}</CardTitle>
      </CardHeader>
      <CardContent>
        <div className="h-64">
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={data}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis
                dataKey="timestamp"
                tickFormatter={formatXAxis}
                fontSize={12}
                tick={{ fill: '#6B7280' }}
              />
              <YAxis
                tickFormatter={formatValue}
                fontSize={12}
                tick={{ fill: '#6B7280' }}
              />
              <Tooltip
                formatter={(value: number) => [formatValue(value), metric]}
                labelFormatter={(timestamp: number) => formatXAxis(timestamp)}
                contentStyle={{
                  backgroundColor: '#1F2937',
                  border: 'none',
                  borderRadius: '8px',
                  color: '#F9FAFB'
                }}
              />
              <Line
                type="monotone"
                dataKey="value"
                stroke={color}
                strokeWidth={2}
                dot={{ fill: color, strokeWidth: 2, r: 4 }}
                activeDot={{ r: 6 }}
              />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </CardContent>
    </Card>
  );
};

/**
 * Performance charts props
 */
export interface PerformanceChartsProps {
  analyticsClient: AnalyticsClient;
  timeRange: { startTime: number; endTime: number };
  userId?: number;
  organizationId?: number;
}

/**
 * Performance charts state
 */
interface PerformanceChartsState {
  executionsData: any[];
  tokensData: any[];
  costData: any[];
  errorsData: any[];
  granularity: 'hour' | 'day';
  loading: {
    executions: boolean;
    tokens: boolean;
    cost: boolean;
    errors: boolean;
  };
  errors: {
    executions?: string;
    tokens?: string;
    cost?: string;
    errors?: string;
  };
}

/**
 * Performance charts component
 */
export const PerformanceCharts: React.FC<PerformanceChartsProps> = ({
  analyticsClient,
  timeRange,
  userId,
  organizationId
}) => {
  const [state, setState] = useState<PerformanceChartsState>({
    executionsData: [],
    tokensData: [],
    costData: [],
    errorsData: [],
    granularity: 'hour',
    loading: {
      executions: true,
      tokens: true,
      cost: true,
      errors: true
    },
    errors: {}
  });

  /**
   * Load chart data
   */
  const loadChartData = useCallback(async () => {
    const metrics = ['executions', 'tokens', 'cost', 'errors'] as const;

    setState(prev => ({
      ...prev,
      loading: {
        executions: true,
        tokens: true,
        cost: true,
        errors: true
      },
      errors: {}
    }));

    // Load all metrics in parallel
    const results = await Promise.allSettled(
      metrics.map(metric =>
        analyticsClient.getTimeSeries(metric, {
          ...timeRange,
          granularity: state.granularity
        })
      )
    );

    const newState = {
      executionsData: [],
      tokensData: [],
      costData: [],
      errorsData: [],
      loading: {
        executions: false,
        tokens: false,
        cost: false,
        errors: false
      },
      errors: {}
    };

    results.forEach((result, index) => {
      const metric = metrics[index];

      if (result.status === 'fulfilled' && result.value.success) {
        const data = result.value.data.dataPoints || [];
        switch (metric) {
          case 'executions':
            newState.executionsData = data;
            break;
          case 'tokens':
            newState.tokensData = data;
            break;
          case 'cost':
            newState.costData = data;
            break;
          case 'errors':
            newState.errorsData = data;
            break;
        }
      } else {
        const error = result.status === 'rejected' 
          ? result.reason.message 
          : 'Failed to load data';
        newState.errors[metric] = error;
      }
    });

    setState(prev => ({
      ...prev,
      ...newState
    }));
  }, [analyticsClient, timeRange, state.granularity]);

  /**
   * Handle granularity change
   */
  const handleGranularityChange = useCallback((newGranularity: 'hour' | 'day') => {
    setState(prev => ({ ...prev, granularity: newGranularity }));
  }, []);

  /**
   * Calculate trend
   */
  const calculateTrend = useCallback((data: any[]) => {
    if (data.length < 2) return null;

    const recent = data.slice(-Math.floor(data.length / 2));
    const earlier = data.slice(0, Math.floor(data.length / 2));

    const recentAvg = recent.reduce((sum, d) => sum + d.value, 0) / recent.length;
    const earlierAvg = earlier.reduce((sum, d) => sum + d.value, 0) / earlier.length;

    if (earlierAvg === 0) return null;

    const change = ((recentAvg - earlierAvg) / earlierAvg) * 100;
    return {
      direction: change > 5 ? 'up' : change < -5 ? 'down' : 'stable',
      value: Math.abs(change),
