// Epic 9.4.2 - Approval Dashboard Component
// Comprehensive dashboard for managing approval requests and reviews

import React, { useState, useEffect } from 'react';
import { 
  ClockIcon,
  CheckCircleIcon,
  XCircleIcon,
  ExclamationTriangleIcon,
  UserGroupIcon,
  DocumentTextIcon,
  FunnelIcon,
  MagnifyingGlassIcon,
  ChevronDownIcon,
  ChevronUpIcon,
  CalendarIcon,
  ArrowPathIcon,
  BellIcon,
  ChatBubbleLeftIcon,
  EyeIcon,
  PencilIcon
} from '@heroicons/react/24/outline';

interface ApprovalRequest {
  id: string;
  workspace_id: string;
  resource_id: string;
  rule_id: string;
  transition_id: string;
  requester_id: string;
  title: string;
  description?: string;
  urgency: 'low' | 'medium' | 'high' | 'critical';
  business_justification?: string;
  status: 'pending' | 'in_review' | 'approved' | 'rejected' | 'cancelled' | 'expired';
  requested_at: Date;
  due_date?: Date;
  completed_at?: Date;
  current_approvals: number;
  required_approvals: number;
  approval_percentage: number;
  escalated_at?: Date;
  escalation_reason?: string;
}

interface ReviewerAssignment {
  id: string;
  approval_request_id: string;
  reviewer_id: string;
  assignment_type: 'primary' | 'secondary' | 'escalated';
  assignment_reason?: string;
  assigned_at: Date;
  status: 'pending' | 'reviewing' | 'approved' | 'rejected' | 'abstained';
  reviewed_at?: Date;
  review_comment?: string;
  criteria_evaluations: Record<string, any>;
}

interface ApprovalDashboardProps {
  workspaceId: string;
  currentUserId: string;
  mode?: 'reviewer' | 'requester' | 'admin';
}

export const ApprovalDashboard: React.FC<ApprovalDashboardProps> = ({
  workspaceId,
  currentUserId,
  mode = 'reviewer'
}) => {
  const [approvalRequests, setApprovalRequests] = useState<ApprovalRequest[]>([]);
  const [reviewerAssignments, setReviewerAssignments] = useState<Record<string, ReviewerAssignment[]>>({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedRequest, setSelectedRequest] = useState<ApprovalRequest | null>(null);
  const [activeTab, setActiveTab] = useState<'pending' | 'completed' | 'all'>('pending');
  const [expandedRequests, setExpandedRequests] = useState<Set<string>>(new Set());

  const [filters, setFilters] = useState({
    status: '',
    urgency: '',
    overdue: false,
    search: ''
  });

  const [sortBy, setSortBy] = useState<'requested_at' | 'due_date' | 'urgency' | 'approval_percentage'>('requested_at');
  const [sortDirection, setSortDirection] = useState<'asc' | 'desc'>('desc');

  // Load approval requests
  useEffect(() => {
    fetchApprovalRequests();
  }, [workspaceId, currentUserId, mode, filters, activeTab]);

  const fetchApprovalRequests = async () => {
    try {
      setLoading(true);

      const queryParams = new URLSearchParams();
      if (mode === 'reviewer') {
        queryParams.append('reviewer_id', currentUserId);
      } else if (mode === 'requester') {
        queryParams.append('requester_id', currentUserId);
      }

      if (activeTab === 'pending') {
        queryParams.append('status', 'pending,in_review');
      } else if (activeTab === 'completed') {
        queryParams.append('status', 'approved,rejected,cancelled,expired');
      }

      if (filters.status) queryParams.append('status', filters.status);
      if (filters.urgency) queryParams.append('urgency', filters.urgency);
      if (filters.overdue) queryParams.append('overdue', 'true');

      const response = await fetch(`/api/approval/requests/${workspaceId}?${queryParams}`);

      if (!response.ok) {
        throw new Error('Failed to fetch approval requests');
      }

      const requests = await response.json();
      setApprovalRequests(requests);

      // Load reviewer assignments for each request
      const assignments: Record<string, ReviewerAssignment[]> = {};
      for (const request of requests) {
        const reviewersResponse = await fetch(`/api/approval/requests/${request.id}/reviewers`);
        if (reviewersResponse.ok) {
          assignments[request.id] = await reviewersResponse.json();
        }
      }
      setReviewerAssignments(assignments);

    } catch (error) {
      setError(error instanceof Error ? error.message : 'Failed to fetch approval requests');
    } finally {
      setLoading(false);
    }
  };

  const handleReviewSubmission = async (
    requestId: string,
    decision: 'approve' | 'reject' | 'abstain',
    comment?: string
  ) => {
    try {
      const response = await fetch(`/api/approval/requests/${requestId}/review`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-user-id': currentUserId
        },
        body: JSON.stringify({
          decision,
          comment
        })
      });

      if (!response.ok) {
        throw new Error('Failed to submit review');
      }

      // Refresh the data
      await fetchApprovalRequests();
    } catch (error) {
      setError(error instanceof Error ? error.message : 'Failed to submit review');
    }
  };

  const getUrgencyColor = (urgency: string) => {
    switch (urgency) {
      case 'critical': return 'bg-red-100 text-red-800';
      case 'high': return 'bg-orange-100 text-orange-800';
      case 'medium': return 'bg-yellow-100 text-yellow-800';
      case 'low': return 'bg-green-100 text-green-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'pending': return 'bg-yellow-100 text-yellow-800';
      case 'in_review': return 'bg-blue-100 text-blue-800';
      case 'approved': return 'bg-green-100 text-green-800';
      case 'rejected': return 'bg-red-100 text-red-800';
      case 'cancelled': return 'bg-gray-100 text-gray-800';
      case 'expired': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'pending': return <ClockIcon className="h-4 w-4" />;
      case 'in_review': return <EyeIcon className="h-4 w-4" />;
      case 'approved': return <CheckCircleIcon className="h-4 w-4" />;
      case 'rejected': return <XCircleIcon className="h-4 w-4" />;
      case 'cancelled': return <XCircleIcon className="h-4 w-4" />;
      case 'expired': return <ExclamationTriangleIcon className="h-4 w-4" />;
      default: return <ClockIcon className="h-4 w-4" />;
    }
  };

  const isOverdue = (request: ApprovalRequest) => {
    return request.due_date && new Date(request.due_date) < new Date() && 
           ['pending', 'in_review'].includes(request.status);
  };

  const canReview = (request: ApprovalRequest) => {
    const assignment = reviewerAssignments[request.id]?.find(a => a.reviewer_id === currentUserId);
    return assignment && assignment.status === 'pending' && 
           ['pending', 'in_review'].includes(request.status);
  };

  const toggleRequestExpansion = (requestId: string) => {
    const newExpanded = new Set(expandedRequests);
    if (newExpanded.has(requestId)) {
      newExpanded.delete(requestId);
    } else {
      newExpanded.add(requestId);
    }
    setExpandedRequests(newExpanded);
  };

  const filteredAndSortedRequests = approvalRequests
    .filter(request => {
      if (filters.search && !request.title.toLowerCase().includes(filters.search.toLowerCase())) {
        return false;
      }
      return true;
    })
    .sort((a, b) => {
      const multiplier = sortDirection === 'asc' ? 1 : -1;
      switch (sortBy) {
        case 'requested_at':
          return (new Date(a.requested_at).getTime() - new Date(b.requested_at).getTime()) * multiplier;
        case 'due_date':
          const aDate = a.due_date ? new Date(a.due_date).getTime() : 0;
          const bDate = b.due_date ? new Date(b.due_date).getTime() : 0;
          return (aDate - bDate) * multiplier;
        case 'urgency':
          const urgencyOrder = { low: 1, medium: 2, high: 3, critical: 4 };
          return (urgencyOrder[a.urgency] - urgencyOrder[b.urgency]) * multiplier;
        case 'approval_percentage':
          return (a.approval_percentage - b.approval_percentage) * multiplier;
        default:
          return 0;
      }
    });

  if (loading) {
    return (
      <div className="flex items-center justify-center p-8">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-50 border border-red-200 rounded-md p-4">
        <div className="flex">
          <XCircleIcon className="h-5 w-5 text-red-400" />
          <div className="ml-3">
            <h3 className="text-sm font-medium text-red-800">Error</h3>
            <div className="mt-2 text-sm text-red-700">{error}</div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-lg shadow">
      {/* Header */}
      <div className="border-b border-gray-200">
        <div className="px-6 py-4">
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-lg font-medium text-gray-900">
                {mode === 'reviewer' ? 'Review Dashboard' : 
                 mode === 'requester' ? 'My Requests' : 'Approval Management'}
              </h2>
              <p className="mt-1 text-sm text-gray-600">
                {mode === 'reviewer' ? 'Approval requests requiring your review' :
                 mode === 'requester' ? 'Your approval requests and their status' :
                 'Manage all approval requests in this workspace'}
              </p>
            </div>
            <div className="flex items-center space-x-3">
              <button
                onClick={fetchApprovalRequests}
                className="inline-flex items-center px-3 py-2 border border-gray-300 shadow-sm text-sm leading-4 font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50"
              >
                <ArrowPathIcon className="h-4 w-4 mr-2" />
                Refresh
              </button>
            </div>
          </div>
        </div>

        {/* Tab Navigation */}
        <div className="flex space-x-8 px-6">
          {[
            { id: 'pending', label: 'Pending', count: approvalRequests.filter(r => ['pending', 'in_review'].includes(r.status)).length },
            { id: 'completed', label: 'Completed', count: approvalRequests.filter(r => ['approved', 'rejected', 'cancelled', 'expired'].includes(r.status)).length },
            { id: 'all', label: 'All', count: approvalRequests.length }
          ].map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`py-2 px-1 border-b-2 font-medium text-sm ${
                activeTab === tab.id
                  ? 'border-blue-500 text-blue-600'
                  : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
              }`}
            >
              {tab.label}
              <span className={`ml-2 px-2 py-1 rounded-full text-xs ${
                activeTab === tab.id
                  ? 'bg-blue-100 text-blue-600'
                  : 'bg-gray-100 text-gray-600'
              }`}>
                {tab.count}
              </span>
            </button>
          ))}
        </div>
      </div>

      {/* Filters */}
      <div className="border-b border-gray-200 p-4">
        <div className="flex flex-wrap items-center gap-4">
          <div className="flex items-center space-x-2">
            <MagnifyingGlassIcon className="h-4 w-4 text-gray-400" />
            <input
              type="text"
              placeholder="Search requests..."
              value={filters.search}
              onChange={(e) => setFilters(prev => ({ ...prev, search: e.target.value }))}
              className="border border-gray-300 rounded-md px-3 py-1 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          <select
            value={filters.urgency}
            onChange={(e) => setFilters(prev => ({ ...prev, urgency: e.target.value }))}
            className="border border-gray-300 rounded-md px-3 py-1 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
          >
            <option value="">All Urgency</option>
            <option value="critical">Critical</option>
            <option value="high">High</option>
            <option value="medium">Medium</option>
            <option value="low">Low</option>
          </select>

          <label className="flex items-center space-x-2">
            <input
              type="checkbox"
              checked={filters.overdue}
              onChange={(e) => setFilters(prev => ({ ...prev, overdue: e.target.checked }))}
              className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
            />
            <span className="text-sm text-gray-700">Overdue only</span>
          </label>

          <div className="flex items-center space-x-2">
            <span className="text-sm text-gray-700">Sort by:</span>
            <select
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value as any)}
              className="border border-gray-300 rounded-md px-3 py-1 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
            >
              <option value="requested_at">Requested Date</option>
              <option value="due_date">Due Date</option>
              <option value="urgency">Urgency</option>
              <option value="approval_percentage">Progress</option>
            </select>
            <button
              onClick={() => setSortDirection(prev => prev === 'asc' ? 'desc' : 'asc')}
              className="p-1 rounded hover:bg-gray-100"
            >
              {sortDirection === 'asc' ? <ChevronUpIcon className="h-4 w-4" /> : <ChevronDownIcon className="h-4 w-4" />}
            </button>
          </div>
        </div>
      </div>

      {/* Request List */}
      <div className="divide-y divide-gray-200">
        {filteredAndSortedRequests.length === 0 ? (
          <div className="text-center py-12">
            <DocumentTextIcon className="mx-auto h-12 w-12 text-gray-400" />
            <h3 className="mt-2 text-sm font-medium text-gray-900">No approval requests</h3>
            <p className="mt-1 text-sm text-gray-500">
              {activeTab === 'pending' ? 'No pending approvals at this time.' : 
               activeTab === 'completed' ? 'No completed approvals found.' : 
               'No approval requests match your current filters.'}
            </p>
          </div>
        ) : (
          filteredAndSortedRequests.map((request) => (
            <div key={request.id} className="p-6 hover:bg-gray-50">
              <div className="flex items-start justify-between">
                <div className="flex-1">
                  <div className="flex items-center space-x-3">
                    <button
                      onClick={() => toggleRequestExpansion(request.id)}
                      className="text-gray-400 hover:text-gray-600"
                    >
                      {expandedRequests.has(request.id) ? (
                        <ChevronDownIcon className="h-4 w-4" />
                      ) : (
                        <ChevronUpIcon className="h-4 w-4" />
                      )}
                    </button>
                    <h3 className="text-lg font-medium text-gray-900">
                      {request.title}
                    </h3>
                    <div className="flex items-center space-x-2">
                      <span className={`inline-flex items-center px-2 py-1 rounded-full text-xs font-medium ${getStatusColor(request.status)}`}>
                        {getStatusIcon(request.status)}
                        <span className="ml-1">{request.status}</span>
                      </span>
                      <span className={`inline-flex items-center px-2 py-1 rounded-full text-xs font-medium ${getUrgencyColor(request.urgency)}`}>
                        {request.urgency}
                      </span>
                      {isOverdue(request) && (
                        <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-red-100 text-red-800">
                          <ExclamationTriangleIcon className="h-3 w-3 mr-1" />
                          Overdue
                        </span>
                      )}
                      {request.escalated_at && (
                        <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-orange-100 text-orange-800">
                          <BellIcon className="h-3 w-3 mr-1" />
                          Escalated
                        </span>
                      )}
                    </div>
                  </div>

                  <div className="mt-2 flex items-center space-x-6 text-sm text-gray-600">
                    <div className="flex items-center space-x-1">
                      <CalendarIcon className="h-4 w-4" />
                      <span>Requested {new Date(request.requested_at).toLocaleDateString()}</span>
                    </div>
                    {request.due_date && (
                      <div className="flex items-center space-x-1">
                        <ClockIcon className="h-4 w-4" />
                        <span>Due {new Date(request.due_date).toLocaleDateString()}</span>
                      </div>
                    )}
                    <div className="flex items-center space-x-1">
                      <UserGroupIcon className="h-4 w-4" />
                      <span>By {request.requester_id}</span>
                    </div>
                  </div>

                  {/* Progress Bar */}
                  <div className="mt-3">
                    <div className="flex items-center justify-between text-sm">
                      <span className="text-gray-600">
                        Approval Progress: {request.current_approvals} of {request.required_approvals}
                      </span>
                      <span className="text-gray-600">{Math.round(request.approval_percentage)}%</span>
                    </div>
                    <div className="mt-1 w-full bg-gray-200 rounded-full h-2">
                      <div 
                        className="bg-blue-600 h-2 rounded-full transition-all duration-300"
                        style={{ width: `${request.approval_percentage}%` }}
                      />
                    </div>
                  </div>
                </div>

                {/* Actions */}
                <div className="flex items-center space-x-2 ml-4">
                  {canReview(request) && (
                    <div className="flex items-center space-x-2">
                      <button
                        onClick={() => handleReviewSubmission(request.id, 'approve')}
                        className="px-3 py-1 bg-green-600 text-white text-sm rounded hover:bg-green-700"
                      >
                        <CheckCircleIcon className="h-4 w-4 mr-1 inline" />
                        Approve
                      </button>
                      <button
                        onClick={() => handleReviewSubmission(request.id, 'reject')}
                        className="px-3 py-1 bg-red-600 text-white text-sm rounded hover:bg-red-700"
                      >
                        <XCircleIcon className="h-4 w-4 mr-1 inline" />
                        Reject
                      </button>
                    </div>
                  )}
                  <button
                    onClick={() => setSelectedRequest(request)}
                    className="px-3 py-1 bg-blue-600 text-white text-sm rounded hover:bg-blue-700"
                  >
                    <EyeIcon className="h-4 w-4 mr-1 inline" />
                    View Details
                  </button>
                </div>
              </div>

              {/* Expanded Details */}
              {expandedRequests.has(request.id) && (
                <div className="mt-4 space-y-4">
                  {request.description && (
                    <div>
                      <h4 className="text-sm font-medium text-gray-900 mb-2">Description</h4>
                      <p className="text-sm text-gray-700">{request.description}</p>
                    </div>
                  )}

                  {request.business_justification && (
                    <div>
                      <h4 className="text-sm font-medium text-gray-900 mb-2">Business Justification</h4>
                      <p className="text-sm text-gray-700">{request.business_justification}</p>
                    </div>
                  )}

                  {/* Reviewers */}
                  <div>
                    <h4 className="text-sm font-medium text-gray-900 mb-2">Reviewers</h4>
                    <div className="space-y-2">
                      {reviewerAssignments[request.id]?.map((assignment) => (
                        <div key={assignment.id} className="flex items-center justify-between p-2 bg-gray-50 rounded">
                          <div className="flex items-center space-x-3">
                            <span className="text-sm font-medium">{assignment.reviewer_id}</span>
                            <span className={`px-2 py-1 rounded text-xs ${getStatusColor(assignment.status)}`}>
                              {assignment.status}
                            </span>
                            <span className={`px-2 py-1 rounded text-xs ${
                              assignment.assignment_type === 'escalated' ? 'bg-orange-100 text-orange-800' : 'bg-gray-100 text-gray-800'
                            }`}>
                              {assignment.assignment_type}
                            </span>
                          </div>
                          {assignment.reviewed_at && (
                            <span className="text-xs text-gray-500">
                              Reviewed {new Date(assignment.reviewed_at).toLocaleDateString()}
                            </span>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              )}
            </div>
          ))
        )}
      </div>
    </div>
  );
};

// Epic 9.4.2 - Approval Review Interface Component
// Detailed interface for reviewing approval requests with diff view

import React, { useState, useEffect } from 'react';
import { 
  CheckCircleIcon,
  XCircleIcon,
  EyeIcon,
  ChatBubbleLeftIcon,
  ClockIcon,
  ExclamationTriangleIcon,
  UserIcon,
  DocumentTextIcon,
  ArrowRightIcon,
  ChevronDownIcon,
  ChevronRightIcon,
  StarIcon,
  ClipboardDocumentListIcon
} from '@heroicons/react/24/outline';

interface ApprovalCriteria {
  id: string;
  name: string;
  description?: string;
  weight: number;
  is_required: boolean;
  conditions: Record<string, any>;
}

interface ApprovalRequest {
  id: string;
  workspace_id: string;
  resource_id: string;
  transition_id: string;
  requester_id: string;
  title: string;
  description?: string;
  urgency: 'low' | 'medium' | 'high' | 'critical';
  business_justification?: string;
  status: 'pending' | 'in_review' | 'approved' | 'rejected' | 'cancelled' | 'expired';
  requested_at: Date;
  due_date?: Date;
  current_approvals: number;
  required_approvals: number;
  approval_percentage: number;
}

interface ReviewerAssignment {
  id: string;
  reviewer_id: string;
  assignment_type: 'primary' | 'secondary' | 'escalated';
  status: 'pending' | 'reviewing' | 'approved' | 'rejected' | 'abstained';
  reviewed_at?: Date;
  review_comment?: string;
  criteria_evaluations: Record<string, any>;
}

interface ApprovalReviewInterfaceProps {
  request: ApprovalRequest;
  workspaceId: string;
  currentUserId: string;
  onReviewSubmit: (decision: 'approve' | 'reject' | 'abstain', comment?: string, criteriaEvaluations?: Record<string, any>) => void;
  onClose: () => void;
  readOnly?: boolean;
}

export const ApprovalReviewInterface: React.FC<ApprovalReviewInterfaceProps> = ({
  request,
  workspaceId,
  currentUserId,
  onReviewSubmit,
  onClose,
  readOnly = false
}) => {
  const [reviewerAssignments, setReviewerAssignments] = useState<ReviewerAssignment[]>([]);
  const [approvalCriteria, setApprovalCriteria] = useState<ApprovalCriteria[]>([]);
  const [selectedDecision, setSelectedDecision] = useState<'approve' | 'reject' | 'abstain' | null>(null);
  const [reviewComment, setReviewComment] = useState('');
  const [criteriaEvaluations, setCriteriaEvaluations] = useState<Record<string, any>>({});
  const [expandedSections, setExpandedSections] = useState<Set<string>>(new Set(['overview', 'criteria']));
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Current user's assignment
  const currentUserAssignment = reviewerAssignments.find(a => a.reviewer_id === currentUserId);
  const canReview = !readOnly && currentUserAssignment?.status === 'pending' && 
                   ['pending', 'in_review'].includes(request.status);

  useEffect(() => {
    loadReviewData();
  }, [request.id, workspaceId]);

  const loadReviewData = async () => {
    try {
      setLoading(true);

      // Load reviewer assignments
      const reviewersResponse = await fetch(`/api/approval/requests/${request.id}/reviewers`);
      if (reviewersResponse.ok) {
        const reviewers = await reviewersResponse.json();
        setReviewerAssignments(reviewers);
      }

      // Load approval criteria
      const criteriaResponse = await fetch(`/api/approval/criteria/${workspaceId}`);
      if (criteriaResponse.ok) {
        const criteria = await criteriaResponse.json();
        setApprovalCriteria(criteria);

        // Initialize criteria evaluations
        const initialEvaluations: Record<string, any> = {};
        criteria.forEach((criterion: ApprovalCriteria) => {
          initialEvaluations[criterion.id] = {
            criteria_id: criterion.id,
            passed: false,
            score: 0,
            comment: ''
          };
        });
        setCriteriaEvaluations(initialEvaluations);
      }
    } catch (error) {
      setError('Failed to load review data');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmitReview = () => {
    if (!selectedDecision) return;

    onReviewSubmit(selectedDecision, reviewComment, criteriaEvaluations);
  };

  const handleCriteriaEvaluation = (criteriaId: string, field: string, value: any) => {
    setCriteriaEvaluations(prev => ({
      ...prev,
      [criteriaId]: {
        ...prev[criteriaId],
        [field]: value
      }
    }));
  };

  const toggleSection = (section: string) => {
    const newExpanded = new Set(expandedSections);
    if (newExpanded.has(section)) {
      newExpanded.delete(section);
    } else {
      newExpanded.add(section);
    }
    setExpandedSections(newExpanded);
  };

  const getUrgencyColor = (urgency: string) => {
    switch (urgency) {
      case 'critical': return 'bg-red-100 text-red-800 border-red-200';
      case 'high': return 'bg-orange-100 text-orange-800 border-orange-200';
      case 'medium': return 'bg-yellow-100 text-yellow-800 border-yellow-200';
      case 'low': return 'bg-green-100 text-green-800 border-green-200';
      default: return 'bg-gray-100 text-gray-800 border-gray-200';
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'approved': return <CheckCircleIcon className="h-4 w-4 text-green-500" />;
      case 'rejected': return <XCircleIcon className="h-4 w-4 text-red-500" />;
      case 'reviewing': return <EyeIcon className="h-4 w-4 text-blue-500" />;
      case 'pending': return <ClockIcon className="h-4 w-4 text-yellow-500" />;
      default: return <ClockIcon className="h-4 w-4 text-gray-500" />;
    }
  };

  const calculateOverallScore = () => {
    const totalWeight = approvalCriteria.reduce((sum, c) => sum + c.weight, 0);
    const weightedScore = approvalCriteria.reduce((sum, c) => {
      const evaluation = criteriaEvaluations[c.id];
      return sum + (evaluation?.score || 0) * c.weight;
    }, 0);
    return totalWeight > 0 ? Math.round((weightedScore / totalWeight) * 100) : 0;
  };

  const getRequiredCriteriaPassed = () => {
    const requiredCriteria = approvalCriteria.filter(c => c.is_required);
    const passedRequired = requiredCriteria.filter(c => criteriaEvaluations[c.id]?.passed).length;
    return { passed: passedRequired, total: requiredCriteria.length };
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center p-8">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-50 border border-red-200 rounded-md p-4">
        <div className="flex">
          <XCircleIcon className="h-5 w-5 text-red-400" />
          <div className="ml-3">
            <h3 className="text-sm font-medium text-red-800">Error</h3>
            <div className="mt-2 text-sm text-red-700">{error}</div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto bg-white rounded-lg shadow-lg">
      {/* Header */}
      <div className="border-b border-gray-200 p-6">
        <div className="flex items-center justify-between">
          <div>
            <h2 className="text-2xl font-bold text-gray-900">{request.title}</h2>
            <div className="mt-2 flex items-center space-x-4">
              <span className={`inline-flex items-center px-3 py-1 rounded-full text-sm font-medium border ${getUrgencyColor(request.urgency)}`}>
                {request.urgency.toUpperCase()}
              </span>
              <span className="text-sm text-gray-600">
                Requested by {request.requester_id} on {new Date(request.requested_at).toLocaleDateString()}
              </span>
              {request.due_date && (
                <span className="text-sm text-gray-600">
                  Due: {new Date(request.due_date).toLocaleDateString()}
                </span>
              )}
            </div>
          </div>
          <button
            onClick={onClose}
            className="text-gray-400 hover:text-gray-600"
          >
            <XCircleIcon className="h-6 w-6" />
          </button>
        </div>

        {/* Progress Bar */}
        <div className="mt-4">
          <div className="flex items-center justify-between text-sm text-gray-600">
            <span>Approval Progress: {request.current_approvals} of {request.required_approvals}</span>
            <span>{Math.round(request.approval_percentage)}%</span>
          </div>
          <div className="mt-1 w-full bg-gray-200 rounded-full h-2">
            <div 
              className="bg-blue-600 h-2 rounded-full transition-all duration-300"
              style={{ width: `${request.approval_percentage}%` }}
            />
          </div>
        </div>
      </div>

      <div className="p-6 space-y-6">
        {/* Overview Section */}
        <div className="border border-gray-200 rounded-lg">
          <button
            onClick={() => toggleSection('overview')}
            className="w-full flex items-center justify-between p-4 hover:bg-gray-50"
          >
            <div className="flex items-center space-x-2">
              <DocumentTextIcon className="h-5 w-5 text-gray-400" />
              <span className="font-medium">Request Overview</span>
            </div>
            {expandedSections.has('overview') ? (
              <ChevronDownIcon className="h-5 w-5 text-gray-400" />
            ) : (
              <ChevronRightIcon className="h-5 w-5 text-gray-400" />
            )}
          </button>

          {expandedSections.has('overview') && (
            <div className="border-t border-gray-200 p-4 space-y-4">
              {request.description && (
                <div>
                  <h4 className="text-sm font-medium text-gray-900 mb-2">Description</h4>
                  <p className="text-sm text-gray-700">{request.description}</p>
                </div>
              )}

              {request.business_justification && (
                <div>
                  <h4 className="text-sm font-medium text-gray-900 mb-2">Business Justification</h4>
                  <p className="text-sm text-gray-700">{request.business_justification}</p>
                </div>
              )}

              <div>
                <h4 className="text-sm font-medium text-gray-900 mb-2">Resource Details</h4>
                <div className="text-sm text-gray-700">
                  <p>Resource ID: {request.resource_id}</p>
                  <p>Transition ID: {request.transition_id}</p>
                  <p>Workspace: {request.workspace_id}</p>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Reviewers Section */}
        <div className="border border-gray-200 rounded-lg">
          <button
            onClick={() => toggleSection('reviewers')}
            className="w-full flex items-center justify-between p-4 hover:bg-gray-50"
          >
            <div className="flex items-center space-x-2">
              <UserIcon className="h-5 w-5 text-gray-400" />
              <span className="font-medium">Reviewers ({reviewerAssignments.length})</span>
            </div>
            {expandedSections.has('reviewers') ? (
              <ChevronDownIcon className="h-5 w-5 text-gray-400" />
            ) : (
              <ChevronRightIcon className="h-5 w-5 text-gray-400" />
            )}
          </button>

          {expandedSections.has('reviewers') && (
            <div className="border-t border-gray-200 p-4">
              <div className="space-y-3">
                {reviewerAssignments.map((assignment) => (
                  <div key={assignment.id} className="flex items-center justify-between p-3 bg-gray-50 rounded">
                    <div className="flex items-center space-x-3">
                      <div className="flex items-center space-x-2">
                        {getStatusIcon(assignment.status)}
                        <span className="font-medium">{assignment.reviewer_id}</span>
                      </div>
                      <span className={`px-2 py-1 rounded text-xs font-medium ${
                        assignment.assignment_type === 'escalated' ? 'bg-orange-100 text-orange-800' :
                        assignment.assignment_type === 'secondary' ? 'bg-blue-100 text-blue-800' :
                        'bg-gray-100 text-gray-800'
                      }`}>
                        {assignment.assignment_type}
                      </span>
                      {assignment.reviewer_id === currentUserId && (
                        <span className="px-2 py-1 rounded text-xs font-medium bg-blue-100 text-blue-800">
                          You
                        </span>
                      )}
                    </div>
                    <div className="text-sm text-gray-600">
                      {assignment.reviewed_at ? (
                        <span>Reviewed {new Date(assignment.reviewed_at).toLocaleDateString()}</span>
                      ) : (
                        <span>Pending review</span>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Criteria Evaluation Section */}
        {canReview && approvalCriteria.length > 0 && (
          <div className="border border-gray-200 rounded-lg">
            <button
              onClick={() => toggleSection('criteria')}
              className="w-full flex items-center justify-between p-4 hover:bg-gray-50"
            >
              <div className="flex items-center space-x-2">
                <ClipboardDocumentListIcon className="h-5 w-5 text-gray-400" />
                <span className="font-medium">Evaluation Criteria ({approvalCriteria.length})</span>
                <span className="text-sm text-gray-600">
                  Score: {calculateOverallScore()}%
                </span>
              </div>
              {expandedSections.has('criteria') ? (
                <ChevronDownIcon className="h-5 w-5 text-gray-400" />
              ) : (
                <ChevronRightIcon className="h-5 w-5 text-gray-400" />
              )}
            </button>

            {expandedSections.has('criteria') && (
              <div className="border-t border-gray-200 p-4">
                <div className="space-y-4">
                  {approvalCriteria.map((criterion) => (
                    <div key={criterion.id} className="border border-gray-200 rounded-lg p-4">
                      <div className="flex items-center justify-between mb-3">
                        <div className="flex items-center space-x-2">
                          <span className="font-medium">{criterion.name}</span>
                          {criterion.is_required && (
                            <span className="px-2 py-1 bg-red-100 text-red-800 text-xs rounded">
                              Required
                            </span>
                          )}
                          <span className="text-sm text-gray-600">
                            Weight: {criterion.weight}
                          </span>
                        </div>
                        <div className="flex items-center space-x-2">
                          <label className="flex items-center space-x-2">
                            <input
                              type="checkbox"
                              checked={criteriaEvaluations[criterion.id]?.passed || false}
                              onChange={(e) => handleCriteriaEvaluation(criterion.id, 'passed', e.target.checked)}
                              className="rounded border-gray-300 text-green-600 focus:ring-green-500"
                            />
                            <span className="text-sm text-gray-700">Passed</span>
                          </label>
                        </div>
                      </div>

                      {criterion.description && (
                        <p className="text-sm text-gray-600 mb-3">{criterion.description}</p>
                      )}

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                          <label className="block text-sm font-medium text-gray-700 mb-1">
                            Score (0-100)
                          </label>
                          <input
                            type="number"
                            min="0"
                            max="100"
                            value={criteriaEvaluations[criterion.id]?.score || 0}
                            onChange={(e) => handleCriteriaEvaluation(criterion.id, 'score', parseInt(e.target.value))}
                            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                          />
                        </div>
                        <div>
                          <label className="block text-sm font-medium text-gray-700 mb-1">
                            Comment
                          </label>
                          <textarea
                            value={criteriaEvaluations[criterion.id]?.comment || ''}
                            onChange={(e) => handleCriteriaEvaluation(criterion.id, 'comment', e.target.value)}
                            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                            rows={2}
                            placeholder="Add evaluation comment..."
                          />
                        </div>
                      </div>
                    </div>
                  ))}

                  {/* Criteria Summary */}
                  <div className="bg-gray-50 p-4 rounded-lg">
                    <h4 className="font-medium text-gray-900 mb-2">Evaluation Summary</h4>
                    <div className="grid grid-cols-2 gap-4 text-sm">
                      <div>
                        <span className="text-gray-600">Overall Score:</span>
                        <span className="ml-2 font-medium">{calculateOverallScore()}%</span>
                      </div>
                      <div>
                        <span className="text-gray-600">Required Criteria:</span>
                        <span className="ml-2 font-medium">
                          {getRequiredCriteriaPassed().passed} of {getRequiredCriteriaPassed().total} passed
                        </span>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}

        {/* Review Decision Section */}
        {canReview && (
          <div className="border border-gray-200 rounded-lg p-4">
            <h3 className="font-medium text-gray-900 mb-4">Your Review Decision</h3>

            <div className="space-y-4">
              <div className="flex items-center space-x-4">
                <label className="flex items-center space-x-2">
                  <input
                    type="radio"
                    name="decision"
                    value="approve"
                    checked={selectedDecision === 'approve'}
                    onChange={(e) => setSelectedDecision(e.target.value as 'approve')}
                    className="text-green-600 focus:ring-green-500"
                  />
                  <CheckCircleIcon className="h-5 w-5 text-green-600" />
                  <span className="text-green-800 font-medium">Approve</span>
                </label>

                <label className="flex items-center space-x-2">
                  <input
                    type="radio"
                    name="decision"
                    value="reject"
                    checked={selectedDecision === 'reject'}
                    onChange={(e) => setSelectedDecision(e.target.value as 'reject')}
                    className="text-red-600 focus:ring-red-500"
                  />
                  <XCircleIcon className="h-5 w-5 text-red-600" />
                  <span className="text-red-800 font-medium">Reject</span>
                </label>

                <label className="flex items-center space-x-2">
                  <input
                    type="radio"
                    name="decision"
                    value="abstain"
                    checked={selectedDecision === 'abstain'}
                    onChange={(e) => setSelectedDecision(e.target.value as 'abstain')}
                    className="text-gray-600 focus:ring-gray-500"
                  />
                  <ClockIcon className="h-5 w-5 text-gray-600" />
                  <span className="text-gray-800 font-medium">Abstain</span>
                </label>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Review Comment {selectedDecision === 'reject' ? '(required)' : '(optional)'}
                </label>
                <textarea
                  value={reviewComment}
                  onChange={(e) => setReviewComment(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  rows={4}
                  placeholder="Provide your review feedback..."
                />
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Footer */}
      <div className="border-t border-gray-200 p-6 flex items-center justify-between">
        <div className="text-sm text-gray-600">
          {canReview ? (
            'Complete your review to submit your decision.'
          ) : currentUserAssignment ? (
            'You have already submitted your review.'
          ) : (
            'You are not assigned as a reviewer for this request.'
          )}
        </div>

        <div className="flex items-center space-x-3">
          <button
            onClick={onClose}
            className="px-4 py-2 text-sm font-medium text-gray-700 bg-gray-100 rounded-md hover:bg-gray-200"
          >
            Close
          </button>

          {canReview && (
            <button
              onClick={handleSubmitReview}
              disabled={!selectedDecision || (selectedDecision === 'reject' && !reviewComment.trim())}
              className="px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded-md hover:bg-blue-700 disabled:bg-gray-300 disabled:cursor-not-allowed"
            >
              Submit Review
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

// Epic 9.4.2 - Approval Statistics Component
// Comprehensive statistics and analytics for approval workflows

import React, { useState, useEffect } from 'react';
import { 
  ChartBarIcon,
  ClockIcon,
  CheckCircleIcon,
  XCircleIcon,
  ExclamationTriangleIcon,
  TrendingUpIcon,
  TrendingDownIcon,
  UserGroupIcon,
  DocumentTextIcon,
  CalendarIcon,
  ArrowPathIcon
} from '@heroicons/react/24/outline';

interface ApprovalStatistics {
  total_requests: number;
  pending_requests: number;
  overdue_requests: number;
  avg_approval_time_hours: number;
  approval_rate: number;
  by_urgency: Record<string, number>;
  by_status: Record<string, number>;
  top_reviewers: Array<{ reviewer_id: string; count: number }>;
}

interface PerformanceMetrics {
  avg_completion_time: number;
  avg_first_review_time: number;
  avg_criteria_pass_rate: number;
  avg_satisfaction_score: number;
  total_approvals: number;
  approved_count: number;
  rejected_count: number;
  escalated_count: number;
}

interface ApprovalStatisticsProps {
  workspaceId: string;
  period?: '7d' | '30d' | '90d' | '1y';
  refreshInterval?: number;
}

export const ApprovalStatistics: React.FC<ApprovalStatisticsProps> = ({
  workspaceId,
  period = '30d',
  refreshInterval = 30000 // 30 seconds
}) => {
  const [statistics, setStatistics] = useState<ApprovalStatistics | null>(null);
  const [performanceMetrics, setPerformanceMetrics] = useState<PerformanceMetrics | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [lastUpdated, setLastUpdated] = useState<Date>(new Date());

  useEffect(() => {
    fetchStatistics();

    const interval = setInterval(fetchStatistics, refreshInterval);
    return () => clearInterval(interval);
  }, [workspaceId, period, refreshInterval]);

  const fetchStatistics = async () => {
    try {
      setLoading(true);
      setError(null);

      // Fetch general statistics
      const [statsResponse, performanceResponse] = await Promise.all([
        fetch(`/api/approval/statistics/${workspaceId}`),
        fetch(`/api/approval/statistics/${workspaceId}/performance?period=${period}`)
      ]);

      if (!statsResponse.ok || !performanceResponse.ok) {
        throw new Error('Failed to fetch statistics');
      }

      const stats = await statsResponse.json();
      const performance = await performanceResponse.json();

      setStatistics(stats);
      setPerformanceMetrics(performance);
      setLastUpdated(new Date());
    } catch (error) {
      setError(error instanceof Error ? error.message : 'Failed to fetch statistics');
    } finally {
      setLoading(false);
    }
  };

  const formatDuration = (hours: number) => {
    if (hours < 1) return `${Math.round(hours * 60)}m`;
    if (hours < 24) return `${Math.round(hours)}h`;
    return `${Math.round(hours / 24)}d`;
  };

  const formatPercentage = (value: number) => {
    return `${Math.round(value)}%`;
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'pending': return 'bg-yellow-100 text-yellow-800';
      case 'in_review': return 'bg-blue-100 text-blue-800';
      case 'approved': return 'bg-green-100 text-green-800';
      case 'rejected': return 'bg-red-100 text-red-800';
      case 'expired': return 'bg-gray-100 text-gray-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getUrgencyColor = (urgency: string) => {
    switch (urgency) {
      case 'critical': return 'bg-red-500';
      case 'high': return 'bg-orange-500';
      case 'medium': return 'bg-yellow-500';
      case 'low': return 'bg-green-500';
      default: return 'bg-gray-500';
    }
  };

  const getTrendIcon = (current: number, previous: number) => {
    if (current > previous) {
      return <TrendingUpIcon className="h-4 w-4 text-green-500" />;
    } else if (current < previous) {
      return <TrendingDownIcon className="h-4 w-4 text-red-500" />;
    }
    return <div className="h-4 w-4" />;
  };

  const StatCard: React.FC<{
    title: string;
    value: string | number;
    icon: React.ReactNode;
    color: string;
    trend?: React.ReactNode;
    subtitle?: string;
  }> = ({ title, value, icon, color, trend, subtitle }) => (
    <div className="bg-white rounded-lg shadow p-6">
      <div className="flex items-center">
        <div className={`p-3 rounded-md ${color}`}>
          {icon}
        </div>
        <div className="ml-4 flex-1">
          <div className="flex items-center justify-between">
            <p className="text-sm font-medium text-gray-900">{title}</p>
            {trend}
          </div>
          <p className="text-2xl font-bold text-gray-900">{value}</p>
          {subtitle && (
            <p className="text-sm text-gray-600">{subtitle}</p>
          )}
        </div>
      </div>
    </div>
  );

  const ChartCard: React.FC<{
    title: string;
    data: Record<string, number>;
    type: 'bar' | 'pie';
    colorMap?: (key: string) => string;
  }> = ({ title, data, type, colorMap }) => (
    <div className="bg-white rounded-lg shadow p-6">
      <h3 className="text-lg font-medium text-gray-900 mb-4">{title}</h3>
      {type === 'bar' ? (
        <div className="space-y-3">
          {Object.entries(data).map(([key, value]) => (
            <div key={key} className="flex items-center justify-between">
              <span className="text-sm text-gray-600 capitalize">{key}</span>
              <div className="flex items-center space-x-2">
                <div className="w-32 bg-gray-200 rounded-full h-2">
                  <div 
                    className={`h-2 rounded-full ${colorMap ? colorMap(key) : 'bg-blue-500'}`}
                    style={{ width: `${Math.min((value / Math.max(...Object.values(data))) * 100, 100)}%` }}
                  />
                </div>
                <span className="text-sm font-medium text-gray-900 w-8">{value}</span>
              </div>
            </div>
          ))}
        </div>
      ) : (
        <div className="space-y-2">
          {Object.entries(data).map(([key, value]) => (
            <div key={key} className="flex items-center justify-between">
              <div className="flex items-center space-x-2">
                <div className={`w-3 h-3 rounded-full ${colorMap ? colorMap(key) : 'bg-blue-500'}`} />
                <span className="text-sm text-gray-600 capitalize">{key}</span>
              </div>
              <span className="text-sm font-medium text-gray-900">{value}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );

  if (loading && !statistics) {
    return (
      <div className="flex items-center justify-center p-8">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-50 border border-red-200 rounded-md p-4">
        <div className="flex">
          <XCircleIcon className="h-5 w-5 text-red-400" />
          <div className="ml-3">
            <h3 className="text-sm font-medium text-red-800">Error</h3>
            <div className="mt-2 text-sm text-red-700">{error}</div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Approval Statistics</h2>
          <p className="mt-1 text-sm text-gray-600">
            Overview of approval workflows and performance metrics
          </p>
        </div>
        <div className="flex items-center space-x-4">
          <div className="text-sm text-gray-600">
            Last updated: {lastUpdated.toLocaleTimeString()}
          </div>
          <button
            onClick={fetchStatistics}
            className="inline-flex items-center px-3 py-2 border border-gray-300 shadow-sm text-sm leading-4 font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50"
          >
            <ArrowPathIcon className="h-4 w-4 mr-2" />
            Refresh
          </button>
        </div>
      </div>

      {/* Key Metrics */}
      {statistics && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <StatCard
            title="Total Requests"
            value={statistics.total_requests}
            icon={<DocumentTextIcon className="h-6 w-6 text-white" />}
            color="bg-blue-500"
            subtitle="All time"
          />

          <StatCard
            title="Pending Reviews"
            value={statistics.pending_requests}
            icon={<ClockIcon className="h-6 w-6 text-white" />}
            color="bg-yellow-500"
            subtitle="Awaiting action"
          />

          <StatCard
            title="Approval Rate"
            value={formatPercentage(statistics.approval_rate)}
            icon={<CheckCircleIcon className="h-6 w-6 text-white" />}
            color="bg-green-500"
            subtitle="Success rate"
          />

          <StatCard
            title="Avg. Review Time"
            value={formatDuration(statistics.avg_approval_time_hours)}
            icon={<ChartBarIcon className="h-6 w-6 text-white" />}
            color="bg-purple-500"
            subtitle="Time to completion"
          />
        </div>
      )}

      {/* Performance Metrics */}
      {performanceMetrics && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <StatCard
            title="First Review Time"
            value={formatDuration(performanceMetrics.avg_first_review_time)}
            icon={<ClockIcon className="h-6 w-6 text-white" />}
            color="bg-indigo-500"
            subtitle="Time to first review"
          />

          <StatCard
            title="Criteria Pass Rate"
            value={formatPercentage(performanceMetrics.avg_criteria_pass_rate)}
            icon={<CheckCircleIcon className="h-6 w-6 text-white" />}
            color="bg-green-500"
            subtitle="Quality metric"
          />

          <StatCard
            title="Satisfaction Score"
            value={`${Math.round(performanceMetrics.avg_satisfaction_score * 10) / 10}/5`}
            icon={<DocumentTextIcon className="h-6 w-6 text-white" />}
            color="bg-pink-500"
            subtitle="User satisfaction"
          />

          <StatCard
            title="Escalations"
            value={performanceMetrics.escalated_count}
            icon={<ExclamationTriangleIcon className="h-6 w-6 text-white" />}
            color="bg-orange-500"
            subtitle="Escalated reviews"
          />
        </div>
      )}

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Status Distribution */}
        {statistics && (
          <ChartCard
            title="Requests by Status"
            data={statistics.by_status}
            type="bar"
            colorMap={(status) => {
              switch (status) {
                case 'pending': return 'bg-yellow-500';
                case 'in_review': return 'bg-blue-500';
                case 'approved': return 'bg-green-500';
                case 'rejected': return 'bg-red-500';
                case 'expired': return 'bg-gray-500';
                default: return 'bg-gray-500';
              }
            }}
          />
        )}

        {/* Urgency Distribution */}
        {statistics && (
          <ChartCard
            title="Requests by Urgency"
            data={statistics.by_urgency}
            type="pie"
            colorMap={(urgency) => getUrgencyColor(urgency).replace('bg-', '')}
          />
        )}
      </div>

      {/* Top Reviewers */}
      {statistics && statistics.top_reviewers.length > 0 && (
        <div className="bg-white rounded-lg shadow p-6">
          <h3 className="text-lg font-medium text-gray-900 mb-4">Top Reviewers</h3>
          <div className="space-y-3">
            {statistics.top_reviewers.slice(0, 10).map((reviewer, index) => (
              <div key={reviewer.reviewer_id} className="flex items-center justify-between">
                <div className="flex items-center space-x-3">
                  <div className="flex-shrink-0 w-8 h-8 bg-blue-100 rounded-full flex items-center justify-center">
                    <span className="text-sm font-medium text-blue-800">#{index + 1}</span>
                  </div>
                  <div>
                    <p className="text-sm font-medium text-gray-900">{reviewer.reviewer_id}</p>
                    <p className="text-xs text-gray-600">Active reviewer</p>
                  </div>
                </div>
                <div className="flex items-center space-x-2">
                  <span className="text-sm font-medium text-gray-900">{reviewer.count}</span>
                  <span className="text-xs text-gray-600">reviews</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Recent Activity Summary */}
      <div className="bg-white rounded-lg shadow p-6">
        <h3 className="text-lg font-medium text-gray-900 mb-4">
          Performance Summary ({period})
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="text-center">
            <div className="text-2xl font-bold text-green-600">
              {performanceMetrics?.approved_count || 0}
            </div>
            <div className="text-sm text-gray-600">Approved</div>
          </div>
          <div className="text-center">
            <div className="text-2xl font-bold text-red-600">
              {performanceMetrics?.rejected_count || 0}
            </div>
            <div className="text-sm text-gray-600">Rejected</div>
          </div>
          <div className="text-center">
            <div className="text-2xl font-bold text-blue-600">
              {performanceMetrics?.total_approvals || 0}
            </div>
            <div className="text-sm text-gray-600">Total Reviews</div>
          </div>
        </div>
      </div>

      {/* Health Indicators */}
      <div className="bg-white rounded-lg shadow p-6">
        <h3 className="text-lg font-medium text-gray-900 mb-4">System Health</h3>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="flex items-center space-x-3">
            <div className={`w-3 h-3 rounded-full ${
              statistics && statistics.overdue_requests === 0 ? 'bg-green-500' : 'bg-red-500'
            }`} />
            <div>
              <p className="text-sm font-medium text-gray-900">Overdue Requests</p>
              <p className="text-xs text-gray-600">{statistics?.overdue_requests || 0} overdue</p>
            </div>
          </div>

          <div className="flex items-center space-x-3">
            <div className={`w-3 h-3 rounded-full ${
              statistics && statistics.avg_approval_time_hours < 48 ? 'bg-green-500' : 'bg-yellow-500'
            }`} />
            <div>
              <p className="text-sm font-medium text-gray-900">Response Time</p>
              <p className="text-xs text-gray-600">
                {statistics ? formatDuration(statistics.avg_approval_time_hours) : 'N/A'} average
              </p>
            </div>
          </div>

          <div className="flex items-center space-x-3">
            <div className={`w-3 h-3 rounded-full ${
              statistics && statistics.approval_rate > 80 ? 'bg-green-500' : 'bg-yellow-500'
            }`} />
            <div>
              <p className="text-sm font-medium text-gray-900">Approval Rate</p>
              <p className="text-xs text-gray-600">{statistics ? formatPercentage(statistics.approval_rate) : 'N/A'}</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

// Epic 9.4.2 - Approval Workflow Manager Component
// Main component that orchestrates all approval workflow functionality

import React, { useState, useEffect } from 'react';
import { 
  Cog6ToothIcon,
  ClipboardDocumentListIcon,
  ChartBarIcon,
  UserGroupIcon,
  DocumentTextIcon,
  PlusIcon,
  PencilIcon,
  TrashIcon,
  CheckCircleIcon,
  XCircleIcon
} from '@heroicons/react/24/outline';

import { ApprovalDashboard } from './ApprovalDashboard';
import { ApprovalReviewInterface } from './ApprovalReviewInterface';
import { ApprovalStatistics } from './ApprovalStatistics';

interface ApprovalCriteria {
  id: string;
  workspace_id: string;
  name: string;
  description?: string;
  conditions: Record<string, any>;
  weight: number;
  is_required: boolean;
  created_at: Date;
  updated_at: Date;
}

interface ApprovalRule {
  id: string;
  workspace_id: string;
  transition_id: string;
  name: string;
  description?: string;
  reviewer_assignment_type: 'manual' | 'automatic' | 'role_based' | 'round_robin';
  required_reviewers: number;
  minimum_approvals: number;
  allow_self_approval: boolean;
  criteria_ids: string[];
  require_all_criteria: boolean;
  approval_timeout_hours: number;
  escalation_enabled: boolean;
  escalation_after_hours: number;
  escalation_reviewers: string[];
  auto_approval_enabled: boolean;
  auto_approval_conditions: Record<string, any>;
  created_at: Date;
  updated_at: Date;
}

interface ApprovalWorkflowManagerProps {
  workspaceId: string;
  currentUserId: string;
  userRole: 'admin' | 'manager' | 'reviewer' | 'user';
}

export const ApprovalWorkflowManager: React.FC<ApprovalWorkflowManagerProps> = ({
  workspaceId,
  currentUserId,
  userRole
}) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'rules' | 'criteria' | 'statistics'>('dashboard');
  const [approvalCriteria, setApprovalCriteria] = useState<ApprovalCriteria[]>([]);
  const [approvalRules, setApprovalRules] = useState<ApprovalRule[]>([]);
  const [selectedRequest, setSelectedRequest] = useState<any>(null);
  const [showReviewInterface, setShowReviewInterface] = useState(false);
  const [showCriteriaModal, setShowCriteriaModal] = useState(false);
  const [showRuleModal, setShowRuleModal] = useState(false);
  const [editingCriteria, setEditingCriteria] = useState<ApprovalCriteria | null>(null);
  const [editingRule, setEditingRule] = useState<ApprovalRule | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Determine dashboard mode based on user role
  const dashboardMode = userRole === 'admin' ? 'admin' : 'reviewer';

  useEffect(() => {
    loadApprovalData();
  }, [workspaceId]);

  const loadApprovalData = async () => {
    try {
      setLoading(true);
      setError(null);

      const [criteriaResponse, rulesResponse] = await Promise.all([
        fetch(`/api/approval/criteria/${workspaceId}`),
        fetch(`/api/approval/rules/${workspaceId}`)
      ]);

      if (criteriaResponse.ok) {
        const criteria = await criteriaResponse.json();
        setApprovalCriteria(criteria);
      }

      if (rulesResponse.ok) {
        const rules = await rulesResponse.json();
        setApprovalRules(rules);
      }
    } catch (error) {
      setError('Failed to load approval data');
    } finally {
      setLoading(false);
    }
  };

  const handleCreateCriteria = async (data: Partial<ApprovalCriteria>) => {
    try {
      const response = await fetch('/api/approval/criteria', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...data, workspace_id: workspaceId })
      });

      if (response.ok) {
        await loadApprovalData();
        setShowCriteriaModal(false);
      }
    } catch (error) {
      setError('Failed to create criteria');
    }
  };

  const handleUpdateCriteria = async (id: string, data: Partial<ApprovalCriteria>) => {
    try {
      const response = await fetch(`/api/approval/criteria/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(data)
      });

      if (response.ok) {
        await loadApprovalData();
        setEditingCriteria(null);
      }
    } catch (error) {
      setError('Failed to update criteria');
    }
  };

  const handleDeleteCriteria = async (id: string) => {
    if (!confirm('Are you sure you want to delete this criteria?')) return;

    try {
      const response = await fetch(`/api/approval/criteria/${id}`, {
        method: 'DELETE'
      });

      if (response.ok) {
        await loadApprovalData();
      }
    } catch (error) {
      setError('Failed to delete criteria');
    }
  };

  const handleCreateRule = async (data: Partial<ApprovalRule>) => {
    try {
      const response = await fetch('/api/approval/rules', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...data, workspace_id: workspaceId })
      });

      if (response.ok) {
        await loadApprovalData();
        setShowRuleModal(false);
      }
    } catch (error) {
      setError('Failed to create rule');
    }
  };

  const handleReviewSubmit = async (
    decision: 'approve' | 'reject' | 'abstain',
    comment?: string,
    criteriaEvaluations?: Record<string, any>
  ) => {
    if (!selectedRequest) return;

    try {
      const response = await fetch(`/api/approval/requests/${selectedRequest.id}/review`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-user-id': currentUserId
        },
        body: JSON.stringify({
          decision,
          comment,
          criteria_evaluations: criteriaEvaluations
        })
      });

      if (response.ok) {
        setShowReviewInterface(false);
        setSelectedRequest(null);
        // Refresh dashboard data would be handled by the dashboard component
      }
    } catch (error) {
      setError('Failed to submit review');
    }
  };

  const CriteriaModal: React.FC<{
    criteria?: ApprovalCriteria;
    onSave: (data: Partial<ApprovalCriteria>) => void;
    onClose: () => void;
  }> = ({ criteria, onSave, onClose }) => {
    const [formData, setFormData] = useState({
      name: criteria?.name || '',
      description: criteria?.description || '',
      weight: criteria?.weight || 1,
      is_required: criteria?.is_required || false,
      conditions: criteria?.conditions || {}
    });

    const handleSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      onSave(formData);
    };

    return (
      <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
        <div className="bg-white rounded-lg p-6 max-w-md w-full mx-4">
          <h3 className="text-lg font-medium text-gray-900 mb-4">
            {criteria ? 'Edit Criteria' : 'Create New Criteria'}
          </h3>

          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Name
              </label>
              <input
                type="text"
                value={formData.name}
                onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))}
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                required
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Description
              </label>
              <textarea
                value={formData.description}
                onChange={(e) => setFormData(prev => ({ ...prev, description: e.target.value }))}
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                rows={3}
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Weight (1-10)
              </label>
              <input
                type="number"
                min="1"
                max="10"
                value={formData.weight}
                onChange={(e) => setFormData(prev => ({ ...prev, weight: parseInt(e.target.value) }))}
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                required
              />
            </div>

            <div className="flex items-center space-x-2">
              <input
                type="checkbox"
                checked={formData.is_required}
                onChange={(e) => setFormData(prev => ({ ...prev, is_required: e.target.checked }))}
                className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
              />
              <label className="text-sm text-gray-700">
                Required criteria
              </label>
            </div>

            <div className="flex justify-end space-x-3">
              <button
                type="button"
                onClick={onClose}
                className="px-4 py-2 text-sm font-medium text-gray-700 bg-gray-100 rounded-md hover:bg-gray-200"
              >
                Cancel
              </button>
              <button
                type="submit"
                className="px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded-md hover:bg-blue-700"
              >
                {criteria ? 'Update' : 'Create'}
              </button>
            </div>
          </form>
        </div>
      </div>
    );
  };

  const canManageWorkflow = ['admin', 'manager'].includes(userRole);

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Approval Workflow</h1>
          <p className="mt-1 text-sm text-gray-600">
            Manage approval processes, criteria, and review workflows
          </p>
        </div>

        {canManageWorkflow && (
          <div className="flex items-center space-x-3">
            <button
              onClick={() => setShowCriteriaModal(true)}
              className="inline-flex items-center px-3 py-2 border border-transparent text-sm leading-4 font-medium rounded-md text-white bg-blue-600 hover:bg-blue-700"
            >
              <PlusIcon className="h-4 w-4 mr-2" />
              Add Criteria
            </button>
            <button
              onClick={() => setShowRuleModal(true)}
              className="inline-flex items-center px-3 py-2 border border-transparent text-sm leading-4 font-medium rounded-md text-white bg-green-600 hover:bg-green-700"
            >
              <PlusIcon className="h-4 w-4 mr-2" />
              Add Rule
            </button>
          </div>
        )}
      </div>

      {/* Tab Navigation */}
      <div className="border-b border-gray-200">
        <nav className="-mb-px flex space-x-8">
          {[
            { id: 'dashboard', label: 'Dashboard', icon: DocumentTextIcon },
            { id: 'rules', label: 'Rules', icon: Cog6ToothIcon },
            { id: 'criteria', label: 'Criteria', icon: ClipboardDocumentListIcon },
            { id: 'statistics', label: 'Statistics', icon: ChartBarIcon }
          ].map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`flex items-center space-x-2 py-2 px-1 border-b-2 font-medium text-sm ${
                activeTab === tab.id
                  ? 'border-blue-500 text-blue-600'
                  : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
              }`}
            >
              <tab.icon className="h-4 w-4" />
              <span>{tab.label}</span>
            </button>
          ))}
        </nav>
      </div>

      {/* Error Display */}
      {error && (
        <div className="bg-red-50 border border-red-200 rounded-md p-4">
          <div className="flex">
            <XCircleIcon className="h-5 w-5 text-red-400" />
            <div className="ml-3">
              <h3 className="text-sm font-medium text-red-800">Error</h3>
              <div className="mt-2 text-sm text-red-700">{error}</div>
            </div>
          </div>
        </div>
      )}

      {/* Tab Content */}
      <div className="mt-6">
        {activeTab === 'dashboard' && (
          <ApprovalDashboard
            workspaceId={workspaceId}
            currentUserId={currentUserId}
            mode={dashboardMode}
          />
        )}

        {activeTab === 'criteria' && (
          <div className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {approvalCriteria.map((criteria) => (
                <div key={criteria.id} className="bg-white border border-gray-200 rounded-lg p-4">
                  <div className="flex items-center justify-between mb-3">
                    <h3 className="font-medium text-gray-900">{criteria.name}</h3>
                    {canManageWorkflow && (
                      <div className="flex items-center space-x-2">
                        <button
                          onClick={() => setEditingCriteria(criteria)}
                          className="p-1 text-gray-400 hover:text-gray-600"
                        >
                          <PencilIcon className="h-4 w-4" />
                        </button>
                        <button
                          onClick={() => handleDeleteCriteria(criteria.id)}
                          className="p-1 text-gray-400 hover:text-red-600"
                        >
                          <TrashIcon className="h-4 w-4" />
                        </button>
                      </div>
                    )}
                  </div>

                  {criteria.description && (
                    <p className="text-sm text-gray-600 mb-3">{criteria.description}</p>
                  )}

                  <div className="flex items-center justify-between text-sm">
                    <span className="text-gray-600">Weight: {criteria.weight}</span>
                    {criteria.is_required && (
                      <span className="px-2 py-1 bg-red-100 text-red-800 text-xs rounded">
                        Required
                      </span>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'rules' && (
          <div className="space-y-4">
            <div className="grid grid-cols-1 gap-4">
              {approvalRules.map((rule) => (
                <div key={rule.id} className="bg-white border border-gray-200 rounded-lg p-6">
                  <div className="flex items-center justify-between mb-4">
                    <h3 className="text-lg font-medium text-gray-900">{rule.name}</h3>
                    {canManageWorkflow && (
                      <div className="flex items-center space-x-2">
                        <button
                          onClick={() => setEditingRule(rule)}
                          className="p-1 text-gray-400 hover:text-gray-600"
                        >
                          <PencilIcon className="h-4 w-4" />
                        </button>
                      </div>
                    )}
                  </div>

                  {rule.description && (
                    <p className="text-sm text-gray-600 mb-4">{rule.description}</p>
                  )}

                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4 text-sm">
                    <div>
                      <span className="font-medium text-gray-700">Assignment:</span>
                      <span className="ml-2 text-gray-600">{rule.reviewer_assignment_type}</span>
                    </div>
                    <div>
                      <span className="font-medium text-gray-700">Reviewers:</span>
                      <span className="ml-2 text-gray-600">{rule.required_reviewers}</span>
                    </div>
                    <div>
                      <span className="font-medium text-gray-700">Min. Approvals:</span>
                      <span className="ml-2 text-gray-600">{rule.minimum_approvals}</span>
                    </div>
                    <div>
                      <span className="font-medium text-gray-700">Timeout:</span>
                      <span className="ml-2 text-gray-600">{rule.approval_timeout_hours}h</span>
                    </div>
                    <div>
                      <span className="font-medium text-gray-700">Escalation:</span>
                      <span className="ml-2 text-gray-600">{rule.escalation_enabled ? 'Yes' : 'No'}</span>
                    </div>
                    <div>
                      <span className="font-medium text-gray-700">Auto-approval:</span>
                      <span className="ml-2 text-gray-600">{rule.auto_approval_enabled ? 'Yes' : 'No'}</span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'statistics' && (
          <ApprovalStatistics
            workspaceId={workspaceId}
            period="30d"
          />
        )}
      </div>

      {/* Modals */}
      {showCriteriaModal && (
        <CriteriaModal
          onSave={handleCreateCriteria}
          onClose={() => setShowCriteriaModal(false)}
        />
      )}

      {editingCriteria && (
        <CriteriaModal
          criteria={editingCriteria}
          onSave={(data) => handleUpdateCriteria(editingCriteria.id, data)}
          onClose={() => setEditingCriteria(null)}
        />
      )}

      {showReviewInterface && selectedRequest && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="max-w-6xl w-full max-h-[90vh] overflow-y-auto">
            <ApprovalReviewInterface
              request={selectedRequest}
              workspaceId={workspaceId}
              currentUserId={currentUserId}
              onReviewSubmit={handleReviewSubmit}
              onClose={() => {
                setShowReviewInterface(false);
                setSelectedRequest(null);
              }}
            />
          </div>
        </div>
      )}
    </div>
  );
};

// Epic 9.4.4 - Audit Trail Viewer Component
// UI component for viewing and filtering audit trail records

import React, { useState, useEffect, useMemo } from 'react';
import { 
  ClipboardDocumentListIcon,
  FunnelIcon,
  CalendarDaysIcon,
  UserIcon,
  CogIcon,
  ArrowDownTrayIcon,
  EyeIcon,
  MagnifyingGlassIcon,
  ChevronDownIcon,
  ClockIcon,
  CheckCircleIcon,
  XCircleIcon,
  LockClosedIcon,
  LockOpenIcon
} from '@heroicons/react/24/outline';
import { useWorkflowStore, WorkflowHistoryEntry } from '../stores/workflowStore';

interface AuditTrailViewerProps {
  workspaceId: string;
  resourceId?: string;
  onClose?: () => void;
}

interface AuditFilters {
  action_type?: string;
  actor_id?: string;
  resource_id?: string;
  start_date?: Date;
  end_date?: Date;
  search_term?: string;
}

export const AuditTrailViewer: React.FC<AuditTrailViewerProps> = ({
  workspaceId,
  resourceId,
  onClose
}) => {
  const {
    auditHistory,
    loading,
    error,
    fetchAuditHistory,
    exportAuditHistory
  } = useWorkflowStore();

  const [filters, setFilters] = useState<AuditFilters>({
    resource_id: resourceId
  });
  const [showFilters, setShowFilters] = useState(false);
  const [selectedEntries, setSelectedEntries] = useState<Set<string>>(new Set());
  const [showExportDialog, setShowExportDialog] = useState(false);

  // Load audit history
  useEffect(() => {
    fetchAuditHistory(workspaceId, filters);
  }, [workspaceId, filters, fetchAuditHistory]);

  // Filter audit entries
  const filteredEntries = useMemo(() => {
    let entries = auditHistory;

    if (filters.action_type) {
      entries = entries.filter(entry => entry.action_type === filters.action_type);
    }

    if (filters.actor_id) {
      entries = entries.filter(entry => entry.actor_id === filters.actor_id);
    }

    if (filters.resource_id) {
      entries = entries.filter(entry => entry.resource_id === filters.resource_id);
    }

    if (filters.start_date) {
      entries = entries.filter(entry => 
        new Date(entry.action_timestamp) >= filters.start_date!
      );
    }

    if (filters.end_date) {
      entries = entries.filter(entry => 
        new Date(entry.action_timestamp) <= filters.end_date!
      );
    }

    if (filters.search_term) {
      const searchLower = filters.search_term.toLowerCase();
      entries = entries.filter(entry => 
        entry.action_type.toLowerCase().includes(searchLower) ||
        entry.actor_id.toLowerCase().includes(searchLower) ||
        entry.comment?.toLowerCase().includes(searchLower) ||
        JSON.stringify(entry.metadata).toLowerCase().includes(searchLower)
      );
    }

    return entries.sort((a, b) => 
      new Date(b.action_timestamp).getTime() - new Date(a.action_timestamp).getTime()
    );
  }, [auditHistory, filters]);

  // Get unique action types and actors for filter options
  const actionTypes = useMemo(() => 
    Array.from(new Set(auditHistory.map(entry => entry.action_type))).sort()
  , [auditHistory]);

  const actors = useMemo(() => 
    Array.from(new Set(auditHistory.map(entry => entry.actor_id))).sort()
  , [auditHistory]);

  const handleFilterChange = (key: keyof AuditFilters, value: any) => {
    setFilters(prev => ({
      ...prev,
      [key]: value
    }));
  };

  const handleExport = async (format: 'csv' | 'json' | 'pdf') => {
    try {
      await exportAuditHistory(workspaceId, filters, format);
      setShowExportDialog(false);
    } catch (error) {
      console.error('Failed to export audit history:', error);
    }
  };

  const formatTimestamp = (timestamp: Date) => {
    return new Date(timestamp).toLocaleString();
  };

  const getActionTypeIcon = (actionType: string) => {
    switch (actionType) {
      case 'state_change':
        return <CogIcon className="h-4 w-4 text-blue-600" />;
      case 'approval_requested':
        return <ClockIcon className="h-4 w-4 text-yellow-600" />;
      case 'approved':
        return <CheckCircleIcon className="h-4 w-4 text-green-600" />;
      case 'rejected':
        return <XCircleIcon className="h-4 w-4 text-red-600" />;
      case 'locked':
        return <LockClosedIcon className="h-4 w-4 text-orange-600" />;
      case 'unlocked':
        return <LockOpenIcon className="h-4 w-4 text-gray-600" />;
      default:
        return <ClipboardDocumentListIcon className="h-4 w-4 text-gray-600" />;
    }
  };

  const getActionTypeColor = (actionType: string) => {
    switch (actionType) {
      case 'state_change': return 'bg-blue-50 text-blue-800';
      case 'approval_requested': return 'bg-yellow-50 text-yellow-800';
      case 'approved': return 'bg-green-50 text-green-800';
      case 'rejected': return 'bg-red-50 text-red-800';
      case 'locked': return 'bg-orange-50 text-orange-800';
      case 'unlocked': return 'bg-gray-50 text-gray-800';
      default: return 'bg-gray-50 text-gray-800';
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-50 border border-red-200 rounded-lg p-4">
        <div className="flex items-center">
          <XCircleIcon className="h-5 w-5 text-red-600 mr-2" />
          <span className="text-red-800">Failed to load audit history: {error}</span>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-lg shadow-sm border border-gray-200">
      {/* Header */}
      <div className="border-b border-gray-200 p-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <ClipboardDocumentListIcon className="h-6 w-6 text-gray-600" />
            <div>
              <h2 className="text-lg font-semibold text-gray-900">Audit Trail</h2>
              <p className="text-sm text-gray-500">
                {filteredEntries.length} entries found
              </p>
            </div>
          </div>
          <div className="flex items-center space-x-2">
            <button
              onClick={() => setShowFilters(!showFilters)}
              className="flex items-center space-x-1 px-3 py-1 text-sm bg-gray-100 text-gray-700 rounded-md hover:bg-gray-200 transition-colors"
            >
              <FunnelIcon className="h-4 w-4" />
              <span>Filters</span>
              <ChevronDownIcon className={`h-3 w-3 transition-transform ${showFilters ? 'rotate-180' : ''}`} />
            </button>
            <button
              onClick={() => setShowExportDialog(true)}
              className="flex items-center space-x-1 px-3 py-1 text-sm bg-blue-100 text-blue-700 rounded-md hover:bg-blue-200 transition-colors"
            >
              <ArrowDownTrayIcon className="h-4 w-4" />
              <span>Export</span>
            </button>
            {onClose && (
              <button
                onClick={onClose}
                className="text-gray-400 hover:text-gray-600 transition-colors"
              >
                <XCircleIcon className="h-5 w-5" />
              </button>
            )}
          </div>
        </div>
      </div>

      {/* Filters */}
      {showFilters && (
        <div className="border-b border-gray-200 p-4 bg-gray-50">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Action Type
              </label>
              <select
                value={filters.action_type || ''}
                onChange={(e) => handleFilterChange('action_type', e.target.value || undefined)}
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500"
              >
                <option value="">All Actions</option>
                {actionTypes.map(type => (
                  <option key={type} value={type}>
                    {type.replace('_', ' ').toUpperCase()}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Actor
              </label>
              <select
                value={filters.actor_id || ''}
                onChange={(e) => handleFilterChange('actor_id', e.target.value || undefined)}
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500"
              >
                <option value="">All Actors</option>
                {actors.map(actor => (
                  <option key={actor} value={actor}>
                    {actor}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Search
              </label>
              <div className="relative">
                <MagnifyingGlassIcon className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400" />
                <input
                  type="text"
                  value={filters.search_term || ''}
                  onChange={(e) => handleFilterChange('search_term', e.target.value || undefined)}
                  placeholder="Search entries..."
                  className="w-full pl-10 pr-3 py-2 border border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Start Date
              </label>
              <input
                type="datetime-local"
                value={filters.start_date ? filters.start_date.toISOString().slice(0, 16) : ''}
                onChange={(e) => handleFilterChange('start_date', e.target.value ? new Date(e.target.value) : undefined)}
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500"
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                End Date
              </label>
              <input
                type="datetime-local"
                value={filters.end_date ? filters.end_date.toISOString().slice(0, 16) : ''}
                onChange={(e) => handleFilterChange('end_date', e.target.value ? new Date(e.target.value) : undefined)}
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500"
              />
            </div>
          </div>
        </div>
      )}

      {/* Audit entries */}
      <div className="divide-y divide-gray-200 max-h-96 overflow-y-auto">
        {filteredEntries.length === 0 ? (
          <div className="p-8 text-center text-gray-500">
            <ClipboardDocumentListIcon className="h-12 w-12 mx-auto mb-4 text-gray-300" />
            <p>No audit entries found matching your criteria.</p>
          </div>
        ) : (
          filteredEntries.map((entry) => (
            <div key={entry.id} className="p-4 hover:bg-gray-50 transition-colors">
              <div className="flex items-start space-x-3">
                <div className="flex-shrink-0 mt-1">
                  {getActionTypeIcon(entry.action_type)}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center space-x-2">
                    <span className={`px-2 py-1 text-xs font-medium rounded-full ${getActionTypeColor(entry.action_type)}`}>
                      {entry.action_type.replace('_', ' ').toUpperCase()}
                    </span>
                    <span className="text-sm text-gray-500">
                      {formatTimestamp(entry.action_timestamp)}
                    </span>
                  </div>
                  <div className="mt-1 flex items-center space-x-4 text-sm text-gray-600">
                    <div className="flex items-center space-x-1">
                      <UserIcon className="h-4 w-4" />
                      <span>{entry.actor_id}</span>
                    </div>
                    <div className="flex items-center space-x-1">
                      <span>Resource: {entry.resource_id}</span>
                    </div>
                  </div>
                  {entry.comment && (
                    <p className="mt-2 text-sm text-gray-700">
                      {entry.comment}
                    </p>
                  )}
                  {entry.metadata && Object.keys(entry.metadata).length > 0 && (
                    <div className="mt-2 text-xs text-gray-500">
                      <details className="cursor-pointer">
                        <summary className="hover:text-gray-700">
                          Additional metadata ({Object.keys(entry.metadata).length} items)
                        </summary>
                        <pre className="mt-1 bg-gray-100 p-2 rounded text-xs overflow-x-auto">
                          {JSON.stringify(entry.metadata, null, 2)}
                        </pre>
                      </details>
                    </div>
                  )}
                </div>
              </div>
            </div>
          ))
        )}
      </div>

      {/* Export dialog */}
      {showExportDialog && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-full max-w-md">
            <h3 className="text-lg font-semibold mb-4">Export Audit History</h3>
            <div className="space-y-3">
              <button
                onClick={() => handleExport('csv')}
                className="w-full text-left px-4 py-2 bg-gray-100 hover:bg-gray-200 rounded-md transition-colors"
              >
                CSV Format
              </button>
              <button
                onClick={() => handleExport('json')}
                className="w-full text-left px-4 py-2 bg-gray-100 hover:bg-gray-200 rounded-md transition-colors"
              >
                JSON Format
              </button>
              <button
                onClick={() => handleExport('pdf')}
                className="w-full text-left px-4 py-2 bg-gray-100 hover:bg-gray-200 rounded-md transition-colors"
              >
                PDF Report
              </button>
            </div>
            <div className="mt-4 flex justify-end space-x-2">
              <button
                onClick={() => setShowExportDialog(false)}
                className="px-4 py-2 text-gray-600 hover:text-gray-800 transition-colors"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
