              key={index}
              style={{
                display: "flex",
                alignItems: "center",
                gap: 8,
                marginBottom: index < variations.length - 1 ? 8 : 0,
              }}
            >
              <input
                type="text"
                value={variation}
                onChange={(e) => handleUpdate(index, e.target.value)}
                style={{
                  flex: 1,
                  padding: 6,
                  border: "1px solid #4a5568",
                  borderRadius: 2,
                  background: "#1a202c",
                  color: "#e2e8f0",
