                  cursor: "pointer",
                  fontSize: 10,
                }}
              >
                ✕
              </button>
            </div>
          ))}
        </div>
      )}

      <div style={{ display: "flex", gap: 8 }}>
        <input
          type="text"
          value={newItem}
          onChange={(e) => setNewItem(e.target.value)}
          onKeyPress={handleKeyPress}
          placeholder={placeholder}
          style={{
            flex: 1,
            padding: 6,
            border: "1px solid #4a5568",
            borderRadius: 4,
            background: "#2d3748",
            color: "#e2e8f0",
            fontSize: 12,
          }}
        />
        <button
          onClick={handleAdd}
          disabled={!newItem.trim()}
