                if (e.key === 'Enter') {
                  e.preventDefault();
                  handleAdd();
                }
              }}
              placeholder={placeholder}
              disabled={variations.length >= maxVariations}
              style={{
                flex: 1,
                padding: "8px 12px",
                border: "1px solid #4a5568",
                borderRadius: 6,
                fontSize: 14,
                outline: "none",
                background: "#2d3748",
                color: "#e2e8f0",
              }}
            />
            <button
              onClick={handleAdd}
              disabled={!newVariation.trim() || variations.length >= maxVariations}
              style={{
                background: newVariation.trim() && variations.length < maxVariations ? "#3b82f6" : "#9ca3af",
                color: "#fff",
                border: "none",
                borderRadius: 6,
                padding: "8px 16px",
                fontSize: 14,
