                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                ⋮⋮
              </div>
              {editingIndex === index ? (
                <input
                  ref={editInputRef}
                  type="text"
                  value={editingValue}
                  onChange={(e) => setEditingValue(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter') {
                      e.preventDefault();
                      commitEdit();
                    } else if (e.key === 'Escape') {
                      cancelEdit();
                    }
                  }}
                  onBlur={commitEdit}
                  style={{
                    flex: 1,
                    padding: "4px 8px",
                    border: "1px solid #3b82f6",
                    borderRadius: 4,
                    fontSize: 14,
                    outline: "none",
                  }}
                />
              ) : (
                <span
                  onClick={() => startEdit(index)}
                  style={{
                    flex: 1,
                    cursor: "pointer",
                    fontSize: 14,
                    color: "#374151",
                  }}
                  title="Click to edit"
                >
                  {variation}
                </span>
              )}
              <button
                onClick={() => handleRemove(index)}
                style={{
                  background: "none",
                  border: "none",
                  color: "#ef4444",
                  cursor: "pointer",
                  fontSize: 14,
                  marginLeft: 8,
                  padding: 4,
                }}
                title="Remove variation"
              >
                ×
              </button>
            </div>
          ))
        )}
      </div>

      {variations.length >= maxVariations && (
        <div style={{
          marginTop: 8,
          fontSize: 12,
          color: "#ef4444",
          textAlign: "center",
        }}>
          Maximum {maxVariations} variations reached
        </div>
      )}
    </div>
  );
};

