    { value: 120, label: '2 hours' },
    { value: 240, label: '4 hours' },
    { value: 480, label: '8 hours' },
    { value: 1440, label: '24 hours' }
  ];

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setIsSubmitting(true);

    try {
      if (!selectedResource) {
        throw new Error('Please select a resource');
      }

      if (!reason.trim()) {
        throw new Error('Please provide a reason for the lock');
      }

      await onRequest(selectedResource, lockType, reason);
      onClose();
    } catch (error) {
      setError(error instanceof Error ? error.message : 'Failed to request lock');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleCancel = () => {
    setSelectedResource('');
    setLockType('edit');
    setReason('');
    setDuration(60);
    setError(null);
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div className="bg-white rounded-lg shadow-xl w-full max-w-2xl mx-4 max-h-[90vh] overflow-y-auto">
        {/* Header */}
        <div className="flex items-center justify-between p-6 border-b border-gray-200">
          <div className="flex items-center space-x-2">
            <Lock className="h-5 w-5 text-gray-500" />
            <h2 className="text-lg font-semibold text-gray-900">Request Lock</h2>
          </div>
          <button
            onClick={handleCancel}
            className="text-gray-400 hover:text-gray-600"
          >
            <X className="h-5 w-5" />
          </button>
        </div>

        {/* Content */}
        <form onSubmit={handleSubmit} className="p-6">
          {/* Error Display */}
          {error && (
            <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded-md">
              <div className="flex items-center">
                <AlertTriangle className="h-4 w-4 text-red-400 mr-2" />
                <span className="text-sm text-red-700">{error}</span>
              </div>
            </div>
          )}

          {/* Resource Selection */}
          <div className="mb-6">
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Resource ID
            </label>
            <input
              type="text"
              value={selectedResource}
              onChange={(e) => setSelectedResource(e.target.value)}
              placeholder="Enter resource ID"
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
              required
            />
            <p className="mt-1 text-sm text-gray-500">
              The unique identifier of the resource you want to lock
            </p>
          </div>

          {/* Lock Type Selection */}
          <div className="mb-6">
            <label className="block text-sm font-medium text-gray-700 mb-3">
              Lock Type
            </label>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
              {lockTypes.map((type) => {
                const Icon = type.icon;
                return (
                  <div key={type.value}>
                    <label className="flex items-start space-x-3 p-3 border border-gray-200 rounded-lg cursor-pointer hover:bg-gray-50">
                      <input
                        type="radio"
                        name="lockType"
                        value={type.value}
                        checked={lockType === type.value}
                        onChange={(e) => setLockType(e.target.value)}
                        className="mt-1"
                      />
                      <Icon className={`h-5 w-5 ${type.color} mt-0.5`} />
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium text-gray-900">
                          {type.label}
                        </p>
                        <p className="text-sm text-gray-500">
                          {type.description}
                        </p>
                      </div>
                    </label>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Duration Selection */}
          <div className="mb-6">
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Duration
            </label>
            <select
              value={duration}
              onChange={(e) => setDuration(parseInt(e.target.value))}
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
            >
              {durationOptions.map((option) => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </select>
            <p className="mt-1 text-sm text-gray-500">
              How long should the lock be active?
            </p>
          </div>

          {/* Reason */}
          <div className="mb-6">
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Reason <span className="text-red-500">*</span>
            </label>
            <textarea
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              rows={3}
              placeholder="Please explain why you need this lock..."
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
              required
            />
            <p className="mt-1 text-sm text-gray-500">
              A brief explanation of why you need this lock
            </p>
          </div>

          {/* Lock Policy Information */}
          <div className="mb-6 p-4 bg-blue-50 border border-blue-200 rounded-md">
            <div className="flex items-start space-x-2">
              <Info className="h-4 w-4 text-blue-400 mt-0.5" />
              <div className="text-sm text-blue-700">
                <p className="font-medium mb-1">Lock Policy</p>
                <ul className="space-y-1 text-blue-600">
                  <li>• Locks automatically expire after the specified duration</li>
                  <li>• You can release your own locks at any time</li>
                  <li>• Administrators may break locks if necessary</li>
                  <li>• Conflicting lock requests may be queued</li>
                </ul>
              </div>
            </div>
          </div>

          {/* Actions */}
          <div className="flex justify-end space-x-3">
            <button
              type="button"
              onClick={handleCancel}
              className="px-4 py-2 text-sm font-medium text-gray-700 bg-gray-100 rounded-md hover:bg-gray-200"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={isSubmitting}
              className="px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded-md hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {isSubmitting ? 'Requesting...' : 'Request Lock'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

// Epic 9.4.3 - Lock Status Overview Component
// Overview dashboard for lock statistics and conflicts

import React from 'react';
import { Lock, Clock, AlertTriangle, Users, Activity, TrendingUp } from 'lucide-react';
import { LockingStatistics, LockConflict } from '../types/locking';

interface LockStatusOverviewProps {
  statistics: LockingStatistics;
  conflicts: LockConflict[];
  onConflictClick: (conflict: LockConflict) => void;
}

export const LockStatusOverview: React.FC<LockStatusOverviewProps> = ({
  statistics,
  conflicts,
  onConflictClick
}) => {
  const pendingConflicts = conflicts.filter(c => c.status === 'pending');
  const resolvedConflicts = conflicts.filter(c => c.status === 'resolved');

  const StatCard = ({ title, value, icon: Icon, color, subtext }: {
    title: string;
    value: string | number;
    icon: React.ComponentType<{ className?: string }>;
    color: string;
    subtext?: string;
  }) => (
    <div className="bg-white rounded-lg border border-gray-200 p-4">
      <div className="flex items-center justify-between">
        <div>
          <p className="text-sm text-gray-500">{title}</p>
          <p className="text-2xl font-semibold text-gray-900">{value}</p>
          {subtext && <p className="text-sm text-gray-400">{subtext}</p>}
        </div>
        <div className={`p-3 rounded-full ${color}`}>
          <Icon className="h-6 w-6 text-white" />
        </div>
      </div>
    </div>
  );

  return (
    <div className="space-y-6">
      {/* Statistics Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard
          title="Active Locks"
          value={statistics.active_locks}
          icon={Lock}
          color="bg-blue-500"
          subtext={`${statistics.total_locks} total`}
        />
        <StatCard
          title="Pending Conflicts"
          value={pendingConflicts.length}
          icon={AlertTriangle}
          color="bg-red-500"
          subtext={`${resolvedConflicts.length} resolved`}
        />
        <StatCard
          title="Avg Duration"
          value={`${Math.round(statistics.avg_lock_duration_minutes)}m`}
          icon={Clock}
          color="bg-green-500"
          subtext="per lock"
        />
        <StatCard
          title="Conflict Rate"
          value={`${Math.round(statistics.conflict_rate)}%`}
          icon={TrendingUp}
          color="bg-orange-500"
          subtext="resolution rate"
        />
      </div>

      {/* Lock Type Distribution */}
      <div className="bg-white rounded-lg border border-gray-200 p-6">
        <h3 className="text-lg font-semibold text-gray-900 mb-4">Lock Type Distribution</h3>
        <div className="space-y-3">
          {Object.entries(statistics.by_type).map(([type, count]) => {
            const percentage = statistics.total_locks > 0 ? (count / statistics.total_locks) * 100 : 0;
            const colorMap: Record<string, string> = {
              edit: 'bg-blue-500',
              state_change: 'bg-orange-500',
              delete: 'bg-red-500',
              admin: 'bg-purple-500',
              custom: 'bg-gray-500'
            };

            return (
              <div key={type} className="flex items-center justify-between">
                <div className="flex items-center space-x-2">
                  <div className={`w-3 h-3 rounded-full ${colorMap[type] || 'bg-gray-400'}`}></div>
                  <span className="text-sm font-medium text-gray-700 capitalize">
                    {type.replace('_', ' ')}
                  </span>
                </div>
                <div className="flex items-center space-x-2">
                  <div className="w-24 bg-gray-200 rounded-full h-2">
                    <div
                      className={`h-2 rounded-full ${colorMap[type] || 'bg-gray-400'}`}
                      style={{ width: `${percentage}%` }}
                    ></div>
                  </div>
                  <span className="text-sm text-gray-600 w-12 text-right">
                    {count}
                  </span>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Top Users */}
      <div className="bg-white rounded-lg border border-gray-200 p-6">
        <h3 className="text-lg font-semibold text-gray-900 mb-4">Top Lock Holders</h3>
        <div className="space-y-3">
          {Object.entries(statistics.by_user)
            .sort(([, a], [, b]) => b - a)
            .slice(0, 5)
            .map(([userId, count]) => (
              <div key={userId} className="flex items-center justify-between">
                <div className="flex items-center space-x-2">
                  <Users className="h-4 w-4 text-gray-400" />
                  <span className="text-sm font-medium text-gray-700">
                    {userId.substring(0, 8)}...
                  </span>
                </div>
                <span className="text-sm text-gray-600">{count} locks</span>
              </div>
            ))}
        </div>
      </div>

      {/* Most Contended Resources */}
      <div className="bg-white rounded-lg border border-gray-200 p-6">
        <h3 className="text-lg font-semibold text-gray-900 mb-4">Most Contended Resources</h3>
        <div className="space-y-3">
          {statistics.most_contended_resources.slice(0, 5).map((resource) => (
            <div key={resource.resource_id} className="flex items-center justify-between">
              <div className="flex items-center space-x-2">
                <Activity className="h-4 w-4 text-gray-400" />
                <span className="text-sm font-medium text-gray-700">
                  {resource.resource_id.substring(0, 8)}...
                </span>
              </div>
              <div className="text-right">
                <span className="text-sm text-gray-600">
                  {resource.conflict_count} conflicts
                </span>
                <br />
                <span className="text-xs text-gray-500">
                  {Math.round(resource.avg_wait_time)}m avg wait
                </span>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Recent Conflicts */}
      {pendingConflicts.length > 0 && (
        <div className="bg-white rounded-lg border border-gray-200 p-6">
          <h3 className="text-lg font-semibold text-gray-900 mb-4">
            Pending Conflicts ({pendingConflicts.length})
          </h3>
          <div className="space-y-3">
            {pendingConflicts.slice(0, 10).map((conflict) => (
              <div
                key={conflict.id}
                className="flex items-center justify-between p-3 bg-red-50 border border-red-200 rounded-lg cursor-pointer hover:bg-red-100"
                onClick={() => onConflictClick(conflict)}
              >
                <div className="flex items-center space-x-3">
                  <AlertTriangle className="h-4 w-4 text-red-500" />
                  <div>
                    <p className="text-sm font-medium text-gray-900">
                      Resource: {conflict.resource_id.substring(0, 8)}...
                    </p>
                    <p className="text-xs text-gray-500">
                      Requesting: {conflict.requesting_user_id.substring(0, 8)}...
                    </p>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-sm text-gray-600 capitalize">
                    {conflict.conflict_type}
                  </p>
                  <p className="text-xs text-gray-500">
                    {new Date(conflict.created_at).toLocaleDateString()}
                  </p>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* No Data State */}
      {statistics.total_locks === 0 && (
        <div className="bg-white rounded-lg border border-gray-200 p-8">
          <div className="text-center">
            <Lock className="h-12 w-12 text-gray-400 mx-auto mb-4" />
            <h3 className="text-lg font-medium text-gray-900 mb-2">No Active Locks</h3>
            <p className="text-gray-500">
              There are currently no active locks in this workspace.
            </p>
          </div>
        </div>
      )}
    </div>
  );
};

// Epic 9.4.3 - Locking Manager Component
// Main UI component for managing locks in the workspace

import React, { useState, useEffect, useCallback } from 'react';
import { Lock, Unlock, Clock, AlertTriangle, Users, X, Settings, Filter, Search } from 'lucide-react';
import { useLockingStore } from '../stores/lockingStore';
import { LockIndicator } from './LockIndicator';
import { LockRequestDialog } from './LockRequestDialog';
import { LockBreakingWorkflow } from './LockBreakingWorkflow';
import { LockStatusOverview } from './LockStatusOverview';
import { LockQueueVisualization } from './LockQueueVisualization';
import { LockNotifications } from './LockNotifications';
import { LockPolicyEditor } from './LockPolicyEditor';

interface LockingManagerProps {
  workspaceId: string;
  userId: string;
  onLockStateChange?: (resourceId: string, isLocked: boolean) => void;
}

export const LockingManager: React.FC<LockingManagerProps> = ({
  workspaceId,
  userId,
  onLockStateChange
}) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'locks' | 'queue' | 'notifications' | 'policy'>('overview');
  const [selectedResource, setSelectedResource] = useState<string | null>(null);
  const [showRequestDialog, setShowRequestDialog] = useState(false);
  const [showBreakingWorkflow, setShowBreakingWorkflow] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [lockTypeFilter, setLockTypeFilter] = useState<string>('all');
  const [showExpiredLocks, setShowExpiredLocks] = useState(false);

  const {
    locks,
    conflicts,
    queue,
    notifications,
    statistics,
    isLoading,
    error,
    fetchLocks,
    fetchConflicts,
    fetchQueue,
    fetchNotifications,
    fetchStatistics,
    acquireLock,
    releaseLock,
    breakLock,
    clearError
  } = useLockingStore();

  // Load data on component mount
  useEffect(() => {
    fetchLocks(workspaceId);
    fetchConflicts(workspaceId);
    fetchQueue(workspaceId);
    fetchNotifications(userId);
    fetchStatistics(workspaceId);
  }, [workspaceId, userId]);

  // Auto-refresh data every 30 seconds
  useEffect(() => {
    const interval = setInterval(() => {
      fetchLocks(workspaceId);
      fetchConflicts(workspaceId);
      fetchQueue(workspaceId);
      fetchNotifications(userId);
      fetchStatistics(workspaceId);
    }, 30000);

    return () => clearInterval(interval);
  }, [workspaceId, userId]);

  const handleLockRequest = useCallback(async (resourceId: string, lockType: string, reason?: string) => {
    try {
      const result = await acquireLock({
        resource_id: resourceId,
        user_id: userId,
        lock_type: lockType,
        scope: 'resource',
        reason
      });

      if (result.success) {
        onLockStateChange?.(resourceId, true);
        setShowRequestDialog(false);
        setSelectedResource(null);
      }
    } catch (error) {
      console.error('Failed to acquire lock:', error);
    }
  }, [userId, acquireLock, onLockStateChange]);

  const handleLockRelease = useCallback(async (lockId: string, resourceId: string) => {
    try {
      const result = await releaseLock(lockId, userId);
      if (result.success) {
        onLockStateChange?.(resourceId, false);
      }
    } catch (error) {
      console.error('Failed to release lock:', error);
    }
  }, [userId, releaseLock, onLockStateChange]);

  const handleLockBreak = useCallback(async (lockId: string, resourceId: string, justification: string) => {
    try {
      const result = await breakLock(lockId, userId, justification);
      if (result.success) {
        onLockStateChange?.(resourceId, false);
        setShowBreakingWorkflow(false);
      }
    } catch (error) {
      console.error('Failed to break lock:', error);
    }
  }, [userId, breakLock, onLockStateChange]);

  const filteredLocks = locks.filter(lock => {
    const matchesSearch = !searchTerm || 
      lock.resource_id.toLowerCase().includes(searchTerm.toLowerCase()) ||
      lock.lock_reason?.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesType = lockTypeFilter === 'all' || lock.lock_type === lockTypeFilter;

    const matchesExpired = showExpiredLocks || !lock.expires_at || new Date(lock.expires_at) > new Date();

    return matchesSearch && matchesType && matchesExpired;
  });

  const unreadNotifications = notifications.filter(n => !n.read_at).length;

  if (isLoading) {
    return (
      <div className="flex items-center justify-center p-8">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
        <span className="ml-2 text-gray-600">Loading lock information...</span>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-lg shadow-lg">
      {/* Header */}
      <div className="border-b border-gray-200 px-6 py-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <Lock className="h-5 w-5 text-gray-500" />
            <h2 className="text-lg font-semibold text-gray-900">Lock Management</h2>
          </div>
          <div className="flex items-center space-x-2">
            <button
              onClick={() => setShowRequestDialog(true)}
              className="px-3 py-1 bg-blue-600 text-white rounded text-sm hover:bg-blue-700"
            >
              Request Lock
            </button>
            <button
              onClick={() => fetchLocks(workspaceId)}
              className="px-3 py-1 bg-gray-100 text-gray-700 rounded text-sm hover:bg-gray-200"
            >
              Refresh
            </button>
          </div>
        </div>

        {/* Tab Navigation */}
        <div className="flex space-x-4 mt-4">
          <button
            onClick={() => setActiveTab('overview')}
            className={`pb-2 px-1 border-b-2 font-medium text-sm ${
              activeTab === 'overview'
                ? 'border-blue-500 text-blue-600'
                : 'border-transparent text-gray-500 hover:text-gray-700'
            }`}
          >
            Overview
          </button>
          <button
            onClick={() => setActiveTab('locks')}
            className={`pb-2 px-1 border-b-2 font-medium text-sm ${
              activeTab === 'locks'
                ? 'border-blue-500 text-blue-600'
                : 'border-transparent text-gray-500 hover:text-gray-700'
            }`}
          >
            Active Locks ({filteredLocks.length})
          </button>
          <button
            onClick={() => setActiveTab('queue')}
            className={`pb-2 px-1 border-b-2 font-medium text-sm ${
              activeTab === 'queue'
                ? 'border-blue-500 text-blue-600'
                : 'border-transparent text-gray-500 hover:text-gray-700'
            }`}
          >
            Queue ({queue.length})
          </button>
          <button
            onClick={() => setActiveTab('notifications')}
            className={`pb-2 px-1 border-b-2 font-medium text-sm relative ${
              activeTab === 'notifications'
                ? 'border-blue-500 text-blue-600'
                : 'border-transparent text-gray-500 hover:text-gray-700'
            }`}
          >
            Notifications
            {unreadNotifications > 0 && (
              <span className="absolute -top-1 -right-1 h-4 w-4 bg-red-500 text-white text-xs rounded-full flex items-center justify-center">
                {unreadNotifications}
              </span>
            )}
          </button>
          <button
            onClick={() => setActiveTab('policy')}
            className={`pb-2 px-1 border-b-2 font-medium text-sm ${
              activeTab === 'policy'
                ? 'border-blue-500 text-blue-600'
                : 'border-transparent text-gray-500 hover:text-gray-700'
            }`}
          >
            Policy
          </button>
        </div>
      </div>

      {/* Error Display */}
      {error && (
        <div className="bg-red-50 border border-red-200 rounded-md p-4 m-4">
          <div className="flex items-center">
            <AlertTriangle className="h-5 w-5 text-red-400 mr-2" />
            <span className="text-red-700">{error}</span>
            <button
              onClick={clearError}
              className="ml-auto text-red-400 hover:text-red-600"
            >
              <X className="h-4 w-4" />
            </button>
          </div>
        </div>
      )}

      {/* Content */}
      <div className="p-6">
        {activeTab === 'overview' && (
          <LockStatusOverview
            statistics={statistics}
            conflicts={conflicts}
            onConflictClick={(conflict) => {
              setSelectedResource(conflict.resource_id);
              setShowBreakingWorkflow(true);
            }}
          />
        )}

        {activeTab === 'locks' && (
          <div className="space-y-4">
            {/* Filters */}
            <div className="flex items-center space-x-4 bg-gray-50 p-4 rounded-lg">
              <div className="flex items-center space-x-2">
                <Search className="h-4 w-4 text-gray-400" />
                <input
                  type="text"
                  placeholder="Search locks..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="border border-gray-300 rounded px-3 py-1 text-sm"
                />
              </div>
              <div className="flex items-center space-x-2">
                <Filter className="h-4 w-4 text-gray-400" />
                <select
                  value={lockTypeFilter}
                  onChange={(e) => setLockTypeFilter(e.target.value)}
                  className="border border-gray-300 rounded px-3 py-1 text-sm"
                >
                  <option value="all">All Types</option>
                  <option value="edit">Edit</option>
                  <option value="state_change">State Change</option>
                  <option value="delete">Delete</option>
                  <option value="admin">Admin</option>
                </select>
              </div>
              <label className="flex items-center space-x-2">
                <input
                  type="checkbox"
                  checked={showExpiredLocks}
                  onChange={(e) => setShowExpiredLocks(e.target.checked)}
                  className="rounded border-gray-300"
                />
                <span className="text-sm text-gray-700">Show expired</span>
              </label>
            </div>

            {/* Lock List */}
            <div className="space-y-2">
              {filteredLocks.map((lock) => (
                <div key={lock.id} className="border border-gray-200 rounded-lg p-4">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center space-x-3">
                      <LockIndicator
                        lock={lock}
                        size="small"
                        showTooltip={false}
                      />
                      <div>
                        <p className="font-medium text-gray-900">
                          Resource: {lock.resource_id.substring(0, 8)}...
                        </p>
                        <p className="text-sm text-gray-500">
                          Type: {lock.lock_type} • By: {lock.locked_by}
                        </p>
                        {lock.lock_reason && (
                          <p className="text-sm text-gray-600 mt-1">
                            Reason: {lock.lock_reason}
                          </p>
                        )}
                      </div>
                    </div>
                    <div className="flex items-center space-x-2">
                      {lock.expires_at && (
                        <span className="text-xs text-gray-500">
                          Expires: {new Date(lock.expires_at).toLocaleString()}
                        </span>
                      )}
                      {lock.locked_by === userId ? (
                        <button
                          onClick={() => handleLockRelease(lock.id, lock.resource_id)}
                          className="px-2 py-1 bg-green-100 text-green-700 rounded text-xs hover:bg-green-200"
                        >
                          <Unlock className="h-3 w-3" />
                          Release
                        </button>
                      ) : (
                        <button
                          onClick={() => {
                            setSelectedResource(lock.resource_id);
                            setShowBreakingWorkflow(true);
                          }}
                          className="px-2 py-1 bg-red-100 text-red-700 rounded text-xs hover:bg-red-200"
                        >
                          <AlertTriangle className="h-3 w-3" />
                          Break
                        </button>
                      )}
                    </div>
                  </div>
                </div>
              ))}
              {filteredLocks.length === 0 && (
                <div className="text-center py-8 text-gray-500">
                  No locks found matching your criteria.
                </div>
              )}
            </div>
          </div>
        )}

        {activeTab === 'queue' && (
          <LockQueueVisualization
            queue={queue}
            onRemoveFromQueue={(queueId) => {
              // Implementation for removing from queue
              console.log('Remove from queue:', queueId);
            }}
          />
        )}

        {activeTab === 'notifications' && (
          <LockNotifications
            notifications={notifications}
            onMarkAsRead={(notificationId) => {
              // Implementation for marking as read
              console.log('Mark as read:', notificationId);
            }}
          />
        )}

        {activeTab === 'policy' && (
          <LockPolicyEditor
            workspaceId={workspaceId}
            onPolicyUpdate={() => {
              // Refresh data after policy update
              fetchLocks(workspaceId);
              fetchStatistics(workspaceId);
            }}
          />
        )}
      </div>

      {/* Dialogs */}
      {showRequestDialog && (
        <LockRequestDialog
          isOpen={showRequestDialog}
          onClose={() => setShowRequestDialog(false)}
          onRequest={handleLockRequest}
          resourceId={selectedResource}
          userId={userId}
        />
      )}

      {showBreakingWorkflow && selectedResource && (
        <LockBreakingWorkflow
          isOpen={showBreakingWorkflow}
          onClose={() => setShowBreakingWorkflow(false)}
          resourceId={selectedResource}
          onBreakLock={handleLockBreak}
          userId={userId}
        />
      )}
    </div>
  );
};

