// Diff Node Renderer - Custom node component for visual diff
// Story 9.3.2 - Visual Diff Tool

import React, { memo } from 'react';
import { Handle, Position, NodeProps } from 'reactflow';

interface DiffNodeData {
  originalNode: any;
  diffState: 'added' | 'removed' | 'modified' | 'unchanged';
  changeDetails: Record<string, any>;
  showMetadata: boolean;
  side: 'source' | 'target';
  [key: string]: any;
}

export const DiffNodeRenderer = memo<NodeProps<DiffNodeData>>(({ data, selected }) => {
  const { originalNode, diffState, changeDetails, showMetadata, side } = data;

  // Get styling based on diff state
  const getNodeStyle = () => {
    const baseStyle = {
      padding: '8px 12px',
      borderRadius: '6px',
      border: '2px solid',
      minWidth: '120px',
      fontSize: '14px',
      fontWeight: '500',
      transition: 'all 0.2s ease',
      position: 'relative' as const
    };

    const stateStyles = {
      added: {
        borderColor: '#10b981',
        backgroundColor: '#ecfdf5',
        color: '#065f46'
      },
      removed: {
        borderColor: '#ef4444',
        backgroundColor: '#fef2f2',
        color: '#991b1b',
        opacity: 0.7
      },
      modified: {
        borderColor: '#f59e0b',
        backgroundColor: '#fffbeb',
        color: '#92400e'
      },
      unchanged: {
        borderColor: '#6b7280',
        backgroundColor: '#f9fafb',
        color: '#374151'
      }
    };

    return {
      ...baseStyle,
      ...stateStyles[diffState],
      ...(selected && {
        boxShadow: '0 0 0 2px #3b82f6',
        borderColor: '#3b82f6'
      })
    };
  };

  // Get badge content
  const getBadge = () => {
    const badges = {
      added: { text: '+', color: '#10b981' },
      removed: { text: '−', color: '#ef4444' },
      modified: { text: '~', color: '#f59e0b' },
      unchanged: { text: '=', color: '#6b7280' }
    };

    const badge = badges[diffState];

    return (
      <div
        className="absolute -top-2 -right-2 w-5 h-5 rounded-full text-xs font-bold flex items-center justify-center text-white"
        style={{ backgroundColor: badge.color }}
      >
        {badge.text}
      </div>
    );
  };

  // Format node label
  const getLabel = () => {
    if (originalNode.data?.label) {
      return originalNode.data.label;
    }

    if (originalNode.type) {
      return originalNode.type.charAt(0).toUpperCase() + originalNode.type.slice(1);
    }

    return originalNode.id;
  };

  // Get property changes count
  const getChangesCount = () => {
    const changes = Object.keys(changeDetails).length;
    return changes > 0 ? ` (${changes} changes)` : '';
  };

  return (
    <div style={getNodeStyle()}>
      {getBadge()}

      {/* Main Content */}
      <div>
        <div className="font-medium">{getLabel()}</div>

        {/* Type Information */}
        {originalNode.type && (
          <div className="text-xs opacity-75 mt-1">
            {originalNode.type}{getChangesCount()}
          </div>
        )}

        {/* Metadata */}
        {showMetadata && (
          <div className="mt-2 text-xs">
            <div className="opacity-75">
              Side: {side}
            </div>
            {originalNode.position && (
              <div className="opacity-75">
                Position: ({Math.round(originalNode.position.x)}, {Math.round(originalNode.position.y)})
              </div>
            )}
          </div>
        )}

        {/* Change Details */}
        {diffState === 'modified' && Object.keys(changeDetails).length > 0 && (
          <div className="mt-2 text-xs">
            <div className="font-medium opacity-75 mb-1">Changes:</div>
            <div className="space-y-1">
              {Object.entries(changeDetails).slice(0, 3).map(([key, change]) => (
                <div key={key} className="opacity-75">
                  <span className="font-medium">{key}:</span>
                  <span className="ml-1">
                    {typeof change === 'object' && change !== null
                      ? change.type || 'modified'
                      : 'changed'
                    }
                  </span>
                </div>
              ))}
              {Object.keys(changeDetails).length > 3 && (
                <div className="opacity-75">
                  +{Object.keys(changeDetails).length - 3} more...
                </div>
              )}
            </div>
          </div>
        )}
      </div>

      {/* Connection Handles */}
      <Handle 
        type="target" 
        position={Position.Left} 
        style={{ 
          background: '#6b7280',
          border: 'none',
          width: '8px',
          height: '8px'
        }}
      />
      <Handle 
        type="source" 
        position={Position.Right} 
        style={{ 
          background: '#6b7280',
          border: 'none',
          width: '8px',
          height: '8px'
        }}
      />
    </div>
  );
});

DiffNodeRenderer.displayName = 'DiffNodeRenderer';

// Version Selector - UI for selecting source and target versions
// Story 9.3.2 - Visual Diff Tool

import React, { useMemo } from 'react';

export interface Version {
  id: string;
  version_number: number;
  description: string;
  created_at: Date;
  created_by?: string;
  is_current?: boolean;
}

export interface VersionSelectorProps {
  graphId: string;
  versions: Version[];
  sourceVersionId: string;
  targetVersionId: string;
  onVersionChange: (sourceId: string, targetId: string) => void;
  className?: string;
}

export const VersionSelector: React.FC<VersionSelectorProps> = ({
  graphId,
  versions,
  sourceVersionId,
  targetVersionId,
  onVersionChange,
  className = ''
}) => {
  // Sort versions by version number (descending)
  const sortedVersions = useMemo(() => {
    return [...versions].sort((a, b) => b.version_number - a.version_number);
  }, [versions]);

  // Format version display
  const formatVersion = (version: Version) => {
    const date = new Date(version.created_at).toLocaleDateString();
    const time = new Date(version.created_at).toLocaleTimeString([], { 
      hour: '2-digit', 
      minute: '2-digit' 
    });

    return `v${version.version_number} - ${version.description || 'No description'} (${date} ${time})`;
  };

  // Handle source version change
  const handleSourceChange = (versionId: string) => {
    if (versionId !== targetVersionId) {
      onVersionChange(versionId, targetVersionId);
    }
  };

  // Handle target version change
  const handleTargetChange = (versionId: string) => {
    if (versionId !== sourceVersionId) {
      onVersionChange(sourceVersionId, versionId);
    }
  };

  // Get quick compare options (recent versions)
  const getQuickCompareOptions = () => {
    if (sortedVersions.length < 2) return [];

    return [
      {
        label: 'Current vs Previous',
        source: sortedVersions[1]?.id,
        target: sortedVersions[0]?.id
      },
      {
        label: 'Current vs 2 versions ago',
        source: sortedVersions[2]?.id,
        target: sortedVersions[0]?.id
      },
      {
        label: 'Previous vs 2 versions ago',
        source: sortedVersions[2]?.id,
        target: sortedVersions[1]?.id
      }
    ].filter(option => option.source && option.target);
  };

  const quickOptions = getQuickCompareOptions();

  if (versions.length === 0) {
    return (
      <div className={`text-center py-4 text-gray-500 ${className}`}>
        No versions available for comparison
      </div>
    );
  }

  if (versions.length === 1) {
    return (
      <div className={`text-center py-4 text-gray-500 ${className}`}>
        Need at least 2 versions to compare
      </div>
    );
  }

  return (
    <div className={`space-y-4 ${className}`}>
      {/* Version Selectors */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {/* Source Version */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            Source Version (Compare from)
          </label>
          <select
            value={sourceVersionId}
            onChange={(e) => handleSourceChange(e.target.value)}
            className="w-full rounded border-gray-300 text-sm focus:border-blue-500 focus:ring-blue-500"
          >
            <option value="">Select source version...</option>
            {sortedVersions.map((version) => (
              <option 
                key={version.id} 
                value={version.id}
                disabled={version.id === targetVersionId}
              >
                {formatVersion(version)}
                {version.is_current && ' (Current)'}
              </option>
            ))}
          </select>
        </div>

        {/* Target Version */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            Target Version (Compare to)
          </label>
          <select
            value={targetVersionId}
            onChange={(e) => handleTargetChange(e.target.value)}
            className="w-full rounded border-gray-300 text-sm focus:border-blue-500 focus:ring-blue-500"
          >
            <option value="">Select target version...</option>
            {sortedVersions.map((version) => (
              <option 
                key={version.id} 
                value={version.id}
                disabled={version.id === sourceVersionId}
              >
                {formatVersion(version)}
                {version.is_current && ' (Current)'}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* Quick Compare Options */}
      {quickOptions.length > 0 && (
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Quick Compare Options
          </label>
          <div className="flex flex-wrap gap-2">
            {quickOptions.map((option, index) => (
              <button
                key={index}
                onClick={() => onVersionChange(option.source!, option.target!)}
                className="px-3 py-1 text-sm bg-blue-50 text-blue-700 rounded border border-blue-200 hover:bg-blue-100 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-1"
              >
                {option.label}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Swap Button */}
      {sourceVersionId && targetVersionId && (
        <div className="flex justify-center">
          <button
            onClick={() => onVersionChange(targetVersionId, sourceVersionId)}
            className="flex items-center space-x-1 px-3 py-1 text-sm text-gray-600 hover:text-gray-800 border border-gray-300 rounded hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-1"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4" />
            </svg>
            <span>Swap versions</span>
          </button>
        </div>
      )}

      {/* Validation Message */}
      {sourceVersionId && targetVersionId && sourceVersionId === targetVersionId && (
        <div className="text-sm text-orange-600 bg-orange-50 border border-orange-200 rounded p-2">
          <div className="flex items-center space-x-1">
            <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
            </svg>
            <span>Please select different versions to compare</span>
          </div>
        </div>
      )}

      {/* Success Message */}
      {sourceVersionId && targetVersionId && sourceVersionId !== targetVersionId && (
        <div className="text-sm text-green-600 bg-green-50 border border-green-200 rounded p-2">
          <div className="flex items-center space-x-1">
            <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
            </svg>
            <span>Ready to compare selected versions</span>
          </div>
        </div>
      )}
    </div>
  );
};

// Visual Diff Panel - Main component for visual graph comparison
// Story 9.3.2 - Visual Diff Tool

import React, { useState, useCallback, useEffect } from 'react';
import { ReactFlow, Node, Edge, Controls, Background, Panel } from 'reactflow';
import { ComparisonToolbar } from './ComparisonToolbar';
import { DiffLegend } from './DiffLegend';
import { VersionSelector } from './VersionSelector';
import { ComparisonStats } from './ComparisonStats';
import { DiffNodeRenderer } from './DiffNodeRenderer';
import { DiffEdgeRenderer } from './DiffEdgeRenderer';
import { useDiffSession } from '../../hooks/useDiffSession';
import { useGraphVersions } from '../../hooks/useGraphVersions';
import {
  DetailedComparison,
  VisualDiffSession,
  ViewMode,
  HighlightMode,
  NodeChange,
  EdgeChange
} from '../../types/comparison';

export interface VisualDiffPanelProps {
  graphId: string;
  initialSourceVersionId?: string;
  initialTargetVersionId?: string;
  onClose?: () => void;
  className?: string;
}

export const VisualDiffPanel: React.FC<VisualDiffPanelProps> = ({
  graphId,
  initialSourceVersionId,
  initialTargetVersionId,
  onClose,
  className = ''
}) => {
  // State
  const [sourceVersionId, setSourceVersionId] = useState<string>(initialSourceVersionId || '');
  const [targetVersionId, setTargetVersionId] = useState<string>(initialTargetVersionId || '');
  const [viewMode, setViewMode] = useState<ViewMode>('side-by-side');
  const [highlightMode, setHighlightMode] = useState<HighlightMode>('changes');
  const [showUnchanged, setShowUnchanged] = useState(true);
  const [showMetadata, setShowMetadata] = useState(false);
  const [zoomLevel, setZoomLevel] = useState(1.0);

  // Hooks
  const { versions, loading: versionsLoading } = useGraphVersions(graphId);
  const { 
    session, 
    comparison, 
    loading: sessionLoading, 
    error: sessionError,
    createSession,
    updateSession 
  } = useDiffSession();

  // Effects
  useEffect(() => {
    if (sourceVersionId && targetVersionId && sourceVersionId !== targetVersionId) {
      createSession({
        graph_id: graphId,
        source_version_id: sourceVersionId,
        target_version_id: targetVersionId,
        view_mode: viewMode,
        highlight_mode: highlightMode
      });
    }
  }, [sourceVersionId, targetVersionId, graphId]);

  useEffect(() => {
    if (session) {
      updateSession(session.id, {
        view_mode: viewMode,
        highlight_mode: highlightMode,
        show_unchanged: showUnchanged,
        show_metadata: showMetadata,
        zoom_level: zoomLevel
      });
    }
  }, [viewMode, highlightMode, showUnchanged, showMetadata, zoomLevel, session?.id]);

  // Handlers
  const handleVersionChange = useCallback((source: string, target: string) => {
    setSourceVersionId(source);
    setTargetVersionId(target);
  }, []);

  const handleViewModeChange = useCallback((mode: ViewMode) => {
    setViewMode(mode);
  }, []);

  const handleHighlightModeChange = useCallback((mode: HighlightMode) => {
    setHighlightMode(mode);
  }, []);

  const handleZoomChange = useCallback((zoom: number) => {
    setZoomLevel(zoom);
  }, []);

  // Prepare nodes and edges for visualization
  const prepareVisualizationData = useCallback(() => {
    if (!comparison) return { sourceNodes: [], sourceEdges: [], targetNodes: [], targetEdges: [] };

    const sourceNodes = prepareNodes(comparison.source_data.nodes, comparison.node_matches, 'source');
    const sourceEdges = prepareEdges(comparison.source_data.edges, comparison.edge_matches, 'source');
    const targetNodes = prepareNodes(comparison.target_data.nodes, comparison.node_matches, 'target');
    const targetEdges = prepareEdges(comparison.target_data.edges, comparison.edge_matches, 'target');

    return { sourceNodes, sourceEdges, targetNodes, targetEdges };
  }, [comparison, highlightMode, showUnchanged]);

  const prepareNodes = useCallback((
    nodes: any[],
    nodeMatches: any[],
    side: 'source' | 'target'
  ): Node[] => {
    if (!comparison) return [];

    return nodes.map(node => {
      const match = nodeMatches.find(m => 
        side === 'source' ? m.source_node_id === node.id : m.target_node_id === node.id
      );

      let diffState = 'unchanged';
      let changeDetails = {};

      if (match) {
        switch (match.match_type) {
          case 'added':
            diffState = 'added';
            break;
          case 'removed':
            diffState = 'removed';
            break;
          case 'modified':
          case 'similar':
            diffState = 'modified';
            changeDetails = match.property_changes;
            break;
          case 'exact':
            diffState = 'unchanged';
            break;
        }
      }

      // Filter based on highlight mode and show unchanged setting
      if (!showUnchanged && diffState === 'unchanged') {
        return null;
      }

      if (highlightMode !== 'all') {
        switch (highlightMode) {
          case 'changes':
            if (diffState === 'unchanged') return null;
            break;
          case 'additions':
            if (diffState !== 'added') return null;
            break;
          case 'deletions':
            if (diffState !== 'removed') return null;
            break;
        }
      }

      return {
        id: node.id,
        type: 'diffNode',
        position: node.position || { x: 0, y: 0 },
        data: {
          ...node.data,
          originalNode: node,
          diffState,
          changeDetails,
          showMetadata,
          side
        },
        style: getDiffNodeStyle(diffState, highlightMode)
      };
    }).filter(Boolean) as Node[];
  }, [comparison, highlightMode, showUnchanged, showMetadata]);

  const prepareEdges = useCallback((
    edges: any[],
    edgeMatches: any[],
    side: 'source' | 'target'
  ): Edge[] => {
    if (!comparison) return [];

    return edges.map(edge => {
      const match = edgeMatches.find(m => 
        side === 'source' ? m.source_edge_id === edge.id : m.target_edge_id === edge.id
      );

      let diffState = 'unchanged';
      let changeDetails = {};

      if (match) {
        switch (match.match_type) {
          case 'added':
            diffState = 'added';
            break;
          case 'removed':
            diffState = 'removed';
            break;
          case 'modified':
          case 'similar':
            diffState = 'modified';
            changeDetails = match.property_changes;
            break;
          case 'exact':
            diffState = 'unchanged';
            break;
        }
      }

      // Filter based on highlight mode and show unchanged setting
      if (!showUnchanged && diffState === 'unchanged') {
        return null;
      }

      if (highlightMode !== 'all') {
        switch (highlightMode) {
          case 'changes':
            if (diffState === 'unchanged') return null;
            break;
          case 'additions':
            if (diffState !== 'added') return null;
            break;
          case 'deletions':
            if (diffState !== 'removed') return null;
            break;
        }
      }

      return {
        id: edge.id,
        source: edge.source,
        target: edge.target,
        type: 'diffEdge',
        data: {
          ...edge.data,
          originalEdge: edge,
          diffState,
          changeDetails,
          side
        },
        style: getDiffEdgeStyle(diffState, highlightMode)
      };
    }).filter(Boolean) as Edge[];
  }, [comparison, highlightMode, showUnchanged]);

  // Get node styling based on diff state
  const getDiffNodeStyle = (diffState: string, highlightMode: HighlightMode) => {
    const baseStyle = {
      border: '2px solid',
      borderRadius: '6px',
      transition: 'all 0.2s ease'
    };

    switch (diffState) {
      case 'added':
        return { ...baseStyle, borderColor: '#10b981', backgroundColor: '#ecfdf5' };
      case 'removed':
        return { ...baseStyle, borderColor: '#ef4444', backgroundColor: '#fef2f2', opacity: 0.7 };
      case 'modified':
        return { ...baseStyle, borderColor: '#f59e0b', backgroundColor: '#fffbeb' };
      default:
        return { ...baseStyle, borderColor: '#6b7280', backgroundColor: '#f9fafb' };
    }
  };

  // Get edge styling based on diff state
  const getDiffEdgeStyle = (diffState: string, highlightMode: HighlightMode) => {
    const baseStyle = {
      strokeWidth: 2,
      transition: 'all 0.2s ease'
    };

    switch (diffState) {
      case 'added':
        return { ...baseStyle, stroke: '#10b981' };
      case 'removed':
        return { ...baseStyle, stroke: '#ef4444', opacity: 0.7, strokeDasharray: '5,5' };
      case 'modified':
        return { ...baseStyle, stroke: '#f59e0b' };
      default:
        return { ...baseStyle, stroke: '#6b7280' };
    }
  };

  // Render loading state
  if (versionsLoading || sessionLoading) {
    return (
      <div className={`visual-diff-panel ${className}`}>
        <div className="flex items-center justify-center h-64">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-500"></div>
          <span className="ml-2">Loading comparison...</span>
        </div>
      </div>
    );
  }

  // Render error state
  if (sessionError) {
    return (
      <div className={`visual-diff-panel ${className}`}>
        <div className="bg-red-50 border border-red-200 rounded-md p-4">
          <div className="flex">
            <div className="flex-shrink-0">
              <svg className="h-5 w-5 text-red-400" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
              </svg>
            </div>
            <div className="ml-3">
              <h3 className="text-sm font-medium text-red-800">Comparison Error</h3>
              <p className="mt-1 text-sm text-red-700">{sessionError}</p>
            </div>
          </div>
        </div>
      </div>
    );
  }

  const { sourceNodes, sourceEdges, targetNodes, targetEdges } = prepareVisualizationData();

  // Custom node types
  const nodeTypes = {
    diffNode: DiffNodeRenderer
  };

  // Custom edge types
  const edgeTypes = {
    diffEdge: DiffEdgeRenderer
  };

  return (
    <div className={`visual-diff-panel ${className}`}>
      {/* Header */}
      <div className="border-b border-gray-200 bg-white px-4 py-3">
        <div className="flex items-center justify-between">
          <h2 className="text-lg font-semibold text-gray-900">Visual Diff</h2>
          {onClose && (
            <button
              onClick={onClose}
              className="text-gray-400 hover:text-gray-600 transition-colors"
            >
              <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          )}
        </div>

        {/* Version Selector */}
        <VersionSelector
          graphId={graphId}
          versions={versions}
          sourceVersionId={sourceVersionId}
          targetVersionId={targetVersionId}
          onVersionChange={handleVersionChange}
          className="mt-3"
        />

        {/* Comparison Stats */}
        {comparison && (
          <ComparisonStats
            comparison={comparison}
            className="mt-3"
          />
        )}
      </div>

      {/* Toolbar */}
      <ComparisonToolbar
        viewMode={viewMode}
        highlightMode={highlightMode}
        showUnchanged={showUnchanged}
        showMetadata={showMetadata}
        zoomLevel={zoomLevel}
        onViewModeChange={handleViewModeChange}
        onHighlightModeChange={handleHighlightModeChange}
        onShowUnchangedChange={setShowUnchanged}
        onShowMetadataChange={setShowMetadata}
        onZoomChange={handleZoomChange}
        className="border-b border-gray-200"
      />

      {/* Main Content */}
      <div className="flex-1 relative">
        {viewMode === 'side-by-side' && (
          <div className="flex h-full">
            {/* Source Graph */}
            <div className="flex-1 border-r border-gray-200">
              <div className="h-full relative">
                <div className="absolute top-2 left-2 z-10 bg-white rounded px-2 py-1 shadow-sm text-sm font-medium text-gray-700">
                  Source Version
                </div>
                <ReactFlow
                  nodes={sourceNodes}
                  edges={sourceEdges}
                  nodeTypes={nodeTypes}
                  edgeTypes={edgeTypes}
                  fitView
                  zoomOnScroll={false}
                  panOnScroll
                  defaultZoom={zoomLevel}
                >
                  <Background />
                  <Controls showInteractive={false} />
                </ReactFlow>
              </div>
            </div>

            {/* Target Graph */}
            <div className="flex-1">
              <div className="h-full relative">
                <div className="absolute top-2 left-2 z-10 bg-white rounded px-2 py-1 shadow-sm text-sm font-medium text-gray-700">
                  Target Version
                </div>
                <ReactFlow
                  nodes={targetNodes}
                  edges={targetEdges}
                  nodeTypes={nodeTypes}
                  edgeTypes={edgeTypes}
                  fitView
                  zoomOnScroll={false}
                  panOnScroll
                  defaultZoom={zoomLevel}
                >
                  <Background />
                  <Controls showInteractive={false} />
                </ReactFlow>
              </div>
            </div>
          </div>
        )}

        {viewMode === 'unified' && (
          <div className="h-full">
            <ReactFlow
              nodes={[...sourceNodes, ...targetNodes]}
              edges={[...sourceEdges, ...targetEdges]}
              nodeTypes={nodeTypes}
              edgeTypes={edgeTypes}
              fitView
              zoomOnScroll={false}
              panOnScroll
              defaultZoom={zoomLevel}
            >
              <Background />
              <Controls showInteractive={false} />
            </ReactFlow>
          </div>
        )}

        {viewMode === 'overlay' && (
          <div className="h-full relative">
            {/* Base layer - source */}
            <div className="absolute inset-0">
              <ReactFlow
                nodes={sourceNodes}
                edges={sourceEdges}
                nodeTypes={nodeTypes}
                edgeTypes={edgeTypes}
                fitView
                zoomOnScroll={false}
                panOnScroll
                defaultZoom={zoomLevel}
              >
                <Background />
                <Controls showInteractive={false} />
              </ReactFlow>
            </div>

            {/* Overlay layer - target */}
            <div className="absolute inset-0 opacity-70">
              <ReactFlow
                nodes={targetNodes}
                edges={targetEdges}
                nodeTypes={nodeTypes}
                edgeTypes={edgeTypes}
                fitView
                zoomOnScroll={false}
                panOnScroll
                defaultZoom={zoomLevel}
              >
                <Background />
              </ReactFlow>
            </div>
          </div>
        )}

        {/* Legend */}
        <DiffLegend
          highlightMode={highlightMode}
          className="absolute bottom-4 right-4 z-10"
        />
      </div>
    </div>
  );
};

