import React from 'react';
import { ConnectionState } from '../websocket/WebSocketClient';

interface WebSocketStatusProps {
  connectionState: ConnectionState;
  queuedMessages?: number;
  className?: string;
  showDetails?: boolean;
}

export const WebSocketStatus: React.FC<WebSocketStatusProps> = ({
  connectionState,
  queuedMessages = 0,
  className = '',
  showDetails = false
}) => {
  const getStatusColor = (status: ConnectionState['status']): string => {
    switch (status) {
      case 'connected':
      case 'authenticated':
        return 'text-green-500';
      case 'connecting':
      case 'authenticating':
        return 'text-yellow-500';
      case 'disconnected':
        return 'text-gray-500';
      case 'error':
        return 'text-red-500';
      default:
        return 'text-gray-500';
    }
  };

  const getStatusIcon = (status: ConnectionState['status']): string => {
    switch (status) {
      case 'connected':
      case 'authenticated':
        return '●';
      case 'connecting':
      case 'authenticating':
        return '◐';
      case 'disconnected':
        return '○';
      case 'error':
        return '✕';
      default:
        return '○';
    }
  };

  const getStatusText = (status: ConnectionState['status']): string => {
    switch (status) {
      case 'connected':
        return 'Connected';
      case 'authenticated':
        return 'Connected & Authenticated';
      case 'connecting':
        return 'Connecting...';
      case 'authenticating':
        return 'Authenticating...';
      case 'disconnected':
        return 'Disconnected';
      case 'error':
        return 'Connection Error';
      default:
        return 'Unknown';
    }
  };

  const formatTime = (timestamp?: number): string => {
    if (!timestamp) return 'Never';
    const date = new Date(timestamp);
    return date.toLocaleTimeString();
  };

  return (
    <div className={`flex items-center space-x-2 ${className}`}>
      <span 
        className={`text-sm font-mono ${getStatusColor(connectionState.status)}`}
        title={`Status: ${getStatusText(connectionState.status)}`}
      >
        {getStatusIcon(connectionState.status)}
      </span>

      <span className="text-sm text-gray-600">
        {getStatusText(connectionState.status)}
      </span>

      {connectionState.reconnectAttempts > 0 && (
        <span className="text-xs text-yellow-600">
          (Retry {connectionState.reconnectAttempts})
        </span>
      )}

      {queuedMessages > 0 && (
        <span className="text-xs bg-blue-100 text-blue-800 px-2 py-1 rounded">
          {queuedMessages} queued
        </span>
      )}

      {connectionState.error && (
        <span 
          className="text-xs text-red-600 cursor-help" 
          title={connectionState.error}
        >
          ⚠
        </span>
      )}

      {showDetails && (
        <div className="text-xs text-gray-500 space-x-2">
          {connectionState.lastConnected && (
            <span>
              Last connected: {formatTime(connectionState.lastConnected)}
            </span>
          )}
        </div>
      )}
    </div>
  );
};

