/**
 * Epic 9.2.3 - Activity Filters Component
 * Filter controls for activity feed
 */

import React, { useState } from 'react';
import { ActivityEventFilter } from '../../types/workspace';

interface ActivityFiltersProps {
  filters: ActivityEventFilter;
  eventTypes: string[];
  onFilterChange: (filters: Partial<ActivityEventFilter>) => void;
  className?: string;
}

export const ActivityFilters: React.FC<ActivityFiltersProps> = ({
  filters,
  eventTypes,
  onFilterChange,
  className = '',
}) => {
  const [showAdvanced, setShowAdvanced] = useState(false);
  const [dateRange, setDateRange] = useState({
    from: filters.from_date ? filters.from_date.toISOString().split('T')[0] : '',
    to: filters.to_date ? filters.to_date.toISOString().split('T')[0] : '',
  });

  const handleEventTypeChange = (eventType: string, checked: boolean) => {
    const currentTypes = filters.event_types || [];
    const newTypes = checked
      ? [...currentTypes, eventType]
      : currentTypes.filter(t => t !== eventType);

    onFilterChange({ event_types: newTypes.length > 0 ? newTypes : undefined });
  };

  const handleDateRangeChange = (field: 'from' | 'to', value: string) => {
    const newDateRange = { ...dateRange, [field]: value };
    setDateRange(newDateRange);

    onFilterChange({
      from_date: newDateRange.from ? new Date(newDateRange.from) : undefined,
      to_date: newDateRange.to ? new Date(newDateRange.to) : undefined,
    });
  };

  const clearFilters = () => {
    setDateRange({ from: '', to: '' });
    onFilterChange({
      actor_id: undefined,
      event_types: undefined,
      from_date: undefined,
      to_date: undefined,
    });
  };

  const hasActiveFilters = !!(
    filters.actor_id ||
    (filters.event_types && filters.event_types.length > 0) ||
    filters.from_date ||
    filters.to_date
  );

  const eventTypeGroups = {
    workspace: eventTypes.filter(t => t.startsWith('workspace.')),
    project: eventTypes.filter(t => t.startsWith('project.')),
    resource: eventTypes.filter(t => t.startsWith('resource.')),
    comment: eventTypes.filter(t => t.startsWith('comment.')),
    user: eventTypes.filter(t => t.startsWith('user.')),
    other: eventTypes.filter(t => !['workspace.', 'project.', 'resource.', 'comment.', 'user.'].some(prefix => t.startsWith(prefix))),
  };

  return (
    <div className={`activity-filters ${className}`}>
      <div className="activity-filters__header">
        <h4>Filter Activity</h4>
        <div className="activity-filters__actions">
          {hasActiveFilters && (
            <button
              className="btn btn--ghost btn--small"
              onClick={clearFilters}
            >
              Clear Filters
            </button>
          )}
          <button
            className="btn btn--ghost btn--small"
            onClick={() => setShowAdvanced(!showAdvanced)}
          >
            {showAdvanced ? 'Simple' : 'Advanced'}
          </button>
        </div>
      </div>

      <div className="activity-filters__content">
        {/* Quick Filters */}
        <div className="filter-group">
          <label className="filter-label">Quick Filters</label>
          <div className="quick-filters">
            <button
              className={`quick-filter ${!hasActiveFilters ? 'quick-filter--active' : ''}`}
              onClick={clearFilters}
            >
              All Activity
            </button>
            <button
              className={`quick-filter ${filters.event_types?.includes('comment.created') ? 'quick-filter--active' : ''}`}
              onClick={() => onFilterChange({ event_types: ['comment.created'] })}
            >
              Comments
            </button>
            <button
              className={`quick-filter ${filters.event_types?.some(t => t.includes('created')) ? 'quick-filter--active' : ''}`}
              onClick={() => onFilterChange({ 
                event_types: eventTypes.filter(t => t.includes('created'))
              })}
            >
              Created Items
            </button>
            <button
              className={`quick-filter ${filters.event_types?.some(t => t.startsWith('user.')) ? 'quick-filter--active' : ''}`}
              onClick={() => onFilterChange({ 
                event_types: eventTypes.filter(t => t.startsWith('user.'))
              })}
            >
              User Activity
            </button>
          </div>
        </div>

        {/* Date Range */}
        <div className="filter-group">
          <label className="filter-label">Date Range</label>
          <div className="date-range-inputs">
            <input
              type="date"
              value={dateRange.from}
              onChange={(e) => handleDateRangeChange('from', e.target.value)}
              className="form-input form-input--small"
              placeholder="From date"
            />
            <span className="date-range-separator">to</span>
            <input
              type="date"
              value={dateRange.to}
              onChange={(e) => handleDateRangeChange('to', e.target.value)}
              className="form-input form-input--small"
              placeholder="To date"
            />
          </div>
        </div>

        {/* User Filter */}
        <div className="filter-group">
          <label className="filter-label">User</label>
          <input
            type="text"
            value={filters.actor_id || ''}
            onChange={(e) => onFilterChange({ actor_id: e.target.value || undefined })}
            placeholder="Filter by user ID..."
            className="form-input form-input--small"
          />
        </div>

        {/* Advanced Filters */}
        {showAdvanced && (
          <div className="filter-group filter-group--advanced">
            <label className="filter-label">Event Types</label>
            <div className="event-type-filters">
              {Object.entries(eventTypeGroups).map(([group, types]) => {
                if (types.length === 0) return null;

                return (
                  <div key={group} className="event-type-group">
                    <h5 className="event-type-group__title">
                      {group.charAt(0).toUpperCase() + group.slice(1)} Events
                    </h5>
                    <div className="event-type-checkboxes">
                      {types.map(eventType => (
                        <label key={eventType} className="checkbox-label">
                          <input
                            type="checkbox"
                            checked={filters.event_types?.includes(eventType) || false}
                            onChange={(e) => handleEventTypeChange(eventType, e.target.checked)}
                          />
                          <span className="checkbox-text">
                            {eventType.replace(/[._]/g, ' ')}
                          </span>
                        </label>
                      ))}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </div>

      {/* Active Filters Summary */}
      {hasActiveFilters && (
        <div className="activity-filters__summary">
          <div className="active-filters">
            <span className="active-filters__label">Active filters:</span>
            <div className="active-filters__tags">
              {filters.actor_id && (
                <span className="filter-tag">
                  User: {filters.actor_id}
                  <button onClick={() => onFilterChange({ actor_id: undefined })}>×</button>
                </span>
              )}
              {filters.event_types?.map(type => (
                <span key={type} className="filter-tag">
                  {type.replace(/[._]/g, ' ')}
                  <button onClick={() => handleEventTypeChange(type, false)}>×</button>
                </span>
              ))}
              {filters.from_date && (
                <span className="filter-tag">
                  From: {filters.from_date.toLocaleDateString()}
                  <button onClick={() => handleDateRangeChange('from', '')}>×</button>
                </span>
              )}
              {filters.to_date && (
                <span className="filter-tag">
                  To: {filters.to_date.toLocaleDateString()}
                  <button onClick={() => handleDateRangeChange('to', '')}>×</button>
                </span>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ActivityFilters;

/**
 * Epic 9.2.3 - Activity Item Component
 * Individual activity event display component
 */

import React from 'react';
import { ActivityEventWithActorInfo } from '../../types/workspace';

interface ActivityItemProps {
  activity: ActivityEventWithActorInfo;
  onClick?: () => void;
  compact?: boolean;
  showProject?: boolean;
  isLast?: boolean;
}

export const ActivityItem: React.FC<ActivityItemProps> = ({
  activity,
  onClick,
  compact = false,
  showProject = true,
  isLast = false,
}) => {
  const getActivityIcon = (eventType: string) => {
    if (eventType.includes('created')) return '✨';
    if (eventType.includes('updated')) return '✏️';
    if (eventType.includes('deleted')) return '🗑️';
    if (eventType.includes('invited')) return '👥';
    if (eventType.includes('comment')) return '💬';
    if (eventType.includes('archived')) return '📦';
    return '📝';
  };

  const getActivityTitle = () => {
    const { event_type, event_data, actor_name, actor_id } = activity;
    const actorDisplay = actor_name || actor_id;

    switch (event_type) {
      case 'workspace.created':
        return `${actorDisplay} created the workspace`;
      case 'workspace.updated':
        return `${actorDisplay} updated workspace settings`;
      case 'workspace.archived':
        return `${actorDisplay} archived the workspace`;

      case 'project.created':
        return `${actorDisplay} created project "${event_data.project_name}"`;
      case 'project.updated':
        return `${actorDisplay} updated project settings`;
      case 'project.deleted':
        return `${actorDisplay} deleted a project`;

      case 'resource.created':
        return `${actorDisplay} created ${event_data.resource_type} "${event_data.resource_name}"`;
      case 'resource.updated':
        return `${actorDisplay} updated a ${event_data.resource_type}`;
      case 'resource.deleted':
        return `${actorDisplay} deleted a ${event_data.resource_type}`;

      case 'comment.created':
        return `${actorDisplay} added a comment`;
      case 'comment.updated':
        return `${actorDisplay} edited a comment`;
      case 'comment.deleted':
        return `${actorDisplay} deleted a comment`;

      case 'user.invited':
        return `${actorDisplay} invited ${event_data.invited_user} as ${event_data.role}`;
      case 'user.joined':
        return `${actorDisplay} joined the workspace`;
      case 'user.left':
        return `${actorDisplay} left the workspace`;

      default:
        return `${actorDisplay} performed ${event_type.replace(/[._]/g, ' ')}`;
    }
  };

  const getActivityDescription = () => {
    const { event_type, event_data } = activity;

    if (compact) return null;

    switch (event_type) {
      case 'workspace.updated':
        return event_data.changes ? 
          `Updated: ${event_data.changes.join(', ')}` : 
          'Updated workspace settings';

      case 'project.created':
        return event_data.description || 'New project created';

      case 'resource.created':
        return `Created new ${event_data.resource_type} in the project`;

      case 'comment.created':
        if (event_data.target_type === 'node') {
          return 'Commented on a graph node';
        } else if (event_data.target_type === 'region') {
          return 'Commented on a graph region';
        }
        return 'Added a comment to the resource';

      case 'user.invited':
        return `Invited with ${event_data.role} permissions`;

      default:
        return null;
    }
  };

  const formatTime = (date: Date) => {
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);

    if (diffMins < 1) return 'Just now';
    if (diffMins < 60) return `${diffMins}m ago`;
    if (diffHours < 24) return `${diffHours}h ago`;
    if (diffDays < 7) return `${diffDays}d ago`;

    return date.toLocaleDateString();
  };

  const title = getActivityTitle();
  const description = getActivityDescription();
  const icon = getActivityIcon(activity.event_type);

  return (
    <div 
      className={`activity-item ${compact ? 'activity-item--compact' : ''} ${onClick ? 'activity-item--clickable' : ''} ${isLast ? 'activity-item--last' : ''}`}
      onClick={onClick}
    >
      <div className="activity-item__icon">
        {icon}
      </div>

      <div className="activity-item__content">
        <div className="activity-item__header">
          <div className="activity-item__title">
            {title}
          </div>
          <div className="activity-item__time">
            {formatTime(new Date(activity.created_at))}
          </div>
        </div>

        {description && (
          <div className="activity-item__description">
            {description}
          </div>
        )}

        {showProject && activity.project_name && (
          <div className="activity-item__context">
            <span className="activity-item__project">
              📁 {activity.project_name}
            </span>
            {activity.resource_name && (
              <span className="activity-item__resource">
                • {activity.resource_name}
              </span>
            )}
          </div>
        )}

        {!compact && (
          <div className="activity-item__meta">
            <span className="activity-item__event-type">
              {activity.event_type}
            </span>
            {activity.aggregation_key && (
              <span className="activity-item__group">
                Grouped
              </span>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default ActivityItem;

/**
 * Epic 9.2.3 - Activity Stats Component
 * Statistics dashboard for workspace activity
 */

import React, { useState } from 'react';

interface ActivityStatsData {
  total_events: number;
  events_by_type: Record<string, number>;
  events_by_day: Array<{ date: string; count: number }>;
  most_active_users: Array<{ user_id: string; count: number }>;
}

interface ActivityStatsProps {
  stats: ActivityStatsData;
  workspaceId: string;
  className?: string;
}

export const ActivityStats: React.FC<ActivityStatsProps> = ({
  stats,
  workspaceId,
  className = '',
}) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'types' | 'timeline' | 'users'>('overview');

  const topEventTypes = Object.entries(stats.events_by_type)
    .sort(([, a], [, b]) => b - a)
    .slice(0, 5);

  const recentDays = stats.events_by_day.slice(-7);
  const maxDayCount = Math.max(...recentDays.map(d => d.count), 1);

  const formatEventType = (type: string) => {
    return type.replace(/[._]/g, ' ').replace(/\b\w/g, l => l.toUpperCase());
  };

  return (
    <div className={`activity-stats ${className}`}>
      <div className="activity-stats__header">
        <h3>Activity Overview</h3>
        <div className="activity-stats__period">
          Last 30 days
        </div>
      </div>

      <div className="activity-stats__tabs">
        <button
          className={`stats-tab ${activeTab === 'overview' ? 'stats-tab--active' : ''}`}
          onClick={() => setActiveTab('overview')}
        >
          Overview
        </button>
        <button
          className={`stats-tab ${activeTab === 'types' ? 'stats-tab--active' : ''}`}
          onClick={() => setActiveTab('types')}
        >
          Event Types
        </button>
        <button
          className={`stats-tab ${activeTab === 'timeline' ? 'stats-tab--active' : ''}`}
          onClick={() => setActiveTab('timeline')}
        >
          Timeline
        </button>
        <button
          className={`stats-tab ${activeTab === 'users' ? 'stats-tab--active' : ''}`}
          onClick={() => setActiveTab('users')}
        >
          Active Users
        </button>
      </div>

      <div className="activity-stats__content">
        {activeTab === 'overview' && (
          <div className="stats-overview">
            <div className="stats-grid">
              <div className="stat-card">
                <div className="stat-card__value">{stats.total_events}</div>
                <div className="stat-card__label">Total Events</div>
              </div>

              <div className="stat-card">
                <div className="stat-card__value">{Object.keys(stats.events_by_type).length}</div>
                <div className="stat-card__label">Event Types</div>
              </div>

              <div className="stat-card">
                <div className="stat-card__value">{stats.most_active_users.length}</div>
                <div className="stat-card__label">Active Users</div>
              </div>

              <div className="stat-card">
                <div className="stat-card__value">
                  {Math.round(stats.total_events / Math.max(stats.events_by_day.length, 1))}
                </div>
                <div className="stat-card__label">Avg/Day</div>
              </div>
            </div>

            <div className="overview-summary">
              <h4>Summary</h4>
              <div className="summary-items">
                <div className="summary-item">
                  <strong>Most common activity:</strong> {
                    topEventTypes.length > 0 
                      ? formatEventType(topEventTypes[0][0])
                      : 'None'
                  }
                </div>
                <div className="summary-item">
                  <strong>Most active user:</strong> {
                    stats.most_active_users.length > 0
                      ? stats.most_active_users[0].user_id
                      : 'None'
                  }
                </div>
                <div className="summary-item">
                  <strong>Recent activity:</strong> {
                    recentDays.length > 0
                      ? `${recentDays[recentDays.length - 1].count} events today`
                      : 'No recent activity'
                  }
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'types' && (
          <div className="stats-types">
            <h4>Events by Type</h4>
            <div className="event-type-chart">
              {topEventTypes.map(([type, count]) => {
                const percentage = (count / stats.total_events) * 100;
                return (
                  <div key={type} className="event-type-bar">
                    <div className="event-type-bar__info">
                      <span className="event-type-bar__label">
                        {formatEventType(type)}
                      </span>
                      <span className="event-type-bar__count">
                        {count} ({percentage.toFixed(1)}%)
                      </span>
                    </div>
                    <div className="event-type-bar__track">
                      <div 
                        className="event-type-bar__fill"
                        style={{ width: `${percentage}%` }}
                      ></div>
                    </div>
                  </div>
                );
              })}
            </div>

            {Object.keys(stats.events_by_type).length > 5 && (
              <div className="stats-note">
                Showing top 5 event types out of {Object.keys(stats.events_by_type).length} total
              </div>
            )}
          </div>
        )}

        {activeTab === 'timeline' && (
          <div className="stats-timeline">
            <h4>Activity Timeline (Last 7 Days)</h4>
            <div className="timeline-chart">
              {recentDays.map((day, index) => {
                const height = Math.max((day.count / maxDayCount) * 100, 2);
                const date = new Date(day.date);
                const dayName = date.toLocaleDateString('en-US', { weekday: 'short' });

                return (
                  <div key={day.date} className="timeline-bar">
                    <div className="timeline-bar__column">
                      <div 
                        className="timeline-bar__fill"
                        style={{ height: `${height}%` }}
                        title={`${day.count} events on ${date.toLocaleDateString()}`}
                      ></div>
                    </div>
                    <div className="timeline-bar__label">
                      <div className="timeline-bar__day">{dayName}</div>
                      <div className="timeline-bar__count">{day.count}</div>
                    </div>
                  </div>
                );
              })}
            </div>

            {recentDays.length === 0 && (
              <div className="stats-empty">
                No activity data available for the selected period.
              </div>
            )}
          </div>
        )}

        {activeTab === 'users' && (
          <div className="stats-users">
            <h4>Most Active Users</h4>
            <div className="user-activity-list">
              {stats.most_active_users.slice(0, 10).map((user, index) => {
                const percentage = (user.count / stats.total_events) * 100;
                return (
                  <div key={user.user_id} className="user-activity-item">
                    <div className="user-activity-item__rank">
                      #{index + 1}
                    </div>
                    <div className="user-activity-item__user">
                      <div className="user-avatar user-avatar--small">
                        {user.user_id.charAt(0).toUpperCase()}
                      </div>
                      <div className="user-info">
                        <div className="user-name">{user.user_id}</div>
                        <div className="user-stats">
                          {user.count} events ({percentage.toFixed(1)}%)
                        </div>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>

            {stats.most_active_users.length === 0 && (
              <div className="stats-empty">
                No user activity data available.
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default ActivityStats;

