                  type="url"
                  value={formData.website}
                  onChange={(e) => setFormData(prev => ({ ...prev, website: e.target.value }))}
                  className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  placeholder="https://example.com"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Plan
                </label>
                <select
                  value={formData.plan}
                  onChange={(e) => setFormData(prev => ({ ...prev, plan: e.target.value as 'free' | 'pro' | 'enterprise' }))}
                  className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                >
                  <option value="free">Free</option>
                  <option value="pro">Pro</option>
                  <option value="enterprise">Enterprise</option>
                </select>
              </div>
            </div>

            <div className="flex space-x-3 mt-6">
              <button
                onClick={() => {
                  setShowCreateForm(false);
                  setEditingOrg(null);
                  resetForm();
                }}
                className="flex-1 px-4 py-2 text-gray-700 bg-gray-100 rounded-lg hover:bg-gray-200 transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={editingOrg ? updateOrganization : createOrganization}
                disabled={!formData.name.trim()}
                className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                {editingOrg ? 'Update' : 'Create'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// Epic 11.4 Team Manager Component
// React component for team management with hierarchical structure and member management

import React, { useState, useEffect } from 'react';
import { 
  Users, 
  Plus, 
  Edit2, 
  Trash2, 
  Crown,
  Shield,
  User,
  Eye,
  ChevronRight,
  ChevronDown,
  UserPlus,
  Settings,
  Activity
} from 'lucide-react';

interface Team {
  id: string;
  organizationId: string;
  parentTeamId?: string;
  name: string;
  description?: string;
  settings: Record<string, any>;
  createdAt: Date;
  updatedAt: Date;
  level?: number;
  path?: string[];
}

interface TeamMember {
  id: string;
  userId: string;
  role: 'owner' | 'admin' | 'member' | 'viewer';
  joinedAt: Date;
  invitedBy?: string;
  user: {
    id: string;
    email: string;
    displayName?: string;
    firstName?: string;
    lastName?: string;
    avatarUrl?: string;
  };
}

interface CreateTeamData {
  name: string;
  description?: string;
  parentTeamId?: string;
  settings?: Record<string, any>;
}

interface TeamManagerProps {
  organizationId: string;
}

export const TeamManager: React.FC<TeamManagerProps> = ({ organizationId }) => {
  const [teams, setTeams] = useState<Team[]>([]);
  const [selectedTeam, setSelectedTeam] = useState<Team | null>(null);
  const [teamMembers, setTeamMembers] = useState<TeamMember[]>([]);
  const [activeTab, setActiveTab] = useState<'overview' | 'members' | 'settings'>('overview');
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [editingTeam, setEditingTeam] = useState<Team | null>(null);
  const [showAddMember, setShowAddMember] = useState(false);
  const [expandedTeams, setExpandedTeams] = useState<Set<string>>(new Set());
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Form state
  const [formData, setFormData] = useState<CreateTeamData>({
    name: '',
    description: '',
    parentTeamId: '',
    settings: {},
  });

  const [memberFormData, setMemberFormData] = useState({
    userId: '',
    role: 'member' as 'owner' | 'admin' | 'member' | 'viewer',
  });

  useEffect(() => {
    loadTeams();
  }, [organizationId]);

  useEffect(() => {
    if (selectedTeam) {
      loadTeamMembers(selectedTeam.id);
    }
  }, [selectedTeam]);

  const loadTeams = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/auth/organizations/${organizationId}/teams/hierarchy`, {
        credentials: 'include',
      });

      if (!response.ok) {
        throw new Error('Failed to load teams');
      }

      const data = await response.json();
      setTeams(data.data);

      // Auto-select first team
      if (data.data.length > 0 && !selectedTeam) {
        setSelectedTeam(data.data[0]);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load teams');
    } finally {
      setLoading(false);
    }
  };

  const loadTeamMembers = async (teamId: string) => {
    try {
      const response = await fetch(`/api/auth/teams/${teamId}/members`, {
        credentials: 'include',
      });

      if (!response.ok) {
        throw new Error('Failed to load team members');
      }

      const data = await response.json();
      setTeamMembers(data.data);
    } catch (err) {
      console.error('Failed to load team members:', err);
    }
  };

  const createTeam = async () => {
    try {
      const response = await fetch(`/api/auth/organizations/${organizationId}/teams`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        credentials: 'include',
        body: JSON.stringify({
          ...formData,
          parentTeamId: formData.parentTeamId || undefined,
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Failed to create team');
      }

      const data = await response.json();
      await loadTeams(); // Reload to get hierarchy
      setSelectedTeam(data.data);
      setShowCreateForm(false);
      resetForm();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to create team');
    }
  };

  const updateTeam = async () => {
    if (!editingTeam) return;

    try {
      const response = await fetch(`/api/auth/teams/${editingTeam.id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        credentials: 'include',
        body: JSON.stringify({
          ...formData,
          parentTeamId: formData.parentTeamId || undefined,
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Failed to update team');
      }

      await loadTeams();
      setEditingTeam(null);
      resetForm();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to update team');
    }
  };

  const deleteTeam = async (teamId: string) => {
    if (!confirm('Are you sure you want to delete this team? This action cannot be undone.')) {
      return;
    }

    try {
      const response = await fetch(`/api/auth/teams/${teamId}`, {
        method: 'DELETE',
        credentials: 'include',
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Failed to delete team');
      }

      await loadTeams();

      if (selectedTeam?.id === teamId) {
        setSelectedTeam(teams.find(team => team.id !== teamId) || null);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to delete team');
    }
  };

  const addTeamMember = async () => {
    if (!selectedTeam) return;

    try {
      const response = await fetch(`/api/auth/teams/${selectedTeam.id}/members`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        credentials: 'include',
        body: JSON.stringify(memberFormData),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Failed to add team member');
      }

      await loadTeamMembers(selectedTeam.id);
      setShowAddMember(false);
      setMemberFormData({ userId: '', role: 'member' });
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to add team member');
    }
  };

  const removeTeamMember = async (userId: string) => {
    if (!selectedTeam || !confirm('Are you sure you want to remove this member?')) return;

    try {
      const response = await fetch(`/api/auth/teams/${selectedTeam.id}/members/${userId}`, {
        method: 'DELETE',
        credentials: 'include',
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Failed to remove team member');
      }

      await loadTeamMembers(selectedTeam.id);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to remove team member');
    }
  };

  const updateMemberRole = async (userId: string, newRole: string) => {
    if (!selectedTeam) return;

    try {
      const response = await fetch(`/api/auth/teams/${selectedTeam.id}/members/${userId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        credentials: 'include',
        body: JSON.stringify({ role: newRole }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Failed to update member role');
      }

      await loadTeamMembers(selectedTeam.id);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to update member role');
    }
  };

  const resetForm = () => {
    setFormData({
      name: '',
      description: '',
      parentTeamId: '',
      settings: {},
    });
  };

  const startEditing = (team: Team) => {
    setEditingTeam(team);
    setFormData({
      name: team.name,
      description: team.description || '',
      parentTeamId: team.parentTeamId || '',
      settings: team.settings,
    });
  };

  const toggleTeamExpansion = (teamId: string) => {
    const newExpanded = new Set(expandedTeams);
    if (newExpanded.has(teamId)) {
      newExpanded.delete(teamId);
    } else {
      newExpanded.add(teamId);
    }
    setExpandedTeams(newExpanded);
  };

  const getRoleIcon = (role: string) => {
    switch (role) {
      case 'owner': return <Crown className="w-4 h-4 text-yellow-600" />;
      case 'admin': return <Shield className="w-4 h-4 text-blue-600" />;
      case 'member': return <User className="w-4 h-4 text-green-600" />;
      case 'viewer': return <Eye className="w-4 h-4 text-gray-600" />;
      default: return <User className="w-4 h-4 text-gray-600" />;
    }
  };

  const getRoleBadge = (role: string) => {
    switch (role) {
      case 'owner': return 'bg-yellow-100 text-yellow-800';
      case 'admin': return 'bg-blue-100 text-blue-800';
      case 'member': return 'bg-green-100 text-green-800';
      case 'viewer': return 'bg-gray-100 text-gray-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const renderTeamTree = (teamList: Team[], parentId?: string, level = 0) => {
    const filteredTeams = teamList.filter(team => team.parentTeamId === parentId);

    return filteredTeams.map((team) => {
      const hasChildren = teamList.some(t => t.parentTeamId === team.id);
      const isExpanded = expandedTeams.has(team.id);

      return (
        <div key={team.id}>
          <div
            onClick={() => setSelectedTeam(team)}
            className={`flex items-center p-3 cursor-pointer hover:bg-gray-50 transition-colors ${
              selectedTeam?.id === team.id ? 'bg-blue-50 border-r-2 border-blue-600' : ''
            }`}
            style={{ paddingLeft: `${level * 20 + 12}px` }}
          >
            {hasChildren && (
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  toggleTeamExpansion(team.id);
                }}
                className="mr-2"
              >
                {isExpanded ? (
                  <ChevronDown className="w-4 h-4 text-gray-400" />
                ) : (
                  <ChevronRight className="w-4 h-4 text-gray-400" />
                )}
              </button>
            )}
            {!hasChildren && <div className="w-6" />}

            <div className="flex-1 min-w-0">
              <h3 className="text-sm font-medium text-gray-900 truncate">
                {team.name}
              </h3>
              {team.description && (
                <p className="text-xs text-gray-500 truncate">{team.description}</p>
              )}
            </div>
          </div>

          {hasChildren && isExpanded && (
            <div>
              {renderTeamTree(teamList, team.id, level + 1)}
            </div>
          )}
        </div>
      );
    });
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto p-6">
      <div className="flex items-center justify-between mb-8">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">Teams</h1>
          <p className="text-gray-600 mt-2">Manage teams and their members</p>
        </div>
        <button
          onClick={() => setShowCreateForm(true)}
          className="flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
        >
          <Plus className="w-4 h-4 mr-2" />
          Create Team
        </button>
      </div>

      {error && (
        <div className="mb-6 p-4 bg-red-100 border border-red-300 text-red-700 rounded-lg">
          {error}
          <button 
            onClick={() => setError(null)}
            className="ml-2 text-red-500 hover:text-red-700"
          >
            ×
          </button>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
        {/* Team Tree */}
        <div className="lg:col-span-1">
          <div className="bg-white rounded-lg border border-gray-200 overflow-hidden">
            <div className="p-4 border-b border-gray-200">
              <h2 className="text-lg font-semibold text-gray-900">Teams</h2>
            </div>
            <div className="divide-y divide-gray-200 max-h-96 overflow-y-auto">
              {teams.length > 0 ? (
                renderTeamTree(teams)
              ) : (
                <div className="p-8 text-center text-gray-500">
                  <Users className="w-8 h-8 mx-auto mb-2" />
                  <p>No teams created yet</p>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Team Details */}
        <div className="lg:col-span-3">
          {selectedTeam ? (
            <div className="bg-white rounded-lg border border-gray-200">
              {/* Header */}
              <div className="p-6 border-b border-gray-200">
                <div className="flex items-start justify-between">
                  <div>
                    <h2 className="text-2xl font-bold text-gray-900">{selectedTeam.name}</h2>
                    {selectedTeam.description && (
                      <p className="text-gray-600 mt-2">{selectedTeam.description}</p>
                    )}
                    <div className="text-sm text-gray-500 mt-2">
                      Created {new Date(selectedTeam.createdAt).toLocaleDateString()}
                    </div>
                  </div>
                  <div className="flex space-x-2">
                    <button
                      onClick={() => startEditing(selectedTeam)}
                      className="p-2 text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-lg transition-colors"
                    >
                      <Edit2 className="w-4 h-4" />
                    </button>
                    <button
                      onClick={() => deleteTeam(selectedTeam.id)}
                      className="p-2 text-red-600 hover:text-red-900 hover:bg-red-100 rounded-lg transition-colors"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              </div>

              {/* Tabs */}
              <div className="border-b border-gray-200">
                <nav className="flex space-x-8 px-6">
                  {[
                    { id: 'overview', label: 'Overview', icon: Activity },
                    { id: 'members', label: 'Members', icon: Users },
                    { id: 'settings', label: 'Settings', icon: Settings },
                  ].map((tab) => (
                    <button
                      key={tab.id}
                      onClick={() => setActiveTab(tab.id as any)}
                      className={`flex items-center py-4 px-1 border-b-2 font-medium text-sm transition-colors ${
                        activeTab === tab.id
                          ? 'border-blue-500 text-blue-600'
                          : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                      }`}
                    >
                      <tab.icon className="w-4 h-4 mr-2" />
                      {tab.label}
                    </button>
                  ))}
                </nav>
              </div>

              {/* Tab Content */}
              <div className="p-6">
                {activeTab === 'overview' && (
                  <div className="space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                      <div className="bg-gray-50 p-4 rounded-lg">
                        <div className="text-2xl font-bold text-gray-900">{teamMembers.length}</div>
                        <div className="text-sm text-gray-600">Team Members</div>
                      </div>
                      <div className="bg-gray-50 p-4 rounded-lg">
                        <div className="text-2xl font-bold text-gray-900">
                          {teamMembers.filter(m => m.role === 'admin' || m.role === 'owner').length}
                        </div>
                        <div className="text-sm text-gray-600">Administrators</div>
                      </div>
                      <div className="bg-gray-50 p-4 rounded-lg">
                        <div className="text-2xl font-bold text-gray-900">
                          {teams.filter(t => t.parentTeamId === selectedTeam.id).length}
                        </div>
                        <div className="text-sm text-gray-600">Sub-teams</div>
                      </div>
                    </div>

                    <div className="bg-gray-50 p-4 rounded-lg">
                      <h3 className="text-lg font-semibold text-gray-900 mb-3">Team Information</h3>
                      <div className="space-y-2">
                        <div className="text-sm">
                          <span className="font-medium text-gray-700">Created:</span>
                          <span className="ml-2 text-gray-600">
                            {new Date(selectedTeam.createdAt).toLocaleDateString()}
                          </span>
                        </div>
                        <div className="text-sm">
                          <span className="font-medium text-gray-700">Last Updated:</span>
                          <span className="ml-2 text-gray-600">
                            {new Date(selectedTeam.updatedAt).toLocaleDateString()}
                          </span>
                        </div>
                        {selectedTeam.parentTeamId && (
                          <div className="text-sm">
                            <span className="font-medium text-gray-700">Parent Team:</span>
                            <span className="ml-2 text-gray-600">
                              {teams.find(t => t.id === selectedTeam.parentTeamId)?.name || 'Unknown'}
                            </span>
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                )}

                {activeTab === 'members' && (
                  <div className="space-y-6">
                    <div className="flex items-center justify-between">
                      <h3 className="text-lg font-semibold text-gray-900">Team Members</h3>
                      <button
                        onClick={() => setShowAddMember(true)}
                        className="flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
                      >
                        <UserPlus className="w-4 h-4 mr-2" />
                        Add Member
                      </button>
                    </div>

                    <div className="space-y-4">
                      {teamMembers.map((member) => (
                        <div key={member.id} className="flex items-center justify-between p-4 bg-gray-50 rounded-lg">
                          <div className="flex items-center space-x-4">
                            <div className="w-10 h-10 bg-gray-200 rounded-full flex items-center justify-center">
                              {member.user.avatarUrl ? (
                                <img 
                                  src={member.user.avatarUrl} 
                                  alt={member.user.displayName}
                                  className="w-10 h-10 rounded-full object-cover"
                                />
                              ) : (
                                <span className="text-sm font-medium text-gray-600">
                                  {(member.user.displayName || member.user.email).charAt(0).toUpperCase()}
                                </span>
                              )}
                            </div>
                            <div>
                              <div className="font-medium text-gray-900">
                                {member.user.displayName || `${member.user.firstName} ${member.user.lastName}`.trim() || member.user.email}
                              </div>
                              <div className="text-sm text-gray-600">{member.user.email}</div>
                              <div className="text-xs text-gray-500">
                                Joined {new Date(member.joinedAt).toLocaleDateString()}
                              </div>
                            </div>
                          </div>
                          <div className="flex items-center space-x-3">
                            <select
                              value={member.role}
                              onChange={(e) => updateMemberRole(member.userId, e.target.value)}
                              className="text-sm border border-gray-300 rounded-lg px-3 py-1 focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                            >
                              <option value="viewer">Viewer</option>
                              <option value="member">Member</option>
                              <option value="admin">Admin</option>
                              <option value="owner">Owner</option>
                            </select>
                            <span className={`inline-flex items-center px-2 py-1 rounded-full text-xs font-medium ${getRoleBadge(member.role)}`}>
                              {getRoleIcon(member.role)}
                              <span className="ml-1">{member.role.charAt(0).toUpperCase() + member.role.slice(1)}</span>
                            </span>
                            <button
                              onClick={() => removeTeamMember(member.userId)}
                              className="p-1 text-red-600 hover:text-red-900 hover:bg-red-100 rounded transition-colors"
                            >
                              <Trash2 className="w-4 h-4" />
                            </button>
                          </div>
                        </div>
                      ))}

                      {teamMembers.length === 0 && (
                        <div className="text-center py-8 text-gray-500">
                          <Users className="w-8 h-8 mx-auto mb-2" />
                          <p>No team members yet</p>
                        </div>
                      )}
                    </div>
                  </div>
                )}

                {activeTab === 'settings' && (
                  <div className="space-y-6">
                    <h3 className="text-lg font-semibold text-gray-900">Team Settings</h3>
                    <div className="space-y-4">
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                          Team Name
                        </label>
                        <div className="text-sm text-gray-900">{selectedTeam.name}</div>
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                          Description
                        </label>
                        <div className="text-sm text-gray-900">{selectedTeam.description || 'No description'}</div>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            </div>
          ) : (
            <div className="bg-white rounded-lg border border-gray-200 p-12 text-center">
              <Users className="w-12 h-12 text-gray-400 mx-auto mb-4" />
              <h3 className="text-lg font-medium text-gray-900 mb-2">No Team Selected</h3>
              <p className="text-gray-600">Select a team from the list to view details</p>
            </div>
          )}
        </div>
      </div>

      {/* Create/Edit Team Modal */}
      {(showCreateForm || editingTeam) && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
          <div className="bg-white rounded-lg max-w-md w-full p-6">
            <h3 className="text-lg font-semibold text-gray-900 mb-4">
              {editingTeam ? 'Edit Team' : 'Create Team'}
            </h3>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Team Name *
                </label>
                <input
                  type="text"
                  value={formData.name}
                  onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))}
                  className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  placeholder="Enter team name"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Description
                </label>
                <textarea
                  value={formData.description}
                  onChange={(e) => setFormData(prev => ({ ...prev, description: e.target.value }))}
                  className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  rows={3}
                  placeholder="Describe the team's purpose"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Parent Team (optional)
                </label>
                <select
                  value={formData.parentTeamId}
                  onChange={(e) => setFormData(prev => ({ ...prev, parentTeamId: e.target.value }))}
                  className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                >
                  <option value="">No parent team</option>
                  {teams
                    .filter(team => team.id !== editingTeam?.id) // Don't allow self-parent
                    .map((team) => (
                      <option key={team.id} value={team.id}>
                        {team.name}
                      </option>
                    ))}
                </select>
              </div>
            </div>

            <div className="flex space-x-3 mt-6">
              <button
                onClick={() => {
                  setShowCreateForm(false);
                  setEditingTeam(null);
                  resetForm();
                }}
                className="flex-1 px-4 py-2 text-gray-700 bg-gray-100 rounded-lg hover:bg-gray-200 transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={editingTeam ? updateTeam : createTeam}
                disabled={!formData.name.trim()}
                className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                {editingTeam ? 'Update' : 'Create'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Add Member Modal */}
      {showAddMember && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
          <div className="bg-white rounded-lg max-w-md w-full p-6">
            <h3 className="text-lg font-semibold text-gray-900 mb-4">Add Team Member</h3>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  User ID *
                </label>
                <input
                  type="text"
                  value={memberFormData.userId}
                  onChange={(e) => setMemberFormData(prev => ({ ...prev, userId: e.target.value }))}
                  className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  placeholder="Enter user ID"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Role
                </label>
                <select
                  value={memberFormData.role}
                  onChange={(e) => setMemberFormData(prev => ({ ...prev, role: e.target.value as any }))}
                  className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                >
                  <option value="viewer">Viewer</option>
                  <option value="member">Member</option>
                  <option value="admin">Admin</option>
                  <option value="owner">Owner</option>
                </select>
              </div>
            </div>

            <div className="flex space-x-3 mt-6">
              <button
                onClick={() => {
                  setShowAddMember(false);
                  setMemberFormData({ userId: '', role: 'member' });
                }}
                className="flex-1 px-4 py-2 text-gray-700 bg-gray-100 rounded-lg hover:bg-gray-200 transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={addTeamMember}
                disabled={!memberFormData.userId.trim()}
                className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                Add Member
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { 
  Card, 
  Tree, 
  Button, 
  Modal, 
  Form, 
  Input, 
  Select, 
  Switch, 
  Tag, 
  Tooltip, 
  Space, 
  Typography,
  Popconfirm,
  Dropdown,
  Menu,
  Badge,
  Alert,
  Timeline,
  Statistic,
  Row,
  Col,
  Drawer,
  Divider,
} from 'antd';
import {
  BranchesOutlined,
  PlusOutlined,
  EditOutlined,
  DeleteOutlined,
  MergeOutlined,
  SettingOutlined,
  UserOutlined,
  ClockCircleOutlined,
  MoreOutlined,
  GitlabOutlined,
  LockOutlined,
  UnlockOutlined,
  EyeOutlined,
  ForkOutlined,
  CheckCircleOutlined,
  CloseCircleOutlined,
  ExclamationCircleOutlined,
} from '@ant-design/icons';
import { 
  ProjectBranch,
  BranchHierarchy,
  BranchStatsResponse,
  CreateBranchRequest,
  UpdateBranchRequest,
  BranchType,
  BranchStatus,
  ProtectionLevel,
  BRANCH_TYPE_DESCRIPTIONS,
  BRANCH_STATUS_DESCRIPTIONS,
  PROTECTION_LEVEL_DESCRIPTIONS,
} from '../../types/branching';
import { useBranching } from '../../hooks/useBranching';
import { MergeRequestPanel } from './MergeRequestPanel';

const { Title, Text } = Typography;
const { Option } = Select;
const { TextArea } = Input;

interface BranchManagerProps {
  projectId: string;
  currentBranchId?: string;
  onBranchSelect?: (branchId: string) => void;
  onBranchCreate?: (branch: ProjectBranch) => void;
  onBranchUpdate?: (branch: ProjectBranch) => void;
  onBranchDelete?: (branchId: string) => void;
}

interface BranchNodeProps {
  branch: ProjectBranch;
  onEdit: (branch: ProjectBranch) => void;
  onDelete: (branchId: string) => void;
  onCreateChild: (parentId: string) => void;
  onSelect: (branchId: string) => void;
  isSelected: boolean;
}

const BranchNode: React.FC<BranchNodeProps> = ({ 
  branch, 
  onEdit, 
  onDelete, 
  onCreateChild, 
  onSelect,
  isSelected 
}) => {
  const getBranchTypeColor = (type: BranchType) => {
    switch (type) {
      case 'main':
        return 'purple';
      case 'feature':
        return 'blue';
      case 'hotfix':
        return 'red';
      case 'release':
        return 'green';
      case 'experiment':
        return 'orange';
      default:
        return 'default';
    }
  };

  const getBranchStatusColor = (status: BranchStatus) => {
    switch (status) {
      case 'active':
        return 'success';
      case 'merged':
        return 'processing';
      case 'abandoned':
        return 'error';
      case 'archived':
        return 'default';
      default:
        return 'default';
    }
  };

  const getProtectionIcon = (level: ProtectionLevel) => {
    switch (level) {
      case 'locked':
        return <LockOutlined style={{ color: '#ff4d4f' }} />;
      case 'protected':
        return <LockOutlined style={{ color: '#fa8c16' }} />;
      default:
        return <UnlockOutlined style={{ color: '#52c41a' }} />;
    }
  };

  const formatLastActivity = (date: Date) => {
    const now = new Date();
    const diff = now.getTime() - date.getTime();
    const days = Math.floor(diff / (1000 * 60 * 60 * 24));

    if (days === 0) return 'Today';
    if (days === 1) return 'Yesterday';
    if (days < 7) return `${days} days ago`;
    if (days < 30) return `${Math.floor(days / 7)} weeks ago`;
    return `${Math.floor(days / 30)} months ago`;
  };

  const menu = (
    <Menu>
      <Menu.Item key="select" icon={<EyeOutlined />} onClick={() => onSelect(branch.id)}>
        Switch to Branch
      </Menu.Item>
      <Menu.Item key="create" icon={<ForkOutlined />} onClick={() => onCreateChild(branch.id)}>
        Create Child Branch
      </Menu.Item>
      <Menu.Item key="edit" icon={<EditOutlined />} onClick={() => onEdit(branch)}>
        Edit Settings
      </Menu.Item>
      <Menu.Divider />
      <Menu.Item 
        key="delete" 
        icon={<DeleteOutlined />} 
        onClick={() => onDelete(branch.id)}
        disabled={branch.branchType === 'main'}
        danger
      >
        Delete Branch
      </Menu.Item>
    </Menu>
  );

  return (
    <div 
      style={{ 
        padding: '8px 12px', 
        borderRadius: '6px',
        backgroundColor: isSelected ? '#e6f7ff' : 'transparent',
        border: isSelected ? '1px solid #1890ff' : '1px solid transparent',
        marginBottom: '4px',
        cursor: 'pointer',
      }}
      onClick={() => onSelect(branch.id)}
    >
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px', flex: 1 }}>
          <BranchesOutlined style={{ color: getBranchTypeColor(branch.branchType) }} />
          <div>
            <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
              <Text strong>{branch.displayName || branch.name}</Text>
              <Tag color={getBranchTypeColor(branch.branchType)} size="small">
                {branch.branchType}
              </Tag>
              <Tag color={getBranchStatusColor(branch.status) as any} size="small">
                {branch.status}
              </Tag>
              <Tooltip title={PROTECTION_LEVEL_DESCRIPTIONS[branch.protectionLevel]}>
                {getProtectionIcon(branch.protectionLevel)}
              </Tooltip>
            </div>
            <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginTop: '2px' }}>
              <Text type="secondary" style={{ fontSize: '11px' }}>
                {branch.commitCount} commits
              </Text>
              <Text type="secondary" style={{ fontSize: '11px' }}>
                {branch.contributorCount} contributors
              </Text>
              <Text type="secondary" style={{ fontSize: '11px' }}>
                {formatLastActivity(branch.lastActivityAt)}
              </Text>
            </div>
          </div>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
          {branch.requiresReview && (
            <Tooltip title="Requires review">
              <CheckCircleOutlined style={{ color: '#fa8c16' }} />
            </Tooltip>
          )}
          {branch.autoMergeEnabled && (
            <Tooltip title="Auto-merge enabled">
              <MergeOutlined style={{ color: '#52c41a' }} />
            </Tooltip>
          )}

          <Dropdown overlay={menu} trigger={['click']}>
            <Button type="text" size="small" icon={<MoreOutlined />} />
          </Dropdown>
        </div>
      </div>
    </div>
  );
};

export const BranchManager: React.FC<BranchManagerProps> = ({
  projectId,
  currentBranchId,
  onBranchSelect,
  onBranchCreate,
  onBranchUpdate,
  onBranchDelete,
}) => {
  const [hierarchy, setHierarchy] = useState<BranchHierarchy[]>([]);
  const [stats, setStats] = useState<BranchStatsResponse | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showMergeRequestPanel, setShowMergeRequestPanel] = useState(false);
  const [selectedBranch, setSelectedBranch] = useState<ProjectBranch | null>(null);
  const [editingBranch, setEditingBranch] = useState<ProjectBranch | null>(null);
  const [parentBranchId, setParentBranchId] = useState<string | null>(null);
  const [form] = Form.useForm();

  const {
    createBranch,
    updateBranch,
    deleteBranch,
    getBranchHierarchy,
    getBranchStats,
    loading,
    error,
  } = useBranching();

  useEffect(() => {
    loadBranchData();
  }, [projectId]);

  const loadBranchData = async () => {
    try {
      const [hierarchyData, statsData] = await Promise.all([
        getBranchHierarchy(projectId),
        getBranchStats(projectId),
      ]);
      setHierarchy(hierarchyData);
      setStats(statsData);
    } catch (error) {
      console.error('Failed to load branch data:', error);
    }
  };

  const handleCreateBranch = async (values: any) => {
    try {
      const request: CreateBranchRequest = {
        projectId,
        name: values.name,
        displayName: values.displayName,
        description: values.description,
        parentBranchId: parentBranchId || undefined,
        branchType: values.branchType,
        autoMergeEnabled: values.autoMergeEnabled || false,
        requiresReview: values.requiresReview || false,
        allowForcePush: values.allowForcePush || false,
        deleteOnMerge: values.deleteOnMerge || false,
      };

      const branch = await createBranch(request);
      setShowCreateModal(false);
      form.resetFields();
      setParentBranchId(null);
      onBranchCreate?.(branch);
      loadBranchData();
    } catch (error) {
      console.error('Failed to create branch:', error);
    }
  };

  const handleUpdateBranch = async (values: any) => {
    if (!editingBranch) return;

    try {
      const request: UpdateBranchRequest = {
        displayName: values.displayName,
        description: values.description,
        protectionLevel: values.protectionLevel,
        autoMergeEnabled: values.autoMergeEnabled,
        requiresReview: values.requiresReview,
        allowForcePush: values.allowForcePush,
        deleteOnMerge: values.deleteOnMerge,
      };

      const branch = await updateBranch(editingBranch.id, request);
      setShowEditModal(false);
      setEditingBranch(null);
      form.resetFields();
      onBranchUpdate?.(branch);
      loadBranchData();
    } catch (error) {
      console.error('Failed to update branch:', error);
    }
  };

  const handleDeleteBranch = async (branchId: string) => {
    try {
      await deleteBranch(branchId);
      onBranchDelete?.(branchId);
      loadBranchData();
    } catch (error) {
      console.error('Failed to delete branch:', error);
    }
  };

  const handleBranchSelect = (branchId: string) => {
    const branch = findBranchById(branchId);
    setSelectedBranch(branch);
    onBranchSelect?.(branchId);
  };

  const handleEditBranch = (branch: ProjectBranch) => {
    setEditingBranch(branch);
    form.setFieldsValue({
      displayName: branch.displayName,
      description: branch.description,
      protectionLevel: branch.protectionLevel,
      autoMergeEnabled: branch.autoMergeEnabled,
      requiresReview: branch.requiresReview,
      allowForcePush: branch.allowForcePush,
      deleteOnMerge: branch.deleteOnMerge,
    });
    setShowEditModal(true);
  };

  const handleCreateChild = (parentId: string) => {
    setParentBranchId(parentId);
    setShowCreateModal(true);
  };

  const findBranchById = (branchId: string): ProjectBranch | null => {
    const searchInHierarchy = (nodes: BranchHierarchy[]): ProjectBranch | null => {
      for (const node of nodes) {
        if (node.branch.id === branchId) {
          return node.branch;
        }
        const found = searchInHierarchy(node.children);
        if (found) return found;
      }
      return null;
    };
    return searchInHierarchy(hierarchy);
  };

  const renderBranchHierarchy = (nodes: BranchHierarchy[]) => {
    return nodes.map((node) => (
      <div key={node.branch.id} style={{ marginLeft: `${node.depth * 20}px` }}>
        <BranchNode
          branch={node.branch}
          onEdit={handleEditBranch}
          onDelete={handleDeleteBranch}
          onCreateChild={handleCreateChild}
          onSelect={handleBranchSelect}
          isSelected={node.branch.id === currentBranchId}
        />
        {node.children.length > 0 && renderBranchHierarchy(node.children)}
      </div>
    ));
  };

  return (
    <div style={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
      {/* Header */}
      <div style={{ padding: '16px', borderBottom: '1px solid #f0f0f0' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <Title level={4} style={{ margin: 0 }}>
            <BranchesOutlined /> Branches
          </Title>
          <Space>
            <Button 
              type="primary" 
              icon={<PlusOutlined />} 
              onClick={() => setShowCreateModal(true)}
            >
              New Branch
            </Button>
            <Button 
              icon={<MergeOutlined />} 
              onClick={() => setShowMergeRequestPanel(true)}
            >
              Merge Requests
            </Button>
          </Space>
        </div>

        {/* Statistics */}
        {stats && (
          <Row gutter={16} style={{ marginTop: '16px' }}>
            <Col span={6}>
              <Statistic 
                title="Total" 
                value={stats.totalBranches}
                prefix={<BranchesOutlined />}
              />
            </Col>
            <Col span={6}>
              <Statistic 
                title="Active" 
                value={stats.activeBranches}
                prefix={<CheckCircleOutlined />}
                valueStyle={{ color: '#52c41a' }}
              />
            </Col>
            <Col span={6}>
              <Statistic 
                title="Merged" 
                value={stats.mergedBranches}
                prefix={<MergeOutlined />}
                valueStyle={{ color: '#1890ff' }}
              />
            </Col>
            <Col span={6}>
              <Statistic 
                title="Abandoned" 
                value={stats.abandonedBranches}
                prefix={<CloseCircleOutlined />}
                valueStyle={{ color: '#ff4d4f' }}
              />
            </Col>
          </Row>
        )}
      </div>

      {/* Branch List */}
      <div style={{ flex: 1, padding: '16px', overflowY: 'auto' }}>
        {error && (
          <Alert
            message="Error"
            description={error}
            type="error"
            showIcon
            closable
            style={{ marginBottom: '16px' }}
          />
        )}

        {hierarchy.length > 0 ? (
          <div>{renderBranchHierarchy(hierarchy)}</div>
        ) : (
          <div style={{ textAlign: 'center', padding: '40px' }}>
            <Text type="secondary">No branches found</Text>
          </div>
        )}
      </div>

      {/* Create Branch Modal */}
      <Modal
        title="Create New Branch"
        visible={showCreateModal}
        onCancel={() => {
          setShowCreateModal(false);
          form.resetFields();
          setParentBranchId(null);
        }}
        footer={null}
        width={600}
      >
        <Form
          form={form}
          layout="vertical"
          onFinish={handleCreateBranch}
          initialValues={{
            branchType: 'feature',
            autoMergeEnabled: false,
            requiresReview: false,
            allowForcePush: false,
            deleteOnMerge: false,
          }}
        >
          <Form.Item
            name="name"
            label="Branch Name"
            rules={[{ required: true, message: 'Please enter branch name' }]}
          >
            <Input placeholder="e.g., feature/user-authentication" />
          </Form.Item>

          <Form.Item name="displayName" label="Display Name">
            <Input placeholder="e.g., User Authentication Feature" />
          </Form.Item>

          <Form.Item name="description" label="Description">
            <TextArea rows={3} placeholder="Describe the purpose of this branch..." />
          </Form.Item>

          <Form.Item name="branchType" label="Branch Type">
            <Select>
              {Object.entries(BRANCH_TYPE_DESCRIPTIONS).map(([key, description]) => (
                <Option key={key} value={key}>
                  {key.charAt(0).toUpperCase() + key.slice(1)} - {description}
                </Option>
              ))}
            </Select>
          </Form.Item>

          <Divider />

          <Form.Item name="autoMergeEnabled" valuePropName="checked">
            <Switch /> Auto-merge when approved
          </Form.Item>

          <Form.Item name="requiresReview" valuePropName="checked">
            <Switch /> Require review before merge
          </Form.Item>

          <Form.Item name="allowForcePush" valuePropName="checked">
            <Switch /> Allow force push
          </Form.Item>

          <Form.Item name="deleteOnMerge" valuePropName="checked">
            <Switch /> Delete branch after merge
          </Form.Item>

          <div style={{ textAlign: 'right', marginTop: '24px' }}>
            <Space>
              <Button onClick={() => setShowCreateModal(false)}>
                Cancel
              </Button>
              <Button type="primary" htmlType="submit" loading={loading}>
                Create Branch
              </Button>
            </Space>
          </div>
        </Form>
      </Modal>

      {/* Edit Branch Modal */}
      <Modal
        title="Edit Branch Settings"
        visible={showEditModal}
        onCancel={() => {
          setShowEditModal(false);
          setEditingBranch(null);
          form.resetFields();
        }}
        footer={null}
        width={600}
      >
        {editingBranch && (
          <Form
            form={form}
            layout="vertical"
            onFinish={handleUpdateBranch}
          >
            <Form.Item name="displayName" label="Display Name">
              <Input placeholder="e.g., User Authentication Feature" />
            </Form.Item>

            <Form.Item name="description" label="Description">
              <TextArea rows={3} placeholder="Describe the purpose of this branch..." />
            </Form.Item>

            <Form.Item name="protectionLevel" label="Protection Level">
              <Select>
                {Object.entries(PROTECTION_LEVEL_DESCRIPTIONS).map(([key, description]) => (
                  <Option key={key} value={key}>
                    {key.charAt(0).toUpperCase() + key.slice(1)} - {description}
                  </Option>
                ))}
              </Select>
            </Form.Item>

            <Divider />

            <Form.Item name="autoMergeEnabled" valuePropName="checked">
              <Switch /> Auto-merge when approved
            </Form.Item>

            <Form.Item name="requiresReview" valuePropName="checked">
              <Switch /> Require review before merge
            </Form.Item>

            <Form.Item name="allowForcePush" valuePropName="checked">
              <Switch /> Allow force push
            </Form.Item>

            <Form.Item name="deleteOnMerge" valuePropName="checked">
              <Switch /> Delete branch after merge
            </Form.Item>

            <div style={{ textAlign: 'right', marginTop: '24px' }}>
              <Space>
                <Button onClick={() => setShowEditModal(false)}>
                  Cancel
                </Button>
                <Button type="primary" htmlType="submit" loading={loading}>
                  Update Branch
                </Button>
              </Space>
            </div>
          </Form>
        )}
      </Modal>

      {/* Merge Request Panel */}
      <Drawer
        title="Merge Requests"
        placement="right"
        onClose={() => setShowMergeRequestPanel(false)}
        visible={showMergeRequestPanel}
        width={800}
      >
        <MergeRequestPanel
          projectId={projectId}
          visible={showMergeRequestPanel}
          onClose={() => setShowMergeRequestPanel(false)}
        />
      </Drawer>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { 
  Card, 
  List, 
  Button, 
  Modal, 
  Form, 
  Input, 
  Select, 
  Tag, 
  Typography, 
  Space, 
  Avatar,
  Tooltip,
  Alert,
  Divider,
  Timeline,
  Badge,
  Dropdown,
  Menu,
} from 'antd';
import {
  MergeOutlined,
  PlusOutlined,
  CheckOutlined,
  CloseOutlined,
  CommentOutlined,
  UserOutlined,
  ClockCircleOutlined,
  MoreOutlined,
  EditOutlined,
  DeleteOutlined,
  EyeOutlined,
  BranchesOutlined,
} from '@ant-design/icons';
import { 
  BranchMergeRequest,
  ProjectBranch,
  CreateMergeRequestRequest,
  MergeRequestStatus,
  ReviewStatus,
} from '../../types/branching';
import { useBranching } from '../../hooks/useBranching';

const { Title, Text } = Typography;
const { Option } = Select;
const { TextArea } = Input;

interface MergeRequestPanelProps {
  projectId: string;
  visible: boolean;
  onClose: () => void;
}

interface MergeRequestItemProps {
  mergeRequest: BranchMergeRequest;
  onView: (mergeRequest: BranchMergeRequest) => void;
  onMerge: (mergeRequest: BranchMergeRequest) => void;
  onClose: (mergeRequest: BranchMergeRequest) => void;
}

const MergeRequestItem: React.FC<MergeRequestItemProps> = ({ 
  mergeRequest, 
  onView, 
  onMerge, 
  onClose 
}) => {
  const getStatusColor = (status: MergeRequestStatus) => {
    switch (status) {
      case 'open':
        return 'success';
      case 'merged':
        return 'processing';
      case 'closed':
        return 'default';
      case 'draft':
        return 'warning';
      default:
        return 'default';
    }
  };

  const formatDate = (date: Date) => {
    return new Date(date).toLocaleDateString();
  };

  const menu = (
    <Menu>
      <Menu.Item key="view" icon={<EyeOutlined />} onClick={() => onView(mergeRequest)}>
        View Details
      </Menu.Item>
      {mergeRequest.status === 'open' && (
        <>
          <Menu.Item key="merge" icon={<MergeOutlined />} onClick={() => onMerge(mergeRequest)}>
            Merge
          </Menu.Item>
          <Menu.Item key="close" icon={<CloseOutlined />} onClick={() => onClose(mergeRequest)}>
            Close
          </Menu.Item>
        </>
      )}
    </Menu>
  );

  return (
    <Card size="small" style={{ marginBottom: '8px' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
        <div style={{ flex: 1 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '4px' }}>
            <Text strong>{mergeRequest.title}</Text>
            <Tag color={getStatusColor(mergeRequest.status) as any}>
              {mergeRequest.status.toUpperCase()}
