/**
 * Epic 9.2.4 - Comment Form Component
 * Form for creating and editing comments
 */

import React, { useState, useRef, useEffect } from 'react';

interface CommentFormProps {
  onSubmit: (content: string) => Promise<void>;
  onCancel: () => void;
  initialValue?: string;
  placeholder?: string;
  submitText?: string;
  userId: string;
  compact?: boolean;
  autoFocus?: boolean;
}

export const CommentForm: React.FC<CommentFormProps> = ({
  onSubmit,
  onCancel,
  initialValue = '',
  placeholder = 'Write a comment...',
  submitText = 'Post Comment',
  userId,
  compact = false,
  autoFocus = true,
}) => {
  const [content, setContent] = useState(initialValue);
  const [submitting, setSubmitting] = useState(false);
  const [focused, setFocused] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (autoFocus && textareaRef.current) {
      textareaRef.current.focus();
    }
  }, [autoFocus]);

  useEffect(() => {
    // Auto-resize textarea
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${textareaRef.current.scrollHeight}px`;
    }
  }, [content]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!content.trim() || submitting) return;

    setSubmitting(true);
    try {
      await onSubmit(content.trim());
      setContent('');
    } catch (error) {
      console.error('Failed to submit comment:', error);
    } finally {
      setSubmitting(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
      e.preventDefault();
      handleSubmit(e);
    }

    if (e.key === 'Escape') {
      e.preventDefault();
      onCancel();
    }
  };

  const insertFormatting = (before: string, after: string = '') => {
    if (!textareaRef.current) return;

    const textarea = textareaRef.current;
    const start = textarea.selectionStart;
    const end = textarea.selectionEnd;
    const selectedText = content.substring(start, end);

    const newContent = 
      content.substring(0, start) + 
      before + selectedText + after + 
      content.substring(end);

    setContent(newContent);

    // Restore cursor position
    setTimeout(() => {
      if (textarea) {
        const newCursorPos = start + before.length + selectedText.length;
        textarea.setSelectionRange(newCursorPos, newCursorPos);
        textarea.focus();
      }
    }, 0);
  };

  const isExpanded = focused || content.length > 0;

  return (
    <div className={`comment-form ${compact ? 'comment-form--compact' : ''} ${isExpanded ? 'comment-form--expanded' : ''}`}>
      <div className="comment-form__avatar">
        <div className="user-avatar user-avatar--small">
          {userId.charAt(0).toUpperCase()}
        </div>
      </div>

      <form onSubmit={handleSubmit} className="comment-form__form">
        <div className="comment-form__input-container">
          <textarea
            ref={textareaRef}
            value={content}
            onChange={(e) => setContent(e.target.value)}
            onFocus={() => setFocused(true)}
            onBlur={() => setFocused(false)}
            onKeyDown={handleKeyDown}
            placeholder={placeholder}
            className="comment-form__textarea"
            rows={compact ? 2 : 3}
            disabled={submitting}
          />

          {isExpanded && (
            <div className="comment-form__toolbar">
              <div className="comment-form__formatting">
                <button
                  type="button"
                  className="formatting-btn"
                  onClick={() => insertFormatting('**', '**')}
                  title="Bold (Ctrl+B)"
                >
                  <strong>B</strong>
                </button>
                <button
                  type="button"
                  className="formatting-btn"
                  onClick={() => insertFormatting('*', '*')}
                  title="Italic (Ctrl+I)"
                >
                  <em>I</em>
                </button>
                <button
                  type="button"
                  className="formatting-btn"
                  onClick={() => insertFormatting('`', '`')}
                  title="Code"
                >
                  {'</>'}
                </button>
              </div>

              <div className="comment-form__help">
                <span className="help-text">
                  <kbd>Cmd/Ctrl</kbd> + <kbd>Enter</kbd> to submit
                </span>
              </div>
            </div>
          )}
        </div>

        <div className="comment-form__actions">
          <button
            type="button"
            className="btn btn--ghost btn--small"
            onClick={onCancel}
            disabled={submitting}
          >
            Cancel
          </button>
          <button
            type="submit"
            className="btn btn--primary btn--small"
            disabled={!content.trim() || submitting}
          >
            {submitting ? 'Posting...' : submitText}
          </button>
        </div>

        {!compact && (
          <div className="comment-form__tips">
            <div className="formatting-tips">
              <span className="tip">
                Use <strong>**bold**</strong>, <em>*italic*</em>, or <code>`code`</code>
              </span>
            </div>
          </div>
        )}
      </form>
    </div>
  );
};

export default CommentForm;

/**
 * Epic 9.2.4 - Comment Item Component
 * Individual comment display and interaction
 */

import React, { useState } from 'react';
import { Comment } from '../../types/workspace';
import { CommentForm } from './CommentForm';

interface CommentItemProps {
  comment: Comment;
  userId: string;
  onUpdate: (commentId: string, content: string, metadata?: any) => Promise<void>;
  onDelete: (commentId: string) => Promise<void>;
  onResolve?: (commentId: string, resolved: boolean) => Promise<void>;
  onReply?: () => void;
  compact?: boolean;
  isReply?: boolean;
  isThreadRoot?: boolean;
  isLast?: boolean;
}

export const CommentItem: React.FC<CommentItemProps> = ({
  comment,
  userId,
  onUpdate,
  onDelete,
  onResolve,
  onReply,
  compact = false,
  isReply = false,
  isThreadRoot = false,
  isLast = false,
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [showActions, setShowActions] = useState(false);
  const [deleting, setDeleting] = useState(false);

  const isAuthor = comment.author_id === userId;
  const isResolved = comment.metadata?.resolved;
  const resolvedBy = comment.metadata?.resolved_by;
  const resolvedAt = comment.metadata?.resolved_at;

  const handleEdit = async (content: string) => {
    try {
      await onUpdate(comment.id, content);
      setIsEditing(false);
    } catch (error) {
      console.error('Failed to update comment:', error);
    }
  };

  const handleDelete = async () => {
    if (window.confirm('Are you sure you want to delete this comment?')) {
      setDeleting(true);
      try {
        await onDelete(comment.id);
      } catch (error) {
        console.error('Failed to delete comment:', error);
        setDeleting(false);
      }
    }
  };

  const handleResolve = async () => {
    if (onResolve) {
      try {
        await onResolve(comment.id, !isResolved);
      } catch (error) {
        console.error('Failed to resolve comment:', error);
      }
    }
  };

  const formatTime = (date: Date) => {
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);

    if (diffMins < 1) return 'Just now';
    if (diffMins < 60) return `${diffMins}m ago`;
    if (diffHours < 24) return `${diffHours}h ago`;
    if (diffDays < 7) return `${diffDays}d ago`;

    return date.toLocaleDateString();
  };

  const formatContent = (content: string) => {
    // Simple markdown-like formatting
    return content
      .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
      .replace(/\*(.*?)\*/g, '<em>$1</em>')
      .replace(/`(.*?)`/g, '<code>$1</code>')
      .replace(/\n/g, '<br />');
  };

  if (deleting) {
    return (
      <div className="comment-item comment-item--deleting">
        <div className="comment-item__content">
          <div className="deletion-notice">
            Comment is being deleted...
          </div>
        </div>
      </div>
    );
  }

  return (
    <div 
      className={`comment-item ${compact ? 'comment-item--compact' : ''} ${isReply ? 'comment-item--reply' : ''} ${isThreadRoot ? 'comment-item--thread-root' : ''} ${isLast ? 'comment-item--last' : ''} ${isResolved ? 'comment-item--resolved' : ''}`}
      onMouseEnter={() => setShowActions(true)}
      onMouseLeave={() => setShowActions(false)}
    >
      <div className="comment-item__avatar">
        <div className="user-avatar user-avatar--small">
          {(comment.author_name || comment.author_id).charAt(0).toUpperCase()}
        </div>
      </div>

      <div className="comment-item__content">
        <div className="comment-item__header">
          <div className="comment-item__author">
            <span className="author-name">
              {comment.author_name || comment.author_id}
            </span>
            <span className="comment-item__time">
              {formatTime(new Date(comment.created_at))}
            </span>
            {comment.updated_at > comment.created_at && (
              <span className="comment-item__edited">
                (edited)
              </span>
            )}
          </div>

          <div className={`comment-item__actions ${showActions || isResolved ? 'comment-item__actions--visible' : ''}`}>
            {isResolved && (
              <span className="comment-item__resolved-badge">
                ✓ Resolved
              </span>
            )}

            {!isEditing && (
              <>
                {onReply && !isReply && (
                  <button
                    className="comment-action"
                    onClick={onReply}
                    title="Reply"
                  >
                    Reply
                  </button>
                )}

                {isAuthor && (
                  <button
                    className="comment-action"
                    onClick={() => setIsEditing(true)}
                    title="Edit"
                  >
                    Edit
                  </button>
                )}

                {onResolve && isThreadRoot && (
                  <button
                    className="comment-action"
                    onClick={handleResolve}
                    title={isResolved ? 'Mark as unresolved' : 'Mark as resolved'}
                  >
                    {isResolved ? 'Unresolve' : 'Resolve'}
                  </button>
                )}

                {isAuthor && (
                  <button
                    className="comment-action comment-action--danger"
                    onClick={handleDelete}
                    title="Delete"
                  >
                    Delete
                  </button>
                )}
              </>
            )}
          </div>
        </div>

        <div className="comment-item__body">
          {isEditing ? (
            <CommentForm
              onSubmit={handleEdit}
              onCancel={() => setIsEditing(false)}
              initialValue={comment.content}
              submitText="Save Changes"
              userId={userId}
              compact={true}
            />
          ) : (
            <div 
              className="comment-item__text"
              dangerouslySetInnerHTML={{ __html: formatContent(comment.content) }}
            />
          )}
        </div>

        {isResolved && resolvedBy && resolvedAt && (
          <div className="comment-item__resolution">
            <span className="resolution-info">
              Resolved by {resolvedBy} {formatTime(new Date(resolvedAt))}
            </span>
          </div>
        )}
      </div>
    </div>
  );
};

export default CommentItem;

/**
 * Epic 9.2.4 - Comment System Component
 * Main interface for threaded commenting system
 */

import React, { useState, useEffect } from 'react';
import { Comment, CreateComment, UpdateComment } from '../../types/workspace';
import { CommentThread } from './CommentThread';
import { CommentForm } from './CommentForm';
import { useComments } from '../../hooks/useComments';

interface CommentSystemProps {
  workspaceId: string;
  targetType: string;
  targetId: string;
  userId: string;
  resourceId?: string;
  projectId?: string;
  className?: string;
  compact?: boolean;
}

export const CommentSystem: React.FC<CommentSystemProps> = ({
  workspaceId,
  targetType,
  targetId,
  userId,
  resourceId,
  projectId,
  className = '',
  compact = false,
}) => {
  const [showCommentForm, setShowCommentForm] = useState(false);
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc');

  const {
    comments,
    loading,
    error,
    createComment,
    updateComment,
    deleteComment,
    loadMore,
    hasMore,
    refresh,
  } = useComments({
    workspaceId,
    targetType,
    targetId,
    userId,
    sortOrder,
  });

  const handleCreateComment = async (content: string, parentCommentId?: string) => {
    const commentData: CreateComment = {
      workspace_id: workspaceId,
      project_id: projectId,
      resource_id: resourceId,
      author_id: userId,
      content,
      parent_comment_id: parentCommentId,
      target_type: targetType,
      target_id: targetId,
      metadata: {},
    };

    try {
      await createComment(commentData);
      if (!parentCommentId) {
        setShowCommentForm(false);
      }
    } catch (error) {
      console.error('Failed to create comment:', error);
    }
  };

  const handleUpdateComment = async (commentId: string, content: string, metadata?: any) => {
    const updates: UpdateComment = { content };
    if (metadata) {
      updates.metadata = metadata;
    }

    try {
      await updateComment(commentId, updates);
    } catch (error) {
      console.error('Failed to update comment:', error);
    }
  };

  const handleDeleteComment = async (commentId: string) => {
    try {
      await deleteComment(commentId);
    } catch (error) {
      console.error('Failed to delete comment:', error);
    }
  };

  const handleResolveComment = async (commentId: string, resolved: boolean) => {
    const comment = comments.find(c => c.id === commentId);
    if (!comment) return;

    const updates: UpdateComment = {
      metadata: {
        ...comment.metadata,
        resolved,
        resolved_by: resolved ? userId : undefined,
        resolved_at: resolved ? new Date().toISOString() : undefined,
      },
    };

    try {
      await updateComment(commentId, updates);
    } catch (error) {
      console.error('Failed to resolve comment:', error);
    }
  };

  const totalComments = comments.reduce((total, comment) => {
    return total + 1 + (comment.reply_count || 0);
  }, 0);

  if (loading && comments.length === 0) {
    return (
      <div className={`comment-system comment-system--loading ${className}`}>
        <div className="comment-system__skeleton">
          <div className="skeleton-line skeleton-line--title"></div>
          <div className="skeleton-line skeleton-line--content"></div>
          <div className="skeleton-line skeleton-line--short"></div>
        </div>
      </div>
    );
  }

  return (
    <div className={`comment-system ${compact ? 'comment-system--compact' : ''} ${className}`}>
      <div className="comment-system__header">
        <div className="comment-system__title">
          <h3>
            Comments {totalComments > 0 && `(${totalComments})`}
          </h3>
          <div className="comment-system__actions">
            {comments.length > 1 && (
              <select
                value={sortOrder}
                onChange={(e) => setSortOrder(e.target.value as 'asc' | 'desc')}
                className="comment-sort-select"
              >
                <option value="desc">Newest first</option>
                <option value="asc">Oldest first</option>
              </select>
            )}
            <button
              className="btn btn--primary btn--small"
              onClick={() => setShowCommentForm(!showCommentForm)}
            >
              {showCommentForm ? 'Cancel' : 'Add Comment'}
            </button>
          </div>
        </div>

        {error && (
          <div className="comment-system__error">
            <span className="error-message">{error}</span>
            <button
              className="btn btn--ghost btn--small"
              onClick={refresh}
            >
              Retry
            </button>
          </div>
        )}
      </div>

      {showCommentForm && (
        <div className="comment-system__form">
          <CommentForm
            onSubmit={(content) => handleCreateComment(content)}
            onCancel={() => setShowCommentForm(false)}
            placeholder="Add a comment..."
            submitText="Post Comment"
            userId={userId}
          />
        </div>
      )}

      <div className="comment-system__content">
        {comments.length === 0 && !loading ? (
          <div className="comment-system__empty">
            <div className="empty-state">
              <div className="empty-state__icon">💬</div>
              <div className="empty-state__title">No comments yet</div>
              <div className="empty-state__message">
                Start a conversation by adding the first comment.
              </div>
              {!showCommentForm && (
                <button
                  className="btn btn--primary"
                  onClick={() => setShowCommentForm(true)}
                >
                  Add First Comment
                </button>
              )}
            </div>
          </div>
        ) : (
          <div className="comment-system__threads">
            {comments.map((comment, index) => (
              <CommentThread
                key={comment.id}
                comment={comment}
                workspaceId={workspaceId}
                userId={userId}
                onReply={(content) => handleCreateComment(content, comment.id)}
                onUpdate={handleUpdateComment}
                onDelete={handleDeleteComment}
                onResolve={handleResolveComment}
                compact={compact}
                isLast={index === comments.length - 1}
              />
            ))}

            {hasMore && (
              <div className="comment-system__load-more">
                <button
                  className="btn btn--ghost"
                  onClick={loadMore}
                  disabled={loading}
                >
                  {loading ? 'Loading...' : 'Load More Comments'}
                </button>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default CommentSystem;

/**
 * Epic 9.2.4 - Comment Thread Component
 * Individual comment thread with replies
 */

import React, { useState } from 'react';
import { Comment } from '../../types/workspace';
import { CommentItem } from './CommentItem';
import { CommentForm } from './CommentForm';
import { useCommentReplies } from '../../hooks/useCommentReplies';

interface CommentThreadProps {
  comment: Comment;
  workspaceId: string;
  userId: string;
  onReply: (content: string) => Promise<void>;
  onUpdate: (commentId: string, content: string, metadata?: any) => Promise<void>;
  onDelete: (commentId: string) => Promise<void>;
  onResolve: (commentId: string, resolved: boolean) => Promise<void>;
  compact?: boolean;
  isLast?: boolean;
}

export const CommentThread: React.FC<CommentThreadProps> = ({
  comment,
  workspaceId,
  userId,
  onReply,
  onUpdate,
  onDelete,
  onResolve,
  compact = false,
  isLast = false,
}) => {
  const [showReplyForm, setShowReplyForm] = useState(false);
  const [showReplies, setShowReplies] = useState(false);

  const {
    replies,
    loading: repliesLoading,
    error: repliesError,
    loadMore: loadMoreReplies,
    hasMore: hasMoreReplies,
    refresh: refreshReplies,
  } = useCommentReplies({
    commentId: comment.id,
    userId,
    enabled: showReplies,
  });

  const handleReply = async (content: string) => {
    try {
      await onReply(content);
      setShowReplyForm(false);
      // Refresh replies to show the new one
      if (showReplies) {
        refreshReplies();
      } else {
        setShowReplies(true);
      }
    } catch (error) {
      console.error('Failed to reply to comment:', error);
    }
  };

  const handleShowReplies = () => {
    setShowReplies(!showReplies);
  };

  const canShowReplies = comment.reply_count > 0 || showReplies;
  const isResolved = comment.metadata?.resolved;

  return (
    <div 
      className={`comment-thread ${compact ? 'comment-thread--compact' : ''} ${isLast ? 'comment-thread--last' : ''} ${isResolved ? 'comment-thread--resolved' : ''}`}
    >
      <CommentItem
        comment={comment}
        userId={userId}
        onUpdate={onUpdate}
        onDelete={onDelete}
        onResolve={onResolve}
        onReply={() => setShowReplyForm(!showReplyForm)}
        compact={compact}
        isThreadRoot={true}
      />

      {showReplyForm && (
        <div className="comment-thread__reply-form">
          <CommentForm
            onSubmit={handleReply}
            onCancel={() => setShowReplyForm(false)}
            placeholder={`Reply to ${comment.author_name || comment.author_id}...`}
            submitText="Post Reply"
            userId={userId}
            compact={true}
          />
        </div>
      )}

      {canShowReplies && (
        <div className="comment-thread__replies">
          {comment.reply_count > 0 && !showReplies && (
            <button
              className="comment-thread__show-replies"
              onClick={handleShowReplies}
            >
              <span className="thread-connector"></span>
              Show {comment.reply_count} {comment.reply_count === 1 ? 'reply' : 'replies'}
            </button>
          )}

          {showReplies && (
            <div className="comment-replies">
              <div className="comment-replies__header">
                <button
                  className="comment-replies__toggle"
                  onClick={handleShowReplies}
                >
                  <span className="thread-connector thread-connector--active"></span>
                  Hide replies
                </button>
              </div>

              <div className="comment-replies__list">
                {repliesLoading && replies.length === 0 ? (
                  <div className="comment-replies__loading">
                    <div className="skeleton-comment">
                      <div className="skeleton-line skeleton-line--short"></div>
                      <div className="skeleton-line skeleton-line--content"></div>
                    </div>
                  </div>
                ) : repliesError ? (
                  <div className="comment-replies__error">
                    <span className="error-message">Failed to load replies</span>
                    <button
                      className="btn btn--ghost btn--small"
                      onClick={refreshReplies}
                    >
                      Retry
                    </button>
                  </div>
                ) : (
                  <>
                    {replies.map((reply, index) => (
                      <div key={reply.id} className="comment-reply">
                        <CommentItem
                          comment={reply}
                          userId={userId}
                          onUpdate={onUpdate}
                          onDelete={onDelete}
                          onResolve={onResolve}
                          compact={true}
                          isReply={true}
                          isLast={index === replies.length - 1 && !hasMoreReplies}
                        />
                      </div>
                    ))}

                    {hasMoreReplies && (
                      <div className="comment-replies__load-more">
                        <button
                          className="btn btn--ghost btn--small"
                          onClick={loadMoreReplies}
                          disabled={repliesLoading}
                        >
                          {repliesLoading ? 'Loading...' : 'Load more replies'}
                        </button>
                      </div>
                    )}
                  </>
                )}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default CommentThread;

