interface ExportWizardProps {
  projectId: string;
  template?: ExportTemplate | null;
  onComplete: (exportData: CreateExportJob) => void;
  onCancel: () => void;
}

type WizardStep = 'format' | 'options' | 'filters' | 'review';

const EXPORT_FORMATS: Array<{
  value: ExportFormat;
  label: string;
  description: string;
  icon: string;
}> = [
  { value: 'json', label: 'JSON', description: 'JavaScript Object Notation - structured data', icon: '{}' },
  { value: 'yaml', label: 'YAML', description: 'Human-readable data serialization', icon: '📄' },
  { value: 'xml', label: 'XML', description: 'Extensible Markup Language', icon: '</>' },
  { value: 'csv', label: 'CSV', description: 'Comma-separated values - spreadsheet format', icon: '📊' },
  { value: 'markdown', label: 'Markdown', description: 'Human-readable markup format', icon: '📝' },
  { value: 'pdf', label: 'PDF', description: 'Portable Document Format', icon: '📋' },
  { value: 'html', label: 'HTML', description: 'Web page format', icon: '🌐' },
  { value: 'zip', label: 'ZIP', description: 'Compressed archive', icon: '📦' }
];

const EXPORT_TYPES: Array<{
  value: ExportType;
  label: string;
  description: string;
}> = [
  { value: 'version', label: 'Version Snapshot', description: 'Export a specific version of the project' },
  { value: 'branch', label: 'Branch Data', description: 'Export data from a specific branch' },
  { value: 'comparison', label: 'Version Comparison', description: 'Export differences between versions' },
  { value: 'full_project', label: 'Full Project', description: 'Export entire project with all data' }
];

export const ExportWizard: React.FC<ExportWizardProps> = ({
  projectId,
  template,
  onComplete,
  onCancel
}) => {
  const [currentStep, setCurrentStep] = useState<WizardStep>('format');
  const [exportData, setExportData] = useState<Partial<CreateExportJob>>({
    export_format: template?.export_format || 'json',
    export_type: 'full_project',
    export_scope: {},
    export_options: {},
    custom_filters: {}
  });
  const [formatDefinitions, setFormatDefinitions] = useState<ExportFormatDefinition[]>([]);
  const [validationErrors, setValidationErrors] = useState<string[]>([]);

  const { createExportJob, loading } = useExport(projectId);

  useEffect(() => {
    // Load format definitions
    const loadFormats = async () => {
      try {
        const response = await fetch('/api/export/formats');
        const data = await response.json();
        if (data.success) {
          setFormatDefinitions(data.data);
        }
      } catch (error) {
        console.error('Failed to load format definitions:', error);
      }
    };
    loadFormats();
  }, []);

  useEffect(() => {
    if (template) {
      setExportData({
        export_format: template.export_format,
        export_type: 'full_project',
        export_scope: {},
        export_options: template.format_options || {},
        custom_filters: template.filter_options || {}
      });
    }
  }, [template]);

  const handleNext = () => {
    if (validateCurrentStep()) {
      const steps: WizardStep[] = ['format', 'options', 'filters', 'review'];
      const currentIndex = steps.indexOf(currentStep);
      if (currentIndex < steps.length - 1) {
        setCurrentStep(steps[currentIndex + 1]);
      }
    }
  };

  const handlePrevious = () => {
    const steps: WizardStep[] = ['format', 'options', 'filters', 'review'];
    const currentIndex = steps.indexOf(currentStep);
    if (currentIndex > 0) {
      setCurrentStep(steps[currentIndex - 1]);
    }
  };

  const validateCurrentStep = (): boolean => {
    const errors: string[] = [];

    switch (currentStep) {
      case 'format':
        if (!exportData.export_format) {
          errors.push('Please select an export format');
        }
        if (!exportData.export_type) {
          errors.push('Please select an export type');
        }
        break;
      case 'options':
        if (exportData.export_format && exportData.export_options) {
          const validation = validateExportOptions(exportData.export_format, exportData.export_options);
          if (!validation.success) {
            errors.push(...validation.error.errors.map(e => e.message));
          }
        }
        break;
    }

    setValidationErrors(errors);
    return errors.length === 0;
  };

  const handleComplete = async () => {
    if (!validateCurrentStep()) return;

    try {
      const completeExportData = {
        ...exportData,
        template_id: template?.id
      } as CreateExportJob;

      await createExportJob(completeExportData);
      onComplete(completeExportData);
    } catch (error) {
      console.error('Failed to create export job:', error);
    }
  };

  const renderFormatStep = () => (
    <div className="space-y-6">
      <div>
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
          Choose Export Format
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {EXPORT_FORMATS.map((format) => (
            <button
              key={format.value}
              onClick={() => setExportData(prev => ({ ...prev, export_format: format.value }))}
              className={`p-4 rounded-lg border-2 text-left transition-colors ${
                exportData.export_format === format.value
                  ? 'border-blue-500 bg-blue-50 dark:bg-blue-900/20'
                  : 'border-gray-200 dark:border-gray-700 hover:border-gray-300 dark:hover:border-gray-600'
              }`}
            >
              <div className="flex items-center justify-between">
                <div className="flex items-center">
                  <span className="text-2xl mr-3">{format.icon}</span>
                  <div>
                    <p className="font-medium text-gray-900 dark:text-white">{format.label}</p>
                    <p className="text-sm text-gray-600 dark:text-gray-300">{format.description}</p>
                  </div>
                </div>
                {exportData.export_format === format.value && (
                  <FiCheck className="w-5 h-5 text-blue-600" />
                )}
              </div>
            </button>
          ))}
        </div>
      </div>

      <div>
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
          Export Type
        </h3>
        <div className="space-y-3">
          {EXPORT_TYPES.map((type) => (
            <button
              key={type.value}
              onClick={() => setExportData(prev => ({ ...prev, export_type: type.value }))}
              className={`w-full p-4 rounded-lg border-2 text-left transition-colors ${
                exportData.export_type === type.value
                  ? 'border-blue-500 bg-blue-50 dark:bg-blue-900/20'
                  : 'border-gray-200 dark:border-gray-700 hover:border-gray-300 dark:hover:border-gray-600'
              }`}
            >
              <div className="flex items-center justify-between">
                <div>
                  <p className="font-medium text-gray-900 dark:text-white">{type.label}</p>
                  <p className="text-sm text-gray-600 dark:text-gray-300">{type.description}</p>
                </div>
                {exportData.export_type === type.value && (
                  <FiCheck className="w-5 h-5 text-blue-600" />
                )}
              </div>
            </button>
          ))}
        </div>
      </div>
    </div>
  );

  const renderOptionsStep = () => {
    const currentFormat = formatDefinitions.find(f => f.format_name === exportData.export_format);

    return (
      <div className="space-y-6">
        <div>
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
            Export Options
          </h3>
          <div className="bg-blue-50 dark:bg-blue-900/20 p-4 rounded-lg mb-6">
            <div className="flex items-center">
              <FiInfo className="w-5 h-5 text-blue-600 mr-2" />
              <p className="text-sm text-blue-800 dark:text-blue-200">
                Configure format-specific options for {exportData.export_format?.toUpperCase()} export
              </p>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Common Options */}
          <div className="space-y-4">
            <h4 className="font-medium text-gray-900 dark:text-white">Content Options</h4>
            {[
              { key: 'include_metadata', label: 'Include Metadata', description: 'Export metadata and timestamps' },
              { key: 'include_attribution', label: 'Include Attribution', description: 'Export author and contribution data' },
              { key: 'include_history', label: 'Include History', description: 'Export version history' },
              { key: 'include_branching', label: 'Include Branching', description: 'Export branch information' },
              { key: 'include_comments', label: 'Include Comments', description: 'Export comments and annotations' },
              { key: 'include_attachments', label: 'Include Attachments', description: 'Export file attachments' }
            ].map((option) => (
              <label key={option.key} className="flex items-start space-x-3">
                <input
                  type="checkbox"
                  checked={exportData.export_options?.[option.key] || false}
                  onChange={(e) => setExportData(prev => ({
                    ...prev,
                    export_options: {
                      ...prev.export_options,
                      [option.key]: e.target.checked
                    }
                  }))}
                  className="mt-1 rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                />
                <div>
                  <p className="font-medium text-gray-900 dark:text-white">{option.label}</p>
                  <p className="text-sm text-gray-600 dark:text-gray-300">{option.description}</p>
                </div>
              </label>
            ))}
          </div>

          {/* Format-Specific Options */}
          <div className="space-y-4">
            <h4 className="font-medium text-gray-900 dark:text-white">Format Options</h4>
            {exportData.export_format === 'json' && (
              <div className="space-y-3">
                <label className="flex items-center space-x-3">
                  <input
                    type="checkbox"
                    checked={exportData.export_options?.pretty || false}
                    onChange={(e) => setExportData(prev => ({
                      ...prev,
                      export_options: {
                        ...prev.export_options,
                        pretty: e.target.checked
                      }
                    }))}
                    className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                  />
                  <span className="text-gray-900 dark:text-white">Pretty Print JSON</span>
                </label>
                <label className="flex items-center space-x-3">
                  <input
                    type="checkbox"
                    checked={exportData.export_options?.include_schema || false}
                    onChange={(e) => setExportData(prev => ({
                      ...prev,
                      export_options: {
                        ...prev.export_options,
                        include_schema: e.target.checked
                      }
                    }))}
                    className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                  />
                  <span className="text-gray-900 dark:text-white">Include JSON Schema</span>
                </label>
              </div>
            )}

            {exportData.export_format === 'csv' && (
              <div className="space-y-3">
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Delimiter
                  </label>
                  <select
                    value={exportData.export_options?.delimiter || ','}
                    onChange={(e) => setExportData(prev => ({
                      ...prev,
                      export_options: {
                        ...prev.export_options,
                        delimiter: e.target.value
                      }
                    }))}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500"
                  >
                    <option value=",">Comma (,)</option>
                    <option value=";">Semicolon (;)</option>
                    <option value="\t">Tab</option>
                    <option value="|">Pipe (|)</option>
                  </select>
                </div>
                <label className="flex items-center space-x-3">
                  <input
                    type="checkbox"
                    checked={exportData.export_options?.include_headers || false}
                    onChange={(e) => setExportData(prev => ({
                      ...prev,
                      export_options: {
                        ...prev.export_options,
                        include_headers: e.target.checked
                      }
                    }))}
                    className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                  />
                  <span className="text-gray-900 dark:text-white">Include Headers</span>
                </label>
              </div>
            )}

            {exportData.export_format === 'pdf' && (
              <div className="space-y-3">
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Page Size
                  </label>
                  <select
                    value={exportData.export_options?.page_size || 'A4'}
                    onChange={(e) => setExportData(prev => ({
                      ...prev,
                      export_options: {
                        ...prev.export_options,
                        page_size: e.target.value
                      }
                    }))}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500"
                  >
                    <option value="A4">A4</option>
                    <option value="A3">A3</option>
                    <option value="Letter">Letter</option>
                    <option value="Legal">Legal</option>
                  </select>
                </div>
                <label className="flex items-center space-x-3">
                  <input
                    type="checkbox"
                    checked={exportData.export_options?.include_images || false}
                    onChange={(e) => setExportData(prev => ({
                      ...prev,
                      export_options: {
                        ...prev.export_options,
                        include_images: e.target.checked
                      }
                    }))}
                    className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                  />
                  <span className="text-gray-900 dark:text-white">Include Images</span>
                </label>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  };

  const renderFiltersStep = () => (
    <div className="space-y-6">
      <div>
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
          Content Filters
        </h3>
        <p className="text-sm text-gray-600 dark:text-gray-300 mb-6">
          Apply filters to customize what data is included in your export
        </p>
      </div>

      <div className="space-y-6">
        <div>
          <h4 className="font-medium text-gray-900 dark:text-white mb-3">Date Range</h4>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                Start Date
              </label>
              <input
                type="date"
                value={exportData.custom_filters?.date_range?.start || ''}
                onChange={(e) => setExportData(prev => ({
                  ...prev,
                  custom_filters: {
                    ...prev.custom_filters,
                    date_range: {
                      ...prev.custom_filters?.date_range,
                      start: e.target.value
                    }
                  }
                }))}
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                End Date
              </label>
              <input
                type="date"
                value={exportData.custom_filters?.date_range?.end || ''}
                onChange={(e) => setExportData(prev => ({
                  ...prev,
                  custom_filters: {
                    ...prev.custom_filters,
                    date_range: {
                      ...prev.custom_filters?.date_range,
                      end: e.target.value
                    }
                  }
                }))}
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500"
              />
            </div>
          </div>
        </div>

        <div>
          <h4 className="font-medium text-gray-900 dark:text-white mb-3">Output Options</h4>
          <div className="space-y-3">
            <label className="flex items-center space-x-3">
              <input
                type="checkbox"
                checked={exportData.custom_filters?.compress_output || false}
                onChange={(e) => setExportData(prev => ({
                  ...prev,
                  custom_filters: {
                    ...prev.custom_filters,
                    compress_output: e.target.checked
                  }
                }))}
                className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
              />
              <span className="text-gray-900 dark:text-white">Compress Output</span>
            </label>
            <label className="flex items-center space-x-3">
              <input
                type="checkbox"
                checked={exportData.custom_filters?.encrypt_output || false}
                onChange={(e) => setExportData(prev => ({
                  ...prev,
                  custom_filters: {
                    ...prev.custom_filters,
                    encrypt_output: e.target.checked
                  }
                }))}
                className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
              />
              <span className="text-gray-900 dark:text-white">Encrypt Output</span>
            </label>
          </div>
        </div>
      </div>
    </div>
  );

  const renderReviewStep = () => (
    <div className="space-y-6">
      <div>
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
          Review Export Configuration
        </h3>
        <p className="text-sm text-gray-600 dark:text-gray-300 mb-6">
          Review your export settings before starting the export process
        </p>
      </div>

      <div className="bg-gray-50 dark:bg-gray-800 rounded-lg p-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div>
            <h4 className="font-medium text-gray-900 dark:text-white mb-3">Export Format</h4>
            <p className="text-sm text-gray-600 dark:text-gray-300">
              {EXPORT_FORMATS.find(f => f.value === exportData.export_format)?.label} - {EXPORT_FORMATS.find(f => f.value === exportData.export_format)?.description}
            </p>
          </div>
          <div>
            <h4 className="font-medium text-gray-900 dark:text-white mb-3">Export Type</h4>
            <p className="text-sm text-gray-600 dark:text-gray-300">
              {EXPORT_TYPES.find(t => t.value === exportData.export_type)?.label} - {EXPORT_TYPES.find(t => t.value === exportData.export_type)?.description}
            </p>
          </div>
        </div>

        <div className="mt-6">
          <h4 className="font-medium text-gray-900 dark:text-white mb-3">Content Options</h4>
          <div className="grid grid-cols-2 md:grid-cols-3 gap-2">
            {Object.entries(exportData.export_options || {}).map(([key, value]) => (
              value && (
                <div key={key} className="flex items-center space-x-2">
                  <FiCheck className="w-4 h-4 text-green-600" />
                  <span className="text-sm text-gray-600 dark:text-gray-300">
                    {key.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase())}
                  </span>
                </div>
              )
            ))}
          </div>
        </div>

        {exportData.custom_filters?.date_range && (
          <div className="mt-6">
            <h4 className="font-medium text-gray-900 dark:text-white mb-3">Date Range</h4>
            <p className="text-sm text-gray-600 dark:text-gray-300">
              {exportData.custom_filters.date_range.start || 'No start date'} to {exportData.custom_filters.date_range.end || 'No end date'}
            </p>
          </div>
        )}
      </div>
    </div>
  );

  const renderStepContent = () => {
    switch (currentStep) {
      case 'format':
        return renderFormatStep();
      case 'options':
        return renderOptionsStep();
      case 'filters':
        return renderFiltersStep();
      case 'review':
        return renderReviewStep();
      default:
        return null;
    }
  };

  const getStepIcon = (step: WizardStep) => {
    switch (step) {
      case 'format':
        return FiFile;
      case 'options':
        return FiSettings;
      case 'filters':
        return FiFilter;
      case 'review':
        return FiCheck;
      default:
        return FiFile;
    }
  };

  const steps = [
    { id: 'format', label: 'Format' },
    { id: 'options', label: 'Options' },
    { id: 'filters', label: 'Filters' },
    { id: 'review', label: 'Review' }
  ];

  const currentStepIndex = steps.findIndex(s => s.id === currentStep);

  return (
    <div className="export-wizard">
      {/* Header */}
      <div className="flex items-center justify-between p-6 border-b border-gray-200 dark:border-gray-700">
        <div>
          <h2 className="text-xl font-semibold text-gray-900 dark:text-white">
            {template ? 'Export with Template' : 'New Export'}
          </h2>
          {template && (
            <p className="text-sm text-gray-600 dark:text-gray-300">
              Using template: {template.name}
            </p>
          )}
        </div>
        <button
          onClick={onCancel}
          className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
        >
          <FiX className="w-6 h-6" />
        </button>
      </div>

      {/* Progress Steps */}
      <div className="px-6 py-4 border-b border-gray-200 dark:border-gray-700">
        <div className="flex items-center justify-between">
          {steps.map((step, index) => {
            const Icon = getStepIcon(step.id as WizardStep);
            const isActive = step.id === currentStep;
            const isCompleted = index < currentStepIndex;

            return (
              <div
                key={step.id}
                className={`flex items-center ${index < steps.length - 1 ? 'flex-1' : ''}`}
              >
                <div className={`flex items-center justify-center w-8 h-8 rounded-full ${
                  isActive 
                    ? 'bg-blue-600 text-white' 
                    : isCompleted 
                      ? 'bg-green-600 text-white' 
                      : 'bg-gray-300 text-gray-600'
                }`}>
                  {isCompleted ? (
                    <FiCheck className="w-4 h-4" />
                  ) : (
                    <Icon className="w-4 h-4" />
                  )}
                </div>
                <span className={`ml-2 text-sm ${
                  isActive 
                    ? 'text-blue-600 font-medium' 
                    : isCompleted 
                      ? 'text-green-600' 
                      : 'text-gray-500'
                }`}>
                  {step.label}
                </span>
                {index < steps.length - 1 && (
                  <div className={`flex-1 h-0.5 mx-4 ${
                    isCompleted ? 'bg-green-600' : 'bg-gray-300'
                  }`} />
                )}
              </div>
            );
          })}
        </div>
      </div>

      {/* Content */}
      <div className="p-6 max-h-96 overflow-y-auto">
        {validationErrors.length > 0 && (
          <div className="mb-6 p-4 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg">
            <h4 className="font-medium text-red-800 dark:text-red-200 mb-2">
              Please fix the following errors:
            </h4>
            <ul className="list-disc list-inside text-sm text-red-700 dark:text-red-300">
              {validationErrors.map((error, index) => (
                <li key={index}>{error}</li>
              ))}
            </ul>
          </div>
        )}

        {renderStepContent()}
      </div>

      {/* Actions */}
      <div className="flex items-center justify-between p-6 border-t border-gray-200 dark:border-gray-700">
        <button
          onClick={handlePrevious}
          disabled={currentStep === 'format'}
          className="flex items-center space-x-2 px-4 py-2 text-gray-600 dark:text-gray-300 hover:text-gray-800 dark:hover:text-gray-100 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          <FiChevronLeft className="w-4 h-4" />
          <span>Previous</span>
        </button>

        <div className="flex items-center space-x-3">
          <button
            onClick={onCancel}
            className="px-4 py-2 text-gray-600 dark:text-gray-300 hover:text-gray-800 dark:hover:text-gray-100"
          >
            Cancel
          </button>
          {currentStep === 'review' ? (
            <button
              onClick={handleComplete}
              disabled={loading}
              className="flex items-center space-x-2 bg-blue-600 text-white px-6 py-2 rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              <FiDownload className="w-4 h-4" />
              <span>{loading ? 'Creating...' : 'Start Export'}</span>
            </button>
          ) : (
            <button
              onClick={handleNext}
              className="flex items-center space-x-2 bg-blue-600 text-white px-6 py-2 rounded-lg hover:bg-blue-700"
            >
              <span>Next</span>
              <FiChevronRight className="w-4 h-4" />
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default ExportWizard;

/**
 * Epic 9.2.5 - Notification Center UI Component
 * Complete notification system with real-time updates, filtering, and user preferences
 */

import React, { useState, useEffect, useRef } from 'react';
import { NotificationManager } from './NotificationManager';

export interface Notification {
  id: string;
  user_id: string;
  workspace_id: string;
  event_id?: string;
  notification_type: string;
  title: string;
  message: string;
  action_url?: string;
  priority: 'low' | 'normal' | 'high' | 'urgent';
  delivery_channel: 'in_app' | 'email' | 'push';
  read_at?: string;
  delivered_at: string;

  // Additional UI properties
  icon?: string;
  color?: string;
  action_label?: string;
}

interface NotificationCenterProps {
  notificationManager: NotificationManager;
  isOpen: boolean;
  onClose: () => void;
  className?: string;
}

export const NotificationCenter: React.FC<NotificationCenterProps> = ({
  notificationManager,
  isOpen,
  onClose,
  className = ''
}) => {
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [loading, setLoading] = useState(false);
  const [filter, setFilter] = useState<'all' | 'unread' | 'mentions' | 'workspace'>('all');
  const [sortBy, setSortBy] = useState<'newest' | 'priority' | 'type'>('newest');
  const panelRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (isOpen) {
      loadNotifications();
    }
  }, [isOpen, filter, sortBy]);

  useEffect(() => {
    // Set up real-time notification updates
    const unsubscribe = notificationManager.onNotificationReceived((notification) => {
      setNotifications(prev => [notification, ...prev]);
      if (!notification.read_at) {
        setUnreadCount(prev => prev + 1);
      }
    });

    return unsubscribe;
  }, [notificationManager]);

  useEffect(() => {
    // Close panel when clicking outside
    const handleClickOutside = (event: MouseEvent) => {
      if (panelRef.current && !panelRef.current.contains(event.target as Node)) {
        onClose();
      }
    };

    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [isOpen, onClose]);

  const loadNotifications = async () => {
    try {
      setLoading(true);
      const result = await notificationManager.getNotifications({
        filter,
        sort_by: sortBy,
        limit: 50
      });
      setNotifications(result.notifications);
      setUnreadCount(result.unread_count);
    } catch (error) {
      console.error('Failed to load notifications:', error);
    } finally {
      setLoading(false);
    }
  };

  const markAsRead = async (notificationId: string) => {
    try {
      await notificationManager.markAsRead(notificationId);
      setNotifications(prev => 
        prev.map(n => 
          n.id === notificationId 
            ? { ...n, read_at: new Date().toISOString() }
            : n
        )
      );
      setUnreadCount(prev => Math.max(0, prev - 1));
    } catch (error) {
      console.error('Failed to mark notification as read:', error);
    }
  };

  const markAllAsRead = async () => {
    try {
      const unreadIds = notifications.filter(n => !n.read_at).map(n => n.id);
      await notificationManager.markAllAsRead(unreadIds);

      setNotifications(prev => 
        prev.map(n => ({ ...n, read_at: n.read_at || new Date().toISOString() }))
      );
      setUnreadCount(0);
    } catch (error) {
      console.error('Failed to mark all notifications as read:', error);
    }
  };

  const deleteNotification = async (notificationId: string) => {
    try {
      await notificationManager.deleteNotification(notificationId);
      setNotifications(prev => prev.filter(n => n.id !== notificationId));
    } catch (error) {
      console.error('Failed to delete notification:', error);
    }
  };

  const handleNotificationClick = (notification: Notification) => {
    if (!notification.read_at) {
      markAsRead(notification.id);
    }

    if (notification.action_url) {
      // Navigate to the action URL
      window.location.href = notification.action_url;
    }
  };

  const getNotificationIcon = (notification: Notification): string => {
    if (notification.icon) return notification.icon;

    switch (notification.notification_type) {
      case 'comment':
        return '💬';
      case 'mention':
        return '@';
      case 'collaboration':
        return '👥';
      case 'workspace':
        return '🏢';
      case 'template':
        return '📋';
      case 'approval':
        return '✅';
      case 'rejection':
        return '❌';
      case 'system':
        return 'ℹ️';
      default:
        return '🔔';
    }
  };

  const getPriorityColor = (priority: string): string => {
    switch (priority) {
      case 'urgent':
        return 'text-red-600 bg-red-100';
      case 'high':
        return 'text-orange-600 bg-orange-100';
      case 'normal':
        return 'text-blue-600 bg-blue-100';
      case 'low':
        return 'text-gray-600 bg-gray-100';
      default:
        return 'text-gray-600 bg-gray-100';
    }
  };

  const formatTimeAgo = (dateString: string): string => {
    const date = new Date(dateString);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMins / 60);
    const diffDays = Math.floor(diffHours / 24);

    if (diffMins < 1) return 'Just now';
    if (diffMins < 60) return `${diffMins}m ago`;
    if (diffHours < 24) return `${diffHours}h ago`;
    if (diffDays < 7) return `${diffDays}d ago`;

    return date.toLocaleDateString();
  };

  if (!isOpen) return null;

  return (
    <div className={`notification-center ${className}`}>
      <div 
        ref={panelRef}
        className="absolute right-0 top-12 w-96 bg-white rounded-lg shadow-xl border border-gray-200 z-50 max-h-[80vh] flex flex-col"
      >
        {/* Header */}
        <div className="p-4 border-b border-gray-200">
          <div className="flex items-center justify-between mb-3">
            <h3 className="text-lg font-semibold text-gray-900">Notifications</h3>
            <div className="flex items-center space-x-2">
              {unreadCount > 0 && (
                <button
                  onClick={markAllAsRead}
                  className="text-sm text-blue-600 hover:text-blue-800 transition-colors"
                >
                  Mark all read
                </button>
              )}
              <button
                onClick={onClose}
                className="text-gray-400 hover:text-gray-500 transition-colors"
              >
                <svg className="h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>
          </div>

          {/* Filters */}
          <div className="flex space-x-2">
            <select
              value={filter}
              onChange={(e) => setFilter(e.target.value as any)}
              className="text-sm border border-gray-300 rounded px-2 py-1 focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            >
              <option value="all">All</option>
              <option value="unread">Unread</option>
              <option value="mentions">Mentions</option>
              <option value="workspace">Workspace</option>
            </select>

            <select
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value as any)}
              className="text-sm border border-gray-300 rounded px-2 py-1 focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            >
              <option value="newest">Newest</option>
              <option value="priority">Priority</option>
              <option value="type">Type</option>
            </select>
          </div>
        </div>

        {/* Notifications List */}
        <div className="flex-1 overflow-y-auto">
          {loading ? (
            <div className="flex justify-center items-center py-8">
              <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-blue-500"></div>
            </div>
          ) : notifications.length === 0 ? (
            <div className="text-center py-8 text-gray-500">
              <div className="text-4xl mb-2">🔔</div>
              <h4 className="font-medium text-gray-900 mb-1">All caught up!</h4>
              <p className="text-sm">No notifications to display.</p>
            </div>
          ) : (
            <div className="divide-y divide-gray-100">
              {notifications.map(notification => (
                <NotificationItem
                  key={notification.id}
                  notification={notification}
                  onClick={() => handleNotificationClick(notification)}
                  onMarkAsRead={() => markAsRead(notification.id)}
                  onDelete={() => deleteNotification(notification.id)}
                  getIcon={getNotificationIcon}
                  getPriorityColor={getPriorityColor}
                  formatTimeAgo={formatTimeAgo}
                />
              ))}
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-gray-200">
          <button
            onClick={() => {
              // Navigate to notification preferences
              window.location.href = '/settings/notifications';
            }}
            className="w-full text-sm text-blue-600 hover:text-blue-800 transition-colors"
          >
            Notification Settings
          </button>
        </div>
      </div>
    </div>
  );
};

interface NotificationItemProps {
  notification: Notification;
  onClick: () => void;
  onMarkAsRead: () => void;
  onDelete: () => void;
  getIcon: (notification: Notification) => string;
  getPriorityColor: (priority: string) => string;
  formatTimeAgo: (dateString: string) => string;
}

const NotificationItem: React.FC<NotificationItemProps> = ({
  notification,
  onClick,
  onMarkAsRead,
  onDelete,
  getIcon,
  getPriorityColor,
  formatTimeAgo
}) => {
  const [showActions, setShowActions] = useState(false);

  return (
    <div 
      className={`p-4 hover:bg-gray-50 transition-colors cursor-pointer relative ${
        !notification.read_at ? 'bg-blue-50 border-l-4 border-l-blue-500' : ''
      }`}
      onClick={onClick}
      onMouseEnter={() => setShowActions(true)}
      onMouseLeave={() => setShowActions(false)}
    >
      <div className="flex items-start space-x-3">
        {/* Icon */}
        <div className="flex-shrink-0">
          <span className="text-lg">{getIcon(notification)}</span>
        </div>

        {/* Content */}
        <div className="flex-1 min-w-0">
          <div className="flex items-center justify-between mb-1">
            <h4 className="text-sm font-medium text-gray-900 truncate">
              {notification.title}
            </h4>
            <div className="flex items-center space-x-2">
              {notification.priority !== 'normal' && (
                <span className={`text-xs px-2 py-1 rounded-full ${getPriorityColor(notification.priority)}`}>
                  {notification.priority}
                </span>
              )}
              <span className="text-xs text-gray-500">
                {formatTimeAgo(notification.delivered_at)}
              </span>
            </div>
          </div>

          <p className="text-sm text-gray-600 line-clamp-2">
            {notification.message}
          </p>

          {notification.action_label && (
            <button className="text-xs text-blue-600 hover:text-blue-800 mt-2">
              {notification.action_label}
            </button>
          )}
        </div>

        {/* Action Buttons */}
        {showActions && (
          <div className="absolute top-2 right-2 flex space-x-1">
            {!notification.read_at && (
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  onMarkAsRead();
                }}
                className="p-1 text-gray-400 hover:text-blue-600 transition-colors"
                title="Mark as read"
              >
                <svg className="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                </svg>
              </button>
            )}

            <button
              onClick={(e) => {
                e.stopPropagation();
                onDelete();
              }}
              className="p-1 text-gray-400 hover:text-red-600 transition-colors"
              title="Delete"
            >
              <svg className="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
              </svg>
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

/**
 * Epic 9.2.5 - Notification Manager
 * Manages notification delivery, preferences, and real-time updates
 */

import { Notification } from './NotificationCenter';

export interface NotificationPreferences {
  in_app_enabled: boolean;
  email_enabled: boolean;
  push_enabled: boolean;

  // Event type preferences
  comments: {
    enabled: boolean;
    channels: ('in_app' | 'email' | 'push')[];
    mentions_only: boolean;
  };
  collaboration: {
    enabled: boolean;
    channels: ('in_app' | 'email' | 'push')[];
    presence_updates: boolean;
  };
  workspace: {
    enabled: boolean;
    channels: ('in_app' | 'email' | 'push')[];
    member_changes: boolean;
  };
  approvals: {
    enabled: boolean;
    channels: ('in_app' | 'email' | 'push')[];
  };
  system: {
    enabled: boolean;
    channels: ('in_app' | 'email' | 'push')[];
    maintenance_only: boolean;
  };

  // Timing preferences
  quiet_hours: {
    enabled: boolean;
    start_time: string; // HH:MM format
    end_time: string;
    timezone: string;
  };
  digest: {
    enabled: boolean;
    frequency: 'hourly' | 'daily' | 'weekly';
    time: string; // HH:MM format
  };
}

export interface NotificationFilter {
  filter: 'all' | 'unread' | 'mentions' | 'workspace';
  sort_by: 'newest' | 'priority' | 'type';
  limit?: number;
  offset?: number;
  start_date?: string;
  end_date?: string;
}

export interface NotificationStats {
  total: number;
  unread: number;
  by_type: Record<string, number>;
  by_priority: Record<string, number>;
  by_day: { date: string; count: number }[];
}

export class NotificationManager {
  private notifications = new Map<string, Notification>();
  private preferences: NotificationPreferences | null = null;
  private wsConnection: WebSocket | null = null;
  private listeners = new Set<(notification: Notification) => void>();
  private reconnectAttempts = 0;
  private maxReconnectAttempts = 5;

  constructor(private apiClient: any, private userId: string) {
    this.initializeWebSocket();
    this.loadPreferences();
  }

  // Real-time notification handling
  private initializeWebSocket() {
    try {
      const wsUrl = `ws://localhost:8000/ws/notifications/${this.userId}`;
      this.wsConnection = new WebSocket(wsUrl);

      this.wsConnection.onopen = () => {
        console.log('Notification WebSocket connected');
        this.reconnectAttempts = 0;
      };

      this.wsConnection.onmessage = (event) => {
        try {
          const notification = JSON.parse(event.data) as Notification;
          this.handleIncomingNotification(notification);
        } catch (error) {
          console.error('Failed to parse notification:', error);
        }
      };

      this.wsConnection.onclose = () => {
        console.log('Notification WebSocket disconnected');
        this.attemptReconnect();
      };

      this.wsConnection.onerror = (error) => {
        console.error('Notification WebSocket error:', error);
      };
    } catch (error) {
      console.error('Failed to initialize WebSocket:', error);
    }
  }

  private attemptReconnect() {
    if (this.reconnectAttempts < this.maxReconnectAttempts) {
      this.reconnectAttempts++;
      const delay = Math.min(1000 * Math.pow(2, this.reconnectAttempts), 30000);

      setTimeout(() => {
        console.log(`Attempting notification WebSocket reconnection (${this.reconnectAttempts}/${this.maxReconnectAttempts})`);
        this.initializeWebSocket();
      }, delay);
    }
  }

  private handleIncomingNotification(notification: Notification) {
    // Store notification
    this.notifications.set(notification.id, notification);

    // Check if notification should be shown based on preferences
    if (this.shouldShowNotification(notification)) {
      // Show browser notification if supported and enabled
      this.showBrowserNotification(notification);

      // Notify listeners
      this.listeners.forEach(listener => listener(notification));
    }
  }

  private shouldShowNotification(notification: Notification): boolean {
    if (!this.preferences) return true;

    // Check global preferences
    if (!this.preferences.in_app_enabled && notification.delivery_channel === 'in_app') {
      return false;
    }

    // Check quiet hours
    if (this.preferences.quiet_hours.enabled && this.isInQuietHours()) {
      // Only show urgent notifications during quiet hours
      return notification.priority === 'urgent';
    }

    // Check type-specific preferences
    const typePrefs = this.getTypePreferences(notification.notification_type);
    if (!typePrefs?.enabled) {
      return false;
    }

    return true;
  }

  private isInQuietHours(): boolean {
    if (!this.preferences?.quiet_hours.enabled) return false;

    const now = new Date();
    const currentTime = now.toTimeString().slice(0, 5); // HH:MM format
    const startTime = this.preferences.quiet_hours.start_time;
    const endTime = this.preferences.quiet_hours.end_time;

    // Handle overnight quiet hours (e.g., 22:00 to 08:00)
    if (startTime > endTime) {
      return currentTime >= startTime || currentTime <= endTime;
    } else {
      return currentTime >= startTime && currentTime <= endTime;
    }
  }

  private getTypePreferences(notificationType: string) {
    if (!this.preferences) return null;

    switch (notificationType) {
      case 'comment':
      case 'mention':
        return this.preferences.comments;
      case 'collaboration':
        return this.preferences.collaboration;
      case 'workspace':
        return this.preferences.workspace;
      case 'approval':
      case 'rejection':
        return this.preferences.approvals;
      case 'system':
        return this.preferences.system;
      default:
        return null;
    }
  }

  private showBrowserNotification(notification: Notification) {
    if (!('Notification' in window) || Notification.permission !== 'granted') {
      return;
    }

    const browserNotification = new Notification(notification.title, {
      body: notification.message,
      icon: '/favicon.ico',
      tag: notification.id,
      requireInteraction: notification.priority === 'urgent'
    });

    browserNotification.onclick = () => {
      window.focus();
      if (notification.action_url) {
        window.location.href = notification.action_url;
      }
      browserNotification.close();
    };

    // Auto-close after 5 seconds for non-urgent notifications
    if (notification.priority !== 'urgent') {
      setTimeout(() => browserNotification.close(), 5000);
    }
  }

  // Public API methods
  async getNotifications(filter: NotificationFilter): Promise<{ notifications: Notification[]; total: number; unread_count: number }> {
    try {
      const params = new URLSearchParams();
      Object.entries(filter).forEach(([key, value]) => {
        if (value !== undefined) {
          params.append(key, String(value));
        }
      });

      const response = await this.apiClient.get(`/api/notifications?${params}`);
      const result = response.data;

      // Update local cache
      result.notifications.forEach((notification: Notification) => {
        this.notifications.set(notification.id, notification);
      });

      return result;
    } catch (error) {
      console.error('Failed to get notifications:', error);
      throw error;
    }
  }

  async markAsRead(notificationId: string): Promise<void> {
    try {
      await this.apiClient.put(`/api/notifications/${notificationId}/read`);

      // Update local cache
      const notification = this.notifications.get(notificationId);
      if (notification) {
        notification.read_at = new Date().toISOString();
        this.notifications.set(notificationId, notification);
      }
    } catch (error) {
      console.error('Failed to mark notification as read:', error);
      throw error;
    }
  }

  async markAllAsRead(notificationIds: string[]): Promise<void> {
    try {
      await this.apiClient.put('/api/notifications/read-all', {
        notification_ids: notificationIds
      });

      // Update local cache
      const now = new Date().toISOString();
      notificationIds.forEach(id => {
        const notification = this.notifications.get(id);
        if (notification) {
          notification.read_at = now;
          this.notifications.set(id, notification);
        }
      });
    } catch (error) {
      console.error('Failed to mark all notifications as read:', error);
      throw error;
    }
  }

  async deleteNotification(notificationId: string): Promise<void> {
    try {
      await this.apiClient.delete(`/api/notifications/${notificationId}`);
      this.notifications.delete(notificationId);
    } catch (error) {
      console.error('Failed to delete notification:', error);
      throw error;
    }
  }

  async getStats(days: number = 30): Promise<NotificationStats> {
    try {
      const response = await this.apiClient.get(`/api/notifications/stats?days=${days}`);
      return response.data;
    } catch (error) {
      console.error('Failed to get notification stats:', error);
      throw error;
    }
  }

  // Preference management
  async getPreferences(): Promise<NotificationPreferences> {
    try {
      const response = await this.apiClient.get('/api/notification-preferences');
      this.preferences = response.data;
      return this.preferences;
    } catch (error) {
      console.error('Failed to get notification preferences:', error);
      throw error;
    }
  }

  async updatePreferences(preferences: Partial<NotificationPreferences>): Promise<NotificationPreferences> {
    try {
      const response = await this.apiClient.put('/api/notification-preferences', preferences);
      this.preferences = response.data;
      return this.preferences;
    } catch (error) {
      console.error('Failed to update notification preferences:', error);
      throw error;
    }
  }

  private async loadPreferences() {
    try {
      await this.getPreferences();
    } catch (error) {
      // Use default preferences if loading fails
      this.preferences = this.getDefaultPreferences();
    }
  }

  private getDefaultPreferences(): NotificationPreferences {
    return {
      in_app_enabled: true,
      email_enabled: true,
      push_enabled: false,
      comments: {
        enabled: true,
        channels: ['in_app', 'email'],
        mentions_only: false
      },
      collaboration: {
        enabled: true,
        channels: ['in_app'],
        presence_updates: false
      },
      workspace: {
        enabled: true,
        channels: ['in_app', 'email'],
        member_changes: true
      },
      approvals: {
        enabled: true,
        channels: ['in_app', 'email']
      },
      system: {
        enabled: true,
        channels: ['in_app'],
        maintenance_only: true
      },
      quiet_hours: {
        enabled: false,
        start_time: '22:00',
        end_time: '08:00',
        timezone: Intl.DateTimeFormat().resolvedOptions().timeZone
      },
      digest: {
        enabled: false,
        frequency: 'daily',
        time: '09:00'
      }
    };
  }

  // Event listeners
  onNotificationReceived(callback: (notification: Notification) => void): () => void {
    this.listeners.add(callback);
    return () => this.listeners.delete(callback);
  }

  // Utility methods
  async requestPermission(): Promise<NotificationPermission> {
    if (!('Notification' in window)) {
      return 'denied';
    }

    if (Notification.permission === 'default') {
      return await Notification.requestPermission();
    }

    return Notification.permission;
  }

  getUnreadCount(): number {
    return Array.from(this.notifications.values()).filter(n => !n.read_at).length;
  }

  // Send notification (for testing/admin purposes)
  async sendNotification(notification: Omit<Notification, 'id' | 'user_id' | 'delivered_at'>): Promise<void> {
    try {
      await this.apiClient.post('/api/notifications', notification);
    } catch (error) {
      console.error('Failed to send notification:', error);
      throw error;
    }
  }

  // Cleanup
  disconnect() {
    if (this.wsConnection) {
      this.wsConnection.close();
      this.wsConnection = null;
    }
    this.listeners.clear();
  }
}

/**
 * Epic 9.2.5 - Notification Preferences Component
 * User interface for managing notification settings and preferences
 */

import React, { useState, useEffect } from 'react';
import { NotificationManager, NotificationPreferences as PrefsType } from './NotificationManager';

interface NotificationPreferencesProps {
  notificationManager: NotificationManager;
  className?: string;
}

export const NotificationPreferences: React.FC<NotificationPreferencesProps> = ({
  notificationManager,
  className = ''
}) => {
  const [preferences, setPreferences] = useState<PrefsType | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [hasChanges, setHasChanges] = useState(false);
  const [browserPermission, setBrowserPermission] = useState<NotificationPermission>('default');

  useEffect(() => {
    loadPreferences();
    checkBrowserPermission();
  }, []);

  const loadPreferences = async () => {
    try {
      setLoading(true);
      const prefs = await notificationManager.getPreferences();
      setPreferences(prefs);
    } catch (error) {
      console.error('Failed to load preferences:', error);
    } finally {
      setLoading(false);
    }
  };

  const checkBrowserPermission = () => {
    if ('Notification' in window) {
      setBrowserPermission(Notification.permission);
    }
  };

  const requestBrowserPermission = async () => {
    const permission = await notificationManager.requestPermission();
    setBrowserPermission(permission);
  };

  const updatePreferences = (updates: Partial<PrefsType>) => {
    if (!preferences) return;

    const newPrefs = { ...preferences, ...updates };
    setPreferences(newPrefs);
    setHasChanges(true);
  };

  const updateTypePreferences = (type: keyof PrefsType, updates: any) => {
    if (!preferences) return;

    const newPrefs = {
      ...preferences,
      [type]: { ...preferences[type], ...updates }
    };
    setPreferences(newPrefs);
    setHasChanges(true);
  };

  const savePreferences = async () => {
    if (!preferences || !hasChanges) return;

    try {
      setSaving(true);
      await notificationManager.updatePreferences(preferences);
      setHasChanges(false);
    } catch (error) {
      console.error('Failed to save preferences:', error);
    } finally {
      setSaving(false);
    }
  };

  const resetToDefaults = () => {
    // This would reset to default preferences
    loadPreferences();
    setHasChanges(false);
  };

  if (loading || !preferences) {
    return (
      <div className={`notification-preferences ${className}`}>
        <div className="flex justify-center items-center py-8">
          <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-blue-500"></div>
        </div>
      </div>
    );
  }

  return (
    <div className={`notification-preferences ${className} max-w-4xl mx-auto`}>
      {/* Header */}
      <div className="mb-8">
        <h2 className="text-2xl font-bold text-gray-900 mb-2">Notification Preferences</h2>
        <p className="text-gray-600">
          Customize how and when you receive notifications to stay informed without being overwhelmed.
        </p>
      </div>

      {/* Browser Permission Warning */}
      {browserPermission !== 'granted' && (
        <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4 mb-6">
          <div className="flex items-start">
            <svg className="h-5 w-5 text-yellow-400 mt-0.5 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.728-.833-2.498 0L3.316 16.5c-.77.833.192 2.5 1.732 2.5z" />
            </svg>
            <div className="flex-1">
              <h3 className="text-sm font-medium text-yellow-800">Browser notifications disabled</h3>
              <p className="text-sm text-yellow-700 mt-1">
                Enable browser notifications to receive real-time alerts even when the app isn't active.
              </p>
              <button
                onClick={requestBrowserPermission}
                className="mt-2 text-sm bg-yellow-100 text-yellow-800 px-3 py-1 rounded hover:bg-yellow-200 transition-colors"
              >
                Enable Browser Notifications
              </button>
            </div>
          </div>
