const { Option } = Select;

interface RestorationPreviewProps {
  preview: RestorationPreviewResponse;
  config: RestorationConfig;
  onConflictResolve: (conflictId: string, strategy: ResolutionStrategy) => void;
}

export const RestorationPreview: React.FC<RestorationPreviewProps> = ({
  preview,
  config,
  onConflictResolve,
}) => {
  const [activeTab, setActiveTab] = useState('changes');
  const [conflictResolutions, setConflictResolutions] = useState<Record<string, ResolutionStrategy>>({});

  const handleConflictResolution = (conflictId: string, strategy: ResolutionStrategy) => {
    setConflictResolutions(prev => ({
      ...prev,
      [conflictId]: strategy,
    }));
    onConflictResolve(conflictId, strategy);
  };

  const getChangeIcon = (type: string) => {
    switch (type) {
      case 'add':
        return <PlusOutlined style={{ color: '#52c41a' }} />;
      case 'update':
        return <EditOutlined style={{ color: '#1890ff' }} />;
      case 'delete':
        return <MinusOutlined style={{ color: '#ff4d4f' }} />;
      default:
        return <InfoCircleOutlined />;
    }
  };

  const getChangeColor = (type: string) => {
    switch (type) {
      case 'add':
        return 'success';
      case 'update':
        return 'processing';
      case 'delete':
        return 'error';
      default:
        return 'default';
    }
  };

  const getRiskLevelColor = (level: string) => {
    switch (level) {
      case 'low':
        return 'success';
      case 'medium':
        return 'warning';
      case 'high':
        return 'error';
      default:
        return 'default';
    }
  };

  const nodeColumns = [
    {
      title: 'Action',
      dataIndex: 'action',
      key: 'action',
      width: 80,
      render: (action: string) => (
        <Tag color={getChangeColor(action) as any} icon={getChangeIcon(action)}>
          {action.toUpperCase()}
        </Tag>
      ),
    },
    {
      title: 'Node ID',
      dataIndex: 'id',
      key: 'id',
      width: 200,
      render: (id: string) => (
        <Text code style={{ fontSize: '12px' }}>
          {id}
        </Text>
      ),
    },
    {
      title: 'Type',
      dataIndex: 'type',
      key: 'type',
      width: 120,
    },
    {
      title: 'Label',
      dataIndex: 'label',
      key: 'label',
      render: (label: string) => label || <Text type="secondary">No label</Text>,
    },
    {
      title: 'Properties',
      dataIndex: 'properties',
      key: 'properties',
      render: (properties: any) => (
        <Text type="secondary">
          {properties ? Object.keys(properties).length : 0} properties
        </Text>
      ),
    },
  ];

  const edgeColumns = [
    {
      title: 'Action',
      dataIndex: 'action',
      key: 'action',
      width: 80,
      render: (action: string) => (
        <Tag color={getChangeColor(action) as any} icon={getChangeIcon(action)}>
          {action.toUpperCase()}
        </Tag>
      ),
    },
    {
      title: 'Edge ID',
      dataIndex: 'id',
      key: 'id',
      width: 200,
      render: (id: string) => (
        <Text code style={{ fontSize: '12px' }}>
          {id}
        </Text>
      ),
    },
    {
      title: 'From',
      dataIndex: 'source',
      key: 'source',
      width: 150,
      render: (source: string) => (
        <Text code style={{ fontSize: '12px' }}>
          {source}
        </Text>
      ),
    },
    {
      title: 'To',
      dataIndex: 'target',
      key: 'target',
      width: 150,
      render: (target: string) => (
        <Text code style={{ fontSize: '12px' }}>
          {target}
        </Text>
      ),
    },
    {
      title: 'Type',
      dataIndex: 'type',
      key: 'type',
      width: 120,
    },
  ];

  const conflictColumns = [
    {
      title: 'Conflict',
      dataIndex: 'conflictType',
      key: 'conflictType',
      width: 150,
      render: (type: string) => (
        <Tooltip title={CONFLICT_DESCRIPTIONS[type as keyof typeof CONFLICT_DESCRIPTIONS]}>
          <Tag color="warning" icon={<WarningOutlined />}>
            {type.replace('_', ' ').toUpperCase()}
          </Tag>
        </Tooltip>
      ),
    },
    {
      title: 'Resource',
      dataIndex: 'resourceId',
      key: 'resourceId',
      width: 200,
      render: (resourceId: string, record: RestorationConflict) => (
        <div>
          <Text code style={{ fontSize: '12px' }}>
            {resourceId}
          </Text>
          <br />
          <Text type="secondary" style={{ fontSize: '11px' }}>
            {record.resourceType}
          </Text>
        </div>
      ),
    },
    {
      title: 'Description',
      dataIndex: 'conflictDescription',
      key: 'conflictDescription',
      render: (description: string) => description || <Text type="secondary">No description</Text>,
    },
    {
      title: 'Resolution',
      dataIndex: 'id',
      key: 'resolution',
      width: 200,
      render: (conflictId: string) => (
        <Select
          placeholder="Choose resolution"
          style={{ width: '100%' }}
          value={conflictResolutions[conflictId]}
          onChange={(value) => handleConflictResolution(conflictId, value)}
        >
          {Object.entries(RESOLUTION_STRATEGY_DESCRIPTIONS).map(([key, description]) => (
            <Option key={key} value={key}>
              <Tooltip title={description}>
                {key.replace('_', ' ').toUpperCase()}
              </Tooltip>
            </Option>
          ))}
        </Select>
      ),
    },
  ];

  const allNodeChanges = [
    ...preview.preview.nodesToAdd.map((node: any) => ({ ...node, action: 'add' })),
    ...preview.preview.nodesToUpdate.map((node: any) => ({ ...node, action: 'update' })),
    ...preview.preview.nodesToDelete.map((id: string) => ({ id, action: 'delete' })),
  ];

  const allEdgeChanges = [
    ...preview.preview.edgesToAdd.map((edge: any) => ({ ...edge, action: 'add' })),
    ...preview.preview.edgesToUpdate.map((edge: any) => ({ ...edge, action: 'update' })),
    ...preview.preview.edgesToDelete.map((id: string) => ({ id, action: 'delete' })),
  ];

  const unresolvedConflicts = preview.conflicts.filter(
    conflict => !conflictResolutions[conflict.id]
  );

  return (
    <div>
      {/* Summary Cards */}
      <Row gutter={16} style={{ marginBottom: '24px' }}>
        <Col span={6}>
          <Card>
            <Statistic
              title="Total Changes"
              value={preview.summary.totalChanges}
              prefix={<EditOutlined />}
            />
          </Card>
        </Col>
        <Col span={6}>
          <Card>
            <Statistic
              title="Conflicts"
              value={preview.summary.totalConflicts}
              prefix={<WarningOutlined />}
              valueStyle={{ color: preview.summary.totalConflicts > 0 ? '#ff4d4f' : '#3f8600' }}
            />
          </Card>
        </Col>
        <Col span={6}>
          <Card>
            <Statistic
              title="Estimated Duration"
              value={preview.summary.estimatedDuration}
              suffix="ms"
              prefix={<InfoCircleOutlined />}
            />
          </Card>
        </Col>
        <Col span={6}>
          <Card>
            <Statistic
              title="Risk Level"
              value={preview.summary.riskLevel.toUpperCase()}
              prefix={<QuestionCircleOutlined />}
              valueStyle={{ color: getRiskLevelColor(preview.summary.riskLevel) }}
            />
          </Card>
        </Col>
      </Row>

      {/* Conflicts Alert */}
      {preview.summary.totalConflicts > 0 && (
        <Alert
          type="warning"
          message="Conflicts Detected"
          description={
            <div>
              <Text>
                {preview.summary.totalConflicts} conflicts were detected that require resolution.
              </Text>
              {unresolvedConflicts.length > 0 && (
                <Text type="secondary">
                  {' '}({unresolvedConflicts.length} unresolved)
                </Text>
              )}
            </div>
          }
          showIcon
          style={{ marginBottom: '16px' }}
        />
      )}

      {/* Main Content Tabs */}
      <Tabs activeKey={activeTab} onChange={setActiveTab}>
        <TabPane
          tab={
            <Badge count={allNodeChanges.length + allEdgeChanges.length} offset={[10, 0]}>
              Changes
            </Badge>
          }
          key="changes"
        >
          <Collapse defaultActiveKey={['nodes', 'edges']}>
            <Panel
              header={
                <Space>
                  <Text strong>Node Changes</Text>
                  <Badge count={allNodeChanges.length} showZero />
                </Space>
              }
              key="nodes"
            >
              <Table
                columns={nodeColumns}
                dataSource={allNodeChanges}
                rowKey="id"
                size="small"
                pagination={{ pageSize: 10 }}
                scroll={{ y: 300 }}
              />
            </Panel>
            <Panel
              header={
                <Space>
                  <Text strong>Edge Changes</Text>
                  <Badge count={allEdgeChanges.length} showZero />
                </Space>
              }
              key="edges"
            >
              <Table
                columns={edgeColumns}
                dataSource={allEdgeChanges}
                rowKey="id"
                size="small"
                pagination={{ pageSize: 10 }}
                scroll={{ y: 300 }}
              />
            </Panel>
          </Collapse>
        </TabPane>

        <TabPane
          tab={
            <Badge count={preview.summary.totalConflicts} offset={[10, 0]}>
              Conflicts
            </Badge>
          }
          key="conflicts"
        >
          {preview.summary.totalConflicts > 0 ? (
            <Table
              columns={conflictColumns}
              dataSource={preview.conflicts}
              rowKey="id"
              size="small"
              pagination={{ pageSize: 10 }}
              scroll={{ y: 400 }}
            />
          ) : (
            <div style={{ textAlign: 'center', padding: '40px' }}>
              <Text type="secondary">
                No conflicts detected. The restoration can proceed without manual intervention.
              </Text>
            </div>
          )}
        </TabPane>

        <TabPane tab="Configuration" key="config">
          <Card>
            <Row gutter={16}>
              <Col span={12}>
                <Title level={5}>Restoration Settings</Title>
                <p><Text strong>Type:</Text> {config.restorationType}</p>
                <p><Text strong>Strategy:</Text> {config.restorationStrategy}</p>
                <p><Text strong>Preserve Changes:</Text> {config.preserveCurrentChanges ? 'Yes' : 'No'}</p>
              </Col>
              <Col span={12}>
                <Title level={5}>Options</Title>
                <p><Text strong>Create Backup:</Text> {config.createBackup ? 'Yes' : 'No'}</p>
                <p><Text strong>Notify on Completion:</Text> {config.notifyOnCompletion ? 'Yes' : 'No'}</p>
              </Col>
            </Row>
          </Card>
        </TabPane>
      </Tabs>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Modal, Steps, Button, Form, Select, Checkbox, Alert, Progress, Typography } from 'antd';
import { 
  RestoreOutlined, 
  ExclamationCircleOutlined, 
  CheckCircleOutlined, 
  CloseCircleOutlined,
  LoadingOutlined 
} from '@ant-design/icons';
import { RestorationPreview } from './RestorationPreview';
import { RestorationConfirmation } from './RestorationConfirmation';
import { RestoreProgressPanel } from './RestoreProgressPanel';
import { 
  RestorationConfig, 
  RestorationPreviewResponse, 
  RestorationAttempt,
  RestorationType,
  RestorationStrategy,
  RestorationProgressResponse,
} from '../../types/restoration';
import { useRestoration } from '../../hooks/useRestoration';

const { Step } = Steps;
const { Title, Text } = Typography;
const { Option } = Select;

interface RestorationWizardProps {
  visible: boolean;
  onClose: () => void;
  projectId: string;
  sourceSnapshotId: string;
  targetSnapshotId?: string;
  onSuccess?: (attempt: RestorationAttempt) => void;
  onError?: (error: string) => void;
}

interface WizardStep {
  title: string;
  description: string;
  icon: React.ReactNode;
}

const wizardSteps: WizardStep[] = [
  {
    title: 'Configure',
    description: 'Set restoration options',
    icon: <RestoreOutlined />,
  },
  {
    title: 'Preview',
    description: 'Review changes',
    icon: <ExclamationCircleOutlined />,
  },
  {
    title: 'Confirm',
    description: 'Confirm restoration',
    icon: <CheckCircleOutlined />,
  },
  {
    title: 'Progress',
    description: 'Monitor progress',
    icon: <LoadingOutlined />,
  },
];

export const RestorationWizard: React.FC<RestorationWizardProps> = ({
  visible,
  onClose,
  projectId,
  sourceSnapshotId,
  targetSnapshotId,
  onSuccess,
  onError,
}) => {
  const [currentStep, setCurrentStep] = useState(0);
  const [form] = Form.useForm();
  const [config, setConfig] = useState<RestorationConfig>({
    restorationType: 'full',
    restorationStrategy: 'replace',
    preserveCurrentChanges: false,
    createBackup: true,
    notifyOnCompletion: true,
  });
  const [preview, setPreview] = useState<RestorationPreviewResponse | null>(null);
  const [restorationAttempt, setRestorationAttempt] = useState<RestorationAttempt | null>(null);
  const [progress, setProgress] = useState<RestorationProgressResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const { 
    generatePreview, 
    createRestoration, 
    getProgress, 
    cancelRestoration 
  } = useRestoration();

  // Reset state when modal opens/closes
  useEffect(() => {
    if (visible) {
      setCurrentStep(0);
      setConfig({
        restorationType: 'full',
        restorationStrategy: 'replace',
        preserveCurrentChanges: false,
        createBackup: true,
        notifyOnCompletion: true,
      });
      setPreview(null);
      setRestorationAttempt(null);
      setProgress(null);
      setError(null);
      form.resetFields();
    }
  }, [visible, form]);

  // Poll for progress updates
  useEffect(() => {
    let interval: NodeJS.Timeout;

    if (restorationAttempt && currentStep === 3) {
      interval = setInterval(async () => {
        try {
          const progressData = await getProgress(restorationAttempt.id);
          setProgress(progressData);

          if (progressData.status === 'completed') {
            clearInterval(interval);
            onSuccess?.(restorationAttempt);
          } else if (progressData.status === 'failed') {
            clearInterval(interval);
            setError(progressData.errorMessage || 'Restoration failed');
            onError?.(progressData.errorMessage || 'Restoration failed');
          }
        } catch (error) {
          console.error('Failed to get progress:', error);
        }
      }, 1000);
    }

    return () => {
      if (interval) clearInterval(interval);
    };
  }, [restorationAttempt, currentStep, getProgress, onSuccess, onError]);

  const handleNext = async () => {
    if (currentStep === 0) {
      // Configuration step - validate and generate preview
      try {
        const values = await form.validateFields();
        const updatedConfig = { ...config, ...values };
        setConfig(updatedConfig);

        setLoading(true);
        const previewData = await generatePreview({
          projectId,
          sourceSnapshotId,
          targetSnapshotId,
          config: updatedConfig,
        });
        setPreview(previewData);
        setCurrentStep(1);
      } catch (error) {
        console.error('Failed to generate preview:', error);
        setError('Failed to generate preview. Please try again.');
      } finally {
        setLoading(false);
      }
    } else if (currentStep === 1) {
      // Preview step - move to confirmation
      setCurrentStep(2);
    } else if (currentStep === 2) {
      // Confirmation step - start restoration
      try {
        setLoading(true);
        const attempt = await createRestoration({
          projectId,
          sourceSnapshotId,
          targetSnapshotId,
          config,
        });
        setRestorationAttempt(attempt);
        setCurrentStep(3);
      } catch (error) {
        console.error('Failed to start restoration:', error);
        setError('Failed to start restoration. Please try again.');
      } finally {
        setLoading(false);
      }
    }
  };

  const handlePrevious = () => {
    setCurrentStep(Math.max(0, currentStep - 1));
    setError(null);
  };

  const handleCancel = async () => {
    if (restorationAttempt && currentStep === 3) {
      try {
        await cancelRestoration(restorationAttempt.id);
      } catch (error) {
        console.error('Failed to cancel restoration:', error);
      }
    }
    onClose();
  };

  const canGoNext = () => {
    if (currentStep === 0) return true;
    if (currentStep === 1) return preview !== null;
    if (currentStep === 2) return true;
    return false;
  };

  const canGoPrevious = () => {
    return currentStep > 0 && currentStep < 3;
  };

  const renderStepContent = () => {
    switch (currentStep) {
      case 0:
        return (
          <Form
            form={form}
            layout="vertical"
            initialValues={config}
            onValuesChange={(changedValues) => {
              setConfig(prev => ({ ...prev, ...changedValues }));
            }}
          >
            <Form.Item
              name="restorationType"
              label="Restoration Type"
              tooltip="Choose how much of the snapshot to restore"
            >
              <Select>
                <Option value="full">Full Restoration</Option>
                <Option value="partial">Partial Restoration</Option>
                <Option value="selective">Selective Restoration</Option>
              </Select>
            </Form.Item>

            <Form.Item
              name="restorationStrategy"
              label="Restoration Strategy"
              tooltip="Choose how to handle conflicts with current state"
            >
              <Select>
                <Option value="replace">Replace Current State</Option>
                <Option value="merge">Merge with Current State</Option>
                <Option value="selective">Selective Merge</Option>
              </Select>
            </Form.Item>

            <Form.Item name="preserveCurrentChanges" valuePropName="checked">
              <Checkbox>
                Preserve current changes where possible
              </Checkbox>
            </Form.Item>

            <Form.Item name="createBackup" valuePropName="checked">
              <Checkbox>
                Create backup before restoration
              </Checkbox>
            </Form.Item>

            <Form.Item name="notifyOnCompletion" valuePropName="checked">
              <Checkbox>
                Notify when restoration completes
              </Checkbox>
            </Form.Item>
          </Form>
        );

      case 1:
        return preview ? (
          <RestorationPreview
            preview={preview}
            config={config}
            onConflictResolve={(conflictId, strategy) => {
              // Handle conflict resolution
              console.log('Resolving conflict:', conflictId, strategy);
            }}
          />
        ) : (
          <div style={{ textAlign: 'center', padding: '40px' }}>
            <LoadingOutlined style={{ fontSize: '48px', marginBottom: '16px' }} />
            <Title level={4}>Generating Preview...</Title>
            <Text type="secondary">
              Please wait while we analyze the changes that will be made.
            </Text>
          </div>
        );

      case 2:
        return preview ? (
          <RestorationConfirmation
            preview={preview}
            config={config}
            onConfirm={() => handleNext()}
            onCancel={() => handlePrevious()}
          />
        ) : null;

      case 3:
        return progress ? (
          <RestoreProgressPanel
            progress={progress}
            onCancel={() => handleCancel()}
            showDetails={true}
          />
        ) : (
          <div style={{ textAlign: 'center', padding: '40px' }}>
            <LoadingOutlined style={{ fontSize: '48px', marginBottom: '16px' }} />
            <Title level={4}>Starting Restoration...</Title>
            <Text type="secondary">
              Please wait while we prepare the restoration process.
            </Text>
          </div>
        );

      default:
        return null;
    }
  };

  const getModalTitle = () => {
    const stepTitles = [
      'Configure Restoration',
      'Preview Changes',
      'Confirm Restoration',
      'Restoration in Progress',
    ];
    return stepTitles[currentStep] || 'Version Restoration';
  };

  const getModalWidth = () => {
    switch (currentStep) {
      case 1:
      case 2:
        return 900;
      case 3:
        return 700;
      default:
        return 600;
    }
  };

  return (
    <Modal
      title={getModalTitle()}
      visible={visible}
      onCancel={handleCancel}
      width={getModalWidth()}
      footer={null}
      destroyOnClose
      maskClosable={false}
    >
      <div style={{ marginBottom: '24px' }}>
        <Steps current={currentStep} size="small">
          {wizardSteps.map((step, index) => (
            <Step
              key={index}
              title={step.title}
              description={step.description}
              icon={step.icon}
            />
          ))}
        </Steps>
      </div>

      {error && (
        <Alert
          type="error"
          message="Error"
          description={error}
          showIcon
          closable
          onClose={() => setError(null)}
          style={{ marginBottom: '16px' }}
        />
      )}

      <div style={{ minHeight: '400px' }}>
        {renderStepContent()}
      </div>

      {currentStep < 3 && (
        <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '24px' }}>
          <Button
            onClick={handlePrevious}
            disabled={!canGoPrevious()}
          >
            Previous
          </Button>

          <div>
            <Button
              onClick={handleCancel}
              style={{ marginRight: '8px' }}
            >
              Cancel
            </Button>
            <Button
              type="primary"
              onClick={handleNext}
              disabled={!canGoNext()}
              loading={loading}
            >
              {currentStep === 2 ? 'Start Restoration' : 'Next'}
            </Button>
          </div>
        </div>
      )}
    </Modal>
  );
};

import React, { useState } from 'react';
import { 
  Card, 
  Progress, 
  Typography, 
  Space, 
  Button, 
  Statistic,
  Row,
  Col,
  Alert,
  Tag,
  List,
  Collapse,
  Tooltip,
  Modal,
} from 'antd';
import {
  LoadingOutlined,
  CheckCircleOutlined,
  CloseCircleOutlined,
  WarningOutlined,
  StopOutlined,
  InfoCircleOutlined,
  ClockCircleOutlined,
  EditOutlined,
  ExclamationCircleOutlined,
} from '@ant-design/icons';
import { 
  RestorationProgressResponse,
  RestorationStatus,
} from '../../types/restoration';

const { Title, Text } = Typography;
const { Panel } = Collapse;

interface RestoreProgressPanelProps {
  progress: RestorationProgressResponse;
  onCancel: () => void;
  showDetails?: boolean;
}

export const RestoreProgressPanel: React.FC<RestoreProgressPanelProps> = ({
  progress,
  onCancel,
  showDetails = false,
}) => {
  const [showCancelModal, setShowCancelModal] = useState(false);
  const [detailsVisible, setDetailsVisible] = useState(showDetails);

  const getStatusIcon = (status: RestorationStatus) => {
    switch (status) {
      case 'pending':
        return <ClockCircleOutlined style={{ color: '#fa8c16' }} />;
      case 'in_progress':
        return <LoadingOutlined style={{ color: '#1890ff' }} />;
      case 'completed':
        return <CheckCircleOutlined style={{ color: '#52c41a' }} />;
      case 'failed':
        return <CloseCircleOutlined style={{ color: '#ff4d4f' }} />;
      case 'cancelled':
        return <StopOutlined style={{ color: '#d9d9d9' }} />;
      default:
        return <InfoCircleOutlined />;
    }
  };

  const getStatusColor = (status: RestorationStatus) => {
    switch (status) {
      case 'pending':
        return 'warning';
      case 'in_progress':
        return 'processing';
      case 'completed':
        return 'success';
      case 'failed':
        return 'error';
      case 'cancelled':
        return 'default';
      default:
        return 'default';
    }
  };

  const getProgressStatus = () => {
    switch (progress.status) {
      case 'completed':
        return 'success';
      case 'failed':
        return 'exception';
      case 'cancelled':
        return 'exception';
      default:
        return 'active';
    }
  };

  const formatTime = (milliseconds: number) => {
    if (milliseconds < 1000) {
      return `${milliseconds}ms`;
    }
    const seconds = Math.floor(milliseconds / 1000);
    if (seconds < 60) {
      return `${seconds}s`;
    }
    const minutes = Math.floor(seconds / 60);
    return `${minutes}m ${seconds % 60}s`;
  };

  const handleCancelConfirm = () => {
    setShowCancelModal(false);
    onCancel();
  };

  const isInProgress = progress.status === 'in_progress' || progress.status === 'pending';
  const isCompleted = progress.status === 'completed';
  const isFailed = progress.status === 'failed';
  const isCancelled = progress.status === 'cancelled';

  return (
    <div>
      {/* Status Header */}
      <Card style={{ marginBottom: '16px' }}>
        <Row align="middle" justify="space-between">
          <Col>
            <Space size="large">
              <Space>
                {getStatusIcon(progress.status)}
                <Title level={4} style={{ margin: 0 }}>
                  {progress.status.replace('_', ' ').toUpperCase()}
                </Title>
              </Space>
              <Tag color={getStatusColor(progress.status) as any} size="large">
                {progress.status.replace('_', ' ').toUpperCase()}
              </Tag>
            </Space>
          </Col>
          <Col>
            {isInProgress && (
              <Button 
                danger 
                icon={<StopOutlined />}
                onClick={() => setShowCancelModal(true)}
              >
                Cancel Restoration
              </Button>
            )}
          </Col>
        </Row>
      </Card>

      {/* Progress Bar */}
      <Card title="Progress" style={{ marginBottom: '16px' }}>
        <Progress
          percent={progress.progressPercentage}
          status={getProgressStatus()}
          strokeWidth={12}
          showInfo={true}
          format={(percent) => `${percent}%`}
        />

        {progress.currentOperation && (
          <div style={{ marginTop: '8px' }}>
            <Text type="secondary">Current operation: </Text>
            <Text code>{progress.currentOperation}</Text>
          </div>
        )}

        {progress.estimatedTimeRemaining && progress.estimatedTimeRemaining > 0 && (
          <div style={{ marginTop: '8px' }}>
            <Text type="secondary">Estimated time remaining: </Text>
            <Text strong>{formatTime(progress.estimatedTimeRemaining)}</Text>
          </div>
        )}
      </Card>

      {/* Statistics */}
      <Row gutter={16} style={{ marginBottom: '16px' }}>
        <Col span={6}>
          <Card>
            <Statistic
              title="Operations"
              value={progress.operationsCompleted}
              suffix={`/ ${progress.totalOperations}`}
              prefix={<EditOutlined />}
            />
          </Card>
        </Col>
        <Col span={6}>
          <Card>
            <Statistic
              title="Conflicts"
              value={progress.conflictsResolved}
              suffix={`/ ${progress.totalConflicts}`}
              prefix={<WarningOutlined />}
              valueStyle={{ 
                color: progress.totalConflicts > 0 ? '#fa8c16' : '#3f8600' 
              }}
            />
          </Card>
        </Col>
        <Col span={6}>
          <Card>
            <Statistic
              title="Progress"
              value={progress.progressPercentage}
              suffix="%"
              prefix={<LoadingOutlined />}
            />
          </Card>
        </Col>
        <Col span={6}>
          <Card>
            <Statistic
              title="Status"
              value={progress.status.replace('_', ' ').toUpperCase()}
              prefix={getStatusIcon(progress.status)}
            />
          </Card>
        </Col>
      </Row>

      {/* Error Message */}
      {isFailed && progress.errorMessage && (
        <Alert
          type="error"
          message="Restoration Failed"
          description={progress.errorMessage}
          showIcon
          style={{ marginBottom: '16px' }}
        />
      )}

      {/* Success Message */}
      {isCompleted && (
        <Alert
          type="success"
          message="Restoration Completed Successfully"
          description="The version restoration has been completed successfully. All changes have been applied to your project."
          showIcon
          style={{ marginBottom: '16px' }}
        />
      )}

      {/* Cancellation Message */}
      {isCancelled && (
        <Alert
          type="info"
          message="Restoration Cancelled"
          description="The restoration operation has been cancelled. Your project remains in its previous state."
          showIcon
          style={{ marginBottom: '16px' }}
        />
      )}

      {/* Details */}
      {detailsVisible && (
        <Card 
          title="Details" 
          extra={
            <Button 
              type="link" 
              onClick={() => setDetailsVisible(!detailsVisible)}
            >
              {detailsVisible ? 'Hide' : 'Show'} Details
            </Button>
          }
        >
          <Collapse>
            <Panel header="Operation Progress" key="operations">
              <List
                size="small"
                dataSource={[
                  { label: 'Total Operations', value: progress.totalOperations },
                  { label: 'Completed Operations', value: progress.operationsCompleted },
                  { label: 'Remaining Operations', value: progress.totalOperations - progress.operationsCompleted },
                  { label: 'Success Rate', value: `${Math.round((progress.operationsCompleted / progress.totalOperations) * 100)}%` },
                ]}
                renderItem={(item) => (
                  <List.Item>
                    <Space>
                      <Text type="secondary">{item.label}:</Text>
                      <Text strong>{item.value}</Text>
                    </Space>
                  </List.Item>
                )}
              />
            </Panel>

            <Panel header="Conflict Resolution" key="conflicts">
              <List
                size="small"
                dataSource={[
                  { label: 'Total Conflicts', value: progress.totalConflicts },
                  { label: 'Resolved Conflicts', value: progress.conflictsResolved },
                  { label: 'Remaining Conflicts', value: progress.totalConflicts - progress.conflictsResolved },
                  { label: 'Resolution Rate', value: progress.totalConflicts > 0 ? `${Math.round((progress.conflictsResolved / progress.totalConflicts) * 100)}%` : 'N/A' },
                ]}
                renderItem={(item) => (
                  <List.Item>
                    <Space>
                      <Text type="secondary">{item.label}:</Text>
                      <Text strong>{item.value}</Text>
                    </Space>
                  </List.Item>
                )}
              />
            </Panel>

            <Panel header="System Information" key="system">
              <List
                size="small"
                dataSource={[
                  { label: 'Restoration ID', value: progress.restorationAttemptId },
                  { label: 'Status', value: progress.status },
                  { label: 'Current Operation', value: progress.currentOperation || 'N/A' },
                  { label: 'Estimated Time Remaining', value: progress.estimatedTimeRemaining ? formatTime(progress.estimatedTimeRemaining) : 'N/A' },
                ]}
                renderItem={(item) => (
                  <List.Item>
                    <Space>
                      <Text type="secondary">{item.label}:</Text>
                      <Text code style={{ fontSize: '12px' }}>{item.value}</Text>
                    </Space>
                  </List.Item>
                )}
              />
            </Panel>
          </Collapse>
        </Card>
      )}

      {/* Cancel Confirmation Modal */}
      <Modal
        title="Cancel Restoration"
        visible={showCancelModal}
        onOk={handleCancelConfirm}
        onCancel={() => setShowCancelModal(false)}
        okText="Yes, Cancel"
        cancelText="No, Continue"
        okButtonProps={{ danger: true }}
      >
        <Space direction="vertical" size="middle" style={{ width: '100%' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            <ExclamationCircleOutlined style={{ color: '#fa8c16', fontSize: '20px' }} />
            <Text strong>Are you sure you want to cancel this restoration?</Text>
          </div>

          <Text type="secondary">
            Cancelling the restoration will stop the process and leave your project in its current state. 
            Any changes that have already been applied will remain.
          </Text>

          <div style={{ background: '#f5f5f5', padding: '12px', borderRadius: '4px' }}>
            <Text type="secondary">
              Progress: {progress.progressPercentage}% complete ({progress.operationsCompleted}/{progress.totalOperations} operations)
            </Text>
          </div>
        </Space>
      </Modal>
    </div>
  );
};

/**
 * Epic 9.2.6 - Template Creation Wizard
 * Multi-step wizard for creating new project templates from existing graphs
 */

import React, { useState, useEffect } from 'react';
import { ProjectTemplate, TemplateVariable, CustomizationPoint, TemplateCategory, ProjectTemplateManager } from '../../templates/ProjectTemplateManager';

interface TemplateCreationWizardProps {
  graphData: any; // The current graph to turn into a template
  isOpen: boolean;
  onClose: () => void;
  onComplete: (template: ProjectTemplate) => void;
  templateManager: ProjectTemplateManager;
}

type WizardStep = 'basic' | 'variables' | 'customization' | 'preview' | 'publish';

export const TemplateCreationWizard: React.FC<TemplateCreationWizardProps> = ({
  graphData,
  isOpen,
  onClose,
  onComplete,
  templateManager
}) => {
  const [currentStep, setCurrentStep] = useState<WizardStep>('basic');
  const [templateData, setTemplateData] = useState<Partial<ProjectTemplate>>({
    name: '',
    description: '',
    category: '',
    tags: [],
    version: '1.0.0',
    complexity_level: 'beginner',
    estimated_time: 30,
    prerequisites: [],
    learning_objectives: [],
    is_public: false,
    is_featured: false,
    variables: [],
    customization_points: [],
    graph_data: graphData
  });
  const [categories, setCategories] = useState<TemplateCategory[]>([]);
  const [errors, setErrors] = useState<Record<string, string>>({});

  useEffect(() => {
    if (isOpen) {
      loadCategories();
      setTemplateData(prev => ({ ...prev, graph_data: graphData }));
    }
  }, [isOpen, graphData]);

  const loadCategories = async () => {
    try {
      const cats = templateManager.getCategories();
      setCategories(cats);
    } catch (error) {
      console.error('Failed to load categories:', error);
    }
  };

  const steps: { key: WizardStep; title: string; description: string }[] = [
    { key: 'basic', title: 'Basic Information', description: 'Template name, description, and category' },
    { key: 'variables', title: 'Variables', description: 'Define configurable variables' },
    { key: 'customization', title: 'Customization', description: 'Set up customization points' },
    { key: 'preview', title: 'Preview', description: 'Review your template' },
    { key: 'publish', title: 'Publish', description: 'Publish your template' }
  ];

  const currentStepIndex = steps.findIndex(step => step.key === currentStep);

  const validateCurrentStep = (): boolean => {
    const newErrors: Record<string, string> = {};

    switch (currentStep) {
      case 'basic':
        if (!templateData.name?.trim()) {
          newErrors.name = 'Template name is required';
        }
        if (!templateData.description?.trim()) {
          newErrors.description = 'Description is required';
        }
        if (!templateData.category) {
          newErrors.category = 'Category is required';
        }
        if (!templateData.estimated_time || templateData.estimated_time <= 0) {
          newErrors.estimated_time = 'Estimated time must be greater than 0';
        }
        break;
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const nextStep = () => {
    if (validateCurrentStep()) {
      const nextIndex = Math.min(currentStepIndex + 1, steps.length - 1);
      setCurrentStep(steps[nextIndex].key);
    }
  };

  const prevStep = () => {
    const prevIndex = Math.max(currentStepIndex - 1, 0);
    setCurrentStep(steps[prevIndex].key);
  };

  const handleComplete = async () => {
    try {
      const template = await templateManager.createTemplate(templateData as any);
      onComplete(template);
      onClose();
    } catch (error) {
      console.error('Failed to create template:', error);
      setErrors({ publish: 'Failed to create template. Please try again.' });
    }
  };

  const updateTemplateData = (updates: Partial<ProjectTemplate>) => {
    setTemplateData(prev => ({ ...prev, ...updates }));
    // Clear related errors
    const newErrors = { ...errors };
    Object.keys(updates).forEach(key => {
      delete newErrors[key];
    });
    setErrors(newErrors);
  };

  const addVariable = () => {
    const newVariable: TemplateVariable = {
      id: crypto.randomUUID(),
      name: '',
      label: '',
      type: 'text',
      description: '',
      default_value: '',
      required: false
    };

    setTemplateData(prev => ({
      ...prev,
      variables: [...(prev.variables || []), newVariable]
    }));
  };

  const updateVariable = (index: number, updates: Partial<TemplateVariable>) => {
    setTemplateData(prev => ({
      ...prev,
      variables: prev.variables?.map((variable, i) => 
        i === index ? { ...variable, ...updates } : variable
      ) || []
    }));
  };

  const removeVariable = (index: number) => {
    setTemplateData(prev => ({
      ...prev,
      variables: prev.variables?.filter((_, i) => i !== index) || []
    }));
  };

  const addCustomizationPoint = () => {
    const newPoint: CustomizationPoint = {
      id: crypto.randomUUID(),
      name: '',
      type: 'node_properties',
      target_nodes: [],
      properties: [],
      description: '',
      ui_component: 'input'
    };

    setTemplateData(prev => ({
      ...prev,
      customization_points: [...(prev.customization_points || []), newPoint]
    }));
  };

  const updateCustomizationPoint = (index: number, updates: Partial<CustomizationPoint>) => {
    setTemplateData(prev => ({
      ...prev,
      customization_points: prev.customization_points?.map((point, i) => 
        i === index ? { ...point, ...updates } : point
      ) || []
    }));
  };

  const removeCustomizationPoint = (index: number) => {
    setTemplateData(prev => ({
      ...prev,
      customization_points: prev.customization_points?.filter((_, i) => i !== index) || []
    }));
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-lg shadow-xl max-w-6xl w-full max-h-[90vh] overflow-hidden">
        {/* Header */}
        <div className="border-b border-gray-200 px-6 py-4">
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-xl font-semibold text-gray-900">Create Template</h2>
              <p className="text-sm text-gray-600 mt-1">
                Step {currentStepIndex + 1} of {steps.length}: {steps[currentStepIndex].title}
              </p>
            </div>
            <button
              onClick={onClose}
              className="text-gray-400 hover:text-gray-500 transition-colors"
            >
              <svg className="h-6 w-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>
        </div>

        {/* Progress Bar */}
        <div className="bg-gray-50 px-6 py-3">
          <div className="flex items-center space-x-4">
            {steps.map((step, index) => (
              <div
                key={step.key}
                className={`flex items-center ${index < steps.length - 1 ? 'flex-1' : ''}`}
              >
                <div className={`flex items-center justify-center w-8 h-8 rounded-full text-sm font-medium ${
                  index <= currentStepIndex 
                    ? 'bg-blue-500 text-white' 
                    : 'bg-gray-200 text-gray-500'
                }`}>
                  {index < currentStepIndex ? '✓' : index + 1}
                </div>
                <span className={`ml-2 text-sm ${
                  index <= currentStepIndex ? 'text-gray-900' : 'text-gray-500'
                }`}>
                  {step.title}
                </span>
                {index < steps.length - 1 && (
                  <div className={`flex-1 h-0.5 mx-4 ${
                    index < currentStepIndex ? 'bg-blue-500' : 'bg-gray-200'
                  }`} />
                )}
              </div>
            ))}
          </div>
        </div>

        {/* Content */}
        <div className="px-6 py-6 overflow-y-auto max-h-[60vh]">
          {currentStep === 'basic' && (
            <BasicInfoStep
              data={templateData}
              categories={categories}
              errors={errors}
              onChange={updateTemplateData}
            />
          )}

          {currentStep === 'variables' && (
            <VariablesStep
              variables={templateData.variables || []}
              onAdd={addVariable}
              onUpdate={updateVariable}
              onRemove={removeVariable}
            />
          )}

          {currentStep === 'customization' && (
            <CustomizationStep
              points={templateData.customization_points || []}
              graphData={graphData}
              onAdd={addCustomizationPoint}
              onUpdate={updateCustomizationPoint}
              onRemove={removeCustomizationPoint}
            />
          )}

          {currentStep === 'preview' && (
            <PreviewStep template={templateData as ProjectTemplate} />
          )}

          {currentStep === 'publish' && (
            <PublishStep
              data={templateData}
              errors={errors}
              onChange={updateTemplateData}
            />
          )}
        </div>

        {/* Footer */}
        <div className="border-t border-gray-200 px-6 py-4 flex justify-between">
          <button
            onClick={prevStep}
            disabled={currentStepIndex === 0}
            className="px-4 py-2 text-sm border border-gray-300 rounded-md hover:bg-gray-50 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            Previous
          </button>

          <div className="flex space-x-3">
            <button
              onClick={onClose}
              className="px-4 py-2 text-sm border border-gray-300 rounded-md hover:bg-gray-50 transition-colors"
            >
              Cancel
            </button>

            {currentStepIndex < steps.length - 1 ? (
              <button
                onClick={nextStep}
                className="px-4 py-2 text-sm bg-blue-500 text-white rounded-md hover:bg-blue-600 transition-colors"
              >
                Next
              </button>
            ) : (
              <button
                onClick={handleComplete}
                className="px-4 py-2 text-sm bg-green-500 text-white rounded-md hover:bg-green-600 transition-colors"
              >
                Create Template
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

// Step Components

interface BasicInfoStepProps {
  data: Partial<ProjectTemplate>;
  categories: TemplateCategory[];
  errors: Record<string, string>;
  onChange: (updates: Partial<ProjectTemplate>) => void;
}

const BasicInfoStep: React.FC<BasicInfoStepProps> = ({ data, categories, errors, onChange }) => {
  const [newTag, setNewTag] = useState('');

  const addTag = () => {
    if (newTag.trim() && !data.tags?.includes(newTag.trim())) {
      onChange({ tags: [...(data.tags || []), newTag.trim()] });
      setNewTag('');
    }
  };

  const removeTag = (tag: string) => {
    onChange({ tags: data.tags?.filter(t => t !== tag) || [] });
  };

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Template Name *
          </label>
          <input
            type="text"
            value={data.name || ''}
            onChange={(e) => onChange({ name: e.target.value })}
            placeholder="Enter template name"
            className={`w-full px-3 py-2 border rounded-md focus:ring-2 focus:ring-blue-500 focus:border-transparent ${
              errors.name ? 'border-red-300' : 'border-gray-300'
            }`}
          />
          {errors.name && <p className="text-sm text-red-600 mt-1">{errors.name}</p>}
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Category *
          </label>
          <select
            value={data.category || ''}
            onChange={(e) => onChange({ category: e.target.value })}
            className={`w-full px-3 py-2 border rounded-md focus:ring-2 focus:ring-blue-500 focus:border-transparent ${
              errors.category ? 'border-red-300' : 'border-gray-300'
            }`}
          >
            <option value="">Select a category</option>
            {categories.map(category => (
              <option key={category.id} value={category.id}>{category.name}</option>
            ))}
          </select>
          {errors.category && <p className="text-sm text-red-600 mt-1">{errors.category}</p>}
        </div>
      </div>

      <div>
        <label className="block text-sm font-medium text-gray-700 mb-2">
          Description *
        </label>
        <textarea
          value={data.description || ''}
          onChange={(e) => onChange({ description: e.target.value })}
          placeholder="Describe what this template does and when to use it"
          rows={3}
          className={`w-full px-3 py-2 border rounded-md focus:ring-2 focus:ring-blue-500 focus:border-transparent ${
            errors.description ? 'border-red-300' : 'border-gray-300'
          }`}
        />
        {errors.description && <p className="text-sm text-red-600 mt-1">{errors.description}</p>}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Complexity Level
          </label>
          <select
            value={data.complexity_level || 'beginner'}
            onChange={(e) => onChange({ complexity_level: e.target.value as any })}
            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          >
            <option value="beginner">Beginner</option>
            <option value="intermediate">Intermediate</option>
            <option value="advanced">Advanced</option>
          </select>
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Estimated Time (minutes) *
          </label>
          <input
            type="number"
            value={data.estimated_time || ''}
            onChange={(e) => onChange({ estimated_time: parseInt(e.target.value) || 0 })}
            placeholder="30"
            min="1"
            className={`w-full px-3 py-2 border rounded-md focus:ring-2 focus:ring-blue-500 focus:border-transparent ${
              errors.estimated_time ? 'border-red-300' : 'border-gray-300'
            }`}
          />
          {errors.estimated_time && <p className="text-sm text-red-600 mt-1">{errors.estimated_time}</p>}
        </div>
      </div>

      <div>
        <label className="block text-sm font-medium text-gray-700 mb-2">
          Tags
        </label>
        <div className="flex items-center space-x-2 mb-2">
          <input
            type="text"
            value={newTag}
            onChange={(e) => setNewTag(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && addTag()}
            placeholder="Add a tag"
            className="flex-1 px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          />
          <button
            type="button"
            onClick={addTag}
            className="px-3 py-2 bg-blue-500 text-white rounded-md hover:bg-blue-600 transition-colors"
          >
            Add
          </button>
        </div>
        <div className="flex flex-wrap gap-2">
          {data.tags?.map(tag => (
            <span
              key={tag}
              className="inline-flex items-center px-2 py-1 bg-blue-100 text-blue-800 text-sm rounded-md"
            >
              {tag}
              <button
                type="button"
                onClick={() => removeTag(tag)}
                className="ml-1 text-blue-600 hover:text-blue-800"
              >
                ×
              </button>
            </span>
          ))}
        </div>
      </div>
    </div>
  );
};

interface VariablesStepProps {
  variables: TemplateVariable[];
  onAdd: () => void;
  onUpdate: (index: number, updates: Partial<TemplateVariable>) => void;
  onRemove: (index: number) => void;
}

const VariablesStep: React.FC<VariablesStepProps> = ({ variables, onAdd, onUpdate, onRemove }) => {
  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-lg font-medium text-gray-900">Template Variables</h3>
          <p className="text-sm text-gray-600">
            Define variables that users can customize when using this template.
          </p>
        </div>
        <button
          onClick={onAdd}
          className="px-4 py-2 bg-blue-500 text-white rounded-md hover:bg-blue-600 transition-colors"
        >
          Add Variable
        </button>
      </div>

      {variables.length === 0 ? (
        <div className="text-center py-8 text-gray-500">
          No variables defined. Click "Add Variable" to create configurable elements.
        </div>
      ) : (
        <div className="space-y-4">
          {variables.map((variable, index) => (
            <div key={variable.id} className="border border-gray-200 rounded-lg p-4">
              <div className="flex items-start justify-between mb-4">
                <h4 className="font-medium text-gray-900">Variable {index + 1}</h4>
                <button
                  onClick={() => onRemove(index)}
                  className="text-red-500 hover:text-red-700 transition-colors"
                >
                  Remove
                </button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Name
                  </label>
                  <input
                    type="text"
                    value={variable.name}
                    onChange={(e) => onUpdate(index, { name: e.target.value })}
                    placeholder="variable_name"
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Label
                  </label>
                  <input
                    type="text"
                    value={variable.label}
                    onChange={(e) => onUpdate(index, { label: e.target.value })}
                    placeholder="Display Label"
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Type
                  </label>
                  <select
