 */

import React, { useState } from 'react';

interface InviteUserModalProps {
  workspaceId: string;
  workspaceName: string;
  onSubmit: (data: { userId: string; role: string }) => void;
  onCancel: () => void;
}

const ROLES = [
  { value: 'admin', label: 'Admin', description: 'Full workspace access and management' },
  { value: 'editor', label: 'Editor', description: 'Can create and edit projects and resources' },
  { value: 'commenter', label: 'Commenter', description: 'Can view content and add comments' },
  { value: 'viewer', label: 'Viewer', description: 'Read-only access to content' },
];

export const InviteUserModal: React.FC<InviteUserModalProps> = ({
  workspaceId,
  workspaceName,
  onSubmit,
  onCancel,
}) => {
  const [formData, setFormData] = useState({
    userId: '',
    role: 'editor',
  });
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  const validateForm = () => {
    const newErrors: Record<string, string> = {};

    if (!formData.userId.trim()) {
      newErrors.userId = 'User ID or email is required';
    } else if (formData.userId.length < 3) {
      newErrors.userId = 'User ID must be at least 3 characters';
    }

    if (!formData.role) {
      newErrors.role = 'Role selection is required';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    setIsSubmitting(true);
    try {
      await onSubmit({
        userId: formData.userId.trim(),
        role: formData.role,
      });
    } catch (error) {
      console.error('Failed to invite user:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleChange = (field: string, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    // Clear error when user starts typing
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: '' }));
    }
  };

  const selectedRole = ROLES.find(role => role.value === formData.role);

  return (
    <div className="modal-overlay">
      <div className="modal modal--medium">
        <div className="modal__header">
          <h2>Invite User to Workspace</h2>
          <button
            className="modal__close"
            onClick={onCancel}
            type="button"
          >
            ×
          </button>
        </div>

        <form onSubmit={handleSubmit} className="modal__content">
          <div className="invite-modal__workspace-info">
            <h3>Inviting to: {workspaceName}</h3>
            <p>The user will receive a notification and can start collaborating immediately.</p>
          </div>

          <div className="form-group">
            <label htmlFor="user-id" className="form-label">
              User ID or Email *
            </label>
            <input
              id="user-id"
              type="text"
              value={formData.userId}
              onChange={(e) => handleChange('userId', e.target.value)}
              className={`form-input ${errors.userId ? 'form-input--error' : ''}`}
              placeholder="Enter user ID or email address"
              disabled={isSubmitting}
            />
            {errors.userId && (
              <div className="form-error">{errors.userId}</div>
            )}
            <div className="form-hint">
              Enter the user's ID or email address to send them an invitation
            </div>
          </div>

          <div className="form-group">
            <label className="form-label">
              Role *
            </label>
            <div className="role-selection">
              {ROLES.map(role => (
                <label
                  key={role.value}
                  className={`role-option ${formData.role === role.value ? 'role-option--selected' : ''}`}
                >
                  <input
                    type="radio"
                    name="role"
                    value={role.value}
                    checked={formData.role === role.value}
                    onChange={(e) => handleChange('role', e.target.value)}
                    disabled={isSubmitting}
                  />
                  <div className="role-option__content">
                    <div className="role-option__name">{role.label}</div>
                    <div className="role-option__description">{role.description}</div>
                  </div>
                </label>
              ))}
            </div>
            {errors.role && (
              <div className="form-error">{errors.role}</div>
            )}
          </div>

          {selectedRole && (
            <div className="invite-preview">
              <h3>Permission Summary</h3>
              <div className="permission-summary">
                <div className="permission-summary__role">
                  <strong>{selectedRole.label}</strong>
                </div>
                <div className="permission-summary__description">
                  {selectedRole.description}
                </div>
                <div className="permission-summary__details">
                  <h4>This role will be able to:</h4>
                  <ul>
                    {formData.role === 'admin' && (
                      <>
                        <li>Manage workspace settings and members</li>
                        <li>Create, edit, and delete projects</li>
                        <li>Invite and remove users</li>
                        <li>Access all workspace content</li>
                      </>
                    )}
                    {formData.role === 'editor' && (
                      <>
                        <li>Create and edit projects and resources</li>
                        <li>Comment on content</li>
                        <li>View workspace activity</li>
                      </>
                    )}
                    {formData.role === 'commenter' && (
                      <>
                        <li>View all workspace content</li>
                        <li>Add comments and discussions</li>
                        <li>View workspace activity</li>
                      </>
                    )}
                    {formData.role === 'viewer' && (
                      <>
                        <li>View all workspace content</li>
                        <li>View workspace activity</li>
                      </>
                    )}
                  </ul>
                </div>
              </div>
            </div>
          )}
        </form>

        <div className="modal__footer">
          <button
            type="button"
            className="btn btn--secondary"
            onClick={onCancel}
            disabled={isSubmitting}
          >
            Cancel
          </button>
          <button
            type="submit"
            className="btn btn--primary"
            onClick={handleSubmit}
            disabled={isSubmitting || !formData.userId.trim()}
          >
            {isSubmitting ? 'Sending Invitation...' : 'Send Invitation'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default InviteUserModal;

/**
 * Epic 9.2.1 - Workspace List Component
 * Displays list of user's workspaces with search and filtering
 */

import React, { useState, useMemo } from 'react';
import { WorkspaceWithMembership } from '../../types/workspace';

interface WorkspaceListProps {
  workspaces: WorkspaceWithMembership[];
  selectedWorkspace: WorkspaceWithMembership | null;
  onWorkspaceSelect: (workspace: WorkspaceWithMembership) => void;
  loading?: boolean;
}

export const WorkspaceList: React.FC<WorkspaceListProps> = ({
  workspaces,
  selectedWorkspace,
  onWorkspaceSelect,
  loading = false,
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterBy, setFilterBy] = useState<'all' | 'owner' | 'member'>('all');

  const filteredWorkspaces = useMemo(() => {
    let filtered = workspaces;

    // Apply search filter
    if (searchTerm) {
      filtered = filtered.filter(workspace =>
        workspace.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        workspace.description?.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    // Apply role filter
    if (filterBy !== 'all') {
      filtered = filtered.filter(workspace => {
        if (filterBy === 'owner') {
          return workspace.owner_id === workspace.membership?.user_id;
        } else if (filterBy === 'member') {
          return workspace.owner_id !== workspace.membership?.user_id;
        }
        return true;
      });
    }

    // Sort by name
    return filtered.sort((a, b) => a.name.localeCompare(b.name));
  }, [workspaces, searchTerm, filterBy]);

  if (loading) {
    return (
      <div className="workspace-list workspace-list--loading">
        <div className="workspace-list__header">
          <h3>Loading workspaces...</h3>
        </div>
        <div className="workspace-list__skeleton">
          {[1, 2, 3].map(i => (
            <div key={i} className="workspace-item workspace-item--skeleton">
              <div className="workspace-item__avatar"></div>
              <div className="workspace-item__content">
                <div className="workspace-item__name"></div>
                <div className="workspace-item__description"></div>
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="workspace-list">
      <div className="workspace-list__header">
        <h3>Your Workspaces ({workspaces.length})</h3>

        <div className="workspace-list__search">
          <input
            type="text"
            placeholder="Search workspaces..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="search-input"
          />
        </div>

        <div className="workspace-list__filters">
          <select
            value={filterBy}
            onChange={(e) => setFilterBy(e.target.value as any)}
            className="filter-select"
          >
            <option value="all">All workspaces</option>
            <option value="owner">Owned by me</option>
            <option value="member">Member of</option>
          </select>
        </div>
      </div>

      <div className="workspace-list__items">
        {filteredWorkspaces.length === 0 ? (
          <div className="workspace-list__empty">
            {searchTerm || filterBy !== 'all' ? (
              <p>No workspaces match your filters.</p>
            ) : (
              <p>You don't have any workspaces yet. Create one to get started!</p>
            )}
          </div>
        ) : (
          filteredWorkspaces.map(workspace => (
            <WorkspaceItem
              key={workspace.id}
              workspace={workspace}
              isSelected={selectedWorkspace?.id === workspace.id}
              onSelect={() => onWorkspaceSelect(workspace)}
            />
          ))
        )}
      </div>
    </div>
  );
};

interface WorkspaceItemProps {
  workspace: WorkspaceWithMembership;
  isSelected: boolean;
  onSelect: () => void;
}

const WorkspaceItem: React.FC<WorkspaceItemProps> = ({
  workspace,
  isSelected,
  onSelect,
}) => {
  const isOwner = workspace.owner_id === workspace.membership?.user_id;
  const memberCount = 1; // TODO: Get actual member count from API

  return (
    <div
      className={`workspace-item ${isSelected ? 'workspace-item--selected' : ''}`}
      onClick={onSelect}
    >
      <div className="workspace-item__avatar">
        {workspace.name.charAt(0).toUpperCase()}
      </div>

      <div className="workspace-item__content">
        <div className="workspace-item__header">
          <h4 className="workspace-item__name">{workspace.name}</h4>
          <div className="workspace-item__badges">
            {isOwner && (
              <span className="badge badge--owner">Owner</span>
            )}
          </div>
        </div>

        {workspace.description && (
          <p className="workspace-item__description">
            {workspace.description.length > 60
              ? `${workspace.description.substring(0, 60)}...`
              : workspace.description
            }
          </p>
        )}

        <div className="workspace-item__meta">
          <span className="workspace-item__members">
            {memberCount} member{memberCount !== 1 ? 's' : ''}
          </span>
          <span className="workspace-item__activity">
            Updated {new Date(workspace.updated_at).toLocaleDateString()}
          </span>
        </div>
      </div>
    </div>
  );
};

export default WorkspaceList;

/**
 * Epic 9.2.1 - Workspace Manager Component
 * Main workspace management interface
 */

import React, { useState, useEffect } from 'react';
import { WorkspaceList } from './WorkspaceList';
import { CreateWorkspaceModal } from './CreateWorkspaceModal';
import { InviteUserModal } from './InviteUserModal';
import { WorkspaceSettings } from './WorkspaceSettings';
import { useWorkspaces } from '../../hooks/useWorkspaces';
import { Workspace, WorkspaceWithMembership } from '../../types/workspace';

interface WorkspaceManagerProps {
  userId: string;
  onWorkspaceSelect?: (workspace: Workspace) => void;
}

export const WorkspaceManager: React.FC<WorkspaceManagerProps> = ({
  userId,
  onWorkspaceSelect,
}) => {
  const [selectedWorkspace, setSelectedWorkspace] = useState<WorkspaceWithMembership | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showInviteModal, setShowInviteModal] = useState(false);
  const [showSettings, setShowSettings] = useState(false);

  const {
    workspaces,
    loading,
    error,
    createWorkspace,
    updateWorkspace,
    archiveWorkspace,
    inviteUser,
    refreshWorkspaces,
  } = useWorkspaces(userId);

  const handleWorkspaceSelect = (workspace: WorkspaceWithMembership) => {
    setSelectedWorkspace(workspace);
    onWorkspaceSelect?.(workspace);
  };

  const handleCreateWorkspace = async (data: { name: string; description?: string }) => {
    try {
      const newWorkspace = await createWorkspace(data);
      setSelectedWorkspace(newWorkspace);
      setShowCreateModal(false);
      onWorkspaceSelect?.(newWorkspace);
    } catch (error) {
      console.error('Failed to create workspace:', error);
    }
  };

  const handleInviteUser = async (data: { userId: string; role: string }) => {
    if (!selectedWorkspace) return;

    try {
      await inviteUser(selectedWorkspace.id, data.userId, data.role);
      setShowInviteModal(false);
      // Optionally refresh or show success message
    } catch (error) {
      console.error('Failed to invite user:', error);
    }
  };

  const handleWorkspaceUpdate = async (updates: { name?: string; description?: string }) => {
    if (!selectedWorkspace) return;

    try {
      const updatedWorkspace = await updateWorkspace(selectedWorkspace.id, updates);
      setSelectedWorkspace(updatedWorkspace);
      setShowSettings(false);
    } catch (error) {
      console.error('Failed to update workspace:', error);
    }
  };

  const handleWorkspaceArchive = async () => {
    if (!selectedWorkspace) return;

    try {
      await archiveWorkspace(selectedWorkspace.id);
      setSelectedWorkspace(null);
      setShowSettings(false);
      refreshWorkspaces();
    } catch (error) {
      console.error('Failed to archive workspace:', error);
    }
  };

  const canManageWorkspace = selectedWorkspace?.role_permissions && 
    (selectedWorkspace.role_permissions & (1 << 2)) !== 0; // WORKSPACE_ADMIN

  const canInviteUsers = selectedWorkspace?.role_permissions && 
    (selectedWorkspace.role_permissions & (1 << 15)) !== 0; // USER_INVITE

  return (
    <div className="workspace-manager">
      <div className="workspace-manager__header">
        <h2>Workspaces</h2>
        <button
          className="btn btn--primary"
          onClick={() => setShowCreateModal(true)}
        >
          Create Workspace
        </button>
      </div>

      {error && (
        <div className="alert alert--error">
          <p>Error loading workspaces: {error}</p>
          <button onClick={refreshWorkspaces}>Retry</button>
        </div>
      )}

      <div className="workspace-manager__content">
        <div className="workspace-manager__sidebar">
          <WorkspaceList
            workspaces={workspaces}
            selectedWorkspace={selectedWorkspace}
            onWorkspaceSelect={handleWorkspaceSelect}
            loading={loading}
          />
        </div>

        <div className="workspace-manager__main">
          {selectedWorkspace ? (
            <div className="workspace-detail">
              <div className="workspace-detail__header">
                <div className="workspace-detail__info">
                  <h3>{selectedWorkspace.name}</h3>
                  {selectedWorkspace.description && (
                    <p className="workspace-detail__description">
                      {selectedWorkspace.description}
                    </p>
                  )}
                </div>

                <div className="workspace-detail__actions">
                  {canInviteUsers && (
                    <button
                      className="btn btn--secondary"
                      onClick={() => setShowInviteModal(true)}
                    >
                      Invite Users
                    </button>
                  )}

                  {canManageWorkspace && (
                    <button
                      className="btn btn--secondary"
                      onClick={() => setShowSettings(true)}
                    >
                      Settings
                    </button>
                  )}
                </div>
              </div>

              <div className="workspace-detail__stats">
                <div className="stat">
                  <span className="stat__label">Role</span>
                  <span className="stat__value">
                    {selectedWorkspace.owner_id === userId ? 'Owner' : 'Member'}
                  </span>
                </div>

                <div className="stat">
                  <span className="stat__label">Joined</span>
                  <span className="stat__value">
                    {selectedWorkspace.membership?.joined_at 
                      ? new Date(selectedWorkspace.membership.joined_at).toLocaleDateString()
                      : 'N/A'
                    }
                  </span>
                </div>
              </div>
            </div>
          ) : (
            <div className="workspace-detail--empty">
              <h3>Select a workspace</h3>
              <p>Choose a workspace from the list to view details and manage projects.</p>
            </div>
          )}
        </div>
      </div>

      {/* Modals */}
      {showCreateModal && (
        <CreateWorkspaceModal
          onSubmit={handleCreateWorkspace}
          onCancel={() => setShowCreateModal(false)}
        />
      )}

      {showInviteModal && selectedWorkspace && (
        <InviteUserModal
          workspaceId={selectedWorkspace.id}
          workspaceName={selectedWorkspace.name}
          onSubmit={handleInviteUser}
          onCancel={() => setShowInviteModal(false)}
        />
      )}

      {showSettings && selectedWorkspace && (
        <WorkspaceSettings
          workspace={selectedWorkspace}
          onUpdate={handleWorkspaceUpdate}
          onArchive={handleWorkspaceArchive}
          onCancel={() => setShowSettings(false)}
          canArchive={canManageWorkspace}
        />
      )}
    </div>
  );
};

export default WorkspaceManager;

/**
 * Epic 9.2.1 - Workspace Settings Component
 * Settings modal for workspace configuration
 */

import React, { useState } from 'react';
import { WorkspaceWithMembership } from '../../types/workspace';

interface WorkspaceSettingsProps {
  workspace: WorkspaceWithMembership;
  onUpdate: (updates: { name?: string; description?: string }) => void;
  onArchive: () => void;
  onCancel: () => void;
  canArchive: boolean;
}

export const WorkspaceSettings: React.FC<WorkspaceSettingsProps> = ({
  workspace,
  onUpdate,
  onArchive,
  onCancel,
  canArchive,
}) => {
  const [activeTab, setActiveTab] = useState<'general' | 'members' | 'danger'>('general');
  const [formData, setFormData] = useState({
    name: workspace.name,
    description: workspace.description || '',
  });
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showArchiveConfirm, setShowArchiveConfirm] = useState(false);

  const validateForm = () => {
    const newErrors: Record<string, string> = {};

    if (!formData.name.trim()) {
      newErrors.name = 'Workspace name is required';
    } else if (formData.name.length < 3) {
      newErrors.name = 'Workspace name must be at least 3 characters';
    } else if (formData.name.length > 50) {
      newErrors.name = 'Workspace name must be less than 50 characters';
    }

    if (formData.description && formData.description.length > 200) {
      newErrors.description = 'Description must be less than 200 characters';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    // Check if there are any changes
    const hasChanges = 
      formData.name !== workspace.name ||
      formData.description !== (workspace.description || '');

    if (!hasChanges) {
      onCancel();
      return;
    }

    setIsSubmitting(true);
    try {
      await onUpdate({
        name: formData.name.trim(),
        description: formData.description.trim() || undefined,
      });
    } catch (error) {
      console.error('Failed to update workspace:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleChange = (field: string, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    // Clear error when user starts typing
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: '' }));
    }
  };

  const handleArchive = async () => {
    setIsSubmitting(true);
    try {
      await onArchive();
    } catch (error) {
      console.error('Failed to archive workspace:', error);
    } finally {
      setIsSubmitting(false);
      setShowArchiveConfirm(false);
    }
  };

  return (
    <div className="modal-overlay">
      <div className="modal modal--large">
        <div className="modal__header">
          <h2>Workspace Settings</h2>
          <button
            className="modal__close"
            onClick={onCancel}
            type="button"
          >
            ×
          </button>
        </div>

        <div className="modal__content">
          <div className="settings-tabs">
            <button
              className={`settings-tab ${activeTab === 'general' ? 'settings-tab--active' : ''}`}
              onClick={() => setActiveTab('general')}
            >
              General
            </button>
            <button
              className={`settings-tab ${activeTab === 'members' ? 'settings-tab--active' : ''}`}
              onClick={() => setActiveTab('members')}
            >
              Members
            </button>
            {canArchive && (
              <button
                className={`settings-tab ${activeTab === 'danger' ? 'settings-tab--active' : ''}`}
                onClick={() => setActiveTab('danger')}
              >
                Danger Zone
              </button>
            )}
          </div>

          <div className="settings-content">
            {activeTab === 'general' && (
              <form onSubmit={handleSubmit} className="settings-form">
                <div className="form-group">
                  <label htmlFor="workspace-name" className="form-label">
                    Workspace Name *
                  </label>
                  <input
                    id="workspace-name"
                    type="text"
                    value={formData.name}
                    onChange={(e) => handleChange('name', e.target.value)}
                    className={`form-input ${errors.name ? 'form-input--error' : ''}`}
                    placeholder="Enter workspace name"
                    maxLength={50}
                    disabled={isSubmitting}
                  />
                  {errors.name && (
                    <div className="form-error">{errors.name}</div>
                  )}
                </div>

                <div className="form-group">
                  <label htmlFor="workspace-description" className="form-label">
                    Description (Optional)
                  </label>
                  <textarea
                    id="workspace-description"
                    value={formData.description}
                    onChange={(e) => handleChange('description', e.target.value)}
                    className={`form-textarea ${errors.description ? 'form-textarea--error' : ''}`}
                    placeholder="Describe what this workspace is for..."
                    rows={3}
                    maxLength={200}
                    disabled={isSubmitting}
                  />
                  {errors.description && (
                    <div className="form-error">{errors.description}</div>
                  )}
                  <div className="form-hint">
                    {formData.description.length}/200 characters
                  </div>
                </div>

                <div className="workspace-info">
                  <h3>Workspace Information</h3>
                  <div className="info-grid">
                    <div className="info-item">
                      <label>Created</label>
                      <span>{new Date(workspace.created_at).toLocaleDateString()}</span>
                    </div>
                    <div className="info-item">
                      <label>Last Updated</label>
                      <span>{new Date(workspace.updated_at).toLocaleDateString()}</span>
                    </div>
                    <div className="info-item">
                      <label>Owner</label>
                      <span>{workspace.owner_id}</span>
                    </div>
                  </div>
                </div>
              </form>
            )}

            {activeTab === 'members' && (
              <div className="members-tab">
                <div className="members-header">
                  <h3>Workspace Members</h3>
                  <p>Manage who has access to this workspace and their permissions.</p>
                </div>

                <div className="members-list">
                  <div className="member-item">
                    <div className="member-avatar">
                      {workspace.owner_id.charAt(0).toUpperCase()}
                    </div>
                    <div className="member-info">
                      <div className="member-name">{workspace.owner_id}</div>
                      <div className="member-role">Owner</div>
                    </div>
                    <div className="member-actions">
                      <span className="badge badge--owner">Owner</span>
                    </div>
                  </div>

                  {/* TODO: Add actual member list from API */}
                  <div className="members-empty">
                    <p>No other members yet. Use the "Invite Users" button to add collaborators.</p>
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'danger' && canArchive && (
              <div className="danger-tab">
                <div className="danger-section">
                  <h3>Archive Workspace</h3>
                  <p>
                    Archiving this workspace will make it read-only and hide it from the main workspace list.
                    All projects and data will be preserved but no new content can be created.
                  </p>

                  {!showArchiveConfirm ? (
                    <button
                      type="button"
                      className="btn btn--danger"
                      onClick={() => setShowArchiveConfirm(true)}
                      disabled={isSubmitting}
                    >
                      Archive Workspace
                    </button>
                  ) : (
                    <div className="confirm-action">
                      <p><strong>Are you sure you want to archive "{workspace.name}"?</strong></p>
                      <p>This action cannot be easily undone.</p>
                      <div className="confirm-actions">
                        <button
                          type="button"
                          className="btn btn--secondary"
                          onClick={() => setShowArchiveConfirm(false)}
                          disabled={isSubmitting}
                        >
                          Cancel
                        </button>
                        <button
                          type="button"
                          className="btn btn--danger"
                          onClick={handleArchive}
                          disabled={isSubmitting}
                        >
                          {isSubmitting ? 'Archiving...' : 'Yes, Archive Workspace'}
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="modal__footer">
          <button
            type="button"
            className="btn btn--secondary"
            onClick={onCancel}
            disabled={isSubmitting}
          >
            Cancel
          </button>
          {activeTab === 'general' && (
            <button
              type="submit"
              className="btn btn--primary"
              onClick={handleSubmit}
              disabled={isSubmitting}
            >
              {isSubmitting ? 'Saving...' : 'Save Changes'}
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default WorkspaceSettings;

