  constraints: z.object({
    performance: z.object({
      maxExecutionTime: z.number().optional(),
      maxMemoryUsage: z.number().optional()
    }).optional(),
    security: z.object({
      permissions: z.array(z.string()).optional(),
      sandboxed: z.boolean().optional()
