      Object.entries(graph.categories).forEach(([category, nodes]) => {
        if (nodes.length > 0) {
          dot += `    subgraph cluster_${category} {\n`;
          dot += `        label="${category.toUpperCase()}";\n`;
          dot += `        style=filled;\n`;
          dot += `        color=lightgrey;\n`;

