  setEdges: (edges) => set({ edges }),
  addNode: (node) => set((state) => ({ nodes: [...state.nodes, node] })),
  addEdge: (edge) => set((state) => ({ edges: [...state.edges, edge] })),
  updateNode: (nodeId, partial) =>
    set((state) => ({
      nodes: state.nodes.map((n) =>
        n.id === nodeId ? { ...n, data: { ...n.data, ...partial } } : n
      ),
    })),

  addVariation: (nodeId, variation) =>
    set((state) => ({
      nodes: state.nodes.map((n) =>
        n.id === nodeId
          ? { ...n, data: addVariationToNode(n.data as NodeData, variation) }
          : n
      ),
    })),

  removeVariation: (nodeId, variationIndex) =>
    set((state) => ({
      nodes: state.nodes.map((n) =>
        n.id === nodeId
          ? { ...n, data: removeVariationFromNode(n.data as NodeData, variationIndex) }
          : n
      ),
    })),

  updateVariation: (nodeId, variationIndex, newValue) =>
    set((state) => ({
      nodes: state.nodes.map((n) =>
        n.id === nodeId
          ? { ...n, data: updateVariationInNode(n.data as NodeData, variationIndex, newValue) }
          : n
      ),
    })),

  reorderVariations: (nodeId, fromIndex, toIndex) =>
    set((state) => ({
      nodes: state.nodes.map((n) =>
        n.id === nodeId
          ? { ...n, data: reorderVariationsInNode(n.data as NodeData, fromIndex, toIndex) }
          : n
      ),
    })),

  duplicateNode: (nodeId) =>
    set((state) => {
      const nodeToClone = state.nodes.find((n) => n.id === nodeId);
      if (!nodeToClone) return state;

      const newNode = {
        ...nodeToClone,
        id: `${nodeToClone.id}-copy-${Date.now()}`,
        position: {
          x: nodeToClone.position.x + 100,
          y: nodeToClone.position.y + 100,
        },
        data: {
          ...nodeToClone.data,
          label: `${nodeToClone.data.label} (Copy)`,
        },
      };

      return { nodes: [...state.nodes, newNode] };
    }),

  deleteNode: (nodeId) =>
    set((state) => ({
      nodes: state.nodes.filter((n) => n.id !== nodeId),
      edges: state.edges.filter((e) => e.source !== nodeId && e.target !== nodeId),
    })),
}));

/**
 * Epic 9.2.3 - useActivityFeed Hook
 * React hook for activity feed management
 */

import { useState, useEffect, useCallback } from 'react';
import { 
  ActivityEventWithActorInfo, 
  ActivityEventFilter, 
  PaginatedResponse 
} from '../types/workspace';

const API_BASE = process.env.REACT_APP_API_BASE || 'http://localhost:8000/api';

interface UseActivityFeedOptions {
  limit?: number;
  autoRefresh?: boolean;
  refreshInterval?: number;
}

interface ActivityStatsData {
  total_events: number;
  events_by_type: Record<string, number>;
  events_by_day: Array<{ date: string; count: number }>;
  most_active_users: Array<{ user_id: string; count: number }>;
}

export function useActivityFeed(
  workspaceId: string,
  userId: string,
  filters: ActivityEventFilter = {},
  options: UseActivityFeedOptions = {}
) {
  const { limit = 20, autoRefresh = false, refreshInterval = 30000 } = options;

  const [activities, setActivities] = useState<ActivityEventWithActorInfo[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [hasMore, setHasMore] = useState(false);
  const [page, setPage] = useState(1);
  const [stats, setStats] = useState<ActivityStatsData | null>(null);
  const [eventTypes, setEventTypes] = useState<string[]>([]);

  // Build query string from filters
  const buildQueryString = useCallback((filters: ActivityEventFilter, page: number) => {
    const params = new URLSearchParams({
      page: page.toString(),
      limit: limit.toString(),
    });

    if (filters.project_id) params.append('project_id', filters.project_id);
    if (filters.actor_id) params.append('actor_id', filters.actor_id);
    if (filters.event_types?.length) params.append('event_types', filters.event_types.join(','));
    if (filters.from_date) params.append('from_date', filters.from_date.toISOString());
    if (filters.to_date) params.append('to_date', filters.to_date.toISOString());

    return params.toString();
  }, [limit]);

  // Fetch activity feed
  const fetchActivities = useCallback(async (
    filters: ActivityEventFilter,
    page: number = 1,
    append: boolean = false
  ) => {
    try {
      if (!append) {
        setLoading(true);
      } else {
        setLoadingMore(true);
      }
      setError(null);

      const queryString = buildQueryString(filters, page);
      const response = await fetch(`${API_BASE}/workspaces/${workspaceId}/activity?${queryString}`, {
        headers: {
          'Content-Type': 'application/json',
          'X-User-Id': userId,
        },
      });

      if (!response.ok) {
        throw new Error(`Failed to fetch activity: ${response.statusText}`);
      }

      const data: PaginatedResponse<ActivityEventWithActorInfo> = await response.json();

      if (append) {
        setActivities(prev => [...prev, ...data.data]);
      } else {
        setActivities(data.data);
      }

      setHasMore(data.pagination.has_next);
      setPage(page);
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Unknown error occurred';
      setError(errorMessage);
      console.error('Failed to fetch activities:', err);
    } finally {
      setLoading(false);
      setLoadingMore(false);
    }
  }, [workspaceId, userId, buildQueryString]);

  // Fetch activity statistics
  const fetchStats = useCallback(async () => {
    try {
      const response = await fetch(`${API_BASE}/workspaces/${workspaceId}/activity/stats`, {
        headers: {
          'Content-Type': 'application/json',
          'X-User-Id': userId,
        },
      });

      if (!response.ok) {
        throw new Error(`Failed to fetch stats: ${response.statusText}`);
      }

      const statsData: ActivityStatsData = await response.json();
      setStats(statsData);
    } catch (err) {
      console.error('Failed to fetch activity stats:', err);
    }
  }, [workspaceId, userId]);

  // Fetch event types
  const fetchEventTypes = useCallback(async () => {
    try {
      const response = await fetch(`${API_BASE}/workspaces/${workspaceId}/activity/types`, {
        headers: {
          'Content-Type': 'application/json',
          'X-User-Id': userId,
        },
      });

      if (!response.ok) {
        throw new Error(`Failed to fetch event types: ${response.statusText}`);
      }

      const types: string[] = await response.json();
      setEventTypes(types);
    } catch (err) {
      console.error('Failed to fetch event types:', err);
    }
  }, [workspaceId, userId]);

  // Load more activities (pagination)
  const loadMore = useCallback(() => {
    if (!hasMore || loadingMore) return;
    fetchActivities(filters, page + 1, true);
  }, [filters, page, hasMore, loadingMore, fetchActivities]);

  // Refresh activities (reset to first page)
  const refresh = useCallback(() => {
    setPage(1);
    fetchActivities(filters, 1, false);
  }, [filters, fetchActivities]);

  // Fetch single activity event
  const fetchActivityEvent = useCallback(async (eventId: string): Promise<ActivityEventWithActorInfo | null> => {
    try {
      const response = await fetch(`${API_BASE}/activity/${eventId}`, {
        headers: {
          'Content-Type': 'application/json',
          'X-User-Id': userId,
        },
      });

      if (!response.ok) {
        if (response.status === 404) return null;
        throw new Error(`Failed to fetch activity event: ${response.statusText}`);
      }

      return await response.json();
    } catch (err) {
      console.error('Failed to fetch activity event:', err);
      return null;
    }
  }, [userId]);

  // Initial fetch and setup
  useEffect(() => {
    fetchActivities(filters, 1, false);
    fetchStats();
    fetchEventTypes();
  }, [fetchActivities, fetchStats, fetchEventTypes, filters]);

  // Auto-refresh interval
  useEffect(() => {
    if (!autoRefresh) return;

    const interval = setInterval(() => {
      refresh();
    }, refreshInterval);

    return () => clearInterval(interval);
  }, [autoRefresh, refreshInterval, refresh]);

  // Real-time updates (placeholder for WebSocket integration)
  useEffect(() => {
    // TODO: Integrate with WebSocket for real-time activity updates
    // This would listen for workspace activity events and update the feed accordingly

    const handleVisibilityChange = () => {
      if (!document.hidden && autoRefresh) {
        refresh();
      }
    };

    document.addEventListener('visibilitychange', handleVisibilityChange);
    return () => document.removeEventListener('visibilitychange', handleVisibilityChange);
  }, [autoRefresh, refresh]);

  return {
    activities,
    loading,
    loadingMore,
    error,
    hasMore,
    page,
    stats,
    eventTypes,
    loadMore,
    refresh,
    fetchActivityEvent,
  };
}

// Hook for project-specific activity feed
export function useProjectActivityFeed(
  projectId: string,
  userId: string,
  options: UseActivityFeedOptions = {}
) {
  const { limit = 20, autoRefresh = false, refreshInterval = 30000 } = options;

  const [activities, setActivities] = useState<ActivityEventWithActorInfo[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [hasMore, setHasMore] = useState(false);
  const [page, setPage] = useState(1);

  const fetchProjectActivities = useCallback(async (page: number = 1, append: boolean = false) => {
    try {
      if (!append) {
        setLoading(true);
      } else {
        setLoadingMore(true);
      }
      setError(null);

      const params = new URLSearchParams({
        page: page.toString(),
        limit: limit.toString(),
      });

      const response = await fetch(`${API_BASE}/projects/${projectId}/activity?${params}`, {
        headers: {
          'Content-Type': 'application/json',
          'X-User-Id': userId,
        },
      });

      if (!response.ok) {
        throw new Error(`Failed to fetch project activity: ${response.statusText}`);
      }

      const data: PaginatedResponse<ActivityEventWithActorInfo> = await response.json();

      if (append) {
        setActivities(prev => [...prev, ...data.data]);
      } else {
        setActivities(data.data);
      }

      setHasMore(data.pagination.has_next);
      setPage(page);
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Unknown error occurred';
      setError(errorMessage);
      console.error('Failed to fetch project activities:', err);
    } finally {
      setLoading(false);
      setLoadingMore(false);
    }
  }, [projectId, userId, limit]);

  const loadMore = useCallback(() => {
    if (!hasMore || loadingMore) return;
    fetchProjectActivities(page + 1, true);
  }, [page, hasMore, loadingMore, fetchProjectActivities]);

  const refresh = useCallback(() => {
    setPage(1);
    fetchProjectActivities(1, false);
  }, [fetchProjectActivities]);

  useEffect(() => {
    fetchProjectActivities(1, false);
  }, [fetchProjectActivities]);

  useEffect(() => {
    if (!autoRefresh) return;

    const interval = setInterval(() => {
      refresh();
    }, refreshInterval);

    return () => clearInterval(interval);
  }, [autoRefresh, refreshInterval, refresh]);

  return {
    activities,
    loading,
    loadingMore,
    error,
    hasMore,
    page,
    loadMore,
    refresh,
  };
}

import { useState, useCallback } from 'react';
import { 
  CreateAttributionRequest,
  AttributionFilter,
  AttributionStatsRequest,
  UpdatePrivacySettingsRequest,
  ChangeAttribution,
  AttributionStatsResponse,
  AttributionTimelineResponse,
  ContributorStatsResponse,
  AttributionPrivacySettings,
  AttributionSession,
  AttributionContext,
} from '../types/attribution';

interface UseAttributionReturn {
  // State
  loading: boolean;
  error: string | null;

  // Actions
  recordAttribution: (request: CreateAttributionRequest) => Promise<ChangeAttribution>;
  getAttributionStats: (request: AttributionStatsRequest) => Promise<AttributionStatsResponse>;
  getAttributionTimeline: (projectId: string, filter: AttributionFilter) => Promise<AttributionTimelineResponse>;
  getContributorStats: (projectId: string, dateRange?: { start: Date; end: Date }) => Promise<ContributorStatsResponse>;
  listAttributions: (filter: AttributionFilter) => Promise<ChangeAttribution[]>;
  startSession: (projectId: string, sessionId?: string) => Promise<AttributionSession>;
  endSession: (sessionId: string) => Promise<void>;
  updatePrivacySettings: (request: UpdatePrivacySettingsRequest) => Promise<AttributionPrivacySettings>;
  getPrivacySettings: (projectId: string) => Promise<AttributionPrivacySettings | null>;
  cleanupOldData: (projectId: string) => Promise<void>;
  getResourceAttribution: (projectId: string, resourceType: string, resourceId: string) => Promise<ChangeAttribution[]>;
  getAuthorAttribution: (projectId: string, authorId: string, dateRange?: { start: Date; end: Date }) => Promise<ChangeAttribution[]>;
  recordBatchAttributions: (projectId: string, attributions: any[], batchId?: string) => Promise<ChangeAttribution[]>;

  // Utility
  clearError: () => void;
}

export const useAttribution = (): UseAttributionReturn => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const apiCall = useCallback(async <T>(
    url: string,
    options: RequestInit = {}
  ): Promise<T> => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch(url, {
        ...options,
        headers: {
          'Content-Type': 'application/json',
          ...options.headers,
        },
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error || `HTTP ${response.status}: ${response.statusText}`);
      }

      const data = await response.json();

      if (!data.success) {
        throw new Error(data.error || 'Request failed');
      }

      return data.data;
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'An unknown error occurred';
      setError(errorMessage);
      throw err;
    } finally {
      setLoading(false);
    }
  }, []);

  const recordAttribution = useCallback(async (request: CreateAttributionRequest): Promise<ChangeAttribution> => {
    return apiCall<ChangeAttribution>('/api/attribution/record', {
      method: 'POST',
      body: JSON.stringify(request),
    });
  }, [apiCall]);

  const getAttributionStats = useCallback(async (request: AttributionStatsRequest): Promise<AttributionStatsResponse> => {
    const params = new URLSearchParams();

    if (request.period) params.append('period', request.period);
    if (request.authorId) params.append('authorId', request.authorId);
    if (request.startDate) params.append('startDate', request.startDate.toISOString());
    if (request.endDate) params.append('endDate', request.endDate.toISOString());
    if (request.resourceType) params.append('resourceType', request.resourceType);
    if (request.changeType) params.append('changeType', request.changeType);
    if (request.includeAggregations !== undefined) params.append('includeAggregations', request.includeAggregations.toString());
    if (request.includeTimeline !== undefined) params.append('includeTimeline', request.includeTimeline.toString());
    if (request.includeHeatmap !== undefined) params.append('includeHeatmap', request.includeHeatmap.toString());
    if (request.includeCollaborationMetrics !== undefined) params.append('includeCollaborationMetrics', request.includeCollaborationMetrics.toString());

    return apiCall<AttributionStatsResponse>(`/api/attribution/stats/${request.projectId}?${params.toString()}`);
  }, [apiCall]);

  const getAttributionTimeline = useCallback(async (projectId: string, filter: AttributionFilter): Promise<AttributionTimelineResponse> => {
    const params = new URLSearchParams();

    if (filter.resourceType) params.append('resourceType', filter.resourceType);
    if (filter.resourceId) params.append('resourceId', filter.resourceId);
    if (filter.changeType) params.append('changeType', filter.changeType);
    if (filter.authorId) params.append('authorId', filter.authorId);
    if (filter.authorType) params.append('authorType', filter.authorType);
    if (filter.sessionId) params.append('sessionId', filter.sessionId);
    if (filter.dateFrom) params.append('dateFrom', filter.dateFrom.toISOString());
    if (filter.dateTo) params.append('dateTo', filter.dateTo.toISOString());
    if (filter.limit) params.append('limit', filter.limit.toString());
    if (filter.offset) params.append('offset', filter.offset.toString());

    return apiCall<AttributionTimelineResponse>(`/api/attribution/timeline/${projectId}?${params.toString()}`);
  }, [apiCall]);

  const getContributorStats = useCallback(async (projectId: string, dateRange?: { start: Date; end: Date }): Promise<ContributorStatsResponse> => {
    const params = new URLSearchParams();

    if (dateRange?.start) params.append('startDate', dateRange.start.toISOString());
    if (dateRange?.end) params.append('endDate', dateRange.end.toISOString());

    return apiCall<ContributorStatsResponse>(`/api/attribution/contributors/${projectId}?${params.toString()}`);
  }, [apiCall]);

  const listAttributions = useCallback(async (filter: AttributionFilter): Promise<ChangeAttribution[]> => {
    const params = new URLSearchParams();

    if (filter.projectId) params.append('projectId', filter.projectId);
    if (filter.resourceType) params.append('resourceType', filter.resourceType);
    if (filter.resourceId) params.append('resourceId', filter.resourceId);
    if (filter.changeType) params.append('changeType', filter.changeType);
    if (filter.authorId) params.append('authorId', filter.authorId);
    if (filter.authorType) params.append('authorType', filter.authorType);
    if (filter.sessionId) params.append('sessionId', filter.sessionId);
    if (filter.batchId) params.append('batchId', filter.batchId);
    if (filter.snapshotId) params.append('snapshotId', filter.snapshotId);
    if (filter.dateFrom) params.append('dateFrom', filter.dateFrom.toISOString());
    if (filter.dateTo) params.append('dateTo', filter.dateTo.toISOString());
    if (filter.isCollaborative !== undefined) params.append('isCollaborative', filter.isCollaborative.toString());
    if (filter.minConfidenceScore !== undefined) params.append('minConfidenceScore', filter.minConfidenceScore.toString());
    if (filter.limit) params.append('limit', filter.limit.toString());
    if (filter.offset) params.append('offset', filter.offset.toString());
    if (filter.sortBy) params.append('sortBy', filter.sortBy);
    if (filter.sortOrder) params.append('sortOrder', filter.sortOrder);

    return apiCall<ChangeAttribution[]>(`/api/attribution/list?${params.toString()}`);
  }, [apiCall]);

  const startSession = useCallback(async (projectId: string, sessionId?: string): Promise<AttributionSession> => {
    return apiCall<AttributionSession>('/api/attribution/session/start', {
      method: 'POST',
      body: JSON.stringify({ projectId, sessionId }),
    });
  }, [apiCall]);

  const endSession = useCallback(async (sessionId: string): Promise<void> => {
    return apiCall<void>('/api/attribution/session/end', {
      method: 'POST',
      body: JSON.stringify({ sessionId }),
    });
  }, [apiCall]);

  const updatePrivacySettings = useCallback(async (request: UpdatePrivacySettingsRequest): Promise<AttributionPrivacySettings> => {
    return apiCall<AttributionPrivacySettings>(`/api/attribution/privacy/${request.projectId}`, {
      method: 'PUT',
      body: JSON.stringify(request),
    });
  }, [apiCall]);

  const getPrivacySettings = useCallback(async (projectId: string): Promise<AttributionPrivacySettings | null> => {
    return apiCall<AttributionPrivacySettings | null>(`/api/attribution/privacy/${projectId}`);
  }, [apiCall]);

  const cleanupOldData = useCallback(async (projectId: string): Promise<void> => {
    return apiCall<void>(`/api/attribution/cleanup/${projectId}`, {
      method: 'POST',
    });
  }, [apiCall]);

  const getResourceAttribution = useCallback(async (projectId: string, resourceType: string, resourceId: string): Promise<ChangeAttribution[]> => {
    return apiCall<ChangeAttribution[]>(`/api/attribution/resource/${projectId}/${resourceType}/${resourceId}`);
  }, [apiCall]);

  const getAuthorAttribution = useCallback(async (projectId: string, authorId: string, dateRange?: { start: Date; end: Date }): Promise<ChangeAttribution[]> => {
    const params = new URLSearchParams();

    if (dateRange?.start) params.append('dateFrom', dateRange.start.toISOString());
    if (dateRange?.end) params.append('dateTo', dateRange.end.toISOString());

    return apiCall<ChangeAttribution[]>(`/api/attribution/author/${projectId}/${authorId}?${params.toString()}`);
  }, [apiCall]);

  const recordBatchAttributions = useCallback(async (projectId: string, attributions: any[], batchId?: string): Promise<ChangeAttribution[]> => {
    return apiCall<ChangeAttribution[]>('/api/attribution/batch', {
      method: 'POST',
      body: JSON.stringify({ projectId, attributions, batchId }),
    });
  }, [apiCall]);

  const clearError = useCallback(() => {
    setError(null);
  }, []);

  return {
    loading,
    error,
    recordAttribution,
    getAttributionStats,
    getAttributionTimeline,
    getContributorStats,
    listAttributions,
    startSession,
    endSession,
    updatePrivacySettings,
    getPrivacySettings,
    cleanupOldData,
    getResourceAttribution,
    getAuthorAttribution,
    recordBatchAttributions,
    clearError,
  };
};

import { useEffect, useState } from "react";
export const useAutosave = ({ nodes, edges, intervalMs = 5000, storageKey = 'graphDraft', }) => {
    const [showRestorePrompt, setShowRestorePrompt] = useState(false);
    const [restoreDraft, setRestoreDraft] = useState(null);
    // Check for existing draft on mount
    useEffect(() => {
        try {
            const saved = localStorage.getItem(storageKey);
            if (saved) {
                const draft = JSON.parse(saved);
                if (draft && draft.nodes && draft.edges) {
                    setRestoreDraft(draft);
                    setShowRestorePrompt(true);
                }
            }
        }
        catch (error) {
            console.warn('Failed to parse saved draft:', error);
            localStorage.removeItem(storageKey);
        }
    }, [storageKey]);
    // Autosave graph every intervalMs
    useEffect(() => {
        const save = () => {
            try {
                const draft = JSON.stringify({ nodes, edges });
                localStorage.setItem(storageKey, draft);
            }
            catch (error) {
                console.warn('Failed to save draft:', error);
            }
        };
        const interval = setInterval(save, intervalMs);
        return () => clearInterval(interval);
    }, [nodes, edges, intervalMs, storageKey]);
    // Clear localStorage on mount to prevent infinite loops (emergency fix)
    useEffect(() => {
        console.log('Clearing localStorage to prevent infinite loops');
        localStorage.removeItem(storageKey);
        localStorage.clear();
    }, [storageKey]);
    return {
        showRestorePrompt,
        restoreDraft,
        setShowRestorePrompt,
        setRestoreDraft,
    };
};

