  MergeBranchRequest,
  SyncBranchRequest,
  BranchFilter,
  MergeRequestFilter,
} from '../types/branching';

interface UseBranchingReturn {
  // State
  loading: boolean;
  error: string | null;

  // Branch operations
  createBranch: (request: CreateBranchRequest) => Promise<ProjectBranch>;
  updateBranch: (branchId: string, request: UpdateBranchRequest) => Promise<ProjectBranch>;
  deleteBranch: (branchId: string) => Promise<void>;
  getBranchById: (branchId: string) => Promise<ProjectBranch>;
  listBranches: (filter: BranchFilter) => Promise<ProjectBranch[]>;

  // Commit operations
  createCommit: (request: CreateCommitRequest) => Promise<BranchCommit>;
  getBranchCommits: (branchId: string, limit?: number, offset?: number) => Promise<BranchCommit[]>;

  // Merge request operations
  createMergeRequest: (request: CreateMergeRequestRequest) => Promise<BranchMergeRequest>;
  updateMergeRequest: (mergeRequestId: string, request: UpdateMergeRequestRequest) => Promise<BranchMergeRequest>;
  getMergeRequestById: (mergeRequestId: string) => Promise<BranchMergeRequest>;
  listMergeRequests: (filter: MergeRequestFilter) => Promise<BranchMergeRequest[]>;
  closeMergeRequest: (mergeRequestId: string) => Promise<BranchMergeRequest>;
  mergeBranch: (request: MergeBranchRequest) => Promise<BranchMergeRequest>;

  // Review operations
  createReview: (request: CreateReviewRequest) => Promise<BranchMergeReview>;
  updateReview: (reviewId: string, request: UpdateReviewRequest) => Promise<BranchMergeReview>;
  getMergeRequestReviews: (mergeRequestId: string) => Promise<BranchMergeReview[]>;

  // Analytics and insights
  getBranchStats: (projectId: string) => Promise<BranchStatsResponse>;
  getBranchTimeline: (projectId: string, dateRange?: { start: Date; end: Date }) => Promise<BranchTimelineResponse>;
  getBranchHierarchy: (projectId: string) => Promise<BranchHierarchy[]>;
  compareBranches: (sourceBranchId: string, targetBranchId: string) => Promise<BranchComparisonResponse>;

  // Synchronization
  syncBranch: (request: SyncBranchRequest) => Promise<void>;

  // Utility
  clearError: () => void;
}

export const useBranching = (): UseBranchingReturn => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const apiCall = useCallback(async <T>(
    url: string,
    options: RequestInit = {}
  ): Promise<T> => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch(url, {
        ...options,
        headers: {
          'Content-Type': 'application/json',
          ...options.headers,
        },
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error || `HTTP ${response.status}: ${response.statusText}`);
      }

      const data = await response.json();

      if (!data.success) {
        throw new Error(data.error || 'Request failed');
      }

      return data.data;
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'An unknown error occurred';
      setError(errorMessage);
      throw err;
    } finally {
      setLoading(false);
    }
  }, []);

  // Branch operations
  const createBranch = useCallback(async (request: CreateBranchRequest): Promise<ProjectBranch> => {
    return apiCall<ProjectBranch>('/api/branches', {
      method: 'POST',
      body: JSON.stringify(request),
    });
  }, [apiCall]);

  const updateBranch = useCallback(async (branchId: string, request: UpdateBranchRequest): Promise<ProjectBranch> => {
    return apiCall<ProjectBranch>(`/api/branches/${branchId}`, {
      method: 'PUT',
      body: JSON.stringify(request),
    });
  }, [apiCall]);

  const deleteBranch = useCallback(async (branchId: string): Promise<void> => {
    return apiCall<void>(`/api/branches/${branchId}`, {
      method: 'DELETE',
    });
  }, [apiCall]);

  const getBranchById = useCallback(async (branchId: string): Promise<ProjectBranch> => {
    return apiCall<ProjectBranch>(`/api/branches/${branchId}`);
  }, [apiCall]);

  const listBranches = useCallback(async (filter: BranchFilter): Promise<ProjectBranch[]> => {
    const params = new URLSearchParams();

    if (filter.projectId) params.append('projectId', filter.projectId);
    if (filter.branchType) params.append('branchType', filter.branchType);
    if (filter.status) params.append('status', filter.status);
    if (filter.protectionLevel) params.append('protectionLevel', filter.protectionLevel);
    if (filter.createdBy) params.append('createdBy', filter.createdBy);
    if (filter.parentBranchId) params.append('parentBranchId', filter.parentBranchId);
    if (filter.namePattern) params.append('namePattern', filter.namePattern);
    if (filter.createdAfter) params.append('createdAfter', filter.createdAfter.toISOString());
    if (filter.createdBefore) params.append('createdBefore', filter.createdBefore.toISOString());
    if (filter.limit) params.append('limit', filter.limit.toString());
    if (filter.offset) params.append('offset', filter.offset.toString());
    if (filter.sortBy) params.append('sortBy', filter.sortBy);
    if (filter.sortOrder) params.append('sortOrder', filter.sortOrder);

    return apiCall<ProjectBranch[]>(`/api/branches?${params.toString()}`);
  }, [apiCall]);

  // Commit operations
  const createCommit = useCallback(async (request: CreateCommitRequest): Promise<BranchCommit> => {
    return apiCall<BranchCommit>(`/api/branches/${request.branchId}/commits`, {
      method: 'POST',
      body: JSON.stringify({
        snapshotId: request.snapshotId,
        commitMessage: request.commitMessage,
        parentCommitIds: request.parentCommitIds,
        commitMetadata: request.commitMetadata,
      }),
    });
  }, [apiCall]);

  const getBranchCommits = useCallback(async (branchId: string, limit = 20, offset = 0): Promise<BranchCommit[]> => {
    const params = new URLSearchParams();
    params.append('limit', limit.toString());
    params.append('offset', offset.toString());

    return apiCall<BranchCommit[]>(`/api/branches/${branchId}/commits?${params.toString()}`);
  }, [apiCall]);

  // Merge request operations
  const createMergeRequest = useCallback(async (request: CreateMergeRequestRequest): Promise<BranchMergeRequest> => {
    return apiCall<BranchMergeRequest>('/api/merge-requests', {
      method: 'POST',
      body: JSON.stringify(request),
    });
  }, [apiCall]);

  const updateMergeRequest = useCallback(async (mergeRequestId: string, request: UpdateMergeRequestRequest): Promise<BranchMergeRequest> => {
    return apiCall<BranchMergeRequest>(`/api/merge-requests/${mergeRequestId}`, {
      method: 'PUT',
      body: JSON.stringify(request),
    });
  }, [apiCall]);

  const getMergeRequestById = useCallback(async (mergeRequestId: string): Promise<BranchMergeRequest> => {
    return apiCall<BranchMergeRequest>(`/api/merge-requests/${mergeRequestId}`);
  }, [apiCall]);

  const listMergeRequests = useCallback(async (filter: MergeRequestFilter): Promise<BranchMergeRequest[]> => {
    const params = new URLSearchParams();

    if (filter.projectId) params.append('projectId', filter.projectId);
    if (filter.sourceBranchId) params.append('sourceBranchId', filter.sourceBranchId);
    if (filter.targetBranchId) params.append('targetBranchId', filter.targetBranchId);
    if (filter.status) params.append('status', filter.status);
    if (filter.createdBy) params.append('createdBy', filter.createdBy);
    if (filter.assignedTo) params.append('assignedTo', filter.assignedTo);
    if (filter.reviewerId) params.append('reviewerId', filter.reviewerId);
    if (filter.createdAfter) params.append('createdAfter', filter.createdAfter.toISOString());
    if (filter.createdBefore) params.append('createdBefore', filter.createdBefore.toISOString());
    if (filter.limit) params.append('limit', filter.limit.toString());
    if (filter.offset) params.append('offset', filter.offset.toString());
    if (filter.sortBy) params.append('sortBy', filter.sortBy);
    if (filter.sortOrder) params.append('sortOrder', filter.sortOrder);

    return apiCall<BranchMergeRequest[]>(`/api/merge-requests?${params.toString()}`);
  }, [apiCall]);

  const closeMergeRequest = useCallback(async (mergeRequestId: string): Promise<BranchMergeRequest> => {
    return apiCall<BranchMergeRequest>(`/api/merge-requests/${mergeRequestId}/close`, {
      method: 'POST',
    });
  }, [apiCall]);

  const mergeBranch = useCallback(async (request: MergeBranchRequest): Promise<BranchMergeRequest> => {
    return apiCall<BranchMergeRequest>(`/api/merge-requests/${request.mergeRequestId}/merge`, {
      method: 'POST',
      body: JSON.stringify({
        mergeStrategy: request.mergeStrategy,
        commitMessage: request.commitMessage,
        deleteSourceBranch: request.deleteSourceBranch,
      }),
    });
  }, [apiCall]);

  // Review operations
  const createReview = useCallback(async (request: CreateReviewRequest): Promise<BranchMergeReview> => {
    return apiCall<BranchMergeReview>(`/api/merge-requests/${request.mergeRequestId}/reviews`, {
      method: 'POST',
      body: JSON.stringify({
        status: request.status,
        reviewMessage: request.reviewMessage,
      }),
    });
  }, [apiCall]);

  const updateReview = useCallback(async (reviewId: string, request: UpdateReviewRequest): Promise<BranchMergeReview> => {
    // Would implement update review endpoint
    throw new Error('Update review not implemented yet');
  }, [apiCall]);

  const getMergeRequestReviews = useCallback(async (mergeRequestId: string): Promise<BranchMergeReview[]> => {
    return apiCall<BranchMergeReview[]>(`/api/merge-requests/${mergeRequestId}/reviews`);
  }, [apiCall]);

  // Analytics and insights
  const getBranchStats = useCallback(async (projectId: string): Promise<BranchStatsResponse> => {
    return apiCall<BranchStatsResponse>(`/api/branches/stats/${projectId}`);
  }, [apiCall]);

  const getBranchTimeline = useCallback(async (projectId: string, dateRange?: { start: Date; end: Date }): Promise<BranchTimelineResponse> => {
    const params = new URLSearchParams();

    if (dateRange?.start) params.append('startDate', dateRange.start.toISOString());
    if (dateRange?.end) params.append('endDate', dateRange.end.toISOString());

    return apiCall<BranchTimelineResponse>(`/api/branches/timeline/${projectId}?${params.toString()}`);
  }, [apiCall]);

  const getBranchHierarchy = useCallback(async (projectId: string): Promise<BranchHierarchy[]> => {
    return apiCall<BranchHierarchy[]>(`/api/branches/hierarchy/${projectId}`);
  }, [apiCall]);

  const compareBranches = useCallback(async (sourceBranchId: string, targetBranchId: string): Promise<BranchComparisonResponse> => {
    return apiCall<BranchComparisonResponse>(`/api/branches/${sourceBranchId}/compare/${targetBranchId}`);
  }, [apiCall]);

  // Synchronization
  const syncBranch = useCallback(async (request: SyncBranchRequest): Promise<void> => {
    return apiCall<void>(`/api/branches/${request.branchId}/sync`, {
      method: 'POST',
      body: JSON.stringify(request),
    });
  }, [apiCall]);

  const clearError = useCallback(() => {
    setError(null);
  }, []);

  return {
    loading,
    error,
    createBranch,
    updateBranch,
    deleteBranch,
    getBranchById,
    listBranches,
    createCommit,
    getBranchCommits,
    createMergeRequest,
    updateMergeRequest,
    getMergeRequestById,
    listMergeRequests,
    closeMergeRequest,
    mergeBranch,
    createReview,
    updateReview,
    getMergeRequestReviews,
    getBranchStats,
    getBranchTimeline,
    getBranchHierarchy,
    compareBranches,
    syncBranch,
    clearError,
  };
};

/**
 * Epic 9.2.4 - useCommentReplies Hook
 * Hook for managing replies to a specific comment
 */

import { useState, useEffect, useCallback } from 'react';
import { Comment, PaginatedResponse } from '../types/workspace';

const API_BASE = process.env.REACT_APP_API_BASE || 'http://localhost:8000/api';

interface UseCommentRepliesOptions {
  commentId: string;
  userId: string;
  limit?: number;
  sortOrder?: 'asc' | 'desc';
  enabled?: boolean;
  autoRefresh?: boolean;
  refreshInterval?: number;
}

export function useCommentReplies(options: UseCommentRepliesOptions) {
  const { 
    commentId, 
    userId, 
    limit = 10, 
    sortOrder = 'asc',
    enabled = true,
    autoRefresh = false,
    refreshInterval = 30000 
  } = options;

  const [replies, setReplies] = useState<Comment[]>([]);
  const [loading, setLoading] = useState(false);
  const [loadingMore, setLoadingMore] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [hasMore, setHasMore] = useState(false);
  const [page, setPage] = useState(1);

  // Fetch replies from API
  const fetchReplies = useCallback(async (pageNum: number = 1, append: boolean = false) => {
    if (!enabled) return;

    try {
      if (!append) {
        setLoading(true);
      } else {
        setLoadingMore(true);
      }
      setError(null);

      const params = new URLSearchParams({
        page: pageNum.toString(),
        limit: limit.toString(),
        sort_order: sortOrder,
      });

      const response = await fetch(`${API_BASE}/comments/${commentId}/replies?${params}`, {
        headers: {
          'Content-Type': 'application/json',
          'X-User-Id': userId,
        },
      });

      if (!response.ok) {
        throw new Error(`Failed to fetch replies: ${response.statusText}`);
      }

      const data: PaginatedResponse<Comment> = await response.json();

      if (append) {
        setReplies(prev => [...prev, ...data.data]);
      } else {
        setReplies(data.data);
      }

      setHasMore(data.pagination.has_next);
      setPage(pageNum);
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Unknown error occurred';
      setError(errorMessage);
      console.error('Failed to fetch replies:', err);
    } finally {
      setLoading(false);
      setLoadingMore(false);
    }
  }, [commentId, userId, limit, sortOrder, enabled]);

  // Load more replies (pagination)
  const loadMore = useCallback(() => {
    if (!hasMore || loadingMore || !enabled) return;
    fetchReplies(page + 1, true);
  }, [fetchReplies, page, hasMore, loadingMore, enabled]);

  // Refresh replies (reset to first page)
  const refresh = useCallback(() => {
    if (!enabled) return;
    setPage(1);
    fetchReplies(1, false);
  }, [fetchReplies, enabled]);

  // Add a new reply to the list (called when a reply is created)
  const addReply = useCallback((newReply: Comment) => {
    setReplies(prev => {
      if (sortOrder === 'desc') {
        return [newReply, ...prev];
      } else {
        return [...prev, newReply];
      }
    });
  }, [sortOrder]);

  // Update a reply in the list
  const updateReply = useCallback((replyId: string, updatedReply: Comment) => {
    setReplies(prev => prev.map(reply => 
      reply.id === replyId ? updatedReply : reply
    ));
  }, []);

  // Remove a reply from the list
  const removeReply = useCallback((replyId: string) => {
    setReplies(prev => prev.filter(reply => reply.id !== replyId));
  }, []);

  // Initial fetch when enabled
  useEffect(() => {
    if (enabled) {
      fetchReplies(1, false);
    } else {
      // Clear replies when disabled
      setReplies([]);
      setPage(1);
      setHasMore(false);
      setError(null);
    }
  }, [enabled, fetchReplies]);

  // Auto-refresh interval
  useEffect(() => {
    if (!autoRefresh || !enabled) return;

    const interval = setInterval(() => {
      refresh();
    }, refreshInterval);

    return () => clearInterval(interval);
  }, [autoRefresh, enabled, refreshInterval, refresh]);

  // Handle sort order changes
  useEffect(() => {
    if (replies.length > 0 && enabled) {
      refresh();
    }
  }, [sortOrder]); // Only refresh when sort order changes

  return {
    replies,
    loading,
    loadingMore,
    error,
    hasMore,
    page,
    loadMore,
    refresh,
    addReply,
    updateReply,
    removeReply,
  };
}

/**
 * Epic 9.2.4 - useComments Hook
 * Hook for managing comments in a workspace target
 */

import { useState, useEffect, useCallback } from 'react';
import { Comment, CreateComment, UpdateComment, PaginatedResponse } from '../types/workspace';

const API_BASE = process.env.REACT_APP_API_BASE || 'http://localhost:8000/api';

interface UseCommentsOptions {
  workspaceId: string;
  targetType: string;
  targetId: string;
  userId: string;
  limit?: number;
  sortOrder?: 'asc' | 'desc';
  autoRefresh?: boolean;
  refreshInterval?: number;
}

export function useComments(options: UseCommentsOptions) {
  const { 
    workspaceId, 
    targetType, 
    targetId, 
    userId, 
    limit = 20, 
    sortOrder = 'desc',
    autoRefresh = false,
    refreshInterval = 30000 
  } = options;

  const [comments, setComments] = useState<Comment[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [hasMore, setHasMore] = useState(false);
  const [page, setPage] = useState(1);

  // Fetch comments from API
  const fetchComments = useCallback(async (pageNum: number = 1, append: boolean = false) => {
    try {
      if (!append) {
        setLoading(true);
      } else {
        setLoadingMore(true);
      }
      setError(null);

      const params = new URLSearchParams({
        target_type: targetType,
        target_id: targetId,
        page: pageNum.toString(),
        limit: limit.toString(),
        sort_order: sortOrder,
      });

      const response = await fetch(`${API_BASE}/workspaces/${workspaceId}/comments?${params}`, {
        headers: {
          'Content-Type': 'application/json',
          'X-User-Id': userId,
        },
      });

      if (!response.ok) {
        throw new Error(`Failed to fetch comments: ${response.statusText}`);
      }

      const data: PaginatedResponse<Comment> = await response.json();

      if (append) {
        setComments(prev => [...prev, ...data.data]);
      } else {
        setComments(data.data);
      }

      setHasMore(data.pagination.has_next);
      setPage(pageNum);
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Unknown error occurred';
      setError(errorMessage);
      console.error('Failed to fetch comments:', err);
    } finally {
      setLoading(false);
      setLoadingMore(false);
    }
  }, [workspaceId, targetType, targetId, userId, limit, sortOrder]);

  // Create a new comment
  const createComment = useCallback(async (commentData: CreateComment): Promise<Comment> => {
    const response = await fetch(`${API_BASE}/comments`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-User-Id': userId,
      },
      body: JSON.stringify(commentData),
    });

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(errorData.message || `Failed to create comment: ${response.statusText}`);
    }

    const newComment: Comment = await response.json();

    // Add the new comment to the list
    setComments(prev => {
      if (sortOrder === 'desc') {
        return [newComment, ...prev];
      } else {
        return [...prev, newComment];
      }
    });

    return newComment;
  }, [userId, sortOrder]);

  // Update an existing comment
  const updateComment = useCallback(async (commentId: string, updates: UpdateComment): Promise<Comment> => {
    const response = await fetch(`${API_BASE}/comments/${commentId}`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json',
        'X-User-Id': userId,
      },
      body: JSON.stringify(updates),
    });

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(errorData.message || `Failed to update comment: ${response.statusText}`);
    }

    const updatedComment: Comment = await response.json();

    // Update the comment in the list
    setComments(prev => prev.map(comment => 
      comment.id === commentId ? updatedComment : comment
    ));

    return updatedComment;
  }, [userId]);

  // Delete a comment
  const deleteComment = useCallback(async (commentId: string): Promise<void> => {
    const response = await fetch(`${API_BASE}/comments/${commentId}`, {
      method: 'DELETE',
      headers: {
        'Content-Type': 'application/json',
        'X-User-Id': userId,
      },
    });

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(errorData.message || `Failed to delete comment: ${response.statusText}`);
    }

    // Remove the comment from the list
    setComments(prev => prev.filter(comment => comment.id !== commentId));
  }, [userId]);

  // Load more comments (pagination)
  const loadMore = useCallback(() => {
    if (!hasMore || loadingMore) return;
    fetchComments(page + 1, true);
  }, [fetchComments, page, hasMore, loadingMore]);

  // Refresh comments (reset to first page)
  const refresh = useCallback(() => {
    setPage(1);
    fetchComments(1, false);
  }, [fetchComments]);

  // Get a single comment by ID
  const getComment = useCallback(async (commentId: string): Promise<Comment | null> => {
    try {
      const response = await fetch(`${API_BASE}/comments/${commentId}`, {
        headers: {
          'Content-Type': 'application/json',
          'X-User-Id': userId,
        },
      });

      if (!response.ok) {
        if (response.status === 404) return null;
        throw new Error(`Failed to fetch comment: ${response.statusText}`);
      }

      return await response.json();
    } catch (err) {
      console.error('Failed to fetch comment:', err);
      return null;
    }
  }, [userId]);

  // Initial fetch and setup
  useEffect(() => {
    fetchComments(1, false);
  }, [fetchComments]);

  // Auto-refresh interval
  useEffect(() => {
    if (!autoRefresh) return;

    const interval = setInterval(() => {
      refresh();
    }, refreshInterval);

    return () => clearInterval(interval);
  }, [autoRefresh, refreshInterval, refresh]);

  // Handle sort order changes
  useEffect(() => {
    if (comments.length > 0) {
      refresh();
    }
  }, [sortOrder]); // Only refresh when sort order changes

  return {
    comments,
    loading,
    loadingMore,
    error,
    hasMore,
    page,
    createComment,
    updateComment,
    deleteComment,
    loadMore,
    refresh,
    getComment,
  };
}

// Hook for managing visual diff sessions
// Story 9.3.2 - Visual Diff Tool

import { useState, useCallback } from 'react';
import {
  VisualDiffSession,
  DetailedComparison,
  CreateDiffSessionRequest,
  UpdateDiffSessionRequest
} from '../types/comparison';

interface UseDiffSessionResult {
  session: VisualDiffSession | null;
  comparison: DetailedComparison | null;
  loading: boolean;
  error: string | null;
  createSession: (request: CreateDiffSessionRequest) => Promise<void>;
  updateSession: (sessionId: string, updates: UpdateDiffSessionRequest) => Promise<void>;
  deleteSession: (sessionId: string) => Promise<void>;
  clearError: () => void;
}

export const useDiffSession = (): UseDiffSessionResult => {
  const [session, setSession] = useState<VisualDiffSession | null>(null);
  const [comparison, setComparison] = useState<DetailedComparison | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const apiCall = useCallback(async (url: string, options: RequestInit = {}) => {
    const response = await fetch(`/api/visual-diff${url}`, {
      headers: {
        'Content-Type': 'application/json',
        ...options.headers
      },
      ...options
    });

    const data = await response.json();

    if (!response.ok) {
      throw new Error(data.message || data.error || 'Request failed');
    }

    return data;
  }, []);

  const createSession = useCallback(async (request: CreateDiffSessionRequest) => {
    setLoading(true);
    setError(null);

    try {
      const result = await apiCall('/sessions', {
        method: 'POST',
        body: JSON.stringify(request)
      });

      setSession(result.data);

      // Fetch the comparison data
      const sessionData = await apiCall(`/sessions/${result.session_id}`);
      setComparison(sessionData.data.comparison);

    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to create session';
      setError(errorMessage);
      console.error('Failed to create diff session:', err);
    } finally {
      setLoading(false);
    }
  }, [apiCall]);

  const updateSession = useCallback(async (sessionId: string, updates: UpdateDiffSessionRequest) => {
    if (!session) return;

    setLoading(true);
    setError(null);

    try {
      const result = await apiCall(`/sessions/${sessionId}`, {
        method: 'PATCH',
        body: JSON.stringify(updates)
      });

      setSession(result.data);

    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to update session';
      setError(errorMessage);
      console.error('Failed to update diff session:', err);
    } finally {
      setLoading(false);
    }
  }, [session, apiCall]);

  const deleteSession = useCallback(async (sessionId: string) => {
    setLoading(true);
    setError(null);

    try {
      await apiCall(`/sessions/${sessionId}`, {
        method: 'DELETE'
      });

      setSession(null);
      setComparison(null);

    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to delete session';
      setError(errorMessage);
      console.error('Failed to delete diff session:', err);
    } finally {
      setLoading(false);
    }
  }, [apiCall]);

  const clearError = useCallback(() => {
    setError(null);
  }, []);

  return {
    session,
    comparison,
    loading,
    error,
    createSession,
    updateSession,
    deleteSession,
    clearError
  };
};

import { useState, useCallback } from 'react';
import { 
  ExportTemplate, 
  CreateExportTemplate, 
  UpdateExportTemplate,
  ExportJob, 
  CreateExportJob, 
  UpdateExportJob,
  ExportSchedule, 
  CreateExportSchedule, 
  UpdateExportSchedule,
  ExportShare, 
  CreateExportShare, 
  UpdateExportShare,
  ExportAnalytics, 
  CreateExportAnalytics,
  ExportFormatDefinition,
  ExportFormat,
  ExportType,
  ExportJobStatus,
  ExportResult,
  ExportProgress,
  ExportStatistics,
  ExportTemplateWithStats,
  ExportJobWithTemplate,
  ExportScheduleWithStats
} from '../types/export';

interface UseExportState {
  templates: ExportTemplate[];
  jobs: ExportJob[];
  schedules: ExportSchedule[];
  shares: ExportShare[];
  analytics: ExportAnalytics[];
  formatDefinitions: ExportFormatDefinition[];
  statistics: ExportStatistics | null;
  loading: boolean;
  error: string | null;
}

interface UseExportActions {
  // Templates
  fetchTemplates: (options?: { format?: ExportFormat; isPublic?: boolean; limit?: number; offset?: number }) => Promise<void>;
  createTemplate: (template: CreateExportTemplate) => Promise<ExportTemplate>;
  updateTemplate: (id: string, updates: UpdateExportTemplate) => Promise<ExportTemplate>;
  deleteTemplate: (id: string) => Promise<void>;
  getTemplateWithStats: (id: string) => Promise<ExportTemplateWithStats>;

  // Jobs
  fetchJobs: (options?: { status?: ExportJobStatus; format?: ExportFormat; userId?: string; limit?: number; offset?: number }) => Promise<void>;
  createExportJob: (job: CreateExportJob) => Promise<ExportJob>;
  updateExportJob: (id: string, updates: UpdateExportJob) => Promise<ExportJob>;
  cancelExportJob: (id: string) => Promise<void>;
  getJobWithTemplate: (id: string) => Promise<ExportJobWithTemplate>;
  getJobProgress: (id: string) => Promise<ExportProgress>;
  downloadExportFile: (id: string) => Promise<void>;

  // Schedules
  fetchSchedules: () => Promise<void>;
  createSchedule: (schedule: CreateExportSchedule) => Promise<ExportSchedule>;
  updateSchedule: (id: string, updates: UpdateExportSchedule) => Promise<ExportSchedule>;
  deleteSchedule: (id: string) => Promise<void>;
  getScheduleWithStats: (id: string) => Promise<ExportScheduleWithStats>;

  // Shares
  fetchShares: (jobId?: string) => Promise<void>;
  createShare: (share: CreateExportShare) => Promise<ExportShare>;
  updateShare: (id: string, updates: UpdateExportShare) => Promise<ExportShare>;
  deleteShare: (id: string) => Promise<void>;

  // Analytics
  fetchAnalytics: (options?: { startDate?: string; endDate?: string; format?: ExportFormat }) => Promise<void>;
  createAnalytics: (analytics: CreateExportAnalytics) => Promise<ExportAnalytics>;

  // Format Definitions
  fetchFormatDefinitions: () => Promise<void>;
  getFormatDefinition: (formatName: string) => Promise<ExportFormatDefinition>;
  validateFormatOptions: (formatName: string, options: any) => Promise<{ valid: boolean; errors: string[]; validatedOptions: any }>;

  // Statistics
  fetchStatistics: () => Promise<void>;

  // Utilities
  refetch: () => Promise<void>;
  clearError: () => void;
  setLoading: (loading: boolean) => void;
}

export type UseExportReturn = UseExportState & UseExportActions;

export const useExport = (projectId: string): UseExportReturn => {
  const [state, setState] = useState<UseExportState>({
    templates: [],
    jobs: [],
    schedules: [],
    shares: [],
    analytics: [],
    formatDefinitions: [],
    statistics: null,
    loading: false,
    error: null
  });

  const setLoading = useCallback((loading: boolean) => {
    setState(prev => ({ ...prev, loading }));
  }, []);

  const setError = useCallback((error: string | null) => {
    setState(prev => ({ ...prev, error }));
  }, []);

  const clearError = useCallback(() => {
    setError(null);
  }, [setError]);

  const handleApiCall = useCallback(async <T>(
    apiCall: () => Promise<T>,
    onSuccess?: (result: T) => void
  ): Promise<T> => {
    try {
      setLoading(true);
      setError(null);
      const result = await apiCall();
      if (onSuccess) {
        onSuccess(result);
      }
      return result;
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'An error occurred';
      setError(errorMessage);
      throw error;
    } finally {
      setLoading(false);
    }
  }, [setLoading, setError]);

  // Template Actions
  const fetchTemplates = useCallback(async (options: {
    format?: ExportFormat;
    isPublic?: boolean;
    limit?: number;
    offset?: number;
  } = {}) => {
    await handleApiCall(async () => {
      const params = new URLSearchParams();
      if (options.format) params.append('format', options.format);
      if (options.isPublic !== undefined) params.append('isPublic', options.isPublic.toString());
      if (options.limit) params.append('limit', options.limit.toString());
      if (options.offset) params.append('offset', options.offset.toString());

      const response = await fetch(`/api/projects/${projectId}/export/templates?${params}`);
      const data = await response.json();

      if (!data.success) {
        throw new Error(data.error || 'Failed to fetch templates');
      }

      return data.data;
    }, (templates) => {
      setState(prev => ({ ...prev, templates }));
    });
  }, [projectId, handleApiCall]);

  const createTemplate = useCallback(async (template: CreateExportTemplate): Promise<ExportTemplate> => {
    return handleApiCall(async () => {
      const response = await fetch(`/api/projects/${projectId}/export/templates`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(template)
      });
      const data = await response.json();

      if (!data.success) {
        throw new Error(data.error || 'Failed to create template');
      }

      return data.data;
    }, (newTemplate) => {
      setState(prev => ({ 
        ...prev, 
        templates: [...prev.templates, newTemplate] 
      }));
    });
  }, [projectId, handleApiCall]);

  const updateTemplate = useCallback(async (id: string, updates: UpdateExportTemplate): Promise<ExportTemplate> => {
    return handleApiCall(async () => {
      const response = await fetch(`/api/export/templates/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(updates)
      });
      const data = await response.json();

      if (!data.success) {
        throw new Error(data.error || 'Failed to update template');
      }

      return data.data;
    }, (updatedTemplate) => {
      setState(prev => ({ 
        ...prev, 
        templates: prev.templates.map(t => t.id === id ? updatedTemplate : t) 
      }));
    });
  }, [handleApiCall]);

  const deleteTemplate = useCallback(async (id: string): Promise<void> => {
    await handleApiCall(async () => {
      const response = await fetch(`/api/export/templates/${id}`, {
        method: 'DELETE'
      });
      const data = await response.json();

      if (!data.success) {
        throw new Error(data.error || 'Failed to delete template');
      }
