      }

      return data.data;
    }, (statistics) => {
      setState(prev => ({ ...prev, statistics }));
    });
  }, [projectId, handleApiCall]);

  // Utility Actions
  const refetch = useCallback(async () => {
    await Promise.all([
      fetchTemplates(),
      fetchJobs(),
      fetchSchedules(),
      fetchShares(),
      fetchAnalytics(),
      fetchFormatDefinitions(),
      fetchStatistics()
    ]);
  }, [
    fetchTemplates,
    fetchJobs,
    fetchSchedules,
    fetchShares,
    fetchAnalytics,
    fetchFormatDefinitions,
    fetchStatistics
  ]);

  return {
    // State
    ...state,

    // Template Actions
    fetchTemplates,
    createTemplate,
    updateTemplate,
    deleteTemplate,
    getTemplateWithStats,

    // Job Actions
    fetchJobs,
    createExportJob,
    updateExportJob,
    cancelExportJob,
