import { useMemo } from "react";
import { NodeMeta } from "../Palette";

interface UseNodeUtilsProps {
  nodeTypes: NodeMeta[];
}

interface UseNodeUtilsReturn {
  getNodeMeta: (nodeType: string) => NodeMeta;
  getCategoryColor: (category: string) => string;
}

export const useNodeUtils = ({ nodeTypes }: UseNodeUtilsProps): UseNodeUtilsReturn => {
  const getNodeMeta = useMemo(() => {
    return (nodeType: string): NodeMeta => {
      // Handle undefined/null/invalid types
      if (!nodeType || typeof nodeType !== 'string') {
        return { 
          id: 'default', 
          label: 'Unknown', 
          icon: "🔧", 
          category: "unknown",
          tooltip: "Unknown node type"
        };
      }

      return nodeTypes.find(n => n.id === nodeType) || { 
        id: nodeType, 
        label: nodeType.charAt(0).toUpperCase() + nodeType.slice(1), 
        icon: "🔧", 
        category: "unknown",
        tooltip: `${nodeType} node`
      };
    };
  }, [nodeTypes]);

  const getCategoryColor = useMemo(() => {
    return (category: string): string => {
      switch (category) {
        case 'text': return '#4f46e5'; // Indigo
        case 'logic': return '#059669'; // Emerald  
        case 'output': return '#dc2626'; // Red
        case 'variable': return '#7c3aed'; // Violet
        default: return '#6b7280'; // Gray
      }
    };
  }, []);

  return {
    getNodeMeta,
    getCategoryColor,
  };
};

import { useState, useCallback } from 'react';
import { 
  CreateRestorationAttemptRequest,
  RestorationPreviewRequest,
  ConflictResolutionRequest,
  RestorationBookmarkRequest,
  RestorationAttempt,
  RestorationPreviewResponse,
  RestorationProgressResponse,
  RestorationStatsResponse,
  RestorationBookmark,
  ConflictResolutionResult,
  RestorationFilter,
} from '../types/restoration';

interface UseRestorationReturn {
  // State
  loading: boolean;
  error: string | null;

  // Actions
  generatePreview: (request: RestorationPreviewRequest) => Promise<RestorationPreviewResponse>;
  createRestoration: (request: CreateRestorationAttemptRequest) => Promise<RestorationAttempt>;
  getProgress: (restorationAttemptId: string) => Promise<RestorationProgressResponse>;
  resolveConflict: (request: ConflictResolutionRequest) => Promise<ConflictResolutionResult>;
  cancelRestoration: (restorationAttemptId: string) => Promise<void>;
  getStats: (projectId: string) => Promise<RestorationStatsResponse>;
  createBookmark: (request: RestorationBookmarkRequest) => Promise<RestorationBookmark>;
  getBookmarks: (projectId: string) => Promise<RestorationBookmark[]>;
  deleteBookmark: (bookmarkId: string) => Promise<void>;
  listRestorations: (filter: RestorationFilter) => Promise<RestorationAttempt[]>;
  getRestorationDetails: (restorationAttemptId: string) => Promise<any>;

  // Utility
  clearError: () => void;
}

export const useRestoration = (): UseRestorationReturn => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const apiCall = useCallback(async <T>(
    url: string,
    options: RequestInit = {}
  ): Promise<T> => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch(url, {
        ...options,
        headers: {
          'Content-Type': 'application/json',
          ...options.headers,
        },
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error || `HTTP ${response.status}: ${response.statusText}`);
      }

      const data = await response.json();

      if (!data.success) {
        throw new Error(data.error || 'Request failed');
      }

      return data.data;
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'An unknown error occurred';
      setError(errorMessage);
      throw err;
    } finally {
      setLoading(false);
    }
  }, []);

  const generatePreview = useCallback(async (request: RestorationPreviewRequest): Promise<RestorationPreviewResponse> => {
    return apiCall<RestorationPreviewResponse>('/api/restoration/preview', {
      method: 'POST',
      body: JSON.stringify(request),
    });
  }, [apiCall]);

  const createRestoration = useCallback(async (request: CreateRestorationAttemptRequest): Promise<RestorationAttempt> => {
    return apiCall<RestorationAttempt>('/api/restoration/attempts', {
      method: 'POST',
      body: JSON.stringify(request),
    });
  }, [apiCall]);

  const getProgress = useCallback(async (restorationAttemptId: string): Promise<RestorationProgressResponse> => {
    return apiCall<RestorationProgressResponse>(`/api/restoration/attempts/${restorationAttemptId}/progress`);
  }, [apiCall]);

  const resolveConflict = useCallback(async (request: ConflictResolutionRequest): Promise<ConflictResolutionResult> => {
    return apiCall<ConflictResolutionResult>('/api/restoration/conflicts/resolve', {
      method: 'POST',
      body: JSON.stringify(request),
    });
  }, [apiCall]);

  const cancelRestoration = useCallback(async (restorationAttemptId: string): Promise<void> => {
    return apiCall<void>(`/api/restoration/attempts/${restorationAttemptId}/cancel`, {
      method: 'POST',
    });
  }, [apiCall]);

  const getStats = useCallback(async (projectId: string): Promise<RestorationStatsResponse> => {
    return apiCall<RestorationStatsResponse>(`/api/restoration/stats/${projectId}`);
  }, [apiCall]);

  const createBookmark = useCallback(async (request: RestorationBookmarkRequest): Promise<RestorationBookmark> => {
    return apiCall<RestorationBookmark>('/api/restoration/bookmarks', {
      method: 'POST',
      body: JSON.stringify(request),
    });
  }, [apiCall]);

  const getBookmarks = useCallback(async (projectId: string): Promise<RestorationBookmark[]> => {
    return apiCall<RestorationBookmark[]>(`/api/restoration/bookmarks/${projectId}`);
  }, [apiCall]);

  const deleteBookmark = useCallback(async (bookmarkId: string): Promise<void> => {
    return apiCall<void>(`/api/restoration/bookmarks/${bookmarkId}`, {
      method: 'DELETE',
    });
  }, [apiCall]);

  const listRestorations = useCallback(async (filter: RestorationFilter): Promise<RestorationAttempt[]> => {
    const params = new URLSearchParams();

    if (filter.projectId) params.append('projectId', filter.projectId);
    if (filter.initiatedBy) params.append('initiatedBy', filter.initiatedBy);
    if (filter.status) params.append('status', filter.status);
    if (filter.restorationType) params.append('restorationType', filter.restorationType);
    if (filter.dateFrom) params.append('dateFrom', filter.dateFrom.toISOString());
    if (filter.dateTo) params.append('dateTo', filter.dateTo.toISOString());
    if (filter.limit) params.append('limit', filter.limit.toString());
    if (filter.offset) params.append('offset', filter.offset.toString());

    return apiCall<RestorationAttempt[]>(`/api/restoration/attempts?${params.toString()}`);
  }, [apiCall]);

  const getRestorationDetails = useCallback(async (restorationAttemptId: string): Promise<any> => {
    return apiCall<any>(`/api/restoration/attempts/${restorationAttemptId}`);
  }, [apiCall]);

  const clearError = useCallback(() => {
    setError(null);
  }, []);

  return {
    loading,
    error,
    generatePreview,
    createRestoration,
    getProgress,
    resolveConflict,
    cancelRestoration,
    getStats,
    createBookmark,
    getBookmarks,
    deleteBookmark,
    listRestorations,
    getRestorationDetails,
    clearError,
  };
};

import { useState, useCallback, useEffect } from "react";
import { Edge, Node } from "reactflow";
import { ValidationError, validateConnection } from "../validation";

interface UseValidationReturn {
  errors: ValidationError[];
  styledEdges: Edge[];
  styledNodes: Node[];
  runValidation: (edges: Edge[], nodes: Node[]) => void;
}

interface UseValidationProps {
  edges: Edge[];
  nodes: Node[];
  highlightNodeIds?: Set<string>;
  highlightEdgeIds?: Set<string>;
  validateConnection?: (edges: Edge[], nodes: Node[]) => ValidationError[];
}

export const useValidation = ({
  edges,
  nodes,
  highlightNodeIds = new Set(),
  highlightEdgeIds = new Set(),
  validateConnection: customValidateConnection = validateConnection,
}: UseValidationProps): UseValidationReturn => {
  const [errors, setErrors] = useState<ValidationError[]>([]);

  const runValidation = useCallback(
    (edgesToValidate: Edge[], nodesToValidate: Node[]) => {
      const errs = customValidateConnection(edgesToValidate, nodesToValidate);
      setErrors(errs);
    },
    [customValidateConnection]
  );

  // Apply highlight styles to nodes
  const styledNodes = nodes.map((n) => {
    const highlight = highlightNodeIds.has(n.id)
      ? { border: '2px solid #ffd700' }
      : {};
    return { ...n, style: { ...n.style, ...highlight } };
  });

  // Apply error and highlight styles to edges
  const styledEdges = edges.map((e) => {
    const base = errors.find((err) => err.edgeId === e.id)
      ? { stroke: 'red', strokeWidth: 2 }
      : {};
    const highlight = highlightEdgeIds.has(e.id)
      ? { stroke: '#ffd700', strokeWidth: 3 }
      : {};
    return { ...e, style: { ...e.style, ...base, ...highlight } };
  });

  // Recompute validation errors when edges or nodes change
  useEffect(() => {
    runValidation(edges, nodes);
  }, [edges, nodes, runValidation]);

  return {
    errors,
    styledEdges,
    styledNodes,
    runValidation,
  };
};

import { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { WebSocketClient } from '../websocket/WebSocketClient';
const DEFAULT_CONFIG = {
    reconnectInterval: 1000,
    maxReconnectAttempts: 5,
    heartbeatInterval: 30000,
    connectionTimeout: 10000,
    enableOfflineQueue: true
};
export function useWebSocket(options) {
    const { url = `ws://localhost:8001`, documentId, userId = 'anonymous', authToken, enabled = true, reconnectInterval = DEFAULT_CONFIG.reconnectInterval, maxReconnectAttempts = DEFAULT_CONFIG.maxReconnectAttempts, onGraphUpdate, onPresenceUpdate, onUserJoin, onUserLeave, onError } = options;
    const [connectionState, setConnectionState] = useState({
        status: 'disconnected',
        reconnectAttempts: 0
    });
    const [queuedMessages, setQueuedMessages] = useState(0);
    const clientRef = useRef(null);
    const optionsRef = useRef(options);
    // Update options ref when options change
    useEffect(() => {
        optionsRef.current = options;
    }, [options]);
    // Initialize WebSocket client
    useEffect(() => {
        if (!enabled || !documentId) {
            return;
        }
        const config = {
            url,
            reconnectInterval: reconnectInterval || DEFAULT_CONFIG.reconnectInterval,
            maxReconnectAttempts: maxReconnectAttempts || DEFAULT_CONFIG.maxReconnectAttempts,
            heartbeatInterval: DEFAULT_CONFIG.heartbeatInterval,
            connectionTimeout: DEFAULT_CONFIG.connectionTimeout,
            enableOfflineQueue: DEFAULT_CONFIG.enableOfflineQueue,
            authToken
        };
        const client = new WebSocketClient(config);
        clientRef.current = client;
        // Set up event listeners
        const handleConnectionStateChange = () => {
            setConnectionState(client.getConnectionState());
            setQueuedMessages(client.getQueuedMessagesCount());
        };
        client.on('connected', handleConnectionStateChange);
        client.on('disconnected', handleConnectionStateChange);
        client.on('authenticated', handleConnectionStateChange);
        client.on('reconnecting', handleConnectionStateChange);
        client.on('reconnect_failed', handleConnectionStateChange);
        client.on('auth_error', handleConnectionStateChange);
        client.on('graph_update', (update) => {
            optionsRef.current.onGraphUpdate?.(update);
        });
        client.on('presence_update', (presence) => {
            optionsRef.current.onPresenceUpdate?.(presence);
        });
        client.on('user_join', (user) => {
            optionsRef.current.onUserJoin?.(user);
        });
        client.on('user_leave', (user) => {
            optionsRef.current.onUserLeave?.(user);
        });
        client.on('error', (error) => {
            optionsRef.current.onError?.(error);
        });
        // Auto-connect if enabled
        if (enabled) {
            client.connect(documentId, userId).catch((error) => {
                console.error('Failed to connect WebSocket:', error);
                optionsRef.current.onError?.(error);
            });
        }
        return () => {
            client.disconnect();
            client.removeAllListeners();
            clientRef.current = null;
        };
    }, [url, documentId, userId, authToken, enabled, reconnectInterval, maxReconnectAttempts]);
    const sendGraphUpdate = useCallback((update) => {
        return clientRef.current?.sendGraphUpdate(update) || false;
    }, []);
    const sendPresenceUpdate = useCallback((presence) => {
        return clientRef.current?.sendPresenceUpdate(presence) || false;
    }, []);
    const connect = useCallback(async () => {
        if (clientRef.current && documentId) {
            await clientRef.current.connect(documentId, userId);
        }
    }, [documentId, userId]);
    const disconnect = useCallback(() => {
        clientRef.current?.disconnect();
    }, []);
    const clearQueue = useCallback(() => {
        clientRef.current?.clearMessageQueue();
        setQueuedMessages(0);
    }, []);
    return {
        connectionState,
        isConnected: connectionState.status === 'authenticated' || connectionState.status === 'connected',
        isConnecting: connectionState.status === 'connecting' || connectionState.status === 'authenticating',
        sendGraphUpdate,
        sendPresenceUpdate,
        connect,
        disconnect,
        queuedMessages,
        clearQueue
    };
}
// Enhanced hook for managing user presence
export function usePresence(documentId, userId, userName, userAvatar) {
    const [cursor, setCursor] = useState(null);
    const [selection, setSelection] = useState([]);
    const [currentTool, setCurrentTool] = useState('');
    const [isTyping, setIsTyping] = useState(false);
    const [focusedNodeId, setFocusedNodeId] = useState('');
    // Other users' presence data
    const [otherUsers, setOtherUsers] = useState(new Map());
    const [userCursors, setUserCursors] = useState(new Map());
    const [userSelections, setUserSelections] = useState(new Map());
    const [userActivity, setUserActivity] = useState(new Map());
    const { sendCursorUpdate, sendSelectionUpdate, sendActivityUpdate, requestPresenceData, isConnected } = useWebSocket({
        documentId,
        userId,
        authToken: undefined, // Add your auth token here
        onPresenceSync: (data) => {
            const usersMap = new Map();
            data.users.forEach((user) => {
                usersMap.set(user.userId, user);
            });
            setOtherUsers(usersMap);
        },
        onPresenceUpdate: (presence) => {
            if (presence.userId !== userId) {
                setOtherUsers(prev => new Map(prev.set(presence.userId, presence)));
            }
        },
        onCursorUpdate: (data) => {
            if (data.userId !== userId) {
                setUserCursors(prev => new Map(prev.set(data.userId, data.cursor)));
            }
        },
        onSelectionUpdate: (data) => {
            if (data.userId !== userId) {
                setUserSelections(prev => new Map(prev.set(data.userId, data.selection)));
            }
        },
        onActivityUpdate: (data) => {
            if (data.userId !== userId) {
                setUserActivity(prev => new Map(prev.set(data.userId, {
                    currentTool: data.currentTool,
                    isTyping: data.isTyping,
                    focusedNodeId: data.focusedNodeId
                })));
            }
        },
        onUserJoin: (user) => {
            // User will be added via presence_sync
        },
        onUserLeave: (user) => {
            setOtherUsers(prev => {
                const next = new Map(prev);
                next.delete(user.userId);
                return next;
            });
            setUserCursors(prev => {
                const next = new Map(prev);
                next.delete(user.userId);
                return next;
            });
            setUserSelections(prev => {
                const next = new Map(prev);
                next.delete(user.userId);
                return next;
            });
            setUserActivity(prev => {
                const next = new Map(prev);
                next.delete(user.userId);
                return next;
            });
        },
        onUserStatusChanged: (data) => {
            setOtherUsers(prev => {
                const user = prev.get(data.userId);
                if (user) {
                    return new Map(prev.set(data.userId, { ...user, status: data.status }));
                }
                return prev;
            });
        }
    });
    // Request presence data when connected
    useEffect(() => {
        if (isConnected) {
            requestPresenceData();
        }
    }, [isConnected, requestPresenceData]);
    const updateCursor = useCallback((x, y, nodeId, viewportBounds) => {
        setCursor({ x, y, nodeId });
        sendCursorUpdate(x, y, nodeId, viewportBounds);
    }, [sendCursorUpdate]);
    const updateSelection = useCallback((newSelection) => {
        setSelection(newSelection);
        sendSelectionUpdate(newSelection);
    }, [sendSelectionUpdate]);
    const updateActivity = useCallback((tool, typing, focusedNode) => {
        if (tool !== undefined)
            setCurrentTool(tool);
        if (typing !== undefined)
            setIsTyping(typing);
        if (focusedNode !== undefined)
            setFocusedNodeId(focusedNode);
        sendActivityUpdate(tool !== undefined ? tool : currentTool, typing !== undefined ? typing : isTyping, focusedNode !== undefined ? focusedNode : focusedNodeId);
    }, [currentTool, isTyping, focusedNodeId, sendActivityUpdate]);
    // Auto-clear typing indicator
    useEffect(() => {
        if (isTyping) {
            const timeout = setTimeout(() => {
                setIsTyping(false);
                sendActivityUpdate(currentTool, false, focusedNodeId);
            }, 3000);
            return () => clearTimeout(timeout);
        }
    }, [isTyping, currentTool, focusedNodeId, sendActivityUpdate]);
    // Combine all user data
    const allUsers = useMemo(() => {
        const users = [];
        for (const [userId, userData] of otherUsers) {
            const cursor = userCursors.get(userId);
            const selection = userSelections.get(userId);
            const activity = userActivity.get(userId);
            users.push({
                ...userData,
                cursor,
                selection: selection?.nodeIds || [],
                currentTool: activity?.currentTool,
                isTyping: activity?.isTyping,
                focusedNodeId: activity?.focusedNodeId
            });
        }
        return users;
    }, [otherUsers, userCursors, userSelections, userActivity]);
    return {
        // Current user state
        cursor,
        selection,
        currentTool,
        isTyping,
        focusedNodeId,
        // Other users
        otherUsers: allUsers,
        userCursors: Array.from(userCursors.entries()),
        userSelections: Array.from(userSelections.entries()),
        typingUsers: allUsers.filter(user => user.isTyping),
        // Actions
        updateCursor,
        updateSelection,
        updateActivity
    };
}

import { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { WebSocketClient, WebSocketClientConfig, ConnectionState } from '../websocket/WebSocketClient';
import { GraphUpdatePayload, PresenceUpdatePayload } from '../../../server/src/websocket/types';

export interface UseWebSocketOptions {
  url?: string;
  documentId: string;
  userId?: string;
  authToken?: string;
  enabled?: boolean;
  reconnectInterval?: number;
  maxReconnectAttempts?: number;
  onGraphUpdate?: (update: GraphUpdatePayload) => void;
  onPresenceUpdate?: (presence: PresenceUpdatePayload) => void;
  onUserJoin?: (user: any) => void;
  onUserLeave?: (user: any) => void;
  onError?: (error: any) => void;
}

export interface UseWebSocketReturn {
  connectionState: ConnectionState;
  isConnected: boolean;
  isConnecting: boolean;
  sendGraphUpdate: (update: GraphUpdatePayload) => boolean;
  sendPresenceUpdate: (presence: PresenceUpdatePayload) => boolean;
  connect: () => Promise<void>;
  disconnect: () => void;
  queuedMessages: number;
  clearQueue: () => void;
}

const DEFAULT_CONFIG: Partial<WebSocketClientConfig> = {
  reconnectInterval: 1000,
  maxReconnectAttempts: 5,
  heartbeatInterval: 30000,
  connectionTimeout: 10000,
  enableOfflineQueue: true
};

export function useWebSocket(options: UseWebSocketOptions): UseWebSocketReturn {
  const {
    url = `ws://localhost:8001`,
    documentId,
    userId = 'anonymous',
    authToken,
    enabled = true,
    reconnectInterval = DEFAULT_CONFIG.reconnectInterval,
    maxReconnectAttempts = DEFAULT_CONFIG.maxReconnectAttempts,
    onGraphUpdate,
    onPresenceUpdate,
    onUserJoin,
    onUserLeave,
    onError
  } = options;

  const [connectionState, setConnectionState] = useState<ConnectionState>({
    status: 'disconnected',
    reconnectAttempts: 0
  });

  const [queuedMessages, setQueuedMessages] = useState(0);
  const clientRef = useRef<WebSocketClient | null>(null);
  const optionsRef = useRef(options);

  // Update options ref when options change
  useEffect(() => {
    optionsRef.current = options;
  }, [options]);

  // Initialize WebSocket client
  useEffect(() => {
    if (!enabled || !documentId) {
      return;
    }

    const config: WebSocketClientConfig = {
      url,
      reconnectInterval: reconnectInterval || DEFAULT_CONFIG.reconnectInterval!,
      maxReconnectAttempts: maxReconnectAttempts || DEFAULT_CONFIG.maxReconnectAttempts!,
      heartbeatInterval: DEFAULT_CONFIG.heartbeatInterval!,
      connectionTimeout: DEFAULT_CONFIG.connectionTimeout!,
      enableOfflineQueue: DEFAULT_CONFIG.enableOfflineQueue!,
      authToken
    };

    const client = new WebSocketClient(config);
    clientRef.current = client;

    // Set up event listeners
    const handleConnectionStateChange = () => {
      setConnectionState(client.getConnectionState());
      setQueuedMessages(client.getQueuedMessagesCount());
    };

    client.on('connected', handleConnectionStateChange);
    client.on('disconnected', handleConnectionStateChange);
    client.on('authenticated', handleConnectionStateChange);
    client.on('reconnecting', handleConnectionStateChange);
    client.on('reconnect_failed', handleConnectionStateChange);
    client.on('auth_error', handleConnectionStateChange);

    client.on('graph_update', (update: GraphUpdatePayload) => {
      optionsRef.current.onGraphUpdate?.(update);
    });

    client.on('presence_update', (presence: PresenceUpdatePayload) => {
      optionsRef.current.onPresenceUpdate?.(presence);
    });

    client.on('user_join', (user: any) => {
      optionsRef.current.onUserJoin?.(user);
    });

    client.on('user_leave', (user: any) => {
      optionsRef.current.onUserLeave?.(user);
    });

    client.on('error', (error: any) => {
      optionsRef.current.onError?.(error);
    });

    // Auto-connect if enabled
    if (enabled) {
      client.connect(documentId, userId).catch((error) => {
        console.error('Failed to connect WebSocket:', error);
        optionsRef.current.onError?.(error);
      });
    }

    return () => {
      client.disconnect();
      client.removeAllListeners();
      clientRef.current = null;
    };
  }, [url, documentId, userId, authToken, enabled, reconnectInterval, maxReconnectAttempts]);

  const sendGraphUpdate = useCallback((update: GraphUpdatePayload): boolean => {
    return clientRef.current?.sendGraphUpdate(update) || false;
  }, []);

  const sendPresenceUpdate = useCallback((presence: PresenceUpdatePayload): boolean => {
    return clientRef.current?.sendPresenceUpdate(presence) || false;
  }, []);

  const connect = useCallback(async (): Promise<void> => {
    if (clientRef.current && documentId) {
      await clientRef.current.connect(documentId, userId);
    }
  }, [documentId, userId]);

  const disconnect = useCallback((): void => {
    clientRef.current?.disconnect();
  }, []);

  const clearQueue = useCallback((): void => {
    clientRef.current?.clearMessageQueue();
    setQueuedMessages(0);
  }, []);

  return {
    connectionState,
    isConnected: connectionState.status === 'authenticated' || connectionState.status === 'connected',
    isConnecting: connectionState.status === 'connecting' || connectionState.status === 'authenticating',
    sendGraphUpdate,
    sendPresenceUpdate,
    connect,
    disconnect,
    queuedMessages,
    clearQueue
  };
}

