    const entry: ParameterHistory = {
      id: this.generateId(),
      parameters,
      timestamp: new Date().toISOString(),
      success,
      generationTime,
      errorCount
    };

    this.history.unshift(entry);

    // Maintain max history size
    if (this.history.length > this.options.maxHistorySize) {
