            packetLoss <= this.config.packetLossThreshold.fair) {
            return ConnectionQuality.FAIR;
        }
        else {
            return ConnectionQuality.POOR;
        }
    }
    /**
     * Add state to history
     */
    addToStateHistory(state, timestamp, reason) {
        this.stateData.stateHistory.push({ state, timestamp, reason });
        // Trim history if too large
        if (this.stateData.stateHistory.length > this.config.maxHistorySize) {
            this.stateData.stateHistory = this.stateData.stateHistory.slice(-this.config.maxHistorySize);
        }
    }
    /**
     * Update total downtime
     */
    updateDowntime() {
        if (this.stateData.disconnectedAt && this.stateData.lastConnected) {
            const downtime = Date.now() - this.stateData.disconnectedAt;
            this.stateData.totalDowntime += downtime;
        }
    }
    /**
     * Calculate state frequency
     */
    calculateStateFrequency() {
        const frequency = {
            [ConnectionState.CONNECTED]: 0,
            [ConnectionState.CONNECTING]: 0,
            [ConnectionState.DISCONNECTED]: 0,
            [ConnectionState.RECONNECTING]: 0,
            [ConnectionState.FAILED]: 0,
            [ConnectionState.OFFLINE]: 0
        };
        for (const entry of this.stateData.stateHistory) {
            frequency[entry.state]++;
        }
        return frequency;
    }
    /**
     * Calculate connection reliability
     */
    calculateReliability() {
        if (this.stateData.stateHistory.length === 0)
            return 0;
        const connectedCount = this.stateData.stateHistory.filter(entry => entry.state === ConnectionState.CONNECTED).length;
        return connectedCount / this.stateData.stateHistory.length;
    }
    /**
     * Stop all timers
     */
    stopAllTimers() {
        this.stopPingMonitoring();
        if (this.qualityTimer) {
            clearInterval(this.qualityTimer);
            this.qualityTimer = null;
        }
        if (this.offlineTimer) {
            clearTimeout(this.offlineTimer);
            this.offlineTimer = null;
        }
    }
}

import { EventEmitter } from 'events';

export enum ConnectionState {
  CONNECTED = 'connected',
  CONNECTING = 'connecting',
  DISCONNECTED = 'disconnected',
  RECONNECTING = 'reconnecting',
  FAILED = 'failed',
  OFFLINE = 'offline'
}

export enum ConnectionQuality {
  EXCELLENT = 'excellent',
  GOOD = 'good',
  FAIR = 'fair',
  POOR = 'poor',
  UNKNOWN = 'unknown'
}

export interface ConnectionMetrics {
  latency: number;
  packetLoss: number;
  bandwidth: number;
  jitter: number;
  lastMeasurement: number;
  measurementCount: number;
}

export interface NetworkInfo {
  type: 'wifi' | 'cellular' | 'ethernet' | 'unknown';
  effectiveType: '2g' | '3g' | '4g' | 'slow-2g' | 'unknown';
  downlink: number;
  rtt: number;
  saveData: boolean;
}

export interface ConnectionStateData {
  state: ConnectionState;
  quality: ConnectionQuality;
  isOnline: boolean;
  lastConnected: number | null;
  disconnectedAt: number | null;
  reconnectAttempts: number;
  totalDowntime: number;
  metrics: ConnectionMetrics;
  networkInfo: NetworkInfo | null;
  stateHistory: Array<{
    state: ConnectionState;
    timestamp: number;
    reason?: string;
  }>;
}

export interface ConnectionStateConfig {
  pingInterval: number;
  qualityCheckInterval: number;
  latencyThreshold: {
    excellent: number;
    good: number;
    fair: number;
  };
  packetLossThreshold: {
    excellent: number;
    good: number;
    fair: number;
  };
  maxHistorySize: number;
  offlineDetectionTimeout: number;
  onlineCheckUrl: string;
  enableNetworkInfoAPI: boolean;
  enablePerformanceMonitoring: boolean;
}

export class ConnectionStateManager extends EventEmitter {
  private state: ConnectionState = ConnectionState.DISCONNECTED;
  private quality: ConnectionQuality = ConnectionQuality.UNKNOWN;
  private config: ConnectionStateConfig;
  private stateData: ConnectionStateData;
  private pingTimer: NodeJS.Timeout | null = null;
  private qualityTimer: NodeJS.Timeout | null = null;
  private offlineTimer: NodeJS.Timeout | null = null;
  private performanceObserver: PerformanceObserver | null = null;
  private networkChangeHandler: (() => void) | null = null;

  constructor(config: Partial<ConnectionStateConfig> = {}) {
    super();

    this.config = {
      pingInterval: 5000, // 5 seconds
      qualityCheckInterval: 10000, // 10 seconds
      latencyThreshold: {
        excellent: 50,  // < 50ms
        good: 150,      // < 150ms
        fair: 300       // < 300ms
      },
      packetLossThreshold: {
        excellent: 0.01, // < 1%
        good: 0.05,      // < 5%
        fair: 0.15       // < 15%
      },
      maxHistorySize: 100,
      offlineDetectionTimeout: 15000, // 15 seconds
      onlineCheckUrl: '/api/health',
      enableNetworkInfoAPI: true,
      enablePerformanceMonitoring: true,
      ...config
    };

    this.stateData = {
      state: ConnectionState.DISCONNECTED,
      quality: ConnectionQuality.UNKNOWN,
      isOnline: navigator.onLine,
      lastConnected: null,
      disconnectedAt: null,
      reconnectAttempts: 0,
      totalDowntime: 0,
      metrics: {
        latency: 0,
        packetLoss: 0,
        bandwidth: 0,
        jitter: 0,
        lastMeasurement: Date.now(),
        measurementCount: 0
      },
      networkInfo: null,
      stateHistory: []
    };

    this.initializeNetworkMonitoring();
    this.initializePerformanceMonitoring();
    this.startQualityMonitoring();
  }

  /**
   * Get current connection state
   */
  getState(): ConnectionState {
    return this.state;
  }

  /**
   * Get current connection quality
   */
  getQuality(): ConnectionQuality {
    return this.quality;
  }

  /**
   * Get complete state data
   */
  getStateData(): ConnectionStateData {
    return { ...this.stateData };
  }

  /**
   * Check if currently online
   */
  isOnline(): boolean {
    return this.stateData.isOnline && this.state === ConnectionState.CONNECTED;
  }

  /**
   * Check if connection is stable
   */
  isStable(): boolean {
    return this.isOnline() && 
           this.quality !== ConnectionQuality.POOR &&
           this.stateData.metrics.packetLoss < this.config.packetLossThreshold.fair;
  }

  /**
   * Update connection state
   */
  setState(newState: ConnectionState, reason?: string): void {
    if (this.state === newState) return;

    const previousState = this.state;
    const timestamp = Date.now();

    this.state = newState;
    this.stateData.state = newState;

    // Update state-specific data
    switch (newState) {
      case ConnectionState.CONNECTED:
        this.stateData.lastConnected = timestamp;
        this.stateData.disconnectedAt = null;
        this.stateData.reconnectAttempts = 0;
        this.stateData.isOnline = true;
        this.startPingMonitoring();
        break;

      case ConnectionState.DISCONNECTED:
      case ConnectionState.OFFLINE:
        if (this.stateData.lastConnected && !this.stateData.disconnectedAt) {
          this.stateData.disconnectedAt = timestamp;
        }
        this.stateData.isOnline = false;
        this.stopPingMonitoring();
        break;

      case ConnectionState.RECONNECTING:
        this.stateData.reconnectAttempts++;
        break;

      case ConnectionState.FAILED:
        this.stateData.isOnline = false;
        this.stopPingMonitoring();
        break;
    }

    // Update state history
    this.addToStateHistory(newState, timestamp, reason);

    // Calculate total downtime
    if (previousState === ConnectionState.CONNECTED && 
        (newState === ConnectionState.DISCONNECTED || newState === ConnectionState.OFFLINE)) {
      this.updateDowntime();
    }

    console.log(`Connection state changed: ${previousState} -> ${newState}${reason ? ` (${reason})` : ''}`);

    this.emit('state_changed', {
      previousState,
      newState,
      timestamp,
      reason,
      stateData: this.getStateData()
    });
  }

  /**
   * Update connection quality based on metrics
   */
  updateQuality(metrics?: Partial<ConnectionMetrics>): void {
    if (metrics) {
      this.updateMetrics(metrics);
    }

    const newQuality = this.calculateQuality();

    if (this.quality !== newQuality) {
      const previousQuality = this.quality;
      this.quality = newQuality;
      this.stateData.quality = newQuality;

      console.log(`Connection quality changed: ${previousQuality} -> ${newQuality}`);

      this.emit('quality_changed', {
        previousQuality,
        newQuality,
        metrics: { ...this.stateData.metrics },
        timestamp: Date.now()
      });
    }
  }

  /**
   * Update connection metrics
   */
  updateMetrics(metrics: Partial<ConnectionMetrics>): void {
    const timestamp = Date.now();

    // Update metrics with exponential moving average
    if (metrics.latency !== undefined) {
      this.stateData.metrics.latency = this.stateData.metrics.measurementCount === 0 
        ? metrics.latency 
        : (this.stateData.metrics.latency * 0.8) + (metrics.latency * 0.2);
    }

    if (metrics.packetLoss !== undefined) {
      this.stateData.metrics.packetLoss = this.stateData.metrics.measurementCount === 0
        ? metrics.packetLoss
        : (this.stateData.metrics.packetLoss * 0.9) + (metrics.packetLoss * 0.1);
    }

    if (metrics.bandwidth !== undefined) {
      this.stateData.metrics.bandwidth = metrics.bandwidth;
    }

    if (metrics.jitter !== undefined) {
      this.stateData.metrics.jitter = this.stateData.metrics.measurementCount === 0
        ? metrics.jitter
        : (this.stateData.metrics.jitter * 0.8) + (metrics.jitter * 0.2);
    }

    this.stateData.metrics.lastMeasurement = timestamp;
    this.stateData.metrics.measurementCount++;

    this.emit('metrics_updated', { ...this.stateData.metrics });
  }

  /**
   * Perform connection test
   */
  async testConnection(): Promise<ConnectionMetrics> {
    const startTime = performance.now();

    try {
      const response = await fetch(this.config.onlineCheckUrl, {
        method: 'HEAD',
        cache: 'no-cache',
        timeout: 5000
      } as any);

      const endTime = performance.now();
      const latency = endTime - startTime;

      const metrics: ConnectionMetrics = {
        latency,
        packetLoss: response.ok ? 0 : 1,
        bandwidth: 0, // Would need separate bandwidth test
        jitter: Math.abs(latency - this.stateData.metrics.latency),
        lastMeasurement: Date.now(),
        measurementCount: this.stateData.metrics.measurementCount + 1
      };

      return metrics;

    } catch (error) {
      const endTime = performance.now();
      const latency = endTime - startTime;

      return {
        latency,
        packetLoss: 1,
        bandwidth: 0,
        jitter: 0,
        lastMeasurement: Date.now(),
        measurementCount: this.stateData.metrics.measurementCount + 1
      };
    }
  }

  /**
   * Get connection statistics
   */
  getStatistics() {
    const now = Date.now();
    const uptime = this.stateData.lastConnected ? now - this.stateData.lastConnected : 0;
    const stateFrequency = this.calculateStateFrequency();

    return {
      currentState: this.state,
      currentQuality: this.quality,
      uptime,
      totalDowntime: this.stateData.totalDowntime,
      reconnectAttempts: this.stateData.reconnectAttempts,
      averageLatency: this.stateData.metrics.latency,
      packetLossRate: this.stateData.metrics.packetLoss,
      measurementCount: this.stateData.metrics.measurementCount,
      stateFrequency,
      reliability: this.calculateReliability(),
      lastMeasurement: this.stateData.metrics.lastMeasurement
    };
  }

  /**
   * Reset connection state and metrics
   */
  reset(): void {
    this.stopAllTimers();

    this.state = ConnectionState.DISCONNECTED;
    this.quality = ConnectionQuality.UNKNOWN;

    this.stateData = {
      state: ConnectionState.DISCONNECTED,
      quality: ConnectionQuality.UNKNOWN,
      isOnline: navigator.onLine,
      lastConnected: null,
      disconnectedAt: null,
      reconnectAttempts: 0,
      totalDowntime: 0,
      metrics: {
        latency: 0,
        packetLoss: 0,
        bandwidth: 0,
        jitter: 0,
        lastMeasurement: Date.now(),
        measurementCount: 0
      },
      networkInfo: null,
      stateHistory: []
    };

    this.startQualityMonitoring();
    this.emit('reset');
  }

  /**
   * Cleanup and stop monitoring
   */
  cleanup(): void {
    this.stopAllTimers();

    if (this.performanceObserver) {
      this.performanceObserver.disconnect();
    }

    if (this.networkChangeHandler) {
      window.removeEventListener('online', this.networkChangeHandler);
      window.removeEventListener('offline', this.networkChangeHandler);
    }

    this.removeAllListeners();
  }

  /**
   * Initialize network monitoring
   */
  private initializeNetworkMonitoring(): void {
    // Monitor online/offline events
    this.networkChangeHandler = () => {
      const isOnline = navigator.onLine;
      this.stateData.isOnline = isOnline;

      if (isOnline) {
        this.setState(ConnectionState.CONNECTING, 'Browser detected online');
      } else {
        this.setState(ConnectionState.OFFLINE, 'Browser detected offline');
      }
    };

    window.addEventListener('online', this.networkChangeHandler);
    window.addEventListener('offline', this.networkChangeHandler);

    // Network Information API
    if (this.config.enableNetworkInfoAPI && 'connection' in navigator) {
      const connection = (navigator as any).connection;

      const updateNetworkInfo = () => {
        this.stateData.networkInfo = {
          type: connection.type || 'unknown',
          effectiveType: connection.effectiveType || 'unknown',
          downlink: connection.downlink || 0,
          rtt: connection.rtt || 0,
          saveData: connection.saveData || false
        };

        this.emit('network_info_changed', this.stateData.networkInfo);
      };

      connection.addEventListener('change', updateNetworkInfo);
      updateNetworkInfo(); // Initial update
    }
  }

  /**
   * Initialize performance monitoring
   */
  private initializePerformanceMonitoring(): void {
    if (!this.config.enablePerformanceMonitoring || !window.PerformanceObserver) {
      return;
    }

    try {
      this.performanceObserver = new PerformanceObserver((entries) => {
        for (const entry of entries.getEntries()) {
          if (entry.entryType === 'navigation') {
            const navEntry = entry as PerformanceNavigationTiming;

            this.updateMetrics({
              latency: navEntry.responseEnd - navEntry.requestStart,
              bandwidth: navEntry.transferSize / (navEntry.loadEventEnd - navEntry.loadEventStart) * 1000
            });
          }
        }
      });

      this.performanceObserver.observe({ entryTypes: ['navigation', 'resource'] });
    } catch (error) {
      console.warn('Performance monitoring not available:', error);
    }
  }

  /**
   * Start ping monitoring
   */
  private startPingMonitoring(): void {
    if (this.pingTimer) return;

    this.pingTimer = setInterval(async () => {
      try {
        const metrics = await this.testConnection();
        this.updateMetrics(metrics);
        this.updateQuality();

        // Detect disconnection based on failed pings
        if (metrics.packetLoss >= 1) {
          this.handlePingFailure();
        }

      } catch (error) {
        this.handlePingFailure();
      }
    }, this.config.pingInterval);
  }

  /**
   * Stop ping monitoring
   */
  private stopPingMonitoring(): void {
    if (this.pingTimer) {
      clearInterval(this.pingTimer);
      this.pingTimer = null;
    }
  }

  /**
   * Start quality monitoring
   */
  private startQualityMonitoring(): void {
    if (this.qualityTimer) return;

    this.qualityTimer = setInterval(() => {
      this.updateQuality();
    }, this.config.qualityCheckInterval);
  }

  /**
   * Handle ping failure
   */
  private handlePingFailure(): void {
    if (this.offlineTimer) return; // Already handling

    this.offlineTimer = setTimeout(() => {
      if (this.state === ConnectionState.CONNECTED) {
        this.setState(ConnectionState.DISCONNECTED, 'Ping failures detected');
      }
      this.offlineTimer = null;
    }, this.config.offlineDetectionTimeout);
  }

  /**
   * Calculate connection quality based on metrics
   */
  private calculateQuality(): ConnectionQuality {
    if (this.stateData.metrics.measurementCount === 0) {
      return ConnectionQuality.UNKNOWN;
    }

    const latency = this.stateData.metrics.latency;
    const packetLoss = this.stateData.metrics.packetLoss;

    // Determine quality based on thresholds
    if (latency <= this.config.latencyThreshold.excellent && 
        packetLoss <= this.config.packetLossThreshold.excellent) {
      return ConnectionQuality.EXCELLENT;
    } else if (latency <= this.config.latencyThreshold.good && 
               packetLoss <= this.config.packetLossThreshold.good) {
      return ConnectionQuality.GOOD;
    } else if (latency <= this.config.latencyThreshold.fair && 
               packetLoss <= this.config.packetLossThreshold.fair) {
      return ConnectionQuality.FAIR;
    } else {
      return ConnectionQuality.POOR;
    }
  }

  /**
   * Add state to history
   */
  private addToStateHistory(state: ConnectionState, timestamp: number, reason?: string): void {
    this.stateData.stateHistory.push({ state, timestamp, reason });

    // Trim history if too large
    if (this.stateData.stateHistory.length > this.config.maxHistorySize) {
      this.stateData.stateHistory = this.stateData.stateHistory.slice(-this.config.maxHistorySize);
    }
  }

  /**
   * Update total downtime
   */
  private updateDowntime(): void {
    if (this.stateData.disconnectedAt && this.stateData.lastConnected) {
      const downtime = Date.now() - this.stateData.disconnectedAt;
      this.stateData.totalDowntime += downtime;
    }
  }

  /**
   * Calculate state frequency
   */
  private calculateStateFrequency(): Record<ConnectionState, number> {
    const frequency: Record<ConnectionState, number> = {
      [ConnectionState.CONNECTED]: 0,
      [ConnectionState.CONNECTING]: 0,
      [ConnectionState.DISCONNECTED]: 0,
      [ConnectionState.RECONNECTING]: 0,
      [ConnectionState.FAILED]: 0,
      [ConnectionState.OFFLINE]: 0
    };

    for (const entry of this.stateData.stateHistory) {
      frequency[entry.state]++;
    }

    return frequency;
  }

  /**
   * Calculate connection reliability
   */
  private calculateReliability(): number {
    if (this.stateData.stateHistory.length === 0) return 0;

    const connectedCount = this.stateData.stateHistory.filter(
      entry => entry.state === ConnectionState.CONNECTED
    ).length;

    return connectedCount / this.stateData.stateHistory.length;
  }

  /**
   * Stop all timers
   */
  private stopAllTimers(): void {
    this.stopPingMonitoring();

    if (this.qualityTimer) {
      clearInterval(this.qualityTimer);
      this.qualityTimer = null;
    }

    if (this.offlineTimer) {
      clearTimeout(this.offlineTimer);
      this.offlineTimer = null;
    }
  }
}

import { EventEmitter } from 'events';
import { OfflineOperationQueue } from './OfflineOperationQueue';
import { ConnectionStateManager, ConnectionState } from './ConnectionStateManager';
import { ReconnectionHandler } from './ReconnectionHandler';
import { SynchronizationRecovery } from './SynchronizationRecovery';
export class NetworkResilienceManager extends EventEmitter {
    config;
    offlineQueue;
    connectionState;
    reconnectionHandler;
    syncRecovery;
    isInitialized = false;
    isEnabled = true;
    documentId = null;
    userId = null;
    websocket = null;
    metricsTimer = null;
    persistenceTimer = null;
    syncInProgress = false;
    lastSyncTime = null;
    metrics;
    constructor(config = {}) {
        super();
        this.config = {
            enabled: true,
            offlineQueue: {},
            connectionState: {},
            reconnection: {},
            recovery: {},
            notifications: {
                enabled: true,
                showOfflineIndicator: true,
                showConnectionQuality: true,
                notifyOnReconnect: true,
                notifyOnSyncComplete: true
            },
            persistence: {
                enabled: true,
                storageKey: 'network-resilience-state',
                maxStorageSize: 50 * 1024 * 1024 // 50MB
            },
            performance: {
                enableMetrics: true,
                metricsInterval: 30000, // 30 seconds
                enableProfiling: false
            },
            ...config
        };
        this.metrics = {
            uptime: 0,
            totalDowntime: 0,
            connectionAttempts: 0,
            successfulReconnections: 0,
            queuedOperations: 0,
            syncedOperations: 0,
            pendingOperations: 0,
            averageReconnectTime: 0,
            dataLoss: 0,
            conflicts: 0
        };
        this.initializeComponents();
        this.setupEventHandlers();
    }
    /**
     * Initialize the network resilience system
     */
    async initialize(documentId, userId) {
        if (this.isInitialized) {
            console.warn('NetworkResilienceManager already initialized');
            return;
        }
        this.documentId = documentId;
        this.userId = userId;
        console.log(`Initializing network resilience for document ${documentId}, user ${userId}`);
        // Load persisted state
        if (this.config.persistence.enabled) {
            await this.loadPersistedState();
        }
        // Start monitoring
        this.startMetricsCollection();
        this.startPersistence();
        this.isInitialized = true;
        this.emit('initialized', { documentId, userId });
    }
    /**
     * Connect to WebSocket server
     */
    async connect(websocketUrl, authToken) {
        if (!this.isInitialized) {
            throw new Error('Manager not initialized. Call initialize() first.');
        }
        console.log(`Connecting to ${websocketUrl}`);
        this.connectionState.setState(ConnectionState.CONNECTING, 'User initiated connection');
        try {
            await this.establishWebSocketConnection(websocketUrl, authToken);
            this.connectionState.setState(ConnectionState.CONNECTED, 'WebSocket connected');
            // Process any queued operations
            await this.processQueuedOperations();
        }
        catch (error) {
            console.error('Connection failed:', error);
            this.connectionState.setState(ConnectionState.FAILED, 'Connection attempt failed');
            // Start reconnection process
            if (this.config.reconnection) {
                await this.startReconnection();
            }
            throw error;
        }
    }
    /**
     * Disconnect from server
     */
    disconnect(reason = 'User requested') {
        console.log(`Disconnecting: ${reason}`);
        this.reconnectionHandler.stopReconnection();
        if (this.websocket) {
            this.websocket.close(1000, reason);
            this.websocket = null;
        }
        this.connectionState.setState(ConnectionState.DISCONNECTED, reason);
    }
    /**
     * Queue operation for processing (offline or online)
     */
    queueOperation(operation) {
        if (!this.isEnabled) {
            throw new Error('Network resilience is disabled');
        }
        const operationId = this.offlineQueue.enqueue({
            ...operation,
            documentId: this.documentId || 'unknown',
            userId: this.userId || 'unknown'
        });
        this.metrics.queuedOperations++;
        this.updateMetrics();
        // Try to process immediately if online
        if (this.connectionState.isOnline() && !this.syncInProgress) {
            this.processQueuedOperations().catch(error => {
                console.error('Failed to process queued operations:', error);
            });
        }
        return operationId;
    }
    /**
     * Get current network status
     */
    getStatus() {
        return {
            isOnline: this.connectionState.isOnline(),
            connectionState: this.connectionState.getState(),
            connectionQuality: this.connectionState.getQuality(),
            reconnectionState: this.reconnectionHandler.getState(),
            queueSize: this.offlineQueue.size(),
            pendingSync: this.syncInProgress,
            lastSync: this.lastSyncTime,
            metrics: { ...this.metrics }
        };
    }
    /**
     * Force synchronization
     */
    async forceSync() {
        if (!this.isInitialized || !this.documentId) {
            throw new Error('Manager not properly initialized');
        }
        if (this.syncInProgress) {
            console.log('Sync already in progress');
            return null;
        }
        console.log('Forcing synchronization');
        this.syncInProgress = true;
        try {
            // Get current document state (would integrate with actual document system)
            const localState = await this.getCurrentDocumentState();
            // Perform recovery sync
            const delta = await this.syncRecovery.startRecovery(this.documentId, localState, () => this.getServerDocumentState());
            this.lastSyncTime = Date.now();
            this.metrics.syncedOperations += delta.operations.length;
            this.metrics.conflicts += delta.conflicts.length;
            this.emit('sync_completed', {
                operationsSynced: delta.operations.length,
                conflicts: delta.conflicts.length,
                duration: Date.now() - (this.lastSyncTime - 1000) // Approximate
            });
            return delta;
        }
        finally {
            this.syncInProgress = false;
        }
    }
    /**
     * Get comprehensive metrics
     */
    getMetrics() {
        return {
            ...this.metrics,
            pendingOperations: this.offlineQueue.size(),
            ...this.connectionState.getStatistics(),
            ...this.reconnectionHandler.getStats(),
            ...this.syncRecovery.getStats()
        };
    }
    /**
     * Enable or disable network resilience
     */
    setEnabled(enabled) {
        this.isEnabled = enabled;
        if (!enabled) {
            this.reconnectionHandler.stopReconnection();
        }
        this.emit('enabled_changed', enabled);
    }
    /**
     * Clear all queued operations
     */
    clearQueue() {
        const clearedCount = this.offlineQueue.size();
        this.offlineQueue.clear();
        this.emit('queue_cleared', clearedCount);
    }
    /**
     * Export current state for debugging
     */
    exportState() {
        return {
            config: this.config,
            status: this.getStatus(),
            metrics: this.getMetrics(),
            queuedOperations: this.offlineQueue.getMetrics(),
            connectionHistory: this.connectionState.getStateData().stateHistory,
            reconnectionAttempts: this.reconnectionHandler.getRecentAttempts(),
            pendingConflicts: this.syncRecovery.getPendingConflicts(),
            timestamp: Date.now()
        };
    }
    /**
     * Cleanup and shutdown
     */
    cleanup() {
        console.log('Cleaning up NetworkResilienceManager');
        this.disconnect('Manager cleanup');
        this.stopMetricsCollection();
        this.stopPersistence();
        this.offlineQueue.cleanup();
        this.connectionState.cleanup();
        this.reconnectionHandler.cleanup();
        this.syncRecovery.cleanup();
        this.removeAllListeners();
        this.isInitialized = false;
    }
    /**
     * Initialize sub-components
     */
    initializeComponents() {
        // Initialize offline queue
        this.offlineQueue = new OfflineOperationQueue({
            ...this.config.offlineQueue,
            storageKey: `${this.config.persistence.storageKey}-queue`
        });
        // Initialize connection state manager
        this.connectionState = new ConnectionStateManager(this.config.connectionState);
        // Initialize reconnection handler
        this.reconnectionHandler = new ReconnectionHandler(this.config.reconnection);
        // Initialize sync recovery
        this.syncRecovery = new SynchronizationRecovery(this.config.recovery);
        // Set up reconnection factory
        this.reconnectionHandler.setConnectionFactory(async () => {
            try {
                // Attempt to reconnect WebSocket
                if (this.websocket) {
                    this.websocket.close();
                }
                // This would use the last known URL and auth
                // For now, just simulate reconnection
                await new Promise(resolve => setTimeout(resolve, 1000));
                return Math.random() > 0.3; // 70% success rate for simulation
            }
            catch (error) {
                console.error('Reconnection attempt failed:', error);
                return false;
            }
        });
    }
    /**
     * Set up event handlers between components
     */
    setupEventHandlers() {
        // Connection state events
        this.connectionState.on('state_changed', (event) => {
            this.emit('connection_state_changed', event);
            if (event.newState === ConnectionState.DISCONNECTED) {
                this.startReconnection();
            }
            else if (event.newState === ConnectionState.CONNECTED) {
                this.processQueuedOperations();
            }
        });
        this.connectionState.on('quality_changed', (event) => {
            this.emit('connection_quality_changed', event);
        });
        // Reconnection events
        this.reconnectionHandler.on('reconnection_success', (event) => {
            this.metrics.successfulReconnections++;
            this.metrics.averageReconnectTime = (this.metrics.averageReconnectTime * 0.8) + (event.duration * 0.2);
            this.emit('reconnection_success', event);
            this.processQueuedOperations();
        });
        this.reconnectionHandler.on('reconnection_failed', (event) => {
            this.emit('reconnection_failed', event);
        });
        // Queue events
        this.offlineQueue.on('operation_queued', (operation) => {
            this.emit('operation_queued', operation);
        });
        this.offlineQueue.on('operation_success', (operation) => {
            this.metrics.syncedOperations++;
            this.emit('operation_synced', operation);
        });
        this.offlineQueue.on('operation_failed', (operation, error) => {
            this.emit('operation_failed', operation, error);
        });
        // Sync recovery events
        this.syncRecovery.on('recovery_success', (event) => {
            this.emit('sync_recovery_success', event);
        });
        this.syncRecovery.on('conflict_detected', (conflict) => {
            this.metrics.conflicts++;
            this.emit('conflict_detected', conflict);
        });
    }
    /**
     * Establish WebSocket connection
     */
    async establishWebSocketConnection(url, authToken) {
        return new Promise((resolve, reject) => {
            try {
                this.websocket = new WebSocket(url);
                this.websocket.onopen = () => {
                    console.log('WebSocket connected');
                    // Send authentication if provided
                    if (authToken && this.documentId && this.userId) {
                        this.websocket?.send(JSON.stringify({
                            type: 'auth_request',
                            payload: {
                                token: authToken,
                                documentId: this.documentId,
                                userId: this.userId,
                                userName: 'User', // Would come from user context
                                platform: navigator.platform
                            }
                        }));
                    }
                    resolve();
                };
                this.websocket.onerror = (error) => {
                    console.error('WebSocket error:', error);
                    reject(new Error('WebSocket connection failed'));
                };
                this.websocket.onclose = (event) => {
                    console.log(`WebSocket closed: ${event.code} - ${event.reason}`);
                    this.connectionState.setState(ConnectionState.DISCONNECTED, event.reason || 'Connection closed');
                };
                this.websocket.onmessage = (event) => {
                    this.handleWebSocketMessage(event);
                };
                // Connection timeout
                setTimeout(() => {
                    if (this.websocket?.readyState !== WebSocket.OPEN) {
                        this.websocket?.close();
                        reject(new Error('WebSocket connection timeout'));
                    }
                }, 10000);
            }
            catch (error) {
                reject(error);
            }
        });
    }
    /**
     * Handle incoming WebSocket messages
     */
    handleWebSocketMessage(event) {
        try {
            const message = JSON.parse(event.data);
            switch (message.type) {
                case 'auth_response':
                    if (message.payload.success) {
                        console.log('Authentication successful');
                    }
                    else {
                        console.error('Authentication failed:', message.payload.message);
                    }
                    break;
                case 'graph_update':
                    this.handleRemoteGraphUpdate(message.payload);
                    break;
                case 'conflict_detected':
                    this.handleConflictDetected(message.payload);
                    break;
                case 'pong':
                    this.connectionState.updateMetrics({
                        latency: Date.now() - message.payload.timestamp
                    });
                    break;
                default:
                    console.log('Unhandled message type:', message.type);
            }
        }
        catch (error) {
            console.error('Failed to parse WebSocket message:', error);
        }
    }
    /**
     * Start reconnection process
     */
    async startReconnection() {
        if (!this.isEnabled || this.reconnectionHandler.isReconnecting()) {
            return;
        }
        this.metrics.connectionAttempts++;
        await this.reconnectionHandler.startReconnection();
    }
    /**
     * Process queued operations
     */
    async processQueuedOperations() {
        if (!this.connectionState.isOnline() || this.syncInProgress) {
            return;
        }
        const batch = this.offlineQueue.dequeue(10); // Process in small batches
        if (batch.length === 0) {
            return;
        }
        console.log(`Processing ${batch.length} queued operations`);
        for (const operation of batch) {
            try {
                await this.sendOperationToServer(operation);
                this.offlineQueue.markSuccess(operation.id);
            }
            catch (error) {
                console.error(`Failed to process operation ${operation.id}:`, error);
                this.offlineQueue.markFailure(operation.id, error);
            }
        }
    }
    /**
     * Send operation to server
     */
    async sendOperationToServer(operation) {
        if (!this.websocket || this.websocket.readyState !== WebSocket.OPEN) {
            throw new Error('WebSocket not connected');
        }
        return new Promise((resolve, reject) => {
            const message = {
                type: operation.type,
                payload: operation.payload,
                messageId: operation.id
            };
            // Set up response handler
            const handleResponse = (event) => {
                try {
                    const response = JSON.parse(event.data);
                    if (response.messageId === operation.id) {
                        this.websocket?.removeEventListener('message', handleResponse);
                        if (response.type.includes('error')) {
                            reject(new Error(response.payload.error));
                        }
                        else {
                            resolve();
                        }
                    }
                }
                catch (error) {
                    // Ignore parsing errors for other messages
                }
            };
            this.websocket.addEventListener('message', handleResponse);
            this.websocket.send(JSON.stringify(message));
            // Timeout after 10 seconds
            setTimeout(() => {
                this.websocket?.removeEventListener('message', handleResponse);
                reject(new Error('Operation timeout'));
            }, 10000);
        });
    }
    /**
     * Handle remote graph updates
     */
    handleRemoteGraphUpdate(payload) {
        // This would integrate with the actual graph system
        this.emit('remote_update', payload);
    }
    /**
     * Handle conflict detection
     */
    handleConflictDetected(payload) {
        this.metrics.conflicts++;
        this.emit('conflict_detected', payload);
    }
    /**
     * Get current document state (stub)
     */
    async getCurrentDocumentState() {
        // This would integrate with the actual document/graph system
        return {
            version: 1,
            checksum: 'placeholder',
            lastModified: Date.now(),
            operations: [],
            metadata: {}
        };
    }
    /**
     * Get server document state (stub)
     */
    async getServerDocumentState() {
        // This would make an HTTP request to get server state
        return {
            version: 2,
            checksum: 'server-placeholder',
            lastModified: Date.now(),
            operations: [],
            metadata: {}
        };
    }
    /**
     * Start metrics collection
     */
    startMetricsCollection() {
        if (!this.config.performance.enableMetrics)
            return;
        this.metricsTimer = setInterval(() => {
            this.updateMetrics();
        }, this.config.performance.metricsInterval);
    }
    /**
     * Stop metrics collection
     */
    stopMetricsCollection() {
        if (this.metricsTimer) {
            clearInterval(this.metricsTimer);
            this.metricsTimer = null;
        }
    }
    /**
     * Update metrics
     */
    updateMetrics() {
        const queueMetrics = this.offlineQueue.getMetrics();
        const connectionStats = this.connectionState.getStatistics();
        this.metrics.pendingOperations = queueMetrics.pendingOperations;
        this.metrics.uptime = connectionStats.uptime;
        this.metrics.totalDowntime = connectionStats.totalDowntime;
        this.emit('metrics_updated', this.metrics);
    }
    /**
     * Start persistence
     */
    startPersistence() {
        if (!this.config.persistence.enabled)
            return;
        this.persistenceTimer = setInterval(() => {
            this.saveState();
        }, 60000); // Save every minute
    }
    /**
     * Stop persistence
     */
    stopPersistence() {
        if (this.persistenceTimer) {
            clearInterval(this.persistenceTimer);
            this.persistenceTimer = null;
        }
    }
    /**
     * Save current state to storage
     */
    saveState() {
        if (typeof localStorage === 'undefined')
            return;
        try {
            const state = {
                metrics: this.metrics,
                lastSync: this.lastSyncTime,
                timestamp: Date.now()
            };
            localStorage.setItem(this.config.persistence.storageKey, JSON.stringify(state));
        }
        catch (error) {
            console.error('Failed to save state:', error);
        }
    }
    /**
     * Load persisted state
     */
    async loadPersistedState() {
        if (typeof localStorage === 'undefined')
            return;
        try {
            const stored = localStorage.getItem(this.config.persistence.storageKey);
            if (!stored)
                return;
            const state = JSON.parse(stored);
            // Restore metrics
            if (state.metrics) {
                this.metrics = { ...this.metrics, ...state.metrics };
            }
            if (state.lastSync) {
                this.lastSyncTime = state.lastSync;
            }
            console.log('Restored persisted state');
        }
        catch (error) {
            console.error('Failed to load persisted state:', error);
        }
    }
}

import { EventEmitter } from 'events';
import { OfflineOperationQueue, QueuedOperation, OfflineQueueConfig } from './OfflineOperationQueue';
import { ConnectionStateManager, ConnectionState, ConnectionQuality, ConnectionStateConfig } from './ConnectionStateManager';
import { ReconnectionHandler, ReconnectionState, ReconnectionConfig } from './ReconnectionHandler';
import { SynchronizationRecovery, DocumentState, SyncDelta, RecoveryConfig } from './SynchronizationRecovery';

export interface NetworkResilienceConfig {
  enabled: boolean;
  offlineQueue: Partial<OfflineQueueConfig>;
  connectionState: Partial<ConnectionStateConfig>;
  reconnection: Partial<ReconnectionConfig>;
  recovery: Partial<RecoveryConfig>;
  notifications: {
    enabled: boolean;
    showOfflineIndicator: boolean;
    showConnectionQuality: boolean;
    notifyOnReconnect: boolean;
    notifyOnSyncComplete: boolean;
  };
  persistence: {
    enabled: boolean;
    storageKey: string;
    maxStorageSize: number;
  };
  performance: {
    enableMetrics: boolean;
    metricsInterval: number;
    enableProfiling: boolean;
  };
}

export interface ResilienceMetrics {
  uptime: number;
  totalDowntime: number;
  connectionAttempts: number;
  successfulReconnections: number;
  queuedOperations: number;
  syncedOperations: number;
  pendingOperations: number;
  averageReconnectTime: number;
  dataLoss: number;
  conflicts: number;
}

export interface NetworkStatus {
  isOnline: boolean;
  connectionState: ConnectionState;
  connectionQuality: ConnectionQuality;
  reconnectionState: ReconnectionState;
  queueSize: number;
  pendingSync: boolean;
  lastSync: number | null;
  metrics: ResilienceMetrics;
}

export class NetworkResilienceManager extends EventEmitter {
  private config: NetworkResilienceConfig;
  private offlineQueue: OfflineOperationQueue;
  private connectionState: ConnectionStateManager;
  private reconnectionHandler: ReconnectionHandler;
  private syncRecovery: SynchronizationRecovery;

  private isInitialized: boolean = false;
  private isEnabled: boolean = true;
  private documentId: string | null = null;
  private userId: string | null = null;
  private websocket: WebSocket | null = null;

  private metricsTimer: NodeJS.Timeout | null = null;
  private persistenceTimer: NodeJS.Timeout | null = null;
  private syncInProgress: boolean = false;
  private lastSyncTime: number | null = null;

  private metrics: ResilienceMetrics;

  constructor(config: Partial<NetworkResilienceConfig> = {}) {
    super();

    this.config = {
      enabled: true,
      offlineQueue: {},
      connectionState: {},
      reconnection: {},
      recovery: {},
      notifications: {
        enabled: true,
        showOfflineIndicator: true,
        showConnectionQuality: true,
        notifyOnReconnect: true,
        notifyOnSyncComplete: true
      },
      persistence: {
        enabled: true,
        storageKey: 'network-resilience-state',
        maxStorageSize: 50 * 1024 * 1024 // 50MB
      },
      performance: {
        enableMetrics: true,
        metricsInterval: 30000, // 30 seconds
        enableProfiling: false
      },
      ...config
    };

    this.metrics = {
      uptime: 0,
      totalDowntime: 0,
      connectionAttempts: 0,
      successfulReconnections: 0,
      queuedOperations: 0,
      syncedOperations: 0,
      pendingOperations: 0,
      averageReconnectTime: 0,
      dataLoss: 0,
      conflicts: 0
    };

    this.initializeComponents();
    this.setupEventHandlers();
  }

  /**
   * Initialize the network resilience system
   */
  async initialize(documentId: string, userId: string): Promise<void> {
    if (this.isInitialized) {
      console.warn('NetworkResilienceManager already initialized');
      return;
    }

    this.documentId = documentId;
    this.userId = userId;

    console.log(`Initializing network resilience for document ${documentId}, user ${userId}`);

    // Load persisted state
    if (this.config.persistence.enabled) {
      await this.loadPersistedState();
    }

    // Start monitoring
    this.startMetricsCollection();
    this.startPersistence();

    this.isInitialized = true;
    this.emit('initialized', { documentId, userId });
  }

  /**
   * Connect to WebSocket server
   */
  async connect(websocketUrl: string, authToken?: string): Promise<void> {
    if (!this.isInitialized) {
      throw new Error('Manager not initialized. Call initialize() first.');
    }

    console.log(`Connecting to ${websocketUrl}`);
    this.connectionState.setState(ConnectionState.CONNECTING, 'User initiated connection');

    try {
      await this.establishWebSocketConnection(websocketUrl, authToken);
      this.connectionState.setState(ConnectionState.CONNECTED, 'WebSocket connected');

      // Process any queued operations
      await this.processQueuedOperations();

    } catch (error) {
      console.error('Connection failed:', error);
      this.connectionState.setState(ConnectionState.FAILED, 'Connection attempt failed');

      // Start reconnection process
      if (this.config.reconnection) {
        await this.startReconnection();
      }

      throw error;
    }
  }

  /**
   * Disconnect from server
   */
  disconnect(reason: string = 'User requested'): void {
    console.log(`Disconnecting: ${reason}`);

    this.reconnectionHandler.stopReconnection();

    if (this.websocket) {
      this.websocket.close(1000, reason);
      this.websocket = null;
    }

    this.connectionState.setState(ConnectionState.DISCONNECTED, reason);
  }

  /**
   * Queue operation for processing (offline or online)
   */
  queueOperation(operation: Omit<QueuedOperation, 'id' | 'timestamp' | 'retryCount'>): string {
    if (!this.isEnabled) {
      throw new Error('Network resilience is disabled');
    }

    const operationId = this.offlineQueue.enqueue({
      ...operation,
      documentId: this.documentId || 'unknown',
      userId: this.userId || 'unknown'
    });

    this.metrics.queuedOperations++;
    this.updateMetrics();

    // Try to process immediately if online
    if (this.connectionState.isOnline() && !this.syncInProgress) {
      this.processQueuedOperations().catch(error => {
        console.error('Failed to process queued operations:', error);
      });
    }

    return operationId;
  }

  /**
   * Get current network status
   */
  getStatus(): NetworkStatus {
    return {
      isOnline: this.connectionState.isOnline(),
      connectionState: this.connectionState.getState(),
      connectionQuality: this.connectionState.getQuality(),
      reconnectionState: this.reconnectionHandler.getState(),
      queueSize: this.offlineQueue.size(),
      pendingSync: this.syncInProgress,
      lastSync: this.lastSyncTime,
      metrics: { ...this.metrics }
    };
  }

  /**
   * Force synchronization
   */
  async forceSync(): Promise<SyncDelta | null> {
    if (!this.isInitialized || !this.documentId) {
      throw new Error('Manager not properly initialized');
    }

    if (this.syncInProgress) {
      console.log('Sync already in progress');
      return null;
    }

    console.log('Forcing synchronization');
    this.syncInProgress = true;

    try {
      // Get current document state (would integrate with actual document system)
      const localState = await this.getCurrentDocumentState();

      // Perform recovery sync
      const delta = await this.syncRecovery.startRecovery(
        this.documentId,
        localState,
        () => this.getServerDocumentState()
      );

      this.lastSyncTime = Date.now();
      this.metrics.syncedOperations += delta.operations.length;
      this.metrics.conflicts += delta.conflicts.length;

      this.emit('sync_completed', {
        operationsSynced: delta.operations.length,
        conflicts: delta.conflicts.length,
        duration: Date.now() - (this.lastSyncTime - 1000) // Approximate
      });

      return delta;

    } finally {
      this.syncInProgress = false;
    }
  }

  /**
   * Get comprehensive metrics
   */
  getMetrics(): ResilienceMetrics {
    return {
      ...this.metrics,
      pendingOperations: this.offlineQueue.size(),
      ...this.connectionState.getStatistics(),
      ...this.reconnectionHandler.getStats(),
      ...this.syncRecovery.getStats()
    };
  }

  /**
   * Enable or disable network resilience
   */
  setEnabled(enabled: boolean): void {
    this.isEnabled = enabled;

    if (!enabled) {
      this.reconnectionHandler.stopReconnection();
    }

    this.emit('enabled_changed', enabled);
  }

  /**
   * Clear all queued operations
   */
  clearQueue(): void {
    const clearedCount = this.offlineQueue.size();
    this.offlineQueue.clear();

    this.emit('queue_cleared', clearedCount);
  }

  /**
   * Export current state for debugging
   */
  exportState(): any {
    return {
      config: this.config,
      status: this.getStatus(),
      metrics: this.getMetrics(),
      queuedOperations: this.offlineQueue.getMetrics(),
      connectionHistory: this.connectionState.getStateData().stateHistory,
      reconnectionAttempts: this.reconnectionHandler.getRecentAttempts(),
      pendingConflicts: this.syncRecovery.getPendingConflicts(),
      timestamp: Date.now()
    };
  }

  /**
   * Cleanup and shutdown
   */
  cleanup(): void {
    console.log('Cleaning up NetworkResilienceManager');

    this.disconnect('Manager cleanup');

    this.stopMetricsCollection();
    this.stopPersistence();

    this.offlineQueue.cleanup();
    this.connectionState.cleanup();
    this.reconnectionHandler.cleanup();
    this.syncRecovery.cleanup();

    this.removeAllListeners();
    this.isInitialized = false;
  }

  /**
   * Initialize sub-components
   */
  private initializeComponents(): void {
    // Initialize offline queue
    this.offlineQueue = new OfflineOperationQueue({
      ...this.config.offlineQueue,
      storageKey: `${this.config.persistence.storageKey}-queue`
    });

    // Initialize connection state manager
    this.connectionState = new ConnectionStateManager(this.config.connectionState);

    // Initialize reconnection handler
    this.reconnectionHandler = new ReconnectionHandler(this.config.reconnection);

    // Initialize sync recovery
    this.syncRecovery = new SynchronizationRecovery(this.config.recovery);

    // Set up reconnection factory
    this.reconnectionHandler.setConnectionFactory(async () => {
      try {
        // Attempt to reconnect WebSocket
        if (this.websocket) {
          this.websocket.close();
        }

        // This would use the last known URL and auth
        // For now, just simulate reconnection
        await new Promise(resolve => setTimeout(resolve, 1000));

        return Math.random() > 0.3; // 70% success rate for simulation

      } catch (error) {
        console.error('Reconnection attempt failed:', error);
        return false;
      }
    });
  }

  /**
   * Set up event handlers between components
   */
  private setupEventHandlers(): void {
    // Connection state events
    this.connectionState.on('state_changed', (event) => {
      this.emit('connection_state_changed', event);

      if (event.newState === ConnectionState.DISCONNECTED) {
        this.startReconnection();
      } else if (event.newState === ConnectionState.CONNECTED) {
        this.processQueuedOperations();
      }
    });

    this.connectionState.on('quality_changed', (event) => {
      this.emit('connection_quality_changed', event);
    });

    // Reconnection events
    this.reconnectionHandler.on('reconnection_success', (event) => {
      this.metrics.successfulReconnections++;
      this.metrics.averageReconnectTime = (this.metrics.averageReconnectTime * 0.8) + (event.duration * 0.2);

      this.emit('reconnection_success', event);
      this.processQueuedOperations();
    });

    this.reconnectionHandler.on('reconnection_failed', (event) => {
      this.emit('reconnection_failed', event);
    });

    // Queue events
    this.offlineQueue.on('operation_queued', (operation) => {
      this.emit('operation_queued', operation);
    });

    this.offlineQueue.on('operation_success', (operation) => {
      this.metrics.syncedOperations++;
      this.emit('operation_synced', operation);
    });

    this.offlineQueue.on('operation_failed', (operation, error) => {
      this.emit('operation_failed', operation, error);
    });

    // Sync recovery events
    this.syncRecovery.on('recovery_success', (event) => {
      this.emit('sync_recovery_success', event);
    });

    this.syncRecovery.on('conflict_detected', (conflict) => {
      this.metrics.conflicts++;
      this.emit('conflict_detected', conflict);
    });
  }

  /**
   * Establish WebSocket connection
   */
  private async establishWebSocketConnection(url: string, authToken?: string): Promise<void> {
    return new Promise((resolve, reject) => {
      try {
        this.websocket = new WebSocket(url);

        this.websocket.onopen = () => {
          console.log('WebSocket connected');

          // Send authentication if provided
          if (authToken && this.documentId && this.userId) {
            this.websocket?.send(JSON.stringify({
              type: 'auth_request',
              payload: {
                token: authToken,
                documentId: this.documentId,
                userId: this.userId,
                userName: 'User', // Would come from user context
                platform: navigator.platform
              }
            }));
          }

          resolve();
        };

        this.websocket.onerror = (error) => {
          console.error('WebSocket error:', error);
          reject(new Error('WebSocket connection failed'));
        };

        this.websocket.onclose = (event) => {
          console.log(`WebSocket closed: ${event.code} - ${event.reason}`);
          this.connectionState.setState(ConnectionState.DISCONNECTED, event.reason || 'Connection closed');
        };

        this.websocket.onmessage = (event) => {
          this.handleWebSocketMessage(event);
        };

        // Connection timeout
        setTimeout(() => {
          if (this.websocket?.readyState !== WebSocket.OPEN) {
            this.websocket?.close();
            reject(new Error('WebSocket connection timeout'));
          }
        }, 10000);

      } catch (error) {
        reject(error);
      }
    });
  }

  /**
   * Handle incoming WebSocket messages
   */
  private handleWebSocketMessage(event: MessageEvent): void {
    try {
      const message = JSON.parse(event.data);

      switch (message.type) {
        case 'auth_response':
          if (message.payload.success) {
            console.log('Authentication successful');
          } else {
            console.error('Authentication failed:', message.payload.message);
          }
          break;

        case 'graph_update':
          this.handleRemoteGraphUpdate(message.payload);
          break;

        case 'conflict_detected':
          this.handleConflictDetected(message.payload);
          break;

        case 'pong':
          this.connectionState.updateMetrics({
            latency: Date.now() - message.payload.timestamp
          });
          break;

        default:
          console.log('Unhandled message type:', message.type);
      }

    } catch (error) {
      console.error('Failed to parse WebSocket message:', error);
    }
  }

  /**
   * Start reconnection process
   */
  private async startReconnection(): Promise<void> {
    if (!this.isEnabled || this.reconnectionHandler.isReconnecting()) {
      return;
    }

    this.metrics.connectionAttempts++;
    await this.reconnectionHandler.startReconnection();
  }

  /**
   * Process queued operations
   */
  private async processQueuedOperations(): Promise<void> {
    if (!this.connectionState.isOnline() || this.syncInProgress) {
      return;
    }

    const batch = this.offlineQueue.dequeue(10); // Process in small batches

    if (batch.length === 0) {
      return;
    }

    console.log(`Processing ${batch.length} queued operations`);

    for (const operation of batch) {
      try {
        await this.sendOperationToServer(operation);
        this.offlineQueue.markSuccess(operation.id);

      } catch (error) {
        console.error(`Failed to process operation ${operation.id}:`, error);
        this.offlineQueue.markFailure(operation.id, error as Error);
      }
    }
  }

  /**
   * Send operation to server
   */
  private async sendOperationToServer(operation: QueuedOperation): Promise<void> {
    if (!this.websocket || this.websocket.readyState !== WebSocket.OPEN) {
      throw new Error('WebSocket not connected');
    }

    return new Promise((resolve, reject) => {
      const message = {
        type: operation.type,
        payload: operation.payload,
        messageId: operation.id
      };

      // Set up response handler
      const handleResponse = (event: MessageEvent) => {
        try {
          const response = JSON.parse(event.data);
          if (response.messageId === operation.id) {
            this.websocket?.removeEventListener('message', handleResponse);

            if (response.type.includes('error')) {
              reject(new Error(response.payload.error));
            } else {
              resolve();
            }
          }
        } catch (error) {
          // Ignore parsing errors for other messages
        }
      };

      this.websocket.addEventListener('message', handleResponse);
      this.websocket.send(JSON.stringify(message));

      // Timeout after 10 seconds
      setTimeout(() => {
        this.websocket?.removeEventListener('message', handleResponse);
        reject(new Error('Operation timeout'));
      }, 10000);
    });
  }

  /**
   * Handle remote graph updates
   */
  private handleRemoteGraphUpdate(payload: any): void {
    // This would integrate with the actual graph system
    this.emit('remote_update', payload);
  }

  /**
   * Handle conflict detection
   */
  private handleConflictDetected(payload: any): void {
    this.metrics.conflicts++;
    this.emit('conflict_detected', payload);
  }

  /**
   * Get current document state (stub)
   */
  private async getCurrentDocumentState(): Promise<DocumentState> {
    // This would integrate with the actual document/graph system
    return {
      version: 1,
      checksum: 'placeholder',
      lastModified: Date.now(),
      operations: [],
      metadata: {}
    };
  }

  /**
   * Get server document state (stub)
   */
  private async getServerDocumentState(): Promise<DocumentState> {
    // This would make an HTTP request to get server state
    return {
      version: 2,
      checksum: 'server-placeholder',
      lastModified: Date.now(),
      operations: [],
      metadata: {}
    };
  }

  /**
   * Start metrics collection
   */
  private startMetricsCollection(): void {
    if (!this.config.performance.enableMetrics) return;

    this.metricsTimer = setInterval(() => {
      this.updateMetrics();
    }, this.config.performance.metricsInterval);
  }

  /**
   * Stop metrics collection
   */
  private stopMetricsCollection(): void {
    if (this.metricsTimer) {
      clearInterval(this.metricsTimer);
      this.metricsTimer = null;
    }
  }

  /**
   * Update metrics
   */
  private updateMetrics(): void {
    const queueMetrics = this.offlineQueue.getMetrics();
    const connectionStats = this.connectionState.getStatistics();

    this.metrics.pendingOperations = queueMetrics.pendingOperations;
    this.metrics.uptime = connectionStats.uptime;
    this.metrics.totalDowntime = connectionStats.totalDowntime;

    this.emit('metrics_updated', this.metrics);
  }

  /**
   * Start persistence
   */
  private startPersistence(): void {
    if (!this.config.persistence.enabled) return;

    this.persistenceTimer = setInterval(() => {
      this.saveState();
    }, 60000); // Save every minute
  }

  /**
   * Stop persistence
   */
  private stopPersistence(): void {
    if (this.persistenceTimer) {
      clearInterval(this.persistenceTimer);
      this.persistenceTimer = null;
    }
  }

  /**
   * Save current state to storage
   */
  private saveState(): void {
    if (typeof localStorage === 'undefined') return;

    try {
      const state = {
        metrics: this.metrics,
        lastSync: this.lastSyncTime,
        timestamp: Date.now()
      };

      localStorage.setItem(this.config.persistence.storageKey, JSON.stringify(state));

    } catch (error) {
      console.error('Failed to save state:', error);
    }
  }

  /**
   * Load persisted state
   */
  private async loadPersistedState(): Promise<void> {
    if (typeof localStorage === 'undefined') return;

    try {
      const stored = localStorage.getItem(this.config.persistence.storageKey);
      if (!stored) return;

      const state = JSON.parse(stored);

      // Restore metrics
      if (state.metrics) {
        this.metrics = { ...this.metrics, ...state.metrics };
      }

      if (state.lastSync) {
        this.lastSyncTime = state.lastSync;
      }

      console.log('Restored persisted state');

    } catch (error) {
      console.error('Failed to load persisted state:', error);
    }
  }
}

import { EventEmitter } from 'events';
import { v4 as uuidv4 } from 'uuid';
export class OfflineOperationQueue extends EventEmitter {
    queue = [];
