            this.evictOldestOperation();
        }
        const queuedOperation = {
            id: uuidv4(),
            timestamp: Date.now(),
            retryCount: 0,
            expiresAt: Date.now() + this.config.operationTtlMs,
            maxRetries: operation.maxRetries || this.config.maxRetries,
            ...operation
        };
