     * Start cleanup timer
     */
    startCleanupTimer() {
        this.cleanupTimer = setInterval(() => {
            const now = Date.now();
            const initialLength = this.queue.length;
            // Remove expired operations
            this.queue = this.queue.filter(op => {
                if (op.expiresAt && op.expiresAt < now) {
