        }
    }
    /**
     * Load queue from localStorage
     */
    loadFromPersistence() {
        if (!this.config.persistToLocalStorage || typeof localStorage === 'undefined') {
            return;
        }
        try {
            const stored = localStorage.getItem(this.config.storageKey);
