            }
            this.queue = data.queue || [];
            this.failedOperations = new Map(data.failedOperations || []);
            this.updateMetrics();
            console.log(`Restored ${this.queue.length} operations from localStorage`);
            this.emit('queue_restored', this.queue.length);
        }
        catch (error) {
