        this.metrics.retryingOperations++;

        this.updateMetrics();
        this.persistToStorage();

        this.emit('operation_retry', operation, backoffTime);
        console.log(`Retrying operation ${operation.type} (attempt ${operation.retryCount}) after ${backoffTime}ms`);
