  });
}

/**
 * Utility function to validate Python code
 */
export async function validatePythonCode(
  code: string,
  options: Partial<PythonValidationRequest> = {}
): Promise<PythonValidationResult> {
  return pythonExecutorClient.validate({
    code,
    ...options,
  });
}

