      }
    }

    // Validate initial state
    if (this.initialState && !this.states.includes(this.initialState)) {
      errors.push(`Initial state '${this.initialState}' is not in states list`);
    }

    return {
      valid: errors.length === 0,
      errors,
      warnings
    };
  }
}

/**
