    const nodeConfig: AdvancedNodeConfig = {
      deterministic: true,
      cacheable: false, // Don't cache since output depends on state
      stateful: true,   // Maintains state between executions
      performanceHints: {
        expectedExecutionTime: 'fast',
        memoryUsage: 'low'
      }
    };

