    this.markovConfig = {
      maxTransitions: 1000,
      normalizeProbabilities: false,
      terminationStates: [],
      detectLoops: false,
      ...config
    };

    // Set up I/O specification
    const ioSpec = new IOSpecBuilder()
      .addInput({
        id: 'states',
        label: 'States',
        dataType: 'stringArray',
        required: false,
        defaultValue: [],
        description: 'Array of possible states'
      })
      .addInput({
        id: 'transitions',
        label: 'Transition Matrix',
        dataType: 'object',
        required: false,
        defaultValue: {},
        description: 'Transition probabilities between states'
      })
      .addInput({
        id: 'initialState',
        label: 'Initial State',
        dataType: 'string',
        required: false,
        defaultValue: '',
        description: 'Starting state for the Markov chain'
      })
      .addTextOutput('result', 'Current State')
      .build();

