      return {
        valid: false,
        errors: [`Validation service error: ${error.message}`],
        warnings: [],
      };
    }
  }

  /**
   * Check if Python executor service is available
   */
  async isServiceAvailable(): Promise<boolean> {
    try {
      await this.pythonClient.health();
      return true;
    } catch {
      return false;
    }
