      const builtNode = conditional('grades')
        .if('score >= 90', 'A')
        .elseIf('score >= 80', 'B')
        .elseIf('score >= 70', 'C')
        .elseIf('score >= 60', 'D')
        .else('F')
        .build('grade-node');

      context.variables.score = 85;
      expect(builtNode.run(context)).toBe('B');

      context.variables.score = 55;
      expect(builtNode.run(context)).toBe('F');
    });
  });
});

