      // Should progress linearly
      expect(matrix.transition('first', () => 0.5)).toBe('second');
      expect(matrix.transition('second', () => 0.5)).toBe('third');
      expect(matrix.transition('third', () => 0.5)).toBe('third'); // Stay at end
