  LockRequest, 
  LockPolicy,
  WorkflowLock,
  LockConflict,
  LockQueue,
  LockNotification,
  LockingStatistics
} from '../types/locking';

const API_BASE = process.env.REACT_APP_API_BASE || 'http://localhost:8000';

interface LockingStore extends LockingState, LockingActions {}

const initialState: LockingState = {
  locks: [],
  conflicts: [],
  queue: [],
  notifications: [],
  statistics: {
    total_locks: 0,
    active_locks: 0,
    expired_locks: 0,
    broken_locks: 0,
    by_type: {},
    by_user: {},
    avg_lock_duration_minutes: 0,
    conflict_rate: 0,
    most_contended_resources: []
  },
  policy: null,
  isLoading: false,
  error: null
};

export const useLockingStore = create<LockingStore>()(
  devtools(
    (set, get) => ({
      ...initialState,

      // Utility actions
      clearError: () => set({ error: null }),
      setLoading: (loading: boolean) => set({ isLoading: loading }),

      // Lock management
      fetchLocks: async (workspaceId: string) => {
        set({ isLoading: true, error: null });
        try {
          const response = await fetch(`${API_BASE}/api/locking/workspaces/${workspaceId}/locks`);
          if (!response.ok) throw new Error('Failed to fetch locks');

          const data = await response.json();
          set({ locks: data.locks || [], isLoading: false });
        } catch (error) {
          set({ 
            error: error instanceof Error ? error.message : 'Failed to fetch locks',
            isLoading: false 
          });
        }
      },

      acquireLock: async (request: LockRequest) => {
        set({ isLoading: true, error: null });
        try {
          const response = await fetch(`${API_BASE}/api/locking/locks/acquire`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(request)
          });

          const data = await response.json();

          if (!response.ok) {
            set({ error: data.error || 'Failed to acquire lock', isLoading: false });
            return { success: false, error: data.error };
          }

          // Refresh locks after successful acquisition
          await get().fetchLocks(request.resource_id);

          set({ isLoading: false });
          return { success: true };
        } catch (error) {
          const errorMessage = error instanceof Error ? error.message : 'Failed to acquire lock';
          set({ error: errorMessage, isLoading: false });
          return { success: false, error: errorMessage };
        }
      },

      releaseLock: async (lockId: string, userId: string) => {
        set({ isLoading: true, error: null });
        try {
          const response = await fetch(`${API_BASE}/api/locking/locks/${lockId}`, {
            method: 'DELETE',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ user_id: userId })
          });

          const data = await response.json();

          if (!response.ok) {
            set({ error: data.error || 'Failed to release lock', isLoading: false });
            return { success: false, error: data.error };
          }

          // Remove lock from local state
          set(state => ({
            locks: state.locks.filter(lock => lock.id !== lockId),
            isLoading: false
          }));

          return { success: true };
        } catch (error) {
          const errorMessage = error instanceof Error ? error.message : 'Failed to release lock';
          set({ error: errorMessage, isLoading: false });
          return { success: false, error: errorMessage };
        }
      },

      breakLock: async (lockId: string, userId: string, justification?: string) => {
        set({ isLoading: true, error: null });
        try {
          const response = await fetch(`${API_BASE}/api/locking/locks/break`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              lock_id: lockId,
              breaker_user_id: userId,
              justification
            })
          });

          const data = await response.json();

          if (!response.ok) {
            set({ error: data.error || 'Failed to break lock', isLoading: false });
            return { success: false, error: data.error };
          }

          // Remove lock from local state
          set(state => ({
            locks: state.locks.filter(lock => lock.id !== lockId),
            isLoading: false
          }));

          return { success: true };
        } catch (error) {
          const errorMessage = error instanceof Error ? error.message : 'Failed to break lock';
          set({ error: errorMessage, isLoading: false });
          return { success: false, error: errorMessage };
        }
      },

      // Conflict management
      fetchConflicts: async (workspaceId: string, status?: string) => {
        set({ isLoading: true, error: null });
        try {
          const url = new URL(`${API_BASE}/api/locking/workspaces/${workspaceId}/lock-conflicts`);
          if (status) url.searchParams.append('status', status);

          const response = await fetch(url.toString());
          if (!response.ok) throw new Error('Failed to fetch conflicts');

          const data = await response.json();
          set({ conflicts: data.conflicts || [], isLoading: false });
        } catch (error) {
          set({ 
            error: error instanceof Error ? error.message : 'Failed to fetch conflicts',
            isLoading: false 
          });
        }
      },

      resolveLockConflict: async (conflictId: string, resolution: string, userId: string) => {
        set({ isLoading: true, error: null });
        try {
          const response = await fetch(`${API_BASE}/api/locking/lock-conflicts/${conflictId}/resolve`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ resolution, user_id: userId })
          });

          const data = await response.json();

          if (!response.ok) {
            set({ error: data.error || 'Failed to resolve conflict', isLoading: false });
            return { success: false, error: data.error };
          }

          // Update conflict in local state
          set(state => ({
            conflicts: state.conflicts.map(conflict =>
              conflict.id === conflictId
                ? { ...conflict, status: 'resolved' as const, resolved_at: new Date().toISOString() }
                : conflict
            ),
            isLoading: false
          }));

          return { success: true };
        } catch (error) {
          const errorMessage = error instanceof Error ? error.message : 'Failed to resolve conflict';
          set({ error: errorMessage, isLoading: false });
          return { success: false, error: errorMessage };
        }
      },

      // Queue management
      fetchQueue: async (workspaceId: string) => {
        set({ isLoading: true, error: null });
        try {
          const response = await fetch(`${API_BASE}/api/locking/workspaces/${workspaceId}/lock-queue`);
          if (!response.ok) throw new Error('Failed to fetch queue');

          const data = await response.json();
          set({ queue: data.queue || [], isLoading: false });
        } catch (error) {
          set({ 
            error: error instanceof Error ? error.message : 'Failed to fetch queue',
            isLoading: false 
          });
        }
      },

      removeFromQueue: async (queueId: string, userId: string) => {
        set({ isLoading: true, error: null });
        try {
          const response = await fetch(`${API_BASE}/api/locking/lock-queue/${queueId}`, {
            method: 'DELETE',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ user_id: userId })
          });

          const data = await response.json();

          if (!response.ok) {
            set({ error: data.error || 'Failed to remove from queue', isLoading: false });
            return { success: false, error: data.error };
          }

          // Remove from local state
          set(state => ({
            queue: state.queue.filter(item => item.id !== queueId),
            isLoading: false
          }));

          return { success: true };
        } catch (error) {
          const errorMessage = error instanceof Error ? error.message : 'Failed to remove from queue';
          set({ error: errorMessage, isLoading: false });
          return { success: false, error: errorMessage };
        }
      },

      // Notifications
      fetchNotifications: async (userId: string, unreadOnly = false) => {
        set({ isLoading: true, error: null });
        try {
          const url = new URL(`${API_BASE}/api/locking/users/${userId}/lock-notifications`);
          if (unreadOnly) url.searchParams.append('unread_only', 'true');

          const response = await fetch(url.toString());
          if (!response.ok) throw new Error('Failed to fetch notifications');

          const data = await response.json();
          set({ notifications: data.notifications || [], isLoading: false });
        } catch (error) {
          set({ 
            error: error instanceof Error ? error.message : 'Failed to fetch notifications',
            isLoading: false 
          });
        }
      },

      markNotificationAsRead: async (notificationId: string) => {
        set({ isLoading: true, error: null });
        try {
          const response = await fetch(`${API_BASE}/api/locking/lock-notifications/${notificationId}/read`, {
            method: 'POST'
          });

          const data = await response.json();

          if (!response.ok) {
            set({ error: data.error || 'Failed to mark notification as read', isLoading: false });
            return { success: false, error: data.error };
          }

          // Update notification in local state
          set(state => ({
            notifications: state.notifications.map(notification =>
              notification.id === notificationId
                ? { ...notification, read_at: new Date().toISOString() }
                : notification
            ),
            isLoading: false
          }));

          return { success: true };
        } catch (error) {
          const errorMessage = error instanceof Error ? error.message : 'Failed to mark notification as read';
          set({ error: errorMessage, isLoading: false });
          return { success: false, error: errorMessage };
        }
      },

      // Statistics
      fetchStatistics: async (workspaceId: string) => {
        set({ isLoading: true, error: null });
        try {
          const response = await fetch(`${API_BASE}/api/locking/workspaces/${workspaceId}/lock-statistics`);
          if (!response.ok) throw new Error('Failed to fetch statistics');

          const data = await response.json();
          set({ statistics: data.statistics || initialState.statistics, isLoading: false });
        } catch (error) {
          set({ 
            error: error instanceof Error ? error.message : 'Failed to fetch statistics',
            isLoading: false 
          });
        }
      },

      // Policy management
      fetchPolicy: async (workspaceId: string) => {
        set({ isLoading: true, error: null });
        try {
          const response = await fetch(`${API_BASE}/api/locking/workspaces/${workspaceId}/lock-policy`);
          if (!response.ok) throw new Error('Failed to fetch policy');

          const data = await response.json();
          set({ policy: data.policy || null, isLoading: false });
        } catch (error) {
          set({ 
            error: error instanceof Error ? error.message : 'Failed to fetch policy',
            isLoading: false 
          });
        }
      },

      updatePolicy: async (workspaceId: string, policyData: Partial<LockPolicy>) => {
        set({ isLoading: true, error: null });
        try {
          const response = await fetch(`${API_BASE}/api/locking/workspaces/${workspaceId}/lock-policy`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(policyData)
          });

          const data = await response.json();

          if (!response.ok) {
            set({ error: data.error || 'Failed to update policy', isLoading: false });
            return { success: false, error: data.error };
          }

          set({ policy: data.policy, isLoading: false });
          return { success: true };
        } catch (error) {
          const errorMessage = error instanceof Error ? error.message : 'Failed to update policy';
          set({ error: errorMessage, isLoading: false });
          return { success: false, error: errorMessage };
        }
      }
    }),
    {
      name: 'locking-store',
      enabled: process.env.NODE_ENV === 'development'
    }
  )
);

// Epic 9.4 - Workflow Store
// Zustand store for workflow state management

import { create } from 'zustand';
import { devtools } from 'zustand/middleware';

// Type definitions for workflow entities
export interface WorkflowState {
  id: string;
  workspace_id: string;
  name: string;
  description?: string;
  color: string;
  icon?: string;
  is_initial: boolean;
  is_final: boolean;
  is_locked: boolean;
  sort_order: number;
  created_at: Date;
  updated_at: Date;
}

export interface WorkflowTransition {
  id: string;
  workspace_id: string;
  from_state_id?: string;
  to_state_id: string;
  name: string;
  description?: string;
  requires_approval: boolean;
  required_permissions: bigint;
  conditions: Record<string, any>;
  created_at: Date;
}

export interface WorkflowApproval {
  id: string;
  workspace_id: string;
  resource_id: string;
  transition_id: string;
  requester_id: string;
  status: 'pending' | 'approved' | 'rejected' | 'cancelled';
  requested_at: Date;
  due_date?: Date;
  priority: 'low' | 'medium' | 'high' | 'urgent';
  approved_by?: string;
  approved_at?: Date;
  rejection_reason?: string;
  approval_comment?: string;
  created_at: Date;
  updated_at: Date;
}

export interface WorkflowLock {
  id: string;
  workspace_id: string;
  resource_id: string;
  locked_by: string;
  lock_type: 'edit' | 'state_change' | 'delete' | 'custom';
  lock_reason?: string;
  locked_at: Date;
  expires_at?: Date;
  auto_release: boolean;
  metadata: Record<string, any>;
}

export interface WorkflowHistoryEntry {
  id: string;
  workspace_id: string;
  resource_id: string;
  action_type: string;
  previous_state_id?: string;
  new_state_id?: string;
  actor_id: string;
  action_timestamp: Date;
  approval_id?: string;
  transition_id?: string;
  comment?: string;
  metadata: Record<string, any>;
}

export interface WorkflowStatistics {
  total_states: number;
  total_transitions: number;
  pending_approvals: number;
  active_locks: number;
  scheduled_executions: number;
  resources_by_state: Record<string, number>;
  approval_stats: {
    pending: number;
    approved: number;
    rejected: number;
    cancelled: number;
    avg_approval_time_hours: number;
  };
  lock_stats: {
    total_active: number;
    by_type: Record<string, number>;
    avg_lock_duration_hours: number;
  };
  schedule_stats: {
    total_active: number;
    by_type: Record<string, number>;
    successful_executions: number;
    failed_executions: number;
  };
}

export interface StateTransitionResult {
  success: boolean;
  new_state_id?: string;
  approval_required?: boolean;
  approval_id?: string;
  error?: string;
  workflow_history_id?: string;
}

// Store interface
interface WorkflowStore {
  // State
  states: WorkflowState[];
  transitions: WorkflowTransition[];
  approvals: WorkflowApproval[];
  locks: WorkflowLock[];
  history: WorkflowHistoryEntry[];
  statistics: WorkflowStatistics | null;
  loading: boolean;
  error: string | null;

  // Actions - State Management
  fetchStates: (workspaceId: string) => Promise<void>;
  createState: (data: Partial<WorkflowState>) => Promise<WorkflowState>;
  updateState: (id: string, updates: Partial<WorkflowState>) => Promise<WorkflowState>;
  deleteState: (id: string) => Promise<void>;

  // Actions - Transition Management
  fetchTransitions: (workspaceId: string, fromStateId?: string) => Promise<void>;
  createTransition: (data: Partial<WorkflowTransition>) => Promise<WorkflowTransition>;
  deleteTransition: (id: string) => Promise<void>;

  // Actions - State Transitions
  transitionResourceState: (
    resourceId: string,
    toStateId: string,
    actorId: string,
    options?: {
      comment?: string;
      metadata?: Record<string, any>;
      force?: boolean;
      lockDuration?: number;
    }
  ) => Promise<StateTransitionResult>;

  // Actions - Approval Management
  fetchApprovals: (workspaceId: string, filters?: any) => Promise<void>;
  createApproval: (data: Partial<WorkflowApproval>) => Promise<WorkflowApproval>;
  approveWorkflow: (approvalId: string, approverId: string, comment?: string) => Promise<StateTransitionResult>;
  rejectWorkflow: (approvalId: string, rejectorId: string, reason: string) => Promise<boolean>;

  // Actions - Lock Management
  fetchLocks: (workspaceId: string, filters?: any) => Promise<void>;
  acquireLock: (
    resourceId: string,
    userId: string,
    lockType?: 'edit' | 'state_change' | 'delete' | 'custom',
    options?: {
      reason?: string;
      duration?: number;
      metadata?: Record<string, any>;
    }
  ) => Promise<WorkflowLock>;
  releaseLock: (lockId: string, userId: string) => Promise<boolean>;
  releaseLocksByResource: (resourceId: string, userId: string, lockType?: string) => Promise<number>;

  // Actions - History and Statistics
  fetchHistory: (workspaceId: string, filters?: any) => Promise<void>;
  fetchStatistics: (workspaceId: string) => Promise<void>;

  // Actions - Utilities
  validateStateTransition: (resourceId: string, toStateId: string) => Promise<{
    valid: boolean;
    transition?: WorkflowTransition;
    error?: string;
  }>;
  canUserTransitionState: (userId: string, resourceId: string, toStateId: string) => Promise<boolean>;
  isResourceLocked: (resourceId: string, lockType?: string) => Promise<boolean>;
  performMaintenance: () => Promise<any>;

  // Internal actions
  setLoading: (loading: boolean) => void;
  setError: (error: string | null) => void;
  clearError: () => void;
}

// API base URL
const API_BASE = process.env.REACT_APP_API_URL || 'http://localhost:8000';

// Utility function for API calls
async function apiCall(endpoint: string, options: RequestInit = {}) {
  const url = `${API_BASE}/api/workflow${endpoint}`;
  const response = await fetch(url, {
    ...options,
    headers: {
      'Content-Type': 'application/json',
      'x-user-id': 'current-user-id', // TODO: Get from auth context
      ...options.headers,
    },
  });

  if (!response.ok) {
    throw new Error(`API call failed: ${response.status} ${response.statusText}`);
  }

  return response.json();
}

// Create the store
export const useWorkflowStore = create<WorkflowStore>()(
  devtools(
    (set, get) => ({
      // Initial state
      states: [],
      transitions: [],
      approvals: [],
      locks: [],
      history: [],
      statistics: null,
      loading: false,
      error: null,

      // State management actions
      fetchStates: async (workspaceId: string) => {
        try {
          set({ loading: true, error: null });
          const states = await apiCall(`/states/${workspaceId}`);
          set({ states, loading: false });
        } catch (error) {
          set({ error: error instanceof Error ? error.message : 'Failed to fetch states', loading: false });
        }
      },

      createState: async (data: Partial<WorkflowState>) => {
        try {
          set({ loading: true, error: null });
          const newState = await apiCall('/states', {
            method: 'POST',
            body: JSON.stringify(data),
          });
          set(state => ({ 
            states: [...state.states, newState].sort((a, b) => a.sort_order - b.sort_order),
            loading: false 
          }));
          return newState;
        } catch (error) {
          set({ error: error instanceof Error ? error.message : 'Failed to create state', loading: false });
          throw error;
        }
      },

      updateState: async (id: string, updates: Partial<WorkflowState>) => {
        try {
          set({ loading: true, error: null });
          const updatedState = await apiCall(`/states/${id}`, {
            method: 'PUT',
            body: JSON.stringify(updates),
          });
          set(state => ({
            states: state.states.map(s => s.id === id ? updatedState : s),
            loading: false
          }));
          return updatedState;
        } catch (error) {
          set({ error: error instanceof Error ? error.message : 'Failed to update state', loading: false });
          throw error;
        }
      },

      deleteState: async (id: string) => {
        try {
          set({ loading: true, error: null });
          await apiCall(`/states/${id}`, { method: 'DELETE' });
          set(state => ({
            states: state.states.filter(s => s.id !== id),
            loading: false
          }));
        } catch (error) {
          set({ error: error instanceof Error ? error.message : 'Failed to delete state', loading: false });
          throw error;
        }
      },

      // Transition management actions
      fetchTransitions: async (workspaceId: string, fromStateId?: string) => {
        try {
          set({ loading: true, error: null });
          const queryParams = fromStateId ? `?from_state_id=${fromStateId}` : '';
          const transitions = await apiCall(`/transitions/${workspaceId}${queryParams}`);
          set({ transitions, loading: false });
        } catch (error) {
          set({ error: error instanceof Error ? error.message : 'Failed to fetch transitions', loading: false });
        }
      },

      createTransition: async (data: Partial<WorkflowTransition>) => {
        try {
          set({ loading: true, error: null });
          const newTransition = await apiCall('/transitions', {
            method: 'POST',
            body: JSON.stringify(data),
          });
          set(state => ({ 
            transitions: [...state.transitions, newTransition],
            loading: false 
          }));
          return newTransition;
        } catch (error) {
          set({ error: error instanceof Error ? error.message : 'Failed to create transition', loading: false });
          throw error;
        }
      },

      deleteTransition: async (id: string) => {
        try {
          set({ loading: true, error: null });
          await apiCall(`/transitions/${id}`, { method: 'DELETE' });
          set(state => ({
            transitions: state.transitions.filter(t => t.id !== id),
            loading: false
          }));
        } catch (error) {
          set({ error: error instanceof Error ? error.message : 'Failed to delete transition', loading: false });
          throw error;
        }
      },

      // State transition actions
      transitionResourceState: async (
        resourceId: string,
        toStateId: string,
        actorId: string,
        options = {}
      ) => {
        try {
          set({ loading: true, error: null });
          const result = await apiCall(`/resources/${resourceId}/transition`, {
            method: 'POST',
            body: JSON.stringify({
              to_state_id: toStateId,
              ...options,
            }),
          });
          set({ loading: false });
          return result;
        } catch (error) {
          set({ error: error instanceof Error ? error.message : 'Failed to transition state', loading: false });
          throw error;
        }
      },

      // Approval management actions
      fetchApprovals: async (workspaceId: string, filters = {}) => {
        try {
          set({ loading: true, error: null });
          const queryParams = new URLSearchParams(filters).toString();
          const approvals = await apiCall(`/approvals/${workspaceId}?${queryParams}`);
          set({ approvals, loading: false });
        } catch (error) {
          set({ error: error instanceof Error ? error.message : 'Failed to fetch approvals', loading: false });
        }
      },

      createApproval: async (data: Partial<WorkflowApproval>) => {
        try {
          set({ loading: true, error: null });
          const newApproval = await apiCall('/approvals', {
            method: 'POST',
            body: JSON.stringify(data),
          });
          set(state => ({ 
            approvals: [...state.approvals, newApproval],
            loading: false 
          }));
          return newApproval;
        } catch (error) {
          set({ error: error instanceof Error ? error.message : 'Failed to create approval', loading: false });
          throw error;
        }
      },

      approveWorkflow: async (approvalId: string, approverId: string, comment?: string) => {
        try {
          set({ loading: true, error: null });
          const result = await apiCall(`/approvals/${approvalId}/approve`, {
            method: 'POST',
            body: JSON.stringify({ comment }),
          });
          // Update approval status in local state
          set(state => ({
            approvals: state.approvals.map(a => 
              a.id === approvalId 
                ? { ...a, status: 'approved' as const, approved_by: approverId, approved_at: new Date() }
                : a
            ),
            loading: false
          }));
          return result;
        } catch (error) {
          set({ error: error instanceof Error ? error.message : 'Failed to approve workflow', loading: false });
          throw error;
        }
      },

      rejectWorkflow: async (approvalId: string, rejectorId: string, reason: string) => {
        try {
          set({ loading: true, error: null });
          const result = await apiCall(`/approvals/${approvalId}/reject`, {
            method: 'POST',
            body: JSON.stringify({ reason }),
          });
          // Update approval status in local state
          set(state => ({
            approvals: state.approvals.map(a => 
              a.id === approvalId 
                ? { ...a, status: 'rejected' as const, approved_by: rejectorId, rejection_reason: reason }
                : a
            ),
            loading: false
          }));
          return result;
        } catch (error) {
          set({ error: error instanceof Error ? error.message : 'Failed to reject workflow', loading: false });
          throw error;
        }
      },

      // Lock management actions
      fetchLocks: async (workspaceId: string, filters = {}) => {
        try {
          set({ loading: true, error: null });
          const queryParams = new URLSearchParams(filters).toString();
          const locks = await apiCall(`/locks/${workspaceId}?${queryParams}`);
          set({ locks, loading: false });
        } catch (error) {
          set({ error: error instanceof Error ? error.message : 'Failed to fetch locks', loading: false });
        }
      },

      acquireLock: async (
        resourceId: string,
        userId: string,
        lockType = 'edit',
        options = {}
      ) => {
        try {
          set({ loading: true, error: null });
          const newLock = await apiCall('/locks', {
            method: 'POST',
            body: JSON.stringify({
              resource_id: resourceId,
              lock_type: lockType,
              ...options,
            }),
          });
          set(state => ({ 
            locks: [...state.locks, newLock],
            loading: false 
          }));
          return newLock;
        } catch (error) {
          set({ error: error instanceof Error ? error.message : 'Failed to acquire lock', loading: false });
          throw error;
        }
      },

      releaseLock: async (lockId: string, userId: string) => {
        try {
          set({ loading: true, error: null });
          await apiCall(`/locks/${lockId}`, { method: 'DELETE' });
          set(state => ({
            locks: state.locks.filter(l => l.id !== lockId),
            loading: false
          }));
          return true;
        } catch (error) {
          set({ error: error instanceof Error ? error.message : 'Failed to release lock', loading: false });
          throw error;
        }
      },

      releaseLocksByResource: async (resourceId: string, userId: string, lockType?: string) => {
        try {
          set({ loading: true, error: null });
          const queryParams = lockType ? `?lock_type=${lockType}` : '';
          const result = await apiCall(`/locks/resource/${resourceId}${queryParams}`, {
            method: 'DELETE',
          });
          // Remove locks from local state
          set(state => ({
            locks: state.locks.filter(l => l.resource_id !== resourceId || (lockType && l.lock_type !== lockType)),
            loading: false
          }));
          return result.released_count;
        } catch (error) {
          set({ error: error instanceof Error ? error.message : 'Failed to release locks', loading: false });
          throw error;
        }
      },

      // History and statistics actions
      fetchHistory: async (workspaceId: string, filters = {}) => {
        try {
          set({ loading: true, error: null });
          const queryParams = new URLSearchParams(filters).toString();
          const history = await apiCall(`/history/${workspaceId}?${queryParams}`);
          set({ history, loading: false });
        } catch (error) {
          set({ error: error instanceof Error ? error.message : 'Failed to fetch history', loading: false });
        }
      },

      fetchStatistics: async (workspaceId: string) => {
        try {
          set({ loading: true, error: null });
          const statistics = await apiCall(`/statistics/${workspaceId}`);
          set({ statistics, loading: false });
        } catch (error) {
          set({ error: error instanceof Error ? error.message : 'Failed to fetch statistics', loading: false });
        }
      },

      // Utility actions
      validateStateTransition: async (resourceId: string, toStateId: string) => {
        try {
          return await apiCall(`/validate/transition?resource_id=${resourceId}&to_state_id=${toStateId}&user_id=current-user-id`);
        } catch (error) {
          return { valid: false, error: error instanceof Error ? error.message : 'Validation failed' };
        }
      },

      canUserTransitionState: async (userId: string, resourceId: string, toStateId: string) => {
        try {
          const result = await apiCall(`/validate/transition?resource_id=${resourceId}&to_state_id=${toStateId}&user_id=${userId}`);
          return result.can_transition;
        } catch (error) {
          return false;
        }
      },

      isResourceLocked: async (resourceId: string, lockType?: string) => {
        try {
          const queryParams = lockType ? `?lock_type=${lockType}` : '';
          const result = await apiCall(`/validate/lock?resource_id=${resourceId}${queryParams}`);
          return result.is_locked;
        } catch (error) {
          return false;
        }
      },

      performMaintenance: async () => {
        try {
          return await apiCall('/maintenance', { method: 'POST' });
        } catch (error) {
          throw error;
        }
      },

      // Internal actions
      setLoading: (loading: boolean) => set({ loading }),
      setError: (error: string | null) => set({ error }),
      clearError: () => set({ error: null }),
    }),
    {
      name: 'workflow-store',
    }
  )
);

