  version_tag?: string;
  workflow_state?: string;
  approval_status?: string;
}

export class VersionHistoryManager {
  private snapshots = new Map<string, VersionSnapshot>();
  private branches = new Map<string, Branch>();
  private changeEvents: ChangeEvent[] = [];
  private currentSessionId: string;

  constructor(
    private apiClient: any,
    private projectId: string,
    private userId: string
  ) {
    this.currentSessionId = crypto.randomUUID();
  }

  // Snapshot Management
  async createSnapshot(graphData: any, options: SnapshotCreationOptions = {}): Promise<VersionSnapshot> {
    try {
      // Prepare snapshot data
      const snapshotData = {
        project_id: this.projectId,
        graph_data: graphData,
        title: options.title,
        description: options.description,
        changelog: options.changelog,
        snapshot_type: options.snapshot_type || 'manual',
        trigger_event: options.trigger_event,
        version_tag: options.version_tag,
        workflow_state: options.workflow_state || 'draft',
        approval_status: options.approval_status,
        created_by: this.userId
      };

      const response = await this.apiClient.post('/api/version-snapshots', snapshotData);
      const snapshot = response.data;

      // Update local cache
      this.snapshots.set(snapshot.id, snapshot);

      // Record change event
      await this.recordChangeEvent({
        event_type: 'snapshot_created',
        event_data: {
          snapshot_id: snapshot.id,
          snapshot_type: snapshot.snapshot_type,
          version_number: snapshot.version_number
        },
        affected_nodes: this.extractNodeIds(graphData),
        change_magnitude: this.calculateChangeMagnitude(graphData)
      });

      return snapshot;
    } catch (error) {
      console.error('Failed to create snapshot:', error);
      throw error;
    }
  }

  async getSnapshots(filter: VersionHistoryFilter = {}): Promise<{ snapshots: VersionSnapshot[]; total: number }> {
    try {
      const params = new URLSearchParams();
      params.append('project_id', this.projectId);

      Object.entries(filter).forEach(([key, value]) => {
        if (value !== undefined) {
          params.append(key, String(value));
        }
      });

      const response = await this.apiClient.get(`/api/version-snapshots?${params}`);
      const result = response.data;

      // Update local cache
      result.snapshots.forEach((snapshot: VersionSnapshot) => {
        this.snapshots.set(snapshot.id, snapshot);
      });

      return result;
    } catch (error) {
      console.error('Failed to get snapshots:', error);
      throw error;
    }
  }

  async getSnapshot(snapshotId: string): Promise<VersionSnapshot> {
    try {
      // Check cache first
      if (this.snapshots.has(snapshotId)) {
        return this.snapshots.get(snapshotId)!;
      }

      const response = await this.apiClient.get(`/api/version-snapshots/${snapshotId}`);
      const snapshot = response.data;

      this.snapshots.set(snapshotId, snapshot);
      return snapshot;
    } catch (error) {
      console.error('Failed to get snapshot:', error);
      throw error;
    }
  }

  async getSnapshotData(snapshotId: string): Promise<any> {
    try {
      const response = await this.apiClient.get(`/api/version-snapshots/${snapshotId}/data`);
      return response.data;
    } catch (error) {
      console.error('Failed to get snapshot data:', error);
      throw error;
    }
  }

  async deleteSnapshot(snapshotId: string): Promise<void> {
    try {
      await this.apiClient.delete(`/api/version-snapshots/${snapshotId}`);
      this.snapshots.delete(snapshotId);

      // Record change event
      await this.recordChangeEvent({
        event_type: 'snapshot_deleted',
        event_data: { snapshot_id: snapshotId },
        affected_nodes: [],
        change_magnitude: 0
      });
    } catch (error) {
      console.error('Failed to delete snapshot:', error);
      throw error;
    }
  }

  // Diff Management
  async compareFreshSnapshots(fromSnapshotId: string, toSnapshotId: string): Promise<VersionDiff> {
    try {
      const response = await this.apiClient.get(`/api/version-diffs/${fromSnapshotId}/${toSnapshotId}`);
      return response.data;
    } catch (error) {
      console.error('Failed to compare snapshots:', error);
      throw error;
    }
  }

  async getSnapshotDiff(fromSnapshotId: string, toSnapshotId: string): Promise<VersionDiff> {
    try {
      // Try to get cached diff first
      const response = await this.apiClient.get(`/api/version-diffs/${fromSnapshotId}/${toSnapshotId}`);
      return response.data;
    } catch (error) {
      // If not cached, compute diff
      return await this.computeDiff(fromSnapshotId, toSnapshotId);
    }
  }

  private async computeDiff(fromSnapshotId: string, toSnapshotId: string): Promise<VersionDiff> {
    try {
      const response = await this.apiClient.post('/api/version-diffs/compute', {
        from_snapshot_id: fromSnapshotId,
        to_snapshot_id: toSnapshotId
      });
      return response.data;
    } catch (error) {
      console.error('Failed to compute diff:', error);
      throw error;
    }
  }

  // Branch Management
  async createBranch(
    name: string,
    options: {
      description?: string;
      branch_type?: 'feature' | 'hotfix' | 'experiment';
      parent_branch_id?: string;
      base_snapshot_id?: string;
      visibility?: 'private' | 'workspace' | 'public';
    } = {}
  ): Promise<Branch> {
    try {
      const branchData = {
        project_id: this.projectId,
        name,
        description: options.description,
        branch_type: options.branch_type || 'feature',
        parent_branch_id: options.parent_branch_id,
        base_snapshot_id: options.base_snapshot_id,
        visibility: options.visibility || 'workspace',
        created_by: this.userId
      };

      const response = await this.apiClient.post('/api/branches', branchData);
      const branch = response.data;

      this.branches.set(branch.id, branch);

      // Record change event
      await this.recordChangeEvent({
        event_type: 'branch_created',
        event_data: {
          branch_id: branch.id,
          branch_name: branch.name,
          branch_type: branch.branch_type
        },
        affected_nodes: [],
        change_magnitude: 0
      });

      return branch;
    } catch (error) {
      console.error('Failed to create branch:', error);
      throw error;
    }
  }

  async getBranches(): Promise<Branch[]> {
    try {
      const response = await this.apiClient.get(`/api/branches?project_id=${this.projectId}`);
      const branches = response.data;

      branches.forEach((branch: Branch) => {
        this.branches.set(branch.id, branch);
      });

      return branches;
    } catch (error) {
      console.error('Failed to get branches:', error);
      throw error;
    }
  }

  async switchBranch(branchName: string): Promise<Branch> {
    try {
      const response = await this.apiClient.post(`/api/branches/switch`, {
        project_id: this.projectId,
        branch_name: branchName
      });

      const branch = response.data.branch;
      this.branches.set(branch.id, branch);

      // Record change event
      await this.recordChangeEvent({
        event_type: 'branch_switched',
        event_data: {
          branch_name: branchName,
          head_snapshot_id: branch.head_snapshot_id
        },
        affected_nodes: [],
        change_magnitude: 0
      });

      return branch;
    } catch (error) {
      console.error('Failed to switch branch:', error);
      throw error;
    }
  }

  async mergeBranch(
    sourceBranchId: string,
    targetBranchId: string,
    options: {
      merge_message?: string;
      strategy?: 'merge' | 'squash' | 'rebase';
      delete_source?: boolean;
    } = {}
  ): Promise<VersionSnapshot> {
    try {
      const response = await this.apiClient.post('/api/branches/merge', {
        source_branch_id: sourceBranchId,
        target_branch_id: targetBranchId,
        merge_message: options.merge_message,
        strategy: options.strategy || 'merge',
        delete_source: options.delete_source || false
      });

      const mergeSnapshot = response.data;
      this.snapshots.set(mergeSnapshot.id, mergeSnapshot);

      // Record change event
      await this.recordChangeEvent({
        event_type: 'branch_merged',
        event_data: {
          source_branch_id: sourceBranchId,
          target_branch_id: targetBranchId,
          merge_snapshot_id: mergeSnapshot.id,
          strategy: options.strategy
        },
        affected_nodes: [],
        change_magnitude: 5 // Merges are significant changes
      });

      return mergeSnapshot;
    } catch (error) {
      console.error('Failed to merge branch:', error);
      throw error;
    }
  }

  // Change Event Tracking
  async recordChangeEvent(event: {
    event_type: string;
    event_data: any;
    affected_nodes: string[];
    change_magnitude: number;
    workflow_state?: string;
    approval_required?: boolean;
  }): Promise<ChangeEvent> {
    try {
      const eventData: Partial<ChangeEvent> = {
        project_id: this.projectId,
        event_type: event.event_type,
        event_data: event.event_data,
        author_id: this.userId,
        session_id: this.currentSessionId,
        occurred_at: new Date().toISOString(),
        affected_nodes: event.affected_nodes,
        affected_properties: this.extractAffectedProperties(event.event_data),
        change_magnitude: event.change_magnitude,
        workflow_state: event.workflow_state,
        approval_required: event.approval_required || false
      };

      const response = await this.apiClient.post('/api/change-events', eventData);
      const changeEvent = response.data;

      this.changeEvents.push(changeEvent);
      return changeEvent;
    } catch (error) {
      console.error('Failed to record change event:', error);
      throw error;
    }
  }

  async getChangeEvents(filter: {
    start_date?: string;
    end_date?: string;
    author_id?: string;
    event_types?: string[];
    limit?: number;
    offset?: number;
  } = {}): Promise<{ events: ChangeEvent[]; total: number }> {
    try {
      const params = new URLSearchParams();
      params.append('project_id', this.projectId);

      Object.entries(filter).forEach(([key, value]) => {
        if (value !== undefined) {
          if (Array.isArray(value)) {
            value.forEach(v => params.append(key, String(v)));
          } else {
            params.append(key, String(value));
          }
        }
      });

      const response = await this.apiClient.get(`/api/change-events?${params}`);
      return response.data;
    } catch (error) {
      console.error('Failed to get change events:', error);
      throw error;
    }
  }

  // Annotation Management
  async addAnnotation(
    snapshotId: string,
    annotation: {
      annotation_type?: 'comment' | 'review' | 'approval' | 'flag';
      title?: string;
      content_markdown: string;
      priority?: 'low' | 'normal' | 'high' | 'critical';
      target_element_id?: string;
      target_coordinates?: { x: number; y: number };
    }
  ): Promise<VersionAnnotation> {
    try {
      const annotationData = {
        snapshot_id: snapshotId,
        annotation_type: annotation.annotation_type || 'comment',
        title: annotation.title,
        content_markdown: annotation.content_markdown,
        priority: annotation.priority || 'normal',
        target_element_id: annotation.target_element_id,
        target_coordinates: annotation.target_coordinates,
        author_id: this.userId
      };

      const response = await this.apiClient.post('/api/version-annotations', annotationData);
      return response.data;
    } catch (error) {
      console.error('Failed to add annotation:', error);
      throw error;
    }
  }

  async getAnnotations(snapshotId: string): Promise<VersionAnnotation[]> {
    try {
      const response = await this.apiClient.get(`/api/version-annotations?snapshot_id=${snapshotId}`);
      return response.data;
    } catch (error) {
      console.error('Failed to get annotations:', error);
      throw error;
    }
  }

  async resolveAnnotation(annotationId: string, resolutionNote?: string): Promise<VersionAnnotation> {
    try {
      const response = await this.apiClient.put(`/api/version-annotations/${annotationId}/resolve`, {
        resolved_by: this.userId,
        resolution_note: resolutionNote
      });
      return response.data;
    } catch (error) {
      console.error('Failed to resolve annotation:', error);
      throw error;
    }
  }

  // Utility Methods
  private extractNodeIds(graphData: any): string[] {
    return graphData?.nodes?.map((node: any) => node.id) || [];
  }

  private extractAffectedProperties(eventData: any): string[] {
    // Extract property names from event data
    const properties: string[] = [];

    if (eventData.property_changes) {
      properties.push(...Object.keys(eventData.property_changes));
    }

    if (eventData.modified_properties) {
      properties.push(...eventData.modified_properties);
    }

    return properties;
  }

  private calculateChangeMagnitude(graphData: any): number {
    // Simple heuristic for change magnitude
    const nodeCount = graphData?.nodes?.length || 0;
    const edgeCount = graphData?.edges?.length || 0;

    // Normalize to 0-10 scale
    return Math.min(10, Math.log10(nodeCount + edgeCount + 1) * 2);
  }

  // Statistics and Analytics
  async getVersionStatistics(): Promise<{
    total_snapshots: number;
    total_branches: number;
    total_changes: number;
    most_active_authors: Array<{ author_id: string; change_count: number }>;
    change_frequency: Array<{ date: string; count: number }>;
    branch_activity: Array<{ branch_name: string; snapshot_count: number }>;
  }> {
    try {
      const response = await this.apiClient.get(`/api/version-statistics?project_id=${this.projectId}`);
      return response.data;
    } catch (error) {
      console.error('Failed to get version statistics:', error);
      throw error;
    }
  }

  // Cleanup and Maintenance
  startNewSession(): void {
    this.currentSessionId = crypto.randomUUID();
  }

  async cleanupOldData(options: {
    days_old?: number;
    keep_milestones?: boolean;
    keep_tagged_versions?: boolean;
  } = {}): Promise<{ deleted_snapshots: number; deleted_diffs: number }> {
    try {
      const response = await this.apiClient.post('/api/version-cleanup', {
        project_id: this.projectId,
        days_old: options.days_old || 90,
        keep_milestones: options.keep_milestones !== false,
        keep_tagged_versions: options.keep_tagged_versions !== false
      });
      return response.data;
    } catch (error) {
      console.error('Failed to cleanup old data:', error);
      throw error;
    }
  }
}

/**
 * Epic 9.3.3 - Version Restore Manager
 * Handles version restoration with conflict detection, preview, and selective restore capabilities
 */

export interface RestoreOptions {
  create_backup?: boolean;
  backup_title?: string;
  restore_mode?: 'full' | 'selective' | 'merge';
  conflict_resolution?: 'abort' | 'overwrite' | 'merge' | 'prompt';
  preserve_current_changes?: boolean;
  restore_metadata?: boolean;
  restore_workflow_state?: boolean;
  notify_collaborators?: boolean;
}

export interface RestoreConflict {
  id: string;
  type: 'data_conflict' | 'workflow_conflict' | 'permission_conflict' | 'dependency_conflict';
  element_id: string;
  element_type: 'node' | 'edge' | 'property' | 'metadata';
  description: string;
  current_value: any;
  restore_value: any;
  suggested_resolution: 'keep_current' | 'use_restore' | 'merge' | 'manual';
  severity: 'low' | 'medium' | 'high' | 'critical';
  auto_resolvable: boolean;
}

export interface RestorePreview {
  restore_id: string;
  snapshot_id: string;
  conflicts: RestoreConflict[];
  changes_summary: {
    nodes_to_add: number;
    nodes_to_remove: number;
    nodes_to_modify: number;
    edges_to_add: number;
    edges_to_remove: number;
    edges_to_modify: number;
    properties_to_change: number;
  };
  estimated_duration: number; // seconds
  risk_level: 'low' | 'medium' | 'high' | 'critical';
  backup_required: boolean;
  collaborator_impact: {
    active_users: string[];
    potential_conflicts: string[];
    recommended_actions: string[];
  };
}

export interface RestoreResult {
  success: boolean;
  restore_id: string;
  backup_snapshot_id?: string;
  conflicts_resolved: number;
  conflicts_remaining: number;
  changes_applied: {
    nodes_added: number;
    nodes_removed: number;
    nodes_modified: number;
    edges_added: number;
    edges_removed: number;
    edges_modified: number;
    properties_changed: number;
  };
  duration_ms: number;
  warnings: string[];
  errors: string[];
}

export interface RestoreState {
  id: string;
  status: 'pending' | 'in_progress' | 'completed' | 'failed' | 'cancelled';
  progress: number; // 0-100
  current_step: string;
  total_steps: number;
  completed_steps: number;
  started_at: string;
  completed_at?: string;
  error_message?: string;
}

export class VersionRestoreManager {
  private activeRestores = new Map<string, RestoreState>();
  private restoreHistory: RestoreResult[] = [];

  constructor(
    private apiClient: any,
    private projectId: string,
    private userId: string,
    private versionHistoryManager: any
  ) {}

  // Create restore preview
  async createRestorePreview(
    snapshotId: string,
    currentGraphData: any,
    options: RestoreOptions = {}
  ): Promise<RestorePreview> {
    try {
      const response = await this.apiClient.post('/api/version-restore/preview', {
        project_id: this.projectId,
        snapshot_id: snapshotId,
        current_graph_data: currentGraphData,
        options,
        user_id: this.userId
      });

      return response.data;
    } catch (error) {
      console.error('Failed to create restore preview:', error);
      throw error;
    }
  }

  // Execute version restore
  async executeRestore(
    snapshotId: string,
    options: RestoreOptions = {},
    conflictResolutions: Record<string, 'keep_current' | 'use_restore' | 'merge' | 'custom'> = {}
  ): Promise<{ restoreId: string; result: Promise<RestoreResult> }> {
    try {
      const restoreId = crypto.randomUUID();

      // Initialize restore state
      this.activeRestores.set(restoreId, {
        id: restoreId,
        status: 'pending',
        progress: 0,
        current_step: 'Initializing restore...',
        total_steps: 8,
        completed_steps: 0,
        started_at: new Date().toISOString()
      });

      // Start restore process
      const resultPromise = this.performRestore(restoreId, snapshotId, options, conflictResolutions);

      return { restoreId, result: resultPromise };
    } catch (error) {
      console.error('Failed to execute restore:', error);
      throw error;
    }
  }

  private async performRestore(
    restoreId: string,
    snapshotId: string,
    options: RestoreOptions,
    conflictResolutions: Record<string, string>
  ): Promise<RestoreResult> {
    const startTime = Date.now();
    let backupSnapshotId: string | undefined;

    try {
      this.updateRestoreState(restoreId, {
        status: 'in_progress',
        current_step: 'Creating backup...',
        progress: 10
      });

      // Step 1: Create backup if requested
      if (options.create_backup !== false) {
        backupSnapshotId = await this.createBackupSnapshot(options.backup_title);
      }

      this.updateRestoreState(restoreId, {
        current_step: 'Loading snapshot data...',
        progress: 20,
        completed_steps: 1
      });

      // Step 2: Load snapshot data
      const snapshotData = await this.versionHistoryManager.getSnapshotData(snapshotId);

      this.updateRestoreState(restoreId, {
        current_step: 'Analyzing conflicts...',
        progress: 30,
        completed_steps: 2
      });

      // Step 3: Detect and resolve conflicts
      const currentGraphData = await this.getCurrentGraphData();
      const conflicts = await this.detectConflicts(snapshotData, currentGraphData);
      const resolvedConflicts = await this.resolveConflicts(conflicts, conflictResolutions);

      this.updateRestoreState(restoreId, {
        current_step: 'Validating permissions...',
        progress: 40,
        completed_steps: 3
      });

      // Step 4: Validate permissions and dependencies
      await this.validateRestorePermissions(snapshotData, options);

      this.updateRestoreState(restoreId, {
        current_step: 'Preparing changes...',
        progress: 50,
        completed_steps: 4
      });

      // Step 5: Calculate and prepare changes
      const changesToApply = await this.calculateChangesToApply(
        currentGraphData,
        snapshotData,
        options,
        resolvedConflicts
      );

      this.updateRestoreState(restoreId, {
        current_step: 'Applying changes...',
        progress: 60,
        completed_steps: 5
      });

      // Step 6: Apply changes
      const appliedChanges = await this.applyChanges(changesToApply, options);

      this.updateRestoreState(restoreId, {
        current_step: 'Updating metadata...',
        progress: 80,
        completed_steps: 6
      });

      // Step 7: Update metadata and workflow state
      if (options.restore_metadata !== false) {
        await this.restoreMetadata(snapshotData, options);
      }

      this.updateRestoreState(restoreId, {
        current_step: 'Finalizing restore...',
        progress: 90,
        completed_steps: 7
      });

      // Step 8: Notify collaborators and finalize
      if (options.notify_collaborators !== false) {
        await this.notifyCollaborators(snapshotId, restoreId, appliedChanges);
      }

      const result: RestoreResult = {
        success: true,
        restore_id: restoreId,
        backup_snapshot_id: backupSnapshotId,
        conflicts_resolved: resolvedConflicts.resolved.length,
        conflicts_remaining: resolvedConflicts.unresolved.length,
        changes_applied: appliedChanges,
        duration_ms: Date.now() - startTime,
        warnings: resolvedConflicts.warnings,
        errors: []
      };

      this.updateRestoreState(restoreId, {
        status: 'completed',
        progress: 100,
        completed_steps: 8,
        completed_at: new Date().toISOString()
      });

      this.restoreHistory.push(result);
      return result;

    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';

      this.updateRestoreState(restoreId, {
        status: 'failed',
        error_message: errorMessage,
        completed_at: new Date().toISOString()
      });

      const result: RestoreResult = {
        success: false,
        restore_id: restoreId,
        backup_snapshot_id: backupSnapshotId,
        conflicts_resolved: 0,
        conflicts_remaining: 0,
        changes_applied: {
          nodes_added: 0,
          nodes_removed: 0,
          nodes_modified: 0,
          edges_added: 0,
          edges_removed: 0,
          edges_modified: 0,
          properties_changed: 0
        },
        duration_ms: Date.now() - startTime,
        warnings: [],
        errors: [errorMessage]
      };

      this.restoreHistory.push(result);
      throw error;
    }
  }

  private async createBackupSnapshot(title?: string): Promise<string> {
    try {
      const currentGraphData = await this.getCurrentGraphData();
      const snapshot = await this.versionHistoryManager.createSnapshot(currentGraphData, {
        title: title || `Pre-restore backup ${new Date().toISOString()}`,
        description: 'Automatic backup created before version restore',
        snapshot_type: 'backup',
        trigger_event: 'pre_restore_backup'
      });

      return snapshot.id;
    } catch (error) {
      console.error('Failed to create backup snapshot:', error);
      throw new Error('Failed to create backup snapshot');
    }
  }

  private async getCurrentGraphData(): Promise<any> {
    try {
      const response = await this.apiClient.get(`/api/projects/${this.projectId}/current-graph`);
      return response.data;
    } catch (error) {
      console.error('Failed to get current graph data:', error);
      throw error;
    }
  }

  private async detectConflicts(snapshotData: any, currentData: any): Promise<RestoreConflict[]> {
    const conflicts: RestoreConflict[] = [];

    // Detect data conflicts
    conflicts.push(...this.detectDataConflicts(snapshotData, currentData));

    // Detect workflow conflicts
    conflicts.push(...this.detectWorkflowConflicts(snapshotData, currentData));

    // Detect dependency conflicts
    conflicts.push(...this.detectDependencyConflicts(snapshotData, currentData));

    return conflicts;
  }

  private detectDataConflicts(snapshotData: any, currentData: any): RestoreConflict[] {
    const conflicts: RestoreConflict[] = [];

    // Compare nodes
    const currentNodes = new Map(currentData.nodes?.map((n: any) => [n.id, n]) || []);
    const snapshotNodes = new Map(snapshotData.nodes?.map((n: any) => [n.id, n]) || []);

    for (const [nodeId, snapshotNode] of snapshotNodes) {
      const currentNode = currentNodes.get(nodeId);
      if (currentNode && this.hasSignificantDifferences(currentNode, snapshotNode)) {
        conflicts.push({
          id: crypto.randomUUID(),
          type: 'data_conflict',
          element_id: nodeId,
          element_type: 'node',
          description: `Node "${nodeId}" has been modified since the snapshot was created`,
          current_value: currentNode,
          restore_value: snapshotNode,
          suggested_resolution: this.suggestResolution(currentNode, snapshotNode),
          severity: this.calculateConflictSeverity(currentNode, snapshotNode),
          auto_resolvable: this.isAutoResolvable(currentNode, snapshotNode)
        });
      }
    }

    // Compare edges
    const currentEdges = new Map(currentData.edges?.map((e: any) => [e.id, e]) || []);
    const snapshotEdges = new Map(snapshotData.edges?.map((e: any) => [e.id, e]) || []);

    for (const [edgeId, snapshotEdge] of snapshotEdges) {
      const currentEdge = currentEdges.get(edgeId);
      if (currentEdge && this.hasSignificantDifferences(currentEdge, snapshotEdge)) {
        conflicts.push({
          id: crypto.randomUUID(),
          type: 'data_conflict',
          element_id: edgeId,
          element_type: 'edge',
          description: `Edge "${edgeId}" has been modified since the snapshot was created`,
          current_value: currentEdge,
          restore_value: snapshotEdge,
          suggested_resolution: this.suggestResolution(currentEdge, snapshotEdge),
          severity: this.calculateConflictSeverity(currentEdge, snapshotEdge),
          auto_resolvable: this.isAutoResolvable(currentEdge, snapshotEdge)
        });
      }
    }

    return conflicts;
  }

  private detectWorkflowConflicts(snapshotData: any, currentData: any): RestoreConflict[] {
    const conflicts: RestoreConflict[] = [];

    // Check workflow state conflicts
    if (snapshotData.workflow_state !== currentData.workflow_state) {
      conflicts.push({
        id: crypto.randomUUID(),
        type: 'workflow_conflict',
        element_id: 'workflow_state',
        element_type: 'metadata',
        description: `Workflow state has changed from "${snapshotData.workflow_state}" to "${currentData.workflow_state}"`,
        current_value: currentData.workflow_state,
        restore_value: snapshotData.workflow_state,
        suggested_resolution: 'keep_current',
        severity: 'medium',
        auto_resolvable: false
      });
    }

    // Check approval status conflicts
    if (snapshotData.approval_status !== currentData.approval_status) {
      conflicts.push({
        id: crypto.randomUUID(),
        type: 'workflow_conflict',
        element_id: 'approval_status',
        element_type: 'metadata',
        description: `Approval status has changed since snapshot`,
        current_value: currentData.approval_status,
        restore_value: snapshotData.approval_status,
        suggested_resolution: 'keep_current',
        severity: 'high',
        auto_resolvable: false
      });
    }

    return conflicts;
  }

  private detectDependencyConflicts(snapshotData: any, currentData: any): RestoreConflict[] {
    const conflicts: RestoreConflict[] = [];

    // Check for missing dependencies
    const snapshotDependencies = snapshotData.dependencies || [];
    for (const dependency of snapshotDependencies) {
      if (!this.isDependencyAvailable(dependency)) {
        conflicts.push({
          id: crypto.randomUUID(),
          type: 'dependency_conflict',
          element_id: dependency.id,
          element_type: 'metadata',
          description: `Required dependency "${dependency.name}" is not available`,
          current_value: null,
          restore_value: dependency,
          suggested_resolution: 'manual',
          severity: 'critical',
          auto_resolvable: false
        });
      }
    }

    return conflicts;
  }

  private async resolveConflicts(
    conflicts: RestoreConflict[],
    conflictResolutions: Record<string, string>
  ): Promise<{ resolved: RestoreConflict[]; unresolved: RestoreConflict[]; warnings: string[] }> {
    const resolved: RestoreConflict[] = [];
    const unresolved: RestoreConflict[] = [];
    const warnings: string[] = [];

    for (const conflict of conflicts) {
      const resolution = conflictResolutions[conflict.id] || conflict.suggested_resolution;

      if (resolution === 'manual' || (!conflict.auto_resolvable && resolution !== 'keep_current' && resolution !== 'use_restore')) {
        unresolved.push(conflict);
      } else {
        try {
          await this.applyConflictResolution(conflict, resolution);
          resolved.push(conflict);
        } catch (error) {
          warnings.push(`Failed to resolve conflict ${conflict.id}: ${error}`);
          unresolved.push(conflict);
        }
      }
    }

    return { resolved, unresolved, warnings };
  }

  private async applyConflictResolution(conflict: RestoreConflict, resolution: string): Promise<void> {
    // Implementation would depend on the specific conflict type and resolution strategy
    switch (resolution) {
      case 'keep_current':
        // Keep the current value, don't apply the restore value
        break;
      case 'use_restore':
        // Use the restore value, overwrite current
        break;
      case 'merge':
        // Attempt to merge the values
        await this.mergeConflictValues(conflict);
        break;
      default:
        throw new Error(`Unknown resolution strategy: ${resolution}`);
    }
  }

  private async mergeConflictValues(conflict: RestoreConflict): Promise<void> {
    // Implement intelligent merging based on conflict type
    switch (conflict.element_type) {
      case 'node':
        await this.mergeNodeValues(conflict);
        break;
      case 'edge':
        await this.mergeEdgeValues(conflict);
        break;
      case 'property':
        await this.mergePropertyValues(conflict);
        break;
      default:
        throw new Error(`Cannot merge conflict type: ${conflict.element_type}`);
    }
  }

  private async mergeNodeValues(conflict: RestoreConflict): Promise<void> {
    // Implement node-specific merging logic
    const current = conflict.current_value;
    const restore = conflict.restore_value;

    // Example: merge data properties, keep position from current
    const merged = {
      ...restore,
      position: current.position, // Keep current position
      data: { ...restore.data, ...current.data }, // Merge data with current taking precedence
      style: { ...restore.style, ...current.style } // Merge styles
    };

    // Apply the merged value
    await this.updateElement(conflict.element_id, 'node', merged);
  }

  private async mergeEdgeValues(conflict: RestoreConflict): Promise<void> {
    // Implement edge-specific merging logic
    const current = conflict.current_value;
    const restore = conflict.restore_value;

    const merged = {
      ...restore,
      data: { ...restore.data, ...current.data }
    };

    await this.updateElement(conflict.element_id, 'edge', merged);
  }

  private async mergePropertyValues(conflict: RestoreConflict): Promise<void> {
    // Implement property-specific merging logic
    // This would depend on the specific property type
  }

  private async validateRestorePermissions(snapshotData: any, options: RestoreOptions): Promise<void> {
    // Check if user has permission to restore
    const hasPermission = await this.checkRestorePermission();
    if (!hasPermission) {
      throw new Error('Insufficient permissions to restore version');
    }

    // Check if project is locked
    const isLocked = await this.checkProjectLock();
    if (isLocked) {
      throw new Error('Project is locked and cannot be modified');
