import { EventEmitter } from 'events';
import { WSMessageSchema } from '../../../server/src/websocket/types';
export class WebSocketClient extends EventEmitter {
    ws = null;
    config;
    state;
    messageQueue = [];
    heartbeatInterval = null;
    reconnectTimeout = null;
    connectionTimeout = null;
    documentId = null;
    userId = null;
    constructor(config) {
        super();
        this.config = config;
        this.state = {
            status: 'disconnected',
            reconnectAttempts: 0
        };
    }
    /**
     * Connect to WebSocket server
     */
    async connect(documentId, userId) {
        if (this.state.status === 'connecting' || this.state.status === 'connected') {
            return;
        }
        this.documentId = documentId;
        this.userId = userId || 'anonymous';
        this.state.status = 'connecting';
        this.state.error = undefined;
        try {
            await this.establishConnection();
        }
        catch (error) {
            this.handleConnectionError(error);
            throw error;
        }
    }
    /**
     * Disconnect from WebSocket server
     */
    disconnect() {
        this.clearTimeouts();
        if (this.ws) {
            this.ws.close();
            this.ws = null;
        }
        this.state.status = 'disconnected';
        this.emit('disconnected');
    }
    /**
     * Send graph update
     */
    sendGraphUpdate(update) {
        return this.sendMessage({
            type: 'graph_update',
            payload: update,
            timestamp: Date.now(),
            documentId: this.documentId || undefined,
            userId: this.userId || undefined
        });
    }
    /**
     * Send presence update
     */
    sendPresenceUpdate(presence) {
        return this.sendMessage({
            type: 'presence_update',
            payload: presence,
            timestamp: Date.now(),
            documentId: this.documentId || undefined,
            userId: this.userId || undefined
        });
    }
    /**
     * Send cursor position update
     */
    sendCursorUpdate(x, y, nodeId, viewportBounds) {
        return this.sendMessage({
            type: 'cursor_update',
            payload: { x, y, nodeId, viewportBounds },
            timestamp: Date.now(),
            documentId: this.documentId || undefined,
            userId: this.userId || undefined
        });
    }
    /**
     * Send selection update
     */
    sendSelectionUpdate(nodeIds, edgeIds, selectionBox) {
        return this.sendMessage({
            type: 'selection_update',
            payload: { nodeIds, edgeIds, selectionBox },
            timestamp: Date.now(),
            documentId: this.documentId || undefined,
            userId: this.userId || undefined
        });
    }
    /**
