 * Epic 9.1.1 - Testing CRDT performance with large graphs
 */
import { GraphSyncHandler } from '../src/graph-sync';
class CRDTBenchmark {
    results = [];
    /**
     * Run a benchmark and record results
     */
    async runBenchmark(name, operations, fn) {
        // Force garbage collection if available
        if (global.gc) {
            global.gc();
        }
        const memBefore = process.memoryUsage().heapUsed;
        const start = process.hrtime.bigint();
        await fn();
        const end = process.hrtime.bigint();
        const duration = Number(end - start) / 1_000_000; // Convert to milliseconds
        const memAfter = process.memoryUsage().heapUsed;
        const result = {
            name,
            operations,
            duration,
            opsPerSecond: (operations / duration) * 1000,
            memoryUsed: memAfter - memBefore
        };
        this.results.push(result);
        return result;
    }
    /**
     * Benchmark single-user node creation
     */
    async benchmarkNodeCreation(nodeCount) {
        return this.runBenchmark(`Create ${nodeCount} nodes (single user)`, nodeCount, () => {
            const sync = new GraphSyncHandler('bench', 'user1');
            const graph = sync.getGraph();
            for (let i = 0; i < nodeCount; i++) {
                const node = {
                    id: `node${i}`,
                    type: 'WeightedChoice',
                    position: { x: i * 100, y: i * 100 },
                    data: {
                        choices: ['Option A', 'Option B', 'Option C'],
                        weights: [0.33, 0.33, 0.34]
                    },
                    metadata: {
                        label: `Node ${i}`,
                        description: `This is test node number ${i}`,
                        created: Date.now()
                    }
                };
                graph.addNode(node);
            }
            sync.destroy();
        });
    }
    /**
     * Benchmark concurrent node creation
     */
    async benchmarkConcurrentNodeCreation(nodeCount, userCount) {
        const nodesPerUser = Math.floor(nodeCount / userCount);
        return this.runBenchmark(`Create ${nodeCount} nodes (${userCount} concurrent users)`, nodeCount, () => {
            const syncs = [];
            // Create sync handlers for each user
            for (let u = 0; u < userCount; u++) {
                syncs.push(new GraphSyncHandler('bench', `user${u}`));
            }
            // Each user creates their nodes
            for (let u = 0; u < userCount; u++) {
                const graph = syncs[u].getGraph();
                const startIdx = u * nodesPerUser;
                for (let i = 0; i < nodesPerUser; i++) {
                    const node = {
                        id: `node${startIdx + i}`,
                        type: 'WeightedChoice',
                        position: { x: i * 100, y: i * 100 },
                        data: { choices: ['A', 'B', 'C'] },
                        metadata: { creator: `user${u}` }
                    };
                    graph.addNode(node);
                }
            }
            // Sync all documents
            for (let i = 0; i < syncs.length; i++) {
                for (let j = i + 1; j < syncs.length; j++) {
                    const update1 = syncs[i].getStateAsUpdate();
                    const update2 = syncs[j].getStateAsUpdate();
                    syncs[i].applyUpdate(update2);
                    syncs[j].applyUpdate(update1);
                }
            }
            // Cleanup
            syncs.forEach(sync => sync.destroy());
        });
    }
    /**
     * Benchmark edge creation in a large graph
     */
    async benchmarkEdgeCreation(nodeCount, edgeCount) {
        return this.runBenchmark(`Create ${edgeCount} edges in ${nodeCount} node graph`, edgeCount, () => {
            const sync = new GraphSyncHandler('bench', 'user1');
            const graph = sync.getGraph();
            // First create nodes
            for (let i = 0; i < nodeCount; i++) {
                const node = {
                    id: `node${i}`,
                    type: 'WeightedChoice',
                    position: { x: i * 100, y: i * 100 },
                    data: {},
                    metadata: {}
                };
                graph.addNode(node);
            }
            // Then create edges
