        if (node) {
          this.nodes.set(nodeId, { ...node, ...updates });
        }
      });
    } else {
      const node = this.nodes.get(nodeId);
      if (node) {
        this.nodes.set(nodeId, { ...node, ...updates });
      }
    }
  }

  /**
   * Delete a node from the graph
   */
  deleteNode(nodeId: string): void {
    if (this.doc) {
      this.doc.transact(() => {
        // Delete the node
