        doc1.destroy();
        doc2.destroy();
    });
    /**
     * Helper to sync two documents
     */
    function syncDocs(doc1, doc2) {
        const state1 = Y.encodeStateAsUpdate(doc1);
        const state2 = Y.encodeStateAsUpdate(doc2);
        Y.applyUpdate(doc1, state2);
        Y.applyUpdate(doc2, state1);
