      const node: GraphNode = {
        id: 'node1',
        type: 'Output',
        data: { text: 'Hello' }
      };

      crdt.addNode(node);
      crdt.updateNode('node1', { data: { text: 'Hello World' } });

      const graph = crdt.toGraphDocument();
      expect(graph.nodes.get('node1')?.data.text).toBe('Hello World');
    });

