              choices: 'not-an-array' // Invalid choices
            }
          }]
        ]),
        edges: new Map([
          ['edge1', {
            id: 'edge1',
            source: 'node1',
            target: 'nonexistent' // Missing target
          }],
          ['edge2', {
            id: 'edge2',
            source: 'node2',
            target: 'node2' // Self-loop
          }]
        ]),
        metadata: null as any // Invalid metadata
      };

      const result = validator.validate(graph);

      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(3);

      // Should detect multiple types of errors
      const errorTypes = result.errors.map(e => e.type);
      expect(errorTypes).toContain('MALFORMED_GRAPH');
      expect(errorTypes).toContain('INVALID_DATA');
      expect(errorTypes).toContain('INVALID_NODE_TYPE');
      expect(errorTypes).toContain('MISSING_NODE');
      expect(errorTypes).toContain('INVALID_EDGE');
    });
  });
});

/**
 * CRDT integration for graph synchronization
 * Enhanced implementation with conflict resolution and real-time sync
 */

import * as Y from 'yjs';
import { GraphDocument, GraphNode, GraphEdge, GraphMetadata } from './types';

export interface CRDTOptions {
  clientId?: string;
  enableUndo?: boolean;
  maxHistorySize?: number;
}

export interface SyncStatus {
  connected: boolean;
  lastSync: Date;
  pendingOperations: number;
  conflictCount: number;
}

export class GraphCRDT {
  private ydoc: Y.Doc;
  private nodes: Y.Map<any>;
  private edges: Y.Map<any>;
  private metadata: Y.Map<any>;
  private operationHistory: Y.Array<any>;
  private clientId: string;
  private changeListeners: Set<(event: Y.YEvent<any>[]) => void> = new Set();

  constructor(options: CRDTOptions = {}) {
    this.clientId = options.clientId || this.generateClientId();
    this.ydoc = new Y.Doc();

    this.nodes = this.ydoc.getMap('nodes');
    this.edges = this.ydoc.getMap('edges');
    this.metadata = this.ydoc.getMap('metadata');
    this.operationHistory = this.ydoc.getArray('history');

    // Set up change tracking
    this.setupChangeTracking();
  }

  /**
   * Add or update a node in the graph
   */
  addNode(node: GraphNode): void {
    this.ydoc.transact(() => {
      this.nodes.set(node.id, {
        id: node.id,
        type: node.type,
        position: node.position,
        data: node.data,
        inputs: node.inputs,
        lastModified: new Date().toISOString(),
        modifiedBy: this.clientId
      });

      this.recordOperation('addNode', { nodeId: node.id, type: node.type });
    });
  }

  /**
   * Update an existing node
   */
  updateNode(nodeId: string, updates: Partial<GraphNode>): void {
    this.ydoc.transact(() => {
      const existing = this.nodes.get(nodeId);
      if (existing) {
        const updated = {
          ...existing,
          ...updates,
          id: nodeId, // Ensure ID doesn't change
          lastModified: new Date().toISOString(),
          modifiedBy: this.clientId
        };
        this.nodes.set(nodeId, updated);
        this.recordOperation('updateNode', { nodeId, updates });
      }
    });
  }

  /**
   * Remove a node from the graph
   */
  removeNode(nodeId: string): void {
    this.ydoc.transact(() => {
      this.nodes.delete(nodeId);

      // Remove edges connected to this node
      const edgesToRemove: string[] = [];
      this.edges.forEach((edge, edgeId) => {
        if (edge.source === nodeId || edge.target === nodeId) {
          edgesToRemove.push(edgeId);
        }
      });

      edgesToRemove.forEach(edgeId => this.edges.delete(edgeId));

      this.recordOperation('removeNode', { nodeId, removedEdges: edgesToRemove });
    });
  }

  /**
   * Add or update an edge
   */
  addEdge(edge: GraphEdge): void {
    this.ydoc.transact(() => {
      // Validate that source and target nodes exist
      if (!this.nodes.has(edge.source) || !this.nodes.has(edge.target)) {
        throw new Error(`Cannot create edge: source or target node does not exist`);
      }

      this.edges.set(edge.id, {
        id: edge.id,
        source: edge.source,
        target: edge.target,
        sourceHandle: edge.sourceHandle,
        targetHandle: edge.targetHandle,
        lastModified: new Date().toISOString(),
        modifiedBy: this.clientId
      });

      this.recordOperation('addEdge', { edgeId: edge.id, source: edge.source, target: edge.target });
    });
  }

  /**
   * Remove an edge
   */
  removeEdge(edgeId: string): void {
    this.ydoc.transact(() => {
      const edge = this.edges.get(edgeId);
      this.edges.delete(edgeId);
      this.recordOperation('removeEdge', { edgeId, edge });
    });
  }

  /**
   * Update graph metadata
   */
  updateMetadata(metadata: Partial<GraphMetadata>): void {
    this.ydoc.transact(() => {
      const current = this.metadata.get('current') || {};
      const updated = {
        ...current,
        ...metadata,
        modified: new Date().toISOString(),
        modifiedBy: this.clientId
      };
      this.metadata.set('current', updated);
      this.recordOperation('updateMetadata', { metadata });
    });
  }

  /**
   * Convert CRDT state to GraphDocument
   */
  toGraphDocument(): GraphDocument {
    const nodes = new Map<string, GraphNode>();
    const edges = new Map<string, GraphEdge>();

    // Convert nodes
    this.nodes.forEach((nodeData, nodeId) => {
      nodes.set(nodeId, {
        id: nodeData.id,
        type: nodeData.type,
        position: nodeData.position,
        data: nodeData.data,
        inputs: nodeData.inputs
      });
    });

    // Convert edges
    this.edges.forEach((edgeData, edgeId) => {
      edges.set(edgeId, {
        id: edgeData.id,
        source: edgeData.source,
        target: edgeData.target,
        sourceHandle: edgeData.sourceHandle,
        targetHandle: edgeData.targetHandle
      });
    });

    // Get metadata
    const metadataData = this.metadata.get('current') || {};

    return {
      id: metadataData.id || this.generateGraphId(),
      nodes,
      edges,
      metadata: {
        version: metadataData.version || '1.0.0',
        created: new Date(metadataData.created || Date.now()),
        modified: new Date(metadataData.modified || Date.now()),
        author: metadataData.author,
        platform: metadataData.platform
      },
      seed: metadataData.seed
    };
  }

  /**
   * Load a GraphDocument into the CRDT
   */
  fromGraphDocument(graph: GraphDocument): void {
    this.ydoc.transact(() => {
      // Clear existing data
      this.nodes.clear();
      this.edges.clear();
      this.metadata.clear();

      // Load nodes
      graph.nodes.forEach((node, nodeId) => {
        this.nodes.set(nodeId, {
          ...node,
          lastModified: new Date().toISOString(),
          modifiedBy: this.clientId
        });
      });

      // Load edges
      graph.edges.forEach((edge, edgeId) => {
        this.edges.set(edgeId, {
          ...edge,
          lastModified: new Date().toISOString(),
          modifiedBy: this.clientId
        });
      });

      // Load metadata
      this.metadata.set('current', {
        ...graph.metadata,
        id: graph.id,
        seed: graph.seed,
        modified: new Date().toISOString(),
        modifiedBy: this.clientId
      });

      this.recordOperation('loadGraph', { graphId: graph.id, nodeCount: graph.nodes.size });
    });
  }

  /**
   * Get the underlying Yjs document for sync providers
   */
  getDoc(): Y.Doc {
    return this.ydoc;
  }

  /**
   * Get current sync status
   */
  getSyncStatus(): SyncStatus {
    return {
      connected: false, // Will be updated by sync provider
      lastSync: new Date(),
      pendingOperations: this.operationHistory.length,
      conflictCount: 0 // Will be tracked by conflict resolution
    };
  }

  /**
   * Subscribe to changes
   */
  onChange(callback: (event: Y.YEvent<any>[]) => void): () => void {
    this.changeListeners.add(callback);
    return () => this.changeListeners.delete(callback);
  }

  /**
   * Get operation history
   */
  getHistory(): any[] {
    return this.operationHistory.toArray();
  }

  /**
   * Clear operation history (keep only recent entries)
   */
  pruneHistory(maxEntries: number = 1000): void {
    this.ydoc.transact(() => {
      const currentLength = this.operationHistory.length;
      if (currentLength > maxEntries) {
        const toRemove = currentLength - maxEntries;
        this.operationHistory.delete(0, toRemove);
      }
    });
  }

  /**
   * Export graph state as update for sync
   */
  exportUpdate(): Uint8Array {
    return Y.encodeStateAsUpdate(this.ydoc);
  }

  /**
   * Apply update from remote sync
   */
  applyUpdate(update: Uint8Array): void {
    Y.applyUpdate(this.ydoc, update);
  }

  /**
   * Get state vector for efficient sync
   */
  getStateVector(): Uint8Array {
    return Y.encodeStateVector(this.ydoc);
  }

  /**
   * Get diff update since state vector
   */
  getDiffUpdate(stateVector: Uint8Array): Uint8Array {
    return Y.encodeStateAsUpdate(this.ydoc, stateVector);
  }

  /**
   * Destroy the CRDT instance
   */
  destroy(): void {
    this.changeListeners.clear();
    this.ydoc.destroy();
  }

  // Private methods

  private setupChangeTracking(): void {
    const observer = (event: Y.YMapEvent<any>, transaction: Y.Transaction) => {
      // Convert single event to array format for compatibility
      const events = [event];

      // Notify all change listeners
      this.changeListeners.forEach(callback => {
        try {
          callback(events);
        } catch (error) {
          console.error('Error in CRDT change listener:', error);
        }
      });
    };

    this.nodes.observe(observer);
    this.edges.observe(observer);
    this.metadata.observe(observer);
  }

  private recordOperation(type: string, data: any): void {
    this.operationHistory.push([{
      type,
      data,
      timestamp: new Date().toISOString(),
      clientId: this.clientId,
      id: this.generateOperationId()
    }]);
  }

  private generateClientId(): string {
    return `client_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }


  private generateGraphId(): string {
    return `graph_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  private generateOperationId(): string {
    return `op_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }
}

/**
 * Factory function to create a GraphCRDT instance
 */
export function createGraphCRDT(options?: CRDTOptions): GraphCRDT {
  return new GraphCRDT(options);
}

/**
 * Merge multiple graph documents using CRDT semantics
 */
export function mergeGraphs(graphs: GraphDocument[]): GraphDocument {
  if (graphs.length === 0) {
    throw new Error('Cannot merge empty graph array');
  }

  if (graphs.length === 1) {
    return graphs[0];
  }

  const crdt = new GraphCRDT();

  // Apply each graph as an update
  graphs.forEach(graph => {
    const tempCrdt = new GraphCRDT();
    tempCrdt.fromGraphDocument(graph);
    const update = tempCrdt.exportUpdate();
    crdt.applyUpdate(update);
    tempCrdt.destroy();
  });

  const merged = crdt.toGraphDocument();
  crdt.destroy();

  return merged;
}

/**
 * Graph execution engine
 * Extracted and refactored from server/src/engine.ts for cross-platform use
 */

import { GraphDocument, ExecutionResult, ExecutionContext, GraphNode, RuntimeNode } from './types';
import { GraphValidator, ValidationResult } from './validation';
import seedrandom from 'seedrandom';

// Re-export core runtime nodes
export * from './runtime';

export class GraphEngine {
  private validator = new GraphValidator();

  /**
   * Execute a graph and return outputs from all Output nodes
   */
  async execute(graph: GraphDocument, seed?: number | string): Promise<ExecutionResult> {
    const startTime = Date.now();
    const executionSeed = seed ?? graph.seed ?? Date.now();
    const executionId = this.generateExecutionId();

    try {
      // Validate graph structure
      const validation = this.validator.validate(graph);
      if (!validation.valid) {
        return {
          success: false,
          outputs: [],
          error: `Graph validation failed: ${validation.errors.map(e => e.message).join(', ')}`,
          metadata: {
            executionTime: Date.now() - startTime,
            seed: executionSeed,
            nodeCount: graph.nodes.size,
            executionId
          }
        };
      }

      // Convert Map-based graph to array for execution
      const nodeArray = Array.from(graph.nodes.values());

      // Create execution context
      const context: ExecutionContext = {
        variables: {},
        seed: executionSeed,
        edges: Array.from(graph.edges.values())
      };

      // Execute graph using depth-first traversal
      const outputs = await this.executeNodes(nodeArray, context);

      return {
        success: true,
        outputs,
        metadata: {
          executionTime: Date.now() - startTime,
          seed: executionSeed,
          nodeCount: graph.nodes.size,
          executionId
        }
      };

    } catch (error) {
      return {
        success: false,
        outputs: [],
        error: error instanceof Error ? error.message : String(error),
        metadata: {
          executionTime: Date.now() - startTime,
          seed: executionSeed,
          nodeCount: graph.nodes.size,
          executionId
        }
      };
    }
  }

  /**
   * Validate a graph structure
   */
  validate(graph: GraphDocument): ValidationResult {
    return this.validator.validate(graph);
  }

  /**
   * Check if graph is valid (returns boolean for convenience)
   */
  isValid(graph: GraphDocument): boolean {
    const validation = this.validator.validate(graph);
    return validation.valid;
  }

  /**
   * Serialize graph to binary format for CRDT storage
   */
  serialize(graph: GraphDocument): Uint8Array {
    const jsonString = JSON.stringify({
      id: graph.id,
      nodes: Array.from(graph.nodes.entries()),
      edges: Array.from(graph.edges.entries()),
      metadata: graph.metadata,
      seed: graph.seed
    });

    return new TextEncoder().encode(jsonString);
  }

  /**
   * Deserialize binary data to graph document
   */
  deserialize(data: Uint8Array): GraphDocument {
    const jsonString = new TextDecoder().decode(data);
    const parsed = JSON.parse(jsonString);

    return {
      id: parsed.id,
      nodes: new Map(parsed.nodes),
      edges: new Map(parsed.edges),
      metadata: parsed.metadata,
      seed: parsed.seed
    };
  }

  /**
   * Create a new empty graph document
   */
  createEmptyGraph(id?: string): GraphDocument {
    return {
      id: id || this.generateGraphId(),
      nodes: new Map(),
      edges: new Map(),
      metadata: {
        version: '1.0.0',
        created: new Date(),
        modified: new Date()
      }
    };
  }

  /**
   * Clone a graph document
   */
  cloneGraph(graph: GraphDocument): GraphDocument {
    return this.deserialize(this.serialize(graph));
  }

  // Private methods

  private async executeNodes(nodes: GraphNode[], context: ExecutionContext): Promise<string[]> {
    const outputs: string[] = [];
    const nodeMap = new Map(nodes.map(node => [node.id, node]));
    const visited = new Set<string>();
    const executing = new Set<string>();

    // Build dependency graph from edges and inputs
    const dependencies = new Map<string, string[]>();
    for (const node of nodes) {
      dependencies.set(node.id, []);
    }

    // Add dependencies from edges (source -> target relationship)
    for (const edge of context.edges || []) {
      const targetDeps = dependencies.get(edge.target) || [];
      targetDeps.push(edge.source);
      dependencies.set(edge.target, targetDeps);
    }

    // Also add from node.inputs if present
    for (const node of nodes) {
      if (node.inputs) {
        const existingDeps = dependencies.get(node.id) || [];
        dependencies.set(node.id, [...existingDeps, ...node.inputs]);
      }
    }

    // Find Output nodes and execute the graph with dependencies
    const outputNodes = nodes.filter(node => node.type === 'Output');

    for (const outputNode of outputNodes) {
      const result = await this.executeNodeWithDeps(outputNode, nodeMap, dependencies, context, visited, executing);
      if (typeof result === 'string') {
        outputs.push(result);
      }
    }

    return outputs;
  }

  private async executeNodeWithDeps(
    node: GraphNode,
    nodeMap: Map<string, GraphNode>,
    dependencies: Map<string, string[]>,
    context: ExecutionContext,
    visited: Set<string>,
    executing: Set<string>
  ): Promise<any> {
    // Detect cycles
    if (executing.has(node.id)) {
      throw new Error(`Cycle detected at node ${node.id}`);
    }

    // Return cached result if already visited
    if (visited.has(node.id)) {
      return context.variables[`__result_${node.id}`];
    }

    executing.add(node.id);

    try {
      // Execute dependency nodes first
      const inputResults: any[] = [];
      const deps = dependencies.get(node.id) || [];

      for (const depId of deps) {
        const depNode = nodeMap.get(depId);
        if (depNode) {
          const result = await this.executeNodeWithDeps(depNode, nodeMap, dependencies, context, visited, executing);
          inputResults.push(result);
        }
      }

      // Create runtime node and execute
      const runtimeNode = this.createRuntimeNode(node, inputResults, context);
      const result = await runtimeNode.run(context);

      // Cache result
      context.variables[`__result_${node.id}`] = result;
      visited.add(node.id);

      return result;
    } finally {
      executing.delete(node.id);
    }
  }

  private async executeNode(
    node: GraphNode,
    nodeMap: Map<string, GraphNode>,
    context: ExecutionContext,
    visited: Set<string>,
    executing: Set<string>
  ): Promise<any> {
    // Legacy method - redirect to new implementation
    const dependencies = new Map<string, string[]>();
    for (const [id, n] of nodeMap) {
      dependencies.set(id, n.inputs || []);
    }
    return this.executeNodeWithDeps(node, nodeMap, dependencies, context, visited, executing);
  }

  private createRuntimeNode(node: GraphNode, inputs: any[], context: ExecutionContext): RuntimeNode {
    switch (node.type) {
      case 'WeightedChoice':
        return new WeightedChoiceRuntimeNode(node.id, node.data.choices || []);

      case 'Concat':
        return new ConcatRuntimeNode(node.id, node.data.template, inputs, context);

      case 'Output':
        return new OutputRuntimeNode(node.id, node.data.text, inputs, context);

      case 'Include':
        return new IncludeRuntimeNode(node.id, node.data.name || '', node.data.lookup || {});

      case 'SetVariable':
        return new SetVariableRuntimeNode(node.id, node.data.key || '', node.data.value);

      case 'GetVariable':
        return new GetVariableRuntimeNode(node.id, node.data.key || '');

      default:
        throw new Error(`Unsupported node type: ${node.type}`);
    }
  }

  private seededRandom(seed: string | number): number {
    return seedrandom(String(seed))();
  }

  private generateExecutionId(): string {
    return `exec_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  private generateGraphId(): string {
    return `graph_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }
}

// Runtime node implementations

class WeightedChoiceRuntimeNode extends RuntimeNode<string> {
  constructor(id: string, private choices: Array<{ value: string; weight: number }>) {
    super(id);
  }

  run(ctx: ExecutionContext): string {
    if (this.choices.length === 0) return '';

    const total = this.choices.reduce((sum, c) => sum + c.weight, 0);
    if (total === 0) return this.choices[0].value;

    // Create node-specific seed for deterministic results
    const nodeSeed = `${ctx.seed}_${this.id}`;
    let r = seedrandom(nodeSeed)() * total;

    for (const choice of this.choices) {
      if (r < choice.weight) return choice.value;
      r -= choice.weight;
    }
    return this.choices[this.choices.length - 1].value;
  }
}

class ConcatRuntimeNode extends RuntimeNode<string> {
  constructor(
    id: string, 
    private template: string, 
    private inputs: any[], 
    private context: ExecutionContext
  ) {
    super(id);
  }

  run(): string {
    if (!this.template) {
      return this.inputs.join('');
    }
    return this.substituteTemplate(this.template);
  }

  private substituteTemplate(template: string): string {
    return template.replace(/\{\{(\w+)\}\}/g, (match, nodeId) => {
      const value = this.context.variables[`__result_${nodeId}`];
      return value !== undefined ? String(value) : match;
    });
  }
}

class OutputRuntimeNode extends RuntimeNode<string> {
  constructor(
    id: string, 
    private text: string, 
    private inputs: any[], 
    private context: ExecutionContext
  ) {
    super(id);
  }

  run(): string {
    if (!this.text) {
      return this.inputs.join('');
    }
    return this.substituteTemplate(this.text);
  }

  private substituteTemplate(template: string): string {
    return template.replace(/\{\{(\w+)\}\}/g, (match, nodeId) => {
      const value = this.context.variables[`__result_${nodeId}`];
      return value !== undefined ? String(value) : match;
    });
  }
}

class IncludeRuntimeNode extends RuntimeNode<string> {
  constructor(id: string, private name: string, private lookup: Record<string, string>) {
    super(id);
  }

  run(): string {
    return this.lookup[this.name] || '';
  }
}

class SetVariableRuntimeNode extends RuntimeNode<void> {
  constructor(id: string, private key: string, private value: any) {
    super(id);
  }

  run(ctx: ExecutionContext): void {
    ctx.variables[this.key] = this.value;
  }
}

class GetVariableRuntimeNode extends RuntimeNode<any> {
  constructor(id: string, private key: string) {
    super(id);
  }

  run(ctx: ExecutionContext): any {
    return ctx.variables[this.key];
  }
}

/**
 * Core types for graph-core package
 * Extracted from existing packages/core for Epic 15 cross-platform support
 */

import { z } from 'zod';

// Re-export node type definitions from existing schema
export const NodeTypeEnum = z.enum([
  'WeightedChoice',
  'Concat',
  'Output',
  'Include',
  'SetVariable',
  'GetVariable',
  // Epic 7 Advanced Node Types
  'WeightedAdvanced',
  'Conditional',
  'Sequential',
  'Markov',
  // Epic 8 Python Integration
  'PythonTransform',
]);

export type NodeType = z.infer<typeof NodeTypeEnum>;

// Base node schema for cross-platform compatibility
export const BaseNodeSchema = z.object({
  id: z.string(),
  type: NodeTypeEnum,
  inputs: z.array(z.string()).optional(), // ids of upstream nodes (ordered)
});

// Execution context for deterministic graph execution
export interface ExecutionContext {
  variables: Record<string, any>;
  seed: string | number;
  [key: string]: any; // Allow for extensions
}

// Advanced execution context for Epic 7 compatibility
export interface AdvancedExecutionContext extends ExecutionContext {
  nodeStates: Map<string, any>;
  evaluationDepth: number;
  performanceCache: Map<string, any>;
  executionTrace: string[];
}

// Graph document structure for CRDT integration
export interface GraphDocument {
  id: string;
  nodes: Map<string, GraphNode>;
  edges: Map<string, GraphEdge>;
  metadata: GraphMetadata;
  seed?: string | number;
}

// Node definition compatible with existing schema
export interface GraphNode {
  id: string;
  type: NodeType;
  position?: { x: number; y: number }; // Optional for non-UI contexts
  data: Record<string, any>;
  inputs?: string[]; // Input node IDs
}

// Edge definition for graph connections
export interface GraphEdge {
  id: string;
  source: string;
  target: string;
  sourceHandle?: string;
  targetHandle?: string;
}

// Metadata for graph documents
export interface GraphMetadata {
  version: string;
  created: Date;
  modified: Date;
  author?: string;
  platform?: 'web' | 'mobile' | 'desktop';
}

// Execution result interface
export interface ExecutionResult {
  success: boolean;
  outputs: string[];
  error?: string;
  metadata: {
    executionTime: number;
    seed?: number | string;
    nodeCount: number;
    executionId: string;
  };
}

// Abstract base for runtime nodes
export abstract class RuntimeNode<TOutput = unknown> {
  constructor(public id: string) {}

  /**
   * Execute this node and return its output. May mutate context.
   */
  abstract run(ctx: ExecutionContext): Promise<TOutput> | TOutput;
}

// Choice structure for weighted nodes
export interface WeightedChoice {
  value: string;
  weight: number;
}

/**
 * Graph validation utilities
 * Enhanced validation with cycle detection and comprehensive error reporting
 */

import { GraphDocument, GraphNode, GraphEdge, NodeType } from './types';

export interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
  warnings: ValidationWarning[];
}

export interface ValidationError {
  type: 'MISSING_NODE' | 'CYCLE_DETECTED' | 'INVALID_EDGE' | 'INVALID_DATA' | 'INVALID_NODE_TYPE' | 'MALFORMED_GRAPH';
  message: string;
  nodeId?: string;
  edgeId?: string;
  severity: 'error' | 'warning';
}

export interface ValidationWarning {
  type: 'DISCONNECTED_NODE' | 'UNUSED_VARIABLE' | 'PERFORMANCE_CONCERN';
  message: string;
  nodeId?: string;
  suggestion?: string;
}

export class GraphValidator {
  /**
   * Validate a complete graph document
   */
  validate(graph: GraphDocument): ValidationResult {
    const errors: ValidationError[] = [];
    const warnings: ValidationWarning[] = [];

    try {
      // Basic structure validation
      this.validateStructure(graph, errors);

      // Node validation
      this.validateNodes(graph, errors, warnings);

      // Edge validation
      this.validateEdges(graph, errors);

      // Cycle detection
      this.detectCycles(graph, errors);

      // Performance analysis
      this.analyzePerformance(graph, warnings);

      // Connectivity analysis
      this.analyzeConnectivity(graph, warnings);

    } catch (error) {
      errors.push({
        type: 'MALFORMED_GRAPH',
        message: `Validation failed: ${error instanceof Error ? error.message : String(error)}`,
        severity: 'error'
      });
    }

    return {
      valid: errors.length === 0,
      errors,
      warnings
    };
  }

  /**
   * Validate graph structure
   */
  private validateStructure(graph: GraphDocument, errors: ValidationError[]): void {
    if (!graph.id || typeof graph.id !== 'string') {
      errors.push({
        type: 'MALFORMED_GRAPH',
        message: 'Graph must have a valid string ID',
        severity: 'error'
      });
    }

    if (!graph.nodes || !(graph.nodes instanceof Map)) {
      errors.push({
        type: 'MALFORMED_GRAPH',
        message: 'Graph must have a nodes Map',
        severity: 'error'
      });
    }

    if (!graph.edges || !(graph.edges instanceof Map)) {
      errors.push({
        type: 'MALFORMED_GRAPH',
        message: 'Graph must have an edges Map',
        severity: 'error'
      });
    }

    if (!graph.metadata || typeof graph.metadata !== 'object') {
      errors.push({
        type: 'MALFORMED_GRAPH',
        message: 'Graph must have metadata object',
        severity: 'error'
      });
    }
  }

  /**
   * Validate individual nodes
   */
  private validateNodes(graph: GraphDocument, errors: ValidationError[], warnings: ValidationWarning[]): void {
    const validNodeTypes = new Set([
      'WeightedChoice', 'Concat', 'Output', 'Include', 'SetVariable', 'GetVariable',
      'WeightedAdvanced', 'Conditional', 'Sequential', 'Markov', 'PythonTransform'
    ]);

    for (const [nodeId, node] of graph.nodes) {
      // Validate node ID consistency
      if (node.id !== nodeId) {
        errors.push({
          type: 'INVALID_DATA',
          message: `Node ID mismatch: map key "${nodeId}" !== node.id "${node.id}"`,
          nodeId,
          severity: 'error'
        });
      }

      // Validate node type
      if (!validNodeTypes.has(node.type)) {
        errors.push({
          type: 'INVALID_NODE_TYPE',
          message: `Invalid node type: "${node.type}"`,
          nodeId,
          severity: 'error'
        });
      }

      // Validate node data based on type
      this.validateNodeData(node, errors);

      // Validate inputs array
      if (node.inputs) {
        if (!Array.isArray(node.inputs)) {
          errors.push({
            type: 'INVALID_DATA',
            message: 'Node inputs must be an array',
            nodeId,
            severity: 'error'
          });
        } else {
          // Check that input nodes exist
          for (const inputId of node.inputs) {
            if (!graph.nodes.has(inputId)) {
              errors.push({
                type: 'MISSING_NODE',
                message: `Node "${nodeId}" references non-existent input node "${inputId}"`,
                nodeId,
                severity: 'error'
              });
            }
          }
        }
      }
    }
  }

  /**
   * Validate node-specific data
   */
  private validateNodeData(node: GraphNode, errors: ValidationError[]): void {
    switch (node.type) {
      case 'WeightedChoice':
        if (!node.data.choices || !Array.isArray(node.data.choices)) {
          errors.push({
            type: 'INVALID_DATA',
            message: 'WeightedChoice node must have choices array',
            nodeId: node.id,
            severity: 'error'
          });
        } else {
          for (const choice of node.data.choices) {
            if (typeof choice.value !== 'string' || typeof choice.weight !== 'number' || choice.weight < 0) {
              errors.push({
                type: 'INVALID_DATA',
                message: 'WeightedChoice choices must have string value and non-negative number weight',
                nodeId: node.id,
                severity: 'error'
              });
            }
          }
        }
        break;

      case 'SetVariable':
        if (!node.data.key || typeof node.data.key !== 'string') {
          errors.push({
            type: 'INVALID_DATA',
            message: 'SetVariable node must have a string key',
            nodeId: node.id,
            severity: 'error'
          });
        }
        break;

      case 'GetVariable':
        if (!node.data.key || typeof node.data.key !== 'string') {
          errors.push({
            type: 'INVALID_DATA',
            message: 'GetVariable node must have a string key',
            nodeId: node.id,
            severity: 'error'
          });
        }
        break;

      case 'Include':
        if (!node.data.name || typeof node.data.name !== 'string') {
          errors.push({
            type: 'INVALID_DATA',
            message: 'Include node must have a string name',
            nodeId: node.id,
            severity: 'error'
          });
        }
        break;
    }
  }

  /**
   * Validate edges
   */
  private validateEdges(graph: GraphDocument, errors: ValidationError[]): void {
    for (const [edgeId, edge] of graph.edges) {
      // Validate edge ID consistency
      if (edge.id !== edgeId) {
        errors.push({
          type: 'INVALID_DATA',
          message: `Edge ID mismatch: map key "${edgeId}" !== edge.id "${edge.id}"`,
          edgeId,
          severity: 'error'
        });
      }

      // Validate source and target nodes exist
      if (!graph.nodes.has(edge.source)) {
        errors.push({
          type: 'MISSING_NODE',
          message: `Edge "${edgeId}" references non-existent source node "${edge.source}"`,
          edgeId,
          severity: 'error'
        });
      }

      if (!graph.nodes.has(edge.target)) {
        errors.push({
          type: 'MISSING_NODE',
          message: `Edge "${edgeId}" references non-existent target node "${edge.target}"`,
          edgeId,
          severity: 'error'
        });
      }

      // Validate no self-loops
      if (edge.source === edge.target) {
        errors.push({
          type: 'INVALID_EDGE',
          message: `Edge "${edgeId}" creates a self-loop on node "${edge.source}"`,
          edgeId,
          severity: 'error'
        });
      }
    }
  }

  /**
   * Detect cycles in the graph using DFS
   */
  private detectCycles(graph: GraphDocument, errors: ValidationError[]): void {
    const visited = new Set<string>();
    const recursionStack = new Set<string>();
    const adjacencyList = this.buildAdjacencyList(graph);

    const dfs = (nodeId: string, path: string[]): boolean => {
      if (recursionStack.has(nodeId)) {
        const cycleStart = path.indexOf(nodeId);
        const cycle = path.slice(cycleStart).concat(nodeId);
        errors.push({
          type: 'CYCLE_DETECTED',
          message: `Cycle detected: ${cycle.join(' → ')}`,
          nodeId,
          severity: 'error'
        });
        return true;
      }

      if (visited.has(nodeId)) {
        return false;
      }

      visited.add(nodeId);
      recursionStack.add(nodeId);
      path.push(nodeId);

      const neighbors = adjacencyList.get(nodeId) || [];
      for (const neighbor of neighbors) {
        if (dfs(neighbor, [...path])) {
          return true;
        }
      }

      recursionStack.delete(nodeId);
      return false;
    };

    for (const nodeId of graph.nodes.keys()) {
      if (!visited.has(nodeId)) {
        dfs(nodeId, []);
      }
    }
  }

  /**
   * Analyze performance concerns
   */
  private analyzePerformance(graph: GraphDocument, warnings: ValidationWarning[]): void {
    const nodeCount = graph.nodes.size;
    const edgeCount = graph.edges.size;

    // Large graph warning
    if (nodeCount > 100) {
      warnings.push({
        type: 'PERFORMANCE_CONCERN',
        message: `Large graph with ${nodeCount} nodes may impact performance`,
        suggestion: 'Consider breaking into smaller sub-graphs'
      });
    }

    // High connectivity warning
    if (edgeCount > nodeCount * 2) {
      warnings.push({
        type: 'PERFORMANCE_CONCERN',
        message: `High edge-to-node ratio (${edgeCount}:${nodeCount}) may impact performance`,
        suggestion: 'Review graph structure for optimization opportunities'
      });
    }

    // Check for very deep chains
    const chains = this.findLongestChains(graph);
    for (const chain of chains) {
      if (chain.length > 20) {
        warnings.push({
          type: 'PERFORMANCE_CONCERN',
          message: `Very deep execution chain (${chain.length} nodes)`,
          nodeId: chain[0],
          suggestion: 'Consider breaking long chains for better performance'
        });
      }
    }
  }

  /**
   * Analyze graph connectivity
   */
  private analyzeConnectivity(graph: GraphDocument, warnings: ValidationWarning[]): void {
    const adjacencyList = this.buildAdjacencyList(graph);
    const incomingEdges = new Map<string, number>();

    // Count incoming edges
    for (const neighbors of adjacencyList.values()) {
      for (const neighbor of neighbors) {
        incomingEdges.set(neighbor, (incomingEdges.get(neighbor) || 0) + 1);
      }
    }

    // Find disconnected nodes
    for (const nodeId of graph.nodes.keys()) {
      const hasOutgoing = adjacencyList.has(nodeId) && adjacencyList.get(nodeId)!.length > 0;
      const hasIncoming = incomingEdges.has(nodeId);

      if (!hasOutgoing && !hasIncoming) {
        warnings.push({
          type: 'DISCONNECTED_NODE',
          message: `Node "${nodeId}" is completely disconnected`,
          nodeId,
          suggestion: 'Connect node to the graph or remove if unused'
        });
      }
    }

    // Check for Output nodes
    const outputNodes = Array.from(graph.nodes.values()).filter(node => node.type === 'Output');
    if (outputNodes.length === 0) {
      warnings.push({
        type: 'DISCONNECTED_NODE',
        message: 'Graph has no Output nodes',
        suggestion: 'Add at least one Output node to generate results'
      });
    }
  }

  /**
   * Build adjacency list from graph
   */
  private buildAdjacencyList(graph: GraphDocument): Map<string, string[]> {
    const adjacencyList = new Map<string, string[]>();

    // Initialize with all nodes
    for (const nodeId of graph.nodes.keys()) {
      adjacencyList.set(nodeId, []);
    }

    // Add edges
    for (const edge of graph.edges.values()) {
      const sourceNeighbors = adjacencyList.get(edge.source) || [];
      sourceNeighbors.push(edge.target);
      adjacencyList.set(edge.source, sourceNeighbors);
    }

    return adjacencyList;
  }

  /**
   * Find longest execution chains for performance analysis
   */
  private findLongestChains(graph: GraphDocument): string[][] {
    const adjacencyList = this.buildAdjacencyList(graph);
    const chains: string[][] = [];

    const dfs = (nodeId: string, currentChain: string[], visited: Set<string>): void => {
      if (visited.has(nodeId)) return;

      visited.add(nodeId);
      currentChain.push(nodeId);

      const neighbors = adjacencyList.get(nodeId) || [];
      if (neighbors.length === 0) {
        // End of chain
        if (currentChain.length > 1) {
          chains.push([...currentChain]);
        }
      } else {
        for (const neighbor of neighbors) {
          dfs(neighbor, [...currentChain], new Set(visited));
        }
      }
    };

    // Start DFS from nodes with no incoming edges
    const hasIncoming = new Set<string>();
    for (const neighbors of adjacencyList.values()) {
      neighbors.forEach(neighbor => hasIncoming.add(neighbor));
    }

    for (const nodeId of graph.nodes.keys()) {
      if (!hasIncoming.has(nodeId)) {
        dfs(nodeId, [], new Set());
      }
    }

    return chains.sort((a, b) => b.length - a.length);
  }
}

