            id: 'test-graph',
            nodes: nodes.map((node, index) => ({
                id: node.id || `node${index}`,
                type: node.type || 'text',
                data: node.data || {},
                position: { x: 0, y: 0 },
                ...node
            })),
            edges: edges.map((edge, index) => ({
                id: edge.id || `edge${index}`,
                source: edge.source || '',
                target: edge.target || '',
                ...edge
            })),
            metadata: {
                name: 'Test Graph',
                created: new Date(),
                modified: new Date(),
                version: '1.0.0'
            },
            version: '1.0.0'
        };
    }
});

import { MappingEngine } from '../src/engine/MappingEngine.js';
