                id: 'node1',
                type: 'text',
                data: { content: 'Simple test prompt' },
                position: { x: 0, y: 0 }
            }
        ],
        edges: [],
        metadata: {
            created: new Date(),
            modified: new Date(),
            version: '1.0'
        }
