                version: adaptor.version,
                supportedFormats: capabilities.supportedFormats
            },
            keyFeatures: capabilities.features
                .filter(f => f.supported)
                .slice(0, 5)
                .map(f => f.name),
            quickStart: this.generateQuickStart(adaptor)
        };
    }
