                platform: adaptor.platform,
                adaptorId: adaptor.id,
                error: errorMessage
            });
            return {
                platform: adaptor.platform,
                adaptorId: adaptor.id,
                adaptorVersion: adaptor.version,
                results: [{
                        id: 'validation-failed',
                        type: 'error',
                        severity: 'critical',
                        message: 'Platform validation failed',
                        description: errorMessage,
                        autoFixable: false
                    }],
                capabilities: {
                    supportedNodeTypes: [],
                    parameters: [],
                    limitations: [],
                    features: [],
                    supportedFormats: []
                },
                quality: {
                    overall: 0,
                    fidelity: 0,
                    compatibility: 0,
                    performance: 0,
                    completeness: 0,
                    breakdown: {
                        nodeTranslation: 0,
                        parameterMapping: 0,
                        featureSupport: 0,
                        semanticPreservation: 0,
                        syntaxValidity: 0
                    }
                },
                compatible: false,
                duration: Date.now() - startTime
            };
        }
    }
    /**
     * Analyze cross-platform compatibility issues
     */
    analyzeCrossPlatformCompatibility(platformResults) {
        const issues = [];
        // Find features supported by some but not all platforms
        const allFeatures = new Set();
        const platformFeatures = new Map();
        platformResults.forEach(result => {
            const features = new Set(result.capabilities.features
                .filter((f) => f.supported)
                .map((f) => f.name));
            platformFeatures.set(result.platform, features);
            features.forEach((f) => allFeatures.add(f));
        });
        allFeatures.forEach(feature => {
            const supportingPlatforms = Array.from(platformFeatures.entries())
                .filter(([_, features]) => features.has(feature))
                .map(([platform, _]) => platform);
            if (supportingPlatforms.length > 0 && supportingPlatforms.length < platformResults.length) {
                issues.push({
                    type: 'feature_support',
                    severity: 'medium',
                    feature,
                    supportingPlatforms,
                    unsupportedPlatforms: platformResults
                        .map(r => r.platform)
                        .filter(p => !supportingPlatforms.includes(p)),
                    description: `Feature "${feature}" is not supported across all platforms`,
                    impact: 'Reduced functionality on some platforms'
                });
            }
        });
        // Find node types with compatibility issues
        const nodeTypeSupport = new Map();
        platformResults.forEach(result => {
            result.capabilities.supportedNodeTypes.forEach((nodeType) => {
                if (!nodeTypeSupport.has(nodeType)) {
                    nodeTypeSupport.set(nodeType, []);
                }
                nodeTypeSupport.get(nodeType).push(result.platform);
            });
        });
        // TODO: Add more cross-platform analysis
        return issues;
    }
    /**
     * Aggregate validation results
     */
    aggregateResults(report, structuralResults, customResults) {
        const allResults = [
            ...structuralResults,
            ...customResults,
            ...Array.from(report.platformResults.values())
                .flatMap(pr => pr.results)
        ];
        allResults.forEach(result => {
            report.totalIssues++;
            if (result.type === 'error') {
                report.overallValid = false;
                if (result.severity === 'critical') {
                    report.summary.criticalErrors++;
                }
                else {
                    report.summary.highErrors++;
                }
            }
            else if (result.type === 'warning') {
                report.summary.mediumWarnings++;
            }
            else {
                report.summary.lowInfos++;
            }
        });
    }
    /**
     * Generate auto-fix suggestions
     */
    generateAutoFixSuggestions(report) {
        const suggestions = [];
        // Collect all auto-fixable issues from all platform results
        const autoFixableIssues = [];
        report.platformResults.forEach(platformResult => {
            const fixableResults = platformResult.results.filter(r => r.autoFixable);
            autoFixableIssues.push(...fixableResults);
        });
        // Group by issue type and create suggestions
        const fixGroups = new Map();
        autoFixableIssues.forEach(issue => {
            if (issue.suggestions && issue.suggestions.length > 0) {
                issue.suggestions.forEach(suggestion => {
                    let key;
                    if (suggestion.action && suggestion.action.targetId) {
                        key = `${suggestion.action.type}:${suggestion.action.targetId}`;
                    }
                    else {
                        // Fallback grouping by issue type for suggestions without actions
                        key = `${issue.type}:${issue.severity}:${suggestion.type}`;
                    }
                    if (!fixGroups.has(key)) {
                        fixGroups.set(key, []);
                    }
                    fixGroups.get(key).push(issue);
                });
            }
            else {
                // Create default suggestion for auto-fixable issues without explicit suggestions
                const key = `${issue.type}:${issue.severity}:default`;
                if (!fixGroups.has(key)) {
                    fixGroups.set(key, []);
                }
                fixGroups.get(key).push(issue);
            }
        });
        // Generate suggestions from groups
        fixGroups.forEach((issues, key) => {
            const firstIssue = issues[0];
            let suggestion;
            if (firstIssue.suggestions && firstIssue.suggestions.length > 0) {
                suggestion = firstIssue.suggestions[0];
            }
            else {
                // Create default suggestion
                suggestion = {
                    type: 'fix',
                    description: `Fix ${issues.length} ${firstIssue.type}${issues.length > 1 ? 's' : ''}`,
                    action: {
                        type: 'node_modify',
                        targetId: firstIssue.nodeId || firstIssue.edgeId || 'unknown',
                        changes: {}
                    }
                };
            }
            suggestions.push({
                id: `autofix-${key.replace(/:/g, '-')}`,
                type: suggestion.type || 'fix',
                description: suggestion.description,
                action: suggestion.action || {
                    type: 'node_modify',
                    targetId: 'unknown',
                    changes: {}
                },
                affectedIssues: issues.map(i => i.id),
                confidence: this.calculateFixConfidence(issues),
                impact: this.assessFixImpact(issues)
            });
        });
        return suggestions;
    }
    /**
     * Detect cycles in the graph
     */
    detectCycles(graph) {
        const cycles = [];
        const visited = new Set();
        const recursionStack = new Set();
        const path = [];
        const adjacencyList = new Map();
        // Build adjacency list
        graph.nodes.forEach(node => {
            adjacencyList.set(node.id, []);
        });
        graph.edges?.forEach(edge => {
            const targets = adjacencyList.get(edge.source) || [];
            targets.push(edge.target);
            adjacencyList.set(edge.source, targets);
        });
        const dfs = (nodeId) => {
            visited.add(nodeId);
            recursionStack.add(nodeId);
            path.push(nodeId);
            const neighbors = adjacencyList.get(nodeId) || [];
            for (const neighbor of neighbors) {
                if (!visited.has(neighbor)) {
                    if (dfs(neighbor)) {
                        return true;
                    }
                }
                else if (recursionStack.has(neighbor)) {
                    // Found cycle
                    const cycleStart = path.indexOf(neighbor);
                    cycles.push([...path.slice(cycleStart), neighbor]);
                    return true;
                }
            }
            recursionStack.delete(nodeId);
            path.pop();
            return false;
        };
        graph.nodes.forEach(node => {
            if (!visited.has(node.id)) {
                dfs(node.id);
            }
        });
        return cycles;
    }
    /**
     * Find connected components in the graph
     */
    findConnectedComponents(graph) {
        const visited = new Set();
        const components = [];
        const adjacencyList = new Map();
        // Build undirected adjacency list
        graph.nodes.forEach(node => {
            adjacencyList.set(node.id, []);
        });
        graph.edges?.forEach(edge => {
            const sourceTargets = adjacencyList.get(edge.source) || [];
            const targetTargets = adjacencyList.get(edge.target) || [];
            sourceTargets.push(edge.target);
            targetTargets.push(edge.source);
            adjacencyList.set(edge.source, sourceTargets);
            adjacencyList.set(edge.target, targetTargets);
        });
        const dfs = (nodeId, component) => {
            visited.add(nodeId);
            component.push(nodeId);
            const neighbors = adjacencyList.get(nodeId) || [];
            neighbors.forEach(neighbor => {
                if (!visited.has(neighbor)) {
                    dfs(neighbor, component);
                }
            });
        };
        graph.nodes.forEach(node => {
            if (!visited.has(node.id)) {
                const component = [];
                dfs(node.id, component);
                components.push(component);
            }
        });
        return components;
    }
    /**
     * Calculate confidence for an auto-fix suggestion
     */
    calculateFixConfidence(issues) {
        // Simple heuristic: more severe issues = lower confidence for auto-fix
        const severityWeights = { critical: 0.1, high: 0.3, medium: 0.7, low: 0.9 };
        const avgConfidence = issues.reduce((sum, issue) => {
            return sum + (severityWeights[issue.severity] || 0.5);
        }, 0) / issues.length;
        return Math.round(avgConfidence * 100);
    }
    /**
     * Assess impact of an auto-fix
     */
    assessFixImpact(issues) {
        const hasHighSeverity = issues.some(i => i.severity === 'critical' || i.severity === 'high');
        if (hasHighSeverity)
            return 'high';
        if (issues.length > 3)
            return 'medium';
        return 'low';
    }
    /**
     * Add custom validation rule
     */
    addCustomRule(rule) {
        this.customRules.push(rule);
        this.logger.info('Custom validation rule added', { ruleId: rule.id });
    }
    /**
     * Remove custom validation rule
     */
    removeCustomRule(ruleId) {
        const index = this.customRules.findIndex(rule => rule.id === ruleId);
        if (index >= 0) {
            this.customRules.splice(index, 1);
            this.logger.info('Custom validation rule removed', { ruleId });
        }
    }
}

import { PluginContext, ValidationResult, PromptGraph, TargetPrompt } from '../types/index.js';

/**
 * Lifecycle hooks for adaptor initialization, validation, and cleanup
 */
export interface AdaptorLifecycle {
  /**
   * Initialize the adaptor with context and configuration
   */
  initialize(context: PluginContext): Promise<void>;

  /**
   * Validate adaptor health and connectivity
   */
  healthCheck(): Promise<AdaptorHealthStatus>;

  /**
   * Pre-processing hook before validation
   */
  beforeValidate?(graph: PromptGraph): Promise<PromptGraph>;

  /**
   * Post-processing hook after validation
   */
  afterValidate?(graph: PromptGraph, results: ValidationResult[]): Promise<ValidationResult[]>;

  /**
   * Pre-processing hook before transformation
   */
  beforeTransform?(graph: PromptGraph): Promise<PromptGraph>;

  /**
   * Post-processing hook after transformation
   */
  afterTransform?(graph: PromptGraph, result: TargetPrompt): Promise<TargetPrompt>;

  /**
   * Cleanup resources and connections
   */
  destroy(): Promise<void>;

  /**
   * Handle configuration changes at runtime
   */
  onConfigurationChange?(newConfig: Record<string, any>): Promise<void>;

  /**
   * Handle capability refresh requests
   */
  onCapabilityRefresh?(): Promise<void>;
}

/**
 * Health status information for an adaptor
 */
export interface AdaptorHealthStatus {
  healthy: boolean;
  status: 'healthy' | 'degraded' | 'unhealthy' | 'unknown';
  lastChecked: Date;
  details: AdaptorHealthDetails;
  metrics: AdaptorHealthMetrics;
}

export interface AdaptorHealthDetails {
  connectivity: {
    reachable: boolean;
    latency?: number;
    lastSuccessfulConnection?: Date;
    errorMessage?: string;
  };
  capabilities: {
    available: boolean;
    lastUpdated?: Date;
    errorMessage?: string;
  };
  configuration: {
    valid: boolean;
    errorMessage?: string;
  };
  dependencies: AdaptorDependencyStatus[];
}

export interface AdaptorDependencyStatus {
  name: string;
  type: 'api' | 'service' | 'library' | 'configuration';
  status: 'available' | 'unavailable' | 'degraded';
  version?: string;
  errorMessage?: string;
}

export interface AdaptorHealthMetrics {
  uptime: number; // milliseconds
  requestCount: number;
  successRate: number; // 0-1
  averageResponseTime: number; // milliseconds
  errorRate: number; // 0-1
  lastError?: {
    timestamp: Date;
    message: string;
    type: string;
  };
}

/**
 * Pipeline stage interface for modular processing
 */
export interface PipelineStage<TInput, TOutput> {
  readonly name: string;
  readonly order: number;
  readonly required: boolean;

  canHandle(input: TInput): boolean;
  process(input: TInput, context: ProcessingContext): Promise<TOutput>;
  onError?(error: Error, input: TInput, context: ProcessingContext): Promise<TOutput | void>;
}

export interface ProcessingContext {
  adaptorId: string;
  requestId: string;
  startTime: Date;
  metadata: Record<string, any>;
  logger: any;
  metrics: any;
  config: Record<string, any>;
}

/**
 * Validation pipeline stage
 */
export interface ValidationPipelineStage extends PipelineStage<PromptGraph, ValidationResult[]> {
  readonly validationType: 'structural' | 'semantic' | 'platform' | 'performance' | 'security';
}

/**
 * Transformation pipeline stage
 */
export interface TransformationPipelineStage extends PipelineStage<PromptGraph, PartialTargetPrompt> {
  readonly transformationType: 'preprocessing' | 'core' | 'postprocessing' | 'optimization';
}

export interface PartialTargetPrompt {
  content?: string | object;
  parameters?: Record<string, any>;
  metadata?: Record<string, any>;
  format?: string;
}

/**
 * Enhanced adaptor registry for lifecycle management
 */
export class AdaptorRegistry {
  private adaptors = new Map<string, AdaptorLifecycle>();
  private healthStatuses = new Map<string, AdaptorHealthStatus>();
  private healthCheckInterval?: NodeJS.Timeout;

  constructor(
    private logger: any,
    private metrics: any,
    private healthCheckIntervalMs: number = 60000 // 1 minute
  ) {}

  /**
   * Register an adaptor with lifecycle management
   */
  async register(id: string, adaptor: AdaptorLifecycle, context: PluginContext): Promise<void> {
    try {
      await adaptor.initialize(context);
      this.adaptors.set(id, adaptor);

      const health = await adaptor.healthCheck();
      this.healthStatuses.set(id, health);

      this.logger.info('Adaptor registered successfully', { 
        adaptorId: id,
        healthy: health.healthy 
      });

      this.metrics.counter('adaptor.registered', 1, { adaptor_id: id });

      // Start health checking if this is the first adaptor
      if (this.adaptors.size === 1) {
        this.startHealthChecking();
      }
    } catch (error) {
      this.logger.error('Failed to register adaptor', {
        adaptorId: id,
        error: error.message
      });
      throw error;
    }
  }

  /**
   * Unregister an adaptor and cleanup resources
   */
  async unregister(id: string): Promise<void> {
    const adaptor = this.adaptors.get(id);
    if (adaptor) {
      try {
        await adaptor.destroy();
        this.adaptors.delete(id);
        this.healthStatuses.delete(id);

        this.logger.info('Adaptor unregistered successfully', { adaptorId: id });
        this.metrics.counter('adaptor.unregistered', 1, { adaptor_id: id });

        // Stop health checking if no adaptors remain
        if (this.adaptors.size === 0) {
          this.stopHealthChecking();
        }
      } catch (error) {
        this.logger.error('Error during adaptor cleanup', {
          adaptorId: id,
          error: error.message
        });
      }
    }
  }

  /**
   * Get all registered adaptors
   */
  getAdaptors(): Map<string, AdaptorLifecycle> {
    return new Map(this.adaptors);
  }

  /**
   * Get health status for all adaptors
   */
  getHealthStatuses(): Map<string, AdaptorHealthStatus> {
    return new Map(this.healthStatuses);
  }

  /**
   * Get health status for specific adaptor
   */
  getHealthStatus(adaptorId: string): AdaptorHealthStatus | undefined {
    return this.healthStatuses.get(adaptorId);
  }

  /**
   * Force health check for all adaptors
   */
  async checkHealth(): Promise<Map<string, AdaptorHealthStatus>> {
    const results = new Map<string, AdaptorHealthStatus>();

    for (const [id, adaptor] of this.adaptors.entries()) {
      try {
        const health = await adaptor.healthCheck();
        this.healthStatuses.set(id, health);
        results.set(id, health);

        this.metrics.gauge('adaptor.health.status', health.healthy ? 1 : 0, {
          adaptor_id: id
        });
      } catch (error) {
        const unhealthyStatus: AdaptorHealthStatus = {
          healthy: false,
          status: 'unhealthy',
          lastChecked: new Date(),
          details: {
            connectivity: {
              reachable: false,
              errorMessage: error.message
            },
            capabilities: { available: false },
            configuration: { valid: false },
            dependencies: []
          },
          metrics: {
            uptime: 0,
            requestCount: 0,
            successRate: 0,
            averageResponseTime: 0,
            errorRate: 1,
            lastError: {
              timestamp: new Date(),
              message: error.message,
              type: error.constructor.name
            }
          }
        };

        this.healthStatuses.set(id, unhealthyStatus);
        results.set(id, unhealthyStatus);

        this.logger.error('Health check failed', {
          adaptorId: id,
          error: error.message
        });
      }
    }

    return results;
  }

  /**
   * Start periodic health checking
   */
  private startHealthChecking(): void {
    if (this.healthCheckInterval) {
      return; // Already running
    }

    this.healthCheckInterval = setInterval(async () => {
      await this.checkHealth();
    }, this.healthCheckIntervalMs);

    this.logger.info('Started adaptor health checking', {
      intervalMs: this.healthCheckIntervalMs
    });
  }

  /**
   * Stop periodic health checking
   */
  private stopHealthChecking(): void {
    if (this.healthCheckInterval) {
      clearInterval(this.healthCheckInterval);
      this.healthCheckInterval = undefined;

      this.logger.info('Stopped adaptor health checking');
    }
  }

  /**
   * Cleanup all adaptors and stop health checking
   */
  async destroy(): Promise<void> {
    this.stopHealthChecking();

    const cleanupPromises = Array.from(this.adaptors.keys()).map(id => 
      this.unregister(id)
    );

    await Promise.all(cleanupPromises);

    this.logger.info('Adaptor registry destroyed');
  }
}

import {
  ModelAdaptor,
  Platform,
  Capabilities,
  PromptGraph,
  ValidationResult,
  TargetPrompt,
  TransformOptions,
  QualityScore,
  PluginContext,
  Logger,
  CacheInterface,
  MetricsInterface,
  TransformationError,
  ValidationError
} from '../types/index.js';

/**
 * Abstract base class for all model adaptors.
 * Provides common functionality and enforces the adaptor interface.
 */
export abstract class BaseAdaptor implements ModelAdaptor {
  protected logger: Logger;
  protected cache: CacheInterface;
  protected metrics: MetricsInterface;
  protected config: Record<string, any>;

  constructor(
    public readonly id: string,
    public readonly version: string,
    public readonly platform: Platform,
    public readonly name: string,
    public readonly description: string,
    context: PluginContext
  ) {
    this.logger = context.logger;
    this.cache = context.cache;
    this.metrics = context.metrics;
    this.config = context.config;
  }

  // Abstract methods that must be implemented by concrete adaptors
  abstract capabilities(): Promise<Capabilities>;
  protected abstract doTransform(graph: PromptGraph, options?: TransformOptions): Promise<TargetPrompt>;
  protected abstract doValidate(graph: PromptGraph): Promise<ValidationResult[]>;

  /**
   * Validates a prompt graph for compatibility with this adaptor
   */
  async validate(graph: PromptGraph): Promise<ValidationResult[]> {
    const timer = this.metrics.timer('adaptor.validate.duration');

    try {
      this.logger.debug('Starting validation', { 
        adaptorId: this.id, 
        graphId: graph.id 
      });

      // Basic structural validation
      const structuralResults = await this.validateStructure(graph);

      // Adaptor-specific validation
      const adaptorResults = await this.doValidate(graph);

      const allResults = [...structuralResults, ...adaptorResults];

      this.metrics.counter('adaptor.validate.total', 1, { 
        adaptor: this.id,
        platform: this.platform 
      });

      this.metrics.counter('adaptor.validate.issues', allResults.length, { 
        adaptor: this.id,
        platform: this.platform 
      });

      this.logger.info('Validation completed', {
        adaptorId: this.id,
        graphId: graph.id,
        issueCount: allResults.length
      });

      return allResults;
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : String(error);

      this.metrics.counter('adaptor.validate.error', 1, { 
        adaptor: this.id,
        platform: this.platform 
      });

      this.logger.error('Validation failed', {
        adaptorId: this.id,
        graphId: graph.id,
        error: errorMessage
      });

      throw new ValidationError(`Validation failed: ${errorMessage}`, []);
    } finally {
      timer.end();
    }
  }

  /**
   * Transforms a prompt graph into platform-specific format
   */
  async transform(graph: PromptGraph, options?: TransformOptions): Promise<TargetPrompt> {
    const timer = this.metrics.timer('adaptor.transform.duration');

    try {
      this.logger.debug('Starting transformation', {
        adaptorId: this.id,
        graphId: graph.id,
        options
      });

      // Validate first
      const validationResults = await this.validate(graph);
      const errors = validationResults.filter(r => r.type === 'error');

      if (errors.length > 0) {
        throw new ValidationError('Graph validation failed', validationResults);
      }

      // Check cache
      const cacheKey = this.generateCacheKey(graph, options);
      const cached = await this.cache.get(cacheKey);

      if (cached) {
        this.metrics.counter('adaptor.transform.cache.hit', 1, { 
          adaptor: this.id,
          platform: this.platform 
        });

        this.logger.debug('Cache hit for transformation', {
          adaptorId: this.id,
          graphId: graph.id,
          cacheKey
        });

        return cached;
      }

      // Perform transformation
      const result = await this.doTransform(graph, options);

      // Cache the result
      await this.cache.set(cacheKey, result, this.getCacheTTL());

      this.metrics.counter('adaptor.transform.success', 1, { 
        adaptor: this.id,
        platform: this.platform 
      });

      this.metrics.counter('adaptor.transform.cache.miss', 1, { 
        adaptor: this.id,
        platform: this.platform 
      });

      this.logger.info('Transformation completed', {
        adaptorId: this.id,
        graphId: graph.id,
        quality: result.metadata.quality.overall
      });

      return result;
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : String(error);

      this.metrics.counter('adaptor.transform.error', 1, { 
        adaptor: this.id,
        platform: this.platform 
      });

      this.logger.error('Transformation failed', {
        adaptorId: this.id,
        graphId: graph.id,
        error: errorMessage
      });

      if (error instanceof ValidationError || error instanceof TransformationError) {
        throw error;
      }

      throw new TransformationError(`Transformation failed: ${errorMessage}`);
    } finally {
      timer.end();
    }
  }

  /**
   * Estimates the quality of transformation for a given graph
   */
  async estimateQuality(graph: PromptGraph): Promise<QualityScore> {
    try {
      const capabilities = await this.capabilities();
      const validationResults = await this.validate(graph);

      return this.calculateQualityScore(graph, capabilities, validationResults);
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : String(error);
      this.logger.warn('Quality estimation failed', {
        adaptorId: this.id,
        graphId: graph.id,
        error: errorMessage
      });

      // Return a low quality score if estimation fails
      return {
        overall: 10,
        fidelity: 10,
        compatibility: 10,
        performance: 10,
        completeness: 10,
        breakdown: {
          nodeTranslation: 10,
          parameterMapping: 10,
          featureSupport: 10,
          semanticPreservation: 10,
          syntaxValidity: 10
        }
      };
    }
  }

  /**
   * Basic structural validation common to all adaptors
   */
  protected async validateStructure(graph: PromptGraph): Promise<ValidationResult[]> {
    const results: ValidationResult[] = [];

    // Check for empty graph
    if (!graph.nodes || graph.nodes.length === 0) {
      results.push({
        id: 'empty-graph',
        type: 'error',
        severity: 'critical',
        message: 'Graph is empty',
        description: 'The prompt graph contains no nodes',
        autoFixable: false
      });
    }

    // Check for disconnected nodes
    const nodeIds = new Set(graph.nodes.map(n => n.id));
    const connectedNodes = new Set<string>();

    graph.edges.forEach(edge => {
      connectedNodes.add(edge.source);
      connectedNodes.add(edge.target);
    });

    graph.nodes.forEach(node => {
      if (!connectedNodes.has(node.id) && graph.nodes.length > 1) {
        results.push({
          id: `disconnected-node-${node.id}`,
          type: 'warning',
          severity: 'medium',
          message: 'Disconnected node detected',
          description: `Node "${node.data.label || node.id}" is not connected to the graph`,
          nodeId: node.id,
          autoFixable: true,
          suggestions: [{
            type: 'fix',
            description: 'Remove disconnected node or connect it to the graph'
          }]
        });
      }
    });

    // Check for invalid edges
    graph.edges.forEach(edge => {
      if (!nodeIds.has(edge.source)) {
        results.push({
          id: `invalid-edge-source-${edge.id}`,
          type: 'error',
          severity: 'high',
          message: 'Invalid edge source',
          description: `Edge "${edge.id}" references non-existent source node "${edge.source}"`,
          edgeId: edge.id,
          autoFixable: true
        });
      }

      if (!nodeIds.has(edge.target)) {
        results.push({
          id: `invalid-edge-target-${edge.id}`,
          type: 'error',
          severity: 'high',
          message: 'Invalid edge target',
          description: `Edge "${edge.id}" references non-existent target node "${edge.target}"`,
          edgeId: edge.id,
          autoFixable: true
        });
      }
    });

    return results;
  }

  /**
   * Calculate quality score based on graph, capabilities, and validation results
   */
  protected calculateQualityScore(
    graph: PromptGraph,
    capabilities: Capabilities,
    validationResults: ValidationResult[]
  ): QualityScore {
    const errors = validationResults.filter(r => r.type === 'error').length;
    const warnings = validationResults.filter(r => r.type === 'warning').length;

    // Node type support analysis
    const unsupportedNodes = graph.nodes.filter(
      node => !capabilities.supportedNodeTypes.includes(node.type)
    ).length;

    const nodeSupport = Math.max(0, 100 - (unsupportedNodes / graph.nodes.length) * 100);

    // Error/warning impact
    const errorImpact = Math.max(0, 100 - errors * 25);
    const warningImpact = Math.max(0, 100 - warnings * 10);

    // Feature completeness
    const featureSupport = capabilities.features
      .filter(f => f.supported)
      .length / Math.max(1, capabilities.features.length) * 100;

    // Overall calculations
    const fidelity = (nodeSupport + errorImpact) / 2;
    const compatibility = (nodeSupport + featureSupport) / 2;
    const performance = warningImpact;
    const completeness = featureSupport;

    const overall = (fidelity + compatibility + performance + completeness) / 4;

    return {
      overall: Math.round(overall),
      fidelity: Math.round(fidelity),
      compatibility: Math.round(compatibility),
      performance: Math.round(performance),
      completeness: Math.round(completeness),
      breakdown: {
        nodeTranslation: Math.round(nodeSupport),
        parameterMapping: Math.round(featureSupport),
        featureSupport: Math.round(featureSupport),
        semanticPreservation: Math.round(fidelity),
        syntaxValidity: Math.round(errorImpact)
      }
    };
  }

  /**
   * Generate cache key for a graph and options combination
   */
  protected generateCacheKey(graph: PromptGraph, options?: TransformOptions): string {
    const graphHash = this.hashObject({
      nodes: graph.nodes,
      edges: graph.edges,
      version: graph.version
    });

    const optionsHash = options ? this.hashObject(options) : 'none';

    return `${this.id}:${this.version}:${graphHash}:${optionsHash}`;
  }

  /**
   * Simple object hashing for cache keys
   */
  protected hashObject(obj: any): string {
    const str = JSON.stringify(obj, Object.keys(obj).sort());
    let hash = 0;

    for (let i = 0; i < str.length; i++) {
      const char = str.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash; // Convert to 32-bit integer
    }

    return Math.abs(hash).toString(36);
  }

  /**
   * Get cache TTL for this adaptor's results
   */
  protected getCacheTTL(): number {
    return this.config.cacheTTL || 3600; // Default 1 hour
  }

  /**
   * Helper to create validation results
   */
  protected createValidationResult(
    id: string,
    type: 'error' | 'warning' | 'info',
    severity: 'critical' | 'high' | 'medium' | 'low',
    message: string,
    options: {
      description?: string;
      nodeId?: string;
      edgeId?: string;
      autoFixable?: boolean;
      suggestions?: Array<{ type: 'fix' | 'alternative' | 'workaround'; description: string }>;
    } = {}
  ): ValidationResult {
    return {
      id,
      type,
      severity,
      message,
      description: options.description,
      nodeId: options.nodeId,
      edgeId: options.edgeId,
      autoFixable: options.autoFixable || false,
      suggestions: options.suggestions || []
    };
  }
}

import {
  Capabilities,
  PromptGraph,
  PromptNode,
  ValidationResult,
  TargetPrompt,
  TransformOptions,
  ParameterSpec,
  Feature,
  PluginContext,
  TransformationLog
} from '../types/index.js';
import { BaseAdaptor } from './BaseAdaptor.js';

/**
 * DALL-E adaptor for text-to-image prompt translation
 * Supports DALL-E 3 and DALL-E 2 API parameters
 */
export class DallEAdaptor extends BaseAdaptor {
  private readonly supportedSizes = [
    '256x256', '512x512', '1024x1024', // DALL-E 2
    '1024x1024', '1792x1024', '1024x1792' // DALL-E 3
  ];

  private readonly supportedQualities = ['standard', 'hd'];
  private readonly supportedStyles = ['vivid', 'natural'];
  private readonly supportedModels = ['dall-e-2', 'dall-e-3'];

  constructor(context: PluginContext) {
    super(
      'dall-e',
      '1.0.0',
      'openai-dalle',
      'DALL-E Image Generator',
      'Adaptor for OpenAI DALL-E text-to-image generation',
      context
    );
  }

  async capabilities(): Promise<Capabilities> {
    return {
      supportedNodeTypes: [
        'text',
        'image', // For image references/editing
        'style',
        'conditional',
        'weighted',
        'concat',
        'output'
      ],
      parameters: [
        {
          name: 'model',
          type: 'enum',
          required: false,
          default: 'dall-e-3',
          options: this.supportedModels,
          description: 'DALL-E model version to use'
        },
        {
          name: 'size',
          type: 'enum',
          required: false,
          default: '1024x1024',
          options: this.supportedSizes,
          description: 'Image dimensions'
        },
        {
          name: 'quality',
          type: 'enum',
          required: false,
          default: 'standard',
          options: this.supportedQualities,
          description: 'Image quality (DALL-E 3 only)'
        },
        {
          name: 'style',
          type: 'enum',
          required: false,
          default: 'vivid',
          options: this.supportedStyles,
          description: 'Image style (DALL-E 3 only)'
        },
        {
          name: 'n',
          type: 'number',
          required: false,
          default: 1,
          min: 1,
          max: 4,
          description: 'Number of images to generate (DALL-E 2: 1-10, DALL-E 3: 1)'
        },
        {
          name: 'response_format',
          type: 'enum',
          required: false,
          default: 'url',
          options: ['url', 'b64_json'],
          description: 'Response format for generated images'
        }
      ],
      limitations: [
        {
          type: 'prompt_length',
          description: 'Maximum prompt length 4000 characters',
          severity: 'error',
          impact: 'Prompts exceeding 4000 characters will be rejected'
        },
        {
          type: 'feature',
          description: 'OpenAI content policy restrictions apply',
          severity: 'warning',
          impact: 'Images violating content policy will be rejected'
        },
        {
          type: 'feature',
          description: 'DALL-E 3 limited to 1 image per request',
          severity: 'info',
          impact: 'Multiple image generation requires separate API calls'
        }
      ],
      features: [
        {
          name: 'high_resolution',
          supported: true,
          description: 'Supports HD quality images (DALL-E 3)'
        },
        {
          name: 'style_control',
          supported: true,
          description: 'Vivid and natural style options (DALL-E 3)'
        },
        {
          name: 'image_editing',
          supported: true,
          description: 'Edit and variation capabilities'
        },
        {
          name: 'multiple_images',
          supported: true,
          description: 'Generate multiple variations (DALL-E 2)'
        },
        {
          name: 'custom_sizes',
          supported: false,
          description: 'Limited to predefined sizes only',
          alternatives: ['Choose from supported size options']
        }
      ],
      maxNodes: 15,
      maxPromptLength: 4000,
      supportedFormats: ['openai_dalle_prompt']
    };
  }

  protected async doValidate(graph: PromptGraph): Promise<ValidationResult[]> {
    const results: ValidationResult[] = [];
    const capabilities = await this.capabilities();

    // Check prompt length
    const estimatedPromptLength = this.estimatePromptLength(graph);
    if (estimatedPromptLength > capabilities.maxPromptLength!) {
      results.push(this.createValidationResult(
        'prompt-too-long',
        'error',
        'high',
        'Prompt exceeds DALL-E maximum length',
        {
          description: `Estimated length ${estimatedPromptLength} exceeds maximum ${capabilities.maxPromptLength}`,
          autoFixable: false,
          suggestions: [{
            type: 'fix',
            description: 'Simplify prompt or reduce content length'
          }]
        }
      ));
    }

    // Validate model-specific parameters
    const extractedParams = this.extractParameters(graph);
    const model = extractedParams.model || 'dall-e-3';

    // DALL-E 3 specific validations
    if (model === 'dall-e-3') {
      if (extractedParams.n && extractedParams.n > 1) {
        results.push(this.createValidationResult(
          'dalle3-multiple-images',
          'error',
          'medium',
          'DALL-E 3 only supports single image generation',
          {
            description: 'Parameter "n" must be 1 for DALL-E 3',
            autoFixable: true,
            suggestions: [{
              type: 'fix',
              description: 'Set n=1 or use DALL-E 2 for multiple images'
            }]
          }
        ));
      }

      // Check size compatibility
      if (extractedParams.size && !['1024x1024', '1792x1024', '1024x1792'].includes(extractedParams.size)) {
        results.push(this.createValidationResult(
          'dalle3-invalid-size',
          'warning',
          'medium',
          'Size not optimized for DALL-E 3',
          {
            description: `Size "${extractedParams.size}" may not be supported. Recommended: 1024x1024, 1792x1024, 1024x1792`,
            autoFixable: true,
            suggestions: [{
              type: 'fix',
              description: 'Use DALL-E 3 optimized sizes for best results'
            }]
          }
        ));
      }
    }

    // DALL-E 2 specific validations
    if (model === 'dall-e-2') {
      if (extractedParams.quality && extractedParams.quality !== 'standard') {
        results.push(this.createValidationResult(
          'dalle2-quality-not-supported',
          'warning',
          'low',
          'Quality parameter not supported in DALL-E 2',
          {
            description: 'Quality parameter is ignored for DALL-E 2',
            autoFixable: true,
            suggestions: [{
              type: 'fix',
              description: 'Remove quality parameter or upgrade to DALL-E 3'
            }]
          }
        ));
      }

      if (extractedParams.style && extractedParams.style !== 'vivid') {
        results.push(this.createValidationResult(
          'dalle2-style-not-supported',
          'warning',
          'low',
          'Style parameter not supported in DALL-E 2',
          {
            description: 'Style parameter is ignored for DALL-E 2',
            autoFixable: true,
            suggestions: [{
              type: 'fix',
              description: 'Remove style parameter or upgrade to DALL-E 3'
            }]
          }
        ));
      }
    }

    // Validate individual parameters
    graph.nodes.forEach(node => {
      if (node.data.parameters) {
        Object.entries(node.data.parameters).forEach(([key, value]) => {
          const paramSpec = capabilities.parameters.find(p => p.name === key);
          if (paramSpec) {
            const validation = this.validateParameter(key, value, paramSpec);
            if (validation) {
              results.push({
                ...validation,
                nodeId: node.id
              });
            }
          }
        });
      }
    });

    // Content policy checks (basic)
    const contentWarnings = this.checkContentPolicy(graph);
    results.push(...contentWarnings);

    return results;
  }

  protected async doTransform(graph: PromptGraph, options?: TransformOptions): Promise<TargetPrompt> {
    const transformations: TransformationLog[] = [];
    const capabilities = await this.capabilities();

    // Extract and normalize parameters
    const extractedParams = this.extractParameters(graph);
    const parameters: Record<string, any> = {};

    // Normalize parameters according to capabilities
    Object.entries(extractedParams).forEach(([key, value]) => {
      const paramSpec = capabilities.parameters.find(p => p.name === key);
      if (paramSpec) {
        parameters[key] = this.normalizeParameter(value, paramSpec);
      }
    });

    // Apply defaults for missing parameters
    capabilities.parameters.forEach(param => {
      if (param.default !== undefined && !(param.name in parameters)) {
        parameters[param.name] = param.default;
      }
    });

    // Process the graph to build prompt text
    const processedContent = await this.processGraph(graph, transformations);
    let promptText = processedContent.mainPrompt;

    // Apply DALL-E specific optimizations
    promptText = this.optimizeForDallE(promptText, parameters, transformations);

    // Ensure prompt length compliance
    if (promptText.length > capabilities.maxPromptLength!) {
      const truncated = promptText.substring(0, capabilities.maxPromptLength! - 3) + '...';
      transformations.push({
        step: 'truncate_prompt',
        action: 'Truncated prompt to fit length limit',
        details: {
          originalLength: promptText.length,
          truncatedLength: truncated.length,
          maxLength: capabilities.maxPromptLength
        }
      });
      promptText = truncated;
    }

    // Calculate quality score
    const validationResults = await this.doValidate(graph);
    const quality = this.calculateQualityScore(graph, capabilities, validationResults);

    const targetPrompt: TargetPrompt = {
      platform: this.platform,
      content: promptText,
      parameters,
      format: 'openai_dalle_prompt',
      metadata: {
        originalGraphId: graph.id,
        translationId: this.generateTranslationId(),
        timestamp: new Date(),
        adaptorVersion: this.version,
        quality,
        warnings: validationResults.filter(r => r.type === 'warning'),
        transformations,
        apiParameters: this.buildApiParameters(parameters)
      }
    };

    return targetPrompt;
  }

  /**
   * Process the graph to extract content and build prompt
   */
  private async processGraph(graph: PromptGraph, transformations: TransformationLog[]): Promise<{
    mainPrompt: string;
  }> {
    let mainPrompt = '';
    const processedElements: string[] = [];

    // Find output nodes first
    const outputNodes = graph.nodes.filter(node => node.type === 'output');

    if (outputNodes.length === 0) {
      // No output nodes - process all content nodes
      const contentNodes = graph.nodes.filter(node => 
        ['text', 'style', 'image'].includes(node.type) && 
        (node.data.content || node.data.description)
      );

      for (const node of contentNodes) {
        const content = await this.processNode(node, graph, transformations);
        if (content) {
          processedElements.push(content);
        }
      }

      transformations.push({
        step: 'process_all_content_nodes',
        action: 'Processed all content nodes as no output nodes found',
        details: { nodeCount: contentNodes.length }
      });
    } else {
      // Process output nodes
      for (const outputNode of outputNodes) {
        const content = await this.processNode(outputNode, graph, transformations);
        if (content) {
          processedElements.push(content);
        }
      }
    }

    // Join elements with natural language flow
    mainPrompt = processedElements.join('. ').trim();

    // Clean up formatting
    mainPrompt = mainPrompt
      .replace(/\.\s*\./g, '.') // Remove double periods
      .replace(/\s+/g, ' ') // Multiple spaces
      .trim();

    return { mainPrompt };
  }

  /**
   * Process a single node and its dependencies
   */
  private async processNode(
    node: PromptNode,
    graph: PromptGraph,
    transformations: TransformationLog[],
    visited: Set<string> = new Set()
  ): Promise<string> {
    if (visited.has(node.id)) {
      return '';
    }
    visited.add(node.id);

    let content = '';

    // Get input edges for this node
    const inputEdges = graph.edges.filter(edge => edge.target === node.id);

    if (inputEdges.length > 0) {
      // Process input nodes first
      const inputContents: string[] = [];
      for (const edge of inputEdges) {
        const sourceNode = graph.nodes.find(n => n.id === edge.source);
        if (sourceNode) {
          const sourceContent = await this.processNode(sourceNode, graph, transformations, visited);
          if (sourceContent) {
            inputContents.push(sourceContent);
          }
        }
      }
      content = inputContents.join(' ');
    }

    // Process current node content
    switch (node.type) {
      case 'text':
        const textContent = node.data.content || '';
        content = content ? `${content} ${textContent}` : textContent;
        break;

      case 'style':
        const styleContent = node.data.style || node.data.content || '';
        if (styleContent) {
          content = content ? `${content}, in ${styleContent} style` : `in ${styleContent} style`;
          transformations.push({
            step: 'process_style',
            sourceNodeId: node.id,
            action: 'Added style descriptor',
            details: { style: styleContent }
          });
        }
        break;

      case 'image':
        const imageDesc = node.data.description || node.data.content || '';
        if (imageDesc) {
          content = content ? `${content}, inspired by ${imageDesc}` : `inspired by ${imageDesc}`;
          transformations.push({
            step: 'process_image_reference',
            sourceNodeId: node.id,
            action: 'Added image inspiration',
            details: { description: imageDesc }
          });
        }
        break;

      case 'weighted':
        if (node.data.options && node.data.options.length > 0) {
          const selectedOption = this.selectWeightedOption(node.data.options);
          content = content ? `${content} ${selectedOption.text}` : selectedOption.text;
          transformations.push({
            step: 'process_weighted',
            sourceNodeId: node.id,
            action: 'Selected weighted option',
            details: { selectedIndex: selectedOption.index, weight: selectedOption.weight }
          });
        }
        break;

      case 'conditional':
        if (node.data.trueBranch) {
          content = content ? `${content} ${node.data.trueBranch}` : node.data.trueBranch;
          transformations.push({
            step: 'process_conditional',
            sourceNodeId: node.id,
            action: 'Selected true branch',
            details: { condition: node.data.condition }
          });
        }
        break;

      default:
        if (node.data.content) {
          content = content ? `${content} ${node.data.content}` : node.data.content;
        }
    }

    return content.trim();
  }

  /**
   * Optimize prompt for DALL-E
   */
  private optimizeForDallE(
    prompt: string,
    parameters: Record<string, any>,
    transformations: TransformationLog[]
  ): string {
    let optimized = prompt;

    // Add descriptive elements if prompt is too simple
    if (optimized.length < 50) {
      optimized = `A detailed image of ${optimized}`;
      transformations.push({
        step: 'enhance_simple_prompt',
        action: 'Enhanced short prompt with descriptive prefix',
        details: { originalLength: prompt.length }
      });
    }

    // Add quality descriptors for HD mode
    if (parameters.quality === 'hd') {
      const hasQualityDescriptors = /\b(detailed|sharp|clear|crisp|high.?quality|professional)\b/i.test(optimized);
      if (!hasQualityDescriptors) {
        optimized += ', highly detailed and sharp';
        transformations.push({
          step: 'add_hd_descriptors',
          action: 'Added quality descriptors for HD mode',
          details: { added: 'highly detailed and sharp' }
        });
      }
    }

    // Style-specific optimizations
    if (parameters.style === 'vivid') {
      const hasColorDescriptors = /\b(vibrant|bright|colorful|vivid|bold)\b/i.test(optimized);
      if (!hasColorDescriptors && optimized.length < 3500) {
        optimized += ', with vibrant colors';
        transformations.push({
          step: 'add_vivid_descriptors',
          action: 'Added color descriptors for vivid style',
          details: { added: 'with vibrant colors' }
        });
      }
    }

    return optimized.trim();
  }

  /**
   * Check for potential content policy issues
   */
  private checkContentPolicy(graph: PromptGraph): ValidationResult[] {
    const results: ValidationResult[] = [];
    const flaggedTerms = [
      'violent', 'gore', 'blood', 'weapon', 'gun', 'knife',
      'nude', 'naked', 'sexual', 'erotic', 'porn',
      'hate', 'racist', 'discriminatory'
    ];

    graph.nodes.forEach(node => {
      const content = (node.data.content || '').toLowerCase();
      const flaggedWords = flaggedTerms.filter(term => content.includes(term));

      if (flaggedWords.length > 0) {
        results.push(this.createValidationResult(
          `content-policy-${node.id}`,
          'warning',
          'high',
          'Potential content policy issue',
          {
            description: `Content may violate OpenAI policy. Flagged terms: ${flaggedWords.join(', ')}`,
            autoFixable: false,
            nodeId: node.id,
            suggestions: [{
              type: 'workaround',
              description: 'Review content for policy compliance before generation'
            }]
          }
        ));
      }
    });

    return results;
  }

  /**
   * Build API parameters for OpenAI DALL-E API
   */
  private buildApiParameters(parameters: Record<string, any>): Record<string, any> {
    const apiParams: Record<string, any> = {};

    // Map internal parameters to API parameters
    if (parameters.model) apiParams.model = parameters.model;
    if (parameters.size) apiParams.size = parameters.size;
    if (parameters.quality && parameters.model === 'dall-e-3') {
      apiParams.quality = parameters.quality;
    }
    if (parameters.style && parameters.model === 'dall-e-3') {
      apiParams.style = parameters.style;
    }
    if (parameters.n) {
      // DALL-E 3 only supports n=1
      apiParams.n = parameters.model === 'dall-e-3' ? 1 : parameters.n;
    }
    if (parameters.response_format) {
      apiParams.response_format = parameters.response_format;
    }

    return apiParams;
  }

  /**
   * Estimate prompt length
   */
  private estimatePromptLength(graph: PromptGraph): number {
    let totalLength = 0;

    graph.nodes.forEach(node => {
      if (node.data.content) totalLength += node.data.content.length;
      if (node.data.description) totalLength += node.data.description.length;
      if (node.data.style) totalLength += node.data.style.length;
    });

    return totalLength;
  }

  /**
   * Extract parameters from graph nodes
   */
  private extractParameters(graph: PromptGraph): Record<string, any> {
    const parameters: Record<string, any> = {};

    graph.nodes.forEach(node => {
      if (node.data.parameters) {
        Object.assign(parameters, node.data.parameters);
      }
    });

    return parameters;
  }

  /**
   * Select weighted option (simplified implementation)
   */
  private selectWeightedOption(options: any[]): { text: string; index: number; weight: number } {
    if (!options || options.length === 0) {
      return { text: '', index: -1, weight: 0 };
    }

    const selected = options[0];
    return {
      text: selected.text || selected.content || '',
      index: 0,
      weight: selected.weight || 1
    };
  }

  /**
   * Generate a unique translation ID
   */
  private generateTranslationId(): string {
    return `${this.id}-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }

  /**
   * Validate parameter value against specification
   */
  private validateParameter(
    name: string,
    value: any,
    spec: ParameterSpec
  ): ValidationResult | null {
    if (spec.type === 'number') {
      if (typeof value !== 'number' || isNaN(value)) {
        return this.createValidationResult(
          `invalid-param-${name}`,
          'error',
          'medium',
          `Invalid number value for parameter "${name}"`,
          {
            description: `Expected number, got ${typeof value}`,
            autoFixable: true
          }
        );
      }

      if (spec.min !== undefined && value < spec.min) {
        return this.createValidationResult(
          `param-too-low-${name}`,
          'warning',
          'low',
          `Parameter "${name}" value too low`,
          {
            description: `Value ${value} is below minimum ${spec.min}`,
            autoFixable: true
          }
        );
      }

      if (spec.max !== undefined && value > spec.max) {
        return this.createValidationResult(
          `param-too-high-${name}`,
          'warning',
          'low',
          `Parameter "${name}" value too high`,
          {
            description: `Value ${value} is above maximum ${spec.max}`,
            autoFixable: true
          }
        );
      }
    }

    if (spec.type === 'enum' && spec.options) {
      if (!spec.options.includes(value)) {
        return this.createValidationResult(
          `invalid-enum-${name}`,
          'error',
          'medium',
          `Invalid enum value for parameter "${name}"`,
          {
            description: `Value "${value}" not in allowed options: ${spec.options.join(', ')}`,
            autoFixable: true
          }
        );
      }
    }

    return null;
  }

  /**
   * Normalize parameter value according to specification
   */
  private normalizeParameter(value: any, spec: ParameterSpec): any {
    if (spec.type === 'number') {
      const num = Number(value);
      if (isNaN(num)) return spec.default;

      if (spec.min !== undefined) return Math.max(spec.min, num);
      if (spec.max !== undefined) return Math.min(spec.max, num);

      return num;
    }

    if (spec.type === 'enum' && spec.options) {
      return spec.options.includes(value) ? value : spec.default;
    }

    return value;
  }
}

import {
  ModelAdaptor,
  Platform,
  Capabilities,
  PromptGraph,
  ValidationResult,
  TargetPrompt,
  TransformOptions,
  QualityScore,
  PluginContext,
  Logger,
  CacheInterface,
  MetricsInterface,
  TransformationError,
  ValidationError
} from '../types/index.js';

import {
  AdaptorLifecycle,
  AdaptorHealthStatus,
  AdaptorHealthDetails,
  AdaptorHealthMetrics,
  PipelineStage,
  ProcessingContext,
  ValidationPipelineStage,
  TransformationPipelineStage,
  PartialTargetPrompt
} from './AdaptorLifecycle.js';

/**
 * Enhanced base adaptor with lifecycle management and pipeline processing
 */
export abstract class EnhancedBaseAdaptor implements ModelAdaptor, AdaptorLifecycle {
  protected logger: Logger;
  protected cache: CacheInterface;
  protected metrics: MetricsInterface;
  protected config: Record<string, any>;

  // Lifecycle tracking
  protected initialized = false;
  protected destroyed = false;
  protected initializeTime?: Date;
  protected lastHealthCheck?: Date;
  protected healthMetrics: AdaptorHealthMetrics;

  // Pipeline stages
  protected validationPipeline: ValidationPipelineStage[] = [];
  protected transformationPipeline: TransformationPipelineStage[] = [];

  constructor(
    public readonly id: string,
    public readonly version: string,
    public readonly platform: Platform,
    public readonly name: string,
    public readonly description: string,
    context?: PluginContext
  ) {
    if (context) {
      this.logger = context.logger;
      this.cache = context.cache;
      this.metrics = context.metrics;
      this.config = context.config;
    }

    this.healthMetrics = {
      uptime: 0,
      requestCount: 0,
      successRate: 1,
      averageResponseTime: 0,
      errorRate: 0
    };

    this.setupDefaultPipelines();
  }

  // Abstract methods that must be implemented by concrete adaptors
  abstract capabilities(): Promise<Capabilities>;
  protected abstract doValidate(graph: PromptGraph): Promise<ValidationResult[]>;
  protected abstract doTransform(graph: PromptGraph, options?: TransformOptions): Promise<TargetPrompt>;

  // Optional lifecycle hooks that can be overridden
  protected async onInitialize?(): Promise<void>;
  protected async onDestroy?(): Promise<void>;
  protected async onHealthCheck?(): Promise<Partial<AdaptorHealthDetails>>;

  /**
   * Initialize the adaptor with context and configuration
   */
  async initialize(context: PluginContext): Promise<void> {
    if (this.initialized) {
      return;
    }

    try {
      this.logger = context.logger;
      this.cache = context.cache;
      this.metrics = context.metrics;
      this.config = context.config;

      this.initializeTime = new Date();

      // Run custom initialization if provided
      if (this.onInitialize) {
        await this.onInitialize();
      }

      this.initialized = true;

      this.logger.info('Adaptor initialized successfully', {
        adaptorId: this.id,
        version: this.version,
        platform: this.platform
      });

      this.metrics.counter('adaptor.initialize.success', 1, {
        adaptor_id: this.id,
        platform: this.platform
      });
    } catch (error) {
      this.logger.error('Adaptor initialization failed', {
        adaptorId: this.id,
        error: error.message
      });

      this.metrics.counter('adaptor.initialize.error', 1, {
        adaptor_id: this.id,
        platform: this.platform
      });

      throw new TransformationError(`Initialization failed: ${error.message}`, undefined, 'initialize');
    }
  }

  /**
   * Validate adaptor health and connectivity
   */
  async healthCheck(): Promise<AdaptorHealthStatus> {
    const startTime = Date.now();
    this.lastHealthCheck = new Date();

    try {
      // Update uptime
      if (this.initializeTime) {
        this.healthMetrics.uptime = Date.now() - this.initializeTime.getTime();
      }

      // Basic health checks
      const details: AdaptorHealthDetails = {
        connectivity: {
          reachable: this.initialized && !this.destroyed,
          latency: 0,
          lastSuccessfulConnection: this.initializeTime
        },
        capabilities: {
          available: this.initialized,
          lastUpdated: this.initializeTime
        },
        configuration: {
          valid: this.validateConfiguration()
        },
        dependencies: await this.checkDependencies()
      };

      // Run custom health checks if provided
      if (this.onHealthCheck) {
        const customDetails = await this.onHealthCheck();
        Object.assign(details, customDetails);
      }

      // Test basic functionality
      try {
        await this.capabilities();
        details.capabilities.available = true;
      } catch (error) {
        details.capabilities.available = false;
        details.capabilities.errorMessage = error.message;
      }

      const healthy = details.connectivity.reachable && 
                     details.capabilities.available && 
                     details.configuration.valid;

      const status: AdaptorHealthStatus = {
        healthy,
        status: healthy ? 'healthy' : 'degraded',
        lastChecked: this.lastHealthCheck,
        details,
        metrics: { ...this.healthMetrics }
      };

      // Update connectivity latency
      status.details.connectivity.latency = Date.now() - startTime;

      this.metrics.gauge('adaptor.health.latency', status.details.connectivity.latency, {
        adaptor_id: this.id
      });

      return status;
    } catch (error) {
      this.logger.error('Health check failed', {
        adaptorId: this.id,
        error: error.message
      });

      return {
        healthy: false,
        status: 'unhealthy',
        lastChecked: this.lastHealthCheck,
        details: {
          connectivity: {
            reachable: false,
            errorMessage: error.message
          },
          capabilities: { available: false },
          configuration: { valid: false },
          dependencies: []
        },
        metrics: { ...this.healthMetrics }
      };
    }
  }

  /**
   * Enhanced validation with pipeline processing
   */
  async validate(graph: PromptGraph): Promise<ValidationResult[]> {
    if (!this.initialized) {
      throw new ValidationError('Adaptor not initialized', []);
    }

    const timer = this.metrics.timer('adaptor.validate.duration');
    const startTime = Date.now();
    this.healthMetrics.requestCount++;

    try {
      this.logger.debug('Starting validation', { 
        adaptorId: this.id, 
        graphId: graph.id 
      });

      // Pre-processing hook
      let processedGraph = graph;
      if (this.beforeValidate) {
        processedGraph = await this.beforeValidate(graph);
      }

      // Run validation pipeline
      let allResults: ValidationResult[] = [];

      const context: ProcessingContext = {
        adaptorId: this.id,
        requestId: `val-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
        startTime: new Date(),
        metadata: { originalGraphId: graph.id },
        logger: this.logger,
        metrics: this.metrics,
        config: this.config
      };

      // Execute validation pipeline stages
      for (const stage of this.validationPipeline) {
        if (stage.canHandle(processedGraph)) {
          try {
            const stageResults = await stage.process(processedGraph, context);
            allResults.push(...stageResults);
          } catch (error) {
            if (stage.onError) {
              const errorResults = await stage.onError(error, processedGraph, context);
              if (errorResults) {
                allResults.push(...errorResults);
              }
            } else {
              allResults.push({
                id: `pipeline-error-${stage.name}`,
                type: 'error',
                severity: 'high',
                message: `Validation stage "${stage.name}" failed`,
                description: error.message,
                autoFixable: false
              });
            }
          }
        }
      }

      // Run adaptor-specific validation
      const adaptorResults = await this.doValidate(processedGraph);
      allResults.push(...adaptorResults);

      // Post-processing hook
      if (this.afterValidate) {
        allResults = await this.afterValidate(processedGraph, allResults);
      }

      // Update metrics
      const duration = Date.now() - startTime;
      this.updateSuccessMetrics(duration);

      this.metrics.counter('adaptor.validate.total', 1, { 
        adaptor: this.id,
        platform: this.platform 
      });

      this.metrics.counter('adaptor.validate.issues', allResults.length, { 
        adaptor: this.id,
        platform: this.platform 
      });

      this.logger.info('Validation completed', {
        adaptorId: this.id,
        graphId: graph.id,
        issueCount: allResults.length,
        duration
      });

      return allResults;
    } catch (error) {
      this.updateErrorMetrics(Date.now() - startTime, error);

      this.metrics.counter('adaptor.validate.error', 1, { 
        adaptor: this.id,
        platform: this.platform 
      });

      this.logger.error('Validation failed', {
        adaptorId: this.id,
        graphId: graph.id,
        error: error.message
      });

      if (error instanceof ValidationError) {
        throw error;
      }

      throw new ValidationError(`Validation failed: ${error.message}`, []);
    } finally {
      timer.end();
    }
  }

  /**
   * Enhanced transformation with pipeline processing
   */
  async transform(graph: PromptGraph, options?: TransformOptions): Promise<TargetPrompt> {
    if (!this.initialized) {
      throw new TransformationError('Adaptor not initialized');
    }

    const timer = this.metrics.timer('adaptor.transform.duration');
    const startTime = Date.now();
    this.healthMetrics.requestCount++;

    try {
      this.logger.debug('Starting transformation', {
        adaptorId: this.id,
        graphId: graph.id,
        options
      });

      // Validate first
      const validationResults = await this.validate(graph);
      const errors = validationResults.filter(r => r.type === 'error');

      if (errors.length > 0) {
        throw new ValidationError('Graph validation failed', validationResults);
      }

      // Pre-processing hook
      let processedGraph = graph;
      if (this.beforeTransform) {
        processedGraph = await this.beforeTransform(graph);
      }

      // Check cache
      const cacheKey = this.generateCacheKey(processedGraph, options);
      const cached = await this.cache.get(cacheKey);

      if (cached) {
        this.metrics.counter('adaptor.transform.cache.hit', 1, { 
          adaptor: this.id,
          platform: this.platform 
        });

        this.logger.debug('Cache hit for transformation', {
          adaptorId: this.id,
          graphId: graph.id,
          cacheKey
        });

        this.updateSuccessMetrics(Date.now() - startTime);
        return cached;
      }

      // Run transformation pipeline
      const context: ProcessingContext = {
        adaptorId: this.id,
        requestId: `trans-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
        startTime: new Date(),
        metadata: { originalGraphId: graph.id, options },
        logger: this.logger,
        metrics: this.metrics,
        config: this.config
      };

      let partialResult: PartialTargetPrompt = {};

      // Execute transformation pipeline stages
      for (const stage of this.transformationPipeline) {
        if (stage.canHandle(processedGraph)) {
          try {
            const stageResult = await stage.process(processedGraph, context);

            // Merge stage results
            if (stageResult.content !== undefined) {
              partialResult.content = stageResult.content;
            }
            if (stageResult.parameters) {
              partialResult.parameters = { ...partialResult.parameters, ...stageResult.parameters };
            }
            if (stageResult.metadata) {
              partialResult.metadata = { ...partialResult.metadata, ...stageResult.metadata };
            }
            if (stageResult.format) {
              partialResult.format = stageResult.format;
            }
          } catch (error) {
            if (stage.onError) {
              const errorResult = await stage.onError(error, processedGraph, context);
              if (errorResult) {
                // Handle error recovery
              }
            }

            if (stage.required) {
              throw new TransformationError(
                `Required transformation stage "${stage.name}" failed: ${error.message}`,
                undefined,
                stage.name
              );
            }
          }
        }
      }

      // Run core adaptor transformation
      let result = await this.doTransform(processedGraph, options);

      // Merge pipeline results with core results
      if (partialResult.content !== undefined) {
        result.content = partialResult.content;
      }
      if (partialResult.parameters) {
        result.parameters = { ...result.parameters, ...partialResult.parameters };
      }
      if (partialResult.metadata) {
        result.metadata = { ...result.metadata, ...partialResult.metadata };
      }
      if (partialResult.format) {
        result.format = partialResult.format;
      }

      // Post-processing hook
      if (this.afterTransform) {
        result = await this.afterTransform(processedGraph, result);
      }

      // Cache the result
      await this.cache.set(cacheKey, result, this.getCacheTTL());

      // Update metrics
      const duration = Date.now() - startTime;
      this.updateSuccessMetrics(duration);

      this.metrics.counter('adaptor.transform.success', 1, { 
        adaptor: this.id,
        platform: this.platform 
      });

      this.metrics.counter('adaptor.transform.cache.miss', 1, { 
        adaptor: this.id,
        platform: this.platform 
      });

      this.logger.info('Transformation completed', {
        adaptorId: this.id,
        graphId: graph.id,
        quality: result.metadata.quality.overall,
        duration
      });

      return result;
    } catch (error) {
      this.updateErrorMetrics(Date.now() - startTime, error);

      this.metrics.counter('adaptor.transform.error', 1, { 
        adaptor: this.id,
        platform: this.platform 
      });

      this.logger.error('Transformation failed', {
        adaptorId: this.id,
        graphId: graph.id,
        error: error.message
      });

      if (error instanceof ValidationError || error instanceof TransformationError) {
        throw error;
      }

      throw new TransformationError(`Transformation failed: ${error.message}`);
    } finally {
      timer.end();
    }
  }

  /**
   * Estimates the quality of transformation for a given graph
   */
  async estimateQuality(graph: PromptGraph): Promise<QualityScore> {
    try {
      const capabilities = await this.capabilities();
      const validationResults = await this.validate(graph);

      return this.calculateQualityScore(graph, capabilities, validationResults);
    } catch (error) {
      this.logger.warn('Quality estimation failed', {
        adaptorId: this.id,
        graphId: graph.id,
        error: error.message
      });

      // Return a low quality score if estimation fails
      return {
        overall: 10,
        fidelity: 10,
        compatibility: 10,
        performance: 10,
        completeness: 10,
        breakdown: {
          nodeTranslation: 10,
          parameterMapping: 10,
          featureSupport: 10,
          semanticPreservation: 10,
          syntaxValidity: 10
        }
      };
    }
  }

  /**
   * Cleanup resources and connections
   */
  async destroy(): Promise<void> {
    if (this.destroyed) {
      return;
    }

    try {
      // Run custom cleanup if provided
      if (this.onDestroy) {
        await this.onDestroy();
      }

      this.destroyed = true;
      this.initialized = false;

      this.logger.info('Adaptor destroyed successfully', {
        adaptorId: this.id
      });

      this.metrics.counter('adaptor.destroy.success', 1, {
        adaptor_id: this.id,
        platform: this.platform
      });
    } catch (error) {
      this.logger.error('Adaptor destruction failed', {
        adaptorId: this.id,
        error: error.message
      });

      this.metrics.counter('adaptor.destroy.error', 1, {
        adaptor_id: this.id,
        platform: this.platform
      });

      throw error;
    }
  }

  /**
   * Handle configuration changes at runtime
   */
  async onConfigurationChange(newConfig: Record<string, any>): Promise<void> {
    this.config = { ...this.config, ...newConfig };

    this.logger.info('Configuration updated', {
      adaptorId: this.id,
      configKeys: Object.keys(newConfig)
    });

    this.metrics.counter('adaptor.config.change', 1, {
      adaptor_id: this.id
    });
  }

  /**
   * Setup default validation and transformation pipelines
   */
  protected setupDefaultPipelines(): void {
    // Default validation stages can be added here
    // Concrete adaptors can override this method to customize pipelines
  }

  /**
   * Add a validation pipeline stage
   */
  protected addValidationStage(stage: ValidationPipelineStage): void {
    this.validationPipeline.push(stage);
    this.validationPipeline.sort((a, b) => a.order - b.order);
  }

  /**
   * Add a transformation pipeline stage
   */
  protected addTransformationStage(stage: TransformationPipelineStage): void {
    this.transformationPipeline.push(stage);
    this.transformationPipeline.sort((a, b) => a.order - b.order);
  }

  /**
   * Validate current configuration
   */
  protected validateConfiguration(): boolean {
    try {
      // Basic validation - can be overridden by concrete adaptors
      return this.config !== null && typeof this.config === 'object';
    } catch {
      return false;
    }
  }

  /**
   * Check adaptor dependencies
   */
  protected async checkDependencies(): Promise<any[]> {
    // Default implementation - can be overridden by concrete adaptors
    return [];
  }

  /**
   * Update success metrics
   */
  protected updateSuccessMetrics(duration: number): void {
    const oldCount = this.healthMetrics.requestCount - 1;
    const oldAvg = this.healthMetrics.averageResponseTime;

    this.healthMetrics.averageResponseTime = 
      (oldAvg * oldCount + duration) / this.healthMetrics.requestCount;

    this.healthMetrics.successRate = 
      (this.healthMetrics.successRate * oldCount + 1) / this.healthMetrics.requestCount;
  }

  /**
   * Update error metrics
   */
  protected updateErrorMetrics(duration: number, error: Error): void {
    this.healthMetrics.lastError = {
      timestamp: new Date(),
      message: error.message,
      type: error.constructor.name
    };

    const oldCount = this.healthMetrics.requestCount - 1;
    const oldAvg = this.healthMetrics.averageResponseTime;
    const oldSuccessRate = this.healthMetrics.successRate;

    this.healthMetrics.averageResponseTime = 
      (oldAvg * oldCount + duration) / this.healthMetrics.requestCount;

    this.healthMetrics.successRate = 
      (oldSuccessRate * oldCount) / this.healthMetrics.requestCount;

    this.healthMetrics.errorRate = 1 - this.healthMetrics.successRate;
  }

  // Inherit utility methods from BaseAdaptor
  protected generateCacheKey(graph: PromptGraph, options?: TransformOptions): string {
    const graphHash = this.hashObject({
      nodes: graph.nodes,
      edges: graph.edges,
      version: graph.version
    });

    const optionsHash = options ? this.hashObject(options) : 'none';

    return `${this.id}:${this.version}:${graphHash}:${optionsHash}`;
  }

  protected hashObject(obj: any): string {
    const str = JSON.stringify(obj, Object.keys(obj).sort());
    let hash = 0;

    for (let i = 0; i < str.length; i++) {
      const char = str.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash;
    }

    return Math.abs(hash).toString(36);
  }

  protected getCacheTTL(): number {
    return this.config.cacheTTL || 3600;
  }

  protected calculateQualityScore(
    graph: PromptGraph,
    capabilities: Capabilities,
    validationResults: ValidationResult[]
  ): QualityScore {
    const errors = validationResults.filter(r => r.type === 'error').length;
    const warnings = validationResults.filter(r => r.type === 'warning').length;

    // Node type support analysis
    const unsupportedNodes = graph.nodes.filter(
      node => !capabilities.supportedNodeTypes.includes(node.type)
    ).length;

    const nodeSupport = Math.max(0, 100 - (unsupportedNodes / graph.nodes.length) * 100);

    // Error/warning impact
    const errorImpact = Math.max(0, 100 - errors * 25);
    const warningImpact = Math.max(0, 100 - warnings * 10);

    // Feature completeness
    const featureSupport = capabilities.features
      .filter(f => f.supported)
      .length / Math.max(1, capabilities.features.length) * 100;

    // Overall calculations
    const fidelity = (nodeSupport + errorImpact) / 2;
    const compatibility = (nodeSupport + featureSupport) / 2;
    const performance = warningImpact;
    const completeness = featureSupport;

    const overall = (fidelity + compatibility + performance + completeness) / 4;

    return {
      overall: Math.round(overall),
      fidelity: Math.round(fidelity),
      compatibility: Math.round(compatibility),
      performance: Math.round(performance),
      completeness: Math.round(completeness),
      breakdown: {
        nodeTranslation: Math.round(nodeSupport),
        parameterMapping: Math.round(featureSupport),
        featureSupport: Math.round(featureSupport),
        semanticPreservation: Math.round(fidelity),
        syntaxValidity: Math.round(errorImpact)
      }
    };
  }

  protected createValidationResult(
    id: string,
    type: 'error' | 'warning' | 'info',
    severity: 'critical' | 'high' | 'medium' | 'low',
    message: string,
    options: {
      description?: string;
      nodeId?: string;
      edgeId?: string;
      autoFixable?: boolean;
      suggestions?: Array<{ type: string; description: string }>;
    } = {}
  ): ValidationResult {
    return {
      id,
      type,
      severity,
      message,
      description: options.description,
      nodeId: options.nodeId,
      edgeId: options.edgeId,
      autoFixable: options.autoFixable || false,
      suggestions: options.suggestions || []
    };
  }
}

import {
  Capabilities,
  PromptGraph,
  PromptNode,
  ValidationResult,
  TargetPrompt,
  TransformOptions,
  ParameterSpec,
  Feature,
  PluginContext,
  TransformationLog
} from '../types/index.js';
import { BaseAdaptor } from './BaseAdaptor.js';

/**
 * Midjourney adaptor for text-to-image prompt translation
 * Supports Midjourney v6 syntax and parameters
 */
export class MidjourneyAdaptor extends BaseAdaptor {
  private readonly supportedAspectRatios = [
    '1:1', '2:3', '3:2', '4:5', '5:4', '16:9', '9:16'
  ];

  private readonly supportedVersions = [
    'v6', 'v5.2', 'v5.1', 'v5', 'v4'
  ];

  constructor(context: PluginContext) {
    super(
      'midjourney',
      '1.0.0',
      'midjourney',
      'Midjourney Image Generator',
      'Adaptor for Midjourney text-to-image generation',
      context
    );
  }

  async capabilities(): Promise<Capabilities> {
    return {
      supportedNodeTypes: [
        'text',
        'image', // For image references/descriptions
        'style',
        'conditional',
        'weighted',
        'concat',
        'output'
      ],
      parameters: [
        {
          name: 'aspect_ratio',
          type: 'enum',
          required: false,
          default: '1:1',
          options: this.supportedAspectRatios,
          description: 'Image aspect ratio (e.g., 16:9, 4:3)'
        },
        {
          name: 'stylize',
          type: 'number',
          required: false,
          default: 100,
          min: 0,
          max: 1000,
          description: 'Stylization level (0-1000, default 100)'
        },
        {
          name: 'quality',
          type: 'number',
          required: false,
          default: 1,
          min: 0.25,
          max: 2,
          description: 'Image quality (0.25, 0.5, 1, 2)'
        },
        {
          name: 'chaos',
          type: 'number',
          required: false,
          default: 0,
          min: 0,
          max: 100,
          description: 'Variation amount (0-100)'
        },
        {
          name: 'version',
          type: 'enum',
          required: false,
          default: 'v6',
          options: this.supportedVersions,
          description: 'Midjourney version to use'
        },
        {
          name: 'weird',
          type: 'number',
          required: false,
          min: 0,
          max: 3000,
          description: 'Weirdness level (0-3000, v6 only)'
        },
        {
          name: 'tile',
          type: 'boolean',
          required: false,
          default: false,
          description: 'Generate tileable images'
        }
      ],
      limitations: [
        {
          type: 'prompt_length',
          description: 'Maximum prompt length ~6000 characters',
          severity: 'warning',
          impact: 'Long prompts may be truncated'
        },
        {
          type: 'feature',
          description: 'No direct text generation support',
          severity: 'error',
          impact: 'Text-only nodes will be converted to image descriptions'
        },
        {
          type: 'parameter',
          description: 'Some parameters are version-specific',
          severity: 'info',
          impact: 'Parameters may be ignored on older versions'
        }
      ],
      features: [
        {
          name: 'aspect_ratios',
          supported: true,
          description: 'Supports custom aspect ratios'
        },
        {
          name: 'stylization',
          supported: true,
          description: 'Adjustable stylization levels'
        },
        {
          name: 'variations',
          supported: true,
          description: 'Generate variations with chaos parameter'
        },
        {
          name: 'image_references',
          supported: true,
          description: 'Use image URLs as references'
        },
        {
          name: 'style_references',
          supported: true,
          description: 'Use style reference images'
        },
        {
          name: 'blend_mode',
          supported: false,
          description: 'Blend mode not supported in this adaptor version',
          alternatives: ['Use image references for similar effects']
        }
      ],
      maxNodes: 20,
      maxPromptLength: 6000,
      supportedFormats: ['midjourney_prompt']
    };
  }

  protected async doValidate(graph: PromptGraph): Promise<ValidationResult[]> {
    const results: ValidationResult[] = [];
    const capabilities = await this.capabilities();

    // Check for pure text nodes (should have image context)
    const textOnlyNodes = graph.nodes.filter(node => 
      node.type === 'text' && 
      !this.hasImageContext(node, graph)
    );

    if (textOnlyNodes.length === graph.nodes.length && textOnlyNodes.length > 0) {
      results.push(this.createValidationResult(
        'text-only-graph',
        'warning',
        'medium',
        'Graph contains only text nodes',
        {
          description: 'Midjourney works best with visual descriptions. Consider adding style or image context.',
          autoFixable: true,
          suggestions: [{
            type: 'workaround',
            description: 'Add visual descriptors or style keywords to improve image generation'
          }]
        }
      ));
    }

    // Check prompt length
    const estimatedPromptLength = this.estimatePromptLength(graph);
    if (estimatedPromptLength > capabilities.maxPromptLength!) {
      results.push(this.createValidationResult(
        'prompt-too-long',
        'warning',
        'high',
        'Prompt may be too long',
        {
          description: `Estimated length ${estimatedPromptLength} exceeds recommended ${capabilities.maxPromptLength}`,
          autoFixable: false,
          suggestions: [{
            type: 'fix',
            description: 'Simplify prompt or split into multiple generations'
          }]
        }
      ));
    }

    // Validate parameters
    graph.nodes.forEach(node => {
      if (node.data.parameters) {
        Object.entries(node.data.parameters).forEach(([key, value]) => {
          const paramSpec = capabilities.parameters.find(p => p.name === key);
          if (paramSpec) {
            const validation = this.validateParameter(key, value, paramSpec);
            if (validation) {
              results.push({
                ...validation,
                nodeId: node.id
              });
            }
          }
        });
      }
    });

    // Check for conflicting parameters
    const versionParams = this.extractVersionSpecificParams(graph);
    if (versionParams.conflicts.length > 0) {
      versionParams.conflicts.forEach(conflict => {
        results.push(this.createValidationResult(
          `version-conflict-${conflict.param}`,
          'warning',
          'medium',
          'Version-specific parameter conflict',
          {
            description: `Parameter "${conflict.param}" is not supported in version ${conflict.version}`,
            autoFixable: true,
            suggestions: [{
              type: 'fix',
              description: `Remove parameter or upgrade to compatible version`
            }]
          }
        ));
      });
    }

    return results;
  }

  protected async doTransform(graph: PromptGraph, options?: TransformOptions): Promise<TargetPrompt> {
    const transformations: TransformationLog[] = [];
    const capabilities = await this.capabilities();

    // Build the Midjourney prompt
    let promptText = '';
    const parameters: Record<string, any> = {};

    // Process the graph to build prompt text
    const processedContent = await this.processGraph(graph, transformations);
    promptText = processedContent.mainPrompt;

    // Extract and normalize parameters
    const extractedParams = this.extractParameters(graph);
    Object.entries(extractedParams).forEach(([key, value]) => {
      const paramSpec = capabilities.parameters.find(p => p.name === key);
      if (paramSpec) {
        parameters[key] = this.normalizeParameter(value, paramSpec);
      }
    });

    // Apply default parameters
    capabilities.parameters.forEach(param => {
      if (param.default !== undefined && !(param.name in parameters)) {
        parameters[param.name] = param.default;
      }
    });

    // Build parameter string for Midjourney
    const paramString = this.buildParameterString(parameters, transformations);

    // Combine prompt text with parameters
    const finalPrompt = `${promptText}${paramString}`.trim();

    // Calculate quality score
    const validationResults = await this.doValidate(graph);
    const quality = this.calculateQualityScore(graph, capabilities, validationResults);

    const targetPrompt: TargetPrompt = {
      platform: this.platform,
      content: finalPrompt,
      parameters,
      format: 'midjourney_prompt',
      metadata: {
        originalGraphId: graph.id,
        translationId: this.generateTranslationId(),
        timestamp: new Date(),
        adaptorVersion: this.version,
        quality,
        warnings: validationResults.filter(r => r.type === 'warning'),
        transformations
      }
    };

    return targetPrompt;
  }

  /**
   * Process the graph to extract content and build prompt
   */
  private async processGraph(graph: PromptGraph, transformations: TransformationLog[]): Promise<{
    mainPrompt: string;
  }> {
    let mainPrompt = '';
    const processedElements: string[] = [];

    // Find output nodes first
    const outputNodes = graph.nodes.filter(node => node.type === 'output');

    if (outputNodes.length === 0) {
      // No output nodes - process all content nodes
      const contentNodes = graph.nodes.filter(node => 
        ['text', 'style', 'image'].includes(node.type) && 
        (node.data.content || node.data.description)
      );

      for (const node of contentNodes) {
        const content = await this.processNode(node, graph, transformations);
        if (content) {
          processedElements.push(content);
        }
      }

      transformations.push({
        step: 'process_all_content_nodes',
        action: 'Processed all content nodes as no output nodes found',
        details: { nodeCount: contentNodes.length }
      });
    } else {
      // Process output nodes
      for (const outputNode of outputNodes) {
        const content = await this.processNode(outputNode, graph, transformations);
        if (content) {
          processedElements.push(content);
        }
      }
    }

    // Join elements with appropriate separators
    mainPrompt = processedElements.join(', ').trim();

    // Enhance with Midjourney-specific optimizations
    mainPrompt = this.optimizeForMidjourney(mainPrompt, transformations);

    return { mainPrompt };
  }

  /**
   * Process a single node and its dependencies
   */
  private async processNode(
    node: PromptNode,
    graph: PromptGraph,
    transformations: TransformationLog[],
    visited: Set<string> = new Set()
  ): Promise<string> {
    if (visited.has(node.id)) {
      return '';
    }
    visited.add(node.id);

    let content = '';

    // Get input edges for this node
    const inputEdges = graph.edges.filter(edge => edge.target === node.id);

    if (inputEdges.length > 0) {
      // Process input nodes first
      const inputContents: string[] = [];
      for (const edge of inputEdges) {
        const sourceNode = graph.nodes.find(n => n.id === edge.source);
        if (sourceNode) {
          const sourceContent = await this.processNode(sourceNode, graph, transformations, visited);
          if (sourceContent) {
            inputContents.push(sourceContent);
          }
        }
      }
      content = inputContents.join(' ');
    }

    // Process current node content
    switch (node.type) {
      case 'text':
        const textContent = node.data.content || '';
        content = content ? `${content} ${textContent}` : textContent;
        break;

      case 'style':
        const styleContent = node.data.style || node.data.content || '';
        if (styleContent) {
          // Add style modifiers
          content = content ? `${content}, ${styleContent}` : styleContent;
          transformations.push({
            step: 'process_style',
            sourceNodeId: node.id,
            action: 'Added style modifiers',
            details: { style: styleContent }
          });
        }
        break;

      case 'image':
        const imageRef = node.data.url || node.data.content;
        const imageDesc = node.data.description || node.data.alt || '';

        if (imageRef && imageRef.startsWith('http')) {
          // Image URL reference
          content = content ? `${content} ${imageRef}` : imageRef;
          transformations.push({
            step: 'process_image_reference',
            sourceNodeId: node.id,
            action: 'Added image URL reference',
            details: { url: imageRef }
          });
        } else if (imageDesc) {
          // Image description
          content = content ? `${content}, ${imageDesc}` : imageDesc;
          transformations.push({
            step: 'process_image_description',
            sourceNodeId: node.id,
            action: 'Added image description',
            details: { description: imageDesc }
          });
        }
        break;

      case 'concat':
        // Content already processed from inputs
        transformations.push({
          step: 'process_concat',
          sourceNodeId: node.id,
          action: 'Concatenated input nodes'
        });
        break;

      case 'weighted':
        // Select based on weights (simplified - could be enhanced)
        if (node.data.options && node.data.options.length > 0) {
          const selectedOption = this.selectWeightedOption(node.data.options);
          content = content ? `${content} ${selectedOption.text}` : selectedOption.text;
          transformations.push({
            step: 'process_weighted',
            sourceNodeId: node.id,
            action: 'Selected weighted option',
            details: { selectedIndex: selectedOption.index, weight: selectedOption.weight }
          });
        }
        break;

      case 'conditional':
        // For simplicity, take the 'true' branch (could be enhanced with condition evaluation)
        if (node.data.trueBranch) {
          content = content ? `${content} ${node.data.trueBranch}` : node.data.trueBranch;
          transformations.push({
            step: 'process_conditional',
            sourceNodeId: node.id,
            action: 'Selected true branch',
            details: { condition: node.data.condition }
          });
        }
        break;

      case 'output':
        // Content already processed from inputs
        transformations.push({
          step: 'process_output',
          sourceNodeId: node.id,
          action: 'Processed output node'
        });
        break;

      default:
        // For unsupported node types, try to extract any text content
        if (node.data.content) {
          content = content ? `${content} ${node.data.content}` : node.data.content;
          transformations.push({
            step: 'process_fallback',
            sourceNodeId: node.id,
            action: `Processed unsupported node type: ${node.type}`,
            details: { nodeType: node.type }
          });
        }
    }

    return content.trim();
  }

  /**
   * Build parameter string for Midjourney format
   */
  private buildParameterString(
    parameters: Record<string, any>,
    transformations: TransformationLog[]
  ): string {
    const paramParts: string[] = [];

    // Aspect ratio
    if (parameters.aspect_ratio && parameters.aspect_ratio !== '1:1') {
      paramParts.push(`--ar ${parameters.aspect_ratio}`);
    }

    // Stylize
    if (parameters.stylize && parameters.stylize !== 100) {
      paramParts.push(`--s ${parameters.stylize}`);
    }

    // Quality
    if (parameters.quality && parameters.quality !== 1) {
      paramParts.push(`--q ${parameters.quality}`);
    }

    // Chaos
    if (parameters.chaos && parameters.chaos > 0) {
      paramParts.push(`--c ${parameters.chaos}`);
    }

    // Version
    if (parameters.version && parameters.version !== 'v6') {
      paramParts.push(`--${parameters.version}`);
    }

    // Weird (v6 only)
    if (parameters.weird && parameters.weird > 0) {
      if (parameters.version === 'v6' || !parameters.version) {
        paramParts.push(`--weird ${parameters.weird}`);
      } else {
        transformations.push({
          step: 'skip_incompatible_param',
          action: 'Skipped --weird parameter (not supported in selected version)',
          details: { version: parameters.version }
        });
      }
    }

    // Tile
    if (parameters.tile) {
      paramParts.push('--tile');
    }

    return paramParts.length > 0 ? ` ${paramParts.join(' ')}` : '';
  }

  /**
   * Optimize prompt text for Midjourney
   */
  private optimizeForMidjourney(prompt: string, transformations: TransformationLog[]): string {
    let optimized = prompt;

    // Add common quality modifiers if not present
    const qualityKeywords = [
      'highly detailed', 'professional', 'masterpiece', '8k', '4k',
      'photorealistic', 'cinematic', 'studio lighting'
    ];

    const hasQualityModifiers = qualityKeywords.some(keyword => 
      optimized.toLowerCase().includes(keyword.toLowerCase())
    );

    if (!hasQualityModifiers && optimized.length < 4000) {
      optimized += ', highly detailed, professional quality';
      transformations.push({
        step: 'add_quality_modifiers',
        action: 'Added default quality modifiers',
        details: { added: 'highly detailed, professional quality' }
      });
    }

    // Clean up common issues
    optimized = optimized
      .replace(/\s+/g, ' ') // Multiple spaces
      .replace(/,\s*,/g, ',') // Double commas
      .replace(/^\s*,\s*/, '') // Leading comma
      .replace(/\s*,\s*$/, '') // Trailing comma
      .trim();

    return optimized;
  }

  /**
   * Check if node has image context
   */
  private hasImageContext(node: PromptNode, graph: PromptGraph): boolean {
    // Check if the text contains visual descriptors
    const visualKeywords = [
      'image', 'photo', 'picture', 'art', 'painting', 'drawing', 'sketch',
      'render', 'illustration', 'design', 'style', 'color', 'lighting',
      'composition', 'visual', 'aesthetic', 'cinematic', 'landscape',
      'portrait', 'character', 'scene', 'environment', 'background'
    ];

    const content = (node.data.content || '').toLowerCase();
    const hasVisualWords = visualKeywords.some(keyword => content.includes(keyword));

    if (hasVisualWords) return true;

    // Check if connected to style or image nodes
    const connectedEdges = graph.edges.filter(edge => 
      edge.source === node.id || edge.target === node.id
    );

    for (const edge of connectedEdges) {
      const otherNodeId = edge.source === node.id ? edge.target : edge.source;
      const otherNode = graph.nodes.find(n => n.id === otherNodeId);
      if (otherNode && ['style', 'image'].includes(otherNode.type)) {
        return true;
      }
    }

    return false;
  }

  /**
   * Estimate final prompt length
   */
  private estimatePromptLength(graph: PromptGraph): number {
    let totalLength = 0;

    graph.nodes.forEach(node => {
      if (node.data.content) {
        totalLength += node.data.content.length;
      }
      if (node.data.description) {
        totalLength += node.data.description.length;
      }
      if (node.data.style) {
        totalLength += node.data.style.length;
      }
    });

    // Add estimated parameter length
    totalLength += 100; // Rough estimate for parameters

    return totalLength;
  }

  /**
   * Extract version-specific parameter conflicts
   */
  private extractVersionSpecificParams(graph: PromptGraph): {
    version: string;
    conflicts: Array<{ param: string; version: string }>;
  } {
    const extractedParams = this.extractParameters(graph);
    const version = extractedParams.version || 'v6';
    const conflicts: Array<{ param: string; version: string }> = [];

    // Check for version-specific conflicts
    if (version !== 'v6' && extractedParams.weird) {
      conflicts.push({ param: 'weird', version });
    }

    return { version, conflicts };
  }

  /**
   * Select weighted option (simplified implementation)
   */
  private selectWeightedOption(options: any[]): { text: string; index: number; weight: number } {
    if (!options || options.length === 0) {
      return { text: '', index: -1, weight: 0 };
    }

    // For now, just select the first option
    // Could be enhanced with actual weighted random selection
    const selected = options[0];
    return {
      text: selected.text || selected.content || '',
      index: 0,
      weight: selected.weight || 1
    };
  }

  /**
   * Validate a parameter value against its specification
   */
  private validateParameter(
    name: string,
    value: any,
    spec: ParameterSpec
  ): ValidationResult | null {
    // Implement parameter validation logic
    if (spec.type === 'number') {
      if (typeof value !== 'number' || isNaN(value)) {
        return this.createValidationResult(
          `invalid-param-${name}`,
          'error',
          'medium',
          `Invalid number value for parameter "${name}"`,
          {
            description: `Expected number, got ${typeof value}`,
            autoFixable: true
          }
        );
      }

      if (spec.min !== undefined && value < spec.min) {
        return this.createValidationResult(
          `param-too-low-${name}`,
          'warning',
          'low',
          `Parameter "${name}" value too low`,
          {
            description: `Value ${value} is below minimum ${spec.min}`,
            autoFixable: true
          }
        );
      }

      if (spec.max !== undefined && value > spec.max) {
        return this.createValidationResult(
          `param-too-high-${name}`,
          'warning',
          'low',
          `Parameter "${name}" value too high`,
          {
            description: `Value ${value} is above maximum ${spec.max}`,
            autoFixable: true
          }
        );
      }
    }

    if (spec.type === 'enum' && spec.options) {
      if (!spec.options.includes(value)) {
        return this.createValidationResult(
          `invalid-enum-${name}`,
          'error',
          'medium',
          `Invalid enum value for parameter "${name}"`,
          {
            description: `Value "${value}" not in allowed options: ${spec.options.join(', ')}`,
            autoFixable: true
          }
        );
      }
    }

    return null;
  }

  /**
   * Normalize parameter value according to its specification
   */
  private normalizeParameter(value: any, spec: ParameterSpec): any {
    if (spec.type === 'number') {
      const num = Number(value);
      if (isNaN(num)) return spec.default;

      if (spec.min !== undefined) return Math.max(spec.min, num);
      if (spec.max !== undefined) return Math.min(spec.max, num);

      return num;
    }

    if (spec.type === 'enum' && spec.options) {
      return spec.options.includes(value) ? value : spec.default;
    }

    return value;
  }

  /**
   * Extract parameters from graph nodes
   */
  private extractParameters(graph: PromptGraph): Record<string, any> {
    const parameters: Record<string, any> = {};

    graph.nodes.forEach(node => {
      if (node.data.parameters) {
        Object.assign(parameters, node.data.parameters);
      }
    });

    return parameters;
  }

  /**
   * Generate a unique translation ID
   */
  private generateTranslationId(): string {
    return `${this.id}-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }
}

import {
  Capabilities,
  PromptGraph,
  PromptNode,
  ValidationResult,
  TargetPrompt,
  TransformOptions,
  ParameterSpec,
  Feature,
  PluginContext,
  TransformationLog
} from '../types/index.js';
import { BaseAdaptor } from './BaseAdaptor.js';

/**
 * OpenAI GPT adaptor for text-to-text prompt translation
 * Supports GPT-3.5 and GPT-4 models with chat completion format
 */
export class OpenAIGPTAdaptor extends BaseAdaptor {
  constructor(context: PluginContext) {
    super(
      'openai-gpt',
      '1.0.0',
      'openai-gpt',
      'OpenAI GPT Models',
      'Adaptor for OpenAI GPT-3.5 and GPT-4 text generation models',
      context
    );
  }

  async capabilities(): Promise<Capabilities> {
    return {
      supportedNodeTypes: [
        'text',
        'conditional',
        'weighted',
        'concat',
        'output'
      ],
      parameters: [
        {
          name: 'temperature',
          type: 'number',
          required: false,
          default: 0.7,
          min: 0.0,
          max: 2.0,
          description: 'Controls randomness in generation (0.0 = deterministic, 2.0 = very random)'
        },
        {
          name: 'max_tokens',
          type: 'number',
          required: false,
          default: 1000,
          min: 1,
          max: 4096,
          description: 'Maximum number of tokens to generate'
        },
        {
          name: 'top_p',
          type: 'number',
          required: false,
          default: 1.0,
          min: 0.0,
          max: 1.0,
          description: 'Nucleus sampling parameter'
        },
        {
          name: 'frequency_penalty',
          type: 'number',
          required: false,
          default: 0.0,
          min: -2.0,
          max: 2.0,
          description: 'Reduces repetition of frequent tokens'
        },
        {
          name: 'presence_penalty',
          type: 'number',
