import {
  PromptGraph,
  Platform,
  TranslationRequest,
  TranslationResponse,
  TransformOptions,
  ModelAdaptor,
  Logger,
  CacheInterface,
  MetricsInterface,
  TranslationError,
  ValidationError,
  PromptTargetingError
} from '../types/index.js';

/**
 * Core mapping engine that orchestrates prompt translations
 */
export class MappingEngine {
  private adaptors = new Map<Platform, ModelAdaptor>();
  private logger: Logger;
  private cache: CacheInterface;
  private metrics: MetricsInterface;

  constructor(
    logger: Logger,
    cache: CacheInterface,
    metrics: MetricsInterface
  ) {
    this.logger = logger;
    this.cache = cache;
    this.metrics = metrics;
  }

  /**
   * Register an adaptor for a specific platform
   */
  registerAdaptor(platform: Platform, adaptor: ModelAdaptor): void {
    this.adaptors.set(platform, adaptor);
    this.logger.info('Adaptor registered', {
      platform,
      adaptorId: adaptor.id,
      version: adaptor.version
    });

    this.metrics.counter('mapping_engine.adaptor.registered', 1, {
      platform,
      adaptor_id: adaptor.id
    });
  }

  /**
   * Unregister an adaptor for a platform
   */
  unregisterAdaptor(platform: Platform): void {
    const adaptor = this.adaptors.get(platform);
    if (adaptor) {
      this.adaptors.delete(platform);
      this.logger.info('Adaptor unregistered', {
        platform,
        adaptorId: adaptor.id
      });

      this.metrics.counter('mapping_engine.adaptor.unregistered', 1, {
        platform,
        adaptor_id: adaptor.id
      });
    }
  }

  /**
   * Get all registered platforms
   */
  getRegisteredPlatforms(): Platform[] {
    return Array.from(this.adaptors.keys());
  }

  /**
   * Get adaptor for a specific platform
   */
  getAdaptor(platform: Platform): ModelAdaptor | undefined {
    return this.adaptors.get(platform);
  }

  /**
   * Check if a platform is supported
   */
  isPlatformSupported(platform: Platform): boolean {
    return this.adaptors.has(platform);
  }

  /**
   * Translate a prompt graph to target platform
   */
  async translate(request: TranslationRequest): Promise<TranslationResponse> {
    const startTime = Date.now();
    const requestId = request.requestId || this.generateRequestId();

    this.logger.info('Translation started', {
      requestId,
      graphId: request.graph.id,
      targetPlatform: request.targetPlatform
    });

    this.metrics.counter('mapping_engine.translation.started', 1, {
      platform: request.targetPlatform
    });

    try {
      // Validate request
      this.validateRequest(request);

      // Get adaptor
      const adaptor = this.getAdaptor(request.targetPlatform);
      if (!adaptor) {
        throw new TranslationError(
          `No adaptor registered for platform: ${request.targetPlatform}`,
          'ADAPTOR_NOT_FOUND',
          { platform: request.targetPlatform },
          false
        );
      }

      // Check cache first
      const cacheKey = this.generateCacheKey(request);
      const cached = await this.checkCache(cacheKey);
      if (cached) {
        this.metrics.counter('mapping_engine.translation.cache_hit', 1, {
          platform: request.targetPlatform
        });

        return {
          requestId,
          success: true,
          targetPrompt: cached.targetPrompt,
          quality: cached.quality,
          validationResults: cached.validationResults,
          timing: {
            total: Date.now() - startTime,
            validation: 0,
            transformation: 0,
            postProcessing: 0
          }
        };
      }

      // Perform translation
      const validationStart = Date.now();
      const validationResults = await adaptor.validate(request.graph);
      const validationTime = Date.now() - validationStart;

      // Check for critical errors
      const criticalErrors = validationResults.filter(
        r => r.type === 'error' && r.severity === 'critical'
      );

      if (criticalErrors.length > 0) {
        throw new ValidationError(
          'Critical validation errors prevent translation',
          criticalErrors
        );
      }

      // Transform
      const transformStart = Date.now();
      const targetPrompt = await adaptor.transform(request.graph, request.options);
      const transformTime = Date.now() - transformStart;

      // Post-processing
      const postProcessStart = Date.now();
      const quality = await adaptor.estimateQuality(request.graph);
      const postProcessTime = Date.now() - postProcessStart;

      // Cache result
      await this.cacheResult(cacheKey, {
        targetPrompt,
        quality,
        validationResults
      });

      const totalTime = Date.now() - startTime;

      this.logger.info('Translation completed', {
        requestId,
        graphId: request.graph.id,
        targetPlatform: request.targetPlatform,
        quality: quality.overall,
        duration: totalTime
      });

      this.metrics.counter('mapping_engine.translation.success', 1, {
        platform: request.targetPlatform
      });

      this.metrics.histogram('mapping_engine.translation.duration', totalTime, {
        platform: request.targetPlatform
      });

      return {
        requestId,
        success: true,
        targetPrompt,
        quality,
        validationResults,
        timing: {
          total: totalTime,
          validation: validationTime,
          transformation: transformTime,
          postProcessing: postProcessTime
        }
      };

    } catch (error) {
      const totalTime = Date.now() - startTime;
      const errorMessage = error instanceof Error ? error.message : String(error);
      const errorType = error instanceof Error ? error.constructor.name : 'UnknownError';

      this.logger.error('Translation failed', {
        requestId,
        graphId: request.graph.id,
        targetPlatform: request.targetPlatform,
        error: errorMessage,
        duration: totalTime
      });

      this.metrics.counter('mapping_engine.translation.error', 1, {
        platform: request.targetPlatform,
        error_type: errorType
      });

      if (error instanceof PromptTargetingError) {
        return {
          requestId,
          success: false,
          validationResults: [],
          error: {
            code: error.code,
            message: error.message,
            details: error.details,
            recoverable: error.recoverable,
            name: error.name
          },
          timing: {
            total: totalTime,
            validation: 0,
            transformation: 0,
            postProcessing: 0
          }
        };
      }

      // Unexpected error
      return {
        requestId,
        success: false,
        validationResults: [],
        error: {
          code: 'UNEXPECTED_ERROR',
          message: 'An unexpected error occurred during translation',
          details: { originalError: errorMessage },
          recoverable: true,
          name: 'UnexpectedError'
        },
        timing: {
          total: totalTime,
          validation: 0,
          transformation: 0,
          postProcessing: 0
        }
      };
    }
  }

  /**
   * Validate translation request
   */
  private validateRequest(request: TranslationRequest): void {
    if (!request.graph) {
      throw new TranslationError(
        'Graph is required',
        'INVALID_REQUEST',
        {},
        false
      );
    }

    if (!request.targetPlatform) {
      throw new TranslationError(
        'Target platform is required',
        'INVALID_REQUEST',
        {},
        false
      );
    }

    if (!request.graph.nodes || request.graph.nodes.length === 0) {
      throw new TranslationError(
        'Graph must contain at least one node',
        'INVALID_GRAPH',
        {},
        false
      );
    }

    // Validate graph structure
    const nodeIds = new Set(request.graph.nodes.map(n => n.id));

    for (const edge of request.graph.edges || []) {
      if (!nodeIds.has(edge.source)) {
        throw new TranslationError(
          `Edge references invalid source node: ${edge.source}`,
          'INVALID_GRAPH',
          { edgeId: edge.id, sourceId: edge.source },
          false
        );
      }

      if (!nodeIds.has(edge.target)) {
        throw new TranslationError(
          `Edge references invalid target node: ${edge.target}`,
          'INVALID_GRAPH',
          { edgeId: edge.id, targetId: edge.target },
          false
        );
      }
    }
  }

  /**
   * Generate cache key for translation request
   */
  private generateCacheKey(request: TranslationRequest): string {
    const adaptor = this.getAdaptor(request.targetPlatform);
    const adaptorVersion = adaptor?.version || 'unknown';

    const graphHash = this.hashObject({
      nodes: request.graph.nodes,
      edges: request.graph.edges,
      version: request.graph.version
    });

    const optionsHash = request.options ? this.hashObject(request.options) : 'none';

    return `translation:${request.targetPlatform}:${adaptorVersion}:${graphHash}:${optionsHash}`;
  }

  /**
   * Check cache for existing translation
   */
  private async checkCache(cacheKey: string): Promise<any | null> {
    try {
      const cached = await this.cache.get(cacheKey);
      if (cached && this.isCacheValid(cached)) {
        this.logger.debug('Cache hit', { cacheKey });
        return cached;
      }
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : String(error);
      this.logger.warn('Cache lookup failed', {
        cacheKey,
        error: errorMessage
      });
    }

    return null;
  }

  /**
   * Cache translation result
   */
  private async cacheResult(cacheKey: string, result: any): Promise<void> {
    try {
      const cacheEntry = {
        ...result,
        timestamp: new Date(),
        version: '1.0'
      };

      await this.cache.set(cacheKey, cacheEntry, 3600); // 1 hour TTL

      this.logger.debug('Result cached', { cacheKey });
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : String(error);
      this.logger.warn('Cache storage failed', {
        cacheKey,
        error: errorMessage
      });
    }
  }

  /**
   * Check if cached result is still valid
   */
  private isCacheValid(cached: any): boolean {
    if (!cached.timestamp) return false;

    const age = Date.now() - new Date(cached.timestamp).getTime();
    const maxAge = 3600 * 1000; // 1 hour in milliseconds

    return age < maxAge;
  }

  /**
   * Generate unique request ID
   */
  private generateRequestId(): string {
    return `req-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }

  /**
   * Simple object hashing
   */
  private hashObject(obj: any): string {
    const str = JSON.stringify(obj, Object.keys(obj).sort());
    let hash = 0;

    for (let i = 0; i < str.length; i++) {
      const char = str.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash;
    }

    return Math.abs(hash).toString(36);
  }

  /**
   * Get engine statistics
   */
  getStats(): {
    registeredAdaptors: number;
    supportedPlatforms: Platform[];
    adaptorInfo: Array<{
      platform: Platform;
      id: string;
      version: string;
      name: string;
    }>;
  } {
    const adaptorInfo = Array.from(this.adaptors.entries()).map(([platform, adaptor]) => ({
      platform,
      id: adaptor.id,
      version: adaptor.version,
      name: adaptor.name
    }));

    return {
      registeredAdaptors: this.adaptors.size,
      supportedPlatforms: Array.from(this.adaptors.keys()),
      adaptorInfo
    };
  }
}

import {
  MappingEngine,
  ValidationEngine,
  OpenAIGPTAdaptor,
  MidjourneyAdaptor,
  PromptGraph,
  Platform,
  TranslationRequest,
  ConsoleLogger,
  MemoryCache,
  MemoryMetrics
} from '../index.js';

/**
 * Comprehensive example demonstrating the prompt targeting system
 */
export class PromptTargetingExample {
  private engine: MappingEngine;
  private validator: ValidationEngine;
  private logger: ConsoleLogger;
  private cache: MemoryCache;
  private metrics: MemoryMetrics;

  constructor() {
    // Initialize dependencies
    this.logger = new ConsoleLogger('Example');
    this.cache = new MemoryCache();
    this.metrics = new MemoryMetrics();

    // Create engines
    this.engine = new MappingEngine(this.logger, this.cache, this.metrics);
    this.validator = new ValidationEngine(this.logger, this.metrics);

    // Register adaptors
    this.setupAdaptors();
  }

  private setupAdaptors(): void {
    const context = {
      logger: this.logger,
      cache: this.cache,
      metrics: this.metrics,
      config: {}
    };

    // Register OpenAI GPT adaptor
    const gptAdaptor = new OpenAIGPTAdaptor(context);
    this.engine.registerAdaptor('openai-gpt', gptAdaptor);

    // Register Midjourney adaptor
    const midjourneyAdaptor = new MidjourneyAdaptor(context);
    this.engine.registerAdaptor('midjourney', midjourneyAdaptor);

    this.logger.info('Adaptors registered', {
      platforms: this.engine.getRegisteredPlatforms()
    });
  }

  /**
   * Example 1: Simple text-to-text translation
   */
  async simpleTextTranslation(): Promise<void> {
    console.log('\n=== Simple Text Translation ===');

    const graph: PromptGraph = {
      id: 'simple-text-graph',
      version: '1.0',
      nodes: [
        {
          id: 'prompt-node',
          type: 'text',
          data: {
            content: 'Write a short story about a robot discovering emotions',
            parameters: {
              temperature: 0.8,
              max_tokens: 500
            }
          },
          position: { x: 0, y: 0 }
        }
      ],
      edges: [],
      metadata: {
        name: 'Simple Story Prompt',
        created: new Date(),
        modified: new Date(),
        version: '1.0'
      }
    };

    const request: TranslationRequest = {
      graph,
      targetPlatform: 'openai-gpt' as Platform
    };

    const response = await this.engine.translate(request);

    if (response.success) {
      console.log('✅ Translation successful');
      console.log('Target Platform:', response.targetPrompt?.platform);
      console.log('Format:', response.targetPrompt?.format);
      console.log('Quality Score:', response.quality?.overall);
      console.log('Content:', JSON.stringify(response.targetPrompt?.content, null, 2));
    } else {
      console.log('❌ Translation failed:', response.error?.message);
    }
  }

  /**
   * Example 2: Complex graph with multiple nodes
   */
  async complexGraphTranslation(): Promise<void> {
    console.log('\n=== Complex Graph Translation ===');

    const graph: PromptGraph = {
      id: 'complex-graph',
      version: '1.0',
      nodes: [
        {
          id: 'subject-node',
          type: 'text',
          data: { content: 'A majestic dragon' },
          position: { x: 0, y: 0 }
        },
        {
          id: 'setting-node',
          type: 'text',
          data: { content: 'perched on a mountain peak at sunset' },
          position: { x: 200, y: 0 }
        },
        {
          id: 'style-node',
          type: 'style',
          data: {
            style: 'fantasy art, highly detailed, cinematic lighting',
            content: 'epic fantasy illustration'
          },
          position: { x: 100, y: 100 }
        },
        {
          id: 'concat-node',
          type: 'concat',
          data: { label: 'Combine elements' },
          position: { x: 100, y: 200 }
        },
        {
          id: 'output-node',
          type: 'output',
          data: {
            label: 'Final output',
            parameters: {
              aspect_ratio: '16:9',
              stylize: 250,
              quality: 2
            }
          },
          position: { x: 100, y: 300 }
        }
      ],
      edges: [
        { id: 'e1', source: 'subject-node', target: 'concat-node' },
        { id: 'e2', source: 'setting-node', target: 'concat-node' },
        { id: 'e3', source: 'style-node', target: 'concat-node' },
        { id: 'e4', source: 'concat-node', target: 'output-node' }
      ],
      metadata: {
        name: 'Fantasy Dragon Scene',
        created: new Date(),
        modified: new Date(),
        version: '1.0'
      }
    };

    // Translate to both platforms
    const platforms: Platform[] = ['openai-gpt', 'midjourney'];

    for (const platform of platforms) {
      console.log(`\n--- Translating to ${platform} ---`);

      const request: TranslationRequest = {
        graph,
        targetPlatform: platform
      };

      const response = await this.engine.translate(request);

      if (response.success) {
        console.log('✅ Translation successful');
        console.log('Quality Score:', response.quality?.overall);
        console.log('Warnings:', response.validationResults.filter(r => r.type === 'warning').length);

        if (platform === 'midjourney') {
          console.log('Midjourney Prompt:', response.targetPrompt?.content);
        } else {
          const content = response.targetPrompt?.content as any;
          console.log('User Message:', content?.messages?.find((m: any) => m.role === 'user')?.content);
        }
      } else {
        console.log('❌ Translation failed:', response.error?.message);
      }
    }
  }

  /**
   * Example 3: Validation and quality assessment
   */
  async validationExample(): Promise<void> {
    console.log('\n=== Validation Example ===');

    // Create a problematic graph
    const problematicGraph: PromptGraph = {
      id: 'problematic-graph',
      version: '1.0',
      nodes: [
        {
          id: 'disconnected-node',
          type: 'text',
          data: { content: 'This node is disconnected' },
          position: { x: 0, y: 0 }
        },
        {
          id: 'main-node',
          type: 'text',
          data: { 
            content: 'Main prompt content',
            parameters: {
              temperature: 5.0, // Invalid value
              invalid_param: 'should not exist'
            }
          },
          position: { x: 200, y: 0 }
        },
        {
          id: 'image-node',
          type: 'image',
          data: { url: 'https://example.com/image.jpg' },
          position: { x: 100, y: 100 }
        }
      ],
      edges: [
        { id: 'e1', source: 'main-node', target: 'image-node' }
      ],
      metadata: {
        name: 'Problematic Graph',
        created: new Date(),
        modified: new Date(),
        version: '1.0'
      }
    };

    // Get all adaptors for validation
    const gptAdaptor = new OpenAIGPTAdaptor({
      logger: this.logger,
      cache: this.cache,
      metrics: this.metrics,
      config: {}
    });

    const midjourneyAdaptor = new MidjourneyAdaptor({
      logger: this.logger,
      cache: this.cache,
      metrics: this.metrics,
      config: {}
    });

    const report = await this.validator.validateGraph(
      problematicGraph,
      [gptAdaptor, midjourneyAdaptor]
    );

    console.log('Validation Report:');
    console.log('Overall Valid:', report.overallValid);
    console.log('Total Issues:', report.totalIssues);
    console.log('Critical Errors:', report.summary.criticalErrors);
    console.log('High Errors:', report.summary.highErrors);
    console.log('Medium Warnings:', report.summary.mediumWarnings);
    console.log('Low Infos:', report.summary.lowInfos);

    console.log('\nPlatform Compatibility:');
    report.platformResults.forEach((result, platform) => {
      console.log(`${platform}: ${result.compatible ? '✅' : '❌'} (Quality: ${result.quality.overall}%)`);
    });

    console.log('\nAuto-fix Suggestions:');
    report.autoFixSuggestions.forEach((suggestion, index) => {
      console.log(`${index + 1}. ${suggestion.description} (Confidence: ${suggestion.confidence}%)`);
    });

    if (report.crossPlatformIssues.length > 0) {
      console.log('\nCross-platform Issues:');
      report.crossPlatformIssues.forEach((issue, index) => {
        console.log(`${index + 1}. ${issue.description}`);
        console.log(`   Supporting: ${issue.supportingPlatforms.join(', ')}`);
        console.log(`   Unsupported: ${issue.unsupportedPlatforms.join(', ')}`);
      });
    }
  }

  /**
   * Example 4: Performance and caching demonstration
   */
  async performanceExample(): Promise<void> {
    console.log('\n=== Performance & Caching Example ===');

    const graph: PromptGraph = {
      id: 'performance-test-graph',
      version: '1.0',
      nodes: [
        {
          id: 'test-node',
          type: 'text',
          data: { content: 'Performance test prompt' },
          position: { x: 0, y: 0 }
        }
      ],
      edges: [],
      metadata: {
        name: 'Performance Test',
        created: new Date(),
        modified: new Date(),
        version: '1.0'
      }
    };

    const request: TranslationRequest = {
      graph,
      targetPlatform: 'openai-gpt' as Platform
    };

    // First translation (cache miss)
    console.log('First translation (cache miss):');
    const start1 = Date.now();
    const response1 = await this.engine.translate(request);
    const duration1 = Date.now() - start1;
    console.log(`Duration: ${duration1}ms`);
    console.log(`Success: ${response1.success}`);

    // Second translation (cache hit)
    console.log('\nSecond translation (cache hit):');
    const start2 = Date.now();
    const response2 = await this.engine.translate(request);
    const duration2 = Date.now() - start2;
    console.log(`Duration: ${duration2}ms`);
    console.log(`Success: ${response2.success}`);
    console.log(`Speedup: ${Math.round(duration1 / duration2)}x faster`);

    // Show metrics
    console.log('\nMetrics:');
    const metrics = this.metrics.getMetrics();
    console.log('Counters:', metrics.counters);
    console.log('Translation Duration Stats:', metrics.histograms['mapping_engine.translation.duration']);
  }

  /**
   * Run all examples
   */
  async runAllExamples(): Promise<void> {
    console.log('🚀 Starting Prompt Targeting System Examples\n');

    try {
      await this.simpleTextTranslation();
      await this.complexGraphTranslation();
      await this.validationExample();
      await this.performanceExample();

      console.log('\n✅ All examples completed successfully!');

      // Show final stats
      console.log('\nEngine Statistics:');
      const stats = this.engine.getStats();
      console.log(`Registered Adaptors: ${stats.registeredAdaptors}`);
      console.log(`Supported Platforms: ${stats.supportedPlatforms.join(', ')}`);

      console.log('\nCache Statistics:');
      const cacheStats = this.cache.getStats();
      console.log(`Cache Size: ${cacheStats.size} entries`);

    } catch (error) {
      console.error('❌ Example failed:', error);
    }
  }
}

// Export factory function for easy usage
export function createPromptTargetingExample(): PromptTargetingExample {
  return new PromptTargetingExample();
}

// CLI runner if executed directly
if (typeof require !== 'undefined' && require.main === module) {
  const example = createPromptTargetingExample();
  example.runAllExamples().catch(console.error);
}

import { Platform } from '../types/index.js';
import { GalleryItem } from '../gallery/ResultGallerySystem.js';
import { GenerationMetadata } from '../metadata/MetadataManager.js';

/**
 * Export format types
 */
export type ExportFormat = 
  | 'json' 
  | 'csv' 
  | 'xlsx' 
  | 'pdf' 
  | 'html' 
  | 'zip' 
  | 'png' 
  | 'jpeg' 
  | 'webp'
  | 'midjourney_prompt'
  | 'dalle_prompt'
  | 'stable_diffusion_prompt';

/**
 * Export options configuration
 */
export interface ExportOptions {
  format: ExportFormat;
  includeImages?: boolean;
  includeMetadata?: boolean;
  includePrompts?: boolean;
  includeParameters?: boolean;
  imageFormat?: 'original' | 'png' | 'jpeg' | 'webp';
  imageQuality?: number; // 0.1 - 1.0
  maxImageSize?: { width: number; height: number };
  compression?: 'none' | 'low' | 'medium' | 'high';
  password?: string;
  customFields?: string[];
  templateId?: string;
  batchSize?: number;
  metadata?: Record<string, any>;
}

/**
 * Export request
 */
export interface ExportRequest {
  id: string;
  name: string;
  description?: string;
  items: string[]; // Gallery item IDs
  options: ExportOptions;
  created: Date;
  requestedBy?: string;
}

/**
 * Export result
 */
export interface ExportResult {
  id: string;
  requestId: string;
  status: 'pending' | 'processing' | 'completed' | 'failed' | 'expired';
  format: ExportFormat;
  url?: string;
  filename?: string;
  size?: number; // bytes
  itemCount: number;
  created: Date;
  completed?: Date;
  expiresAt?: Date;
  downloadCount: number;
  error?: string;
  progress?: number; // 0-100
  metadata?: Record<string, any>;
}

/**
 * Export template for reusable configurations
 */
export interface ExportTemplate {
  id: string;
  name: string;
  description?: string;
  options: ExportOptions;
  isPublic: boolean;
  created: Date;
  modified: Date;
  usageCount: number;
  tags: string[];
}

/**
 * Platform-specific export configuration
 */
export interface PlatformExportConfig {
  platform: Platform;
  promptFormat: string;
  parameterMapping: Record<string, string>;
  fileExtension: string;
  mimeType: string;
  maxPromptLength?: number;
  supportedParameters?: string[];
  templateVariables?: Record<string, string>;
}

/**
 * Export progress callback
 */
export type ExportProgressCallback = (progress: {
  requestId: string;
  status: ExportResult['status'];
  progress: number;
  message?: string;
  itemsProcessed?: number;
  totalItems?: number;
}) => void;

/**
 * Comprehensive export system for gallery items and metadata
 */
export class ExportSystem {
  private requests: Map<string, ExportRequest> = new Map();
  private results: Map<string, ExportResult> = new Map();
  private templates: Map<string, ExportTemplate> = new Map();
  private platformConfigs: Map<Platform, PlatformExportConfig> = new Map();
  private progressCallbacks: Map<string, ExportProgressCallback> = new Map();

  private readonly maxConcurrentExports = 3;
  private readonly maxFileSize = 500 * 1024 * 1024; // 500MB
  private readonly resultTTL = 7 * 24 * 60 * 60 * 1000; // 7 days

  private processingQueue: string[] = [];
  private activeExports: Set<string> = new Set();

  constructor() {
    this.initializePlatformConfigs();
    this.initializeDefaultTemplates();
    this.startBackgroundCleaner();
  }

  /**
   * Create export request
   */
  async createExportRequest(
    name: string,
    itemIds: string[],
    options: ExportOptions,
    description?: string,
    onProgress?: ExportProgressCallback
  ): Promise<string> {
    const requestId = this.generateRequestId();

    const request: ExportRequest = {
      id: requestId,
      name,
      description,
      items: itemIds,
      options,
      created: new Date()
    };

    const result: ExportResult = {
      id: this.generateResultId(),
      requestId,
      status: 'pending',
      format: options.format,
      itemCount: itemIds.length,
      created: new Date(),
      downloadCount: 0,
      progress: 0
    };

    this.requests.set(requestId, request);
    this.results.set(result.id, result);

    if (onProgress) {
      this.progressCallbacks.set(requestId, onProgress);
    }

    // Add to processing queue
    this.processingQueue.push(requestId);
    this.processQueue();

    return result.id;
  }

  /**
   * Get export result
   */
  getExportResult(resultId: string): ExportResult | null {
    const result = this.results.get(resultId);
    if (result && result.url) {
      // Track download
      result.downloadCount++;
    }
    return result || null;
  }

  /**
   * Get export request
   */
  getExportRequest(requestId: string): ExportRequest | null {
    return this.requests.get(requestId) || null;
  }

  /**
   * Cancel export request
   */
  cancelExport(requestId: string): boolean {
    // Remove from queue if pending
    const queueIndex = this.processingQueue.indexOf(requestId);
    if (queueIndex >= 0) {
      this.processingQueue.splice(queueIndex, 1);

      // Update result status
      const result = Array.from(this.results.values()).find(r => r.requestId === requestId);
      if (result) {
        result.status = 'failed';
        result.error = 'Cancelled by user';
      }

      this.progressCallbacks.delete(requestId);
      return true;
    }

    // Cannot cancel active exports
    return false;
  }

  /**
   * Create export template
   */
  createTemplate(
    name: string,
    options: ExportOptions,
    description?: string,
    isPublic = false,
    tags: string[] = []
  ): string {
    const templateId = this.generateTemplateId();

    const template: ExportTemplate = {
      id: templateId,
      name,
      description,
      options,
      isPublic,
      created: new Date(),
      modified: new Date(),
      usageCount: 0,
      tags
    };

    this.templates.set(templateId, template);
    return templateId;
  }

  /**
   * Get export template
   */
  getTemplate(templateId: string): ExportTemplate | null {
    return this.templates.get(templateId) || null;
  }

  /**
   * Get all templates
   */
  getTemplates(includePublic = true): ExportTemplate[] {
    const templates = Array.from(this.templates.values());
    return includePublic ? templates : templates.filter(t => t.isPublic);
  }

  /**
   * Update template
   */
  updateTemplate(templateId: string, updates: Partial<ExportTemplate>): boolean {
    const template = this.templates.get(templateId);
    if (!template) return false;

    Object.assign(template, updates);
    template.modified = new Date();

    return true;
  }

  /**
   * Delete template
   */
  deleteTemplate(templateId: string): boolean {
    return this.templates.delete(templateId);
  }

  /**
   * Export to platform-specific format
   */
  async exportToPlatform(
    itemIds: string[],
    platform: Platform,
    options?: Partial<ExportOptions>
  ): Promise<string> {
    const config = this.platformConfigs.get(platform);
    if (!config) {
      throw new Error(`No export configuration found for platform: ${platform}`);
    }

    const exportOptions: ExportOptions = {
      format: config.promptFormat as ExportFormat,
      includePrompts: true,
      includeParameters: true,
      includeMetadata: false,
      ...options
    };

    return this.createExportRequest(
      `${platform} Export`,
      itemIds,
      exportOptions,
      `Export optimized for ${platform} platform`
    );
  }

  /**
   * Get export statistics
   */
  getExportStats(): {
    totalExports: number;
    successfulExports: number;
    failedExports: number;
    totalDownloads: number;
    popularFormats: Array<{ format: ExportFormat; count: number }>;
    averageFileSize: number;
  } {
    const results = Array.from(this.results.values());

    const totalExports = results.length;
    const successfulExports = results.filter(r => r.status === 'completed').length;
    const failedExports = results.filter(r => r.status === 'failed').length;
    const totalDownloads = results.reduce((sum, r) => sum + r.downloadCount, 0);

    // Popular formats
    const formatCounts: Record<ExportFormat, number> = {} as Record<ExportFormat, number>;
    results.forEach(result => {
      formatCounts[result.format] = (formatCounts[result.format] || 0) + 1;
    });

    const popularFormats = Object.entries(formatCounts)
      .sort(([, a], [, b]) => b - a)
      .slice(0, 10)
      .map(([format, count]) => ({ format: format as ExportFormat, count }));

    // Average file size
    const completedResults = results.filter(r => r.status === 'completed' && r.size);
    const averageFileSize = completedResults.length > 0
      ? completedResults.reduce((sum, r) => sum + (r.size || 0), 0) / completedResults.length
      : 0;

    return {
      totalExports,
      successfulExports,
      failedExports,
      totalDownloads,
      popularFormats,
      averageFileSize
    };
  }

  /**
   * Process export queue
   */
  private async processQueue(): Promise<void> {
    if (this.activeExports.size >= this.maxConcurrentExports || this.processingQueue.length === 0) {
      return;
    }

    const requestId = this.processingQueue.shift();
    if (!requestId) return;

    const request = this.requests.get(requestId);
    const result = Array.from(this.results.values()).find(r => r.requestId === requestId);

    if (!request || !result) return;

    this.activeExports.add(requestId);
    result.status = 'processing';
    result.progress = 0;

    this.notifyProgress(requestId, 'processing', 0, 'Starting export...');

    try {
      await this.processExport(request, result);

      result.status = 'completed';
      result.completed = new Date();
      result.expiresAt = new Date(Date.now() + this.resultTTL);
      result.progress = 100;

      this.notifyProgress(requestId, 'completed', 100, 'Export completed successfully');

    } catch (error) {
      result.status = 'failed';
      result.error = error instanceof Error ? error.message : 'Unknown error';
      result.completed = new Date();

      this.notifyProgress(requestId, 'failed', 0, `Export failed: ${result.error}`);
    } finally {
      this.activeExports.delete(requestId);
      this.progressCallbacks.delete(requestId);

      // Process next item in queue
      this.processQueue();
    }
  }

  /**
   * Process individual export request
   */
  private async processExport(request: ExportRequest, result: ExportResult): Promise<void> {
    const { options, items } = request;

    // Simulate processing delay
    await new Promise(resolve => setTimeout(resolve, 1000));

    this.notifyProgress(request.id, 'processing', 20, 'Gathering items...');

    // Validate items exist (mock)
    const validItems = items; // In real implementation, validate against gallery

    this.notifyProgress(request.id, 'processing', 40, 'Processing items...');

    // Generate export based on format
    let exportData: any;
    let filename: string;
    let mimeType: string;

    switch (options.format) {
      case 'json':
        exportData = await this.generateJSONExport(validItems, options);
        filename = `${request.name}.json`;
        mimeType = 'application/json';
        break;

      case 'csv':
        exportData = await this.generateCSVExport(validItems, options);
        filename = `${request.name}.csv`;
        mimeType = 'text/csv';
        break;

      case 'zip':
        exportData = await this.generateZIPExport(validItems, options);
        filename = `${request.name}.zip`;
        mimeType = 'application/zip';
        break;

      case 'pdf':
        exportData = await this.generatePDFExport(validItems, options);
        filename = `${request.name}.pdf`;
        mimeType = 'application/pdf';
        break;

      case 'html':
        exportData = await this.generateHTMLExport(validItems, options);
        filename = `${request.name}.html`;
        mimeType = 'text/html';
        break;

      case 'midjourney_prompt':
        exportData = await this.generatePlatformExport(validItems, 'midjourney', options);
        filename = `${request.name}_midjourney.txt`;
        mimeType = 'text/plain';
        break;

      case 'dalle_prompt':
        exportData = await this.generatePlatformExport(validItems, 'openai-dalle', options);
        filename = `${request.name}_dalle.txt`;
        mimeType = 'text/plain';
        break;

      default:
        throw new Error(`Unsupported export format: ${options.format}`);
    }

    this.notifyProgress(request.id, 'processing', 80, 'Finalizing export...');

    // Simulate file upload/storage
    await new Promise(resolve => setTimeout(resolve, 500));

    result.url = `https://example.com/exports/${result.id}/${filename}`;
    result.filename = filename;
    result.size = this.calculateSize(exportData);

    if (result.size > this.maxFileSize) {
      throw new Error('Export file size exceeds maximum limit');
    }

    this.notifyProgress(request.id, 'processing', 100, 'Export ready for download');
  }

