import { MetricsInterface } from '../types/index.js';

/**
 * Simple in-memory metrics implementation
 */
export class MemoryMetrics implements MetricsInterface {
  private counters = new Map<string, number>();
  private gauges = new Map<string, number>();
  private histograms = new Map<string, number[]>();
  private timers = new Map<string, number>();

  counter(name: string, value: number = 1, tags?: Record<string, string>): void {
    const key = this.buildKey(name, tags);
    const current = this.counters.get(key) || 0;
    this.counters.set(key, current + value);
  }

  gauge(name: string, value: number, tags?: Record<string, string>): void {
    const key = this.buildKey(name, tags);
    this.gauges.set(key, value);
  }

  histogram(name: string, value: number, tags?: Record<string, string>): void {
    const key = this.buildKey(name, tags);
    const values = this.histograms.get(key) || [];
    values.push(value);
    this.histograms.set(key, values);
  }

  timer(name: string): { end(): void } {
    const startTime = Date.now();
    const timerId = `${name}-${Math.random()}`;

    return {
      end: () => {
        const duration = Date.now() - startTime;
        this.histogram(name, duration);
      }
    };
  }

  /**
   * Get all metrics data
   */
  getMetrics(): {
    counters: Record<string, number>;
    gauges: Record<string, number>;
    histograms: Record<string, {
      count: number;
      min: number;
      max: number;
      avg: number;
      p95: number;
      p99: number;
    }>;
  } {
    const histogramStats: Record<string, any> = {};

    for (const [key, values] of this.histograms.entries()) {
      if (values.length > 0) {
        const sorted = [...values].sort((a, b) => a - b);
        const count = values.length;
        const min = sorted[0];
        const max = sorted[count - 1];
        const sum = values.reduce((a, b) => a + b, 0);
        const avg = sum / count;
        const p95Index = Math.floor(count * 0.95);
        const p99Index = Math.floor(count * 0.99);
        const p95 = sorted[p95Index] || max;
        const p99 = sorted[p99Index] || max;

        histogramStats[key] = { count, min, max, avg, p95, p99 };
      }
    }

    return {
      counters: Object.fromEntries(this.counters),
      gauges: Object.fromEntries(this.gauges),
      histograms: histogramStats
    };
  }

  /**
   * Reset all metrics
   */
  reset(): void {
    this.counters.clear();
    this.gauges.clear();
    this.histograms.clear();
    this.timers.clear();
  }

  private buildKey(name: string, tags?: Record<string, string>): string {
    if (!tags || Object.keys(tags).length === 0) {
      return name;
    }

    const tagString = Object.entries(tags)
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([key, value]) => `${key}=${value}`)
      .join(',');

    return `${name}{${tagString}}`;
  }
}

/**
 * No-op metrics for testing or when metrics are disabled
 */
export class NoOpMetrics implements MetricsInterface {
  counter(): void {}
  gauge(): void {}
  histogram(): void {}
  timer(): { end(): void } {
    return { end: () => {} };
  }
}

import {
  PromptGraph,
  ValidationResult,
  Platform,
  ModelAdaptor,
  AutoFixAction,
  Logger,
  MetricsInterface
} from '../types/index.js';

/**
 * Comprehensive validation engine for prompt graphs
 */
export class ValidationEngine {
  private logger: Logger;
  private metrics: MetricsInterface;
  private customRules: ValidationRule[] = [];

  constructor(logger: Logger, metrics: MetricsInterface) {
    this.logger = logger;
    this.metrics = metrics;
  }

  /**
   * Validate a graph against multiple adaptors
   */
  async validateGraph(
    graph: PromptGraph,
    adaptors: ModelAdaptor[],
    options: ValidationOptions = {}
  ): Promise<ValidationReport> {
    const startTime = Date.now();

    this.logger.info('Starting graph validation', {
      graphId: graph.id,
      adaptorCount: adaptors.length
    });

    const report: ValidationReport = {
      graphId: graph.id,
      timestamp: new Date(),
      overallValid: true,
      totalIssues: 0,
      platformResults: new Map(),
      summary: {
        criticalErrors: 0,
        highErrors: 0,
        mediumWarnings: 0,
        lowInfos: 0
      },
      autoFixSuggestions: [],
      crossPlatformIssues: []
    };

    try {
      // Structural validation (platform-agnostic)
      const structuralResults = await this.validateStructure(graph);

      // Custom rule validation
      const customResults = await this.validateCustomRules(graph);

      // Platform-specific validation
      for (const adaptor of adaptors) {
        const platformResults = await this.validateForPlatform(graph, adaptor);
        report.platformResults.set(adaptor.platform, platformResults);
      }

      // Cross-platform analysis
      report.crossPlatformIssues = this.analyzeCrossPlatformCompatibility(
        Array.from(report.platformResults.values())
      );

      // Add structural and custom results to each platform result
      report.platformResults.forEach((platformResult, platform) => {
        platformResult.results.unshift(...structuralResults, ...customResults);
      });

      // Aggregate results
      this.aggregateResults(report, structuralResults, customResults);

      // Generate auto-fix suggestions
      report.autoFixSuggestions = this.generateAutoFixSuggestions(report);

      const duration = Date.now() - startTime;

      this.logger.info('Graph validation completed', {
        graphId: graph.id,
        overallValid: report.overallValid,
        totalIssues: report.totalIssues,
        duration
      });

      this.metrics.histogram('validation.duration', duration);
      this.metrics.counter('validation.completed', 1, {
        valid: report.overallValid.toString()
      });

      return report;

    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : String(error);
      this.logger.error('Graph validation failed', {
        graphId: graph.id,
        error: errorMessage
      });

      this.metrics.counter('validation.failed', 1);
      throw error;
    }
  }

  /**
   * Validate graph structure (platform-agnostic)
   */
  private async validateStructure(graph: PromptGraph): Promise<ValidationResult[]> {
    const results: ValidationResult[] = [];

    // Check for empty graph
    if (!graph.nodes || graph.nodes.length === 0) {
      results.push({
        id: 'empty-graph',
        type: 'error',
        severity: 'critical',
        message: 'Graph is empty',
        description: 'The prompt graph contains no nodes',
        autoFixable: false
      });
      return results;
    }

    // Check for cycles
    const cycles = this.detectCycles(graph);
    cycles.forEach((cycle, index) => {
      results.push({
        id: `cycle-${index}`,
        type: 'error',
        severity: 'high',
        message: 'Circular dependency detected',
        description: `Cycle involves nodes: ${cycle.join(' → ')}`,
        autoFixable: true,
        suggestions: [{
          type: 'fix',
          description: 'Remove one edge to break the cycle',
          action: {
            type: 'edge_remove',
            targetId: `${cycle[cycle.length - 1]}-${cycle[0]}`,
            changes: {}
          }
        }]
      });
    });

    // Check for disconnected components
    const components = this.findConnectedComponents(graph);
    if (components.length > 1) {
      results.push({
        id: 'disconnected-components',
        type: 'warning',
        severity: 'medium',
        message: 'Graph has disconnected components',
        description: `Found ${components.length} separate components`,
        autoFixable: true,
        suggestions: [{
          type: 'fix',
          description: 'Connect disconnected components or remove isolated nodes',
          action: {
            type: 'node_modify',
            targetId: 'disconnected-components',
            changes: {}
          }
        }]
      });
    }

    // Check for orphaned nodes
    const connectedNodeIds = new Set<string>();
    graph.edges?.forEach(edge => {
      connectedNodeIds.add(edge.source);
      connectedNodeIds.add(edge.target);
    });

    graph.nodes.forEach(node => {
      if (!connectedNodeIds.has(node.id) && graph.nodes.length > 1) {
        results.push({
          id: `orphaned-node-${node.id}`,
          type: 'warning',
          severity: 'low',
          message: 'Orphaned node detected',
          description: `Node "${node.data.label || node.id}" is not connected`,
          nodeId: node.id,
          autoFixable: true,
          suggestions: [{
            type: 'fix',
            description: 'Remove orphaned node or connect it to the graph',
            action: {
              type: 'node_remove',
              targetId: node.id,
              changes: {}
            }
          }]
        });
      }
    });

    // Check for missing required data
    graph.nodes.forEach(node => {
      if (!node.data) {
        results.push({
          id: `missing-data-${node.id}`,
          type: 'error',
          severity: 'high',
          message: 'Node missing data',
          description: `Node "${node.id}" has no data object`,
          nodeId: node.id,
          autoFixable: true,
          suggestions: [{
            type: 'fix',
            description: 'Add default data object to node'
          }]
        });
      }
    });

    return results;
  }

  /**
   * Validate against custom rules
   */
  private async validateCustomRules(graph: PromptGraph): Promise<ValidationResult[]> {
    const results: ValidationResult[] = [];

    for (const rule of this.customRules) {
      try {
        const ruleResults = await rule.validate(graph);
        results.push(...ruleResults);
      } catch (error) {
        const errorMessage = error instanceof Error ? error.message : String(error);
        this.logger.warn('Custom rule validation failed', {
          ruleId: rule.id,
          error: errorMessage
        });
      }
    }

    return results;
  }

  /**
   * Validate graph for specific platform
   */
  private async validateForPlatform(
    graph: PromptGraph,
    adaptor: ModelAdaptor
  ): Promise<PlatformValidationResult> {
    const startTime = Date.now();

    try {
      const results = await adaptor.validate(graph);
      const capabilities = await adaptor.capabilities();
      const quality = await adaptor.estimateQuality(graph);

      return {
        platform: adaptor.platform,
        adaptorId: adaptor.id,
        adaptorVersion: adaptor.version,
        results,
        capabilities,
        quality,
        compatible: results.filter(r => r.type === 'error').length === 0,
        duration: Date.now() - startTime
      };
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : String(error);
      this.logger.error('Platform validation failed', {
        platform: adaptor.platform,
        adaptorId: adaptor.id,
        error: errorMessage
      });

      return {
        platform: adaptor.platform,
        adaptorId: adaptor.id,
        adaptorVersion: adaptor.version,
        results: [{
          id: 'validation-failed',
          type: 'error',
          severity: 'critical',
          message: 'Platform validation failed',
          description: errorMessage,
          autoFixable: false
        }],
        capabilities: {
          supportedNodeTypes: [],
          parameters: [],
          limitations: [],
          features: [],
          supportedFormats: []
        },
        quality: {
          overall: 0,
          fidelity: 0,
          compatibility: 0,
          performance: 0,
          completeness: 0,
          breakdown: {
            nodeTranslation: 0,
            parameterMapping: 0,
            featureSupport: 0,
            semanticPreservation: 0,
            syntaxValidity: 0
          }
        },
        compatible: false,
        duration: Date.now() - startTime
      };
    }
  }

  /**
   * Analyze cross-platform compatibility issues
   */
  private analyzeCrossPlatformCompatibility(
    platformResults: PlatformValidationResult[]
  ): CrossPlatformIssue[] {
    const issues: CrossPlatformIssue[] = [];

    // Find features supported by some but not all platforms
    const allFeatures = new Set<string>();
    const platformFeatures = new Map<Platform, Set<string>>();

    platformResults.forEach(result => {
      const features = new Set<string>(
        result.capabilities.features
          .filter((f: any) => f.supported)
          .map((f: any) => f.name)
      );

      platformFeatures.set(result.platform, features);
      features.forEach((f: string) => allFeatures.add(f));
    });

    allFeatures.forEach(feature => {
      const supportingPlatforms = Array.from(platformFeatures.entries())
        .filter(([_, features]) => features.has(feature))
        .map(([platform, _]) => platform);

      if (supportingPlatforms.length > 0 && supportingPlatforms.length < platformResults.length) {
        issues.push({
          type: 'feature_support',
          severity: 'medium',
          feature,
          supportingPlatforms,
          unsupportedPlatforms: platformResults
            .map(r => r.platform)
            .filter(p => !supportingPlatforms.includes(p)),
          description: `Feature "${feature}" is not supported across all platforms`,
          impact: 'Reduced functionality on some platforms'
        });
      }
    });

    // Find node types with compatibility issues
    const nodeTypeSupport = new Map<string, Platform[]>();

    platformResults.forEach(result => {
      result.capabilities.supportedNodeTypes.forEach((nodeType: any) => {
        if (!nodeTypeSupport.has(nodeType)) {
          nodeTypeSupport.set(nodeType, []);
        }
        nodeTypeSupport.get(nodeType)!.push(result.platform);
      });
    });

    // TODO: Add more cross-platform analysis

    return issues;
  }

  /**
   * Aggregate validation results
   */
  private aggregateResults(
    report: ValidationReport,
    structuralResults: ValidationResult[],
    customResults: ValidationResult[]
  ): void {
    const allResults = [
      ...structuralResults,
      ...customResults,
      ...Array.from(report.platformResults.values())
        .flatMap(pr => pr.results)
    ];

    allResults.forEach(result => {
      report.totalIssues++;

      if (result.type === 'error') {
        report.overallValid = false;

        if (result.severity === 'critical') {
          report.summary.criticalErrors++;
        } else {
          report.summary.highErrors++;
        }
      } else if (result.type === 'warning') {
        report.summary.mediumWarnings++;
      } else {
        report.summary.lowInfos++;
      }
    });
  }

  /**
   * Generate auto-fix suggestions
   */
  private generateAutoFixSuggestions(report: ValidationReport): AutoFixSuggestion[] {
    const suggestions: AutoFixSuggestion[] = [];

    // Collect all auto-fixable issues from all platform results
    const autoFixableIssues: ValidationResult[] = [];

    report.platformResults.forEach(platformResult => {
      const fixableResults = platformResult.results.filter(r => r.autoFixable);
      autoFixableIssues.push(...fixableResults);
    });

    // Group by issue type and create suggestions
    const fixGroups = new Map<string, ValidationResult[]>();

    autoFixableIssues.forEach(issue => {
      if (issue.suggestions && issue.suggestions.length > 0) {
        issue.suggestions.forEach(suggestion => {
          let key: string;

          if (suggestion.action && suggestion.action.targetId) {
            key = `${suggestion.action.type}:${suggestion.action.targetId}`;
          } else {
            // Fallback grouping by issue type for suggestions without actions
            key = `${issue.type}:${issue.severity}:${suggestion.type}`;
          }

          if (!fixGroups.has(key)) {
            fixGroups.set(key, []);
          }
          fixGroups.get(key)!.push(issue);
        });
      } else {
        // Create default suggestion for auto-fixable issues without explicit suggestions
        const key = `${issue.type}:${issue.severity}:default`;
        if (!fixGroups.has(key)) {
          fixGroups.set(key, []);
        }
        fixGroups.get(key)!.push(issue);
      }
    });

    // Generate suggestions from groups
    fixGroups.forEach((issues, key) => {
      const firstIssue = issues[0];
      let suggestion: any;

      if (firstIssue.suggestions && firstIssue.suggestions.length > 0) {
        suggestion = firstIssue.suggestions[0];
      } else {
        // Create default suggestion
        suggestion = {
          type: 'fix',
          description: `Fix ${issues.length} ${firstIssue.type}${issues.length > 1 ? 's' : ''}`,
          action: {
            type: 'node_modify',
            targetId: firstIssue.nodeId || firstIssue.edgeId || 'unknown',
            changes: {}
          }
        };
      }

      suggestions.push({
        id: `autofix-${key.replace(/:/g, '-')}`,
        type: suggestion.type || 'fix',
        description: suggestion.description,
        action: suggestion.action || {
          type: 'node_modify',
          targetId: 'unknown',
          changes: {}
        },
        affectedIssues: issues.map(i => i.id),
        confidence: this.calculateFixConfidence(issues),
        impact: this.assessFixImpact(issues)
      });
    });

    return suggestions;
  }

  /**
   * Detect cycles in the graph
   */
  private detectCycles(graph: PromptGraph): string[][] {
    const cycles: string[][] = [];
    const visited = new Set<string>();
    const recursionStack = new Set<string>();
    const path: string[] = [];

    const adjacencyList = new Map<string, string[]>();

    // Build adjacency list
    graph.nodes.forEach(node => {
      adjacencyList.set(node.id, []);
    });

    graph.edges?.forEach(edge => {
      const targets = adjacencyList.get(edge.source) || [];
      targets.push(edge.target);
      adjacencyList.set(edge.source, targets);
    });

    const dfs = (nodeId: string): boolean => {
      visited.add(nodeId);
      recursionStack.add(nodeId);
      path.push(nodeId);

      const neighbors = adjacencyList.get(nodeId) || [];

      for (const neighbor of neighbors) {
        if (!visited.has(neighbor)) {
          if (dfs(neighbor)) {
            return true;
          }
        } else if (recursionStack.has(neighbor)) {
          // Found cycle
          const cycleStart = path.indexOf(neighbor);
          cycles.push([...path.slice(cycleStart), neighbor]);
          return true;
        }
      }

      recursionStack.delete(nodeId);
      path.pop();
      return false;
    };

    graph.nodes.forEach(node => {
      if (!visited.has(node.id)) {
        dfs(node.id);
      }
    });

    return cycles;
  }

  /**
   * Find connected components in the graph
   */
  private findConnectedComponents(graph: PromptGraph): string[][] {
    const visited = new Set<string>();
    const components: string[][] = [];

    const adjacencyList = new Map<string, string[]>();

    // Build undirected adjacency list
    graph.nodes.forEach(node => {
      adjacencyList.set(node.id, []);
    });

    graph.edges?.forEach(edge => {
      const sourceTargets = adjacencyList.get(edge.source) || [];
      const targetTargets = adjacencyList.get(edge.target) || [];

      sourceTargets.push(edge.target);
      targetTargets.push(edge.source);

      adjacencyList.set(edge.source, sourceTargets);
      adjacencyList.set(edge.target, targetTargets);
    });

    const dfs = (nodeId: string, component: string[]): void => {
      visited.add(nodeId);
      component.push(nodeId);

      const neighbors = adjacencyList.get(nodeId) || [];
      neighbors.forEach(neighbor => {
        if (!visited.has(neighbor)) {
          dfs(neighbor, component);
        }
      });
    };

    graph.nodes.forEach(node => {
      if (!visited.has(node.id)) {
        const component: string[] = [];
        dfs(node.id, component);
        components.push(component);
      }
    });

    return components;
  }

  /**
   * Calculate confidence for an auto-fix suggestion
   */
  private calculateFixConfidence(issues: ValidationResult[]): number {
    // Simple heuristic: more severe issues = lower confidence for auto-fix
    const severityWeights = { critical: 0.1, high: 0.3, medium: 0.7, low: 0.9 };

    const avgConfidence = issues.reduce((sum, issue) => {
      return sum + (severityWeights[issue.severity] || 0.5);
    }, 0) / issues.length;

    return Math.round(avgConfidence * 100);
  }

  /**
   * Assess impact of an auto-fix
   */
  private assessFixImpact(issues: ValidationResult[]): 'low' | 'medium' | 'high' {
    const hasHighSeverity = issues.some(i => 
      i.severity === 'critical' || i.severity === 'high'
    );

    if (hasHighSeverity) return 'high';
    if (issues.length > 3) return 'medium';
    return 'low';
  }

  /**
   * Add custom validation rule
   */
  addCustomRule(rule: ValidationRule): void {
    this.customRules.push(rule);
    this.logger.info('Custom validation rule added', { ruleId: rule.id });
  }

  /**
   * Remove custom validation rule
   */
  removeCustomRule(ruleId: string): void {
    const index = this.customRules.findIndex(rule => rule.id === ruleId);
    if (index >= 0) {
      this.customRules.splice(index, 1);
      this.logger.info('Custom validation rule removed', { ruleId });
    }
  }
}

// Supporting interfaces and types
export interface ValidationOptions {
  includeWarnings?: boolean;
  includeLowSeverity?: boolean;
  customRules?: boolean;
}

export interface ValidationReport {
  graphId: string;
  timestamp: Date;
  overallValid: boolean;
  totalIssues: number;
  platformResults: Map<Platform, PlatformValidationResult>;
  summary: ValidationSummary;
  autoFixSuggestions: AutoFixSuggestion[];
  crossPlatformIssues: CrossPlatformIssue[];
}

export interface PlatformValidationResult {
  platform: Platform;
  adaptorId: string;
  adaptorVersion: string;
  results: ValidationResult[];
  capabilities: any;
  quality: any;
  compatible: boolean;
  duration: number;
}

export interface ValidationSummary {
  criticalErrors: number;
  highErrors: number;
  mediumWarnings: number;
  lowInfos: number;
}

export interface AutoFixSuggestion {
  id: string;
  type: 'fix' | 'alternative' | 'workaround';
  description: string;
  action: AutoFixAction;
  affectedIssues: string[];
  confidence: number; // 0-100
  impact: 'low' | 'medium' | 'high';
}

export interface CrossPlatformIssue {
  type: 'feature_support' | 'node_type' | 'parameter';
  severity: 'low' | 'medium' | 'high';
  feature?: string;
  supportingPlatforms: Platform[];
  unsupportedPlatforms: Platform[];
  description: string;
  impact: string;
}

export interface ValidationRule {
  id: string;
  name: string;
  description: string;
  validate(graph: PromptGraph): Promise<ValidationResult[]>;
}

/**
 * Configuration system tests
 * Epic 10.2.2 - Configuration System Testing
 */

import { ConfigurationManager, GlobalConfigSchema } from '../src/config/ConfigurationManager';

describe('Configuration System', () => {
  let configManager: ConfigurationManager;

  beforeEach(() => {
    configManager = new ConfigurationManager();
  });

  describe('ConfigurationManager', () => {
    test('should initialize with default configuration', () => {
      const config = configManager.getConfig();

      expect(config.qualityPreference).toBe(0.7);
      expect(config.stylePreference).toBe('default');
      expect(config.enableOptimizations).toBe(true);
      expect(config.platformOverrides).toEqual({});
    });

    test('should initialize with custom configuration', () => {
      const customConfig = {
        qualityPreference: 0.9,
        stylePreference: 'photorealistic' as const,
        platformOverrides: {
          openai: {
            model: 'gpt-4' as const,
            temperature: 0.2,
          },
        },
      };

      const manager = new ConfigurationManager(customConfig);
      const config = manager.getConfig();

      expect(config.qualityPreference).toBe(0.9);
      expect(config.stylePreference).toBe('photorealistic');
      expect(config.platformOverrides.openai?.model).toBe('gpt-4');
      expect(config.platformOverrides.openai?.temperature).toBe(0.2);
    });

    test('should validate configuration updates', () => {
      const result = configManager.updateConfig({
        qualityPreference: 0.8,
        stylePreference: 'artistic',
      });

      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);

      const config = configManager.getConfig();
      expect(config.qualityPreference).toBe(0.8);
      expect(config.stylePreference).toBe('artistic');
    });

    test('should reject invalid configuration updates', () => {
      const result = configManager.updateConfig({
        qualityPreference: 2.5, // Invalid: must be 0-1
      } as any);

      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);

      // Original config should remain unchanged
      const config = configManager.getConfig();
      expect(config.qualityPreference).toBe(0.7);
    });

    test('should set and get specific configuration values', () => {
      const result = configManager.setConfigValue('platformOverrides.openai.temperature', 0.3);

      expect(result.valid).toBe(true);
      expect(configManager.getConfigValue('platformOverrides.openai.temperature')).toBe(0.3);
    });

    test('should provide business logic warnings', () => {
      const result = configManager.updateConfig({
        qualityPreference: 0.9,
        stylePreference: 'minimal', // Conflicting: high quality + minimal style
      });

      expect(result.valid).toBe(true);
      expect(result.warnings.length).toBeGreaterThan(0);
      expect(result.warnings[0].message).toContain('High quality preference with minimal style');
    });

    test('should track configuration history', () => {
      configManager.updateConfig({ qualityPreference: 0.8 }, 'Test update 1');
      configManager.updateConfig({ qualityPreference: 0.9 }, 'Test update 2');

      const history = configManager.getConfigHistory(5);

      expect(history).toHaveLength(2);
      expect(history[0].reason).toBe('Test update 1');
      expect(history[1].reason).toBe('Test update 2');
    });

    test('should reset to default configuration', () => {
      // Modify config
      configManager.updateConfig({
        qualityPreference: 0.9,
        stylePreference: 'artistic',
      });

      // Reset to defaults
      const result = configManager.resetToDefaults();

      expect(result.valid).toBe(true);

      const config = configManager.getConfig();
      expect(config.qualityPreference).toBe(0.7);
      expect(config.stylePreference).toBe('default');
    });
  });

  describe('Configuration Presets', () => {
    test('should have built-in presets', () => {
      const presets = configManager.listPresets();

      expect(presets.length).toBeGreaterThan(0);

      const builtInPresets = presets.filter(p => p.isBuiltIn);
      expect(builtInPresets.length).toBeGreaterThan(0);

      // Check for expected built-in presets
      const presetNames = presets.map(p => p.name);
      expect(presetNames).toContain('high-quality');
      expect(presetNames).toContain('creative');
      expect(presetNames).toContain('fast');
    });

    test('should create custom presets', () => {
      configManager.createPreset(
        'test-preset',
        'Test preset description',
        { qualityPreference: 0.8 },
        ['test', 'custom']
      );

      const presets = configManager.listPresets();
      const testPreset = presets.find(p => p.name === 'test-preset');

      expect(testPreset).toBeDefined();
      expect(testPreset?.description).toBe('Test preset description');
      expect(testPreset?.isBuiltIn).toBe(false);
      expect(testPreset?.tags).toContain('test');
      expect(testPreset?.tags).toContain('custom');
    });

    test('should apply presets', () => {
      const result = configManager.applyPreset('high-quality');

      expect(result.valid).toBe(true);

      const config = configManager.getConfig();
      expect(config.qualityPreference).toBe(0.9);
      expect(config.stylePreference).toBe('photorealistic');
    });

    test('should filter presets by tags', () => {
      configManager.createPreset('preset1', 'Desc1', {}, ['tag1', 'tag2']);
      configManager.createPreset('preset2', 'Desc2', {}, ['tag2', 'tag3']);
      configManager.createPreset('preset3', 'Desc3', {}, ['tag3']);

      const tag2Presets = configManager.listPresets(['tag2']);

      expect(tag2Presets).toHaveLength(2);
      expect(tag2Presets.map(p => p.name)).toContain('preset1');
      expect(tag2Presets.map(p => p.name)).toContain('preset2');
    });

    test('should delete custom presets', () => {
      configManager.createPreset('deletable', 'Will be deleted', {});

      const success = configManager.deletePreset('deletable');
      expect(success).toBe(true);

      const presets = configManager.listPresets();
      expect(presets.find(p => p.name === 'deletable')).toBeUndefined();
    });

    test('should not delete built-in presets', () => {
      expect(() => {
        configManager.deletePreset('high-quality');
      }).toThrow('Cannot delete built-in presets');
    });

    test('should handle non-existent preset application', () => {
      const result = configManager.applyPreset('non-existent');

      expect(result.valid).toBe(false);
      expect(result.errors[0].code).toBe('PRESET_NOT_FOUND');
    });
  });

  describe('Import/Export', () => {
    test('should export configuration as JSON', () => {
      configManager.updateConfig({
        qualityPreference: 0.8,
        stylePreference: 'artistic',
      });

      const exported = configManager.exportConfig('json');
      const parsed = JSON.parse(exported);

      expect(parsed.qualityPreference).toBe(0.8);
      expect(parsed.stylePreference).toBe('artistic');
    });

    test('should export configuration as YAML', () => {
      configManager.updateConfig({
        qualityPreference: 0.8,
        stylePreference: 'artistic',
      });

      const exported = configManager.exportConfig('yaml');

      expect(typeof exported).toBe('string');
      expect(exported).toContain('qualityPreference: 0.8');
      expect(exported).toContain('stylePreference: artistic');
    });

    test('should import JSON configuration', () => {
      const configData = JSON.stringify({
        qualityPreference: 0.6,
        stylePreference: 'minimal',
        enableOptimizations: false,
      });

      const result = configManager.importConfig(configData, 'json');

      expect(result.valid).toBe(true);

      const config = configManager.getConfig();
      expect(config.qualityPreference).toBe(0.6);
      expect(config.stylePreference).toBe('minimal');
      expect(config.enableOptimizations).toBe(false);
    });

    test('should handle invalid JSON import', () => {
      const result = configManager.importConfig('invalid json', 'json');

      expect(result.valid).toBe(false);
      expect(result.errors[0].code).toBe('IMPORT_ERROR');
    });

    test('should import YAML configuration', () => {
      const yamlData = `
qualityPreference: 0.6
stylePreference: minimal
enableOptimizations: false
      `.trim();

      const result = configManager.importConfig(yamlData, 'yaml');

      expect(result.valid).toBe(true);

      const config = configManager.getConfig();
      expect(config.qualityPreference).toBe(0.6);
      expect(config.stylePreference).toBe('minimal');
      expect(config.enableOptimizations).toBe(false);
    });
  });

  describe('Configuration Summary', () => {
    test('should provide configuration summary', () => {
      configManager.updateConfig({
        qualityPreference: 0.9,
        platformOverrides: {
          openai: { model: 'gpt-4' },
          midjourney: { version: '6' },
        },
      });

      const summary = configManager.getConfigSummary();

      expect(summary.platforms).toContain('openai');
      expect(summary.platforms).toContain('midjourney');
      expect(summary.qualityLevel).toBe('High');
      expect(summary.optimizationsEnabled).toBe(true);
      expect(summary.presetCount).toBeGreaterThan(0);
    });

    test('should categorize quality levels correctly', () => {
      // Low quality
      configManager.updateConfig({ qualityPreference: 0.3 });
      expect(configManager.getConfigSummary().qualityLevel).toBe('Low');

      // Medium quality
      configManager.updateConfig({ qualityPreference: 0.6 });
      expect(configManager.getConfigSummary().qualityLevel).toBe('Medium');

      // High quality
      configManager.updateConfig({ qualityPreference: 0.9 });
      expect(configManager.getConfigSummary().qualityLevel).toBe('High');
    });
  });

  describe('Schema Validation', () => {
    test('should validate global configuration schema', () => {
      const validConfig = {
        qualityPreference: 0.8,
        stylePreference: 'artistic',
        enableOptimizations: true,
        platformOverrides: {
          openai: {
            model: 'gpt-4',
            temperature: 0.7,
          },
        },
      };

      expect(() => GlobalConfigSchema.parse(validConfig)).not.toThrow();
    });

    test('should reject invalid schema values', () => {
      const invalidConfig = {
        qualityPreference: 2.0, // Invalid: > 1
        stylePreference: 'invalid-style', // Invalid enum value
      };

      expect(() => GlobalConfigSchema.parse(invalidConfig)).toThrow();
    });

    test('should apply default values for missing fields', () => {
      const partialConfig = {
        qualityPreference: 0.8,
      };

      const parsed = GlobalConfigSchema.parse(partialConfig);

      expect(parsed.stylePreference).toBe('default');
      expect(parsed.enableOptimizations).toBe(true);
      expect(parsed.platformOverrides).toEqual({});
    });
  });

  describe('Event System', () => {
    test('should emit config change events', (done) => {
      configManager.on('config:changed', (path, newValue, oldValue) => {
        expect(path).toBe('qualityPreference');
        expect(newValue).toBe(0.8);
        expect(oldValue).toBe(0.7);
        done();
      });

      configManager.setConfigValue('qualityPreference', 0.8);
    });

    test('should emit validation events', (done) => {
      configManager.on('config:validated', (result) => {
        expect(result.valid).toBe(true);
        done();
      });

      configManager.updateConfig({ qualityPreference: 0.8 });
    });

    test('should emit preset application events', (done) => {
      configManager.on('config:preset:applied', (presetName, config) => {
        expect(presetName).toBe('creative');
        expect(config.stylePreference).toBe('artistic');
        done();
      });

      configManager.applyPreset('creative');
    });

    test('should emit export events', (done) => {
      configManager.on('config:exported', (format, config) => {
        expect(format).toBe('json');
        expect(config.qualityPreference).toBe(0.7);
        done();
      });

      configManager.exportConfig('json');
    });

    test('should emit import events', (done) => {
      configManager.on('config:imported', (source, config) => {
        expect(source).toBe('json');
        expect(config.qualityPreference).toBe(0.6);
        done();
      });

      const configData = JSON.stringify({ qualityPreference: 0.6 });
      configManager.importConfig(configData, 'json');
    });
  });

  describe('Error Handling', () => {
    test('should handle malformed configuration gracefully', () => {
      const result = configManager.updateConfig({
        qualityPreference: 'invalid' as any,
      });

      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);

      // Original config should remain unchanged
      const config = configManager.getConfig();
      expect(config.qualityPreference).toBe(0.7);
    });

    test('should handle missing nested properties', () => {
      const result = configManager.setConfigValue('nonexistent.deeply.nested.path', 'value');

      expect(result.valid).toBe(true);
      expect(configManager.getConfigValue('nonexistent.deeply.nested.path')).toBe('value');
    });

    test('should handle concurrent updates safely', async () => {
      const promises = Array.from({ length: 10 }, (_, i) =>
        configManager.updateConfig({ qualityPreference: i / 10 })
      );

      const results = await Promise.all(promises);

      // All updates should succeed individually
      results.forEach(result => {
        expect(result.valid).toBe(true);
      });

      // Final config should have a valid value
      const finalConfig = configManager.getConfig();
      expect(finalConfig.qualityPreference).toBeGreaterThanOrEqual(0);
      expect(finalConfig.qualityPreference).toBeLessThanOrEqual(1);
    });
  });
});

