/**
 * Adaptor registry for discovery and management
 * Epic 10.1.2 - Common Interface Definition
 */

import {
  ModelAdaptor,
  AdaptorRegistry,
  PlatformCapabilities,
  AdaptorError,
} from '../types';
import { EventEmitter } from 'events';
import semver from 'semver';

/**
 * Events emitted by the adaptor registry
 */
export interface AdaptorRegistryEvents {
  'adaptor:registered': (adaptor: ModelAdaptor) => void;
  'adaptor:unregistered': (adaptorId: string) => void;
  'adaptor:updated': (adaptor: ModelAdaptor, oldVersion: string) => void;
  'capabilities:changed': (adaptorId: string, capabilities: PlatformCapabilities) => void;
}

/**
 * Implementation of adaptor registry for managing platform adaptors
 */
export class DefaultAdaptorRegistry extends EventEmitter implements AdaptorRegistry {
  private adaptors = new Map<string, ModelAdaptor>();
  private capabilitiesCache = new Map<string, PlatformCapabilities>();
  private platformIndex = new Map<string, Set<string>>();
  private capabilityIndex = new Map<string, Set<string>>();
  private logger: Console = console;

  constructor() {
    super();
    this.setupEventHandlers();
  }

  /**
   * Register an adaptor in the registry
   */
  public async register(adaptor: ModelAdaptor): Promise<void> {
    try {
      // Validate adaptor interface
      this.validateAdaptor(adaptor);

      // Check for version conflicts
      const existingAdaptor = this.adaptors.get(adaptor.id);
      if (existingAdaptor) {
        await this.handleVersionConflict(existingAdaptor, adaptor);
      }

      // Initialize adaptor if not already initialized
      if (typeof adaptor.initialize === 'function') {
        await adaptor.initialize();
      }

      // Get and cache capabilities
      const capabilities = await adaptor.capabilities();
      this.capabilitiesCache.set(adaptor.id, capabilities);

      // Update indices
      this.updatePlatformIndex(adaptor);
      this.updateCapabilityIndex(adaptor, capabilities);

      // Register adaptor
      this.adaptors.set(adaptor.id, adaptor);

      this.logger.log(`Registered adaptor: ${adaptor.id} v${adaptor.version}`);
      this.emit('adaptor:registered', adaptor);
    } catch (error) {
      throw new AdaptorError(
        `Failed to register adaptor ${adaptor.id}: ${error instanceof Error ? error.message : 'Unknown error'}`,
        adaptor.id,
        'REGISTRATION_FAILED',
        { error }
      );
    }
  }

  /**
   * Unregister an adaptor from the registry
   */
  public async unregister(adaptorId: string): Promise<void> {
    const adaptor = this.adaptors.get(adaptorId);
    if (!adaptor) {
      throw new AdaptorError(
        `Adaptor ${adaptorId} not found in registry`,
        adaptorId,
        'ADAPTOR_NOT_FOUND'
      );
    }

    try {
      // Clean up adaptor
      if (typeof adaptor.cleanup === 'function') {
        await adaptor.cleanup();
      }

      // Remove from indices
      this.removePlatformIndex(adaptor);
      this.removeCapabilityIndex(adaptor);

      // Remove from registry
      this.adaptors.delete(adaptorId);
      this.capabilitiesCache.delete(adaptorId);

      this.logger.log(`Unregistered adaptor: ${adaptorId}`);
      this.emit('adaptor:unregistered', adaptorId);
    } catch (error) {
      throw new AdaptorError(
        `Failed to unregister adaptor ${adaptorId}: ${error instanceof Error ? error.message : 'Unknown error'}`,
        adaptorId,
        'UNREGISTRATION_FAILED',
        { error }
      );
    }
  }

  /**
   * Get adaptor by ID
   */
  public get(adaptorId: string): ModelAdaptor | undefined {
    return this.adaptors.get(adaptorId);
  }

  /**
   * List all registered adaptors
   */
  public list(): ModelAdaptor[] {
    return Array.from(this.adaptors.values());
  }

  /**
   * Find adaptors by platform
   */
  public findByPlatform(platform: string): ModelAdaptor[] {
    const adaptorIds = this.platformIndex.get(platform);
    if (!adaptorIds) {
      return [];
    }

    return Array.from(adaptorIds)
      .map(id => this.adaptors.get(id))
      .filter((adaptor): adaptor is ModelAdaptor => adaptor !== undefined);
  }

  /**
   * Find adaptors by capability
   */
  public findByCapability(capability: string): ModelAdaptor[] {
    const adaptorIds = this.capabilityIndex.get(capability);
    if (!adaptorIds) {
      return [];
    }

    return Array.from(adaptorIds)
      .map(id => this.adaptors.get(id))
      .filter((adaptor): adaptor is ModelAdaptor => adaptor !== undefined);
  }

  /**
   * Get cached capabilities for an adaptor
   */
  public getCapabilities(adaptorId: string): PlatformCapabilities | undefined {
    return this.capabilitiesCache.get(adaptorId);
  }

  /**
   * Refresh capabilities for an adaptor
   */
  public async refreshCapabilities(adaptorId: string): Promise<PlatformCapabilities> {
    const adaptor = this.adaptors.get(adaptorId);
    if (!adaptor) {
      throw new AdaptorError(
        `Adaptor ${adaptorId} not found`,
        adaptorId,
        'ADAPTOR_NOT_FOUND'
      );
    }

    try {
      const capabilities = await adaptor.capabilities();
      this.capabilitiesCache.set(adaptorId, capabilities);
      this.updateCapabilityIndex(adaptor, capabilities);

      this.emit('capabilities:changed', adaptorId, capabilities);
      return capabilities;
    } catch (error) {
      throw new AdaptorError(
        `Failed to refresh capabilities for ${adaptorId}: ${error instanceof Error ? error.message : 'Unknown error'}`,
        adaptorId,
        'CAPABILITIES_REFRESH_FAILED',
        { error }
      );
    }
  }

  /**
   * Get all supported platforms
   */
  public getSupportedPlatforms(): string[] {
    return Array.from(this.platformIndex.keys());
  }

  /**
   * Get all available capabilities
   */
  public getAvailableCapabilities(): string[] {
    return Array.from(this.capabilityIndex.keys());
  }

  /**
   * Find best adaptor for platform with specific requirements
   */
  public findBestAdaptor(
    platform: string,
    requirements?: {
      minVersion?: string;
      requiredCapabilities?: string[];
      preferredCapabilities?: string[];
    }
  ): ModelAdaptor | undefined {
    const candidates = this.findByPlatform(platform);

    if (candidates.length === 0) {
      return undefined;
    }

    // Filter by version requirement
    let filtered = candidates;
    if (requirements?.minVersion) {
      filtered = candidates.filter(adaptor => 
        semver.gte(adaptor.version, requirements.minVersion!)
      );
    }

    // Filter by required capabilities
    if (requirements?.requiredCapabilities && requirements.requiredCapabilities.length > 0) {
      filtered = filtered.filter(adaptor => {
        const capabilities = this.capabilitiesCache.get(adaptor.id);
        if (!capabilities) return false;

        return requirements.requiredCapabilities!.every(req =>
          capabilities.features.includes(req)
        );
      });
    }

    if (filtered.length === 0) {
      return undefined;
    }

    // Sort by preferred capabilities and version
    filtered.sort((a, b) => {
      // First, prefer adaptors with more preferred capabilities
      if (requirements?.preferredCapabilities) {
        const aCapabilities = this.capabilitiesCache.get(a.id);
        const bCapabilities = this.capabilitiesCache.get(b.id);

        if (aCapabilities && bCapabilities) {
          const aScore = requirements.preferredCapabilities.filter(pref =>
            aCapabilities.features.includes(pref)
          ).length;
          const bScore = requirements.preferredCapabilities.filter(pref =>
            bCapabilities.features.includes(pref)
          ).length;

          if (aScore !== bScore) {
            return bScore - aScore; // Higher score first
          }
        }
      }

      // Then prefer newer versions
      return semver.compare(b.version, a.version);
    });

    return filtered[0];
  }

  /**
   * Validate adaptor interface compliance
   */
  private validateAdaptor(adaptor: ModelAdaptor): void {
    const required = ['id', 'version', 'name', 'description', 'platforms'];
    const missing = required.filter(prop => !(prop in adaptor));

    if (missing.length > 0) {
      throw new AdaptorError(
        `Adaptor missing required properties: ${missing.join(', ')}`,
        adaptor.id || 'unknown',
        'INVALID_ADAPTOR_INTERFACE'
      );
    }

    if (!semver.valid(adaptor.version)) {
      throw new AdaptorError(
        `Adaptor version must be valid semver: ${adaptor.version}`,
        adaptor.id,
        'INVALID_VERSION'
      );
    }

    if (!Array.isArray(adaptor.platforms) || adaptor.platforms.length === 0) {
      throw new AdaptorError(
        'Adaptor must support at least one platform',
        adaptor.id,
        'NO_PLATFORMS_SUPPORTED'
      );
    }

    if (typeof adaptor.capabilities !== 'function') {
      throw new AdaptorError(
        'Adaptor must implement capabilities() method',
        adaptor.id,
        'MISSING_CAPABILITIES_METHOD'
      );
    }

    if (typeof adaptor.validate !== 'function') {
      throw new AdaptorError(
        'Adaptor must implement validate() method',
        adaptor.id,
        'MISSING_VALIDATE_METHOD'
      );
    }

    if (typeof adaptor.transform !== 'function') {
      throw new AdaptorError(
        'Adaptor must implement transform() method',
        adaptor.id,
        'MISSING_TRANSFORM_METHOD'
      );
    }
  }

  /**
   * Handle version conflicts when registering adaptors
   */
  private async handleVersionConflict(
    existing: ModelAdaptor,
    incoming: ModelAdaptor
  ): Promise<void> {
    const comparison = semver.compare(incoming.version, existing.version);

    if (comparison > 0) {
      // Incoming version is newer
      this.logger.log(`Updating adaptor ${incoming.id} from v${existing.version} to v${incoming.version}`);
      await this.unregister(existing.id);
      this.emit('adaptor:updated', incoming, existing.version);
    } else if (comparison === 0) {
      throw new AdaptorError(
        `Adaptor ${incoming.id} v${incoming.version} is already registered`,
        incoming.id,
        'DUPLICATE_VERSION'
      );
    } else {
      throw new AdaptorError(
        `Cannot register older version ${incoming.version} of adaptor ${incoming.id} (current: v${existing.version})`,
        incoming.id,
        'OLDER_VERSION_REJECTED'
      );
    }
  }

  /**
   * Update platform index for fast platform-based lookups
   */
  private updatePlatformIndex(adaptor: ModelAdaptor): void {
    adaptor.platforms.forEach(platform => {
      if (!this.platformIndex.has(platform)) {
        this.platformIndex.set(platform, new Set());
      }
      this.platformIndex.get(platform)!.add(adaptor.id);
    });
  }

  /**
   * Remove adaptor from platform index
   */
  private removePlatformIndex(adaptor: ModelAdaptor): void {
    adaptor.platforms.forEach(platform => {
      const adaptorIds = this.platformIndex.get(platform);
      if (adaptorIds) {
        adaptorIds.delete(adaptor.id);
        if (adaptorIds.size === 0) {
          this.platformIndex.delete(platform);
        }
      }
    });
  }

  /**
   * Update capability index for fast capability-based lookups
   */
  private updateCapabilityIndex(adaptor: ModelAdaptor, capabilities: PlatformCapabilities): void {
    capabilities.features.forEach(feature => {
      if (!this.capabilityIndex.has(feature)) {
        this.capabilityIndex.set(feature, new Set());
      }
      this.capabilityIndex.get(feature)!.add(adaptor.id);
    });
  }

  /**
   * Remove adaptor from capability index
   */
  private removeCapabilityIndex(adaptor: ModelAdaptor): void {
    const capabilities = this.capabilitiesCache.get(adaptor.id);
    if (capabilities) {
      capabilities.features.forEach(feature => {
        const adaptorIds = this.capabilityIndex.get(feature);
        if (adaptorIds) {
          adaptorIds.delete(adaptor.id);
          if (adaptorIds.size === 0) {
            this.capabilityIndex.delete(feature);
          }
        }
      });
    }
  }

  /**
   * Setup event handlers for registry management
   */
  private setupEventHandlers(): void {
    this.on('adaptor:registered', (adaptor) => {
      this.logger.log(`✓ Adaptor registered: ${adaptor.id} v${adaptor.version} (platforms: ${adaptor.platforms.join(', ')})`);
    });

    this.on('adaptor:unregistered', (adaptorId) => {
      this.logger.log(`✓ Adaptor unregistered: ${adaptorId}`);
    });

    this.on('adaptor:updated', (adaptor, oldVersion) => {
      this.logger.log(`✓ Adaptor updated: ${adaptor.id} v${oldVersion} → v${adaptor.version}`);
    });

    this.on('capabilities:changed', (adaptorId, capabilities) => {
      this.logger.log(`✓ Capabilities refreshed for: ${adaptorId} (${capabilities.features.length} features)`);
    });
  }

  /**
   * Get registry statistics
   */
  public getStatistics(): {
    totalAdaptors: number;
    platformCount: number;
    capabilityCount: number;
    adaptorsByPlatform: Record<string, number>;
    mostCommonCapabilities: Array<{ capability: string; count: number }>;
  } {
    const adaptorsByPlatform: Record<string, number> = {};
    this.platformIndex.forEach((adaptors, platform) => {
      adaptorsByPlatform[platform] = adaptors.size;
    });

    const capabilityCounts = Array.from(this.capabilityIndex.entries())
      .map(([capability, adaptors]) => ({ capability, count: adaptors.size }))
      .sort((a, b) => b.count - a.count);

    return {
      totalAdaptors: this.adaptors.size,
      platformCount: this.platformIndex.size,
      capabilityCount: this.capabilityIndex.size,
      adaptorsByPlatform,
      mostCommonCapabilities: capabilityCounts.slice(0, 10),
    };
  }
}

/**
 * Advanced base adaptor with enhanced pipeline and lifecycle management
 * Epic 10.2.1 - Enhanced ModelAdaptor Base Class
 */

import {
  ModelAdaptor,
  PlatformCapabilities,
  ValidationResult,
  PlatformPrompt,
  AdaptorConfig,
  TranslationContext,
  AdaptorError,
  ValidationError,
  TranslationError,
} from '../types';
import { BaseAdaptor } from './BaseAdaptor';
import { EventEmitter } from 'events';
import { v4 as uuidv4 } from 'uuid';

/**
 * Pipeline stage result interface
 */
export interface PipelineStageResult<T = unknown> {
  success: boolean;
  data?: T;
  error?: Error;
  metadata?: Record<string, unknown>;
  duration?: number;
}

/**
 * Pipeline stage interface
 */
export interface PipelineStage<TInput = unknown, TOutput = unknown> {
  name: string;
  execute(input: TInput, context: TranslationContext): Promise<PipelineStageResult<TOutput>>;
  shouldSkip?(input: TInput, context: TranslationContext): Promise<boolean>;
  onError?(error: Error, input: TInput, context: TranslationContext): Promise<PipelineStageResult<TOutput>>;
}

/**
 * Enhanced adaptor events
 */
export interface AdvancedAdaptorEvents {
  'pipeline:start': (context: TranslationContext) => void;
  'pipeline:stage': (stage: string, result: PipelineStageResult, context: TranslationContext) => void;
  'pipeline:complete': (result: PlatformPrompt, context: TranslationContext) => void;
  'pipeline:error': (error: Error, context: TranslationContext) => void;
  'validation:start': (graph: any, context: TranslationContext) => void;
  'validation:complete': (result: ValidationResult, context: TranslationContext) => void;
  'optimization:applied': (optimization: string, context: TranslationContext) => void;
}

/**
 * Advanced configuration interface
 */
export interface AdvancedAdaptorConfig extends AdaptorConfig {
  /** Pipeline configuration */
  pipeline?: {
    /** Skip validation stage */
    skipValidation?: boolean;
    /** Skip optimization stage */
    skipOptimization?: boolean;
    /** Custom stage timeouts */
    stageTimeouts?: Record<string, number>;
    /** Retry configuration */
    retries?: {
      maxAttempts?: number;
      backoffMs?: number;
      retryableErrors?: string[];
    };
  };
  /** Performance monitoring */
  monitoring?: {
    /** Enable detailed timing */
    enableTiming?: boolean;
    /** Enable memory tracking */
    enableMemoryTracking?: boolean;
    /** Enable event emission */
    enableEvents?: boolean;
  };
}

/**
 * Enhanced base adaptor with advanced pipeline and lifecycle management
 */
export abstract class AdvancedBaseAdaptor extends BaseAdaptor {
  protected eventEmitter: EventEmitter;
  protected pipeline: PipelineStage[];
  protected stats: {
    translations: number;
    validations: number;
    errors: number;
    totalDuration: number;
    avgDuration: number;
  };

  constructor() {
    super();
    this.eventEmitter = new EventEmitter();
    this.pipeline = [];
    this.stats = {
      translations: 0,
      validations: 0,
      errors: 0,
      totalDuration: 0,
      avgDuration: 0,
    };
    this.initializePipeline();
  }

  /**
   * Enhanced transform with full pipeline execution
   */
  public async transform(graph: any, config?: AdvancedAdaptorConfig): Promise<PlatformPrompt> {
    const context = this.createTranslationContext(graph, config);
    const startTime = Date.now();

    try {
      this.emitEvent('pipeline:start', context);

      // Execute pipeline stages
      let currentData = graph;
      for (const stage of this.pipeline) {
        if (await this.shouldSkipStage(stage, currentData, context)) {
          continue;
        }

        const stageResult = await this.executeStage(stage, currentData, context);

        this.emitEvent('pipeline:stage', stage.name, stageResult, context);

        if (!stageResult.success) {
          throw new TranslationError(
            `Pipeline stage '${stage.name}' failed: ${stageResult.error?.message}`,
            this.platforms[0],
            'PIPELINE_STAGE_FAILED',
            { stage: stage.name, error: stageResult.error }
          );
        }

        currentData = stageResult.data || currentData;
      }

      // Finalize result
      const result = await this.finalizeTranslation(currentData as PlatformPrompt, context);

      // Update statistics
      const duration = Date.now() - startTime;
      this.updateStats(duration, false);

      this.emitEvent('pipeline:complete', result, context);

      return result;
    } catch (error) {
      this.updateStats(Date.now() - startTime, true);
      this.emitEvent('pipeline:error', error as Error, context);
      throw error;
    }
  }

  /**
   * Enhanced validation with detailed reporting
   */
  public async validate(graph: any, config?: AdvancedAdaptorConfig): Promise<ValidationResult> {
    const context = this.createTranslationContext(graph, config);
    const startTime = Date.now();

    try {
      this.emitEvent('validation:start', graph, context);

      // Multi-stage validation
      const validationStages = [
        () => this.validateGraphStructure(graph),
        () => this.validatePlatformConstraints(graph, config),
        () => this.validateContentQuality(graph, config),
        () => this.validatePerformanceImpact(graph, config),
      ];

      const results: ValidationResult[] = [];

      for (const stage of validationStages) {
        try {
          const result = await stage();
          results.push(result);
        } catch (error) {
          results.push({
            valid: false,
            errors: [{
              code: 'VALIDATION_STAGE_ERROR',
              message: `Validation stage failed: ${error instanceof Error ? error.message : 'Unknown error'}`,
              severity: 'error',
            }],
            warnings: [],
            compatibilityScore: 0,
          });
        }
      }

      // Combine validation results
      const finalResult = this.combineValidationResults(...results);

      // Update statistics
      this.stats.validations++;

      this.emitEvent('validation:complete', finalResult, context);

      return finalResult;
    } catch (error) {
      this.stats.errors++;
      throw new ValidationError(
        `Enhanced validation failed: ${error instanceof Error ? error.message : 'Unknown error'}`,
        [],
        'ENHANCED_VALIDATION_FAILED'
      );
    }
  }

  /**
   * Initialize the translation pipeline
   */
  protected initializePipeline(): void {
    this.pipeline = [
      this.createPreprocessingStage(),
      this.createValidationStage(),
      this.createOptimizationStage(),
      this.createTransformationStage(),
      this.createPostprocessingStage(),
    ];
  }

  /**
   * Create preprocessing pipeline stage
   */
  protected createPreprocessingStage(): PipelineStage {
    return {
      name: 'preprocessing',
      execute: async (graph: any, context: TranslationContext) => {
        const startTime = Date.now();
        try {
          const preprocessed = await this.preprocessGraph(graph, context);
          return {
            success: true,
            data: preprocessed,
            duration: Date.now() - startTime,
          };
        } catch (error) {
          return {
            success: false,
            error: error as Error,
            duration: Date.now() - startTime,
          };
        }
      },
    };
  }

  /**
   * Create validation pipeline stage
   */
  protected createValidationStage(): PipelineStage {
    return {
      name: 'validation',
      execute: async (graph: any, context: TranslationContext) => {
        const startTime = Date.now();
        try {
          const validation = await this.performPlatformValidation(graph, context.config);

          if (!validation.valid) {
            return {
              success: false,
              error: new ValidationError('Graph validation failed', validation.errors),
              data: validation,
              duration: Date.now() - startTime,
            };
          }

          return {
            success: true,
            data: { graph, validation },
            duration: Date.now() - startTime,
          };
        } catch (error) {
          return {
            success: false,
            error: error as Error,
            duration: Date.now() - startTime,
          };
        }
      },
      shouldSkip: async (graph: any, context: TranslationContext) => {
        return context.config?.pipeline?.skipValidation === true;
      },
    };
  }

  /**
   * Create optimization pipeline stage
   */
  protected createOptimizationStage(): PipelineStage {
    return {
      name: 'optimization',
      execute: async (data: any, context: TranslationContext) => {
        const startTime = Date.now();
        try {
          const { graph } = data;
          const optimizations = await this.applyOptimizations(graph, context);

          // Emit optimization events
          optimizations.forEach(opt => {
            this.emitEvent('optimization:applied', opt, context);
          });

          return {
            success: true,
            data: { ...data, optimizations },
            duration: Date.now() - startTime,
          };
        } catch (error) {
          return {
            success: false,
            error: error as Error,
            duration: Date.now() - startTime,
          };
        }
      },
      shouldSkip: async (data: any, context: TranslationContext) => {
        return context.config?.pipeline?.skipOptimization === true;
      },
    };
  }

  /**
   * Create transformation pipeline stage
   */
  protected createTransformationStage(): PipelineStage {
    return {
      name: 'transformation',
      execute: async (data: any, context: TranslationContext) => {
        const startTime = Date.now();
        try {
          const { graph } = data;
          const result = await this.performTransformation(graph, context.config);

          return {
            success: true,
            data: result,
            duration: Date.now() - startTime,
          };
        } catch (error) {
          return {
            success: false,
            error: error as Error,
            duration: Date.now() - startTime,
          };
        }
      },
    };
  }

  /**
   * Create postprocessing pipeline stage
   */
  protected createPostprocessingStage(): PipelineStage {
    return {
      name: 'postprocessing',
      execute: async (result: any, context: TranslationContext) => {
        const startTime = Date.now();
        try {
          const postprocessed = await this.postprocessResult(result, context);
          return {
            success: true,
            data: postprocessed,
            duration: Date.now() - startTime,
          };
        } catch (error) {
          return {
            success: false,
            error: error as Error,
            duration: Date.now() - startTime,
          };
        }
      },
    };
  }

  /**
   * Create translation context
   */
  protected createTranslationContext(graph: any, config?: AdvancedAdaptorConfig): TranslationContext {
    return {
      sourceGraph: graph,
      targetPlatform: this.platforms[0],
      config: config || {},
      metadata: {
        startTime: new Date(),
        sessionId: uuidv4(),
        adaptorId: this.id,
        adaptorVersion: this.version,
      },
    };
  }

  /**
   * Execute a pipeline stage with error handling and retries
   */
  protected async executeStage(
    stage: PipelineStage,
    data: any,
    context: TranslationContext
  ): Promise<PipelineStageResult> {
    const maxAttempts = context.config?.pipeline?.retries?.maxAttempts || 1;
    const backoffMs = context.config?.pipeline?.retries?.backoffMs || 100;

    let lastError: Error | undefined;

    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
      try {
        const result = await stage.execute(data, context);

        if (result.success) {
          return result;
        }

        lastError = result.error;

        // Check if error is retryable
        if (attempt < maxAttempts && this.isRetryableError(result.error, context)) {
          await this.delay(backoffMs * attempt);
          continue;
        }

        // Handle error through stage error handler
        if (stage.onError) {
          return await stage.onError(result.error!, data, context);
        }

        return result;
      } catch (error) {
        lastError = error as Error;

        if (attempt < maxAttempts && this.isRetryableError(error as Error, context)) {
          await this.delay(backoffMs * attempt);
          continue;
        }

        throw error;
      }
    }

    throw lastError || new Error(`Stage ${stage.name} failed after ${maxAttempts} attempts`);
  }

  /**
   * Check if stage should be skipped
   */
  protected async shouldSkipStage(
    stage: PipelineStage,
    data: any,
    context: TranslationContext
  ): Promise<boolean> {
    if (stage.shouldSkip) {
      return await stage.shouldSkip(data, context);
    }
    return false;
  }

  /**
   * Check if error is retryable
   */
  protected isRetryableError(error: Error, context: TranslationContext): boolean {
    const retryableErrors = context.config?.pipeline?.retries?.retryableErrors || [
      'NETWORK_ERROR',
      'TIMEOUT_ERROR',
      'RATE_LIMIT_ERROR',
    ];

    return retryableErrors.some(code => error.message.includes(code));
  }

  /**
   * Delay utility for retries
   */
  protected delay(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  /**
   * Finalize translation result with metadata
   */
  protected async finalizeTranslation(
    result: PlatformPrompt,
    context: TranslationContext
  ): Promise<PlatformPrompt> {
    const sourceHash = this.generateGraphHash(context.sourceGraph);
    const optimizations = await this.getAppliedOptimizations(context.sourceGraph, context.config);

    return {
      ...result,
      metadata: {
        sourceHash,
        timestamp: new Date(),
        qualityScore: result.metadata?.qualityScore || 0.8,
        optimizations,
        ...result.metadata,
        pipeline: {
          adaptorId: this.id,
          adaptorVersion: this.version,
          sessionId: context.metadata.sessionId,
          stages: this.pipeline.length,
        },
      },
    };
  }

  /**
   * Advanced graph structure validation
   */
  protected async validateGraphStructure(graph: any): Promise<ValidationResult> {
    const errors: any[] = [];
    const warnings: any[] = [];

    // Deep structure validation
    if (!this.isValidGraphStructure(graph)) {
      errors.push({
        code: 'INVALID_GRAPH_STRUCTURE',
        message: 'Graph structure is invalid or corrupted',
        severity: 'error',
      });
    }

    // Cycle detection
    if (this.hasCycles(graph)) {
      errors.push({
        code: 'GRAPH_HAS_CYCLES',
        message: 'Graph contains cycles which may cause infinite loops',
        severity: 'error',
      });
    }

    // Performance warnings
    if (graph.nodes && graph.nodes.length > 100) {
      warnings.push({
        code: 'LARGE_GRAPH',
        message: 'Graph is very large and may impact performance',
        optimization: 'Consider breaking into smaller subgraphs',
      });
    }

    return {
      valid: errors.length === 0,
      errors,
      warnings,
      compatibilityScore: errors.length === 0 ? 0.9 : 0.3,
    };
  }

  /**
   * Validate platform-specific constraints
   */
  protected async validatePlatformConstraints(
    graph: any,
    config?: AdvancedAdaptorConfig
  ): Promise<ValidationResult> {
    // Delegate to existing platform validation
    return this.performPlatformValidation(graph, config);
  }

  /**
   * Validate content quality and coherence
   */
  protected async validateContentQuality(
    graph: any,
    config?: AdvancedAdaptorConfig
  ): Promise<ValidationResult> {
    const errors: any[] = [];
    const warnings: any[] = [];

    const textContent = this.extractTextContent(graph);

    // Content length validation
    if (textContent.length === 0) {
      warnings.push({
        code: 'EMPTY_CONTENT',
        message: 'Graph produces no text content',
        optimization: 'Add content nodes to generate meaningful output',
      });
    }

    // Content coherence check (basic)
    if (this.hasIncoherentContent(textContent)) {
      warnings.push({
        code: 'INCOHERENT_CONTENT',
        message: 'Content may be incoherent or contradictory',
        optimization: 'Review node connections and content flow',
      });
    }

    return {
      valid: errors.length === 0,
      errors,
      warnings,
      compatibilityScore: 0.8,
    };
  }

  /**
   * Validate performance impact
   */
  protected async validatePerformanceImpact(
    graph: any,
    config?: AdvancedAdaptorConfig
  ): Promise<ValidationResult> {
    const warnings: any[] = [];

    // Estimate processing complexity
    const complexity = this.estimateComplexity(graph);

    if (complexity > 100) {
      warnings.push({
        code: 'HIGH_COMPLEXITY',
        message: 'Graph has high processing complexity',
        optimization: 'Simplify graph structure or use caching',
      });
    }

    return {
      valid: true,
      errors: [],
      warnings,
      compatibilityScore: complexity > 100 ? 0.7 : 0.9,
    };
  }

  /**
   * Preprocess graph before translation
   */
  protected async preprocessGraph(graph: any, context: TranslationContext): Promise<any> {
    // Normalize node structure
    const normalized = this.normalizeGraphStructure(graph);

    // Apply preprocessing optimizations
    const optimized = await this.applyPreprocessingOptimizations(normalized, context);

    return optimized;
  }

  /**
   * Apply optimizations to the graph
   */
  protected async applyOptimizations(graph: any, context: TranslationContext): Promise<string[]> {
    const optimizations: string[] = [];

    // Content optimization
    if (this.canOptimizeContent(graph)) {
      optimizations.push('content-optimization');
    }

    // Structure optimization
    if (this.canOptimizeStructure(graph)) {
      optimizations.push('structure-optimization');
    }

    // Platform-specific optimizations
    const platformOpts = await this.getPlatformOptimizations(graph, context.config);
    optimizations.push(...platformOpts);

    return optimizations;
  }

  /**
   * Postprocess translation result
   */
  protected async postprocessResult(result: any, context: TranslationContext): Promise<any> {
    // Apply post-processing filters
    const filtered = this.applyPostprocessingFilters(result, context);

    // Validate final result
    const isValid = this.validateFinalResult(filtered);
    if (!isValid) {
      throw new TranslationError(
        'Postprocessing validation failed',
        context.targetPlatform,
        'POSTPROCESSING_VALIDATION_FAILED'
      );
    }

    return filtered;
  }

  /**
   * Emit event if monitoring is enabled
   */
  protected emitEvent(event: string, ...args: any[]): void {
    if (this.config.monitoring?.enableEvents !== false) {
      this.eventEmitter.emit(event, ...args);
    }
  }

  /**
   * Update performance statistics
   */
  protected updateStats(duration: number, isError: boolean): void {
    if (isError) {
      this.stats.errors++;
    } else {
      this.stats.translations++;
    }

    this.stats.totalDuration += duration;
    this.stats.avgDuration = this.stats.totalDuration / (this.stats.translations + this.stats.errors);
  }

  /**
   * Get adaptor statistics
   */
  public getStatistics(): typeof this.stats {
    return { ...this.stats };
  }

  /**
   * Add event listener
   */
  public on(event: string, listener: (...args: any[]) => void): void {
    this.eventEmitter.on(event, listener);
  }

  /**
   * Remove event listener
   */
  public off(event: string, listener: (...args: any[]) => void): void {
    this.eventEmitter.off(event, listener);
  }

  // Abstract methods for subclasses to implement
  protected abstract isValidGraphStructure(graph: any): boolean;
  protected abstract hasCycles(graph: any): boolean;
  protected abstract hasIncoherentContent(content: string): boolean;
  protected abstract estimateComplexity(graph: any): number;
  protected abstract normalizeGraphStructure(graph: any): any;
  protected abstract applyPreprocessingOptimizations(graph: any, context: TranslationContext): Promise<any>;
  protected abstract canOptimizeContent(graph: any): boolean;
  protected abstract canOptimizeStructure(graph: any): boolean;
  protected abstract applyPostprocessingFilters(result: any, context: TranslationContext): any;
  protected abstract validateFinalResult(result: any): boolean;
}

/**
 * Base adaptor implementation for platform-specific prompt translation
 * Epic 10.1.2 - Common Interface Definition
 */

import {
  ModelAdaptor,
  PlatformCapabilities,
  ValidationResult,
  PlatformPrompt,
  AdaptorConfig,
  AdaptorError,
  ValidationError,
  TranslationError,
} from '../types';
import { createHash } from 'crypto';
import { v4 as uuidv4 } from 'uuid';

/**
 * Abstract base class for all platform adaptors
 * Provides common functionality and enforces interface compliance
 */
export abstract class BaseAdaptor implements ModelAdaptor {
  public abstract readonly id: string;
  public abstract readonly version: string;
  public abstract readonly name: string;
  public abstract readonly description: string;
  public abstract readonly platforms: string[];

  protected initialized: boolean = false;
  protected config: Record<string, unknown> = {};
  protected logger: Console = console;

  /**
   * Initialize the adaptor with configuration
   */
  public async initialize(config: Record<string, unknown> = {}): Promise<void> {
    try {
      this.config = { ...this.getDefaultConfig(), ...config };
      await this.onInitialize();
      this.initialized = true;
      this.logger.log(`Adaptor ${this.id} v${this.version} initialized successfully`);
    } catch (error) {
      throw new AdaptorError(
        `Failed to initialize adaptor ${this.id}: ${error instanceof Error ? error.message : 'Unknown error'}`,
        this.id,
        'INITIALIZATION_ERROR',
        { config, error }
      );
    }
  }

  /**
   * Clean up adaptor resources
   */
  public async cleanup(): Promise<void> {
    try {
      await this.onCleanup();
      this.initialized = false;
      this.logger.log(`Adaptor ${this.id} cleaned up successfully`);
    } catch (error) {
      this.logger.error(`Error cleaning up adaptor ${this.id}:`, error);
    }
  }

  /**
   * Get platform capabilities
   */
  public abstract capabilities(): Promise<PlatformCapabilities>;

  /**
   * Validate a prompt graph for this platform
   */
  public async validate(graph: any, config?: AdaptorConfig): Promise<ValidationResult> {
    this.ensureInitialized();

    try {
      // Base validation checks
      const baseValidation = await this.performBaseValidation(graph, config);

      // Platform-specific validation
      const platformValidation = await this.performPlatformValidation(graph, config);

      // Combine results
      return this.combineValidationResults(baseValidation, platformValidation);
    } catch (error) {
      throw new ValidationError(
        `Validation failed for adaptor ${this.id}: ${error instanceof Error ? error.message : 'Unknown error'}`,
        [],
        'VALIDATION_FAILED'
      );
    }
  }

  /**
   * Transform a prompt graph to platform-specific format
   */
  public async transform(graph: any, config?: AdaptorConfig): Promise<PlatformPrompt> {
    this.ensureInitialized();

    try {
      // Validate first
      const validation = await this.validate(graph, config);
      if (!validation.valid) {
        throw new ValidationError(
          'Graph validation failed before transformation',
          validation.errors,
          'PRE_TRANSFORM_VALIDATION_FAILED'
        );
      }

      // Perform transformation
      const startTime = Date.now();
      const result = await this.performTransformation(graph, config);
      const transformTime = Date.now() - startTime;

      // Add metadata
      const sourceHash = this.generateGraphHash(graph);
      const platformPrompt: PlatformPrompt = {
        ...result,
        metadata: {
          sourceHash,
          timestamp: new Date(),
          qualityScore: validation.compatibilityScore,
          optimizations: await this.getAppliedOptimizations(graph, config),
          ...result.metadata,
          transformTime,
        },
      };

      this.logger.log(`Transform completed for ${this.id} in ${transformTime}ms`);
      return platformPrompt;
    } catch (error) {
      if (error instanceof ValidationError) {
        throw error;
      }
      throw new TranslationError(
        `Transformation failed for adaptor ${this.id}: ${error instanceof Error ? error.message : 'Unknown error'}`,
        this.platforms[0],
        'TRANSFORMATION_FAILED',
        { graph, config, error }
      );
    }
  }

  /**
   * Get default configuration for this adaptor
   */
  protected getDefaultConfig(): Record<string, unknown> {
    return {
      enableOptimizations: true,
      qualityPreference: 0.7,
      stylePreference: 'default',
    };
  }

  /**
   * Lifecycle hook for initialization
   */
  protected async onInitialize(): Promise<void> {
    // Override in subclasses
  }

  /**
   * Lifecycle hook for cleanup
   */
  protected async onCleanup(): Promise<void> {
    // Override in subclasses
  }

  /**
   * Platform-specific validation implementation
   */
  protected abstract performPlatformValidation(
    graph: any,
    config?: AdaptorConfig
  ): Promise<ValidationResult>;

  /**
   * Platform-specific transformation implementation
   */
  protected abstract performTransformation(
    graph: any,
    config?: AdaptorConfig
  ): Promise<Omit<PlatformPrompt, 'metadata'>>;

  /**
   * Base validation checks common to all platforms
   */
  protected async performBaseValidation(
    graph: any,
    config?: AdaptorConfig
  ): Promise<ValidationResult> {
    const errors: any[] = [];
    const warnings: any[] = [];

    // Check if graph exists and has basic structure
    if (!graph) {
      errors.push({
        code: 'MISSING_GRAPH',
        message: 'No graph provided for validation',
        severity: 'error' as const,
      });
      return { valid: false, errors, warnings, compatibilityScore: 0 };
    }

    // Check for required graph properties
    if (!graph.nodes || !Array.isArray(graph.nodes)) {
      errors.push({
        code: 'INVALID_GRAPH_STRUCTURE',
        message: 'Graph must contain a nodes array',
        severity: 'error' as const,
      });
    }

    if (!graph.edges || !Array.isArray(graph.edges)) {
      errors.push({
        code: 'INVALID_GRAPH_STRUCTURE',
        message: 'Graph must contain an edges array',
        severity: 'error' as const,
      });
    }

    // Check for empty graph
    if (graph.nodes && graph.nodes.length === 0) {
      warnings.push({
        code: 'EMPTY_GRAPH',
        message: 'Graph contains no nodes',
        optimization: 'Add content nodes to generate meaningful output',
      });
    }

    // Calculate base compatibility score
    const errorWeight = 0.5;
    const warningWeight = 0.1;
    const maxScore = 1.0;

    const errorPenalty = errors.length * errorWeight;
    const warningPenalty = warnings.length * warningWeight;
    const compatibilityScore = Math.max(0, maxScore - errorPenalty - warningPenalty);

    return {
      valid: errors.length === 0,
      errors,
      warnings,
      compatibilityScore,
    };
  }

  /**
   * Combine multiple validation results
   */
  protected combineValidationResults(...results: ValidationResult[]): ValidationResult {
    const allErrors = results.flatMap(r => r.errors);
    const allWarnings = results.flatMap(r => r.warnings);
    const avgCompatibilityScore = results.reduce((sum, r) => sum + r.compatibilityScore, 0) / results.length;

    return {
      valid: allErrors.length === 0,
      errors: allErrors,
      warnings: allWarnings,
      compatibilityScore: avgCompatibilityScore,
    };
  }

  /**
   * Generate a hash for the source graph
   */
  protected generateGraphHash(graph: any): string {
    const graphString = JSON.stringify(graph, Object.keys(graph).sort());
    return createHash('sha256').update(graphString).digest('hex').substring(0, 16);
  }

  /**
   * Get list of optimizations applied during transformation
   */
  protected async getAppliedOptimizations(
    graph: any,
    config?: AdaptorConfig
  ): Promise<string[]> {
    const optimizations: string[] = [];

    if (config?.enableOptimizations !== false) {
      optimizations.push('parameter-normalization');

      // Add platform-specific optimizations
      const platformOptimizations = await this.getPlatformOptimizations(graph, config);
      optimizations.push(...platformOptimizations);
    }

    return optimizations;
  }

  /**
   * Get platform-specific optimizations (override in subclasses)
   */
  protected async getPlatformOptimizations(
    graph: any,
    config?: AdaptorConfig
  ): Promise<string[]> {
    return [];
  }

  /**
   * Ensure adaptor is initialized before operations
   */
  protected ensureInitialized(): void {
    if (!this.initialized) {
      throw new AdaptorError(
        `Adaptor ${this.id} must be initialized before use`,
        this.id,
        'NOT_INITIALIZED'
      );
    }
  }

  /**
   * Normalize parameter value to platform range
   */
  protected normalizeParameter(
    value: number,
    sourceRange: [number, number],
    targetRange: [number, number]
  ): number {
    const [sourceMin, sourceMax] = sourceRange;
    const [targetMin, targetMax] = targetRange;

    // Clamp to source range
    const clampedValue = Math.max(sourceMin, Math.min(sourceMax, value));

    // Normalize to 0-1
    const normalized = (clampedValue - sourceMin) / (sourceMax - sourceMin);

    // Scale to target range
    return targetMin + normalized * (targetMax - targetMin);
  }

  /**
   * Extract text content from graph nodes
   */
  protected extractTextContent(graph: any): string {
    if (!graph.nodes || !Array.isArray(graph.nodes)) {
      return '';
    }

    return graph.nodes
      .filter((node: any) => node.data?.text || node.data?.content)
      .map((node: any) => node.data.text || node.data.content)
      .join(' ')
      .trim();
  }

  /**
   * Extract style information from graph
   */
  protected extractStyleInfo(graph: any): Record<string, unknown> {
    const style: Record<string, unknown> = {};

    if (!graph.nodes || !Array.isArray(graph.nodes)) {
      return style;
    }

    // Look for style-related nodes
    graph.nodes.forEach((node: any) => {
      if (node.type === 'style' || node.data?.style) {
        Object.assign(style, node.data.style || {});
      }
    });

    return style;
  }

  /**
   * Create a session ID for tracking
   */
  protected createSessionId(): string {
    return uuidv4();
  }

  /**
   * Log performance metrics
   */
  protected logPerformance(operation: string, startTime: number, metadata?: Record<string, unknown>): void {
    const duration = Date.now() - startTime;
    this.logger.log(`[${this.id}] ${operation} completed in ${duration}ms`, metadata);
  }
}

