/**
 * Configuration preset interface
 */
export interface ConfigurationPreset {
  name: string;
  description: string;
  config: GlobalConfig;
  tags: string[];
  isBuiltIn: boolean;
  created: Date;
  updated: Date;
}

/**
 * Configuration validation result
 */
export interface ConfigValidationResult {
  valid: boolean;
  errors: {
    path: string;
    message: string;
    code: string;
  }[];
  warnings: {
    path: string;
    message: string;
    suggestion: string;
  }[];
}

/**
 * Configuration events
 */
export interface ConfigurationEvents {
  'config:changed': (path: string, newValue: unknown, oldValue: unknown) => void;
  'config:preset:applied': (presetName: string, config: GlobalConfig) => void;
  'config:validated': (result: ConfigValidationResult) => void;
  'config:exported': (format: string, config: GlobalConfig) => void;
  'config:imported': (source: string, config: GlobalConfig) => void;
}

/**
 * Comprehensive configuration manager
 */
export class ConfigurationManager extends EventEmitter {
  private config: GlobalConfig;
  private presets: Map<string, ConfigurationPreset> = new Map();
  private configHistory: Array<{ timestamp: Date; config: GlobalConfig; reason: string }> = [];
  private logger: Console = console;

  constructor(initialConfig?: Partial<GlobalConfig>) {
    super();
    this.config = GlobalConfigSchema.parse(initialConfig || {});
    this.initializeBuiltInPresets();
  }

  /**
   * Get current configuration
   */
  public getConfig(): GlobalConfig {
    return structuredClone(this.config);
  }

  /**
   * Update configuration with validation
   */
  public updateConfig(updates: Partial<GlobalConfig>, reason = 'Manual update'): ConfigValidationResult {
    const oldConfig = structuredClone(this.config);

    try {
      // Merge updates with current config
      const newConfig = this.mergeConfigs(this.config, updates);

      // Validate merged config
      const validationResult = this.validateConfig(newConfig);

      if (validationResult.valid) {
        this.config = newConfig;

        // Add to history
        this.configHistory.push({
          timestamp: new Date(),
          config: structuredClone(newConfig),
          reason,
        });

        // Emit change events
        this.emitConfigChanges(oldConfig, newConfig);

        this.logger.log(`Configuration updated: ${reason}`);
      }

      this.emit('config:validated', validationResult);
      return validationResult;
    } catch (error) {
      const validationResult: ConfigValidationResult = {
        valid: false,
        errors: [{
          path: 'root',
          message: error instanceof Error ? error.message : 'Unknown validation error',
          code: 'VALIDATION_ERROR',
        }],
        warnings: [],
      };

      this.emit('config:validated', validationResult);
      return validationResult;
    }
  }

  /**
   * Set specific configuration value
   */
  public setConfigValue(path: string, value: unknown): ConfigValidationResult {
    const updates = this.createNestedUpdate(path, value);
    return this.updateConfig(updates, `Set ${path} = ${JSON.stringify(value)}`);
  }

  /**
   * Get specific configuration value
   */
  public getConfigValue(path: string): unknown {
    return this.getNestedValue(this.config, path);
  }

  /**
   * Validate configuration
   */
  public validateConfig(config: unknown = this.config): ConfigValidationResult {
    try {
      GlobalConfigSchema.parse(config);

      // Additional business logic validation
      const warnings = this.performBusinessValidation(config as GlobalConfig);

      return {
        valid: true,
        errors: [],
        warnings,
      };
    } catch (error) {
      if (error instanceof z.ZodError) {
        return {
          valid: false,
          errors: error.errors.map(err => ({
            path: err.path.join('.'),
            message: err.message,
            code: err.code,
          })),
          warnings: [],
        };
      }

      return {
        valid: false,
        errors: [{
          path: 'root',
          message: error instanceof Error ? error.message : 'Unknown error',
          code: 'UNKNOWN_ERROR',
        }],
        warnings: [],
      };
    }
  }

  /**
   * Create configuration preset
   */
  public createPreset(
    name: string,
    description: string,
    config: Partial<GlobalConfig> = this.config,
    tags: string[] = []
  ): void {
    const preset: ConfigurationPreset = {
      name,
      description,
      config: GlobalConfigSchema.parse(config),
      tags,
      isBuiltIn: false,
      created: new Date(),
      updated: new Date(),
    };

    this.presets.set(name, preset);
    this.logger.log(`Created configuration preset: ${name}`);
  }

  /**
   * Apply configuration preset
   */
  public applyPreset(name: string): ConfigValidationResult {
    const preset = this.presets.get(name);
    if (!preset) {
      return {
        valid: false,
        errors: [{
          path: 'preset',
          message: `Preset '${name}' not found`,
          code: 'PRESET_NOT_FOUND',
        }],
        warnings: [],
      };
    }

    const result = this.updateConfig(preset.config, `Applied preset: ${name}`);

    if (result.valid) {
      this.emit('config:preset:applied', name, preset.config);
    }

    return result;
  }

  /**
   * List available presets
   */
  public listPresets(tags?: string[]): ConfigurationPreset[] {
    const presets = Array.from(this.presets.values());

    if (tags && tags.length > 0) {
      return presets.filter(preset => 
        tags.some(tag => preset.tags.includes(tag))
      );
    }

    return presets;
  }

  /**
   * Delete preset
   */
  public deletePreset(name: string): boolean {
    const preset = this.presets.get(name);
    if (!preset) {
      return false;
    }

    if (preset.isBuiltIn) {
      throw new Error('Cannot delete built-in presets');
    }

    this.presets.delete(name);
    this.logger.log(`Deleted configuration preset: ${name}`);
    return true;
  }

  /**
   * Export configuration
   */
  public exportConfig(format: 'json' | 'yaml' = 'json'): string {
    const config = this.getConfig();

    let exported: string;
    switch (format) {
      case 'json':
        exported = JSON.stringify(config, null, 2);
        break;
      case 'yaml':
        // Simple YAML export - in production, use a proper YAML library
        exported = this.configToYaml(config);
        break;
      default:
        throw new Error(`Unsupported export format: ${format}`);
    }

    this.emit('config:exported', format, config);
    return exported;
  }

  /**
   * Import configuration
   */
  public importConfig(data: string, format: 'json' | 'yaml' = 'json'): ConfigValidationResult {
    try {
      let imported: unknown;

      switch (format) {
        case 'json':
          imported = JSON.parse(data);
          break;
        case 'yaml':
          // Simple YAML import - in production, use a proper YAML library
          imported = this.yamlToConfig(data);
          break;
        default:
          throw new Error(`Unsupported import format: ${format}`);
      }

      const result = this.updateConfig(imported as Partial<GlobalConfig>, `Imported from ${format}`);

      if (result.valid) {
        this.emit('config:imported', format, this.config);
      }

      return result;
    } catch (error) {
      return {
        valid: false,
        errors: [{
          path: 'import',
          message: `Failed to import ${format}: ${error instanceof Error ? error.message : 'Unknown error'}`,
          code: 'IMPORT_ERROR',
        }],
        warnings: [],
      };
    }
  }

  /**
   * Get configuration history
   */
  public getConfigHistory(limit = 10): Array<{ timestamp: Date; reason: string }> {
    return this.configHistory
      .slice(-limit)
      .map(entry => ({
        timestamp: entry.timestamp,
        reason: entry.reason,
      }));
  }

  /**
   * Reset to default configuration
   */
  public resetToDefaults(): ConfigValidationResult {
    const defaultConfig = GlobalConfigSchema.parse({});
    return this.updateConfig(defaultConfig, 'Reset to defaults');
  }

  /**
   * Get configuration summary for UI
   */
  public getConfigSummary(): {
    platforms: string[];
    qualityLevel: string;
    optimizationsEnabled: boolean;
    presetCount: number;
    lastUpdated: Date | null;
  } {
    const platforms = Object.keys(this.config.platformOverrides).filter(
      platform => Object.keys(this.config.platformOverrides[platform as keyof typeof this.config.platformOverrides] || {}).length > 0
    );

    const qualityLevel = this.config.qualityPreference > 0.8 ? 'High' : 
                        this.config.qualityPreference > 0.5 ? 'Medium' : 'Low';

    const lastEntry = this.configHistory[this.configHistory.length - 1];

    return {
      platforms,
      qualityLevel,
      optimizationsEnabled: this.config.enableOptimizations,
      presetCount: this.presets.size,
      lastUpdated: lastEntry?.timestamp || null,
    };
  }

  /**
   * Initialize built-in presets
   */
  private initializeBuiltInPresets(): void {
    // High Quality Preset
    this.presets.set('high-quality', {
      name: 'High Quality',
      description: 'Optimized for highest quality output with minimal creativity',
      config: GlobalConfigSchema.parse({
