        },
      }),
      tags: ['quality', 'professional', 'precise'],
      isBuiltIn: true,
      created: new Date(),
      updated: new Date(),
    });

    // Creative Preset
    this.presets.set('creative', {
      name: 'Creative',
      description: 'Optimized for creative and artistic output',
      config: GlobalConfigSchema.parse({
        qualityPreference: 0.6,
        stylePreference: 'artistic',
        enableOptimizations: true,
        platformOverrides: {
          openai: { temperature: 0.8, topP: 0.9 },
          midjourney: { defaultQuality: 1, defaultStylize: 250, defaultChaos: 25 },
        },
      }),
      tags: ['creative', 'artistic', 'experimental'],
      isBuiltIn: true,
      created: new Date(),
      updated: new Date(),
    });

    // Fast Processing Preset
    this.presets.set('fast', {
      name: 'Fast Processing',
      description: 'Optimized for speed with basic quality',
      config: GlobalConfigSchema.parse({
        qualityPreference: 0.5,
        stylePreference: 'minimal',
        enableOptimizations: false,
        pipeline: {
          skipOptimization: true,
          stageTimeouts: {
            validation: 1000,
            transformation: 2000,
          },
        },
        platformOverrides: {
          openai: { temperature: 0.7, maxTokens: 1000 },
          midjourney: { defaultQuality: 0.5 },
        },
      }),
      tags: ['fast', 'basic', 'efficient'],
      isBuiltIn: true,
      created: new Date(),
      updated: new Date(),
    });

    this.logger.log('Initialized built-in configuration presets');
  }

  /**
   * Merge configurations deeply
   */
  private mergeConfigs(base: GlobalConfig, updates: Partial<GlobalConfig>): GlobalConfig {
    const merged = structuredClone(base);

    for (const [key, value] of Object.entries(updates)) {
      if (value !== undefined) {
        if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
          (merged as any)[key] = this.mergeObjects((merged as any)[key] || {}, value);
        } else {
          (merged as any)[key] = value;
        }
      }
    }

    return merged;
  }

  /**
   * Merge objects recursively
   */
  private mergeObjects(target: any, source: any): any {
    const result = { ...target };

    for (const [key, value] of Object.entries(source)) {
      if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
        result[key] = this.mergeObjects(result[key] || {}, value);
      } else {
        result[key] = value;
      }
    }

    return result;
  }

  /**
   * Create nested update object from path
   */
  private createNestedUpdate(path: string, value: unknown): any {
    const parts = path.split('.');
    const update: any = {};

    let current = update;
    for (let i = 0; i < parts.length - 1; i++) {
      current[parts[i]] = {};
      current = current[parts[i]];
    }

    current[parts[parts.length - 1]] = value;
    return update;
  }

  /**
   * Get nested value from object
   */
  private getNestedValue(obj: any, path: string): unknown {
    return path.split('.').reduce((current, key) => current?.[key], obj);
  }

  /**
   * Perform business logic validation
   */
  private performBusinessValidation(config: GlobalConfig): ConfigValidationResult['warnings'] {
    const warnings: ConfigValidationResult['warnings'] = [];

    // Check for conflicting settings
    if (config.qualityPreference > 0.8 && config.stylePreference === 'minimal') {
      warnings.push({
        path: 'stylePreference',
        message: 'High quality preference with minimal style may produce unexpected results',
        suggestion: 'Consider using photorealistic or artistic style for high quality',
      });
    }

    // Check OpenAI settings
    const openaiConfig = config.platformOverrides.openai;
    if (openaiConfig?.temperature && openaiConfig.temperature > 1.5 && config.qualityPreference > 0.7) {
      warnings.push({
        path: 'platformOverrides.openai.temperature',
        message: 'High temperature with high quality preference may reduce output consistency',
        suggestion: 'Lower temperature for more consistent high-quality results',
      });
    }

    // Check Midjourney settings
    const midjourneyConfig = config.platformOverrides.midjourney;
    if (midjourneyConfig?.defaultChaos && midjourneyConfig.defaultChaos > 50 && config.qualityPreference > 0.8) {
      warnings.push({
        path: 'platformOverrides.midjourney.defaultChaos',
        message: 'High chaos with high quality preference may produce unpredictable results',
        suggestion: 'Lower chaos value for more predictable high-quality images',
      });
    }

    return warnings;
  }

  /**
   * Emit configuration change events
   */
  private emitConfigChanges(oldConfig: GlobalConfig, newConfig: GlobalConfig): void {
    const changes = this.getConfigChanges(oldConfig, newConfig);

    for (const change of changes) {
      this.emit('config:changed', change.path, change.newValue, change.oldValue);
    }
  }

  /**
   * Get configuration changes between two configs
   */
  private getConfigChanges(oldConfig: any, newConfig: any, path = ''): Array<{
    path: string;
    oldValue: unknown;
    newValue: unknown;
  }> {
    const changes: Array<{ path: string; oldValue: unknown; newValue: unknown }> = [];

    const allKeys = new Set([...Object.keys(oldConfig || {}), ...Object.keys(newConfig || {})]);

    for (const key of allKeys) {
      const currentPath = path ? `${path}.${key}` : key;
      const oldValue = oldConfig?.[key];
      const newValue = newConfig?.[key];

      if (oldValue !== newValue) {
        if (typeof oldValue === 'object' && typeof newValue === 'object' && 
            oldValue !== null && newValue !== null && 
            !Array.isArray(oldValue) && !Array.isArray(newValue)) {
          changes.push(...this.getConfigChanges(oldValue, newValue, currentPath));
        } else {
          changes.push({
            path: currentPath,
            oldValue,
            newValue,
          });
        }
      }
    }

    return changes;
  }

  /**
   * Simple config to YAML conversion
   */
  private configToYaml(config: any, indent = 0): string {
    const spaces = ' '.repeat(indent);
    let yaml = '';

    for (const [key, value] of Object.entries(config)) {
      if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
        yaml += `${spaces}${key}:\n`;
        yaml += this.configToYaml(value, indent + 2);
      } else if (Array.isArray(value)) {
        yaml += `${spaces}${key}:\n`;
        for (const item of value) {
          yaml += `${spaces}  - ${item}\n`;
        }
      } else {
        yaml += `${spaces}${key}: ${value}\n`;
      }
    }

    return yaml;
  }

  /**
   * Simple YAML to config conversion
   */
  private yamlToConfig(yaml: string): any {
    // Very basic YAML parser - in production, use a proper library
    const lines = yaml.split('\n').filter(line => line.trim());
    const config: any = {};

    for (const line of lines) {
      const [key, ...valueParts] = line.split(':');
      if (valueParts.length > 0) {
        const value = valueParts.join(':').trim();
        config[key.trim()] = this.parseYamlValue(value);
      }
    }

    return config;
  }

  /**
   * Parse YAML value to appropriate type
   */
  private parseYamlValue(value: string): any {
    if (value === 'true') return true;
    if (value === 'false') return false;
    if (value === 'null') return null;
    if (/^-?\d+$/.test(value)) return parseInt(value, 10);
    if (/^-?\d*\.\d+$/.test(value)) return parseFloat(value);
    return value;
  }
}

/**
 * Core mapping engine for prompt transformation
 * Epic 10.1.3 - Mapping Strategy Development
 */

import {
  MappingEngine,
  PlatformPrompt,
  AdaptorConfig,
  ValidationResult,
  AdaptorRegistry,
  TranslationError,
  ValidationError,
  TranslationCache,
} from '../types';
import { createHash } from 'crypto';

/**
 * Configuration for the mapping engine
 */
export interface MappingEngineConfig {
  /** Enable caching of translation results */
  enableCaching?: boolean;
  /** Cache TTL in seconds */
  cacheTTL?: number;
  /** Maximum concurrent translations */
  maxConcurrency?: number;
  /** Timeout for individual translations (ms) */
  translationTimeout?: number;
  /** Enable detailed logging */
  enableLogging?: boolean;
}

/**
 * Implementation of the core mapping engine
 */
export class DefaultMappingEngine implements MappingEngine {
  private registry: AdaptorRegistry;
  private cache?: TranslationCache;
  private config: Required<MappingEngineConfig>;
  private logger: Console = console;
  private activeTranslations = new Map<string, Promise<PlatformPrompt>>();

  constructor(
    registry: AdaptorRegistry,
    cache?: TranslationCache,
    config: MappingEngineConfig = {}
  ) {
    this.registry = registry;
    this.cache = cache;
    this.config = {
      enableCaching: true,
      cacheTTL: 3600, // 1 hour
      maxConcurrency: 10,
      translationTimeout: 30000, // 30 seconds
      enableLogging: true,
      ...config,
    };
  }

  /**
   * Execute translation pipeline for a single platform
   */
  public async translate(
    graph: any,
    targetPlatform: string,
    config?: AdaptorConfig
  ): Promise<PlatformPrompt> {
    const startTime = Date.now();

    try {
      // Generate cache key
      const cacheKey = this.generateCacheKey(graph, targetPlatform, config);

      // Check cache first
      if (this.config.enableCaching && this.cache) {
        const cached = await this.cache.get(cacheKey);
        if (cached) {
          this.logPerformance('translate (cached)', startTime, { platform: targetPlatform });
          return cached;
        }
      }

      // Check for existing translation in progress
      if (this.activeTranslations.has(cacheKey)) {
        this.log(`Waiting for in-progress translation: ${targetPlatform}`);
        return await this.activeTranslations.get(cacheKey)!;
      }

      // Start new translation
      const translationPromise = this.executeTranslation(graph, targetPlatform, config);
      this.activeTranslations.set(cacheKey, translationPromise);

      try {
        const result = await translationPromise;

        // Cache the result
        if (this.config.enableCaching && this.cache) {
          await this.cache.set(cacheKey, result, this.config.cacheTTL);
        }

        this.logPerformance('translate', startTime, { 
          platform: targetPlatform,
          qualityScore: result.metadata.qualityScore 
        });

        return result;
      } finally {
        this.activeTranslations.delete(cacheKey);
      }
    } catch (error) {
      this.logError('Translation failed', error, { platform: targetPlatform });
      throw error;
    }
  }

  /**
   * Batch translate to multiple platforms
   */
  public async translateBatch(
    graph: any,
    targetPlatforms: string[],
    config?: AdaptorConfig
  ): Promise<Record<string, PlatformPrompt>> {
    const startTime = Date.now();

    try {
      // Limit concurrency
      const results: Record<string, PlatformPrompt> = {};
      const chunks = this.chunkArray(targetPlatforms, this.config.maxConcurrency);

      for (const chunk of chunks) {
        const promises = chunk.map(async platform => {
          try {
            const result = await this.translate(graph, platform, config);
            return { platform, result, error: null };
          } catch (error) {
            return { platform, result: null, error };
          }
        });

        const chunkResults = await Promise.all(promises);

        for (const { platform, result, error } of chunkResults) {
          if (result) {
            results[platform] = result;
          } else {
            this.logError(`Batch translation failed for ${platform}`, error);
            // Continue with other platforms rather than failing the entire batch
          }
        }
      }

      this.logPerformance('translateBatch', startTime, { 
        platformCount: targetPlatforms.length,
        successCount: Object.keys(results).length 
      });

      return results;
    } catch (error) {
      this.logError('Batch translation failed', error);
      throw error;
    }
  }

  /**
   * Validate translation without executing
   */
  public async validateTranslation(
    graph: any,
    targetPlatform: string,
    config?: AdaptorConfig
  ): Promise<ValidationResult> {
    const startTime = Date.now();

    try {
      // Find adaptor for platform
      const adaptor = this.findBestAdaptor(targetPlatform);
      if (!adaptor) {
        return {
          valid: false,
          errors: [{
            code: 'NO_ADAPTOR_FOUND',
            message: `No adaptor found for platform: ${targetPlatform}`,
            severity: 'error',
          }],
          warnings: [],
          compatibilityScore: 0,
        };
      }

      // Perform validation
      const result = await this.withTimeout(
        adaptor.validate(graph, config),
        this.config.translationTimeout,
        `Validation timeout for ${targetPlatform}`
      );

      this.logPerformance('validateTranslation', startTime, { 
        platform: targetPlatform,
        valid: result.valid,
        compatibilityScore: result.compatibilityScore 
      });

      return result;
    } catch (error) {
      this.logError('Validation failed', error, { platform: targetPlatform });
      throw error;
    }
  }

  /**
   * Execute the actual translation with timeout and error handling
   */
  private async executeTranslation(
    graph: any,
    targetPlatform: string,
    config?: AdaptorConfig
  ): Promise<PlatformPrompt> {
    // Find best adaptor for the platform
    const adaptor = this.findBestAdaptor(targetPlatform);
    if (!adaptor) {
      throw new TranslationError(
        `No adaptor found for platform: ${targetPlatform}`,
        targetPlatform,
        'NO_ADAPTOR_FOUND'
      );
    }

    this.log(`Starting translation to ${targetPlatform} using adaptor ${adaptor.id} v${adaptor.version}`);

    // Execute transformation with timeout
    try {
      const result = await this.withTimeout(
        adaptor.transform(graph, config),
        this.config.translationTimeout,
        `Translation timeout for ${targetPlatform}`
      );

      // Validate result
      this.validateTranslationResult(result, targetPlatform);

      return result;
    } catch (error) {
      if (error instanceof ValidationError) {
        throw error;
      }

      throw new TranslationError(
        `Translation failed for ${targetPlatform}: ${error instanceof Error ? error.message : 'Unknown error'}`,
        targetPlatform,
        'TRANSLATION_EXECUTION_FAILED',
        { adaptorId: adaptor.id, error }
      );
    }
  }

  /**
   * Find the best adaptor for a given platform
   */
  private findBestAdaptor(platform: string) {
    const adaptors = this.registry.findByPlatform(platform);

    if (adaptors.length === 0) {
      return undefined;
    }

    // For now, return the first adaptor
    // TODO: Implement more sophisticated selection logic
    return adaptors[0];
  }

  /**
   * Generate cache key for translation result
   */
  private generateCacheKey(graph: any, platform: string, config?: AdaptorConfig): string {
    const graphString = JSON.stringify(graph, Object.keys(graph).sort());
    const configString = JSON.stringify(config || {}, Object.keys(config || {}).sort());
    const combined = `${graphString}:${platform}:${configString}`;

    return createHash('sha256').update(combined).digest('hex').substring(0, 32);
  }

  /**
   * Validate translation result format
   */
  private validateTranslationResult(result: PlatformPrompt, platform: string): void {
    if (!result.platform) {
      throw new TranslationError(
        'Translation result missing platform identifier',
        platform,
        'INVALID_RESULT_FORMAT'
      );
    }

    if (!result.prompt) {
      throw new TranslationError(
        'Translation result missing prompt text',
        platform,
        'INVALID_RESULT_FORMAT'
      );
    }

    if (!result.metadata) {
      throw new TranslationError(
        'Translation result missing metadata',
        platform,
        'INVALID_RESULT_FORMAT'
      );
    }

    if (!result.metadata.sourceHash) {
      throw new TranslationError(
        'Translation result missing source hash',
        platform,
        'INVALID_RESULT_FORMAT'
      );
    }
  }

  /**
   * Execute a promise with timeout
   */
  private async withTimeout<T>(
    promise: Promise<T>,
    timeoutMs: number,
    timeoutMessage: string
  ): Promise<T> {
    const timeoutPromise = new Promise<never>((_, reject) => {
      setTimeout(() => {
        reject(new Error(timeoutMessage));
      }, timeoutMs);
    });

    return Promise.race([promise, timeoutPromise]);
  }

  /**
   * Split array into chunks of specified size
   */
  private chunkArray<T>(array: T[], chunkSize: number): T[][] {
    const chunks: T[][] = [];
    for (let i = 0; i < array.length; i += chunkSize) {
      chunks.push(array.slice(i, i + chunkSize));
    }
    return chunks;
  }

  /**
   * Log message if logging is enabled
   */
  private log(message: string, metadata?: Record<string, unknown>): void {
    if (this.config.enableLogging) {
      this.logger.log(`[MappingEngine] ${message}`, metadata);
    }
  }

  /**
   * Log error if logging is enabled
   */
  private logError(message: string, error: unknown, metadata?: Record<string, unknown>): void {
    if (this.config.enableLogging) {
      this.logger.error(`[MappingEngine] ${message}`, error, metadata);
    }
  }

  /**
   * Log performance metrics
   */
  private logPerformance(operation: string, startTime: number, metadata?: Record<string, unknown>): void {
    if (this.config.enableLogging) {
      const duration = Date.now() - startTime;
      this.log(`${operation} completed in ${duration}ms`, { duration, ...metadata });
    }
  }

  /**
   * Get engine statistics
   */
  public getStatistics(): {
    activeTranslations: number;
    cacheEnabled: boolean;
    cacheStats?: any;
    configuration: MappingEngineConfig;
  } {
    return {
      activeTranslations: this.activeTranslations.size,
      cacheEnabled: this.config.enableCaching && !!this.cache,
      cacheStats: this.cache ? undefined : undefined, // TODO: Implement cache.stats()
      configuration: this.config,
    };
  }

  /**
   * Update engine configuration
   */
  public updateConfiguration(newConfig: Partial<MappingEngineConfig>): void {
    this.config = { ...this.config, ...newConfig };
    this.log('Configuration updated', newConfig);
  }
}

/**
 * Redis-based translation cache implementation
 * Epic 10.1.5 - Performance Considerations
 */

import { TranslationCache, PlatformPrompt } from '../types';
import { createClient, RedisClientType } from 'redis';

/**
 * Configuration for Redis translation cache
 */
export interface RedisCacheConfig {
  /** Redis connection URL */
  url?: string;
  /** Redis host */
  host?: string;
  /** Redis port */
  port?: number;
  /** Redis password */
  password?: string;
  /** Redis database number */
  database?: number;
  /** Key prefix for cache entries */
  keyPrefix?: string;
  /** Default TTL in seconds */
  defaultTTL?: number;
  /** Enable compression for large values */
  enableCompression?: boolean;
  /** Maximum value size before compression (bytes) */
  compressionThreshold?: number;
}

/**
 * Redis-based implementation of translation cache
 */
export class RedisTranslationCache implements TranslationCache {
  private client: RedisClientType;
  private config: Required<RedisCacheConfig>;
  private connected: boolean = false;
  private stats = {
    hits: 0,
    misses: 0,
    sets: 0,
    deletes: 0,
    errors: 0,
  };
  private logger: Console = console;

  constructor(config: RedisCacheConfig = {}) {
    this.config = {
      url: config.url || process.env.REDIS_URL || 'redis://localhost:6379',
      host: config.host || 'localhost',
      port: config.port || 6379,
      password: config.password || process.env.REDIS_PASSWORD,
      database: config.database || 0,
      keyPrefix: config.keyPrefix || 'prompt-targeting:',
      defaultTTL: config.defaultTTL || 3600,
      enableCompression: config.enableCompression || true,
      compressionThreshold: config.compressionThreshold || 1024,
    };

    this.client = createClient({
      url: this.config.url,
      password: this.config.password,
      database: this.config.database,
    });

    this.setupEventHandlers();
  }

  /**
   * Initialize Redis connection
   */
  public async connect(): Promise<void> {
    try {
      await this.client.connect();
      this.connected = true;
      this.logger.log('Redis translation cache connected');
    } catch (error) {
      this.logger.error('Failed to connect to Redis:', error);
      throw error;
    }
  }

  /**
   * Close Redis connection
   */
  public async disconnect(): Promise<void> {
    try {
      await this.client.disconnect();
      this.connected = false;
      this.logger.log('Redis translation cache disconnected');
    } catch (error) {
      this.logger.error('Error disconnecting from Redis:', error);
    }
  }

  /**
   * Get cached translation result
   */
  public async get(key: string): Promise<PlatformPrompt | null> {
    if (!this.connected) {
      this.stats.misses++;
      return null;
    }

    try {
      const fullKey = this.buildKey(key);
      const value = await this.client.get(fullKey);

      if (value === null) {
        this.stats.misses++;
        return null;
      }

      this.stats.hits++;
      const parsed = await this.deserializeValue(value);
      this.logger.log(`Cache hit for key: ${key}`);
      return parsed;
    } catch (error) {
      this.stats.errors++;
      this.logger.error(`Cache get error for key ${key}:`, error);
      return null;
    }
  }

  /**
   * Cache translation result
   */
  public async set(key: string, value: PlatformPrompt, ttl?: number): Promise<void> {
    if (!this.connected) {
      return;
    }

    try {
      const fullKey = this.buildKey(key);
      const serialized = await this.serializeValue(value);
      const expiration = ttl || this.config.defaultTTL;

      await this.client.setEx(fullKey, expiration, serialized);

      this.stats.sets++;
      this.logger.log(`Cached translation for key: ${key} (TTL: ${expiration}s)`);
    } catch (error) {
      this.stats.errors++;
      this.logger.error(`Cache set error for key ${key}:`, error);
    }
  }

  /**
   * Check if key exists in cache
   */
  public async has(key: string): Promise<boolean> {
    if (!this.connected) {
      return false;
    }

    try {
      const fullKey = this.buildKey(key);
      const exists = await this.client.exists(fullKey);
      return exists === 1;
    } catch (error) {
      this.stats.errors++;
      this.logger.error(`Cache exists check error for key ${key}:`, error);
      return false;
    }
  }

  /**
   * Remove cached translation
   */
  public async delete(key: string): Promise<void> {
    if (!this.connected) {
      return;
    }

    try {
      const fullKey = this.buildKey(key);
      await this.client.del(fullKey);

      this.stats.deletes++;
      this.logger.log(`Deleted cache entry for key: ${key}`);
    } catch (error) {
      this.stats.errors++;
      this.logger.error(`Cache delete error for key ${key}:`, error);
    }
  }

  /**
   * Clear all cached translations
   */
  public async clear(): Promise<void> {
    if (!this.connected) {
      return;
    }

    try {
      const pattern = this.buildKey('*');
      const keys = await this.client.keys(pattern);

      if (keys.length > 0) {
        await this.client.del(keys);
        this.logger.log(`Cleared ${keys.length} cache entries`);
      }
    } catch (error) {
      this.stats.errors++;
      this.logger.error('Cache clear error:', error);
    }
  }

  /**
   * Get cache statistics
   */
  public async stats(): Promise<{
    hits: number;
    misses: number;
    size: number;
    hitRate: number;
  }> {
    let size = 0;

    if (this.connected) {
      try {
        const pattern = this.buildKey('*');
        const keys = await this.client.keys(pattern);
        size = keys.length;
      } catch (error) {
        this.logger.error('Error getting cache size:', error);
      }
    }

    const totalRequests = this.stats.hits + this.stats.misses;
    const hitRate = totalRequests > 0 ? this.stats.hits / totalRequests : 0;

    return {
      hits: this.stats.hits,
      misses: this.stats.misses,
      size,
      hitRate,
    };
  }

  /**
   * Get detailed cache statistics
   */
  public async getDetailedStats(): Promise<{
    hits: number;
    misses: number;
    sets: number;
    deletes: number;
    errors: number;
    size: number;
    hitRate: number;
    connected: boolean;
    memoryUsage?: number;
    keyspaceHits?: number;
    keyspaceMisses?: number;
  }> {
    const basicStats = await this.stats();
    let redisInfo = {};

    if (this.connected) {
      try {
        const info = await this.client.info('memory');
        const keyspaceInfo = await this.client.info('keyspace');

        // Parse memory usage
        const memoryMatch = info.match(/used_memory:(\d+)/);
        const memoryUsage = memoryMatch ? parseInt(memoryMatch[1]) : undefined;

        // Parse keyspace stats
        const hitsMatch = keyspaceInfo.match(/keyspace_hits:(\d+)/);
        const missesMatch = keyspaceInfo.match(/keyspace_misses:(\d+)/);

        redisInfo = {
          memoryUsage,
          keyspaceHits: hitsMatch ? parseInt(hitsMatch[1]) : undefined,
          keyspaceMisses: missesMatch ? parseInt(missesMatch[1]) : undefined,
        };
      } catch (error) {
        this.logger.error('Error getting Redis info:', error);
      }
    }

    return {
      ...basicStats,
      sets: this.stats.sets,
      deletes: this.stats.deletes,
      errors: this.stats.errors,
      connected: this.connected,
      ...redisInfo,
    };
  }

  /**
   * Set cache expiration for a key
   */
  public async expire(key: string, ttl: number): Promise<void> {
    if (!this.connected) {
      return;
    }

    try {
      const fullKey = this.buildKey(key);
      await this.client.expire(fullKey, ttl);
    } catch (error) {
      this.stats.errors++;
      this.logger.error(`Cache expire error for key ${key}:`, error);
    }
  }

  /**
   * Get time to live for a key
   */
  public async ttl(key: string): Promise<number> {
    if (!this.connected) {
      return -1;
    }

    try {
      const fullKey = this.buildKey(key);
      return await this.client.ttl(fullKey);
    } catch (error) {
      this.stats.errors++;
      this.logger.error(`Cache TTL error for key ${key}:`, error);
      return -1;
    }
  }

  /**
   * Build full Redis key with prefix
   */
  private buildKey(key: string): string {
    return `${this.config.keyPrefix}${key}`;
  }

  /**
   * Serialize value for storage
   */
  private async serializeValue(value: PlatformPrompt): Promise<string> {
    const json = JSON.stringify(value);

    // Apply compression if enabled and value is large enough
    if (this.config.enableCompression && json.length > this.config.compressionThreshold) {
      // For now, just return JSON - compression can be added later
      // TODO: Implement compression using zlib
      return json;
    }

    return json;
  }

  /**
   * Deserialize value from storage
   */
  private async deserializeValue(value: string): Promise<PlatformPrompt> {
    // For now, just parse JSON - decompression can be added later
    // TODO: Implement decompression using zlib
    return JSON.parse(value);
  }

  /**
   * Setup Redis event handlers
   */
  private setupEventHandlers(): void {
    this.client.on('error', (error) => {
      this.logger.error('Redis client error:', error);
      this.connected = false;
    });

    this.client.on('connect', () => {
      this.logger.log('Redis client connected');
      this.connected = true;
    });

    this.client.on('disconnect', () => {
      this.logger.log('Redis client disconnected');
      this.connected = false;
    });

    this.client.on('reconnecting', () => {
      this.logger.log('Redis client reconnecting');
    });
  }

  /**
   * Health check for cache
   */
  public async healthCheck(): Promise<{
    healthy: boolean;
    connected: boolean;
    latency?: number;
    error?: string;
  }> {
    if (!this.connected) {
      return {
        healthy: false,
        connected: false,
        error: 'Not connected to Redis',
      };
    }

    try {
      const start = Date.now();
      await this.client.ping();
      const latency = Date.now() - start;

      return {
        healthy: true,
        connected: true,
        latency,
      };
    } catch (error) {
      return {
        healthy: false,
        connected: false,
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }
}

/**
 * Factory functions for creating prompt targeting system components
 * Epic 10.1.2 - Common Interface Definition
 */

import {
  AdaptorRegistry,
  MappingEngine,
  TranslationCache,
} from './types';
import { DefaultAdaptorRegistry } from './adaptors/AdaptorRegistry';
import { DefaultMappingEngine, MappingEngineConfig } from './engines/MappingEngine';
import { RedisTranslationCache, RedisCacheConfig } from './engines/RedisTranslationCache';

/**
 * Configuration for the prompt targeting system
 */
export interface PromptTargetingSystemConfig {
  /** Cache configuration */
  cache?: {
    enabled?: boolean;
    type?: 'redis' | 'memory';
    config?: RedisCacheConfig;
  };
  /** Mapping engine configuration */
  mapping?: MappingEngineConfig;
  /** Enable detailed logging */
  enableLogging?: boolean;
}

/**
 * Complete prompt targeting system
 */
export interface PromptTargetingSystem {
  registry: AdaptorRegistry;
  engine: MappingEngine;
  cache?: TranslationCache;
}

/**
 * Create a complete prompt targeting system with all components
 */
export async function createPromptTargetingSystem(
  config: PromptTargetingSystemConfig = {}
): Promise<PromptTargetingSystem> {
  const logger = console;

  // Create registry
  const registry = new DefaultAdaptorRegistry();

  // Create cache if enabled
  let cache: TranslationCache | undefined;
  if (config.cache?.enabled !== false) {
    if (config.cache?.type === 'redis' || !config.cache?.type) {
      cache = new RedisTranslationCache(config.cache?.config);

      // Connect to Redis
      try {
        await (cache as RedisTranslationCache).connect();
        if (config.enableLogging) {
          logger.log('✓ Redis cache connected');
        }
      } catch (error) {
        if (config.enableLogging) {
          logger.warn('Failed to connect to Redis cache, proceeding without cache:', error);
        }
        cache = undefined;
      }
    }
    // TODO: Add memory cache implementation
  }

  // Create mapping engine
  const engine = new DefaultMappingEngine(registry, cache, {
    enableLogging: config.enableLogging,
    ...config.mapping,
  });

  if (config.enableLogging) {
    logger.log('✓ Prompt targeting system created');
    logger.log(`  Registry: ${registry.constructor.name}`);
    logger.log(`  Engine: ${engine.constructor.name}`);
    logger.log(`  Cache: ${cache ? cache.constructor.name : 'disabled'}`);
  }

  return {
    registry,
    engine,
    cache,
  };
}

/**
 * Create a basic prompt targeting system for development/testing
 */
export function createBasicPromptTargetingSystem(): PromptTargetingSystem {
  const registry = new DefaultAdaptorRegistry();
  const engine = new DefaultMappingEngine(registry, undefined, {
    enableCaching: false,
    enableLogging: true,
  });

  return {
    registry,
    engine,
  };
}

/**
 * Create a production-ready prompt targeting system
 */
export async function createProductionPromptTargetingSystem(
  redisConfig?: RedisCacheConfig,
  mappingConfig?: MappingEngineConfig
): Promise<PromptTargetingSystem> {
  return createPromptTargetingSystem({
    cache: {
      enabled: true,
      type: 'redis',
      config: redisConfig,
    },
    mapping: {
      enableCaching: true,
      maxConcurrency: 20,
      translationTimeout: 30000,
      enableLogging: true,
      ...mappingConfig,
    },
    enableLogging: true,
  });
}

/**
 * Comprehensive testing framework for adaptors
 * Epic 10.2.1 - Testing Framework for Adaptors
 */

import {
  ModelAdaptor,
  PlatformCapabilities,
  ValidationResult,
  PlatformPrompt,
  AdaptorConfig,
} from '../types';

/**
 * Test case interface
 */
export interface AdaptorTestCase {
  name: string;
  description: string;
  graph: any;
  config?: AdaptorConfig;
  expectedValid?: boolean;
  expectedErrors?: string[];
  expectedWarnings?: string[];
  minCompatibilityScore?: number;
  shouldTranslate?: boolean;
  expectedPromptContains?: string[];
  expectedParameters?: Record<string, unknown>;
  timeout?: number;
}

/**
 * Test suite configuration
 */
export interface TestSuiteConfig {
  /** Name of the test suite */
  name: string;
  /** Adaptor to test */
  adaptor: ModelAdaptor;
  /** Test cases to run */
  testCases: AdaptorTestCase[];
  /** Global timeout in ms */
  timeout?: number;
  /** Skip initialization */
  skipInitialization?: boolean;
  /** Custom setup function */
  setup?: () => Promise<void>;
  /** Custom teardown function */
  teardown?: () => Promise<void>;
}

/**
 * Test result interface
 */
export interface TestResult {
  testCase: string;
  passed: boolean;
  duration: number;
  error?: Error;
  details: {
    validation?: ValidationResult;
    translation?: PlatformPrompt;
    capabilities?: PlatformCapabilities;
  };
  assertions: {
    name: string;
    passed: boolean;
    expected: unknown;
    actual: unknown;
    message?: string;
  }[];
}

/**
 * Test suite results
 */
export interface TestSuiteResult {
  suiteName: string;
  totalTests: number;
  passedTests: number;
  failedTests: number;
  duration: number;
  results: TestResult[];
  summary: {
    validationTests: number;
    translationTests: number;
    capabilityTests: number;
    performanceTests: number;
  };
}

/**
 * Comprehensive testing framework for adaptors
 */
export class AdaptorTestFramework {
  private logger: Console = console;

  /**
   * Run a complete test suite for an adaptor
   */
  public async runTestSuite(config: TestSuiteConfig): Promise<TestSuiteResult> {
    const startTime = Date.now();
    const results: TestResult[] = [];

    this.logger.log(`\n🧪 Running test suite: ${config.name}`);
    this.logger.log(`   Adaptor: ${config.adaptor.name} v${config.adaptor.version}`);
    this.logger.log(`   Test cases: ${config.testCases.length}`);

    try {
      // Setup
      if (config.setup) {
        await config.setup();
      }

      // Initialize adaptor if needed
      if (!config.skipInitialization) {
        await config.adaptor.initialize?.();
      }

      // Run test cases
      for (let i = 0; i < config.testCases.length; i++) {
        const testCase = config.testCases[i];
        this.logger.log(`\n   [${i + 1}/${config.testCases.length}] ${testCase.name}`);

        const result = await this.runTestCase(config.adaptor, testCase);
        results.push(result);

        if (result.passed) {
          this.logger.log(`     ✅ PASSED (${result.duration}ms)`);
        } else {
          this.logger.log(`     ❌ FAILED (${result.duration}ms): ${result.error?.message}`);
        }
      }

      // Teardown
      if (config.teardown) {
        await config.teardown();
      }

      // Cleanup adaptor
      if (!config.skipInitialization) {
        await config.adaptor.cleanup?.();
      }

    } catch (error) {
      this.logger.error('Test suite setup/teardown failed:', error);
    }

    // Calculate summary
    const passedTests = results.filter(r => r.passed).length;
    const failedTests = results.length - passedTests;
    const duration = Date.now() - startTime;

    const summary = {
      validationTests: results.filter(r => r.details.validation).length,
      translationTests: results.filter(r => r.details.translation).length,
      capabilityTests: results.filter(r => r.details.capabilities).length,
      performanceTests: results.filter(r => r.duration > 1000).length,
    };

    const suiteResult: TestSuiteResult = {
      suiteName: config.name,
      totalTests: results.length,
      passedTests,
      failedTests,
      duration,
      results,
      summary,
    };

    this.printSummary(suiteResult);
    return suiteResult;
  }

  /**
   * Run a single test case
   */
  public async runTestCase(adaptor: ModelAdaptor, testCase: AdaptorTestCase): Promise<TestResult> {
    const startTime = Date.now();
    const assertions: TestResult['assertions'] = [];
    let error: Error | undefined;
    const details: TestResult['details'] = {};

    try {
      // Test validation if expected
      if (testCase.expectedValid !== undefined || testCase.expectedErrors || testCase.expectedWarnings) {
        const validation = await adaptor.validate(testCase.graph, testCase.config);
        details.validation = validation;

        // Assert validation result
        if (testCase.expectedValid !== undefined) {
          this.assert(
            assertions,
            'validation.valid',
            validation.valid,
            testCase.expectedValid,
            `Expected validation to be ${testCase.expectedValid}`
          );
        }

        // Assert expected errors
        if (testCase.expectedErrors) {
          for (const expectedError of testCase.expectedErrors) {
            const hasError = validation.errors.some(e => e.code === expectedError);
            this.assert(
              assertions,
              `validation.errors.${expectedError}`,
              hasError,
              true,
              `Expected error code '${expectedError}'`
            );
          }
        }

        // Assert expected warnings
        if (testCase.expectedWarnings) {
          for (const expectedWarning of testCase.expectedWarnings) {
            const hasWarning = validation.warnings.some(w => w.code === expectedWarning);
            this.assert(
              assertions,
              `validation.warnings.${expectedWarning}`,
              hasWarning,
              true,
              `Expected warning code '${expectedWarning}'`
            );
          }
        }

        // Assert minimum compatibility score
        if (testCase.minCompatibilityScore !== undefined) {
          this.assert(
            assertions,
            'validation.compatibilityScore',
            validation.compatibilityScore >= testCase.minCompatibilityScore,
            true,
            `Expected compatibility score >= ${testCase.minCompatibilityScore}, got ${validation.compatibilityScore}`
          );
        }
      }

      // Test translation if expected
      if (testCase.shouldTranslate || testCase.expectedPromptContains || testCase.expectedParameters) {
        const translation = await adaptor.transform(testCase.graph, testCase.config);
        details.translation = translation;

        // Assert prompt contains expected strings
        if (testCase.expectedPromptContains) {
          for (const expectedString of testCase.expectedPromptContains) {
            const contains = translation.prompt.includes(expectedString);
            this.assert(
              assertions,
              `translation.prompt.contains.${expectedString}`,
              contains,
              true,
              `Expected prompt to contain '${expectedString}'`
            );
          }
        }

        // Assert expected parameters
        if (testCase.expectedParameters) {
          for (const [key, expectedValue] of Object.entries(testCase.expectedParameters)) {
            const actualValue = translation.parameters[key];
            this.assert(
              assertions,
              `translation.parameters.${key}`,
              actualValue,
              expectedValue,
              `Expected parameter '${key}' to be ${expectedValue}, got ${actualValue}`
            );
          }
        }

        // Assert basic translation properties
        this.assert(
          assertions,
          'translation.platform',
          translation.platform,
          adaptor.platforms[0],
          `Expected platform to be ${adaptor.platforms[0]}`
        );

        this.assert(
          assertions,
          'translation.metadata.sourceHash',
          !!translation.metadata.sourceHash,
          true,
          'Expected translation to have source hash'
        );
      }

      // Test capabilities
      const capabilities = await adaptor.capabilities();
      details.capabilities = capabilities;

      // Assert basic capabilities
      this.assert(
        assertions,
        'capabilities.platform',
        !!capabilities.platform,
        true,
        'Expected capabilities to have platform'
      );

      this.assert(
        assertions,
        'capabilities.features',
        Array.isArray(capabilities.features) && capabilities.features.length > 0,
        true,
        'Expected capabilities to have features array'
      );

    } catch (err) {
      error = err as Error;
    }

    const duration = Date.now() - startTime;
    const passed = !error && assertions.every(a => a.passed);

    return {
      testCase: testCase.name,
      passed,
      duration,
      error,
      details,
      assertions,
    };
  }

