  /**
   * Assert a condition and record the result
   */
  private assert(
    assertions: TestResult['assertions'],
    name: string,
    actual: unknown,
    expected: unknown,
    message?: string
  ): void {
    const passed = this.deepEqual(actual, expected);
    assertions.push({
      name,
      passed,
      actual,
      expected,
      message,
    });
  }

  /**
   * Deep equality check
   */
  private deepEqual(a: unknown, b: unknown): boolean {
    if (a === b) return true;
    if (a == null || b == null) return a === b;
    if (typeof a !== typeof b) return false;

    if (typeof a === 'object') {
      const aKeys = Object.keys(a as object);
      const bKeys = Object.keys(b as object);

      if (aKeys.length !== bKeys.length) return false;

      for (const key of aKeys) {
        if (!bKeys.includes(key)) return false;
        if (!this.deepEqual((a as any)[key], (b as any)[key])) return false;
      }

      return true;
    }

    return false;
  }

  /**
   * Print test suite summary
   */
  private printSummary(result: TestSuiteResult): void {
    this.logger.log(`\n📊 Test Suite Results: ${result.suiteName}`);
    this.logger.log(`   Total Tests: ${result.totalTests}`);
    this.logger.log(`   ✅ Passed: ${result.passedTests}`);
    this.logger.log(`   ❌ Failed: ${result.failedTests}`);
    this.logger.log(`   ⏱️  Duration: ${result.duration}ms`);
    this.logger.log(`   📈 Success Rate: ${((result.passedTests / result.totalTests) * 100).toFixed(1)}%`);

    this.logger.log(`\n📋 Test Breakdown:`);
    this.logger.log(`   Validation Tests: ${result.summary.validationTests}`);
    this.logger.log(`   Translation Tests: ${result.summary.translationTests}`);
    this.logger.log(`   Capability Tests: ${result.summary.capabilityTests}`);
    this.logger.log(`   Performance Tests: ${result.summary.performanceTests}`);

    if (result.failedTests > 0) {
      this.logger.log(`\n❌ Failed Tests:`);
      result.results
        .filter(r => !r.passed)
        .forEach(r => {
          this.logger.log(`   • ${r.testCase}: ${r.error?.message || 'Assertion failed'}`);

          // Show failed assertions
          const failedAssertions = r.assertions.filter(a => !a.passed);
          if (failedAssertions.length > 0) {
            failedAssertions.forEach(a => {
              this.logger.log(`     - ${a.name}: expected ${a.expected}, got ${a.actual}`);
            });
          }
        });
    }
  }

  /**
   * Generate performance report
   */
  public generatePerformanceReport(results: TestSuiteResult[]): {
    averageDuration: number;
    slowestTest: string;
    fastestTest: string;
    performanceScore: number;
  } {
    const allResults = results.flatMap(suite => suite.results);
    const durations = allResults.map(r => r.duration);

    const averageDuration = durations.reduce((sum, d) => sum + d, 0) / durations.length;
    const slowestResult = allResults.reduce((slowest, current) => 
      current.duration > slowest.duration ? current : slowest
    );
    const fastestResult = allResults.reduce((fastest, current) => 
      current.duration < fastest.duration ? current : fastest
    );

    // Performance score: higher is better, based on speed and consistency
    const maxDuration = Math.max(...durations);
    const performanceScore = Math.max(0, 100 - (averageDuration / 10) - (maxDuration / 100));

    return {
      averageDuration,
      slowestTest: slowestResult.testCase,
      fastestTest: fastestResult.testCase,
      performanceScore,
    };
  }
}

/**
 * Core types and interfaces for the Prompt Targeting System
 * Epic 10 - Cross-platform prompt translation
 */

import { z } from 'zod';

// Re-export PromptGraph type from core package
export type { PromptGraph } from '../../../core/types';

/**
 * Platform-specific capabilities and constraints
 */
export interface PlatformCapabilities {
  /** Unique platform identifier */
  platform: string;
  /** Platform version */
  version: string;
  /** Maximum input tokens/characters */
  maxTokens?: number;
  /** Supported aspect ratios for image generation */
  supportedAspectRatios?: string[];
  /** Parameter ranges for platform-specific settings */
  parameterRanges: Record<string, [number, number]>;
  /** Available features */
  features: string[];
  /** Style customization support */
  styleSupport: boolean;
  /** Negative prompt support (for image generation) */
  negativePromptSupport: boolean;
  /** Custom parameter support */
  customParameters?: Record<string, unknown>;
}

/**
 * Validation result for prompt translation
 */
export interface ValidationResult {
  /** Validation success status */
  valid: boolean;
  /** Validation errors */
  errors: ValidationError[];
  /** Validation warnings */
  warnings: ValidationWarning[];
  /** Overall compatibility score (0-1) */
  compatibilityScore: number;
}

/**
 * Validation error details
 */
export interface ValidationError {
  /** Error code */
  code: string;
  /** Human-readable error message */
  message: string;
  /** Severity level */
  severity: 'error' | 'warning' | 'info';
  /** Source location in the graph */
  source?: {
    nodeId?: string;
    property?: string;
  };
  /** Suggested fix */
  suggestion?: string;
}

/**
 * Validation warning details
 */
export interface ValidationWarning {
  /** Warning code */
  code: string;
  /** Human-readable warning message */
  message: string;
  /** Source location */
  source?: {
    nodeId?: string;
    property?: string;
  };
  /** Optimization suggestion */
  optimization?: string;
}

/**
 * Platform-specific prompt representation
 */
export interface PlatformPrompt {
  /** Target platform identifier */
  platform: string;
  /** Generated prompt text */
  prompt: string;
  /** Negative prompt (for image generation) */
  negativePrompt?: string;
  /** Platform-specific parameters */
  parameters: Record<string, unknown>;
  /** Metadata about the translation */
  metadata: {
    /** Source graph hash */
    sourceHash: string;
    /** Translation timestamp */
    timestamp: Date;
    /** Translation quality score */
    qualityScore: number;
    /** Applied optimizations */
    optimizations: string[];
  };
}

/**
 * Adaptor configuration options
 */
export interface AdaptorConfig {
  /** Quality preference (0-1, higher = more quality-focused) */
  qualityPreference?: number;
  /** Style preference */
  stylePreference?: 'default' | 'artistic' | 'photorealistic' | 'minimal';
  /** Platform-specific overrides */
  platformOverrides?: Record<string, unknown>;
  /** Enable optimizations */
  enableOptimizations?: boolean;
  /** Custom parameter mappings */
  customMappings?: Record<string, unknown>;
}

/**
 * Translation context for maintaining state
 */
export interface TranslationContext {
  /** Source graph being translated */
  sourceGraph: any; // PromptGraph from core
  /** Target platform */
  targetPlatform: string;
  /** Translation configuration */
  config: AdaptorConfig;
  /** Previous translation results (for caching) */
  cache?: Map<string, PlatformPrompt>;
  /** Execution metadata */
  metadata: {
    startTime: Date;
    userId?: string;
    sessionId?: string;
  };
}

/**
 * Base interface for all platform adaptors
 */
export interface ModelAdaptor {
  /** Unique adaptor identifier */
  readonly id: string;
  /** Adaptor version (semver) */
  readonly version: string;
  /** Human-readable name */
  readonly name: string;
  /** Description of the adaptor */
  readonly description: string;
  /** Supported platform(s) */
  readonly platforms: string[];

  /**
   * Get platform capabilities
   */
  capabilities(): Promise<PlatformCapabilities>;

  /**
   * Validate a prompt graph for this platform
   */
  validate(graph: any, config?: AdaptorConfig): Promise<ValidationResult>;

  /**
   * Transform a prompt graph to platform-specific format
   */
  transform(graph: any, config?: AdaptorConfig): Promise<PlatformPrompt>;

  /**
   * Initialize the adaptor (load models, connect to APIs, etc.)
   */
  initialize?(config?: Record<string, unknown>): Promise<void>;

  /**
   * Clean up resources
   */
  cleanup?(): Promise<void>;
}

/**
 * Text-to-text specific adaptor interface
 */
export interface TextToTextAdaptor extends ModelAdaptor {
  /** Text generation specific capabilities */
  textCapabilities(): Promise<{
    maxContextLength: number;
    supportsChatFormat: boolean;
    supportsSystemMessages: boolean;
    supportsFunctionCalling: boolean;
    temperatureRange: [number, number];
    topPRange: [number, number];
  }>;
}

/**
 * Text-to-image specific adaptor interface
 */
export interface TextToImageAdaptor extends ModelAdaptor {
  /** Image generation specific capabilities */
  imageCapabilities(): Promise<{
    maxPromptLength: number;
    supportedDimensions: string[];
    supportedFormats: string[];
    supportsNegativePrompts: boolean;
    supportsStyleTransfer: boolean;
    qualityRange: [number, number];
    guidanceRange: [number, number];
  }>;

  /**
   * Generate preview image (low resolution/quality)
   */
  generatePreview?(prompt: PlatformPrompt): Promise<{
    url: string;
    width: number;
    height: number;
    metadata: Record<string, unknown>;
  }>;
}

/**
 * Adaptor registry for discovery and management
 */
export interface AdaptorRegistry {
  /**
   * Register an adaptor
   */
  register(adaptor: ModelAdaptor): Promise<void>;

  /**
   * Unregister an adaptor
   */
  unregister(adaptorId: string): Promise<void>;

  /**
   * Get adaptor by ID
   */
  get(adaptorId: string): ModelAdaptor | undefined;

  /**
   * List all registered adaptors
   */
  list(): ModelAdaptor[];

  /**
   * Find adaptors by platform
   */
  findByPlatform(platform: string): ModelAdaptor[];

  /**
   * Find adaptors by capability
   */
  findByCapability(capability: string): ModelAdaptor[];
}

/**
 * Mapping engine for core translation logic
 */
export interface MappingEngine {
  /**
   * Execute translation pipeline
   */
  translate(
    graph: any,
    targetPlatform: string,
    config?: AdaptorConfig
  ): Promise<PlatformPrompt>;

  /**
   * Batch translate to multiple platforms
   */
  translateBatch(
    graph: any,
    targetPlatforms: string[],
    config?: AdaptorConfig
  ): Promise<Record<string, PlatformPrompt>>;

  /**
   * Validate translation without executing
   */
  validateTranslation(
    graph: any,
    targetPlatform: string,
    config?: AdaptorConfig
  ): Promise<ValidationResult>;
}

/**
 * Cache interface for translation results
 */
export interface TranslationCache {
  /**
   * Get cached translation result
   */
  get(key: string): Promise<PlatformPrompt | null>;

  /**
   * Cache translation result
   */
  set(key: string, value: PlatformPrompt, ttl?: number): Promise<void>;

  /**
   * Check if key exists in cache
   */
  has(key: string): Promise<boolean>;

  /**
   * Remove cached translation
   */
  delete(key: string): Promise<void>;

  /**
   * Clear all cached translations
   */
  clear(): Promise<void>;

  /**
   * Get cache statistics
   */
  stats(): Promise<{
    hits: number;
    misses: number;
    size: number;
    hitRate: number;
  }>;
}

/**
 * Zod schemas for runtime validation
 */
export const PlatformCapabilitiesSchema = z.object({
  platform: z.string(),
  version: z.string(),
  maxTokens: z.number().optional(),
  supportedAspectRatios: z.array(z.string()).optional(),
  parameterRanges: z.record(z.tuple([z.number(), z.number()])),
  features: z.array(z.string()),
  styleSupport: z.boolean(),
  negativePromptSupport: z.boolean(),
  customParameters: z.record(z.unknown()).optional(),
});

export const ValidationResultSchema = z.object({
  valid: z.boolean(),
  errors: z.array(z.object({
    code: z.string(),
    message: z.string(),
    severity: z.enum(['error', 'warning', 'info']),
    source: z.object({
      nodeId: z.string().optional(),
      property: z.string().optional(),
    }).optional(),
    suggestion: z.string().optional(),
  })),
  warnings: z.array(z.object({
    code: z.string(),
    message: z.string(),
    source: z.object({
      nodeId: z.string().optional(),
      property: z.string().optional(),
    }).optional(),
    optimization: z.string().optional(),
  })),
  compatibilityScore: z.number().min(0).max(1),
});

export const PlatformPromptSchema = z.object({
  platform: z.string(),
  prompt: z.string(),
  negativePrompt: z.string().optional(),
  parameters: z.record(z.unknown()),
  metadata: z.object({
    sourceHash: z.string(),
    timestamp: z.date(),
    qualityScore: z.number().min(0).max(1),
    optimizations: z.array(z.string()),
  }),
});

export const AdaptorConfigSchema = z.object({
  qualityPreference: z.number().min(0).max(1).optional(),
  stylePreference: z.enum(['default', 'artistic', 'photorealistic', 'minimal']).optional(),
  platformOverrides: z.record(z.unknown()).optional(),
  enableOptimizations: z.boolean().optional(),
  customMappings: z.record(z.unknown()).optional(),
});

/**
 * Error classes for prompt targeting system
 */
export class PromptTargetingError extends Error {
  constructor(
    message: string,
    public code: string,
    public platform?: string,
    public details?: Record<string, unknown>
  ) {
    super(message);
    this.name = 'PromptTargetingError';
  }
}

export class AdaptorError extends PromptTargetingError {
  constructor(
    message: string,
    public adaptorId: string,
    code: string = 'ADAPTOR_ERROR',
    details?: Record<string, unknown>
  ) {
    super(message, code, undefined, details);
    this.name = 'AdaptorError';
  }
}

export class ValidationError extends PromptTargetingError {
  constructor(
    message: string,
    public validationErrors: ValidationError[],
    code: string = 'VALIDATION_ERROR'
  ) {
    super(message, code);
    this.name = 'ValidationError';
  }
}

export class TranslationError extends PromptTargetingError {
  constructor(
    message: string,
    platform: string,
    code: string = 'TRANSLATION_ERROR',
    details?: Record<string, unknown>
  ) {
    super(message, code, platform, details);
    this.name = 'TranslationError';
  }
}

/**
 * Configuration panel UI component
 * Epic 10.2.2 - Configuration System UI Components
 */

import React, { useState, useEffect, useCallback } from 'react';
import { ConfigurationManager, GlobalConfig, ConfigValidationResult, ConfigurationPreset } from '../../config/ConfigurationManager';

/**
 * Configuration panel props
 */
export interface ConfigurationPanelProps {
  configManager: ConfigurationManager;
  className?: string;
  onConfigChanged?: (config: GlobalConfig) => void;
  onValidationResult?: (result: ConfigValidationResult) => void;
}

/**
 * Configuration section props
 */
interface ConfigSectionProps {
  title: string;
  children: React.ReactNode;
  collapsible?: boolean;
  defaultExpanded?: boolean;
}

/**
 * Form field props
 */
interface FormFieldProps {
  label: string;
  value: any;
  onChange: (value: any) => void;
  type: 'text' | 'number' | 'select' | 'boolean' | 'range';
  options?: { value: any; label: string }[];
  min?: number;
  max?: number;
  step?: number;
  placeholder?: string;
  error?: string;
  warning?: string;
  help?: string;
}

/**
 * Main configuration panel component
 */
export const ConfigurationPanel: React.FC<ConfigurationPanelProps> = ({
  configManager,
  className = '',
  onConfigChanged,
  onValidationResult,
}) => {
  const [config, setConfig] = useState<GlobalConfig>(configManager.getConfig());
  const [validationResult, setValidationResult] = useState<ConfigValidationResult | null>(null);
  const [presets, setPresets] = useState<ConfigurationPreset[]>([]);
  const [selectedPreset, setSelectedPreset] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'general' | 'platforms' | 'pipeline' | 'presets'>('general');
  const [isDirty, setIsDirty] = useState(false);

  // Load initial data
  useEffect(() => {
    setPresets(configManager.listPresets());

    // Subscribe to config changes
    const handleConfigChanged = () => {
      const newConfig = configManager.getConfig();
      setConfig(newConfig);
      setIsDirty(false);
      onConfigChanged?.(newConfig);
    };

    const handleValidation = (result: ConfigValidationResult) => {
      setValidationResult(result);
      onValidationResult?.(result);
    };

    configManager.on('config:changed', handleConfigChanged);
    configManager.on('config:validated', handleValidation);
    configManager.on('config:preset:applied', handleConfigChanged);

    return () => {
      configManager.off('config:changed', handleConfigChanged);
      configManager.off('config:validated', handleValidation);
      configManager.off('config:preset:applied', handleConfigChanged);
    };
  }, [configManager, onConfigChanged, onValidationResult]);

  // Update configuration value
  const updateConfig = useCallback((path: string, value: any) => {
    const result = configManager.setConfigValue(path, value);
    setIsDirty(true);

    if (!result.valid) {
      console.error('Configuration validation failed:', result.errors);
    }
  }, [configManager]);

  // Apply preset
  const applyPreset = useCallback((presetName: string) => {
    if (!presetName) return;

    const result = configManager.applyPreset(presetName);
    if (result.valid) {
      setSelectedPreset(presetName);
      setIsDirty(false);
    }
  }, [configManager]);

  // Save current config as preset
  const saveAsPreset = useCallback((name: string, description: string) => {
    configManager.createPreset(name, description, config, ['custom']);
    setPresets(configManager.listPresets());
  }, [configManager, config]);

  // Reset to defaults
  const resetToDefaults = useCallback(() => {
    configManager.resetToDefaults();
    setSelectedPreset('');
  }, [configManager]);

  // Export configuration
  const exportConfig = useCallback((format: 'json' | 'yaml' = 'json') => {
    const exported = configManager.exportConfig(format);
    const blob = new Blob([exported], { type: format === 'json' ? 'application/json' : 'text/yaml' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `prompt-targeting-config.${format}`;
    a.click();
    URL.revokeObjectURL(url);
  }, [configManager]);

  return (
    <div className={`configuration-panel ${className}`}>
      {/* Header */}
      <div className="config-header">
        <h2>Prompt Targeting Configuration</h2>
        <div className="config-actions">
          <button onClick={() => exportConfig('json')} className="btn-secondary">
            Export JSON
          </button>
          <button onClick={() => exportConfig('yaml')} className="btn-secondary">
            Export YAML
          </button>
          <button onClick={resetToDefaults} className="btn-warning">
            Reset to Defaults
          </button>
        </div>
      </div>

      {/* Validation status */}
      {validationResult && (
        <ValidationStatus result={validationResult} />
      )}

      {/* Dirty state indicator */}
      {isDirty && (
        <div className="dirty-indicator">
          <span className="icon">⚠️</span>
          Configuration has unsaved changes
        </div>
      )}

      {/* Tab navigation */}
      <div className="config-tabs">
        <button 
          className={activeTab === 'general' ? 'active' : ''}
          onClick={() => setActiveTab('general')}
        >
          General
        </button>
        <button 
          className={activeTab === 'platforms' ? 'active' : ''}
          onClick={() => setActiveTab('platforms')}
        >
          Platforms
        </button>
        <button 
          className={activeTab === 'pipeline' ? 'active' : ''}
          onClick={() => setActiveTab('pipeline')}
        >
          Pipeline
        </button>
        <button 
          className={activeTab === 'presets' ? 'active' : ''}
          onClick={() => setActiveTab('presets')}
        >
          Presets
        </button>
      </div>

      {/* Tab content */}
      <div className="config-content">
        {activeTab === 'general' && (
          <GeneralConfigSection config={config} onUpdate={updateConfig} />
        )}

        {activeTab === 'platforms' && (
          <PlatformConfigSection config={config} onUpdate={updateConfig} />
        )}

        {activeTab === 'pipeline' && (
          <PipelineConfigSection config={config} onUpdate={updateConfig} />
        )}

        {activeTab === 'presets' && (
          <PresetsSection
            presets={presets}
            selectedPreset={selectedPreset}
            onApplyPreset={applyPreset}
            onSavePreset={saveAsPreset}
            configManager={configManager}
          />
        )}
      </div>
    </div>
  );
};

/**
 * Validation status component
 */
const ValidationStatus: React.FC<{ result: ConfigValidationResult }> = ({ result }) => {
  if (result.valid && result.warnings.length === 0) {
    return (
      <div className="validation-status success">
        <span className="icon">✅</span>
        Configuration is valid
      </div>
    );
  }

  return (
    <div className="validation-status">
      {result.errors.length > 0 && (
        <div className="validation-errors">
          <h4>❌ Errors:</h4>
          <ul>
            {result.errors.map((error, index) => (
              <li key={index}>
                <strong>{error.path}:</strong> {error.message}
              </li>
            ))}
          </ul>
        </div>
      )}

      {result.warnings.length > 0 && (
        <div className="validation-warnings">
          <h4>⚠️ Warnings:</h4>
          <ul>
            {result.warnings.map((warning, index) => (
              <li key={index}>
                <strong>{warning.path}:</strong> {warning.message}
                {warning.suggestion && <em> ({warning.suggestion})</em>}
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
};

