/**
 * Reusable form field component
 */
const FormField: React.FC<FormFieldProps> = ({
  label,
  value,
  onChange,
  type,
  options,
  min,
  max,
  step,
  placeholder,
  error,
  warning,
  help,
}) => {
  const renderInput = () => {
    switch (type) {
      case 'boolean':
        return (
          <input
            type="checkbox"
            checked={value}
            onChange={(e) => onChange(e.target.checked)}
          />
        );

      case 'number':
        return (
          <input
            type="number"
            value={value}
            onChange={(e) => onChange(Number(e.target.value))}
            min={min}
            max={max}
            step={step}
            placeholder={placeholder}
          />
        );

      case 'range':
        return (
          <div className="range-input">
            <input
              type="range"
              value={value}
              onChange={(e) => onChange(Number(e.target.value))}
              min={min}
              max={max}
              step={step}
            />
            <span className="range-value">{value}</span>
          </div>
        );

      case 'select':
        return (
          <select
            value={value}
            onChange={(e) => onChange(e.target.value)}
          >
            {options?.map((option) => (
              <option key={option.value} value={option.value}>
                {option.label}
              </option>
            ))}
          </select>
        );

      default:
        return (
          <input
            type="text"
            value={value}
            onChange={(e) => onChange(e.target.value)}
            placeholder={placeholder}
          />
        );
    }
  };

  return (
    <div className={`form-field ${error ? 'error' : ''} ${warning ? 'warning' : ''}`}>
      <label>{label}</label>
      {renderInput()}
      {help && <div className="field-help">{help}</div>}
      {error && <div className="field-error">{error}</div>}
      {warning && <div className="field-warning">{warning}</div>}
    </div>
  );
};

/**
 * Configuration management React hook
 * Epic 10.2.2 - Configuration System UI Components
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { ConfigurationManager, GlobalConfig, ConfigValidationResult, ConfigurationPreset } from '../../config/ConfigurationManager';

/**
 * Configuration hook return type
 */
export interface UseConfigurationReturn {
  config: GlobalConfig;
  isLoading: boolean;
  isDirty: boolean;
  validationResult: ConfigValidationResult | null;
  presets: ConfigurationPreset[];

  // Configuration management
  updateConfig: (updates: Partial<GlobalConfig>) => ConfigValidationResult;
  setConfigValue: (path: string, value: unknown) => ConfigValidationResult;
  getConfigValue: (path: string) => unknown;
  resetToDefaults: () => ConfigValidationResult;

  // Preset management
  applyPreset: (name: string) => ConfigValidationResult;
  createPreset: (name: string, description: string, tags?: string[]) => void;
  deletePreset: (name: string) => boolean;

  // Import/Export
  exportConfig: (format?: 'json' | 'yaml') => string;
  importConfig: (data: string, format?: 'json' | 'yaml') => ConfigValidationResult;

  // Utilities
  validateConfig: () => ConfigValidationResult;
  getConfigSummary: () => ReturnType<ConfigurationManager['getConfigSummary']>;
  getConfigHistory: (limit?: number) => ReturnType<ConfigurationManager['getConfigHistory']>;
}

/**
 * Configuration hook options
 */
export interface UseConfigurationOptions {
  /** Auto-save delay in milliseconds */
  autoSaveDelay?: number;
  /** Enable automatic validation */
  autoValidate?: boolean;
  /** Validation debounce delay */
  validationDelay?: number;
  /** Subscribe to external config changes */
  subscribeToChanges?: boolean;
}

/**
 * React hook for configuration management
 */
export function useConfiguration(
  configManager: ConfigurationManager,
  options: UseConfigurationOptions = {}
): UseConfigurationReturn {
  const {
    autoSaveDelay = 1000,
    autoValidate = true,
    validationDelay = 300,
    subscribeToChanges = true,
  } = options;

  // State
  const [config, setConfig] = useState<GlobalConfig>(configManager.getConfig());
  const [isLoading, setIsLoading] = useState(false);
  const [isDirty, setIsDirty] = useState(false);
  const [validationResult, setValidationResult] = useState<ConfigValidationResult | null>(null);
  const [presets, setPresets] = useState<ConfigurationPreset[]>([]);

  // Refs for debouncing
  const autoSaveTimeoutRef = useRef<NodeJS.Timeout>();
  const validationTimeoutRef = useRef<NodeJS.Timeout>();
  const lastConfigRef = useRef<GlobalConfig>(config);

  // Load presets
  useEffect(() => {
    setPresets(configManager.listPresets());
  }, [configManager]);

  // Subscribe to configuration changes
  useEffect(() => {
    if (!subscribeToChanges) return;

    const handleConfigChange = () => {
      const newConfig = configManager.getConfig();
      setConfig(newConfig);
      lastConfigRef.current = newConfig;
      setIsDirty(false);
    };

    const handleValidation = (result: ConfigValidationResult) => {
      setValidationResult(result);
    };

    const handlePresetApplied = () => {
      setPresets(configManager.listPresets());
      setIsDirty(false);
    };

    configManager.on('config:changed', handleConfigChange);
    configManager.on('config:validated', handleValidation);
    configManager.on('config:preset:applied', handlePresetApplied);

    return () => {
      configManager.off('config:changed', handleConfigChange);
      configManager.off('config:validated', handleValidation);
      configManager.off('config:preset:applied', handlePresetApplied);
    };
  }, [configManager, subscribeToChanges]);

  // Auto-save effect
  useEffect(() => {
    if (!isDirty || !autoSaveDelay) return;

    autoSaveTimeoutRef.current = setTimeout(() => {
      // Only save if config actually changed
      if (JSON.stringify(config) !== JSON.stringify(lastConfigRef.current)) {
        configManager.updateConfig(config, 'Auto-save');
        lastConfigRef.current = config;
        setIsDirty(false);
      }
    }, autoSaveDelay);

    return () => {
      if (autoSaveTimeoutRef.current) {
        clearTimeout(autoSaveTimeoutRef.current);
      }
    };
  }, [config, isDirty, autoSaveDelay, configManager]);

  // Auto-validation effect
  useEffect(() => {
    if (!autoValidate || !validationDelay) return;

    if (validationTimeoutRef.current) {
      clearTimeout(validationTimeoutRef.current);
    }

    validationTimeoutRef.current = setTimeout(() => {
      const result = configManager.validateConfig(config);
      setValidationResult(result);
    }, validationDelay);

    return () => {
      if (validationTimeoutRef.current) {
        clearTimeout(validationTimeoutRef.current);
      }
    };
  }, [config, autoValidate, validationDelay, configManager]);

  // Update configuration
  const updateConfig = useCallback((updates: Partial<GlobalConfig>): ConfigValidationResult => {
    const result = configManager.updateConfig(updates);

    if (result.valid) {
      setConfig(configManager.getConfig());
      setIsDirty(false);
    } else {
      // Keep the invalid config in state for editing
      const mergedConfig = { ...config, ...updates };
      setConfig(mergedConfig);
      setIsDirty(true);
    }

    return result;
  }, [configManager, config]);

  // Set specific configuration value
  const setConfigValue = useCallback((path: string, value: unknown): ConfigValidationResult => {
    const result = configManager.setConfigValue(path, value);

    if (result.valid) {
      setConfig(configManager.getConfig());
      setIsDirty(false);
    } else {
      // Update local state for immediate UI feedback
      const newConfig = structuredClone(config);
      setNestedValue(newConfig, path, value);
      setConfig(newConfig);
      setIsDirty(true);
    }

    return result;
  }, [configManager, config]);

  // Get specific configuration value
  const getConfigValue = useCallback((path: string): unknown => {
    return getNestedValue(config, path);
  }, [config]);

  // Reset to defaults
  const resetToDefaults = useCallback((): ConfigValidationResult => {
    const result = configManager.resetToDefaults();
    setConfig(configManager.getConfig());
    setIsDirty(false);
    return result;
  }, [configManager]);

  // Apply preset
  const applyPreset = useCallback((name: string): ConfigValidationResult => {
    const result = configManager.applyPreset(name);

    if (result.valid) {
      setConfig(configManager.getConfig());
      setIsDirty(false);
    }

    return result;
  }, [configManager]);

  // Create preset
  const createPreset = useCallback((name: string, description: string, tags: string[] = []): void => {
    configManager.createPreset(name, description, config, tags);
    setPresets(configManager.listPresets());
  }, [configManager, config]);

  // Delete preset
  const deletePreset = useCallback((name: string): boolean => {
    const success = configManager.deletePreset(name);
    if (success) {
      setPresets(configManager.listPresets());
    }
    return success;
  }, [configManager]);

  // Export configuration
  const exportConfig = useCallback((format: 'json' | 'yaml' = 'json'): string => {
    return configManager.exportConfig(format);
  }, [configManager]);

  // Import configuration
  const importConfig = useCallback((data: string, format: 'json' | 'yaml' = 'json'): ConfigValidationResult => {
    setIsLoading(true);
    const result = configManager.importConfig(data, format);

    if (result.valid) {
      setConfig(configManager.getConfig());
      setIsDirty(false);
    }

    setIsLoading(false);
    return result;
  }, [configManager]);

  // Validate current configuration
  const validateConfig = useCallback((): ConfigValidationResult => {
    const result = configManager.validateConfig(config);
    setValidationResult(result);
    return result;
  }, [configManager, config]);

  // Get configuration summary
  const getConfigSummary = useCallback(() => {
    return configManager.getConfigSummary();
  }, [configManager]);

  // Get configuration history
  const getConfigHistory = useCallback((limit?: number) => {
    return configManager.getConfigHistory(limit);
  }, [configManager]);

  return {
    config,
    isLoading,
    isDirty,
    validationResult,
    presets,
    updateConfig,
    setConfigValue,
    getConfigValue,
    resetToDefaults,
    applyPreset,
    createPreset,
    deletePreset,
    exportConfig,
    importConfig,
    validateConfig,
    getConfigSummary,
    getConfigHistory,
  };
}

/**
 * Set nested value in object by path
 */
function setNestedValue(obj: any, path: string, value: unknown): void {
  const parts = path.split('.');
  let current = obj;

  for (let i = 0; i < parts.length - 1; i++) {
    const part = parts[i];
    if (!(part in current) || typeof current[part] !== 'object') {
      current[part] = {};
    }
    current = current[part];
  }

  current[parts[parts.length - 1]] = value;
}

/**
 * Get nested value from object by path
 */
function getNestedValue(obj: any, path: string): unknown {
  return path.split('.').reduce((current, key) => current?.[key], obj);
}

/**
 * Configuration context for React components
 */
import React, { createContext, useContext } from 'react';

const ConfigurationContext = createContext<{
  configManager: ConfigurationManager;
  configHook: UseConfigurationReturn;
} | null>(null);

/**
 * Configuration provider component
 */
export const ConfigurationProvider: React.FC<{
  configManager: ConfigurationManager;
  options?: UseConfigurationOptions;
  children: React.ReactNode;
}> = ({ configManager, options, children }) => {
  const configHook = useConfiguration(configManager, options);

  return (
    <ConfigurationContext.Provider value={{ configManager, configHook }}>
      {children}
    </ConfigurationContext.Provider>
  );
};

/**
 * Hook to use configuration context
 */
export function useConfigurationContext(): {
  configManager: ConfigurationManager;
  configHook: UseConfigurationReturn;
} {
  const context = useContext(ConfigurationContext);
  if (!context) {
    throw new Error('useConfigurationContext must be used within a ConfigurationProvider');
  }
  return context;
}

/**
 * Higher-order component for configuration
 */
export function withConfiguration<P extends object>(
  Component: React.ComponentType<P & { configHook: UseConfigurationReturn }>
) {
  return function WithConfigurationComponent(props: P) {
    const { configHook } = useConfigurationContext();
    return <Component {...props} configHook={configHook} />;
  };
}

/**
 * Additional validation rules for enhanced validation capabilities
 * Epic 10.2.3 - Validation Rules System Extensions
 */

import { ValidationRule, ValidationRuleResult, ValidationContext, ValidationCategory, ValidationSeverity } from './ValidationRulesEngine';

/**
 * Validates that all nodes have valid and required properties
 */
export class MissingRequiredPropertiesRule implements ValidationRule {
  id = 'missing-required-properties';
  name = 'Missing Required Properties Check';
  description = 'Validates that nodes have required properties';
  category = ValidationCategory.STRUCTURE;
  severity = ValidationSeverity.ERROR;
  enabled = true;

  private readonly requiredPropertiesByType: Record<string, string[]> = {
    'output': ['text', 'content'],
    'input': ['name'],
    'transform': ['template', 'content'],
    'conditional': ['condition'],
    'loop': ['iterations'],
    'variable': ['name', 'value'],
  };

  applies() { return true; }

  async validate(context: ValidationContext): Promise<ValidationRuleResult> {
    const { graph } = context;

    if (!graph.nodes || graph.nodes.length === 0) {
      return {
        passed: true,
        message: 'No nodes to validate',
      };
    }

    const missingPropsNodes: Array<{nodeId: string, missing: string[]}> = [];

    for (const node of graph.nodes) {
      const nodeType = (node.type || node.data?.type || '').toLowerCase();
      const nodeData = node.data || {};
      const requiredProps = this.requiredPropertiesByType[nodeType] || [];

      if (requiredProps.length > 0) {
        const missingProps: string[] = [];

        for (const prop of requiredProps) {
          // Check if at least one required property exists and has content
          const hasProperty = requiredProps.some(p => {
            const value = nodeData[p];
            return value !== undefined && value !== null && String(value).trim().length > 0;
          });

          if (!hasProperty && !missingProps.length) {
            missingProps.push(...requiredProps.filter(p => !nodeData[p] || String(nodeData[p]).trim().length === 0));
          }
        }

        if (missingProps.length > 0) {
          missingPropsNodes.push({ nodeId: node.id, missing: missingProps });
        }
      }
    }

    if (missingPropsNodes.length > 0) {
      const affectedNodes = missingPropsNodes.map(n => n.nodeId);
      const totalMissing = missingPropsNodes.reduce((sum, n) => sum + n.missing.length, 0);

      return {
        passed: false,
        message: `${missingPropsNodes.length} node(s) missing required properties (${totalMissing} total)`,
        details: {
          affectedNodeCount: missingPropsNodes.length,
          totalMissingProperties: totalMissing,
          missingByNode: missingPropsNodes,
        },
        affectedNodes,
      };
    }

    return {
      passed: true,
      message: 'All nodes have required properties',
      details: { nodesChecked: graph.nodes.length },
    };
  }

  getSuggestion(): string {
    return 'Add missing required properties to nodes or provide default values';
  }

  async autoFix(context: ValidationContext): Promise<{ fixed: boolean; changes: any[] }> {
    const changes: any[] = [];
    let fixed = false;

    if (context.graph.nodes) {
      for (const node of context.graph.nodes) {
        const nodeType = (node.type || node.data?.type || '').toLowerCase();
        const nodeData = node.data || {};
        const requiredProps = this.requiredPropertiesByType[nodeType] || [];

        for (const prop of requiredProps) {
          if (!nodeData[prop] || String(nodeData[prop]).trim().length === 0) {
            // Add default value based on property type
            const defaultValue = this.getDefaultValue(prop, nodeType);
            nodeData[prop] = defaultValue;

            fixed = true;
            changes.push({
              nodeId: node.id,
              type: 'property_added',
              property: prop,
              value: defaultValue,
            });
          }
        }
      }
    }

    return { fixed, changes };
  }

  private getDefaultValue(property: string, nodeType: string): string {
    const defaults: Record<string, string> = {
      text: `[${nodeType} content]`,
      content: `[${nodeType} content]`,
      template: `[${nodeType} template]`,
      name: `${nodeType}_${Date.now()}`,
      condition: 'true',
      iterations: '1',
      value: '',
    };

    return defaults[property] || `[${property}]`;
  }
}

/**
 * Detects duplicate content across nodes
 */
export class DuplicateContentRule implements ValidationRule {
  id = 'duplicate-content';
  name = 'Duplicate Content Check';
  description = 'Detects duplicate content in the graph';
  category = ValidationCategory.CONTENT;
  severity = ValidationSeverity.WARNING;
  enabled = true;

  applies() { return true; }

  async validate(context: ValidationContext): Promise<ValidationRuleResult> {
    const { graph } = context;

    if (!graph.nodes || graph.nodes.length < 2) {
      return {
        passed: true,
        message: 'Insufficient nodes for duplicate detection',
      };
    }

    const contentMap = new Map<string, string[]>(); // content -> nodeIds[]
    const contentFields = ['text', 'content', 'prompt', 'template'];

    // Extract and normalize content from all nodes
    for (const node of graph.nodes) {
      const nodeData = node.data || {};

      for (const field of contentFields) {
        if (nodeData[field]) {
          const content = String(nodeData[field]).trim().toLowerCase();

          if (content.length > 10) { // Only check substantial content
            if (!contentMap.has(content)) {
              contentMap.set(content, []);
            }
            contentMap.get(content)!.push(node.id);
          }
        }
      }
    }

    // Find duplicates
    const duplicates = Array.from(contentMap.entries())
      .filter(([_, nodeIds]) => nodeIds.length > 1);

    if (duplicates.length > 0) {
      const totalDuplicateNodes = duplicates.reduce((sum, [_, nodeIds]) => sum + nodeIds.length, 0);
      const affectedNodes = duplicates.flatMap(([_, nodeIds]) => nodeIds);

      return {
        passed: false,
        message: `Found ${duplicates.length} duplicate content pattern(s) affecting ${totalDuplicateNodes} node(s)`,
        details: {
          duplicatePatterns: duplicates.length,
          affectedNodeCount: totalDuplicateNodes,
          duplicates: duplicates.map(([content, nodeIds]) => ({
            content: content.substring(0, 50) + (content.length > 50 ? '...' : ''),
            nodeIds,
            duplicateCount: nodeIds.length,
          })),
        },
        affectedNodes,
      };
    }

    return {
      passed: true,
      message: 'No duplicate content detected',
      details: { contentPatternsChecked: contentMap.size },
    };
  }

  getSuggestion(): string {
    return 'Review and modify duplicate content to ensure variation and uniqueness';
  }
}

/**
 * Validates language consistency across content
 */
export class LanguageConsistencyRule implements ValidationRule {
  id = 'language-consistency';
  name = 'Language Consistency Check';
  description = 'Validates language consistency across content';
  category = ValidationCategory.CONTENT;
  severity = ValidationSeverity.INFO;
  enabled = true;

  private readonly languagePatterns: Record<string, RegExp[]> = {
    english: [
      /\b(the|and|or|but|in|on|at|to|for|of|with|by)\b/gi,
      /\b(this|that|these|those|here|there)\b/gi,
    ],
    spanish: [
      /\b(el|la|los|las|y|o|pero|en|de|con|por|para)\b/gi,
      /\b(este|esta|estos|estas|aquí|allí)\b/gi,
    ],
    french: [
      /\b(le|la|les|et|ou|mais|dans|de|avec|par|pour)\b/gi,
      /\b(ce|cette|ces|ici|là)\b/gi,
    ],
    german: [
      /\b(der|die|das|und|oder|aber|in|auf|mit|von|für)\b/gi,
      /\b(dieser|diese|dieses|hier|dort)\b/gi,
    ],
  };

  applies() { return true; }

  async validate(context: ValidationContext): Promise<ValidationRuleResult> {
    const { graph } = context;

    if (!graph.nodes || graph.nodes.length === 0) {
      return {
        passed: true,
        message: 'No content to analyze for language consistency',
      };
    }

    const contentTexts: Array<{nodeId: string, content: string}> = [];
    const contentFields = ['text', 'content', 'prompt', 'template'];

    // Extract content from all nodes
    for (const node of graph.nodes) {
      const nodeData = node.data || {};

      for (const field of contentFields) {
        if (nodeData[field]) {
          const content = String(nodeData[field]).trim();
          if (content.length > 20) { // Only analyze substantial content
            contentTexts.push({ nodeId: node.id, content });
          }
        }
      }
    }

    if (contentTexts.length < 2) {
      return {
        passed: true,
        message: 'Insufficient content for language consistency analysis',
      };
    }

    // Detect languages for each content piece
    const languageDetections = contentTexts.map(({ nodeId, content }) => ({
      nodeId,
      content,
      languages: this.detectLanguages(content),
    }));

    // Find language inconsistencies
    const languageCounts = new Map<string, number>();
    for (const detection of languageDetections) {
      for (const lang of detection.languages) {
        languageCounts.set(lang, (languageCounts.get(lang) || 0) + 1);
      }
    }

    const primaryLanguage = Array.from(languageCounts.entries())
      .sort(([,a], [,b]) => b - a)[0]?.[0];

    if (!primaryLanguage) {
      return {
        passed: true,
        message: 'Unable to determine primary language',
      };
    }

    const inconsistentNodes = languageDetections
      .filter(detection => !detection.languages.includes(primaryLanguage))
      .map(detection => detection.nodeId);

    if (inconsistentNodes.length > 0) {
      const consistencyScore = ((languageDetections.length - inconsistentNodes.length) / languageDetections.length) * 100;

      return {
        passed: consistencyScore >= 80,
        message: `Language inconsistency detected (${Math.round(consistencyScore)}% consistency)`,
        details: {
          primaryLanguage,
          consistencyScore: Math.round(consistencyScore),
          inconsistentNodeCount: inconsistentNodes.length,
          totalContentNodes: languageDetections.length,
          languageDistribution: Object.fromEntries(languageCounts),
        },
        affectedNodes: inconsistentNodes,
        metrics: { consistencyScore: consistencyScore / 100 },
      };
    }

    return {
      passed: true,
      message: `Language consistency is good (primary: ${primaryLanguage})`,
      details: {
        primaryLanguage,
        consistencyScore: 100,
        contentNodesAnalyzed: languageDetections.length,
      },
      metrics: { consistencyScore: 1 },
    };
  }

  private detectLanguages(content: string): string[] {
    const detectedLanguages: string[] = [];

    for (const [language, patterns] of Object.entries(this.languagePatterns)) {
      let matchCount = 0;

      for (const pattern of patterns) {
        const matches = content.match(pattern);
        if (matches) {
          matchCount += matches.length;
        }
      }

      // If we found enough matches, consider this language present
      const wordCount = content.split(/\s+/).length;
      const matchRatio = matchCount / wordCount;

      if (matchRatio > 0.05) { // At least 5% of words match language patterns
        detectedLanguages.push(language);
      }
    }

    return detectedLanguages.length > 0 ? detectedLanguages : ['unknown'];
  }

  getSuggestion(): string {
    return 'Ensure consistent language usage across all content or clearly separate multilingual sections';
  }
}

/**
 * Detects potentially sensitive or inappropriate content
 */
export class SensitiveContentRule implements ValidationRule {
  id = 'sensitive-content';
  name = 'Sensitive Content Check';
  description = 'Detects potentially sensitive or inappropriate content';
  category = ValidationCategory.SECURITY;
  severity = ValidationSeverity.WARNING;
  enabled = true;

  private readonly sensitivePatterns = [
    // Personal Information
    /\b\d{3}-\d{2}-\d{4}\b/g, // SSN pattern
    /\b\d{4}[\s-]?\d{4}[\s-]?\d{4}[\s-]?\d{4}\b/g, // Credit card pattern
    /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g, // Email pattern

    // Potentially harmful content
    /\b(password|secret|confidential|classified)\b/gi,
    /\b(violence|harm|hate|discrimination)\b/gi,
    /\b(illegal|fraud|scam|phishing)\b/gi,

    // Inappropriate content indicators
    /\b(explicit|nsfw|adult|mature)\b/gi,
  ];

  private readonly sensitiveCategories = [
    'Personal Information',
    'Confidential Data',
    'Potentially Harmful',
    'Inappropriate Content',
  ];

  applies() { return true; }

  async validate(context: ValidationContext): Promise<ValidationRuleResult> {
    const { graph } = context;

    if (!graph.nodes || graph.nodes.length === 0) {
      return {
        passed: true,
        message: 'No content to scan for sensitive information',
      };
    }

    const sensitiveFindings: Array<{
      nodeId: string;
      category: string;
      pattern: string;
      matches: number;
    }> = [];

    const contentFields = ['text', 'content', 'prompt', 'template'];

    for (const node of graph.nodes) {
      const nodeData = node.data || {};

      for (const field of contentFields) {
        if (nodeData[field]) {
          const content = String(nodeData[field]);

          for (let i = 0; i < this.sensitivePatterns.length; i++) {
            const pattern = this.sensitivePatterns[i];
            const matches = content.match(pattern);

            if (matches && matches.length > 0) {
              sensitiveFindings.push({
                nodeId: node.id,
                category: this.sensitiveCategories[Math.floor(i / 2)] || 'Unknown',
                pattern: pattern.source,
                matches: matches.length,
              });
            }
          }
        }
      }
    }

    if (sensitiveFindings.length > 0) {
      const affectedNodes = [...new Set(sensitiveFindings.map(f => f.nodeId))];
      const totalMatches = sensitiveFindings.reduce((sum, f) => sum + f.matches, 0);

      return {
        passed: false,
        message: `Potentially sensitive content detected in ${affectedNodes.length} node(s) (${totalMatches} pattern matches)`,
        details: {
          findingCount: sensitiveFindings.length,
          affectedNodeCount: affectedNodes.length,
          totalMatches,
          categories: [...new Set(sensitiveFindings.map(f => f.category))],
          findings: sensitiveFindings.slice(0, 10), // Limit to first 10 findings
        },
        affectedNodes,
      };
    }

    return {
      passed: true,
      message: 'No sensitive content patterns detected',
      details: { 
        patternsChecked: this.sensitivePatterns.length,
        nodesScanned: graph.nodes.length,
      },
    };
  }

  getSuggestion(): string {
    return 'Review and remove or sanitize sensitive information before deployment';
  }

  async autoFix(context: ValidationContext): Promise<{ fixed: boolean; changes: any[] }> {
    const changes: any[] = [];
    let fixed = false;

    if (context.graph.nodes) {
      for (const node of context.graph.nodes) {
        const nodeData = node.data || {};
        const contentFields = ['text', 'content', 'prompt', 'template'];

        for (const field of contentFields) {
          if (nodeData[field]) {
            const originalContent = String(nodeData[field]);
            let sanitizedContent = originalContent;

            // Sanitize sensitive patterns
            for (const pattern of this.sensitivePatterns) {
              if (pattern.test(sanitizedContent)) {
                sanitizedContent = sanitizedContent.replace(pattern, '[REDACTED]');
                fixed = true;
              }
            }

            if (sanitizedContent !== originalContent) {
              nodeData[field] = sanitizedContent;
              changes.push({
                nodeId: node.id,
                type: 'content_sanitized',
                field,
                original: originalContent.substring(0, 100),
                sanitized: sanitizedContent.substring(0, 100),
              });
            }
          }
        }
      }
    }

    return { fixed, changes };
  }
}

/**
 * Estimates and validates processing time for the graph
 */
export class ProcessingTimeRule implements ValidationRule {
  id = 'processing-time';
  name = 'Processing Time Check';
  description = 'Estimates processing time for the graph';
  category = ValidationCategory.PERFORMANCE;
  severity = ValidationSeverity.WARNING;
  enabled = true;

  private readonly nodeProcessingTimes: Record<string, number> = {
    'output': 0.1,
    'input': 0.05,
    'transform': 0.5,
    'conditional': 0.2,
    'loop': 1.0,
    'variable': 0.05,
    'api-call': 2.0,
    'ai-generation': 5.0,
  };

  applies() { return true; }

  async validate(context: ValidationContext): Promise<ValidationRuleResult> {
    const { graph, metadata } = context;

    if (!graph.nodes || graph.nodes.length === 0) {
      return {
        passed: true,
        message: 'No nodes to estimate processing time',
        metrics: { estimatedTime: 0 },
      };
    }

    let totalEstimatedTime = 0;
    let complexityMultiplier = 1;

    // Calculate base processing time
    for (const node of graph.nodes) {
      const nodeType = (node.type || node.data?.type || 'output').toLowerCase();
      const baseTime = this.nodeProcessingTimes[nodeType] || 0.1;

      // Factor in content complexity
      const content = this.extractContent(node.data || {});
      const contentComplexity = Math.min(5, content.length / 1000); // Max 5x multiplier

      totalEstimatedTime += baseTime * (1 + contentComplexity);
    }

    // Factor in graph complexity
    const nodeCount = graph.nodes.length;
    const edgeCount = graph.edges?.length || 0;

    if (nodeCount > 20) {
      complexityMultiplier *= 1 + ((nodeCount - 20) * 0.1);
    }

    if (edgeCount > nodeCount) {
      complexityMultiplier *= 1 + ((edgeCount - nodeCount) * 0.05);
    }

    totalEstimatedTime *= complexityMultiplier;

    // Apply metadata if available
    if (metadata?.estimatedTokens) {
      // Add time for token processing (rough estimate)
      totalEstimatedTime += metadata.estimatedTokens * 0.001;
    }

    // Determine if processing time is acceptable
    const warningThreshold = 30; // 30 seconds
    const errorThreshold = 120; // 2 minutes

    let passed = true;
    let message = `Estimated processing time: ${totalEstimatedTime.toFixed(1)} seconds`;

    if (totalEstimatedTime > errorThreshold) {
      passed = false;
      message = `Processing time may be excessive (${totalEstimatedTime.toFixed(1)}s > ${errorThreshold}s)`;
    } else if (totalEstimatedTime > warningThreshold) {
      passed = false;
      message = `Processing time is elevated (${totalEstimatedTime.toFixed(1)}s > ${warningThreshold}s)`;
    }

    return {
      passed,
      message,
      details: {
        estimatedTime: Math.round(totalEstimatedTime * 100) / 100,
        complexityMultiplier: Math.round(complexityMultiplier * 100) / 100,
        nodeCount,
        edgeCount,
        warningThreshold,
        errorThreshold,
      },
      metrics: {
        estimatedTime: totalEstimatedTime,
        complexity: complexityMultiplier,
      },
    };
  }

  private extractContent(nodeData: any): string {
    const contentFields = ['text', 'content', 'prompt', 'template'];

    for (const field of contentFields) {
      if (nodeData[field] && typeof nodeData[field] === 'string') {
        return nodeData[field].trim();
      }
    }

    return '';
  }

  getSuggestion(): string {
    return 'Consider simplifying the graph or breaking it into smaller components to reduce processing time';
  }
}

/**
 * Estimates memory usage for graph processing
 */
export class MemoryUsageRule implements ValidationRule {
  id = 'memory-usage';
  name = 'Memory Usage Check';
  description = 'Estimates memory usage for graph processing';
  category = ValidationCategory.PERFORMANCE;
  severity = ValidationSeverity.INFO;
  enabled = true;

  private readonly nodeMemoryUsage: Record<string, number> = {
    'output': 1, // 1KB base
    'input': 0.5,
    'transform': 2,
    'conditional': 1,
    'loop': 5,
    'variable': 0.5,
    'api-call': 10,
    'ai-generation': 50,
  };

  applies() { return true; }

  async validate(context: ValidationContext): Promise<ValidationRuleResult> {
    const { graph } = context;

    if (!graph.nodes || graph.nodes.length === 0) {
      return {
        passed: true,
        message: 'No nodes to estimate memory usage',
        metrics: { estimatedMemoryKB: 0 },
      };
    }

    let totalMemoryKB = 0;

    // Calculate memory usage for each node
    for (const node of graph.nodes) {
      const nodeType = (node.type || node.data?.type || 'output').toLowerCase();
      const baseMemory = this.nodeMemoryUsage[nodeType] || 1;

      // Factor in content size
      const content = this.extractContent(node.data || {});
      const contentMemoryKB = content.length / 1024; // Rough estimate

      totalMemoryKB += baseMemory + contentMemoryKB;
    }

    // Add overhead for graph structure
    const graphOverheadKB = (graph.nodes.length * 0.1) + ((graph.edges?.length || 0) * 0.05);
    totalMemoryKB += graphOverheadKB;

    // Determine if memory usage is acceptable
    const warningThresholdMB = 100; // 100MB
    const errorThresholdMB = 500; // 500MB

    const totalMemoryMB = totalMemoryKB / 1024;

    let passed = true;
    let message = `Estimated memory usage: ${totalMemoryMB.toFixed(1)} MB`;

    if (totalMemoryMB > errorThresholdMB) {
      passed = false;
      message = `Memory usage may be excessive (${totalMemoryMB.toFixed(1)}MB > ${errorThresholdMB}MB)`;
    } else if (totalMemoryMB > warningThresholdMB) {
      passed = true; // Warning level, not failure
      message = `Memory usage is elevated (${totalMemoryMB.toFixed(1)}MB > ${warningThresholdMB}MB)`;
    }

    return {
      passed,
      message,
      details: {
        estimatedMemoryKB: Math.round(totalMemoryKB),
        estimatedMemoryMB: Math.round(totalMemoryMB * 100) / 100,
        nodeCount: graph.nodes.length,
        edgeCount: graph.edges?.length || 0,
        warningThresholdMB,
        errorThresholdMB,
      },
      metrics: {
        memoryKB: totalMemoryKB,
        memoryMB: totalMemoryMB,
      },
    };
  }

  private extractContent(nodeData: any): string {
    const contentFields = ['text', 'content', 'prompt', 'template'];

    for (const field of contentFields) {
      if (nodeData[field] && typeof nodeData[field] === 'string') {
        return nodeData[field];
      }
    }

    return '';
  }

  getSuggestion(): string {
    return 'Consider reducing content size or breaking the graph into smaller components to reduce memory usage';
  }
}

/**
 * Advanced validation rules engine with severity levels
 * Epic 10.2.3 - Validation Rules System with Severity Levels
 */

import { ValidationResult, ValidationError, ValidationWarning, PlatformCapabilities } from '../types';
import { EventEmitter } from 'events';

/**
 * Validation rule severity levels
 */
export enum ValidationSeverity {
  INFO = 'info',
  WARNING = 'warning',
  ERROR = 'error',
  CRITICAL = 'critical'
}

/**
 * Validation rule category
 */
export enum ValidationCategory {
  STRUCTURE = 'structure',
  CONTENT = 'content',
  PLATFORM = 'platform',
  PERFORMANCE = 'performance',
  SECURITY = 'security',
  QUALITY = 'quality'
}

/**
 * Validation context interface
 */
export interface ValidationContext {
  graph: any;
  targetPlatform: string;
  capabilities?: PlatformCapabilities;
  config?: any;
  metadata?: {
    nodeCount?: number;
    edgeCount?: number;
    complexity?: number;
    estimatedTokens?: number;
  };
}

/**
 * Validation rule interface
 */
export interface ValidationRule {
  id: string;
  name: string;
  description: string;
  category: ValidationCategory;
  severity: ValidationSeverity;
  enabled: boolean;

  /**
   * Check if rule applies to the current context
   */
  applies(context: ValidationContext): boolean;

  /**
   * Execute the validation rule
   */
  validate(context: ValidationContext): Promise<ValidationRuleResult>;

  /**
   * Get suggested fix for the validation issue
   */
  getSuggestion?(context: ValidationContext, result: ValidationRuleResult): string;

  /**
   * Auto-fix the validation issue if possible
   */
  autoFix?(context: ValidationContext): Promise<{ fixed: boolean; changes: any[] }>;
}

/**
 * Validation rule result
 */
export interface ValidationRuleResult {
  passed: boolean;
  message: string;
  details?: Record<string, unknown>;
  affectedNodes?: string[];
  metrics?: Record<string, number>;
}

/**
 * Validation report
 */
export interface ValidationReport {
  valid: boolean;
  score: number; // 0-100
  executionTime: number;
  rulesExecuted: number;
  rulesPassed: number;
  rulesFailed: number;

  results: {
    rule: ValidationRule;
    result: ValidationRuleResult;
    severity: ValidationSeverity;
    category: ValidationCategory;
  }[];

  summary: {
    critical: number;
    errors: number;
    warnings: number;
    info: number;
  };

  recommendations: string[];
  autoFixable: number;
}

/**
 * Validation engine configuration
 */
export interface ValidationEngineConfig {
  enabledCategories: ValidationCategory[];
  minSeverity: ValidationSeverity;
  enableAutoFix: boolean;
  maxExecutionTime: number;
  parallelExecution: boolean;
  enableMetrics: boolean;
}

/**
 * Advanced validation rules engine
 */
export class ValidationRulesEngine extends EventEmitter {
  private rules: Map<string, ValidationRule> = new Map();
  private config: ValidationEngineConfig;
  private metrics: {
    totalValidations: number;
    averageExecutionTime: number;
    rulePerformance: Map<string, { executions: number; totalTime: number; failureRate: number }>;
  };

  constructor(config: Partial<ValidationEngineConfig> = {}) {
    super();

    this.config = {
      enabledCategories: Object.values(ValidationCategory),
      minSeverity: ValidationSeverity.INFO,
      enableAutoFix: false,
      maxExecutionTime: 10000, // 10 seconds
      parallelExecution: true,
      enableMetrics: true,
      ...config,
    };

    this.metrics = {
      totalValidations: 0,
      averageExecutionTime: 0,
      rulePerformance: new Map(),
    };

    this.initializeBuiltInRules();
  }

  /**
   * Register a validation rule
   */
  public registerRule(rule: ValidationRule): void {
    if (this.rules.has(rule.id)) {
      throw new Error(`Validation rule with ID '${rule.id}' already exists`);
    }

    this.rules.set(rule.id, rule);
    this.emit('rule:registered', rule);
  }

  /**
   * Unregister a validation rule
   */
  public unregisterRule(ruleId: string): boolean {
    const removed = this.rules.delete(ruleId);
    if (removed) {
      this.emit('rule:unregistered', ruleId);
    }
    return removed;
  }

  /**
   * Enable/disable a validation rule
   */
  public setRuleEnabled(ruleId: string, enabled: boolean): void {
    const rule = this.rules.get(ruleId);
    if (rule) {
      rule.enabled = enabled;
      this.emit('rule:toggled', ruleId, enabled);
    }
  }

  /**
   * Get all registered rules
   */
  public getRules(): ValidationRule[] {
    return Array.from(this.rules.values());
  }

  /**
   * Get rules by category
   */
  public getRulesByCategory(category: ValidationCategory): ValidationRule[] {
    return this.getRules().filter(rule => rule.category === category);
  }

  /**
   * Get rules by severity
   */
  public getRulesBySeverity(severity: ValidationSeverity): ValidationRule[] {
    return this.getRules().filter(rule => rule.severity === severity);
  }

  /**
   * Execute validation with comprehensive reporting
   */
  public async validate(context: ValidationContext): Promise<ValidationReport> {
    const startTime = Date.now();
    this.emit('validation:started', context);

    try {
      // Filter applicable rules
      const applicableRules = this.getApplicableRules(context);

      if (applicableRules.length === 0) {
        return this.createEmptyReport(Date.now() - startTime);
      }

      // Execute rules
      const ruleResults = await this.executeRules(applicableRules, context);

      // Generate report
      const report = this.generateReport(ruleResults, Date.now() - startTime);

      // Update metrics
      this.updateMetrics(report);

      this.emit('validation:completed', report);
      return report;
    } catch (error) {
      this.emit('validation:error', error);
      throw error;
    }
  }

  /**
   * Execute validation with auto-fix
   */
  public async validateAndFix(context: ValidationContext): Promise<{
    report: ValidationReport;
    fixes: Array<{ ruleId: string; changes: any[]; success: boolean }>;
  }> {
    const originalReport = await this.validate(context);
    const fixes: Array<{ ruleId: string; changes: any[]; success: boolean }> = [];

    if (this.config.enableAutoFix && !originalReport.valid) {
      // Attempt auto-fixes for failed rules
      for (const result of originalReport.results) {
        if (!result.result.passed && result.rule.autoFix) {
          try {
            const fixResult = await result.rule.autoFix(context);
            fixes.push({
              ruleId: result.rule.id,
              changes: fixResult.changes,
              success: fixResult.fixed,
            });
          } catch (error) {
            fixes.push({
              ruleId: result.rule.id,
              changes: [],
              success: false,
            });
          }
        }
      }

      // Re-validate if fixes were applied
      if (fixes.some(f => f.success)) {
        const fixedReport = await this.validate(context);
        return { report: fixedReport, fixes };
      }
    }

    return { report: originalReport, fixes };
  }

  /**
   * Convert validation report to legacy format
   */
  public convertToLegacyFormat(report: ValidationReport): ValidationResult {
    const errors: ValidationError[] = [];
    const warnings: ValidationWarning[] = [];

    for (const result of report.results) {
      if (!result.result.passed) {
        const item = {
          code: result.rule.id,
          message: result.result.message,
          source: result.result.affectedNodes?.length ? {
            nodeId: result.result.affectedNodes[0]
          } : undefined,
        };

        if (result.severity === ValidationSeverity.ERROR || result.severity === ValidationSeverity.CRITICAL) {
          errors.push({
            ...item,
            severity: 'error' as const,
            suggestion: result.rule.getSuggestion?.(report.results[0] as any, result.result),
          });
        } else {
          warnings.push({
            ...item,
            optimization: result.rule.getSuggestion?.(report.results[0] as any, result.result),
          });
        }
      }
    }

    return {
      valid: report.valid,
      errors,
      warnings,
      compatibilityScore: report.score / 100,
    };
  }

  /**
   * Get validation engine statistics
   */
  public getStatistics(): {
    totalValidations: number;
    averageExecutionTime: number;
    registeredRules: number;
    enabledRules: number;
    rulePerformance: Array<{
      ruleId: string;
      executions: number;
      averageTime: number;
      failureRate: number;
    }>;
  } {
    const enabledRules = this.getRules().filter(r => r.enabled).length;
    const rulePerformance = Array.from(this.metrics.rulePerformance.entries()).map(([ruleId, stats]) => ({
      ruleId,
      executions: stats.executions,
      averageTime: stats.totalTime / stats.executions,
      failureRate: stats.failureRate,
    }));

    return {
      totalValidations: this.metrics.totalValidations,
      averageExecutionTime: this.metrics.averageExecutionTime,
      registeredRules: this.rules.size,
      enabledRules,
      rulePerformance,
    };
  }

  /**
   * Initialize built-in validation rules
   */
  private initializeBuiltInRules(): void {
    // Import additional rules
    import('./AdditionalValidationRules').then(module => {
      // Register additional comprehensive rules
      this.registerRule(new module.MissingRequiredPropertiesRule());
      this.registerRule(new module.DuplicateContentRule());
      this.registerRule(new module.LanguageConsistencyRule());
      this.registerRule(new module.SensitiveContentRule());
      this.registerRule(new module.ProcessingTimeRule());
      this.registerRule(new module.MemoryUsageRule());
    }).catch(() => {
      // Fallback to basic rules if additional rules fail to load
      console.warn('Failed to load additional validation rules, using basic rules only');
    });

    // Structure validation rules
    this.registerRule(new EmptyGraphRule());
    this.registerRule(new CyclicGraphRule());
    this.registerRule(new DisconnectedNodesRule());
    this.registerRule(new InvalidNodeTypeRule());
    this.registerRule(new MissingRequiredPropertiesRule());

    // Content validation rules
    this.registerRule(new EmptyContentRule());
    this.registerRule(new ContentLengthRule());
    this.registerRule(new ContentQualityRule());
    this.registerRule(new DuplicateContentRule());
    this.registerRule(new LanguageConsistencyRule());

    // Platform-specific rules
    this.registerRule(new PlatformCompatibilityRule());
    this.registerRule(new TokenLimitRule());
    this.registerRule(new ParameterValidationRule());
    this.registerRule(new FeatureSupportRule());

    // Performance rules
    this.registerRule(new ComplexityRule());
    this.registerRule(new ProcessingTimeRule());
    this.registerRule(new MemoryUsageRule());

    // Security rules
    this.registerRule(new InjectionDetectionRule());
    this.registerRule(new SensitiveContentRule());
    this.registerRule(new MaliciousPatternRule());

    // Quality rules
    this.registerRule(new OutputCoherenceRule());
    this.registerRule(new StyleConsistencyRule());
    this.registerRule(new OptimizationOpportunityRule());
  }

  /**
   * Get rules applicable to the current context
   */
  private getApplicableRules(context: ValidationContext): ValidationRule[] {
    return this.getRules().filter(rule => {
      if (!rule.enabled) return false;
      if (!this.config.enabledCategories.includes(rule.category)) return false;
      if (this.getSeverityOrder(rule.severity) < this.getSeverityOrder(this.config.minSeverity)) return false;

      return rule.applies(context);
    });
  }

  /**
   * Execute validation rules
   */
  private async executeRules(
    rules: ValidationRule[],
    context: ValidationContext
  ): Promise<Array<{ rule: ValidationRule; result: ValidationRuleResult; executionTime: number }>> {
    const results: Array<{ rule: ValidationRule; result: ValidationRuleResult; executionTime: number }> = [];

    if (this.config.parallelExecution) {
      // Execute rules in parallel
      const promises = rules.map(async (rule) => {
        const startTime = Date.now();
        try {
          const result = await this.executeRuleWithTimeout(rule, context);
          const executionTime = Date.now() - startTime;

          this.updateRuleMetrics(rule.id, executionTime, !result.passed);
          return { rule, result, executionTime };
        } catch (error) {
          const executionTime = Date.now() - startTime;
          this.updateRuleMetrics(rule.id, executionTime, true);

          return {
            rule,
            result: {
              passed: false,
              message: `Rule execution failed: ${error instanceof Error ? error.message : 'Unknown error'}`,
            },
            executionTime,
          };
        }
      });

      results.push(...await Promise.all(promises));
    } else {
      // Execute rules sequentially
      for (const rule of rules) {
        const startTime = Date.now();
        try {
          const result = await this.executeRuleWithTimeout(rule, context);
          const executionTime = Date.now() - startTime;

          this.updateRuleMetrics(rule.id, executionTime, !result.passed);
          results.push({ rule, result, executionTime });
        } catch (error) {
          const executionTime = Date.now() - startTime;
          this.updateRuleMetrics(rule.id, executionTime, true);

          results.push({
            rule,
            result: {
              passed: false,
              message: `Rule execution failed: ${error instanceof Error ? error.message : 'Unknown error'}`,
            },
            executionTime,
          });
        }
      }
    }

    return results;
  }

  /**
   * Execute rule with timeout
   */
  private async executeRuleWithTimeout(rule: ValidationRule, context: ValidationContext): Promise<ValidationRuleResult> {
    return new Promise((resolve, reject) => {
      const timeout = setTimeout(() => {
        reject(new Error(`Rule ${rule.id} execution timeout`));
      }, this.config.maxExecutionTime);

      rule.validate(context)
        .then(result => {
          clearTimeout(timeout);
          resolve(result);
        })
        .catch(error => {
          clearTimeout(timeout);
          reject(error);
        });
    });
  }

  /**
   * Generate comprehensive validation report
   */
  private generateReport(
    ruleResults: Array<{ rule: ValidationRule; result: ValidationRuleResult; executionTime: number }>,
    totalExecutionTime: number
  ): ValidationReport {
    const results = ruleResults.map(({ rule, result }) => ({
      rule,
      result,
      severity: rule.severity,
      category: rule.category,
    }));

    const summary = {
      critical: results.filter(r => r.severity === ValidationSeverity.CRITICAL && !r.result.passed).length,
      errors: results.filter(r => r.severity === ValidationSeverity.ERROR && !r.result.passed).length,
      warnings: results.filter(r => r.severity === ValidationSeverity.WARNING && !r.result.passed).length,
      info: results.filter(r => r.severity === ValidationSeverity.INFO && !r.result.passed).length,
    };

    const rulesPassed = results.filter(r => r.result.passed).length;
    const rulesFailed = results.length - rulesPassed;

    // Calculate validation score (0-100)
    const score = this.calculateValidationScore(results, summary);

    // Generate recommendations
    const recommendations = this.generateRecommendations(results);

    // Count auto-fixable issues
    const autoFixable = results.filter(r => !r.result.passed && r.rule.autoFix).length;

    return {
      valid: summary.critical === 0 && summary.errors === 0,
      score,
      executionTime: totalExecutionTime,
      rulesExecuted: results.length,
      rulesPassed,
      rulesFailed,
      results,
      summary,
      recommendations,
      autoFixable,
    };
  }

  /**
   * Calculate validation score based on severity weights
   */
  private calculateValidationScore(
    results: ValidationReport['results'],
    summary: ValidationReport['summary']
  ): number {
    const weights = {
      [ValidationSeverity.CRITICAL]: 40,
      [ValidationSeverity.ERROR]: 25,
      [ValidationSeverity.WARNING]: 10,
      [ValidationSeverity.INFO]: 5,
    };

    const totalPossiblePoints = results.reduce((sum, r) => sum + weights[r.severity], 0);
    if (totalPossiblePoints === 0) return 100;

    const lostPoints = results
      .filter(r => !r.result.passed)
      .reduce((sum, r) => sum + weights[r.severity], 0);

    return Math.max(0, Math.round(((totalPossiblePoints - lostPoints) / totalPossiblePoints) * 100));
  }

  /**
   * Generate recommendations based on validation results
   */
  private generateRecommendations(results: ValidationReport['results']): string[] {
    const recommendations: string[] = [];
    const failedResults = results.filter(r => !r.result.passed);

    // Group by category for better recommendations
    const byCategory = failedResults.reduce((acc, result) => {
      if (!acc[result.category]) acc[result.category] = [];
      acc[result.category].push(result);
      return acc;
    }, {} as Record<ValidationCategory, typeof failedResults>);

    // Generate category-specific recommendations
    for (const [category, categoryResults] of Object.entries(byCategory)) {
      const count = categoryResults.length;

      switch (category) {
        case ValidationCategory.STRUCTURE:
          recommendations.push(`Fix ${count} structural issue${count > 1 ? 's' : ''} to improve graph validity`);
          break;
        case ValidationCategory.CONTENT:
          recommendations.push(`Address ${count} content issue${count > 1 ? 's' : ''} to enhance output quality`);
          break;
        case ValidationCategory.PLATFORM:
          recommendations.push(`Resolve ${count} platform compatibility issue${count > 1 ? 's' : ''}`);
          break;
        case ValidationCategory.PERFORMANCE:
          recommendations.push(`Optimize ${count} performance aspect${count > 1 ? 's' : ''} for better efficiency`);
          break;
        case ValidationCategory.SECURITY:
          recommendations.push(`Address ${count} security concern${count > 1 ? 's' : ''} before deployment`);
          break;
        case ValidationCategory.QUALITY:
          recommendations.push(`Improve ${count} quality metric${count > 1 ? 's' : ''} for better results`);
          break;
      }
    }

    return recommendations;
  }

  /**
   * Create empty report for no applicable rules
   */
  private createEmptyReport(executionTime: number): ValidationReport {
    return {
      valid: true,
      score: 100,
      executionTime,
      rulesExecuted: 0,
      rulesPassed: 0,
      rulesFailed: 0,
      results: [],
      summary: { critical: 0, errors: 0, warnings: 0, info: 0 },
      recommendations: [],
      autoFixable: 0,
    };
  }

  /**
   * Update validation metrics
   */
  private updateMetrics(report: ValidationReport): void {
    if (!this.config.enableMetrics) return;

    this.metrics.totalValidations++;

    // Update average execution time
    const totalTime = this.metrics.averageExecutionTime * (this.metrics.totalValidations - 1) + report.executionTime;
    this.metrics.averageExecutionTime = totalTime / this.metrics.totalValidations;
  }

  /**
   * Update rule-specific metrics
   */
  private updateRuleMetrics(ruleId: string, executionTime: number, failed: boolean): void {
    if (!this.config.enableMetrics) return;

    if (!this.metrics.rulePerformance.has(ruleId)) {
      this.metrics.rulePerformance.set(ruleId, {
        executions: 0,
        totalTime: 0,
        failureRate: 0,
      });
    }

    const stats = this.metrics.rulePerformance.get(ruleId)!;
    const previousFailures = stats.failureRate * stats.executions;

    stats.executions++;
    stats.totalTime += executionTime;
    stats.failureRate = (previousFailures + (failed ? 1 : 0)) / stats.executions;
  }

  /**
   * Get severity order for comparison
   */
  private getSeverityOrder(severity: ValidationSeverity): number {
    const order = {
      [ValidationSeverity.INFO]: 0,
      [ValidationSeverity.WARNING]: 1,
      [ValidationSeverity.ERROR]: 2,
      [ValidationSeverity.CRITICAL]: 3,
    };
    return order[severity];
  }
}

