  let adapter: WebAdapter;

  beforeEach(() => {
    adapter = new WebAdapter();
  });

  describe('Event handling', () => {
    it('handles press events', () => {
      const callback = jest.fn();
      const pressHandler = adapter.handlePress(callback);

      expect(pressHandler).toHaveProperty('onClick');
      expect(pressHandler).toHaveProperty('onKeyDown');

      // Test click
      pressHandler.onClick();
      expect(callback).toHaveBeenCalledTimes(1);

      // Test Enter key
      pressHandler.onKeyDown({ key: 'Enter', preventDefault: jest.fn() } as any);
      expect(callback).toHaveBeenCalledTimes(2);

      // Test Space key
      pressHandler.onKeyDown({ key: ' ', preventDefault: jest.fn() } as any);
      expect(callback).toHaveBeenCalledTimes(3);
    });

    it('handles long press events', () => {
      const callback = jest.fn();
      const longPressHandler = adapter.handleLongPress(callback);

      expect(longPressHandler).toHaveProperty('onMouseDown');
      expect(longPressHandler).toHaveProperty('onMouseUp');
      expect(longPressHandler).toHaveProperty('onMouseLeave');

      // Test long press
      longPressHandler.onMouseDown();

      // Fast-forward time to trigger callback
      jest.advanceTimersByTime(500);
      expect(callback).toHaveBeenCalledTimes(1);
    });

    it('handles hover events', () => {
      const callback = jest.fn();
      const hoverHandler = adapter.handleHover(callback);

      expect(hoverHandler).toHaveProperty('onMouseEnter');
      hoverHandler.onMouseEnter();
      expect(callback).toHaveBeenCalledTimes(1);
    });
  });

  describe('Styling', () => {
    it('creates stylesheet', () => {
      const styles = { button: { color: 'red' } };
      const result = adapter.createStyleSheet(styles);
      expect(result).toBe(styles);
    });

    it('resolves styles', () => {
      const singleStyle = { color: 'red' };
      expect(adapter.resolveStyle(singleStyle)).toBe(singleStyle);

      const arrayStyles = [{ color: 'red' }, { fontSize: '16px' }];
      const resolved = adapter.resolveStyle(arrayStyles);
      expect(resolved).toEqual({ color: 'red', fontSize: '16px' });
    });
  });

  describe('Navigation', () => {
    it('opens URLs', () => {
      const mockOpen = jest.spyOn(window, 'open').mockImplementation();
      adapter.openUrl('https://example.com');
      expect(mockOpen).toHaveBeenCalledWith('https://example.com', '_blank', 'noopener,noreferrer');
      mockOpen.mockRestore();
    });

    it('goes back', () => {
      const mockBack = jest.spyOn(window.history, 'back').mockImplementation();
      Object.defineProperty(window.history, 'length', { value: 2 });

      adapter.goBack();
      expect(mockBack).toHaveBeenCalled();
      mockBack.mockRestore();
    });
  });

  describe('Storage', () => {
    it('gets storage items', async () => {
      localStorage.getItem = jest.fn().mockReturnValue('test-value');
      const result = await adapter.getStorageItem('test-key');
      expect(result).toBe('test-value');
      expect(localStorage.getItem).toHaveBeenCalledWith('test-key');
    });

    it('sets storage items', async () => {
      localStorage.setItem = jest.fn();
      await adapter.setStorageItem('test-key', 'test-value');
      expect(localStorage.setItem).toHaveBeenCalledWith('test-key', 'test-value');
    });

    it('removes storage items', async () => {
      localStorage.removeItem = jest.fn();
      await adapter.removeStorageItem('test-key');
      expect(localStorage.removeItem).toHaveBeenCalledWith('test-key');
    });
  });

  describe('Device features', () => {
    it('provides haptic feedback', () => {
      navigator.vibrate = jest.fn();
      adapter.hapticFeedback('medium');
      expect(navigator.vibrate).toHaveBeenCalledWith(20);
    });

    it('copies to clipboard', async () => {
      navigator.clipboard.writeText = jest.fn().mockResolvedValue(undefined);
      await adapter.copyToClipboard('test text');
      expect(navigator.clipboard.writeText).toHaveBeenCalledWith('test text');
    });

    it('shares content', async () => {
      navigator.share = jest.fn().mockResolvedValue(undefined);
      const content = { title: 'Test', text: 'Test content' };

      await adapter.shareContent(content);
      expect(navigator.share).toHaveBeenCalledWith(content);
    });

    it('falls back to clipboard for sharing when share API unavailable', async () => {
      navigator.share = undefined;
      navigator.clipboard.writeText = jest.fn().mockResolvedValue(undefined);

      const content = { title: 'Test', text: 'Test content', url: 'https://example.com' };
      await adapter.shareContent(content);

      expect(navigator.clipboard.writeText).toHaveBeenCalledWith('Test\nTest content\nhttps://example.com');
    });
  });

  describe('Layout measurements', () => {
    it('measures elements', async () => {
      const mockElement = {
        getBoundingClientRect: jest.fn().mockReturnValue({
          width: 100,
          height: 50,
          left: 10,
          top: 20
        })
      };

      const result = await adapter.measureElement(mockElement as any);
      expect(result).toEqual({ width: 100, height: 50, x: 10, y: 20 });
    });
  });

  describe('Animation', () => {
    it('creates animations', () => {
      const config = { duration: 500, easing: 'ease-in-out' };
      const animation = adapter.createAnimation(config);

      expect(animation).toEqual({
        duration: 500,
        easing: 'ease-in-out',
        fill: 'forwards'
      });
    });
  });

  describe('File system', () => {
    it('reads files', async () => {
      const mockFile = new File(['test content'], 'test.txt', { type: 'text/plain' });
      const result = await adapter.readFile(mockFile as any);
      expect(result).toBe('test content');
    });

    it('writes files', async () => {
      const mockCreateObjectURL = jest.spyOn(URL, 'createObjectURL').mockReturnValue('mock-url');
      const mockRevokeObjectURL = jest.spyOn(URL, 'revokeObjectURL').mockImplementation();

      const mockLink = {
        href: '',
        download: '',
        click: jest.fn()
      };
      const mockCreateElement = jest.spyOn(document, 'createElement').mockReturnValue(mockLink as any);
      const mockAppendChild = jest.spyOn(document.body, 'appendChild').mockImplementation();
      const mockRemoveChild = jest.spyOn(document.body, 'removeChild').mockImplementation();

      await adapter.writeFile('test.txt', 'test content');

      expect(mockCreateElement).toHaveBeenCalledWith('a');
      expect(mockLink.download).toBe('test.txt');
      expect(mockLink.click).toHaveBeenCalled();

      mockCreateObjectURL.mockRestore();
      mockRevokeObjectURL.mockRestore();
      mockCreateElement.mockRestore();
      mockAppendChild.mockRestore();
      mockRemoveChild.mockRestore();
    });
  });

  describe('Platform info', () => {
    it('gets device info', () => {
      const info = adapter.getDeviceInfo();
      expect(info).toHaveProperty('model');
      expect(info).toHaveProperty('brand', 'Web');
      expect(info).toHaveProperty('osVersion');
      expect(info).toHaveProperty('appVersion');
    });
  });
});

/**
 * Button component tests
 */

import React from 'react';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { Button } from '../../src/components/Button';
import { ThemeProvider } from '../../src/components/ThemeProvider';

const renderButton = (props = {}) => {
  return render(
    <ThemeProvider>
      <Button {...props}>Test Button</Button>
    </ThemeProvider>
  );
};

describe('Button', () => {
  it('renders correctly', () => {
    renderButton();
    expect(screen.getByRole('button')).toBeInTheDocument();
    expect(screen.getByText('Test Button')).toBeInTheDocument();
  });

  it('handles click events', async () => {
    const handleClick = jest.fn();
    renderButton({ onClick: handleClick });

    const button = screen.getByRole('button');
    await userEvent.click(button);

    expect(handleClick).toHaveBeenCalledTimes(1);
  });

  it('supports different variants', () => {
    const { rerender } = renderButton({ variant: 'primary' });
    expect(screen.getByRole('button')).toHaveClass('ui-button--primary');

    rerender(
      <ThemeProvider>
        <Button variant="secondary">Test Button</Button>
      </ThemeProvider>
    );
    expect(screen.getByRole('button')).toHaveClass('ui-button--secondary');
  });

  it('supports different sizes', () => {
    const { rerender } = renderButton({ size: 'sm' });
    expect(screen.getByRole('button')).toHaveClass('ui-button--sm');

    rerender(
      <ThemeProvider>
        <Button size="lg">Test Button</Button>
      </ThemeProvider>
    );
    expect(screen.getByRole('button')).toHaveClass('ui-button--lg');
  });

  it('shows loading state', () => {
    renderButton({ loading: true });
    const button = screen.getByRole('button');
    expect(button).toBeDisabled();
    expect(button).toHaveClass('ui-button--loading');
  });

  it('can be disabled', () => {
    renderButton({ disabled: true });
    const button = screen.getByRole('button');
    expect(button).toBeDisabled();
    expect(button).toHaveClass('ui-button--disabled');
  });

  it('supports icons', () => {
    renderButton({ icon: '🚀', iconPosition: 'left' });
    expect(screen.getByText('🚀')).toBeInTheDocument();
  });

  it('supports full width', () => {
    renderButton({ fullWidth: true });
    expect(screen.getByRole('button')).toHaveClass('ui-button--full-width');
  });

  it('handles keyboard navigation', async () => {
    const handleClick = jest.fn();
    renderButton({ onClick: handleClick });

    const button = screen.getByRole('button');
    button.focus();

    await userEvent.keyboard('{Enter}');
    expect(handleClick).toHaveBeenCalledTimes(1);

    await userEvent.keyboard(' ');
    expect(handleClick).toHaveBeenCalledTimes(2);
  });

  it('supports accessibility attributes', () => {
    renderButton({ 
      'aria-label': 'Custom button label',
      'aria-describedby': 'button-description'
    });

    const button = screen.getByRole('button');
    expect(button).toHaveAttribute('aria-label', 'Custom button label');
    expect(button).toHaveAttribute('aria-describedby', 'button-description');
  });

  it('prevents multiple clicks when loading', async () => {
    const handleClick = jest.fn();
    renderButton({ onClick: handleClick, loading: true });

    const button = screen.getByRole('button');
    await userEvent.click(button);
    await userEvent.click(button);

    expect(handleClick).not.toHaveBeenCalled();
  });

  it('applies custom className and styles', () => {
    renderButton({ 
      className: 'custom-button',
      style: { backgroundColor: 'red' }
    });

    const button = screen.getByRole('button');
    expect(button).toHaveClass('custom-button');
    expect(button).toHaveStyle({ backgroundColor: 'red' });
  });

  it('forwards ref correctly', () => {
    const ref = React.createRef<HTMLButtonElement>();
    render(
      <ThemeProvider>
        <Button ref={ref}>Test Button</Button>
      </ThemeProvider>
    );

    expect(ref.current).toBeInstanceOf(HTMLButtonElement);
  });
});

/**
 * GraphCanvas component tests
 */

import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { GraphCanvas } from '../../src/components/GraphCanvas';
import { ThemeProvider } from '../../src/components/ThemeProvider';

const mockGraph = {
  nodes: [
    {
      id: 'node1',
      type: 'WeightedChoice',
      data: { choices: [{ value: 'Option 1', weight: 1 }] },
      position: { x: 100, y: 100 }
    },
    {
      id: 'node2',
      type: 'Output',
      data: { text: 'Hello World' },
      position: { x: 300, y: 100 }
    }
  ],
  edges: [
    {
      id: 'edge1',
      source: 'node1',
      target: 'node2'
    }
  ]
};

const renderGraphCanvas = (props = {}) => {
  return render(
    <ThemeProvider>
      <GraphCanvas 
        graph={mockGraph}
        onNodeSelect={jest.fn()}
        onNodeMove={jest.fn()}
        onEdgeCreate={jest.fn()}
        onEdgeDelete={jest.fn()}
        {...props}
      />
    </ThemeProvider>
  );
};

describe('GraphCanvas', () => {
  it('renders graph nodes', () => {
    renderGraphCanvas();
    expect(screen.getByText('WeightedChoice')).toBeInTheDocument();
    expect(screen.getByText('Output')).toBeInTheDocument();
  });

  it('renders graph edges', () => {
    renderGraphCanvas();
    const svg = document.querySelector('svg.ui-graph-edges');
    expect(svg).toBeInTheDocument();

    const edges = svg?.querySelectorAll('line');
    expect(edges).toHaveLength(1);
  });

  it('calls onNodeSelect when node is clicked', async () => {
    const handleNodeSelect = jest.fn();
    renderGraphCanvas({ onNodeSelect: handleNodeSelect });

    const node = screen.getByText('WeightedChoice').closest('.ui-graph-node');
    if (node) {
      await userEvent.click(node);
      expect(handleNodeSelect).toHaveBeenCalledWith(expect.objectContaining({
        id: 'node1',
        type: 'WeightedChoice'
      }));
    }
  });

  it('shows selected node with highlight', () => {
    renderGraphCanvas({ selectedNodeId: 'node1' });
    const selectedNode = screen.getByText('WeightedChoice').closest('.ui-graph-node');
    expect(selectedNode).toHaveClass('ui-graph-node--selected');
  });

  it('shows zoom controls when enabled', () => {
    renderGraphCanvas({ showControls: true });
    expect(screen.getByText('🔍+')).toBeInTheDocument();
    expect(screen.getByText('🔍-')).toBeInTheDocument();
    expect(screen.getByText('🎯')).toBeInTheDocument();
    expect(screen.getByText('📐')).toBeInTheDocument();
  });

  it('hides controls when disabled', () => {
    renderGraphCanvas({ showControls: false });
    expect(screen.queryByText('🔍+')).not.toBeInTheDocument();
  });

  it('shows minimap when enabled', () => {
    renderGraphCanvas({ showMinimap: true });
    expect(screen.getByText('Minimap')).toBeInTheDocument();
  });

  it('shows status info', () => {
    renderGraphCanvas();
    expect(screen.getByText(/Nodes: 2/)).toBeInTheDocument();
    expect(screen.getByText(/Edges: 1/)).toBeInTheDocument();
    expect(screen.getByText(/Zoom: 100%/)).toBeInTheDocument();
  });

  it('handles zoom controls', async () => {
    renderGraphCanvas({ showControls: true });

    const zoomInButton = screen.getByText('🔍+');
    const zoomOutButton = screen.getByText('🔍-');

    await userEvent.click(zoomInButton);
    expect(screen.getByText(/Zoom: 120%/)).toBeInTheDocument();

    await userEvent.click(zoomOutButton);
    expect(screen.getByText(/Zoom: 100%/)).toBeInTheDocument();
  });

  it('handles wheel zoom', () => {
    renderGraphCanvas();
    const canvas = screen.getByRole('generic', { hidden: true });

    fireEvent.wheel(canvas, { deltaY: -100 });
    expect(screen.getByText(/Zoom: 110%/)).toBeInTheDocument();

    fireEvent.wheel(canvas, { deltaY: 100 });
    expect(screen.getByText(/Zoom: 100%/)).toBeInTheDocument();
  });

  it('supports readonly mode', () => {
    renderGraphCanvas({ readOnly: true });
    const nodes = document.querySelectorAll('.ui-graph-node');

    nodes.forEach(node => {
      expect(node).toHaveStyle({ cursor: 'pointer' });
    });

    // Connection handles should not be visible in readonly mode
    const connectionHandles = document.querySelectorAll('.ui-connection-handle');
    expect(connectionHandles).toHaveLength(0);
  });

  it('shows connection handles in edit mode', () => {
    renderGraphCanvas({ readOnly: false });
    const connectionHandles = document.querySelectorAll('.ui-connection-handle');
    expect(connectionHandles.length).toBeGreaterThan(0);
  });

  it('handles mouse interactions for panning', () => {
    renderGraphCanvas();
    const container = document.querySelector('.ui-graph-canvas-container');

    if (container) {
      fireEvent.mouseDown(container, { clientX: 100, clientY: 100 });
      fireEvent.mouseMove(container, { clientX: 110, clientY: 110, movementX: 10, movementY: 10 });
      fireEvent.mouseUp(container);
    }

    // Pan functionality would be tested through viewport state changes
  });

  it('applies node type-specific styling', () => {
    renderGraphCanvas();

    const weightedChoiceNode = screen.getByText('WeightedChoice').closest('.ui-graph-node');
    const outputNode = screen.getByText('Output').closest('.ui-graph-node');

    // Different node types should have different border colors
    expect(weightedChoiceNode).toHaveStyle({ borderColor: expect.any(String) });
    expect(outputNode).toHaveStyle({ borderColor: expect.any(String) });
  });

  it('handles empty graph', () => {
    renderGraphCanvas({ graph: { nodes: [], edges: [] } });
    expect(screen.getByText(/Nodes: 0/)).toBeInTheDocument();
    expect(screen.getByText(/Edges: 0/)).toBeInTheDocument();
  });

  it('supports custom className and styles', () => {
    renderGraphCanvas({ 
      className: 'custom-canvas',
      style: { backgroundColor: 'red' }
    });

    const canvas = document.querySelector('.ui-graph-canvas');
    expect(canvas).toHaveClass('custom-canvas');
    expect(canvas).toHaveStyle({ backgroundColor: 'red' });
  });
});

