/**
 * Mock IntersectionObserver for lazy loading tests
 */
export class MockIntersectionObserver {
  private callback: IntersectionObserverCallback;
  private elements: Set<Element> = new Set();

  constructor(callback: IntersectionObserverCallback) {
    this.callback = callback;
  }

  observe(element: Element) {
    this.elements.add(element);
    // Simulate immediate intersection
    this.callback([{
      target: element,
      isIntersecting: true,
      intersectionRatio: 1,
      boundingClientRect: element.getBoundingClientRect(),
      intersectionRect: element.getBoundingClientRect(),
      rootBounds: null,
      time: Date.now()
    }], this);
  }

  unobserve(element: Element) {
    this.elements.delete(element);
  }

  disconnect() {
    this.elements.clear();
  }
}

global.IntersectionObserver = MockIntersectionObserver as any;

/**
 * Mock ResizeObserver for responsive tests
 */
export class MockResizeObserver {
  private callback: ResizeObserverCallback;
  private elements: Set<Element> = new Set();

  constructor(callback: ResizeObserverCallback) {
    this.callback = callback;
  }

  observe(element: Element) {
    this.elements.add(element);
    // Simulate resize
    this.callback([{
      target: element,
      contentRect: element.getBoundingClientRect(),
      borderBoxSize: [{ inlineSize: 100, blockSize: 100 }],
      contentBoxSize: [{ inlineSize: 100, blockSize: 100 }],
      devicePixelContentBoxSize: [{ inlineSize: 100, blockSize: 100 }]
    }], this);
  }

  unobserve(element: Element) {
    this.elements.delete(element);
  }

  disconnect() {
    this.elements.clear();
  }
}

global.ResizeObserver = MockResizeObserver as any;

/**
 * Mock touch events
 */
export function createTouchEvent(
  type: string,
  touches: Array<{ clientX: number; clientY: number; identifier: number }>
): TouchEvent {
  const touchList = {
    length: touches.length,
    item: (index: number) => touches[index],
    ...touches.reduce((acc, touch, index) => ({ ...acc, [index]: touch }), {})
  } as unknown as TouchList;

  return new Event(type, { bubbles: true }) as TouchEvent & {
    touches: TouchList;
    changedTouches: TouchList;
    targetTouches: TouchList;
  };
}

