/**
 * Platform Provider for managing platform-specific adaptations
 */

import React, { createContext, useContext, useMemo } from 'react';
import { Platform, DeviceCapabilities } from '../types';
import { detectPlatform } from '../platform';

interface PlatformContextValue {
  platform: Platform;
  capabilities: DeviceCapabilities;
  isWeb: boolean;
  isMobile: boolean;
  isDesktop: boolean;
  isReactNative: boolean;
}

const PlatformContext = createContext<PlatformContextValue | null>(null);

interface PlatformProviderProps {
  children: React.ReactNode;
  platform?: Platform;
  capabilities?: Partial<DeviceCapabilities>;
}

export const PlatformProvider: React.FC<PlatformProviderProps> = ({
  children,
  platform: overridePlatform,
  capabilities: overrideCapabilities
}) => {
  const detectedPlatform = useMemo(() => {
    return overridePlatform || detectPlatform();
  }, [overridePlatform]);

  const defaultCapabilities: DeviceCapabilities = useMemo(() => {
    const isWebPlatform = detectedPlatform === 'web';
    const isMobilePlatform = detectedPlatform === 'mobile';

    return {
      touchSupport: isMobilePlatform || (typeof window !== 'undefined' && 'ontouchstart' in window),
      hoverSupport: !isMobilePlatform && (typeof window !== 'undefined' && window.matchMedia('(hover: hover)').matches),
      keyboardSupport: true,
      maxViewportWidth: typeof window !== 'undefined' ? window.screen.width : 1920,
      maxViewportHeight: typeof window !== 'undefined' ? window.screen.height : 1080,
      pixelRatio: typeof window !== 'undefined' ? window.devicePixelRatio : 1,
      ...overrideCapabilities
    };
  }, [detectedPlatform, overrideCapabilities]);

  const contextValue: PlatformContextValue = useMemo(() => ({
    platform: detectedPlatform,
    capabilities: defaultCapabilities,
    isWeb: detectedPlatform === 'web',
    isMobile: detectedPlatform === 'mobile',
    isDesktop: detectedPlatform === 'desktop',
    isReactNative: false // Will be overridden by React Native adapter
  }), [detectedPlatform, defaultCapabilities]);

  return (
    <PlatformContext.Provider value={contextValue}>
      {children}
    </PlatformContext.Provider>
  );
};

export const usePlatformContext = (): PlatformContextValue => {
  const context = useContext(PlatformContext);
  if (!context) {
    throw new Error('usePlatformContext must be used within a PlatformProvider');
  }
  return context;
};

/**
 * React Native platform adapter implementation
 */

import { PlatformAdapter } from './usePlatformAdapter';

export class ReactNativeAdapter implements PlatformAdapter {
  // Event handling
  handlePress = (callback: () => void) => ({
    onPress: callback
  });

  handleLongPress = (callback: () => void) => ({
    onLongPress: callback
  });

  handleHover = (callback: () => void) => {
    // React Native doesn't have hover events on mobile
    return {};
  };

  // Styling
  createStyleSheet = (styles: any) => {
    // In React Native, we would use StyleSheet.create()
    // For now, returning styles as-is for cross-platform compatibility
    try {
      // Try to import StyleSheet if available
      const StyleSheet = require('react-native').StyleSheet;
      return StyleSheet.create(styles);
    } catch {
      return styles;
    }
  };

  resolveStyle = (style: any) => {
    if (Array.isArray(style)) {
      return style; // React Native handles array styles natively
    }
    return style;
  };

  // Navigation
  openUrl = (url: string) => {
    try {
      const { Linking } = require('react-native');
      Linking.openURL(url);
    } catch (error) {
      console.warn('Failed to open URL:', error);
    }
  };

  goBack = () => {
    try {
      const { BackHandler } = require('react-native');
      BackHandler.exitApp();
    } catch (error) {
      console.warn('Failed to go back:', error);
    }
  };

  // Storage (using AsyncStorage)
  getStorageItem = async (key: string): Promise<string | null> => {
    try {
      const AsyncStorage = require('@react-native-async-storage/async-storage').default;
      return await AsyncStorage.getItem(key);
    } catch {
      return null;
    }
  };

  setStorageItem = async (key: string, value: string): Promise<void> => {
    try {
      const AsyncStorage = require('@react-native-async-storage/async-storage').default;
      await AsyncStorage.setItem(key, value);
    } catch (error) {
      console.warn('Failed to set storage item:', error);
    }
  };

  removeStorageItem = async (key: string): Promise<void> => {
    try {
      const AsyncStorage = require('@react-native-async-storage/async-storage').default;
      await AsyncStorage.removeItem(key);
    } catch (error) {
      console.warn('Failed to remove storage item:', error);
    }
  };

  // Device features
  hapticFeedback = (type: 'light' | 'medium' | 'heavy' = 'light') => {
    try {
      const { HapticFeedback } = require('react-native');
      const feedbackTypes = {
        light: HapticFeedback.HapticFeedbackTypes.impactLight,
        medium: HapticFeedback.HapticFeedbackTypes.impactMedium,
        heavy: HapticFeedback.HapticFeedbackTypes.impactHeavy
      };
      HapticFeedback.trigger(feedbackTypes[type]);
    } catch (error) {
      console.warn('Haptic feedback not available:', error);
    }
  };

  copyToClipboard = async (text: string): Promise<void> => {
    try {
      const { Clipboard } = require('react-native');
      await Clipboard.setString(text);
    } catch (error) {
      console.warn('Failed to copy to clipboard:', error);
      throw error;
    }
  };

  shareContent = async (content: { title?: string; text?: string; url?: string }): Promise<void> => {
    try {
      const { Share } = require('react-native');
      await Share.share({
        title: content.title,
        message: content.text || content.url || '',
        url: content.url
      });
    } catch (error) {
      console.warn('Failed to share content:', error);
      throw error;
    }
  };

  // Layout measurements
  measureElement = async (element: any): Promise<{ width: number; height: number; x: number; y: number }> => {
    return new Promise((resolve) => {
      if (element && element.measure) {
        element.measure((x: number, y: number, width: number, height: number) => {
          resolve({ width, height, x, y });
        });
      } else {
        resolve({ width: 0, height: 0, x: 0, y: 0 });
      }
    });
  };

  // Animation (using React Native Animated API)
  createAnimation = (config: {
    duration?: number;
    easing?: any;
    useNativeDriver?: boolean;
  }) => {
    try {
      const { Animated, Easing } = require('react-native');
      return {
        duration: config.duration || 300,
        easing: config.easing || Easing.ease,
        useNativeDriver: config.useNativeDriver !== false
      };
    } catch {
      return config;
    }
  };

  // Platform-specific components (React Native implementations)
  get ScrollView() {
    try {
      return require('react-native').ScrollView;
    } catch {
      return 'div'; // Fallback for web
    }
  }

  get SafeAreaView() {
    try {
      return require('react-native').SafeAreaView;
    } catch {
      return 'div'; // Fallback for web
    }
  }

  get StatusBar() {
    try {
      return require('react-native').StatusBar;
    } catch {
      return null; // Not available on web
    }
  }

  get KeyboardAvoidingView() {
    try {
      return require('react-native').KeyboardAvoidingView;
    } catch {
      return 'div'; // Fallback for web
    }
  }

  // File system (React Native File System)
  readFile = async (path: string): Promise<string> => {
    try {
      const RNFS = require('react-native-fs');
      return await RNFS.readFile(path, 'utf8');
    } catch (error) {
      console.warn('Failed to read file:', error);
      throw error;
    }
  };

  writeFile = async (path: string, content: string): Promise<void> => {
    try {
      const RNFS = require('react-native-fs');
      await RNFS.writeFile(path, content, 'utf8');
    } catch (error) {
      console.warn('Failed to write file:', error);
      throw error;
    }
  };

  // Network
  fetch = fetch;

  // Platform info
  getDeviceInfo = () => {
    try {
      const { Platform } = require('react-native');
      const DeviceInfo = require('react-native-device-info');

      return {
        model: DeviceInfo.getModel(),
        brand: DeviceInfo.getBrand(),
        osVersion: Platform.Version,
        appVersion: DeviceInfo.getVersion()
      };
    } catch {
      return {
        model: 'Unknown',
        brand: 'React Native',
        osVersion: 'Unknown',
        appVersion: '1.0.0'
      };
    }
  };
}

/**
 * Web platform adapter implementation
 */

import { PlatformAdapter } from './usePlatformAdapter';

export class WebAdapter implements PlatformAdapter {
  // Event handling
  handlePress = (callback: () => void) => ({
    onClick: callback,
    onKeyDown: (e: KeyboardEvent) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        callback();
      }
    }
  });

  handleLongPress = (callback: () => void) => {
    let timeout: NodeJS.Timeout;
    return {
      onMouseDown: () => {
        timeout = setTimeout(callback, 500);
      },
      onMouseUp: () => {
        clearTimeout(timeout);
      },
      onMouseLeave: () => {
        clearTimeout(timeout);
      }
    };
  };

  handleHover = (callback: () => void) => ({
    onMouseEnter: callback
  });

  // Styling
  createStyleSheet = (styles: any) => styles; // Web doesn't need stylesheet compilation

  resolveStyle = (style: any) => {
    if (Array.isArray(style)) {
      return Object.assign({}, ...style);
    }
    return style;
  };

  // Navigation
  openUrl = (url: string) => {
    window.open(url, '_blank', 'noopener,noreferrer');
  };

  goBack = () => {
    if (window.history.length > 1) {
      window.history.back();
    }
  };

  // Storage (using localStorage)
  getStorageItem = async (key: string): Promise<string | null> => {
    try {
      return localStorage.getItem(key);
    } catch {
      return null;
    }
  };

  setStorageItem = async (key: string, value: string): Promise<void> => {
    try {
      localStorage.setItem(key, value);
    } catch (error) {
      console.warn('Failed to set storage item:', error);
    }
  };

  removeStorageItem = async (key: string): Promise<void> => {
    try {
      localStorage.removeItem(key);
    } catch (error) {
      console.warn('Failed to remove storage item:', error);
    }
  };

  // Device features
  hapticFeedback = (type: 'light' | 'medium' | 'heavy' = 'light') => {
    // Web vibration API (if available)
    if ('vibrate' in navigator) {
      const patterns = {
        light: 10,
        medium: 20,
        heavy: 50
      };
      navigator.vibrate(patterns[type]);
    }
  };

  copyToClipboard = async (text: string): Promise<void> => {
    try {
      if (navigator.clipboard) {
        await navigator.clipboard.writeText(text);
      } else {
        // Fallback for older browsers
        const textArea = document.createElement('textarea');
        textArea.value = text;
        document.body.appendChild(textArea);
        textArea.select();
        document.execCommand('copy');
        document.body.removeChild(textArea);
      }
    } catch (error) {
      console.warn('Failed to copy to clipboard:', error);
      throw error;
    }
  };

  shareContent = async (content: { title?: string; text?: string; url?: string }): Promise<void> => {
    try {
      if (navigator.share) {
        await navigator.share(content);
      } else {
        // Fallback: copy to clipboard
        const shareText = `${content.title || ''}\n${content.text || ''}\n${content.url || ''}`.trim();
        await this.copyToClipboard(shareText);
      }
    } catch (error) {
      console.warn('Failed to share content:', error);
      throw error;
    }
  };

  // Layout measurements
  measureElement = async (element: HTMLElement): Promise<{ width: number; height: number; x: number; y: number }> => {
    return new Promise((resolve) => {
      if (element.getBoundingClientRect) {
        const rect = element.getBoundingClientRect();
        resolve({
          width: rect.width,
          height: rect.height,
          x: rect.left,
          y: rect.top
        });
      } else {
        resolve({ width: 0, height: 0, x: 0, y: 0 });
      }
    });
  };

  // Animation (using Web Animations API or CSS transitions)
  createAnimation = (config: {
    duration?: number;
    easing?: string;
    fill?: 'forwards' | 'backwards' | 'both';
  }) => {
    return {
      duration: config.duration || 300,
      easing: config.easing || 'ease',
      fill: config.fill || 'forwards'
    };
  };

  // Platform-specific components (Web implementations)
  ScrollView = 'div';
  SafeAreaView = 'div';
  StatusBar = null;
  KeyboardAvoidingView = 'div';

  // File system (Web File API)
  readFile = async (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = reject;
      reader.readAsText(file);
    });
  };

  writeFile = async (filename: string, content: string): Promise<void> => {
    // Web download implementation
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  // Network
  fetch = fetch.bind(window);

  // Platform info
  getDeviceInfo = () => {
    const userAgent = navigator.userAgent;
    const platform = navigator.platform;

    return {
      model: platform,
      brand: 'Web',
      osVersion: userAgent,
      appVersion: typeof process !== 'undefined' ? process.env.npm_package_version : '1.0.0'
    };
  };
}

/**
 * React Native-specific Button implementation
 */

import React from 'react';
import { Button, ButtonProps } from '../../components/Button';
import { usePlatformAdapter } from '../usePlatformAdapter';

export interface RNButtonProps extends ButtonProps {
  hapticFeedback?: 'light' | 'medium' | 'heavy';
  accessibilityRole?: string;
  accessibilityHint?: string;
  testID?: string;
}

export const RNButton: React.FC<RNButtonProps> = ({
  hapticFeedback,
  accessibilityRole = 'button',
  accessibilityHint,
  testID,
  onClick,
  onLongPress,
  children,
  ...props
}) => {
  const adapter = usePlatformAdapter();

  const handlePress = () => {
    // Haptic feedback on button press
    if (hapticFeedback) {
      adapter.hapticFeedback(hapticFeedback);
    }

    onClick?.();
  };

  const handleLongPress = () => {
    // Stronger haptic feedback for long press
    adapter.hapticFeedback('medium');
    onLongPress?.();
  };

  // Convert web-style props to React Native props
  const rnProps = {
    ...adapter.handlePress(handlePress),
    ...(onLongPress && adapter.handleLongPress(handleLongPress)),
    accessibilityRole,
    accessibilityLabel: props['aria-label'],
    accessibilityHint,
    testID: testID || props.testId,
    // React Native specific styling
    style: {
      ...props.style,
      // Ensure proper touch target size (minimum 44x44 points)
      minHeight: 44,
      minWidth: 44,
      // Remove web-specific properties
      transition: undefined,
      userSelect: undefined,
      WebkitTapHighlightColor: undefined
    }
  };

  return (
    <Button
      {...props}
      {...rnProps}
      style={rnProps.style}
    >
      {children}
    </Button>
  );
};

/**
 * React Native-specific GraphCanvas implementation
 */

import React, { useRef, useState, useCallback } from 'react';
import { GraphCanvas, GraphCanvasProps } from '../../components/GraphCanvas';
import { usePlatformAdapter } from '../usePlatformAdapter';

export interface RNGraphCanvasProps extends GraphCanvasProps {
  enablePinchZoom?: boolean;
  enableDoubleTapZoom?: boolean;
  enableRotation?: boolean;
  minimumZoomScale?: number;
  maximumZoomScale?: number;
  bounces?: boolean;
  bouncesZoom?: boolean;
  scrollEnabled?: boolean;
  zoomEnabled?: boolean;
  testID?: string;
}

export const RNGraphCanvas: React.FC<RNGraphCanvasProps> = ({
  enablePinchZoom = true,
  enableDoubleTapZoom = true,
  enableRotation = false,
  minimumZoomScale = 0.1,
  maximumZoomScale = 3,
  bounces = true,
  bouncesZoom = true,
  scrollEnabled = true,
  zoomEnabled = true,
  testID,
  onNodeSelect,
  onNodeMove,
  onEdgeCreate,
  onEdgeDelete,
  ...props
}) => {
  const adapter = usePlatformAdapter();
  const [gestureState, setGestureState] = useState({
    scale: 1,
    translateX: 0,
    translateY: 0,
    rotation: 0
  });

  // Try to use React Native gesture handling if available
  let PanGestureHandler, PinchGestureHandler, TapGestureHandler;
  try {
    const GestureHandler = require('react-native-gesture-handler');
    PanGestureHandler = GestureHandler.PanGestureHandler;
    PinchGestureHandler = GestureHandler.PinchGestureHandler;
    TapGestureHandler = GestureHandler.TapGestureHandler;
  } catch {
    // Fallback to basic touch handling
    PanGestureHandler = 'div';
    PinchGestureHandler = 'div';
    TapGestureHandler = 'div';
  }

  // Gesture handlers
  const handlePanGesture = useCallback((event: any) => {
    if (!scrollEnabled) return;

    const { translationX, translationY } = event.nativeEvent;
    setGestureState(prev => ({
      ...prev,
      translateX: prev.translateX + translationX,
      translateY: prev.translateY + translationY
    }));
  }, [scrollEnabled]);

  const handlePinchGesture = useCallback((event: any) => {
    if (!zoomEnabled || !enablePinchZoom) return;

    const { scale } = event.nativeEvent;
    const clampedScale = Math.max(minimumZoomScale, Math.min(maximumZoomScale, scale));

    setGestureState(prev => ({
      ...prev,
      scale: clampedScale
    }));
  }, [zoomEnabled, enablePinchZoom, minimumZoomScale, maximumZoomScale]);

  const handleDoubleTap = useCallback(() => {
    if (!enableDoubleTapZoom) return;

    // Toggle between fit-to-screen and 1:1 zoom
    const targetScale = gestureState.scale === 1 ? 2 : 1;
    setGestureState(prev => ({
      ...prev,
      scale: targetScale,
      translateX: targetScale === 1 ? 0 : prev.translateX,
      translateY: targetScale === 1 ? 0 : prev.translateY
    }));

    // Haptic feedback for double tap
    adapter.hapticFeedback('light');
  }, [enableDoubleTapZoom, gestureState.scale, adapter]);

  const handleNodePress = useCallback((node: any) => {
    // Haptic feedback for node selection
    adapter.hapticFeedback('light');
    onNodeSelect?.(node);
  }, [onNodeSelect, adapter]);

  const handleLongPress = useCallback((node: any) => {
    // Stronger haptic feedback for long press
    adapter.hapticFeedback('medium');
    // Could show context menu or enter edit mode
  }, [adapter]);

  // React Native specific touch handling
  const touchProps = {
    onTouchStart: (e: any) => {
      // Handle touch start
    },
    onTouchMove: (e: any) => {
      // Handle touch move for node dragging
      if (props.readOnly) return;

      // Touch-based node dragging logic
    },
    onTouchEnd: (e: any) => {
      // Handle touch end
    }
  };

  const containerStyle = {
    flex: 1,
    backgroundColor: 'transparent',
    // Apply gesture transformations
    transform: [
      { scale: gestureState.scale },
      { translateX: gestureState.translateX },
      { translateY: gestureState.translateY },
      ...(enableRotation ? [{ rotate: `${gestureState.rotation}deg` }] : [])
    ]
  };

  // Enhanced GraphCanvas with React Native optimizations
  const enhancedProps = {
    ...props,
    onNodeSelect: handleNodePress,
    onNodeMove,
    onEdgeCreate,
    onEdgeDelete,
    style: {
      ...props.style,
      // React Native specific styling
      flex: 1,
      // Remove web-specific properties
      cursor: undefined,
      userSelect: undefined,
      WebkitUserSelect: undefined
    }
  };

  if (PanGestureHandler !== 'div' && PinchGestureHandler !== 'div') {
    // Use React Native Gesture Handler if available
    return (
      <PanGestureHandler onGestureEvent={handlePanGesture}>
        <PinchGestureHandler onGestureEvent={handlePinchGesture}>
          <TapGestureHandler numberOfTaps={2} onActivated={handleDoubleTap}>
            <div style={containerStyle} testID={testID}>
              <GraphCanvas {...enhancedProps} />
            </div>
          </TapGestureHandler>
        </PinchGestureHandler>
      </PanGestureHandler>
    );
  }

  // Fallback to basic touch handling
  return (
    <div 
      style={containerStyle}
      testID={testID}
      {...touchProps}
    >
      <GraphCanvas {...enhancedProps} />

      {/* Touch-friendly controls overlay */}
      <div
        style={{
          position: 'absolute',
          bottom: 20,
          right: 20,
          flexDirection: 'column'
        }}
      >
        {/* Zoom controls optimized for touch */}
        <div
          style={{
            width: 60,
            height: 60,
            borderRadius: 30,
            backgroundColor: 'rgba(0, 0, 0, 0.7)',
            justifyContent: 'center',
            alignItems: 'center',
            marginBottom: 10
          }}
          onTouchEnd={() => {
            adapter.hapticFeedback('light');
            // Zoom in
            const newScale = Math.min(maximumZoomScale, gestureState.scale * 1.2);
            setGestureState(prev => ({ ...prev, scale: newScale }));
          }}
        >
          <span style={{ color: 'white', fontSize: 24 }}>+</span>
        </div>

        <div
          style={{
            width: 60,
            height: 60,
            borderRadius: 30,
            backgroundColor: 'rgba(0, 0, 0, 0.7)',
            justifyContent: 'center',
            alignItems: 'center'
          }}
          onTouchEnd={() => {
            adapter.hapticFeedback('light');
            // Zoom out
            const newScale = Math.max(minimumZoomScale, gestureState.scale / 1.2);
            setGestureState(prev => ({ ...prev, scale: newScale }));
          }}
        >
          <span style={{ color: 'white', fontSize: 24 }}>−</span>
        </div>
      </div>
    </div>
  );
};

