  // Fallback to web implementation with React Native-like behavior
  // This would be similar to the WebSafeAreaView but with different detection logic
  const webSafeAreaStyle = {
    flex: 1,
    // Default safe area insets for mobile web
    paddingTop: edges.includes('top') ? 20 : 0,
    paddingBottom: edges.includes('bottom') ? 0 : 0,
    paddingLeft: edges.includes('left') ? 0 : 0,
    paddingRight: edges.includes('right') ? 0 : 0,
    ...style
  };

  return (
    <div 
      ref={ref}
      style={webSafeAreaStyle}
      data-testid={testID}
      {...props}
    >
      {children}
    </div>
  );
});

RNSafeAreaView.displayName = 'RNSafeAreaView';

/**
 * React Native-specific ScrollView implementation
 */

import React, { forwardRef } from 'react';

export interface RNScrollViewProps {
  children: React.ReactNode;
  horizontal?: boolean;
  showsVerticalScrollIndicator?: boolean;
  showsHorizontalScrollIndicator?: boolean;
  bounces?: boolean;
  pagingEnabled?: boolean;
  scrollEnabled?: boolean;
  keyboardShouldPersistTaps?: 'always' | 'never' | 'handled';
  contentContainerStyle?: any;
  style?: any;
  onScroll?: (event: any) => void;
  scrollEventThrottle?: number;
  decelerationRate?: 'normal' | 'fast' | number;
  maximumZoomScale?: number;
  minimumZoomScale?: number;
  pinchGestureEnabled?: boolean;
  zoomScale?: number;
  testID?: string;
}

export const RNScrollView = forwardRef<any, RNScrollViewProps>(({
  children,
  horizontal = false,
  showsVerticalScrollIndicator = true,
  showsHorizontalScrollIndicator = true,
  bounces = true,
  pagingEnabled = false,
  scrollEnabled = true,
  keyboardShouldPersistTaps = 'never',
  contentContainerStyle,
  style,
  onScroll,
  scrollEventThrottle = 16,
  decelerationRate = 'normal',
  maximumZoomScale = 1,
  minimumZoomScale = 1,
  pinchGestureEnabled = false,
  zoomScale = 1,
  testID,
  ...props
}, ref) => {
  // Try to use React Native ScrollView if available
  let RNScrollViewComponent;
  try {
    RNScrollViewComponent = require('react-native').ScrollView;
  } catch {
    // Fallback to web implementation
    RNScrollViewComponent = null;
  }

  const rnProps = {
    ref,
    horizontal,
    showsVerticalScrollIndicator,
    showsHorizontalScrollIndicator,
    bounces,
    pagingEnabled,
    scrollEnabled,
    keyboardShouldPersistTaps,
    contentContainerStyle,
    style,
    onScroll,
    scrollEventThrottle,
    decelerationRate,
    maximumZoomScale,
    minimumZoomScale,
    pinchGestureEnabled,
    zoomScale,
    testID,
    ...props
  };

  if (RNScrollViewComponent) {
    return (
      <RNScrollViewComponent {...rnProps}>
        {children}
      </RNScrollViewComponent>
    );
  }

  // Fallback to web implementation with React Native-like behavior
  const webScrollViewStyle = {
    flex: 1,
    overflow: scrollEnabled ? 'auto' : 'hidden',
    overflowX: horizontal ? 'auto' : 'hidden',
    overflowY: !horizontal ? 'auto' : 'hidden',
    // Simulate React Native scrolling behavior
    WebkitOverflowScrolling: 'touch',
    scrollbarWidth: showsVerticalScrollIndicator || showsHorizontalScrollIndicator ? 'thin' : 'none',
    msOverflowStyle: showsVerticalScrollIndicator || showsHorizontalScrollIndicator ? 'auto' : 'none',
    ...style
  };

  const webContentStyle = {
    display: horizontal ? 'flex' : 'block',
    flexDirection: horizontal ? 'row' : undefined,
    minWidth: horizontal ? 'max-content' : undefined,
    ...contentContainerStyle
  };

  return (
    <div 
      ref={ref}
      style={webScrollViewStyle}
      onScroll={onScroll}
      data-testid={testID}
      {...props}
    >
      <div style={webContentStyle}>
        {children}
      </div>
    </div>
  );
});

