export interface WebTextAreaProps extends TextAreaProps {
  autoComplete?: string;
  spellCheck?: boolean;
  autoCapitalize?: 'none' | 'sentences' | 'words' | 'characters';
  autoCorrect?: boolean;
  minLength?: number;
  maxLength?: number;
  wrap?: 'hard' | 'soft' | 'off';
}

export const WebTextArea: React.FC<WebTextAreaProps> = ({
  autoComplete = 'off',
  spellCheck = true,
  autoCapitalize = 'sentences',
  autoCorrect = true,
  minLength,
  maxLength,
  wrap = 'soft',
  onKeyDown,
  ...props
}) => {
  const textAreaRef = useRef<HTMLTextAreaElement>(null);

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    // Web-specific keyboard shortcuts for text areas
    if (e.ctrlKey || e.metaKey) {
      switch (e.key) {
        case 'Enter':
          // Ctrl+Enter for submit in some contexts
          e.preventDefault();
          // Could trigger onSubmit callback if provided
          break;
      }
    }

    // Tab handling for code editing
    if (e.key === 'Tab' && props.hint?.includes('code')) {
      e.preventDefault();
      const textarea = e.currentTarget;
      const start = textarea.selectionStart;
      const end = textarea.selectionEnd;
      const value = textarea.value;

      if (e.shiftKey) {
        // Remove indentation
        const beforeCursor = value.substring(0, start);
        const afterCursor = value.substring(end);
        const lines = beforeCursor.split('\n');
        const currentLine = lines[lines.length - 1];

        if (currentLine.startsWith('  ')) {
          lines[lines.length - 1] = currentLine.substring(2);
          const newValue = lines.join('\n') + afterCursor;
          textarea.value = newValue;
          textarea.setSelectionRange(start - 2, end - 2);
          props.onChange?.(newValue);
        }
      } else {
        // Add indentation
        const newValue = value.substring(0, start) + '  ' + value.substring(end);
        textarea.value = newValue;
        textarea.setSelectionRange(start + 2, end + 2);
        props.onChange?.(newValue);
      }
      return;
    }

    onKeyDown?.(e);
  };

  return (
    <TextArea
      {...props}
      ref={textAreaRef}
      onKeyDown={handleKeyDown}
      // Web-specific attributes
      autoComplete={autoComplete}
      spellCheck={spellCheck}
      autoCapitalize={autoCapitalize}
      autoCorrect={autoCorrect ? 'on' : 'off'}
      minLength={minLength}
      maxLength={maxLength}
      wrap={wrap}
      style={{
        ...props.style,
        // Web-specific styling
        WebkitTapHighlightColor: 'transparent',
        WebkitAppearance: 'none',
        resize: 'vertical'
      }}
    />
  );
};

/**
 * Web-specific Modal implementation with enhanced features
 */

import React, { useEffect, useCallback } from 'react';
import { Modal, ModalProps } from '../../components/Modal';
import { usePlatformAdapter } from '../usePlatformAdapter';

export interface WebModalProps extends ModalProps {
  backdrop?: 'static' | 'clickable';
  keyboard?: boolean;
  scrollable?: boolean;
  centered?: boolean;
  fullscreen?: boolean | 'sm' | 'md' | 'lg' | 'xl';
  animation?: boolean;
}

export const WebModal: React.FC<WebModalProps> = ({
  backdrop = 'clickable',
  keyboard = true,
  scrollable = true,
  centered = false,
  fullscreen = false,
  animation = true,
  isOpen,
  onClose,
  children,
  ...props
}) => {
  const adapter = usePlatformAdapter();

  // Enhanced escape key handling
  const handleEscapeKey = useCallback((e: KeyboardEvent) => {
    if (keyboard && e.key === 'Escape' && isOpen) {
      e.preventDefault();
      onClose();
    }
  }, [keyboard, isOpen, onClose]);

  useEffect(() => {
    if (isOpen) {
      document.addEventListener('keydown', handleEscapeKey);

      // Prevent body scroll when modal is open
      document.body.style.overflow = 'hidden';

      // Focus management - focus the modal when it opens
      const modal = document.querySelector('[data-modal="true"]') as HTMLElement;
      if (modal) {
        modal.focus();
      }
    } else {
      document.body.style.overflow = '';
    }

    return () => {
      document.removeEventListener('keydown', handleEscapeKey);
      document.body.style.overflow = '';
    };
  }, [isOpen, handleEscapeKey]);

  // Enhanced overlay click handling
  const handleOverlayClick = (e: React.MouseEvent) => {
    if (backdrop === 'clickable' && e.target === e.currentTarget) {
      onClose();
    }
  };

  // Browser history integration
  useEffect(() => {
    if (isOpen && typeof window !== 'undefined') {
      // Add a history entry when modal opens
      const handlePopState = () => {
        onClose();
      };

      window.addEventListener('popstate', handlePopState);
      window.history.pushState({ modal: true }, '');

      return () => {
        window.removeEventListener('popstate', handlePopState);
        // Clean up history state
        if (window.history.state?.modal) {
          window.history.back();
        }
      };
    }
  }, [isOpen, onClose]);

  const getModalSize = () => {
    if (fullscreen === true) return 'full';
    if (typeof fullscreen === 'string') return `fullscreen-${fullscreen}`;
    return props.size;
  };

  return (
    <Modal
      {...props}
      isOpen={isOpen}
      onClose={onClose}
      size={getModalSize()}
      closeOnOverlayClick={backdrop === 'clickable'}
      closeOnEscape={keyboard}
      style={{
        ...props.style,
        // Web-specific enhancements
        ...(animation && {
          transition: 'all 0.3s ease',
          opacity: isOpen ? 1 : 0,
          transform: isOpen ? 'scale(1)' : 'scale(0.95)'
        }),
        ...(centered && {
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center'
        }),
        ...(scrollable && {
          maxHeight: '90vh',
          overflow: 'auto'
        })
      }}
      data-modal="true"
      tabIndex={-1}
      role="dialog"
      aria-modal="true"
      onClick={handleOverlayClick}
    >
      {children}
    </Modal>
  );
};

/**
 * Web-specific SafeAreaView implementation
 */

import React, { forwardRef, useEffect, useState } from 'react';
import { useTheme } from '../../hooks';

export interface WebSafeAreaViewProps extends React.HTMLAttributes<HTMLDivElement> {
  edges?: ('top' | 'bottom' | 'left' | 'right')[];
  mode?: 'padding' | 'margin';
}

export const WebSafeAreaView = forwardRef<HTMLDivElement, WebSafeAreaViewProps>(({
  children,
  edges = ['top', 'bottom', 'left', 'right'],
  mode = 'padding',
  style,
  className,
  ...props
}, ref) => {
  const theme = useTheme();
  const [safeAreaInsets, setSafeAreaInsets] = useState({
    top: 0,
    bottom: 0,
    left: 0,
    right: 0
  });

  useEffect(() => {
    // Detect safe area insets using CSS environment variables
    const updateSafeAreaInsets = () => {
      if (typeof window !== 'undefined' && CSS.supports('top: env(safe-area-inset-top)')) {
        const computedStyle = getComputedStyle(document.documentElement);

        setSafeAreaInsets({
          top: parseInt(computedStyle.getPropertyValue('--safe-area-inset-top') || '0', 10),
          bottom: parseInt(computedStyle.getPropertyValue('--safe-area-inset-bottom') || '0', 10),
          left: parseInt(computedStyle.getPropertyValue('--safe-area-inset-left') || '0', 10),
          right: parseInt(computedStyle.getPropertyValue('--safe-area-inset-right') || '0', 10)
        });
      } else {
        // Fallback for browsers that don't support safe area insets
        // Detect if we're in a PWA or fullscreen mode
        const isStandalone = window.matchMedia('(display-mode: standalone)').matches ||
                            (window.navigator as any).standalone ||
                            document.referrer.includes('android-app://');

        if (isStandalone) {
          // Approximate safe area for common devices
          const userAgent = navigator.userAgent;

          if (/iPhone/.test(userAgent)) {
            // iPhone with notch detection
            const hasNotch = window.screen.height >= 812; // iPhone X and newer
            setSafeAreaInsets({
              top: hasNotch ? 44 : 20,
              bottom: hasNotch ? 34 : 0,
              left: 0,
              right: 0
            });
          } else {
            // Default for other devices
            setSafeAreaInsets({
              top: 24, // Status bar height
              bottom: 0,
              left: 0,
              right: 0
            });
          }
        }
      }
    };

    updateSafeAreaInsets();

    // Listen for orientation changes
    window.addEventListener('orientationchange', updateSafeAreaInsets);
    window.addEventListener('resize', updateSafeAreaInsets);

    return () => {
      window.removeEventListener('orientationchange', updateSafeAreaInsets);
      window.removeEventListener('resize', updateSafeAreaInsets);
    };
  }, []);

  const getSafeAreaStyle = (): React.CSSProperties => {
    const appliedInsets = {
      top: edges.includes('top') ? safeAreaInsets.top : 0,
      bottom: edges.includes('bottom') ? safeAreaInsets.bottom : 0,
      left: edges.includes('left') ? safeAreaInsets.left : 0,
      right: edges.includes('right') ? safeAreaInsets.right : 0
    };

    if (mode === 'padding') {
      return {
        paddingTop: `${appliedInsets.top}px`,
        paddingBottom: `${appliedInsets.bottom}px`,
        paddingLeft: `${appliedInsets.left}px`,
        paddingRight: `${appliedInsets.right}px`
      };
    } else {
      return {
        marginTop: `${appliedInsets.top}px`,
        marginBottom: `${appliedInsets.bottom}px`,
        marginLeft: `${appliedInsets.left}px`,
        marginRight: `${appliedInsets.right}px`
      };
    }
  };

  const safeAreaViewStyles: React.CSSProperties = {
    width: '100%',
    height: '100%',
    backgroundColor: theme.colors.background,
    ...getSafeAreaStyle(),
    ...style
  };

  return (
    <>
      {/* CSS custom properties for safe area insets */}
      <style jsx global>{`
        :root {
          --safe-area-inset-top: env(safe-area-inset-top, ${safeAreaInsets.top}px);
          --safe-area-inset-bottom: env(safe-area-inset-bottom, ${safeAreaInsets.bottom}px);
          --safe-area-inset-left: env(safe-area-inset-left, ${safeAreaInsets.left}px);
          --safe-area-inset-right: env(safe-area-inset-right, ${safeAreaInsets.right}px);
        }
      `}</style>

      <div
        ref={ref}
        className={`web-safe-area-view ${className || ''}`}
        style={safeAreaViewStyles}
        {...props}
      >
        {children}
      </div>
    </>
  );
});

WebSafeAreaView.displayName = 'WebSafeAreaView';

/**
 * Web-specific ScrollView implementation
 */

import React, { forwardRef } from 'react';
import { useTheme } from '../../hooks';

export interface WebScrollViewProps extends React.HTMLAttributes<HTMLDivElement> {
  horizontal?: boolean;
  showsVerticalScrollIndicator?: boolean;
  showsHorizontalScrollIndicator?: boolean;
  bounces?: boolean;
  pagingEnabled?: boolean;
  scrollEnabled?: boolean;
  contentContainerStyle?: React.CSSProperties;
  keyboardShouldPersistTaps?: 'always' | 'never' | 'handled';
}

export const WebScrollView = forwardRef<HTMLDivElement, WebScrollViewProps>(({
  children,
  horizontal = false,
  showsVerticalScrollIndicator = true,
  showsHorizontalScrollIndicator = true,
  bounces = true,
  pagingEnabled = false,
  scrollEnabled = true,
  contentContainerStyle,
  style,
  className,
  ...props
}, ref) => {
  const theme = useTheme();

  const scrollViewStyles: React.CSSProperties = {
    overflow: scrollEnabled ? 'auto' : 'hidden',
    overflowX: horizontal ? 'auto' : 'hidden',
    overflowY: !horizontal ? 'auto' : 'hidden',
    // Custom scrollbar styling
    scrollbarWidth: 'thin',
    scrollbarColor: `${theme.colors.border} ${theme.colors.surface}`,
    // Webkit scrollbar styling
    ...(!showsVerticalScrollIndicator && {
      scrollbarWidth: 'none',
      msOverflowStyle: 'none'
    }),
    ...(!showsHorizontalScrollIndicator && horizontal && {
      scrollbarWidth: 'none',
      msOverflowStyle: 'none'
    }),
    // Smooth scrolling
    scrollBehavior: 'smooth',
    // Momentum scrolling on iOS Safari
    WebkitOverflowScrolling: 'touch',
    // Paging
    ...(pagingEnabled && {
      scrollSnapType: horizontal ? 'x mandatory' : 'y mandatory'
    }),
    // Bouncing effect (approximated with CSS)
    ...(bounces && {
      overscrollBehavior: 'contain'
    }),
    ...style
  };

  const contentStyles: React.CSSProperties = {
    display: horizontal ? 'flex' : 'block',
    flexDirection: horizontal ? 'row' : undefined,
    minWidth: horizontal ? 'max-content' : undefined,
    minHeight: !horizontal ? 'max-content' : undefined,
    ...(pagingEnabled && {
      scrollSnapAlign: 'start'
    }),
    ...contentContainerStyle
  };

  return (
    <div
      ref={ref}
      className={`web-scroll-view ${className || ''}`}
      style={scrollViewStyles}
      {...props}
    >
      <div className="web-scroll-view-content" style={contentStyles}>
        {children}
      </div>

      {/* Custom scrollbar styles */}
      <style jsx>{`
        .web-scroll-view::-webkit-scrollbar {
          width: ${showsVerticalScrollIndicator ? '8px' : '0px'};
          height: ${showsHorizontalScrollIndicator ? '8px' : '0px'};
        }

        .web-scroll-view::-webkit-scrollbar-track {
          background: ${theme.colors.surface};
          border-radius: 4px;
        }

        .web-scroll-view::-webkit-scrollbar-thumb {
          background: ${theme.colors.border};
          border-radius: 4px;
          transition: background-color 0.2s ease;
        }

        .web-scroll-view::-webkit-scrollbar-thumb:hover {
          background: ${theme.colors.textSecondary};
        }

        .web-scroll-view::-webkit-scrollbar-corner {
          background: ${theme.colors.surface};
        }

        ${!showsVerticalScrollIndicator ? `
          .web-scroll-view::-webkit-scrollbar:vertical {
            display: none;
          }
        ` : ''}

        ${!showsHorizontalScrollIndicator ? `
          .web-scroll-view::-webkit-scrollbar:horizontal {
            display: none;
          }
        ` : ''}
      `}</style>
    </div>
  );
});

WebScrollView.displayName = 'WebScrollView';

