/**
 * Cross-platform Button component
 */

import React, { forwardRef } from 'react';
import { ButtonProps } from '../types';
import { useTheme } from '../hooks';
import { cn, createButtonVariantStyles, createSizeStyles } from '../utils';

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      children,
      variant = 'primary',
      size = 'md',
      disabled = false,
      loading = false,
      fullWidth = false,
      leftIcon,
      rightIcon,
      onClick,
      type = 'button',
      className,
      style,
      testId,
      ...props
    },
    ref
  ) => {
    const theme = useTheme();

    const baseStyles = {
      ...createButtonVariantStyles(variant, theme),
      ...createSizeStyles(size, theme, 'button'),
      ...(fullWidth && { width: '100%' }),
      ...(loading && { 
        cursor: 'not-allowed',
        opacity: 0.7
      }),
      ...style
    };

    const handleClick = () => {
      if (!disabled && !loading && onClick) {
        onClick();
      }
    };

    return (
      <button
        ref={ref}
        type={type}
        disabled={disabled || loading}
        onClick={handleClick}
        className={cn('ui-button', className)}
        style={baseStyles}
        data-testid={testId}
        aria-disabled={disabled || loading}
        {...props}
      >
        {leftIcon && (
          <span 
            className="ui-button-icon-left"
            style={{ 
              marginRight: children ? `${theme.spacing.xs}px` : 0,
              display: 'flex',
              alignItems: 'center'
            }}
          >
            {leftIcon}
          </span>
        )}

        {loading ? (
          <span 
            className="ui-button-loading"
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: `${theme.spacing.xs}px`
            }}
          >
            <LoadingSpinner size={size} />
            {children && <span>{children}</span>}
          </span>
        ) : (
          children
        )}

        {rightIcon && !loading && (
          <span 
            className="ui-button-icon-right"
            style={{ 
              marginLeft: children ? `${theme.spacing.xs}px` : 0,
              display: 'flex',
              alignItems: 'center'
            }}
          >
            {rightIcon}
          </span>
        )}
      </button>
    );
  }
);

Button.displayName = 'Button';

// Simple loading spinner component
const LoadingSpinner: React.FC<{ size: string }> = ({ size }) => {
  const theme = useTheme();

  const sizeMap = {
    xs: 12,
    sm: 14,
    md: 16,
    lg: 18,
    xl: 20
  };

  const spinnerSize = sizeMap[size as keyof typeof sizeMap] || 16;

  return (
    <div
      className="ui-loading-spinner"
      style={{
        width: `${spinnerSize}px`,
        height: `${spinnerSize}px`,
        border: '2px solid transparent',
        borderTopColor: 'currentColor',
        borderRadius: '50%',
        animation: 'ui-spin 0.8s linear infinite'
      }}
    />
  );
};

