/**
 * Cross-platform Card component
 */

import React, { forwardRef } from 'react';
import { CardProps } from '../types';
import { useTheme } from '../hooks';
import { cn, createSpacingStyles, resolveResponsiveValue, createTransition } from '../utils';

export const Card = forwardRef<HTMLDivElement, CardProps>(
  (
    {
      children,
      variant = 'default',
      padding = 'md',
      clickable = false,
      onClick,
      className,
      style,
      testId,
      ...props
    },
    ref
  ) => {
    const theme = useTheme();

    const getVariantStyles = () => {
      const baseStyles = {
        backgroundColor: theme.colors.surface,
        borderRadius: `${theme.borderRadius}px`,
        transition: createTransition(['box-shadow', 'transform']),
        position: 'relative' as const,
        overflow: 'hidden' as const
      };

      switch (variant) {
        case 'outlined':
          return {
            ...baseStyles,
            border: `1px solid ${theme.colors.border}`,
            backgroundColor: theme.colors.background
          };

        case 'elevated':
          return {
            ...baseStyles,
            boxShadow: theme.shadows.md,
            border: 'none',
            '&:hover': clickable ? {
              boxShadow: theme.shadows.lg,
              transform: 'translateY(-2px)'
            } : {}
          };

        case 'filled':
          return {
            ...baseStyles,
            backgroundColor: theme.colors.surface,
            border: 'none'
          };

        case 'default':
        default:
          return {
            ...baseStyles,
            boxShadow: theme.shadows.sm,
            border: `1px solid ${theme.colors.border}`
          };
      }
    };

    const paddingStyles = createSpacingStyles('padding', padding, theme);

    const clickableStyles = clickable ? {
      cursor: 'pointer',
      userSelect: 'none' as const,
      WebkitTapHighlightColor: 'transparent',
      '&:hover': {
        transform: 'translateY(-1px)',
        boxShadow: variant === 'elevated' ? theme.shadows.lg : theme.shadows.md
      },
      '&:active': {
        transform: 'translateY(0)',
        transition: createTransition(['transform'], '100ms')
      }
    } : {};

    const cardStyles = {
      ...getVariantStyles(),
      ...paddingStyles,
      ...clickableStyles,
      ...style
    };

    const handleClick = () => {
      if (clickable && onClick) {
        onClick();
      }
    };

    const handleKeyDown = (event: React.KeyboardEvent) => {
      if (clickable && (event.key === 'Enter' || event.key === ' ')) {
        event.preventDefault();
        onClick?.();
      }
    };

    return (
      <div
        ref={ref}
        className={cn('ui-card', className)}
        style={cardStyles}
        onClick={handleClick}
        onKeyDown={handleKeyDown}
        role={clickable ? 'button' : undefined}
        tabIndex={clickable ? 0 : undefined}
        data-testid={testId}
        {...props}
      >
        {children}
        {clickable && (
          <div
            className="ui-card-ripple"
            style={{
              position: 'absolute',
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              background: 'radial-gradient(circle, rgba(255,255,255,0.3) 1px, transparent 1px)',
              backgroundSize: '0 0',
              transition: createTransition(['background-size'], '300ms'),
              pointerEvents: 'none'
            }}
          />
        )}
      </div>
    );
  }
);

Card.displayName = 'Card';

