/**
 * Cross-platform Input component
 */

import React, { forwardRef, useState, useCallback } from 'react';
import { InputProps } from '../types';
import { useTheme } from '../hooks';
import { cn, createInputStyles, createSizeStyles, generateId } from '../utils';

export const Input = forwardRef<HTMLInputElement, InputProps>(
  (
    {
      type = 'text',
      placeholder,
      value,
      defaultValue,
      size = 'md',
      disabled = false,
      readOnly = false,
      error,
      label,
      hint,
      required = false,
      leftIcon,
      rightIcon,
      onChange,
      onBlur,
      onFocus,
      className,
      style,
      testId,
      ...props
    },
    ref
  ) => {
    const theme = useTheme();
    const [isFocused, setIsFocused] = useState(false);
    const [internalValue, setInternalValue] = useState(value || defaultValue || '');

    const inputId = generateId('input');
    const errorId = error ? `${inputId}-error` : undefined;
    const hintId = hint ? `${inputId}-hint` : undefined;

    const inputStyles = {
      ...createInputStyles(theme, error, disabled),
      ...createSizeStyles(size, theme, 'input'),
      ...(leftIcon && { paddingLeft: `${theme.spacing.xl}px` }),
      ...(rightIcon && { paddingRight: `${theme.spacing.xl}px` }),
      ...style
    };

    const handleChange = useCallback((event: React.ChangeEvent<HTMLInputElement>) => {
      const newValue = event.target.value;
      setInternalValue(newValue);
      onChange?.(newValue);
    }, [onChange]);

    const handleFocus = useCallback((event: React.FocusEvent<HTMLInputElement>) => {
      setIsFocused(true);
      onFocus?.();
    }, [onFocus]);

    const handleBlur = useCallback((event: React.FocusEvent<HTMLInputElement>) => {
      setIsFocused(false);
      onBlur?.();
    }, [onBlur]);

    const currentValue = value !== undefined ? value : internalValue;

    return (
      <div className={cn('ui-input-container', className)}>
        {label && (
          <label
            htmlFor={inputId}
            className="ui-input-label"
            style={{
              display: 'block',
              marginBottom: `${theme.spacing.xs}px`,
              fontSize: `${theme.typography.fontSize.sm}px`,
              fontWeight: theme.typography.fontWeight.medium,
              color: error ? theme.colors.error : theme.colors.text,
              fontFamily: theme.typography.fontFamily
            }}
          >
            {label}
            {required && (
              <span
                className="ui-input-required"
                style={{
                  color: theme.colors.error,
                  marginLeft: `${theme.spacing.xs / 2}px`
                }}
              >
                *
              </span>
            )}
          </label>
        )}

        <div
          className="ui-input-wrapper"
          style={{
            position: 'relative',
            display: 'flex',
            alignItems: 'center'
          }}
        >
          {leftIcon && (
            <div
              className="ui-input-icon-left"
              style={{
                position: 'absolute',
                left: `${theme.spacing.sm}px`,
                display: 'flex',
                alignItems: 'center',
                color: disabled ? theme.colors.textSecondary : theme.colors.textSecondary,
                pointerEvents: 'none',
                zIndex: 1
              }}
            >
              {leftIcon}
            </div>
          )}

          <input
            ref={ref}
            id={inputId}
            type={type}
            placeholder={placeholder}
            value={currentValue}
            disabled={disabled}
            readOnly={readOnly}
            required={required}
            onChange={handleChange}
            onFocus={handleFocus}
            onBlur={handleBlur}
            className="ui-input"
            style={inputStyles}
            data-testid={testId}
            aria-describedby={[errorId, hintId].filter(Boolean).join(' ') || undefined}
            aria-invalid={!!error}
            {...props}
          />

          {rightIcon && (
            <div
              className="ui-input-icon-right"
              style={{
                position: 'absolute',
                right: `${theme.spacing.sm}px`,
                display: 'flex',
                alignItems: 'center',
                color: disabled ? theme.colors.textSecondary : theme.colors.textSecondary,
                pointerEvents: 'none',
                zIndex: 1
              }}
            >
              {rightIcon}
            </div>
          )}
        </div>

        {error && (
          <div
            id={errorId}
            className="ui-input-error"
            style={{
              marginTop: `${theme.spacing.xs}px`,
              fontSize: `${theme.typography.fontSize.sm}px`,
              color: theme.colors.error,
              fontFamily: theme.typography.fontFamily
            }}
          >
            {error}
          </div>
        )}

        {hint && !error && (
          <div
            id={hintId}
            className="ui-input-hint"
            style={{
              marginTop: `${theme.spacing.xs}px`,
              fontSize: `${theme.typography.fontSize.sm}px`,
              color: theme.colors.textSecondary,
              fontFamily: theme.typography.fontFamily
            }}
          >
            {hint}
          </div>
        )}
      </div>
    );
  }
);

Input.displayName = 'Input';

// TextArea variant
export const TextArea = forwardRef<HTMLTextAreaElement, InputProps & { rows?: number; resize?: boolean }>(
  (
    {
      placeholder,
      value,
      defaultValue,
      size = 'md',
      disabled = false,
      readOnly = false,
      error,
      label,
      hint,
      required = false,
      onChange,
      onBlur,
      onFocus,
      className,
      style,
      testId,
      rows = 4,
      resize = true,
      ...props
    },
    ref
  ) => {
    const theme = useTheme();
    const [internalValue, setInternalValue] = useState(value || defaultValue || '');

    const inputId = generateId('textarea');
    const errorId = error ? `${inputId}-error` : undefined;
    const hintId = hint ? `${inputId}-hint` : undefined;

    const textareaStyles = {
      ...createInputStyles(theme, error, disabled),
      ...createSizeStyles(size, theme, 'input'),
      minHeight: `${rows * 1.5}em`,
      resize: resize ? 'vertical' : 'none',
      lineHeight: theme.typography.lineHeight.normal,
      ...style
    };

    const handleChange = useCallback((event: React.ChangeEvent<HTMLTextAreaElement>) => {
      const newValue = event.target.value;
      setInternalValue(newValue);
      onChange?.(newValue);
    }, [onChange]);

    const currentValue = value !== undefined ? value : internalValue;

    return (
      <div className={cn('ui-textarea-container', className)}>
        {label && (
          <label
            htmlFor={inputId}
            className="ui-textarea-label"
            style={{
              display: 'block',
              marginBottom: `${theme.spacing.xs}px`,
              fontSize: `${theme.typography.fontSize.sm}px`,
              fontWeight: theme.typography.fontWeight.medium,
              color: error ? theme.colors.error : theme.colors.text,
              fontFamily: theme.typography.fontFamily
            }}
          >
            {label}
            {required && (
              <span
                className="ui-textarea-required"
                style={{
                  color: theme.colors.error,
                  marginLeft: `${theme.spacing.xs / 2}px`
                }}
              >
                *
              </span>
            )}
          </label>
        )}

        <textarea
          ref={ref}
          id={inputId}
          placeholder={placeholder}
          value={currentValue}
          disabled={disabled}
          readOnly={readOnly}
          required={required}
          rows={rows}
          onChange={handleChange}
          onFocus={onFocus}
          onBlur={onBlur}
          className="ui-textarea"
          style={textareaStyles}
          data-testid={testId}
          aria-describedby={[errorId, hintId].filter(Boolean).join(' ') || undefined}
          aria-invalid={!!error}
          {...props as any}
        />

        {error && (
          <div
            id={errorId}
            className="ui-textarea-error"
            style={{
              marginTop: `${theme.spacing.xs}px`,
              fontSize: `${theme.typography.fontSize.sm}px`,
              color: theme.colors.error,
              fontFamily: theme.typography.fontFamily
            }}
          >
            {error}
          </div>
        )}

        {hint && !error && (
          <div
            id={hintId}
            className="ui-textarea-hint"
            style={{
              marginTop: `${theme.spacing.xs}px`,
              fontSize: `${theme.typography.fontSize.sm}px`,
              color: theme.colors.textSecondary,
              fontFamily: theme.typography.fontFamily
            }}
          >
            {hint}
          </div>
        )}
      </div>
    );
  }
);

TextArea.displayName = 'TextArea';

/**
 * Inspector Panel component for editing node properties
 */

import React, { useState, useMemo } from 'react';
import { InspectorPanelProps } from '../types';
import { useTheme, useResponsive } from '../hooks';
import { Button } from './Button';
import { Input, TextArea } from './Input';
import { Card, CardHeader, CardTitle, CardContent } from './Card';
import { Stack } from './Layout';
import { cn } from '../utils';

export const InspectorPanel: React.FC<InspectorPanelProps> = ({
  selectedNode,
  onNodeUpdate,
  onNodeDelete,
  collapsed = false,
  position = 'right',
  className,
  style,
  testId,
  ...props
}) => {
  const theme = useTheme();
  const { isMobile } = useResponsive();
  const [internalCollapsed, setInternalCollapsed] = useState(collapsed);

  // Get node editor component based on node type
  const nodeEditor = useMemo(() => {
    if (!selectedNode) return null;

    switch (selectedNode.type) {
      case 'WeightedChoice':
        return <WeightedChoiceEditor node={selectedNode} onUpdate={onNodeUpdate} />;
      case 'Concat':
        return <ConcatEditor node={selectedNode} onUpdate={onNodeUpdate} />;
      case 'Output':
        return <OutputEditor node={selectedNode} onUpdate={onNodeUpdate} />;
      case 'Include':
        return <IncludeEditor node={selectedNode} onUpdate={onNodeUpdate} />;
      case 'SetVariable':
        return <SetVariableEditor node={selectedNode} onUpdate={onNodeUpdate} />;
      case 'GetVariable':
        return <GetVariableEditor node={selectedNode} onUpdate={onNodeUpdate} />;
      case 'WeightedAdvanced':
        return <WeightedAdvancedEditor node={selectedNode} onUpdate={onNodeUpdate} />;
      case 'Conditional':
        return <ConditionalEditor node={selectedNode} onUpdate={onNodeUpdate} />;
      case 'Sequential':
        return <SequentialEditor node={selectedNode} onUpdate={onNodeUpdate} />;
      case 'Markov':
        return <MarkovEditor node={selectedNode} onUpdate={onNodeUpdate} />;
      default:
        return <GenericEditor node={selectedNode} onUpdate={onNodeUpdate} />;
    }
  }, [selectedNode, onNodeUpdate]);

  const getPanelStyles = () => {
    const baseStyles = {
      width: position === 'bottom' ? '100%' : '320px',
      height: position === 'bottom' ? '300px' : '100%',
      backgroundColor: theme.colors.surface,
      border: `1px solid ${theme.colors.border}`,
      borderRadius: `${theme.borderRadius}px`,
      overflow: 'hidden',
      display: 'flex',
      flexDirection: 'column' as const,
      ...style
    };

    if (isMobile) {
      return {
        ...baseStyles,
        width: '100%',
        height: internalCollapsed ? '48px' : '50vh',
        position: 'fixed' as const,
        bottom: 0,
        left: 0,
        right: 0,
        borderRadius: internalCollapsed ? 0 : `${theme.borderRadius}px ${theme.borderRadius}px 0 0`,
        zIndex: 100
      };
    }

    return baseStyles;
  };

  const panelStyles = getPanelStyles();

  if (internalCollapsed) {
    return (
      <div
        className={cn('ui-inspector-panel ui-inspector-panel--collapsed', className)}
        style={panelStyles}
        data-testid={testId}
        {...props}
      >
        <div style={{
          padding: `${theme.spacing.sm}px`,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          borderBottom: !isMobile ? `1px solid ${theme.colors.border}` : 'none'
        }}>
          <span style={{
            fontSize: `${theme.typography.fontSize.sm}px`,
            fontWeight: theme.typography.fontWeight.medium,
            color: theme.colors.text
          }}>
            Inspector
          </span>

          <Button
            variant="ghost"
            size="xs"
            onClick={() => setInternalCollapsed(false)}
            aria-label="Expand inspector panel"
          >
            {position === 'bottom' || isMobile ? '🔼' : '▶️'}
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div
      className={cn('ui-inspector-panel', className)}
      style={panelStyles}
      data-testid={testId}
      {...props}
    >
      {/* Header */}
      <div
        className="ui-inspector-panel-header"
        style={{
          padding: `${theme.spacing.md}px`,
          borderBottom: `1px solid ${theme.colors.border}`,
          backgroundColor: theme.colors.background,
          flexShrink: 0
        }}
      >
        <div style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between'
        }}>
          <h3 style={{
            margin: 0,
            fontSize: `${theme.typography.fontSize.md}px`,
            fontWeight: theme.typography.fontWeight.semibold,
            color: theme.colors.text
          }}>
            Inspector
          </h3>

          <Button
            variant="ghost"
            size="xs"
            onClick={() => setInternalCollapsed(true)}
            aria-label="Collapse inspector panel"
          >
            {position === 'bottom' || isMobile ? '🔽' : '◀️'}
          </Button>
        </div>

        {selectedNode && (
          <div style={{
            marginTop: `${theme.spacing.xs}px`,
            fontSize: `${theme.typography.fontSize.sm}px`,
            color: theme.colors.textSecondary
          }}>
            {selectedNode.type} Node
          </div>
        )}
      </div>

      {/* Content */}
      <div
        className="ui-inspector-panel-content"
        style={{
          flex: 1,
          overflow: 'auto',
          padding: `${theme.spacing.md}px`
        }}
      >
        {selectedNode ? (
          <Stack spacing="md">
            {/* Node basic info */}
            <Card variant="outlined" padding="sm">
              <Stack spacing="sm">
                <Input
                  label="Node ID"
                  value={selectedNode.id}
                  readOnly
                  size="sm"
                />

                <Input
                  label="Node Type"
                  value={selectedNode.type}
                  readOnly
                  size="sm"
                />
              </Stack>
            </Card>

            {/* Node-specific editor */}
            {nodeEditor}

            {/* Actions */}
            <div style={{
              display: 'flex',
              gap: `${theme.spacing.sm}px`,
              justifyContent: 'flex-end'
            }}>
              <Button
                variant="outline"
                size="sm"
                onClick={() => onNodeDelete?.(selectedNode.id)}
              >
                Delete Node
              </Button>
            </div>
          </Stack>
        ) : (
          <div style={{
            padding: `${theme.spacing.xl}px`,
            textAlign: 'center',
            color: theme.colors.textSecondary
          }}>
            <div style={{
              fontSize: '48px',
              marginBottom: `${theme.spacing.md}px`
            }}>
              🎯
            </div>
            <div style={{
              fontSize: `${theme.typography.fontSize.md}px`,
              marginBottom: `${theme.spacing.sm}px`
            }}>
              No Node Selected
            </div>
            <div style={{
              fontSize: `${theme.typography.fontSize.sm}px`
            }}>
              Select a node to edit its properties
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

// Individual node editors
import { GraphNode } from '@prompt-spaghetti/graph-core';

interface NodeEditorProps {
  node: GraphNode;
  onUpdate?: (nodeId: string, updates: Partial<GraphNode>) => void;
}

const WeightedChoiceEditor: React.FC<NodeEditorProps> = ({ node, onUpdate }) => {
  const choices = node.data.choices || [];

  const updateChoices = (newChoices: any[]) => {
    onUpdate?.(node.id, {
      data: { ...node.data, choices: newChoices }
    });
  };

  const addChoice = () => {
    updateChoices([...choices, { value: '', weight: 1 }]);
  };

  const removeChoice = (index: number) => {
    updateChoices(choices.filter((_, i) => i !== index));
  };

  const updateChoice = (index: number, field: 'value' | 'weight', value: any) => {
    const newChoices = [...choices];
    newChoices[index] = { ...newChoices[index], [field]: value };
    updateChoices(newChoices);
  };

  return (
    <Card variant="outlined" padding="sm">
      <CardHeader>
        <CardTitle level={4}>Weighted Choices</CardTitle>
      </CardHeader>
      <CardContent>
        <Stack spacing="sm">
          {choices.map((choice: any, index: number) => (
            <div key={index} style={{ display: 'flex', gap: '8px', alignItems: 'end' }}>
              <Input
                label={`Choice ${index + 1}`}
                value={choice.value}
                onChange={(value) => updateChoice(index, 'value', value)}
                size="sm"
                style={{ flex: 1 }}
              />
              <Input
                label="Weight"
                type="number"
                value={choice.weight}
                onChange={(value) => updateChoice(index, 'weight', parseFloat(value) || 0)}
                size="sm"
                style={{ width: '80px' }}
              />
              <Button
                variant="outline"
                size="sm"
                onClick={() => removeChoice(index)}
              >
                ❌
              </Button>
            </div>
          ))}

          <Button variant="outline" size="sm" onClick={addChoice}>
            Add Choice
          </Button>
        </Stack>
      </CardContent>
    </Card>
  );
};

