/**
 * Theme Provider component for cross-platform theming
 */

import React, { useState, useEffect, useMemo } from 'react';
import { ThemeContext } from '../hooks/useTheme';
import { Theme } from '../types';
import { createTheme } from '../platform';

interface ThemeProviderProps {
  children: React.ReactNode;
  theme?: Partial<Theme>;
  defaultColorMode?: 'light' | 'dark' | 'system';
}

export const ThemeProvider: React.FC<ThemeProviderProps> = ({
  children,
  theme: themeOverrides,
  defaultColorMode = 'system'
}) => {
  const [colorMode, setColorMode] = useState<'light' | 'dark'>(() => {
    if (defaultColorMode === 'system') {
      return typeof window !== 'undefined' && 
        window.matchMedia('(prefers-color-scheme: dark)').matches 
        ? 'dark' 
        : 'light';
    }
    return defaultColorMode;
  });

  const [customTheme, setCustomTheme] = useState<Partial<Theme>>(themeOverrides || {});

  // Listen for system color mode changes
  useEffect(() => {
    if (defaultColorMode === 'system' && typeof window !== 'undefined') {
      const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');

      const handleChange = (e: MediaQueryListEvent) => {
        setColorMode(e.matches ? 'dark' : 'light');
      };

      mediaQuery.addEventListener('change', handleChange);
      return () => mediaQuery.removeEventListener('change', handleChange);
    }
  }, [defaultColorMode]);

  // Create theme with color mode and custom overrides
  const theme = useMemo(() => {
    const baseTheme = createTheme();

    // Apply color mode
    const colorModeTheme = colorMode === 'dark' ? {
      ...baseTheme,
      colors: {
        primary: '#0A84FF',
        secondary: '#5E5CE6',
        accent: '#FF9F0A',
        background: '#000000',
        surface: '#1C1C1E',
        text: '#FFFFFF',
        textSecondary: '#8E8E93',
        border: '#38383A',
        error: '#FF453A',
        warning: '#FF9F0A',
        success: '#32D74B',
        info: '#64D2FF'
      }
    } : baseTheme;

    // Apply custom theme overrides
    return {
      ...colorModeTheme,
      ...customTheme,
      colors: {
        ...colorModeTheme.colors,
        ...(customTheme.colors || {})
      }
    };
  }, [colorMode, customTheme]);

  const setTheme = (themeOverrides: Partial<Theme>) => {
    setCustomTheme(prev => ({
      ...prev,
      ...themeOverrides,
      colors: {
        ...prev.colors,
        ...(themeOverrides.colors || {})
      }
    }));
  };

  const toggleColorMode = () => {
    setColorMode(prev => prev === 'light' ? 'dark' : 'light');
  };

  const contextValue = {
    theme,
    setTheme,
    toggleColorMode,
    colorMode
  };

  return (
    <ThemeContext.Provider value={contextValue}>
      <div
        className="ui-theme-provider"
        style={{
          backgroundColor: theme.colors.background,
          color: theme.colors.text,
          fontFamily: theme.typography.fontFamily,
          fontSize: `${theme.typography.fontSize.md}px`,
          lineHeight: theme.typography.lineHeight.normal,
          minHeight: '100%'
        }}
      >
        {children}
        <style dangerouslySetInnerHTML={{
          __html: `
            :root {
              --ui-primary: ${theme.colors.primary};
              --ui-secondary: ${theme.colors.secondary};
              --ui-accent: ${theme.colors.accent};
              --ui-background: ${theme.colors.background};
              --ui-surface: ${theme.colors.surface};
              --ui-text: ${theme.colors.text};
              --ui-text-secondary: ${theme.colors.textSecondary};
              --ui-border: ${theme.colors.border};
              --ui-error: ${theme.colors.error};
              --ui-warning: ${theme.colors.warning};
              --ui-success: ${theme.colors.success};
              --ui-info: ${theme.colors.info};

              --ui-spacing-xs: ${theme.spacing.xs}px;
              --ui-spacing-sm: ${theme.spacing.sm}px;
              --ui-spacing-md: ${theme.spacing.md}px;
              --ui-spacing-lg: ${theme.spacing.lg}px;
              --ui-spacing-xl: ${theme.spacing.xl}px;

              --ui-border-radius: ${theme.borderRadius}px;
              --ui-shadow-sm: ${theme.shadows.sm};
              --ui-shadow-md: ${theme.shadows.md};
              --ui-shadow-lg: ${theme.shadows.lg};

              --ui-font-family: ${theme.typography.fontFamily};
              --ui-font-size-xs: ${theme.typography.fontSize.xs}px;
              --ui-font-size-sm: ${theme.typography.fontSize.sm}px;
              --ui-font-size-md: ${theme.typography.fontSize.md}px;
              --ui-font-size-lg: ${theme.typography.fontSize.lg}px;
              --ui-font-size-xl: ${theme.typography.fontSize.xl}px;
              --ui-font-size-xxl: ${theme.typography.fontSize.xxl}px;
            }

            * {
              box-sizing: border-box;
            }

            .ui-theme-provider {
              transition: background-color 0.2s ease, color 0.2s ease;
            }

            /* Focus styles */
            .ui-theme-provider :focus {
              outline: 2px solid ${theme.colors.primary};
              outline-offset: 2px;
            }

            .ui-theme-provider :focus:not(:focus-visible) {
              outline: none;
            }

            /* Scrollbar styles */
            .ui-theme-provider ::-webkit-scrollbar {
              width: 8px;
              height: 8px;
            }

            .ui-theme-provider ::-webkit-scrollbar-track {
              background: ${theme.colors.surface};
            }

            .ui-theme-provider ::-webkit-scrollbar-thumb {
              background: ${theme.colors.border};
              border-radius: 4px;
            }

            .ui-theme-provider ::-webkit-scrollbar-thumb:hover {
              background: ${theme.colors.textSecondary};
            }

            /* Selection styles */
            .ui-theme-provider ::selection {
              background: ${theme.colors.primary};
              color: ${theme.colors.background};
            }

            /* Reduced motion support */
            @media (prefers-reduced-motion: reduce) {
              .ui-theme-provider * {
                animation-duration: 0.01ms !important;
                animation-iteration-count: 1 !important;
                transition-duration: 0.01ms !important;
              }
            }
          `
        }} />
      </div>
    </ThemeContext.Provider>
  );
};

/**
 * Platform detection and capabilities hook
 */

import { useState, useEffect } from 'react';
import { Platform, DeviceCapabilities } from '../types';
import { 
  detectPlatform, 
  getPlatformCapabilities, 
  getPlatformOptimizations,
  isReducedMotion,
  isTouchDevice,
  isApplePlatform
} from '../platform';

export interface PlatformState {
  platform: Platform;
  capabilities: DeviceCapabilities;
  optimizations: ReturnType<typeof getPlatformOptimizations>;
  isReducedMotion: boolean;
  isTouchDevice: boolean;
  isApplePlatform: boolean;
  isOnline: boolean;
}

export function usePlatform(): PlatformState {
  const [platformState, setPlatformState] = useState<PlatformState>(() => {
    const platform = detectPlatform();
    const capabilities = getPlatformCapabilities();
    const optimizations = getPlatformOptimizations(platform);

    return {
      platform,
      capabilities,
      optimizations,
      isReducedMotion: isReducedMotion(),
      isTouchDevice: isTouchDevice(),
      isApplePlatform: isApplePlatform(),
      isOnline: typeof navigator !== 'undefined' ? navigator.onLine : true
    };
  });

  useEffect(() => {
    const updatePlatformState = () => {
      const platform = detectPlatform();
      const capabilities = getPlatformCapabilities();
      const optimizations = getPlatformOptimizations(platform);

      setPlatformState(prev => ({
        ...prev,
        platform,
        capabilities,
        optimizations,
        isReducedMotion: isReducedMotion(),
        isTouchDevice: isTouchDevice(),
        isApplePlatform: isApplePlatform()
      }));
    };

    // Listen for media query changes
    if (typeof window !== 'undefined') {
      const reducedMotionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
      const hoverQuery = window.matchMedia('(hover: hover)');

      const handleMediaChange = () => updatePlatformState();

      reducedMotionQuery.addEventListener('change', handleMediaChange);
      hoverQuery.addEventListener('change', handleMediaChange);

      // Listen for online/offline changes
      const handleOnline = () => setPlatformState(prev => ({ ...prev, isOnline: true }));
      const handleOffline = () => setPlatformState(prev => ({ ...prev, isOnline: false }));

      window.addEventListener('online', handleOnline);
      window.addEventListener('offline', handleOffline);

      return () => {
        reducedMotionQuery.removeEventListener('change', handleMediaChange);
        hoverQuery.removeEventListener('change', handleMediaChange);
        window.removeEventListener('online', handleOnline);
        window.removeEventListener('offline', handleOffline);
      };
    }
  }, []);

  return platformState;
}

// Specific platform checks
export function useIsMobile(): boolean {
  const { platform } = usePlatform();
  return platform === 'mobile';
}

export function useIsDesktop(): boolean {
  const { platform } = usePlatform();
  return platform === 'desktop';
}

export function useIsWeb(): boolean {
  const { platform } = usePlatform();
  return platform === 'web';
}

export function useTouchSupport(): boolean {
  const { capabilities } = usePlatform();
  return capabilities.touchSupport;
}

export function useHoverSupport(): boolean {
  const { capabilities } = usePlatform();
  return capabilities.hoverSupport;
}

export function useKeyboardSupport(): boolean {
  const { capabilities } = usePlatform();
  return capabilities.keyboardSupport;
}

/**
 * Responsive design hook
 */

import { useState, useEffect } from 'react';
import { getBreakpoint, getViewportSize } from '../platform';

export interface ResponsiveState {
  isMobile: boolean;
  isTablet: boolean;
  isDesktop: boolean;
  breakpoint: 'mobile' | 'tablet' | 'desktop';
  width: number;
  height: number;
}

export function useResponsive(): ResponsiveState {
  const [responsiveState, setResponsiveState] = useState<ResponsiveState>(() => {
    const { width, height } = getViewportSize();
    const breakpoint = getBreakpoint(width);

    return {
      isMobile: breakpoint === 'mobile',
      isTablet: breakpoint === 'tablet',
      isDesktop: breakpoint === 'desktop',
      breakpoint,
      width,
      height
    };
  });

  useEffect(() => {
    const updateResponsiveState = () => {
      const { width, height } = getViewportSize();
      const breakpoint = getBreakpoint(width);

      setResponsiveState({
        isMobile: breakpoint === 'mobile',
        isTablet: breakpoint === 'tablet',
        isDesktop: breakpoint === 'desktop',
        breakpoint,
        width,
        height
      });
    };

    // Update on window resize
    if (typeof window !== 'undefined') {
      window.addEventListener('resize', updateResponsiveState);

      // Also listen for orientation change on mobile
      window.addEventListener('orientationchange', () => {
        // Small delay to allow viewport to update
        setTimeout(updateResponsiveState, 100);
      });

      return () => {
        window.removeEventListener('resize', updateResponsiveState);
        window.removeEventListener('orientationchange', updateResponsiveState);
      };
    }
  }, []);

  return responsiveState;
}

// Hook for specific breakpoint queries
export function useBreakpoint(breakpoint: 'mobile' | 'tablet' | 'desktop'): boolean {
  const { breakpoint: currentBreakpoint } = useResponsive();
  return currentBreakpoint === breakpoint;
}

// Hook for media queries
export function useMediaQuery(query: string): boolean {
  const [matches, setMatches] = useState(false);

  useEffect(() => {
    if (typeof window === 'undefined') return;

    const mediaQuery = window.matchMedia(query);
    const updateMatches = () => setMatches(mediaQuery.matches);

    updateMatches();
    mediaQuery.addEventListener('change', updateMatches);

    return () => mediaQuery.removeEventListener('change', updateMatches);
  }, [query]);

  return matches;
}

/**
 * Theme management hook
 */

import { createContext, useContext } from 'react';
import { Theme } from '../types';
import { createTheme } from '../platform';

// Theme context
export const ThemeContext = createContext<{
  theme: Theme;
  setTheme: (theme: Partial<Theme>) => void;
  toggleColorMode: () => void;
  colorMode: 'light' | 'dark';
}>({
  theme: createTheme(),
  setTheme: () => {},
  toggleColorMode: () => {},
  colorMode: 'light'
});

// Hook to use theme
export function useTheme(): Theme {
  const context = useContext(ThemeContext);

  if (!context) {
    // Return default theme if no provider
    return createTheme();
  }

  return context.theme;
}

// Hook to use theme controls
export function useThemeControls() {
  const context = useContext(ThemeContext);

  if (!context) {
    throw new Error('useThemeControls must be used within a ThemeProvider');
  }

  return {
    setTheme: context.setTheme,
    toggleColorMode: context.toggleColorMode,
    colorMode: context.colorMode
  };
}

/**
 * Global UI state management hook
 */

import { create } from 'zustand';
import { subscribeWithSelector } from 'zustand/middleware';
import { UIState, Theme } from '../types';
import { createTheme, detectPlatform, getPlatformCapabilities, getBreakpoint, getViewportSize } from '../platform';

interface UIStore extends UIState {
  // Actions
  setTheme: (theme: Partial<Theme>) => void;
  setSelectedNodeId: (nodeId: string | undefined) => void;
  toggleInspector: () => void;
  togglePalette: () => void;
  setInspectorOpen: (open: boolean) => void;
  setPaletteOpen: (open: boolean) => void;
  updateBreakpoint: () => void;
}

export const useUIStore = create<UIStore>()(
  subscribeWithSelector((set, get) => {
    const initialTheme = createTheme();
    const initialPlatform = detectPlatform();
    const initialCapabilities = getPlatformCapabilities();
    const { width } = getViewportSize();
    const initialBreakpoint = getBreakpoint(width);

    return {
      // Initial state
      theme: initialTheme,
      platform: initialPlatform,
      capabilities: initialCapabilities,
      breakpoint: initialBreakpoint,
      isReducedMotion: typeof window !== 'undefined' && window.matchMedia('(prefers-reduced-motion: reduce)').matches,
      selectedNodeId: undefined,
      inspectorOpen: false,
      paletteOpen: true,

      // Actions
      setTheme: (themeOverrides) => {
        const currentTheme = get().theme;
        const newTheme = { ...currentTheme, ...themeOverrides };
        set({ theme: newTheme });
      },

      setSelectedNodeId: (nodeId) => {
        set({ selectedNodeId: nodeId });
      },

      toggleInspector: () => {
        set((state) => ({ inspectorOpen: !state.inspectorOpen }));
      },

      togglePalette: () => {
        set((state) => ({ paletteOpen: !state.paletteOpen }));
      },

      setInspectorOpen: (open) => {
        set({ inspectorOpen: open });
      },

      setPaletteOpen: (open) => {
        set({ paletteOpen: open });
      },

      updateBreakpoint: () => {
        const { width } = getViewportSize();
        const breakpoint = getBreakpoint(width);
        set({ breakpoint });
      }
    };
  })
);

// Hook to use UI state
export function useUIState() {
  const state = useUIStore();
  return state;
}

// Specific UI state hooks
export function useSelectedNode() {
  const selectedNodeId = useUIStore((state) => state.selectedNodeId);
  const setSelectedNodeId = useUIStore((state) => state.setSelectedNodeId);

  return { selectedNodeId, setSelectedNodeId };
}

export function useInspectorState() {
  const inspectorOpen = useUIStore((state) => state.inspectorOpen);
  const toggleInspector = useUIStore((state) => state.toggleInspector);
  const setInspectorOpen = useUIStore((state) => state.setInspectorOpen);

  return { inspectorOpen, toggleInspector, setInspectorOpen };
}

export function usePaletteState() {
  const paletteOpen = useUIStore((state) => state.paletteOpen);
  const togglePalette = useUIStore((state) => state.togglePalette);
  const setPaletteOpen = useUIStore((state) => state.setPaletteOpen);

  return { paletteOpen, togglePalette, setPaletteOpen };
}

// Theme-specific hooks
export function useThemeState() {
  const theme = useUIStore((state) => state.theme);
  const setTheme = useUIStore((state) => state.setTheme);

  return { theme, setTheme };
}

// Initialize responsive updates
if (typeof window !== 'undefined') {
  const updateBreakpoint = () => {
    useUIStore.getState().updateBreakpoint();
  };

  window.addEventListener('resize', updateBreakpoint);
  window.addEventListener('orientationchange', () => {
    setTimeout(updateBreakpoint, 100);
  });
}

/**
 * Mobile-optimized button component
 */

import React from 'react';
import { Button, ButtonProps } from '../../components/Button';
import { TOUCH_TARGETS, mobileStyles } from '../design-system';
import { useDeviceDetection } from '../../responsive/utilities';
import { cn } from '../../utils';

export interface MobileButtonProps extends ButtonProps {
  /**
   * Make button full width on mobile
   */
  mobileFullWidth?: boolean;

  /**
   * Add haptic feedback on press (mobile only)
   */
  hapticFeedback?: boolean;

  /**
   * Show loading spinner inline on mobile
   */
  mobileLoading?: boolean;
}

export const MobileButton: React.FC<MobileButtonProps> = ({
  size = 'md',
  mobileFullWidth = false,
  hapticFeedback = true,
  mobileLoading = false,
  onClick,
  className,
  style,
  children,
  ...props
}) => {
  const { isMobile, isTouch } = useDeviceDetection();

  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    // Haptic feedback for supported devices
    if (hapticFeedback && isTouch && 'vibrate' in navigator) {
      navigator.vibrate(10); // Light haptic feedback
    }

    onClick?.(e);
  };

  // Mobile-specific styles
  const mobileButtonStyles: React.CSSProperties = {
    minHeight: TOUCH_TARGETS.preferred,
    minWidth: TOUCH_TARGETS.preferred,
    // Larger tap area with padding
    padding: '12px 24px',
    // Full width on mobile if specified
    width: (isMobile && mobileFullWidth) ? '100%' : undefined,
    // Prevent double-tap zoom
    touchAction: 'manipulation',
    // Remove tap highlight on iOS
    WebkitTapHighlightColor: 'transparent',
    // Ensure text doesn't wrap
    whiteSpace: 'nowrap',
    ...style
  };

  return (
    <Button
      {...props}
      size={size}
      onClick={handleClick}
      className={cn(
        'mobile-button',
        isTouch && 'touch-device',
        className
      )}
      style={mobileButtonStyles}
      loading={mobileLoading || props.loading}
    >
      {children}
    </Button>
  );
};

/**
 * Mobile floating action button
 */
export interface MobileFABProps extends Omit<MobileButtonProps, 'variant'> {
  position?: 'bottom-right' | 'bottom-left' | 'bottom-center';
  offset?: number;
}

export const MobileFAB: React.FC<MobileFABProps> = ({
  position = 'bottom-right',
  offset = 16,
  className,
  style,
  children,
  ...props
}) => {
  const positionStyles: React.CSSProperties = {
    position: 'fixed',
    zIndex: 1000,
    minWidth: TOUCH_TARGETS.large,
    minHeight: TOUCH_TARGETS.large,
    borderRadius: '50%',
    boxShadow: '0 4px 12px rgba(0, 0, 0, 0.15)',
    ...mobileStyles.tapHighlight,
    ...mobileStyles.noSelect
  };

  // Position-specific styles
  switch (position) {
    case 'bottom-right':
      positionStyles.bottom = `calc(${offset}px + env(safe-area-inset-bottom))`;
      positionStyles.right = `calc(${offset}px + env(safe-area-inset-right))`;
      break;
    case 'bottom-left':
      positionStyles.bottom = `calc(${offset}px + env(safe-area-inset-bottom))`;
      positionStyles.left = `calc(${offset}px + env(safe-area-inset-left))`;
      break;
    case 'bottom-center':
      positionStyles.bottom = `calc(${offset}px + env(safe-area-inset-bottom))`;
      positionStyles.left = '50%';
      positionStyles.transform = 'translateX(-50%)';
      break;
  }

  return (
    <MobileButton
      {...props}
      variant="primary"
      className={cn('mobile-fab', className)}
      style={{
        ...positionStyles,
        ...style
      }}
    >
      {children}
    </MobileButton>
  );
};

