  position?: 'left' | 'right';
  width?: number | string;
  className?: string;
  style?: React.CSSProperties;
  children: React.ReactNode;
}

export const SlideMenu: React.FC<SlideMenuProps> = ({
  isOpen,
  onClose,
  position = 'left',
  width = '80%',
  className,
  style,
  children
}) => {
  return (
    <>
      {/* Backdrop */}
      {isOpen && (
        <div
          className="slide-menu-backdrop"
          onClick={onClose}
          style={{
            position: 'fixed',
            inset: 0,
            backgroundColor: 'rgba(0, 0, 0, 0.5)',
            zIndex: 1000,
            opacity: isOpen ? 1 : 0,
            transition: 'opacity 0.3s ease'
          }}
        />
      )}

      {/* Menu */}
      <div
        className={cn('slide-menu', `position-${position}`, isOpen && 'is-open', className)}
        style={{
          position: 'fixed',
          top: 0,
          bottom: 0,
          [position]: 0,
          width,
          maxWidth: '100vw',
          backgroundColor: 'var(--color-background)',
          transform: `translateX(${isOpen ? '0' : position === 'left' ? '-100%' : '100%'})`,
          transition: 'transform 0.3s ease',
          zIndex: 1001,
          overflowY: 'auto',
          ...mobileStyles.smoothScroll,
          ...style
        }}
      >
        {children}
      </div>
    </>
  );
};

