/**
 * Material Design app bar
 */
export interface MaterialAppBarProps {
  title?: string;
  type?: 'center' | 'small' | 'medium' | 'large';
  navigationIcon?: React.ReactNode;
  actions?: React.ReactNode[];
  scrolled?: boolean;
  onNavigationClick?: () => void;
}

export const MaterialAppBar: React.FC<MaterialAppBarProps> = ({
  title,
  type = 'small',
  navigationIcon,
  actions,
  scrolled = false,
  onNavigationClick
}) => {
  const [elevation, setElevation] = useState(0);

  useEffect(() => {
    const handleScroll = () => {
      setElevation(window.scrollY > 0 ? 2 : 0);
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const getHeight = () => {
    switch (type) {
      case 'center': return 64;
      case 'small': return 64;
      case 'medium': return scrolled ? 64 : 112;
      case 'large': return scrolled ? 64 : 152;
      default: return 64;
    }
  };

  return (
    <header
      className={`material-app-bar ${type}`}
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        height: getHeight(),
        backgroundColor: 'var(--md-sys-color-surface)',
        boxShadow: elevation > 0 ? materialElevation.level2 : 'none',
        transition: `all ${materialMotion.duration.medium2}ms ${materialMotion.emphasized}`,
        zIndex: 1000,
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'flex-end'
      }}
    >
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          height: 64,
          padding: '0 4px'
        }}
      >
        {navigationIcon && (
          <button
            onClick={onNavigationClick}
            className="material-icon-button"
            style={{
              width: 48,
              height: 48,
              borderRadius: '50%',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              backgroundColor: 'transparent',
              border: 'none',
              cursor: 'pointer',
              color: 'var(--md-sys-color-on-surface)'
            }}
          >
            {navigationIcon}
          </button>
        )}

        <h1
          style={{
            flex: 1,
            fontSize: type === 'large' && !scrolled ? '28px' : '22px',
            fontWeight: 400,
            margin: 0,
            padding: '0 16px',
            textAlign: type === 'center' ? 'center' : 'left',
            transition: `font-size ${materialMotion.duration.medium2}ms ${materialMotion.emphasized}`,
            color: 'var(--md-sys-color-on-surface)'
          }}
        >
          {title}
        </h1>

        {actions && (
          <div style={{ display: 'flex', gap: '4px' }}>
            {actions}
          </div>
        )}
      </div>
    </header>
  );
};

/**
 * Material Design bottom navigation
 */
export interface MaterialBottomNavProps {
  items: Array<{
    id: string;
    label: string;
    icon: React.ReactNode;
    activeIcon?: React.ReactNode;
    badge?: number;
  }>;
  activeItem: string;
  onItemSelect: (id: string) => void;
}

export const MaterialBottomNav: React.FC<MaterialBottomNavProps> = ({
  items,
  activeItem,
  onItemSelect
}) => {
  return (
    <nav
      className="material-bottom-nav"
      style={{
        position: 'fixed',
        bottom: 0,
        left: 0,
        right: 0,
        height: 80,
        backgroundColor: 'var(--md-sys-color-surface-container)',
        boxShadow: materialElevation.level2,
        display: 'flex',
        paddingBottom: 'env(safe-area-inset-bottom, 0)'
      }}
    >
      {items.map(item => {
        const isActive = activeItem === item.id;

        return (
          <button
            key={item.id}
            onClick={() => {
              onItemSelect(item.id);
              HapticFeedback.getInstance().trigger('selection');
            }}
            className={`nav-item ${isActive ? 'active' : ''}`}
            style={{
              flex: 1,
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              gap: '4px',
              backgroundColor: 'transparent',
              border: 'none',
              cursor: 'pointer',
              position: 'relative',
              color: isActive ? 'var(--md-sys-color-on-secondary-container)' : 'var(--md-sys-color-on-surface-variant)',
              transition: `all ${materialMotion.duration.short4}ms ${materialMotion.standard}`
            }}
          >
            <div
              className="nav-indicator"
              style={{
                position: 'absolute',
                top: '12px',
                width: isActive ? '64px' : '0',
                height: '32px',
                borderRadius: '16px',
                backgroundColor: 'var(--md-sys-color-secondary-container)',
                transition: `width ${materialMotion.duration.medium1}ms ${materialMotion.emphasized}`,
                opacity: isActive ? 1 : 0
              }}
            />

            <div style={{ 
              position: 'relative', 
              fontSize: '24px',
              transition: `transform ${materialMotion.duration.short4}ms ${materialMotion.standard}`,
              transform: isActive ? 'translateY(-2px)' : 'translateY(0)'
            }}>
              {isActive && item.activeIcon ? item.activeIcon : item.icon}
            </div>

            <span style={{ 
              fontSize: '12px',
              fontWeight: isActive ? 500 : 400,
              position: 'relative'
            }}>
              {item.label}
            </span>

            {item.badge && item.badge > 0 && (
              <div
                className="badge"
                style={{
                  position: 'absolute',
                  top: '8px',
                  right: 'calc(50% - 20px)',
                  backgroundColor: 'var(--md-sys-color-error)',
                  color: 'var(--md-sys-color-on-error)',
                  borderRadius: '8px',
                  padding: '2px 6px',
                  fontSize: '11px',
                  minWidth: '16px',
                  textAlign: 'center',
                  fontWeight: 500
                }}
              >
                {item.badge > 99 ? '99+' : item.badge}
              </div>
            )}
          </button>
        );
      })}
    </nav>
  );
};

