/**
 * Desktop-specific UI adaptations and features
 */

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { deviceDetector } from '../../responsive/device-detection';

/**
 * Desktop hover states manager
 */
export const useHoverState = () => {
  const [isHovered, setIsHovered] = useState(false);
  const [hoverPosition, setHoverPosition] = useState({ x: 0, y: 0 });

  const hoverProps = {
    onMouseEnter: (e: React.MouseEvent) => {
      setIsHovered(true);
      setHoverPosition({ x: e.clientX, y: e.clientY });
    },
    onMouseLeave: () => setIsHovered(false),
    onMouseMove: (e: React.MouseEvent) => {
      setHoverPosition({ x: e.clientX, y: e.clientY });
    }
  };

  return { isHovered, hoverPosition, hoverProps };
};

/**
 * Keyboard shortcut definition
 */
export interface KeyboardShortcut {
  id: string;
  key: string;
  modifiers?: ('ctrl' | 'cmd' | 'alt' | 'shift')[];
  description: string;
  handler: () => void;
  category?: string;
  enabled?: boolean;
}

/**
 * Keyboard shortcuts manager
 */
export class KeyboardShortcutsManager {
  private shortcuts: Map<string, KeyboardShortcut> = new Map();
  private listeners: ((shortcuts: KeyboardShortcut[]) => void)[] = [];

  constructor() {
    if (typeof window !== 'undefined') {
      window.addEventListener('keydown', this.handleKeyDown);
    }
  }

  register(shortcut: KeyboardShortcut): void {
    const key = this.getShortcutKey(shortcut);
    this.shortcuts.set(key, shortcut);
    this.notifyListeners();
  }

  unregister(id: string): void {
    for (const [key, shortcut] of this.shortcuts.entries()) {
      if (shortcut.id === id) {
        this.shortcuts.delete(key);
        this.notifyListeners();
        break;
      }
    }
  }

  getShortcuts(): KeyboardShortcut[] {
    return Array.from(this.shortcuts.values());
  }

  getShortcutsByCategory(category: string): KeyboardShortcut[] {
    return this.getShortcuts().filter(s => s.category === category);
  }

  subscribe(callback: (shortcuts: KeyboardShortcut[]) => void): () => void {
    this.listeners.push(callback);
    callback(this.getShortcuts());

    return () => {
      const index = this.listeners.indexOf(callback);
      if (index > -1) {
        this.listeners.splice(index, 1);
      }
    };
  }

  private handleKeyDown = (e: KeyboardEvent) => {
    const key = this.getEventKey(e);
    const shortcut = this.shortcuts.get(key);

    if (shortcut && (shortcut.enabled !== false)) {
      e.preventDefault();
      e.stopPropagation();
      shortcut.handler();
    }
  };

  private getShortcutKey(shortcut: KeyboardShortcut): string {
    const modifiers = shortcut.modifiers || [];
    const parts = [...modifiers.sort(), shortcut.key.toLowerCase()];
    return parts.join('+');
  }

  private getEventKey(e: KeyboardEvent): string {
    const modifiers = [];
    const isMac = deviceDetector.getOS() === 'macOS';

    if (e.ctrlKey || (isMac && e.metaKey)) modifiers.push('ctrl');
    if (e.altKey) modifiers.push('alt');
    if (e.shiftKey) modifiers.push('shift');

    const key = e.key.toLowerCase();
    const parts = [...modifiers.sort(), key];
    return parts.join('+');
  }

  private notifyListeners(): void {
    const shortcuts = this.getShortcuts();
    this.listeners.forEach(listener => listener(shortcuts));
  }

  destroy(): void {
    if (typeof window !== 'undefined') {
      window.removeEventListener('keydown', this.handleKeyDown);
    }
    this.shortcuts.clear();
    this.listeners = [];
  }
}

/**
 * React hook for keyboard shortcuts
 */
export const useKeyboardShortcuts = (shortcuts: Omit<KeyboardShortcut, 'id'>[]) => {
  const managerRef = useRef<KeyboardShortcutsManager>();

  useEffect(() => {
    managerRef.current = new KeyboardShortcutsManager();

    shortcuts.forEach((shortcut, index) => {
      managerRef.current!.register({
        ...shortcut,
        id: `shortcut-${index}`
      });
    });

    return () => {
      managerRef.current?.destroy();
    };
  }, [shortcuts]);
};

/**
 * Desktop tooltip component
 */
export interface DesktopTooltipProps {
  content: React.ReactNode;
  position?: 'top' | 'bottom' | 'left' | 'right' | 'auto';
  delay?: number;
  children: React.ReactNode;
}

export const DesktopTooltip: React.FC<DesktopTooltipProps> = ({
  content,
  position = 'auto',
  delay = 500,
  children
}) => {
  const [visible, setVisible] = useState(false);
  const [tooltipPosition, setTooltipPosition] = useState({ x: 0, y: 0 });
  const timeoutRef = useRef<NodeJS.Timeout>();
  const targetRef = useRef<HTMLDivElement>(null);
  const tooltipRef = useRef<HTMLDivElement>(null);

  const showTooltip = useCallback((e: React.MouseEvent) => {
    timeoutRef.current = setTimeout(() => {
      setVisible(true);

      if (targetRef.current && tooltipRef.current) {
        const targetRect = targetRef.current.getBoundingClientRect();
        const tooltipRect = tooltipRef.current.getBoundingClientRect();

        let x = targetRect.left + targetRect.width / 2 - tooltipRect.width / 2;
        let y = targetRect.top - tooltipRect.height - 8;

        // Auto position if needed
        if (position === 'auto' || y < 0) {
          y = targetRect.bottom + 8;
        }

        // Keep on screen
        x = Math.max(8, Math.min(x, window.innerWidth - tooltipRect.width - 8));
        y = Math.max(8, Math.min(y, window.innerHeight - tooltipRect.height - 8));

        setTooltipPosition({ x, y });
      }
    }, delay);
  }, [delay, position]);

  const hideTooltip = useCallback(() => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }
    setVisible(false);
  }, []);

  return (
    <>
      <div
        ref={targetRef}
        onMouseEnter={showTooltip}
        onMouseLeave={hideTooltip}
        style={{ display: 'inline-block' }}
      >
        {children}
      </div>

      {visible && (
        <div
          ref={tooltipRef}
          className="desktop-tooltip"
          style={{
            position: 'fixed',
            left: tooltipPosition.x,
            top: tooltipPosition.y,
            backgroundColor: 'rgba(0, 0, 0, 0.9)',
            color: 'white',
            padding: '6px 12px',
            borderRadius: '4px',
            fontSize: '12px',
            whiteSpace: 'nowrap',
            pointerEvents: 'none',
            zIndex: 10000,
            opacity: visible ? 1 : 0,
            transition: 'opacity 0.2s ease'
          }}
        >
          {content}
        </div>
      )}
    </>
  );
};

/**
 * Desktop context menu
 */
export interface DesktopContextMenuProps {
  items: Array<{
    label: string;
    icon?: React.ReactNode;
    shortcut?: string;
    disabled?: boolean;
    danger?: boolean;
    separator?: boolean;
    submenu?: any[];
    onClick?: () => void;
  }>;
  children: React.ReactNode;
}

export const DesktopContextMenu: React.FC<DesktopContextMenuProps> = ({
  items,
  children
}) => {
  const [visible, setVisible] = useState(false);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const menuRef = useRef<HTMLDivElement>(null);

  const handleContextMenu = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    setPosition({ x: e.clientX, y: e.clientY });
    setVisible(true);
  }, []);

  const handleClickOutside = useCallback((e: MouseEvent) => {
    if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
      setVisible(false);
    }
  }, []);

  useEffect(() => {
    if (visible) {
      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }
  }, [visible, handleClickOutside]);

  return (
    <>
      <div onContextMenu={handleContextMenu}>
        {children}
      </div>

      {visible && (
        <div
          ref={menuRef}
          className="desktop-context-menu"
          style={{
            position: 'fixed',
            left: position.x,
            top: position.y,
            backgroundColor: 'var(--color-background)',
            border: '1px solid var(--color-border)',
            borderRadius: '6px',
            boxShadow: '0 2px 8px rgba(0, 0, 0, 0.15)',
            padding: '4px 0',
            minWidth: '200px',
            zIndex: 10000
          }}
        >
          {items.map((item, index) => {
            if (item.separator) {
              return <div key={index} className="menu-separator" style={{
                height: '1px',
                backgroundColor: 'var(--color-border)',
                margin: '4px 8px'
              }} />;
            }

            return (
              <button
                key={index}
                className="menu-item"
                disabled={item.disabled}
                onClick={() => {
                  item.onClick?.();
                  setVisible(false);
                }}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  width: '100%',
                  padding: '8px 16px',
                  backgroundColor: 'transparent',
                  border: 'none',
                  cursor: item.disabled ? 'not-allowed' : 'pointer',
                  opacity: item.disabled ? 0.5 : 1,
                  color: item.danger ? 'var(--color-danger)' : 'var(--color-text)',
                  fontSize: '14px',
                  transition: 'background-color 0.1s ease'
                }}
                onMouseEnter={(e) => {
                  if (!item.disabled) {
                    e.currentTarget.style.backgroundColor = 'var(--color-hover)';
                  }
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.backgroundColor = 'transparent';
                }}
              >
                {item.icon && <span style={{ marginRight: '8px' }}>{item.icon}</span>}
                <span style={{ flex: 1, textAlign: 'left' }}>{item.label}</span>
                {item.shortcut && (
                  <span style={{ 
                    fontSize: '12px', 
                    color: 'var(--color-text-secondary)',
                    marginLeft: '16px'
                  }}>
                    {item.shortcut}
                  </span>
                )}
              </button>
            );
          })}
        </div>
      )}
    </>
  );
};

