/**
 * Enhanced breakpoint management system
 */

import { Theme } from '../types';

export interface Breakpoints {
  xs: number;      // Extra small devices (phones) < 576px
  sm: number;      // Small devices (landscape phones) >= 576px
  md: number;      // Medium devices (tablets) >= 768px
  lg: number;      // Large devices (desktops) >= 1024px
  xl: number;      // Extra large devices (large desktops) >= 1280px
  xxl: number;     // Extra extra large devices >= 1536px
}

export const defaultBreakpoints: Breakpoints = {
  xs: 0,
  sm: 576,
  md: 768,
  lg: 1024,
  xl: 1280,
  xxl: 1536
};

export type BreakpointKey = keyof Breakpoints;

export interface BreakpointConfig {
  breakpoints: Breakpoints;
  defaultBreakpoint: BreakpointKey;
  mobileFirst: boolean;
}

export const defaultBreakpointConfig: BreakpointConfig = {
  breakpoints: defaultBreakpoints,
  defaultBreakpoint: 'md',
  mobileFirst: true
};

/**
 * Get the current breakpoint based on viewport width
 */
export function getCurrentBreakpoint(
  width: number, 
  breakpoints: Breakpoints = defaultBreakpoints
): BreakpointKey {
  const sortedBreakpoints = Object.entries(breakpoints)
    .sort(([, a], [, b]) => b - a);

  for (const [key, value] of sortedBreakpoints) {
    if (width >= value) {
      return key as BreakpointKey;
    }
  }

  return 'xs';
}

/**
 * Check if viewport matches a specific breakpoint
 */
export function matchesBreakpoint(
  width: number,
  breakpoint: BreakpointKey,
  breakpoints: Breakpoints = defaultBreakpoints
): boolean {
  const current = getCurrentBreakpoint(width, breakpoints);
  const sortedKeys = Object.keys(breakpoints) as BreakpointKey[];
  const currentIndex = sortedKeys.indexOf(current);
  const targetIndex = sortedKeys.indexOf(breakpoint);

  return currentIndex >= targetIndex;
}

/**
 * Generate media query for a breakpoint
 */
export function createMediaQuery(
  breakpoint: BreakpointKey,
  type: 'up' | 'down' | 'only' = 'up',
  breakpoints: Breakpoints = defaultBreakpoints
): string {
  const value = breakpoints[breakpoint];
  const sortedKeys = Object.keys(breakpoints) as BreakpointKey[];
  const index = sortedKeys.indexOf(breakpoint);

  switch (type) {
    case 'up':
      return `(min-width: ${value}px)`;

    case 'down':
      const nextBreakpoint = sortedKeys[index + 1];
      const maxWidth = nextBreakpoint ? breakpoints[nextBreakpoint] - 1 : Infinity;
      return maxWidth === Infinity 
        ? `(min-width: 0px)` 
        : `(max-width: ${maxWidth}px)`;

    case 'only':
      const nextBp = sortedKeys[index + 1];
      if (!nextBp) {
        return `(min-width: ${value}px)`;
      }
      const max = breakpoints[nextBp] - 1;
      return `(min-width: ${value}px) and (max-width: ${max}px)`;

    default:
      return `(min-width: ${value}px)`;
  }
}

/**
 * Resolve a responsive value based on current breakpoint
 */
export function resolveResponsiveValue<T>(
  values: Partial<Record<BreakpointKey, T>>,
  currentBreakpoint: BreakpointKey,
  defaultValue?: T
): T | undefined {
  const sortedKeys = Object.keys(defaultBreakpoints) as BreakpointKey[];
  const currentIndex = sortedKeys.indexOf(currentBreakpoint);

  // Check from current breakpoint down to find a value
  for (let i = currentIndex; i >= 0; i--) {
    const key = sortedKeys[i];
    if (values[key] !== undefined) {
      return values[key];
    }
  }

  return defaultValue;
}

/**
 * Create CSS object with responsive values
 */
export function createResponsiveStyles<T>(
  property: string,
  values: Partial<Record<BreakpointKey, T>>,
  transform?: (value: T) => string | number,
  breakpoints: Breakpoints = defaultBreakpoints
): Record<string, any> {
  const styles: Record<string, any> = {};
  const sortedEntries = Object.entries(values)
    .filter(([, value]) => value !== undefined)
    .sort(([a], [b]) => breakpoints[a as BreakpointKey] - breakpoints[b as BreakpointKey]);

  // Base style (smallest breakpoint)
  const [firstKey, firstValue] = sortedEntries[0] || [];
  if (firstKey && firstValue !== undefined) {
    styles[property] = transform ? transform(firstValue) : firstValue;
  }

  // Media query styles
  sortedEntries.slice(1).forEach(([key, value]) => {
    if (value !== undefined) {
      const mediaQuery = `@media ${createMediaQuery(key as BreakpointKey, 'up', breakpoints)}`;
      styles[mediaQuery] = {
        [property]: transform ? transform(value) : value
      };
    }
  });

  return styles;
}

/**
 * Breakpoint helper utilities
 */
export const breakpoints = {
  up: (bp: BreakpointKey, bps = defaultBreakpoints) => 
    createMediaQuery(bp, 'up', bps),

  down: (bp: BreakpointKey, bps = defaultBreakpoints) => 
    createMediaQuery(bp, 'down', bps),

  only: (bp: BreakpointKey, bps = defaultBreakpoints) => 
    createMediaQuery(bp, 'only', bps),

  between: (start: BreakpointKey, end: BreakpointKey, bps = defaultBreakpoints) => {
    const min = bps[start];
    const max = bps[end] - 1;
    return `(min-width: ${min}px) and (max-width: ${max}px)`;
  }
};

/**
 * Adaptive container components
 */

import React, { useState, useEffect } from 'react';
import { cn } from '../utils';
import { useResponsive } from '../hooks';
import { BreakpointKey } from './breakpoints';

export interface CollapsiblePanelProps {
  title: string;
  defaultOpen?: boolean;
  collapsible?: boolean;
  collapseOn?: BreakpointKey | BreakpointKey[];
  icon?: React.ReactNode;
  actions?: React.ReactNode;
  className?: string;
  headerClassName?: string;
  contentClassName?: string;
  children: React.ReactNode;
  onToggle?: (isOpen: boolean) => void;
}

/**
 * Collapsible panel that can auto-collapse on specific breakpoints
 */
export const CollapsiblePanel: React.FC<CollapsiblePanelProps> = ({
  title,
  defaultOpen = true,
  collapsible = true,
  collapseOn,
  icon,
  actions,
  className,
  headerClassName,
  contentClassName,
  children,
  onToggle
}) => {
  const [isOpen, setIsOpen] = useState(defaultOpen);
  const { breakpoint } = useResponsive();

  // Auto-collapse based on breakpoint
  useEffect(() => {
    if (collapseOn) {
      const breakpoints = Array.isArray(collapseOn) ? collapseOn : [collapseOn];
      const shouldCollapse = breakpoints.includes(breakpoint);
      setIsOpen(!shouldCollapse);
    }
  }, [breakpoint, collapseOn]);

  const handleToggle = () => {
    if (!collapsible) return;
    const newState = !isOpen;
    setIsOpen(newState);
    onToggle?.(newState);
  };

  return (
    <div className={cn('ui-collapsible-panel', className)}>
      <div
        className={cn(
          'ui-panel-header',
          collapsible && 'cursor-pointer',
          headerClassName
        )}
        onClick={handleToggle}
        role={collapsible ? 'button' : undefined}
        tabIndex={collapsible ? 0 : undefined}
        onKeyDown={(e) => {
          if (collapsible && (e.key === 'Enter' || e.key === ' ')) {
            e.preventDefault();
            handleToggle();
          }
        }}
      >
        <div className="flex items-center gap-2">
          {collapsible && (
            <span className="ui-collapse-icon">
              {isOpen ? '▼' : '▶'}
            </span>
          )}
          {icon && <span className="ui-panel-icon">{icon}</span>}
          <h3 className="ui-panel-title">{title}</h3>
        </div>
        {actions && (
          <div className="ui-panel-actions" onClick={(e) => e.stopPropagation()}>
            {actions}
          </div>
        )}
      </div>
      {isOpen && (
        <div className={cn('ui-panel-content', contentClassName)}>
          {children}
        </div>
      )}
    </div>
  );
};

export interface AdaptiveLayoutProps {
  sidebar?: React.ReactNode;
  sidebarPosition?: 'left' | 'right';
  sidebarWidth?: number | string;
  sidebarCollapsible?: boolean;
  sidebarCollapseOn?: BreakpointKey | BreakpointKey[];
  main: React.ReactNode;
  header?: React.ReactNode;
  footer?: React.ReactNode;
  className?: string;
}

/**
 * Adaptive layout that adjusts based on viewport
 */
export const AdaptiveLayout: React.FC<AdaptiveLayoutProps> = ({
  sidebar,
  sidebarPosition = 'left',
  sidebarWidth = 280,
  sidebarCollapsible = true,
  sidebarCollapseOn = ['xs', 'sm'],
  main,
  header,
  footer,
  className
}) => {
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const { breakpoint } = useResponsive();

  // Auto-collapse sidebar on small screens
  useEffect(() => {
    if (sidebarCollapseOn) {
      const breakpoints = Array.isArray(sidebarCollapseOn) ? sidebarCollapseOn : [sidebarCollapseOn];
      const shouldCollapse = breakpoints.includes(breakpoint);
      setSidebarOpen(!shouldCollapse);
    }
  }, [breakpoint, sidebarCollapseOn]);

  return (
    <div className={cn('ui-adaptive-layout', className)}>
      {header && <div className="ui-layout-header">{header}</div>}

      <div className="ui-layout-body">
        {sidebar && sidebarOpen && (
          <aside
            className={cn(
              'ui-layout-sidebar',
              `ui-sidebar-${sidebarPosition}`
            )}
            style={{ width: sidebarWidth }}
          >
            {sidebar}
          </aside>
        )}

        <main className="ui-layout-main">
          {sidebarCollapsible && sidebar && !sidebarOpen && (
            <button
              className="ui-sidebar-toggle"
              onClick={() => setSidebarOpen(true)}
              aria-label="Open sidebar"
            >
              ☰
            </button>
          )}
          {main}
        </main>
      </div>

      {footer && <div className="ui-layout-footer">{footer}</div>}
    </div>
  );
};

export interface ResponsiveDrawerProps {
  open: boolean;
  onClose: () => void;
  anchor?: 'left' | 'right' | 'top' | 'bottom';
  variant?: 'temporary' | 'persistent' | 'permanent';
  breakpoint?: BreakpointKey;
  width?: number | string;
  className?: string;
  children: React.ReactNode;
}

/**
 * Responsive drawer that adapts behavior based on screen size
 */
export const ResponsiveDrawer: React.FC<ResponsiveDrawerProps> = ({
  open,
  onClose,
  anchor = 'left',
  variant = 'temporary',
  breakpoint = 'md',
  width = 280,
  className,
  children
}) => {
  const { breakpoint: currentBreakpoint } = useResponsive();
  const breakpointOrder = ['xs', 'sm', 'md', 'lg', 'xl', 'xxl'];
  const isLargeScreen = breakpointOrder.indexOf(currentBreakpoint) >= breakpointOrder.indexOf(breakpoint);

  const actualVariant = isLargeScreen && variant === 'temporary' ? 'persistent' : variant;

  if (!open && actualVariant === 'temporary') {
    return null;
  }

  return (
    <>
      {actualVariant === 'temporary' && (
        <div
          className="ui-drawer-backdrop"
          onClick={onClose}
          aria-hidden="true"
        />
      )}

      <div
        className={cn(
          'ui-drawer',
          `ui-drawer-${anchor}`,
          `ui-drawer-${actualVariant}`,
          open && 'ui-drawer-open',
          className
        )}
        style={{
          width: anchor === 'left' || anchor === 'right' ? width : '100%',
          height: anchor === 'top' || anchor === 'bottom' ? width : '100%'
        }}
      >
        {actualVariant === 'temporary' && (
          <button
            className="ui-drawer-close"
            onClick={onClose}
            aria-label="Close drawer"
          >
            ×
          </button>
        )}
        {children}
      </div>
    </>
  );
};

export interface TabsProps {
  tabs: Array<{
    id: string;
    label: string;
    content: React.ReactNode;
    icon?: React.ReactNode;
    disabled?: boolean;
  }>;
  defaultTab?: string;
  orientation?: 'horizontal' | 'vertical';
  variant?: 'default' | 'pills' | 'underline';
  stackOn?: BreakpointKey | BreakpointKey[];
  className?: string;
  onChange?: (tabId: string) => void;
}

/**
 * Responsive tabs that can stack on small screens
 */
export const ResponsiveTabs: React.FC<TabsProps> = ({
  tabs,
  defaultTab,
  orientation = 'horizontal',
  variant = 'default',
  stackOn = ['xs', 'sm'],
  className,
  onChange
}) => {
  const [activeTab, setActiveTab] = useState(defaultTab || tabs[0]?.id);
  const { breakpoint } = useResponsive();

  const shouldStack = Array.isArray(stackOn) 
    ? stackOn.includes(breakpoint)
    : breakpoint === stackOn;

  const handleTabChange = (tabId: string) => {
    setActiveTab(tabId);
    onChange?.(tabId);
  };

  const actualOrientation = shouldStack ? 'vertical' : orientation;

  return (
    <div
      className={cn(
        'ui-tabs',
        `ui-tabs-${actualOrientation}`,
        `ui-tabs-${variant}`,
        className
      )}
    >
      <div className="ui-tabs-list" role="tablist">
        {tabs.map((tab) => (
          <button
            key={tab.id}
            className={cn(
              'ui-tab',
              activeTab === tab.id && 'ui-tab-active',
              tab.disabled && 'ui-tab-disabled'
            )}
            role="tab"
            aria-selected={activeTab === tab.id}
            aria-controls={`tabpanel-${tab.id}`}
            disabled={tab.disabled}
            onClick={() => handleTabChange(tab.id)}
          >
            {tab.icon && <span className="ui-tab-icon">{tab.icon}</span>}
            <span className="ui-tab-label">{tab.label}</span>
          </button>
        ))}
      </div>

      <div className="ui-tabs-panels">
        {tabs.map((tab) => (
          <div
            key={tab.id}
            id={`tabpanel-${tab.id}`}
            className={cn(
              'ui-tab-panel',
              activeTab === tab.id && 'ui-tab-panel-active'
            )}
            role="tabpanel"
            aria-labelledby={`tab-${tab.id}`}
            hidden={activeTab !== tab.id}
          >
            {tab.content}
          </div>
        ))}
      </div>
    </div>
  );
};

/**
 * Enhanced device detection and targeting
 */

export interface DeviceInfo {
  type: 'mobile' | 'tablet' | 'desktop' | 'tv';
  os: 'ios' | 'android' | 'windows' | 'macos' | 'linux' | 'unknown';
  browser: 'chrome' | 'firefox' | 'safari' | 'edge' | 'opera' | 'unknown';
  orientation: 'portrait' | 'landscape';
  touch: boolean;
  retina: boolean;
  dpr: number;
  gpu: 'high' | 'medium' | 'low';
  connection: 'fast' | 'slow' | 'offline';
}

/**
 * Detect device type from user agent and screen size
 */
export function detectDeviceType(): DeviceInfo['type'] {
  if (typeof window === 'undefined') return 'desktop';

  const ua = navigator.userAgent.toLowerCase();
  const width = window.screen.width;

  // TV detection
  if (ua.includes('smart-tv') || ua.includes('smarttv') || 
      ua.includes('googletv') || ua.includes('appletv')) {
    return 'tv';
  }

  // Mobile detection
  if (/mobile|android|iphone|ipod|blackberry|opera mini|iemobile/i.test(ua)) {
    return 'mobile';
  }

  // Tablet detection
  if (/ipad|tablet|playbook|silk/i.test(ua) || 
      (width >= 768 && width <= 1024 && 'ontouchstart' in window)) {
    return 'tablet';
  }

  return 'desktop';
}

/**
 * Detect operating system
 */
export function detectOS(): DeviceInfo['os'] {
  if (typeof window === 'undefined') return 'unknown';

  const ua = navigator.userAgent.toLowerCase();
  const platform = navigator.platform.toLowerCase();

  if (ua.includes('iphone') || ua.includes('ipad') || platform.includes('mac')) {
    return 'ios';
  }
  if (ua.includes('android')) return 'android';
  if (ua.includes('windows') || platform.includes('win')) return 'windows';
  if (platform.includes('mac')) return 'macos';
  if (platform.includes('linux')) return 'linux';

  return 'unknown';
}

/**
 * Detect browser
 */
export function detectBrowser(): DeviceInfo['browser'] {
  if (typeof window === 'undefined') return 'unknown';

  const ua = navigator.userAgent.toLowerCase();

  if (ua.includes('chrome') && !ua.includes('edge')) return 'chrome';
  if (ua.includes('firefox')) return 'firefox';
  if (ua.includes('safari') && !ua.includes('chrome')) return 'safari';
  if (ua.includes('edge')) return 'edge';
  if (ua.includes('opera') || ua.includes('opr')) return 'opera';

  return 'unknown';
}

/**
 * Detect device orientation
 */
export function detectOrientation(): DeviceInfo['orientation'] {
  if (typeof window === 'undefined') return 'portrait';

  if ('orientation' in window) {
    return Math.abs(window.orientation as number) === 90 ? 'landscape' : 'portrait';
  }

  return window.innerWidth > window.innerHeight ? 'landscape' : 'portrait';
}

/**
 * Detect GPU performance tier
 */
export function detectGPU(): DeviceInfo['gpu'] {
  if (typeof window === 'undefined') return 'medium';

  // Simple heuristic based on device pixel ratio and screen size
  const dpr = window.devicePixelRatio || 1;
  const screenPixels = window.screen.width * window.screen.height;

  if (dpr >= 3 && screenPixels > 2000000) return 'high';
  if (dpr < 2 || screenPixels < 1000000) return 'low';

  return 'medium';
}

/**
 * Detect connection speed
 */
export function detectConnection(): DeviceInfo['connection'] {
  if (typeof window === 'undefined') return 'fast';

  if (!navigator.onLine) return 'offline';

  // Use Network Information API if available
  const connection = (navigator as any).connection || 
                    (navigator as any).mozConnection || 
                    (navigator as any).webkitConnection;

  if (connection) {
    const effectiveType = connection.effectiveType;
    if (effectiveType === 'slow-2g' || effectiveType === '2g') return 'slow';
    if (effectiveType === '3g') return 'slow';
  }

  return 'fast';
}

/**
 * Get comprehensive device information
 */
export function getDeviceInfo(): DeviceInfo {
  return {
    type: detectDeviceType(),
    os: detectOS(),
    browser: detectBrowser(),
    orientation: detectOrientation(),
    touch: 'ontouchstart' in window || navigator.maxTouchPoints > 0,
    retina: window.devicePixelRatio > 1,
    dpr: window.devicePixelRatio || 1,
    gpu: detectGPU(),
    connection: detectConnection()
  };
}

/**
 * Device capability checks
 */
export const deviceCapabilities = {
  hasTouch: () => 'ontouchstart' in window || navigator.maxTouchPoints > 0,
  hasHover: () => window.matchMedia('(hover: hover)').matches,
  hasPointer: () => window.matchMedia('(pointer: fine)').matches,
  hasKeyboard: () => !deviceCapabilities.hasTouch() || detectDeviceType() === 'desktop',
  hasNotch: () => {
    // iOS notch detection
    const hasNotch = (window as any).CSS && 
      CSS.supports('padding-top: env(safe-area-inset-top)') &&
      parseInt(getComputedStyle(document.documentElement).getPropertyValue('env(safe-area-inset-top)') || '0') > 0;
    return hasNotch;
  },
  supportsVibration: () => 'vibrate' in navigator,
  supportsClipboard: () => 'clipboard' in navigator,
  supportsShare: () => 'share' in navigator,
  supportsNotifications: () => 'Notification' in window,
  supportsFullscreen: () => 
    'requestFullscreen' in document.documentElement ||
    'webkitRequestFullscreen' in document.documentElement ||
    'mozRequestFullScreen' in document.documentElement ||
    'msRequestFullscreen' in document.documentElement
};

/**
 * Performance-based feature detection
 */
export function getPerformanceFeatures() {
  const info = getDeviceInfo();
  const isLowEnd = info.gpu === 'low' || info.connection === 'slow';

  return {
    enableAnimations: !isLowEnd && !window.matchMedia('(prefers-reduced-motion: reduce)').matches,
    enableParallax: !isLowEnd && info.type === 'desktop',
    enableBlur: !isLowEnd,
    enableShadows: !isLowEnd,
    enableTransitions: !window.matchMedia('(prefers-reduced-motion: reduce)').matches,
    maxConcurrentAnimations: isLowEnd ? 2 : 10,
    debounceDelay: isLowEnd ? 500 : 250,
    throttleDelay: isLowEnd ? 100 : 50
  };
}

/**
 * Platform-specific adjustments
 */
export function getPlatformAdjustments() {
  const info = getDeviceInfo();

  return {
    // Touch target sizes
    minTouchTarget: info.touch ? 44 : 24,

    // Scroll behavior
    scrollBehavior: info.os === 'ios' ? '-webkit-overflow-scrolling: touch' : 'auto',

    // Safe areas for notched devices
    safeAreaInsets: deviceCapabilities.hasNotch() ? {
      top: 'env(safe-area-inset-top)',
      right: 'env(safe-area-inset-right)',
      bottom: 'env(safe-area-inset-bottom)',
      left: 'env(safe-area-inset-left)'
    } : null,

    // Font adjustments
    fontSmoothing: info.os === 'macos' || info.os === 'ios' ? {
      '-webkit-font-smoothing': 'antialiased',
      '-moz-osx-font-smoothing': 'grayscale'
    } : {},

    // Input adjustments
    inputMode: info.type === 'mobile' ? {
      autoComplete: 'off',
      autoCorrect: 'off',
      autoCapitalize: 'off',
      spellCheck: false
    } : {}
  };
}

/**
 * Responsive grid system
 */

import React from 'react';
import { Theme } from '../types';
import { BreakpointKey, createResponsiveStyles } from './breakpoints';
import { cn } from '../utils';

export interface GridProps {
  container?: boolean;
  item?: boolean;
  spacing?: number | Partial<Record<BreakpointKey, number>>;
  columns?: number | Partial<Record<BreakpointKey, number>>;
  xs?: number | 'auto';
  sm?: number | 'auto';
  md?: number | 'auto';
  lg?: number | 'auto';
  xl?: number | 'auto';
  xxl?: number | 'auto';
  direction?: 'row' | 'column' | Partial<Record<BreakpointKey, 'row' | 'column'>>;
  justify?: 'start' | 'center' | 'end' | 'space-between' | 'space-around' | 'space-evenly';
  align?: 'start' | 'center' | 'end' | 'stretch' | 'baseline';
  wrap?: boolean | 'nowrap' | 'wrap' | 'wrap-reverse';
  className?: string;
  style?: React.CSSProperties;
  children?: React.ReactNode;
}

/**
 * Calculate grid item width based on columns
 */
function calculateWidth(span?: number | 'auto', columns: number = 12): string {
  if (span === 'auto') return 'auto';
  if (!span || span < 1) return '100%';
  return `${(span / columns) * 100}%`;
}

/**
 * Create grid container styles
 */
function createGridContainerStyles(
  props: GridProps,
  theme: Theme
): React.CSSProperties {
  const {
    spacing = 0,
    direction = 'row',
    justify,
    align,
    wrap = true
  } = props;

  const styles: React.CSSProperties = {
    display: 'flex',
    boxSizing: 'border-box'
  };

  // Spacing
  if (typeof spacing === 'object') {
    Object.assign(styles, createResponsiveStyles(
      'gap',
      spacing,
      (value) => `${theme.spacing.sm * value}px`
    ));
  } else {
    styles.gap = `${theme.spacing.sm * spacing}px`;
  }

  // Direction
  if (typeof direction === 'object') {
    Object.assign(styles, createResponsiveStyles('flexDirection', direction));
  } else {
    styles.flexDirection = direction;
  }

  // Justify
  if (justify) {
    styles.justifyContent = justify.replace('space-', 'space-');
  }

  // Align
  if (align) {
    styles.alignItems = align === 'start' ? 'flex-start' : 
                      align === 'end' ? 'flex-end' : align;
  }

  // Wrap
  if (typeof wrap === 'boolean') {
    styles.flexWrap = wrap ? 'wrap' : 'nowrap';
  } else {
    styles.flexWrap = wrap;
  }

  return styles;
}

/**
 * Create grid item styles
 */
function createGridItemStyles(
  props: GridProps,
  theme: Theme
): React.CSSProperties {
  const { columns = 12 } = props;
  const styles: React.CSSProperties = {
    boxSizing: 'border-box'
  };

  // Column spans
  const columnSpans: Partial<Record<BreakpointKey, number | 'auto'>> = {};

  if (props.xs !== undefined) columnSpans.xs = props.xs;
  if (props.sm !== undefined) columnSpans.sm = props.sm;
  if (props.md !== undefined) columnSpans.md = props.md;
  if (props.lg !== undefined) columnSpans.lg = props.lg;
  if (props.xl !== undefined) columnSpans.xl = props.xl;
  if (props.xxl !== undefined) columnSpans.xxl = props.xxl;

  // Calculate responsive widths
  if (Object.keys(columnSpans).length > 0) {
    const widthValues: Partial<Record<BreakpointKey, string>> = {};

    Object.entries(columnSpans).forEach(([breakpoint, span]) => {
      const cols = typeof columns === 'object' 
        ? columns[breakpoint as BreakpointKey] || 12 
        : columns;
      widthValues[breakpoint as BreakpointKey] = calculateWidth(span, cols);
    });

    Object.assign(styles, createResponsiveStyles('flexBasis', widthValues));
    Object.assign(styles, createResponsiveStyles('maxWidth', widthValues));
  }

  return styles;
}

/**
 * Responsive grid component
 */
export const Grid = React.forwardRef<HTMLDivElement, GridProps>((props, ref) => {
  const {
    container,
    item,
    className,
    style,
    children,
    ...rest
  } = props;

  const theme: Theme = {
    colors: {} as any,
    spacing: { xs: 4, sm: 8, md: 16, lg: 24, xl: 32 },
    typography: {} as any,
    borderRadius: 8,
    shadows: {} as any,
    breakpoints: {} as any
  };

  let computedStyles: React.CSSProperties = {};

  if (container) {
    computedStyles = createGridContainerStyles(props, theme);
  } else if (item) {
    computedStyles = createGridItemStyles(props, theme);
  }

  return (
    <div
      ref={ref}
      className={cn('ui-grid', className)}
      style={{
        ...computedStyles,
        ...style
      }}
    >
      {children}
    </div>
  );
});

Grid.displayName = 'Grid';

