};

/**
 * Touch gestures for node manipulation in graph editor
 */

import React, { useRef, useEffect, useState } from 'react';
import { GraphNode, GraphEdge } from '@prompt-spaghetti/graph-core';
import { TouchManager } from './TouchManager';
import { GestureEvent } from './gestures';
import { touchTargetUtils } from './accessibility';
import { VisualFeedback } from './feedback';
import { TOUCH_TARGETS } from '../mobile/design-system';

export interface NodeGestureHandlers {
  onNodeSelect?: (nodeId: string, multiSelect: boolean) => void;
  onNodeMove?: (nodeId: string, position: { x: number; y: number }) => void;
  onNodeDelete?: (nodeId: string) => void;
  onNodeEdit?: (nodeId: string) => void;
  onNodeConnect?: (sourceId: string, targetId: string) => void;
  onNodeContextMenu?: (nodeId: string, position: { x: number; y: number }) => void;
  onCanvasPan?: (delta: { x: number; y: number }) => void;
  onCanvasZoom?: (scale: number, center: { x: number; y: number }) => void;
  onSelectionBox?: (bounds: { x: number; y: number; width: number; height: number }) => void;
}

export interface TouchableNodeProps {
  node: GraphNode;
  isSelected: boolean;
  canConnect: boolean;
  handlers: NodeGestureHandlers;
  children: React.ReactNode;
}

/**
 * Touchable node wrapper with gesture support
 */
export const TouchableNode: React.FC<TouchableNodeProps> = ({
  node,
  isSelected,
  canConnect,
  handlers,
  children
}) => {
  const nodeRef = useRef<HTMLDivElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [isConnecting, setIsConnecting] = useState(false);
  const dragStartPos = useRef<{ x: number; y: number } | null>(null);

  useEffect(() => {
    if (!nodeRef.current) return;

    // Ensure accessible touch target
    touchTargetUtils.ensureMinimumSize(nodeRef.current, TOUCH_TARGETS.large);

    const touchManager = new TouchManager({
      element: nodeRef.current,
      handlers: {
        tap: (e: GestureEvent) => {
          handlers.onNodeSelect?.(node.id, e.touches.length > 1);

          // Visual feedback for selection
          VisualFeedback.trigger(nodeRef.current!, {
            enabled: true,
            type: 'highlight',
            duration: 200,
            color: 'var(--color-primary)'
          });
        },

        doubleTap: (e: GestureEvent) => {
          handlers.onNodeEdit?.(node.id);
        },

        longPress: (e: GestureEvent) => {
          handlers.onNodeContextMenu?.(node.id, e.center);
        },

        drag: (e: GestureEvent) => {
          if (!dragStartPos.current) {
            dragStartPos.current = {
              x: node.position?.x || 0,
              y: node.position?.y || 0
            };
            setIsDragging(true);
          }

          const newPosition = {
            x: dragStartPos.current.x + e.deltaX,
            y: dragStartPos.current.y + e.deltaY
          };

          handlers.onNodeMove?.(node.id, newPosition);
        }
      }
    });

    // Handle drag end
    const handleDragEnd = () => {
      dragStartPos.current = null;
      setIsDragging(false);
      setIsConnecting(false);
    };

    nodeRef.current.addEventListener('touchend', handleDragEnd);
    nodeRef.current.addEventListener('mouseup', handleDragEnd);

    return () => {
      touchManager.destroy();
      nodeRef.current?.removeEventListener('touchend', handleDragEnd);
      nodeRef.current?.removeEventListener('mouseup', handleDragEnd);
    };
  }, [node, handlers]);

  return (
    <div
      ref={nodeRef}
      className={`touchable-node ${isSelected ? 'selected' : ''} ${isDragging ? 'dragging' : ''}`}
      style={{
        position: 'absolute',
        left: node.position?.x || 0,
        top: node.position?.y || 0,
        cursor: isDragging ? 'grabbing' : 'grab',
        touchAction: 'none',
        userSelect: 'none',
        WebkitUserSelect: 'none',
        transform: isDragging ? 'scale(1.05)' : 'scale(1)',
        transition: isDragging ? 'none' : 'transform 0.2s',
        zIndex: isDragging ? 1000 : isSelected ? 100 : 1
      }}
    >
      {children}

      {/* Connection handles */}
      {canConnect && (
        <>
          <ConnectionHandle
            type="input"
            nodeId={node.id}
            onConnect={handlers.onNodeConnect}
          />
          <ConnectionHandle
            type="output"
            nodeId={node.id}
            onConnect={handlers.onNodeConnect}
          />
        </>
      )}
    </div>
  );
};

/**
 * Connection handle for creating edges
 */
interface ConnectionHandleProps {
  type: 'input' | 'output';
  nodeId: string;
  onConnect?: (sourceId: string, targetId: string) => void;
}

const ConnectionHandle: React.FC<ConnectionHandleProps> = ({ type, nodeId, onConnect }) => {
  const handleRef = useRef<HTMLDivElement>(null);
  const [isConnecting, setIsConnecting] = useState(false);
  const connectionLine = useRef<HTMLDivElement | null>(null);
  const startPos = useRef<{ x: number; y: number } | null>(null);

  useEffect(() => {
    if (!handleRef.current) return;

    const touchManager = new TouchManager({
      element: handleRef.current,
      config: {
        preventDefault: true,
        longPressDelay: 300
      },
      handlers: {
        drag: (e: GestureEvent) => {
          if (!isConnecting) {
            setIsConnecting(true);
            startPos.current = e.center;
            createConnectionLine();
          }

          updateConnectionLine(e.center);
        }
      }
    });

    return () => touchManager.destroy();
  }, []);

  const createConnectionLine = () => {
    const line = document.createElement('div');
    line.className = 'connection-line';
    line.style.cssText = `
      position: fixed;
      background: var(--color-primary);
      height: 2px;
      transform-origin: left center;
      pointer-events: none;
      z-index: 9999;
    `;
    document.body.appendChild(line);
    connectionLine.current = line;
  };

  const updateConnectionLine = (endPos: { x: number; y: number }) => {
    if (!connectionLine.current || !startPos.current) return;

    const dx = endPos.x - startPos.current.x;
    const dy = endPos.y - startPos.current.y;
    const distance = Math.sqrt(dx * dx + dy * dy);
    const angle = Math.atan2(dy, dx) * 180 / Math.PI;

    connectionLine.current.style.left = `${startPos.current.x}px`;
    connectionLine.current.style.top = `${startPos.current.y}px`;
    connectionLine.current.style.width = `${distance}px`;
    connectionLine.current.style.transform = `rotate(${angle}deg)`;
  };

  const endConnection = (e: TouchEvent | MouseEvent) => {
    if (!isConnecting) return;

    // Find target node handle
    const point = e instanceof TouchEvent ? e.changedTouches[0] : e;
    const target = document.elementFromPoint(point.clientX, point.clientY);

    if (target && target.classList.contains('connection-handle')) {
      const targetNodeId = target.getAttribute('data-node-id');
      const targetType = target.getAttribute('data-handle-type');

      if (targetNodeId && targetType !== type) {
        if (type === 'output') {
          onConnect?.(nodeId, targetNodeId);
        } else {
          onConnect?.(targetNodeId, nodeId);
        }
      }
    }

    // Clean up
    connectionLine.current?.remove();
    connectionLine.current = null;
    setIsConnecting(false);
    startPos.current = null;
  };

  useEffect(() => {
    document.addEventListener('touchend', endConnection);
    document.addEventListener('mouseup', endConnection);

    return () => {
      document.removeEventListener('touchend', endConnection);
      document.removeEventListener('mouseup', endConnection);
    };
  }, [isConnecting]);

  return (
    <div
      ref={handleRef}
      className={`connection-handle ${type}`}
      data-node-id={nodeId}
      data-handle-type={type}
      style={{
        position: 'absolute',
        [type === 'input' ? 'left' : 'right']: -8,
        top: '50%',
        transform: 'translateY(-50%)',
        width: TOUCH_TARGETS.minimum,
        height: TOUCH_TARGETS.minimum,
        borderRadius: '50%',
        backgroundColor: isConnecting ? 'var(--color-primary)' : 'var(--color-border)',
        border: '2px solid var(--color-background)',
        cursor: 'crosshair',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        touchAction: 'none',
        transition: 'background-color 0.2s, transform 0.2s',
        zIndex: 10
      }}
    >
      <div
        style={{
          width: 12,
          height: 12,
          borderRadius: '50%',
          backgroundColor: 'var(--color-background)'
        }}
      />
    </div>
  );
};

/**
 * Multi-select gesture handler
 */
export interface SelectionBoxProps {
  onSelect: (nodeIds: string[]) => void;
  nodes: GraphNode[];
  children: React.ReactNode;
}

export const SelectionBox: React.FC<SelectionBoxProps> = ({ onSelect, nodes, children }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [selectionBounds, setSelectionBounds] = useState<{
    x: number;
    y: number;
    width: number;
    height: number;
  } | null>(null);
  const startPos = useRef<{ x: number; y: number } | null>(null);

  useEffect(() => {
    if (!containerRef.current) return;

    const touchManager = new TouchManager({
      element: containerRef.current,
      config: {
        panThreshold: 20
      },
      handlers: {
        pan: (e: GestureEvent) => {
          if (!startPos.current) {
            startPos.current = {
              x: e.center.x - e.deltaX,
              y: e.center.y - e.deltaY
            };
          }

          const bounds = {
            x: Math.min(startPos.current.x, e.center.x),
            y: Math.min(startPos.current.y, e.center.y),
            width: Math.abs(e.center.x - startPos.current.x),
            height: Math.abs(e.center.y - startPos.current.y)
          };

          setSelectionBounds(bounds);

          // Find nodes within bounds
          const selectedNodeIds = nodes
            .filter(node => {
              if (!node.position) return false;

              return (
                node.position.x >= bounds.x &&
                node.position.x <= bounds.x + bounds.width &&
                node.position.y >= bounds.y &&
                node.position.y <= bounds.y + bounds.height
              );
            })
            .map(node => node.id);

          onSelect(selectedNodeIds);
        }
      }
    });

    const handleEnd = () => {
      setSelectionBounds(null);
      startPos.current = null;
    };

    containerRef.current.addEventListener('touchend', handleEnd);
    containerRef.current.addEventListener('mouseup', handleEnd);

    return () => {
      touchManager.destroy();
      containerRef.current?.removeEventListener('touchend', handleEnd);
      containerRef.current?.removeEventListener('mouseup', handleEnd);
    };
  }, [nodes, onSelect]);

  return (
    <div ref={containerRef} style={{ position: 'relative', width: '100%', height: '100%' }}>
      {children}

      {selectionBounds && (
        <div
          className="selection-box"
          style={{
            position: 'absolute',
            left: selectionBounds.x,
            top: selectionBounds.y,
            width: selectionBounds.width,
            height: selectionBounds.height,
            border: '2px dashed var(--color-primary)',
            backgroundColor: 'rgba(var(--color-primary-rgb), 0.1)',
            pointerEvents: 'none',
            zIndex: 9999
          }}
        />
      )}
    </div>
  );
};

/**
 * Touch-optimized context menu with long-press activation
 */

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { TouchManager } from './TouchManager';
import { GestureEvent } from './gestures';
import { HapticFeedback, VisualFeedback } from './feedback';
import { TOUCH_TARGETS } from '../mobile/design-system';
import { touchTargetUtils } from './accessibility';

export interface ContextMenuItem {
  id: string;
  label: string;
  icon?: React.ReactNode;
  type?: 'normal' | 'separator' | 'submenu' | 'checkbox' | 'radio';
  checked?: boolean;
  disabled?: boolean;
  danger?: boolean;
  shortcut?: string;
  submenu?: ContextMenuItem[];
  onSelect?: () => void;
}

export interface TouchContextMenuProps {
  items: ContextMenuItem[];
  onSelect?: (item: ContextMenuItem) => void;
  onDismiss?: () => void;
  position?: { x: number; y: number };
  anchor?: 'auto' | 'top' | 'bottom' | 'left' | 'right' | 'center';
  showShortcuts?: boolean;
  enableHaptics?: boolean;
}

/**
 * Touch-friendly context menu component
 */
export const TouchContextMenu: React.FC<TouchContextMenuProps> = ({
  items,
  onSelect,
  onDismiss,
  position,
  anchor = 'auto',
  showShortcuts = false,
  enableHaptics = true
}) => {
  const menuRef = useRef<HTMLDivElement>(null);
  const [selectedIndex, setSelectedIndex] = useState(-1);
  const [submenuOpen, setSubmenuOpen] = useState<string | null>(null);
  const [menuPosition, setMenuPosition] = useState(position || { x: 0, y: 0 });
  const haptic = useRef(HapticFeedback.getInstance());

  // Calculate menu position to keep it on screen
  useEffect(() => {
    if (!menuRef.current || !position) return;

    const menu = menuRef.current;
    const rect = menu.getBoundingClientRect();
    const viewport = {
      width: window.innerWidth,
      height: window.innerHeight
    };

    let x = position.x;
    let y = position.y;

    // Auto-anchor based on available space
    if (anchor === 'auto') {
      // Horizontal adjustment
      if (x + rect.width > viewport.width - 20) {
        x = viewport.width - rect.width - 20;
      }
      if (x < 20) {
        x = 20;
      }

      // Vertical adjustment
      if (y + rect.height > viewport.height - 20) {
        y = viewport.height - rect.height - 20;
      }
      if (y < 20) {
        y = 20;
      }
    } else {
      // Manual anchor positions
      switch (anchor) {
        case 'top':
          y = Math.max(20, position.y - rect.height);
          break;
        case 'bottom':
          y = Math.min(viewport.height - rect.height - 20, position.y);
          break;
        case 'left':
          x = Math.max(20, position.x - rect.width);
          break;
        case 'right':
          x = Math.min(viewport.width - rect.width - 20, position.x);
          break;
        case 'center':
          x = position.x - rect.width / 2;
          y = position.y - rect.height / 2;
          break;
      }
    }

    setMenuPosition({ x, y });
  }, [position, anchor]);

  // Handle item selection
  const handleItemSelect = useCallback((item: ContextMenuItem, index: number) => {
    if (item.disabled) return;

    if (item.type === 'submenu' && item.submenu) {
      setSubmenuOpen(submenuOpen === item.id ? null : item.id);
      if (enableHaptics) haptic.current.trigger('light');
      return;
    }

    if (enableHaptics) haptic.current.trigger('selection');

    // Visual feedback
    VisualFeedback.trigger(menuRef.current!, {
      enabled: true,
      type: 'highlight',
      duration: 200
    });

    item.onSelect?.();
    onSelect?.(item);
    onDismiss?.();
  }, [submenuOpen, enableHaptics, onSelect, onDismiss]);

  // Handle keyboard navigation
  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    const visibleItems = items.filter(item => item.type !== 'separator');
    const currentIndex = selectedIndex;

    switch (e.key) {
      case 'ArrowUp':
        e.preventDefault();
        const prevIndex = currentIndex <= 0 ? visibleItems.length - 1 : currentIndex - 1;
        setSelectedIndex(prevIndex);
        break;

      case 'ArrowDown':
        e.preventDefault();
        const nextIndex = currentIndex >= visibleItems.length - 1 ? 0 : currentIndex + 1;
        setSelectedIndex(nextIndex);
        break;

      case 'Enter':
      case ' ':
        e.preventDefault();
        if (currentIndex >= 0 && visibleItems[currentIndex]) {
          handleItemSelect(visibleItems[currentIndex], currentIndex);
        }
        break;

      case 'Escape':
        e.preventDefault();
        onDismiss?.();
        break;
    }
  }, [items, selectedIndex, handleItemSelect, onDismiss]);

  // Dismiss on outside click
  useEffect(() => {
    const handleOutsideClick = (e: MouseEvent | TouchEvent) => {
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
        onDismiss?.();
      }
    };

    document.addEventListener('mousedown', handleOutsideClick);
    document.addEventListener('touchstart', handleOutsideClick);

    return () => {
      document.removeEventListener('mousedown', handleOutsideClick);
      document.removeEventListener('touchstart', handleOutsideClick);
    };
  }, [onDismiss]);

  // Render menu item
  const renderMenuItem = (item: ContextMenuItem, index: number) => {
    if (item.type === 'separator') {
      return <div key={item.id} className="context-menu-separator" />;
    }

    const isSelected = selectedIndex === index;
    const hasSubmenu = item.type === 'submenu' && item.submenu;
    const isSubmenuOpen = submenuOpen === item.id;

    return (
      <div key={item.id}>
        <button
          className={`
            context-menu-item
            ${isSelected ? 'selected' : ''}
            ${item.disabled ? 'disabled' : ''}
            ${item.danger ? 'danger' : ''}
            ${item.checked ? 'checked' : ''}
          `}
          onClick={() => handleItemSelect(item, index)}
          disabled={item.disabled}
          style={{
            minHeight: TOUCH_TARGETS.large,
            padding: '12px 16px',
            display: 'flex',
            alignItems: 'center',
            gap: '12px',
            width: '100%',
            justifyContent: 'space-between'
          }}
        >
          <div className="menu-item-content">
            {item.icon && <span className="menu-item-icon">{item.icon}</span>}
            <span className="menu-item-label">{item.label}</span>
          </div>

          <div className="menu-item-extras">
            {showShortcuts && item.shortcut && (
              <span className="menu-item-shortcut">{item.shortcut}</span>
            )}
            {hasSubmenu && (
              <span className="menu-item-arrow">▶</span>
            )}
            {item.type === 'checkbox' && item.checked && (
              <span className="menu-item-check">✓</span>
            )}
          </div>
        </button>

        {hasSubmenu && isSubmenuOpen && (
          <div className="context-submenu">
            {item.submenu!.map((subItem, subIndex) => 
              renderMenuItem(subItem, items.length + subIndex)
            )}
          </div>
        )}
      </div>
    );
  };

  return (
    <div
      ref={menuRef}
      className="touch-context-menu"
      style={{
        position: 'fixed',
        left: menuPosition.x,
        top: menuPosition.y,
        zIndex: 10000,
        minWidth: '200px',
        maxWidth: '300px',
        backgroundColor: 'var(--color-background)',
        border: '1px solid var(--color-border)',
        borderRadius: '8px',
        boxShadow: '0 4px 24px rgba(0, 0, 0, 0.15)',
        padding: '8px 0',
        fontSize: '16px',
        touchAction: 'none',
        userSelect: 'none'
      }}
      onKeyDown={handleKeyDown}
      tabIndex={0}
    >
      {items.map((item, index) => renderMenuItem(item, index))}
    </div>
  );
};

/**
 * Context menu provider for long-press activation
 */
export interface ContextMenuProviderProps {
  items: ContextMenuItem[] | ((target: HTMLElement) => ContextMenuItem[]);
  longPressDelay?: number;
  enableHaptics?: boolean;
  children: React.ReactNode;
}

export const ContextMenuProvider: React.FC<ContextMenuProviderProps> = ({
  items,
  longPressDelay = 500,
  enableHaptics = true,
  children
}) => {
  const [menuState, setMenuState] = useState<{
    visible: boolean;
    position: { x: number; y: number };
    items: ContextMenuItem[];
  }>({
    visible: false,
    position: { x: 0, y: 0 },
    items: []
  });

  const containerRef = useRef<HTMLDivElement>(null);
  const targetRef = useRef<HTMLElement | null>(null);

  useEffect(() => {
    if (!containerRef.current) return;

    const touchManager = new TouchManager({
      element: containerRef.current,
      config: {
        longPressDelay,
        preventDefault: false // Allow normal touch interactions
      },
      handlers: {
        longPress: (event: GestureEvent) => {
          const target = event.target as HTMLElement;
          targetRef.current = target;

          // Get context items
          const contextItems = typeof items === 'function' ? items(target) : items;

          // Show menu
          setMenuState({
            visible: true,
            position: event.center,
            items: contextItems
          });

          // Haptic feedback
          if (enableHaptics) {
            HapticFeedback.getInstance().trigger('heavy');
          }
        }
      }
    });

    return () => touchManager.destroy();
  }, [items, longPressDelay, enableHaptics]);

  const handleDismiss = useCallback(() => {
    setMenuState(prev => ({ ...prev, visible: false }));
    targetRef.current = null;
  }, []);

  return (
    <>
      <div ref={containerRef} style={{ width: '100%', height: '100%' }}>
        {children}
      </div>

      {menuState.visible && (
        <TouchContextMenu
          items={menuState.items}
          position={menuState.position}
          onDismiss={handleDismiss}
          enableHaptics={enableHaptics}
        />
      )}
    </>
  );
};

