/**
 * Core touch event handler and gesture recognition
 */

import {
  GestureType,
  GestureState,
  GestureEvent,
  GestureConfig,
  TouchPoint,
  defaultGestureConfig,
  getDistance,
  getCenter,
  getVelocity,
  getSwipeDirection,
  getPinchScale,
  getRotation,
  gestureHelpers
} from './gestures';
import { TouchFeedback } from './feedback';

export type GestureHandler = (event: GestureEvent) => void;

export interface TouchManagerOptions {
  element: HTMLElement;
  config?: Partial<GestureConfig>;
  handlers?: Partial<Record<GestureType, GestureHandler>>;
  enableFeedback?: boolean;
}

export class TouchManager {
  private element: HTMLElement;
  private config: GestureConfig;
  private handlers: Map<GestureType, GestureHandler[]> = new Map();
  private feedback: TouchFeedback;
  private enableFeedback: boolean;

  // Gesture state
  private currentGesture: GestureState | null = null;
  private touches: Map<number, TouchPoint> = new Map();
  private gestureHistory: GestureState[] = [];

  // Timers
  private longPressTimer?: NodeJS.Timeout;
  private doubleTapTimer?: NodeJS.Timeout;
  private lastTapTime = 0;

  constructor(options: TouchManagerOptions) {
    this.element = options.element;
    this.config = { ...defaultGestureConfig, ...options.config };
    this.feedback = new TouchFeedback();
    this.enableFeedback = options.enableFeedback ?? true;

    // Register initial handlers
    if (options.handlers) {
      Object.entries(options.handlers).forEach(([type, handler]) => {
        this.on(type as GestureType, handler);
      });
    }

    this.attachEventListeners();
  }

  /**
   * Register a gesture handler
   */
  on(type: GestureType, handler: GestureHandler): void {
    if (!this.handlers.has(type)) {
      this.handlers.set(type, []);
    }
    this.handlers.get(type)!.push(handler);
  }

  /**
   * Remove a gesture handler
   */
  off(type: GestureType, handler: GestureHandler): void {
    const handlers = this.handlers.get(type);
    if (handlers) {
      const index = handlers.indexOf(handler);
      if (index !== -1) {
        handlers.splice(index, 1);
      }
    }
  }

  /**
   * Destroy the touch manager
   */
  destroy(): void {
    this.removeEventListeners();
    this.clearTimers();
    this.handlers.clear();
  }

  private attachEventListeners(): void {
    // Touch events
    this.element.addEventListener('touchstart', this.handleTouchStart, { passive: false });
    this.element.addEventListener('touchmove', this.handleTouchMove, { passive: false });
    this.element.addEventListener('touchend', this.handleTouchEnd, { passive: false });
    this.element.addEventListener('touchcancel', this.handleTouchCancel, { passive: false });

    // Mouse events (for desktop testing)
    this.element.addEventListener('mousedown', this.handleMouseDown);
    this.element.addEventListener('mousemove', this.handleMouseMove);
    this.element.addEventListener('mouseup', this.handleMouseUp);
    this.element.addEventListener('mouseleave', this.handleMouseLeave);

    // Wheel events for pinch simulation
    this.element.addEventListener('wheel', this.handleWheel, { passive: false });
  }

  private removeEventListeners(): void {
    this.element.removeEventListener('touchstart', this.handleTouchStart);
    this.element.removeEventListener('touchmove', this.handleTouchMove);
    this.element.removeEventListener('touchend', this.handleTouchEnd);
    this.element.removeEventListener('touchcancel', this.handleTouchCancel);

    this.element.removeEventListener('mousedown', this.handleMouseDown);
    this.element.removeEventListener('mousemove', this.handleMouseMove);
    this.element.removeEventListener('mouseup', this.handleMouseUp);
    this.element.removeEventListener('mouseleave', this.handleMouseLeave);

    this.element.removeEventListener('wheel', this.handleWheel);
  }

  private handleTouchStart = (e: TouchEvent): void => {
    if (this.config.preventDefault) e.preventDefault();
    if (this.config.stopPropagation) e.stopPropagation();

    // Update touches
    Array.from(e.changedTouches).forEach(touch => {
      this.touches.set(touch.identifier, {
        id: touch.identifier,
        x: touch.clientX,
        y: touch.clientY,
        startX: touch.clientX,
        startY: touch.clientY,
        timestamp: Date.now(),
        force: touch.force
      });
    });

    // Start gesture
    this.startGesture();

    // Check for long press
    if (this.touches.size === 1) {
      this.startLongPressTimer();
    }
  };

  private handleTouchMove = (e: TouchEvent): void => {
    if (this.config.preventDefault) e.preventDefault();

    // Update touches
    Array.from(e.changedTouches).forEach(touch => {
      const point = this.touches.get(touch.identifier);
      if (point) {
        point.x = touch.clientX;
        point.y = touch.clientY;
        point.force = touch.force;
      }
    });

    // Update gesture
    this.updateGesture();

    // Cancel long press if moved too much
    if (this.currentGesture && this.touches.size === 1) {
      const touch = Array.from(this.touches.values())[0];
      const distance = getDistance(
        { x: touch.startX, y: touch.startY },
        { x: touch.x, y: touch.y }
      );

      if (distance > this.config.longPressMoveThreshold) {
        this.cancelLongPress();
      }
    }
  };

  private handleTouchEnd = (e: TouchEvent): void => {
    if (this.config.preventDefault) e.preventDefault();

    // Update touches
    Array.from(e.changedTouches).forEach(touch => {
      this.touches.delete(touch.identifier);
    });

    // End gesture if no more touches
    if (this.touches.size === 0) {
      this.endGesture();
    } else {
      this.updateGesture();
    }
  };

  private handleTouchCancel = (e: TouchEvent): void => {
    this.handleTouchEnd(e);
  };

  // Mouse event handlers for desktop
  private handleMouseDown = (e: MouseEvent): void => {
    // Only handle left click
    if (e.button !== 0) return;

    this.touches.set(0, {
      id: 0,
      x: e.clientX,
      y: e.clientY,
      startX: e.clientX,
      startY: e.clientY,
      timestamp: Date.now()
    });

    this.startGesture();
    this.startLongPressTimer();
  };

  private handleMouseMove = (e: MouseEvent): void => {
    const touch = this.touches.get(0);
    if (!touch) return;

    touch.x = e.clientX;
    touch.y = e.clientY;

    this.updateGesture();

    // Cancel long press if moved too much
    const distance = getDistance(
      { x: touch.startX, y: touch.startY },
      { x: touch.x, y: touch.y }
    );

    if (distance > this.config.longPressMoveThreshold) {
      this.cancelLongPress();
    }
  };

  private handleMouseUp = (e: MouseEvent): void => {
    if (!this.touches.has(0)) return;

    this.touches.delete(0);
    this.endGesture();
  };

  private handleMouseLeave = (e: MouseEvent): void => {
    if (this.touches.has(0)) {
      this.touches.delete(0);
      this.cancelGesture();
    }
  };

  private handleWheel = (e: WheelEvent): void => {
    if (this.config.preventDefault) e.preventDefault();

    // Simulate pinch gesture
    const scale = e.deltaY > 0 ? 0.95 : 1.05;
    this.emitGesture('pinch', {
      center: { x: e.clientX, y: e.clientY },
      scale
    });
  };

  private startGesture(): void {
    const touches = Array.from(this.touches.values());

    this.currentGesture = {
      type: this.detectGestureType(),
      active: true,
      startTime: Date.now(),
      touches,
      center: getCenter(touches)
    };
  }

  private updateGesture(): void {
    if (!this.currentGesture) return;

    const touches = Array.from(this.touches.values());
    const previousTouches = this.currentGesture.touches;

    this.currentGesture.touches = touches;
    this.currentGesture.center = getCenter(touches);

    // Detect gesture type changes
    const newType = this.detectGestureType();
    if (newType !== this.currentGesture.type) {
      this.currentGesture.type = newType;
    }

    // Calculate gesture-specific data
    if (touches.length === 2 && previousTouches.length === 2) {
      this.currentGesture.scale = getPinchScale(previousTouches, touches);
      this.currentGesture.rotation = getRotation(previousTouches, touches);
    }

    // Emit ongoing gestures
    if (this.currentGesture.type === 'pan' || 
        this.currentGesture.type === 'drag' ||
        this.currentGesture.type === 'pinch' ||
        this.currentGesture.type === 'rotate') {
      this.emitCurrentGesture();
    }
  }

  private endGesture(): void {
    if (!this.currentGesture) return;

    this.currentGesture.active = false;
    this.currentGesture.endTime = Date.now();

    // Calculate final velocity
    if (this.currentGesture.touches.length > 0) {
      const touch = this.currentGesture.touches[0];
      this.currentGesture.velocity = getVelocity(
        {
          x: touch.startX,
          y: touch.startY,
          timestamp: this.currentGesture.startTime
        },
        {
          x: touch.x,
          y: touch.y,
          timestamp: this.currentGesture.endTime
        }
      );
    }

    // Detect final gesture type
    const finalType = this.detectFinalGestureType();
    if (finalType) {
      this.currentGesture.type = finalType;
      this.emitCurrentGesture();
    }

    // Store in history
    this.gestureHistory.push(this.currentGesture);
    if (this.gestureHistory.length > 10) {
      this.gestureHistory.shift();
    }

    this.currentGesture = null;
    this.clearTimers();
  }

  private cancelGesture(): void {
    this.currentGesture = null;
    this.clearTimers();
  }

  private detectGestureType(): GestureType {
    const touchCount = this.touches.size;

    if (touchCount === 0) return 'tap';
    if (touchCount === 1) return 'drag';
    if (touchCount === 2) return 'pinch';

    return 'tap';
  }

  private detectFinalGestureType(): GestureType | null {
    if (!this.currentGesture) return null;

    const gesture = this.currentGesture;

    // Check for tap
    if (gestureHelpers.isTap(gesture, this.config)) {
      // Check for double tap
      const now = Date.now();
      if (now - this.lastTapTime < this.config.doubleTapDelay) {
        this.lastTapTime = 0;
        return 'doubleTap';
      }
      this.lastTapTime = now;
      return 'tap';
    }

    // Check for swipe
    if (gestureHelpers.isSwipe(gesture, this.config)) {
      return 'swipe';
    }

    // Check for long press (already handled by timer)

    return null;
  }

  private startLongPressTimer(): void {
    this.cancelLongPress();

    this.longPressTimer = setTimeout(() => {
      if (this.currentGesture && gestureHelpers.isLongPress(this.currentGesture, this.config)) {
        this.currentGesture.type = 'longPress';
        this.emitCurrentGesture();
      }
    }, this.config.longPressDelay);
  }

  private cancelLongPress(): void {
    if (this.longPressTimer) {
      clearTimeout(this.longPressTimer);
      this.longPressTimer = undefined;
    }
  }

  private clearTimers(): void {
    this.cancelLongPress();
    if (this.doubleTapTimer) {
      clearTimeout(this.doubleTapTimer);
      this.doubleTapTimer = undefined;
    }
  }

  private emitCurrentGesture(): void {
    if (!this.currentGesture) return;

    const touch = this.currentGesture.touches[0];
    const event: GestureEvent = {
      type: this.currentGesture.type,
      target: this.element,
      touches: this.currentGesture.touches,
      center: this.currentGesture.center,
      deltaX: touch ? touch.x - touch.startX : 0,
      deltaY: touch ? touch.y - touch.startY : 0,
      distance: touch ? getDistance(
        { x: touch.startX, y: touch.startY },
        { x: touch.x, y: touch.y }
      ) : 0,
      direction: touch ? getSwipeDirection(
        touch.x - touch.startX,
        touch.y - touch.startY
      ) : undefined,
      velocity: this.currentGesture.velocity,
      scale: this.currentGesture.scale,
      rotation: this.currentGesture.rotation,
      preventDefault: () => {},
      stopPropagation: () => {}
    };

    this.emitGesture(this.currentGesture.type, event);
  }

  private emitGesture(type: GestureType, event: Partial<GestureEvent> = {}): void {
    const fullEvent: GestureEvent = {
      type,
      target: this.element,
      touches: Array.from(this.touches.values()),
      center: getCenter(Array.from(this.touches.values())),
      deltaX: 0,
      deltaY: 0,
      distance: 0,
      preventDefault: () => {},
      stopPropagation: () => {},
      ...event
    };

    // Trigger feedback
    if (this.enableFeedback) {
      this.feedback.trigger(type, this.element, fullEvent.center);
    }

    // Call handlers
    const handlers = this.handlers.get(type);
    if (handlers) {
      handlers.forEach(handler => handler(fullEvent));
    }
  }
}

/**
 * Touch target accessibility utilities
 */

import { TOUCH_TARGETS } from '../mobile/design-system';

export interface TouchTargetConfig {
  minSize: number;
  preferredSize: number;
  padding: number;
  spacing: number;
}

export interface TouchTargetAnalysis {
  isAccessible: boolean;
  actualSize: { width: number; height: number };
  recommendedSize: { width: number; height: number };
  issues: string[];
  suggestions: string[];
}

/**
 * WCAG 2.1 Level AA and AAA touch target guidelines
 */
export const accessibilityGuidelines = {
  // WCAG 2.1 Level AA
  wcagAA: {
    minSize: 44,
    preferredSize: 48,
    padding: 8,
    spacing: 8
  },

  // WCAG 2.1 Level AAA
  wcagAAA: {
    minSize: 48,
    preferredSize: 56,
    padding: 12,
    spacing: 12
  },

  // Apple Human Interface Guidelines
  ios: {
    minSize: 44,
    preferredSize: 44,
    padding: 8,
    spacing: 8
  },

  // Material Design Guidelines
  material: {
    minSize: 48,
    preferredSize: 48,
    padding: 8,
    spacing: 8
  },

  // Custom for graph editing (larger targets for precision)
  graphEditing: {
    minSize: 56,
    preferredSize: 64,
    padding: 12,
    spacing: 16
  }
};

/**
 * Analyze touch target accessibility
 */
export function analyzeTouchTarget(
  element: HTMLElement,
  guideline: keyof typeof accessibilityGuidelines = 'wcagAA'
): TouchTargetAnalysis {
  const rect = element.getBoundingClientRect();
  const config = accessibilityGuidelines[guideline];
  const issues: string[] = [];
  const suggestions: string[] = [];

  // Check size
  const actualSize = {
    width: rect.width,
    height: rect.height
  };

  const isWidthAccessible = actualSize.width >= config.minSize;
  const isHeightAccessible = actualSize.height >= config.minSize;
  const isAccessible = isWidthAccessible && isHeightAccessible;

  if (!isWidthAccessible) {
    issues.push(`Width (${actualSize.width}px) is below minimum (${config.minSize}px)`);
    suggestions.push(`Increase width to at least ${config.minSize}px`);
  }

  if (!isHeightAccessible) {
    issues.push(`Height (${actualSize.height}px) is below minimum (${config.minSize}px)`);
    suggestions.push(`Increase height to at least ${config.minSize}px`);
  }

  // Check spacing to nearby targets
  const nearbyTargets = findNearbyTouchTargets(element, config.spacing * 2);
  nearbyTargets.forEach(target => {
    const targetRect = target.getBoundingClientRect();
    const distance = calculateDistance(rect, targetRect);

    if (distance < config.spacing) {
      issues.push(`Too close to another touch target (${distance}px spacing)`);
      suggestions.push(`Increase spacing to at least ${config.spacing}px`);
    }
  });

  // Recommend preferred size
  if (actualSize.width < config.preferredSize || actualSize.height < config.preferredSize) {
    suggestions.push(`Consider using preferred size of ${config.preferredSize}x${config.preferredSize}px`);
  }

  return {
    isAccessible,
    actualSize,
    recommendedSize: {
      width: Math.max(actualSize.width, config.preferredSize),
      height: Math.max(actualSize.height, config.preferredSize)
    },
    issues,
    suggestions
  };
}

/**
 * Find nearby touch targets
 */
function findNearbyTouchTargets(element: HTMLElement, radius: number): HTMLElement[] {
  const rect = element.getBoundingClientRect();
  const targets: HTMLElement[] = [];

  // Find all interactive elements
  const interactiveSelectors = [
    'button',
    'a',
    'input',
    'select',
    'textarea',
    '[role="button"]',
    '[role="link"]',
    '[role="checkbox"]',
    '[role="radio"]',
    '[role="switch"]',
    '[role="tab"]',
    '[role="menuitem"]',
    '[tabindex]:not([tabindex="-1"])'
  ];

  const allTargets = document.querySelectorAll<HTMLElement>(interactiveSelectors.join(', '));

  allTargets.forEach(target => {
    if (target === element) return;

    const targetRect = target.getBoundingClientRect();
    const distance = calculateDistance(rect, targetRect);

    if (distance <= radius) {
      targets.push(target);
    }
  });

  return targets;
}

/**
 * Calculate distance between two rectangles
 */
function calculateDistance(rect1: DOMRect, rect2: DOMRect): number {
  const x1 = rect1.left + rect1.width / 2;
  const y1 = rect1.top + rect1.height / 2;
  const x2 = rect2.left + rect2.width / 2;
  const y2 = rect2.top + rect2.height / 2;

  // If rectangles overlap, distance is 0
  if (!(rect1.right < rect2.left || 
        rect2.right < rect1.left || 
        rect1.bottom < rect2.top || 
        rect2.bottom < rect1.top)) {
    return 0;
  }

  // Calculate edge-to-edge distance
  let dx = 0;
  let dy = 0;

  if (rect1.right < rect2.left) {
    dx = rect2.left - rect1.right;
  } else if (rect2.right < rect1.left) {
    dx = rect1.left - rect2.right;
  }

  if (rect1.bottom < rect2.top) {
    dy = rect2.top - rect1.bottom;
  } else if (rect2.bottom < rect1.top) {
    dy = rect1.top - rect2.bottom;
  }

  return Math.sqrt(dx * dx + dy * dy);
}

/**
 * Create accessible touch target wrapper
 */
export function createAccessibleTouchTarget(
  element: HTMLElement,
  config: TouchTargetConfig = accessibilityGuidelines.wcagAA
): HTMLElement {
  const wrapper = document.createElement('div');
  wrapper.className = 'accessible-touch-target';

  // Calculate current size
  const rect = element.getBoundingClientRect();
  const currentWidth = rect.width;
  const currentHeight = rect.height;

  // Calculate padding needed
  const paddingX = Math.max(0, (config.minSize - currentWidth) / 2);
  const paddingY = Math.max(0, (config.minSize - currentHeight) / 2);

  // Apply styles
  Object.assign(wrapper.style, {
    display: 'inline-flex',
    alignItems: 'center',
    justifyContent: 'center',
    minWidth: `${config.minSize}px`,
    minHeight: `${config.minSize}px`,
    padding: `${paddingY}px ${paddingX}px`,
    cursor: 'pointer',
    position: 'relative',
    // Ensure touch events work properly
    touchAction: 'manipulation',
    WebkitTapHighlightColor: 'transparent',
    // Prevent text selection on touch
    userSelect: 'none',
    WebkitUserSelect: 'none'
  });

  // Wrap the element
  if (element.parentNode) {
    element.parentNode.insertBefore(wrapper, element);
  }
  wrapper.appendChild(element);

  return wrapper;
}

/**
 * Touch target visual debugging
 */
export function enableTouchTargetDebugging(show = true): void {
  const debugId = 'touch-target-debug-styles';
  const existingStyles = document.getElementById(debugId);

  if (!show) {
    existingStyles?.remove();
    return;
  }

  if (existingStyles) return;

  const styles = document.createElement('style');
  styles.id = debugId;
  styles.textContent = `
    /* Highlight all touch targets */
    button,
    a,
    input,
    select,
    textarea,
    [role="button"],
    [role="link"],
    [role="checkbox"],
    [role="radio"],
    [role="switch"],
    [role="tab"],
    [role="menuitem"],
    [tabindex]:not([tabindex="-1"]) {
      position: relative;
      outline: 2px dashed rgba(255, 0, 0, 0.5) !important;
    }

    /* Show touch target size */
    button::after,
    a::after,
    [role="button"]::after {
      content: attr(data-touch-size, '');
      position: absolute;
      top: 0;
      right: 0;
      background: rgba(255, 0, 0, 0.8);
      color: white;
      font-size: 10px;
      padding: 2px 4px;
      pointer-events: none;
      z-index: 9999;
    }

    /* Highlight too-small targets */
    button:not(.touch-accessible),
    a:not(.touch-accessible),
    [role="button"]:not(.touch-accessible) {
      background-color: rgba(255, 0, 0, 0.1) !important;
    }

    /* Show spacing issues */
    .touch-spacing-issue {
      box-shadow: 0 0 0 4px rgba(255, 165, 0, 0.3) !important;
    }
  `;

  document.head.appendChild(styles);

  // Analyze all touch targets
  const targets = document.querySelectorAll<HTMLElement>([
    'button',
    'a',
    '[role="button"]',
    '[role="link"]',
    '[tabindex]:not([tabindex="-1"])'
  ].join(', '));

  targets.forEach(target => {
    const analysis = analyzeTouchTarget(target);

    // Add size info
    target.setAttribute('data-touch-size', 
      `${Math.round(analysis.actualSize.width)}×${Math.round(analysis.actualSize.height)}`
    );

    // Mark accessibility
    if (analysis.isAccessible) {
      target.classList.add('touch-accessible');
    } else {
      target.classList.remove('touch-accessible');
    }

    // Mark spacing issues
    if (analysis.issues.some(issue => issue.includes('spacing'))) {
      target.classList.add('touch-spacing-issue');
    }
  });
}

/**
 * Touch target enhancement utilities
 */
export const touchTargetUtils = {
  /**
   * Ensure minimum touch target size
   */
  ensureMinimumSize(
    element: HTMLElement,
    minSize = TOUCH_TARGETS.minimum
  ): void {
    const rect = element.getBoundingClientRect();

    if (rect.width < minSize) {
      element.style.minWidth = `${minSize}px`;
    }

    if (rect.height < minSize) {
      element.style.minHeight = `${minSize}px`;
    }
  },

  /**
   * Add touch-friendly padding
   */
  addTouchPadding(
    element: HTMLElement,
    padding = 8
  ): void {
    const currentPadding = window.getComputedStyle(element);
    const paddingTop = parseInt(currentPadding.paddingTop) || 0;
    const paddingBottom = parseInt(currentPadding.paddingBottom) || 0;
    const paddingLeft = parseInt(currentPadding.paddingLeft) || 0;
    const paddingRight = parseInt(currentPadding.paddingRight) || 0;

    element.style.padding = 
      `${Math.max(padding, paddingTop)}px ` +
      `${Math.max(padding, paddingRight)}px ` +
      `${Math.max(padding, paddingBottom)}px ` +
      `${Math.max(padding, paddingLeft)}px`;
  },

  /**
   * Create invisible touch area extension
   */
  extendTouchArea(
    element: HTMLElement,
    extension = 8
  ): void {
    element.style.position = 'relative';

    // Create pseudo-element for extended touch area
    const styleId = `touch-area-${Math.random().toString(36).substr(2, 9)}`;
    element.classList.add(styleId);

    const style = document.createElement('style');
    style.textContent = `
      .${styleId}::before {
        content: '';
        position: absolute;
        top: -${extension}px;
        right: -${extension}px;
        bottom: -${extension}px;
        left: -${extension}px;
        z-index: 1;
      }
    `;

    document.head.appendChild(style);
  }
};

/**
 * Touch feedback system for visual and haptic responses
 */

import { GestureType } from './gestures';

export type HapticStyle = 
  | 'light'
  | 'medium' 
  | 'heavy'
  | 'soft'
  | 'rigid'
  | 'selection'
  | 'success'
  | 'warning'
  | 'error';

export type VisualFeedbackType =
  | 'ripple'
  | 'highlight'
  | 'scale'
  | 'glow'
  | 'pulse'
  | 'shake';

export interface HapticFeedbackConfig {
  enabled: boolean;
  intensity: number; // 0-1
  duration: number; // ms
  pattern?: number[]; // Custom vibration pattern
}

export interface VisualFeedbackConfig {
  enabled: boolean;
  type: VisualFeedbackType;
  duration: number; // ms
  color?: string;
  scale?: number;
  opacity?: number;
}

export interface TouchFeedbackConfig {
  haptic: HapticFeedbackConfig;
  visual: VisualFeedbackConfig;
  audio?: {
    enabled: boolean;
    volume: number; // 0-1
    sound?: string; // URL or preset
  };
}

