// CSS class name utility (similar to clsx)
export function cn(...classes: (string | undefined | null | false)[]): string {
  return classes.filter(Boolean).join(' ');
}

// Resolve responsive values based on current breakpoint
export function resolveResponsiveValue<T>(
  value: ResponsiveValue<T>,
  breakpoint?: 'mobile' | 'tablet' | 'desktop'
): T {
  if (typeof value !== 'object' || value === null) {
    return value as T;
  }

  const currentBreakpoint = breakpoint || getBreakpoint(getViewportSize().width);

  // Return the most specific value available
  if (value[currentBreakpoint] !== undefined) {
    return value[currentBreakpoint]!;
  }

  // Fallback logic
  if (currentBreakpoint === 'desktop' && value.tablet !== undefined) {
    return value.tablet;
  }

  if (currentBreakpoint !== 'mobile' && value.mobile !== undefined) {
    return value.mobile;
  }

  // Return first available value as fallback
  return value.desktop || value.tablet || value.mobile || (value as any);
}

// Convert component size to pixel value
export function sizeToPixels(size: ComponentSize, theme: Theme): number {
  const sizeMap = {
    xs: theme.spacing.xs,
    sm: theme.spacing.sm,
    md: theme.spacing.md,
    lg: theme.spacing.lg,
    xl: theme.spacing.xl
  };

  return sizeMap[size];
}

// Generate CSS styles for responsive values
export function createResponsiveStyles<T>(
  property: string,
  value: ResponsiveValue<T>,
  transform?: (val: T) => string
): Record<string, any> {
  if (typeof value !== 'object' || value === null) {
    return {
      [property]: transform ? transform(value as T) : value
    };
  }

  const styles: Record<string, any> = {};

  // Base value (mobile-first)
  if (value.mobile !== undefined) {
    styles[property] = transform ? transform(value.mobile) : value.mobile;
  }

  // Tablet breakpoint
  if (value.tablet !== undefined) {
    styles[`@media (min-width: 768px)`] = {
      [property]: transform ? transform(value.tablet) : value.tablet
    };
  }

  // Desktop breakpoint
  if (value.desktop !== undefined) {
    styles[`@media (min-width: 1024px)`] = {
      [property]: transform ? transform(value.desktop) : value.desktop
    };
  }

  return styles;
}

// Generate padding/margin CSS from ComponentSize
export function createSpacingStyles(
  type: 'padding' | 'margin',
  value: ResponsiveValue<ComponentSize>,
  theme: Theme
): Record<string, any> {
  return createResponsiveStyles(
    type,
    value,
    (size) => `${sizeToPixels(size, theme)}px`
  );
}

// Animation utilities
export function createTransition(
  properties: string | string[],
  duration = '200ms',
  timing = 'ease-in-out'
): string {
  const props = Array.isArray(properties) ? properties : [properties];
  return props.map(prop => `${prop} ${duration} ${timing}`).join(', ');
}

// Focus ring styles for accessibility
export function createFocusStyles(theme: Theme): Record<string, any> {
  return {
    '&:focus': {
      outline: 'none',
      boxShadow: `0 0 0 2px ${theme.colors.primary}`,
      borderColor: theme.colors.primary
    },
    '&:focus:not(:focus-visible)': {
      boxShadow: 'none',
      borderColor: 'inherit'
    }
  };
}

// Button variant styles
export function createButtonVariantStyles(
  variant: 'primary' | 'secondary' | 'outline' | 'ghost' | 'link',
  theme: Theme
): Record<string, any> {
  const baseStyles = {
    border: 'none',
    cursor: 'pointer',
    textDecoration: 'none',
    display: 'inline-flex',
    alignItems: 'center',
    justifyContent: 'center',
    borderRadius: `${theme.borderRadius}px`,
    fontFamily: theme.typography.fontFamily,
    fontWeight: theme.typography.fontWeight.medium,
    transition: createTransition(['background-color', 'border-color', 'color']),
    ...createFocusStyles(theme)
  };

  switch (variant) {
    case 'primary':
      return {
        ...baseStyles,
        backgroundColor: theme.colors.primary,
        color: theme.colors.background,
        '&:hover:not(:disabled)': {
          backgroundColor: theme.colors.secondary
        },
        '&:disabled': {
          backgroundColor: theme.colors.border,
          color: theme.colors.textSecondary,
          cursor: 'not-allowed'
        }
      };

    case 'secondary':
      return {
        ...baseStyles,
        backgroundColor: theme.colors.surface,
        color: theme.colors.text,
        border: `1px solid ${theme.colors.border}`,
        '&:hover:not(:disabled)': {
          backgroundColor: theme.colors.border
        },
        '&:disabled': {
          backgroundColor: theme.colors.surface,
          color: theme.colors.textSecondary,
          cursor: 'not-allowed'
        }
      };

    case 'outline':
      return {
        ...baseStyles,
        backgroundColor: 'transparent',
        color: theme.colors.primary,
        border: `1px solid ${theme.colors.primary}`,
        '&:hover:not(:disabled)': {
          backgroundColor: theme.colors.primary,
          color: theme.colors.background
        },
        '&:disabled': {
          borderColor: theme.colors.border,
          color: theme.colors.textSecondary,
          cursor: 'not-allowed'
        }
      };

    case 'ghost':
      return {
        ...baseStyles,
        backgroundColor: 'transparent',
        color: theme.colors.text,
        '&:hover:not(:disabled)': {
          backgroundColor: theme.colors.surface
        },
        '&:disabled': {
          color: theme.colors.textSecondary,
          cursor: 'not-allowed'
        }
      };

    case 'link':
      return {
        ...baseStyles,
        backgroundColor: 'transparent',
        color: theme.colors.primary,
        padding: 0,
        borderRadius: 0,
        '&:hover:not(:disabled)': {
          textDecoration: 'underline'
        },
        '&:disabled': {
          color: theme.colors.textSecondary,
          cursor: 'not-allowed'
        }
      };

    default:
      return baseStyles;
  }
}

// Input styles
export function createInputStyles(
  theme: Theme,
  error?: string,
  disabled?: boolean
): Record<string, any> {
  return {
    appearance: 'none',
    border: `1px solid ${error ? theme.colors.error : theme.colors.border}`,
    borderRadius: `${theme.borderRadius}px`,
    padding: `${theme.spacing.sm}px ${theme.spacing.md}px`,
    fontSize: `${theme.typography.fontSize.md}px`,
    fontFamily: theme.typography.fontFamily,
    backgroundColor: disabled ? theme.colors.surface : theme.colors.background,
    color: disabled ? theme.colors.textSecondary : theme.colors.text,
    transition: createTransition(['border-color', 'box-shadow']),
    ...createFocusStyles(theme),
    '&::placeholder': {
      color: theme.colors.textSecondary
    },
    '&:disabled': {
      cursor: 'not-allowed'
    }
  };
}

// Size-based styles
