    expect(bundle.grammar.concat1).toEqual({
      type: 'sequential',
      items: ['var2', 'wc1']
    });

    expect(bundle.grammar.include1).toEqual({ 
      $include: 'external_template' 
    });

    // Check entry points
    expect(bundle.entry_points.default).toBe('output1');

