    expect(bundle.entry_points.default).toBe('empty_output');
    expect(bundle.grammar.empty_output).toEqual(['']);
    expect(bundle.grammar.empty_concat).toEqual(['']);
  });

  it('should handle invalid GeneratorBundle format gracefully', () => {
