        version: '1.0.0',
        author: 'Test Author',
        created: new Date().toISOString(),
      },
      variables: {},
      grammar: {
        'conditional1': {
          type: 'conditional',
          cases: [
            { condition: 'x > 10', value: 'Large' },
            { condition: 'x <= 10', value: 'Small' }
          ]
        },
        'modifier1': {
          type: 'modifier_chain',
          base: 'conditional1',
          mods: ['uppercase', 'trim']
