// Epic 11 Database Service
// PostgreSQL database service for authentication

import { Pool, PoolClient, QueryResult } from 'pg';
import { AuthConfig } from '../types';

export class DatabaseService {
  private pool: Pool;
  private config: AuthConfig;

  constructor(config: AuthConfig) {
    this.config = config;
    this.pool = new Pool({
      host: config.database.host,
      port: config.database.port,
      database: config.database.database,
      user: config.database.username,
      password: config.database.password,
      ssl: config.database.ssl,
      max: config.database.poolSize || 10,
      idleTimeoutMillis: 30000,
      connectionTimeoutMillis: 2000,
    });

    // Handle pool errors
    this.pool.on('error', (err) => {
      console.error('Unexpected error on idle client', err);
    });
  }

  async query(text: string, params?: any[]): Promise<QueryResult<any>> {
    const start = Date.now();
    try {
      const result = await this.pool.query(text, params);
      const duration = Date.now() - start;

      if (duration > 1000) {
        console.warn(`Slow query (${duration}ms):`, text);
      }

      return result;
    } catch (error) {
      console.error('Database query error:', {
        query: text,
        params: params ? params.map(p => typeof p === 'string' && p.length > 100 ? `${p.substring(0, 100)}...` : p) : undefined,
        error: error.message,
      });
      throw error;
    }
  }

  async transaction<T>(callback: (client: PoolClient) => Promise<T>): Promise<T> {
    const client = await this.pool.connect();

    try {
      await client.query('BEGIN');
      const result = await callback(client);
      await client.query('COMMIT');
      return result;
    } catch (error) {
      await client.query('ROLLBACK');
      throw error;
    } finally {
      client.release();
    }
  }

  async healthCheck(): Promise<boolean> {
    try {
      const result = await this.query('SELECT 1 as health');
      return result.rows.length > 0 && result.rows[0].health === 1;
    } catch (error) {
      console.error('Database health check failed:', error);
      return false;
    }
  }

  async initializeSchema(): Promise<void> {
    try {
      const fs = require('fs');
      const path = require('path');

      // Read schema file
      const schemaPath = path.join(__dirname, '../schema.sql');
      const schema = fs.readFileSync(schemaPath, 'utf8');

      // Execute schema in transaction
      await this.transaction(async (client) => {
        await client.query(schema);
      });

      console.log('Database schema initialized successfully');
    } catch (error) {
      console.error('Failed to initialize database schema:', error);
      throw error;
    }
  }

  async close(): Promise<void> {
    await this.pool.end();
  }

  // Get connection pool statistics
  getPoolStats() {
    return {
      totalCount: this.pool.totalCount,
      idleCount: this.pool.idleCount,
      waitingCount: this.pool.waitingCount,
    };
  }

  // Get a client from the pool for manual transaction handling
  async getClient(): Promise<PoolClient> {
    return await this.pool.connect();
  }

  // User database operations for PasswordResetService
  async findUserByEmail(email: string): Promise<any | null> {
    const result = await this.query(
      'SELECT * FROM users WHERE email = $1 AND status = $2',
      [email.toLowerCase(), 'active']
    );
    return result.rows.length > 0 ? result.rows[0] : null;
  }

  async findUserById(id: string): Promise<any | null> {
    const result = await this.query(
      'SELECT * FROM users WHERE id = $1',
      [id]
    );
    return result.rows.length > 0 ? result.rows[0] : null;
  }
}

// Epic 11 Redis Service
// Redis service for session management and rate limiting

import Redis from 'ioredis';
import { RedisConfig } from '../types';

export class RedisService {
  private client: Redis;
  private config: RedisConfig;

  constructor(config: RedisConfig) {
    this.config = config;
    this.client = new Redis({
      host: config.host,
      port: config.port,
      password: config.password,
      db: config.db || 0,
      keyPrefix: config.keyPrefix || 'auth:',
      retryDelayOnFailover: 100,
      enableReadyCheck: true,
      lazyConnect: true,
      maxRetriesPerRequest: 3,
    });

    // Handle Redis events
    this.client.on('connect', () => {
      console.log('Redis connected');
    });

    this.client.on('error', (err) => {
      console.error('Redis error:', err);
    });

    this.client.on('disconnect', () => {
      console.warn('Redis disconnected');
    });
  }

  async connect(): Promise<void> {
    if (this.client.status !== 'ready') {
      await this.client.connect();
    }
  }

  async get(key: string): Promise<string | null> {
    try {
      return await this.client.get(key);
    } catch (error) {
      console.error(`Redis GET error for key ${key}:`, error);
      return null;
    }
  }

  async set(key: string, value: string): Promise<void> {
    try {
      await this.client.set(key, value);
    } catch (error) {
      console.error(`Redis SET error for key ${key}:`, error);
      throw error;
    }
  }

  async setex(key: string, seconds: number, value: string): Promise<void> {
    try {
      await this.client.setex(key, seconds, value);
    } catch (error) {
      console.error(`Redis SETEX error for key ${key}:`, error);
      throw error;
    }
  }

  async exists(key: string): Promise<boolean> {
    try {
      const result = await this.client.exists(key);
      return result === 1;
    } catch (error) {
      console.error(`Redis EXISTS error for key ${key}:`, error);
      return false;
    }
  }

  async del(key: string): Promise<void> {
    try {
      await this.client.del(key);
    } catch (error) {
      console.error(`Redis DEL error for key ${key}:`, error);
      throw error;
    }
  }

  async incr(key: string): Promise<number> {
    try {
      return await this.client.incr(key);
    } catch (error) {
      console.error(`Redis INCR error for key ${key}:`, error);
      throw error;
    }
  }

  async expire(key: string, seconds: number): Promise<void> {
    try {
      await this.client.expire(key, seconds);
    } catch (error) {
      console.error(`Redis EXPIRE error for key ${key}:`, error);
      throw error;
    }
  }

  async ttl(key: string): Promise<number> {
    try {
      return await this.client.ttl(key);
    } catch (error) {
      console.error(`Redis TTL error for key ${key}:`, error);
      return -1;
    }
  }

  // Rate limiting with sliding window
  async checkRateLimit(key: string, window: number, limit: number): Promise<{
    allowed: boolean;
    count: number;
    remaining: number;
    resetTime: Date;
  }> {
    try {
      const now = Date.now();
      const pipeline = this.client.pipeline();

      // Remove expired entries
      pipeline.zremrangebyscore(key, 0, now - window * 1000);

      // Count current entries
      pipeline.zcard(key);

      // Add current request
      pipeline.zadd(key, now, `${now}-${Math.random()}`);

      // Set expiry for the key
      pipeline.expire(key, window);

      const results = await pipeline.exec();

      if (!results) {
        throw new Error('Redis pipeline failed');
      }

      const count = (results[1][1] as number) || 0;
      const allowed = count < limit;
      const remaining = Math.max(0, limit - count - 1);
      const resetTime = new Date(now + window * 1000);

      return {
        allowed,
        count: count + 1,
        remaining,
        resetTime,
      };
    } catch (error) {
      console.error(`Redis rate limit error for key ${key}:`, error);
      // Default to allowing the request if Redis is down
      return {
        allowed: true,
        count: 1,
        remaining: limit - 1,
        resetTime: new Date(Date.now() + window * 1000),
      };
    }
  }

  // Session management
  async storeSession(sessionId: string, data: any, ttl: number): Promise<void> {
    const key = `session:${sessionId}`;
    await this.setex(key, ttl, JSON.stringify(data));
  }

  async getSession(sessionId: string): Promise<any | null> {
    const key = `session:${sessionId}`;
    const data = await this.get(key);
    return data ? JSON.parse(data) : null;
  }

  async deleteSession(sessionId: string): Promise<void> {
    const key = `session:${sessionId}`;
    await this.del(key);
  }

  async extendSession(sessionId: string, ttl: number): Promise<void> {
    const key = `session:${sessionId}`;
    await this.expire(key, ttl);
  }

  // Cache management
  async cache(key: string, data: any, ttl: number): Promise<void> {
    await this.setex(key, ttl, JSON.stringify(data));
  }

  async getCache(key: string): Promise<any | null> {
    const data = await this.get(key);
    return data ? JSON.parse(data) : null;
  }

  async invalidateCache(pattern: string): Promise<void> {
    try {
      const keys = await this.client.keys(pattern);
      if (keys.length > 0) {
        await this.client.del(...keys);
      }
    } catch (error) {
      console.error(`Redis cache invalidation error for pattern ${pattern}:`, error);
    }
  }

  async healthCheck(): Promise<boolean> {
    try {
      const result = await this.client.ping();
      return result === 'PONG';
    } catch (error) {
      console.error('Redis health check failed:', error);
      return false;
    }
  }

  async getInfo(): Promise<any> {
    try {
      const info = await this.client.info();
      const lines = info.split('\r\n');
      const result: any = {};

      let section = '';
      for (const line of lines) {
        if (line.startsWith('#')) {
          section = line.substring(2).toLowerCase();
          result[section] = {};
        } else if (line.includes(':')) {
          const [key, value] = line.split(':');
          if (section && key && value) {
            result[section][key] = isNaN(Number(value)) ? value : Number(value);
          }
        }
      }

      return result;
    } catch (error) {
      console.error('Redis info error:', error);
      return {};
    }
  }

  async close(): Promise<void> {
    await this.client.quit();
  }

  // Get Redis client for advanced operations
  getClient(): Redis {
    return this.client;
  }
}

// Epic 11.3 Permission-Based Authorization Middleware
// Fastify middleware for RBAC permission checking

import { FastifyRequest, FastifyReply } from 'fastify';
import { RBACService } from '../services/RBACService';
import { PermissionCheck, PermissionContext } from '../types';

export interface PermissionAuthOptions {
  resource: string;
  action: string;
  scope?: 'global' | 'organization' | 'team' | 'own';
  requireAll?: boolean; // If multiple permissions, require all or any
  allowSuperAdmin?: boolean; // Allow super_admin to bypass checks
  extractContext?: (request: FastifyRequest) => PermissionContext | Promise<PermissionContext>;
}

export function createPermissionAuthMiddleware(rbacService: RBACService) {
  return function permissionAuth(options: PermissionAuthOptions | PermissionAuthOptions[]) {
    return async function (request: FastifyRequest, reply: FastifyReply) {
      try {
        const user = (request.user as any);

        if (!user || !user.id) {
          return reply.status(401).send({
            error: 'Unauthorized',
            message: 'Authentication required',
          });
        }

        const userId = user.id;
        const permissions = Array.isArray(options) ? options : [options];

        // Check for super admin bypass
        if (permissions.some(p => p.allowSuperAdmin !== false)) {
          const userRoles = await rbacService.getUserRoles(userId);
          if (userRoles.some(role => role.name === 'super_admin')) {
            // Allow super admin to bypass permission checks
            return;
          }
        }

        // Extract context from request
        let context: PermissionContext = { userId };

        if (permissions[0].extractContext) {
          context = await permissions[0].extractContext(request);
        } else {
          // Default context extraction
          context = await extractDefaultContext(request, userId);
        }

        // Check permissions
        const permissionChecks: PermissionCheck[] = permissions.map(p => ({
          resource: p.resource,
          action: p.action,
          context,
        }));

        const requireAll = permissions[0].requireAll ?? false;
        const results = await Promise.all(
          permissionChecks.map(check => rbacService.checkPermission(userId, check, context))
        );

        let allowed: boolean;
        if (requireAll) {
          allowed = results.every(result => result.allowed);
        } else {
          allowed = results.some(result => result.allowed);
        }

        if (!allowed) {
          const deniedPermissions = permissionChecks.filter((_, index) => !results[index].allowed);
          const reasons = results.filter(r => !r.allowed).map(r => r.reason).join(', ');

          return reply.status(403).send({
            error: 'Forbidden',
            message: 'Insufficient permissions',
            details: {
              required: deniedPermissions.map(p => `${p.resource}:${p.action}`),
              reasons,
            },
          });
        }

        // Add permission info to request for later use
        (request as any).permissions = {
          checked: permissionChecks,
          results,
          context,
        };

        // Continue to next handler
      } catch (error) {
        console.error('Permission check error:', error);
        return reply.status(500).send({
          error: 'Internal Server Error',
          message: 'Permission check failed',
        });
      }
    };
  };
}

async function extractDefaultContext(
  request: FastifyRequest,
  userId: string
): Promise<PermissionContext> {
  const context: PermissionContext = { userId };

  // Extract from URL parameters
  const params = request.params as any;
  if (params.organizationId) {
    context.organizationId = params.organizationId;
  }
  if (params.teamId) {
    context.teamId = params.teamId;
  }
  if (params.id || params.resourceId) {
    context.resourceId = params.id || params.resourceId;
  }

  // Extract from query parameters
  const query = request.query as any;
  if (query.organizationId) {
    context.organizationId = query.organizationId;
  }
  if (query.teamId) {
    context.teamId = query.teamId;
  }

  // Extract from request headers
  const headers = request.headers;
  if (headers['x-organization-id']) {
    context.organizationId = headers['x-organization-id'] as string;
  }
  if (headers['x-team-id']) {
    context.teamId = headers['x-team-id'] as string;
  }

  return context;
}

