// Epic 11 API Token Routes
// HTTP routes for managing API tokens with scope-based authorization

import { FastifyInstance, FastifyRequest, FastifyReply } from 'fastify';
import { z } from 'zod';
import { AuthenticationService } from '../AuthenticationService';
import { TokenService } from '../services/TokenService';

// API token creation schema
const createApiTokenSchema = z.object({
  name: z.string().min(1, 'Token name is required').max(255),
  scopes: z.array(z.string()).min(1, 'At least one scope is required'),
  expiresIn: z.string().optional().default('90d'),
});

// API token revocation schema
const revokeApiTokenSchema = z.object({
  tokenId: z.string().uuid(),
});

// Available scopes for API tokens
const AVAILABLE_SCOPES = [
  'graphs:read',
  'graphs:write',
  'graphs:execute',
  'graphs:delete',
  'user:read',
  'user:write',
  'organizations:read',
  'organizations:write',
  'teams:read',
  'teams:write',
  'admin:users',
  'admin:system',
  '*', // Full access (admin only)
];

interface ApiTokenRouteContext {
  authService: AuthenticationService;
  tokenService: TokenService;
}

export async function apiTokenRoutes(fastify: FastifyInstance, context: ApiTokenRouteContext) {
  const { authService, tokenService } = context;

  // Get available scopes
  fastify.get('/api-tokens/scopes', {
    schema: {
      response: {
        200: {
          type: 'object',
          properties: {
            scopes: {
              type: 'array',
              items: {
                type: 'object',
                properties: {
                  name: { type: 'string' },
                  description: { type: 'string' },
                  category: { type: 'string' },
                },
              },
            },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    const scopeDescriptions = {
      'graphs:read': { description: 'Read access to graphs', category: 'graphs' },
      'graphs:write': { description: 'Create and modify graphs', category: 'graphs' },
      'graphs:execute': { description: 'Execute graphs', category: 'graphs' },
      'graphs:delete': { description: 'Delete graphs', category: 'graphs' },
      'user:read': { description: 'Read user profile information', category: 'user' },
      'user:write': { description: 'Modify user profile information', category: 'user' },
      'organizations:read': { description: 'Read organization information', category: 'organizations' },
      'organizations:write': { description: 'Modify organization information', category: 'organizations' },
      'teams:read': { description: 'Read team information', category: 'teams' },
      'teams:write': { description: 'Modify team information', category: 'teams' },
      'admin:users': { description: 'Administrative access to user management', category: 'admin' },
      'admin:system': { description: 'Administrative access to system management', category: 'admin' },
      '*': { description: 'Full access to all resources', category: 'admin' },
    };

    const scopes = AVAILABLE_SCOPES.map(scope => ({
      name: scope,
      description: scopeDescriptions[scope]?.description || 'Unknown scope',
      category: scopeDescriptions[scope]?.category || 'other',
    }));

    return reply.send({ scopes });
  });

  // Create API token
  fastify.post<{
    Body: z.infer<typeof createApiTokenSchema>;
  }>('/api-tokens', {
    preHandler: [fastify.authenticate], // JWT authentication middleware
    schema: {
      body: createApiTokenSchema,
      response: {
        201: {
          type: 'object',
          properties: {
            token: { type: 'string' },
            tokenId: { type: 'string' },
            name: { type: 'string' },
            scopes: { type: 'array', items: { type: 'string' } },
            expiresAt: { type: 'string' },
            warning: { type: 'string' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { name, scopes, expiresIn } = request.body as z.infer<typeof createApiTokenSchema>;
      const userId = (request.user as any)?.id;
      const userRoles = (request.user as any)?.roles || [];

      if (!userId) {
        return reply.status(401).send({
          error: 'Unauthorized',
          message: 'User authentication required',
        });
      }

      // Validate scopes
      const invalidScopes = scopes.filter(scope => !AVAILABLE_SCOPES.includes(scope));
      if (invalidScopes.length > 0) {
        return reply.status(400).send({
          error: 'Invalid Scopes',
          message: `Invalid scopes: ${invalidScopes.join(', ')}`,
        });
      }

      // Check if user has permission to create tokens with these scopes
      const hasAdminRole = userRoles.includes('super_admin') || userRoles.includes('admin');
      const hasWildcardScope = scopes.includes('*');
      const hasAdminScopes = scopes.some(scope => scope.startsWith('admin:'));

      if ((hasWildcardScope || hasAdminScopes) && !hasAdminRole) {
        return reply.status(403).send({
          error: 'Forbidden',
          message: 'Administrator privileges required for admin scopes',
        });
      }

      // Get user data
      const userService = authService.getService('user');
      const user = await userService.getUserById(userId);

      if (!user) {
        return reply.status(404).send({
          error: 'User Not Found',
          message: 'User not found',
        });
      }

      // Generate API token
      const { token, tokenId } = await tokenService.generateApiToken(
        user,
        scopes,
        expiresIn,
        name
      );

      // Calculate expiration date
      const decoded = require('jsonwebtoken').decode(token) as any;
      const expiresAt = new Date(decoded.exp * 1000);

      // Log token creation
      const auditService = authService.getService('audit');
      await auditService.logEvent({
        userId,
        action: 'api_token_created',
        details: {
          tokenId,
          name,
          scopes,
          expiresAt,
        },
        ipAddress: request.ip,
        userAgent: request.headers['user-agent'],
        severity: 'info',
      });

      return reply.status(201).send({
        token,
        tokenId,
        name,
        scopes,
        expiresAt: expiresAt.toISOString(),
        warning: 'Store this token securely. It will not be shown again.',
      });
    } catch (error) {
      fastify.log.error('Create API token error:', error);
      return reply.status(500).send({
        error: 'Internal Server Error',
        message: 'Failed to create API token',
      });
    }
  });

  // Get user's API tokens
  fastify.get('/api-tokens', {
    preHandler: [fastify.authenticate], // JWT authentication middleware
    schema: {
      response: {
        200: {
          type: 'object',
          properties: {
            tokens: {
              type: 'array',
              items: {
                type: 'object',
                properties: {
                  id: { type: 'string' },
                  name: { type: 'string' },
                  scopes: { type: 'array', items: { type: 'string' } },
                  expiresAt: { type: 'string' },
                  createdAt: { type: 'string' },
                  lastUsedAt: { type: 'string' },
                  revoked: { type: 'boolean' },
                },
              },
            },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const userId = (request.user as any)?.id;

      if (!userId) {
        return reply.status(401).send({
          error: 'Unauthorized',
          message: 'User authentication required',
        });
      }

      const tokens = await tokenService.getUserApiTokens(userId);

      return reply.send({
        tokens: tokens.map(token => ({
          id: token.id,
          name: token.name,
          scopes: typeof token.scopes === 'string' ? JSON.parse(token.scopes) : token.scopes,
          expiresAt: token.expiresAt?.toISOString(),
          createdAt: token.createdAt.toISOString(),
          lastUsedAt: token.lastUsedAt?.toISOString(),
          revoked: token.revoked,
        })),
      });
    } catch (error) {
      fastify.log.error('Get API tokens error:', error);
      return reply.status(500).send({
        error: 'Internal Server Error',
        message: 'Failed to retrieve API tokens',
      });
    }
  });

  // Revoke API token
  fastify.post<{
    Body: z.infer<typeof revokeApiTokenSchema>;
  }>('/api-tokens/revoke', {
    preHandler: [fastify.authenticate], // JWT authentication middleware
    schema: {
      body: revokeApiTokenSchema,
      response: {
        200: {
          type: 'object',
          properties: {
            success: { type: 'boolean' },
            message: { type: 'string' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { tokenId } = request.body as z.infer<typeof revokeApiTokenSchema>;
      const userId = (request.user as any)?.id;

      if (!userId) {
        return reply.status(401).send({
          error: 'Unauthorized',
          message: 'User authentication required',
        });
      }

      // Verify token belongs to user
      const userTokens = await tokenService.getUserApiTokens(userId);
      const targetToken = userTokens.find(t => t.id === tokenId);

      if (!targetToken) {
        return reply.status(404).send({
          error: 'Token Not Found',
          message: 'API token not found or does not belong to user',
        });
      }

      if (targetToken.revoked) {
        return reply.status(400).send({
          error: 'Token Already Revoked',
          message: 'API token has already been revoked',
        });
      }

      // Revoke the token
      await tokenService.revokeApiToken(tokenId);

      // Log token revocation
      const auditService = authService.getService('audit');
      await auditService.logEvent({
        userId,
        action: 'api_token_revoked',
        details: {
          tokenId,
          name: targetToken.name,
          scopes: targetToken.scopes,
        },
        ipAddress: request.ip,
        userAgent: request.headers['user-agent'],
        severity: 'info',
      });

      return reply.send({
        success: true,
        message: 'API token revoked successfully',
      });
    } catch (error) {
      fastify.log.error('Revoke API token error:', error);
      return reply.status(500).send({
        error: 'Internal Server Error',
        message: 'Failed to revoke API token',
      });
    }
  });

  // Test API token endpoint
  fastify.get('/api-tokens/test', {
    preHandler: [fastify.authenticate], // JWT authentication middleware
    schema: {
      response: {
        200: {
          type: 'object',
          properties: {
            valid: { type: 'boolean' },
            tokenType: { type: 'string' },
            scopes: { type: 'array', items: { type: 'string' } },
            user: { type: 'object' },
            expiresAt: { type: 'string' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const user = request.user as any;
      const authHeader = request.headers.authorization;
      const token = authHeader?.split(' ')[1];

      if (!token) {
        return reply.status(401).send({
          error: 'Unauthorized',
          message: 'No token provided',
        });
      }

      const payload = await tokenService.verifyAccessToken(token);
      const isApiToken = (payload as any).type === 'api';

      return reply.send({
        valid: true,
        tokenType: isApiToken ? 'api' : 'access',
        scopes: (payload as any).scopes || [],
        user: {
          id: user.id,
          email: user.email,
          roles: user.roles,
        },
        expiresAt: new Date(payload.exp * 1000).toISOString(),
      });
    } catch (error) {
      fastify.log.error('Test API token error:', error);
      return reply.status(401).send({
        error: 'Unauthorized',
        message: 'Invalid token',
      });
    }
  });

  // API token usage statistics
  fastify.get('/api-tokens/stats', {
    preHandler: [fastify.authenticate], // JWT authentication middleware
    schema: {
      response: {
        200: {
          type: 'object',
          properties: {
            totalTokens: { type: 'number' },
            activeTokens: { type: 'number' },
            revokedTokens: { type: 'number' },
            expiredTokens: { type: 'number' },
            recentlyUsed: { type: 'array' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const userId = (request.user as any)?.id;

      if (!userId) {
        return reply.status(401).send({
          error: 'Unauthorized',
          message: 'User authentication required',
        });
      }

      const dbService = authService.getService('database');
      const result = await dbService.query(`
        SELECT 
          COUNT(*) as total_tokens,
          COUNT(CASE WHEN NOT revoked AND expires_at > NOW() THEN 1 END) as active_tokens,
          COUNT(CASE WHEN revoked THEN 1 END) as revoked_tokens,
          COUNT(CASE WHEN expires_at < NOW() THEN 1 END) as expired_tokens
        FROM api_tokens
        WHERE user_id = $1
      `, [userId]);

      const stats = result.rows[0];

      // Get recently used tokens
      const recentResult = await dbService.query(`
        SELECT name, last_used_at, scopes
        FROM api_tokens
        WHERE user_id = $1 AND last_used_at IS NOT NULL
        ORDER BY last_used_at DESC
        LIMIT 5
      `, [userId]);

      const recentlyUsed = recentResult.rows.map(row => ({
        name: row.name,
        lastUsedAt: row.last_used_at,
        scopes: typeof row.scopes === 'string' ? JSON.parse(row.scopes) : row.scopes,
      }));

      return reply.send({
        totalTokens: parseInt(stats.total_tokens),
        activeTokens: parseInt(stats.active_tokens),
        revokedTokens: parseInt(stats.revoked_tokens),
        expiredTokens: parseInt(stats.expired_tokens),
        recentlyUsed,
      });
    } catch (error) {
      fastify.log.error('Get API token stats error:', error);
      return reply.status(500).send({
        error: 'Internal Server Error',
        message: 'Failed to retrieve token statistics',
      });
    }
  });
}

// Epic 11 OAuth Routes
// HTTP routes for OAuth authentication flows

import { FastifyInstance, FastifyRequest, FastifyReply } from 'fastify';
import { z } from 'zod';
import { AuthenticationService } from '../AuthenticationService';
import { OAuthService } from '../services/OAuthService';
import { OAuthProvider } from '../types';

// OAuth authorization initiation schema
const oauthAuthSchema = z.object({
  provider: z.enum(['google', 'github', 'microsoft']),
  returnUrl: z.string().optional(),
});

// OAuth callback schema
const oauthCallbackSchema = z.object({
  code: z.string(),
  state: z.string(),
  error: z.string().optional(),
  error_description: z.string().optional(),
});

// OAuth account linking schema
const oauthLinkSchema = z.object({
  provider: z.enum(['google', 'github', 'microsoft']),
  code: z.string(),
});

// OAuth account unlinking schema
const oauthUnlinkSchema = z.object({
  provider: z.enum(['google', 'github', 'microsoft']),
});

interface OAuthRouteContext {
  authService: AuthenticationService;
  oauthService: OAuthService;
}

export async function oauthRoutes(fastify: FastifyInstance, context: OAuthRouteContext) {
  const { authService, oauthService } = context;

  // OAuth authorization initiation
  fastify.get<{
    Querystring: z.infer<typeof oauthAuthSchema>;
  }>('/oauth/authorize', {
    schema: {
      querystring: oauthAuthSchema,
      response: {
        200: {
          type: 'object',
          properties: {
            url: { type: 'string' },
            state: { type: 'string' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { provider, returnUrl } = request.query as z.infer<typeof oauthAuthSchema>;

      const context = {
        ipAddress: request.ip,
        userAgent: request.headers['user-agent'],
      };

      const { url, state } = await oauthService.generateAuthorizationUrl(
        provider as OAuthProvider,
        returnUrl,
        context
      );

      return reply.send({ url, state });
    } catch (error) {
      fastify.log.error('OAuth authorization error:', error);
      return reply.status(400).send({
        error: 'OAuth Authorization Failed',
        message: error.message,
      });
    }
  });

  // OAuth callback handler
  fastify.get<{
    Querystring: z.infer<typeof oauthCallbackSchema>;
    Params: { provider: string };
  }>('/oauth/callback/:provider', {
    schema: {
      params: {
        type: 'object',
        properties: {
          provider: { type: 'string', enum: ['google', 'github', 'microsoft'] },
        },
      },
      querystring: oauthCallbackSchema,
      response: {
        200: {
          type: 'object',
          properties: {
            accessToken: { type: 'string' },
            refreshToken: { type: 'string' },
            user: { type: 'object' },
            expiresAt: { type: 'string' },
            isNewUser: { type: 'boolean' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { provider } = request.params as { provider: string };
      const { code, state, error, error_description } = request.query as z.infer<typeof oauthCallbackSchema>;

      // Handle OAuth errors
      if (error) {
        fastify.log.warn('OAuth callback error:', { error, error_description });
        return reply.status(400).send({
          error: 'OAuth Authorization Failed',
          message: error_description || error,
        });
      }

      if (!code || !state) {
        return reply.status(400).send({
          error: 'Invalid OAuth Callback',
          message: 'Missing authorization code or state parameter',
        });
      }

      const context = {
        ipAddress: request.ip,
        userAgent: request.headers['user-agent'],
      };

      const result = await oauthService.handleCallback(
        provider as OAuthProvider,
        code,
        state,
        context
      );

      // Set secure HTTP-only cookies for tokens
      const cookieOptions = {
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'strict' as const,
        path: '/',
      };

      reply.setCookie('access_token', result.tokens.accessToken, {
        ...cookieOptions,
        maxAge: 15 * 60 * 1000, // 15 minutes
      });

      reply.setCookie('refresh_token', result.tokens.refreshToken, {
        ...cookieOptions,
        maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
      });

      return reply.send({
        accessToken: result.tokens.accessToken,
        refreshToken: result.tokens.refreshToken,
        user: result.user,
        expiresAt: result.tokens.expiresAt.toISOString(),
        isNewUser: result.isNewUser,
      });
    } catch (error) {
      fastify.log.error('OAuth callback error:', error);
      return reply.status(400).send({
        error: 'OAuth Callback Failed',
        message: error.message,
      });
    }
  });

  // Link OAuth account to existing user (requires authentication)
  fastify.post<{
    Body: z.infer<typeof oauthLinkSchema>;
  }>('/oauth/link', {
    preHandler: [fastify.authenticate], // JWT authentication middleware
    schema: {
      body: oauthLinkSchema,
      response: {
        200: {
          type: 'object',
          properties: {
            success: { type: 'boolean' },
            message: { type: 'string' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { provider, code } = request.body as z.infer<typeof oauthLinkSchema>;
      const userId = (request.user as any)?.id;

      if (!userId) {
        return reply.status(401).send({
          error: 'Unauthorized',
          message: 'User authentication required',
        });
      }

      const context = {
        ipAddress: request.ip,
        userAgent: request.headers['user-agent'],
      };

      await oauthService.linkAccount(userId, provider as OAuthProvider, code, context);

      return reply.send({
        success: true,
        message: `Successfully linked ${provider} account`,
      });
    } catch (error) {
      fastify.log.error('OAuth link error:', error);
      return reply.status(400).send({
        error: 'OAuth Link Failed',
        message: error.message,
      });
    }
  });

  // Unlink OAuth account from user (requires authentication)
  fastify.post<{
    Body: z.infer<typeof oauthUnlinkSchema>;
  }>('/oauth/unlink', {
    preHandler: [fastify.authenticate], // JWT authentication middleware
    schema: {
      body: oauthUnlinkSchema,
      response: {
        200: {
          type: 'object',
          properties: {
            success: { type: 'boolean' },
            message: { type: 'string' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { provider } = request.body as z.infer<typeof oauthUnlinkSchema>;
      const userId = (request.user as any)?.id;

      if (!userId) {
        return reply.status(401).send({
          error: 'Unauthorized',
          message: 'User authentication required',
        });
      }

      const context = {
        ipAddress: request.ip,
        userAgent: request.headers['user-agent'],
      };

      await oauthService.unlinkAccount(userId, provider as OAuthProvider, context);

      return reply.send({
        success: true,
        message: `Successfully unlinked ${provider} account`,
      });
    } catch (error) {
      fastify.log.error('OAuth unlink error:', error);
      return reply.status(400).send({
        error: 'OAuth Unlink Failed',
        message: error.message,
      });
    }
  });

  // Get user's linked OAuth accounts (requires authentication)
  fastify.get('/oauth/accounts', {
    preHandler: [fastify.authenticate], // JWT authentication middleware
    schema: {
      response: {
        200: {
          type: 'object',
          properties: {
            accounts: {
              type: 'array',
              items: {
                type: 'object',
                properties: {
                  provider: { type: 'string' },
                  email: { type: 'string' },
                  name: { type: 'string' },
                  picture: { type: 'string' },
                  createdAt: { type: 'string' },
                  updatedAt: { type: 'string' },
                },
              },
            },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const userId = (request.user as any)?.id;

      if (!userId) {
        return reply.status(401).send({
          error: 'Unauthorized',
          message: 'User authentication required',
        });
      }

      const accounts = await oauthService.getUserOAuthAccounts(userId);

      return reply.send({
        accounts: accounts.map(account => ({
          provider: account.provider,
          email: account.email,
          name: account.name,
          picture: account.picture,
          createdAt: account.created_at,
          updatedAt: account.updated_at,
        })),
      });
    } catch (error) {
      fastify.log.error('Get OAuth accounts error:', error);
      return reply.status(500).send({
        error: 'Internal Server Error',
        message: 'Failed to retrieve OAuth accounts',
      });
    }
  });

  // Get available OAuth providers
  fastify.get('/oauth/providers', {
    schema: {
      response: {
        200: {
          type: 'object',
          properties: {
            providers: {
              type: 'array',
              items: {
                type: 'object',
                properties: {
                  name: { type: 'string' },
                  displayName: { type: 'string' },
                  icon: { type: 'string' },
                  color: { type: 'string' },
                },
              },
            },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    const providers = [
      {
        name: 'google',
        displayName: 'Google',
        icon: 'google',
        color: '#4285f4',
      },
      {
        name: 'github',
        displayName: 'GitHub',
        icon: 'github',
        color: '#333333',
      },
      {
        name: 'microsoft',
        displayName: 'Microsoft',
        icon: 'microsoft',
        color: '#0078d4',
      },
    ];

    return reply.send({ providers });
  });
}

// Epic 11.4 Organization Management Routes
// RESTful API endpoints for organization and team management with RBAC integration

import { FastifyInstance, FastifyRequest } from 'fastify';
import { OrganizationService, CreateOrganizationData, UpdateOrganizationData } from '../services/OrganizationService';
import { RBACService } from '../services/RBACService';
import { requireAuth } from '../middleware/requireAuth';

export interface OrganizationRequest extends FastifyRequest {
  user: {
    id: string;
    email: string;
    roles: string[];
  };
}

export async function organizationRoutes(fastify: FastifyInstance) {
  const orgService = fastify.organizationService as OrganizationService;
  const rbacService = fastify.rbacService as RBACService;

  // Organization Management Routes

  // Create organization
  fastify.post('/organizations', {
    preHandler: [requireAuth],
    schema: {
      body: {
        type: 'object',
        required: ['name'],
        properties: {
          name: { type: 'string', minLength: 1, maxLength: 100 },
          slug: { type: 'string', pattern: '^[a-z0-9-]+$', maxLength: 50 },
          description: { type: 'string', maxLength: 500 },
          website: { type: 'string', format: 'uri' },
          plan: { type: 'string', enum: ['free', 'pro', 'enterprise'] },
          maxUsers: { type: 'number', minimum: 1 },
          settings: { type: 'object' },
          branding: { type: 'object' },
        },
      },
    },
  }, async (request: OrganizationRequest, reply) => {
    try {
      const createData: CreateOrganizationData = request.body as CreateOrganizationData;
      const context = {
        ipAddress: request.ip,
        userAgent: request.headers['user-agent'],
      };

      const organization = await orgService.createOrganization(
        createData,
        request.user.id,
        context
      );

      reply.code(201).send({
        success: true,
        data: organization,
      });
    } catch (error) {
      fastify.log.error('Organization creation failed:', error);
      reply.code(400).send({
        success: false,
        error: error instanceof Error ? error.message : 'Organization creation failed',
      });
    }
  });

  // Get user's organizations
  fastify.get('/organizations/my', {
    preHandler: [requireAuth],
  }, async (request: OrganizationRequest, reply) => {
    try {
      const organizations = await orgService.getUserOrganizations(request.user.id);

      reply.send({
        success: true,
        data: organizations,
      });
    } catch (error) {
      fastify.log.error('Failed to fetch user organizations:', error);
      reply.code(500).send({
        success: false,
        error: 'Failed to fetch organizations',
      });
    }
  });

  // Get organization by ID
  fastify.get('/organizations/:organizationId', {
    preHandler: [requireAuth],
  }, async (request: OrganizationRequest, reply) => {
    try {
      const { organizationId } = request.params as { organizationId: string };

      // Check permission to view organization
      const hasPermission = await rbacService.checkPermission(
        request.user.id,
        { resource: 'organizations', action: 'read' },
        { organizationId }
      );

      if (!hasPermission.allowed) {
        return reply.code(403).send({
          success: false,
          error: 'Insufficient permissions to view organization',
        });
      }

      const organization = await orgService.getOrganizationById(organizationId);
      if (!organization) {
        return reply.code(404).send({
          success: false,
          error: 'Organization not found',
        });
      }

      reply.send({
        success: true,
        data: organization,
      });
    } catch (error) {
      fastify.log.error('Failed to fetch organization:', error);
      reply.code(500).send({
        success: false,
        error: 'Failed to fetch organization',
      });
    }
  });

  // Update organization
  fastify.put('/organizations/:organizationId', {
    preHandler: [requireAuth],
    schema: {
      body: {
        type: 'object',
        properties: {
          name: { type: 'string', minLength: 1, maxLength: 100 },
          description: { type: 'string', maxLength: 500 },
          website: { type: 'string', format: 'uri' },
          plan: { type: 'string', enum: ['free', 'pro', 'enterprise'] },
          maxUsers: { type: 'number', minimum: 1 },
          settings: { type: 'object' },
          branding: { type: 'object' },
        },
      },
    },
  }, async (request: OrganizationRequest, reply) => {
    try {
      const { organizationId } = request.params as { organizationId: string };
      const updateData: UpdateOrganizationData = request.body as UpdateOrganizationData;

      // Check permission to update organization
      const hasPermission = await rbacService.checkPermission(
        request.user.id,
        { resource: 'organizations', action: 'write' },
        { organizationId }
      );

      if (!hasPermission.allowed) {
        return reply.code(403).send({
          success: false,
          error: 'Insufficient permissions to update organization',
        });
      }

      const context = {
        ipAddress: request.ip,
        userAgent: request.headers['user-agent'],
      };

      const organization = await orgService.updateOrganization(
        organizationId,
        updateData,
        request.user.id,
        context
      );

      reply.send({
        success: true,
        data: organization,
      });
    } catch (error) {
      fastify.log.error('Organization update failed:', error);
      reply.code(400).send({
        success: false,
        error: error instanceof Error ? error.message : 'Organization update failed',
      });
    }
  });

  // Delete organization
  fastify.delete('/organizations/:organizationId', {
    preHandler: [requireAuth],
  }, async (request: OrganizationRequest, reply) => {
    try {
      const { organizationId } = request.params as { organizationId: string };

      // Check permission to delete organization (owner only)
