// Epic 11.2 User Profile Routes
// HTTP routes for user profile management and preferences

import { FastifyInstance, FastifyRequest, FastifyReply } from 'fastify';
import { z } from 'zod';
import { AuthenticationService } from '../AuthenticationService';
import { ProfileService } from '../services/ProfileService';
import multipart from '@fastify/multipart';

// Profile update schema
const profileUpdateSchema = z.object({
  displayName: z.string().min(1).max(100).optional(),
  firstName: z.string().min(1).max(50).optional(),
  lastName: z.string().min(1).max(50).optional(),
  bio: z.string().max(500).optional(),
  timezone: z.string().max(50).optional(),
  locale: z.string().max(10).optional(),
});

// Preferences update schema
const preferencesUpdateSchema = z.object({
  category: z.string().min(1).max(50),
  settings: z.record(z.any()),
});

// Notification preferences schema
const notificationPreferencesSchema = z.object({
  email: z.object({
    enabled: z.boolean(),
    frequency: z.enum(['immediate', 'daily', 'weekly', 'never']),
    types: z.object({
      security: z.boolean(),
      system: z.boolean(),
      updates: z.boolean(),
      marketing: z.boolean(),
    }),
  }),
  inApp: z.object({
    enabled: z.boolean(),
    types: z.object({
      security: z.boolean(),
      system: z.boolean(),
      updates: z.boolean(),
      mentions: z.boolean(),
    }),
  }),
  push: z.object({
    enabled: z.boolean(),
    types: z.object({
      security: z.boolean(),
      system: z.boolean(),
      updates: z.boolean(),
      mentions: z.boolean(),
    }),
  }),
  quietHours: z.object({
    enabled: z.boolean(),
    start: z.string().regex(/^\d{2}:\d{2}$/),
    end: z.string().regex(/^\d{2}:\d{2}$/),
    timezone: z.string(),
  }),
});

interface ProfileRouteContext {
  authService: AuthenticationService;
  profileService: ProfileService;
}

export async function profileRoutes(fastify: FastifyInstance, context: ProfileRouteContext) {
  const { authService, profileService } = context;

  // Register multipart support for file uploads
  await fastify.register(multipart, {
    limits: {
      fileSize: 5 * 1024 * 1024, // 5MB limit
    },
  });

  // Get user profile
  fastify.get('/profile', {
    preHandler: [fastify.authenticate],
    schema: {
      response: {
        200: {
          type: 'object',
          properties: {
            profile: {
              type: 'object',
              properties: {
                id: { type: 'string' },
                displayName: { type: 'string' },
                firstName: { type: 'string' },
                lastName: { type: 'string' },
                bio: { type: 'string' },
                avatarUrl: { type: 'string' },
                timezone: { type: 'string' },
                locale: { type: 'string' },
                createdAt: { type: 'string' },
                updatedAt: { type: 'string' },
              },
            },
            completeness: {
              type: 'object',
              properties: {
                percentage: { type: 'number' },
                completedFields: { type: 'array', items: { type: 'string' } },
                missingFields: { type: 'array', items: { type: 'string' } },
              },
            },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const userId = (request.user as any)?.id;

      if (!userId) {
        return reply.status(401).send({
          error: 'Unauthorized',
          message: 'User authentication required',
        });
      }

      const profile = await profileService.getProfile(userId);
      const completeness = await profileService.getProfileCompleteness(userId);

      return reply.send({
        profile,
        completeness,
      });
    } catch (error) {
      fastify.log.error('Get profile error:', error);
      return reply.status(500).send({
        error: 'Internal Server Error',
        message: 'Failed to retrieve profile',
      });
    }
  });

  // Update user profile
  fastify.put<{
    Body: z.infer<typeof profileUpdateSchema>;
  }>('/profile', {
    preHandler: [fastify.authenticate],
    schema: {
      body: profileUpdateSchema,
      response: {
        200: {
          type: 'object',
          properties: {
            profile: { type: 'object' },
            message: { type: 'string' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const userId = (request.user as any)?.id;
      const profileData = request.body as z.infer<typeof profileUpdateSchema>;

      if (!userId) {
        return reply.status(401).send({
          error: 'Unauthorized',
          message: 'User authentication required',
        });
      }

      const context = {
        ipAddress: request.ip,
        userAgent: request.headers['user-agent'],
      };

      const profile = await profileService.updateProfile(userId, profileData, context);

      return reply.send({
        profile,
        message: 'Profile updated successfully',
      });
    } catch (error) {
      fastify.log.error('Update profile error:', error);
      return reply.status(500).send({
        error: 'Internal Server Error',
        message: 'Failed to update profile',
      });
    }
  });

  // Upload profile image
  fastify.post('/profile/avatar', {
    preHandler: [fastify.authenticate],
    schema: {
      response: {
        200: {
          type: 'object',
          properties: {
            avatarUrl: { type: 'string' },
            message: { type: 'string' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const userId = (request.user as any)?.id;

      if (!userId) {
        return reply.status(401).send({
          error: 'Unauthorized',
          message: 'User authentication required',
        });
      }

      const data = await request.file();

      if (!data) {
        return reply.status(400).send({
          error: 'Bad Request',
          message: 'No file uploaded',
        });
      }

      const buffer = await data.file.toBuffer();

      const imageData = {
        originalName: data.filename,
        mimeType: data.mimetype,
        size: buffer.length,
        buffer,
      };

      const context = {
        ipAddress: request.ip,
        userAgent: request.headers['user-agent'],
      };

      const result = await profileService.uploadProfileImage(userId, imageData, context);

      return reply.send({
        avatarUrl: result.avatarUrl,
        message: 'Profile image uploaded successfully',
      });
    } catch (error) {
      fastify.log.error('Upload profile image error:', error);
      return reply.status(400).send({
        error: 'Upload Failed',
        message: error.message || 'Failed to upload profile image',
      });
    }
  });

  // Delete profile image
  fastify.delete('/profile/avatar', {
    preHandler: [fastify.authenticate],
    schema: {
      response: {
        200: {
          type: 'object',
          properties: {
            message: { type: 'string' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const userId = (request.user as any)?.id;

      if (!userId) {
        return reply.status(401).send({
          error: 'Unauthorized',
          message: 'User authentication required',
        });
      }

      const context = {
        ipAddress: request.ip,
        userAgent: request.headers['user-agent'],
      };

      await profileService.deleteProfileImage(userId, context);

      return reply.send({
        message: 'Profile image deleted successfully',
      });
    } catch (error) {
      fastify.log.error('Delete profile image error:', error);
      return reply.status(500).send({
        error: 'Internal Server Error',
        message: 'Failed to delete profile image',
      });
    }
  });

  // Get user preferences
  fastify.get('/preferences', {
    preHandler: [fastify.authenticate],
    schema: {
      querystring: {
        type: 'object',
        properties: {
          category: { type: 'string' },
        },
      },
      response: {
        200: {
          type: 'object',
          properties: {
            preferences: {
              type: 'array',
              items: {
                type: 'object',
                properties: {
                  id: { type: 'string' },
                  category: { type: 'string' },
                  settings: { type: 'object' },
                  createdAt: { type: 'string' },
                  updatedAt: { type: 'string' },
                },
              },
            },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const userId = (request.user as any)?.id;
      const { category } = request.query as { category?: string };

      if (!userId) {
        return reply.status(401).send({
          error: 'Unauthorized',
          message: 'User authentication required',
        });
      }

      const preferences = await profileService.getPreferences(userId, category);

      return reply.send({
        preferences,
      });
    } catch (error) {
      fastify.log.error('Get preferences error:', error);
      return reply.status(500).send({
        error: 'Internal Server Error',
        message: 'Failed to retrieve preferences',
      });
    }
  });

  // Update user preferences
  fastify.put<{
    Body: z.infer<typeof preferencesUpdateSchema>;
  }>('/preferences', {
    preHandler: [fastify.authenticate],
    schema: {
      body: preferencesUpdateSchema,
      response: {
        200: {
          type: 'object',
          properties: {
            preferences: { type: 'object' },
            message: { type: 'string' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const userId = (request.user as any)?.id;
      const { category, settings } = request.body as z.infer<typeof preferencesUpdateSchema>;

      if (!userId) {
        return reply.status(401).send({
          error: 'Unauthorized',
          message: 'User authentication required',
        });
      }

      const context = {
        ipAddress: request.ip,
        userAgent: request.headers['user-agent'],
      };

      const preferences = await profileService.updatePreferences(userId, category, settings, context);

      return reply.send({
        preferences,
        message: 'Preferences updated successfully',
      });
    } catch (error) {
      fastify.log.error('Update preferences error:', error);
      return reply.status(500).send({
        error: 'Internal Server Error',
        message: 'Failed to update preferences',
      });
    }
  });

  // Get notification preferences
  fastify.get('/preferences/notifications', {
    preHandler: [fastify.authenticate],
    schema: {
      response: {
        200: {
          type: 'object',
          properties: {
            preferences: { type: 'object' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const userId = (request.user as any)?.id;

      if (!userId) {
        return reply.status(401).send({
          error: 'Unauthorized',
          message: 'User authentication required',
        });
      }

      const preferences = await profileService.getNotificationPreferences(userId);

      return reply.send({
        preferences,
      });
    } catch (error) {
      fastify.log.error('Get notification preferences error:', error);
      return reply.status(500).send({
        error: 'Internal Server Error',
        message: 'Failed to retrieve notification preferences',
      });
    }
  });

  // Update notification preferences
  fastify.put<{
    Body: z.infer<typeof notificationPreferencesSchema>;
  }>('/preferences/notifications', {
    preHandler: [fastify.authenticate],
    schema: {
      body: notificationPreferencesSchema,
      response: {
        200: {
          type: 'object',
          properties: {
            preferences: { type: 'object' },
            message: { type: 'string' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const userId = (request.user as any)?.id;
      const preferencesData = request.body as z.infer<typeof notificationPreferencesSchema>;

      if (!userId) {
        return reply.status(401).send({
          error: 'Unauthorized',
          message: 'User authentication required',
        });
      }

      const context = {
        ipAddress: request.ip,
        userAgent: request.headers['user-agent'],
      };

      const preferences = await profileService.updateNotificationPreferences(userId, preferencesData, context);

      return reply.send({
        preferences,
        message: 'Notification preferences updated successfully',
      });
    } catch (error) {
      fastify.log.error('Update notification preferences error:', error);
      return reply.status(500).send({
        error: 'Internal Server Error',
        message: 'Failed to update notification preferences',
      });
    }
  });

  // Search user profiles
  fastify.get('/profiles/search', {
    preHandler: [fastify.authenticate],
    schema: {
      querystring: {
        type: 'object',
        properties: {
          q: { type: 'string', minLength: 1 },
          limit: { type: 'number', minimum: 1, maximum: 100, default: 20 },
          offset: { type: 'number', minimum: 0, default: 0 },
        },
        required: ['q'],
      },
      response: {
        200: {
          type: 'object',
          properties: {
            profiles: {
              type: 'array',
              items: { type: 'object' },
            },
            total: { type: 'number' },
            pagination: {
              type: 'object',
              properties: {
                limit: { type: 'number' },
                offset: { type: 'number' },
                hasMore: { type: 'boolean' },
              },
            },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { q, limit = 20, offset = 0 } = request.query as {
        q: string;
        limit: number;
        offset: number;
      };

      const result = await profileService.searchProfiles(q, limit, offset);
      const hasMore = offset + limit < result.total;

      return reply.send({
        profiles: result.profiles,
        total: result.total,
        pagination: {
          limit,
          offset,
          hasMore,
        },
      });
    } catch (error) {
      fastify.log.error('Search profiles error:', error);
      return reply.status(500).send({
        error: 'Internal Server Error',
        message: 'Failed to search profiles',
      });
    }
  });

  // Get public profile (for other users to view)
  fastify.get('/profiles/:userId', {
    preHandler: [fastify.authenticate],
    schema: {
      params: {
        type: 'object',
        properties: {
          userId: { type: 'string', format: 'uuid' },
        },
        required: ['userId'],
      },
      response: {
        200: {
          type: 'object',
          properties: {
            profile: { type: 'object' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { userId } = request.params as { userId: string };
      const currentUserId = (request.user as any)?.id;

      // Check if user is trying to view their own profile
      if (userId === currentUserId) {
        return reply.redirect(307, '/api/auth/profile');
      }

      const profile = await profileService.getProfile(userId);

      if (!profile) {
        return reply.status(404).send({
          error: 'Profile Not Found',
          message: 'User profile not found',
        });
      }

      // Return only public profile information
      const publicProfile = {
        id: profile.id,
        displayName: profile.displayName,
        firstName: profile.firstName,
        lastName: profile.lastName,
        bio: profile.bio,
        avatarUrl: profile.avatarUrl,
        createdAt: profile.createdAt,
      };

      return reply.send({
        profile: publicProfile,
      });
    } catch (error) {
      fastify.log.error('Get public profile error:', error);
      return reply.status(500).send({
        error: 'Internal Server Error',
        message: 'Failed to retrieve profile',
      });
    }
  });

  // Delete user profile (soft delete)
  fastify.delete('/profile', {
    preHandler: [fastify.authenticate],
    schema: {
      response: {
        200: {
          type: 'object',
          properties: {
            message: { type: 'string' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const userId = (request.user as any)?.id;

      if (!userId) {
        return reply.status(401).send({
          error: 'Unauthorized',
          message: 'User authentication required',
        });
      }

      const context = {
        ipAddress: request.ip,
        userAgent: request.headers['user-agent'],
      };

      await profileService.deleteProfile(userId, context);

      return reply.send({
        message: 'Profile deleted successfully',
      });
    } catch (error) {
      fastify.log.error('Delete profile error:', error);
      return reply.status(500).send({
        error: 'Internal Server Error',
        message: 'Failed to delete profile',
      });
    }
  });
}

// Epic 11.3 RBAC Routes
// HTTP routes for role and permission management

import { FastifyInstance, FastifyRequest, FastifyReply } from 'fastify';
import { z } from 'zod';
import { AuthenticationService } from '../AuthenticationService';
import { RBACService } from '../services/RBACService';

// Role creation schema
const createRoleSchema = z.object({
  name: z.string().min(1).max(100),
  description: z.string().max(500).optional(),
  scope: z.enum(['global', 'organization', 'team']),
  organizationId: z.string().uuid().optional(),
  permissions: z.array(z.object({
    resource: z.string().min(1),
    action: z.string().min(1),
    scope: z.enum(['global', 'organization', 'team', 'own']),
    conditions: z.record(z.any()).optional(),
  })),
});

// Role update schema
const updateRoleSchema = createRoleSchema.partial();

// Role assignment schema
const assignRoleSchema = z.object({
  userId: z.string().uuid(),
  roleId: z.string().uuid(),
  expiresAt: z.string().datetime().optional(),
  scopeContext: z.record(z.any()).optional(),
});

// Role removal schema
const removeRoleSchema = z.object({
  userId: z.string().uuid(),
  roleId: z.string().uuid(),
});

// Permission check schema
const checkPermissionSchema = z.object({
  userId: z.string().uuid(),
  resource: z.string(),
  action: z.string(),
  context: z.object({
    organizationId: z.string().uuid().optional(),
    teamId: z.string().uuid().optional(),
    resourceId: z.string().uuid().optional(),
  }).optional(),
});

interface RBACRouteContext {
  authService: AuthenticationService;
  rbacService: RBACService;
}

export async function rbacRoutes(fastify: FastifyInstance, context: RBACRouteContext) {
  const { authService, rbacService } = context;

  // Get all roles with pagination and filtering
  fastify.get('/rbac/roles', {
    preHandler: [
      fastify.authenticate,
      fastify.requirePermission({ resource: 'roles', action: 'read' }),
    ],
    schema: {
      querystring: {
        type: 'object',
        properties: {
          scope: { type: 'string', enum: ['global', 'organization', 'team'] },
          organizationId: { type: 'string', format: 'uuid' },
          search: { type: 'string' },
          limit: { type: 'number', minimum: 1, maximum: 100, default: 50 },
          offset: { type: 'number', minimum: 0, default: 0 },
        },
      },
      response: {
        200: {
          type: 'object',
          properties: {
            roles: {
              type: 'array',
              items: {
                type: 'object',
                properties: {
                  id: { type: 'string' },
                  name: { type: 'string' },
                  description: { type: 'string' },
                  scope: { type: 'string' },
                  organizationId: { type: 'string' },
                  createdAt: { type: 'string' },
                  updatedAt: { type: 'string' },
                },
              },
            },
            total: { type: 'number' },
            pagination: {
              type: 'object',
              properties: {
                limit: { type: 'number' },
                offset: { type: 'number' },
                hasMore: { type: 'boolean' },
              },
            },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { scope, organizationId, search, limit = 50, offset = 0 } = request.query as any;

      const result = await rbacService.getRoles(
        { scope, organizationId, search },
        { limit, offset }
      );

      return reply.send({
        roles: result.roles,
        total: result.total,
        pagination: {
          limit,
          offset,
          hasMore: offset + limit < result.total,
        },
      });
    } catch (error) {
      fastify.log.error('Get roles error:', error);
      return reply.status(500).send({
        error: 'Internal Server Error',
        message: 'Failed to retrieve roles',
      });
    }
  });

  // Get role by ID with permissions
  fastify.get('/rbac/roles/:roleId', {
    preHandler: [
      fastify.authenticate,
      fastify.requirePermission({ resource: 'roles', action: 'read' }),
    ],
    schema: {
      params: {
        type: 'object',
        properties: {
          roleId: { type: 'string', format: 'uuid' },
        },
        required: ['roleId'],
      },
      response: {
        200: {
          type: 'object',
          properties: {
            role: { type: 'object' },
            permissions: { type: 'array' },
            assignedUsers: { type: 'array' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { roleId } = request.params as { roleId: string };

      const [role, permissions, assignedUsers] = await Promise.all([
        rbacService.getRoleById(roleId),
        rbacService.getRolePermissions(roleId),
        rbacService.getUsersWithRole(roleId),
      ]);

      if (!role) {
        return reply.status(404).send({
          error: 'Role Not Found',
          message: 'Role not found',
        });
      }

      return reply.send({
        role,
        permissions,
        assignedUsers,
      });
    } catch (error) {
      fastify.log.error('Get role error:', error);
      return reply.status(500).send({
        error: 'Internal Server Error',
        message: 'Failed to retrieve role',
      });
    }
  });

  // Create new role
  fastify.post<{
    Body: z.infer<typeof createRoleSchema>;
  }>('/rbac/roles', {
    preHandler: [
      fastify.authenticate,
      fastify.requirePermission({ resource: 'roles', action: 'write' }),
    ],
    schema: {
      body: createRoleSchema,
      response: {
        201: {
          type: 'object',
          properties: {
            role: { type: 'object' },
            message: { type: 'string' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const roleData = request.body as z.infer<typeof createRoleSchema>;
      const userId = (request.user as any)?.id;

      const context = {
        ipAddress: request.ip,
        userAgent: request.headers['user-agent'],
        createdBy: userId,
      };

      const role = await rbacService.createRole(roleData, context);

      return reply.status(201).send({
        role,
        message: 'Role created successfully',
      });
    } catch (error) {
      fastify.log.error('Create role error:', error);
      return reply.status(400).send({
        error: 'Role Creation Failed',
        message: error.message || 'Failed to create role',
      });
    }
  });

  // Update role
  fastify.put<{
    Body: z.infer<typeof updateRoleSchema>;
    Params: { roleId: string };
  }>('/rbac/roles/:roleId', {
    preHandler: [
      fastify.authenticate,
      fastify.requirePermission({ resource: 'roles', action: 'write' }),
    ],
    schema: {
      params: {
        type: 'object',
        properties: {
          roleId: { type: 'string', format: 'uuid' },
        },
        required: ['roleId'],
      },
      body: updateRoleSchema,
      response: {
        200: {
          type: 'object',
          properties: {
            role: { type: 'object' },
            message: { type: 'string' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { roleId } = request.params as { roleId: string };
      const updates = request.body as z.infer<typeof updateRoleSchema>;
      const userId = (request.user as any)?.id;

      const context = {
        ipAddress: request.ip,
        userAgent: request.headers['user-agent'],
        updatedBy: userId,
      };

      const role = await rbacService.updateRole(roleId, updates, context);

      return reply.send({
        role,
        message: 'Role updated successfully',
      });
    } catch (error) {
      fastify.log.error('Update role error:', error);
      return reply.status(400).send({
        error: 'Role Update Failed',
        message: error.message || 'Failed to update role',
      });
    }
  });

  // Delete role
  fastify.delete('/rbac/roles/:roleId', {
    preHandler: [
      fastify.authenticate,
      fastify.requirePermission({ resource: 'roles', action: 'delete' }),
    ],
    schema: {
      params: {
        type: 'object',
        properties: {
          roleId: { type: 'string', format: 'uuid' },
        },
        required: ['roleId'],
      },
      response: {
        200: {
          type: 'object',
          properties: {
            message: { type: 'string' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { roleId } = request.params as { roleId: string };
      const userId = (request.user as any)?.id;

      const context = {
        ipAddress: request.ip,
        userAgent: request.headers['user-agent'],
        deletedBy: userId,
      };

      await rbacService.deleteRole(roleId, context);

      return reply.send({
        message: 'Role deleted successfully',
      });
    } catch (error) {
      fastify.log.error('Delete role error:', error);
      return reply.status(400).send({
        error: 'Role Deletion Failed',
        message: error.message || 'Failed to delete role',
      });
    }
  });

  // Assign role to user
  fastify.post<{
    Body: z.infer<typeof assignRoleSchema>;
  }>('/rbac/assign-role', {
    preHandler: [
      fastify.authenticate,
      fastify.requirePermission({ resource: 'users', action: 'write' }),
    ],
    schema: {
      body: assignRoleSchema,
      response: {
        200: {
          type: 'object',
          properties: {
            assignment: { type: 'object' },
            message: { type: 'string' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const assignmentData = request.body as z.infer<typeof assignRoleSchema>;
      const grantedBy = (request.user as any)?.id;

      const context = {
        ipAddress: request.ip,
        userAgent: request.headers['user-agent'],
      };

      const assignment = await rbacService.assignRole(
        {
          ...assignmentData,
          grantedBy,
          expiresAt: assignmentData.expiresAt ? new Date(assignmentData.expiresAt) : undefined,
        },
        context
      );

      return reply.send({
        assignment,
        message: 'Role assigned successfully',
      });
    } catch (error) {
      fastify.log.error('Assign role error:', error);
      return reply.status(400).send({
        error: 'Role Assignment Failed',
        message: error.message || 'Failed to assign role',
      });
    }
  });

  // Remove role from user
  fastify.post<{
    Body: z.infer<typeof removeRoleSchema>;
  }>('/rbac/remove-role', {
    preHandler: [
      fastify.authenticate,
      fastify.requirePermission({ resource: 'users', action: 'write' }),
    ],
    schema: {
      body: removeRoleSchema,
      response: {
        200: {
          type: 'object',
          properties: {
            message: { type: 'string' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { userId, roleId } = request.body as z.infer<typeof removeRoleSchema>;
      const removedBy = (request.user as any)?.id;

      const context = {
        ipAddress: request.ip,
        userAgent: request.headers['user-agent'],
        removedBy,
      };

      await rbacService.removeRole(userId, roleId, context);

      return reply.send({
        message: 'Role removed successfully',
      });
    } catch (error) {
      fastify.log.error('Remove role error:', error);
      return reply.status(400).send({
        error: 'Role Removal Failed',
        message: error.message || 'Failed to remove role',
      });
    }
  });

  // Get user roles and permissions
  fastify.get('/rbac/users/:userId/roles', {
    preHandler: [
      fastify.authenticate,
      fastify.requirePermission({ resource: 'users', action: 'read' }),
    ],
    schema: {
      params: {
        type: 'object',
        properties: {
          userId: { type: 'string', format: 'uuid' },
        },
        required: ['userId'],
      },
      response: {
        200: {
          type: 'object',
          properties: {
            roles: { type: 'array' },
            permissions: { type: 'array' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { userId } = request.params as { userId: string };

      const [roles, permissions] = await Promise.all([
        rbacService.getUserRoles(userId),
        rbacService.getUserPermissions(userId),
      ]);

      return reply.send({
        roles,
        permissions,
      });
    } catch (error) {
      fastify.log.error('Get user roles error:', error);
      return reply.status(500).send({
        error: 'Internal Server Error',
        message: 'Failed to retrieve user roles',
      });
    }
  });

  // Check permission
  fastify.post<{
    Body: z.infer<typeof checkPermissionSchema>;
  }>('/rbac/check-permission', {
    preHandler: [
      fastify.authenticate,
      fastify.requirePermission({ resource: 'users', action: 'read' }),
    ],
    schema: {
      body: checkPermissionSchema,
      response: {
        200: {
          type: 'object',
          properties: {
            allowed: { type: 'boolean' },
            reason: { type: 'string' },
            matchingPermissions: { type: 'array' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { userId, resource, action, context: permContext } = request.body as z.infer<typeof checkPermissionSchema>;

      const result = await rbacService.checkPermission(
        userId,
        { resource, action },
        { userId, ...permContext }
      );

      return reply.send(result);
    } catch (error) {
      fastify.log.error('Check permission error:', error);
      return reply.status(500).send({
        error: 'Internal Server Error',
        message: 'Failed to check permission',
      });
    }
  });

  // Get RBAC statistics
  fastify.get('/rbac/stats', {
    preHandler: [
      fastify.authenticate,
      fastify.requirePermission({ resource: 'system', action: 'read' }),
    ],
    schema: {
      response: {
        200: {
          type: 'object',
          properties: {
            totalRoles: { type: 'number' },
            rolesByScope: { type: 'object' },
            totalAssignments: { type: 'number' },
            recentAssignments: { type: 'number' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const stats = await rbacService.getRoleStats();
      return reply.send(stats);
    } catch (error) {
      fastify.log.error('Get RBAC stats error:', error);
      return reply.status(500).send({
        error: 'Internal Server Error',
        message: 'Failed to retrieve RBAC statistics',
      });
    }
  });

  // Get current user's permissions (for UI state management)
  fastify.get('/rbac/my-permissions', {
    preHandler: [fastify.authenticate],
    schema: {
      response: {
        200: {
          type: 'object',
          properties: {
            roles: { type: 'array' },
            permissions: { type: 'array' },
            permissionMap: { type: 'object' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const userId = (request.user as any)?.id;

      const [roles, permissions] = await Promise.all([
        rbacService.getUserRoles(userId),
        rbacService.getUserPermissions(userId),
      ]);

      // Create permission map for easier frontend checking
      const permissionMap: Record<string, boolean> = {};
      permissions.forEach(perm => {
        const key = `${perm.resource}:${perm.action}`;
        permissionMap[key] = true;
      });

      return reply.send({
        roles,
        permissions,
        permissionMap,
      });
    } catch (error) {
      fastify.log.error('Get my permissions error:', error);
      return reply.status(500).send({
        error: 'Internal Server Error',
        message: 'Failed to retrieve permissions',
      });
    }
  });
}

// Epic 11 Session Management Routes
// HTTP routes for session management and monitoring

import { FastifyInstance, FastifyRequest, FastifyReply } from 'fastify';
import { z } from 'zod';
import { AuthenticationService } from '../AuthenticationService';
import { SessionService } from '../services/SessionService';

// Session revocation schema
const revokeSessionSchema = z.object({
  sessionId: z.string().uuid(),
  reason: z.string().optional(),
});

// Bulk session revocation schema
const revokeBulkSessionsSchema = z.object({
  exceptCurrent: z.boolean().default(true),
  reason: z.string().optional(),
});

interface SessionRouteContext {
  authService: AuthenticationService;
  sessionService: SessionService;
}

export async function sessionRoutes(fastify: FastifyInstance, context: SessionRouteContext) {
  const { authService, sessionService } = context;

  // Get current user's active sessions
  fastify.get('/sessions', {
    preHandler: [fastify.authenticate], // JWT authentication middleware
    schema: {
      response: {
        200: {
          type: 'object',
          properties: {
            sessions: {
              type: 'array',
              items: {
                type: 'object',
                properties: {
                  id: { type: 'string' },
                  deviceInfo: { type: 'object' },
                  location: { type: 'object' },
                  lastAccessedAt: { type: 'string' },
                  createdAt: { type: 'string' },
                  current: { type: 'boolean' },
                },
              },
            },
            stats: {
              type: 'object',
              properties: {
                totalSessions: { type: 'number' },
                activeSessions: { type: 'number' },
                expiredSessions: { type: 'number' },
                revokedSessions: { type: 'number' },
              },
            },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const userId = (request.user as any)?.id;
      const currentSessionId = (request.user as any)?.sessionId;

      if (!userId) {
        return reply.status(401).send({
          error: 'Unauthorized',
          message: 'User authentication required',
        });
      }

      // Get active sessions
      const sessions = await sessionService.getUserActiveSessions(userId);

      // Mark current session
      const sessionsWithCurrent = sessions.map(session => ({
        ...session,
        current: session.id === currentSessionId,
      }));

      // Get session statistics
      const stats = await sessionService.getSessionStats(userId);

      return reply.send({
        sessions: sessionsWithCurrent,
        stats,
      });
    } catch (error) {
      fastify.log.error('Get sessions error:', error);
      return reply.status(500).send({
        error: 'Internal Server Error',
        message: 'Failed to retrieve sessions',
      });
    }
  });

  // Revoke a specific session
  fastify.post<{
    Body: z.infer<typeof revokeSessionSchema>;
  }>('/sessions/revoke', {
    preHandler: [fastify.authenticate], // JWT authentication middleware
    schema: {
      body: revokeSessionSchema,
      response: {
        200: {
          type: 'object',
          properties: {
            success: { type: 'boolean' },
            message: { type: 'string' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { sessionId, reason } = request.body as z.infer<typeof revokeSessionSchema>;
      const userId = (request.user as any)?.id;

      if (!userId) {
        return reply.status(401).send({
          error: 'Unauthorized',
          message: 'User authentication required',
        });
      }

      // Verify the session belongs to the user
      const sessions = await sessionService.getUserActiveSessions(userId);
      const targetSession = sessions.find(s => s.id === sessionId);

      if (!targetSession) {
        return reply.status(404).send({
          error: 'Session Not Found',
          message: 'Session not found or does not belong to user',
        });
      }

      // Find session token to revoke
      const sessionResult = await sessionService.getSession(sessionId);
      if (sessionResult) {
        await sessionService.revokeSession(sessionResult.sessionToken, reason);
      }

      return reply.send({
        success: true,
        message: 'Session revoked successfully',
      });
    } catch (error) {
      fastify.log.error('Revoke session error:', error);
      return reply.status(500).send({
        error: 'Internal Server Error',
        message: 'Failed to revoke session',
      });
    }
  });

  // Revoke all sessions except current (bulk revocation)
  fastify.post<{
    Body: z.infer<typeof revokeBulkSessionsSchema>;
  }>('/sessions/revoke-all', {
    preHandler: [fastify.authenticate], // JWT authentication middleware
    schema: {
      body: revokeBulkSessionsSchema,
      response: {
        200: {
          type: 'object',
          properties: {
            success: { type: 'boolean' },
            message: { type: 'string' },
            revokedCount: { type: 'number' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { exceptCurrent, reason } = request.body as z.infer<typeof revokeBulkSessionsSchema>;
      const userId = (request.user as any)?.id;
      const currentSessionId = (request.user as any)?.sessionId;

      if (!userId) {
        return reply.status(401).send({
          error: 'Unauthorized',
          message: 'User authentication required',
        });
      }

      const exceptSessionId = exceptCurrent ? currentSessionId : undefined;
      const revokedCount = await sessionService.revokeAllUserSessions(userId, exceptSessionId);

      return reply.send({
        success: true,
        message: `Successfully revoked ${revokedCount} session(s)`,
        revokedCount,
      });
    } catch (error) {
      fastify.log.error('Revoke all sessions error:', error);
      return reply.status(500).send({
        error: 'Internal Server Error',
        message: 'Failed to revoke sessions',
      });
    }
  });

  // Renew current session
  fastify.post('/sessions/renew', {
    preHandler: [fastify.authenticate], // JWT authentication middleware
    schema: {
      response: {
        200: {
          type: 'object',
          properties: {
            success: { type: 'boolean' },
            message: { type: 'string' },
            newExpiresAt: { type: 'string' },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const sessionToken = (request.user as any)?.sessionToken;

      if (!sessionToken) {
        return reply.status(401).send({
          error: 'Unauthorized',
          message: 'Session token required',
        });
      }

      const renewedSession = await sessionService.renewSession(sessionToken);

      if (!renewedSession) {
        return reply.status(404).send({
          error: 'Session Not Found',
          message: 'Session not found or already expired',
        });
      }

      return reply.send({
        success: true,
        message: 'Session renewed successfully',
        newExpiresAt: renewedSession.expiresAt.toISOString(),
      });
    } catch (error) {
      fastify.log.error('Renew session error:', error);
      return reply.status(500).send({
        error: 'Internal Server Error',
        message: 'Failed to renew session',
      });
    }
  });

  // Get session security insights
  fastify.get('/sessions/security', {
    preHandler: [fastify.authenticate], // JWT authentication middleware
    schema: {
      response: {
        200: {
          type: 'object',
          properties: {
            suspiciousActivity: {
              type: 'object',
              properties: {
                multipleLocations: { type: 'boolean' },
                unusualDevices: { type: 'boolean' },
                suspiciousLocations: { type: 'array', items: { type: 'string' } },
                newDevices: { type: 'array' },
              },
            },
            recommendations: {
              type: 'array',
              items: { type: 'string' },
            },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const userId = (request.user as any)?.id;

      if (!userId) {
        return reply.status(401).send({
          error: 'Unauthorized',
          message: 'User authentication required',
        });
      }

      const suspiciousActivity = await sessionService.detectSuspiciousActivity(userId);

      // Generate security recommendations
      const recommendations: string[] = [];

      if (suspiciousActivity.multipleLocations) {
        recommendations.push('Multiple login locations detected. Consider enabling two-factor authentication.');
      }

      if (suspiciousActivity.unusualDevices) {
        recommendations.push('Unusual devices detected. Review your active sessions.');
      }

      if (suspiciousActivity.suspiciousLocations.length > 0) {
        recommendations.push('New login locations detected. Revoke sessions from unrecognized locations.');
      }

      if (suspiciousActivity.newDevices.length > 0) {
        recommendations.push('New devices detected. Verify these devices are yours.');
      }

      // Get session stats for additional insights
      const stats = await sessionService.getSessionStats(userId);

      if (stats.activeSessions > 10) {
        recommendations.push('You have many active sessions. Consider revoking old sessions.');
      }

      return reply.send({
        suspiciousActivity,
        recommendations,
      });
    } catch (error) {
      fastify.log.error('Get security insights error:', error);
      return reply.status(500).send({
        error: 'Internal Server Error',
        message: 'Failed to retrieve security insights',
      });
    }
  });

  // Session activity endpoint (for real-time monitoring)
  fastify.get('/sessions/activity', {
    preHandler: [fastify.authenticate], // JWT authentication middleware
    schema: {
      querystring: {
        type: 'object',
        properties: {
          limit: { type: 'number', default: 50 },
          offset: { type: 'number', default: 0 },
        },
      },
      response: {
        200: {
          type: 'object',
          properties: {
            activities: {
              type: 'array',
              items: {
                type: 'object',
                properties: {
                  timestamp: { type: 'string' },
                  action: { type: 'string' },
                  sessionId: { type: 'string' },
                  deviceInfo: { type: 'object' },
                  location: { type: 'object' },
                },
              },
            },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const userId = (request.user as any)?.id;
      const { limit = 50, offset = 0 } = request.query as any;

      if (!userId) {
        return reply.status(401).send({
          error: 'Unauthorized',
          message: 'User authentication required',
        });
      }

      // Get session-related audit logs
      const auditService = authService.getService('audit');
      const activities = await auditService.getAuditLogs({
        userId,
        startDate: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000), // Last 7 days
        limit,
        offset,
      });

      // Filter for session-related activities
      const sessionActivities = activities.filter(activity => 
        activity.action.includes('session')
      );

      return reply.send({
        activities: sessionActivities.map(activity => ({
          timestamp: activity.createdAt.toISOString(),
          action: activity.action,
          sessionId: activity.sessionId,
          deviceInfo: activity.details?.deviceInfo || {},
          location: activity.details?.location || { ipAddress: activity.ipAddress },
        })),
      });
    } catch (error) {
      fastify.log.error('Get session activity error:', error);
      return reply.status(500).send({
        error: 'Internal Server Error',
        message: 'Failed to retrieve session activity',
      });
    }
  });

  // Health check for session service
  fastify.get('/sessions/health', {
    schema: {
      response: {
        200: {
          type: 'object',
          properties: {
            status: { type: 'string' },
            metrics: {
              type: 'object',
              properties: {
                totalActiveSessions: { type: 'number' },
                expiredSessionsLastHour: { type: 'number' },
                averageSessionDuration: { type: 'number' },
              },
            },
          },
        },
      },
    },
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      // Get system-wide session metrics
      const dbService = authService.getService('database');

      const metricsResult = await dbService.query(`
        SELECT 
          COUNT(CASE WHEN NOT revoked AND expires_at > NOW() THEN 1 END) as active_sessions,
          COUNT(CASE WHEN expires_at < NOW() AND expires_at > NOW() - INTERVAL '1 hour' THEN 1 END) as expired_last_hour,
          AVG(EXTRACT(EPOCH FROM (last_accessed_at - created_at))) as avg_duration
        FROM user_sessions
        WHERE created_at > NOW() - INTERVAL '24 hours'
      `);

      const metrics = metricsResult.rows[0];

      return reply.send({
        status: 'healthy',
        metrics: {
          totalActiveSessions: parseInt(metrics.active_sessions) || 0,
          expiredSessionsLastHour: parseInt(metrics.expired_last_hour) || 0,
          averageSessionDuration: parseFloat(metrics.avg_duration) || 0,
        },
      });
    } catch (error) {
      fastify.log.error('Session health check error:', error);
      return reply.status(500).send({
        status: 'unhealthy',
        error: error.message,
      });
    }
  });
}

// Epic 11 Analytics Service
// Registration analytics and monitoring service

import { DatabaseService } from '../database/DatabaseService';
import { AuthConfig } from '../types';

export interface RegistrationMetrics {
  dailyRegistrations: number;
  weeklyRegistrations: number;
  monthlyRegistrations: number;
  conversionRate: number;
  averageCompletionTime: number;
  dropOffPoints: Array<{
    step: string;
    count: number;
    percentage: number;
  }>;
  sourceBreakdown: Record<string, {
    visits: number;
    registrations: number;
    conversionRate: number;
  }>;
}

export interface FormAnalytics {
  fieldInteractionTime: Record<string, number>;
  fieldErrorRate: Record<string, number>;
  mostProblematicFields: Array<{
    field: string;
    errorRate: number;
    averageTime: number;
  }>;
  stepCompletionRates: Record<number, number>;
}

export class AnalyticsService {
  private db: DatabaseService;
  private config: AuthConfig;

  constructor(config: AuthConfig, db: DatabaseService) {
    this.config = config;
    this.db = db;
  }

  async trackRegistrationEvent(
    eventType: string,
    data: {
      emailHash?: string;
      ipAddress?: string;
      userAgent?: string;
      source?: string;
      referrer?: string;
      additionalData?: any;
    }
  ): Promise<void> {
    try {
      await this.db.query(`
        INSERT INTO registration_analytics (
          event_type, email_hash, ip_address, user_agent, 
          source, referrer, additional_data
        ) VALUES ($1, $2, $3, $4, $5, $6, $7)
      `, [
        eventType,
        data.emailHash,
        data.ipAddress,
        data.userAgent,
        data.source || 'organic',
        data.referrer,
        JSON.stringify(data.additionalData || {}),
      ]);
    } catch (error) {
      console.error('Failed to track registration event:', error);
    }
  }

  async trackFormFieldInteraction(
    sessionId: string,
    fieldName: string,
    eventType: 'focus' | 'blur' | 'change' | 'error',
    data: {
      fieldValueLength?: number;
      errorMessage?: string;
      timeSpentMs?: number;
    }
  ): Promise<void> {
    try {
      await this.db.query(`
        INSERT INTO form_field_analytics (
          session_id, field_name, event_type, field_value_length,
          error_message, time_spent_ms
        ) VALUES ($1, $2, $3, $4, $5, $6)
      `, [
        sessionId,
        fieldName,
        eventType,
        data.fieldValueLength || null,
        data.errorMessage || null,
        data.timeSpentMs || null,
      ]);
    } catch (error) {
      console.error('Failed to track form field interaction:', error);
    }
  }

  async trackRegistrationFunnel(
    sessionId: string,
    step: string,
    data: {
      emailHash?: string;
      stepData?: any;
      durationMs?: number;
    }
  ): Promise<void> {
    try {
      await this.db.query(`
        INSERT INTO registration_funnel (
          session_id, email_hash, step, step_data, duration_ms
        ) VALUES ($1, $2, $3, $4, $5)
      `, [
        sessionId,
        data.emailHash,
        step,
        JSON.stringify(data.stepData || {}),
        data.durationMs,
      ]);
    } catch (error) {
      console.error('Failed to track registration funnel:', error);
    }
  }

  async getRegistrationMetrics(timeframe: 'day' | 'week' | 'month' = 'week'): Promise<RegistrationMetrics> {
    const timeframes = {
      day: '1 day',
      week: '1 week',
      month: '1 month',
    };

    try {
      // Get registration counts
      const registrationCounts = await this.db.query(`
        SELECT 
          COUNT(*) FILTER (WHERE created_at >= NOW() - INTERVAL '1 day') as daily,
          COUNT(*) FILTER (WHERE created_at >= NOW() - INTERVAL '1 week') as weekly,
          COUNT(*) FILTER (WHERE created_at >= NOW() - INTERVAL '1 month') as monthly
        FROM registration_analytics 
        WHERE event_type = 'completed'
      `);

      // Get conversion rates from funnel
      const conversionData = await this.db.query(`
        WITH funnel_stats AS (
          SELECT 
            COUNT(DISTINCT CASE WHEN step = 'started' THEN session_id END) as started,
            COUNT(DISTINCT CASE WHEN step = 'completed' THEN session_id END) as completed
          FROM registration_funnel
          WHERE created_at >= NOW() - INTERVAL '${timeframes[timeframe]}'
        )
        SELECT 
          started,
          completed,
          CASE WHEN started > 0 THEN completed::DECIMAL / started ELSE 0 END as conversion_rate
        FROM funnel_stats
      `);

      // Get average completion time
      const completionTime = await this.db.query(`
        WITH session_times AS (
          SELECT 
            session_id,
            MIN(created_at) as start_time,
            MAX(created_at) as end_time
          FROM registration_funnel
          WHERE created_at >= NOW() - INTERVAL '${timeframes[timeframe]}'
            AND step IN ('started', 'completed')
          GROUP BY session_id
          HAVING COUNT(DISTINCT step) = 2
        )
        SELECT AVG(EXTRACT(EPOCH FROM (end_time - start_time))) as avg_seconds
        FROM session_times
      `);

      // Get drop-off points
      const dropOffData = await this.db.query(`
        WITH step_counts AS (
          SELECT 
            step,
            COUNT(DISTINCT session_id) as count
          FROM registration_funnel
          WHERE created_at >= NOW() - INTERVAL '${timeframes[timeframe]}'
          GROUP BY step
        ),
        total_started AS (
          SELECT count as total FROM step_counts WHERE step = 'started'
        )
        SELECT 
          sc.step,
          sc.count,
          CASE WHEN ts.total > 0 THEN (sc.count::DECIMAL / ts.total * 100)::INTEGER ELSE 0 END as percentage
        FROM step_counts sc
        CROSS JOIN total_started ts
        ORDER BY sc.count DESC
      `);

      // Get source breakdown
      const sourceData = await this.db.query(`
        SELECT 
          COALESCE(source, 'organic') as source,
          COUNT(*) FILTER (WHERE event_type = 'started') as visits,
          COUNT(*) FILTER (WHERE event_type = 'completed') as registrations
        FROM registration_analytics
        WHERE created_at >= NOW() - INTERVAL '${timeframes[timeframe]}'
        GROUP BY source
      `);

      const counts = registrationCounts.rows[0] || { daily: 0, weekly: 0, monthly: 0 };
      const conversion = conversionData.rows[0] || { conversion_rate: 0 };
      const avgTime = completionTime.rows[0]?.avg_seconds || 0;

      return {
        dailyRegistrations: parseInt(counts.daily),
        weeklyRegistrations: parseInt(counts.weekly),
        monthlyRegistrations: parseInt(counts.monthly),
        conversionRate: parseFloat(conversion.conversion_rate),
        averageCompletionTime: Math.round(avgTime),
        dropOffPoints: dropOffData.rows.map(row => ({
          step: row.step,
          count: parseInt(row.count),
          percentage: parseInt(row.percentage),
        })),
        sourceBreakdown: sourceData.rows.reduce((acc, row) => {
          const visits = parseInt(row.visits);
          const registrations = parseInt(row.registrations);
          acc[row.source] = {
            visits,
            registrations,
            conversionRate: visits > 0 ? registrations / visits : 0,
          };
          return acc;
        }, {}),
      };
    } catch (error) {
      console.error('Failed to get registration metrics:', error);
      throw error;
    }
  }

  async getFormAnalytics(timeframe: 'day' | 'week' | 'month' = 'week'): Promise<FormAnalytics> {
    const timeframes = {
      day: '1 day',
      week: '1 week',
      month: '1 month',
    };

    try {
      // Get field interaction times
      const fieldTimes = await this.db.query(`
        SELECT 
          field_name,
          AVG(time_spent_ms) as avg_time_ms
        FROM form_field_analytics
        WHERE event_type = 'blur' 
          AND time_spent_ms IS NOT NULL
          AND created_at >= NOW() - INTERVAL '${timeframes[timeframe]}'
        GROUP BY field_name
      `);

      // Get field error rates
      const fieldErrors = await this.db.query(`
        WITH field_stats AS (
          SELECT 
            field_name,
            COUNT(*) as total_interactions,
            COUNT(*) FILTER (WHERE event_type = 'error') as error_count
          FROM form_field_analytics
          WHERE created_at >= NOW() - INTERVAL '${timeframes[timeframe]}'
          GROUP BY field_name
        )
        SELECT 
          field_name,
          CASE WHEN total_interactions > 0 
            THEN error_count::DECIMAL / total_interactions 
            ELSE 0 
          END as error_rate
        FROM field_stats
      `);

      // Get step completion rates
      const stepCompletion = await this.db.query(`
        WITH step_progression AS (
          SELECT 
            session_id,
            MAX(CASE WHEN step = 'form_step_1' THEN 1 ELSE 0 END) as reached_step_1,
            MAX(CASE WHEN step = 'form_step_2' THEN 1 ELSE 0 END) as reached_step_2,
            MAX(CASE WHEN step = 'form_step_3' THEN 1 ELSE 0 END) as reached_step_3,
            MAX(CASE WHEN step = 'completed' THEN 1 ELSE 0 END) as completed
          FROM registration_funnel
          WHERE created_at >= NOW() - INTERVAL '${timeframes[timeframe]}'
          GROUP BY session_id
        )
        SELECT 
          1 as step_number,
          AVG(reached_step_1::INTEGER) as completion_rate
        FROM step_progression
        UNION ALL
        SELECT 
          2 as step_number,
          CASE WHEN SUM(reached_step_1) > 0 
            THEN AVG(reached_step_2::INTEGER) 
            ELSE 0 
          END as completion_rate
        FROM step_progression
        WHERE reached_step_1 = 1
        UNION ALL
        SELECT 
          3 as step_number,
          CASE WHEN SUM(reached_step_2) > 0 
            THEN AVG(reached_step_3::INTEGER) 
            ELSE 0 
          END as completion_rate
        FROM step_progression
        WHERE reached_step_2 = 1
        ORDER BY step_number
      `);

      // Combine data for most problematic fields
      const fieldTimeMap = fieldTimes.rows.reduce((acc, row) => {
        acc[row.field_name] = parseFloat(row.avg_time_ms) || 0;
        return acc;
      }, {});

      const fieldErrorMap = fieldErrors.rows.reduce((acc, row) => {
        acc[row.field_name] = parseFloat(row.error_rate) || 0;
        return acc;
      }, {});

      const mostProblematicFields = Object.keys({ ...fieldTimeMap, ...fieldErrorMap })
        .map(field => ({
          field,
          errorRate: fieldErrorMap[field] || 0,
          averageTime: fieldTimeMap[field] || 0,
        }))
        .filter(item => item.errorRate > 0.1 || item.averageTime > 10000) // High error rate or >10s
        .sort((a, b) => b.errorRate - a.errorRate)
        .slice(0, 10);

      return {
        fieldInteractionTime: fieldTimeMap,
        fieldErrorRate: fieldErrorMap,
        mostProblematicFields,
        stepCompletionRates: stepCompletion.rows.reduce((acc, row) => {
          acc[row.step_number] = parseFloat(row.completion_rate);
          return acc;
        }, {}),
      };
    } catch (error) {
      console.error('Failed to get form analytics:', error);
      throw error;
    }
  }

  async getABTestResults(experimentName: string): Promise<{
    variants: Array<{
      variant: string;
      participants: number;
      conversions: number;
      conversionRate: number;
    }>;
    winner?: string;
    confidence?: number;
  }> {
    try {
      const results = await this.db.query(`
        SELECT 
          variant,
          COUNT(*) as participants,
          COUNT(*) FILTER (WHERE converted = true) as conversions,
          AVG(CASE WHEN converted THEN 1.0 ELSE 0.0 END) as conversion_rate
        FROM registration_experiments
        WHERE experiment_name = $1
        GROUP BY variant
        ORDER BY conversion_rate DESC
      `, [experimentName]);

      const variants = results.rows.map(row => ({
        variant: row.variant,
        participants: parseInt(row.participants),
        conversions: parseInt(row.conversions),
        conversionRate: parseFloat(row.conversion_rate),
      }));

      // Simple statistical significance calculation (would need more sophisticated analysis in production)
      let winner: string | undefined;
      let confidence: number | undefined;

      if (variants.length >= 2) {
        const [best, second] = variants;
        if (best.participants >= 100 && second.participants >= 100) {
          // Simplified z-test
          const p1 = best.conversionRate;
          const p2 = second.conversionRate;
          const n1 = best.participants;
          const n2 = second.participants;

          const pooledP = (best.conversions + second.conversions) / (n1 + n2);
          const se = Math.sqrt(pooledP * (1 - pooledP) * (1/n1 + 1/n2));
          const z = Math.abs(p1 - p2) / se;

          // Approximate confidence level
          confidence = Math.min(99.9, Math.max(0, (1 - 2 * (1 - normalCDF(z))) * 100));

          if (confidence > 95) {
            winner = best.variant;
          }
        }
      }

      return {
        variants,
        winner,
        confidence,
      };
    } catch (error) {
      console.error('Failed to get A/B test results:', error);
      throw error;
    }
  }

  async trackEmailDelivery(
    userId: string | null,
    emailType: string,
    emailAddress: string,
    status: 'sent' | 'delivered' | 'opened' | 'clicked' | 'bounced' | 'failed',
    metadata?: any
  ): Promise<void> {
    try {
      await this.db.query(`
        INSERT INTO email_deliveries (
          user_id, email_type, email_address, status, metadata
        ) VALUES ($1, $2, $3, $4, $5)
        ON CONFLICT (user_id, email_type, email_address) 
        DO UPDATE SET 
          status = EXCLUDED.status,
          metadata = EXCLUDED.metadata,
          ${status}_at = NOW()
      `, [
        userId,
        emailType,
        emailAddress,
        status,
        JSON.stringify(metadata || {}),
      ]);
    } catch (error) {
      console.error('Failed to track email delivery:', error);
    }
  }

  async getEmailDeliveryStats(timeframe: 'day' | 'week' | 'month' = 'week'): Promise<{
    deliveryRates: Record<string, number>;
    openRates: Record<string, number>;
    clickRates: Record<string, number>;
    bounceRates: Record<string, number>;
  }> {
    const timeframes = {
      day: '1 day',
      week: '1 week',
      month: '1 month',
    };

    try {
      const stats = await this.db.query(`
        SELECT 
          email_type,
          COUNT(*) as total_sent,
          COUNT(*) FILTER (WHERE status IN ('delivered', 'opened', 'clicked')) as delivered,
          COUNT(*) FILTER (WHERE status IN ('opened', 'clicked')) as opened,
          COUNT(*) FILTER (WHERE status = 'clicked') as clicked,
          COUNT(*) FILTER (WHERE status = 'bounced') as bounced
        FROM email_deliveries
        WHERE sent_at >= NOW() - INTERVAL '${timeframes[timeframe]}'
        GROUP BY email_type
      `);

      const deliveryRates: Record<string, number> = {};
      const openRates: Record<string, number> = {};
      const clickRates: Record<string, number> = {};
      const bounceRates: Record<string, number> = {};

      stats.rows.forEach(row => {
        const totalSent = parseInt(row.total_sent);
        const delivered = parseInt(row.delivered);
        const opened = parseInt(row.opened);
        const clicked = parseInt(row.clicked);
        const bounced = parseInt(row.bounced);

        deliveryRates[row.email_type] = totalSent > 0 ? delivered / totalSent : 0;
        openRates[row.email_type] = delivered > 0 ? opened / delivered : 0;
        clickRates[row.email_type] = opened > 0 ? clicked / opened : 0;
        bounceRates[row.email_type] = totalSent > 0 ? bounced / totalSent : 0;
      });

      return {
        deliveryRates,
        openRates,
        clickRates,
        bounceRates,
      };
    } catch (error) {
      console.error('Failed to get email delivery stats:', error);
      throw error;
    }
  }
}

// Helper function for normal CDF approximation
function normalCDF(x: number): number {
  return 0.5 * (1 + erf(x / Math.sqrt(2)));
}

function erf(x: number): number {
  // Approximation of error function
  const a1 =  0.254829592;
  const a2 = -0.284496736;
  const a3 =  1.421413741;
  const a4 = -1.453152027;
  const a5 =  1.061405429;
  const p  =  0.3275911;

  const sign = x < 0 ? -1 : 1;
  x = Math.abs(x);

  const t = 1.0 / (1.0 + p * x);
  const y = 1.0 - (((((a5 * t + a4) * t) + a3) * t + a2) * t + a1) * t * Math.exp(-x * x);

  return sign * y;
}

// Epic 11 Audit Service
// Security audit logging and compliance tracking

import { IAuditService, AuditLog, AuthConfig, SecurityEvent } from '../types';
import { DatabaseService } from '../database/DatabaseService';

export class AuditService implements IAuditService {
  private db: DatabaseService;
  private config: AuthConfig;

  constructor(config: AuthConfig, db: DatabaseService) {
    this.config = config;
    this.db = db;
  }

  async logEvent(event: Omit<AuditLog, 'id' | 'createdAt'>): Promise<void> {
    try {
      await this.db.query(`
        INSERT INTO audit_logs (
          user_id, action, resource_type, resource_id, 
          details, ip_address, user_agent, session_id, severity
        ) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
      `, [
        event.userId || null,
        event.action,
        event.resourceType || null,
        event.resourceId || null,
        event.details ? JSON.stringify(event.details) : null,
        event.ipAddress || null,
        event.userAgent || null,
        event.sessionId || null,
        event.severity || 'info',
      ]);

      // Log to console for development
      if (process.env.NODE_ENV === 'development') {
        console.log(`AUDIT [${event.severity?.toUpperCase()}]: ${event.action}`, {
          userId: event.userId,
          resourceType: event.resourceType,
          resourceId: event.resourceId,
          details: event.details,
        });
      }

      // Send alerts for critical events
      if (event.severity === 'critical' || event.severity === 'error') {
        await this.sendAlert(event);
      }
    } catch (error) {
      console.error('Failed to log audit event:', error, event);
      // Don't throw - audit logging should not break the main flow
    }
  }

  // Enhanced security event logging for password reset and other security actions
  async logSecurityEvent(event: SecurityEvent): Promise<void> {
    return this.logEvent({
      userId: event.userId || undefined,
      action: event.type,
      resourceType: 'authentication',
      details: {
        securityEventType: event.type,
        success: event.success,
        email: event.email,
        ...event.metadata,
      },
      ipAddress: event.ipAddress,
      userAgent: event.userAgent,
      severity: event.success ? 'info' : 'warning',
    });
  }

  async getAuditLogs(filters: {
    userId?: string;
    action?: string;
    startDate?: Date;
    endDate?: Date;
    limit?: number;
    offset?: number;
    severity?: string;
    resourceType?: string;
  }): Promise<AuditLog[]> {
    const conditions: string[] = [];
    const params: any[] = [];
    let paramIndex = 1;

    if (filters.userId) {
      conditions.push(`user_id = $${paramIndex}`);
      params.push(filters.userId);
      paramIndex++;
    }

    if (filters.action) {
      conditions.push(`action = $${paramIndex}`);
      params.push(filters.action);
      paramIndex++;
    }

    if (filters.severity) {
      conditions.push(`severity = $${paramIndex}`);
      params.push(filters.severity);
      paramIndex++;
    }

    if (filters.resourceType) {
      conditions.push(`resource_type = $${paramIndex}`);
      params.push(filters.resourceType);
      paramIndex++;
    }

    if (filters.startDate) {
      conditions.push(`created_at >= $${paramIndex}`);
      params.push(filters.startDate);
      paramIndex++;
    }

    if (filters.endDate) {
      conditions.push(`created_at <= $${paramIndex}`);
      params.push(filters.endDate);
      paramIndex++;
    }

    const whereClause = conditions.length > 0 ? `WHERE ${conditions.join(' AND ')}` : '';
    const limit = filters.limit || 100;
    const offset = filters.offset || 0;

    const query = `
      SELECT * FROM audit_logs 
      ${whereClause}
      ORDER BY created_at DESC 
      LIMIT $${paramIndex} OFFSET $${paramIndex + 1}
    `;

    params.push(limit, offset);

    try {
      const result = await this.db.query(query, params);
      return result.rows.map(this.mapDatabaseAuditLog);
    } catch (error) {
      console.error('Failed to get audit logs:', error);
      throw error;
    }
  }

  async getAuditStats(timeframe: 'hour' | 'day' | 'week' | 'month' = 'day'): Promise<{
    totalEvents: number;
    eventsByAction: Record<string, number>;
    eventsBySeverity: Record<string, number>;
    topUsers: Array<{ userId: string; count: number }>;
  }> {
    const timeframes = {
      hour: '1 hour',
      day: '1 day',
      week: '1 week',
      month: '1 month',
    };

    try {
      // Total events
      const totalResult = await this.db.query(`
        SELECT COUNT(*) as total 
        FROM audit_logs 
        WHERE created_at >= NOW() - INTERVAL '${timeframes[timeframe]}'
      `);

      // Events by action
      const actionResult = await this.db.query(`
        SELECT action, COUNT(*) as count 
        FROM audit_logs 
        WHERE created_at >= NOW() - INTERVAL '${timeframes[timeframe]}'
        GROUP BY action 
        ORDER BY count DESC
      `);

      // Events by severity
      const severityResult = await this.db.query(`
        SELECT severity, COUNT(*) as count 
        FROM audit_logs 
        WHERE created_at >= NOW() - INTERVAL '${timeframes[timeframe]}'
        GROUP BY severity 
        ORDER BY count DESC
      `);

      // Top users
      const usersResult = await this.db.query(`
        SELECT user_id, COUNT(*) as count 
        FROM audit_logs 
        WHERE created_at >= NOW() - INTERVAL '${timeframes[timeframe]}'
          AND user_id IS NOT NULL
        GROUP BY user_id 
        ORDER BY count DESC 
        LIMIT 10
      `);

      return {
        totalEvents: parseInt(totalResult.rows[0]?.total || '0'),
        eventsByAction: actionResult.rows.reduce((acc, row) => {
          acc[row.action] = parseInt(row.count);
          return acc;
        }, {}),
        eventsBySeverity: severityResult.rows.reduce((acc, row) => {
          acc[row.severity] = parseInt(row.count);
          return acc;
        }, {}),
        topUsers: usersResult.rows.map(row => ({
          userId: row.user_id,
          count: parseInt(row.count),
        })),
      };
    } catch (error) {
      console.error('Failed to get audit stats:', error);
      throw error;
    }
  }

  async exportAuditLogs(filters: {
    startDate: Date;
    endDate: Date;
    format?: 'json' | 'csv';
  }): Promise<string> {
    const logs = await this.getAuditLogs({
      startDate: filters.startDate,
      endDate: filters.endDate,
      limit: 10000, // Large limit for export
    });

    if (filters.format === 'csv') {
      return this.exportToCSV(logs);
    } else {
      return JSON.stringify(logs, null, 2);
    }
  }

  async cleanupOldLogs(retentionDays: number = 365): Promise<number> {
    try {
      const result = await this.db.query(`
        DELETE FROM audit_logs 
        WHERE created_at < NOW() - INTERVAL '${retentionDays} days'
      `);

      const deletedCount = result.rowCount || 0;

      if (deletedCount > 0) {
        await this.logEvent({
          action: 'audit_logs_cleanup',
          details: { 
            deletedCount, 
            retentionDays,
            cleanupDate: new Date().toISOString(),
          },
          severity: 'info',
        });
      }

      return deletedCount;
    } catch (error) {
      console.error('Failed to cleanup audit logs:', error);
      throw error;
    }
  }

  private async sendAlert(event: Omit<AuditLog, 'id' | 'createdAt'>): Promise<void> {
    // In production, this would integrate with alerting systems like:
    // - PagerDuty
    // - Slack webhooks
    // - Email notifications
    // - SIEM systems

    console.error(`SECURITY ALERT [${event.severity}]: ${event.action}`, {
      userId: event.userId,
      resourceType: event.resourceType,
      resourceId: event.resourceId,
      details: event.details,
      ipAddress: event.ipAddress,
      userAgent: event.userAgent,
      timestamp: new Date().toISOString(),
    });

    // TODO: Implement actual alerting integrations
    // Example: Send to webhook, email, or monitoring system
  }

  private mapDatabaseAuditLog(row: any): AuditLog {
    return {
      id: row.id,
      userId: row.user_id,
      action: row.action,
      resourceType: row.resource_type,
      resourceId: row.resource_id,
      details: row.details ? JSON.parse(row.details) : undefined,
      ipAddress: row.ip_address,
      userAgent: row.user_agent,
      sessionId: row.session_id,
      severity: row.severity,
      createdAt: row.created_at,
    };
  }

  private exportToCSV(logs: AuditLog[]): string {
    const headers = [
      'ID', 'User ID', 'Action', 'Resource Type', 'Resource ID',
      'IP Address', 'User Agent', 'Severity', 'Created At', 'Details'
    ];

    const rows = logs.map(log => [
      log.id,
      log.userId || '',
      log.action,
      log.resourceType || '',
      log.resourceId || '',
      log.ipAddress || '',
      log.userAgent || '',
      log.severity,
      log.createdAt.toISOString(),
      log.details ? JSON.stringify(log.details) : '',
    ]);

    const csvContent = [
      headers.join(','),
      ...rows.map(row => row.map(field => `"${String(field).replace(/"/g, '""')}"`).join(','))
    ].join('\n');

    return csvContent;
  }
}

