  async deleteOrganization(
    organizationId: string,
    deletedBy: string,
    context: { ipAddress?: string; userAgent?: string } = {}
  ): Promise<void> {
    const transaction = await this.dbService.beginTransaction();

    try {
      const organization = await this.getOrganizationById(organizationId);
      if (!organization) {
        throw new Error('Organization not found');
      }

      const now = new Date();

      // Soft delete organization
      await transaction.query(`
        UPDATE organizations 
        SET deleted_at = $1, updated_at = $2
        WHERE id = $3
      `, [now, now, organizationId]);

      // Soft delete all teams in organization
      await transaction.query(`
        UPDATE teams 
        SET deleted_at = $1, updated_at = $2
        WHERE organization_id = $3 AND deleted_at IS NULL
      `, [now, now, organizationId]);

      // Remove all team memberships
      await transaction.query(`
        DELETE FROM team_members 
        WHERE team_id IN (
          SELECT id FROM teams WHERE organization_id = $1
        )
      `, [organizationId]);

      // Remove organization-specific roles
      await transaction.query(`
        DELETE FROM user_roles 
        WHERE role_id IN (
          SELECT id FROM roles WHERE organization_id = $1
        )
      `, [organizationId]);

      await transaction.query(`
        DELETE FROM permissions 
        WHERE role_id IN (
          SELECT id FROM roles WHERE organization_id = $1
        )
      `, [organizationId]);

      await transaction.query(`
        DELETE FROM roles 
        WHERE organization_id = $1
      `, [organizationId]);

      await transaction.commit();

      // Log organization deletion
      await this.auditService.logEvent({
        userId: deletedBy,
        action: 'organization_deleted',
        resourceType: 'organization',
        resourceId: organizationId,
        details: {
          organizationName: organization.name,
          slug: organization.slug,
        },
        ipAddress: context.ipAddress,
        userAgent: context.userAgent,
        severity: 'warning',
      });
    } catch (error) {
      await transaction.rollback();
      throw error;
    }
  }

