  /**
   * Store user interaction record
   */
  storeUserInteraction(interaction: Partial<UserInteraction>): UserInteraction {
    const stmt = this.db.prepare(`
      INSERT INTO user_interactions (
        interaction_id, session_id, user_id, interaction_type, timestamp,
        component, element_id, graph_id, node_id, canvas_x, canvas_y,
        viewport_x, viewport_y, metadata
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      RETURNING *
    `);

    const result = stmt.get(
      interaction.interactionId || uuidv4(),
      interaction.sessionId,
      interaction.userId,
      interaction.interactionType,
      interaction.timestamp,
      interaction.component,
      interaction.elementId,
      interaction.graphId,
      interaction.nodeId,
      interaction.canvasX,
      interaction.canvasY,
      interaction.viewportX,
      interaction.viewportY,
      interaction.metadata || '{}'
    );

    return result as UserInteraction;
  }

  /**
   * Get analytics summary for a time period
   */
  getAnalyticsSummary(filters: AnalyticsFilters): AnalyticsSummary {
    const whereClause = this.buildWhereClause(filters);

    // Get basic metrics
    const basicMetrics = this.db.prepare(`
      SELECT 
        COUNT(*) as totalEvents,
        COUNT(DISTINCT user_id) as uniqueUsers,
        COUNT(DISTINCT session_id) as uniqueSessions
      FROM analytics_events 
      ${whereClause}
    `).get(this.buildWhereParams(filters));

    // Get execution metrics
    const execMetrics = this.db.prepare(`
      SELECT 
        COUNT(*) as totalGraphExecutions,
        AVG(execution_time_ms) as averageExecutionTime,
        (SUM(CASE WHEN success = 1 THEN 1 ELSE 0 END) * 100.0 / COUNT(*)) as successRate
      FROM graph_executions 
      WHERE start_time >= ? AND start_time <= ?
    `).get(filters.startTime || 0, filters.endTime || Date.now());

    // Get node execution count
    const nodeMetrics = this.db.prepare(`
      SELECT COUNT(*) as totalNodeExecutions
      FROM node_executions 
      WHERE start_time >= ? AND start_time <= ?
    `).get(filters.startTime || 0, filters.endTime || Date.now());

    // Get token usage metrics
    const tokenMetrics = this.db.prepare(`
      SELECT 
        COALESCE(SUM(total_tokens), 0) as totalTokenUsage,
        COALESCE(SUM(estimated_cost_usd), 0) as totalCost
      FROM token_usage 
      WHERE request_start >= ? AND request_start <= ?
    `).get(filters.startTime || 0, filters.endTime || Date.now());

    // Get top node types
    const topNodeTypes = this.db.prepare(`
      SELECT 
        node_type as type, 
        COUNT(*) as count,
        AVG(execution_time_ms) as avgTime
      FROM node_executions 
      WHERE start_time >= ? AND start_time <= ?
      GROUP BY node_type 
      ORDER BY count DESC 
      LIMIT 10
    `).all(filters.startTime || 0, filters.endTime || Date.now());

    // Get provider usage
    const providerUsage = this.db.prepare(`
      SELECT 
        provider,
        SUM(total_tokens) as tokens,
        SUM(estimated_cost_usd) as cost
      FROM token_usage 
      WHERE request_start >= ? AND request_start <= ?
      GROUP BY provider 
      ORDER BY cost DESC
    `).all(filters.startTime || 0, filters.endTime || Date.now());

    // Get error breakdown
    const errorBreakdown = this.db.prepare(`
      SELECT 
        event_type as type,
        COUNT(*) as count
      FROM analytics_events 
      WHERE event_type LIKE '%error%' 
        AND timestamp >= ? AND timestamp <= ?
      GROUP BY event_type 
      ORDER BY count DESC
    `).all(filters.startTime || 0, filters.endTime || Date.now());

    return {
      totalEvents: basicMetrics.totalEvents || 0,
      uniqueUsers: basicMetrics.uniqueUsers || 0,
      uniqueSessions: basicMetrics.uniqueSessions || 0,
      totalGraphExecutions: execMetrics.totalGraphExecutions || 0,
      totalNodeExecutions: nodeMetrics.totalNodeExecutions || 0,
      totalTokenUsage: tokenMetrics.totalTokenUsage || 0,
      totalCost: tokenMetrics.totalCost || 0,
      averageExecutionTime: execMetrics.averageExecutionTime || 0,
      successRate: execMetrics.successRate || 100,
      topGraphTypes: [], // Would need graph type tracking
      topNodeTypes: topNodeTypes || [],
      providerUsage: providerUsage || [],
      errorBreakdown: errorBreakdown || []
    };
  }

  /**
   * Get time-series data for analytics dashboard
   */
  getTimeSeriesData(
    metric: string, 
    granularity: 'hour' | 'day', 
    filters: AnalyticsFilters
  ): Array<{ timestamp: number; value: number }> {
    let query: string;
    const timeField = granularity === 'hour' ? 'hour_bucket' : 'date_bucket';
    const table = granularity === 'hour' ? 'analytics_hourly' : 'analytics_daily';

    switch (metric) {
      case 'executions':
        query = `
          SELECT ${timeField} as timestamp, graphs_executed as value
          FROM ${table}
          WHERE ${timeField} >= ? AND ${timeField} <= ?
          ORDER BY ${timeField}
        `;
        break;

      case 'tokens':
        query = `
          SELECT ${timeField} as timestamp, total_token_usage as value
          FROM ${table}
          WHERE ${timeField} >= ? AND ${timeField} <= ?
          ORDER BY ${timeField}
        `;
        break;

      case 'cost':
        query = `
          SELECT ${timeField} as timestamp, total_cost_usd as value
          FROM ${table}
          WHERE ${timeField} >= ? AND ${timeField} <= ?
          ORDER BY ${timeField}
        `;
        break;

      case 'errors':
        query = `
          SELECT ${timeField} as timestamp, error_count as value
          FROM ${table}
          WHERE ${timeField} >= ? AND ${timeField} <= ?
          ORDER BY ${timeField}
        `;
        break;

      default:
        throw new Error(`Unknown metric: ${metric}`);
    }

    return this.db.prepare(query).all(
      filters.startTime || 0, 
      filters.endTime || Date.now()
    );
  }

  /**
   * Get heat map data for canvas interactions
   */
  getHeatMapData(filters: AnalyticsFilters): Array<{ x: number; y: number; intensity: number }> {
    const whereClause = this.buildWhereClause(filters, 'user_interactions');

    const heatMapData = this.db.prepare(`
      SELECT 
        ROUND(canvas_x / 50) * 50 as x,
        ROUND(canvas_y / 50) * 50 as y,
        COUNT(*) as intensity
      FROM user_interactions 
      ${whereClause}
        AND canvas_x IS NOT NULL 
        AND canvas_y IS NOT NULL
      GROUP BY x, y
      HAVING intensity > 1
      ORDER BY intensity DESC
      LIMIT 1000
    `).all(this.buildWhereParams(filters));

    return heatMapData;
  }

  /**
   * Update aggregation tables (should be run periodically)
   */
  updateAggregations(): void {
    // Update hourly aggregations
    this.db.prepare(`
      INSERT OR REPLACE INTO analytics_hourly (
        hour_bucket, user_id, organization_id, total_events, unique_sessions,
        graphs_executed, nodes_executed, avg_execution_time_ms, p95_execution_time_ms,
        total_token_usage, total_cost_usd, success_rate, error_count
      )
      SELECT 
        datetime(timestamp / 1000, 'unixepoch', 'start of hour') as hour_bucket,
        user_id,
        organization_id,
        COUNT(*) as total_events,
        COUNT(DISTINCT session_id) as unique_sessions,
        0 as graphs_executed,
        0 as nodes_executed,
        0 as avg_execution_time_ms,
        0 as p95_execution_time_ms,
        0 as total_token_usage,
        0 as total_cost_usd,
        100.0 as success_rate,
        SUM(CASE WHEN event_type LIKE '%error%' THEN 1 ELSE 0 END) as error_count
      FROM analytics_events
      WHERE timestamp >= (strftime('%s', 'now', '-24 hours') * 1000)
      GROUP BY hour_bucket, user_id, organization_id
    `).run();

    // Update daily aggregations
    this.db.prepare(`
      INSERT OR REPLACE INTO analytics_daily (
        date_bucket, user_id, organization_id, total_events, unique_sessions,
        active_users, graphs_executed, nodes_executed, avg_execution_time_ms,
        p95_execution_time_ms, total_token_usage, total_cost_usd, success_rate, error_count
      )
      SELECT 
        date(timestamp / 1000, 'unixepoch') as date_bucket,
        user_id,
        organization_id,
        COUNT(*) as total_events,
        COUNT(DISTINCT session_id) as unique_sessions,
        COUNT(DISTINCT user_id) as active_users,
        0 as graphs_executed,
        0 as nodes_executed,
        0 as avg_execution_time_ms,
        0 as p95_execution_time_ms,
        0 as total_token_usage,
        0 as total_cost_usd,
        100.0 as success_rate,
        SUM(CASE WHEN event_type LIKE '%error%' THEN 1 ELSE 0 END) as error_count
      FROM analytics_events
      WHERE timestamp >= (strftime('%s', 'now', '-30 days') * 1000)
      GROUP BY date_bucket, user_id, organization_id
    `).run();

    console.log('Analytics aggregations updated');
  }

  /**
   * Get events by filter criteria
   */
  getEvents(filters: AnalyticsFilters): AnalyticsEvent[] {
    const whereClause = this.buildWhereClause(filters);
    const params = this.buildWhereParams(filters);

    let limitClause = '';
    if (filters.limit) {
      limitClause = `LIMIT ${filters.limit}`;
      if (filters.offset) {
        limitClause += ` OFFSET ${filters.offset}`;
      }
    }

    const events = this.db.prepare(`
      SELECT * FROM analytics_events 
      ${whereClause}
      ORDER BY timestamp DESC
      ${limitClause}
    `).all(params);

    return events.map(row => ({
      id: row.event_id,
      type: row.event_type,
      timestamp: row.timestamp,
      sessionId: row.session_id,
      userId: row.user_id,
      organizationId: row.organization_id,
      metadata: JSON.parse(row.metadata)
    }));
  }

  /**
   * Delete old analytics data beyond retention period
   */
  cleanupOldData(retentionDays: number = 30): number {
    const cutoffTime = Date.now() - (retentionDays * 24 * 60 * 60 * 1000);

    const tables = [
      'analytics_events',
      'graph_executions', 
      'node_executions',
      'token_usage',
      'user_interactions',
      'performance_metrics',
      'error_analytics'
    ];

    let totalDeleted = 0;

    tables.forEach(table => {
      const timeField = table === 'analytics_events' ? 'timestamp' : 
                       table.includes('executions') ? 'start_time' :
                       table === 'token_usage' ? 'request_start' :
                       table === 'user_interactions' ? 'timestamp' :
                       table === 'performance_metrics' ? 'timestamp' :
                       'timestamp';

      const result = this.db.prepare(`
        DELETE FROM ${table} WHERE ${timeField} < ?
      `).run(cutoffTime);

      totalDeleted += result.changes;
    });

    console.log(`Cleaned up ${totalDeleted} old analytics records`);
    return totalDeleted;
  }

  /**
   * Build WHERE clause for filtering
   */
  private buildWhereClause(filters: AnalyticsFilters, tableName = 'analytics_events'): string {
    const conditions: string[] = [];

    if (filters.startTime !== undefined) {
      const timeField = tableName === 'user_interactions' ? 'timestamp' : 
                       tableName.includes('executions') ? 'start_time' :
                       tableName === 'token_usage' ? 'request_start' :
                       'timestamp';
      conditions.push(`${timeField} >= ?`);
    }

    if (filters.endTime !== undefined) {
      const timeField = tableName === 'user_interactions' ? 'timestamp' : 
                       tableName.includes('executions') ? 'start_time' :
                       tableName === 'token_usage' ? 'request_start' :
                       'timestamp';
      conditions.push(`${timeField} <= ?`);
    }

    if (filters.userId !== undefined) {
      conditions.push('user_id = ?');
    }

    if (filters.sessionId !== undefined) {
      conditions.push('session_id = ?');
    }

    if (filters.eventTypes && filters.eventTypes.length > 0) {
      const placeholders = filters.eventTypes.map(() => '?').join(', ');
      conditions.push(`event_type IN (${placeholders})`);
    }

    return conditions.length > 0 ? `WHERE ${conditions.join(' AND ')}` : '';
  }

  /**
   * Build parameters array for WHERE clause
   */
  private buildWhereParams(filters: AnalyticsFilters): any[] {
    const params: any[] = [];

    if (filters.startTime !== undefined) params.push(filters.startTime);
    if (filters.endTime !== undefined) params.push(filters.endTime);
    if (filters.userId !== undefined) params.push(filters.userId);
    if (filters.sessionId !== undefined) params.push(filters.sessionId);
    if (filters.eventTypes && filters.eventTypes.length > 0) {
      params.push(...filters.eventTypes);
    }

    return params;
  }

  /**
   * Get event category from event type
   */
  private getEventCategory(eventType: AnalyticsEventType): string {
    if (eventType.includes('execution')) return 'execution';
    if (eventType.includes('user') || eventType.includes('interaction')) return 'user';
    if (eventType.includes('performance') || eventType.includes('token')) return 'performance';
    if (eventType.includes('error')) return 'error';
    return 'general';
  }

  /**
   * Get event severity from event type
   */
  private getEventSeverity(eventType: AnalyticsEventType): string {
    if (eventType.includes('error')) return 'error';
    if (eventType.includes('warning')) return 'warning';
    return 'info';
  }
}

// Graph Comparison Data Access Object
// Story 9.3.2 - Visual Diff Tool

import { Database } from 'better-sqlite3';
import {
  GraphComparison,
  GraphComparisonSnapshot,
  VisualDiffSession,
  NodeMatchResult,
  EdgeMatchResult,
  CompareVersionsRequest,
  CreateDiffSessionRequest,
  UpdateDiffSessionRequest,
  DetailedComparison
} from './comparison-models.js';

export interface PaginationOptions {
  page?: number;
  limit?: number;
}

export interface ComparisonFilter {
  graph_id?: string;
  source_version_id?: string;
  target_version_id?: string;
  comparison_type?: string;
  min_similarity?: number;
  max_similarity?: number;
  created_after?: Date;
  created_before?: Date;
  created_by?: string;
}

export interface PaginatedResult<T> {
  data: T[];
  total: number;
  page: number;
  limit: number;
  total_pages: number;
}

export class ComparisonDAO {
  constructor(private db: Database) {}

  // Snapshot Management
  async createSnapshot(snapshot: Omit<GraphComparisonSnapshot, 'id' | 'created_at'>): Promise<GraphComparisonSnapshot> {
    const id = crypto.randomUUID();
    const now = new Date();

    const stmt = this.db.prepare(`
      INSERT INTO graph_comparison_snapshots (
        id, graph_id, version_id, nodes_hash, edges_hash, structure_hash,
        nodes_index, edges_index, properties_index, node_count, edge_count, complexity_score
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `);

    stmt.run(
      id,
      snapshot.graph_id,
      snapshot.version_id,
      snapshot.nodes_hash,
      snapshot.edges_hash,
      snapshot.structure_hash,
      JSON.stringify(snapshot.nodes_index),
      JSON.stringify(snapshot.edges_index),
      JSON.stringify(snapshot.properties_index),
      snapshot.node_count,
      snapshot.edge_count,
      snapshot.complexity_score
    );

    return { ...snapshot, id, created_at: now };
  }

  async getSnapshot(versionId: string): Promise<GraphComparisonSnapshot | null> {
    const stmt = this.db.prepare(`
      SELECT * FROM graph_comparison_snapshots 
      WHERE version_id = ?
    `);

    const row = stmt.get(versionId) as any;
    if (!row) return null;

    return {
      ...row,
      nodes_index: JSON.parse(row.nodes_index),
      edges_index: JSON.parse(row.edges_index),
      properties_index: JSON.parse(row.properties_index),
      created_at: new Date(row.created_at)
    };
  }

  async deleteSnapshotsForGraph(graphId: string): Promise<number> {
    const stmt = this.db.prepare(`
      DELETE FROM graph_comparison_snapshots 
      WHERE graph_id = ?
    `);

    const result = stmt.run(graphId);
    return result.changes;
  }

  // Comparison Management
  async createComparison(comparison: Omit<GraphComparison, 'id' | 'created_at'>): Promise<GraphComparison> {
    const id = crypto.randomUUID();
    const now = new Date();

    const stmt = this.db.prepare(`
      INSERT INTO graph_comparisons (
        id, source_version_id, target_version_id, comparison_type, similarity_score,
        changes_summary, added_nodes, removed_nodes, modified_nodes,
        added_edges, removed_edges, modified_edges,
        node_diffs, edge_diffs, property_diffs, comparison_duration_ms, created_by
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `);

    stmt.run(
      id,
      comparison.source_version_id,
      comparison.target_version_id,
      comparison.comparison_type,
      comparison.similarity_score,
      JSON.stringify(comparison.changes_summary),
      JSON.stringify(comparison.added_nodes),
      JSON.stringify(comparison.removed_nodes),
      JSON.stringify(comparison.modified_nodes),
      JSON.stringify(comparison.added_edges),
      JSON.stringify(comparison.removed_edges),
      JSON.stringify(comparison.modified_edges),
      JSON.stringify(comparison.node_diffs),
      JSON.stringify(comparison.edge_diffs),
      JSON.stringify(comparison.property_diffs),
      comparison.comparison_duration_ms,
      comparison.created_by
    );

    return { ...comparison, id, created_at: now };
  }

  async getComparison(id: string): Promise<GraphComparison | null> {
    const stmt = this.db.prepare(`
      SELECT * FROM graph_comparisons 
      WHERE id = ?
    `);

    const row = stmt.get(id) as any;
    if (!row) return null;

    return this.parseComparisonRow(row);
  }

  async getComparisonByVersions(
    sourceVersionId: string,
    targetVersionId: string,
    comparisonType?: string
  ): Promise<GraphComparison | null> {
    let query = `
      SELECT * FROM graph_comparisons 
      WHERE source_version_id = ? AND target_version_id = ?
    `;
    const params: any[] = [sourceVersionId, targetVersionId];

    if (comparisonType) {
      query += ` AND comparison_type = ?`;
      params.push(comparisonType);
    }

    query += ` ORDER BY created_at DESC LIMIT 1`;

    const stmt = this.db.prepare(query);
    const row = stmt.get(...params) as any;

    if (!row) return null;
    return this.parseComparisonRow(row);
  }

  async getComparisons(
    filter: ComparisonFilter = {},
    pagination: PaginationOptions = {}
  ): Promise<PaginatedResult<GraphComparison>> {
    const { page = 1, limit = 50 } = pagination;
    const offset = (page - 1) * limit;

    const whereConditions: string[] = [];
    const params: any[] = [];

    if (filter.source_version_id) {
      whereConditions.push('source_version_id = ?');
      params.push(filter.source_version_id);
    }

    if (filter.target_version_id) {
      whereConditions.push('target_version_id = ?');
      params.push(filter.target_version_id);
    }

    if (filter.comparison_type) {
      whereConditions.push('comparison_type = ?');
      params.push(filter.comparison_type);
    }

    if (filter.min_similarity !== undefined) {
      whereConditions.push('similarity_score >= ?');
      params.push(filter.min_similarity);
    }

    if (filter.max_similarity !== undefined) {
      whereConditions.push('similarity_score <= ?');
      params.push(filter.max_similarity);
    }

    if (filter.created_after) {
      whereConditions.push('created_at >= ?');
      params.push(filter.created_after.toISOString());
    }

    if (filter.created_before) {
      whereConditions.push('created_at <= ?');
      params.push(filter.created_before.toISOString());
    }

    if (filter.created_by) {
      whereConditions.push('created_by = ?');
      params.push(filter.created_by);
    }

    const whereClause = whereConditions.length > 0 ? `WHERE ${whereConditions.join(' AND ')}` : '';

    // Count total
    const countStmt = this.db.prepare(`
      SELECT COUNT(*) as total FROM graph_comparisons ${whereClause}
    `);
    const { total } = countStmt.get(...params) as any;

    // Get paginated data
    const dataStmt = this.db.prepare(`
      SELECT * FROM graph_comparisons ${whereClause}
      ORDER BY created_at DESC
      LIMIT ? OFFSET ?
    `);
    const rows = dataStmt.all(...params, limit, offset) as any[];

    const data = rows.map(row => this.parseComparisonRow(row));

    return {
      data,
      total,
      page,
      limit,
      total_pages: Math.ceil(total / limit)
    };
  }

  async deleteComparison(id: string): Promise<boolean> {
    const stmt = this.db.prepare(`DELETE FROM graph_comparisons WHERE id = ?`);
    const result = stmt.run(id);
    return result.changes > 0;
  }

  // Node Match Results
  async createNodeMatchResults(comparisonId: string, matches: Omit<NodeMatchResult, 'id' | 'comparison_id' | 'created_at'>[]): Promise<NodeMatchResult[]> {
    const stmt = this.db.prepare(`
      INSERT INTO node_match_results (
        id, comparison_id, source_node_id, target_node_id, match_type,
        confidence_score, match_criteria, property_changes, position_changed, visual_changes
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `);

    const results: NodeMatchResult[] = [];
    const now = new Date();

    for (const match of matches) {
      const id = crypto.randomUUID();
      stmt.run(
        id,
        comparisonId,
        match.source_node_id,
        match.target_node_id,
        match.match_type,
        match.confidence_score,
        JSON.stringify(match.match_criteria),
        JSON.stringify(match.property_changes),
        match.position_changed,
        JSON.stringify(match.visual_changes)
      );

      results.push({ ...match, id, comparison_id: comparisonId, created_at: now });
    }

    return results;
  }

  async getNodeMatchResults(comparisonId: string): Promise<NodeMatchResult[]> {
    const stmt = this.db.prepare(`
      SELECT * FROM node_match_results 
      WHERE comparison_id = ?
      ORDER BY created_at
    `);

    const rows = stmt.all(comparisonId) as any[];
    return rows.map(row => ({
      ...row,
      match_criteria: JSON.parse(row.match_criteria),
      property_changes: JSON.parse(row.property_changes),
      visual_changes: JSON.parse(row.visual_changes),
      created_at: new Date(row.created_at)
    }));
  }

