  async getEdgeMatchResults(comparisonId: string): Promise<EdgeMatchResult[]> {
    const stmt = this.db.prepare(`
      SELECT * FROM edge_match_results 
      WHERE comparison_id = ?
      ORDER BY created_at
    `);

    const rows = stmt.all(comparisonId) as any[];
