import Database from 'better-sqlite3';
import { readFileSync, readdirSync } from 'fs';
import { join } from 'path';

// Database instance
let db: Database.Database | null = null;

/**
 * Initialize database connection and create tables
 */
export function initDatabase(databasePath: string = 'corrections.db'): Database.Database {
  if (db) {
    return db;
  }

  // Create database connection
  db = new Database(databasePath);

  // Enable WAL mode for better performance
  db.pragma('journal_mode = WAL');
  db.pragma('synchronous = NORMAL');
  db.pragma('cache_size = 10000');
  db.pragma('temp_store = memory');

  // Enable foreign key constraints
  db.pragma('foreign_keys = ON');

  // Read and execute schema
  const schemaPath = join(__dirname, 'schema.sql');
  const schema = readFileSync(schemaPath, 'utf8');

  // Execute schema in a transaction
  db.exec(schema);

  console.log('Database initialized successfully');
  return db;
}

/**
 * Get database instance
 */
export function getDatabase(): Database.Database {
  if (!db) {
    throw new Error('Database not initialized. Call initDatabase() first.');
  }
  return db;
}

/**
 * Close database connection
 */
export function closeDatabase(): void {
  if (db) {
    db.close();
    db = null;
    console.log('Database connection closed');
  }
}

/**
 * Health check for database
 */
export function healthCheck(): boolean {
  try {
    const db = getDatabase();
    const result = db.prepare('SELECT 1 as health').get();
    return result?.health === 1;
  } catch (error) {
    console.error('Database health check failed:', error);
    return false;
  }
}

/**
 * Get database statistics
 */
export function getDatabaseStats() {
  try {
    const db = getDatabase();

    const stats = {
      totalRules: db.prepare('SELECT COUNT(*) as count FROM correction_rules').get(),
      activeRules: db.prepare('SELECT COUNT(*) as count FROM correction_rules WHERE is_active = 1').get(),
      totalHistory: db.prepare('SELECT COUNT(*) as count FROM correction_rule_history').get(),
      totalStatistics: db.prepare('SELECT COUNT(*) as count FROM correction_statistics').get(),
      totalSets: db.prepare('SELECT COUNT(*) as count FROM correction_sets').get(),
      databaseSize: db.prepare('SELECT page_count * page_size as size FROM pragma_page_count(), pragma_page_size()').get(),
    };

    return stats;
  } catch (error) {
    console.error('Failed to get database stats:', error);
    return null;
  }
}

/**
 * Backup database
 */
export function backupDatabase(backupPath: string): boolean {
  try {
    const db = getDatabase();
    db.backup(backupPath);
    console.log(`Database backed up to ${backupPath}`);
    return true;
  } catch (error) {
    console.error('Database backup failed:', error);
    return false;
  }
}

/**
 * Vacuum database (optimize)
 */
export function vacuumDatabase(): boolean {
  try {
    const db = getDatabase();
    db.exec('VACUUM');
    console.log('Database vacuumed successfully');
    return true;
  } catch (error) {
    console.error('Database vacuum failed:', error);
    return false;
  }
}

/**
 * Run database migrations
 */
export function runMigrations(): boolean {
  try {
    const db = getDatabase();

    // Create migrations table if it doesn't exist
    db.exec(`
      CREATE TABLE IF NOT EXISTS migrations (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        version VARCHAR(50) NOT NULL,
        applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        UNIQUE(version)
      )
    `);

    // Get list of applied migrations
    const appliedMigrations = db.prepare('SELECT version FROM migrations').all() as { version: string }[];
    const appliedVersions = new Set(appliedMigrations.map(m => m.version));

    console.log('Applied migrations:', appliedVersions.size ? Array.from(appliedVersions).join(', ') : 'none');

    // Get all migration files
    const migrationsDir = join(__dirname, 'migrations');
    let migrationFiles: string[] = [];

    try {
      migrationFiles = readdirSync(migrationsDir)
        .filter(file => file.endsWith('.sql'))
        .sort(); // Sort to ensure migrations run in order
    } catch (error) {
      console.log('No migrations directory found, skipping migrations');
      return true;
    }

    // Run migrations that haven't been applied
    let appliedCount = 0;
    for (const file of migrationFiles) {
      const version = file.replace('.sql', '');

      if (!appliedVersions.has(version)) {
        console.log(`Applying migration: ${version}...`);
        const migrationPath = join(migrationsDir, file);

        try {
          const migrationSQL = readFileSync(migrationPath, 'utf8');

          // Run migration in a transaction
          const transaction = db.transaction(() => {
            // Execute all statements in the migration file
            const statements = migrationSQL
              .split(';')
              .map(s => s.trim())
              .filter(s => s.length > 0);

            for (const statement of statements) {
              db.exec(statement + ';');
            }

            // Record migration as applied
            db.prepare('INSERT INTO migrations (version) VALUES (?)').run(version);
          });

          transaction();
          console.log(`Migration ${version} applied successfully`);
          appliedCount++;
        } catch (migrationError) {
          console.error(`Failed to apply migration ${version}:`, migrationError);
          // Continue with other migrations but log the error
        }
      }
    }

    if (appliedCount > 0) {
      console.log(`Applied ${appliedCount} migration(s)`);
    } else {
      console.log('All migrations are up to date');
    }

    return true;
  } catch (error) {
    console.error('Migration runner failed:', error);
    return false;
  }
}

// Graceful shutdown
process.on('SIGINT', closeDatabase);
process.on('SIGTERM', closeDatabase);
process.on('beforeExit', closeDatabase);

import { Database } from 'better-sqlite3';
import { v4 as uuidv4 } from 'uuid';
import { getDatabase } from './connection';
import {
  CorrectionRule,
  CorrectionRuleHistory,
  CorrectionStatistics,
  CorrectionSet,
  CorrectionSetRule,
  CreateCorrectionRuleInput,
  UpdateCorrectionRuleInput,
  CreateCorrectionSetInput,
  RuleUsageStats,
  PerformanceMetrics,
  WorkflowStateHistory,
  WorkflowNotification,
} from './models';

/**
 * Data Access Object for Correction Rules
 */
export class CorrectionsDAO {
  private db: Database;

  constructor() {
    this.db = getDatabase();
  }

  // ========== CORRECTION RULES ==========

  /**
   * Create a new correction rule
   */
  createRule(input: CreateCorrectionRuleInput): CorrectionRule {
    const uuid = uuidv4();
    const now = new Date().toISOString();

    const stmt = this.db.prepare(`
      INSERT INTO correction_rules (
        uuid, name, description, find_pattern, replace_with, is_regex, is_active, priority,
        user_id, project_id, scope, created_by, updated_by,
        workflow_state, suggested_by, suggestion_reason, suggestion_date, category, tags,
        usage_count, effectiveness_score
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `);

    const result = stmt.run(
      uuid,
      input.name,
      input.description || null,
      input.find_pattern,
      input.replace_with,
      input.is_regex ? 1 : 0,
      input.is_active ? 1 : 0,
      input.priority,
      input.user_id,
      input.project_id || null,
      input.scope,
      input.user_id,
      input.user_id,
      input.workflow_state || 'draft',
      input.suggested_by || null,
      input.suggestion_reason || null,
      input.suggested_by ? now : null,
      input.category || null,
      input.tags ? JSON.stringify(input.tags) : null,
      0, // usage_count starts at 0
      0.0 // effectiveness_score starts at 0
    );

    const rule = this.getRuleById(result.lastInsertRowid as number);
    if (!rule) {
      throw new Error('Failed to create correction rule');
    }

    // Create history entry
    this.createHistoryEntry(rule, 'created', 'Rule created', input.user_id);

    return rule;
  }

  /**
   * Get all correction rules for a user
   */
  getRulesByUser(userId: number, includeInactive: boolean = false): CorrectionRule[] {
    const whereClause = includeInactive 
      ? 'WHERE user_id = ?'
      : 'WHERE user_id = ? AND is_active = 1';

    const stmt = this.db.prepare(`
      SELECT * FROM correction_rules 
      ${whereClause}
      ORDER BY priority ASC, created_at ASC
    `);

    return stmt.all(userId) as CorrectionRule[];
  }

  /**
   * Get a correction rule by ID
   */
  getRuleById(id: number): CorrectionRule | null {
    const stmt = this.db.prepare('SELECT * FROM correction_rules WHERE id = ?');
    const result = stmt.get(id) as CorrectionRule | undefined;
    return result || null;
  }

  /**
   * Get a correction rule by UUID
   */
  getRuleByUuid(uuid: string): CorrectionRule | null {
    const stmt = this.db.prepare('SELECT * FROM correction_rules WHERE uuid = ?');
    const result = stmt.get(uuid) as CorrectionRule | undefined;
    return result || null;
  }

  /**
   * Update a correction rule
   */
  updateRule(id: number, input: UpdateCorrectionRuleInput, updatedBy: number): CorrectionRule | null {
    const currentRule = this.getRuleById(id);
    if (!currentRule) {
      return null;
    }

    const updates: string[] = [];
    const values: any[] = [];

    // Build dynamic update query
    Object.entries(input).forEach(([key, value]) => {
      if (value !== undefined) {
        if (key === 'is_regex' || key === 'is_active') {
          updates.push(`${key} = ?`);
          values.push(value ? 1 : 0);
        } else if (key === 'tags') {
          updates.push(`${key} = ?`);
          values.push(JSON.stringify(value));
        } else {
          updates.push(`${key} = ?`);
          values.push(value);
        }
      }
    });

    if (updates.length === 0) {
      return currentRule;
    }

    // Add metadata updates
    updates.push('updated_by = ?', 'updated_at = CURRENT_TIMESTAMP');
    values.push(updatedBy);
    values.push(id); // For WHERE clause

    const stmt = this.db.prepare(`
      UPDATE correction_rules 
      SET ${updates.join(', ')}
      WHERE id = ?
    `);

    stmt.run(...values);

    const updatedRule = this.getRuleById(id);
    if (updatedRule) {
      // Create history entry
      this.createHistoryEntry(updatedRule, 'updated', 'Rule updated', updatedBy);
    }

    return updatedRule;
  }

  /**
   * Delete a correction rule
   */
  deleteRule(id: number, deletedBy: number): boolean {
    const rule = this.getRuleById(id);
    if (!rule) {
      return false;
    }

    // Create history entry before deletion
    this.createHistoryEntry(rule, 'deleted', 'Rule deleted', deletedBy);

    const stmt = this.db.prepare('DELETE FROM correction_rules WHERE id = ?');
    const result = stmt.run(id);

    return result.changes > 0;
  }

  /**
   * Toggle rule active state
   */
  toggleRuleActive(id: number, updatedBy: number): CorrectionRule | null {
    const rule = this.getRuleById(id);
    if (!rule) {
      return null;
    }

    const newActiveState = !rule.is_active;
    const stmt = this.db.prepare(`
      UPDATE correction_rules 
      SET is_active = ?, updated_by = ?, updated_at = CURRENT_TIMESTAMP
      WHERE id = ?
    `);

    stmt.run(newActiveState ? 1 : 0, updatedBy, id);

    const updatedRule = this.getRuleById(id);
    if (updatedRule) {
      const changeType = newActiveState ? 'activated' : 'deactivated';
      this.createHistoryEntry(updatedRule, changeType, `Rule ${changeType}`, updatedBy);
    }

    return updatedRule;
  }

  /**
   * Reorder rules
   */
  reorderRules(ruleIds: number[], userId: number): boolean {
    const transaction = this.db.transaction((ids: number[]) => {
      ids.forEach((id, index) => {
        const stmt = this.db.prepare(`
          UPDATE correction_rules 
          SET priority = ?, updated_by = ?, updated_at = CURRENT_TIMESTAMP
          WHERE id = ? AND user_id = ?
        `);
        stmt.run(index, userId, id, userId);
      });
    });

    try {
      transaction(ruleIds);
      return true;
    } catch (error) {
      console.error('Failed to reorder rules:', error);
      return false;
    }
  }

  /**
   * Search rules by pattern or name
   */
  searchRules(query: string, userId: number): CorrectionRule[] {
    const stmt = this.db.prepare(`
      SELECT * FROM correction_rules 
      WHERE user_id = ? AND (
        name LIKE ? OR 
        description LIKE ? OR 
        find_pattern LIKE ?
      )
      ORDER BY priority ASC
    `);

    const searchTerm = `%${query}%`;
    return stmt.all(userId, searchTerm, searchTerm, searchTerm) as CorrectionRule[];
  }

  // ========== WORKFLOW MANAGEMENT ==========

  /**
   * Get rules by workflow state
   */
  getRulesByWorkflowState(userId: number, state: 'draft' | 'published' | 'deprecated'): CorrectionRule[] {
    const stmt = this.db.prepare(`
      SELECT * FROM correction_rules 
      WHERE user_id = ? AND workflow_state = ?
      ORDER BY priority ASC, created_at DESC
    `);

    return stmt.all(userId, state) as CorrectionRule[];
  }

  /**
   * Approve a draft rule
   */
  approveRule(ruleId: number, approvedBy: number, comment?: string): CorrectionRule | null {
    const rule = this.getRuleById(ruleId);
    if (!rule || rule.workflow_state !== 'draft') {
      return null;
    }

    const now = new Date().toISOString();
    const stmt = this.db.prepare(`
      UPDATE correction_rules 
      SET workflow_state = 'published', 
          approved_by = ?, 
          approved_at = ?,
          is_active = 1,
          updated_by = ?, 
          updated_at = CURRENT_TIMESTAMP
      WHERE id = ?
    `);

    stmt.run(approvedBy, now, approvedBy, ruleId);

    const updatedRule = this.getRuleById(ruleId);
    if (updatedRule) {
      // Create workflow history entry
      this.createWorkflowHistoryEntry(ruleId, 'draft', 'published', approvedBy, comment || 'Rule approved');

      // Create history entry
      this.createHistoryEntry(updatedRule, 'updated', 'Rule approved and published', approvedBy);

      // Create notification
      this.createWorkflowNotification(
        rule.user_id,
        ruleId,
        'rule_approved',
        'Rule Approved',
        `Your rule "${rule.name}" has been approved and published.`
      );
    }

    return updatedRule;
  }

  /**
   * Deprecate a published rule
   */
  deprecateRule(ruleId: number, deprecatedBy: number, reason: string): CorrectionRule | null {
    const rule = this.getRuleById(ruleId);
    if (!rule || rule.workflow_state !== 'published') {
      return null;
    }

    const now = new Date().toISOString();
    const stmt = this.db.prepare(`
      UPDATE correction_rules 
      SET workflow_state = 'deprecated', 
          deprecated_at = ?,
          deprecation_reason = ?,
          is_active = 0,
          updated_by = ?, 
          updated_at = CURRENT_TIMESTAMP
      WHERE id = ?
    `);

    stmt.run(now, reason, deprecatedBy, ruleId);

    const updatedRule = this.getRuleById(ruleId);
    if (updatedRule) {
      // Create workflow history entry
      this.createWorkflowHistoryEntry(ruleId, 'published', 'deprecated', deprecatedBy, reason);

      // Create history entry
      this.createHistoryEntry(updatedRule, 'updated', `Rule deprecated: ${reason}`, deprecatedBy);

      // Create notification
      this.createWorkflowNotification(
        rule.user_id,
        ruleId,
        'rule_deprecated',
        'Rule Deprecated',
        `Your rule "${rule.name}" has been deprecated. Reason: ${reason}`
      );
    }

    return updatedRule;
  }

  /**
   * Bulk approve multiple rules
   */
  bulkApproveRules(ruleIds: number[], approvedBy: number): number {
    let approvedCount = 0;

    const transaction = this.db.transaction((ids: number[]) => {
      ids.forEach(id => {
        const result = this.approveRule(id, approvedBy, 'Bulk approval');
        if (result) {
          approvedCount++;
        }
      });
    });

    try {
      transaction(ruleIds);
    } catch (error) {
      console.error('Bulk approval failed:', error);
      throw error;
    }

    return approvedCount;
  }

  /**
   * Bulk deprecate multiple rules
   */
  bulkDeprecateRules(ruleIds: number[], deprecatedBy: number, reason: string): number {
    let deprecatedCount = 0;

    const transaction = this.db.transaction((ids: number[]) => {
      ids.forEach(id => {
        const result = this.deprecateRule(id, deprecatedBy, reason);
        if (result) {
          deprecatedCount++;
        }
      });
    });

    try {
      transaction(ruleIds);
    } catch (error) {
      console.error('Bulk deprecation failed:', error);
      throw error;
    }

    return deprecatedCount;
  }

  /**
   * Get suggested rules
   */
  getSuggestedRules(userId: number): CorrectionRule[] {
    const stmt = this.db.prepare(`
      SELECT * FROM correction_rules 
      WHERE user_id = ? AND suggested_by IS NOT NULL AND workflow_state = 'draft'
      ORDER BY suggestion_date DESC
    `);

    return stmt.all(userId) as CorrectionRule[];
  }

  /**
   * Record rule usage
   */
  recordRuleUsage(ruleId: number): void {
    const now = new Date().toISOString();
    const stmt = this.db.prepare(`
      UPDATE correction_rules 
      SET usage_count = usage_count + 1,
          last_used_at = ?
      WHERE id = ?
    `);

    stmt.run(now, ruleId);
  }

  /**
   * Update rule effectiveness score
   */
  updateRuleEffectiveness(ruleId: number, score: number): void {
    const stmt = this.db.prepare(`
      UPDATE correction_rules 
      SET effectiveness_score = ?
      WHERE id = ?
    `);

    stmt.run(score, ruleId);
  }

  /**
   * Create workflow history entry
   */
  private createWorkflowHistoryEntry(
    ruleId: number,
    previousState: string | null,
    newState: string,
    changedBy: number,
    changeReason: string,
    metadata?: any
  ): void {
    const stmt = this.db.prepare(`
      INSERT INTO workflow_state_history (
        rule_id, previous_state, new_state, changed_by, change_reason, metadata
      ) VALUES (?, ?, ?, ?, ?, ?)
    `);

    stmt.run(
      ruleId,
      previousState,
      newState,
      changedBy,
      changeReason,
      metadata ? JSON.stringify(metadata) : null
    );
  }

  /**
   * Create workflow notification
   */
  private createWorkflowNotification(
    userId: number,
    ruleId: number | null,
    notificationType: string,
    title: string,
    message: string,
    actionUrl?: string,
    metadata?: any
  ): void {
    const stmt = this.db.prepare(`
      INSERT INTO workflow_notifications (
        user_id, rule_id, notification_type, title, message, action_url, metadata
      ) VALUES (?, ?, ?, ?, ?, ?, ?)
    `);

    stmt.run(
      userId,
      ruleId,
      notificationType,
      title,
      message,
      actionUrl || null,
      metadata ? JSON.stringify(metadata) : null
    );
  }

  /**
   * Get unread notifications for a user
   */
  getUnreadNotifications(userId: number, limit: number = 50): WorkflowNotification[] {
    const stmt = this.db.prepare(`
      SELECT * FROM workflow_notifications 
      WHERE user_id = ? AND is_read = 0
      ORDER BY created_at DESC
      LIMIT ?
    `);

    return stmt.all(userId, limit) as WorkflowNotification[];
  }

  /**
   * Mark notification as read
   */
  markNotificationAsRead(notificationId: number, userId: number): boolean {
    const now = new Date().toISOString();
    const stmt = this.db.prepare(`
      UPDATE workflow_notifications 
      SET is_read = 1, read_at = ?
      WHERE id = ? AND user_id = ?
    `);

    const result = stmt.run(now, notificationId, userId);
    return result.changes > 0;
  }

  /**
   * Get workflow state history for a rule
   */
  getWorkflowHistory(ruleId: number): WorkflowStateHistory[] {
    const stmt = this.db.prepare(`
      SELECT * FROM workflow_state_history 
      WHERE rule_id = ?
      ORDER BY changed_at DESC
    `);

    return stmt.all(ruleId) as WorkflowStateHistory[];
  }

  // ========== HISTORY TRACKING ==========

  /**
   * Create a history entry for a rule change
   */
  private createHistoryEntry(
    rule: CorrectionRule, 
    changeType: 'created' | 'updated' | 'deleted' | 'activated' | 'deactivated',
    summary: string,
    changedBy: number
  ): void {
    const stmt = this.db.prepare(`
      INSERT INTO correction_rule_history (
        rule_id, rule_uuid, name, description, find_pattern, replace_with,
        is_regex, is_active, priority, change_type, change_summary, changed_by
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `);

    stmt.run(
      rule.id,
      rule.uuid,
      rule.name,
      rule.description || null,
      rule.find_pattern,
      rule.replace_with,
      rule.is_regex ? 1 : 0,
      rule.is_active ? 1 : 0,
      rule.priority,
      changeType,
      summary,
      changedBy
    );
  }

  /**
   * Get history for a rule
   */
  getRuleHistory(ruleId: number): CorrectionRuleHistory[] {
    const stmt = this.db.prepare(`
      SELECT * FROM correction_rule_history 
      WHERE rule_id = ? 
      ORDER BY changed_at DESC
    `);

    return stmt.all(ruleId) as CorrectionRuleHistory[];
  }

  // ========== STATISTICS ==========

  /**
   * Record rule usage statistics with enhanced effectiveness metrics
   */
  recordRuleUsage(
    ruleId: number,
    executionTimeMs: number,
    charactersProcessed: number,
    success: boolean,
    options: {
      charactersAfter?: number;
      qualityScore?: number;
      impactRating?: number;
      isFalsePositive?: boolean;
      userFeedback?: number;
    } = {}
  ): void {
    const rule = this.getRuleById(ruleId);
    if (!rule) return;

    const now = new Date();
    const dateBucket = now.toISOString().split('T')[0];
    const hourBucket = now.getHours();

    // Calculate enhanced metrics
    const charactersAfter = options.charactersAfter || charactersProcessed;
    const charactersSaved = charactersProcessed - charactersAfter;
    const qualityScore = options.qualityScore || this.calculateQualityScore(rule, charactersSaved, success);
    const impactRating = options.impactRating || this.calculateImpactRating(rule, charactersSaved);
    const complexityScore = this.calculateComplexityScore(rule);

    // Update or insert statistics
    const stmt = this.db.prepare(`
      INSERT INTO correction_statistics (
        rule_id, rule_uuid, date_bucket, hour_bucket, application_count,
        character_count_before, character_count_after, execution_time_ms,
        success_rate, error_count, quality_score, impact_rating,
        false_positive_count, user_feedback_score, avg_characters_saved, complexity_score
      ) VALUES (?, ?, ?, ?, 1, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT(rule_id, date_bucket, hour_bucket) DO UPDATE SET
        application_count = application_count + 1,
        character_count_before = character_count_before + excluded.character_count_before,
        character_count_after = character_count_after + excluded.character_count_after,
        execution_time_ms = (execution_time_ms + excluded.execution_time_ms) / 2,
        success_rate = (success_rate * (application_count - 1) + excluded.success_rate) / application_count,
        error_count = error_count + excluded.error_count,
        quality_score = (quality_score * (application_count - 1) + excluded.quality_score) / application_count,
        impact_rating = (impact_rating * (application_count - 1) + excluded.impact_rating) / application_count,
        false_positive_count = false_positive_count + excluded.false_positive_count,
        user_feedback_score = COALESCE(excluded.user_feedback_score, user_feedback_score),
        avg_characters_saved = (avg_characters_saved * (application_count - 1) + excluded.avg_characters_saved) / application_count,
        complexity_score = excluded.complexity_score,
        updated_at = CURRENT_TIMESTAMP
    `);

    stmt.run(
      ruleId,
      rule.uuid,
      dateBucket,
      hourBucket,
      charactersProcessed,
      charactersAfter,
      executionTimeMs,
      success ? 100 : 0,
      success ? 0 : 1,
      qualityScore,
      impactRating,
      options.isFalsePositive ? 1 : 0,
      options.userFeedback || null,
      charactersSaved,
      complexityScore
    );

    // Update last_used_at
    const updateStmt = this.db.prepare(`
      UPDATE correction_rules 
      SET last_used_at = CURRENT_TIMESTAMP 
      WHERE id = ?
    `);
    updateStmt.run(ruleId);
  }

  /**
   * Get usage statistics for a rule
   */
  getRuleStats(ruleId: number, days: number = 30): CorrectionStatistics[] {
    const stmt = this.db.prepare(`
      SELECT * FROM correction_statistics 
      WHERE rule_id = ? AND date_bucket >= date('now', '-${days} days')
      ORDER BY date_bucket DESC, hour_bucket DESC
    `);

    return stmt.all(ruleId) as CorrectionStatistics[];
  }

  /**
   * Get enhanced performance metrics for all rules
   */
  getPerformanceMetrics(userId: number, days: number = 30): PerformanceMetrics {
    const totalRulesStmt = this.db.prepare('SELECT COUNT(*) as count FROM correction_rules WHERE user_id = ?');
    const activeRulesStmt = this.db.prepare('SELECT COUNT(*) as count FROM correction_rules WHERE user_id = ? AND is_active = 1');

    const totalRules = totalRulesStmt.get(userId) as { count: number };
    const activeRules = activeRulesStmt.get(userId) as { count: number };

    // Get aggregated statistics with enhanced metrics
    const statsStmt = this.db.prepare(`
      SELECT 
        SUM(application_count) as total_executions,
        AVG(execution_time_ms) as avg_execution_time,
        AVG(success_rate) as avg_success_rate,
        SUM(error_count) as total_errors,
        AVG(quality_score) as avg_quality_score,
        AVG(impact_rating) as avg_impact_rating,
        SUM(avg_characters_saved * application_count) as total_characters_saved,
        AVG(CASE WHEN false_positive_count > 0 THEN (false_positive_count * 100.0 / application_count) ELSE 0 END) as false_positive_rate,
        AVG(user_feedback_score) as user_satisfaction_score
      FROM correction_statistics cs
      JOIN correction_rules cr ON cs.rule_id = cr.id
      WHERE cr.user_id = ? AND cs.date_bucket >= date('now', '-${days} days')
    `);

    const stats = statsStmt.get(userId) as any;

    // Get most used rules with enhanced metrics
    const mostUsedStmt = this.db.prepare(`
      SELECT 
        cr.id as rule_id,
        cr.name as rule_name,
        SUM(cs.application_count) as total_applications,
        SUM(cs.character_count_before) as total_characters_processed,
        AVG(cs.execution_time_ms) as average_execution_time,
        AVG(cs.success_rate) as success_rate,
        MAX(cs.date_bucket) as last_used,
        AVG(cs.quality_score) as quality_score,
        AVG(cs.impact_rating) as impact_rating,
        AVG(CASE WHEN cs.false_positive_count > 0 THEN (cs.false_positive_count * 100.0 / cs.application_count) ELSE 0 END) as false_positive_rate,
        AVG(cs.user_feedback_score) as user_feedback_score,
        AVG(cs.avg_characters_saved) as avg_characters_saved,
        AVG(cs.complexity_score) as complexity_score,
        CASE 
          WHEN SUM(cs.application_count) > LAG(SUM(cs.application_count), 7) OVER (ORDER BY cr.id) THEN 'increasing'
          WHEN SUM(cs.application_count) < LAG(SUM(cs.application_count), 7) OVER (ORDER BY cr.id) THEN 'decreasing'
          ELSE 'stable'
        END as usage_trend,
        CASE 
          WHEN AVG(cs.execution_time_ms) < LAG(AVG(cs.execution_time_ms), 7) OVER (ORDER BY cr.id) THEN 'improving'
          WHEN AVG(cs.execution_time_ms) > LAG(AVG(cs.execution_time_ms), 7) OVER (ORDER BY cr.id) THEN 'degrading'
          ELSE 'stable'
        END as performance_trend
      FROM correction_statistics cs
      JOIN correction_rules cr ON cs.rule_id = cr.id
      WHERE cr.user_id = ? AND cs.date_bucket >= date('now', '-${days} days')
      GROUP BY cr.id, cr.name
      ORDER BY total_applications DESC
      LIMIT 10
    `);

    const mostUsedRules = mostUsedStmt.all(userId) as RuleUsageStats[];

    // Get performance trends with enhanced metrics
    const trendsStmt = this.db.prepare(`
      SELECT 
        cs.date_bucket as date,
        SUM(cs.application_count) as executions,
        AVG(cs.execution_time_ms) as avg_time,
        SUM(cs.error_count) as error_count,
        AVG(cs.quality_score) as quality_score,
        AVG(cs.impact_rating) as impact_rating
      FROM correction_statistics cs
      JOIN correction_rules cr ON cs.rule_id = cr.id
      WHERE cr.user_id = ? AND cs.date_bucket >= date('now', '-${days} days')
      GROUP BY cs.date_bucket
      ORDER BY cs.date_bucket ASC
    `);

    const trends = trendsStmt.all(userId) as any[];

    // Get rule effectiveness distribution
    const distributionStmt = this.db.prepare(`
      SELECT 
        SUM(CASE WHEN AVG(cs.impact_rating) >= 4 THEN 1 ELSE 0 END) as high_impact,
        SUM(CASE WHEN AVG(cs.impact_rating) >= 2 AND AVG(cs.impact_rating) < 4 THEN 1 ELSE 0 END) as medium_impact,
        SUM(CASE WHEN AVG(cs.impact_rating) < 2 THEN 1 ELSE 0 END) as low_impact,
        SUM(CASE WHEN AVG(cs.execution_time_ms) < 10 THEN 1 ELSE 0 END) as fast_rules,
        SUM(CASE WHEN AVG(cs.execution_time_ms) > 100 THEN 1 ELSE 0 END) as slow_rules,
        SUM(CASE WHEN AVG(cs.quality_score) >= 80 THEN 1 ELSE 0 END) as excellent_rules,
        SUM(CASE WHEN AVG(cs.quality_score) >= 60 AND AVG(cs.quality_score) < 80 THEN 1 ELSE 0 END) as good_rules,
        SUM(CASE WHEN AVG(cs.quality_score) < 60 THEN 1 ELSE 0 END) as poor_rules
      FROM correction_statistics cs
      JOIN correction_rules cr ON cs.rule_id = cr.id
      WHERE cr.user_id = ? AND cs.date_bucket >= date('now', '-${days} days')
      GROUP BY cr.id
    `);

    const distribution = distributionStmt.get(userId) as any;

    return {
      total_rules: totalRules.count,
      active_rules: activeRules.count,
      total_executions: stats.total_executions || 0,
      average_execution_time: stats.avg_execution_time || 0,
      error_rate: stats.total_errors && stats.total_executions 
        ? (stats.total_errors / stats.total_executions) * 100 
        : 0,
      most_used_rules: mostUsedRules,
      performance_trends: trends,
      overall_quality_score: stats.avg_quality_score || 0,
      average_impact_rating: stats.avg_impact_rating || 0,
      total_characters_saved: stats.total_characters_saved || 0,
      false_positive_rate: stats.false_positive_rate || 0,
      user_satisfaction_score: stats.user_satisfaction_score,
      high_impact_rules: distribution.high_impact || 0,
      medium_impact_rules: distribution.medium_impact || 0,
      low_impact_rules: distribution.low_impact || 0,
      fast_rules: distribution.fast_rules || 0,
      slow_rules: distribution.slow_rules || 0,
      excellent_rules: distribution.excellent_rules || 0,
      good_rules: distribution.good_rules || 0,
      poor_rules: distribution.poor_rules || 0,
    };
  }

  // ========== MIGRATION FROM LOCALSTORAGE ==========

  /**
   * Import rules from localStorage format
   */
  importFromLocalStorage(localStorageRules: any[], userId: number = 1): number {
    let importedCount = 0;

    const transaction = this.db.transaction((rules: any[]) => {
      for (const rule of rules) {
        try {
          const input: CreateCorrectionRuleInput = {
            name: rule.name,
            description: rule.description,
            find_pattern: rule.findPattern,
            replace_with: rule.replaceWith,
            is_regex: rule.isRegex,
            is_active: rule.isActive,
            priority: rule.priority,
            user_id: userId,
            scope: 'private',
          };

          this.createRule(input);
          importedCount++;
        } catch (error) {
          console.error('Failed to import rule:', rule.name, error);
        }
      }
    });

    transaction(localStorageRules);
    return importedCount;
  }

  /**
   * Export rules to localStorage format
   */
  exportToLocalStorage(userId: number): any[] {
    const rules = this.getRulesByUser(userId, true);

    return rules.map(rule => ({
      id: rule.uuid, // Use UUID for external ID
      name: rule.name,
      description: rule.description,
      findPattern: rule.find_pattern,
      replaceWith: rule.replace_with,
      isRegex: rule.is_regex,
      isActive: rule.is_active,
      priority: rule.priority,
      createdAt: rule.created_at,
      updatedAt: rule.updated_at,
    }));
  }

  /**
   * Clear all rules for a user
   */
  clearAllRules(userId: number): number {
    const stmt = this.db.prepare('DELETE FROM correction_rules WHERE user_id = ?');
    const result = stmt.run(userId);
    return result.changes;
  }
}

import { z } from 'zod';
import { CorrectionRule } from './models';

// ========== EXPORT FORMAT SCHEMAS ==========

/**
 * Standard correction rule export format
 */
export const ExportedCorrectionRuleSchema = z.object({
  id: z.string().uuid(),
  name: z.string().min(1),
  description: z.string().optional(),
  findPattern: z.string().min(1),
  replaceWith: z.string(),
  isRegex: z.boolean(),
  isActive: z.boolean(),
  priority: z.number().int().min(0),
  category: z.string().optional(),
  tags: z.array(z.string()).optional(),
  createdAt: z.string().datetime(),
  updatedAt: z.string().datetime(),

  // Optional metadata
  metadata: z.object({
    version: z.string().optional(),
    author: z.string().optional(),
    usage_count: z.number().int().optional(),
    effectiveness_score: z.number().min(0).max(100).optional(),
  }).optional(),
});

/**
 * Correction set export format
 */
export const ExportedCorrectionSetSchema = z.object({
  meta: z.object({
    name: z.string().min(1),
    description: z.string().optional(),
    version: z.string().default('1.0.0'),
    format_version: z.string().default('1.0'),
    created_at: z.string().datetime(),
    updated_at: z.string().datetime(),
    author: z.string().optional(),
    license: z.string().optional(),
    compatibility: z.object({
      min_version: z.string().optional(),
      max_version: z.string().optional(),
    }).optional(),
  }),

  rules: z.array(ExportedCorrectionRuleSchema),

  // Optional sections
  categories: z.array(z.object({
    id: z.string(),
    name: z.string(),
    description: z.string().optional(),
    color: z.string().optional(),
  })).optional(),

  tags: z.array(z.object({
    id: z.string(),
    name: z.string(),
    description: z.string().optional(),
  })).optional(),

  settings: z.object({
    auto_apply: z.boolean().optional(),
    priority_mode: z.enum(['sequence', 'weighted']).optional(),
    performance_mode: z.enum(['fast', 'thorough']).optional(),
  }).optional(),

  // Statistics and metrics
  statistics: z.object({
    total_rules: z.number().int(),
    active_rules: z.number().int(),
    total_executions: z.number().int().optional(),
    success_rate: z.number().min(0).max(100).optional(),
    avg_execution_time: z.number().min(0).optional(),
  }).optional(),
});

// Type definitions
export type ExportedCorrectionRule = z.infer<typeof ExportedCorrectionRuleSchema>;
export type ExportedCorrectionSet = z.infer<typeof ExportedCorrectionSetSchema>;

// ========== FORMAT CONVERTERS ==========

/**
 * Convert database rule to export format
 */
export function ruleToExportFormat(rule: CorrectionRule): ExportedCorrectionRule {
  return {
    id: rule.uuid,
    name: rule.name,
    description: rule.description || undefined,
    findPattern: rule.find_pattern,
    replaceWith: rule.replace_with,
    isRegex: rule.is_regex,
    isActive: rule.is_active,
    priority: rule.priority,
    createdAt: rule.created_at,
    updatedAt: rule.updated_at,

    metadata: {
      version: rule.version.toString(),
      // Additional metadata would be populated from statistics
    },
  };
}

/**
 * Convert export format to database rule input
 */
export function exportFormatToRule(exportedRule: ExportedCorrectionRule): {
  uuid: string;
  name: string;
  description?: string;
  find_pattern: string;
  replace_with: string;
  is_regex: boolean;
  is_active: boolean;
  priority: number;
} {
  return {
    uuid: exportedRule.id,
    name: exportedRule.name,
    description: exportedRule.description,
    find_pattern: exportedRule.findPattern,
    replace_with: exportedRule.replaceWith,
    is_regex: exportedRule.isRegex,
    is_active: exportedRule.isActive,
    priority: exportedRule.priority,
  };
}

// ========== EXPORT FORMATTERS ==========

/**
 * Export correction set to JSON format
 */
export function exportToJSON(correctionSet: ExportedCorrectionSet): string {
  return JSON.stringify(correctionSet, null, 2);
}

/**
 * Export correction set to YAML format
 */
export function exportToYAML(correctionSet: ExportedCorrectionSet): string {
  // Simple YAML serialization - in production, use a proper YAML library
  const yamlLines: string[] = [];

  // Meta section
  yamlLines.push('meta:');
  yamlLines.push(`  name: "${correctionSet.meta.name}"`);
  if (correctionSet.meta.description) {
    yamlLines.push(`  description: "${correctionSet.meta.description}"`);
  }
  yamlLines.push(`  version: "${correctionSet.meta.version}"`);
  yamlLines.push(`  format_version: "${correctionSet.meta.format_version}"`);
  yamlLines.push(`  created_at: "${correctionSet.meta.created_at}"`);
  yamlLines.push(`  updated_at: "${correctionSet.meta.updated_at}"`);

  // Rules section
  yamlLines.push('');
  yamlLines.push('rules:');

  correctionSet.rules.forEach(rule => {
    yamlLines.push(`  - id: "${rule.id}"`);
    yamlLines.push(`    name: "${rule.name}"`);
    if (rule.description) {
      yamlLines.push(`    description: "${rule.description}"`);
    }
    yamlLines.push(`    findPattern: "${rule.findPattern.replace(/"/g, '\\"')}"`);
    yamlLines.push(`    replaceWith: "${rule.replaceWith.replace(/"/g, '\\"')}"`);
    yamlLines.push(`    isRegex: ${rule.isRegex}`);
    yamlLines.push(`    isActive: ${rule.isActive}`);
    yamlLines.push(`    priority: ${rule.priority}`);
    yamlLines.push(`    createdAt: "${rule.createdAt}"`);
    yamlLines.push(`    updatedAt: "${rule.updatedAt}"`);
    yamlLines.push('');
  });

  // Statistics section
  if (correctionSet.statistics) {
    yamlLines.push('statistics:');
    yamlLines.push(`  total_rules: ${correctionSet.statistics.total_rules}`);
    yamlLines.push(`  active_rules: ${correctionSet.statistics.active_rules}`);
    if (correctionSet.statistics.total_executions) {
      yamlLines.push(`  total_executions: ${correctionSet.statistics.total_executions}`);
    }
    if (correctionSet.statistics.success_rate) {
      yamlLines.push(`  success_rate: ${correctionSet.statistics.success_rate}`);
    }
    if (correctionSet.statistics.avg_execution_time) {
      yamlLines.push(`  avg_execution_time: ${correctionSet.statistics.avg_execution_time}`);
    }
  }

  return yamlLines.join('\n');
}

/**
 * Export correction set to CSV format
 */
export function exportToCSV(correctionSet: ExportedCorrectionSet): string {
  const csvLines: string[] = [];

  // CSV header
  csvLines.push([
    'id',
    'name',
    'description',
    'findPattern',
    'replaceWith',
    'isRegex',
    'isActive',
    'priority',
    'createdAt',
    'updatedAt'
  ].join(','));

  // CSV rows
  correctionSet.rules.forEach(rule => {
    csvLines.push([
      rule.id,
      `"${rule.name.replace(/"/g, '""')}"`,
      rule.description ? `"${rule.description.replace(/"/g, '""')}"` : '',
      `"${rule.findPattern.replace(/"/g, '""')}"`,
      `"${rule.replaceWith.replace(/"/g, '""')}"`,
      rule.isRegex.toString(),
      rule.isActive.toString(),
      rule.priority.toString(),
      rule.createdAt,
      rule.updatedAt
    ].join(','));
  });

  return csvLines.join('\n');
}

// ========== IMPORT PARSERS ==========

/**
 * Parse JSON correction set
 */
export function parseFromJSON(jsonString: string): ExportedCorrectionSet {
  const parsed = JSON.parse(jsonString);
  return ExportedCorrectionSetSchema.parse(parsed);
}

/**
 * Parse YAML correction set (simplified implementation)
 */
export function parseFromYAML(yamlString: string): ExportedCorrectionSet {
  // This is a simplified YAML parser - in production, use a proper YAML library
  const lines = yamlString.split('\n');
  const result: any = { meta: {}, rules: [] };

  let currentSection = '';
  let currentRule: any = null;

  for (const line of lines) {
    const trimmed = line.trim();

    if (trimmed === 'meta:') {
      currentSection = 'meta';
      continue;
    }

    if (trimmed === 'rules:') {
      currentSection = 'rules';
      continue;
    }

    if (trimmed.startsWith('- id:')) {
      if (currentRule) {
        result.rules.push(currentRule);
      }
      currentRule = {};
      const id = trimmed.match(/id: "(.+)"/)?.[1];
      if (id) currentRule.id = id;
      continue;
    }

    if (currentSection === 'meta' && trimmed.includes(':')) {
      const [key, value] = trimmed.split(': ', 2);
      if (key && value) {
        result.meta[key] = value.replace(/"/g, '');
      }
    }

    if (currentSection === 'rules' && currentRule && trimmed.includes(':')) {
      const [key, value] = trimmed.split(': ', 2);
      if (key && value) {
        if (key === 'isRegex' || key === 'isActive') {
          currentRule[key] = value === 'true';
        } else if (key === 'priority') {
          currentRule[key] = parseInt(value, 10);
        } else {
          currentRule[key] = value.replace(/"/g, '');
        }
      }
    }
  }

  if (currentRule) {
    result.rules.push(currentRule);
  }

  return ExportedCorrectionSetSchema.parse(result);
}

/**
 * Parse CSV correction set
 */
export function parseFromCSV(csvString: string): ExportedCorrectionSet {
  const lines = csvString.split('\n');
  const headers = lines[0].split(',');

  const rules: ExportedCorrectionRule[] = [];

  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;

    const values = parseCSVLine(line);

    if (values.length >= headers.length) {
      const rule: any = {};
      headers.forEach((header, index) => {
        const value = values[index];
        switch (header) {
          case 'isRegex':
          case 'isActive':
            rule[header] = value === 'true';
            break;
          case 'priority':
            rule[header] = parseInt(value, 10);
            break;
          default:
            rule[header] = value;
        }
      });

      rules.push(rule);
    }
  }

  // Create minimal meta for CSV import
  const meta = {
    name: 'Imported Correction Set',
    version: '1.0.0',
    format_version: '1.0',
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };

  return ExportedCorrectionSetSchema.parse({ meta, rules });
}

/**
 * Parse a single CSV line handling quoted values
 */
function parseCSVLine(line: string): string[] {
  const result: string[] = [];
  let current = '';
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];

    if (char === '"' && !inQuotes) {
      inQuotes = true;
    } else if (char === '"' && inQuotes) {
      if (line[i + 1] === '"') {
        current += '"';
        i++; // Skip next quote
      } else {
        inQuotes = false;
      }
    } else if (char === ',' && !inQuotes) {
      result.push(current);
      current = '';
    } else {
      current += char;
    }
  }

  result.push(current);
  return result;
}

// ========== VALIDATION HELPERS ==========

/**
 * Validate imported correction set
 */
export function validateImportedSet(data: any): {
  valid: boolean;
  errors: string[];
  warnings: string[];
} {
  const errors: string[] = [];
  const warnings: string[] = [];

  try {
    const validatedSet = ExportedCorrectionSetSchema.parse(data);

    // Additional validation
    if (validatedSet.rules.length === 0) {
      warnings.push('No correction rules found in the imported set');
    }

    if (validatedSet.rules.length > 500) {
      warnings.push(`Large number of rules (${validatedSet.rules.length}) - import may be slow`);
    }

    // Check for regex validity
    validatedSet.rules.forEach((rule, index) => {
      if (rule.isRegex) {
        try {
          new RegExp(rule.findPattern);
        } catch (error) {
          errors.push(`Rule ${index + 1} (${rule.name}): Invalid regex pattern`);
        }
      }
    });

    // Check for duplicate names
    const names = validatedSet.rules.map(r => r.name);
    const duplicates = names.filter((name, index) => names.indexOf(name) !== index);
    if (duplicates.length > 0) {
      warnings.push(`Duplicate rule names found: ${duplicates.slice(0, 5).join(', ')}${duplicates.length > 5 ? '...' : ''}`);
    }

    return {
      valid: errors.length === 0,
      errors,
      warnings
    };
  } catch (error) {
    if (error instanceof z.ZodError) {
      error.errors.forEach(e => {
        errors.push(`${e.path.join('.')}: ${e.message}`);
      });
    } else {
      errors.push(`Validation failed: ${error instanceof Error ? error.message : String(error)}`);
    }

    return {
      valid: false,
      errors,
      warnings
    };
  }
}

/**
 * Get format from file extension or content
 */
export function detectFormat(filename: string, content: string): 'json' | 'yaml' | 'csv' | 'unknown' {
  // Check file extension first
  const ext = filename.toLowerCase().split('.').pop();
  if (ext === 'json') return 'json';
  if (ext === 'yaml' || ext === 'yml') return 'yaml';
  if (ext === 'csv') return 'csv';

  // Check content
  const trimmed = content.trim();
  if (trimmed.startsWith('{') && trimmed.endsWith('}')) return 'json';
  if (trimmed.startsWith('[') && trimmed.endsWith(']')) return 'json';
  if (trimmed.includes('meta:') && trimmed.includes('rules:')) return 'yaml';
  if (trimmed.includes('id,name,description,findPattern')) return 'csv';

  return 'unknown';
}

import { CorrectionsDAO } from './corrections-dao';
import { 
  ExportedCorrectionSet, 
  ExportedCorrectionRule,
  ruleToExportFormat,
  exportFormatToRule,
  exportToJSON,
  exportToYAML,
  exportToCSV,
  parseFromJSON,
  parseFromYAML,
  parseFromCSV,
  validateImportedSet,
  detectFormat
} from './export-formats';
import { getDatabase } from './connection';
import { createHash } from 'crypto';

/**
 * Service for handling correction rule imports and exports
 */
export class ExportService {
  private dao: CorrectionsDAO;

  constructor() {
    this.dao = new CorrectionsDAO();
  }

  // ========== EXPORT OPERATIONS ==========

  /**
   * Export correction rules to a standardized format
   */
  async exportRules(
    userId: number,
    format: 'json' | 'yaml' | 'csv' = 'json',
    options: {
      name?: string;
      description?: string;
      includeInactive?: boolean;
      includeStatistics?: boolean;
      ruleIds?: number[];
    } = {}
  ): Promise<{
    success: boolean;
    data?: string;
    filename?: string;
    mimeType?: string;
    error?: string;
  }> {
    try {
      // Get rules to export
      const rules = options.ruleIds 
        ? options.ruleIds.map(id => this.dao.getRuleById(id)).filter(Boolean)
        : this.dao.getRulesByUser(userId, options.includeInactive || false);

      if (rules.length === 0) {
        return {
          success: false,
          error: 'No correction rules found to export'
        };
      }

      // Convert to export format
      const exportedRules: ExportedCorrectionRule[] = rules.map(ruleToExportFormat);

      // Get statistics if requested
      let statistics;
      if (options.includeStatistics) {
        const metrics = this.dao.getPerformanceMetrics(userId);
        statistics = {
          total_rules: metrics.total_rules,
          active_rules: metrics.active_rules,
          total_executions: metrics.total_executions,
          success_rate: 100 - metrics.error_rate,
          avg_execution_time: metrics.average_execution_time,
        };
      }

      // Create export set
      const exportSet: ExportedCorrectionSet = {
        meta: {
          name: options.name || 'Correction Rules Export',
          description: options.description || `Exported ${rules.length} correction rules`,
          version: '1.0.0',
          format_version: '1.0',
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        },
        rules: exportedRules,
        statistics,
      };

      // Format output
      let data: string;
      let filename: string;
      let mimeType: string;

      switch (format) {
        case 'json':
          data = exportToJSON(exportSet);
          filename = `corrections-${Date.now()}.json`;
          mimeType = 'application/json';
          break;
        case 'yaml':
          data = exportToYAML(exportSet);
          filename = `corrections-${Date.now()}.yaml`;
          mimeType = 'application/x-yaml';
          break;
        case 'csv':
          data = exportToCSV(exportSet);
          filename = `corrections-${Date.now()}.csv`;
          mimeType = 'text/csv';
          break;
        default:
          return {
            success: false,
            error: 'Unsupported export format'
          };
      }

      return {
        success: true,
        data,
        filename,
        mimeType
      };
    } catch (error) {
      return {
        success: false,
        error: `Export failed: ${error instanceof Error ? error.message : String(error)}`
      };
    }
  }

  /**
   * Create a shareable correction set
   */
  async createCorrectionSet(
    userId: number,
    ruleIds: number[],
    metadata: {
      name: string;
      description?: string;
      version?: string;
      isPublic?: boolean;
    }
  ): Promise<{
    success: boolean;
    setId?: number;
    error?: string;
  }> {
    try {
      // Get rules
      const rules = ruleIds.map(id => this.dao.getRuleById(id)).filter(Boolean);

      if (rules.length === 0) {
        return {
          success: false,
          error: 'No valid rules found for the correction set'
        };
      }

      // Create export data
      const exportSet: ExportedCorrectionSet = {
        meta: {
          name: metadata.name,
          description: metadata.description || '',
          version: metadata.version || '1.0.0',
          format_version: '1.0',
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        },
        rules: rules.map(ruleToExportFormat),
      };

      const exportData = exportToJSON(exportSet);
      const checksum = createHash('sha256').update(exportData).digest('hex');

      // Store in database
      const db = getDatabase();
      const stmt = db.prepare(`
        INSERT INTO correction_sets (
          name, description, version, created_by, export_format, 
          export_data, checksum, is_public
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
      `);

      const result = stmt.run(
        metadata.name,
        metadata.description || null,
        metadata.version || '1.0.0',
        userId,
        'json',
        exportData,
        checksum,
        metadata.isPublic ? 1 : 0
      );

      const setId = result.lastInsertRowid as number;

      // Link rules to the set
      const linkStmt = db.prepare(`
        INSERT INTO correction_set_rules (set_id, rule_id, order_index)
        VALUES (?, ?, ?)
      `);

      rules.forEach((rule, index) => {
        linkStmt.run(setId, rule.id, index);
      });

      return {
        success: true,
        setId
      };
    } catch (error) {
      return {
        success: false,
        error: `Failed to create correction set: ${error instanceof Error ? error.message : String(error)}`
      };
    }
  }

  // ========== IMPORT OPERATIONS ==========

  /**
   * Import correction rules from file content
   */
  async importRules(
    userId: number,
    filename: string,
    content: string,
    options: {
      overwrite?: boolean;
      merge?: boolean;
      skipDuplicates?: boolean;
    } = {}
  ): Promise<{
    success: boolean;
    importedCount?: number;
    skippedCount?: number;
    errors?: string[];
    warnings?: string[];
  }> {
    try {
      // Detect format
      const format = detectFormat(filename, content);

      if (format === 'unknown') {
        return {
          success: false,
          errors: ['Unable to detect file format. Supported formats: JSON, YAML, CSV']
        };
      }

      // Parse content
      let importedSet: ExportedCorrectionSet;

      try {
        switch (format) {
          case 'json':
            importedSet = parseFromJSON(content);
            break;
          case 'yaml':
            importedSet = parseFromYAML(content);
            break;
          case 'csv':
            importedSet = parseFromCSV(content);
            break;
          default:
            throw new Error('Unsupported format');
        }
      } catch (error) {
        return {
          success: false,
          errors: [`Failed to parse ${format.toUpperCase()} file: ${error instanceof Error ? error.message : String(error)}`]
        };
      }

      // Validate imported data
      const validation = validateImportedSet(importedSet);
      if (!validation.valid) {
        return {
          success: false,
          errors: validation.errors,
          warnings: validation.warnings
        };
      }

      // Import rules
      const importResult = await this.importCorrectionRules(
        userId,
        importedSet.rules,
        options
      );

      return {
        success: true,
        importedCount: importResult.importedCount,
        skippedCount: importResult.skippedCount,
        errors: importResult.errors,
        warnings: [...(validation.warnings || []), ...(importResult.warnings || [])]
      };
    } catch (error) {
      return {
        success: false,
        errors: [`Import failed: ${error instanceof Error ? error.message : String(error)}`]
      };
    }
  }

  /**
   * Import correction rules from exported format
   */
  private async importCorrectionRules(
    userId: number,
    rules: ExportedCorrectionRule[],
    options: {
      overwrite?: boolean;
      merge?: boolean;
      skipDuplicates?: boolean;
    }
  ): Promise<{
    importedCount: number;
    skippedCount: number;
    errors: string[];
    warnings: string[];
  }> {
    let importedCount = 0;
    let skippedCount = 0;
    const errors: string[] = [];
    const warnings: string[] = [];

    // Get existing rules for conflict detection
    const existingRules = this.dao.getRulesByUser(userId, true);
    const existingByName = new Map(existingRules.map(r => [r.name, r]));
    const existingByUuid = new Map(existingRules.map(r => [r.uuid, r]));

    for (const rule of rules) {
      try {
        // Check for conflicts
        const existingByNameConflict = existingByName.get(rule.name);
        const existingByUuidConflict = existingByUuid.get(rule.id);

        if (existingByUuidConflict) {
          if (options.overwrite) {
            // Update existing rule
            const updateData = {
              name: rule.name,
              description: rule.description,
              find_pattern: rule.findPattern,
              replace_with: rule.replaceWith,
              is_regex: rule.isRegex,
              is_active: rule.isActive,
              priority: rule.priority,
            };

            const updated = this.dao.updateRule(existingByUuidConflict.id, updateData, userId);
            if (updated) {
              importedCount++;
            } else {
              errors.push(`Failed to update rule: ${rule.name}`);
            }
          } else if (options.skipDuplicates) {
            skippedCount++;
            warnings.push(`Skipped duplicate rule: ${rule.name}`);
          } else {
            errors.push(`Rule with UUID ${rule.id} already exists: ${rule.name}`);
          }
          continue;
        }

        if (existingByNameConflict) {
          if (options.skipDuplicates) {
            skippedCount++;
            warnings.push(`Skipped rule with duplicate name: ${rule.name}`);
            continue;
          } else if (!options.merge) {
            errors.push(`Rule with name "${rule.name}" already exists`);
            continue;
          }
        }

        // Create new rule
        const ruleData = {
          name: rule.name,
          description: rule.description,
          find_pattern: rule.findPattern,
          replace_with: rule.replaceWith,
          is_regex: rule.isRegex,
          is_active: rule.isActive,
          priority: rule.priority,
          user_id: userId,
          scope: 'private' as const,
        };

        const created = this.dao.createRule(ruleData);
        if (created) {
          importedCount++;
        } else {
          errors.push(`Failed to create rule: ${rule.name}`);
        }
      } catch (error) {
        errors.push(`Error importing rule "${rule.name}": ${error instanceof Error ? error.message : String(error)}`);
      }
    }

    return {
      importedCount,
      skippedCount,
      errors,
      warnings
    };
  }

  // ========== CORRECTION SET OPERATIONS ==========

  /**
   * Get available correction sets
   */
  getCorrectionSets(userId: number, includePublic: boolean = true): any[] {
    const db = getDatabase();

    let whereClause = 'WHERE created_by = ?';
    const params = [userId];

    if (includePublic) {
      whereClause += ' OR is_public = 1';
    }

    const stmt = db.prepare(`
      SELECT 
        cs.*,
        COUNT(csr.rule_id) as rule_count
      FROM correction_sets cs
      LEFT JOIN correction_set_rules csr ON cs.id = csr.set_id
      ${whereClause}
      GROUP BY cs.id
      ORDER BY cs.created_at DESC
    `);

    return stmt.all(...params);
  }

  /**
   * Get correction set by ID
   */
  getCorrectionSetById(setId: number, userId: number): any {
    const db = getDatabase();

    const stmt = db.prepare(`
      SELECT cs.*, COUNT(csr.rule_id) as rule_count
      FROM correction_sets cs
      LEFT JOIN correction_set_rules csr ON cs.id = csr.set_id
      WHERE cs.id = ? AND (cs.created_by = ? OR cs.is_public = 1)
      GROUP BY cs.id
    `);

    return stmt.get(setId, userId);
  }

  /**
   * Download correction set
   */
  async downloadCorrectionSet(setId: number, userId: number): Promise<{
    success: boolean;
    data?: string;
    filename?: string;
    mimeType?: string;
    error?: string;
  }> {
    try {
      const set = this.getCorrectionSetById(setId, userId);

      if (!set) {
        return {
          success: false,
          error: 'Correction set not found or access denied'
        };
      }

      // Increment download count
      const db = getDatabase();
      const updateStmt = db.prepare(`
        UPDATE correction_sets 
        SET download_count = download_count + 1 
        WHERE id = ?
      `);
      updateStmt.run(setId);

      // Return export data
      const mimeType = set.export_format === 'json' 
        ? 'application/json' 
        : set.export_format === 'yaml' 
          ? 'application/x-yaml' 
          : 'text/csv';

      return {
        success: true,
        data: set.export_data,
        filename: `${set.name.replace(/[^a-z0-9]/gi, '_')}.${set.export_format}`,
        mimeType
      };
    } catch (error) {
      return {
        success: false,
        error: `Download failed: ${error instanceof Error ? error.message : String(error)}`
      };
    }
  }

  /**
   * Delete correction set
   */
  deleteCorrectionSet(setId: number, userId: number): boolean {
    try {
      const db = getDatabase();

      // Verify ownership
      const stmt = db.prepare('SELECT id FROM correction_sets WHERE id = ? AND created_by = ?');
      const set = stmt.get(setId, userId);

      if (!set) {
        return false;
      }

      // Delete the set (cascade will handle rules)
      const deleteStmt = db.prepare('DELETE FROM correction_sets WHERE id = ?');
      const result = deleteStmt.run(setId);

      return result.changes > 0;
    } catch (error) {
      console.error('Failed to delete correction set:', error);
      return false;
    }
  }
}

import { CorrectionsDAO } from './corrections-dao';
import { initDatabase } from './connection';

/**
 * Migration service to handle data transition from localStorage to database
 */
export class MigrationService {
  private dao: CorrectionsDAO;

  constructor() {
    initDatabase();
    this.dao = new CorrectionsDAO();
  }

  /**
   * Migrate corrections from localStorage format to database
   */
  async migrateFromLocalStorage(localStorageData: any): Promise<{
    success: boolean;
    importedCount: number;
    errors: string[];
  }> {
    const errors: string[] = [];
    let importedCount = 0;

    try {
      // Parse localStorage data
      const correctionsData = this.parseLocalStorageData(localStorageData);

      if (!correctionsData || !correctionsData.rules) {
        return {
          success: false,
          importedCount: 0,
          errors: ['No valid corrections data found in localStorage']
        };
      }

      // Import rules
      try {
        importedCount = this.dao.importFromLocalStorage(correctionsData.rules);
      } catch (error) {
        errors.push(`Failed to import rules: ${error instanceof Error ? error.message : String(error)}`);
      }

      // Import user preferences if available
      if (correctionsData.preferences) {
        try {
          await this.migrateUserPreferences(correctionsData.preferences);
        } catch (error) {
          errors.push(`Failed to import preferences: ${error instanceof Error ? error.message : String(error)}`);
        }
      }

      return {
        success: errors.length === 0,
        importedCount,
        errors
      };
    } catch (error) {
      return {
        success: false,
        importedCount: 0,
        errors: [`Migration failed: ${error instanceof Error ? error.message : String(error)}`]
      };
    }
  }

  /**
   * Parse localStorage data into structured format
   */
  private parseLocalStorageData(data: any): {
    rules: any[];
    preferences?: any;
  } | null {
    try {
      // Handle different localStorage formats
      if (typeof data === 'string') {
        data = JSON.parse(data);
      }

      // Check for corrections-store format (Zustand persist)
      if (data.state && data.state.rules) {
        return {
          rules: data.state.rules,
          preferences: data.state.preferences || null
        };
      }

      // Check for direct rules array
      if (Array.isArray(data)) {
        return {
          rules: data,
          preferences: null
        };
      }

      // Check for object with rules property
      if (data.rules && Array.isArray(data.rules)) {
        return {
          rules: data.rules,
          preferences: data.preferences || null
        };
      }

      return null;
    } catch (error) {
      console.error('Failed to parse localStorage data:', error);
      return null;
    }
  }

  /**
   * Migrate user preferences
   */
  private async migrateUserPreferences(preferences: any): Promise<void> {
    // TODO: Implement user preferences migration
    // This would update the user_preferences table with the settings
    console.log('User preferences migration not yet implemented:', preferences);
  }

  /**
   * Validate migration data before importing
   */
  validateMigrationData(data: any): {
    valid: boolean;
    errors: string[];
    warnings: string[];
  } {
    const errors: string[] = [];
    const warnings: string[] = [];

    try {
      const parsed = this.parseLocalStorageData(data);

      if (!parsed) {
        errors.push('Unable to parse localStorage data');
        return { valid: false, errors, warnings };
      }

      const { rules } = parsed;

      if (!Array.isArray(rules)) {
        errors.push('Rules data is not an array');
        return { valid: false, errors, warnings };
      }

      // Validate each rule
      rules.forEach((rule, index) => {
        const ruleErrors = this.validateRule(rule, index);
        errors.push(...ruleErrors);
      });

      // Check for potential issues
      if (rules.length === 0) {
        warnings.push('No correction rules found to migrate');
      }

      if (rules.length > 100) {
        warnings.push(`Large number of rules (${rules.length}) - migration may take longer`);
      }

      // Check for duplicate names
      const names = rules.map(r => r.name).filter(Boolean);
      const duplicates = names.filter((name, index) => names.indexOf(name) !== index);
      if (duplicates.length > 0) {
        warnings.push(`Duplicate rule names found: ${duplicates.join(', ')}`);
      }

      return {
        valid: errors.length === 0,
        errors,
        warnings
      };
    } catch (error) {
      errors.push(`Validation failed: ${error instanceof Error ? error.message : String(error)}`);
      return { valid: false, errors, warnings };
    }
  }

  /**
   * Validate a single rule
   */
  private validateRule(rule: any, index: number): string[] {
    const errors: string[] = [];

    if (!rule.name || typeof rule.name !== 'string') {
      errors.push(`Rule ${index}: Missing or invalid name`);
    }

    if (!rule.findPattern || typeof rule.findPattern !== 'string') {
      errors.push(`Rule ${index}: Missing or invalid findPattern`);
    }

    if (rule.replaceWith === undefined || typeof rule.replaceWith !== 'string') {
      errors.push(`Rule ${index}: Missing or invalid replaceWith`);
    }

    if (rule.isRegex && typeof rule.isRegex !== 'boolean') {
      errors.push(`Rule ${index}: Invalid isRegex value`);
    }

    if (rule.isActive && typeof rule.isActive !== 'boolean') {
      errors.push(`Rule ${index}: Invalid isActive value`);
    }

    if (rule.priority !== undefined && typeof rule.priority !== 'number') {
      errors.push(`Rule ${index}: Invalid priority value`);
    }

    // Validate regex patterns
    if (rule.isRegex) {
      try {
        new RegExp(rule.findPattern);
      } catch (error) {
        errors.push(`Rule ${index}: Invalid regex pattern: ${rule.findPattern}`);
      }
    }

    return errors;
  }

  /**
   * Create a backup of current database before migration
   */
  async createBackup(): Promise<string> {
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    const backupPath = `corrections-backup-${timestamp}.db`;

    try {
      const { backupDatabase } = await import('./connection');
      const success = backupDatabase(backupPath);

      if (!success) {
        throw new Error('Backup failed');
      }

      return backupPath;
    } catch (error) {
      throw new Error(`Failed to create backup: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  /**
   * Get migration status and statistics
   */
  getMigrationStatus(): {
    databaseInitialized: boolean;
    totalRules: number;
    activeRules: number;
    canMigrate: boolean;
  } {
    try {
      const { getDatabaseStats } = require('./connection');
      const stats = getDatabaseStats();

      return {
        databaseInitialized: stats !== null,
        totalRules: stats?.totalRules?.count || 0,
        activeRules: stats?.activeRules?.count || 0,
        canMigrate: stats !== null,
      };
    } catch (error) {
      return {
        databaseInitialized: false,
        totalRules: 0,
        activeRules: 0,
        canMigrate: false,
      };
    }
  }
}

/**
 * Standalone migration function for CLI usage
 */
export async function runMigration(localStorageData: any): Promise<void> {
  const migrationService = new MigrationService();

  console.log('Starting corrections migration...');

  // Validate data first
  const validation = migrationService.validateMigrationData(localStorageData);

  if (!validation.valid) {
    console.error('Migration validation failed:');
    validation.errors.forEach(error => console.error(`  - ${error}`));
    return;
  }

  if (validation.warnings.length > 0) {
    console.warn('Migration warnings:');
    validation.warnings.forEach(warning => console.warn(`  - ${warning}`));
  }

  // Create backup
  try {
    const backupPath = await migrationService.createBackup();
    console.log(`Database backup created: ${backupPath}`);
  } catch (error) {
    console.warn('Failed to create backup:', error);
  }

  // Run migration
  const result = await migrationService.migrateFromLocalStorage(localStorageData);

  if (result.success) {
    console.log(`Migration completed successfully! Imported ${result.importedCount} correction rules.`);
  } else {
    console.error('Migration failed:');
    result.errors.forEach(error => console.error(`  - ${error}`));
  }

  // Show final status
  const status = migrationService.getMigrationStatus();
  console.log(`Final status: ${status.totalRules} total rules, ${status.activeRules} active rules`);
}

