    setClause.push('updated_at = ?');
    params.push(new Date().toISOString());
    params.push(id);

    const stmt = this.db.prepare(`
      UPDATE project_templates
      SET ${setClause.join(', ')}
      WHERE id = ? AND archived_at IS NULL
    `);

    stmt.run(...params);
    return this.getTemplate(id);
  }

