 * Epic 9.2.1 - Workspace Data Access Object
 * Database operations for collaborative workspace functionality
 */

import { Database } from 'better-sqlite3';
import { v4 as uuidv4 } from 'uuid';
import {
  Workspace,
  CreateWorkspace,
  UpdateWorkspace,
  Project,
  CreateProject,
  UpdateProject,
  Resource,
  CreateResource,
  ACLRole,
  CreateACLRole,
