  CreateUserMembership,
  ActivityEvent,
  CreateActivityEvent,
  Comment,
  CreateComment,
  UpdateComment,
  Notification,
  CreateNotification,
  User,
  CreateUser,
  UpdateUser,
  UserSession,
  CreateUserSession,
  OAuthState,
  WorkspaceWithMembership,
  ProjectWithStats,
  UserWithRoles,
  ActivityEventWithActorInfo,
  CommentWithReplies,
