  async logSecurityEvent(
    userId: string | null,
    eventType: string,
    details: Record<string, any> = {},
    ipAddress?: string,
    userAgent?: string,
    workspaceId?: string
  ): Promise<void> {
    const id = uuidv4();
    const now = new Date().toISOString();

    const stmt = this.db.prepare(`
      INSERT INTO security_audit_log (
        id, user_id, event_type, details, ip_address, user_agent, workspace_id, created_at
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    `);

    stmt.run(
      id,
      userId,
      eventType,
      JSON.stringify(details),
      ipAddress || null,
      userAgent || null,
      workspaceId || null,
      now
    );
  }

  async getSecurityAuditLog(
    userId?: string,
    eventTypes?: string[],
    startDate?: Date,
    endDate?: Date,
    limit: number = 100
  ): Promise<any[]> {
    let query = 'SELECT * FROM security_audit_log WHERE 1=1';
    const params: any[] = [];

    if (userId) {
      query += ' AND user_id = ?';
      params.push(userId);
    }

    if (eventTypes && eventTypes.length > 0) {
      query += ` AND event_type IN (${eventTypes.map(() => '?').join(', ')})`;
      params.push(...eventTypes);
    }

    if (startDate) {
      query += ' AND created_at >= ?';
      params.push(startDate.toISOString());
    }

    if (endDate) {
      query += ' AND created_at <= ?';
      params.push(endDate.toISOString());
    }

    query += ' ORDER BY created_at DESC LIMIT ?';
    params.push(limit);

    const stmt = this.db.prepare(query);
    const rows = stmt.all(...params) as any[];

    return rows.map(row => ({
      id: row.id,
      user_id: row.user_id,
      event_type: row.event_type,
      details: JSON.parse(row.details),
      ip_address: row.ip_address,
      user_agent: row.user_agent,
      workspace_id: row.workspace_id,
      created_at: new Date(row.created_at),
    }));
  }

  // ====== USER WORKSPACE OPERATIONS ======

  async getUserWorkspaces(userId: string): Promise<Array<{
    id: string;
    name: string;
    role: string;
    permissions: number;
  }>> {
    const stmt = this.db.prepare(`
      SELECT w.id, w.name, um.role, um.permissions
      FROM workspaces w
      JOIN user_memberships um ON w.id = um.workspace_id
      WHERE um.user_id = ? AND w.archived_at IS NULL
      ORDER BY w.name
    `);

    const rows = stmt.all(userId) as any[];
    return rows.map(row => ({
      id: row.id,
      name: row.name,
      role: row.role,
      permissions: row.permissions,
    }));
  }
}

