  }),
  variables: z.record(z.string(), z.unknown()),
  grammar: z.record(z.string(), z.union([
    z.array(z.string()), // ArrayRule
    z.array(z.object({   // WeightedArrayRule
      text: z.string(),
      weight: z.number().optional(),
    })),
    z.object({           // ConditionalRule
      type: z.literal('conditional'),
      cases: z.array(z.object({
        condition: z.string(),
        value: z.string(),
      })),
    }),
    z.object({           // SequentialRule
      type: z.literal('sequential'),
      items: z.array(z.string()),
    }),
    z.union([            // IncludeRule (two formats)
      z.object({ $include: z.string() }),
      z.array(z.union([
        z.object({ _meta: z.record(z.string(), z.unknown()).optional() }),
        z.object({ $include: z.string() }),
      ])),
    ]),
    z.object({           // ModifierChainRule
      type: z.literal('modifier_chain'),
      base: z.string(),
      mods: z.array(z.string()),
    }),
  ])),
  entry_points: z.object({
    default: z.string(),
    alternatives: z.array(z.string()).optional(),
  }),
  lockedValues: z.record(z.string(), z.string()).optional(),
  seed: z.number().optional(),
});

export type GeneratorBundle = z.infer<typeof GeneratorBundleSchema>;

/**
 * Converts a graph to a generator bundle format
 * @param graph Graph to convert
 * @param options Additional metadata for the bundle
 * @returns A GeneratorBundle compatible with the Randomizer Engine
 */
export function graphToBundle(
  graph: Graph, 
  options: {
    name: string;
    version?: string;
    author?: string;
  }
): GeneratorBundle {
  // Create default metadata
  const metadata = {
    name: options.name,
    version: options.version || '1.0.0',
    author: options.author || 'PromptScape Graph Editor',
    created: new Date().toISOString(),
    debug: {
      seed: typeof graph.seed === 'number' ? graph.seed : undefined,
      originGraphGuid: undefined, // Could be added as an optional parameter if needed
    },
  };

  // Initialize bundle structure
  const bundle: GeneratorBundle = {
    metadata,
    variables: {},
    grammar: {},
    entry_points: {
      default: 'main',
      alternatives: [],
    },
    seed: typeof graph.seed === 'number' ? graph.seed : undefined,
  };

  // Find all variable declarations in the graph
  const variables: Record<string, any> = {};
  const outputNodes: Node[] = [];
  const nodeMap = new Map<string, Node>();

  // First pass - catalog all nodes and extract variables
  graph.nodes.forEach(node => {
    nodeMap.set(node.id, node);

    if (node.type === 'SetVariable') {
      variables[node.key] = node.value;
    }

    if (node.type === 'Output') {
      outputNodes.push(node);
    }
  });

  // Add variables to bundle
  bundle.variables = variables;

  // Create grammar rules for each node
  graph.nodes.forEach(node => {
    const ruleId = node.id;
    bundle.grammar[ruleId] = convertNodeToRule(node, nodeMap);
  });

  // Set the default entry point to the first output node
  if (outputNodes.length > 0) {
    bundle.entry_points.default = outputNodes[0].id;

    // If there are multiple output nodes, add them as alternatives
    if (outputNodes.length > 1) {
      bundle.entry_points.alternatives = outputNodes.slice(1).map(n => n.id);
    }
  }

  return bundle;
}

/**
 * Convert a node to its corresponding grammar rule in the GeneratorBundle format
 */
function convertNodeToRule(node: Node, nodeMap: Map<string, Node>): any {
  switch (node.type) {
    case 'WeightedChoice':
      // Convert to weighted array rule
      return node.choices.map(choice => ({
        text: choice.value,
        weight: choice.weight,
      }));

    case 'Concat':
      // If inputs exist, create a sequential rule
      if (node.inputs && node.inputs.length > 0) {
        return {
          type: 'sequential',
          items: node.inputs,
        };
      }
      return ['']; // Empty concat gives empty string

    case 'Output':
      // Output nodes reference their input
      if (node.inputs && node.inputs.length > 0) {
        return [node.inputs[0]];
      }
      return [''];

    case 'Include':
      // Create an include rule
      return { $include: node.name };

    case 'SetVariable':
      // Variable setting doesn't produce content directly
      return [''];

    case 'GetVariable':
      // Create a reference to the variable
      return [`$${node.key}`];

    default:
      // For unknown node types, return empty
      return [''];
  }
}

/**
 * Validates a GeneratorBundle against the schema
 * @param bundle The bundle to validate
 * @returns True if valid, false otherwise
 */
export function validateGeneratorBundle(bundle: any): boolean {
  try {
    GeneratorBundleSchema.parse(bundle);
    return true;
  } catch (error) {
    return false;
  }
}

/**
 * Converts a GeneratorBundle back to a Graph format
 * @param bundle GeneratorBundle to convert
 * @returns Graph compatible with the editor
 */
export function bundleToGraph(bundle: GeneratorBundle): Graph {
  // Validate the bundle first
  if (!validateGeneratorBundle(bundle)) {
    throw new Error('Invalid GeneratorBundle format');
  }

  // Initialize the graph structure
  const graph: Graph = {
    nodes: [],
    seed: bundle.seed
  };

  // Track created nodes by ID to avoid duplicates
  const createdNodeIds = new Set<string>();

  // Process variables first
  Object.entries(bundle.variables).forEach(([key, value]) => {
    const nodeId = `var_${key}`;
    graph.nodes.push({
      id: nodeId,
      type: 'SetVariable',
      key,
      value
    });
    createdNodeIds.add(nodeId);
  });

  // Process grammar rules
  Object.entries(bundle.grammar).forEach(([ruleId, rule]) => {
    // Skip if we already created this node (from variables)
    if (createdNodeIds.has(ruleId)) return;

    const node = convertRuleToNode(ruleId, rule);
    if (node) {
      graph.nodes.push(node);
      createdNodeIds.add(ruleId);
    }
  });

  // Process connections between nodes
  Object.entries(bundle.grammar).forEach(([ruleId, rule]) => {
    // Find referenced nodes and establish connections
    const references = findNodeReferences(rule);
    if (references.length > 0) {
      const node = graph.nodes.find(n => n.id === ruleId);
      if (node) {
        node.inputs = references;
      }
    }
  });

  // Ensure at least one output node exists
  ensureOutputNode(graph, bundle.entry_points.default);

  return graph;
}

/**
 * Converts a grammar rule to a node in the graph
 */
function convertRuleToNode(id: string, rule: any): Node | null {
  // Handle weighted array rule (WeightedChoice)
  if (Array.isArray(rule) && rule.length > 0 && typeof rule[0] === 'object' && 'text' in rule[0]) {
    return {
      id,
      type: 'WeightedChoice',
      choices: rule.map(item => ({
        value: item.text,
        weight: item.weight || 1
      }))
    };
  }

  // Handle simple array rule (can be Output or Include depending on content)
  if (Array.isArray(rule) && rule.length > 0 && typeof rule[0] === 'string') {
    return {
      id,
      type: 'Output',
    };
  }

  // Handle include rule
  if (!Array.isArray(rule) && typeof rule === 'object' && '$include' in rule) {
    return {
      id,
      type: 'Include',
      name: rule.$include
    };
  }

  // Handle sequential rule (Concat)
  if (!Array.isArray(rule) && typeof rule === 'object' && rule.type === 'sequential') {
    return {
      id,
      type: 'Concat',
    };
  }

  // Handle conditional rule
  if (!Array.isArray(rule) && typeof rule === 'object' && rule.type === 'conditional') {
    // For now, convert conditionals to weighted choices as a simplification
    return {
      id,
      type: 'WeightedChoice',
      choices: rule.cases.map((c: { condition: string; value: string }) => ({
        value: c.value,
        weight: 1 // Equal weights as a default
      }))
    };
  }

  // Handle modifier chain (simplify to concat for now)
  if (!Array.isArray(rule) && typeof rule === 'object' && rule.type === 'modifier_chain') {
    return {
      id,
      type: 'Concat',
    };
  }

  // Unknown rule type
  console.warn(`Unsupported rule type for ID ${id}:`, rule);
  return null;
}

/**
 * Find references to other nodes in a rule
 */
function findNodeReferences(rule: any): string[] {
  const refs: string[] = [];

  // Handle sequential rule
  if (!Array.isArray(rule) && typeof rule === 'object' && rule.type === 'sequential') {
    return rule.items || [];
  }

  // Handle array rule that references other rules
  if (Array.isArray(rule)) {
    rule.forEach(item => {
      if (typeof item === 'string' && !item.startsWith('$')) {
        refs.push(item);
      }
    });
  }

  // Handle modifier chain
  if (!Array.isArray(rule) && typeof rule === 'object' && rule.type === 'modifier_chain') {
    if (rule.base) refs.push(rule.base);
  }

  return refs;
}

/**
 * Ensures that at least one output node exists for the entry point
 */
function ensureOutputNode(graph: Graph, entryPointId: string): void {
  // Check if entry point exists as a node
  const entryExists = graph.nodes.some(n => n.id === entryPointId);

  if (!entryExists) {
    // Create a default output node
    graph.nodes.push({
      id: entryPointId,
      type: 'Output'
    });
  } else {
    // If node exists but isn't an output, add an output node that references it
    const isOutput = graph.nodes.some(n => n.id === entryPointId && n.type === 'Output');
    if (!isOutput) {
      const outputId = `output_${entryPointId}`;
      graph.nodes.push({
        id: outputId,
        type: 'Output',
        inputs: [entryPointId]
      });
    }
  }

  // Make sure at least one output node exists in the graph
  const hasOutput = graph.nodes.some(n => n.type === 'Output');
  if (!hasOutput) {
    graph.nodes.push({
      id: 'default_output',
      type: 'Output'
    });
  }
}

/**
 * Graph Validation Engine for PromptSpaghetti
 * 
 * This module provides comprehensive validation for graph structures to ensure
 * they can be safely executed. It checks for common issues like:
 * - Missing required nodes or inputs
 * - Cycles in the graph
 * - Disconnected components
 * - Invalid configuration values
 */

import { Graph, Node, NodeTypeEnum } from '../../packages/core/graphSchema';
import { z } from 'zod';

export interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
}

export interface ValidationError {
  code: string;
  message: string;
  nodeId?: string;
  path?: string;
  severity: 'error' | 'warning';
}

// Basic node schema with required fields
const nodeSchema = z.object({
  id: z.string().min(1, "Node ID cannot be empty"),
  type: z.enum([
    'WeightedChoice',
    'Concat',
    'Output',
    'Include',
    'SetVariable',
    'GetVariable'
  ], { errorMap: () => ({ message: "Invalid node type" }) }),
  inputs: z.array(z.string()).optional(),
});

// Graph schema with required fields
const graphSchema = z.object({
  nodes: z.array(nodeSchema).min(1, "Graph must contain at least one node"),
  seed: z.union([z.number(), z.string(), z.undefined()]).optional(),
});

/**
 * Validates basic graph structure using Zod schema validation
 */
function validateGraphStructure(graph: any): ValidationError[] {
  try {
    graphSchema.parse(graph);
    return [];
  } catch (error) {
    if (error instanceof z.ZodError) {
      return error.errors.map(err => ({
        code: 'INVALID_STRUCTURE',
        message: err.message,
        path: err.path.join('.'),
        severity: 'error'
      }));
    }
    return [{
      code: 'INVALID_STRUCTURE',
      message: 'Invalid graph structure',
      severity: 'error'
    }];
  }
}

/**
 * Validates node references in the graph
 */
function validateNodeReferences(graph: Graph): ValidationError[] {
  const errors: ValidationError[] = [];
  const nodeIds = new Set(graph.nodes.map(node => node.id));

  for (const node of graph.nodes) {
    if (node.inputs) {
      for (const inputId of node.inputs) {
        if (!nodeIds.has(inputId)) {
          errors.push({
            code: 'MISSING_NODE_REFERENCE',
            message: `Node "${node.id}" references non-existent node "${inputId}"`,
            nodeId: node.id,
            severity: 'error'
          });
        }
      }
    }
  }

  return errors;
}

/**
 * Validates that the graph has at least one Output node
 */
function validateOutputNodes(graph: Graph): ValidationError[] {
  const errors: ValidationError[] = [];
  const hasOutputNode = graph.nodes.some(node => node.type === 'Output');

  if (!hasOutputNode) {
    errors.push({
      code: 'NO_OUTPUT_NODES',
      message: 'Graph must have at least one Output node',
      severity: 'error'
    });
  }

  return errors;
}

/**
 * Detects cycles in the graph
 * Uses depth-first search with path tracking to identify cycles
 */
function detectCycles(graph: Graph): ValidationError[] {
  const errors: ValidationError[] = [];
  const nodeMap = new Map(graph.nodes.map(node => [node.id, node]));
  const visited = new Set<string>();
  const path = new Set<string>();

  function dfs(nodeId: string): boolean {
    // Already in the current path -> cycle detected
    if (path.has(nodeId)) {
      errors.push({
        code: 'CYCLE_DETECTED',
        message: `Cycle detected involving node "${nodeId}"`,
        nodeId: nodeId,
        severity: 'error'
      });
      return true;
    }

    // Already visited this node in a different path, no cycle here
    if (visited.has(nodeId)) {
      return false;
    }

    const node = nodeMap.get(nodeId);
    if (!node) return false;

    // Mark node as visited and add to current path
    visited.add(nodeId);
    path.add(nodeId);

    // Check all inputs recursively
    if (node.inputs && node.inputs.length > 0) {
      for (const inputId of node.inputs) {
        if (dfs(inputId)) {
          return true; // Cycle found
        }
      }
    }

    // Remove from current path when backtracking
    path.delete(nodeId);
    return false;
  }

  // Run DFS from each node to detect cycles
  for (const node of graph.nodes) {
    dfs(node.id);
  }

  return errors;
}

/**
 * Validates node configurations based on their types
 */
function validateNodeConfigurations(graph: Graph): ValidationError[] {
  const errors: ValidationError[] = [];

  for (const node of graph.nodes) {
    switch (node.type) {
      case 'WeightedChoice':
        // Validate that choices array exists and is not empty
        if (!('choices' in node) || !Array.isArray(node.choices) || node.choices.length === 0) {
          errors.push({
            code: 'INVALID_WEIGHTEDCHOICE_CONFIG',
            message: `WeightedChoice node "${node.id}" must have a non-empty array of choices`,
            nodeId: node.id,
            severity: 'error'
          });
        } else {
          // Validate that each choice has a value and positive weight
          for (let i = 0; i < node.choices.length; i++) {
            const choice = node.choices[i];
            if (!choice || typeof choice !== 'object') {
              errors.push({
                code: 'INVALID_WEIGHTEDCHOICE_CONFIG',
                message: `WeightedChoice node "${node.id}" has an invalid choice at index ${i}`,
                nodeId: node.id,
                severity: 'error'
              });
            } else if (!('value' in choice) || typeof choice.value !== 'string') {
              errors.push({
                code: 'INVALID_WEIGHTEDCHOICE_CONFIG',
                message: `WeightedChoice node "${node.id}" has a choice without a string value at index ${i}`,
                nodeId: node.id,
                severity: 'error'
              });
            } else if (!('weight' in choice) || typeof choice.weight !== 'number' || choice.weight <= 0) {
              errors.push({
                code: 'INVALID_WEIGHTEDCHOICE_CONFIG',
                message: `WeightedChoice node "${node.id}" has a choice without a positive weight at index ${i}`,
                nodeId: node.id,
                severity: 'error'
              });
            }
          }
        }
        break;

      case 'Include':
        if (!('name' in node) || typeof node.name !== 'string' || node.name.trim() === '') {
          errors.push({
            code: 'INVALID_INCLUDE_CONFIG',
            message: `Include node "${node.id}" must have a non-empty name property`,
            nodeId: node.id,
            severity: 'error'
          });
        }
        break;

      case 'SetVariable':
      case 'GetVariable':
        if (!('key' in node) || typeof node.key !== 'string' || node.key.trim() === '') {
          errors.push({
            code: 'INVALID_VARIABLE_CONFIG',
            message: `${node.type} node "${node.id}" must have a non-empty key property`,
            nodeId: node.id,
            severity: 'error'
          });
        }
        break;
    }
  }

  return errors;
}

/**
 * Performs a full validation on the graph
 */
export function validateGraph(graphData: unknown): ValidationResult {
  // First check if it's a valid graph structure
  const structureErrors = validateGraphStructure(graphData);
  if (structureErrors.length > 0) {
    return {
      valid: false,
      errors: structureErrors
    };
  }

  // Now we know it's a valid Graph type
  const graph = graphData as Graph;

  // Combine all validation results
  const referenceErrors = validateNodeReferences(graph);
  const cycleErrors = detectCycles(graph);
  const outputErrors = validateOutputNodes(graph);
  const configErrors = validateNodeConfigurations(graph);

  const allErrors = [
    ...structureErrors,
    ...referenceErrors,
    ...cycleErrors,
    ...outputErrors,
    ...configErrors
  ];

  return {
    valid: allErrors.length === 0,
    errors: allErrors
  };
}

