  }

  // Review operations
  async createReview(review: Partial<TemplateReview>, client?: PoolClient): Promise<TemplateReview> {
    const useClient = client || this.pool;

    // Check if user has purchased the template
    const purchaseQuery = `
      SELECT id FROM marketplace_purchases 
      WHERE buyer_id = $1 AND template_id = $2 AND status = 'succeeded'
      LIMIT 1
    `;
    const purchaseResult = await useClient.query(purchaseQuery, [review.buyer_id, review.template_id]);
    const verifiedPurchase = purchaseResult.rows.length > 0;
    const purchaseId = verifiedPurchase ? purchaseResult.rows[0].id : null;

    const query = `
      INSERT INTO template_reviews (
        template_id, buyer_id, purchase_id, stars, comment,
        verified_purchase, moderation_status
      ) VALUES ($1, $2, $3, $4, $5, $6, $7)
      RETURNING *
    `;

    const values = [
      review.template_id,
      review.buyer_id,
      purchaseId,
      review.stars,
      review.comment || null,
      verifiedPurchase,
      ModerationStatus.PENDING
    ];

    const result = await useClient.query(query, values);
    return result.rows[0];
  }

  async getTemplateReviews(templateId: string, limit: number = 20): Promise<ReviewWithDetails[]> {
    const query = `
      SELECT 
        r.*,
        u.name as buyer_name
      FROM template_reviews r
      JOIN users u ON r.buyer_id = u.id
      WHERE r.template_id = $1 AND r.moderation_status = 'approved'
      ORDER BY r.created_at DESC
      LIMIT $2
    `;

    const result = await this.pool.query(query, [templateId, limit]);
    return result.rows.map(row => ({
      ...row,
      buyer: {
        id: row.buyer_id,
        name: row.buyer_name,
        verified: row.verified_purchase
      }
    }));
  }

  // Analytics and events
  async recordEvent(event: Partial<MarketplaceEvent>, client?: PoolClient): Promise<void> {
    const useClient = client || this.pool;

    const query = `
      INSERT INTO marketplace_events (
        event_type, user_id, template_id, version_id,
        session_id, metadata, ip_address, user_agent
      ) VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
    `;

    const values = [
      event.event_type,
      event.user_id || null,
      event.template_id,
      event.version_id || null,
      event.session_id || null,
      event.metadata || {},
      event.ip_address || null,
      event.user_agent || null
    ];

    await useClient.query(query, values);
  }

  // Categories
  async getCategories(): Promise<TemplateCategory[]> {
    const query = `
      SELECT * FROM template_categories 
      WHERE is_active = true 
      ORDER BY sort_order, name
    `;

    const result = await this.pool.query(query);
    return result.rows;
  }

  // Utility methods
  async refreshSearchIndex(): Promise<void> {
    await this.pool.query('SELECT refresh_marketplace_search_index()');
  }

  async transaction<T>(callback: (client: PoolClient) => Promise<T>): Promise<T> {
    const client = await this.pool.connect();
    try {
      await client.query('BEGIN');
      const result = await callback(client);
      await client.query('COMMIT');
      return result;
    } catch (error) {
      await client.query('ROLLBACK');
      throw error;
    } finally {
      client.release();
    }
  }
}

// Epic 16 Marketplace - Elasticsearch Integration Service
import { Injectable } from '@nestjs/common';
import { Client } from '@elastic/elasticsearch';
import { SearchFilters, TemplateWithStats } from './types';
import { MarketplaceDAO } from './dao';
import { Pool } from 'pg';

interface ElasticsearchTemplate {
  id: string;
  title: string;
  description: string;
  tags: string[];
  price_cents: number;
  avg_rating: number;
  total_reviews: number;
  total_purchases: number;
  categories: string[];
  owner_name: string;
  owner_verified: boolean;
  is_ai_generated: boolean;
  claude_compat: string[];
  featured_at?: string;
  created_at: string;
  updated_at: string;
}

interface SearchResponse {
  templates: TemplateWithStats[];
  total: number;
  aggregations?: {
    categories: Array<{ name: string; count: number }>;
    price_ranges: Array<{ min: number; max: number; count: number }>;
    avg_ratings: Array<{ rating: number; count: number }>;
    tags: Array<{ name: string; count: number }>;
  };
}

@Injectable()
export class ElasticsearchService {
  private client: Client;
  private dao: MarketplaceDAO;
  private readonly INDEX_NAME = 'marketplace_templates';

  constructor(private pool: Pool) {
    this.dao = new MarketplaceDAO(pool);

    // Initialize Elasticsearch client
    this.client = new Client({
      node: process.env.ELASTICSEARCH_URL || 'http://localhost:9200',
      auth: process.env.ELASTICSEARCH_AUTH ? {
        username: process.env.ELASTICSEARCH_USERNAME || 'elastic',
        password: process.env.ELASTICSEARCH_PASSWORD || 'changeme'
      } : undefined,
      requestTimeout: 30000,
      maxRetries: 3
    });

    this.initializeIndex();
  }

  /**
   * Advanced search with Elasticsearch
   */
  async searchTemplates(filters: SearchFilters): Promise<SearchResponse> {
    try {
      const query = this.buildElasticsearchQuery(filters);
      const response = await this.client.search({
        index: this.INDEX_NAME,
        body: query,
        size: filters.limit || 20,
        from: ((filters.page || 1) - 1) * (filters.limit || 20)
      });

      const templates = await this.processSearchResults(response.body);
      const aggregations = this.processAggregations(response.body.aggregations);

      return {
        templates,
        total: response.body.hits.total.value,
        aggregations
      };
    } catch (error) {
      console.error('Elasticsearch search error:', error);
      // Fallback to PostgreSQL search
      return this.fallbackToPostgresSearch(filters);
    }
  }

  /**
   * Get search suggestions and autocomplete
   */
  async getSearchSuggestions(query: string, limit: number = 10): Promise<string[]> {
    try {
      const response = await this.client.search({
        index: this.INDEX_NAME,
        body: {
          suggest: {
            title_suggest: {
              prefix: query,
              completion: {
                field: 'title_suggest',
                size: limit,
                skip_duplicates: true
              }
            },
            tag_suggest: {
              prefix: query,
              completion: {
                field: 'tags_suggest',
                size: limit,
                skip_duplicates: true
              }
            }
          }
        }
      });

      const suggestions = new Set<string>();

      // Add title suggestions
      response.body.suggest.title_suggest[0].options.forEach((option: any) => {
        suggestions.add(option.text);
      });

      // Add tag suggestions
      response.body.suggest.tag_suggest[0].options.forEach((option: any) => {
        suggestions.add(option.text);
      });

      return Array.from(suggestions).slice(0, limit);
    } catch (error) {
      console.error('Error getting search suggestions:', error);
      return [];
    }
  }

  /**
   * Index a template in Elasticsearch
   */
  async indexTemplate(template: TemplateWithStats): Promise<void> {
    try {
      const doc: ElasticsearchTemplate = {
        id: template.id,
        title: template.title,
        description: template.description || '',
        tags: template.tags,
        price_cents: template.price_cents,
        avg_rating: template.avg_rating,
        total_reviews: template.total_reviews,
        total_purchases: template.total_purchases,
        categories: template.categories || [],
        owner_name: template.owner?.name || '',
        owner_verified: template.owner?.verified || false,
        is_ai_generated: template.is_ai_generated || false,
        claude_compat: template.claude_compat,
        featured_at: template.featured_at,
        created_at: template.created_at,
        updated_at: template.updated_at
      };

      await this.client.index({
        index: this.INDEX_NAME,
        id: template.id,
        body: doc
      });
    } catch (error) {
      console.error('Error indexing template:', error);
    }
  }

  /**
   * Remove a template from Elasticsearch
   */
  async removeTemplate(templateId: string): Promise<void> {
    try {
      await this.client.delete({
        index: this.INDEX_NAME,
        id: templateId
      });
    } catch (error) {
      console.error('Error removing template from index:', error);
    }
  }

  /**
   * Reindex all templates from database
   */
  async reindexAllTemplates(): Promise<void> {
    try {
      // Delete existing index
      await this.client.indices.delete({
        index: this.INDEX_NAME,
        ignore_unavailable: true
      });

      // Recreate index
      await this.initializeIndex();

      // Get all templates from database
      const templates = await this.dao.searchTemplates({ limit: 10000 });

      // Bulk index templates
      if (templates.templates.length > 0) {
        const body = templates.templates.flatMap(template => [
          { index: { _index: this.INDEX_NAME, _id: template.id } },
          this.templateToElasticsearchDoc(template)
        ]);

        await this.client.bulk({ body });
      }

      console.log(`Reindexed ${templates.templates.length} templates`);
    } catch (error) {
      console.error('Error reindexing templates:', error);
      throw error;
    }
  }

  /**
   * Get search analytics
   */
  async getSearchAnalytics(timeRange: string = '7d'): Promise<any> {
    try {
      const response = await this.client.search({
        index: this.INDEX_NAME,
        body: {
          size: 0,
          query: {
            range: {
              created_at: {
                gte: `now-${timeRange}`
              }
            }
          },
          aggs: {
            popular_searches: {
              terms: {
                field: 'title.keyword',
                size: 10
              }
            },
            category_distribution: {
              terms: {
                field: 'categories.keyword',
                size: 20
              }
            },
            price_distribution: {
              histogram: {
                field: 'price_cents',
                interval: 500
              }
            },
            rating_distribution: {
              histogram: {
                field: 'avg_rating',
                interval: 0.5
              }
            }
          }
        }
      });

      return response.body.aggregations;
    } catch (error) {
      console.error('Error getting search analytics:', error);
      return {};
    }
  }

  /**
   * Initialize Elasticsearch index with proper mappings
   */
  private async initializeIndex(): Promise<void> {
    try {
      const indexExists = await this.client.indices.exists({
        index: this.INDEX_NAME
      });

      if (!indexExists.body) {
        await this.client.indices.create({
          index: this.INDEX_NAME,
          body: {
            settings: {
              number_of_shards: 1,
              number_of_replicas: 0,
              analysis: {
                analyzer: {
                  custom_text: {
                    type: 'custom',
                    tokenizer: 'standard',
                    filter: ['lowercase', 'stop', 'stemmer']
                  }
                }
              }
            },
            mappings: {
              properties: {
                id: { type: 'keyword' },
                title: {
                  type: 'text',
                  analyzer: 'custom_text',
                  fields: {
                    keyword: { type: 'keyword' },
                    suggest: { type: 'completion' }
                  }
                },
                description: {
                  type: 'text',
                  analyzer: 'custom_text'
                },
                tags: {
                  type: 'keyword',
                  fields: {
                    suggest: { type: 'completion' }
                  }
                },
                price_cents: { type: 'integer' },
                avg_rating: { type: 'float' },
                total_reviews: { type: 'integer' },
                total_purchases: { type: 'integer' },
                categories: { type: 'keyword' },
                owner_name: {
                  type: 'text',
                  fields: {
                    keyword: { type: 'keyword' }
                  }
                },
                owner_verified: { type: 'boolean' },
                is_ai_generated: { type: 'boolean' },
                claude_compat: { type: 'keyword' },
                featured_at: { type: 'date' },
                created_at: { type: 'date' },
                updated_at: { type: 'date' }
              }
            }
          }
        });

        console.log('Elasticsearch index created successfully');
      }
    } catch (error) {
      console.error('Error initializing Elasticsearch index:', error);
    }
  }

  /**
   * Build Elasticsearch query from filters
   */
  private buildElasticsearchQuery(filters: SearchFilters): any {
    const must: any[] = [];
    const filter: any[] = [];

    // Text search
    if (filters.query) {
      must.push({
        multi_match: {
          query: filters.query,
          fields: ['title^3', 'description^2', 'tags^2', 'categories', 'owner_name'],
          type: 'best_fields',
          fuzziness: 'AUTO'
        }
      });
    }

    // Category filter
    if (filters.categories && filters.categories.length > 0) {
      filter.push({
        terms: {
          categories: filters.categories
        }
      });
    }

    // Tag filter
    if (filters.tags && filters.tags.length > 0) {
      filter.push({
        terms: {
          tags: filters.tags
        }
      });
    }

    // Price filters
    if (filters.price_min !== undefined || filters.price_max !== undefined) {
      const range: any = {};
      if (filters.price_min !== undefined) range.gte = filters.price_min;
      if (filters.price_max !== undefined) range.lte = filters.price_max;

      filter.push({
        range: {
          price_cents: range
        }
      });
    }

    // Rating filter
    if (filters.rating_min !== undefined) {
      filter.push({
        range: {
          avg_rating: {
            gte: filters.rating_min
          }
        }
      });
    }

    // Free/paid filter
    if (filters.is_free === true) {
      filter.push({
        term: {
          price_cents: 0
        }
      });
    } else if (filters.is_free === false) {
      filter.push({
        range: {
          price_cents: {
            gt: 0
          }
        }
      });
    }

    // Featured filter
    if (filters.is_featured === true) {
      filter.push({
        exists: {
          field: 'featured_at'
        }
      });
    }

    // Claude model compatibility
    if (filters.claude_models && filters.claude_models.length > 0) {
      filter.push({
        terms: {
          claude_compat: filters.claude_models
        }
      });
    }

    // Build sort
    const sort = this.buildElasticsearchSort(filters.sort_by, !!filters.query);

    // Build aggregations
    const aggs = {
      categories: {
        terms: {
          field: 'categories',
          size: 50
        }
      },
      price_ranges: {
        range: {
          field: 'price_cents',
          ranges: [
            { key: 'free', to: 1 },
            { key: 'low', from: 1, to: 1000 },
            { key: 'medium', from: 1000, to: 5000 },
            { key: 'high', from: 5000 }
          ]
        }
      },
      avg_ratings: {
        histogram: {
          field: 'avg_rating',
          interval: 1,
          min_doc_count: 1
        }
      },
      tags: {
        terms: {
          field: 'tags',
          size: 20
        }
      }
    };

    return {
      query: {
        bool: {
          must: must.length > 0 ? must : [{ match_all: {} }],
          filter
        }
      },
      sort,
      aggs
    };
  }

  /**
   * Build Elasticsearch sort
   */
  private buildElasticsearchSort(sortBy?: string, hasQuery: boolean = false): any[] {
    switch (sortBy) {
      case 'price_asc':
        return [{ price_cents: { order: 'asc' } }];
      case 'price_desc':
        return [{ price_cents: { order: 'desc' } }];
      case 'rating':
        return [
          { avg_rating: { order: 'desc' } },
          { total_reviews: { order: 'desc' } }
        ];
      case 'popularity':
        return [
          { total_purchases: { order: 'desc' } },
          { avg_rating: { order: 'desc' } }
        ];
      case 'newest':
        return [{ created_at: { order: 'desc' } }];
      case 'oldest':
        return [{ created_at: { order: 'asc' } }];
      case 'relevance':
      default:
        if (hasQuery) {
          return [
            '_score',
            { featured_at: { order: 'desc', missing: '_last' } },
            { avg_rating: { order: 'desc' } }
          ];
        } else {
          return [
            { featured_at: { order: 'desc', missing: '_last' } },
            { avg_rating: { order: 'desc' } },
            { total_purchases: { order: 'desc' } }
          ];
        }
    }
  }

  /**
   * Process Elasticsearch search results
   */
  private async processSearchResults(esResponse: any): Promise<TemplateWithStats[]> {
    const templateIds = esResponse.hits.hits.map((hit: any) => hit._id);

    if (templateIds.length === 0) return [];

    // Get full template data from PostgreSQL to ensure data consistency
    const placeholders = templateIds.map((_: any, i: number) => `$${i + 1}`).join(', ');
    const query = `
      SELECT 
        t.*,
        stats.total_purchases,
        stats.total_reviews,
        stats.avg_rating,
        stats.total_revenue,
        stats.last_purchase_at,
        stats.total_views,
        stats.total_previews,
        array_agg(DISTINCT c.name) FILTER (WHERE c.name IS NOT NULL) as categories,
        u.name as owner_name,
        u.email as owner_email
      FROM marketplace_templates t
      LEFT JOIN marketplace_template_stats stats ON t.id = stats.id
      LEFT JOIN template_category_mappings tcm ON t.id = tcm.template_id
      LEFT JOIN template_categories c ON tcm.category_id = c.id
      LEFT JOIN users u ON t.owner_id = u.id
      WHERE t.id IN (${placeholders}) AND t.status = 'listed'
      GROUP BY t.id, stats.total_purchases, stats.total_reviews, stats.avg_rating, 
               stats.total_revenue, stats.last_purchase_at, stats.total_views, 
               stats.total_previews, u.name, u.email
    `;

    const result = await this.pool.query(query, templateIds);

    // Preserve Elasticsearch order
    const templateMap = new Map(result.rows.map(row => [row.id, {
      ...row,
      categories: row.categories || [],
      total_purchases: row.total_purchases || 0,
      total_reviews: row.total_reviews || 0,
      avg_rating: parseFloat(row.avg_rating) || 0,
      total_revenue: row.total_revenue || 0,
      total_views: row.total_views || 0,
      total_previews: row.total_previews || 0,
      owner: {
        id: row.owner_id,
        name: row.owner_name,
        email: row.owner_email,
        verified: true
      }
    }]));

    return templateIds.map((id: string) => templateMap.get(id)).filter(Boolean);
  }

  /**
   * Process Elasticsearch aggregations
   */
  private processAggregations(aggs: any): any {
    if (!aggs) return undefined;

    return {
      categories: aggs.categories?.buckets?.map((bucket: any) => ({
        name: bucket.key,
        count: bucket.doc_count
      })) || [],
      price_ranges: aggs.price_ranges?.buckets?.map((bucket: any) => ({
        min: bucket.from || 0,
        max: bucket.to || Infinity,
        count: bucket.doc_count
      })) || [],
      avg_ratings: aggs.avg_ratings?.buckets?.map((bucket: any) => ({
        rating: bucket.key,
        count: bucket.doc_count
      })) || [],
      tags: aggs.tags?.buckets?.map((bucket: any) => ({
        name: bucket.key,
        count: bucket.doc_count
      })) || []
    };
  }

  /**
   * Fallback to PostgreSQL search when Elasticsearch fails
   */
  private async fallbackToPostgresSearch(filters: SearchFilters): Promise<SearchResponse> {
    const result = await this.dao.searchTemplates(filters);
    return {
      templates: result.templates,
      total: result.total
    };
  }

  /**
   * Convert template to Elasticsearch document
   */
  private templateToElasticsearchDoc(template: TemplateWithStats): ElasticsearchTemplate {
    return {
      id: template.id,
      title: template.title,
      description: template.description || '',
      tags: template.tags,
      price_cents: template.price_cents,
      avg_rating: template.avg_rating,
      total_reviews: template.total_reviews,
      total_purchases: template.total_purchases,
      categories: template.categories || [],
      owner_name: template.owner?.name || '',
      owner_verified: template.owner?.verified || false,
      is_ai_generated: template.is_ai_generated || false,
      claude_compat: template.claude_compat,
      featured_at: template.featured_at,
      created_at: template.created_at,
      updated_at: template.updated_at
    };
  }
}

// Epic 16.1.5 - License Management Service
import { FastifyInstance } from 'fastify';
import crypto from 'crypto';
import {
  TemplateLicense,
  LicenseTransfer,
  LicenseType,
  LicenseStatus
} from './transaction.types.js';
import { DatabaseService } from '../database/database.service.js';

export class LicenseService {
  private db: DatabaseService;
  private fastify: FastifyInstance;

  constructor(fastify: FastifyInstance) {
    this.fastify = fastify;
    this.db = fastify.db;
  }

  // =============================================
  // License Generation and Management
  // =============================================

  async generateLicense(
    purchaseId: string,
    templateId: string,
    versionId: string,
    buyerId: string,
    licenseType: LicenseType
  ): Promise<TemplateLicense> {
    const licenseId = crypto.randomUUID();
    const licenseKey = this.generateLicenseKey(templateId, buyerId);

    const license: TemplateLicense = {
      id: licenseId,
      purchase_id: purchaseId,
      template_id: templateId,
      version_id: versionId,
      buyer_id: buyerId,
      license_type: licenseType,
      license_key: licenseKey,
      status: LicenseStatus.ACTIVE,
      usage_limit: this.getLicenseUsageLimit(licenseType),
      usage_count: 0,
      valid_from: new Date(),
      valid_until: this.getLicenseExpiration(licenseType),
      transfer_count: 0,
      max_transfers: this.getMaxTransfers(licenseType),
      restrictions: this.getLicenseRestrictions(licenseType),
      metadata: this.getLicenseMetadata(licenseType),
      created_at: new Date(),
      updated_at: new Date()
    };

    await this.saveLicense(license);
    return license;
  }

  async validateLicense(
    licenseKey: string,
    templateId: string,
    userId: string,
    incrementUsage: boolean = true
  ): Promise<{
    valid: boolean;
    license?: TemplateLicense;
    reason?: string;
  }> {
    try {
      const result = await this.db.query(
        `SELECT * FROM template_licenses 
         WHERE license_key = ? AND template_id = ? AND buyer_id = ?`,
        [licenseKey, templateId, userId]
      );

      if (result.length === 0) {
        return { valid: false, reason: 'License not found' };
      }

      const license = this.parseLicense(result[0]);

      // Check license status
      if (license.status !== LicenseStatus.ACTIVE) {
        return { 
          valid: false, 
          reason: `License is ${license.status}`,
          license 
        };
      }

      // Check expiration
      if (license.valid_until && new Date() > license.valid_until) {
        await this.expireLicense(license.id);
        return { 
          valid: false, 
          reason: 'License has expired',
          license 
        };
      }

      // Check usage limits
      if (license.usage_limit && license.usage_count >= license.usage_limit) {
        return { 
          valid: false, 
          reason: 'Usage limit exceeded',
          license 
        };
      }

      // Increment usage if requested
      if (incrementUsage) {
        await this.incrementUsage(license.id);
        license.usage_count += 1;
        license.last_used_at = new Date();
      }

      return { valid: true, license };

    } catch (error) {
      this.fastify.log.error('License validation error:', error);
      return { valid: false, reason: 'Validation failed' };
    }
  }

  async getLicensesByUser(
    userId: string,
    filters: {
      templateId?: string;
      status?: LicenseStatus;
      licenseType?: LicenseType;
      expiring?: boolean; // Expiring in next 30 days
    } = {},
    pagination: {
      page: number;
      limit: number;
    } = { page: 1, limit: 20 }
  ): Promise<{
    licenses: TemplateLicense[];
    total: number;
    page: number;
    limit: number;
    hasMore: boolean;
  }> {
    let whereClause = 'buyer_id = ?';
    const params = [userId];

    if (filters.templateId) {
      whereClause += ' AND template_id = ?';
      params.push(filters.templateId);
    }

    if (filters.status) {
      whereClause += ' AND status = ?';
      params.push(filters.status);
    }

    if (filters.licenseType) {
      whereClause += ' AND license_type = ?';
      params.push(filters.licenseType);
    }

    if (filters.expiring) {
      whereClause += ' AND valid_until IS NOT NULL AND valid_until <= datetime("now", "+30 days")';
    }

    const offset = (pagination.page - 1) * pagination.limit;

    const licenses = await this.db.query(
      `SELECT * FROM template_licenses 
       WHERE ${whereClause} 
       ORDER BY created_at DESC 
       LIMIT ? OFFSET ?`,
      [...params, pagination.limit, offset]
    );

    const totalResult = await this.db.query(
      `SELECT COUNT(*) as count FROM template_licenses WHERE ${whereClause}`,
      params
    );

    const total = totalResult[0].count;
    const hasMore = offset + pagination.limit < total;

    return {
      licenses: licenses.map(this.parseLicense),
      total,
      page: pagination.page,
      limit: pagination.limit,
      hasMore
    };
  }

  // =============================================
  // License Transfer Management
  // =============================================

  async createTransferRequest(
    licenseId: string,
    fromUserId: string,
    toUserEmail: string,
    reason: string
  ): Promise<LicenseTransfer> {
    // Verify license ownership and transfer eligibility
    const license = await this.getLicenseById(licenseId);
    if (!license || license.buyer_id !== fromUserId) {
      throw new Error('License not found or not owned by user');
    }

    if (license.transfer_count >= license.max_transfers) {
      throw new Error('Maximum transfers exceeded for this license');
    }

    if (license.status !== LicenseStatus.ACTIVE) {
      throw new Error('Only active licenses can be transferred');
    }

    // Find target user
    const userResult = await this.db.query(
      'SELECT id, name, email FROM users WHERE email = ?',
      [toUserEmail]
    );

    if (userResult.length === 0) {
      throw new Error('Target user not found');
    }

    const toUser = userResult[0];
    const transferId = crypto.randomUUID();

    const transfer: LicenseTransfer = {
      id: transferId,
      license_id: licenseId,
      from_user_id: fromUserId,
      to_user_id: toUser.id,
      reason,
      created_at: new Date()
    };

    await this.db.query(
      `INSERT INTO license_transfers 
       (id, license_id, from_user_id, to_user_id, reason, created_at)
       VALUES (?, ?, ?, ?, ?, ?)`,
      [
        transferId, licenseId, fromUserId, toUser.id, reason, transfer.created_at
      ]
    );

    // Send notification to target user (placeholder)
    this.fastify.log.info(`License transfer request created: ${transferId}`);

    return transfer;
  }

  async approveTransfer(
    transferId: string,
    adminUserId: string
  ): Promise<void> {
    const transfer = await this.getTransferById(transferId);
    if (!transfer) {
      throw new Error('Transfer request not found');
    }

    if (transfer.approved_at) {
      throw new Error('Transfer already processed');
    }

    const license = await this.getLicenseById(transfer.license_id);
    if (!license) {
      throw new Error('License not found');
    }

    // Update transfer record
    await this.db.query(
      `UPDATE license_transfers 
       SET approved_by = ?, approved_at = datetime('now')
       WHERE id = ?`,
      [adminUserId, transferId]
    );

    // Transfer the license
    await this.db.query(
      `UPDATE template_licenses 
       SET buyer_id = ?, transfer_count = transfer_count + 1, updated_at = datetime('now')
       WHERE id = ?`,
      [transfer.to_user_id, transfer.license_id]
    );

    this.fastify.log.info(`License transferred: ${transfer.license_id} from ${transfer.from_user_id} to ${transfer.to_user_id}`);
  }

  // =============================================
  // License Status Management
  // =============================================

  async suspendLicense(
    licenseId: string,
    reason: string,
    adminUserId?: string
  ): Promise<void> {
    await this.updateLicenseStatus(licenseId, LicenseStatus.SUSPENDED, {
      suspension_reason: reason,
      suspended_by: adminUserId,
      suspended_at: new Date().toISOString()
    });
  }

  async revokeLicense(
    licenseId: string,
    reason: string,
    adminUserId?: string
  ): Promise<void> {
    await this.updateLicenseStatus(licenseId, LicenseStatus.REVOKED, {
      revocation_reason: reason,
      revoked_by: adminUserId,
      revoked_at: new Date().toISOString()
    });
  }

  async reactivateLicense(
    licenseId: string,
    adminUserId?: string
  ): Promise<void> {
    const license = await this.getLicenseById(licenseId);
    if (!license) {
      throw new Error('License not found');
    }

    // Check if license is still valid (not expired)
    if (license.valid_until && new Date() > license.valid_until) {
      throw new Error('Cannot reactivate expired license');
    }

    await this.updateLicenseStatus(licenseId, LicenseStatus.ACTIVE, {
      reactivated_by: adminUserId,
      reactivated_at: new Date().toISOString()
    });
  }

  // =============================================
  // License Analytics and Reporting
  // =============================================

  async getLicenseAnalytics(
    templateId?: string,
    period: string = '30d'
  ): Promise<{
    totalLicenses: number;
    activeLicenses: number;
    licensesByType: Record<LicenseType, number>;
    usageStats: {
      totalUsage: number;
      averageUsage: number;
      topUsers: Array<{ userId: string; usage: number }>;
    };
    transferStats: {
      totalTransfers: number;
      pendingTransfers: number;
    };
  }> {
    const periodDays = {
      '7d': 7,
      '30d': 30,
      '90d': 90,
      '1y': 365
    };

    const daysBack = periodDays[period] || 30;
    const startDate = new Date();
    startDate.setDate(startDate.getDate() - daysBack);

    let whereClause = 'created_at >= ?';
    const params = [startDate.toISOString()];

    if (templateId) {
      whereClause += ' AND template_id = ?';
      params.push(templateId);
    }

    // Get license counts
    const licenseCounts = await this.db.query(
      `SELECT 
         COUNT(*) as total_licenses,
         COUNT(CASE WHEN status = 'active' THEN 1 END) as active_licenses
       FROM template_licenses 
       WHERE ${whereClause}`,
      params
    );

    // Get licenses by type
    const licensesByType = await this.db.query(
      `SELECT license_type, COUNT(*) as count 
       FROM template_licenses 
       WHERE ${whereClause}
       GROUP BY license_type`,
      params
    );

    // Get usage statistics
    const usageStats = await this.db.query(
      `SELECT 
         SUM(usage_count) as total_usage,
         AVG(usage_count) as average_usage
       FROM template_licenses 
       WHERE ${whereClause}`,
      params
    );

    // Get top users by usage
    const topUsers = await this.db.query(
      `SELECT buyer_id as userId, SUM(usage_count) as usage
       FROM template_licenses 
       WHERE ${whereClause}
       GROUP BY buyer_id 
       ORDER BY usage DESC 
       LIMIT 10`,
      params
    );

    // Get transfer statistics
    const transferStats = await this.db.query(
      `SELECT 
         COUNT(*) as total_transfers,
         COUNT(CASE WHEN approved_at IS NULL THEN 1 END) as pending_transfers
       FROM license_transfers lt
       JOIN template_licenses tl ON lt.license_id = tl.id
       WHERE tl.created_at >= ?`,
      [startDate.toISOString()]
    );

    return {
      totalLicenses: licenseCounts[0]?.total_licenses || 0,
      activeLicenses: licenseCounts[0]?.active_licenses || 0,
      licensesByType: licensesByType.reduce((acc, row) => ({
        ...acc,
        [row.license_type]: row.count
      }), {} as Record<LicenseType, number>),
      usageStats: {
        totalUsage: usageStats[0]?.total_usage || 0,
        averageUsage: Math.round(usageStats[0]?.average_usage || 0),
        topUsers: topUsers || []
      },
      transferStats: {
        totalTransfers: transferStats[0]?.total_transfers || 0,
        pendingTransfers: transferStats[0]?.pending_transfers || 0
      }
    };
  }

  // =============================================
  // Helper Methods
  // =============================================

  private generateLicenseKey(templateId: string, userId: string): string {
    const timestamp = Date.now().toString(36);
    const templateHash = crypto
      .createHash('md5')
      .update(templateId)
      .digest('hex')
      .substring(0, 8)
      .toUpperCase();
    const userHash = crypto
      .createHash('md5')
      .update(userId)
      .digest('hex')
      .substring(0, 8)
      .toUpperCase();
    const random = crypto.randomBytes(4).toString('hex').toUpperCase();

    return `${templateHash}-${userHash}-${timestamp.toUpperCase()}-${random}`;
  }

  private getLicenseUsageLimit(licenseType: LicenseType): number | undefined {
    const limits = {
      [LicenseType.PERSONAL]: 100,
      [LicenseType.COMMERCIAL]: 1000,
      [LicenseType.ENTERPRISE]: 10000,
      [LicenseType.EDUCATIONAL]: 50,
      [LicenseType.UNLIMITED]: undefined
    };
    return limits[licenseType];
  }

  private getLicenseExpiration(licenseType: LicenseType): Date | undefined {
    if (licenseType === LicenseType.UNLIMITED) return undefined;

    const now = new Date();
    const expiration = new Date(now);

    // Different license types have different validity periods
    switch (licenseType) {
      case LicenseType.EDUCATIONAL:
        expiration.setFullYear(now.getFullYear() + 1); // 1 year for educational
        break;
      default:
        expiration.setFullYear(now.getFullYear() + 5); // 5 years for others
        break;
    }

    return expiration;
  }

  private getMaxTransfers(licenseType: LicenseType): number {
    const transfers = {
      [LicenseType.PERSONAL]: 1,
      [LicenseType.COMMERCIAL]: 3,
      [LicenseType.ENTERPRISE]: 10,
      [LicenseType.EDUCATIONAL]: 1,
      [LicenseType.UNLIMITED]: 5
    };
    return transfers[licenseType] || 1;
  }

  private getLicenseRestrictions(licenseType: LicenseType): Record<string, any> {
    const restrictions = {
      [LicenseType.PERSONAL]: {
        commercial_use: false,
        redistribution: false,
        modification: true,
        attribution_required: false
      },
      [LicenseType.COMMERCIAL]: {
        commercial_use: true,
        redistribution: false,
        modification: true,
        attribution_required: false
      },
      [LicenseType.ENTERPRISE]: {
        commercial_use: true,
        redistribution: true,
        modification: true,
        white_label: true,
        attribution_required: false
      },
      [LicenseType.EDUCATIONAL]: {
        commercial_use: false,
        redistribution: false,
        modification: true,
        educational_only: true,
        attribution_required: true
      },
      [LicenseType.UNLIMITED]: {
        commercial_use: true,
        redistribution: true,
        modification: true,
        white_label: true,
        attribution_required: false
      }
    };
    return restrictions[licenseType] || {};
  }

  private getLicenseMetadata(licenseType: LicenseType): Record<string, any> {
    return {
      license_version: '1.0',
      generated_by: 'system',
      license_terms_url: `/legal/license-terms/${licenseType}`,
      support_level: licenseType === LicenseType.ENTERPRISE ? 'premium' : 'standard'
    };
  }

  private async saveLicense(license: TemplateLicense): Promise<void> {
    await this.db.query(
      `INSERT INTO template_licenses 
       (id, purchase_id, template_id, version_id, buyer_id, license_type, license_key, 
        status, usage_limit, usage_count, valid_from, valid_until, transfer_count, 
        max_transfers, restrictions, metadata, created_at, updated_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        license.id, license.purchase_id, license.template_id, license.version_id,
        license.buyer_id, license.license_type, license.license_key, license.status,
        license.usage_limit, license.usage_count, license.valid_from, license.valid_until,
        license.transfer_count, license.max_transfers, JSON.stringify(license.restrictions),
        JSON.stringify(license.metadata), license.created_at, license.updated_at
      ]
    );
  }

  private async incrementUsage(licenseId: string): Promise<void> {
    await this.db.query(
      `UPDATE template_licenses 
       SET usage_count = usage_count + 1, last_used_at = datetime('now'), updated_at = datetime('now')
       WHERE id = ?`,
      [licenseId]
    );
  }

  private async expireLicense(licenseId: string): Promise<void> {
    await this.updateLicenseStatus(licenseId, LicenseStatus.EXPIRED);
  }

  private async updateLicenseStatus(
    licenseId: string, 
    status: LicenseStatus,
    metadata: Record<string, any> = {}
  ): Promise<void> {
    const license = await this.getLicenseById(licenseId);
    if (!license) {
      throw new Error('License not found');
    }

    const updatedMetadata = { ...license.metadata, ...metadata };

    await this.db.query(
      `UPDATE template_licenses 
       SET status = ?, metadata = ?, updated_at = datetime('now')
       WHERE id = ?`,
      [status, JSON.stringify(updatedMetadata), licenseId]
    );
  }

  private async getLicenseById(licenseId: string): Promise<TemplateLicense | null> {
    const result = await this.db.query(
      'SELECT * FROM template_licenses WHERE id = ?',
      [licenseId]
    );

    return result.length > 0 ? this.parseLicense(result[0]) : null;
  }

  private async getTransferById(transferId: string): Promise<LicenseTransfer | null> {
    const result = await this.db.query(
      'SELECT * FROM license_transfers WHERE id = ?',
      [transferId]
    );

    return result.length > 0 ? result[0] : null;
  }

  private parseLicense(row: any): TemplateLicense {
    return {
      ...row,
      restrictions: JSON.parse(row.restrictions || '{}'),
      metadata: JSON.parse(row.metadata || '{}'),
      created_at: new Date(row.created_at),
      updated_at: new Date(row.updated_at),
      valid_from: new Date(row.valid_from),
      valid_until: row.valid_until ? new Date(row.valid_until) : undefined,
      last_used_at: row.last_used_at ? new Date(row.last_used_at) : undefined
    };
  }
}

