  fastify.get('/templates/:templateId/reviews', {
    schema: {
      params: z.object({
        templateId: z.string().uuid()
      }),
      querystring: ReviewFiltersSchema,
      response: {
        200: z.object({
          reviews: z.array(z.any()), // ReviewWithDetails[] type
