    } catch (error) {
      fastify.log.error(error);
      reply.code(400).send({ error: error instanceof Error ? error.message : 'Failed to get review queue' });
    }
  });

  // Create submission review (admin only)
  fastify.post('/submissions/:id/review', {
    preHandler: authenticate,
    schema: {
      params: {
        type: 'object',
        properties: {
          id: { type: 'string', format: 'uuid' }
        },
        required: ['id']
      },
      body: {
        type: 'object',
        required: ['decision', 'score', 'comments', 'detailed_feedback'],
        properties: {
          decision: { type: 'string', enum: ['approved', 'rejected', 'changes_requested'] },
          score: { type: 'integer', minimum: 1, maximum: 100 },
          comments: { type: 'string', minLength: 1, maxLength: 2000 },
          detailed_feedback: {
            type: 'array',
            minItems: 1,
            maxItems: 5,
            items: {
              type: 'object',
              required: ['category', 'rating', 'comments'],
              properties: {
                category: { type: 'string', enum: ['content', 'quality', 'compliance', 'usability', 'technical'] },
                rating: { type: 'integer', minimum: 1, maximum: 5 },
                comments: { type: 'string', minLength: 1, maxLength: 1000 },
                suggestions: { type: 'array', items: { type: 'string' }, maxItems: 10 }
              }
            }
          }
        }
      }
    }
  }, async (request: FastifyRequest<{
    Params: { id: string };
    Body: {
      decision: 'approved' | 'rejected' | 'changes_requested';
      score: number;
      comments: string;
      detailed_feedback: Array<{
        category: 'content' | 'quality' | 'compliance' | 'usability' | 'technical';
        rating: number;
        comments: string;
        suggestions: string[];
      }>;
    }
  }>, reply: FastifyReply) => {
    try {
      const userId = (request.user as any).id;
      const review = await submissionService.createReview(request.params.id, userId, request.body);

      reply.code(201).send(review);
    } catch (error) {
      fastify.log.error(error);
      reply.code(400).send({ error: error instanceof Error ? error.message : 'Failed to create review' });
    }
  });

  // Upload file to submission
  fastify.post('/submissions/:id/files', {
    preHandler: authenticate,
    schema: {
      params: {
        type: 'object',
        properties: {
          id: { type: 'string', format: 'uuid' }
        },
        required: ['id']
      },
      body: {
        type: 'object',
        required: ['file_type', 'filename', 'file_size', 'mime_type'],
        properties: {
          file_type: { type: 'string', enum: ['graph_json', 'prompt_yaml', 'asset_file', 'documentation'] },
          filename: { type: 'string', minLength: 1, maxLength: 255 },
          file_size: { type: 'integer', minimum: 1, maximum: 10485760 },
          mime_type: { type: 'string', minLength: 1 }
        }
      }
    }
  }, async (request: FastifyRequest<{
    Params: { id: string };
    Body: {
      file_type: 'graph_json' | 'prompt_yaml' | 'asset_file' | 'documentation';
      filename: string;
      file_size: number;
      mime_type: string;
    }
  }>, reply: FastifyReply) => {
    try {
      const userId = (request.user as any).id;
      const file = await submissionService.uploadFile(request.params.id, userId, request.body);

      reply.code(201).send(file);
    } catch (error) {
      fastify.log.error(error);
      reply.code(400).send({ error: error instanceof Error ? error.message : 'Failed to upload file' });
    }
  });

  // Get validation rules
  fastify.get('/submissions/validation-rules', {
    preHandler: authenticate,
    schema: {
      querystring: {
        type: 'object',
        properties: {
          category: { type: 'string' },
          severity: { type: 'string', enum: ['error', 'warning', 'info'] },
          active_only: { type: 'boolean', default: true }
        }
      }
    }
  }, async (request: FastifyRequest<{
    Querystring: {
      category?: string;
      severity?: 'error' | 'warning' | 'info';
      active_only?: boolean;
    }
  }>, reply: FastifyReply) => {
    try {
      const conditions = [];
      const params = [];
      let paramIndex = 1;

      if (request.query.active_only !== false) {
        conditions.push(`is_active = true`);
      }

      if (request.query.category) {
        conditions.push(`category = $${paramIndex++}`);
        params.push(request.query.category);
      }

      if (request.query.severity) {
        conditions.push(`severity = $${paramIndex++}`);
        params.push(request.query.severity);
      }

      const whereClause = conditions.length > 0 ? `WHERE ${conditions.join(' AND ')}` : '';

      const result = await fastify.pg.query(`
        SELECT rule_id, name, description, severity, category, auto_fixable, validation_logic
        FROM submission_validation_rules
        ${whereClause}
        ORDER BY severity DESC, category, name
      `, params);

      reply.send(result.rows);
    } catch (error) {
      fastify.log.error(error);
      reply.code(400).send({ error: 'Failed to get validation rules' });
    }
  });

  // Get submission statistics
  fastify.get('/submissions/stats', {
    preHandler: authenticate,
    schema: {
      response: {
        200: {
          type: 'object',
          properties: {
            total_submissions: { type: 'integer' },
            approved_submissions: { type: 'integer' },
            rejected_submissions: { type: 'integer' },
            pending_submissions: { type: 'integer' },
            avg_review_score: { type: 'number' },
            avg_review_time_hours: { type: 'number' }
          }
        }
      }
    }
  }, async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const userId = (request.user as any).id;

      const result = await fastify.pg.query(`
        SELECT 
          COUNT(*) as total_submissions,
          COUNT(*) FILTER (WHERE status = 'approved') as approved_submissions,
          COUNT(*) FILTER (WHERE status = 'rejected') as rejected_submissions,
          COUNT(*) FILTER (WHERE status IN ('draft', 'submitted', 'under_review', 'changes_requested')) as pending_submissions,
          AVG(review_score) FILTER (WHERE review_score IS NOT NULL) as avg_review_score,
          AVG(EXTRACT(EPOCH FROM (reviewed_at - submitted_at)) / 3600) FILTER (WHERE reviewed_at IS NOT NULL AND submitted_at IS NOT NULL) as avg_review_time_hours
        FROM template_submissions
        WHERE submitter_id = $1
      `, [userId]);

      reply.send(result.rows[0]);
    } catch (error) {
      fastify.log.error(error);
      reply.code(400).send({ error: 'Failed to get submission statistics' });
    }
  });
}

// Epic 16.2.1 Template Submission Service
import { Injectable, NotFoundException, BadRequestException, ForbiddenException } from '@nestjs/common';
import { Pool } from 'pg';
import * as crypto from 'crypto';
import { v4 as uuidv4 } from 'uuid';
import { 
  TemplateSubmission, 
  SubmissionData, 
  ValidationResult, 
  UploadedFile, 
  SubmissionReview,
  SubmissionStatus,
  ValidationSeverity,
  FileType,
  CreateSubmissionSchema,
  UpdateSubmissionSchema,
  SubmissionReviewSchema,
  FileUploadSchema,
  SubmissionDataSchema
} from './submission.types';
import { TemplateStatus } from './types';
import { MarketplaceDAO } from './dao';

@Injectable()
export class SubmissionService {
  private dao: MarketplaceDAO;

  constructor(private pool: Pool) {
    this.dao = new MarketplaceDAO(pool);
  }

  // Create new submission
  async createSubmission(userId: string, data: any): Promise<TemplateSubmission> {
    const validated = CreateSubmissionSchema.parse(data);

    // Validate submission data
    const validationResults = await this.validateSubmissionData(validated.submission_data);

    // Check if user has permission to create submissions
    if (!(await this.canUserSubmit(userId))) {
      throw new ForbiddenException('User does not have permission to submit templates');
    }

    const submissionId = uuidv4();

    // Create or update template if template_id is provided
    let templateId: string;
    if (validated.template_id) {
      // Updating existing template
      const template = await this.dao.getTemplate(validated.template_id);
      if (!template) {
        throw new NotFoundException('Template not found');
      }
      if (template.owner_id !== userId) {
        throw new ForbiddenException('Not authorized to update this template');
      }
      templateId = validated.template_id;
    } else {
      // Creating new template
      const template = await this.dao.createTemplate({
        owner_id: userId,
        title: validated.submission_data.title,
        description: validated.submission_data.description,
        tags: validated.submission_data.tags,
        price_cents: validated.submission_data.price_cents,
        is_ai_generated: validated.submission_data.is_ai_generated,
        claude_compat: validated.submission_data.claude_compat,
        status: TemplateStatus.DRAFT
      });
      templateId = template.id;
    }

    // Get next version number
    const versions = await this.dao.getTemplateVersions(templateId);
    const nextVersionNumber = versions.length + 1;

    // Create submission record
    const submission = await this.pool.query(`
      INSERT INTO template_submissions (
        id, template_id, submitter_id, version_number, status, 
        submission_data, validation_results, submitted_at, created_at, updated_at
      ) VALUES ($1, $2, $3, $4, $5, $6, $7, NOW(), NOW(), NOW())
      RETURNING *
    `, [
      submissionId,
      templateId,
      userId,
      nextVersionNumber,
      SubmissionStatus.DRAFT,
      JSON.stringify(validated.submission_data),
      JSON.stringify(validationResults)
    ]);

    return this.mapSubmissionResult(submission.rows[0]);
  }

  // Get submission by ID
  async getSubmission(id: string, userId?: string): Promise<TemplateSubmission | null> {
    const result = await this.pool.query(`
      SELECT s.*, t.owner_id, t.title as template_title
      FROM template_submissions s
      JOIN marketplace_templates t ON s.template_id = t.id
      WHERE s.id = $1
    `, [id]);

    if (result.rows.length === 0) {
      return null;
    }

    const submission = result.rows[0];

    // Check permissions
    if (userId && submission.submitter_id !== userId && submission.owner_id !== userId) {
      // Only submitter, template owner, or admin can view
      if (!(await this.isUserAdmin(userId))) {
        throw new ForbiddenException('Not authorized to view this submission');
      }
    }

    return this.mapSubmissionResult(submission);
  }

  // Update submission
  async updateSubmission(id: string, userId: string, updates: any): Promise<TemplateSubmission> {
    const validated = UpdateSubmissionSchema.parse(updates);

    const submission = await this.getSubmission(id, userId);
    if (!submission) {
      throw new NotFoundException('Submission not found');
    }

    if (submission.submitter_id !== userId) {
      throw new ForbiddenException('Not authorized to update this submission');
    }

    if (submission.status === SubmissionStatus.APPROVED || submission.status === SubmissionStatus.REJECTED) {
      throw new BadRequestException('Cannot update submission after final review');
    }

    // Merge submission data if provided
    let updatedData = submission.submission_data;
    if (validated.submission_data) {
      updatedData = { ...updatedData, ...validated.submission_data };
    }

    // Re-validate if submission data changed
    let validationResults = submission.validation_results;
    if (validated.submission_data) {
      validationResults = await this.validateSubmissionData(updatedData);
    }

    const updateFields = [];
    const updateValues = [];
    let paramIndex = 1;

    if (validated.submission_data) {
      updateFields.push(`submission_data = $${paramIndex++}`);
      updateValues.push(JSON.stringify(updatedData));
      updateFields.push(`validation_results = $${paramIndex++}`);
      updateValues.push(JSON.stringify(validationResults));
    }

    if (validated.status) {
      updateFields.push(`status = $${paramIndex++}`);
      updateValues.push(validated.status);
    }

    updateFields.push(`updated_at = NOW()`);
    updateValues.push(id);

    const result = await this.pool.query(`
      UPDATE template_submissions 
      SET ${updateFields.join(', ')}
      WHERE id = $${paramIndex}
      RETURNING *
    `, updateValues);

    return this.mapSubmissionResult(result.rows[0]);
  }

  // Submit for review
  async submitForReview(id: string, userId: string): Promise<TemplateSubmission> {
    const submission = await this.getSubmission(id, userId);
    if (!submission) {
      throw new NotFoundException('Submission not found');
    }

    if (submission.submitter_id !== userId) {
      throw new ForbiddenException('Not authorized to submit this for review');
    }

    if (submission.status !== SubmissionStatus.DRAFT && submission.status !== SubmissionStatus.CHANGES_REQUESTED) {
      throw new BadRequestException('Can only submit draft or change-requested submissions');
    }

    // Check for blocking validation errors
    const hasErrors = submission.validation_results.some(r => r.severity === ValidationSeverity.ERROR);
    if (hasErrors) {
      throw new BadRequestException('Cannot submit with validation errors');
    }

    return this.updateSubmission(id, userId, { 
      status: SubmissionStatus.SUBMITTED,
      submitted_at: new Date()
    });
  }

  // Get user's submissions
  async getUserSubmissions(userId: string, limit: number = 50): Promise<TemplateSubmission[]> {
    const result = await this.pool.query(`
      SELECT s.*, t.title as template_title
      FROM template_submissions s
      JOIN marketplace_templates t ON s.template_id = t.id
      WHERE s.submitter_id = $1
      ORDER BY s.created_at DESC
      LIMIT $2
    `, [userId, limit]);

    return result.rows.map(this.mapSubmissionResult);
  }

  // Get submissions for review (admin only)
  async getSubmissionsForReview(userId: string, status?: SubmissionStatus, limit: number = 50): Promise<TemplateSubmission[]> {
    if (!(await this.isUserAdmin(userId))) {
      throw new ForbiddenException('Not authorized to view submissions for review');
    }

    const conditions = [];
    const params = [];
    let paramIndex = 1;

    if (status) {
      conditions.push(`s.status = $${paramIndex++}`);
      params.push(status);
    } else {
      conditions.push(`s.status IN ($${paramIndex++}, $${paramIndex++})`);
      params.push(SubmissionStatus.SUBMITTED, SubmissionStatus.UNDER_REVIEW);
    }

    params.push(limit);

    const result = await this.pool.query(`
      SELECT s.*, t.title as template_title, u.name as submitter_name
      FROM template_submissions s
      JOIN marketplace_templates t ON s.template_id = t.id
      JOIN users u ON s.submitter_id = u.id
      WHERE ${conditions.join(' AND ')}
      ORDER BY s.submitted_at ASC
      LIMIT $${paramIndex}
    `, params);

    return result.rows.map(this.mapSubmissionResult);
  }

  // Create submission review
  async createReview(submissionId: string, reviewerId: string, reviewData: any): Promise<SubmissionReview> {
    if (!(await this.isUserAdmin(reviewerId))) {
      throw new ForbiddenException('Not authorized to review submissions');
    }

    const validated = SubmissionReviewSchema.parse(reviewData);

    const submission = await this.getSubmission(submissionId);
    if (!submission) {
      throw new NotFoundException('Submission not found');
    }

    if (submission.status !== SubmissionStatus.SUBMITTED && submission.status !== SubmissionStatus.UNDER_REVIEW) {
      throw new BadRequestException('Submission is not in a reviewable state');
    }

    const reviewId = uuidv4();

    // Create review record
    const review = await this.pool.query(`
      INSERT INTO submission_reviews (
        id, submission_id, reviewer_id, decision, score, comments, detailed_feedback, created_at
      ) VALUES ($1, $2, $3, $4, $5, $6, $7, NOW())
      RETURNING *
    `, [
      reviewId,
      submissionId,
      reviewerId,
      validated.decision,
      validated.score,
      validated.comments,
      JSON.stringify(validated.detailed_feedback)
    ]);

    // Update submission status
    let newStatus: SubmissionStatus;
    switch (validated.decision) {
      case 'approved':
        newStatus = SubmissionStatus.APPROVED;
        await this.publishApprovedSubmission(submissionId);
        break;
      case 'rejected':
        newStatus = SubmissionStatus.REJECTED;
        break;
      case 'changes_requested':
        newStatus = SubmissionStatus.CHANGES_REQUESTED;
        break;
    }

    await this.pool.query(`
      UPDATE template_submissions 
      SET status = $1, reviewer_id = $2, review_comments = $3, review_score = $4, reviewed_at = NOW()
      WHERE id = $5
    `, [newStatus, reviewerId, validated.comments, validated.score, submissionId]);

    return this.mapReviewResult(review.rows[0]);
  }

  // File upload handling
  async uploadFile(submissionId: string, userId: string, fileData: any): Promise<UploadedFile> {
    const submission = await this.getSubmission(submissionId, userId);
    if (!submission) {
      throw new NotFoundException('Submission not found');
    }

    if (submission.submitter_id !== userId) {
      throw new ForbiddenException('Not authorized to upload files for this submission');
    }

    const validated = FileUploadSchema.parse(fileData);

    const fileId = uuidv4();
    const s3Key = `submissions/${submissionId}/files/${fileId}/${validated.filename}`;

    // Store file metadata
    const result = await this.pool.query(`
      INSERT INTO submission_files (
        id, submission_id, file_type, filename, file_size, mime_type, 
        s3_key, validation_status, uploaded_at
      ) VALUES ($1, $2, $3, $4, $5, $6, $7, 'pending', NOW())
      RETURNING *
    `, [
      fileId, submissionId, validated.file_type, validated.filename, 
      validated.file_size, validated.mime_type, s3Key
    ]);

    return this.mapFileResult(result.rows[0]);
  }

  // Validate submission data
  private async validateSubmissionData(data: SubmissionData): Promise<ValidationResult[]> {
    const results: ValidationResult[] = [];

    // Validate required fields
    if (!data.title?.trim()) {
      results.push({
        id: uuidv4(),
        rule_id: 'required_title',
        severity: ValidationSeverity.ERROR,
        message: 'Title is required',
        auto_fixable: false
      });
    }

    if (!data.description?.trim() || data.description.length < 10) {
      results.push({
        id: uuidv4(),
        rule_id: 'required_description',
        severity: ValidationSeverity.ERROR,
        message: 'Description must be at least 10 characters',
        auto_fixable: false
      });
    }

    if (!data.tags?.length) {
      results.push({
        id: uuidv4(),
        rule_id: 'required_tags',
        severity: ValidationSeverity.ERROR,
        message: 'At least one tag is required',
        auto_fixable: false
      });
    }

    if (!data.categories?.length) {
      results.push({
        id: uuidv4(),
        rule_id: 'required_categories',
        severity: ValidationSeverity.ERROR,
        message: 'At least one category is required',
        auto_fixable: false
      });
    }

    // Validate graph_json structure
    if (!data.graph_json || typeof data.graph_json !== 'object') {
      results.push({
        id: uuidv4(),
        rule_id: 'invalid_graph_json',
        severity: ValidationSeverity.ERROR,
        message: 'Valid graph JSON is required',
        auto_fixable: false
      });
    }

    // Validate price
    if (data.price_cents < 0) {
      results.push({
        id: uuidv4(),
        rule_id: 'invalid_price',
        severity: ValidationSeverity.ERROR,
        message: 'Price cannot be negative',
        auto_fixable: true,
        suggested_fix: 'Set price to 0 for free template'
      });
    }

    // Validate token estimate
    if (data.token_per_run_estimate < 0) {
      results.push({
        id: uuidv4(),
        rule_id: 'invalid_token_estimate',
        severity: ValidationSeverity.WARNING,
        message: 'Token estimate should be positive',
        auto_fixable: true,
        suggested_fix: 'Set to 0 if unknown'
      });
    }

    // Validate use cases
    if (!data.intended_use_cases?.length) {
      results.push({
        id: uuidv4(),
        rule_id: 'required_use_cases',
        severity: ValidationSeverity.ERROR,
        message: 'At least one intended use case is required',
        auto_fixable: false
      });
    }

    // Validate examples
    if (!data.example_outputs?.length) {
      results.push({
        id: uuidv4(),
        rule_id: 'required_examples',
        severity: ValidationSeverity.ERROR,
        message: 'At least one example output is required',
        auto_fixable: false
      });
    }

    // Check for common issues
    if (data.title && data.title.length > 100) {
      results.push({
        id: uuidv4(),
        rule_id: 'title_too_long',
        severity: ValidationSeverity.WARNING,
        message: 'Title is very long and may be truncated',
        auto_fixable: false
      });
    }

    if (data.tags && data.tags.length > 10) {
      results.push({
        id: uuidv4(),
        rule_id: 'too_many_tags',
        severity: ValidationSeverity.WARNING,
        message: 'Too many tags may reduce discoverability',
        auto_fixable: false
      });
    }

    return results;
  }

  // Publish approved submission
  private async publishApprovedSubmission(submissionId: string): Promise<void> {
    const submission = await this.getSubmission(submissionId);
    if (!submission) return;

    const data = submission.submission_data;

    // Create template version
    const hashContent = JSON.stringify(data.graph_json) + (data.prompt_yaml || '');
    const hash = crypto.createHash('sha256').update(hashContent).digest('hex');

    const version = await this.dao.createVersion({
      template_id: submission.template_id,
      version_number: submission.version_number,
      claude_model: data.claude_model,
      graph_json: data.graph_json,
      prompt_yaml: data.prompt_yaml,
      changelog_md: data.changelog_md,
      hash,
      token_per_run_estimate: data.token_per_run_estimate,
      safety_score: 0.5 // Default, to be calculated
    });

    // Update template
    await this.dao.updateTemplate(submission.template_id, {
      title: data.title,
      description: data.description,
      tags: data.tags,
      price_cents: data.price_cents,
      is_ai_generated: data.is_ai_generated,
      claude_compat: data.claude_compat,
      status: TemplateStatus.LISTED,
      current_version_id: version.id
    });

    // Update category mappings
    await this.updateTemplateCategories(submission.template_id, data.categories);
  }

  // Helper methods
  private async canUserSubmit(userId: string): Promise<boolean> {
    // Check if user exists and is verified
    const result = await this.pool.query(`
      SELECT verified FROM users WHERE id = $1
    `, [userId]);

    return result.rows.length > 0 && result.rows[0].verified;
  }

  private async isUserAdmin(userId: string): Promise<boolean> {
    const result = await this.pool.query(`
      SELECT role FROM users WHERE id = $1
    `, [userId]);

    return result.rows.length > 0 && result.rows[0].role === 'admin';
  }

  private async updateTemplateCategories(templateId: string, categoryIds: string[]): Promise<void> {
    // Remove existing mappings
    await this.pool.query(`
      DELETE FROM template_category_mappings WHERE template_id = $1
    `, [templateId]);

    // Add new mappings
    for (const categoryId of categoryIds) {
      await this.pool.query(`
        INSERT INTO template_category_mappings (template_id, category_id) 
        VALUES ($1, $2)
      `, [templateId, categoryId]);
    }
  }

  private mapSubmissionResult(row: any): TemplateSubmission {
    return {
      id: row.id,
      template_id: row.template_id,
      submitter_id: row.submitter_id,
      version_number: row.version_number,
      status: row.status,
      submission_data: JSON.parse(row.submission_data),
      validation_results: JSON.parse(row.validation_results),
      reviewer_id: row.reviewer_id,
      review_comments: row.review_comments,
      review_score: row.review_score,
      submitted_at: row.submitted_at,
      reviewed_at: row.reviewed_at,
      created_at: row.created_at,
      updated_at: row.updated_at
    };
  }

  private mapReviewResult(row: any): SubmissionReview {
    return {
      id: row.id,
      submission_id: row.submission_id,
      reviewer_id: row.reviewer_id,
      decision: row.decision,
      score: row.score,
      comments: row.comments,
      detailed_feedback: JSON.parse(row.detailed_feedback),
      created_at: row.created_at
    };
  }

  private mapFileResult(row: any): UploadedFile {
    return {
      id: row.id,
      submission_id: row.submission_id,
      file_type: row.file_type,
      filename: row.filename,
      file_size: row.file_size,
      mime_type: row.mime_type,
      s3_key: row.s3_key,
      validation_status: row.validation_status,
      validation_errors: row.validation_errors ? JSON.parse(row.validation_errors) : [],
      uploaded_at: row.uploaded_at
    };
  }
}

// Epic 16.2.1 Template Submission System Types
import { z } from 'zod';
import { TemplateStatus } from './types';

// Submission workflow statuses
export enum SubmissionStatus {
  DRAFT = 'draft',
  SUBMITTED = 'submitted',
  UNDER_REVIEW = 'under_review',
  CHANGES_REQUESTED = 'changes_requested',
  APPROVED = 'approved',
  REJECTED = 'rejected'
}

// Submission validation types
export enum ValidationSeverity {
  ERROR = 'error',
  WARNING = 'warning',
  INFO = 'info'
}

// File upload types
export enum FileType {
  GRAPH_JSON = 'graph_json',
  PROMPT_YAML = 'prompt_yaml',
  ASSET_FILE = 'asset_file',
  DOCUMENTATION = 'documentation'
}

// Template submission interface
export interface TemplateSubmission {
  id: string;
  template_id: string;
  submitter_id: string;
  version_number: number;
  status: SubmissionStatus;
  submission_data: SubmissionData;
  validation_results: ValidationResult[];
  reviewer_id?: string;
  review_comments?: string;
  review_score?: number;
  submitted_at: Date;
  reviewed_at?: Date;
  created_at: Date;
  updated_at: Date;
}

// Submission data structure
export interface SubmissionData {
  // Template metadata
  title: string;
  description: string;
  tags: string[];
  categories: string[];
  price_cents: number;
  is_ai_generated: boolean;
  claude_compat: string[];

  // Version data
  claude_model: string;
  graph_json: Record<string, any>;
  prompt_yaml?: string;
  changelog_md?: string;
  token_per_run_estimate: number;

  // Additional metadata
  intended_use_cases: string[];
  technical_requirements: string[];
  example_outputs: string[];
  documentation_md?: string;

  // Submission specifics
  moderation_notes?: string;
  is_first_submission: boolean;
  previous_version_id?: string;
}

// Validation result interface
export interface ValidationResult {
  id: string;
  rule_id: string;
  severity: ValidationSeverity;
  message: string;
  details?: Record<string, any>;
  suggested_fix?: string;
  auto_fixable: boolean;
  location?: {
    file_type: FileType;
    line?: number;
    column?: number;
    field?: string;
  };
}

// File upload interface
export interface UploadedFile {
  id: string;
  submission_id: string;
  file_type: FileType;
  filename: string;
  file_size: number;
  mime_type: string;
  s3_key: string;
  validation_status: 'pending' | 'valid' | 'invalid';
  validation_errors: string[];
  uploaded_at: Date;
}

// Submission review interface
export interface SubmissionReview {
  id: string;
  submission_id: string;
  reviewer_id: string;
  decision: 'approved' | 'rejected' | 'changes_requested';
  score: number; // 1-100
  comments: string;
  detailed_feedback: ReviewFeedback[];
  created_at: Date;
}

// Review feedback structure
export interface ReviewFeedback {
  category: 'content' | 'quality' | 'compliance' | 'usability' | 'technical';
  rating: number; // 1-5
  comments: string;
  suggestions: string[];
}

// Zod schemas for validation
export const SubmissionDataSchema = z.object({
  // Template metadata
  title: z.string().min(1).max(255),
  description: z.string().min(10).max(2000),
  tags: z.array(z.string().min(1).max(50)).min(1).max(20),
  categories: z.array(z.string().uuid()).min(1).max(3),
  price_cents: z.number().int().min(0).max(100000), // Max $1000
  is_ai_generated: z.boolean(),
  claude_compat: z.array(z.string()).min(1),

  // Version data
  claude_model: z.string().min(1),
  graph_json: z.record(z.any()),
  prompt_yaml: z.string().optional(),
  changelog_md: z.string().optional(),
  token_per_run_estimate: z.number().int().min(0),

  // Additional metadata
  intended_use_cases: z.array(z.string()).min(1).max(10),
  technical_requirements: z.array(z.string()).max(20),
  example_outputs: z.array(z.string()).min(1).max(5),
  documentation_md: z.string().optional(),

  // Submission specifics
  moderation_notes: z.string().optional(),
  is_first_submission: z.boolean(),
  previous_version_id: z.string().uuid().optional(),
});

export const CreateSubmissionSchema = z.object({
  template_id: z.string().uuid().optional(), // Optional for new templates
  submission_data: SubmissionDataSchema,
});

export const UpdateSubmissionSchema = z.object({
  submission_data: SubmissionDataSchema.partial(),
  status: z.nativeEnum(SubmissionStatus).optional(),
});

export const SubmissionReviewSchema = z.object({
  decision: z.enum(['approved', 'rejected', 'changes_requested']),
  score: z.number().int().min(1).max(100),
  comments: z.string().min(1).max(2000),
  detailed_feedback: z.array(z.object({
    category: z.enum(['content', 'quality', 'compliance', 'usability', 'technical']),
    rating: z.number().int().min(1).max(5),
    comments: z.string().min(1).max(1000),
    suggestions: z.array(z.string()).max(10),
  })).min(1).max(5),
});

export const FileUploadSchema = z.object({
  file_type: z.nativeEnum(FileType),
  filename: z.string().min(1).max(255),
  file_size: z.number().int().min(1).max(10 * 1024 * 1024), // 10MB max
  mime_type: z.string().min(1),
});

// Export all types
export type {
  TemplateSubmission,
  SubmissionData,
  ValidationResult,
  UploadedFile,
  SubmissionReview,
  ReviewFeedback,
};

export {
  SubmissionStatus,
  ValidationSeverity,
  FileType,
  SubmissionDataSchema,
  CreateSubmissionSchema,
  UpdateSubmissionSchema,
  SubmissionReviewSchema,
  FileUploadSchema,
};

// Epic 16.1.5 - Transaction Routes
import { FastifyInstance } from 'fastify';
import { z } from 'zod';
import { TransactionService } from './transaction.service.js';
import {
  AddToCartSchema,
  UpdateCartSchema,
  CreatePaymentIntentSchema,
  ProcessPaymentSchema,
  CreateRefundRequestSchema,
  LicenseTransferSchema
} from './transaction.types.js';

export async function transactionRoutes(fastify: FastifyInstance) {
  const transactionService = new TransactionService(fastify);

  // =============================================
  // Shopping Cart Routes
  // =============================================

  // Get current cart
  fastify.get('/cart', {
    preHandler: [fastify.authenticate],
    schema: {
      response: {
        200: z.object({
          cart: z.any().optional() // ShoppingCart type
        })
      }
    }
  }, async (request, reply) => {
    try {
      const cart = await transactionService.getActiveCart(request.user.id);
      reply.send({ cart });
    } catch (error) {
      fastify.log.error('Get cart error:', error);
      reply.code(500).send({ error: 'Failed to get cart' });
    }
  });

  // Add items to cart
  fastify.post('/cart/add', {
    preHandler: [fastify.authenticate],
    schema: {
      body: AddToCartSchema,
      response: {
        200: z.object({
          cart: z.any() // ShoppingCart type
        })
      }
    }
  }, async (request, reply) => {
    try {
      const cart = await transactionService.addToCart(request.user.id, request.body);
      reply.send({ cart });
    } catch (error) {
      fastify.log.error('Add to cart error:', error);

      if (error.message.includes('already own') || error.message.includes('not available')) {
        reply.code(400).send({ error: error.message });
      } else {
        reply.code(500).send({ error: 'Failed to add to cart' });
      }
    }
  });

  // Update cart item
  fastify.put('/cart/:cartId/items', {
    preHandler: [fastify.authenticate],
    schema: {
      params: z.object({
        cartId: z.string().uuid()
      }),
      body: UpdateCartSchema,
      response: {
        200: z.object({
          cart: z.any() // ShoppingCart type
        })
      }
    }
  }, async (request, reply) => {
    try {
      const { cartId } = request.params;
      const cart = await transactionService.updateCartItem(request.user.id, cartId, request.body);
      reply.send({ cart });
    } catch (error) {
      fastify.log.error('Update cart item error:', error);

      if (error.message.includes('not found') || error.message.includes('expired')) {
        reply.code(404).send({ error: error.message });
      } else {
        reply.code(500).send({ error: 'Failed to update cart item' });
      }
    }
  });

  // Clear cart
  fastify.delete('/cart/:cartId', {
    preHandler: [fastify.authenticate],
    schema: {
      params: z.object({
        cartId: z.string().uuid()
      }),
      response: {
        200: z.object({
          success: z.boolean()
        })
      }
    }
  }, async (request, reply) => {
    try {
      const { cartId } = request.params;
      await transactionService.clearCart(request.user.id, cartId);
      reply.send({ success: true });
    } catch (error) {
      fastify.log.error('Clear cart error:', error);
      reply.code(500).send({ error: 'Failed to clear cart' });
    }
  });

  // =============================================
  // Payment Processing Routes
  // =============================================

  // Create payment intent
  fastify.post('/payment/intent', {
    preHandler: [fastify.authenticate],
    schema: {
      body: CreatePaymentIntentSchema,
      response: {
        200: z.object({
          payment_intent: z.any() // PaymentIntent type
        })
      }
    }
  }, async (request, reply) => {
    try {
      const paymentIntent = await transactionService.createPaymentIntent(
        request.user.id, 
        request.body
      );
      reply.send({ payment_intent: paymentIntent });
    } catch (error) {
      fastify.log.error('Create payment intent error:', error);

      if (error.message.includes('Cart is empty') || error.message.includes('risk factors')) {
        reply.code(400).send({ error: error.message });
      } else {
        reply.code(500).send({ error: 'Failed to create payment intent' });
      }
    }
  });

  // Process payment
  fastify.post('/payment/process', {
    preHandler: [fastify.authenticate],
    schema: {
      body: ProcessPaymentSchema,
      response: {
        200: z.object({
          order: z.any() // Order type
        })
      }
    }
  }, async (request, reply) => {
    try {
      const order = await transactionService.processPayment(request.user.id, request.body);
      reply.send({ order });
    } catch (error) {
      fastify.log.error('Process payment error:', error);

      if (error.message.includes('not found') || 
          error.message.includes('requires authentication') ||
          error.message.includes('failed')) {
        reply.code(400).send({ error: error.message });
      } else {
        reply.code(500).send({ error: 'Payment processing failed' });
      }
    }
  });

  // Get payment intent status
  fastify.get('/payment/intent/:intentId', {
    preHandler: [fastify.authenticate],
    schema: {
      params: z.object({
        intentId: z.string().uuid()
      }),
      response: {
        200: z.object({
          payment_intent: z.any() // PaymentIntent type
        })
      }
    }
  }, async (request, reply) => {
    try {
      const { intentId } = request.params;
      const paymentIntent = await transactionService.getPaymentIntent(intentId, request.user.id);

      if (!paymentIntent) {
        reply.code(404).send({ error: 'Payment intent not found' });
        return;
      }

      reply.send({ payment_intent: paymentIntent });
    } catch (error) {
      fastify.log.error('Get payment intent error:', error);
      reply.code(500).send({ error: 'Failed to get payment intent' });
    }
  });

  // =============================================
  // Order Management Routes
  // =============================================

  // Get user orders
  fastify.get('/orders', {
    preHandler: [fastify.authenticate],
    schema: {
      querystring: z.object({
        page: z.coerce.number().min(1).default(1),
        limit: z.coerce.number().min(1).max(100).default(20),
        status: z.string().optional()
      }),
      response: {
        200: z.object({
          orders: z.array(z.any()), // Order[] type
          total: z.number(),
          page: z.number(),
          limit: z.number(),
          has_more: z.boolean()
        })
      }
    }
  }, async (request, reply) => {
    try {
      const { page, limit, status } = request.query;
      const offset = (page - 1) * limit;

      let whereClause = 'user_id = ?';
      const params = [request.user.id];

      if (status) {
        whereClause += ' AND status = ?';
        params.push(status);
      }

      const orders = await fastify.db.query(
        `SELECT * FROM orders WHERE ${whereClause} ORDER BY created_at DESC LIMIT ? OFFSET ?`,
        [...params, limit, offset]
      );

      const totalResult = await fastify.db.query(
        `SELECT COUNT(*) as count FROM orders WHERE ${whereClause}`,
        params
      );

      const total = totalResult[0].count;
      const hasMore = offset + limit < total;

      reply.send({
        orders,
        total,
        page,
        limit,
        has_more: hasMore
      });
    } catch (error) {
      fastify.log.error('Get orders error:', error);
      reply.code(500).send({ error: 'Failed to get orders' });
    }
  });

  // Get specific order
  fastify.get('/orders/:orderId', {
    preHandler: [fastify.authenticate],
    schema: {
      params: z.object({
        orderId: z.string().uuid()
      }),
      response: {
        200: z.object({
          order: z.any() // Order type with items
        })
      }
    }
  }, async (request, reply) => {
    try {
      const { orderId } = request.params;

      const orderResult = await fastify.db.query(
        'SELECT * FROM orders WHERE id = ? AND user_id = ?',
        [orderId, request.user.id]
      );

      if (orderResult.length === 0) {
        reply.code(404).send({ error: 'Order not found' });
        return;
      }

      const order = orderResult[0];

      // Get order items
      const items = await fastify.db.query(
        'SELECT * FROM order_items WHERE order_id = ?',
        [orderId]
      );

      order.items = items;
      order.billing_address = JSON.parse(order.billing_address);
      order.metadata = JSON.parse(order.metadata || '{}');

      reply.send({ order });
    } catch (error) {
      fastify.log.error('Get order error:', error);
      reply.code(500).send({ error: 'Failed to get order' });
    }
  });

  // =============================================
  // License Management Routes
  // =============================================

  // Get user licenses
  fastify.get('/licenses', {
    preHandler: [fastify.authenticate],
    schema: {
      querystring: z.object({
        template_id: z.string().uuid().optional(),
        status: z.string().optional(),
        page: z.coerce.number().min(1).default(1),
        limit: z.coerce.number().min(1).max(100).default(20)
      }),
      response: {
        200: z.object({
          licenses: z.array(z.any()), // TemplateLicense[] type
          total: z.number(),
          page: z.number(),
          limit: z.number(),
          has_more: z.boolean()
        })
      }
    }
  }, async (request, reply) => {
    try {
      const { template_id, status, page, limit } = request.query;
      const offset = (page - 1) * limit;

      let whereClause = 'buyer_id = ?';
      const params = [request.user.id];

      if (template_id) {
        whereClause += ' AND template_id = ?';
        params.push(template_id);
      }

      if (status) {
        whereClause += ' AND status = ?';
        params.push(status);
      }

      const licenses = await fastify.db.query(
        `SELECT * FROM template_licenses WHERE ${whereClause} ORDER BY created_at DESC LIMIT ? OFFSET ?`,
        [...params, limit, offset]
      );

      const totalResult = await fastify.db.query(
        `SELECT COUNT(*) as count FROM template_licenses WHERE ${whereClause}`,
        params
      );

      const total = totalResult[0].count;
      const hasMore = offset + limit < total;

      // Parse JSON fields
      licenses.forEach(license => {
        license.restrictions = JSON.parse(license.restrictions || '{}');
        license.metadata = JSON.parse(license.metadata || '{}');
      });

      reply.send({
        licenses,
        total,
        page,
        limit,
        has_more: hasMore
      });
    } catch (error) {
      fastify.log.error('Get licenses error:', error);
      reply.code(500).send({ error: 'Failed to get licenses' });
    }
  });

  // Validate license
  fastify.post('/licenses/validate', {
    preHandler: [fastify.authenticate],
    schema: {
      body: z.object({
        license_key: z.string(),
        template_id: z.string().uuid()
      }),
      response: {
        200: z.object({
          valid: z.boolean(),
          license: z.any().optional() // TemplateLicense type
        })
      }
    }
  }, async (request, reply) => {
    try {
      const { license_key, template_id } = request.body;
      const valid = await transactionService.validateLicense(license_key, template_id, request.user.id);

      let license = null;
      if (valid) {
        const result = await fastify.db.query(
          'SELECT * FROM template_licenses WHERE license_key = ? AND template_id = ? AND buyer_id = ?',
          [license_key, template_id, request.user.id]
        );

        if (result.length > 0) {
          license = result[0];
          license.restrictions = JSON.parse(license.restrictions || '{}');
          license.metadata = JSON.parse(license.metadata || '{}');
        }
      }

      reply.send({ valid, license });
    } catch (error) {
      fastify.log.error('Validate license error:', error);
      reply.code(500).send({ error: 'Failed to validate license' });
    }
  });

  // Transfer license
  fastify.post('/licenses/transfer', {
    preHandler: [fastify.authenticate],
    schema: {
      body: LicenseTransferSchema,
      response: {
        200: z.object({
          transfer_request: z.any() // LicenseTransfer type
        })
      }
    }
  }, async (request, reply) => {
    try {
      const { license_id, to_user_email, reason } = request.body;

      // Verify license ownership
      const licenseResult = await fastify.db.query(
        'SELECT * FROM template_licenses WHERE id = ? AND buyer_id = ?',
        [license_id, request.user.id]
      );

      if (licenseResult.length === 0) {
        reply.code(404).send({ error: 'License not found or not owned by user' });
        return;
      }

      const license = licenseResult[0];

      // Check transfer eligibility
      if (license.transfer_count >= license.max_transfers) {
        reply.code(400).send({ error: 'Maximum transfers exceeded for this license' });
        return;
      }

      // Find target user
      const userResult = await fastify.db.query(
        'SELECT id FROM users WHERE email = ?',
        [to_user_email]
      );

      if (userResult.length === 0) {
        reply.code(400).send({ error: 'Target user not found' });
        return;
      }

      const toUserId = userResult[0].id;

      // Create transfer request
      const transferId = crypto.randomUUID();
      const transferRequest = {
        id: transferId,
        license_id,
        from_user_id: request.user.id,
        to_user_id: toUserId,
        reason,
        created_at: new Date()
      };

      await fastify.db.query(
        'INSERT INTO license_transfers (id, license_id, from_user_id, to_user_id, reason, created_at) VALUES (?, ?, ?, ?, ?, ?)',
        [transferId, license_id, request.user.id, toUserId, reason, transferRequest.created_at]
      );

      reply.send({ transfer_request: transferRequest });
    } catch (error) {
      fastify.log.error('Transfer license error:', error);
      reply.code(500).send({ error: 'Failed to create license transfer request' });
    }
  });

  // =============================================
  // Refund Routes
  // =============================================

  // Create refund request
  fastify.post('/refunds/request', {
    preHandler: [fastify.authenticate],
    schema: {
      body: CreateRefundRequestSchema,
      response: {
        200: z.object({
          refund_request: z.any() // RefundRequest type
        })
      }
    }
  }, async (request, reply) => {
    try {
      const refundRequest = await transactionService.createRefundRequest(request.user.id, request.body);
      reply.send({ refund_request: refundRequest });
    } catch (error) {
      fastify.log.error('Create refund request error:', error);

      if (error.message.includes('not found') || 
          error.message.includes('not eligible') ||
          error.message.includes('not owned')) {
        reply.code(400).send({ error: error.message });
      } else {
        reply.code(500).send({ error: 'Failed to create refund request' });
      }
    }
  });

  // Get refund requests
  fastify.get('/refunds', {
    preHandler: [fastify.authenticate],
    schema: {
      querystring: z.object({
        status: z.string().optional(),
        page: z.coerce.number().min(1).default(1),
        limit: z.coerce.number().min(1).max(100).default(20)
      }),
      response: {
        200: z.object({
          refund_requests: z.array(z.any()), // RefundRequest[] type
          total: z.number(),
          page: z.number(),
          limit: z.number(),
          has_more: z.boolean()
        })
      }
    }
  }, async (request, reply) => {
    try {
      const { status, page, limit } = request.query;
      const offset = (page - 1) * limit;

      let whereClause = 'user_id = ?';
      const params = [request.user.id];

      if (status) {
        whereClause += ' AND status = ?';
        params.push(status);
      }

      const refundRequests = await fastify.db.query(
        `SELECT * FROM refund_requests WHERE ${whereClause} ORDER BY created_at DESC LIMIT ? OFFSET ?`,
        [...params, limit, offset]
      );

      const totalResult = await fastify.db.query(
        `SELECT COUNT(*) as count FROM refund_requests WHERE ${whereClause}`,
        params
      );

      const total = totalResult[0].count;
      const hasMore = offset + limit < total;

      reply.send({
        refund_requests: refundRequests,
        total,
        page,
        limit,
        has_more: hasMore
      });
    } catch (error) {
      fastify.log.error('Get refund requests error:', error);
      reply.code(500).send({ error: 'Failed to get refund requests' });
    }
  });

  // =============================================
  // Analytics Routes
  // =============================================

  // Get transaction analytics for user
  fastify.get('/analytics/transactions', {
    preHandler: [fastify.authenticate],
    schema: {
      querystring: z.object({
        period: z.enum(['7d', '30d', '90d', '1y']).default('30d'),
        template_id: z.string().uuid().optional()
      }),
      response: {
        200: z.object({
          analytics: z.any() // TransactionAnalytics type
        })
      }
    }
  }, async (request, reply) => {
    try {
      const { period, template_id } = request.query;

      // Calculate date range
      const periodDays = {
        '7d': 7,
        '30d': 30,
        '90d': 90,
        '1y': 365
      };

      const daysBack = periodDays[period];
      const startDate = new Date();
      startDate.setDate(startDate.getDate() - daysBack);

      let whereClause = 'user_id = ? AND created_at >= ?';
      const params = [request.user.id, startDate.toISOString()];

      if (template_id) {
        whereClause += ' AND EXISTS (SELECT 1 FROM order_items oi WHERE oi.order_id = orders.id AND oi.template_id = ?)';
        params.push(template_id);
      }

      // Get transaction metrics
      const metricsResult = await fastify.db.query(
        `SELECT 
           COUNT(*) as total_transactions,
           SUM(total_cents) as total_revenue_cents,
           AVG(total_cents) as avg_order_value_cents
         FROM orders 
         WHERE ${whereClause} AND status = 'completed'`,
        params
      );

      const metrics = metricsResult[0] || {
        total_transactions: 0,
        total_revenue_cents: 0,
        avg_order_value_cents: 0
      };

      const analytics = {
        period_start: startDate,
        period_end: new Date(),
        metrics: {
          total_revenue_cents: metrics.total_revenue_cents || 0,
          total_transactions: metrics.total_transactions || 0,
          average_order_value_cents: Math.round(metrics.avg_order_value_cents || 0),
          conversion_rate: 0, // Would need view tracking
          refund_rate: 0, // Would calculate from refunds
          dispute_rate: 0, // Would calculate from disputes
          fraud_rate: 0 // Would calculate from fraud flags
        },
        payment_methods: [], // Would aggregate by payment method
        geography: [], // Would aggregate by country
        trends: {
          daily_revenue: [], // Would calculate daily totals
          daily_transactions: [] // Would calculate daily counts
        }
      };

      reply.send({ analytics });
    } catch (error) {
      fastify.log.error('Get transaction analytics error:', error);
      reply.code(500).send({ error: 'Failed to get transaction analytics' });
    }
  });
}

// Epic 16.1.5 - Transaction Service
import { FastifyInstance } from 'fastify';
import Stripe from 'stripe';
import {
  ShoppingCart,
  CartItem,
  PaymentIntent,
  Transaction,
  Order,
  OrderItem,
  TemplateLicense,
  RefundRequest,
  Refund,
  RiskAssessment,
  TaxCalculation,
  PaymentProvider,
  TransactionType,
  EscrowStatus,
  LicenseType,
  LicenseStatus,
  BillingAddress,
  AddToCartSchema,
  UpdateCartSchema,
  CreatePaymentIntentSchema,
  ProcessPaymentSchema,
  CreateRefundRequestSchema
} from './transaction.types.js';
import { MarketplaceTemplate, TemplateVersion } from './types.js';
import { DatabaseService } from '../database/database.service.js';

export class TransactionService {
  private stripe: Stripe;
  private db: DatabaseService;
  private fastify: FastifyInstance;

  constructor(fastify: FastifyInstance) {
    this.fastify = fastify;
    this.db = fastify.db;

    if (!process.env.STRIPE_SECRET_KEY) {
      throw new Error('STRIPE_SECRET_KEY environment variable is required');
    }

    this.stripe = new Stripe(process.env.STRIPE_SECRET_KEY, {
      apiVersion: '2023-10-16',
    });
  }

  // =============================================
  // Shopping Cart Management
  // =============================================

  async createCart(userId: string): Promise<ShoppingCart> {
    const cartId = crypto.randomUUID();
    const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000); // 24 hours

    const cart: ShoppingCart = {
      id: cartId,
      user_id: userId,
      items: [],
      discount_codes: [],
      total_cents: 0,
      tax_cents: 0,
      shipping_cents: 0,
      created_at: new Date(),
      updated_at: new Date(),
      expires_at: expiresAt
    };

    await this.db.query(
      `INSERT INTO shopping_carts (id, user_id, items, discount_codes, total_cents, tax_cents, shipping_cents, created_at, updated_at, expires_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [cartId, userId, JSON.stringify([]), JSON.stringify([]), 0, 0, 0, cart.created_at, cart.updated_at, expiresAt]
    );

    return cart;
  }

  async getCart(cartId: string, userId: string): Promise<ShoppingCart | null> {
    const result = await this.db.query(
      `SELECT * FROM shopping_carts WHERE id = ? AND user_id = ? AND expires_at > datetime('now')`,
      [cartId, userId]
    );

    if (result.length === 0) return null;

    const row = result[0];
    return {
      id: row.id,
      user_id: row.user_id,
      items: JSON.parse(row.items),
      discount_codes: JSON.parse(row.discount_codes),
      total_cents: row.total_cents,
      tax_cents: row.tax_cents,
      shipping_cents: row.shipping_cents,
      created_at: new Date(row.created_at),
      updated_at: new Date(row.updated_at),
      expires_at: new Date(row.expires_at)
    };
  }

  async addToCart(userId: string, cartData: any): Promise<ShoppingCart> {
    const validated = AddToCartSchema.parse(cartData);

    // Get or create cart
    let cart = await this.getActiveCart(userId);
    if (!cart) {
      cart = await this.createCart(userId);
    }

    // Validate templates exist and are purchasable
    for (const item of validated.items) {
      const template = await this.getTemplate(item.template_id);
      if (!template || template.status !== 'listed') {
        throw new Error(`Template ${item.template_id} is not available for purchase`);
      }

      // Check if user already owns this template
      const existingPurchase = await this.checkExistingPurchase(userId, item.template_id);
      if (existingPurchase) {
        throw new Error(`You already own template: ${template.title}`);
      }
    }

    // Add items to cart
    for (const itemData of validated.items) {
      const template = await this.getTemplate(itemData.template_id);
      const version = await this.getTemplateVersion(itemData.template_id, itemData.version_id);

      const cartItem: CartItem = {
        id: crypto.randomUUID(),
        template_id: itemData.template_id,
        version_id: version?.id || template?.current_version_id,
        license_type: itemData.license_type,
        quantity: itemData.quantity,
        unit_price_cents: this.calculateLicensePrice(template!.price_cents, itemData.license_type),
        added_at: new Date()
      };

      cart.items.push(cartItem);
    }

    return await this.updateCartTotals(cart);
  }

  async updateCartItem(userId: string, cartId: string, updateData: any): Promise<ShoppingCart> {
    const validated = UpdateCartSchema.parse(updateData);
    const cart = await this.getCart(cartId, userId);

    if (!cart) {
      throw new Error('Cart not found or expired');
    }

    if (validated.quantity === 0) {
      // Remove item
      cart.items = cart.items.filter(item => item.id !== validated.item_id);
    } else {
      // Update item
      const itemIndex = cart.items.findIndex(item => item.id === validated.item_id);
      if (itemIndex === -1) {
        throw new Error('Cart item not found');
      }

      cart.items[itemIndex].quantity = validated.quantity;
      if (validated.license_type) {
        cart.items[itemIndex].license_type = validated.license_type;
        const template = await this.getTemplate(cart.items[itemIndex].template_id);
        cart.items[itemIndex].unit_price_cents = this.calculateLicensePrice(
          template!.price_cents, 
          validated.license_type
        );
      }
    }

    return await this.updateCartTotals(cart);
  }

  async clearCart(userId: string, cartId: string): Promise<void> {
    await this.db.query(
      `DELETE FROM shopping_carts WHERE id = ? AND user_id = ?`,
      [cartId, userId]
    );
  }

  // =============================================
  // Payment Processing
  // =============================================

  async createPaymentIntent(userId: string, paymentData: any): Promise<PaymentIntent> {
    const validated = CreatePaymentIntentSchema.parse(paymentData);
    const cart = await this.getCart(validated.cart_id, userId);

    if (!cart || cart.items.length === 0) {
      throw new Error('Cart is empty or not found');
    }

    // Calculate final totals with tax
    await this.calculateTax(cart, validated.billing_address);
    const finalCart = await this.updateCartTotals(cart);

    // Perform risk assessment
    const riskAssessment = await this.assessRisk(userId, finalCart, validated.billing_address);

    if (riskAssessment.recommendation === 'decline') {
      throw new Error('Payment declined due to risk factors');
    }

    // Create Stripe payment intent
    const stripeIntent = await this.stripe.paymentIntents.create({
      amount: finalCart.total_cents,
      currency: 'usd',
      payment_method: validated.payment_method_id,
      confirmation_method: 'manual',
      confirm: false,
      capture_method: 'manual', // For escrow system
      metadata: {
        cart_id: finalCart.id,
        user_id: userId,
        risk_score: riskAssessment.risk_score.toString()
      }
    });

    const paymentIntent: PaymentIntent = {
      id: crypto.randomUUID(),
      cart_id: finalCart.id,
      user_id: userId,
      amount_cents: finalCart.total_cents,
      currency: 'usd',
      provider: PaymentProvider.STRIPE,
      provider_intent_id: stripeIntent.id,
      payment_method_id: validated.payment_method_id,
      status: stripeIntent.status as any,
      client_secret: stripeIntent.client_secret || undefined,
      metadata: {
        risk_assessment_id: riskAssessment.id,
        billing_address: validated.billing_address
      },
      created_at: new Date(),
      updated_at: new Date()
    };

    // Save payment intent
    await this.db.query(
      `INSERT INTO payment_intents (id, cart_id, user_id, amount_cents, currency, provider, provider_intent_id, 
       payment_method_id, status, client_secret, metadata, created_at, updated_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        paymentIntent.id, paymentIntent.cart_id, paymentIntent.user_id, paymentIntent.amount_cents,
        paymentIntent.currency, paymentIntent.provider, paymentIntent.provider_intent_id,
        paymentIntent.payment_method_id, paymentIntent.status, paymentIntent.client_secret,
        JSON.stringify(paymentIntent.metadata), paymentIntent.created_at, paymentIntent.updated_at
      ]
    );

    return paymentIntent;
  }

  async processPayment(userId: string, paymentData: any): Promise<Order> {
    const validated = ProcessPaymentSchema.parse(paymentData);
    const paymentIntent = await this.getPaymentIntent(validated.payment_intent_id, userId);

    if (!paymentIntent) {
      throw new Error('Payment intent not found');
    }

    // Confirm payment with Stripe
    const stripeIntent = await this.stripe.paymentIntents.confirm(
      paymentIntent.provider_intent_id,
      {
        payment_method: paymentIntent.payment_method_id,
        return_url: `${process.env.CLIENT_URL}/payment/return`
      }
    );

    // Update payment intent status
    await this.updatePaymentIntentStatus(paymentIntent.id, stripeIntent.status as any);

    if (stripeIntent.status === 'succeeded') {
      // Create transaction record
      const transaction = await this.createTransaction(paymentIntent, TransactionType.PURCHASE);

      // Create order and fulfill
      const order = await this.createOrder(paymentIntent, transaction);
      await this.fulfillOrder(order);

      // Clear cart
      await this.clearCart(userId, paymentIntent.cart_id);

      return order;
    } else if (stripeIntent.status === 'requires_action') {
      throw new Error('Payment requires additional authentication');
    } else {
      throw new Error('Payment failed');
    }
  }

  // =============================================
  // Order Management
  // =============================================

  async createOrder(paymentIntent: PaymentIntent, transaction: Transaction): Promise<Order> {
    const cart = await this.getCart(paymentIntent.cart_id, paymentIntent.user_id);
    if (!cart) throw new Error('Cart not found');

    const orderId = crypto.randomUUID();
    const orderNumber = this.generateOrderNumber();
    const billingAddress = paymentIntent.metadata.billing_address as BillingAddress;

    const order: Order = {
      id: orderId,
      user_id: paymentIntent.user_id,
      cart_id: cart.id,
      payment_intent_id: paymentIntent.id,
      order_number: orderNumber,
      status: 'processing',
      items: [],
      subtotal_cents: cart.total_cents - cart.tax_cents,
      tax_cents: cart.tax_cents,
      discount_cents: 0,
      total_cents: cart.total_cents,
      currency: paymentIntent.currency,
      billing_address: billingAddress,
      fulfillment_status: 'pending',
      metadata: {},
      created_at: new Date(),
      updated_at: new Date()
    };

    // Create order items
    for (const cartItem of cart.items) {
      const orderItem: OrderItem = {
        id: crypto.randomUUID(),
        order_id: orderId,
        template_id: cartItem.template_id,
        version_id: cartItem.version_id!,
        license_type: cartItem.license_type,
        quantity: cartItem.quantity,
        unit_price_cents: cartItem.unit_price_cents,
        total_price_cents: cartItem.unit_price_cents * cartItem.quantity,
        fulfillment_status: 'pending',
        metadata: {}
      };
      order.items.push(orderItem);
    }

    // Save order
    await this.db.query(
      `INSERT INTO orders (id, user_id, cart_id, payment_intent_id, order_number, status, subtotal_cents, 
       tax_cents, discount_cents, total_cents, currency, billing_address, fulfillment_status, metadata, created_at, updated_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        orderId, order.user_id, order.cart_id, order.payment_intent_id, order.order_number,
        order.status, order.subtotal_cents, order.tax_cents, order.discount_cents, order.total_cents,
        order.currency, JSON.stringify(order.billing_address), order.fulfillment_status,
        JSON.stringify(order.metadata), order.created_at, order.updated_at
      ]
    );

    // Save order items
    for (const item of order.items) {
      await this.db.query(
        `INSERT INTO order_items (id, order_id, template_id, version_id, license_type, quantity, 
         unit_price_cents, total_price_cents, fulfillment_status, metadata)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          item.id, item.order_id, item.template_id, item.version_id, item.license_type,
          item.quantity, item.unit_price_cents, item.total_price_cents, item.fulfillment_status,
          JSON.stringify(item.metadata)
        ]
      );
    }

    return order;
  }

  async fulfillOrder(order: Order): Promise<void> {
    try {
      // Generate licenses for each item
      for (const item of order.items) {
        const license = await this.generateLicense(order, item);

        // Update order item with license
        await this.db.query(
          `UPDATE order_items SET license_id = ?, fulfillment_status = 'fulfilled' WHERE id = ?`,
          [license.id, item.id]
        );
      }

      // Update order status
      await this.db.query(
        `UPDATE orders SET status = 'completed', fulfillment_status = 'fulfilled', completed_at = datetime('now') WHERE id = ?`,
        [order.id]
      );

      // Generate invoice
      await this.generateInvoice(order);

      // Send confirmation email (placeholder)
      this.fastify.log.info(`Order ${order.order_number} fulfilled successfully`);

    } catch (error) {
      this.fastify.log.error('Order fulfillment failed:', error);

      // Update order status to failed
      await this.db.query(
        `UPDATE orders SET fulfillment_status = 'failed' WHERE id = ?`,
        [order.id]
      );

      throw error;
    }
  }

  // =============================================
  // License Management
  // =============================================

  async generateLicense(order: Order, orderItem: OrderItem): Promise<TemplateLicense> {
    const licenseId = crypto.randomUUID();
    const licenseKey = this.generateLicenseKey();

    const license: TemplateLicense = {
      id: licenseId,
      purchase_id: order.id,
      template_id: orderItem.template_id,
      version_id: orderItem.version_id,
      buyer_id: order.user_id,
      license_type: orderItem.license_type,
      license_key: licenseKey,
      status: LicenseStatus.ACTIVE,
      usage_limit: this.getLicenseUsageLimit(orderItem.license_type),
      usage_count: 0,
      valid_from: new Date(),
      valid_until: this.getLicenseExpiration(orderItem.license_type),
      transfer_count: 0,
      max_transfers: this.getMaxTransfers(orderItem.license_type),
      restrictions: this.getLicenseRestrictions(orderItem.license_type),
      metadata: {},
      created_at: new Date(),
      updated_at: new Date()
    };

    await this.db.query(
      `INSERT INTO template_licenses (id, purchase_id, template_id, version_id, buyer_id, license_type, 
       license_key, status, usage_limit, usage_count, valid_from, valid_until, transfer_count, max_transfers, 
       restrictions, metadata, created_at, updated_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        licenseId, license.purchase_id, license.template_id, license.version_id, license.buyer_id,
        license.license_type, license.license_key, license.status, license.usage_limit,
        license.usage_count, license.valid_from, license.valid_until, license.transfer_count,
        license.max_transfers, JSON.stringify(license.restrictions), JSON.stringify(license.metadata),
        license.created_at, license.updated_at
      ]
    );

    return license;
  }

  async validateLicense(licenseKey: string, templateId: string, userId: string): Promise<boolean> {
    const result = await this.db.query(
      `SELECT * FROM template_licenses WHERE license_key = ? AND template_id = ? AND buyer_id = ? AND status = 'active'`,
      [licenseKey, templateId, userId]
    );

    if (result.length === 0) return false;

    const license = result[0];

    // Check expiration
    if (license.valid_until && new Date() > new Date(license.valid_until)) {
      return false;
    }

    // Check usage limits
    if (license.usage_limit && license.usage_count >= license.usage_limit) {
      return false;
    }

    // Update usage count
    await this.db.query(
      `UPDATE template_licenses SET usage_count = usage_count + 1, last_used_at = datetime('now') WHERE id = ?`,
      [license.id]
    );

    return true;
  }

  // =============================================
  // Refund Processing
  // =============================================

  async createRefundRequest(userId: string, refundData: any): Promise<RefundRequest> {
    const validated = CreateRefundRequestSchema.parse(refundData);

    // Verify purchase ownership
    const purchase = await this.getUserPurchase(userId, validated.purchase_id);
    if (!purchase) {
      throw new Error('Purchase not found or not owned by user');
    }

    // Check refund eligibility
    if (!this.isRefundEligible(purchase)) {
      throw new Error('Purchase is not eligible for refund');
    }

    const refundRequestId = crypto.randomUUID();
    const refundAmount = validated.amount_cents || purchase.total_cents;

    const refundRequest: RefundRequest = {
      id: refundRequestId,
      purchase_id: validated.purchase_id,
      order_id: purchase.id,
      user_id: userId,
      reason: validated.reason,
      amount_cents: refundAmount,
      status: 'pending',
      created_at: new Date()
    };

    await this.db.query(
      `INSERT INTO refund_requests (id, purchase_id, order_id, user_id, reason, amount_cents, status, created_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
      [refundRequestId, refundRequest.purchase_id, refundRequest.order_id, refundRequest.user_id,
       refundRequest.reason, refundRequest.amount_cents, refundRequest.status, refundRequest.created_at]
    );

    return refundRequest;
  }

  // =============================================
  // Helper Methods
  // =============================================

  private async getActiveCart(userId: string): Promise<ShoppingCart | null> {
    const result = await this.db.query(
      `SELECT * FROM shopping_carts WHERE user_id = ? AND expires_at > datetime('now') ORDER BY created_at DESC LIMIT 1`,
      [userId]
    );

    if (result.length === 0) return null;

    const row = result[0];
    return {
      id: row.id,
      user_id: row.user_id,
      items: JSON.parse(row.items),
      discount_codes: JSON.parse(row.discount_codes),
      total_cents: row.total_cents,
      tax_cents: row.tax_cents,
      shipping_cents: row.shipping_cents,
      created_at: new Date(row.created_at),
      updated_at: new Date(row.updated_at),
      expires_at: new Date(row.expires_at)
    };
  }

  private async updateCartTotals(cart: ShoppingCart): Promise<ShoppingCart> {
    const subtotal = cart.items.reduce((sum, item) => sum + (item.unit_price_cents * item.quantity), 0);
    cart.total_cents = subtotal + cart.tax_cents + cart.shipping_cents;
    cart.updated_at = new Date();

    await this.db.query(
      `UPDATE shopping_carts SET items = ?, total_cents = ?, updated_at = ? WHERE id = ?`,
      [JSON.stringify(cart.items), cart.total_cents, cart.updated_at, cart.id]
    );

    return cart;
  }

  private calculateLicensePrice(basePrice: number, licenseType: LicenseType): number {
    const multipliers = {
      [LicenseType.PERSONAL]: 1.0,
      [LicenseType.COMMERCIAL]: 2.0,
      [LicenseType.ENTERPRISE]: 5.0,
      [LicenseType.EDUCATIONAL]: 0.5,
      [LicenseType.UNLIMITED]: 10.0
    };
    return Math.round(basePrice * (multipliers[licenseType] || 1.0));
  }

  private async calculateTax(cart: ShoppingCart, billingAddress: BillingAddress): Promise<void> {
    // Simple tax calculation - in production, use a tax service like TaxJar
    const taxRate = billingAddress.country === 'US' ? 0.08 : 0.0;
    const subtotal = cart.items.reduce((sum, item) => sum + (item.unit_price_cents * item.quantity), 0);
    cart.tax_cents = Math.round(subtotal * taxRate);
  }

  private async assessRisk(userId: string, cart: ShoppingCart, billingAddress: BillingAddress): Promise<RiskAssessment> {
    // Simplified risk assessment - in production, use more sophisticated analysis
    let riskScore = 0;
    const riskFactors: string[] = [];

    // High value transaction
    if (cart.total_cents > 10000) { // $100+
      riskScore += 30;
      riskFactors.push('high_value_transaction');
    }

    // New user
    const userAge = await this.getUserAge(userId);
    if (userAge < 7) { // Less than a week
      riskScore += 20;
      riskFactors.push('new_user');
    }

    // Velocity check
    const recentTransactions = await this.getRecentTransactionCount(userId);
    if (recentTransactions > 5) {
      riskScore += 25;
      riskFactors.push('high_velocity');
    }

    const recommendation = riskScore > 70 ? 'decline' : riskScore > 40 ? 'review' : 'approve';

    const assessment: RiskAssessment = {
      id: crypto.randomUUID(),
      payment_intent_id: '', // Will be set later
      user_id: userId,
      ip_address: '',
      user_agent: '',
      risk_score: riskScore,
      risk_factors: riskFactors,
      geo_location: { country: billingAddress.country },
      velocity_checks: { recent_transactions: recentTransactions },
      recommendation: recommendation as any,
      automated_decision: true,
      created_at: new Date()
    };

    return assessment;
  }

  private generateOrderNumber(): string {
    const timestamp = Date.now().toString(36);
    const random = Math.random().toString(36).substring(2, 8);
    return `ORD-${timestamp}-${random}`.toUpperCase();
  }

  private generateLicenseKey(): string {
    const segments = [];
    for (let i = 0; i < 4; i++) {
      segments.push(Math.random().toString(36).substring(2, 8).toUpperCase());
    }
    return segments.join('-');
  }

  private getLicenseUsageLimit(licenseType: LicenseType): number | undefined {
    const limits = {
      [LicenseType.PERSONAL]: 100,
      [LicenseType.COMMERCIAL]: 1000,
      [LicenseType.ENTERPRISE]: 10000,
      [LicenseType.EDUCATIONAL]: 50,
      [LicenseType.UNLIMITED]: undefined
    };
    return limits[licenseType];
  }

  private getLicenseExpiration(licenseType: LicenseType): Date | undefined {
    if (licenseType === LicenseType.UNLIMITED) return undefined;

    const now = new Date();
    const expiration = new Date(now);
    expiration.setFullYear(now.getFullYear() + 1); // 1 year
    return expiration;
  }

  private getMaxTransfers(licenseType: LicenseType): number {
    const transfers = {
      [LicenseType.PERSONAL]: 1,
      [LicenseType.COMMERCIAL]: 3,
      [LicenseType.ENTERPRISE]: 10,
      [LicenseType.EDUCATIONAL]: 1,
      [LicenseType.UNLIMITED]: 5
    };
    return transfers[licenseType] || 1;
  }

  private getLicenseRestrictions(licenseType: LicenseType): Record<string, any> {
    const restrictions = {
      [LicenseType.PERSONAL]: {
        commercial_use: false,
        redistribution: false,
        modification: true
      },
      [LicenseType.COMMERCIAL]: {
        commercial_use: true,
        redistribution: false,
        modification: true
      },
      [LicenseType.ENTERPRISE]: {
        commercial_use: true,
        redistribution: true,
        modification: true,
        white_label: true
      },
      [LicenseType.EDUCATIONAL]: {
        commercial_use: false,
        redistribution: false,
        modification: true,
        educational_only: true
      },
      [LicenseType.UNLIMITED]: {
        commercial_use: true,
        redistribution: true,
        modification: true,
        white_label: true
      }
    };
    return restrictions[licenseType] || {};
  }

