  /**
   * Setup metrics event listeners
   */
  private setupMetricsListeners(): void {
    this.metricsCollector.on('alert_created', (alert: PerformanceAlert) => {
      this.broadcastAlert(alert);
    });

    this.metricsCollector.on('system_metrics', () => {
      if (this.isActive && this.dashboardClients.size > 0) {
        // Throttled updates to avoid overwhelming clients
        setTimeout(() => this.broadcastUpdate(), 100);
      }
    });
  }

  /**
   * Generate current dashboard data
   */
  private generateDashboardData(): DashboardData {
    const currentMetrics = this.metricsCollector.getCurrentMetrics();
    const activeAlerts = this.metricsCollector.getActiveAlerts();
    const recentAlerts = this.getRecentAlerts();
    const connectionInfo = this.getConnectionInfo();
    const trends = this.calculateCurrentTrends();
    const health = this.calculateHealthScores(currentMetrics, activeAlerts);
    const recommendations = this.generateCurrentRecommendations(currentMetrics, activeAlerts);

    return {
      timestamp: Date.now(),
      health,
      metrics: {
        current: currentMetrics,
        trends
      },
      alerts: {
        active: activeAlerts,
        recent: recentAlerts,
        count: {
          total: activeAlerts.length,
          critical: activeAlerts.filter(a => a.severity === 'critical').length,
          warning: activeAlerts.filter(a => a.severity === 'warning').length
        }
      },
      connections: connectionInfo,
      recommendations
    };
  }

  /**
   * Calculate health scores for different systems
   */
  private calculateHealthScores(metrics: any, alerts: PerformanceAlert[]): any {
    const systemHealth = this.calculateSystemHealth(metrics.system, alerts);
    const webSocketHealth = this.calculateWebSocketHealth(metrics.webSocket, alerts);
    const collaborationHealth = this.calculateCollaborationHealth(metrics.collaboration, alerts);

    const overall = Math.round((systemHealth + webSocketHealth + collaborationHealth) / 3);

    return {
      overall,
      system: systemHealth,
      webSocket: webSocketHealth,
      collaboration: collaborationHealth
    };
  }

  /**
   * Calculate system health score
   */
  private calculateSystemHealth(systemMetrics: SystemMetrics | null, alerts: PerformanceAlert[]): number {
    if (!systemMetrics) return 50;

    let score = 100;

    // Deduct for high CPU usage
    if (systemMetrics.cpuUsage > 80) score -= 30;
    else if (systemMetrics.cpuUsage > 60) score -= 15;

    // Deduct for high memory usage
    if (systemMetrics.memoryUsage.percentage > 85) score -= 25;
    else if (systemMetrics.memoryUsage.percentage > 70) score -= 10;

    // Deduct for system-related alerts
    const systemAlerts = alerts.filter(a => a.metric.includes('cpu') || a.metric.includes('memory'));
    score -= systemAlerts.filter(a => a.severity === 'critical').length * 20;
    score -= systemAlerts.filter(a => a.severity === 'warning').length * 10;

    return Math.max(0, Math.min(100, Math.round(score)));
  }

  /**
   * Calculate WebSocket health score
   */
  private calculateWebSocketHealth(wsMetrics: WebSocketMetrics | null, alerts: PerformanceAlert[]): number {
    if (!wsMetrics) return 50;

    let score = 100;

    // Deduct for high latency
    if (wsMetrics.messageLatency > 1000) score -= 25;
    else if (wsMetrics.messageLatency > 500) score -= 10;

    // Deduct for high error rate
    if (wsMetrics.errorRate > 5) score -= 30;
    else if (wsMetrics.errorRate > 2) score -= 15;

    // Deduct for WebSocket-related alerts
    const wsAlerts = alerts.filter(a => a.metric.includes('message') || a.metric.includes('error'));
    score -= wsAlerts.filter(a => a.severity === 'critical').length * 20;
    score -= wsAlerts.filter(a => a.severity === 'warning').length * 10;

    return Math.max(0, Math.min(100, Math.round(score)));
  }

  /**
   * Calculate collaboration health score
   */
  private calculateCollaborationHealth(collabMetrics: CollaborationMetrics | null, alerts: PerformanceAlert[]): number {
    if (!collabMetrics) return 50;

    let score = 100;

    // Deduct for slow conflict resolution
    if (collabMetrics.conflictResolutionTime > 5000) score -= 25;
    else if (collabMetrics.conflictResolutionTime > 2000) score -= 10;

    // Deduct for high sync latency
    if (collabMetrics.synchronizationLatency > 2000) score -= 20;
    else if (collabMetrics.synchronizationLatency > 1000) score -= 10;

    // Deduct for collaboration-related alerts
    const collabAlerts = alerts.filter(a => a.metric.includes('conflict') || a.metric.includes('sync'));
    score -= collabAlerts.filter(a => a.severity === 'critical').length * 20;
    score -= collabAlerts.filter(a => a.severity === 'warning').length * 10;

    return Math.max(0, Math.min(100, Math.round(score)));
  }

  /**
   * Get recent alerts (last hour)
   */
  private getRecentAlerts(): PerformanceAlert[] {
    const oneHourAgo = Date.now() - 3600000;
    return this.metricsCollector.getMetricsWindow(oneHourAgo, Date.now()).systemMetrics
      .map(() => []) // Simplified - would get actual recent alerts
      .flat();
  }

  /**
   * Get connection information
   */
  private getConnectionInfo(): any {
    if (!this.wsServer) {
      return {
        total: 0,
        activeDocuments: 0,
        averageUsersPerDocument: 0,
        recentConnections: 0,
        recentDisconnections: 0
      };
    }

    const healthMetrics = this.wsServer.getHealthMetrics();
    const documentSessions = this.wsServer.getDocumentSessions();

    return {
      total: healthMetrics.totalConnections,
      activeDocuments: documentSessions.activeDocuments,
      averageUsersPerDocument: documentSessions.activeDocuments > 0 
        ? healthMetrics.totalConnections / documentSessions.activeDocuments 
        : 0,
      recentConnections: 0, // Would track recent connections
      recentDisconnections: 0 // Would track recent disconnections
    };
  }

  /**
   * Calculate current performance trends
   */
  private calculateCurrentTrends(): any {
    const endTime = Date.now();
    const startTime = endTime - this.config.historyWindow;
    const window = this.metricsCollector.getMetricsWindow(startTime, endTime);

    return {
      cpuTrend: window.systemMetrics.slice(-20).map(m => m.cpuUsage),
      memoryTrend: window.systemMetrics.slice(-20).map(m => m.memoryUsage.percentage),
      latencyTrend: window.webSocketMetrics.slice(-20).map(m => m.messageLatency),
      errorRateTrend: window.webSocketMetrics.slice(-20).map(m => m.errorRate)
    };
  }

  /**
   * Generate current recommendations
   */
  private generateCurrentRecommendations(metrics: any, alerts: PerformanceAlert[]): string[] {
    const recommendations: string[] = [];

    if (alerts.length > this.config.alertThreshold) {
      recommendations.push(`High alert count (${alerts.length}). Consider investigating underlying issues.`);
    }

    if (metrics.system?.cpuUsage > 80) {
      recommendations.push('CPU usage is high. Consider scaling or optimizing processes.');
    }

    if (metrics.system?.memoryUsage.percentage > 85) {
      recommendations.push('Memory usage is critical. Implement garbage collection or add more memory.');
    }

    if (metrics.webSocket?.messageLatency > 1000) {
      recommendations.push('WebSocket latency is high. Optimize message processing or check network conditions.');
    }

    if (alerts.filter(a => a.severity === 'critical').length > 0) {
      recommendations.push('Critical alerts detected. Immediate attention required.');
    }

    if (recommendations.length === 0) {
      recommendations.push('System is performing well. Continue monitoring.');
    }

    return recommendations;
  }

  /**
   * Calculate average health over a time window
   */
  private calculateAverageHealth(window: any): number {
    // Simplified calculation - would be more sophisticated in real implementation
    const alertCount = window.systemMetrics.length + window.webSocketMetrics.length + window.collaborationMetrics.length;
    return Math.max(0, 100 - (alertCount * 2));
  }

  /**
   * Calculate performance trends
   */
  private calculateTrends(window: any): any {
    return {
      cpuTrend: this.calculateTrendDirection(window.systemMetrics.map((m: SystemMetrics) => m.cpuUsage)),
      memoryTrend: this.calculateTrendDirection(window.systemMetrics.map((m: SystemMetrics) => m.memoryUsage.percentage)),
      latencyTrend: this.calculateTrendDirection(window.webSocketMetrics.map((m: WebSocketMetrics) => m.messageLatency)),
      errorRateTrend: this.calculateTrendDirection(window.webSocketMetrics.map((m: WebSocketMetrics) => m.errorRate))
    };
  }

  /**
   * Calculate trend direction (up, down, stable)
   */
  private calculateTrendDirection(values: number[]): string {
    if (values.length < 2) return 'stable';

    const recent = values.slice(-5);
    const earlier = values.slice(-10, -5);

    if (recent.length === 0 || earlier.length === 0) return 'stable';

    const recentAvg = recent.reduce((a, b) => a + b, 0) / recent.length;
    const earlierAvg = earlier.reduce((a, b) => a + b, 0) / earlier.length;

    const change = ((recentAvg - earlierAvg) / earlierAvg) * 100;

    if (change > 5) return 'up';
    if (change < -5) return 'down';
    return 'stable';
  }

  /**
   * Generate insights from performance data
   */
  private generateInsights(aggregated: any, window: any): string[] {
    const insights: string[] = [];

    // Performance insights
    if (aggregated.system?.cpu.mean > 70) {
      insights.push('Sustained high CPU usage detected. Consider horizontal scaling.');
    }

    if (aggregated.webSocket?.messageLatency.p95 > 2000) {
      insights.push('95th percentile message latency is concerning. Network optimization needed.');
    }

    if (aggregated.collaboration?.conflictRate.mean > 0.1) {
      insights.push('High conflict rate suggests user workflow improvements needed.');
    }

    return insights;
  }

  /**
   * Broadcast dashboard update to all clients
   */
  private broadcastUpdate(): void {
    if (this.dashboardClients.size === 0) {
      return;
    }

    const dashboardData = this.generateDashboardData();

    this.dashboardClients.forEach(client => {
      this.sendToClient(client, dashboardData);
    });
  }

  /**
   * Broadcast alert to all clients
   */
  private broadcastAlert(alert: PerformanceAlert): void {
    this.dashboardClients.forEach(client => {
      this.sendToClient(client, { type: 'alert', alert });
    });
  }

  /**
   * Send data to a specific client
   */
  private sendToClient(client: any, data: any): void {
    try {
      if (client.send && typeof client.send === 'function') {
        client.send(JSON.stringify(data));
      } else if (client.write && typeof client.write === 'function') {
        client.write(JSON.stringify(data));
      }
    } catch (error) {
      console.error('Failed to send data to dashboard client:', error);
      this.dashboardClients.delete(client);
    }
  }

  /**
   * Get health class for styling
   */
  private getHealthClass(score: number): string {
    if (score >= 90) return 'excellent';
    if (score >= 75) return 'good';
    if (score >= 50) return 'warning';
    return 'critical';
  }
}

import { EventEmitter } from 'events';
import { WebSocketServer } from '../websocket/WebSocketServer';
import { MetricsCollector, PerformanceAlert } from './MetricsCollector';

/**
 * Optimization strategy configuration
 */
export interface OptimizationStrategy {
  name: string;
  description: string;
  enabled: boolean;
  priority: 'low' | 'medium' | 'high' | 'critical';
  triggerConditions: {
    cpuThreshold?: number;
    memoryThreshold?: number;
    latencyThreshold?: number;
    errorRateThreshold?: number;
    connectionCountThreshold?: number;
  };
  actions: OptimizationAction[];
}

/**
 * Optimization action types
 */
export interface OptimizationAction {
  type: 'throttle' | 'batch' | 'cache' | 'compress' | 'prioritize' | 'scale' | 'cleanup';
  target: string;
  parameters: any;
  description: string;
}

/**
 * Optimization result
 */
export interface OptimizationResult {
  strategyName: string;
  actionsExecuted: OptimizationAction[];
  startTime: number;
  endTime: number;
  success: boolean;
  metricsImprovement: {
    cpuReduction?: number;
    memoryReduction?: number;
    latencyReduction?: number;
    errorRateReduction?: number;
  };
  errors: string[];
}

/**
 * Performance optimizer for collaborative editing system
 */
export class PerformanceOptimizer extends EventEmitter {
  private wsServer: WebSocketServer | null = null;
  private metricsCollector: MetricsCollector;
  private strategies: Map<string, OptimizationStrategy> = new Map();
  private optimizationHistory: OptimizationResult[] = [];
  private isActive: boolean = false;
  private monitoringInterval: NodeJS.Timeout | null = null;
  private messageBuffer: Map<string, any[]> = new Map();
  private responseCache: Map<string, any> = new Map();
  private connectionPools: Map<string, any[]> = new Map();

  constructor(metricsCollector: MetricsCollector) {
    super();
    this.metricsCollector = metricsCollector;
    this.initializeStrategies();
    this.setupEventListeners();
  }

  /**
   * Set WebSocket server reference
   */
  setWebSocketServer(wsServer: WebSocketServer): void {
    this.wsServer = wsServer;
  }

  /**
   * Start performance optimization monitoring
   */
  start(): void {
    if (this.isActive) {
      return;
    }

    this.isActive = true;
    console.log('Starting performance optimizer');

    // Monitor performance metrics every 10 seconds
    this.monitoringInterval = setInterval(() => {
      this.evaluateOptimizations();
    }, 10000);

    this.emit('optimizer_started');
  }

  /**
   * Stop performance optimization
   */
  stop(): void {
    if (!this.isActive) {
      return;
    }

    this.isActive = false;
    console.log('Stopping performance optimizer');

    if (this.monitoringInterval) {
      clearInterval(this.monitoringInterval);
      this.monitoringInterval = null;
    }

    this.emit('optimizer_stopped');
  }

  /**
   * Add or update optimization strategy
   */
  addStrategy(strategy: OptimizationStrategy): void {
    this.strategies.set(strategy.name, strategy);
    this.emit('strategy_added', strategy);
  }

  /**
   * Remove optimization strategy
   */
  removeStrategy(strategyName: string): boolean {
    const removed = this.strategies.delete(strategyName);
    if (removed) {
      this.emit('strategy_removed', strategyName);
    }
    return removed;
  }

  /**
   * Enable or disable a strategy
   */
  setStrategyEnabled(strategyName: string, enabled: boolean): boolean {
    const strategy = this.strategies.get(strategyName);
    if (strategy) {
      strategy.enabled = enabled;
      this.emit('strategy_updated', strategy);
      return true;
    }
    return false;
  }

  /**
   * Force execute a specific optimization strategy
   */
  async executeStrategy(strategyName: string): Promise<OptimizationResult> {
    const strategy = this.strategies.get(strategyName);
    if (!strategy) {
      throw new Error(`Strategy not found: ${strategyName}`);
    }

    console.log(`Executing optimization strategy: ${strategyName}`);
    return await this.applyOptimization(strategy);
  }

  /**
   * Get optimization history
   */
  getOptimizationHistory(): OptimizationResult[] {
    return [...this.optimizationHistory];
  }

  /**
   * Get current optimization strategies
   */
  getStrategies(): OptimizationStrategy[] {
    return Array.from(this.strategies.values());
  }

  /**
   * Get performance recommendations
   */
  getRecommendations(): string[] {
    const currentMetrics = this.metricsCollector.getCurrentMetrics();
    const activeAlerts = this.metricsCollector.getActiveAlerts();

    return this.generateRecommendations(currentMetrics, activeAlerts);
  }

  /**
   * WebSocket message batching optimization
   */
  optimizeMessageBatching(documentId: string, messages: any[]): any[] {
    const bufferKey = `${documentId}_batch`;

    if (!this.messageBuffer.has(bufferKey)) {
      this.messageBuffer.set(bufferKey, []);
    }

    const buffer = this.messageBuffer.get(bufferKey)!;
    buffer.push(...messages);

    // Batch messages every 100ms or when buffer reaches 10 messages
    if (buffer.length >= 10) {
      const batchedMessages = this.createMessageBatch(buffer);
      this.messageBuffer.set(bufferKey, []);
      return batchedMessages;
    }

    return [];
  }

  /**
   * Response caching optimization
   */
  getCachedResponse(key: string): any | null {
    return this.responseCache.get(key) || null;
  }

  /**
   * Set cached response
   */
  setCachedResponse(key: string, response: any, ttl: number = 60000): void {
    this.responseCache.set(key, response);

    // Auto-expire cache entries
    setTimeout(() => {
      this.responseCache.delete(key);
    }, ttl);
  }

  /**
   * Connection pooling optimization
   */
  getConnectionPool(documentId: string): any[] {
    return this.connectionPools.get(documentId) || [];
  }

  /**
   * Initialize default optimization strategies
   */
  private initializeStrategies(): void {
    // Message batching strategy
    this.addStrategy({
      name: 'message_batching',
      description: 'Batch WebSocket messages to reduce network overhead',
      enabled: true,
      priority: 'medium',
      triggerConditions: {
        latencyThreshold: 500,
        connectionCountThreshold: 10
      },
      actions: [
        {
          type: 'batch',
          target: 'websocket_messages',
          parameters: { batchSize: 10, batchInterval: 100 },
          description: 'Batch WebSocket messages for efficient transmission'
        }
      ]
    });

    // Response caching strategy
    this.addStrategy({
      name: 'response_caching',
      description: 'Cache frequently requested responses',
      enabled: true,
      priority: 'medium',
      triggerConditions: {
        cpuThreshold: 70,
        latencyThreshold: 1000
      },
      actions: [
        {
          type: 'cache',
          target: 'graph_operations',
          parameters: { ttl: 60000, maxEntries: 1000 },
          description: 'Cache graph operation results'
        }
      ]
    });

    // Connection throttling strategy
    this.addStrategy({
      name: 'connection_throttling',
      description: 'Throttle new connections under high load',
      enabled: true,
      priority: 'high',
      triggerConditions: {
        cpuThreshold: 85,
        memoryThreshold: 90,
        connectionCountThreshold: 100
      },
      actions: [
        {
          type: 'throttle',
          target: 'new_connections',
          parameters: { maxPerSecond: 5, queueSize: 50 },
          description: 'Limit new connection rate'
        }
      ]
    });

    // Message compression strategy
    this.addStrategy({
      name: 'message_compression',
      description: 'Compress large WebSocket messages',
      enabled: true,
      priority: 'low',
      triggerConditions: {
        latencyThreshold: 2000
      },
      actions: [
        {
          type: 'compress',
          target: 'large_messages',
          parameters: { threshold: 1024, algorithm: 'gzip' },
          description: 'Compress messages larger than 1KB'
        }
      ]
    });

    // Priority queue strategy
    this.addStrategy({
      name: 'message_prioritization',
      description: 'Prioritize critical messages over less important ones',
      enabled: true,
      priority: 'medium',
      triggerConditions: {
        latencyThreshold: 1500,
        connectionCountThreshold: 20
      },
      actions: [
        {
          type: 'prioritize',
          target: 'message_queue',
          parameters: { 
            priorities: {
              'graph_update': 1,
              'conflict_resolution': 1,
              'presence_update': 2,
              'cursor_update': 3
            }
          },
          description: 'Process critical messages first'
        }
      ]
    });

    // Memory cleanup strategy
    this.addStrategy({
      name: 'memory_cleanup',
      description: 'Clean up old data and force garbage collection',
      enabled: true,
      priority: 'critical',
      triggerConditions: {
        memoryThreshold: 85
      },
      actions: [
        {
          type: 'cleanup',
          target: 'memory',
          parameters: { 
            cleanupTypes: ['old_sessions', 'expired_cache', 'disconnected_users'],
            forceGC: true
          },
          description: 'Clean up memory and run garbage collection'
        }
      ]
    });

    // Conflict resolution optimization
    this.addStrategy({
      name: 'conflict_resolution_optimization',
      description: 'Optimize conflict resolution for high-conflict scenarios',
      enabled: true,
      priority: 'high',
      triggerConditions: {
        latencyThreshold: 3000
      },
      actions: [
        {
          type: 'batch',
          target: 'conflict_operations',
          parameters: { batchSize: 5, timeout: 200 },
          description: 'Batch conflict resolution operations'
        },
        {
          type: 'prioritize',
          target: 'conflict_queue',
          parameters: { strategy: 'fifo_with_merge' },
          description: 'Prioritize and merge similar conflicts'
        }
      ]
    });
  }

  /**
   * Evaluate current performance and apply optimizations
   */
  private async evaluateOptimizations(): Promise<void> {
    if (!this.isActive) {
      return;
    }

    const currentMetrics = this.metricsCollector.getCurrentMetrics();
    const activeAlerts = this.metricsCollector.getActiveAlerts();

    // Check each strategy's trigger conditions
    for (const strategy of this.strategies.values()) {
      if (!strategy.enabled) {
        continue;
      }

      if (await this.shouldTriggerStrategy(strategy, currentMetrics, activeAlerts)) {
        try {
          const result = await this.applyOptimization(strategy);
          this.optimizationHistory.push(result);

          // Keep only last 100 optimization results
          if (this.optimizationHistory.length > 100) {
            this.optimizationHistory.splice(0, this.optimizationHistory.length - 100);
          }

          this.emit('optimization_applied', result);
        } catch (error) {
          console.error(`Failed to apply optimization ${strategy.name}:`, error);
          this.emit('optimization_failed', strategy, error);
        }
      }
    }
  }

  /**
   * Check if strategy should be triggered
   */
  private async shouldTriggerStrategy(
    strategy: OptimizationStrategy, 
    metrics: any, 
    alerts: PerformanceAlert[]
  ): Promise<boolean> {
    const conditions = strategy.triggerConditions;

    // Check CPU threshold
    if (conditions.cpuThreshold && metrics.system?.cpuUsage > conditions.cpuThreshold) {
      return true;
    }

    // Check memory threshold
    if (conditions.memoryThreshold && metrics.system?.memoryUsage?.percentage > conditions.memoryThreshold) {
      return true;
    }

    // Check latency threshold
    if (conditions.latencyThreshold && metrics.webSocket?.messageLatency > conditions.latencyThreshold) {
      return true;
    }

    // Check error rate threshold
    if (conditions.errorRateThreshold && metrics.webSocket?.errorRate > conditions.errorRateThreshold) {
      return true;
    }

    // Check connection count threshold
    if (conditions.connectionCountThreshold && this.wsServer) {
      const healthMetrics = this.wsServer.getHealthMetrics();
      if (healthMetrics.totalConnections > conditions.connectionCountThreshold) {
        return true;
      }
    }

    // Check for relevant alerts
    const relevantAlerts = alerts.filter(alert => 
      this.isAlertRelevantToStrategy(alert, strategy)
    );

    return relevantAlerts.length > 0;
  }

  /**
   * Check if alert is relevant to strategy
   */
  private isAlertRelevantToStrategy(alert: PerformanceAlert, strategy: OptimizationStrategy): boolean {
    const strategyTargets = strategy.actions.map(action => action.target);

    // Map alert metrics to strategy targets
    const alertTargetMap: {[key: string]: string[]} = {
      'cpu_usage': ['memory', 'new_connections'],
      'memory_usage': ['memory', 'memory_cleanup'],
      'message_latency': ['websocket_messages', 'large_messages', 'message_queue'],
      'error_rate': ['new_connections', 'message_queue'],
      'conflict_resolution_time': ['conflict_operations', 'conflict_queue']
    };

    const relevantTargets = alertTargetMap[alert.metric] || [];
    return relevantTargets.some(target => strategyTargets.includes(target));
  }

  /**
   * Apply optimization strategy
   */
  private async applyOptimization(strategy: OptimizationStrategy): Promise<OptimizationResult> {
    const startTime = Date.now();
    const preOptimizationMetrics = this.metricsCollector.getCurrentMetrics();
    const actionsExecuted: OptimizationAction[] = [];
    const errors: string[] = [];
    let success = true;

    console.log(`Applying optimization: ${strategy.name}`);

    for (const action of strategy.actions) {
      try {
        await this.executeOptimizationAction(action);
        actionsExecuted.push(action);
        console.log(`Executed action: ${action.type} on ${action.target}`);
      } catch (error) {
        console.error(`Failed to execute action ${action.type}:`, error);
        errors.push(`${action.type}: ${error instanceof Error ? error.message : String(error)}`);
        success = false;
      }
    }

    // Wait a moment for metrics to stabilize
    await this.wait(5000);

    const endTime = Date.now();
    const postOptimizationMetrics = this.metricsCollector.getCurrentMetrics();
    const metricsImprovement = this.calculateMetricsImprovement(
      preOptimizationMetrics, 
      postOptimizationMetrics
    );

    const result: OptimizationResult = {
      strategyName: strategy.name,
      actionsExecuted,
      startTime,
      endTime,
      success,
      metricsImprovement,
      errors
    };

    return result;
  }

  /**
   * Execute individual optimization action
   */
  private async executeOptimizationAction(action: OptimizationAction): Promise<void> {
    switch (action.type) {
      case 'throttle':
        await this.executeThrottleAction(action);
        break;
      case 'batch':
        await this.executeBatchAction(action);
        break;
      case 'cache':
        await this.executeCacheAction(action);
        break;
      case 'compress':
        await this.executeCompressAction(action);
        break;
      case 'prioritize':
        await this.executePrioritizeAction(action);
        break;
      case 'scale':
        await this.executeScaleAction(action);
        break;
      case 'cleanup':
        await this.executeCleanupAction(action);
        break;
      default:
        throw new Error(`Unknown optimization action type: ${action.type}`);
    }
  }

  /**
   * Execute throttle optimization
   */
  private async executeThrottleAction(action: OptimizationAction): Promise<void> {
    if (action.target === 'new_connections' && this.wsServer) {
      // Implement connection throttling
      console.log(`Throttling new connections: max ${action.parameters.maxPerSecond} per second`);
      // Would integrate with WebSocket server connection handling
    }
  }

  /**
   * Execute batch optimization
   */
  private async executeBatchAction(action: OptimizationAction): Promise<void> {
    if (action.target === 'websocket_messages') {
      console.log(`Enabling message batching: size ${action.parameters.batchSize}, interval ${action.parameters.batchInterval}ms`);
      // Message batching is handled in optimizeMessageBatching method
    } else if (action.target === 'conflict_operations') {
      console.log(`Batching conflict operations: size ${action.parameters.batchSize}`);
      // Would integrate with conflict resolver
    }
  }

  /**
   * Execute cache optimization
   */
  private async executeCacheAction(action: OptimizationAction): Promise<void> {
    if (action.target === 'graph_operations') {
      console.log(`Enabling response caching: TTL ${action.parameters.ttl}ms, max entries ${action.parameters.maxEntries}`);
      // Response caching is handled in getCachedResponse/setCachedResponse methods
    }
  }

  /**
   * Execute compress optimization
   */
  private async executeCompressAction(action: OptimizationAction): Promise<void> {
    if (action.target === 'large_messages') {
      console.log(`Enabling message compression for messages > ${action.parameters.threshold} bytes`);
      // Would integrate with WebSocket message handling
    }
  }

  /**
   * Execute prioritize optimization
   */
  private async executePrioritizeAction(action: OptimizationAction): Promise<void> {
    if (action.target === 'message_queue') {
      console.log('Enabling message prioritization');
      // Would integrate with message queue processing
    } else if (action.target === 'conflict_queue') {
      console.log('Optimizing conflict queue prioritization');
      // Would integrate with conflict resolution queue
    }
  }

  /**
   * Execute scale optimization
   */
  private async executeScaleAction(action: OptimizationAction): Promise<void> {
    console.log(`Scaling optimization for ${action.target}`);
    // Would trigger auto-scaling mechanisms
  }

  /**
   * Execute cleanup optimization
   */
  private async executeCleanupAction(action: OptimizationAction): Promise<void> {
    if (action.target === 'memory') {
      console.log('Executing memory cleanup');

      // Clear old cache entries
      this.responseCache.clear();

      // Clear old message buffers
      this.messageBuffer.clear();

      // Force garbage collection if enabled
      if (action.parameters.forceGC && global.gc) {
        global.gc();
      }

      // Clean up disconnected connection pools
      for (const [documentId, connections] of this.connectionPools.entries()) {
        const activeConnections = connections.filter(conn => conn.isActive);
        this.connectionPools.set(documentId, activeConnections);
      }
    }
  }

  /**
   * Calculate metrics improvement
   */
  private calculateMetricsImprovement(preMetrics: any, postMetrics: any): any {
    const improvement: any = {};

    if (preMetrics.system && postMetrics.system) {
      improvement.cpuReduction = preMetrics.system.cpuUsage - postMetrics.system.cpuUsage;
      improvement.memoryReduction = preMetrics.system.memoryUsage.percentage - postMetrics.system.memoryUsage.percentage;
    }

    if (preMetrics.webSocket && postMetrics.webSocket) {
      improvement.latencyReduction = preMetrics.webSocket.messageLatency - postMetrics.webSocket.messageLatency;
      improvement.errorRateReduction = preMetrics.webSocket.errorRate - postMetrics.webSocket.errorRate;
    }

    return improvement;
  }

  /**
   * Generate performance recommendations
   */
  private generateRecommendations(metrics: any, alerts: PerformanceAlert[]): string[] {
    const recommendations: string[] = [];

    // CPU recommendations
    if (metrics.system?.cpuUsage > 80) {
      recommendations.push('Enable connection throttling and message batching to reduce CPU load');
    }

    // Memory recommendations
    if (metrics.system?.memoryUsage?.percentage > 85) {
      recommendations.push('Execute memory cleanup and enable response caching with shorter TTL');
    }

    // Latency recommendations
    if (metrics.webSocket?.messageLatency > 1000) {
      recommendations.push('Enable message compression and prioritization for better response times');
    }

    // Error rate recommendations
    if (metrics.webSocket?.errorRate > 5) {
      recommendations.push('Implement connection throttling and improve error handling');
    }

    // Alert-based recommendations
    const criticalAlerts = alerts.filter(a => a.severity === 'critical');
    if (criticalAlerts.length > 0) {
      recommendations.push('Critical performance issues detected. Consider immediate scaling or maintenance');
    }

    // Conflict resolution recommendations
    if (metrics.collaboration?.conflictResolutionTime > 3000) {
      recommendations.push('Optimize conflict resolution by enabling batching and prioritization');
    }

    if (recommendations.length === 0) {
      recommendations.push('System performance is optimal. Continue monitoring.');
    }

    return recommendations;
  }

  /**
   * Create message batch
   */
  private createMessageBatch(messages: any[]): any[] {
    // Group messages by type for efficient batching
    const groupedMessages = new Map<string, any[]>();

    for (const message of messages) {
      const messageType = message.type || 'unknown';
      if (!groupedMessages.has(messageType)) {
        groupedMessages.set(messageType, []);
      }
      groupedMessages.get(messageType)!.push(message);
    }

    // Create batched messages
    const batchedMessages: any[] = [];

    for (const [type, typeMessages] of groupedMessages.entries()) {
      if (typeMessages.length > 1) {
        batchedMessages.push({
          type: `${type}_batch`,
          payload: {
            messages: typeMessages,
            count: typeMessages.length
          },
          timestamp: Date.now()
        });
      } else {
        batchedMessages.push(...typeMessages);
      }
    }

    return batchedMessages;
  }

  /**
   * Setup event listeners
   */
  private setupEventListeners(): void {
    this.metricsCollector.on('alert_created', (alert: PerformanceAlert) => {
      if (alert.severity === 'critical') {
        // Trigger immediate optimization for critical alerts
        this.evaluateOptimizations();
      }
    });
  }

  /**
   * Utility function to wait
   */
  private wait(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }
}

import { EventEmitter } from 'events';
import WebSocket from 'ws';
import { v4 as uuidv4 } from 'uuid';
import { performance } from 'perf_hooks';

/**
 * Performance metrics collected during testing
 */
export interface PerformanceMetrics {
  // WebSocket performance
  connectionTime: number;
  messageLatency: number;
  messageRate: number;
  disconnectionRate: number;

  // Collaboration performance
  conflictResolutionTime: number;
  synchronizationTime: number;
  stateUpdateLatency: number;

  // System performance
  cpuUsage: number;
  memoryUsage: number;
  networkThroughput: number;

  // User experience metrics
  responseTime: number;
  operationSuccessRate: number;
  errorRate: number;

  // Timestamp and context
  timestamp: number;
  testScenario: string;
  userCount: number;
}

/**
 * Test scenario configuration
 */
export interface TestScenario {
  name: string;
  description: string;
  userCount: number;
  duration: number; // in milliseconds
  operationRate: number; // operations per second per user
  operationTypes: OperationType[];
  documentComplexity: DocumentComplexity;
  networkConditions?: NetworkConditions;
}

/**
 * Types of operations to simulate
 */
export enum OperationType {
  CREATE_NODE = 'create_node',
  DELETE_NODE = 'delete_node',
  UPDATE_NODE_PROPERTIES = 'update_node_properties',
  MOVE_NODE = 'move_node',
  CREATE_EDGE = 'create_edge',
  DELETE_EDGE = 'delete_edge',
  UPDATE_CURSOR = 'update_cursor',
  UPDATE_SELECTION = 'update_selection',
  TYPING_ACTIVITY = 'typing_activity',
  TOOL_CHANGE = 'tool_change'
}

/**
 * Document complexity levels
 */
export enum DocumentComplexity {
  SIMPLE = 'simple',     // 10-20 nodes, 10-15 edges
  MEDIUM = 'medium',     // 50-100 nodes, 60-120 edges
  COMPLEX = 'complex',   // 200-500 nodes, 300-800 edges
  ENTERPRISE = 'enterprise' // 1000+ nodes, 1500+ edges
}

/**
 * Network conditions simulation
 */
export interface NetworkConditions {
  latency: number; // in milliseconds
  bandwidth: number; // in kbps
  packetLoss: number; // percentage (0-100)
  jitter: number; // in milliseconds
}

/**
 * Simulated user for performance testing
 */
export class SimulatedUser extends EventEmitter {
  private ws: WebSocket | null = null;
  private connectionId: string | null = null;
  private userId: string;
  private documentId: string;
  private isConnected: boolean = false;
  private operationQueue: Array<() => Promise<void>> = [];
  private metrics: PerformanceMetrics[] = [];
  private scenario: TestScenario;
  private startTime: number = 0;

  constructor(userId: string, documentId: string, scenario: TestScenario) {
    super();
    this.userId = userId;
    this.documentId = documentId;
    this.scenario = scenario;
  }

  /**
   * Connect to WebSocket server
   */
  async connect(serverUrl: string): Promise<void> {
    return new Promise((resolve, reject) => {
      const connectStartTime = performance.now();

      this.ws = new WebSocket(serverUrl);

      this.ws.on('open', () => {
        const connectionTime = performance.now() - connectStartTime;
        this.recordMetric({
          connectionTime,
          messageLatency: 0,
          messageRate: 0,
          disconnectionRate: 0,
          conflictResolutionTime: 0,
          synchronizationTime: 0,
          stateUpdateLatency: 0,
          cpuUsage: 0,
          memoryUsage: 0,
          networkThroughput: 0,
          responseTime: connectionTime,
          operationSuccessRate: 100,
          errorRate: 0,
          timestamp: Date.now(),
          testScenario: this.scenario.name,
          userCount: this.scenario.userCount
        });

        this.isConnected = true;
        this.emit('connected');
        resolve();
      });

      this.ws.on('message', (data) => {
        this.handleMessage(data);
      });

      this.ws.on('error', (error) => {
        this.emit('error', error);
        reject(error);
      });

      this.ws.on('close', () => {
        this.isConnected = false;
        this.emit('disconnected');
      });

      // Timeout for connection
      setTimeout(() => {
        if (!this.isConnected) {
          reject(new Error('Connection timeout'));
        }
      }, 10000);
    });
  }

  /**
   * Start performing operations according to scenario
   */
  startOperations(): void {
    this.startTime = performance.now();
    const interval = 1000 / this.scenario.operationRate; // milliseconds between operations

    const operationTimer = setInterval(() => {
      if (!this.isConnected || (performance.now() - this.startTime) > this.scenario.duration) {
        clearInterval(operationTimer);
        return;
      }

      this.performRandomOperation();
    }, interval);
  }

  /**
   * Perform a random operation based on scenario configuration
   */
  private async performRandomOperation(): Promise<void> {
    const operationType = this.scenario.operationTypes[
      Math.floor(Math.random() * this.scenario.operationTypes.length)
    ];

    const operationStartTime = performance.now();

    try {
      switch (operationType) {
        case OperationType.CREATE_NODE:
          await this.createNode();
          break;
        case OperationType.DELETE_NODE:
          await this.deleteNode();
          break;
        case OperationType.UPDATE_NODE_PROPERTIES:
          await this.updateNodeProperties();
          break;
        case OperationType.MOVE_NODE:
          await this.moveNode();
          break;
        case OperationType.CREATE_EDGE:
          await this.createEdge();
          break;
        case OperationType.DELETE_EDGE:
          await this.deleteEdge();
          break;
        case OperationType.UPDATE_CURSOR:
          await this.updateCursor();
          break;
        case OperationType.UPDATE_SELECTION:
          await this.updateSelection();
          break;
        case OperationType.TYPING_ACTIVITY:
          await this.simulateTyping();
          break;
        case OperationType.TOOL_CHANGE:
          await this.changeTool();
          break;
      }

      const operationTime = performance.now() - operationStartTime;
      this.recordOperationMetric(operationType, operationTime, true);

    } catch (error) {
      const operationTime = performance.now() - operationStartTime;
      this.recordOperationMetric(operationType, operationTime, false);
      this.emit('operation_error', { operationType, error });
    }
  }

  /**
   * Record performance metrics for operations
   */
  private recordOperationMetric(operationType: OperationType, duration: number, success: boolean): void {
    this.recordMetric({
      connectionTime: 0,
      messageLatency: 0,
      messageRate: 0,
      disconnectionRate: 0,
      conflictResolutionTime: 0,
      synchronizationTime: 0,
      stateUpdateLatency: 0,
      cpuUsage: 0,
      memoryUsage: 0,
      networkThroughput: 0,
      responseTime: duration,
      operationSuccessRate: success ? 100 : 0,
      errorRate: success ? 0 : 100,
      timestamp: Date.now(),
      testScenario: `${this.scenario.name}_${operationType}`,
      userCount: this.scenario.userCount
    });
  }

  /**
   * Create a new node
   */
  private async createNode(): Promise<void> {
    const nodeId = uuidv4();
    const nodeData = {
      id: nodeId,
      type: 'output',
      position: {
        x: Math.random() * 800,
        y: Math.random() * 600
      },
      data: {
        text: `Test node ${Date.now()}`
      }
    };

    await this.sendMessage('graph_update', {
      documentId: this.documentId,
      operations: [{
        type: 'node_add',
        nodeId,
        data: nodeData,
        timestamp: Date.now()
      }]
    });
  }

  /**
   * Delete a random node
   */
  private async deleteNode(): Promise<void> {
    const nodeId = `node_${Math.floor(Math.random() * 100)}`;

    await this.sendMessage('graph_update', {
      documentId: this.documentId,
      operations: [{
        type: 'node_remove',
        nodeId,
        timestamp: Date.now()
      }]
    });
  }

  /**
   * Update node properties
   */
  private async updateNodeProperties(): Promise<void> {
    const nodeId = `node_${Math.floor(Math.random() * 100)}`;

    await this.sendMessage('graph_update', {
      documentId: this.documentId,
      operations: [{
        type: 'node_update',
        nodeId,
        data: {
          text: `Updated text ${Date.now()}`
        },
        timestamp: Date.now()
      }]
    });
  }

  /**
   * Move a node to a new position
   */
  private async moveNode(): Promise<void> {
    const nodeId = `node_${Math.floor(Math.random() * 100)}`;

    await this.sendMessage('graph_update', {
      documentId: this.documentId,
      operations: [{
        type: 'node_update',
        nodeId,
        data: {
          position: {
            x: Math.random() * 800,
            y: Math.random() * 600
          }
        },
        timestamp: Date.now()
      }]
    });
  }

  /**
   * Create a new edge
   */
  private async createEdge(): Promise<void> {
    const edgeId = uuidv4();
    const sourceNodeId = `node_${Math.floor(Math.random() * 100)}`;
    const targetNodeId = `node_${Math.floor(Math.random() * 100)}`;

    await this.sendMessage('graph_update', {
      documentId: this.documentId,
      operations: [{
        type: 'edge_add',
        edgeId,
        data: {
          id: edgeId,
          source: sourceNodeId,
          target: targetNodeId
        },
        timestamp: Date.now()
      }]
    });
  }

  /**
   * Delete a random edge
   */
  private async deleteEdge(): Promise<void> {
    const edgeId = `edge_${Math.floor(Math.random() * 100)}`;

    await this.sendMessage('graph_update', {
      documentId: this.documentId,
      operations: [{
        type: 'edge_remove',
        edgeId,
        timestamp: Date.now()
      }]
    });
  }

  /**
   * Update cursor position
   */
  private async updateCursor(): Promise<void> {
    await this.sendMessage('cursor_update', {
      x: Math.random() * 800,
      y: Math.random() * 600,
      nodeId: `node_${Math.floor(Math.random() * 100)}`,
      viewportBounds: {
        x: 0,
        y: 0,
        width: 800,
        height: 600
      }
    });
  }

  /**
   * Update selection
   */
  private async updateSelection(): Promise<void> {
    const nodeIds = Array.from(
      { length: Math.floor(Math.random() * 3) + 1 },
      () => `node_${Math.floor(Math.random() * 100)}`
    );

    await this.sendMessage('selection_update', {
      nodeIds,
      edgeIds: [],
      selectionBox: {
        x: Math.random() * 800,
        y: Math.random() * 600,
        width: Math.random() * 200,
        height: Math.random() * 200
      }
    });
  }

  /**
   * Simulate typing activity
   */
  private async simulateTyping(): Promise<void> {
    await this.sendMessage('activity_update', {
      currentTool: 'text',
      isTyping: true,
      focusedNodeId: `node_${Math.floor(Math.random() * 100)}`
    });

    // Stop typing after a random interval
    setTimeout(async () => {
      await this.sendMessage('activity_update', {
        currentTool: 'text',
        isTyping: false,
        focusedNodeId: null
      });
    }, Math.random() * 2000 + 500);
  }

  /**
   * Change current tool
   */
  private async changeTool(): Promise<void> {
    const tools = ['select', 'text', 'node', 'edge', 'delete'];
    const tool = tools[Math.floor(Math.random() * tools.length)];

    await this.sendMessage('activity_update', {
      currentTool: tool,
      isTyping: false,
      focusedNodeId: null
    });
  }

  /**
   * Send a message to the WebSocket server
   */
  private async sendMessage(type: string, payload: any): Promise<void> {
    if (!this.ws || !this.isConnected) {
      throw new Error('Not connected to server');
    }

    const messageStartTime = performance.now();

    const message = {
      type,
      payload,
      timestamp: Date.now(),
      messageId: uuidv4(),
      documentId: this.documentId
    };

    return new Promise((resolve, reject) => {
      this.ws!.send(JSON.stringify(message));

      // Track message latency (simplified - in real implementation would wait for response)
      setTimeout(() => {
        const messageLatency = performance.now() - messageStartTime;
        this.recordMetric({
          connectionTime: 0,
          messageLatency,
          messageRate: 0,
          disconnectionRate: 0,
          conflictResolutionTime: 0,
          synchronizationTime: 0,
          stateUpdateLatency: 0,
          cpuUsage: 0,
          memoryUsage: 0,
          networkThroughput: 0,
          responseTime: messageLatency,
          operationSuccessRate: 100,
          errorRate: 0,
          timestamp: Date.now(),
          testScenario: this.scenario.name,
          userCount: this.scenario.userCount
        });
        resolve();
      }, 10);
    });
  }

  /**
   * Handle incoming WebSocket messages
   */
  private handleMessage(data: WebSocket.Data): void {
    try {
      const message = JSON.parse(data.toString());

      // Track different types of messages for performance analysis
      switch (message.type) {
        case 'conflict_detected':
          this.handleConflictDetected(message);
          break;
        case 'graph_update':
          this.handleGraphUpdate(message);
          break;
        case 'presence_update':
          this.handlePresenceUpdate(message);
          break;
        case 'sync_response':
          this.handleSyncResponse(message);
          break;
      }

    } catch (error) {
      this.emit('message_error', error);
    }
  }

  /**
   * Handle conflict detection and resolution
   */
  private handleConflictDetected(message: any): void {
    const conflictStartTime = performance.now();

    // Simulate conflict resolution time
    setTimeout(() => {
      const conflictResolutionTime = performance.now() - conflictStartTime;
      this.recordMetric({
        connectionTime: 0,
        messageLatency: 0,
        messageRate: 0,
        disconnectionRate: 0,
        conflictResolutionTime,
        synchronizationTime: 0,
        stateUpdateLatency: 0,
        cpuUsage: 0,
        memoryUsage: 0,
        networkThroughput: 0,
        responseTime: conflictResolutionTime,
        operationSuccessRate: 100,
        errorRate: 0,
        timestamp: Date.now(),
        testScenario: `${this.scenario.name}_conflict_resolution`,
        userCount: this.scenario.userCount
      });
    }, Math.random() * 100 + 50);
  }

  /**
   * Handle graph updates
   */
  private handleGraphUpdate(message: any): void {
    const updateLatency = Date.now() - message.timestamp;

    this.recordMetric({
      connectionTime: 0,
      messageLatency: 0,
      messageRate: 0,
      disconnectionRate: 0,
      conflictResolutionTime: 0,
      synchronizationTime: 0,
      stateUpdateLatency: updateLatency,
      cpuUsage: 0,
      memoryUsage: 0,
      networkThroughput: 0,
      responseTime: updateLatency,
      operationSuccessRate: 100,
      errorRate: 0,
      timestamp: Date.now(),
      testScenario: `${this.scenario.name}_state_update`,
      userCount: this.scenario.userCount
    });
  }

  /**
   * Handle presence updates
   */
  private handlePresenceUpdate(message: any): void {
    // Track presence update frequency and latency
    this.emit('presence_update_received', message);
  }

  /**
   * Handle synchronization responses
   */
  private handleSyncResponse(message: any): void {
    const syncLatency = Date.now() - message.timestamp;

    this.recordMetric({
      connectionTime: 0,
      messageLatency: 0,
      messageRate: 0,
      disconnectionRate: 0,
      conflictResolutionTime: 0,
      synchronizationTime: syncLatency,
      stateUpdateLatency: 0,
      cpuUsage: 0,
      memoryUsage: 0,
      networkThroughput: 0,
      responseTime: syncLatency,
      operationSuccessRate: 100,
      errorRate: 0,
      timestamp: Date.now(),
      testScenario: `${this.scenario.name}_synchronization`,
      userCount: this.scenario.userCount
    });
  }

  /**
   * Record a performance metric
   */
  private recordMetric(metric: PerformanceMetrics): void {
    this.metrics.push(metric);
    this.emit('metric_recorded', metric);
  }

  /**
   * Get collected metrics
   */
  getMetrics(): PerformanceMetrics[] {
    return [...this.metrics];
  }

  /**
   * Disconnect from server
   */
  disconnect(): void {
    if (this.ws) {
      this.ws.close();
    }
  }
}

/**
 * Main performance test suite
 */
export class PerformanceTestSuite extends EventEmitter {
  private users: SimulatedUser[] = [];
  private aggregatedMetrics: PerformanceMetrics[] = [];
  private isRunning: boolean = false;

  /**
   * Run a performance test scenario
   */
  async runScenario(scenario: TestScenario, serverUrl: string): Promise<PerformanceMetrics[]> {
    this.isRunning = true;
    this.users = [];
    this.aggregatedMetrics = [];

    console.log(`Starting performance test: ${scenario.name}`);
    console.log(`Users: ${scenario.userCount}, Duration: ${scenario.duration}ms`);

    // Create simulated users
    const documentId = uuidv4();

    for (let i = 0; i < scenario.userCount; i++) {
      const userId = `user_${i}`;
      const user = new SimulatedUser(userId, documentId, scenario);

      user.on('metric_recorded', (metric) => {
        this.aggregatedMetrics.push(metric);
      });

      user.on('error', (error) => {
        console.error(`User ${userId} error:`, error);
      });

      this.users.push(user);
    }

    // Connect all users
    const connectionPromises = this.users.map(user => user.connect(serverUrl));
    await Promise.all(connectionPromises);

    console.log(`All ${scenario.userCount} users connected`);

    // Start operations
    this.users.forEach(user => user.startOperations());

    // Wait for test duration
    await new Promise(resolve => setTimeout(resolve, scenario.duration));

    // Disconnect all users
    this.users.forEach(user => user.disconnect());

    console.log(`Performance test completed: ${scenario.name}`);
    this.isRunning = false;

    return this.aggregatedMetrics;
  }

  /**
   * Run multiple scenarios in sequence
   */
  async runBenchmark(scenarios: TestScenario[], serverUrl: string): Promise<{ [scenarioName: string]: PerformanceMetrics[] }> {
    const results: { [scenarioName: string]: PerformanceMetrics[] } = {};

    for (const scenario of scenarios) {
      if (!this.isRunning) {
        break;
      }

      const metrics = await this.runScenario(scenario, serverUrl);
      results[scenario.name] = metrics;

      // Wait between scenarios
      await new Promise(resolve => setTimeout(resolve, 5000));
    }

    return results;
  }

  /**
   * Generate performance report
   */
  generateReport(metrics: PerformanceMetrics[]): any {
    if (metrics.length === 0) {
      return null;
    }

    // Calculate aggregated statistics
    const stats = {
      connectionTime: this.calculateStats(metrics.map(m => m.connectionTime).filter(v => v > 0)),
      messageLatency: this.calculateStats(metrics.map(m => m.messageLatency).filter(v => v > 0)),
      conflictResolutionTime: this.calculateStats(metrics.map(m => m.conflictResolutionTime).filter(v => v > 0)),
      synchronizationTime: this.calculateStats(metrics.map(m => m.synchronizationTime).filter(v => v > 0)),
      stateUpdateLatency: this.calculateStats(metrics.map(m => m.stateUpdateLatency).filter(v => v > 0)),
      responseTime: this.calculateStats(metrics.map(m => m.responseTime).filter(v => v > 0)),
      operationSuccessRate: this.calculateStats(metrics.map(m => m.operationSuccessRate)),
      errorRate: this.calculateStats(metrics.map(m => m.errorRate))
    };

    return {
      testDuration: Math.max(...metrics.map(m => m.timestamp)) - Math.min(...metrics.map(m => m.timestamp)),
      totalOperations: metrics.length,
      userCount: metrics[0]?.userCount || 0,
      scenario: metrics[0]?.testScenario || 'unknown',
      statistics: stats,
      rawMetrics: metrics
    };
  }

  /**
   * Calculate statistical measures for a dataset
   */
  private calculateStats(values: number[]): any {
    if (values.length === 0) {
      return { min: 0, max: 0, mean: 0, median: 0, p95: 0, p99: 0 };
    }

    const sorted = values.sort((a, b) => a - b);
    const sum = values.reduce((a, b) => a + b, 0);

    return {
      min: sorted[0],
      max: sorted[sorted.length - 1],
      mean: sum / values.length,
      median: sorted[Math.floor(sorted.length / 2)],
      p95: sorted[Math.floor(sorted.length * 0.95)],
      p99: sorted[Math.floor(sorted.length * 0.99)]
    };
  }

  /**
   * Stop running tests
   */
  stop(): void {
    this.isRunning = false;
    this.users.forEach(user => user.disconnect());
  }
}

