/**
 * Performance Testing and Optimization Suite
 * 
 * This module provides comprehensive performance testing, monitoring, and optimization
 * capabilities for the collaborative editing system.
 */

export { PerformanceTestSuite, SimulatedUser, TEST_SCENARIOS } from './PerformanceTestSuite';
export type { 
  TestScenario, 
  PerformanceMetrics, 
  OperationType, 
  DocumentComplexity, 
  NetworkConditions 
} from './PerformanceTestSuite';

export { MetricsCollector } from './MetricsCollector';
export type { 
  SystemMetrics, 
  WebSocketMetrics, 
  CollaborationMetrics, 
  PerformanceThresholds, 
  PerformanceAlert, 
  MetricsWindow 
} from './MetricsCollector';

export { PerformanceDashboard } from './PerformanceDashboard';
export type { 
  DashboardConfig, 
  DashboardData 
} from './PerformanceDashboard';

export { LoadTestRunner } from './LoadTestRunner';
export type { 
  LoadTestConfig, 
  LoadTestResult 
} from './LoadTestRunner';

export { PerformanceOptimizer } from './PerformanceOptimizer';
export type { 
  OptimizationStrategy, 
  OptimizationAction, 
  OptimizationResult 
} from './PerformanceOptimizer';

/**
 * Complete performance testing and optimization system
 */
export class PerformanceSystem {
  private metricsCollector: MetricsCollector;
  private dashboard: PerformanceDashboard;
  private loadTestRunner: LoadTestRunner;
  private optimizer: PerformanceOptimizer;
  private isRunning: boolean = false;

  constructor() {
    this.metricsCollector = new MetricsCollector();
    this.dashboard = new PerformanceDashboard(this.metricsCollector);
    this.loadTestRunner = new LoadTestRunner();
    this.optimizer = new PerformanceOptimizer(this.metricsCollector);

    this.setupIntegrations();
  }

  /**
   * Start the complete performance system
   */
  start(): void {
    if (this.isRunning) {
      return;
    }

    console.log('Starting performance testing and optimization system');

    this.metricsCollector.startCollection();
    this.dashboard.start();
    this.optimizer.start();

    this.isRunning = true;
    console.log('Performance system started successfully');
  }

  /**
   * Stop the performance system
   */
  stop(): void {
    if (!this.isRunning) {
      return;
    }

    console.log('Stopping performance system');

    this.optimizer.stop();
    this.dashboard.stop();
    this.metricsCollector.stopCollection();
    this.loadTestRunner.stop();

    this.isRunning = false;
    console.log('Performance system stopped');
  }

  /**
   * Get system components
   */
  getComponents() {
    return {
      metricsCollector: this.metricsCollector,
      dashboard: this.dashboard,
      loadTestRunner: this.loadTestRunner,
      optimizer: this.optimizer
    };
  }

  /**
   * Run comprehensive performance assessment
   */
  async runPerformanceAssessment(serverUrl: string): Promise<any> {
    console.log('Starting comprehensive performance assessment');

    // Run predefined test scenarios
    const testConfigs = LoadTestRunner.createCollaborativeEditingTests(serverUrl);
    const results = await this.loadTestRunner.runTestSuite(testConfigs);

    // Generate assessment report
    const report = {
      timestamp: Date.now(),
      summary: {
        totalTests: results.length,
        passedTests: results.filter(r => r.summary.successRate >= 95).length,
        averageLatency: results.reduce((acc, r) => acc + r.summary.averageLatency, 0) / results.length,
        overallThroughput: results.reduce((acc, r) => acc + r.summary.throughput, 0)
      },
      recommendations: this.optimizer.getRecommendations(),
      results
    };

    console.log('Performance assessment completed');
    return report;
  }

  /**
   * Setup integrations between components
   */
  private setupIntegrations(): void {
    // Connect dashboard to load test runner
    this.loadTestRunner.setDashboard(this.dashboard);

    // Connect optimizer to dashboard
    this.dashboard.setWebSocketServer = (wsServer) => {
      this.optimizer.setWebSocketServer(wsServer);
    };
  }
}

#!/usr/bin/env node

/**
 * Performance Testing CLI Tool
 * 
 * Command-line interface for running performance tests and monitoring
 * collaborative editing system performance.
 */

import { Command } from 'commander';
import { PerformanceSystem, LoadTestRunner, TEST_SCENARIOS } from './index';
import { promises as fs } from 'fs';
import { join } from 'path';

const program = new Command();

program
  .name('performance-cli')
  .description('Performance testing and optimization tool for collaborative editing')
  .version('1.0.0');

program
  .command('test')
  .description('Run performance tests')
  .option('-u, --url <url>', 'WebSocket server URL', 'ws://localhost:8000')
  .option('-s, --scenario <scenario>', 'Test scenario name')
  .option('-o, --output <dir>', 'Output directory', './performance-results')
  .option('--stress', 'Run stress test with increasing load')
  .option('--endurance <duration>', 'Run endurance test (duration in minutes)')
  .option('--users <count>', 'Number of simulated users', '5')
  .option('--duration <ms>', 'Test duration in milliseconds', '60000')
  .action(async (options) => {
    try {
      console.log('🚀 Starting performance tests...');
      console.log(`Server URL: ${options.url}`);
      console.log(`Output directory: ${options.output}`);

      const loadTestRunner = new LoadTestRunner();

      if (options.stress) {
        console.log('Running stress test...');
        const baseConfig = LoadTestRunner.createCollaborativeEditingTests(options.url)[0];
        const results = await loadTestRunner.runStressTest(baseConfig, 50, 5);
        console.log(`✅ Stress test completed. Max users: ${findMaxUsers(results)}`);

      } else if (options.endurance) {
        const duration = parseInt(options.endurance) * 60 * 1000; // Convert minutes to ms
        console.log(`Running endurance test for ${options.endurance} minutes...`);
        const baseConfig = LoadTestRunner.createCollaborativeEditingTests(options.url)[0];
        const result = await loadTestRunner.runEnduranceTest(baseConfig, duration);
        console.log(`✅ Endurance test completed. Success rate: ${result.summary.successRate.toFixed(1)}%`);

      } else if (options.scenario) {
        const scenario = TEST_SCENARIOS.find(s => s.name === options.scenario);
        if (!scenario) {
          console.error(`❌ Scenario '${options.scenario}' not found`);
          console.log('Available scenarios:', TEST_SCENARIOS.map(s => s.name).join(', '));
          process.exit(1);
        }

        // Customize scenario with CLI options
        const customScenario = {
          ...scenario,
          userCount: parseInt(options.users),
          duration: parseInt(options.duration)
        };

        console.log(`Running scenario: ${customScenario.name}`);
        const testSuite = new (await import('./PerformanceTestSuite')).PerformanceTestSuite();
        const metrics = await testSuite.runScenario(customScenario, options.url);
        const report = testSuite.generateReport(metrics);

        console.log(`✅ Test completed. Operations: ${metrics.length}, Success rate: ${report?.statistics?.operationSuccessRate?.mean || 0}%`);

      } else {
        console.log('Running standard test suite...');
        const configs = LoadTestRunner.createCollaborativeEditingTests(options.url);
        const results = await loadTestRunner.runTestSuite(configs);

        console.log('✅ Test suite completed:');
        results.forEach(result => {
          console.log(`  ${result.config.name}: ${result.summary.successRate.toFixed(1)}% success, ${result.summary.averageLatency.toFixed(0)}ms avg latency`);
        });
      }

    } catch (error) {
      console.error('❌ Performance test failed:', error);
      process.exit(1);
    }
  });

program
  .command('monitor')
  .description('Start performance monitoring dashboard')
  .option('-p, --port <port>', 'Dashboard port', '3001')
  .option('--metrics-only', 'Only collect metrics without dashboard')
  .action(async (options) => {
    try {
      console.log('📊 Starting performance monitoring...');

      const system = new PerformanceSystem();
      system.start();

      if (!options.metricsOnly) {
        console.log(`🌐 Dashboard available at http://localhost:${options.port}`);
        console.log('📈 Real-time metrics collection started');
        console.log('Press Ctrl+C to stop monitoring');

        // Keep process alive
        process.on('SIGINT', () => {
          console.log('\n🛑 Stopping performance monitoring...');
          system.stop();
          process.exit(0);
        });

        // Prevent process from exiting
        setInterval(() => {}, 1000);
      } else {
        console.log('📈 Metrics collection started (no dashboard)');
        console.log('Press Ctrl+C to stop');

        process.on('SIGINT', () => {
          console.log('\n🛑 Stopping metrics collection...');
          system.stop();
          process.exit(0);
        });

        setInterval(() => {}, 1000);
      }

    } catch (error) {
      console.error('❌ Failed to start monitoring:', error);
      process.exit(1);
    }
  });

program
  .command('optimize')
  .description('Run performance optimization')
  .option('--strategy <strategy>', 'Specific optimization strategy to run')
  .option('--auto', 'Enable automatic optimization')
  .action(async (options) => {
    try {
      console.log('⚡ Starting performance optimization...');

      const { PerformanceOptimizer, MetricsCollector } = await import('./index');
      const metricsCollector = new MetricsCollector();
      const optimizer = new PerformanceOptimizer(metricsCollector);

      metricsCollector.startCollection();

