        error: 'Failed to retrieve export format'
      });
    }
  });

  // POST /api/export/formats/:formatName/validate-options
  fastify.post<{
    Params: { formatName: string };
    Body: any;
  }>('/export/formats/:formatName/validate-options', async (request, reply) => {
