  reason: z.string().optional(),
  duration_minutes: z.number().min(1).max(1440).optional(),
  force: z.boolean().default(false),
  metadata: z.record(z.any()).optional()
});

const LockPolicySchema = z.object({
  workspace_id: z.string().uuid(),
  name: z.string().min(1).max(255),
  description: z.string().optional(),
  max_locks_per_user: z.number().min(1).max(100).default(10),
  max_locks_per_resource: z.number().min(1).max(20).default(5),
  default_duration_minutes: z.number().min(1).max(1440).default(60),
  max_duration_minutes: z.number().min(1).max(10080).default(1440), // 7 days max
  auto_lock_on_edit: z.boolean().default(false),
  auto_lock_on_state_change: z.boolean().default(false),
  auto_lock_duration_minutes: z.number().min(1).max(1440).default(30),
  allow_lock_breaking: z.boolean().default(true),
  lock_breaking_roles: z.array(z.string()).default([]),
  require_justification: z.boolean().default(true),
  conflict_resolution_strategy: z.enum(['queue', 'reject', 'notify', 'escalate']).default('reject'),
  escalation_timeout_minutes: z.number().min(1).max(1440).default(60)
});

const BreakLockSchema = z.object({
  lock_id: z.string().uuid(),
  breaker_user_id: z.string().uuid(),
  justification: z.string().optional(),
  force: z.boolean().default(false)
});

const WorkspaceParamsSchema = z.object({
  workspaceId: z.string().uuid()
});

const ResourceParamsSchema = z.object({
  resourceId: z.string().uuid()
});

const UserParamsSchema = z.object({
  userId: z.string().uuid()
});

const LockParamsSchema = z.object({
  lockId: z.string().uuid()
});

export default async function lockingRoutes(fastify: FastifyInstance) {
  const db = fastify.db as Database;
  const lockingService = new LockingService(db);

  // =============================================================================
  // LOCK ACQUISITION AND RELEASE
  // =============================================================================

  // Acquire a lock
  fastify.post('/locks/acquire', async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const lockRequest = LockRequestSchema.parse(request.body);
      const result = await lockingService.acquireLock(lockRequest);

      if (result.success) {
        reply.code(200).send({
          success: true,
          lock: result.lock,
          message: 'Lock acquired successfully'
        });
      } else {
        reply.code(409).send({
          success: false,
          error: result.error,
          conflict: result.conflict,
          queue_position: result.queue_position
        });
      }
    } catch (error) {
      reply.code(400).send({
        success: false,
        error: error instanceof Error ? error.message : 'Invalid request'
      });
    }
  });

  // Release a lock
  fastify.delete('/locks/:lockId', async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { lockId } = LockParamsSchema.parse(request.params);
      const { user_id } = z.object({ user_id: z.string().uuid() }).parse(request.body);

      const result = await lockingService.releaseLock(lockId, user_id);

      if (result.success) {
        reply.code(200).send({
          success: true,
          message: 'Lock released successfully'
        });
      } else {
        reply.code(400).send({
          success: false,
          error: result.error
        });
      }
    } catch (error) {
      reply.code(400).send({
        success: false,
        error: error instanceof Error ? error.message : 'Invalid request'
      });
    }
  });

  // Break a lock
  fastify.post('/locks/break', async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { lock_id, breaker_user_id, justification, force } = BreakLockSchema.parse(request.body);

      const result = await lockingService.breakLock(lock_id, breaker_user_id, justification, force);

      if (result.success) {
        reply.code(200).send({
          success: true,
          message: 'Lock broken successfully',
          notification_sent: result.notification_sent
        });
      } else {
        reply.code(400).send({
          success: false,
          error: result.error
        });
      }
    } catch (error) {
      reply.code(400).send({
        success: false,
        error: error instanceof Error ? error.message : 'Invalid request'
      });
    }
  });

  // Get locks for a resource
  fastify.get('/resources/:resourceId/locks', async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { resourceId } = ResourceParamsSchema.parse(request.params);
      const locks = await lockingService.getResourceLocks(resourceId);

      reply.code(200).send({
        success: true,
        locks,
        count: locks.length
      });
    } catch (error) {
      reply.code(400).send({
        success: false,
        error: error instanceof Error ? error.message : 'Invalid request'
      });
    }
  });

  // Get locks for a user
  fastify.get('/users/:userId/locks', async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { userId } = UserParamsSchema.parse(request.params);
      const locks = await lockingService.getUserLocks(userId);

      reply.code(200).send({
        success: true,
        locks,
        count: locks.length
      });
    } catch (error) {
      reply.code(400).send({
        success: false,
        error: error instanceof Error ? error.message : 'Invalid request'
      });
    }
  });

  // =============================================================================
  // LOCK POLICIES
  // =============================================================================

  // Create lock policy
  fastify.post('/workspaces/:workspaceId/lock-policy', async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { workspaceId } = WorkspaceParamsSchema.parse(request.params);
      const policyData = LockPolicySchema.parse({ ...request.body, workspace_id: workspaceId });

      const policy = await lockingService.createLockPolicy(policyData);

      reply.code(201).send({
        success: true,
        policy,
        message: 'Lock policy created successfully'
      });
    } catch (error) {
      reply.code(400).send({
        success: false,
        error: error instanceof Error ? error.message : 'Invalid request'
      });
    }
  });

  // Get lock policy
  fastify.get('/workspaces/:workspaceId/lock-policy', async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { workspaceId } = WorkspaceParamsSchema.parse(request.params);
      const policy = await lockingService.getLockPolicy(workspaceId);

      if (policy) {
        reply.code(200).send({
          success: true,
          policy
        });
      } else {
        reply.code(404).send({
          success: false,
          error: 'Lock policy not found'
        });
      }
    } catch (error) {
      reply.code(400).send({
        success: false,
        error: error instanceof Error ? error.message : 'Invalid request'
      });
    }
  });

  // Update lock policy
  fastify.put('/workspaces/:workspaceId/lock-policy', async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { workspaceId } = WorkspaceParamsSchema.parse(request.params);
      const policyData = LockPolicySchema.parse({ ...request.body, workspace_id: workspaceId });

      const policy = await lockingService.updateLockPolicy(workspaceId, policyData);

      reply.code(200).send({
        success: true,
        policy,
        message: 'Lock policy updated successfully'
      });
    } catch (error) {
      reply.code(400).send({
        success: false,
        error: error instanceof Error ? error.message : 'Invalid request'
      });
    }
  });

  // =============================================================================
  // LOCK QUEUE MANAGEMENT
  // =============================================================================

  // Get lock queue for resource
  fastify.get('/resources/:resourceId/lock-queue', async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { resourceId } = ResourceParamsSchema.parse(request.params);
      const queue = await lockingService.getLockQueue(resourceId);

      reply.code(200).send({
        success: true,
        queue,
        count: queue.length
      });
    } catch (error) {
      reply.code(400).send({
        success: false,
        error: error instanceof Error ? error.message : 'Invalid request'
      });
    }
  });

  // Remove from lock queue
  fastify.delete('/lock-queue/:queueId', async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { queueId } = z.object({ queueId: z.string().uuid() }).parse(request.params);
      const { user_id } = z.object({ user_id: z.string().uuid() }).parse(request.body);

      const result = await lockingService.removeFromQueue(queueId, user_id);

      if (result.success) {
        reply.code(200).send({
          success: true,
          message: 'Removed from queue successfully'
        });
      } else {
        reply.code(400).send({
          success: false,
          error: result.error
        });
      }
    } catch (error) {
      reply.code(400).send({
        success: false,
        error: error instanceof Error ? error.message : 'Invalid request'
      });
    }
  });

  // =============================================================================
  // LOCK CONFLICTS
  // =============================================================================

  // Get lock conflicts for workspace
  fastify.get('/workspaces/:workspaceId/lock-conflicts', async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { workspaceId } = WorkspaceParamsSchema.parse(request.params);
      const { status } = z.object({ 
        status: z.enum(['pending', 'resolved', 'rejected']).optional() 
      }).parse(request.query);

      const conflicts = await lockingService.getLockConflicts(workspaceId, status);

      reply.code(200).send({
        success: true,
        conflicts,
        count: conflicts.length
      });
    } catch (error) {
      reply.code(400).send({
        success: false,
        error: error instanceof Error ? error.message : 'Invalid request'
      });
    }
  });

  // Resolve lock conflict
  fastify.post('/lock-conflicts/:conflictId/resolve', async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { conflictId } = z.object({ conflictId: z.string().uuid() }).parse(request.params);
      const { resolution, user_id } = z.object({
        resolution: z.enum(['approve', 'reject', 'escalate']),
        user_id: z.string().uuid()
      }).parse(request.body);

      const result = await lockingService.resolveLockConflict(conflictId, resolution, user_id);

      if (result.success) {
        reply.code(200).send({
          success: true,
          message: 'Conflict resolved successfully'
        });
      } else {
        reply.code(400).send({
          success: false,
          error: result.error
        });
      }
    } catch (error) {
      reply.code(400).send({
        success: false,
        error: error instanceof Error ? error.message : 'Invalid request'
      });
    }
  });

  // =============================================================================
  // NOTIFICATIONS
  // =============================================================================

  // Get lock notifications for user
  fastify.get('/users/:userId/lock-notifications', async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { userId } = UserParamsSchema.parse(request.params);
      const { unread_only } = z.object({ 
        unread_only: z.boolean().default(false) 
      }).parse(request.query);

      const notifications = await lockingService.getLockNotifications(userId, unread_only);

      reply.code(200).send({
        success: true,
        notifications,
        count: notifications.length
      });
    } catch (error) {
      reply.code(400).send({
        success: false,
        error: error instanceof Error ? error.message : 'Invalid request'
      });
    }
  });

  // Mark notification as read
  fastify.post('/lock-notifications/:notificationId/read', async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { notificationId } = z.object({ notificationId: z.string().uuid() }).parse(request.params);

      const result = await lockingService.markNotificationAsRead(notificationId);

      if (result.success) {
        reply.code(200).send({
          success: true,
          message: 'Notification marked as read'
        });
      } else {
        reply.code(400).send({
          success: false,
          error: result.error
        });
      }
    } catch (error) {
      reply.code(400).send({
        success: false,
        error: error instanceof Error ? error.message : 'Invalid request'
      });
    }
  });

  // =============================================================================
  // STATISTICS AND REPORTING
  // =============================================================================

  // Get locking statistics
  fastify.get('/workspaces/:workspaceId/lock-statistics', async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { workspaceId } = WorkspaceParamsSchema.parse(request.params);
      const statistics = await lockingService.getLockingStatistics(workspaceId);

      reply.code(200).send({
        success: true,
        statistics
      });
    } catch (error) {
      reply.code(400).send({
        success: false,
        error: error instanceof Error ? error.message : 'Invalid request'
      });
    }
  });

  // =============================================================================
  // MAINTENANCE
  // =============================================================================

  // Clean up expired locks
  fastify.post('/maintenance/cleanup-expired-locks', async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const expiredCount = await lockingService.releaseExpiredLocks();

      reply.code(200).send({
        success: true,
        expired_count: expiredCount,
        message: `Cleaned up ${expiredCount} expired locks`
      });
    } catch (error) {
      reply.code(500).send({
        success: false,
        error: error instanceof Error ? error.message : 'Cleanup failed'
      });
    }
  });

  // Send expiration warnings
  fastify.post('/maintenance/send-expiration-warnings', async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const warningCount = await lockingService.sendExpirationWarnings();

      reply.code(200).send({
        success: true,
        warning_count: warningCount,
        message: `Sent ${warningCount} expiration warnings`
      });
    } catch (error) {
      reply.code(500).send({
        success: false,
        error: error instanceof Error ? error.message : 'Warning sending failed'
      });
    }
  });

  // Health check
  fastify.get('/health', async (request: FastifyRequest, reply: FastifyReply) => {
    reply.code(200).send({
      success: true,
      service: 'locking-service',
      timestamp: new Date().toISOString(),
      status: 'healthy'
    });
  });
}

// Epic 12 - LLM Agent Randomizer System
// Server routes for randomizer API functionality

import { FastifyInstance, FastifyRequest, FastifyReply } from 'fastify';
import { z } from 'zod';
import { LLMRandomizerSystem } from '../../../packages/core/llm-randomizer';
import { RandomizerParameters } from '../../../packages/core/llm-randomizer/generator/parameters/parameter-schema';

// Request/Response schemas
const RandomizerGenerateRequestSchema = z.object({
  parameters: z.object({
    purpose: z.string().min(1),
    complexity: z.enum(['simple', 'moderate', 'complex']).optional(),
    nodeCount: z.number().int().min(3).max(100).optional(),
    style: z.enum(['creative', 'logical', 'balanced']).optional(),
    provider: z.enum(['openai', 'claude', 'gemini']).optional(),
    temperature: z.number().min(0).max(2).optional(),
    maxRetries: z.number().int().min(1).max(10).optional(),
    domain: z.string().optional(),
    specificRequirements: z.array(z.string()).optional(),
    constraints: z.array(z.string()).optional(),
    qualityLevel: z.enum(['draft', 'standard', 'high']).optional(),
    diversityScore: z.number().min(0).max(1).optional(),
    includeMetadata: z.boolean().optional(),
    validateOutput: z.boolean().optional(),
    includeExplanation: z.boolean().optional()
  })
});

const RandomizerGenerateResponseSchema = z.object({
  success: z.boolean(),
  graph: z.any().optional(),
  metadata: z.object({
    generationTime: z.number(),
    provider: z.string(),
    requestId: z.string(),
    timestamp: z.string()
  }).optional(),
  errors: z.array(z.object({
    type: z.string(),
    message: z.string(),
    details: z.any().optional()
  })).optional(),
  warnings: z.array(z.object({
    type: z.string(),
    message: z.string(),
    suggestion: z.string().optional()
  })).optional()
});

const RandomizerValidateRequestSchema = z.object({
  parameters: z.object({
    purpose: z.string().optional(),
    complexity: z.enum(['simple', 'moderate', 'complex']).optional(),
    nodeCount: z.number().int().min(3).max(100).optional(),
    style: z.enum(['creative', 'logical', 'balanced']).optional(),
    provider: z.enum(['openai', 'claude', 'gemini']).optional(),
    temperature: z.number().min(0).max(2).optional(),
    maxRetries: z.number().int().min(1).max(10).optional(),
    domain: z.string().optional(),
    specificRequirements: z.array(z.string()).optional(),
    constraints: z.array(z.string()).optional(),
    qualityLevel: z.enum(['draft', 'standard', 'high']).optional(),
    diversityScore: z.number().min(0).max(1).optional(),
    includeMetadata: z.boolean().optional(),
    validateOutput: z.boolean().optional(),
    includeExplanation: z.boolean().optional()
  })
});

const RandomizerValidateResponseSchema = z.object({
  isValid: z.boolean(),
  errors: z.array(z.object({
    field: z.string(),
    message: z.string(),
    severity: z.enum(['error', 'warning'])
  })),
  warnings: z.array(z.object({
    field: z.string(),
    message: z.string(),
    suggestion: z.string().optional()
  })),
  suggestions: z.object({
    nodeCount: z.number().optional(),
    temperature: z.number().optional(),
    focusAreas: z.array(z.string()).optional(),
    recommendedProvider: z.string().optional()
  }).optional()
});

// Type definitions
type RandomizerGenerateRequest = z.infer<typeof RandomizerGenerateRequestSchema>;
type RandomizerGenerateResponse = z.infer<typeof RandomizerGenerateResponseSchema>;
type RandomizerValidateRequest = z.infer<typeof RandomizerValidateRequestSchema>;
type RandomizerValidateResponse = z.infer<typeof RandomizerValidateResponseSchema>;

// Global randomizer system instance
const randomizerSystem = new LLMRandomizerSystem();

/**
 * Randomizer routes plugin
 */
export async function randomizerRoutes(fastify: FastifyInstance) {
  /**
   * POST /api/randomizer/generate
   * Generate a graph using LLM randomizer
   */
  fastify.post<{
    Body: RandomizerGenerateRequest;
    Reply: RandomizerGenerateResponse;
  }>('/generate', {
    schema: {
      body: {
        type: 'object',
        required: ['parameters'],
        properties: {
          parameters: {
            type: 'object',
            required: ['purpose'],
            properties: {
              purpose: { type: 'string', minLength: 1 },
              complexity: { type: 'string', enum: ['simple', 'moderate', 'complex'] },
              nodeCount: { type: 'integer', minimum: 3, maximum: 100 },
              style: { type: 'string', enum: ['creative', 'logical', 'balanced'] },
              provider: { type: 'string', enum: ['openai', 'claude', 'gemini'] },
              temperature: { type: 'number', minimum: 0, maximum: 2 },
              maxRetries: { type: 'integer', minimum: 1, maximum: 10 },
              domain: { type: 'string' },
              specificRequirements: { type: 'array', items: { type: 'string' } },
              constraints: { type: 'array', items: { type: 'string' } },
              qualityLevel: { type: 'string', enum: ['draft', 'standard', 'high'] },
              diversityScore: { type: 'number', minimum: 0, maximum: 1 },
              includeMetadata: { type: 'boolean' },
              validateOutput: { type: 'boolean' },
              includeExplanation: { type: 'boolean' }
            }
          }
        }
      },
      response: {
        200: {
          type: 'object',
          properties: {
            success: { type: 'boolean' },
            graph: { type: 'object' },
            metadata: {
              type: 'object',
              properties: {
                generationTime: { type: 'number' },
                provider: { type: 'string' },
                requestId: { type: 'string' },
                timestamp: { type: 'string' }
              }
            },
            errors: {
              type: 'array',
              items: {
                type: 'object',
                properties: {
                  type: { type: 'string' },
                  message: { type: 'string' },
                  details: { type: 'object' }
                }
              }
            },
            warnings: {
              type: 'array',
              items: {
                type: 'object',
                properties: {
                  type: { type: 'string' },
                  message: { type: 'string' },
                  suggestion: { type: 'string' }
                }
              }
            }
          }
        },
        400: {
          type: 'object',
          properties: {
            success: { type: 'boolean' },
            errors: {
              type: 'array',
              items: {
                type: 'object',
                properties: {
                  type: { type: 'string' },
                  message: { type: 'string' }
                }
              }
            }
          }
        },
        500: {
          type: 'object',
          properties: {
            success: { type: 'boolean' },
            errors: {
              type: 'array',
              items: {
                type: 'object',
                properties: {
                  type: { type: 'string' },
                  message: { type: 'string' }
                }
              }
            }
          }
        }
      }
    },
    handler: async (request: FastifyRequest<{ Body: RandomizerGenerateRequest }>, reply: FastifyReply) => {
      try {
        const startTime = Date.now();
        const requestId = `req_${Date.now()}_${Math.random().toString(36).substring(2)}`;

        // Validate request
        const validatedRequest = RandomizerGenerateRequestSchema.parse(request.body);

        // Generate graph using randomizer system
        const result = await randomizerSystem.fullWorkflow(
          validatedRequest.parameters,
          validatedRequest.parameters.provider || 'openai'
        );

        const generationTime = Date.now() - startTime;

        if (result.success) {
          const response: RandomizerGenerateResponse = {
            success: true,
            graph: result.parsedGraph,
            metadata: {
              generationTime,
              provider: validatedRequest.parameters.provider || 'openai',
              requestId,
              timestamp: new Date().toISOString()
            },
            errors: result.errors || [],
            warnings: result.warnings || []
          };

          reply.code(200).send(response);
        } else {
          const response: RandomizerGenerateResponse = {
            success: false,
            errors: result.errors || [{
              type: 'generation_error',
              message: 'Failed to generate graph'
            }],
            warnings: result.warnings || []
          };

          reply.code(400).send(response);
        }
      } catch (error) {
        request.log.error(error);

        if (error instanceof z.ZodError) {
          reply.code(400).send({
            success: false,
            errors: [{
              type: 'validation_error',
              message: `Invalid request: ${error.message}`
            }]
          });
        } else {
          reply.code(500).send({
            success: false,
            errors: [{
              type: 'server_error',
              message: error instanceof Error ? error.message : 'Unknown error'
            }]
          });
        }
      }
    }
  });

  /**
   * POST /api/randomizer/validate
   * Validate randomizer parameters
   */
  fastify.post<{
    Body: RandomizerValidateRequest;
    Reply: RandomizerValidateResponse;
  }>('/validate', {
    schema: {
      body: {
        type: 'object',
        required: ['parameters'],
        properties: {
          parameters: {
            type: 'object',
            properties: {
              purpose: { type: 'string' },
              complexity: { type: 'string', enum: ['simple', 'moderate', 'complex'] },
              nodeCount: { type: 'integer', minimum: 3, maximum: 100 },
              style: { type: 'string', enum: ['creative', 'logical', 'balanced'] },
              provider: { type: 'string', enum: ['openai', 'claude', 'gemini'] },
              temperature: { type: 'number', minimum: 0, maximum: 2 },
              maxRetries: { type: 'integer', minimum: 1, maximum: 10 },
              domain: { type: 'string' },
              specificRequirements: { type: 'array', items: { type: 'string' } },
              constraints: { type: 'array', items: { type: 'string' } },
              qualityLevel: { type: 'string', enum: ['draft', 'standard', 'high'] },
              diversityScore: { type: 'number', minimum: 0, maximum: 1 },
              includeMetadata: { type: 'boolean' },
              validateOutput: { type: 'boolean' },
              includeExplanation: { type: 'boolean' }
            }
          }
        }
      },
      response: {
        200: {
          type: 'object',
          properties: {
            isValid: { type: 'boolean' },
            errors: {
              type: 'array',
              items: {
                type: 'object',
                properties: {
                  field: { type: 'string' },
                  message: { type: 'string' },
                  severity: { type: 'string', enum: ['error', 'warning'] }
                }
              }
            },
            warnings: {
              type: 'array',
              items: {
                type: 'object',
                properties: {
                  field: { type: 'string' },
                  message: { type: 'string' },
                  suggestion: { type: 'string' }
                }
              }
            },
            suggestions: {
              type: 'object',
              properties: {
                nodeCount: { type: 'number' },
                temperature: { type: 'number' },
                focusAreas: { type: 'array', items: { type: 'string' } },
                recommendedProvider: { type: 'string' }
              }
            }
          }
        }
      }
    },
    handler: async (request: FastifyRequest<{ Body: RandomizerValidateRequest }>, reply: FastifyReply) => {
      try {
        const validatedRequest = RandomizerValidateRequestSchema.parse(request.body);

        // Import the parameter manager to validate parameters
        const { ParameterManager } = await import('../../../packages/core/llm-randomizer/generator/parameters/parameter-manager');
        const parameterManager = new ParameterManager();

        // Validate parameters
        const validationResult = parameterManager.validateParameters(validatedRequest.parameters);

        // Get suggestions
        const suggestions = parameterManager.getSuggestions(validatedRequest.parameters);

        const response: RandomizerValidateResponse = {
          isValid: validationResult.isValid,
          errors: validationResult.errors.map(error => ({
            field: error.field,
            message: error.message,
            severity: 'error' as const
          })),
          warnings: validationResult.warnings.map(warning => ({
            field: warning.field,
            message: warning.message,
            suggestion: warning.suggestion
          })),
          suggestions: {
            nodeCount: suggestions.nodeCount,
            temperature: suggestions.temperature,
            focusAreas: suggestions.focusAreas,
            recommendedProvider: suggestions.recommendedProvider
          }
        };

        reply.code(200).send(response);
      } catch (error) {
        request.log.error(error);

        if (error instanceof z.ZodError) {
          reply.code(400).send({
            isValid: false,
            errors: [{
              field: 'request',
              message: `Invalid request: ${error.message}`,
              severity: 'error' as const
            }],
            warnings: []
          });
        } else {
          reply.code(500).send({
            isValid: false,
            errors: [{
              field: 'server',
              message: error instanceof Error ? error.message : 'Unknown error',
              severity: 'error' as const
            }],
            warnings: []
          });
        }
      }
    }
  });

  /**
   * GET /api/randomizer/presets
   * Get available parameter presets
   */
  fastify.get('/presets', {
    schema: {
      response: {
        200: {
          type: 'object',
          properties: {
            presets: {
              type: 'array',
              items: {
                type: 'object',
                properties: {
                  id: { type: 'string' },
                  name: { type: 'string' },
                  description: { type: 'string' },
                  category: { type: 'string' },
                  tags: { type: 'array', items: { type: 'string' } },
                  parameters: { type: 'object' }
                }
              }
            },
            categories: {
              type: 'object',
              additionalProperties: {
                type: 'array',
                items: { type: 'object' }
              }
            }
          }
        }
      }
    },
    handler: async (request: FastifyRequest, reply: FastifyReply) => {
      try {
        const { ParameterManager } = await import('../../../packages/core/llm-randomizer/generator/parameters/parameter-manager');
        const parameterManager = new ParameterManager();

        const presets = parameterManager.getPresets();
        const categories = parameterManager.getPresetsByCategory();

        reply.code(200).send({
          presets,
          categories
        });
      } catch (error) {
        request.log.error(error);
        reply.code(500).send({
          presets: [],
          categories: {}
        });
      }
    }
  });

  /**
   * GET /api/randomizer/health
   * Health check for randomizer system
   */
  fastify.get('/health', {
    schema: {
      response: {
        200: {
          type: 'object',
          properties: {
            status: { type: 'string' },
            timestamp: { type: 'string' },
            services: {
              type: 'object',
              properties: {
                randomizer: { type: 'string' },
                llm_agents: { type: 'string' },
                parser: { type: 'string' },
                serializer: { type: 'string' }
              }
            }
          }
        }
      }
    },
    handler: async (request: FastifyRequest, reply: FastifyReply) => {
      try {
        // Test basic functionality
        const testResult = await randomizerSystem.fullWorkflow({
          purpose: 'test health check',
          complexity: 'simple',
          nodeCount: 3,
          provider: 'openai'
        });

        reply.code(200).send({
