import { FastifyInstance } from 'fastify';
import { z } from 'zod';
import { RestorationService } from '../services/restoration-service';
import { 
  CreateRestorationAttemptRequestSchema,
  RestorationPreviewRequestSchema,
  ConflictResolutionRequestSchema,
  RestorationBookmarkRequestSchema,
  RestorationFilterSchema,
} from '../../packages/core/types/restoration';

export async function restorationRoutes(fastify: FastifyInstance) {
  const restorationService = new RestorationService(fastify.db, fastify.log);

  // Create restoration attempt
  fastify.post('/restoration/attempts', {
    schema: {
      body: CreateRestorationAttemptRequestSchema,
      response: {
        201: {
          type: 'object',
          properties: {
            success: { type: 'boolean' },
            data: { type: 'object' },
          },
        },
      },
    },
  }, async (request, reply) => {
    try {
      const userId = request.user?.id;
      if (!userId) {
        return reply.status(401).send({ success: false, error: 'Unauthorized' });
      }

      const attempt = await restorationService.createRestoration(request.body, userId);

      reply.status(201).send({
        success: true,
        data: attempt,
      });
    } catch (error) {
      fastify.log.error(error);
      reply.status(500).send({
        success: false,
        error: 'Failed to create restoration attempt',
      });
    }
  });

  // Generate restoration preview
  fastify.post('/restoration/preview', {
    schema: {
      body: RestorationPreviewRequestSchema,
      response: {
        200: {
          type: 'object',
          properties: {
            success: { type: 'boolean' },
            data: { type: 'object' },
          },
        },
      },
    },
  }, async (request, reply) => {
    try {
      const userId = request.user?.id;
      if (!userId) {
        return reply.status(401).send({ success: false, error: 'Unauthorized' });
      }

      const preview = await restorationService.generatePreview(request.body, userId);

      reply.send({
        success: true,
        data: preview,
      });
    } catch (error) {
      fastify.log.error(error);
      reply.status(500).send({
        success: false,
        error: 'Failed to generate restoration preview',
      });
    }
  });

  // Get restoration progress
  fastify.get('/restoration/attempts/:id/progress', {
    schema: {
      params: {
        type: 'object',
        properties: {
          id: { type: 'string', format: 'uuid' },
        },
        required: ['id'],
      },
    },
  }, async (request, reply) => {
    try {
      const { id } = request.params as { id: string };
      const progress = await restorationService.getRestorationProgress(id);

      reply.send({
        success: true,
        data: progress,
      });
    } catch (error) {
      fastify.log.error(error);
      reply.status(500).send({
        success: false,
        error: 'Failed to get restoration progress',
      });
    }
  });

  // Resolve conflict
  fastify.post('/restoration/conflicts/resolve', {
    schema: {
      body: ConflictResolutionRequestSchema,
      response: {
        200: {
          type: 'object',
          properties: {
            success: { type: 'boolean' },
            data: { type: 'object' },
          },
        },
      },
    },
  }, async (request, reply) => {
    try {
      const userId = request.user?.id;
      if (!userId) {
        return reply.status(401).send({ success: false, error: 'Unauthorized' });
      }

      const result = await restorationService.resolveConflict(request.body, userId);

      reply.send({
        success: true,
        data: result,
      });
    } catch (error) {
      fastify.log.error(error);
      reply.status(500).send({
        success: false,
        error: 'Failed to resolve conflict',
      });
    }
  });

  // Cancel restoration
  fastify.post('/restoration/attempts/:id/cancel', {
    schema: {
      params: {
        type: 'object',
        properties: {
          id: { type: 'string', format: 'uuid' },
        },
        required: ['id'],
      },
    },
  }, async (request, reply) => {
    try {
      const userId = request.user?.id;
      if (!userId) {
        return reply.status(401).send({ success: false, error: 'Unauthorized' });
      }

      const { id } = request.params as { id: string };
      await restorationService.cancelRestoration(id, userId);

      reply.send({
        success: true,
        message: 'Restoration cancelled successfully',
      });
    } catch (error) {
      fastify.log.error(error);
      reply.status(500).send({
        success: false,
        error: 'Failed to cancel restoration',
      });
    }
  });

  // Get restoration statistics
  fastify.get('/restoration/stats/:projectId', {
    schema: {
      params: {
        type: 'object',
        properties: {
          projectId: { type: 'string', format: 'uuid' },
        },
        required: ['projectId'],
      },
    },
  }, async (request, reply) => {
    try {
      const { projectId } = request.params as { projectId: string };
      const stats = await restorationService.getRestorationStats(projectId);

      reply.send({
        success: true,
        data: stats,
      });
    } catch (error) {
      fastify.log.error(error);
      reply.status(500).send({
        success: false,
        error: 'Failed to get restoration statistics',
      });
    }
  });

  // Create bookmark
  fastify.post('/restoration/bookmarks', {
    schema: {
      body: RestorationBookmarkRequestSchema,
      response: {
        201: {
          type: 'object',
          properties: {
            success: { type: 'boolean' },
            data: { type: 'object' },
          },
        },
      },
    },
  }, async (request, reply) => {
    try {
      const userId = request.user?.id;
      if (!userId) {
        return reply.status(401).send({ success: false, error: 'Unauthorized' });
      }

      const bookmark = await restorationService.createBookmark(request.body, userId);

      reply.status(201).send({
        success: true,
        data: bookmark,
      });
    } catch (error) {
      fastify.log.error(error);
      reply.status(500).send({
        success: false,
        error: 'Failed to create restoration bookmark',
      });
    }
  });

  // Get bookmarks
  fastify.get('/restoration/bookmarks/:projectId', {
    schema: {
      params: {
        type: 'object',
        properties: {
          projectId: { type: 'string', format: 'uuid' },
        },
        required: ['projectId'],
      },
    },
  }, async (request, reply) => {
    try {
      const userId = request.user?.id;
      if (!userId) {
        return reply.status(401).send({ success: false, error: 'Unauthorized' });
      }

      const { projectId } = request.params as { projectId: string };
      const bookmarks = await restorationService.getBookmarks(projectId, userId);

      reply.send({
        success: true,
        data: bookmarks,
      });
    } catch (error) {
      fastify.log.error(error);
      reply.status(500).send({
        success: false,
        error: 'Failed to get restoration bookmarks',
      });
    }
  });

  // Delete bookmark
  fastify.delete('/restoration/bookmarks/:id', {
    schema: {
      params: {
        type: 'object',
        properties: {
          id: { type: 'string', format: 'uuid' },
        },
        required: ['id'],
      },
    },
  }, async (request, reply) => {
    try {
      const userId = request.user?.id;
      if (!userId) {
        return reply.status(401).send({ success: false, error: 'Unauthorized' });
      }

      const { id } = request.params as { id: string };

      await fastify.db.query(`
        DELETE FROM restoration_bookmarks 
        WHERE id = $1 AND created_by = $2
      `, [id, userId]);

      reply.send({
        success: true,
        message: 'Bookmark deleted successfully',
      });
    } catch (error) {
      fastify.log.error(error);
      reply.status(500).send({
        success: false,
        error: 'Failed to delete restoration bookmark',
      });
    }
  });

  // List restoration attempts
  fastify.get('/restoration/attempts', {
    schema: {
      querystring: {
        type: 'object',
        properties: {
          projectId: { type: 'string', format: 'uuid' },
          initiatedBy: { type: 'string', format: 'uuid' },
          status: { type: 'string' },
          restorationType: { type: 'string' },
          dateFrom: { type: 'string', format: 'date-time' },
          dateTo: { type: 'string', format: 'date-time' },
          limit: { type: 'integer', minimum: 1, maximum: 100, default: 20 },
          offset: { type: 'integer', minimum: 0, default: 0 },
        },
      },
    },
  }, async (request, reply) => {
    try {
      const filter = RestorationFilterSchema.parse(request.query);
      const attempts = await restorationService.listRestorations(filter);

      reply.send({
        success: true,
        data: attempts,
      });
    } catch (error) {
      fastify.log.error(error);
      reply.status(500).send({
        success: false,
        error: 'Failed to list restoration attempts',
      });
    }
  });

  // Get restoration attempt details
  fastify.get('/restoration/attempts/:id', {
    schema: {
      params: {
        type: 'object',
        properties: {
          id: { type: 'string', format: 'uuid' },
        },
        required: ['id'],
      },
    },
  }, async (request, reply) => {
    try {
      const { id } = request.params as { id: string };

      const attempt = await fastify.db.query(`
        SELECT * FROM restoration_attempts WHERE id = $1
      `, [id]);

      if (attempt.rows.length === 0) {
        return reply.status(404).send({
          success: false,
          error: 'Restoration attempt not found',
        });
      }

      const conflicts = await fastify.db.query(`
        SELECT * FROM restoration_conflicts 
        WHERE restoration_attempt_id = $1
        ORDER BY created_at DESC
      `, [id]);

      const operations = await fastify.db.query(`
        SELECT * FROM restoration_operations 
        WHERE restoration_attempt_id = $1
        ORDER BY execution_order
      `, [id]);

      reply.send({
        success: true,
        data: {
          attempt: attempt.rows[0],
          conflicts: conflicts.rows,
          operations: operations.rows,
        },
      });
    } catch (error) {
      fastify.log.error(error);
      reply.status(500).send({
        success: false,
        error: 'Failed to get restoration attempt details',
      });
    }
  });

  // Get conflicts for restoration attempt
  fastify.get('/restoration/attempts/:id/conflicts', {
    schema: {
      params: {
        type: 'object',
        properties: {
          id: { type: 'string', format: 'uuid' },
        },
        required: ['id'],
      },
    },
  }, async (request, reply) => {
    try {
      const { id } = request.params as { id: string };

      const conflicts = await fastify.db.query(`
        SELECT * FROM restoration_conflicts 
        WHERE restoration_attempt_id = $1
        ORDER BY created_at DESC
      `, [id]);

      reply.send({
        success: true,
        data: conflicts.rows,
      });
    } catch (error) {
      fastify.log.error(error);
      reply.status(500).send({
        success: false,
        error: 'Failed to get restoration conflicts',
      });
    }
  });

  // Get operations for restoration attempt
  fastify.get('/restoration/attempts/:id/operations', {
    schema: {
      params: {
        type: 'object',
        properties: {
          id: { type: 'string', format: 'uuid' },
        },
        required: ['id'],
      },
    },
  }, async (request, reply) => {
    try {
      const { id } = request.params as { id: string };

      const operations = await fastify.db.query(`
        SELECT * FROM restoration_operations 
        WHERE restoration_attempt_id = $1
        ORDER BY execution_order
      `, [id]);

      reply.send({
        success: true,
        data: operations.rows,
      });
    } catch (error) {
      fastify.log.error(error);
      reply.status(500).send({
        success: false,
        error: 'Failed to get restoration operations',
      });
    }
  });

  // Clean up expired preview sessions
  fastify.post('/restoration/preview/cleanup', {
    schema: {
      response: {
        200: {
          type: 'object',
          properties: {
            success: { type: 'boolean' },
            message: { type: 'string' },
          },
        },
      },
    },
  }, async (request, reply) => {
    try {
      const result = await fastify.db.query(`
        DELETE FROM restoration_preview_sessions 
        WHERE expires_at < CURRENT_TIMESTAMP
      `);

      reply.send({
        success: true,
        message: `Cleaned up ${result.rowCount} expired preview sessions`,
      });
    } catch (error) {
      fastify.log.error(error);
      reply.status(500).send({
        success: false,
        error: 'Failed to clean up expired preview sessions',
      });
    }
  });
}

/**
 * Epic 9.2.6 - Template API Routes
 * REST API endpoints for project template functionality
 */

import { FastifyInstance, FastifyRequest, FastifyReply } from 'fastify';
import { z } from 'zod';
import { TemplateService } from '../services/template-service';
import { TemplateDAO } from '../database/template-dao';
import { WorkspaceDAO } from '../database/workspace-dao';
import {
  CreateProjectTemplateSchema,
  UpdateProjectTemplateSchema,
  CreateTemplateReviewSchema,
  UpdateTemplateReviewSchema,
  CreateTemplateUsageSchema,
  UpdateTemplateUsageSchema,
} from '../database/template-models';

// Request schemas
const GetTemplatesQuerySchema = z.object({
  page: z.coerce.number().min(1).optional().default(1),
  limit: z.coerce.number().min(1).max(100).optional().default(20),
  sort_by: z.enum(['name', 'created_at', 'updated_at', 'rating_average', 'usage_count', 'relevance']).optional().default('created_at'),
  sort_order: z.enum(['asc', 'desc']).optional().default('desc'),
  search: z.string().optional(),
  category: z.string().optional(),
  tags: z.string().optional(), // Comma-separated string
  difficulty_level: z.string().optional(), // Comma-separated string
  visibility: z.string().optional(), // Comma-separated string
  min_rating: z.coerce.number().min(1).max(5).optional(),
  is_featured: z.coerce.boolean().optional(),
  created_by: z.string().optional(),
  workspace_id: z.string().uuid().optional(),
});

const UseTemplateSchema = z.object({
  customizations: z.record(z.unknown()).default({}),
  project_name: z.string().min(1),
  project_description: z.string().optional(),
  workspace_id: z.string().uuid(),
});

const CompleteUsageSchema = z.object({
  completion_status: z.enum(['completed', 'abandoned']),
  time_to_complete_minutes: z.number().int().positive().optional(),
  user_rating: z.number().int().min(1).max(5).optional(),
  user_feedback: z.string().optional(),
});

const ExportTemplateQuerySchema = z.object({
  format: z.enum(['json', 'yaml', 'zip']).optional().default('json'),
  include_analytics: z.coerce.boolean().optional().default(false),
});

const UUIDParamSchema = z.object({
  id: z.string().uuid(),
});

// Mock user authentication - in real implementation, this would extract from JWT
function getCurrentUser(request: FastifyRequest): string {
  return request.headers['x-user-id'] as string || 'dev-user-123';
}

export async function templateRoutes(fastify: FastifyInstance) {
  // Initialize services
  const templateDAO = new TemplateDAO(fastify.db);
  const workspaceDAO = new WorkspaceDAO(fastify.db);
  const templateService = new TemplateService(templateDAO, workspaceDAO, {
    getUserInfo: async (userId: string) => {
      return { name: `User ${userId}`, avatar: undefined };
    },
    checkWorkspaceAccess: async (workspaceId: string, userId: string, permission: number) => {
      // Simplified permission check - in real app, this would check ACL
      return true;
    },
    generateThumbnail: async (templateData: Record<string, any>) => {
      // Mock thumbnail generation - in real app, this would generate actual thumbnails
      return `https://api.placeholder.com/300x200?text=${encodeURIComponent('Template')}`;
    },
    sendNotification: async (userId: string, notification: any) => {
      fastify.log.info('Notification sent:', notification);
    },
  });

  // ====== TEMPLATE ENDPOINTS ======

  // GET /api/templates - List templates with filtering and sorting
  fastify.get<{
    Querystring: z.infer<typeof GetTemplatesQuerySchema>;
  }>('/templates', {
    schema: {
      querystring: GetTemplatesQuerySchema,
      response: {
        200: z.object({
          data: z.array(z.any()),
          pagination: z.any(),
        }),
      },
    },
  }, async (request, reply) => {
    try {
      const userId = getCurrentUser(request);
      const {
        search, category, tags, difficulty_level, visibility, min_rating,
        is_featured, created_by, workspace_id, ...pagination
      } = request.query;

      // Parse comma-separated arrays
      const filter: any = {
        search,
        category,
        min_rating,
        is_featured,
        created_by,
        workspace_id,
      };

      if (tags) {
        filter.tags = tags.split(',').map(tag => tag.trim());
      }
      if (difficulty_level) {
        filter.difficulty_level = difficulty_level.split(',').map(level => level.trim());
      }
      if (visibility) {
        filter.visibility = visibility.split(',').map(vis => vis.trim());
      }

      const sort = {
        sort_by: request.query.sort_by,
        sort_order: request.query.sort_order,
      };

      const result = await templateService.getTemplates(filter, sort, pagination, userId);
      return result;
    } catch (error) {
      reply.code(500).send({ error: 'Failed to fetch templates', message: error.message });
    }
  });

  // POST /api/templates - Create new template
  fastify.post<{
    Body: z.infer<typeof CreateProjectTemplateSchema>;
  }>('/templates', {
    schema: {
      body: CreateProjectTemplateSchema,
      response: {
        201: z.any(),
      },
    },
  }, async (request, reply) => {
    try {
      const userId = getCurrentUser(request);
      const template = await templateService.createTemplate(request.body, userId);

      reply.code(201).send(template);
    } catch (error) {
      const statusCode = error.message.includes('Access denied') ? 403 : 400;
      reply.code(statusCode).send({ error: 'Failed to create template', message: error.message });
    }
  });

  // GET /api/templates/:id - Get template by ID with stats
  fastify.get<{
    Params: z.infer<typeof UUIDParamSchema>;
  }>('/templates/:id', {
    schema: {
      params: UUIDParamSchema,
      response: {
        200: z.any(),
        404: z.object({ error: z.string() }),
      },
    },
  }, async (request, reply) => {
    try {
      const userId = getCurrentUser(request);
      const template = await templateService.getTemplate(request.params.id, userId);

      if (!template) {
        return reply.code(404).send({ error: 'Template not found' });
      }

      return template;
    } catch (error) {
      if (error.message.includes('Access denied')) {
        reply.code(403).send({ error: 'Access denied', message: error.message });
      } else {
        reply.code(500).send({ error: 'Failed to fetch template', message: error.message });
      }
    }
  });

  // PUT /api/templates/:id - Update template
  fastify.put<{
    Params: z.infer<typeof UUIDParamSchema>;
    Body: z.infer<typeof UpdateProjectTemplateSchema>;
  }>('/templates/:id', {
    schema: {
      params: UUIDParamSchema,
      body: UpdateProjectTemplateSchema,
      response: {
        200: z.any(),
        404: z.object({ error: z.string() }),
      },
    },
  }, async (request, reply) => {
    try {
      const userId = getCurrentUser(request);
      const template = await templateService.updateTemplate(
        request.params.id,
        request.body,
        userId
      );

      if (!template) {
        return reply.code(404).send({ error: 'Template not found' });
      }

      return template;
    } catch (error) {
      if (error.message.includes('Insufficient permissions')) {
        reply.code(403).send({ error: 'Access denied', message: error.message });
      } else {
        reply.code(500).send({ error: 'Failed to update template', message: error.message });
      }
    }
  });

  // DELETE /api/templates/:id - Archive template
  fastify.delete<{
    Params: z.infer<typeof UUIDParamSchema>;
  }>('/templates/:id', {
    schema: {
      params: UUIDParamSchema,
      response: {
        204: z.null(),
        404: z.object({ error: z.string() }),
      },
    },
  }, async (request, reply) => {
    try {
      const userId = getCurrentUser(request);
      const success = await templateService.archiveTemplate(request.params.id, userId);

      if (!success) {
        return reply.code(404).send({ error: 'Template not found' });
      }

      reply.code(204).send();
    } catch (error) {
      if (error.message.includes('Insufficient permissions')) {
        reply.code(403).send({ error: 'Access denied', message: error.message });
      } else {
        reply.code(500).send({ error: 'Failed to archive template', message: error.message });
      }
    }
  });

  // POST /api/templates/:id/publish - Publish template
  fastify.post<{
    Params: z.infer<typeof UUIDParamSchema>;
  }>('/templates/:id/publish', {
    schema: {
      params: UUIDParamSchema,
      response: {
        200: z.object({ message: z.string() }),
      },
    },
  }, async (request, reply) => {
    try {
      const userId = getCurrentUser(request);
      const success = await templateService.publishTemplate(request.params.id, userId);

      if (!success) {
        return reply.code(404).send({ error: 'Template not found' });
      }

      return { message: 'Template published successfully' };
    } catch (error) {
      if (error.message.includes('Only the template creator')) {
        reply.code(403).send({ error: 'Access denied', message: error.message });
      } else if (error.message.includes('validation failed')) {
        reply.code(400).send({ error: 'Validation failed', message: error.message });
      } else {
        reply.code(500).send({ error: 'Failed to publish template', message: error.message });
      }
    }
  });

  // POST /api/templates/:id/use - Use template to create project
  fastify.post<{
    Params: z.infer<typeof UUIDParamSchema>;
    Body: z.infer<typeof UseTemplateSchema>;
  }>('/templates/:id/use', {
    schema: {
      params: UUIDParamSchema,
      body: UseTemplateSchema,
      response: {
        201: z.object({
          project: z.any(),
          usage: z.any(),
        }),
      },
    },
  }, async (request, reply) => {
    try {
      const userId = getCurrentUser(request);
      const { customizations, project_name, project_description, workspace_id } = request.body;

      const result = await templateService.useTemplate(
        request.params.id,
        customizations,
        {
          name: project_name,
          description: project_description,
          workspace_id,
        },
        userId
      );

      reply.code(201).send(result);
    } catch (error) {
      if (error.message.includes('Access denied')) {
        reply.code(403).send({ error: 'Access denied', message: error.message });
      } else if (error.message.includes('validation failed')) {
        reply.code(400).send({ error: 'Validation failed', message: error.message });
      } else {
        reply.code(500).send({ error: 'Failed to use template', message: error.message });
      }
    }
  });

  // GET /api/templates/:id/export - Export template
  fastify.get<{
    Params: z.infer<typeof UUIDParamSchema>;
    Querystring: z.infer<typeof ExportTemplateQuerySchema>;
  }>('/templates/:id/export', {
    schema: {
      params: UUIDParamSchema,
      querystring: ExportTemplateQuerySchema,
      response: {
        200: z.any(),
      },
    },
  }, async (request, reply) => {
    try {
      const userId = getCurrentUser(request);
      const { format, include_analytics } = request.query;

      const exportData = await templateService.exportTemplate(
        request.params.id,
        userId,
        format,
        include_analytics
      );

      // Set appropriate content type and filename
      const filename = `${exportData.template.name.replace(/[^a-zA-Z0-9]/g, '_')}_v${exportData.template.version}.${format}`;

      reply.header('Content-Disposition', `attachment; filename="${filename}"`);

      if (format === 'json') {
        reply.type('application/json');
        return exportData;
      } else if (format === 'yaml') {
        reply.type('application/x-yaml');
        // In real implementation, convert to YAML format
        return exportData;
      } else if (format === 'zip') {
        reply.type('application/zip');
        // In real implementation, create ZIP archive
        return exportData;
      }

      return exportData;
    } catch (error) {
      if (error.message.includes('Access denied')) {
        reply.code(403).send({ error: 'Access denied', message: error.message });
      } else {
        reply.code(500).send({ error: 'Failed to export template', message: error.message });
      }
    }
  });

  // ====== TEMPLATE REVIEWS ENDPOINTS ======

  // GET /api/templates/:id/reviews - Get template reviews
  fastify.get<{
    Params: z.infer<typeof UUIDParamSchema>;
    Querystring: {
      page?: number;
      limit?: number;
      min_rating?: number;
      max_rating?: number;
      has_text?: boolean;
    };
  }>('/templates/:id/reviews', {
    schema: {
      params: UUIDParamSchema,
      querystring: z.object({
        page: z.coerce.number().min(1).optional().default(1),
        limit: z.coerce.number().min(1).max(100).optional().default(20),
        min_rating: z.coerce.number().min(1).max(5).optional(),
        max_rating: z.coerce.number().min(1).max(5).optional(),
        has_text: z.coerce.boolean().optional(),
      }),
      response: {
        200: z.object({
          data: z.array(z.any()),
          pagination: z.any(),
        }),
      },
    },
  }, async (request, reply) => {
    try {
      const { min_rating, max_rating, has_text, ...pagination } = request.query;
      const filter = { min_rating, max_rating, has_text };

      const result = await templateService.getTemplateReviews(
        request.params.id,
        filter,
        pagination
      );

      return result;
    } catch (error) {
      reply.code(500).send({ error: 'Failed to fetch reviews', message: error.message });
    }
  });

  // POST /api/templates/:id/reviews - Create template review
  fastify.post<{
    Params: z.infer<typeof UUIDParamSchema>;
    Body: Omit<z.infer<typeof CreateTemplateReviewSchema>, 'template_id'>;
  }>('/templates/:id/reviews', {
    schema: {
      params: UUIDParamSchema,
      body: CreateTemplateReviewSchema.omit({ template_id: true }),
      response: {
        201: z.any(),
      },
    },
  }, async (request, reply) => {
    try {
      const userId = getCurrentUser(request);
      const reviewData = {
        ...request.body,
        template_id: request.params.id,
      };

      const review = await templateService.createTemplateReview(reviewData, userId);

      reply.code(201).send(review);
    } catch (error) {
      if (error.message.includes('Access denied')) {
        reply.code(403).send({ error: 'Access denied', message: error.message });
      } else {
        reply.code(400).send({ error: 'Failed to create review', message: error.message });
      }
    }
  });

  // ====== TEMPLATE FAVORITES ENDPOINTS ======

  // POST /api/templates/:id/favorite - Add template to favorites
  fastify.post<{
    Params: z.infer<typeof UUIDParamSchema>;
  }>('/templates/:id/favorite', {
    schema: {
      params: UUIDParamSchema,
      response: {
        201: z.any(),
      },
    },
  }, async (request, reply) => {
    try {
      const userId = getCurrentUser(request);
      const favorite = await templateService.addTemplateFavorite(request.params.id, userId);

      reply.code(201).send(favorite);
    } catch (error) {
      if (error.message.includes('Access denied')) {
        reply.code(403).send({ error: 'Access denied', message: error.message });
      } else {
        reply.code(400).send({ error: 'Failed to add favorite', message: error.message });
      }
    }
  });

  // DELETE /api/templates/:id/favorite - Remove template from favorites
  fastify.delete<{
    Params: z.infer<typeof UUIDParamSchema>;
  }>('/templates/:id/favorite', {
    schema: {
      params: UUIDParamSchema,
      response: {
        204: z.null(),
      },
    },
  }, async (request, reply) => {
    try {
      const userId = getCurrentUser(request);
      const success = await templateService.removeTemplateFavorite(request.params.id, userId);

      if (!success) {
        return reply.code(404).send({ error: 'Favorite not found' });
      }

      reply.code(204).send();
    } catch (error) {
      reply.code(500).send({ error: 'Failed to remove favorite', message: error.message });
    }
  });

  // GET /api/user/templates/favorites - Get user's favorite templates
  fastify.get<{
    Querystring: {
      page?: number;
      limit?: number;
    };
  }>('/user/templates/favorites', {
    schema: {
      querystring: z.object({
        page: z.coerce.number().min(1).optional().default(1),
        limit: z.coerce.number().min(1).max(100).optional().default(20),
      }),
      response: {
        200: z.object({
          data: z.array(z.any()),
          pagination: z.any(),
        }),
      },
    },
  }, async (request, reply) => {
    try {
      const userId = getCurrentUser(request);
      const result = await templateService.getUserFavoriteTemplates(userId, request.query);

      return result;
    } catch (error) {
      reply.code(500).send({ error: 'Failed to fetch favorite templates', message: error.message });
    }
  });

  // ====== TEMPLATE ANALYTICS ENDPOINTS ======

  // GET /api/templates/:id/analytics - Get template analytics
  fastify.get<{
    Params: z.infer<typeof UUIDParamSchema>;
    Querystring: {
      days?: number;
    };
  }>('/templates/:id/analytics', {
    schema: {
      params: UUIDParamSchema,
      querystring: z.object({
        days: z.coerce.number().min(1).max(365).optional().default(30),
      }),
      response: {
        200: z.any(),
      },
    },
  }, async (request, reply) => {
    try {
      const userId = getCurrentUser(request);
      const analytics = await templateService.getTemplateAnalytics(
        request.params.id,
        userId,
        request.query.days
      );

      return analytics;
    } catch (error) {
      if (error.message.includes('Access denied')) {
        reply.code(403).send({ error: 'Access denied', message: error.message });
      } else {
        reply.code(500).send({ error: 'Failed to fetch analytics', message: error.message });
      }
    }
  });

  // ====== TEMPLATE CATEGORIES ENDPOINTS ======

  // GET /api/template-categories - Get all template categories
  fastify.get('/template-categories', {
    schema: {
      response: {
        200: z.array(z.any()),
      },
    },
  }, async (request, reply) => {
    try {
      const categories = await templateService.getTemplateCategories();
      return categories;
    } catch (error) {
      reply.code(500).send({ error: 'Failed to fetch categories', message: error.message });
    }
  });

  // ====== TEMPLATE USAGE ENDPOINTS ======

  // PUT /api/template-usages/:id/complete - Complete template usage
  fastify.put<{
    Params: z.infer<typeof UUIDParamSchema>;
    Body: z.infer<typeof CompleteUsageSchema>;
  }>('/template-usages/:id/complete', {
    schema: {
      params: UUIDParamSchema,
      body: CompleteUsageSchema,
      response: {
        200: z.any(),
      },
    },
  }, async (request, reply) => {
    try {
      const userId = getCurrentUser(request);
      const usage = await templateService.completeTemplateUsage(
        request.params.id,
        request.body,
        userId
      );

      if (!usage) {
        return reply.code(404).send({ error: 'Template usage not found' });
      }

      return usage;
    } catch (error) {
      reply.code(500).send({ error: 'Failed to complete template usage', message: error.message });
    }
  });
}

// Visual Diff API Routes
// Story 9.3.2 - Visual Diff Tool

import { FastifyPluginAsync } from 'fastify';
import { z } from 'zod';
import { VisualDiffService } from '../services/visual-diff-service.js';
import { ComparisonDAO } from '../database/comparison-dao.js';
import { VersionHistoryDAO } from '../database/version-dao.js';
import {
  CompareVersionsRequestSchema,
  CreateDiffSessionRequestSchema,
  UpdateDiffSessionRequestSchema,
  ComparisonSchemas
} from '../database/comparison-models.js';

// Query schemas
const GetComparisonQuerySchema = z.object({
  include_details: z.string().transform(val => val === 'true').default('true')
});

const GetComparisonHistoryQuerySchema = z.object({
  page: z.string().transform(val => parseInt(val)).default('1'),
  limit: z.string().transform(val => parseInt(val)).default('50')
});

const GetStatisticsQuerySchema = z.object({
  graph_id: z.string().uuid().optional()
});

// Parameter schemas
const ComparisonParamsSchema = z.object({
  comparisonId: z.string().uuid()
});

const SessionParamsSchema = z.object({
  sessionId: z.string().uuid()
});

const GraphParamsSchema = z.object({
  graphId: z.string().uuid()
});

const visualDiffRoutes: FastifyPluginAsync = async (fastify) => {
  // Initialize services
  const comparisonDAO = new ComparisonDAO(fastify.db);
  const versionDAO = new VersionHistoryDAO(fastify.db);
  const visualDiffService = new VisualDiffService(comparisonDAO, versionDAO);

  // Middleware for authentication
  const requireAuth = async (request: any, reply: any) => {
    if (!request.user?.id) {
      return reply.code(401).send({ error: 'Authentication required' });
    }
  };

  // Compare two graph versions
  fastify.post<{
    Body: z.infer<typeof CompareVersionsRequestSchema>;
  }>('/compare', {
    preHandler: requireAuth,
    schema: {
      body: CompareVersionsRequestSchema,
      response: {
        200: z.object({
          success: z.boolean(),
          data: z.record(z.unknown()),
          metadata: z.object({
            comparison_id: z.string().uuid(),
            duration_ms: z.number(),
            similarity_score: z.number(),
            changes_count: z.number()
          })
        })
      }
    }
  }, async (request, reply) => {
    try {
      const comparison = await visualDiffService.compareVersions(
        request.body,
        request.user.id
      );

      return {
        success: true,
        data: comparison,
        metadata: {
          comparison_id: comparison.id,
          duration_ms: comparison.comparison_duration_ms || 0,
          similarity_score: comparison.similarity_score,
          changes_count: comparison.changes_summary.total_changes
        }
      };
    } catch (error) {
      fastify.log.error('Comparison failed:', error);
      return reply.code(500).send({
        success: false,
        error: 'Comparison failed',
        message: error instanceof Error ? error.message : 'Unknown error'
      });
    }
  });

  // Get existing comparison
  fastify.get<{
    Params: z.infer<typeof ComparisonParamsSchema>;
    Querystring: z.infer<typeof GetComparisonQuerySchema>;
  }>('/comparisons/:comparisonId', {
    preHandler: requireAuth,
    schema: {
      params: ComparisonParamsSchema,
      querystring: GetComparisonQuerySchema
    }
  }, async (request, reply) => {
    try {
      const comparison = await comparisonDAO.getComparison(request.params.comparisonId);
      if (!comparison) {
        return reply.code(404).send({ error: 'Comparison not found' });
      }

      return {
        success: true,
        data: comparison
      };
    } catch (error) {
      fastify.log.error('Failed to get comparison:', error);
      return reply.code(500).send({
        success: false,
        error: 'Failed to get comparison'
      });
    }
  });

  // Create diff session
  fastify.post<{
    Body: z.infer<typeof CreateDiffSessionRequestSchema>;
  }>('/sessions', {
    preHandler: requireAuth,
    schema: {
      body: CreateDiffSessionRequestSchema,
      response: {
        201: z.object({
          success: z.boolean(),
          data: z.record(z.unknown()),
          session_id: z.string().uuid()
        })
      }
    }
  }, async (request, reply) => {
    try {
      const session = await visualDiffService.createDiffSession(
        request.body,
        request.user.id
      );

      return reply.code(201).send({
        success: true,
        data: session,
        session_id: session.id
      });
    } catch (error) {
      fastify.log.error('Failed to create diff session:', error);
      return reply.code(500).send({
        success: false,
        error: 'Failed to create diff session',
        message: error instanceof Error ? error.message : 'Unknown error'
      });
    }
  });

  // Get diff session
  fastify.get<{
    Params: z.infer<typeof SessionParamsSchema>;
  }>('/sessions/:sessionId', {
    preHandler: requireAuth,
    schema: {
      params: SessionParamsSchema
    }
  }, async (request, reply) => {
    try {
      const result = await visualDiffService.getDiffSession(
        request.params.sessionId,
        request.user.id
      );

      if (!result) {
        return reply.code(404).send({ error: 'Session not found or access denied' });
      }

      return {
        success: true,
        data: {
          session: result.session,
          comparison: result.comparison
        }
      };
    } catch (error) {
      fastify.log.error('Failed to get diff session:', error);
      return reply.code(500).send({
        success: false,
        error: 'Failed to get diff session'
      });
    }
  });

  // Update diff session
  fastify.patch<{
    Params: z.infer<typeof SessionParamsSchema>;
    Body: z.infer<typeof UpdateDiffSessionRequestSchema>;
  }>('/sessions/:sessionId', {
    preHandler: requireAuth,
    schema: {
      params: SessionParamsSchema,
      body: UpdateDiffSessionRequestSchema
    }
  }, async (request, reply) => {
    try {
      const session = await visualDiffService.updateDiffSession(
        request.params.sessionId,
        request.body,
        request.user.id
      );

      if (!session) {
        return reply.code(404).send({ error: 'Session not found or access denied' });
      }

      return {
        success: true,
        data: session
      };
    } catch (error) {
      fastify.log.error('Failed to update diff session:', error);
      return reply.code(500).send({
        success: false,
        error: 'Failed to update diff session'
      });
    }
  });

  // Delete diff session
  fastify.delete<{
    Params: z.infer<typeof SessionParamsSchema>;
  }>('/sessions/:sessionId', {
    preHandler: requireAuth,
    schema: {
      params: SessionParamsSchema
    }
  }, async (request, reply) => {
    try {
      const success = await visualDiffService.deleteDiffSession(
        request.params.sessionId,
        request.user.id
      );

      if (!success) {
        return reply.code(404).send({ error: 'Session not found or access denied' });
      }

      return {
        success: true,
        message: 'Session deleted successfully'
      };
    } catch (error) {
      fastify.log.error('Failed to delete diff session:', error);
      return reply.code(500).send({
        success: false,
        error: 'Failed to delete diff session'
      });
    }
  });

  // Get user's diff sessions
  fastify.get('/sessions', {
    preHandler: requireAuth
  }, async (request, reply) => {
    try {
      const sessions = await visualDiffService.getUserDiffSessions(request.user.id);

      return {
        success: true,
        data: sessions,
        count: sessions.length
      };
    } catch (error) {
      fastify.log.error('Failed to get user sessions:', error);
      return reply.code(500).send({
        success: false,
        error: 'Failed to get user sessions'
      });
    }
  });

  // Get comparison history for a graph
  fastify.get<{
    Params: z.infer<typeof GraphParamsSchema>;
    Querystring: z.infer<typeof GetComparisonHistoryQuerySchema>;
  }>('/graphs/:graphId/comparisons', {
    preHandler: requireAuth,
    schema: {
      params: GraphParamsSchema,
      querystring: GetComparisonHistoryQuerySchema
    }
  }, async (request, reply) => {
    try {
      const history = await visualDiffService.getComparisonHistory(
        request.params.graphId,
        request.query.page,
        request.query.limit
      );

      return {
        success: true,
        data: history.comparisons,
        pagination: {
          page: history.page,
          total: history.total,
          total_pages: history.total_pages,
          limit: request.query.limit
        }
      };
    } catch (error) {
      fastify.log.error('Failed to get comparison history:', error);
      return reply.code(500).send({
        success: false,
        error: 'Failed to get comparison history'
      });
    }
  });

  // Get comparison statistics
  fastify.get<{
    Querystring: z.infer<typeof GetStatisticsQuerySchema>;
  }>('/statistics', {
    preHandler: requireAuth,
    schema: {
      querystring: GetStatisticsQuerySchema
    }
  }, async (request, reply) => {
    try {
      const stats = await visualDiffService.getComparisonStatistics(request.query.graph_id);

      return {
        success: true,
        data: stats
      };
    } catch (error) {
      fastify.log.error('Failed to get statistics:', error);
      return reply.code(500).send({
        success: false,
        error: 'Failed to get statistics'
      });
    }
  });

  // Quick compare endpoint for UI
  fastify.post<{
    Body: {
      graph_id: string;
      source_version_id: string;
      target_version_id: string;
      comparison_type?: 'structural' | 'semantic' | 'visual';
    };
  }>('/quick-compare', {
    preHandler: requireAuth,
    schema: {
      body: z.object({
        graph_id: z.string().uuid(),
        source_version_id: z.string().uuid(),
        target_version_id: z.string().uuid(),
        comparison_type: z.enum(['structural', 'semantic', 'visual']).optional().default('structural')
      })
    }
  }, async (request, reply) => {
    try {
      // Quick comparison without creating a session
      const comparison = await visualDiffService.compareVersions({
        source_version_id: request.body.source_version_id,
        target_version_id: request.body.target_version_id,
        comparison_type: request.body.comparison_type,
        include_details: false
      }, request.user.id);

      return {
        success: true,
        data: {
          similarity_score: comparison.similarity_score,
          changes_summary: comparison.changes_summary,
          comparison_id: comparison.id,
          duration_ms: comparison.comparison_duration_ms
        }
      };
    } catch (error) {
      fastify.log.error('Quick comparison failed:', error);
      return reply.code(500).send({
        success: false,
        error: 'Quick comparison failed',
        message: error instanceof Error ? error.message : 'Unknown error'
      });
    }
  });

  // Batch compare endpoint for comparing multiple version pairs
  fastify.post<{
    Body: {
      comparisons: Array<{
        source_version_id: string;
        target_version_id: string;
        comparison_type?: 'structural' | 'semantic' | 'visual';
      }>;
    };
  }>('/batch-compare', {
    preHandler: requireAuth,
    schema: {
      body: z.object({
        comparisons: z.array(z.object({
          source_version_id: z.string().uuid(),
          target_version_id: z.string().uuid(),
          comparison_type: z.enum(['structural', 'semantic', 'visual']).optional().default('structural')
        })).max(10) // Limit batch size
      })
    }
  }, async (request, reply) => {
    try {
      const results = await Promise.allSettled(
        request.body.comparisons.map(comp =>
          visualDiffService.compareVersions({
            source_version_id: comp.source_version_id,
            target_version_id: comp.target_version_id,
            comparison_type: comp.comparison_type,
            include_details: false
          }, request.user.id)
        )
      );

      const successful = results
        .filter((result): result is PromiseFulfilledResult<any> => result.status === 'fulfilled')
        .map(result => ({
          similarity_score: result.value.similarity_score,
          changes_summary: result.value.changes_summary,
          comparison_id: result.value.id,
          source_version_id: result.value.source_version_id,
          target_version_id: result.value.target_version_id
        }));

      const failed = results
        .filter((result): result is PromiseRejectedResult => result.status === 'rejected')
        .map(result => ({
          error: result.reason.message || 'Unknown error'
        }));

      return {
        success: true,
        data: {
          successful,
          failed,
          total_requested: request.body.comparisons.length,
          successful_count: successful.length,
          failed_count: failed.length
        }
      };
    } catch (error) {
      fastify.log.error('Batch comparison failed:', error);
      return reply.code(500).send({
        success: false,
        error: 'Batch comparison failed'
      });
    }
  });

  // Admin endpoint for cleanup
  fastify.post('/admin/cleanup', {
    preHandler: [requireAuth, async (request: any, reply: any) => {
      // Add admin check here
      if (!request.user?.role || request.user.role !== 'admin') {
        return reply.code(403).send({ error: 'Admin access required' });
      }
    }]
  }, async (request, reply) => {
    try {
      const result = await visualDiffService.cleanup();

      return {
        success: true,
        data: result,
        message: `Cleaned up ${result.expired_sessions_removed} sessions and ${result.old_comparisons_removed} comparisons`
      };
    } catch (error) {
      fastify.log.error('Cleanup failed:', error);
      return reply.code(500).send({
        success: false,
        error: 'Cleanup failed'
      });
    }
  });

  // Health check for visual diff service
  fastify.get('/health', async (request, reply) => {
    try {
      const stats = await visualDiffService.getComparisonStatistics();

      return {
        success: true,
        status: 'healthy',
        data: {
          total_comparisons: stats.total_comparisons,
          service_uptime: process.uptime(),
          memory_usage: process.memoryUsage(),
          timestamp: new Date().toISOString()
        }
      };
    } catch (error) {
      fastify.log.error('Health check failed:', error);
      return reply.code(503).send({
        success: false,
        status: 'unhealthy',
        error: 'Service unavailable'
      });
    }
  });
};

export default visualDiffRoutes;

// Epic 9.4 - Workflow Orchestration API Routes
// REST API endpoints for workflow state management

import { FastifyInstance, FastifyRequest, FastifyReply } from 'fastify';
import { z } from 'zod';
import { WorkflowService } from '../services/workflow-service';
import { database } from '../database/connection';
import {
  CreateWorkflowStateSchema,
  CreateWorkflowTransitionSchema,
  CreateWorkflowApprovalSchema,
  CreateWorkflowLockSchema,
  CreateWorkflowScheduleSchema,
  ApproveWorkflowSchema,
  RejectWorkflowSchema
} from '../database/workflow-models';

export async function workflowRoutes(fastify: FastifyInstance) {
  const workflowService = new WorkflowService(database);

  // =============================================================================
  // WORKFLOW STATE ENDPOINTS
  // =============================================================================

  // GET /api/workflow/states/:workspaceId - Get workflow states for workspace
  fastify.get<{
    Params: { workspaceId: string };
    Querystring: { 
      is_initial?: boolean;
      is_final?: boolean;
      is_locked?: boolean;
      name_contains?: string;
    };
  }>('/states/:workspaceId', {
    schema: {
      params: z.object({
        workspaceId: z.string().uuid()
      }),
      querystring: z.object({
        is_initial: z.boolean().optional(),
        is_final: z.boolean().optional(),
        is_locked: z.boolean().optional(),
        name_contains: z.string().optional()
      }).optional()
    }
  }, async (request, reply) => {
    try {
      const { workspaceId } = request.params;
      const filters = request.query || {};

      const states = await workflowService.getWorkflowStates(workspaceId);
      const filteredStates = states.filter(state => {
        if (filters.is_initial !== undefined && state.is_initial !== filters.is_initial) return false;
        if (filters.is_final !== undefined && state.is_final !== filters.is_final) return false;
        if (filters.is_locked !== undefined && state.is_locked !== filters.is_locked) return false;
        if (filters.name_contains && !state.name.toLowerCase().includes(filters.name_contains.toLowerCase())) return false;
        return true;
      });

      reply.send(filteredStates);
    } catch (error) {
      reply.status(500).send({ error: 'Failed to fetch workflow states' });
    }
  });

  // POST /api/workflow/states - Create new workflow state
  fastify.post<{
    Body: Zod.infer<typeof CreateWorkflowStateSchema>;
  }>('/states', {
    schema: {
      body: CreateWorkflowStateSchema
    }
  }, async (request, reply) => {
    try {
      const state = await workflowService.createWorkflowState(request.body);
      reply.status(201).send(state);
    } catch (error) {
      reply.status(500).send({ error: 'Failed to create workflow state' });
    }
  });

  // PUT /api/workflow/states/:id - Update workflow state
  fastify.put<{
    Params: { id: string };
    Body: Partial<Zod.infer<typeof CreateWorkflowStateSchema>>;
  }>('/states/:id', {
    schema: {
      params: z.object({
        id: z.string().uuid()
      }),
      body: CreateWorkflowStateSchema.partial()
    }
  }, async (request, reply) => {
    try {
      const { id } = request.params;
      const state = await workflowService.updateWorkflowState(id, request.body);

      if (!state) {
        return reply.status(404).send({ error: 'Workflow state not found' });
      }

      reply.send(state);
    } catch (error) {
      reply.status(500).send({ error: 'Failed to update workflow state' });
    }
  });

  // DELETE /api/workflow/states/:id - Delete workflow state
  fastify.delete<{
    Params: { id: string };
  }>('/states/:id', {
    schema: {
      params: z.object({
        id: z.string().uuid()
      })
    }
  }, async (request, reply) => {
    try {
      const { id } = request.params;
      const deleted = await workflowService.deleteWorkflowState(id);

      if (!deleted) {
        return reply.status(404).send({ error: 'Workflow state not found' });
      }

      reply.status(204).send();
    } catch (error) {
      reply.status(500).send({ error: 'Failed to delete workflow state' });
    }
  });

  // =============================================================================
  // WORKFLOW TRANSITION ENDPOINTS
  // =============================================================================

  // GET /api/workflow/transitions/:workspaceId - Get workflow transitions
  fastify.get<{
    Params: { workspaceId: string };
    Querystring: { from_state_id?: string };
  }>('/transitions/:workspaceId', {
    schema: {
      params: z.object({
        workspaceId: z.string().uuid()
      }),
      querystring: z.object({
        from_state_id: z.string().uuid().optional()
      }).optional()
    }
  }, async (request, reply) => {
    try {
      const { workspaceId } = request.params;
      const { from_state_id } = request.query || {};

      const transitions = await workflowService.getWorkflowTransitions(workspaceId, from_state_id);
      reply.send(transitions);
    } catch (error) {
      reply.status(500).send({ error: 'Failed to fetch workflow transitions' });
    }
  });

  // POST /api/workflow/transitions - Create workflow transition
  fastify.post<{
    Body: Zod.infer<typeof CreateWorkflowTransitionSchema>;
  }>('/transitions', {
    schema: {
      body: CreateWorkflowTransitionSchema
    }
  }, async (request, reply) => {
    try {
      const transition = await workflowService.createWorkflowTransition(request.body);
      reply.status(201).send(transition);
    } catch (error) {
      reply.status(500).send({ error: 'Failed to create workflow transition' });
    }
  });

  // DELETE /api/workflow/transitions/:id - Delete workflow transition
  fastify.delete<{
    Params: { id: string };
  }>('/transitions/:id', {
    schema: {
      params: z.object({
        id: z.string().uuid()
      })
    }
  }, async (request, reply) => {
    try {
      const { id } = request.params;
      const deleted = await workflowService.deleteWorkflowTransition(id);

      if (!deleted) {
        return reply.status(404).send({ error: 'Workflow transition not found' });
      }

      reply.status(204).send();
    } catch (error) {
      reply.status(500).send({ error: 'Failed to delete workflow transition' });
    }
  });

  // =============================================================================
  // STATE TRANSITION ENDPOINTS
  // =============================================================================

  // POST /api/workflow/resources/:resourceId/transition - Transition resource state
  fastify.post<{
    Params: { resourceId: string };
    Body: {
      to_state_id: string;
      comment?: string;
      metadata?: Record<string, any>;
      force?: boolean;
      lock_duration?: number;
    };
    Headers: { 'x-user-id': string };
  }>('/resources/:resourceId/transition', {
    schema: {
      params: z.object({
        resourceId: z.string().uuid()
      }),
      body: z.object({
        to_state_id: z.string().uuid(),
        comment: z.string().optional(),
        metadata: z.record(z.any()).optional(),
        force: z.boolean().optional(),
        lock_duration: z.number().optional()
      }),
      headers: z.object({
        'x-user-id': z.string()
      })
    }
  }, async (request, reply) => {
    try {
      const { resourceId } = request.params;
      const { to_state_id, comment, metadata, force, lock_duration } = request.body;
      const userId = request.headers['x-user-id'];

      const result = await workflowService.transitionResourceState(
        resourceId,
        to_state_id,
        userId,
        { comment, metadata, force, lockDuration: lock_duration }
      );

      reply.send(result);
    } catch (error) {
      reply.status(500).send({ error: 'Failed to transition resource state' });
    }
  });

  // =============================================================================
  // APPROVAL ENDPOINTS
  // =============================================================================

  // GET /api/workflow/approvals/:workspaceId - Get workflow approvals
  fastify.get<{
    Params: { workspaceId: string };
    Querystring: {
      resource_id?: string;
      requester_id?: string;
      status?: 'pending' | 'approved' | 'rejected' | 'cancelled';
      priority?: 'low' | 'medium' | 'high' | 'urgent';
      overdue?: boolean;
    };
  }>('/approvals/:workspaceId', {
    schema: {
      params: z.object({
        workspaceId: z.string().uuid()
      }),
      querystring: z.object({
        resource_id: z.string().uuid().optional(),
        requester_id: z.string().optional(),
        status: z.enum(['pending', 'approved', 'rejected', 'cancelled']).optional(),
        priority: z.enum(['low', 'medium', 'high', 'urgent']).optional(),
        overdue: z.boolean().optional()
      }).optional()
    }
  }, async (request, reply) => {
    try {
      const { workspaceId } = request.params;
      const filters = request.query || {};

      const approvals = await workflowService.getWorkflowApprovals(workspaceId, filters);
      reply.send(approvals);
    } catch (error) {
      reply.status(500).send({ error: 'Failed to fetch workflow approvals' });
    }
  });

  // POST /api/workflow/approvals - Create workflow approval
  fastify.post<{
    Body: Zod.infer<typeof CreateWorkflowApprovalSchema>;
  }>('/approvals', {
    schema: {
      body: CreateWorkflowApprovalSchema
    }
  }, async (request, reply) => {
    try {
      const approval = await workflowService.createWorkflowApproval(request.body);
      reply.status(201).send(approval);
    } catch (error) {
      reply.status(500).send({ error: 'Failed to create workflow approval' });
    }
  });

  // POST /api/workflow/approvals/:id/approve - Approve workflow
  fastify.post<{
    Params: { id: string };
    Body: { comment?: string };
    Headers: { 'x-user-id': string };
  }>('/approvals/:id/approve', {
    schema: {
      params: z.object({
        id: z.string().uuid()
      }),
      body: z.object({
        comment: z.string().optional()
      }),
      headers: z.object({
        'x-user-id': z.string()
      })
    }
  }, async (request, reply) => {
    try {
      const { id } = request.params;
      const { comment } = request.body;
      const userId = request.headers['x-user-id'];

      const result = await workflowService.approveWorkflow(id, userId, comment);
      reply.send(result);
    } catch (error) {
      reply.status(500).send({ error: 'Failed to approve workflow' });
    }
  });

  // POST /api/workflow/approvals/:id/reject - Reject workflow
  fastify.post<{
    Params: { id: string };
    Body: { reason: string };
    Headers: { 'x-user-id': string };
  }>('/approvals/:id/reject', {
    schema: {
      params: z.object({
        id: z.string().uuid()
      }),
      body: z.object({
        reason: z.string().min(1)
      }),
      headers: z.object({
        'x-user-id': z.string()
      })
    }
  }, async (request, reply) => {
    try {
      const { id } = request.params;
      const { reason } = request.body;
      const userId = request.headers['x-user-id'];

      const result = await workflowService.rejectWorkflow(id, userId, reason);

      if (!result) {
        return reply.status(404).send({ error: 'Workflow approval not found' });
      }

      reply.send({ success: true });
    } catch (error) {
      reply.status(500).send({ error: 'Failed to reject workflow' });
    }
  });

  // =============================================================================
  // LOCK ENDPOINTS
  // =============================================================================

  // GET /api/workflow/locks/:workspaceId - Get workflow locks
  fastify.get<{
    Params: { workspaceId: string };
    Querystring: {
      resource_id?: string;
      locked_by?: string;
      lock_type?: 'edit' | 'state_change' | 'delete' | 'custom';
      expired?: boolean;
    };
  }>('/locks/:workspaceId', {
    schema: {
      params: z.object({
        workspaceId: z.string().uuid()
      }),
      querystring: z.object({
        resource_id: z.string().uuid().optional(),
        locked_by: z.string().optional(),
        lock_type: z.enum(['edit', 'state_change', 'delete', 'custom']).optional(),
        expired: z.boolean().optional()
      }).optional()
    }
  }, async (request, reply) => {
    try {
      const { workspaceId } = request.params;
      const filters = request.query || {};

      const locks = await workflowService.getWorkflowLocks(workspaceId, filters);
      reply.send(locks);
    } catch (error) {
      reply.status(500).send({ error: 'Failed to fetch workflow locks' });
    }
  });

  // POST /api/workflow/locks - Acquire workflow lock
  fastify.post<{
    Body: {
      resource_id: string;
      lock_type?: 'edit' | 'state_change' | 'delete' | 'custom';
      reason?: string;
      duration?: number;
      metadata?: Record<string, any>;
    };
    Headers: { 'x-user-id': string };
  }>('/locks', {
    schema: {
      body: z.object({
        resource_id: z.string().uuid(),
        lock_type: z.enum(['edit', 'state_change', 'delete', 'custom']).optional(),
        reason: z.string().optional(),
        duration: z.number().optional(),
        metadata: z.record(z.any()).optional()
      }),
      headers: z.object({
        'x-user-id': z.string()
      })
    }
  }, async (request, reply) => {
    try {
      const { resource_id, lock_type, reason, duration, metadata } = request.body;
      const userId = request.headers['x-user-id'];

      const lock = await workflowService.acquireLock(resource_id, userId, lock_type, {
        reason,
        duration,
        metadata
      });

      reply.status(201).send(lock);
    } catch (error) {
      reply.status(500).send({ error: 'Failed to acquire workflow lock' });
    }
  });

  // DELETE /api/workflow/locks/:id - Release workflow lock
  fastify.delete<{
    Params: { id: string };
    Headers: { 'x-user-id': string };
  }>('/locks/:id', {
    schema: {
      params: z.object({
        id: z.string().uuid()
      }),
      headers: z.object({
        'x-user-id': z.string()
      })
    }
  }, async (request, reply) => {
    try {
      const { id } = request.params;
      const userId = request.headers['x-user-id'];

      const released = await workflowService.releaseLock(id, userId);

      if (!released) {
        return reply.status(404).send({ error: 'Workflow lock not found' });
      }

      reply.status(204).send();
    } catch (error) {
      reply.status(500).send({ error: 'Failed to release workflow lock' });
    }
  });

  // DELETE /api/workflow/locks/resource/:resourceId - Release all locks for resource
  fastify.delete<{
    Params: { resourceId: string };
    Querystring: { lock_type?: string };
    Headers: { 'x-user-id': string };
  }>('/locks/resource/:resourceId', {
    schema: {
      params: z.object({
        resourceId: z.string().uuid()
      }),
      querystring: z.object({
        lock_type: z.string().optional()
      }).optional(),
      headers: z.object({
        'x-user-id': z.string()
      })
    }
  }, async (request, reply) => {
    try {
      const { resourceId } = request.params;
      const { lock_type } = request.query || {};
      const userId = request.headers['x-user-id'];

      const releasedCount = await workflowService.releaseLocksByResource(resourceId, userId, lock_type);

      reply.send({ released_count: releasedCount });
    } catch (error) {
      reply.status(500).send({ error: 'Failed to release workflow locks' });
    }
  });

  // =============================================================================
  // HISTORY ENDPOINTS
  // =============================================================================

  // GET /api/workflow/history/:workspaceId - Get workflow history
  fastify.get<{
    Params: { workspaceId: string };
    Querystring: {
      resource_id?: string;
      actor_id?: string;
      action_type?: string;
      date_from?: string;
      date_to?: string;
      limit?: number;
      offset?: number;
    };
  }>('/history/:workspaceId', {
    schema: {
      params: z.object({
        workspaceId: z.string().uuid()
      }),
      querystring: z.object({
        resource_id: z.string().uuid().optional(),
        actor_id: z.string().optional(),
        action_type: z.string().optional(),
        date_from: z.string().optional(),
        date_to: z.string().optional(),
        limit: z.number().optional(),
        offset: z.number().optional()
      }).optional()
    }
  }, async (request, reply) => {
    try {
      const { workspaceId } = request.params;
      const filters = request.query || {};

      // Parse date filters
      const historyFilters = {
        ...filters,
        date_from: filters.date_from ? new Date(filters.date_from) : undefined,
        date_to: filters.date_to ? new Date(filters.date_to) : undefined
      };

      const history = await workflowService.getWorkflowHistory(workspaceId, historyFilters);
      reply.send(history);
    } catch (error) {
      reply.status(500).send({ error: 'Failed to fetch workflow history' });
    }
  });

  // =============================================================================
  // STATISTICS ENDPOINTS
  // =============================================================================

  // GET /api/workflow/statistics/:workspaceId - Get workflow statistics
  fastify.get<{
    Params: { workspaceId: string };
  }>('/statistics/:workspaceId', {
    schema: {
      params: z.object({
        workspaceId: z.string().uuid()
      })
    }
  }, async (request, reply) => {
    try {
      const { workspaceId } = request.params;
      const statistics = await workflowService.getWorkflowStatistics(workspaceId);
      reply.send(statistics);
    } catch (error) {
      reply.status(500).send({ error: 'Failed to fetch workflow statistics' });
    }
  });

  // =============================================================================
  // MAINTENANCE ENDPOINTS
  // =============================================================================

  // POST /api/workflow/maintenance - Perform maintenance tasks
  fastify.post('/maintenance', async (request, reply) => {
    try {
      const result = await workflowService.performMaintenance();
      reply.send(result);
    } catch (error) {
      reply.status(500).send({ error: 'Failed to perform maintenance' });
    }
  });

  // POST /api/workflow/maintenance/expired-locks - Release expired locks
  fastify.post('/maintenance/expired-locks', async (request, reply) => {
    try {
      const releasedCount = await workflowService.releaseExpiredLocks();
      reply.send({ released_count: releasedCount });
    } catch (error) {
      reply.status(500).send({ error: 'Failed to release expired locks' });
    }
  });

  // =============================================================================
  // VALIDATION ENDPOINTS
  // =============================================================================

  // GET /api/workflow/validate/transition - Validate state transition
  fastify.get<{
    Querystring: {
      resource_id: string;
      to_state_id: string;
      user_id: string;
    };
  }>('/validate/transition', {
    schema: {
      querystring: z.object({
        resource_id: z.string().uuid(),
        to_state_id: z.string().uuid(),
        user_id: z.string()
      })
    }
  }, async (request, reply) => {
    try {
      const { resource_id, to_state_id, user_id } = request.query;

      const validation = await workflowService.validateStateTransition(resource_id, to_state_id);
      const canTransition = await workflowService.canUserTransitionState(user_id, resource_id, to_state_id);
      const isLocked = await workflowService.isResourceLocked(resource_id, 'state_change');

      reply.send({
        ...validation,
        can_transition: canTransition,
        is_locked: isLocked
      });
    } catch (error) {
      reply.status(500).send({ error: 'Failed to validate state transition' });
    }
  });

  // GET /api/workflow/validate/lock - Check if resource is locked
  fastify.get<{
    Querystring: {
      resource_id: string;
      lock_type?: string;
    };
  }>('/validate/lock', {
    schema: {
      querystring: z.object({
        resource_id: z.string().uuid(),
        lock_type: z.string().optional()
      })
    }
  }, async (request, reply) => {
    try {
      const { resource_id, lock_type } = request.query;

      const isLocked = await workflowService.isResourceLocked(resource_id, lock_type);
      reply.send({ is_locked: isLocked });
    } catch (error) {
      reply.status(500).send({ error: 'Failed to check resource lock status' });
    }
  });
}

