/**
 * Epic 9.2.6 - Template Service Layer
 * Business logic for project template operations
 */

import { TemplateDAO } from '../database/template-dao';
import { WorkspaceDAO } from '../database/workspace-dao';
import {
  ProjectTemplate,
  CreateProjectTemplate,
  UpdateProjectTemplate,
  TemplateReview,
  CreateTemplateReview,
  UpdateTemplateReview,
  TemplateUsage,
  CreateTemplateUsage,
  UpdateTemplateUsage,
  TemplateCategory,
  TemplateFavorite,
  TemplateDownload,
  ProjectTemplateWithStats,
  TemplateReviewWithAuthor,
  TemplateUsageWithTemplate,
  TemplateFilter,
  TemplateSort,
  TemplateReviewFilter,
  TemplateUsageFilter,
  TemplateAnalytics,
  TemplateExport,
  PaginatedResult,
  PaginationOptions,
  canUserAccessTemplate,
  validateCustomizations,
  applyTemplateCustomizations,
} from '../database/template-models';

export interface TemplateServiceOptions {
  getUserInfo?: (userId: string) => Promise<{ name: string; avatar?: string } | null>;
  checkWorkspaceAccess?: (workspaceId: string, userId: string, permission: number) => Promise<boolean>;
  generateThumbnail?: (templateData: Record<string, any>) => Promise<string>;
  sendNotification?: (userId: string, notification: any) => Promise<void>;
}

export class TemplateService {
  constructor(
    private templateDAO: TemplateDAO,
    private workspaceDAO: WorkspaceDAO,
    private options: TemplateServiceOptions = {}
  ) {}

  // ====== TEMPLATE OPERATIONS ======

  async createTemplate(data: CreateProjectTemplate, userId: string): Promise<ProjectTemplate> {
    // Validate template name
    if (!data.name.trim()) {
      throw new Error('Template name is required');
    }

    // Validate template data
    if (!data.template_data || Object.keys(data.template_data).length === 0) {
      throw new Error('Template data is required');
    }

    // Check workspace access if workspace_id is provided
    if (data.workspace_id) {
      if (this.options.checkWorkspaceAccess) {
        const hasAccess = await this.options.checkWorkspaceAccess(data.workspace_id, userId, 1); // WORKSPACE_READ permission
        if (!hasAccess) {
          throw new Error('Access denied to workspace');
        }
      }
    }

    // Generate thumbnail if service is available
    if (this.options.generateThumbnail && !data.thumbnail_url) {
      try {
        data.thumbnail_url = await this.options.generateThumbnail(data.template_data);
      } catch (error) {
        console.warn('Failed to generate thumbnail:', error);
      }
    }

    const template = await this.templateDAO.createTemplate(data, userId);

    // Log activity if this is a workspace template
    if (template.workspace_id) {
      await this.workspaceDAO.createActivityEvent({
        workspace_id: template.workspace_id,
        actor_id: userId,
        event_type: 'template.created',
        event_data: {
          template_id: template.id,
          template_name: template.name,
          category: template.category,
        },
      });
    }

    return template;
  }

  async getTemplate(id: string, userId: string): Promise<ProjectTemplateWithStats | null> {
    const template = await this.templateDAO.getTemplateWithStats(id, userId);
    if (!template) return null;

    // Check access permissions
    const userWorkspaces = await this.getUserWorkspaceIds(userId);
    if (!canUserAccessTemplate(template, userId, userWorkspaces)) {
      throw new Error('Access denied to template');
    }

    return template;
  }

  async getTemplates(
    filter: TemplateFilter = {},
    sort: TemplateSort = {},
    pagination: PaginationOptions = {},
    userId?: string
  ): Promise<PaginatedResult<ProjectTemplateWithStats>> {
    // If user is provided, filter to only accessible templates
    if (userId) {
      const userWorkspaces = await this.getUserWorkspaceIds(userId);

      // Modify filter to include accessibility check
      const accessibleFilter = { ...filter };

      // For non-admins, restrict visibility
      if (!accessibleFilter.visibility) {
        accessibleFilter.visibility = ['public'];
        if (userWorkspaces.length > 0) {
          accessibleFilter.visibility.push('workspace');
        }
      }
    }

    return this.templateDAO.getTemplates(filter, sort, pagination, userId);
  }

  async updateTemplate(
    id: string,
    data: UpdateProjectTemplate,
    userId: string
  ): Promise<ProjectTemplate | null> {
    const template = await this.templateDAO.getTemplate(id);
    if (!template) return null;

    // Check permissions - only creator or workspace admin can edit
    if (template.created_by !== userId) {
      if (template.workspace_id && this.options.checkWorkspaceAccess) {
        const hasAccess = await this.options.checkWorkspaceAccess(template.workspace_id, userId, 2); // WORKSPACE_WRITE permission
        if (!hasAccess) {
          throw new Error('Insufficient permissions to update template');
        }
      } else {
        throw new Error('Insufficient permissions to update template');
      }
    }

    // Regenerate thumbnail if template data changed
    if (data.template_data && this.options.generateThumbnail && !data.thumbnail_url) {
      try {
        data.thumbnail_url = await this.options.generateThumbnail(data.template_data);
      } catch (error) {
        console.warn('Failed to generate thumbnail:', error);
      }
    }

    const updatedTemplate = await this.templateDAO.updateTemplate(id, data, userId);

    if (updatedTemplate && template.workspace_id) {
      // Log activity
      await this.workspaceDAO.createActivityEvent({
        workspace_id: template.workspace_id,
        actor_id: userId,
        event_type: 'template.updated',
        event_data: {
          template_id: id,
          template_name: updatedTemplate.name,
          changes: Object.keys(data),
        },
      });
    }

    return updatedTemplate;
  }

  async archiveTemplate(id: string, userId: string): Promise<boolean> {
    const template = await this.templateDAO.getTemplate(id);
    if (!template) return false;

    // Check permissions - only creator or workspace admin can archive
    if (template.created_by !== userId) {
      if (template.workspace_id && this.options.checkWorkspaceAccess) {
        const hasAccess = await this.options.checkWorkspaceAccess(template.workspace_id, userId, 8); // WORKSPACE_DELETE permission
        if (!hasAccess) {
          throw new Error('Insufficient permissions to archive template');
        }
      } else {
        throw new Error('Insufficient permissions to archive template');
      }
    }

    const success = await this.templateDAO.archiveTemplate(id);

    if (success && template.workspace_id) {
      // Log activity
      await this.workspaceDAO.createActivityEvent({
        workspace_id: template.workspace_id,
        actor_id: userId,
        event_type: 'template.archived',
        event_data: {
          template_id: id,
          template_name: template.name,
        },
      });
    }

    return success;
  }

  async publishTemplate(id: string, userId: string): Promise<boolean> {
    const template = await this.templateDAO.getTemplate(id);
    if (!template) return false;

    // Check permissions - only creator can publish
    if (template.created_by !== userId) {
      throw new Error('Only the template creator can publish templates');
    }

    // Validate template before publishing
    const validationErrors = this.validateTemplateForPublishing(template);
    if (validationErrors.length > 0) {
      throw new Error(`Template validation failed: ${validationErrors.join(', ')}`);
    }

    const success = await this.templateDAO.publishTemplate(id);

    if (success && template.workspace_id) {
      // Log activity
      await this.workspaceDAO.createActivityEvent({
        workspace_id: template.workspace_id,
        actor_id: userId,
        event_type: 'template.published',
        event_data: {
          template_id: id,
          template_name: template.name,
        },
      });
    }

    return success;
  }

  // ====== TEMPLATE USAGE OPERATIONS ======

  async useTemplate(
    templateId: string,
    customizations: Record<string, any>,
    projectData: { name: string; description?: string; workspace_id: string },
    userId: string
  ): Promise<{ project: any; usage: TemplateUsage }> {
    const template = await this.templateDAO.getTemplate(templateId);
    if (!template) {
      throw new Error('Template not found');
    }

    // Check access
    const userWorkspaces = await this.getUserWorkspaceIds(userId);
    if (!canUserAccessTemplate(template, userId, userWorkspaces)) {
      throw new Error('Access denied to template');
    }

    // Validate customizations
    const validation = validateCustomizations(customizations, template);
    if (!validation.valid) {
      throw new Error(`Customization validation failed: ${validation.errors.join(', ')}`);
    }

    // Apply customizations to template
    const customizedData = applyTemplateCustomizations(
      template.template_data,
      customizations,
      template
    );

    // Create project from template
    const project = await this.workspaceDAO.createProject({
      workspace_id: projectData.workspace_id,
      name: projectData.name,
      description: projectData.description,
      metadata: {
        ...customizedData,
        template_id: templateId,
        template_version: template.version,
        customizations_applied: customizations,
      },
    }, userId);

    // Create usage record
    const usage = await this.templateDAO.createTemplateUsage({
      template_id: templateId,
      project_id: project.id,
      workspace_id: projectData.workspace_id,
      customizations_applied: customizations,
      source: 'manual',
    }, userId);

    // Log activity
    await this.workspaceDAO.createActivityEvent({
      workspace_id: projectData.workspace_id,
      project_id: project.id,
      actor_id: userId,
      event_type: 'template.used',
      event_data: {
        template_id: templateId,
        template_name: template.name,
        project_name: project.name,
      },
    });

    return { project, usage };
  }

  async completeTemplateUsage(
    usageId: string,
    completionData: {
      completion_status: 'completed' | 'abandoned';
      time_to_complete_minutes?: number;
      user_rating?: number;
      user_feedback?: string;
    },
    userId: string
  ): Promise<TemplateUsage | null> {
    const data: UpdateTemplateUsage = {
      ...completionData,
      completed_at: completionData.completion_status === 'completed' ? new Date() : undefined,
    };

    return this.templateDAO.updateTemplateUsage(usageId, data, userId);
  }

  // ====== TEMPLATE REVIEWS OPERATIONS ======

  async createTemplateReview(data: CreateTemplateReview, userId: string): Promise<TemplateReview> {
    const template = await this.templateDAO.getTemplate(data.template_id);
    if (!template) {
      throw new Error('Template not found');
    }

    // Check if user has access to template
    const userWorkspaces = await this.getUserWorkspaceIds(userId);
    if (!canUserAccessTemplate(template, userId, userWorkspaces)) {
      throw new Error('Access denied to template');
    }

    // Check if user has used the template (for verified reviews)
    // This could be implemented by checking template_usages table

    const review = await this.templateDAO.createTemplateReview(data, userId);

    // Send notification to template creator (if different user)
    if (template.created_by !== userId && this.options.sendNotification) {
      await this.options.sendNotification(template.created_by, {
        type: 'template_review',
        title: 'New review on your template',
        message: `${userId} left a ${data.rating}-star review on "${template.name}"`,
        template_id: template.id,
        review_id: review.id,
      });
    }

    return review;
  }

  async getTemplateReviews(
    templateId: string,
    filter: TemplateReviewFilter = {},
    pagination: PaginationOptions = {}
  ): Promise<PaginatedResult<TemplateReviewWithAuthor>> {
    const filterWithTemplate = { ...filter, template_id: templateId };
    return this.templateDAO.getTemplateReviews(filterWithTemplate, pagination);
  }

  // ====== TEMPLATE FAVORITES OPERATIONS ======

  async addTemplateFavorite(templateId: string, userId: string): Promise<TemplateFavorite> {
    const template = await this.templateDAO.getTemplate(templateId);
    if (!template) {
      throw new Error('Template not found');
    }

    // Check access
    const userWorkspaces = await this.getUserWorkspaceIds(userId);
    if (!canUserAccessTemplate(template, userId, userWorkspaces)) {
      throw new Error('Access denied to template');
    }

    return this.templateDAO.addTemplateFavorite(templateId, userId, template.workspace_id);
  }

  async removeTemplateFavorite(templateId: string, userId: string): Promise<boolean> {
    return this.templateDAO.removeTemplateFavorite(templateId, userId);
  }

  async getUserFavoriteTemplates(
    userId: string,
    pagination: PaginationOptions = {}
  ): Promise<PaginatedResult<ProjectTemplateWithStats>> {
    return this.templateDAO.getUserFavoriteTemplates(userId, pagination);
  }

  // ====== TEMPLATE CATEGORIES OPERATIONS ======

  async getTemplateCategories(): Promise<TemplateCategory[]> {
    return this.templateDAO.getTemplateCategories();
  }

  // ====== ANALYTICS AND REPORTING ======

  async getTemplateAnalytics(templateId: string, userId: string, days = 30): Promise<TemplateAnalytics> {
    const template = await this.templateDAO.getTemplate(templateId);
    if (!template) {
      throw new Error('Template not found');
    }

    // Check permissions - only creator or workspace admin can view analytics
    if (template.created_by !== userId) {
      if (template.workspace_id && this.options.checkWorkspaceAccess) {
        const hasAccess = await this.options.checkWorkspaceAccess(template.workspace_id, userId, 1); // WORKSPACE_READ permission
        if (!hasAccess) {
          throw new Error('Access denied to template analytics');
        }
      } else {
        throw new Error('Access denied to template analytics');
      }
    }

    return this.templateDAO.getTemplateAnalytics(templateId, days);
  }

  // ====== TEMPLATE EXPORT/IMPORT ======

  async exportTemplate(
    templateId: string,
    userId: string,
    format: 'json' | 'yaml' | 'zip' = 'json',
    includeAnalytics = false
  ): Promise<TemplateExport> {
    const template = await this.templateDAO.getTemplate(templateId);
    if (!template) {
      throw new Error('Template not found');
    }

    // Check access
    const userWorkspaces = await this.getUserWorkspaceIds(userId);
    if (!canUserAccessTemplate(template, userId, userWorkspaces)) {
      throw new Error('Access denied to template');
    }

    const exportData: TemplateExport = {
      metadata: {
        template_id: template.id,
        name: template.name,
        version: template.version,
        exported_at: new Date().toISOString(),
        exported_by: userId,
        export_format: format,
      },
      template,
    };

    // Include analytics if requested and user has permission
    if (includeAnalytics && (template.created_by === userId || template.workspace_id)) {
      try {
        exportData.usage_analytics = await this.templateDAO.getTemplateAnalytics(templateId);
      } catch (error) {
        console.warn('Failed to include analytics in export:', error);
      }
    }

    // Record download for analytics
    await this.recordTemplateDownload(templateId, userId, format);

    return exportData;
  }

  async importTemplate(
    templateData: TemplateExport,
    userId: string,
    workspaceId?: string
  ): Promise<ProjectTemplate> {
    const createData: CreateProjectTemplate = {
      ...templateData.template,
      workspace_id: workspaceId,
      name: `${templateData.template.name} (Imported)`,
      version: '1.0.0', // Reset version for imported template
    };

    // Remove id and other auto-generated fields
    delete (createData as any).id;
    delete (createData as any).created_at;
    delete (createData as any).updated_at;
    delete (createData as any).usage_count;
    delete (createData as any).rating_average;
    delete (createData as any).rating_count;

    return this.createTemplate(createData, userId);
  }

  // ====== HELPER METHODS ======

  private async getUserWorkspaceIds(userId: string): Promise<string[]> {
    try {
      const result = await this.workspaceDAO.getWorkspacesForUser(userId);
      return result.data.map(w => w.id);
    } catch (error) {
      console.warn('Failed to get user workspaces:', error);
      return [];
    }
  }

  private async recordTemplateDownload(
    templateId: string,
    userId: string,
    format: 'json' | 'yaml' | 'zip'
  ): Promise<void> {
    // This would be implemented to track downloads for analytics
    // For now, we'll skip the implementation
  }

  private validateTemplateForPublishing(template: ProjectTemplate): string[] {
    const errors: string[] = [];

    // Basic validation
    if (!template.name.trim()) {
      errors.push('Template name is required');
    }

    if (!template.description || template.description.trim().length < 20) {
      errors.push('Template description must be at least 20 characters');
    }

    if (!template.template_data || Object.keys(template.template_data).length === 0) {
      errors.push('Template data is required');
    }

    if (template.tags.length === 0) {
      errors.push('At least one tag is required');
    }

    if (!template.thumbnail_url) {
      errors.push('Template thumbnail is required for publishing');
    }

    // Validate customizable fields
    const customizableFields = template.customizable_fields as Record<string, any>;
    for (const [fieldName, fieldDef] of Object.entries(customizableFields)) {
      if (!fieldDef.type) {
        errors.push(`Customizable field '${fieldName}' is missing type`);
      }
      if (!fieldDef.label) {
        errors.push(`Customizable field '${fieldName}' is missing label`);
      }
    }

    return errors;
  }
}

// Visual Diff Service - Orchestrates graph comparison and diff sessions
// Story 9.3.2 - Visual Diff Tool

import { ComparisonDAO } from '../database/comparison-dao.js';
import { VersionHistoryDAO } from '../database/version-dao.js';
import { GraphComparisonService } from './graph-comparison-service.js';
import {
  GraphComparison,
  VisualDiffSession,
  DetailedComparison,
  CompareVersionsRequest,
  CreateDiffSessionRequest,
  UpdateDiffSessionRequest,
  ComparisonConfig,
  GraphData
} from '../database/comparison-models.js';

export interface VisualDiffServiceOptions {
  comparisonConfig?: Partial<ComparisonConfig>;
  enableCaching?: boolean;
  maxCacheSize?: number;
}

export class VisualDiffService {
  private comparisonService: GraphComparisonService;
  private config: ComparisonConfig;

  constructor(
    private comparisonDAO: ComparisonDAO,
    private versionDAO: VersionHistoryDAO,
    options: VisualDiffServiceOptions = {}
  ) {
    this.config = {
      node_similarity_threshold: 0.8,
      edge_similarity_threshold: 0.9,
      structural_weight: 0.6,
      semantic_weight: 0.3,
      visual_weight: 0.1,
      max_comparison_time_ms: 30000,
      enable_caching: true,
      cache_ttl_hours: 24,
      ...options.comparisonConfig
    };

    this.comparisonService = new GraphComparisonService(this.config);
  }

  /**
   * Compare two graph versions with caching support
   */
  async compareVersions(request: CompareVersionsRequest, userId?: string): Promise<DetailedComparison> {
    const { source_version_id, target_version_id, comparison_type = 'structural', include_details = true } = request;

    try {
      // Check for cached comparison first
      if (this.config.enable_caching) {
        const cached = await this.comparisonDAO.getComparisonByVersions(
          source_version_id,
          target_version_id,
          comparison_type
        );

        if (cached) {
          // Check if cache is still valid
          const cacheAge = Date.now() - cached.created_at.getTime();
          const maxAge = this.config.cache_ttl_hours * 60 * 60 * 1000;

          if (cacheAge < maxAge) {
            return await this.enrichComparisonWithDetails(cached, include_details);
          }
        }
      }

      // Fetch version data
      const [sourceVersion, targetVersion] = await Promise.all([
        this.versionDAO.getVersion(source_version_id),
        this.versionDAO.getVersion(target_version_id)
      ]);

      if (!sourceVersion || !targetVersion) {
        throw new Error('One or both versions not found');
      }

      // Convert version data to GraphData format
      const sourceData = this.convertVersionToGraphData(sourceVersion);
      const targetData = this.convertVersionToGraphData(targetVersion);

      // Perform comparison
      const startTime = Date.now();
      const detailedComparison = await this.comparisonService.compareGraphs(
        sourceData,
        targetData,
        comparison_type
      );

      // Save comparison result
      const savedComparison = await this.comparisonDAO.createComparison({
        source_version_id,
        target_version_id,
        comparison_type,
        similarity_score: detailedComparison.similarity_score,
        changes_summary: detailedComparison.changes_summary,
        added_nodes: detailedComparison.added_nodes,
        removed_nodes: detailedComparison.removed_nodes,
        modified_nodes: detailedComparison.modified_nodes,
        added_edges: detailedComparison.added_edges,
        removed_edges: detailedComparison.removed_edges,
        modified_edges: detailedComparison.modified_edges,
        node_diffs: detailedComparison.node_diffs,
        edge_diffs: detailedComparison.edge_diffs,
        property_diffs: detailedComparison.property_diffs,
        comparison_duration_ms: detailedComparison.comparison_duration_ms,
        created_by: userId
      });

      // Save detailed match results if requested
      if (include_details) {
        await Promise.all([
          this.comparisonDAO.createNodeMatchResults(savedComparison.id, detailedComparison.node_matches),
          this.comparisonDAO.createEdgeMatchResults(savedComparison.id, detailedComparison.edge_matches)
        ]);
      }

      return {
        ...detailedComparison,
        id: savedComparison.id
      };

    } catch (error) {
      throw new Error(`Comparison failed: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Create a new visual diff session
   */
  async createDiffSession(request: CreateDiffSessionRequest, userId: string): Promise<VisualDiffSession> {
    try {
      // First ensure we have a comparison
      const comparison = await this.compareVersions({
        source_version_id: request.source_version_id,
        target_version_id: request.target_version_id,
        comparison_type: 'structural',
        include_details: true
      }, userId);

      // Create session with 24-hour expiry
      const expiresAt = new Date();
      expiresAt.setHours(expiresAt.getHours() + 24);

      const session = await this.comparisonDAO.createDiffSession({
        user_id: userId,
        graph_id: request.graph_id,
        comparison_id: comparison.id,
        view_mode: request.view_mode || 'side-by-side',
        highlight_mode: request.highlight_mode || 'changes',
        zoom_level: 1.0,
        viewport_state: {},
        show_unchanged: true,
        show_metadata: false,
        filter_options: {},
        expires_at: expiresAt
      });

      return session;

    } catch (error) {
      throw new Error(`Failed to create diff session: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Get diff session with comparison data
   */
  async getDiffSession(sessionId: string, userId: string): Promise<{
    session: VisualDiffSession;
    comparison: DetailedComparison;
  } | null> {
    try {
      const session = await this.comparisonDAO.getDiffSession(sessionId);
      if (!session || session.user_id !== userId) {
        return null;
      }

      if (!session.comparison_id) {
        throw new Error('Session has no associated comparison');
      }

      const comparison = await this.comparisonDAO.getComparison(session.comparison_id);
      if (!comparison) {
        throw new Error('Comparison not found');
      }

      const detailedComparison = await this.enrichComparisonWithDetails(comparison, true);

      // Update last accessed time
      await this.comparisonDAO.updateDiffSession(sessionId, {});

      return {
        session,
        comparison: detailedComparison
      };

    } catch (error) {
      throw new Error(`Failed to get diff session: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Update diff session settings
   */
  async updateDiffSession(
    sessionId: string,
    updates: UpdateDiffSessionRequest,
    userId: string
  ): Promise<VisualDiffSession | null> {
    try {
      // Verify session belongs to user
      const session = await this.comparisonDAO.getDiffSession(sessionId);
      if (!session || session.user_id !== userId) {
        return null;
      }

      const success = await this.comparisonDAO.updateDiffSession(sessionId, updates);
      if (!success) {
        return null;
      }

      return await this.comparisonDAO.getDiffSession(sessionId);

    } catch (error) {
      throw new Error(`Failed to update diff session: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Delete diff session
   */
  async deleteDiffSession(sessionId: string, userId: string): Promise<boolean> {
    try {
      // Verify session belongs to user
      const session = await this.comparisonDAO.getDiffSession(sessionId);
      if (!session || session.user_id !== userId) {
        return false;
      }

      return await this.comparisonDAO.deleteDiffSession(sessionId);

    } catch (error) {
      throw new Error(`Failed to delete diff session: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Get user's active diff sessions
   */
  async getUserDiffSessions(userId: string): Promise<VisualDiffSession[]> {
    try {
      return await this.comparisonDAO.getUserDiffSessions(userId);
    } catch (error) {
      throw new Error(`Failed to get user sessions: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Get comparison history for a graph
   */
  async getComparisonHistory(
    graphId: string,
    page: number = 1,
    limit: number = 50
  ): Promise<{
    comparisons: GraphComparison[];
    total: number;
    page: number;
    total_pages: number;
  }> {
    try {
      // Get versions for this graph
      const versions = await this.versionDAO.getVersionHistory(graphId, { page: 1, limit: 1000 });
      const versionIds = versions.data.map(v => v.id);

      if (versionIds.length === 0) {
        return { comparisons: [], total: 0, page, total_pages: 0 };
      }

      // Get comparisons involving these versions
      const result = await this.comparisonDAO.getComparisons({}, { page, limit });

      // Filter to only include comparisons for this graph
      const filteredComparisons = result.data.filter(comp => 
        versionIds.includes(comp.source_version_id) || versionIds.includes(comp.target_version_id)
      );

      return {
        comparisons: filteredComparisons,
        total: filteredComparisons.length,
        page,
        total_pages: Math.ceil(filteredComparisons.length / limit)
      };

    } catch (error) {
      throw new Error(`Failed to get comparison history: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Get comparison statistics
   */
  async getComparisonStatistics(graphId?: string): Promise<{
    total_comparisons: number;
    avg_similarity: number;
    comparison_types: Record<string, number>;
    recent_comparisons: number;
    similarity_distribution: {
      high: number; // > 0.8
      medium: number; // 0.5 - 0.8
      low: number; // < 0.5
    };
  }> {
    try {
      const stats = await this.comparisonDAO.getComparisonStatistics(graphId);

      // Calculate similarity distribution
      const comparisons = await this.comparisonDAO.getComparisons(
        graphId ? { graph_id: graphId } : {},
        { page: 1, limit: 1000 }
      );

      const distribution = { high: 0, medium: 0, low: 0 };
      comparisons.data.forEach(comp => {
        if (comp.similarity_score > 0.8) {
          distribution.high++;
        } else if (comp.similarity_score >= 0.5) {
          distribution.medium++;
        } else {
          distribution.low++;
        }
      });

      return {
        ...stats,
        similarity_distribution: distribution
      };

    } catch (error) {
      throw new Error(`Failed to get statistics: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Clean up expired sessions and old comparisons
   */
  async cleanup(): Promise<{
    expired_sessions_removed: number;
    old_comparisons_removed: number;
  }> {
    try {
      const expiredSessions = await this.comparisonDAO.cleanupExpiredSessions();

      // Remove comparisons older than configured TTL
      const cutoffDate = new Date();
      cutoffDate.setHours(cutoffDate.getHours() - this.config.cache_ttl_hours);

      const oldComparisons = await this.comparisonDAO.getComparisons({
        created_before: cutoffDate
      }, { page: 1, limit: 1000 });

      let removedComparisons = 0;
      for (const comparison of oldComparisons.data) {
        await this.comparisonDAO.deleteComparison(comparison.id);
        removedComparisons++;
      }

      return {
        expired_sessions_removed: expiredSessions,
        old_comparisons_removed: removedComparisons
      };

    } catch (error) {
      throw new Error(`Cleanup failed: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Convert version data to GraphData format for comparison
   */
  private convertVersionToGraphData(version: any): GraphData {
    const graphData = JSON.parse(version.graph_data);

    return {
      id: version.graph_id,
      nodes: graphData.nodes || [],
      edges: graphData.edges || [],
      metadata: {
        version_id: version.id,
        version_number: version.version_number,
        created_at: version.created_at,
        description: version.description
      }
    };
  }

  /**
   * Enrich comparison with detailed match results
   */
  private async enrichComparisonWithDetails(
    comparison: GraphComparison,
    includeDetails: boolean
  ): Promise<DetailedComparison> {
    if (!includeDetails) {
      return {
        ...comparison,
        source_data: { id: '', nodes: [], edges: [] },
        target_data: { id: '', nodes: [], edges: [] },
        node_matches: [],
        edge_matches: [],
        algorithm_metadata: {
          steps_executed: [],
          performance_metrics: {},
          confidence_distribution: {}
        }
      };
    }

    try {
      const [nodeMatches, edgeMatches, sourceVersion, targetVersion] = await Promise.all([
        this.comparisonDAO.getNodeMatchResults(comparison.id),
        this.comparisonDAO.getEdgeMatchResults(comparison.id),
        this.versionDAO.getVersion(comparison.source_version_id),
        this.versionDAO.getVersion(comparison.target_version_id)
      ]);

      const sourceData = sourceVersion ? this.convertVersionToGraphData(sourceVersion) : { id: '', nodes: [], edges: [] };
      const targetData = targetVersion ? this.convertVersionToGraphData(targetVersion) : { id: '', nodes: [], edges: [] };

      // Calculate confidence distribution
      const allMatches = [...nodeMatches, ...edgeMatches];
      const confidenceDistribution = { high: 0, medium: 0, low: 0 };
      allMatches.forEach(match => {
        if (match.confidence_score > 0.8) {
          confidenceDistribution.high++;
        } else if (match.confidence_score >= 0.5) {
          confidenceDistribution.medium++;
        } else {
          confidenceDistribution.low++;
        }
      });

      return {
        ...comparison,
        source_data: sourceData,
        target_data: targetData,
        node_matches: nodeMatches,
        edge_matches: edgeMatches,
        algorithm_metadata: {
          steps_executed: ['Database retrieval', 'Match result assembly'],
          performance_metrics: {
            total_duration_ms: comparison.comparison_duration_ms || 0,
            node_match_count: nodeMatches.length,
            edge_match_count: edgeMatches.length,
            similarity_score: comparison.similarity_score
          },
          confidence_distribution: confidenceDistribution
        }
      };

    } catch (error) {
      throw new Error(`Failed to enrich comparison: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }
}

// Epic 9.4 - Workflow Orchestration Service
// Business logic for workflow state management

import { WorkflowDAO } from '../database/workflow-dao';
import { Database } from '../database/connection';
import {
  WorkflowState,
  WorkflowTransition,
  WorkflowApproval,
  WorkflowLock,
  WorkflowSchedule,
  WorkflowStatistics,
  StateTransitionRequest,
  StateTransitionResult,
  WorkflowEvent,
  WorkflowEventHandler,
  WorkflowConfiguration,
  CreateWorkflowStateSchema,
  CreateWorkflowTransitionSchema,
  CreateWorkflowApprovalSchema,
  CreateWorkflowLockSchema,
  CreateWorkflowScheduleSchema,
  ApproveWorkflowSchema,
  RejectWorkflowSchema
} from '../database/workflow-models';

export class WorkflowService {
  private dao: WorkflowDAO;
  private eventHandlers: Map<string, WorkflowEventHandler[]> = new Map();
  private config: WorkflowConfiguration;

  constructor(db: Database) {
    this.dao = new WorkflowDAO(db);
    this.config = this.getDefaultConfiguration();
  }

  // =============================================================================
  // CONFIGURATION
  // =============================================================================

  private getDefaultConfiguration(): WorkflowConfiguration {
    return {
      auto_lock_on_state_change: true,
      auto_release_locks_on_completion: true,
      require_approval_for_final_states: true,
      default_approval_timeout_hours: 72,
      max_concurrent_locks_per_resource: 3,
      audit_retention_days: 365,
      notification_settings: {
        approval_requested: true,
        approval_completed: true,
        lock_acquired: true,
        schedule_failed: true
      }
    };
  }

  setConfiguration(config: Partial<WorkflowConfiguration>): void {
    this.config = { ...this.config, ...config };
  }

  getConfiguration(): WorkflowConfiguration {
    return { ...this.config };
  }

  // =============================================================================
  // EVENT SYSTEM
  // =============================================================================

  addEventListener(eventType: string, handler: WorkflowEventHandler): void {
    if (!this.eventHandlers.has(eventType)) {
      this.eventHandlers.set(eventType, []);
    }
    this.eventHandlers.get(eventType)!.push(handler);
  }

  removeEventListener(eventType: string, handler: WorkflowEventHandler): void {
    const handlers = this.eventHandlers.get(eventType);
    if (handlers) {
      const index = handlers.indexOf(handler);
      if (index > -1) {
        handlers.splice(index, 1);
      }
    }
  }

  private async emitEvent(event: WorkflowEvent): Promise<void> {
    const handlers = this.eventHandlers.get(event.type) || [];
    await Promise.all(handlers.map(handler => handler(event)));
  }

  // =============================================================================
  // WORKFLOW STATE MANAGEMENT
  // =============================================================================

  async createWorkflowState(data: Zod.infer<typeof CreateWorkflowStateSchema>): Promise<WorkflowState> {
    const state = await this.dao.createWorkflowState(data);

    await this.emitEvent({
      type: 'state_changed',
      workspace_id: data.workspace_id,
      resource_id: '', // Not applicable for state creation
      actor_id: 'system',
      timestamp: new Date(),
      data: { action: 'state_created', state_id: state.id, state_name: state.name }
    });

    return state;
  }

  async getWorkflowStates(workspaceId: string): Promise<WorkflowState[]> {
    return this.dao.getWorkflowStates({ workspace_id: workspaceId });
  }

  async updateWorkflowState(id: string, updates: Partial<WorkflowState>): Promise<WorkflowState | null> {
    return this.dao.updateWorkflowState(id, updates);
  }

  async deleteWorkflowState(id: string): Promise<boolean> {
    return this.dao.deleteWorkflowState(id);
  }

  // =============================================================================
  // WORKFLOW TRANSITIONS
  // =============================================================================

  async createWorkflowTransition(data: Zod.infer<typeof CreateWorkflowTransitionSchema>): Promise<WorkflowTransition> {
    return this.dao.createWorkflowTransition(data);
  }

  async getWorkflowTransitions(workspaceId: string, fromStateId?: string): Promise<WorkflowTransition[]> {
    return this.dao.getWorkflowTransitions(workspaceId, fromStateId);
  }

  async deleteWorkflowTransition(id: string): Promise<boolean> {
    return this.dao.deleteWorkflowTransition(id);
  }

  // =============================================================================
  // STATE TRANSITION LOGIC
  // =============================================================================

  async transitionResourceState(
    resourceId: string,
    toStateId: string,
    actorId: string,
    options: {
      comment?: string;
      metadata?: Record<string, any>;
      force?: boolean;
      lockDuration?: number; // minutes
    } = {}
  ): Promise<StateTransitionResult> {
    // Auto-lock resource if configured
    if (this.config.auto_lock_on_state_change) {
      await this.acquireLock(resourceId, actorId, 'state_change', {
        reason: 'Auto-lock for state transition',
        duration: options.lockDuration || 60 // 1 hour default
      });
    }

    const request: StateTransitionRequest = {
      resource_id: resourceId,
      to_state_id: toStateId,
      comment: options.comment,
      metadata: options.metadata,
      force: options.force
    };

    const result = await this.dao.transitionResourceState(request, actorId);

    // Emit appropriate event
    if (result.success) {
      if (result.approval_required) {
        await this.emitEvent({
          type: 'approval_requested',
          workspace_id: '', // Will be filled by DAO
          resource_id: resourceId,
          actor_id: actorId,
          timestamp: new Date(),
          data: { approval_id: result.approval_id, to_state_id: toStateId }
        });
      } else {
        await this.emitEvent({
          type: 'state_changed',
          workspace_id: '', // Will be filled by DAO
          resource_id: resourceId,
          actor_id: actorId,
          timestamp: new Date(),
          data: { new_state_id: result.new_state_id, comment: options.comment }
        });

        // Auto-release lock if configured
        if (this.config.auto_release_locks_on_completion) {
          await this.releaseLocksByResource(resourceId, actorId, 'state_change');
        }
      }
    }

    return result;
  }

  // =============================================================================
  // APPROVAL MANAGEMENT
  // =============================================================================

  async createWorkflowApproval(data: Zod.infer<typeof CreateWorkflowApprovalSchema>): Promise<WorkflowApproval> {
    // Set default due date if not provided
    if (!data.due_date) {
      const dueDate = new Date();
      dueDate.setHours(dueDate.getHours() + this.config.default_approval_timeout_hours);
      data.due_date = dueDate;
    }

    const approval = await this.dao.createWorkflowApproval(data);

    await this.emitEvent({
      type: 'approval_requested',
      workspace_id: data.workspace_id,
      resource_id: data.resource_id,
      actor_id: data.requester_id,
      timestamp: new Date(),
      data: { approval_id: approval.id, transition_id: data.transition_id }
    });

    return approval;
  }

  async getWorkflowApprovals(workspaceId: string, filters: any = {}): Promise<WorkflowApproval[]> {
    return this.dao.getWorkflowApprovals({ workspace_id: workspaceId, ...filters });
  }

  async approveWorkflow(approvalId: string, approverId: string, comment?: string): Promise<StateTransitionResult> {
    const data = { approved_by: approverId, approval_comment: comment };
    const result = await this.dao.approveWorkflow(approvalId, data);

    if (result.success) {
      await this.emitEvent({
        type: 'approval_completed',
        workspace_id: '', // Will be filled by DAO
        resource_id: '', // Will be filled by DAO
        actor_id: approverId,
        timestamp: new Date(),
        data: { approval_id: approvalId, status: 'approved', comment }
      });

      // Auto-release locks if configured
      if (this.config.auto_release_locks_on_completion) {
        // Resource ID would need to be retrieved from approval
        // await this.releaseLocksByResource(resourceId, approverId, 'state_change');
      }
    }

    return result;
  }

  async rejectWorkflow(approvalId: string, rejectorId: string, reason: string): Promise<boolean> {
    const data = { approved_by: rejectorId, rejection_reason: reason };
    const result = await this.dao.rejectWorkflow(approvalId, data);

    if (result) {
      await this.emitEvent({
        type: 'approval_completed',
        workspace_id: '', // Will be filled by DAO
        resource_id: '', // Will be filled by DAO
        actor_id: rejectorId,
        timestamp: new Date(),
        data: { approval_id: approvalId, status: 'rejected', reason }
      });
    }

    return result;
  }

  // =============================================================================
  // LOCK MANAGEMENT
  // =============================================================================

  async acquireLock(
    resourceId: string,
    userId: string,
    lockType: 'edit' | 'state_change' | 'delete' | 'custom' = 'edit',
    options: {
      reason?: string;
      duration?: number; // minutes
      metadata?: Record<string, any>;
    } = {}
  ): Promise<WorkflowLock> {
    // Check existing locks
    const existingLocks = await this.dao.getWorkflowLocks({ resource_id: resourceId });

    if (existingLocks.length >= this.config.max_concurrent_locks_per_resource) {
      throw new Error(`Maximum concurrent locks (${this.config.max_concurrent_locks_per_resource}) exceeded for resource`);
    }

    // Check for conflicting locks
    const conflictingLock = existingLocks.find(lock => lock.lock_type === lockType);
    if (conflictingLock) {
      throw new Error(`Resource already has a ${lockType} lock`);
    }

    const expiresAt = options.duration ? new Date(Date.now() + options.duration * 60 * 1000) : undefined;

    const lockData = {
      workspace_id: '', // Will be filled by DAO from resource
      resource_id: resourceId,
      locked_by: userId,
      lock_type: lockType,
      lock_reason: options.reason,
      expires_at: expiresAt,
      metadata: options.metadata || {}
    };

    const lock = await this.dao.createWorkflowLock(lockData);

    await this.emitEvent({
      type: 'lock_acquired',
      workspace_id: lock.workspace_id,
      resource_id: resourceId,
      actor_id: userId,
      timestamp: new Date(),
      data: { lock_id: lock.id, lock_type: lockType, expires_at: expiresAt }
    });

    return lock;
  }

  async releaseLock(lockId: string, userId: string): Promise<boolean> {
    const result = await this.dao.releaseWorkflowLock(lockId, userId);

    if (result) {
      await this.emitEvent({
        type: 'lock_released',
        workspace_id: '', // Will be filled by DAO
        resource_id: '', // Will be filled by DAO
        actor_id: userId,
        timestamp: new Date(),
        data: { lock_id: lockId }
      });
    }

    return result;
  }

  async releaseLocksByResource(resourceId: string, userId: string, lockType?: string): Promise<number> {
    const locks = await this.dao.getWorkflowLocks({ 
      resource_id: resourceId, 
      lock_type: lockType as any 
    });

    let releasedCount = 0;
    for (const lock of locks) {
      if (await this.releaseLock(lock.id, userId)) {
        releasedCount++;
      }
    }

    return releasedCount;
  }

  async getWorkflowLocks(workspaceId: string, filters: any = {}): Promise<WorkflowLock[]> {
    return this.dao.getWorkflowLocks({ workspace_id: workspaceId, ...filters });
  }

  async releaseExpiredLocks(): Promise<number> {
    return this.dao.releaseExpiredLocks();
  }

  // =============================================================================
  // WORKFLOW HISTORY
  // =============================================================================

  async getWorkflowHistory(workspaceId: string, filters: any = {}): Promise<any[]> {
    return this.dao.getWorkflowHistory({ workspace_id: workspaceId, ...filters });
  }

  // =============================================================================
  // STATISTICS AND REPORTING
  // =============================================================================

  async getWorkflowStatistics(workspaceId: string): Promise<WorkflowStatistics> {
    return this.dao.getWorkflowStatistics(workspaceId);
  }

  // =============================================================================
  // VALIDATION HELPERS
  // =============================================================================

  async validateStateTransition(resourceId: string, toStateId: string): Promise<{
    valid: boolean;
    transition?: WorkflowTransition;
    error?: string;
  }> {
    // This would include logic to validate if a transition is allowed
    // based on current state, user permissions, etc.
    return { valid: true };
  }

  async canUserTransitionState(userId: string, resourceId: string, toStateId: string): Promise<boolean> {
    // This would check user permissions against the transition requirements
    return true;
  }

  async isResourceLocked(resourceId: string, lockType?: string): Promise<boolean> {
    const locks = await this.dao.getWorkflowLocks({ 
      resource_id: resourceId, 
      lock_type: lockType as any 
    });
    return locks.length > 0;
  }

  // =============================================================================
  // MAINTENANCE TASKS
  // =============================================================================

  async performMaintenance(): Promise<{
    expired_locks_released: number;
    overdue_approvals: number;
    cleanup_tasks_completed: number;
  }> {
    const expiredLocks = await this.releaseExpiredLocks();

    // Get overdue approvals
    const overdueApprovals = await this.dao.getWorkflowApprovals({ overdue: true });

    // Additional cleanup tasks could be added here

    return {
      expired_locks_released: expiredLocks,
      overdue_approvals: overdueApprovals.length,
      cleanup_tasks_completed: 1
    };
  }
}

/**
 * Epic 9.2.1 - Workspace Service Layer
 * Business logic for collaborative workspace operations
 */

import { WorkspaceDAO } from '../database/workspace-dao';
import {
  Workspace,
  CreateWorkspace,
  UpdateWorkspace,
  Project,
  CreateProject,
  UpdateProject,
  Resource,
  CreateResource,
  CreateUserMembership,
  CreateACLAssignment,
  ActivityEvent,
  CreateActivityEvent,
  Comment,
  CreateComment,
  UpdateComment,
  Notification,
  CreateNotification,
  WorkspaceWithMembership,
  ProjectWithStats,
  PaginatedResult,
  PaginationOptions,
  WorkspaceFilter,
  ProjectFilter,
  ActivityEventFilter,
  CommentFilter,
  PERMISSIONS,
} from '../database/workspace-models';

export interface WorkspaceServiceOptions {
  getUserInfo?: (userId: string) => Promise<{ name: string; avatar?: string } | null>;
  sendNotification?: (notification: Notification) => Promise<void>;
}

export class WorkspaceService {
  constructor(
    private dao: WorkspaceDAO,
    private options: WorkspaceServiceOptions = {}
  ) {}

  // ====== WORKSPACE OPERATIONS ======

  async createWorkspace(data: CreateWorkspace, userId: string): Promise<Workspace> {
    // Validate workspace name
    if (!data.name.trim()) {
      throw new Error('Workspace name is required');
    }

    const workspace = await this.dao.createWorkspace(data, userId);

    // Send welcome notification
    if (this.options.sendNotification) {
      const notification = await this.dao.createNotification({
        user_id: userId,
        workspace_id: workspace.id,
        notification_type: 'workspace.created',
        title: 'Welcome to your new workspace',
        message: `Your workspace "${workspace.name}" has been created successfully.`,
        priority: 'normal',
      });
      await this.options.sendNotification(notification);
    }

    return workspace;
  }

  async getWorkspace(id: string, userId: string): Promise<Workspace | null> {
    const workspace = await this.dao.getWorkspace(id);
    if (!workspace) return null;

    // Check if user has access to this workspace
    const hasAccess = await this.checkWorkspaceAccess(id, userId, PERMISSIONS.WORKSPACE_READ);
    if (!hasAccess) {
      throw new Error('Access denied to workspace');
    }

    return workspace;
  }

  async getUserWorkspaces(
    userId: string,
    filter: WorkspaceFilter = {},
    pagination: PaginationOptions = {}
  ): Promise<PaginatedResult<WorkspaceWithMembership>> {
    return this.dao.getWorkspacesForUser(userId, filter, pagination);
  }

  async updateWorkspace(
    id: string,
    data: UpdateWorkspace,
    userId: string
  ): Promise<Workspace | null> {
    // Check permissions
    const hasAccess = await this.checkWorkspaceAccess(id, userId, PERMISSIONS.WORKSPACE_WRITE);
    if (!hasAccess) {
      throw new Error('Insufficient permissions to update workspace');
    }

    const workspace = await this.dao.updateWorkspace(id, data);
    if (workspace) {
      // Log activity
      await this.dao.createActivityEvent({
        workspace_id: id,
        actor_id: userId,
        event_type: 'workspace.updated',
        event_data: { changes: Object.keys(data) },
      });
    }

    return workspace;
  }

  async archiveWorkspace(id: string, userId: string): Promise<boolean> {
    // Check permissions (only admin can archive)
    const hasAccess = await this.checkWorkspaceAccess(id, userId, PERMISSIONS.WORKSPACE_ADMIN);
    if (!hasAccess) {
      throw new Error('Only workspace administrators can archive workspaces');
    }

    const success = await this.dao.archiveWorkspace(id);
    if (success) {
      // Log activity
      await this.dao.createActivityEvent({
        workspace_id: id,
        actor_id: userId,
        event_type: 'workspace.archived',
        event_data: {},
      });
    }

    return success;
  }

  // ====== PROJECT OPERATIONS ======

  async createProject(data: CreateProject, userId: string): Promise<Project> {
    // Check permissions
    const hasAccess = await this.checkWorkspaceAccess(
      data.workspace_id,
      userId,
      PERMISSIONS.PROJECT_CREATE
    );
    if (!hasAccess) {
      throw new Error('Insufficient permissions to create projects');
    }

    if (!data.name.trim()) {
      throw new Error('Project name is required');
    }

    return this.dao.createProject(data, userId);
  }

  async getProject(id: string, userId: string): Promise<Project | null> {
    const project = await this.dao.getProject(id);
    if (!project) return null;

    // Check access
    const hasAccess = await this.checkWorkspaceAccess(
      project.workspace_id,
      userId,
      PERMISSIONS.PROJECT_READ
    );
    if (!hasAccess) {
      throw new Error('Access denied to project');
    }

    return project;
  }

  async getProjectsInWorkspace(
    workspaceId: string,
    userId: string,
    filter: ProjectFilter = {},
    pagination: PaginationOptions = {}
  ): Promise<PaginatedResult<ProjectWithStats>> {
    // Check access
    const hasAccess = await this.checkWorkspaceAccess(workspaceId, userId, PERMISSIONS.PROJECT_READ);
    if (!hasAccess) {
      throw new Error('Access denied to workspace projects');
    }

    return this.dao.getProjectsInWorkspace(workspaceId, filter, pagination);
  }

  async updateProject(
    id: string,
    data: UpdateProject,
    userId: string
  ): Promise<Project | null> {
    const project = await this.dao.getProject(id);
    if (!project) return null;

    // Check permissions
    const hasAccess = await this.checkWorkspaceAccess(
      project.workspace_id,
      userId,
      PERMISSIONS.PROJECT_WRITE
    );
    if (!hasAccess) {
      throw new Error('Insufficient permissions to update project');
    }

    return this.dao.updateProject(id, data, userId);
  }

  async deleteProject(id: string, userId: string): Promise<boolean> {
    const project = await this.dao.getProject(id);
    if (!project) return false;

    // Check permissions
    const hasAccess = await this.checkWorkspaceAccess(
      project.workspace_id,
      userId,
      PERMISSIONS.PROJECT_DELETE
    );
    if (!hasAccess) {
      throw new Error('Insufficient permissions to delete project');
    }

    return this.dao.updateProject(id, { status: 'deleted' }, userId) !== null;
  }

  // ====== RESOURCE OPERATIONS ======

  async createResource(data: CreateResource, userId: string): Promise<Resource> {
    const project = await this.dao.getProject(data.project_id);
    if (!project) {
      throw new Error('Project not found');
    }

    // Check permissions
    const hasAccess = await this.checkWorkspaceAccess(
      project.workspace_id,
      userId,
      PERMISSIONS.RESOURCE_CREATE
    );
    if (!hasAccess) {
      throw new Error('Insufficient permissions to create resources');
    }

    if (!data.name.trim()) {
      throw new Error('Resource name is required');
    }

    return this.dao.createResource(data, userId);
  }

  async getResource(id: string, userId: string): Promise<Resource | null> {
    const resource = await this.dao.getResource(id);
    if (!resource) return null;

    const project = await this.dao.getProject(resource.project_id);
    if (!project) return null;

    // Check access
    const hasAccess = await this.checkWorkspaceAccess(
      project.workspace_id,
      userId,
      PERMISSIONS.RESOURCE_READ
    );
    if (!hasAccess) {
      throw new Error('Access denied to resource');
    }

    return resource;
  }

  // ====== USER MANAGEMENT ======

  async inviteUserToWorkspace(
    workspaceId: string,
    userIdToInvite: string,
    roleName: string,
    invitedBy: string
  ): Promise<void> {
    // Check permissions
    const hasAccess = await this.checkWorkspaceAccess(workspaceId, invitedBy, PERMISSIONS.USER_INVITE);
    if (!hasAccess) {
      throw new Error('Insufficient permissions to invite users');
    }

    // Get the role
    const role = await this.dao.getRole(workspaceId, roleName);
    if (!role) {
      throw new Error(`Role '${roleName}' not found`);
    }

    // Create membership
    await this.dao.createUserMembership(
      {
        user_id: userIdToInvite,
        workspace_id: workspaceId,
      },
      invitedBy
    );

    // Assign role
    await this.dao.createACLAssignment(
      {
        user_id: userIdToInvite,
        role_id: role.id,
        scope_type: 'workspace',
        scope_id: workspaceId,
      },
      invitedBy
    );

    // Log activity
    await this.dao.createActivityEvent({
      workspace_id: workspaceId,
      actor_id: invitedBy,
      event_type: 'user.invited',
      event_data: { invited_user: userIdToInvite, role: roleName },
    });

    // Send notification to invited user
    if (this.options.sendNotification) {
      const workspace = await this.dao.getWorkspace(workspaceId);
      if (workspace) {
        const notification = await this.dao.createNotification({
          user_id: userIdToInvite,
          workspace_id: workspaceId,
          notification_type: 'user.invited',
          title: 'Workspace invitation',
          message: `You've been invited to join the workspace "${workspace.name}".`,
          priority: 'normal',
        });
        await this.options.sendNotification(notification);
      }
    }
  }

  // ====== ACTIVITY FEED ======

  async getActivityFeed(
    workspaceId: string,
    userId: string,
    filter: ActivityEventFilter = {},
    pagination: PaginationOptions = {}
  ): Promise<PaginatedResult<ActivityEventWithActorInfo>> {
    // Check access
    const hasAccess = await this.checkWorkspaceAccess(workspaceId, userId, PERMISSIONS.ACTIVITY_READ);
    if (!hasAccess) {
      throw new Error('Access denied to activity feed');
    }

    return this.dao.getActivityFeed(workspaceId, filter, pagination);
  }

  async getActivityEventById(eventId: string, userId: string): Promise<ActivityEventWithActorInfo | null> {
    const event = await this.dao.getActivityEventById(eventId);
    if (!event) return null;

    // Check access to the workspace
    const hasAccess = await this.checkWorkspaceAccess(event.workspace_id, userId, PERMISSIONS.ACTIVITY_READ);
    if (!hasAccess) {
      throw new Error('Access denied to activity event');
    }

    return event;
  }

  async getActivityEventTypes(workspaceId: string, userId: string): Promise<string[]> {
    // Check access
    const hasAccess = await this.checkWorkspaceAccess(workspaceId, userId, PERMISSIONS.ACTIVITY_READ);
    if (!hasAccess) {
      throw new Error('Access denied to workspace');
    }

    return this.dao.getActivityEventTypes(workspaceId);
  }

  async getActivityStats(
    workspaceId: string,
    userId: string,
    days = 30
  ): Promise<{
    total_events: number;
    events_by_type: Record<string, number>;
    events_by_day: Array<{ date: string; count: number }>;
    most_active_users: Array<{ user_id: string; count: number }>;
  }> {
    // Check access
    const hasAccess = await this.checkWorkspaceAccess(workspaceId, userId, PERMISSIONS.ACTIVITY_READ);
    if (!hasAccess) {
      throw new Error('Access denied to workspace activity stats');
    }

    return this.dao.getActivityStats(workspaceId, days);
  }

  async getProjectActivityFeed(
    projectId: string,
    userId: string,
    pagination: PaginationOptions = {}
  ): Promise<PaginatedResult<ActivityEventWithActorInfo>> {
    const project = await this.dao.getProject(projectId);
    if (!project) {
      throw new Error('Project not found');
    }

    // Check access
    const hasAccess = await this.checkWorkspaceAccess(
      project.workspace_id,
      userId,
      PERMISSIONS.ACTIVITY_READ
    );
    if (!hasAccess) {
      throw new Error('Access denied to project activity');
    }

    return this.dao.getActivityFeed(
      project.workspace_id,
      { project_id: projectId },
      pagination
    );
  }

  async getUserActivityFeed(
    workspaceId: string,
    targetUserId: string,
    requestingUserId: string,
    pagination: PaginationOptions = {}
  ): Promise<PaginatedResult<ActivityEventWithActorInfo>> {
    // Check access
    const hasAccess = await this.checkWorkspaceAccess(workspaceId, requestingUserId, PERMISSIONS.ACTIVITY_READ);
    if (!hasAccess) {
      throw new Error('Access denied to workspace activity');
    }

    return this.dao.getActivityFeed(
      workspaceId,
      { actor_id: targetUserId },
      pagination
    );
  }

  // ====== COMMENT OPERATIONS ======

  async createComment(data: CreateComment): Promise<Comment> {
    // Validate content
    if (!data.content || !data.content.trim()) {
      throw new Error('Comment content is required');
    }

    // Check permissions based on workspace access
    const hasAccess = await this.checkWorkspaceAccess(
      data.workspace_id,
      data.author_id,
      PERMISSIONS.COMMENT_WRITE
    );
    if (!hasAccess) {
      throw new Error('Insufficient permissions to create comments');
    }

    // If this is a reply, validate parent comment exists
    if (data.parent_comment_id) {
      const parentComment = await this.dao.getComment(data.parent_comment_id);
      if (!parentComment) {
        throw new Error('Parent comment not found');
      }
      if (parentComment.workspace_id !== data.workspace_id) {
        throw new Error('Parent comment is not in the same workspace');
      }
    }

    const comment = await this.dao.createComment(data);

    // Send notifications for mentions and replies
    if (data.parent_comment_id) {
      const parentComment = await this.dao.getComment(data.parent_comment_id);
      if (parentComment && parentComment.author_id !== data.author_id) {
        // Notify parent comment author
        await this.createNotification({
          user_id: parentComment.author_id,
          workspace_id: data.workspace_id,
          notification_type: 'comment_reply',
          title: 'New reply to your comment',
          message: `${data.author_id} replied to your comment`,
          action_url: `/workspaces/${data.workspace_id}/comments/${comment.id}`,
          priority: 'normal',
        });
      }
    }

    return comment;
  }

  async updateComment(
    commentId: string,
    updates: UpdateComment,
    userId: string
  ): Promise<Comment | null> {
    const comment = await this.dao.getComment(commentId);
    if (!comment) {
      throw new Error('Comment not found');
    }

    // Only author can edit their comments, or users with admin permissions
    if (comment.author_id !== userId) {
      const hasAccess = await this.checkWorkspaceAccess(
        comment.workspace_id,
        userId,
        PERMISSIONS.COMMENT_DELETE
      );
      if (!hasAccess) {
        throw new Error('Insufficient permissions to edit this comment');
      }
    }

    if (updates.content && !updates.content.trim()) {
      throw new Error('Comment content cannot be empty');
    }

    return this.dao.updateComment(commentId, userId, updates);
  }

  async deleteComment(commentId: string, userId: string): Promise<boolean> {
    const comment = await this.dao.getComment(commentId);
    if (!comment) {
      return false;
    }

    // Only author can delete their comments, or users with admin permissions
    if (comment.author_id !== userId) {
      const hasAccess = await this.checkWorkspaceAccess(
        comment.workspace_id,
        userId,
        PERMISSIONS.COMMENT_DELETE
      );
      if (!hasAccess) {
        throw new Error('Insufficient permissions to delete this comment');
      }
    }

    return this.dao.deleteComment(commentId, userId);
  }

  async getCommentsByTarget(
    workspaceId: string,
    targetType: string,
    targetId: string,
    userId: string,
    options: PaginationOptions = {}
  ): Promise<PaginatedResult<Comment>> {
    // Check read permissions
    const hasAccess = await this.checkWorkspaceAccess(
      workspaceId,
      userId,
      PERMISSIONS.COMMENT_READ
    );
    if (!hasAccess) {
      throw new Error('Insufficient permissions to view comments');
    }

    return this.dao.getCommentsByTarget(workspaceId, targetType, targetId, options);
  }

  async getCommentReplies(
    commentId: string,
    userId: string,
    options: PaginationOptions = {}
  ): Promise<PaginatedResult<Comment>> {
    const comment = await this.dao.getComment(commentId);
    if (!comment) {
      throw new Error('Comment not found');
    }

    // Check read permissions
    const hasAccess = await this.checkWorkspaceAccess(
      comment.workspace_id,
      userId,
      PERMISSIONS.COMMENT_READ
    );
    if (!hasAccess) {
      throw new Error('Insufficient permissions to view comment replies');
    }

    return this.dao.getCommentReplies(commentId, options);
  }

  async getCommentsByResource(
    resourceId: string,
    userId: string,
    options: PaginationOptions = {}
  ): Promise<PaginatedResult<Comment>> {
    const resource = await this.dao.getResource(resourceId);
    if (!resource) {
      throw new Error('Resource not found');
    }

    const project = await this.dao.getProject(resource.project_id);
    if (!project) {
      throw new Error('Project not found');
    }

    // Check read permissions
    const hasAccess = await this.checkWorkspaceAccess(
      project.workspace_id,
      userId,
      PERMISSIONS.COMMENT_READ
    );
    if (!hasAccess) {
      throw new Error('Insufficient permissions to view comments');
    }

    return this.dao.getCommentsByResource(resourceId, options);
  }

  async resolveComment(
    commentId: string,
    userId: string,
    resolved: boolean = true
  ): Promise<Comment | null> {
    const comment = await this.dao.getComment(commentId);
    if (!comment) {
      throw new Error('Comment not found');
    }

    // Check permissions
    const hasAccess = await this.checkWorkspaceAccess(
      comment.workspace_id,
      userId,
      PERMISSIONS.COMMENT_WRITE
    );
    if (!hasAccess) {
      throw new Error('Insufficient permissions to resolve comments');
    }

    return this.dao.updateComment(commentId, userId, {
      metadata: {
        ...comment.metadata,
        resolved,
        resolved_by: resolved ? userId : undefined,
        resolved_at: resolved ? new Date().toISOString() : undefined,
      },
    });
  }

  // ====== PERMISSION CHECKING ======

  private async checkWorkspaceAccess(
    workspaceId: string,
    userId: string,
