/**
 * Fastify type declarations for Epic 9.2.1
 * Extends Fastify types to include custom decorations
 */

import { Database } from 'better-sqlite3';

declare module 'fastify' {
  interface FastifyInstance {
    db: Database;
  }
}

import { FastifyInstance } from 'fastify';
import { WebSocket } from 'ws';
import { EventEmitter } from 'events';
import { v4 as uuidv4 } from 'uuid';
import { AnalyticsCollector } from '../analytics/AnalyticsCollector';
import { AnalyticsDashboard } from '../analytics/AnalyticsDashboard';
import { CostTracker } from '../analytics/CostTracker';

/**
 * WebSocket message types (matching client)
 */
export enum WebSocketMessageType {
  ANALYTICS_UPDATE = 'analytics_update',
  COST_ALERT = 'cost_alert',
  BUDGET_ALERT = 'budget_alert',
  PERFORMANCE_METRIC = 'performance_metric',
  USER_ACTIVITY = 'user_activity',
  SYSTEM_STATUS = 'system_status',
  RECOMMENDATION = 'recommendation',
  ERROR = 'error',
  HEARTBEAT = 'heartbeat',
  SUBSCRIPTION = 'subscription',
  UNSUBSCRIPTION = 'unsubscription'
}

/**
 * WebSocket message structure
 */
export interface WebSocketMessage {
  type: WebSocketMessageType;
  data: any;
  timestamp: number;
  id?: string;
}

/**
 * Client connection info
 */
export interface ClientConnection {
  id: string;
  socket: WebSocket;
  userId?: number;
  organizationId?: number;
  subscriptions: Set<string>;
  lastActivity: number;
  isAuthenticated: boolean;
}

/**
 * Subscription configuration
 */
export interface SubscriptionConfig {
  topic: string;
  filters?: {
    userId?: number;
    organizationId?: number;
    eventTypes?: string[];
    minSeverity?: 'info' | 'warning' | 'critical';
  };
  throttle?: number;
}

/**
 * Analytics WebSocket server
 */
export class AnalyticsWebSocketServer extends EventEmitter {
  private clients: Map<string, ClientConnection> = new Map();
  private topicSubscriptions: Map<string, Set<string>> = new Map();
  private analyticsCollector: AnalyticsCollector;
  private analyticsDashboard: AnalyticsDashboard;
  private costTracker: CostTracker;
  private heartbeatInterval: NodeJS.Timeout | null = null;
  private cleanupInterval: NodeJS.Timeout | null = null;

  constructor(
    analyticsCollector: AnalyticsCollector,
    analyticsDashboard: AnalyticsDashboard,
    costTracker: CostTracker
  ) {
    super();
    this.analyticsCollector = analyticsCollector;
    this.analyticsDashboard = analyticsDashboard;
    this.costTracker = costTracker;

    this.setupEventListeners();
    this.startHeartbeat();
    this.startCleanup();
  }

  /**
   * Setup WebSocket server with Fastify
   */
  setupWebSocketServer(fastify: FastifyInstance): void {
    // Register websocket support
    fastify.register(require('@fastify/websocket'));

    // WebSocket route
    fastify.register(async function (fastify) {
      fastify.get('/ws/analytics', { websocket: true }, (connection, req) => {
        const clientId = uuidv4();
        const client: ClientConnection = {
          id: clientId,
          socket: connection.socket,
          subscriptions: new Set(),
          lastActivity: Date.now(),
          isAuthenticated: false
        };

        this.clients.set(clientId, client);
        this.handleConnection(client);

        // Handle client disconnect
        connection.socket.on('close', () => {
          this.handleDisconnection(clientId);
        });

        // Handle client messages
        connection.socket.on('message', (data) => {
          this.handleMessage(clientId, data);
        });

        // Handle client errors
        connection.socket.on('error', (error) => {
          this.handleError(clientId, error);
        });
      });
    });
  }

  /**
   * Handle new client connection
   */
  private handleConnection(client: ClientConnection): void {
    console.log(`Analytics WebSocket client connected: ${client.id}`);

    // Send welcome message
    this.sendMessage(client, {
      type: WebSocketMessageType.SYSTEM_STATUS,
      data: {
        status: 'connected',
        clientId: client.id,
        timestamp: Date.now()
      },
      timestamp: Date.now(),
      id: uuidv4()
    });

    this.emit('client_connected', client);
  }

  /**
   * Handle client disconnection
   */
  private handleDisconnection(clientId: string): void {
    const client = this.clients.get(clientId);
    if (client) {
      console.log(`Analytics WebSocket client disconnected: ${clientId}`);

      // Remove from all topic subscriptions
      client.subscriptions.forEach(topic => {
        this.unsubscribeFromTopic(clientId, topic);
      });

      this.clients.delete(clientId);
      this.emit('client_disconnected', client);
    }
  }

  /**
   * Handle incoming message from client
   */
  private handleMessage(clientId: string, data: Buffer): void {
    const client = this.clients.get(clientId);
    if (!client) return;

    client.lastActivity = Date.now();

    try {
      const message: WebSocketMessage = JSON.parse(data.toString());

      switch (message.type) {
        case WebSocketMessageType.SUBSCRIPTION:
          this.handleSubscription(clientId, message.data);
          break;

        case WebSocketMessageType.UNSUBSCRIPTION:
          this.handleUnsubscription(clientId, message.data);
          break;

        case WebSocketMessageType.HEARTBEAT:
          this.handleHeartbeat(clientId);
          break;

        default:
          console.warn(`Unknown message type from client ${clientId}: ${message.type}`);
      }
    } catch (error) {
      console.error(`Failed to parse message from client ${clientId}:`, error);
      this.sendError(client, 'Invalid message format');
    }
  }

  /**
   * Handle client error
   */
  private handleError(clientId: string, error: Error): void {
    console.error(`WebSocket error for client ${clientId}:`, error);
    this.emit('client_error', { clientId, error });
  }

  /**
   * Handle subscription request
   */
  private handleSubscription(clientId: string, subscriptionData: any): void {
    const client = this.clients.get(clientId);
    if (!client) return;

    const { topic, filters, auth } = subscriptionData;

    // Handle authentication
    if (auth) {
      if (this.authenticateClient(client, auth)) {
        client.isAuthenticated = true;
        client.userId = auth.userId;
        client.organizationId = auth.organizationId;

        this.sendMessage(client, {
          type: WebSocketMessageType.SYSTEM_STATUS,
          data: { status: 'authenticated' },
          timestamp: Date.now(),
          id: uuidv4()
        });
      } else {
        this.sendError(client, 'Authentication failed');
      }
      return;
    }

    if (!topic) {
      this.sendError(client, 'Topic is required for subscription');
      return;
    }

    // Add client to topic subscription
    this.subscribeToTopic(clientId, topic, filters);

    console.log(`Client ${clientId} subscribed to topic: ${topic}`);
  }

  /**
   * Handle unsubscription request
   */
  private handleUnsubscription(clientId: string, data: any): void {
    const { topic } = data;
    if (topic) {
      this.unsubscribeFromTopic(clientId, topic);
      console.log(`Client ${clientId} unsubscribed from topic: ${topic}`);
    }
  }

  /**
   * Handle heartbeat
   */
  private handleHeartbeat(clientId: string): void {
    const client = this.clients.get(clientId);
    if (client) {
      this.sendMessage(client, {
        type: WebSocketMessageType.HEARTBEAT,
        data: { timestamp: Date.now() },
        timestamp: Date.now(),
        id: uuidv4()
      });
    }
  }

  /**
   * Subscribe client to topic
   */
  private subscribeToTopic(clientId: string, topic: string, filters?: any): void {
    const client = this.clients.get(clientId);
    if (!client) return;

    client.subscriptions.add(topic);

    if (!this.topicSubscriptions.has(topic)) {
      this.topicSubscriptions.set(topic, new Set());
    }

    this.topicSubscriptions.get(topic)!.add(clientId);

    // Send initial data for the topic
    this.sendTopicData(clientId, topic, filters);
  }

  /**
   * Unsubscribe client from topic
   */
  private unsubscribeFromTopic(clientId: string, topic: string): void {
    const client = this.clients.get(clientId);
    if (client) {
      client.subscriptions.delete(topic);
    }

    const topicClients = this.topicSubscriptions.get(topic);
    if (topicClients) {
      topicClients.delete(clientId);
      if (topicClients.size === 0) {
        this.topicSubscriptions.delete(topic);
      }
    }
  }

  /**
   * Send initial data for a topic
   */
  private async sendTopicData(clientId: string, topic: string, filters?: any): Promise<void> {
    const client = this.clients.get(clientId);
    if (!client) return;

    try {
      let data: any = null;

      switch (topic) {
        case 'dashboard':
          data = this.analyticsDashboard.getAnalyticsDashboardData();
          break;

        case 'cost_alerts':
          data = this.costTracker.getActiveAlerts();
          break;

        case 'recommendations':
          data = this.costTracker.getEfficiencyRecommendations(
            client.userId, 
            client.organizationId
          );
          break;

        case 'user_activity':
          data = this.analyticsCollector.getCurrentSummary();
          break;

        default:
          console.warn(`Unknown topic: ${topic}`);
          return;
      }

      if (data) {
        this.sendMessage(client, {
          type: WebSocketMessageType.ANALYTICS_UPDATE,
          data: { topic, data },
          timestamp: Date.now(),
          id: uuidv4()
        });
      }
    } catch (error) {
      console.error(`Failed to send topic data for ${topic}:`, error);
      this.sendError(client, `Failed to load data for topic: ${topic}`);
    }
  }

  /**
   * Broadcast message to all clients subscribed to a topic
   */
  private broadcastToTopic(topic: string, message: WebSocketMessage): void {
    const topicClients = this.topicSubscriptions.get(topic);
    if (!topicClients) return;

    topicClients.forEach(clientId => {
      const client = this.clients.get(clientId);
      if (client) {
        this.sendMessage(client, message);
      }
    });
  }

  /**
   * Send message to specific client
   */
  private sendMessage(client: ClientConnection, message: WebSocketMessage): void {
    if (client.socket.readyState === WebSocket.OPEN) {
      try {
        client.socket.send(JSON.stringify(message));
      } catch (error) {
        console.error(`Failed to send message to client ${client.id}:`, error);
      }
    }
  }

  /**
   * Send error message to client
   */
  private sendError(client: ClientConnection, errorMessage: string): void {
    this.sendMessage(client, {
      type: WebSocketMessageType.ERROR,
      data: { error: errorMessage },
      timestamp: Date.now(),
      id: uuidv4()
    });
  }

  /**
   * Authenticate client
   */
  private authenticateClient(client: ClientConnection, auth: any): boolean {
    // Simple authentication check
    // In production, this would validate against a proper auth system
    return auth.apiKey && auth.apiKey.length > 0;
  }

  /**
   * Setup event listeners for analytics events
   */
  private setupEventListeners(): void {
    // Analytics collector events
    this.analyticsCollector.on('event_recorded', (event) => {
      this.broadcastToTopic('user_activity', {
        type: WebSocketMessageType.USER_ACTIVITY,
        data: event,
        timestamp: Date.now(),
        id: uuidv4()
      });
    });

    // Analytics dashboard events
    this.analyticsDashboard.on('dashboard_updated', (data) => {
      this.broadcastToTopic('dashboard', {
        type: WebSocketMessageType.ANALYTICS_UPDATE,
        data: { topic: 'dashboard', data },
        timestamp: Date.now(),
        id: uuidv4()
      });
    });

    // Cost tracker events
    this.costTracker.on('budget_alert', (alert) => {
      this.broadcastToTopic('cost_alerts', {
        type: WebSocketMessageType.BUDGET_ALERT,
        data: alert,
        timestamp: Date.now(),
        id: uuidv4()
      });
    });

    this.costTracker.on('cost_calculated', (costData) => {
      this.broadcastToTopic('dashboard', {
        type: WebSocketMessageType.PERFORMANCE_METRIC,
        data: { metric: 'cost', value: costData.totalCost },
        timestamp: Date.now(),
        id: uuidv4()
      });
    });
  }

  /**
   * Start heartbeat to keep connections alive
   */
  private startHeartbeat(): void {
    this.heartbeatInterval = setInterval(() => {
      this.clients.forEach(client => {
        if (client.socket.readyState === WebSocket.OPEN) {
          this.sendMessage(client, {
            type: WebSocketMessageType.HEARTBEAT,
            data: { timestamp: Date.now() },
            timestamp: Date.now(),
            id: uuidv4()
          });
        }
      });
    }, 30000); // Every 30 seconds
  }

  /**
   * Start cleanup routine for dead connections
   */
  private startCleanup(): void {
    this.cleanupInterval = setInterval(() => {
      const now = Date.now();
      const timeout = 5 * 60 * 1000; // 5 minutes

      this.clients.forEach((client, clientId) => {
        if (now - client.lastActivity > timeout || client.socket.readyState !== WebSocket.OPEN) {
          console.log(`Cleaning up inactive client: ${clientId}`);
          this.handleDisconnection(clientId);
        }
      });
    }, 60000); // Every minute
  }

  /**
   * Stop the WebSocket server
   */
  stop(): void {
    if (this.heartbeatInterval) {
      clearInterval(this.heartbeatInterval);
      this.heartbeatInterval = null;
    }

    if (this.cleanupInterval) {
      clearInterval(this.cleanupInterval);
      this.cleanupInterval = null;
    }

    // Close all client connections
    this.clients.forEach(client => {
      if (client.socket.readyState === WebSocket.OPEN) {
        client.socket.close();
      }
    });

    this.clients.clear();
    this.topicSubscriptions.clear();
  }

  /**
   * Get server statistics
   */
  getStats(): {
    totalClients: number;
    authenticatedClients: number;
    totalSubscriptions: number;
    topicCounts: { [topic: string]: number };
  } {
    const authenticatedClients = Array.from(this.clients.values()).filter(c => c.isAuthenticated).length;
    const totalSubscriptions = Array.from(this.clients.values()).reduce((sum, client) => sum + client.subscriptions.size, 0);

    const topicCounts: { [topic: string]: number } = {};
    this.topicSubscriptions.forEach((clients, topic) => {
      topicCounts[topic] = clients.size;
    });

    return {
      totalClients: this.clients.size,
      authenticatedClients,
      totalSubscriptions,
      topicCounts
    };
  }
}

import { EventEmitter } from 'events';
import { v4 as uuidv4 } from 'uuid';

// Conflict types and resolution strategies
export enum ConflictType {
  NODE_POSITION = 'node_position',
  NODE_PROPERTIES = 'node_properties',
  NODE_CREATION = 'node_creation',
  NODE_DELETION = 'node_deletion',
  EDGE_CREATION = 'edge_creation',
  EDGE_DELETION = 'edge_deletion',
  EDGE_PROPERTIES = 'edge_properties'
}

export enum ResolutionStrategy {
  LAST_WRITER_WINS = 'last_writer_wins',
  FIRST_WRITER_WINS = 'first_writer_wins',
  MERGE_PROPERTIES = 'merge_properties',
  USER_RESOLUTION = 'user_resolution',
  SEMANTIC_MERGE = 'semantic_merge',
  POSITIONAL_OFFSET = 'positional_offset'
}

export interface ConflictOperation {
  id: string;
  type: ConflictType;
  nodeId?: string;
  edgeId?: string;
  property?: string;
  oldValue: any;
  newValue: any;
  userId: string;
  timestamp: number;
  documentId: string;
}

export interface Conflict {
  id: string;
  type: ConflictType;
  nodeId?: string;
  edgeId?: string;
  property?: string;
  operations: ConflictOperation[];
  detectedAt: number;
  documentId: string;
  status: 'pending' | 'resolved' | 'escalated';
  resolutionStrategy?: ResolutionStrategy;
  resolvedBy?: string;
  resolvedAt?: number;
  autoResolved: boolean;
  description: string;
}

export interface ResolutionResult {
  conflict: Conflict;
  resolvedValue: any;
  operations: ConflictOperation[];
  requiresUserInput: boolean;
  metadata?: {
    mergedFields?: string[];
    discardedOperations?: string[];
    offsetApplied?: { x: number; y: number };
  };
}

export interface ConflictResolverConfig {
  defaultStrategy: ResolutionStrategy;
  autoResolveThreshold: number; // ms
  maxConflictAge: number; // ms
  positionConflictThreshold: number; // pixels
  enableSemanticMerge: boolean;
  preserveConflictHistory: boolean;
  conflictHistoryRetention: number; // ms
}

export class ConflictResolver extends EventEmitter {
  private conflicts: Map<string, Conflict> = new Map();
  private operationHistory: Map<string, ConflictOperation[]> = new Map(); // nodeId/edgeId -> operations
  private config: ConflictResolverConfig;
  private cleanupInterval: NodeJS.Timeout | null = null;

  constructor(config: ConflictResolverConfig) {
    super();
    this.config = config;
    this.startCleanup();
  }

  /**
   * Process an incoming operation and detect conflicts
   */
  processOperation(operation: ConflictOperation): ResolutionResult | null {
    const key = this.getOperationKey(operation);

    // Get existing operations for this entity
    const existingOps = this.operationHistory.get(key) || [];

    // Check for conflicts
    const conflictingOps = this.findConflictingOperations(operation, existingOps);

    if (conflictingOps.length === 0) {
      // No conflict, just store the operation
      this.storeOperation(operation);
      return null;
    }

    // Create or update conflict
    const conflict = this.createOrUpdateConflict(operation, conflictingOps);

    // Attempt automatic resolution
    const resolution = this.attemptAutoResolution(conflict);

    if (resolution.requiresUserInput) {
      this.emit('conflict_detected', conflict);
    } else {
      this.emit('conflict_auto_resolved', resolution);
    }

    return resolution;
  }

  /**
   * Manually resolve a conflict
   */
  resolveConflict(
    conflictId: string, 
    strategy: ResolutionStrategy, 
    userSelection?: any,
    userId?: string
  ): ResolutionResult | null {
    const conflict = this.conflicts.get(conflictId);
    if (!conflict) {
      return null;
    }

    const resolution = this.resolveConflictWithStrategy(conflict, strategy, userSelection);

    // Update conflict status
    conflict.status = 'resolved';
    conflict.resolutionStrategy = strategy;
    conflict.resolvedBy = userId;
    conflict.resolvedAt = Date.now();
    conflict.autoResolved = false;

    this.emit('conflict_resolved', resolution);

    // Store in history if configured
    if (this.config.preserveConflictHistory) {
      // Keep conflict in history
    } else {
      this.conflicts.delete(conflictId);
    }

    return resolution;
  }

  /**
   * Get all pending conflicts for a document
   */
  getPendingConflicts(documentId: string): Conflict[] {
    return Array.from(this.conflicts.values())
      .filter(conflict => conflict.documentId === documentId && conflict.status === 'pending');
  }

  /**
   * Get conflict by ID
   */
  getConflict(conflictId: string): Conflict | null {
    return this.conflicts.get(conflictId) || null;
  }

  /**
   * Clear all conflicts for a document
   */
  clearDocumentConflicts(documentId: string): void {
    for (const [id, conflict] of this.conflicts) {
      if (conflict.documentId === documentId) {
        this.conflicts.delete(id);
      }
    }
  }

  /**
   * Get conflict statistics
   */
  getConflictStats(documentId?: string): {
    total: number;
    pending: number;
    resolved: number;
    escalated: number;
    autoResolved: number;
    avgResolutionTime: number;
  } {
    const conflicts = documentId 
      ? Array.from(this.conflicts.values()).filter(c => c.documentId === documentId)
      : Array.from(this.conflicts.values());

    const pending = conflicts.filter(c => c.status === 'pending').length;
    const resolved = conflicts.filter(c => c.status === 'resolved').length;
    const escalated = conflicts.filter(c => c.status === 'escalated').length;
    const autoResolved = conflicts.filter(c => c.autoResolved).length;

    const resolvedConflicts = conflicts.filter(c => c.status === 'resolved' && c.resolvedAt);
    const avgResolutionTime = resolvedConflicts.length > 0
      ? resolvedConflicts.reduce((sum, c) => sum + (c.resolvedAt! - c.detectedAt), 0) / resolvedConflicts.length
      : 0;

    return {
      total: conflicts.length,
      pending,
      resolved,
      escalated,
      autoResolved,
      avgResolutionTime
    };
  }

  /**
   * Clean up resources
   */
  cleanup(): void {
    if (this.cleanupInterval) {
      clearInterval(this.cleanupInterval);
    }
    this.conflicts.clear();
    this.operationHistory.clear();
  }

  /**
   * Find operations that conflict with the given operation
   */
  private findConflictingOperations(
    operation: ConflictOperation, 
    existingOps: ConflictOperation[]
  ): ConflictOperation[] {
    const conflicts: ConflictOperation[] = [];
    const operationTime = operation.timestamp;

    for (const existingOp of existingOps) {
      // Check if operations are within conflict threshold
      const timeDiff = Math.abs(operationTime - existingOp.timestamp);
      if (timeDiff > this.config.autoResolveThreshold) {
        continue;
      }

      // Different users
      if (existingOp.userId === operation.userId) {
        continue;
      }

      // Check for specific conflict types
      if (this.isConflicting(operation, existingOp)) {
        conflicts.push(existingOp);
      }
    }

    return conflicts;
  }

  /**
   * Check if two operations conflict
   */
  private isConflicting(op1: ConflictOperation, op2: ConflictOperation): boolean {
    if (op1.type !== op2.type) {
      return false;
    }

    switch (op1.type) {
      case ConflictType.NODE_POSITION:
        return this.isPositionConflict(op1, op2);

      case ConflictType.NODE_PROPERTIES:
      case ConflictType.EDGE_PROPERTIES:
        return op1.property === op2.property;

      case ConflictType.NODE_CREATION:
      case ConflictType.NODE_DELETION:
        return op1.nodeId === op2.nodeId;

      case ConflictType.EDGE_CREATION:
      case ConflictType.EDGE_DELETION:
        return op1.edgeId === op2.edgeId;

      default:
        return false;
    }
  }

  /**
   * Check if position operations conflict
   */
  private isPositionConflict(op1: ConflictOperation, op2: ConflictOperation): boolean {
    if (op1.nodeId !== op2.nodeId) {
      return false;
    }

    const pos1 = op1.newValue;
    const pos2 = op2.newValue;

    if (!pos1 || !pos2 || typeof pos1.x !== 'number' || typeof pos1.y !== 'number') {
      return false;
    }

    const distance = Math.sqrt(
      Math.pow(pos1.x - pos2.x, 2) + Math.pow(pos1.y - pos2.y, 2)
    );

    return distance < this.config.positionConflictThreshold;
  }

  /**
   * Create or update a conflict
   */
  private createOrUpdateConflict(
    operation: ConflictOperation, 
    conflictingOps: ConflictOperation[]
  ): Conflict {
    // Check if there's an existing conflict for this entity
    const existingConflict = this.findExistingConflict(operation);

    if (existingConflict) {
      // Add operation to existing conflict
      existingConflict.operations.push(operation);
      return existingConflict;
    }

    // Create new conflict
    const conflict: Conflict = {
      id: uuidv4(),
      type: operation.type,
      nodeId: operation.nodeId,
      edgeId: operation.edgeId,
      property: operation.property,
      operations: [operation, ...conflictingOps],
      detectedAt: Date.now(),
      documentId: operation.documentId,
      status: 'pending',
      autoResolved: false,
      description: this.generateConflictDescription(operation, conflictingOps)
    };

    this.conflicts.set(conflict.id, conflict);
    return conflict;
  }

  /**
   * Find existing conflict for an operation
   */
  private findExistingConflict(operation: ConflictOperation): Conflict | null {
    for (const conflict of this.conflicts.values()) {
      if (conflict.status !== 'pending') continue;

      if (conflict.type === operation.type &&
          conflict.nodeId === operation.nodeId &&
          conflict.edgeId === operation.edgeId &&
          conflict.property === operation.property) {
        return conflict;
      }
    }
    return null;
  }

  /**
   * Attempt automatic conflict resolution
   */
  private attemptAutoResolution(conflict: Conflict): ResolutionResult {
    // Use default strategy for auto-resolution
    return this.resolveConflictWithStrategy(conflict, this.config.defaultStrategy);
  }

  /**
   * Resolve conflict using specified strategy
   */
  private resolveConflictWithStrategy(
    conflict: Conflict, 
    strategy: ResolutionStrategy, 
    userSelection?: any
  ): ResolutionResult {
    switch (strategy) {
      case ResolutionStrategy.LAST_WRITER_WINS:
        return this.resolveLastWriterWins(conflict);

      case ResolutionStrategy.FIRST_WRITER_WINS:
        return this.resolveFirstWriterWins(conflict);

      case ResolutionStrategy.MERGE_PROPERTIES:
        return this.resolveMergeProperties(conflict);

      case ResolutionStrategy.POSITIONAL_OFFSET:
        return this.resolvePositionalOffset(conflict);

      case ResolutionStrategy.SEMANTIC_MERGE:
        return this.resolveSemanticMerge(conflict);

      case ResolutionStrategy.USER_RESOLUTION:
        return this.resolveUserSelection(conflict, userSelection);

      default:
        return this.resolveLastWriterWins(conflict);
    }
  }

  /**
   * Resolve using last writer wins strategy
   */
  private resolveLastWriterWins(conflict: Conflict): ResolutionResult {
    const latestOp = conflict.operations.reduce((latest, op) => 
      op.timestamp > latest.timestamp ? op : latest
    );

    return {
      conflict,
      resolvedValue: latestOp.newValue,
      operations: [latestOp],
      requiresUserInput: false,
      metadata: {
        discardedOperations: conflict.operations
          .filter(op => op.id !== latestOp.id)
          .map(op => op.id)
      }
    };
  }

  /**
   * Resolve using first writer wins strategy
   */
  private resolveFirstWriterWins(conflict: Conflict): ResolutionResult {
    const earliestOp = conflict.operations.reduce((earliest, op) => 
      op.timestamp < earliest.timestamp ? op : earliest
    );

    return {
      conflict,
      resolvedValue: earliestOp.newValue,
      operations: [earliestOp],
      requiresUserInput: false,
      metadata: {
        discardedOperations: conflict.operations
          .filter(op => op.id !== earliestOp.id)
          .map(op => op.id)
      }
    };
  }

  /**
   * Resolve by merging properties
   */
  private resolveMergeProperties(conflict: Conflict): ResolutionResult {
    if (conflict.type !== ConflictType.NODE_PROPERTIES && 
        conflict.type !== ConflictType.EDGE_PROPERTIES) {
      return this.resolveLastWriterWins(conflict);
    }

    const mergedValue = {};
    const mergedFields: string[] = [];

    // Merge all property changes
    for (const op of conflict.operations) {
      if (typeof op.newValue === 'object' && op.newValue !== null) {
        Object.assign(mergedValue, op.newValue);
        mergedFields.push(...Object.keys(op.newValue));
      }
    }

    return {
      conflict,
      resolvedValue: mergedValue,
      operations: conflict.operations,
      requiresUserInput: false,
      metadata: { mergedFields: [...new Set(mergedFields)] }
    };
  }

  /**
   * Resolve position conflicts with offset
   */
  private resolvePositionalOffset(conflict: Conflict): ResolutionResult {
    if (conflict.type !== ConflictType.NODE_POSITION) {
      return this.resolveLastWriterWins(conflict);
    }

    const operations = conflict.operations.sort((a, b) => a.timestamp - b.timestamp);
    const baseOp = operations[0];
    const offsetOps = operations.slice(1);

    const resolvedPositions = offsetOps.map((op, index) => {
      const offset = (index + 1) * 20; // 20px offset per conflicting operation
      return {
        ...op,
        newValue: {
          x: op.newValue.x + offset,
          y: op.newValue.y + offset
        }
      };
    });

    return {
      conflict,
      resolvedValue: baseOp.newValue,
      operations: [baseOp, ...resolvedPositions],
      requiresUserInput: false,
      metadata: { 
        offsetApplied: { x: 20, y: 20 }
      }
    };
  }

  /**
   * Resolve using semantic merge (placeholder for future AI-based resolution)
   */
  private resolveSemanticMerge(conflict: Conflict): ResolutionResult {
    // Placeholder for semantic merge - would use AI/ML for intelligent merging
    // For now, fall back to property merge or last writer wins

    if (conflict.type === ConflictType.NODE_PROPERTIES || 
        conflict.type === ConflictType.EDGE_PROPERTIES) {
      return this.resolveMergeProperties(conflict);
    }

    return this.resolveLastWriterWins(conflict);
  }

  /**
   * Resolve using user selection
   */
  private resolveUserSelection(conflict: Conflict, userSelection?: any): ResolutionResult {
    if (!userSelection) {
      return {
        conflict,
        resolvedValue: null,
        operations: [],
        requiresUserInput: true
      };
    }

    const selectedOp = conflict.operations.find(op => op.id === userSelection.operationId);
    if (!selectedOp) {
      return this.resolveLastWriterWins(conflict);
    }

    return {
      conflict,
      resolvedValue: userSelection.value || selectedOp.newValue,
      operations: [selectedOp],
      requiresUserInput: false,
      metadata: {
        discardedOperations: conflict.operations
          .filter(op => op.id !== selectedOp.id)
          .map(op => op.id)
      }
    };
  }

  /**
   * Store operation in history
   */
  private storeOperation(operation: ConflictOperation): void {
    const key = this.getOperationKey(operation);
    const existing = this.operationHistory.get(key) || [];
    existing.push(operation);

    // Keep only recent operations
    const cutoff = Date.now() - this.config.maxConflictAge;
    const filtered = existing.filter(op => op.timestamp > cutoff);

    this.operationHistory.set(key, filtered);
  }

  /**
   * Get key for operation storage
   */
  private getOperationKey(operation: ConflictOperation): string {
    if (operation.nodeId) {
      return `node:${operation.nodeId}`;
    }
    if (operation.edgeId) {
      return `edge:${operation.edgeId}`;
    }
    return `doc:${operation.documentId}`;
  }

  /**
   * Generate human-readable conflict description
   */
  private generateConflictDescription(
    operation: ConflictOperation, 
    conflictingOps: ConflictOperation[]
  ): string {
    const userCount = new Set([operation.userId, ...conflictingOps.map(op => op.userId)]).size;

    switch (operation.type) {
      case ConflictType.NODE_POSITION:
        return `${userCount} users moved the same node to different positions`;

      case ConflictType.NODE_PROPERTIES:
        return `${userCount} users changed properties of the same node`;

      case ConflictType.NODE_CREATION:
        return `${userCount} users created nodes at the same location`;

      case ConflictType.NODE_DELETION:
        return `${userCount} users tried to modify a deleted node`;

      case ConflictType.EDGE_CREATION:
        return `${userCount} users created conflicting edges`;

      case ConflictType.EDGE_DELETION:
        return `${userCount} users tried to modify a deleted edge`;

      case ConflictType.EDGE_PROPERTIES:
        return `${userCount} users changed properties of the same edge`;

      default:
        return `${userCount} users made conflicting changes`;
    }
  }

  /**
   * Start periodic cleanup of old conflicts and operations
   */
  private startCleanup(): void {
    this.cleanupInterval = setInterval(() => {
      this.performCleanup();
    }, 60000); // Clean up every minute
  }

  /**
   * Perform cleanup of old data
   */
  private performCleanup(): void {
    const cutoff = Date.now() - this.config.conflictHistoryRetention;

    // Clean up old conflicts
    for (const [id, conflict] of this.conflicts) {
      if (conflict.status === 'resolved' && conflict.resolvedAt && conflict.resolvedAt < cutoff) {
        this.conflicts.delete(id);
      }
    }

    // Clean up old operations
    for (const [key, operations] of this.operationHistory) {
      const filtered = operations.filter(op => op.timestamp > cutoff);
      if (filtered.length === 0) {
        this.operationHistory.delete(key);
      } else {
        this.operationHistory.set(key, filtered);
      }
    }
  }
}

import { EventEmitter } from 'events';
import { v4 as uuidv4 } from 'uuid';
import WebSocket from 'ws';
import jwt from 'jsonwebtoken';
import { 
  ConnectionInfo, 
  DocumentSession, 
  WSMessage, 
  WSServerConfig,
  HealthMetrics,
  AuthPayload
} from './types';

export class ConnectionManager extends EventEmitter {
  private connections: Map<string, WebSocket> = new Map();
  private connectionInfo: Map<string, ConnectionInfo> = new Map();
  private documentSessions: Map<string, DocumentSession> = new Map();
  private config: WSServerConfig;
  private heartbeatInterval: NodeJS.Timeout | null = null;
  private metricsInterval: NodeJS.Timeout | null = null;
  private metrics: HealthMetrics;
  private startTime: number;

  constructor(config: WSServerConfig) {
    super();
    this.config = config;
    this.startTime = Date.now();
    this.metrics = {
      totalConnections: 0,
      activeDocuments: 0,
      messagesPerSecond: 0,
      uptime: 0,
      memoryUsage: 0,
      lastUpdated: Date.now()
    };

    this.startHeartbeat();
    this.startMetricsCollection();
  }

  /**
   * Add a new WebSocket connection
   */
  addConnection(ws: WebSocket, request: any): string {
    const connectionId = uuidv4();

    // Extract basic info from request
    const userAgent = request.headers['user-agent'];
    const ipAddress = request.socket.remoteAddress;

    // Store connection
    this.connections.set(connectionId, ws);

    // Initialize connection info (authentication required)
    const connectionInfo: ConnectionInfo = {
      id: connectionId,
      userId: '', // Will be set during authentication
      documentId: '', // Will be set during authentication
      permissions: [],
      lastSeen: Date.now(),
      authenticated: false,
      userAgent,
      ipAddress
    };

    this.connectionInfo.set(connectionId, connectionInfo);

    // Set up WebSocket event handlers
    this.setupWebSocketHandlers(ws, connectionId);

    this.emit('connection_added', connectionId, connectionInfo);
    this.updateMetrics();

    return connectionId;
  }

  /**
   * Remove a connection
   */
  removeConnection(connectionId: string): void {
    const connectionInfo = this.connectionInfo.get(connectionId);

    if (connectionInfo) {
      // Remove from document session
      if (connectionInfo.documentId) {
        this.removeFromDocumentSession(connectionInfo.documentId, connectionId);
      }

      // Clean up connection
      this.connections.delete(connectionId);
      this.connectionInfo.delete(connectionId);

      this.emit('connection_removed', connectionId, connectionInfo);
      this.updateMetrics();
    }
  }

  /**
   * Authenticate a connection
   */
  async authenticateConnection(connectionId: string, authPayload: AuthPayload): Promise<boolean> {
    try {
      if (!this.config.enableAuthentication) {
        // Skip authentication if disabled
        return this.setConnectionAuthenticated(connectionId, 'anonymous', authPayload.documentId, ['read', 'write']);
      }

      if (!this.config.jwtSecret) {
        throw new Error('JWT secret not configured');
      }

      // Verify JWT token
      const decoded = jwt.verify(authPayload.token, this.config.jwtSecret) as any;

      if (!decoded.userId) {
        throw new Error('Invalid token: missing userId');
      }

      // Set authenticated connection info
      const permissions = authPayload.permissions || ['read', 'write'];
      return this.setConnectionAuthenticated(connectionId, decoded.userId, authPayload.documentId, permissions);

    } catch (error) {
      console.error('Authentication failed:', error);
      return false;
    }
  }

  /**
   * Set connection as authenticated
   */
  private setConnectionAuthenticated(connectionId: string, userId: string, documentId: string, permissions: string[]): boolean {
    const connectionInfo = this.connectionInfo.get(connectionId);

    if (!connectionInfo) {
      return false;
    }

    // Update connection info
    connectionInfo.userId = userId;
    connectionInfo.documentId = documentId;
    connectionInfo.permissions = permissions;
    connectionInfo.authenticated = true;
    connectionInfo.lastSeen = Date.now();

    // Add to document session
    this.addToDocumentSession(documentId, connectionId, connectionInfo);

    this.emit('connection_authenticated', connectionId, connectionInfo);
    return true;
  }

  /**
   * Broadcast message to all connections in a document
   */
  broadcastToDocument(documentId: string, message: WSMessage, excludeConnectionId?: string): void {
    const session = this.documentSessions.get(documentId);

    if (!session) {
      return;
    }

    const messageStr = JSON.stringify(message);

    for (const [connectionId, connectionInfo] of session.connections) {
      if (excludeConnectionId && connectionId === excludeConnectionId) {
        continue;
      }

      const ws = this.connections.get(connectionId);
      if (ws && ws.readyState === WebSocket.OPEN) {
        try {
          ws.send(messageStr);
        } catch (error) {
          console.error(`Failed to send message to connection ${connectionId}:`, error);
          this.removeConnection(connectionId);
        }
      }
    }
  }

  /**
   * Send message to specific connection
   */
  sendToConnection(connectionId: string, message: WSMessage): boolean {
    const ws = this.connections.get(connectionId);

    if (!ws || ws.readyState !== WebSocket.OPEN) {
      return false;
    }

    try {
      ws.send(JSON.stringify(message));
      return true;
    } catch (error) {
      console.error(`Failed to send message to connection ${connectionId}:`, error);
      this.removeConnection(connectionId);
      return false;
    }
  }

  /**
   * Get connection info
   */
  getConnectionInfo(connectionId: string): ConnectionInfo | undefined {
    return this.connectionInfo.get(connectionId);
  }

  /**
   * Get document session
   */
  getDocumentSession(documentId: string): DocumentSession | undefined {
    return this.documentSessions.get(documentId);
  }

  /**
   * Get all connections for a document
   */
  getDocumentConnections(documentId: string): ConnectionInfo[] {
    const session = this.documentSessions.get(documentId);
    return session ? Array.from(session.connections.values()) : [];
  }

  /**
   * Get health metrics
   */
  getHealthMetrics(): HealthMetrics {
    return { ...this.metrics };
  }

  /**
   * Check if connection has permission
   */
  hasPermission(connectionId: string, permission: string): boolean {
    const connectionInfo = this.connectionInfo.get(connectionId);
    return connectionInfo?.authenticated && connectionInfo.permissions.includes(permission) || false;
  }

  /**
   * Clean up resources
   */
  cleanup(): void {
    if (this.heartbeatInterval) {
      clearInterval(this.heartbeatInterval);
    }

    if (this.metricsInterval) {
      clearInterval(this.metricsInterval);
    }

    // Close all connections
    for (const ws of this.connections.values()) {
      ws.close();
    }

    this.connections.clear();
    this.connectionInfo.clear();
    this.documentSessions.clear();
  }

  /**
   * Set up WebSocket event handlers for a connection
   */
  private setupWebSocketHandlers(ws: WebSocket, connectionId: string): void {
    ws.on('close', () => {
      this.removeConnection(connectionId);
    });

    ws.on('error', (error) => {
      console.error(`WebSocket error for connection ${connectionId}:`, error);
      this.removeConnection(connectionId);
    });

    ws.on('pong', () => {
      // Update last seen time
      const connectionInfo = this.connectionInfo.get(connectionId);
      if (connectionInfo) {
        connectionInfo.lastSeen = Date.now();
      }
    });
  }

  /**
   * Add connection to document session
   */
  private addToDocumentSession(documentId: string, connectionId: string, connectionInfo: ConnectionInfo): void {
    let session = this.documentSessions.get(documentId);

    if (!session) {
      session = {
        documentId,
        connections: new Map(),
        lastActivity: Date.now(),
        version: 1
      };
      this.documentSessions.set(documentId, session);
    }

    session.connections.set(connectionId, connectionInfo);
    session.lastActivity = Date.now();

    this.emit('user_joined_document', documentId, connectionInfo);
  }

  /**
   * Remove connection from document session
   */
  private removeFromDocumentSession(documentId: string, connectionId: string): void {
    const session = this.documentSessions.get(documentId);

    if (!session) {
      return;
    }

    const connectionInfo = session.connections.get(connectionId);
    session.connections.delete(connectionId);

    // Clean up empty sessions
    if (session.connections.size === 0) {
      this.documentSessions.delete(documentId);
    } else {
      session.lastActivity = Date.now();
    }

    if (connectionInfo) {
      this.emit('user_left_document', documentId, connectionInfo);
    }
  }

  /**
   * Start heartbeat to detect dead connections
   */
  private startHeartbeat(): void {
    this.heartbeatInterval = setInterval(() => {
      const now = Date.now();
      const timeout = this.config.connectionTimeout;

      for (const [connectionId, connectionInfo] of this.connectionInfo) {
        const ws = this.connections.get(connectionId);

        if (!ws) {
          this.removeConnection(connectionId);
          continue;
        }

        // Check for timed out connections
        if (now - connectionInfo.lastSeen > timeout) {
          console.log(`Connection ${connectionId} timed out`);
          ws.close();
          continue;
        }

        // Send ping
        if (ws.readyState === WebSocket.OPEN) {
          try {
            ws.ping();
          } catch (error) {
            console.error(`Failed to ping connection ${connectionId}:`, error);
            this.removeConnection(connectionId);
          }
        }
      }
    }, this.config.heartbeatInterval);
  }

  /**
   * Start metrics collection
   */
  private startMetricsCollection(): void {
    this.metricsInterval = setInterval(() => {
      this.updateMetrics();
    }, 5000); // Update every 5 seconds
  }

  /**
   * Update health metrics
   */
  private updateMetrics(): void {
    this.metrics = {
      totalConnections: this.connections.size,
      activeDocuments: this.documentSessions.size,
      messagesPerSecond: 0, // TODO: Implement message rate tracking
      uptime: Date.now() - this.startTime,
      memoryUsage: process.memoryUsage().heapUsed,
      lastUpdated: Date.now()
    };
  }
}

import { EventEmitter } from 'events';
import { v4 as uuidv4 } from 'uuid';

// Enhanced presence data models
export interface UserPresenceData {
  userId: string;
  userName?: string;
  userAvatar?: string;
  connectionId: string;
  documentId: string;
  // Cursor and selection state
  cursor?: {
    x: number;
    y: number;
    nodeId?: string;
    viewportBounds?: {
      top: number;
      left: number;
      width: number;
      height: number;
      zoom: number;
    };
  };
  selection?: {
    nodeIds: string[];
    edgeIds: string[];
    selectionBox?: {
      x: number;
      y: number;
      width: number;
      height: number;
    };
  };
  // Activity state
  status: 'active' | 'idle' | 'away' | 'offline';
  lastSeen: number;
  lastActivity: number;
  currentTool?: string;
  // Awareness indicators
  isTyping?: boolean;
  focusedNodeId?: string;
  // Privacy settings
  shareLocation: boolean;
  shareSelection: boolean;
  shareActivity: boolean;
  // Session metadata
  sessionId: string;
  joinedAt: number;
  userAgent?: string;
  platform?: string;
}

export interface DocumentPresence {
  documentId: string;
  users: Map<string, UserPresenceData>;
  activeUsers: number;
  maxConcurrentUsers: number;
  lastActivity: number;
  createdAt: number;
}

export interface PresenceStats {
  totalUsers: number;
  activeUsers: number;
  idleUsers: number;
  awayUsers: number;
  documentsWithUsers: number;
  averageSessionDuration: number;
  peakConcurrentUsers: number;
  lastUpdated: number;
}

export interface PresenceConfig {
  idleTimeout: number; // Time before marking user as idle (ms)
  awayTimeout: number; // Time before marking user as away (ms)
  offlineTimeout: number; // Time before removing user presence (ms)
  cleanupInterval: number; // How often to clean up stale presence data (ms)
  maxUsersPerDocument: number;
  enableLocationSharing: boolean;
  enableActivityTracking: boolean;
  retainPresenceHistory: boolean;
  historyRetentionPeriod: number; // How long to keep presence history (ms)
}

export class PresenceManager extends EventEmitter {
  private documentPresence: Map<string, DocumentPresence> = new Map();
  private userSessions: Map<string, UserPresenceData> = new Map(); // connectionId -> presence
  private config: PresenceConfig;
  private cleanupInterval: NodeJS.Timeout | null = null;
  private stats: PresenceStats;

  constructor(config: PresenceConfig) {
    super();
    this.config = config;
    this.stats = {
      totalUsers: 0,
      activeUsers: 0,
      idleUsers: 0,
      awayUsers: 0,
      documentsWithUsers: 0,
      averageSessionDuration: 0,
      peakConcurrentUsers: 0,
      lastUpdated: Date.now()
    };

    this.startCleanup();
  }

  /**
   * Add user presence when they join a document
   */
  addUserPresence(
    connectionId: string,
    userId: string,
    documentId: string,
    metadata: Partial<UserPresenceData> = {}
  ): UserPresenceData {
    const now = Date.now();

    const presence: UserPresenceData = {
      userId,
      connectionId,
      documentId,
      status: 'active',
      lastSeen: now,
      lastActivity: now,
      sessionId: uuidv4(),
      joinedAt: now,
      shareLocation: this.config.enableLocationSharing,
      shareSelection: true,
      shareActivity: this.config.enableActivityTracking,
      ...metadata
    };

    // Add to user sessions
    this.userSessions.set(connectionId, presence);

    // Add to document presence
    let docPresence = this.documentPresence.get(documentId);
    if (!docPresence) {
      docPresence = {
        documentId,
        users: new Map(),
        activeUsers: 0,
        maxConcurrentUsers: 0,
        lastActivity: now,
        createdAt: now
      };
      this.documentPresence.set(documentId, docPresence);
    }

    docPresence.users.set(userId, presence);
    docPresence.activeUsers = docPresence.users.size;
    docPresence.maxConcurrentUsers = Math.max(docPresence.maxConcurrentUsers, docPresence.activeUsers);
    docPresence.lastActivity = now;

    this.updateStats();
    this.emit('user_joined', documentId, presence);

    return presence;
  }

  /**
   * Remove user presence when they leave
   */
  removeUserPresence(connectionId: string): UserPresenceData | null {
    const presence = this.userSessions.get(connectionId);
    if (!presence) {
      return null;
    }

    this.userSessions.delete(connectionId);

    const docPresence = this.documentPresence.get(presence.documentId);
    if (docPresence) {
      docPresence.users.delete(presence.userId);
      docPresence.activeUsers = docPresence.users.size;

      // Clean up empty document presence
      if (docPresence.users.size === 0) {
        this.documentPresence.delete(presence.documentId);
      } else {
        docPresence.lastActivity = Date.now();
      }
    }

    this.updateStats();
    this.emit('user_left', presence.documentId, presence);

    return presence;
  }

  /**
   * Update user presence data
   */
  updateUserPresence(
    connectionId: string,
    updates: Partial<UserPresenceData>
  ): UserPresenceData | null {
    const presence = this.userSessions.get(connectionId);
    if (!presence) {
      return null;
    }

    const now = Date.now();
    const wasActive = presence.status === 'active';

    // Update presence data
    Object.assign(presence, updates, {
      lastSeen: now,
      lastActivity: updates.cursor || updates.selection || updates.isTyping ? now : presence.lastActivity
    });

    // Update document presence
    const docPresence = this.documentPresence.get(presence.documentId);
    if (docPresence) {
      docPresence.users.set(presence.userId, presence);
      docPresence.lastActivity = now;
    }

    // Check for status changes
    const newStatus = this.calculateUserStatus(presence);
    if (newStatus !== presence.status) {
      presence.status = newStatus;
      this.emit('user_status_changed', presence.documentId, presence, presence.status);
    }

    this.updateStats();
    this.emit('user_updated', presence.documentId, presence);

    return presence;
  }

  /**
   * Update user cursor position
   */
  updateUserCursor(
    connectionId: string,
    cursor: UserPresenceData['cursor']
  ): UserPresenceData | null {
    return this.updateUserPresence(connectionId, { cursor });
  }

  /**
   * Update user selection
   */
  updateUserSelection(
    connectionId: string,
    selection: UserPresenceData['selection']
  ): UserPresenceData | null {
    return this.updateUserPresence(connectionId, { selection });
  }

  /**
   * Update user activity status
   */
  updateUserActivity(
    connectionId: string,
    activity: {
      currentTool?: string;
      isTyping?: boolean;
      focusedNodeId?: string;
    }
  ): UserPresenceData | null {
    return this.updateUserPresence(connectionId, activity);
  }

  /**
   * Get presence data for a specific user
   */
  getUserPresence(connectionId: string): UserPresenceData | null {
    return this.userSessions.get(connectionId) || null;
  }

  /**
   * Get all users in a document
   */
  getDocumentUsers(documentId: string): UserPresenceData[] {
    const docPresence = this.documentPresence.get(documentId);
    return docPresence ? Array.from(docPresence.users.values()) : [];
  }

  /**
   * Get document presence info
   */
  getDocumentPresence(documentId: string): DocumentPresence | null {
    return this.documentPresence.get(documentId) || null;
  }

  /**
   * Get users near a specific location
   */
  getUsersNearLocation(
    documentId: string,
    location: { x: number; y: number },
    radius: number = 100
  ): UserPresenceData[] {
    const users = this.getDocumentUsers(documentId);

    return users.filter(user => {
      if (!user.cursor || !user.shareLocation) {
        return false;
      }

      const distance = Math.sqrt(
        Math.pow(user.cursor.x - location.x, 2) + 
        Math.pow(user.cursor.y - location.y, 2)
      );

      return distance <= radius;
    });
  }

  /**
   * Get users with overlapping selections
   */
  getUsersWithOverlappingSelection(
    documentId: string,
    nodeIds: string[]
  ): UserPresenceData[] {
    const users = this.getDocumentUsers(documentId);

    return users.filter(user => {
      if (!user.selection || !user.shareSelection) {
        return false;
      }

      return user.selection.nodeIds.some(nodeId => nodeIds.includes(nodeId));
    });
  }

  /**
   * Get presence statistics
   */
  getPresenceStats(): PresenceStats {
    return { ...this.stats };
  }

  /**
   * Get active users across all documents
   */
  getAllActiveUsers(): UserPresenceData[] {
    return Array.from(this.userSessions.values()).filter(user => user.status === 'active');
  }

  /**
   * Check if document has reached user limit
   */
  isDocumentAtCapacity(documentId: string): boolean {
    const docPresence = this.documentPresence.get(documentId);
    return docPresence ? docPresence.activeUsers >= this.config.maxUsersPerDocument : false;
  }

  /**
   * Clean up stale presence data
   */
  cleanup(): void {
    if (this.cleanupInterval) {
      clearInterval(this.cleanupInterval);
    }

    // Clear all data
    this.documentPresence.clear();
    this.userSessions.clear();
  }

  /**
   * Calculate user status based on activity
   */
  private calculateUserStatus(presence: UserPresenceData): UserPresenceData['status'] {
    const now = Date.now();
    const timeSinceLastSeen = now - presence.lastSeen;
    const timeSinceLastActivity = now - presence.lastActivity;

    if (timeSinceLastSeen > this.config.offlineTimeout) {
      return 'offline';
    } else if (timeSinceLastActivity > this.config.awayTimeout) {
      return 'away';
    } else if (timeSinceLastActivity > this.config.idleTimeout) {
      return 'idle';
    } else {
      return 'active';
    }
  }

  /**
   * Start periodic cleanup of stale presence data
   */
  private startCleanup(): void {
    this.cleanupInterval = setInterval(() => {
      this.performCleanup();
    }, this.config.cleanupInterval);
  }

  /**
   * Perform cleanup of stale presence data
   */
  private performCleanup(): void {
    const now = Date.now();
    const toRemove: string[] = [];

    // Check for stale user sessions
    for (const [connectionId, presence] of this.userSessions) {
      const timeSinceLastSeen = now - presence.lastSeen;

      if (timeSinceLastSeen > this.config.offlineTimeout) {
        toRemove.push(connectionId);
      } else {
        // Update status based on activity
        const newStatus = this.calculateUserStatus(presence);
        if (newStatus !== presence.status) {
          presence.status = newStatus;
          this.emit('user_status_changed', presence.documentId, presence, newStatus);
        }
      }
    }

    // Remove stale sessions
    for (const connectionId of toRemove) {
      this.removeUserPresence(connectionId);
    }

    this.updateStats();
  }

  /**
   * Update presence statistics
   */
  private updateStats(): void {
    const allUsers = Array.from(this.userSessions.values());
    const now = Date.now();

    this.stats = {
      totalUsers: allUsers.length,
      activeUsers: allUsers.filter(u => u.status === 'active').length,
      idleUsers: allUsers.filter(u => u.status === 'idle').length,
      awayUsers: allUsers.filter(u => u.status === 'away').length,
      documentsWithUsers: this.documentPresence.size,
      averageSessionDuration: this.calculateAverageSessionDuration(allUsers, now),
      peakConcurrentUsers: Math.max(this.stats.peakConcurrentUsers, allUsers.length),
      lastUpdated: now
    };
  }

  /**
   * Calculate average session duration
   */
  private calculateAverageSessionDuration(users: UserPresenceData[], now: number): number {
    if (users.length === 0) {
      return 0;
    }

    const totalDuration = users.reduce((sum, user) => {
      return sum + (now - user.joinedAt);
    }, 0);

    return totalDuration / users.length;
  }
}

import { EventEmitter } from 'events';
import { v4 as uuidv4 } from 'uuid';

// Document state and synchronization types
export interface DocumentState {
  documentId: string;
  version: number;
  lastModified: number;
  checksum: string;
  nodes: Map<string, any>;
  edges: Map<string, any>;
  metadata: any;
}

export interface StateUpdate {
  id: string;
  documentId: string;
  version: number;
  timestamp: number;
  userId: string;
  operations: StateOperation[];
  checksum: string;
}

export interface StateOperation {
  id: string;
  type: 'create' | 'update' | 'delete';
  target: 'node' | 'edge' | 'metadata';
  targetId: string;
  data: any;
  oldData?: any;
  timestamp: number;
}

export interface StateDelta {
  fromVersion: number;
  toVersion: number;
  operations: StateOperation[];
  timestamp: number;
  checksum: string;
}

export interface SyncRequest {
  documentId: string;
  clientVersion: number;
  requestedVersion?: number;
  fullSync: boolean;
  checksum?: string;
}

export interface SyncResponse {
  documentId: string;
  currentVersion: number;
  clientVersion: number;
  syncType: 'full' | 'delta' | 'up_to_date';
  state?: DocumentState;
  delta?: StateDelta;
  operations?: StateOperation[];
  conflicts?: string[]; // Conflict IDs
  checksum: string;
}

export interface SyncManagerConfig {
  maxVersionHistory: number;
  deltaCompressionThreshold: number;
  checksumValidation: boolean;
  conflictDetection: boolean;
  autoMerge: boolean;
  syncInterval: number; // ms
  maxSyncBatchSize: number;
}

export class SynchronizationManager extends EventEmitter {
  private documentStates: Map<string, DocumentState> = new Map();
  private versionHistory: Map<string, StateUpdate[]> = new Map(); // documentId -> updates
  private pendingOperations: Map<string, StateOperation[]> = new Map(); // documentId -> operations
  private config: SyncManagerConfig;
  private syncInterval: NodeJS.Timeout | null = null;

  constructor(config: SyncManagerConfig) {
    super();
    this.config = config;
    this.startSyncProcess();
  }

  /**
   * Initialize or get document state
   */
  initializeDocument(documentId: string, initialState?: any): DocumentState {
    let state = this.documentStates.get(documentId);

    if (!state) {
      state = {
        documentId,
        version: 1,
        lastModified: Date.now(),
        checksum: '',
        nodes: new Map(),
        edges: new Map(),
        metadata: initialState?.metadata || {}
      };

      // Load initial data if provided
      if (initialState?.nodes) {
        for (const [id, nodeData] of Object.entries(initialState.nodes)) {
          state.nodes.set(id, nodeData);
        }
      }

      if (initialState?.edges) {
        for (const [id, edgeData] of Object.entries(initialState.edges)) {
          state.edges.set(id, edgeData);
        }
      }

      state.checksum = this.calculateChecksum(state);
      this.documentStates.set(documentId, state);
      this.versionHistory.set(documentId, []);
    }

    return state;
  }

  /**
   * Apply state update to document
   */
  applyStateUpdate(update: StateUpdate): SyncResponse {
    const state = this.documentStates.get(update.documentId);
    if (!state) {
      throw new Error(`Document ${update.documentId} not found`);
    }

    // Validate version sequence
    if (update.version !== state.version + 1) {
      return this.handleVersionConflict(update, state);
    }

    // Apply operations
    const conflicts: string[] = [];
    for (const operation of update.operations) {
      try {
        this.applyOperation(state, operation);
      } catch (error) {
        console.error(`Failed to apply operation ${operation.id}:`, error);
        conflicts.push(operation.id);
      }
    }

    // Update state
    state.version = update.version;
    state.lastModified = update.timestamp;
    state.checksum = this.calculateChecksum(state);

    // Store in history
    this.addToHistory(update);

    // Emit update event
    this.emit('state_updated', {
      documentId: update.documentId,
      version: state.version,
      operations: update.operations,
      conflicts
    });

    return {
      documentId: update.documentId,
      currentVersion: state.version,
      clientVersion: update.version,
      syncType: 'up_to_date',
      conflicts,
      checksum: state.checksum
    };
  }

  /**
   * Handle sync request from client
   */
  handleSyncRequest(request: SyncRequest): SyncResponse {
    const state = this.documentStates.get(request.documentId);
    if (!state) {
      throw new Error(`Document ${request.documentId} not found`);
    }

    // Check if client is up to date
    if (request.clientVersion === state.version) {
      return {
        documentId: request.documentId,
        currentVersion: state.version,
        clientVersion: request.clientVersion,
        syncType: 'up_to_date',
        checksum: state.checksum
      };
    }

    // Handle full sync request
    if (request.fullSync || request.clientVersion === 0) {
      return {
        documentId: request.documentId,
        currentVersion: state.version,
        clientVersion: request.clientVersion,
        syncType: 'full',
        state: this.cloneState(state),
        checksum: state.checksum
      };
    }

    // Handle delta sync
    if (request.clientVersion < state.version) {
      const delta = this.generateDelta(request.documentId, request.clientVersion, state.version);

      if (delta) {
        return {
          documentId: request.documentId,
          currentVersion: state.version,
          clientVersion: request.clientVersion,
          syncType: 'delta',
          delta,
          checksum: state.checksum
        };
      }
    }

    // Fall back to full sync if delta not available
    return {
      documentId: request.documentId,
      currentVersion: state.version,
      clientVersion: request.clientVersion,
      syncType: 'full',
      state: this.cloneState(state),
      checksum: state.checksum
    };
  }

  /**
   * Generate operations for state changes
   */
  generateOperations(
    documentId: string,
    changes: {
      nodes?: { [id: string]: any };
      edges?: { [id: string]: any };
      metadata?: any;
    },
    userId: string
  ): StateOperation[] {
    const operations: StateOperation[] = [];
    const state = this.documentStates.get(documentId);

    if (!state) {
      return operations;
    }

    // Handle node changes
    if (changes.nodes) {
      for (const [nodeId, nodeData] of Object.entries(changes.nodes)) {
        const existingNode = state.nodes.get(nodeId);

        if (!existingNode && nodeData) {
          // Create operation
          operations.push({
            id: uuidv4(),
            type: 'create',
            target: 'node',
            targetId: nodeId,
            data: nodeData,
            timestamp: Date.now()
          });
        } else if (existingNode && !nodeData) {
          // Delete operation
          operations.push({
            id: uuidv4(),
            type: 'delete',
            target: 'node',
            targetId: nodeId,
            data: null,
            oldData: existingNode,
            timestamp: Date.now()
          });
        } else if (existingNode && nodeData) {
          // Update operation
          operations.push({
            id: uuidv4(),
            type: 'update',
            target: 'node',
            targetId: nodeId,
            data: nodeData,
            oldData: existingNode,
            timestamp: Date.now()
          });
        }
      }
    }

    // Handle edge changes
    if (changes.edges) {
      for (const [edgeId, edgeData] of Object.entries(changes.edges)) {
        const existingEdge = state.edges.get(edgeId);

        if (!existingEdge && edgeData) {
          operations.push({
            id: uuidv4(),
            type: 'create',
            target: 'edge',
            targetId: edgeId,
            data: edgeData,
            timestamp: Date.now()
          });
        } else if (existingEdge && !edgeData) {
          operations.push({
            id: uuidv4(),
            type: 'delete',
            target: 'edge',
            targetId: edgeId,
            data: null,
            oldData: existingEdge,
            timestamp: Date.now()
          });
        } else if (existingEdge && edgeData) {
          operations.push({
            id: uuidv4(),
            type: 'update',
            target: 'edge',
            targetId: edgeId,
            data: edgeData,
            oldData: existingEdge,
            timestamp: Date.now()
          });
        }
      }
    }

    // Handle metadata changes
    if (changes.metadata) {
      operations.push({
        id: uuidv4(),
        type: 'update',
        target: 'metadata',
        targetId: 'root',
        data: changes.metadata,
        oldData: state.metadata,
        timestamp: Date.now()
      });
    }

    return operations;
  }

  /**
   * Create state update
   */
  createStateUpdate(
    documentId: string,
    operations: StateOperation[],
    userId: string
  ): StateUpdate {
    const state = this.documentStates.get(documentId);
    if (!state) {
      throw new Error(`Document ${documentId} not found`);
    }

    return {
      id: uuidv4(),
      documentId,
      version: state.version + 1,
      timestamp: Date.now(),
      userId,
      operations,
      checksum: this.calculateChecksum(state) // Current checksum, will be updated after applying
    };
  }

  /**
   * Get document state
   */
  getDocumentState(documentId: string): DocumentState | null {
    return this.documentStates.get(documentId) || null;
  }

  /**
   * Get document statistics
   */
  getDocumentStats(documentId: string): {
    version: number;
    nodeCount: number;
    edgeCount: number;
    lastModified: number;
    historyLength: number;
  } | null {
    const state = this.documentStates.get(documentId);
    if (!state) {
      return null;
    }

    const history = this.versionHistory.get(documentId) || [];

    return {
      version: state.version,
      nodeCount: state.nodes.size,
      edgeCount: state.edges.size,
      lastModified: state.lastModified,
      historyLength: history.length
    };
  }

  /**
   * Verify state integrity
   */
  verifyStateIntegrity(documentId: string): {
    valid: boolean;
    issues: string[];
    expectedChecksum: string;
    actualChecksum: string;
  } {
    const state = this.documentStates.get(documentId);
    if (!state) {
      return {
        valid: false,
        issues: ['Document not found'],
        expectedChecksum: '',
        actualChecksum: ''
      };
    }

    const issues: string[] = [];
    const expectedChecksum = this.calculateChecksum(state);

    // Check checksum
    if (state.checksum !== expectedChecksum) {
      issues.push('Checksum mismatch');
    }

    // Check node/edge references
    for (const [edgeId, edge] of state.edges) {
      if (edge.source && !state.nodes.has(edge.source)) {
        issues.push(`Edge ${edgeId} references non-existent source node ${edge.source}`);
      }
      if (edge.target && !state.nodes.has(edge.target)) {
        issues.push(`Edge ${edgeId} references non-existent target node ${edge.target}`);
      }
    }

    return {
      valid: issues.length === 0,
      issues,
      expectedChecksum,
      actualChecksum: state.checksum
    };
  }

  /**
   * Clean up old data
   */
  cleanup(): void {
    if (this.syncInterval) {
      clearInterval(this.syncInterval);
    }
    this.documentStates.clear();
    this.versionHistory.clear();
    this.pendingOperations.clear();
  }

  /**
   * Apply operation to state
   */
  private applyOperation(state: DocumentState, operation: StateOperation): void {
    switch (operation.target) {
      case 'node':
        this.applyNodeOperation(state, operation);
        break;
      case 'edge':
        this.applyEdgeOperation(state, operation);
        break;
      case 'metadata':
        this.applyMetadataOperation(state, operation);
        break;
    }
  }

  /**
   * Apply node operation
   */
  private applyNodeOperation(state: DocumentState, operation: StateOperation): void {
    switch (operation.type) {
      case 'create':
        if (state.nodes.has(operation.targetId)) {
          throw new Error(`Node ${operation.targetId} already exists`);
        }
        state.nodes.set(operation.targetId, operation.data);
        break;

      case 'update':
        if (!state.nodes.has(operation.targetId)) {
          throw new Error(`Node ${operation.targetId} does not exist`);
        }
        state.nodes.set(operation.targetId, operation.data);
        break;

      case 'delete':
        if (!state.nodes.has(operation.targetId)) {
          throw new Error(`Node ${operation.targetId} does not exist`);
        }
        state.nodes.delete(operation.targetId);

        // Remove connected edges
        for (const [edgeId, edge] of state.edges) {
          if (edge.source === operation.targetId || edge.target === operation.targetId) {
            state.edges.delete(edgeId);
          }
        }
        break;
    }
  }

  /**
   * Apply edge operation
   */
  private applyEdgeOperation(state: DocumentState, operation: StateOperation): void {
    switch (operation.type) {
      case 'create':
        if (state.edges.has(operation.targetId)) {
          throw new Error(`Edge ${operation.targetId} already exists`);
        }
        state.edges.set(operation.targetId, operation.data);
        break;

      case 'update':
        if (!state.edges.has(operation.targetId)) {
          throw new Error(`Edge ${operation.targetId} does not exist`);
        }
        state.edges.set(operation.targetId, operation.data);
        break;

      case 'delete':
        if (!state.edges.has(operation.targetId)) {
          throw new Error(`Edge ${operation.targetId} does not exist`);
        }
        state.edges.delete(operation.targetId);
        break;
    }
  }

  /**
   * Apply metadata operation
   */
  private applyMetadataOperation(state: DocumentState, operation: StateOperation): void {
    if (operation.type === 'update') {
      state.metadata = { ...state.metadata, ...operation.data };
    }
  }

  /**
   * Handle version conflict
   */
  private handleVersionConflict(update: StateUpdate, state: DocumentState): SyncResponse {
    // Return current state for client to resolve conflict
    return {
      documentId: update.documentId,
      currentVersion: state.version,
      clientVersion: update.version,
      syncType: 'full',
      state: this.cloneState(state),
      conflicts: ['version_conflict'],
      checksum: state.checksum
    };
  }

  /**
   * Generate delta between versions
   */
  private generateDelta(documentId: string, fromVersion: number, toVersion: number): StateDelta | null {
    const history = this.versionHistory.get(documentId);
    if (!history) {
      return null;
    }

    const operations: StateOperation[] = [];

    for (const update of history) {
      if (update.version > fromVersion && update.version <= toVersion) {
        operations.push(...update.operations);
      }
    }

    if (operations.length === 0) {
      return null;
    }

    const state = this.documentStates.get(documentId)!;

    return {
      fromVersion,
      toVersion,
      operations,
      timestamp: Date.now(),
      checksum: state.checksum
    };
  }

  /**
   * Add update to history and maintain size limit
   */
  private addToHistory(update: StateUpdate): void {
    let history = this.versionHistory.get(update.documentId);
    if (!history) {
      history = [];
      this.versionHistory.set(update.documentId, history);
    }

    history.push(update);

    // Maintain size limit
    if (history.length > this.config.maxVersionHistory) {
      history.splice(0, history.length - this.config.maxVersionHistory);
    }
  }

  /**
   * Calculate state checksum
   */
  private calculateChecksum(state: DocumentState): string {
    if (!this.config.checksumValidation) {
      return '';
    }

    // Simple checksum implementation - in production, use a proper hash function
    const data = {
      version: state.version,
      nodes: Array.from(state.nodes.entries()).sort(),
      edges: Array.from(state.edges.entries()).sort(),
      metadata: state.metadata
    };

    return Buffer.from(JSON.stringify(data)).toString('base64').slice(0, 16);
  }

  /**
   * Clone state for safe transmission
   */
  private cloneState(state: DocumentState): DocumentState {
    return {
      documentId: state.documentId,
      version: state.version,
      lastModified: state.lastModified,
      checksum: state.checksum,
      nodes: new Map(state.nodes),
      edges: new Map(state.edges),
      metadata: JSON.parse(JSON.stringify(state.metadata))
    };
  }

  /**
   * Start periodic sync process
   */
  private startSyncProcess(): void {
    this.syncInterval = setInterval(() => {
      this.processPendingOperations();
    }, this.config.syncInterval);
  }

  /**
   * Process pending operations
   */
  private processPendingOperations(): void {
    for (const [documentId, operations] of this.pendingOperations) {
      if (operations.length === 0) continue;

      const batch = operations.splice(0, this.config.maxSyncBatchSize);

      this.emit('sync_batch', {
        documentId,
        operations: batch,
        timestamp: Date.now()
      });
    }
  }
}

import { EventEmitter } from 'events';
import WebSocket from 'ws';
import { v4 as uuidv4 } from 'uuid';
import { ConnectionManager } from './ConnectionManager';
import { PresenceManager, PresenceConfig, UserPresenceData } from './PresenceManager';
import { ConflictResolver, ConflictResolverConfig, ConflictOperation, ConflictType } from './ConflictResolver';
import { SynchronizationManager, SyncManagerConfig, StateUpdate } from './SynchronizationManager';
import { 
  WSMessage, 
  WSMessageSchema, 
  WSServerConfig, 
  GraphUpdatePayload,
  PresenceUpdatePayload,
  AuthPayload,
  AuthPayloadSchema,
  GraphUpdatePayloadSchema,
  PresenceUpdatePayloadSchema
} from './types';

// Epic 13 Analytics Integration
import { AnalyticsCollector, AnalyticsEventType } from '../analytics/AnalyticsCollector';
import { AnalyticsDAO } from '../database/analytics-dao';
import { getDatabase } from '../database/connection';

export class WebSocketServer extends EventEmitter {
  private wss: WebSocket.Server | null = null;
  private connectionManager: ConnectionManager;
  private presenceManager: PresenceManager;
  private conflictResolver: ConflictResolver;
  private syncManager: SynchronizationManager;
  private config: WSServerConfig;
  private messageHandlers: Map<string, (connectionId: string, payload: any) => void> = new Map();

  // Epic 13 Analytics Integration
  public analyticsCollector: AnalyticsCollector | null = null;
  private analyticsDAO: AnalyticsDAO | null = null;

  constructor(config: WSServerConfig) {
    super();
    this.config = config;
    this.connectionManager = new ConnectionManager(config);

    // Initialize presence manager
    const presenceConfig: PresenceConfig = {
      idleTimeout: 30000, // 30 seconds
      awayTimeout: 300000, // 5 minutes
      offlineTimeout: 600000, // 10 minutes
      cleanupInterval: 60000, // 1 minute
      maxUsersPerDocument: 50,
      enableLocationSharing: true,
      enableActivityTracking: true,
      retainPresenceHistory: false,
      historyRetentionPeriod: 86400000 // 24 hours
    };
    this.presenceManager = new PresenceManager(presenceConfig);

    // Initialize conflict resolver
    const conflictConfig: ConflictResolverConfig = {
      defaultStrategy: 'last_writer_wins' as any,
      autoResolveThreshold: 5000, // 5 seconds
      maxConflictAge: 300000, // 5 minutes
      positionConflictThreshold: 50, // 50 pixels
      enableSemanticMerge: false,
      preserveConflictHistory: true,
      conflictHistoryRetention: 86400000 // 24 hours
    };
    this.conflictResolver = new ConflictResolver(conflictConfig);

    // Initialize synchronization manager
    const syncConfig: SyncManagerConfig = {
      maxVersionHistory: 100,
      deltaCompressionThreshold: 10,
      checksumValidation: true,
      conflictDetection: true,
      autoMerge: true,
      syncInterval: 1000, // 1 second
      maxSyncBatchSize: 50
    };
    this.syncManager = new SynchronizationManager(syncConfig);

    this.setupMessageHandlers();
    this.setupConnectionManagerEvents();
    this.setupPresenceManagerEvents();
    this.setupConflictResolverEvents();
    this.setupSyncManagerEvents();

    // Initialize analytics if enabled
    this.initializeAnalytics();
  }

  /**
   * Initialize analytics collection for WebSocket interactions
   */
  private initializeAnalytics(): void {
    try {
      const db = getDatabase();
      this.analyticsDAO = new AnalyticsDAO(db);

      this.analyticsCollector = new AnalyticsCollector({
        enabled: process.env.WS_ANALYTICS_ENABLED !== 'false',
        sampleRate: parseFloat(process.env.WS_ANALYTICS_SAMPLE_RATE || '1.0'),
        privacyMode: process.env.ANALYTICS_PRIVACY_MODE === 'true'
      });

      // Set up event storage handler
      this.analyticsCollector.on('events_flushed', (events) => {
        if (this.analyticsDAO) {
          events.forEach((event: any) => this.analyticsDAO.storeEvent(event));
        }
      });

      console.log('WebSocket analytics collection initialized');
    } catch (error) {
      console.error('Failed to initialize WebSocket analytics:', error);
    }
  }

  /**
   * Start the WebSocket server
   */
  start(server?: any): Promise<void> {
    return new Promise((resolve, reject) => {
      try {
        const wsOptions: WebSocket.ServerOptions = {
          port: server ? undefined : this.config.port,
          server: server || undefined,
          verifyClient: (info) => this.verifyClient(info)
        };

        this.wss = new WebSocket.Server(wsOptions);

        this.wss.on('connection', (ws, request) => {
          this.handleConnection(ws, request);
        });

        this.wss.on('error', (error) => {
          console.error('WebSocket server error:', error);
          this.emit('error', error);
        });

        console.log(`WebSocket server started on port ${this.config.port}`);
        this.emit('started');
        resolve();

      } catch (error) {
        reject(error);
      }
    });
  }

  /**
   * Stop the WebSocket server
   */
  stop(): Promise<void> {
    return new Promise((resolve) => {
      if (this.wss) {
        this.wss.close(() => {
          this.connectionManager.cleanup();
          this.presenceManager.cleanup();
          this.conflictResolver.cleanup();
          this.syncManager.cleanup();
          this.emit('stopped');
          resolve();
        });
      } else {
        resolve();
      }
    });
  }

  /**
   * Get server health metrics
   */
  getHealthMetrics() {
    return this.connectionManager.getHealthMetrics();
  }

  /**
   * Get presence statistics
   */
  getPresenceStats() {
    return this.presenceManager.getPresenceStats();
  }

  /**
   * Get document sessions info
   */
  getDocumentSessions() {
    const metrics = this.connectionManager.getHealthMetrics();
    return {
      activeDocuments: metrics.activeDocuments,
      totalConnections: metrics.totalConnections
    };
  }

  /**
   * Get users in a specific document
   */
  getDocumentUsers(documentId: string): UserPresenceData[] {
    return this.presenceManager.getDocumentUsers(documentId);
  }

  /**
   * Get conflict statistics
   */
  getConflictStats(documentId?: string) {
    return this.conflictResolver.getConflictStats(documentId);
  }

  /**
   * Get document synchronization stats
   */
  getDocumentSyncStats(documentId: string) {
    return this.syncManager.getDocumentStats(documentId);
  }

  /**
   * Initialize document for collaboration
   */
  initializeDocument(documentId: string, initialState?: any) {
    return this.syncManager.initializeDocument(documentId, initialState);
  }

  /**
   * Broadcast message to all connections in a document
   */
  broadcastToDocument(documentId: string, message: Omit<WSMessage, 'timestamp'>, excludeConnectionId?: string): void {
    const fullMessage: WSMessage = {
      ...message,
      timestamp: Date.now(),
      messageId: uuidv4(),
      documentId
    };

    this.connectionManager.broadcastToDocument(documentId, fullMessage, excludeConnectionId);
  }

  /**
   * Handle new WebSocket connection
   */
  private handleConnection(ws: WebSocket, request: any): void {
    const connectionId = this.connectionManager.addConnection(ws, request);

    console.log(`New WebSocket connection: ${connectionId}`);

    // Set up message handling
    ws.on('message', (data) => {
      this.handleMessage(connectionId, data);
    });

    // Send connection confirmation
    this.sendToConnection(connectionId, {
      type: 'connect',
      payload: { 
        connectionId,
        requiresAuthentication: this.config.enableAuthentication 
      }
    });
  }

  /**
   * Handle incoming WebSocket message
   */
  private handleMessage(connectionId: string, data: WebSocket.Data): void {
    try {
      const rawMessage = JSON.parse(data.toString());

      // Validate message format
      const message = WSMessageSchema.parse(rawMessage);

      // Update last seen time
      const connectionInfo = this.connectionManager.getConnectionInfo(connectionId);
      if (connectionInfo) {
        connectionInfo.lastSeen = Date.now();
      }

      // Route message to appropriate handler
      const handler = this.messageHandlers.get(message.type);
      if (handler) {
        handler(connectionId, message.payload);
      } else {
        console.warn(`No handler for message type: ${message.type}`);
      }

    } catch (error) {
      console.error(`Invalid message from connection ${connectionId}:`, error);

      this.sendToConnection(connectionId, {
        type: 'error',
        payload: { 
          error: 'Invalid message format',
          details: error instanceof Error ? error.message : String(error)
        }
      });
    }
  }

  /**
   * Send message to specific connection
   */
  private sendToConnection(connectionId: string, message: Omit<WSMessage, 'timestamp' | 'messageId'>): boolean {
    const fullMessage: WSMessage = {
      ...message,
      timestamp: Date.now(),
      messageId: uuidv4()
    };

    return this.connectionManager.sendToConnection(connectionId, fullMessage);
  }

  /**
   * Set up message handlers
   */
  private setupMessageHandlers(): void {
    // Authentication
    this.messageHandlers.set('auth_request', async (connectionId, payload) => {
      try {
        const authPayload = AuthPayloadSchema.parse(payload);
        const success = await this.connectionManager.authenticateConnection(connectionId, authPayload);

        // Track authentication event
        if (this.analyticsCollector) {
          this.analyticsCollector.recordUserInteraction(
            success ? AnalyticsEventType.USER_SESSION_START : AnalyticsEventType.ERROR_OCCURRENCE,
            authPayload.documentId || 'unknown',
            {
              connectionId,
              userId: authPayload.userId,
              authenticationSuccess: success,
              interactionType: 'authentication'
            }
          );
        }

        this.sendToConnection(connectionId, {
          type: 'auth_response',
          payload: { 
            success,
            message: success ? 'Authentication successful' : 'Authentication failed'
          }
        });

        if (success) {
          const connectionInfo = this.connectionManager.getConnectionInfo(connectionId);
          if (connectionInfo) {
            // Add user presence
            const presence = this.presenceManager.addUserPresence(
              connectionId,
              connectionInfo.userId,
              connectionInfo.documentId,
              {
                userName: authPayload.userName,
                userAvatar: authPayload.userAvatar,
                userAgent: connectionInfo.userAgent,
                platform: authPayload.platform
              }
            );

            // Send current users to the new user
            const existingUsers = this.presenceManager.getDocumentUsers(connectionInfo.documentId)
              .filter(user => user.connectionId !== connectionId);

            if (existingUsers.length > 0) {
              this.sendToConnection(connectionId, {
                type: 'presence_sync',
                payload: { users: existingUsers }
              });
            }

            // Notify other users in the document
            this.broadcastToDocument(connectionInfo.documentId, {
              type: 'user_join',
              payload: {
                userId: connectionInfo.userId,
                userName: presence.userName,
                userAvatar: presence.userAvatar,
                timestamp: Date.now()
              }
            }, connectionId);
          }
        }

      } catch (error) {
        this.sendToConnection(connectionId, {
          type: 'auth_response',
          payload: { 
            success: false,
            message: 'Invalid authentication payload'
          }
        });
      }
    });

    // Graph updates with conflict resolution
    this.messageHandlers.set('graph_update', (connectionId, payload) => {
      if (!this.connectionManager.hasPermission(connectionId, 'write')) {
        this.sendToConnection(connectionId, {
          type: 'error',
          payload: { error: 'Insufficient permissions for graph updates' }
        });
        return;
      }

      try {
        const updatePayload = GraphUpdatePayloadSchema.parse(payload);
        const connectionInfo = this.connectionManager.getConnectionInfo(connectionId);

        if (!connectionInfo || !connectionInfo.documentId) {
          return;
        }

        // Track graph update interaction
        if (this.analyticsCollector) {
          const interactionType = this.determineInteractionType(updatePayload);
          this.analyticsCollector.recordUserInteraction(
            interactionType,
            connectionInfo.documentId,
            {
              connectionId,
              userId: connectionInfo.userId,
              updateType: updatePayload.type,
              nodeId: updatePayload.nodeId,
              nodeType: updatePayload.nodeType,
              component: 'graph_editor',
              canvasPosition: updatePayload.position
            }
          );
        }

        // Initialize document if it doesn't exist
        this.syncManager.initializeDocument(connectionInfo.documentId);

        // Convert graph update to operations
        const operations = this.convertGraphUpdateToOperations(updatePayload, connectionInfo.userId);

        // Process each operation through conflict resolver
        for (const operation of operations) {
          const resolution = this.conflictResolver.processOperation(operation);

          if (resolution && resolution.requiresUserInput) {
            // Send conflict to user for resolution
            this.sendToConnection(connectionId, {
              type: 'conflict_detected',
              payload: {
                conflict: resolution.conflict,
                requiresResolution: true
              }
            });
          }
        }

        // Create state update
        const stateUpdate = this.syncManager.createStateUpdate(
          connectionInfo.documentId,
          operations,
          connectionInfo.userId
        );

        // Apply state update
        const syncResponse = this.syncManager.applyStateUpdate(stateUpdate);

        // Broadcast successful updates to other connections
        if (syncResponse.syncType === 'up_to_date') {
          this.broadcastToDocument(connectionInfo.documentId, {
            type: 'graph_update',
            payload: {
              ...updatePayload,
              version: syncResponse.currentVersion,
              conflicts: syncResponse.conflicts
            }
          }, connectionId);
        }

        // Send response to sender
        this.sendToConnection(connectionId, {
          type: 'graph_update_response',
          payload: {
            success: true,
            version: syncResponse.currentVersion,
            conflicts: syncResponse.conflicts
          }
        });

        // Emit event for persistence layer
        this.emit('graph_update', connectionInfo.documentId, updatePayload, connectionInfo);

      } catch (error) {
        this.sendToConnection(connectionId, {
          type: 'error',
          payload: { error: 'Invalid graph update payload' }
        });
      }
    });

    // Presence updates (cursor, selection, etc.)
    this.messageHandlers.set('presence_update', (connectionId, payload) => {
      try {
        const presencePayload = PresenceUpdatePayloadSchema.parse(payload);
        const connectionInfo = this.connectionManager.getConnectionInfo(connectionId);

        if (!connectionInfo || !connectionInfo.documentId) {
          return;
        }

        // Update presence in manager
        const updatedPresence = this.presenceManager.updateUserPresence(connectionId, {
          cursor: presencePayload.cursor,
          selection: presencePayload.selection ? {
            nodeIds: presencePayload.selection,
            edgeIds: [],
            selectionBox: undefined
          } : undefined
        });

        if (updatedPresence) {
          // Broadcast presence to other connections in the document
          this.broadcastToDocument(connectionInfo.documentId, {
            type: 'presence_update',
            payload: {
              userId: updatedPresence.userId,
              userName: updatedPresence.userName,
              cursor: updatedPresence.cursor,
              selection: updatedPresence.selection?.nodeIds || [],
              lastSeen: updatedPresence.lastSeen,
              status: updatedPresence.status
            }
          }, connectionId);
        }

      } catch (error) {
        this.sendToConnection(connectionId, {
          type: 'error',
          payload: { error: 'Invalid presence update payload' }
        });
      }
    });

    // Cursor position updates
    this.messageHandlers.set('cursor_update', (connectionId, payload) => {
      const { x, y, nodeId, viewportBounds } = payload;

      const updatedPresence = this.presenceManager.updateUserCursor(connectionId, {
        x, y, nodeId, viewportBounds
      });

      if (updatedPresence) {
        this.broadcastToDocument(updatedPresence.documentId, {
          type: 'cursor_update',
          payload: {
            userId: updatedPresence.userId,
            cursor: updatedPresence.cursor
          }
        }, connectionId);
      }
    });

    // Selection updates
    this.messageHandlers.set('selection_update', (connectionId, payload) => {
      const { nodeIds, edgeIds, selectionBox } = payload;

      const updatedPresence = this.presenceManager.updateUserSelection(connectionId, {
        nodeIds: nodeIds || [],
        edgeIds: edgeIds || [],
        selectionBox
      });

      if (updatedPresence) {
        this.broadcastToDocument(updatedPresence.documentId, {
          type: 'selection_update',
          payload: {
            userId: updatedPresence.userId,
            selection: updatedPresence.selection
          }
        }, connectionId);
      }
    });

    // Activity updates (typing, tool changes, etc.)
    this.messageHandlers.set('activity_update', (connectionId, payload) => {
      const { currentTool, isTyping, focusedNodeId } = payload;

      const updatedPresence = this.presenceManager.updateUserActivity(connectionId, {
        currentTool,
        isTyping,
        focusedNodeId
      });

      if (updatedPresence) {
        this.broadcastToDocument(updatedPresence.documentId, {
          type: 'activity_update',
          payload: {
            userId: updatedPresence.userId,
            currentTool: updatedPresence.currentTool,
            isTyping: updatedPresence.isTyping,
            focusedNodeId: updatedPresence.focusedNodeId
          }
        }, connectionId);
      }
    });

    // Request presence data for document
    this.messageHandlers.set('presence_request', (connectionId, payload) => {
      const connectionInfo = this.connectionManager.getConnectionInfo(connectionId);

      if (!connectionInfo?.documentId) {
        return;
      }

      const users = this.presenceManager.getDocumentUsers(connectionInfo.documentId)
        .filter(user => user.connectionId !== connectionId);

      this.sendToConnection(connectionId, {
        type: 'presence_sync',
        payload: { users }
      });
    });

    // Conflict resolution
    this.messageHandlers.set('resolve_conflict', (connectionId, payload) => {
      const { conflictId, strategy, userSelection } = payload;
      const connectionInfo = this.connectionManager.getConnectionInfo(connectionId);

      if (!connectionInfo || !this.connectionManager.hasPermission(connectionId, 'write')) {
        this.sendToConnection(connectionId, {
          type: 'error',
          payload: { error: 'Insufficient permissions to resolve conflicts' }
        });
        return;
      }

      const resolution = this.conflictResolver.resolveConflict(
        conflictId,
        strategy,
        userSelection,
        connectionInfo.userId
      );

      if (resolution) {
        // Apply resolution to document state
        if (resolution.operations.length > 0) {
          const stateUpdate = this.syncManager.createStateUpdate(
            connectionInfo.documentId,
            resolution.operations.map(op => ({
              id: op.id,
              type: 'update' as const,
              target: op.nodeId ? 'node' as const : 'edge' as const,
              targetId: op.nodeId || op.edgeId || '',
              data: op.newValue,
              oldData: op.oldValue,
              timestamp: op.timestamp
            })),
            connectionInfo.userId
          );

          this.syncManager.applyStateUpdate(stateUpdate);
        }

        // Broadcast resolution to other users
        this.broadcastToDocument(connectionInfo.documentId, {
          type: 'conflict_resolved',
          payload: {
            conflictId,
            resolution: resolution.resolvedValue,
            resolvedBy: connectionInfo.userId
          }
        });

        this.sendToConnection(connectionId, {
          type: 'conflict_resolution_response',
          payload: { success: true, resolution }
        });
      } else {
        this.sendToConnection(connectionId, {
          type: 'error',
          payload: { error: 'Failed to resolve conflict' }
        });
      }
    });

    // Document synchronization
    this.messageHandlers.set('sync_request', (connectionId, payload) => {
      const connectionInfo = this.connectionManager.getConnectionInfo(connectionId);

      if (!connectionInfo || !connectionInfo.documentId) {
        return;
      }

      try {
        const syncRequest = {
          documentId: connectionInfo.documentId,
          clientVersion: payload.clientVersion || 0,
          fullSync: payload.fullSync || false,
          checksum: payload.checksum
        };

        const syncResponse = this.syncManager.handleSyncRequest(syncRequest);

        this.sendToConnection(connectionId, {
          type: 'sync_response',
          payload: syncResponse
        });

      } catch (error) {
        this.sendToConnection(connectionId, {
          type: 'error',
          payload: { error: 'Sync request failed' }
        });
      }
    });

    // State verification
    this.messageHandlers.set('verify_state', (connectionId, payload) => {
      const connectionInfo = this.connectionManager.getConnectionInfo(connectionId);

      if (!connectionInfo || !connectionInfo.documentId) {
        return;
      }

      const integrity = this.syncManager.verifyStateIntegrity(connectionInfo.documentId);

      this.sendToConnection(connectionId, {
        type: 'state_verification_response',
        payload: integrity
      });
    });

    // Ping/Pong for heartbeat
    this.messageHandlers.set('ping', (connectionId, payload) => {
      this.sendToConnection(connectionId, {
        type: 'pong',
        payload: { timestamp: Date.now() }
      });
    });
  }

  /**
   * Set up connection manager events
   */
  private setupConnectionManagerEvents(): void {
    this.connectionManager.on('user_left_document', (documentId, connectionInfo) => {
      // Remove user presence
      this.presenceManager.removeUserPresence(connectionInfo.id);
    });
  }

  /**
   * Convert graph update payload to conflict operations
   */
  private convertGraphUpdateToOperations(updatePayload: GraphUpdatePayload, userId: string): ConflictOperation[] {
    const operations: ConflictOperation[] = [];

    for (const operation of updatePayload.operations) {
      const conflictOp: ConflictOperation = {
        id: uuidv4(),
        type: this.mapOperationTypeToConflictType(operation.type),
        nodeId: operation.nodeId,
        edgeId: operation.edgeId,
        property: operation.type.includes('update') ? 'properties' : undefined,
        oldValue: operation.oldValue || null,
        newValue: operation.data,
        userId,
        timestamp: operation.timestamp,
        documentId: updatePayload.documentId || ''
      };

      operations.push(conflictOp);
    }

    return operations;
  }

  /**
   * Map operation type to conflict type
   */
  private mapOperationTypeToConflictType(operationType: string): ConflictType {
    switch (operationType) {
      case 'node_add':
        return ConflictType.NODE_CREATION;
      case 'node_remove':
        return ConflictType.NODE_DELETION;
      case 'node_update':
        return ConflictType.NODE_PROPERTIES;
      case 'edge_add':
        return ConflictType.EDGE_CREATION;
      case 'edge_remove':
        return ConflictType.EDGE_DELETION;
      case 'edge_update':
        return ConflictType.EDGE_PROPERTIES;
      default:
        return ConflictType.NODE_PROPERTIES;
    }
  }

  /**
   * Set up conflict resolver events
   */
  private setupConflictResolverEvents(): void {
    this.conflictResolver.on('conflict_detected', (conflict) => {
      // Broadcast conflict to all users in the document
      this.broadcastToDocument(conflict.documentId, {
        type: 'conflict_notification',
        payload: {
          conflictId: conflict.id,
          type: conflict.type,
          description: conflict.description,
          requiresResolution: true
        }
      });
    });

    this.conflictResolver.on('conflict_auto_resolved', (resolution) => {
      // Broadcast auto-resolution
      this.broadcastToDocument(resolution.conflict.documentId, {
        type: 'conflict_auto_resolved',
        payload: {
          conflictId: resolution.conflict.id,
          resolution: resolution.resolvedValue,
          strategy: resolution.conflict.resolutionStrategy
        }
      });
    });

    this.conflictResolver.on('conflict_resolved', (resolution) => {
      // Conflict manually resolved - already handled in message handler
    });
  }

  /**
   * Set up synchronization manager events
   */
  private setupSyncManagerEvents(): void {
    this.syncManager.on('state_updated', (event) => {
      // Broadcast state changes to connected users
      this.broadcastToDocument(event.documentId, {
        type: 'state_updated',
        payload: {
          version: event.version,
          operationCount: event.operations.length,
          hasConflicts: event.conflicts.length > 0
        }
      });
    });

    this.syncManager.on('sync_batch', (batch) => {
      // Handle batch synchronization
      this.emit('sync_batch_processed', batch);
    });
  }

  /**
   * Set up presence manager events
   */
  private setupPresenceManagerEvents(): void {
    this.presenceManager.on('user_joined', (documentId, presence) => {
      // User presence is already broadcast in auth handler
    });

    this.presenceManager.on('user_left', (documentId, presence) => {
      // Notify other users that someone left
      this.broadcastToDocument(documentId, {
        type: 'user_leave',
        payload: {
          userId: presence.userId,
          userName: presence.userName,
          timestamp: Date.now()
        }
      });
    });

    this.presenceManager.on('user_status_changed', (documentId, presence, newStatus) => {
      // Broadcast status change to other users
      this.broadcastToDocument(documentId, {
        type: 'user_status_changed',
        payload: {
          userId: presence.userId,
          status: newStatus,
          timestamp: Date.now()
        }
      });
    });

    this.presenceManager.on('user_updated', (documentId, presence) => {
      // This is handled by specific update handlers above
    });
  }

  /**
   * Verify client connections (CORS, rate limiting, etc.)
   */
  private verifyClient(info: any): boolean {
    // Check origin
    const origin = info.origin;
    if (this.config.corsOrigins.length > 0 && !this.config.corsOrigins.includes(origin)) {
      console.warn(`Rejected connection from unauthorized origin: ${origin}`);
      return false;
    }

    // Check connection limit
    const currentConnections = this.connectionManager.getHealthMetrics().totalConnections;
    if (currentConnections >= this.config.maxConnections) {
      console.warn('Rejected connection: maximum connections reached');
      return false;
    }

    return true;
  }

  /**
   * Determine the analytics event type based on the graph update payload
   */
  private determineInteractionType(updatePayload: any): AnalyticsEventType {
    switch (updatePayload.type) {
      case 'node_created':
      case 'add_node':
        return AnalyticsEventType.NODE_CREATED;
      case 'node_updated':
      case 'update_node':
        return AnalyticsEventType.NODE_UPDATED;
      case 'node_deleted':
      case 'delete_node':
        return AnalyticsEventType.NODE_DELETED;
      case 'connection_created':
      case 'add_connection':
        return AnalyticsEventType.CONNECTION_CREATED;
      case 'connection_deleted':
      case 'delete_connection':
        return AnalyticsEventType.CONNECTION_DELETED;
      case 'canvas_pan':
      case 'canvas_zoom':
      case 'canvas_interaction':
        return AnalyticsEventType.CANVAS_INTERACTION;
      default:
        return AnalyticsEventType.CANVAS_INTERACTION;
    }
  }
}

import { ConflictResolver, ConflictResolverConfig, ConflictOperation, ConflictType, ResolutionStrategy } from '../ConflictResolver';

describe('ConflictResolver', () => {
  let resolver: ConflictResolver;
  let config: ConflictResolverConfig;

  beforeEach(() => {
    config = {
      defaultStrategy: ResolutionStrategy.LAST_WRITER_WINS,
      autoResolveThreshold: 1000, // 1 second for testing
      maxConflictAge: 5000, // 5 seconds for testing
      positionConflictThreshold: 50, // 50 pixels
      enableSemanticMerge: false,
      preserveConflictHistory: true,
      conflictHistoryRetention: 10000 // 10 seconds for testing
    };

    resolver = new ConflictResolver(config);
  });

  afterEach(() => {
    resolver.cleanup();
  });

  describe('conflict detection', () => {
    it('should not detect conflict for single operation', () => {
      const operation: ConflictOperation = {
        id: 'op1',
        type: ConflictType.NODE_POSITION,
        nodeId: 'node1',
        oldValue: { x: 0, y: 0 },
        newValue: { x: 100, y: 100 },
        userId: 'user1',
        timestamp: Date.now(),
        documentId: 'doc1'
      };

      const result = resolver.processOperation(operation);
      expect(result).toBeNull();
    });

    it('should detect position conflict', () => {
      const operation1: ConflictOperation = {
        id: 'op1',
        type: ConflictType.NODE_POSITION,
        nodeId: 'node1',
        oldValue: { x: 0, y: 0 },
        newValue: { x: 100, y: 100 },
        userId: 'user1',
        timestamp: Date.now(),
        documentId: 'doc1'
      };

      const operation2: ConflictOperation = {
        id: 'op2',
        type: ConflictType.NODE_POSITION,
        nodeId: 'node1',
        oldValue: { x: 0, y: 0 },
        newValue: { x: 120, y: 120 }, // Close position
        userId: 'user2',
        timestamp: Date.now() + 500, // Within threshold
        documentId: 'doc1'
      };

      resolver.processOperation(operation1);
      const result = resolver.processOperation(operation2);

      expect(result).toBeDefined();
      expect(result?.conflict.type).toBe(ConflictType.NODE_POSITION);
      expect(result?.conflict.operations).toHaveLength(2);
    });

    it('should detect property conflict', () => {
      const operation1: ConflictOperation = {
        id: 'op1',
        type: ConflictType.NODE_PROPERTIES,
        nodeId: 'node1',
        property: 'name',
        oldValue: 'Old Name',
        newValue: 'New Name 1',
        userId: 'user1',
        timestamp: Date.now(),
        documentId: 'doc1'
      };

      const operation2: ConflictOperation = {
        id: 'op2',
        type: ConflictType.NODE_PROPERTIES,
        nodeId: 'node1',
        property: 'name',
        oldValue: 'Old Name',
        newValue: 'New Name 2',
        userId: 'user2',
        timestamp: Date.now() + 500,
        documentId: 'doc1'
      };

      resolver.processOperation(operation1);
      const result = resolver.processOperation(operation2);

      expect(result).toBeDefined();
      expect(result?.conflict.type).toBe(ConflictType.NODE_PROPERTIES);
    });

    it('should not detect conflict for different nodes', () => {
      const operation1: ConflictOperation = {
        id: 'op1',
        type: ConflictType.NODE_POSITION,
        nodeId: 'node1',
        oldValue: { x: 0, y: 0 },
        newValue: { x: 100, y: 100 },
        userId: 'user1',
        timestamp: Date.now(),
        documentId: 'doc1'
      };

      const operation2: ConflictOperation = {
        id: 'op2',
        type: ConflictType.NODE_POSITION,
        nodeId: 'node2', // Different node
        oldValue: { x: 0, y: 0 },
        newValue: { x: 100, y: 100 },
        userId: 'user2',
        timestamp: Date.now() + 500,
        documentId: 'doc1'
      };

      resolver.processOperation(operation1);
      const result = resolver.processOperation(operation2);

      expect(result).toBeNull();
    });

    it('should not detect conflict for same user', () => {
      const operation1: ConflictOperation = {
        id: 'op1',
        type: ConflictType.NODE_POSITION,
        nodeId: 'node1',
