  describe('automatic resolution', () => {
    it('should auto-resolve with last writer wins', () => {
      const operation1: ConflictOperation = {
        id: 'op1',
        type: ConflictType.NODE_PROPERTIES,
        nodeId: 'node1',
        property: 'name',
        oldValue: 'Old',
