  describe('conflict management', () => {
    it('should get pending conflicts for document', () => {
      const operation1: ConflictOperation = {
        id: 'op1',
        type: ConflictType.NODE_PROPERTIES,
        nodeId: 'node1',
        property: 'name',
        oldValue: 'Old',
        newValue: 'First',
        userId: 'user1',
        timestamp: Date.now(),
        documentId: 'doc1'
      };

      const operation2: ConflictOperation = {
        id: 'op2',
