  constructor() {
    this.testSuites = new Map();
    this.testResults = [];
    this.config = {
      timeout: 30000,
      retries: 0,
      parallel: false,
      coverage: false,
      verbose: false
    };
  }

  async runTests(extensionPath, options = {}) {
    console.log(`🧪 Running tests for extension: ${extensionPath}`);

    this.config = { ...this.config, ...options };

    try {
      // Load extension manifest
      const manifest = this.loadManifest(extensionPath);

      // Discover test files
      const testFiles = this.discoverTests(extensionPath);

      if (testFiles.length === 0) {
        console.log('⚠️ No test files found');
        return { passed: 0, failed: 0, skipped: 0 };
      }

      console.log(`Found ${testFiles.length} test file(s)`);

      // Run tests
      const results = await this.executeTests(testFiles, manifest);

      // Generate report
      this.generateTestReport(results);

      return results.summary;

    } catch (error) {
      console.error(`Test execution failed: ${error.message}`);
      throw error;
    }
  }

  loadManifest(extensionPath) {
    const manifestPath = path.join(extensionPath, 'manifest.json');

    if (!fs.existsSync(manifestPath)) {
      throw new Error('Manifest file not found');
    }

    return JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
  }

  discoverTests(extensionPath) {
    const testFiles = [];
    const testDirs = [
      path.join(extensionPath, 'test'),
      path.join(extensionPath, 'tests'),
      path.join(extensionPath, '__tests__'),
      path.join(extensionPath, 'src', '__tests__')
    ];

    for (const testDir of testDirs) {
      if (fs.existsSync(testDir)) {
        this.walkTestDirectory(testDir, testFiles);
      }
    }

    return testFiles;
  }

  walkTestDirectory(dir, testFiles) {
    const files = fs.readdirSync(dir);

    for (const file of files) {
      const filePath = path.join(dir, file);
      const stat = fs.statSync(filePath);

      if (stat.isDirectory()) {
        this.walkTestDirectory(filePath, testFiles);
      } else if (this.isTestFile(file)) {
        testFiles.push(filePath);
      }
    }
  }

  isTestFile(filename) {
    return /\.(test|spec)\.(js|ts)$/.test(filename);
  }

  async executeTests(testFiles, manifest) {
    const results = {
      summary: { passed: 0, failed: 0, skipped: 0, total: 0 },
      tests: [],
      coverage: null,
      duration: 0
    };

    const startTime = Date.now();

    // Set up test environment
    await this.setupTestEnvironment(manifest);

    for (const testFile of testFiles) {
      console.log(`\n📝 Running ${path.basename(testFile)}`);

      try {
        const testResult = await this.runTestFile(testFile, manifest);
        results.tests.push(testResult);

        results.summary.passed += testResult.passed;
        results.summary.failed += testResult.failed;
        results.summary.skipped += testResult.skipped;
        results.summary.total += testResult.total;

      } catch (error) {
        console.error(`❌ Test file failed: ${error.message}`);
        results.tests.push({
          file: testFile,
          passed: 0,
          failed: 1,
          skipped: 0,
          total: 1,
          error: error.message,
          tests: []
        });
        results.summary.failed += 1;
        results.summary.total += 1;
      }
    }

    results.duration = Date.now() - startTime;

    // Generate coverage report if requested
    if (this.config.coverage) {
      results.coverage = await this.generateCoverageReport();
    }

    return results;
  }

  async setupTestEnvironment(manifest) {
    // Mock extension system APIs
    global.ExtensionSystem = {
      register: () => Promise.resolve(),
      unregister: () => Promise.resolve(),
      getExtension: () => null,
      isEnabled: () => true
    };

    // Mock console if not verbose
    if (!this.config.verbose) {
      global.originalConsole = console;
      console.log = () => {};
      console.warn = () => {};
      console.info = () => {};
    }

    // Set up test globals
    global.TEST_MANIFEST = manifest;
    global.TEST_CONFIG = this.config;
  }

  async runTestFile(testFile, manifest) {
    const testContext = {
      file: testFile,
      passed: 0,
      failed: 0,
      skipped: 0,
      total: 0,
      tests: [],
      duration: 0
    };

    const startTime = Date.now();

    try {
      // Load test file
      delete require.cache[require.resolve(testFile)];
      const testModule = require(testFile);

      // Run tests based on framework
      if (this.isJestTest(testFile)) {
        await this.runJestTest(testFile, testContext);
      } else if (this.isMochaTest(testFile)) {
        await this.runMochaTest(testFile, testContext);
      } else {
        await this.runCustomTest(testModule, testContext);
      }

    } catch (error) {
      testContext.failed += 1;
      testContext.total += 1;
      testContext.tests.push({
        name: 'Test file execution',
        status: 'failed',
        error: error.message,
        duration: 0
      });
    }

    testContext.duration = Date.now() - startTime;
    return testContext;
  }

  isJestTest(testFile) {
    const content = fs.readFileSync(testFile, 'utf8');
    return content.includes('describe(') || content.includes('test(') || content.includes('it(');
  }

  isMochaTest(testFile) {
    const content = fs.readFileSync(testFile, 'utf8');
    return content.includes('describe(') && content.includes('before(');
  }

  async runJestTest(testFile, testContext) {
    return new Promise((resolve, reject) => {
      const jest = spawn('npx', ['jest', testFile, '--json'], {
        cwd: path.dirname(testFile),
        stdio: ['pipe', 'pipe', 'pipe']
      });

      let output = '';
      let errorOutput = '';

      jest.stdout.on('data', (data) => {
        output += data.toString();
      });

      jest.stderr.on('data', (data) => {
        errorOutput += data.toString();
      });

      jest.on('close', (code) => {
        try {
          if (output) {
            const result = JSON.parse(output);
            this.parseJestResults(result, testContext);
          }
          resolve();
        } catch (error) {
          reject(new Error(`Jest execution failed: ${errorOutput}`));
        }
      });

      jest.on('error', (error) => {
        reject(new Error(`Failed to run Jest: ${error.message}`));
      });

      setTimeout(() => {
        jest.kill();
        reject(new Error('Test timeout'));
      }, this.config.timeout);
    });
  }

  parseJestResults(jestResult, testContext) {
    if (jestResult.testResults && jestResult.testResults.length > 0) {
      const fileResult = jestResult.testResults[0];

      testContext.passed = fileResult.numPassingTests || 0;
      testContext.failed = fileResult.numFailingTests || 0;
      testContext.skipped = fileResult.numPendingTests || 0;
      testContext.total = fileResult.numPassingTests + fileResult.numFailingTests + fileResult.numPendingTests;

      // Parse individual test results
      if (fileResult.assertionResults) {
        testContext.tests = fileResult.assertionResults.map(test => ({
          name: test.title,
          status: test.status,
          duration: test.duration || 0,
          error: test.failureMessages ? test.failureMessages.join('\n') : null
        }));
      }
    }
  }

  async runMochaTest(testFile, testContext) {
    return new Promise((resolve, reject) => {
      const mocha = spawn('npx', ['mocha', testFile, '--reporter', 'json'], {
        cwd: path.dirname(testFile),
        stdio: ['pipe', 'pipe', 'pipe']
      });

      let output = '';
      let errorOutput = '';

      mocha.stdout.on('data', (data) => {
        output += data.toString();
      });

      mocha.stderr.on('data', (data) => {
        errorOutput += data.toString();
      });

      mocha.on('close', (code) => {
        try {
          if (output) {
            const result = JSON.parse(output);
            this.parseMochaResults(result, testContext);
          }
          resolve();
        } catch (error) {
          reject(new Error(`Mocha execution failed: ${errorOutput}`));
        }
      });

      mocha.on('error', (error) => {
        reject(new Error(`Failed to run Mocha: ${error.message}`));
      });

      setTimeout(() => {
        mocha.kill();
        reject(new Error('Test timeout'));
      }, this.config.timeout);
    });
  }

  parseMochaResults(mochaResult, testContext) {
    testContext.passed = mochaResult.stats.passes || 0;
    testContext.failed = mochaResult.stats.failures || 0;
    testContext.skipped = mochaResult.stats.pending || 0;
    testContext.total = mochaResult.stats.tests || 0;

    // Parse individual test results
    if (mochaResult.tests) {
      testContext.tests = mochaResult.tests.map(test => ({
        name: test.title,
        status: test.pending ? 'skipped' : (test.err ? 'failed' : 'passed'),
        duration: test.duration || 0,
        error: test.err ? test.err.message : null
      }));
    }
  }

  async runCustomTest(testModule, testContext) {
    // Run custom test format
    if (typeof testModule.runTests === 'function') {
      const results = await testModule.runTests();

      testContext.passed = results.passed || 0;
      testContext.failed = results.failed || 0;
      testContext.skipped = results.skipped || 0;
      testContext.total = results.total || 0;
      testContext.tests = results.tests || [];

    } else {
      throw new Error('Custom test module must export a runTests function');
    }
  }

  async generateCoverageReport() {
    // Mock coverage report
    return {
      statements: 85.5,
      branches: 78.2,
      functions: 92.1,
      lines: 87.8,
      files: [
        {
          filename: 'src/index.ts',
          statements: 95.0,
          branches: 88.0,
          functions: 100.0,
          lines: 96.0
        }
      ]
    };
  }

  generateTestReport(results) {
    console.log('\n📊 Test Results');
    console.log('='.repeat(50));

    const { summary } = results;

    console.log(`Total: ${summary.total}`);
    console.log(`✅ Passed: ${summary.passed}`);
    console.log(`❌ Failed: ${summary.failed}`);
    console.log(`⏭️ Skipped: ${summary.skipped}`);
    console.log(`⏱️ Duration: ${results.duration}ms`);

    const successRate = summary.total > 0 ? (summary.passed / summary.total * 100).toFixed(1) : 0;
    console.log(`📈 Success Rate: ${successRate}%`);

    // Show failed tests
    if (summary.failed > 0) {
      console.log('\n❌ Failed Tests:');

      for (const testFile of results.tests) {
        if (testFile.failed > 0) {
          console.log(`\n📁 ${path.basename(testFile.file)}`);

          for (const test of testFile.tests) {
            if (test.status === 'failed') {
              console.log(`   ❌ ${test.name}`);
              if (test.error) {
                console.log(`      ${test.error.split('\n')[0]}`);
              }
            }
          }
        }
      }
    }

    // Show coverage if available
    if (results.coverage) {
      console.log('\n📋 Coverage Report:');
      console.log(`Statements: ${results.coverage.statements}%`);
      console.log(`Branches: ${results.coverage.branches}%`);
      console.log(`Functions: ${results.coverage.functions}%`);
      console.log(`Lines: ${results.coverage.lines}%`);
    }

    // Performance analysis
    this.generatePerformanceReport(results);

    // Recommendations
    this.generateTestRecommendations(results);
  }

  generatePerformanceReport(results) {
    console.log('\n⚡ Performance Analysis:');

    const slowTests = [];
    const totalDuration = results.duration;

    for (const testFile of results.tests) {
      for (const test of testFile.tests) {
        if (test.duration > 1000) {
          slowTests.push({
            name: test.name,
            file: testFile.file,
            duration: test.duration
          });
        }
      }
    }

    if (slowTests.length > 0) {
      console.log('🐌 Slow tests (>1s):');
      slowTests
        .sort((a, b) => b.duration - a.duration)
        .slice(0, 5)
        .forEach(test => {
          console.log(`   ${test.duration}ms - ${test.name}`);
        });
    } else {
      console.log('✅ All tests completed quickly');
    }

    const avgTestTime = results.summary.total > 0 ? totalDuration / results.summary.total : 0;
    console.log(`Average test time: ${avgTestTime.toFixed(1)}ms`);
  }

  generateTestRecommendations(results) {
    console.log('\n💡 Recommendations:');

    const recommendations = [];

    // Coverage recommendations
    if (results.coverage) {
      if (results.coverage.statements < 80) {
        recommendations.push('Increase test coverage to at least 80%');
      }
      if (results.coverage.branches < 70) {
        recommendations.push('Add more branch coverage tests');
      }
    } else {
      recommendations.push('Enable code coverage reporting');
    }

    // Test count recommendations
    const testCount = results.summary.total;
    if (testCount < 10) {
      recommendations.push('Add more comprehensive tests');
    }

    // Performance recommendations
    const avgDuration = results.duration / Math.max(results.summary.total, 1);
    if (avgDuration > 500) {
      recommendations.push('Optimize slow tests for better performance');
    }

    // Failure rate recommendations
    const failureRate = results.summary.total > 0 ? results.summary.failed / results.summary.total : 0;
    if (failureRate > 0.1) {
      recommendations.push('Fix failing tests to improve reliability');
    }

    if (recommendations.length === 0) {
      console.log('✅ Your test suite looks good!');
    } else {
      recommendations.forEach(rec => console.log(`   • ${rec}`));
    }
  }

  async runBenchmarks(extensionPath) {
    console.log(`📊 Running benchmarks for: ${extensionPath}`);

    const benchmarkFiles = this.discoverBenchmarks(extensionPath);

    if (benchmarkFiles.length === 0) {
      console.log('⚠️ No benchmark files found');
      return;
    }

    const results = [];

    for (const benchmarkFile of benchmarkFiles) {
      console.log(`\n🏃 Running ${path.basename(benchmarkFile)}`);

      try {
        const benchmarkResult = await this.runBenchmarkFile(benchmarkFile);
        results.push(benchmarkResult);

      } catch (error) {
        console.error(`❌ Benchmark failed: ${error.message}`);
      }
    }

    this.generateBenchmarkReport(results);
  }

  discoverBenchmarks(extensionPath) {
    const benchmarkFiles = [];
    const benchmarkDirs = [
      path.join(extensionPath, 'benchmarks'),
      path.join(extensionPath, 'bench')
    ];

    for (const benchmarkDir of benchmarkDirs) {
      if (fs.existsSync(benchmarkDir)) {
        this.walkBenchmarkDirectory(benchmarkDir, benchmarkFiles);
      }
    }

    return benchmarkFiles;
  }

  walkBenchmarkDirectory(dir, benchmarkFiles) {
    const files = fs.readdirSync(dir);

    for (const file of files) {
      const filePath = path.join(dir, file);
      const stat = fs.statSync(filePath);

      if (stat.isDirectory()) {
        this.walkBenchmarkDirectory(filePath, benchmarkFiles);
      } else if (file.includes('bench') || file.includes('perf')) {
        benchmarkFiles.push(filePath);
      }
    }
  }

  async runBenchmarkFile(benchmarkFile) {
    const startTime = performance.now();

    // Load benchmark
    delete require.cache[require.resolve(benchmarkFile)];
    const benchmarkModule = require(benchmarkFile);

    if (typeof benchmarkModule.runBenchmark !== 'function') {
      throw new Error('Benchmark module must export a runBenchmark function');
    }

    // Run benchmark multiple times
    const iterations = 100;
    const results = [];

    for (let i = 0; i < iterations; i++) {
      const iterationStart = performance.now();
      await benchmarkModule.runBenchmark();
      const iterationTime = performance.now() - iterationStart;
      results.push(iterationTime);
    }

    const totalTime = performance.now() - startTime;

    // Calculate statistics
    results.sort((a, b) => a - b);
    const min = results[0];
    const max = results[results.length - 1];
    const avg = results.reduce((sum, time) => sum + time, 0) / results.length;
    const median = results[Math.floor(results.length / 2)];
    const p95 = results[Math.floor(results.length * 0.95)];

    return {
      file: benchmarkFile,
      iterations,
      totalTime,
      stats: {
        min: min.toFixed(2),
        max: max.toFixed(2),
        avg: avg.toFixed(2),
        median: median.toFixed(2),
        p95: p95.toFixed(2)
      }
    };
  }

  generateBenchmarkReport(results) {
    console.log('\n📊 Benchmark Results');
    console.log('='.repeat(50));

    for (const result of results) {
      console.log(`\n📁 ${path.basename(result.file)}`);
      console.log(`Iterations: ${result.iterations}`);
      console.log(`Total time: ${result.totalTime.toFixed(2)}ms`);
      console.log(`Min: ${result.stats.min}ms`);
      console.log(`Max: ${result.stats.max}ms`);
      console.log(`Avg: ${result.stats.avg}ms`);
      console.log(`Median: ${result.stats.median}ms`);
      console.log(`P95: ${result.stats.p95}ms`);
    }
  }
}

// CLI Implementation
async function main() {
  const args = process.argv.slice(2);

  if (args.length === 0) {
    showUsage();
    return;
  }

  const command = args[0];
  const framework = new ExtensionTestFramework();

  switch (command) {
    case 'test':
      await handleTest(framework, args.slice(1));
      break;
    case 'benchmark':
      await handleBenchmark(framework, args.slice(1));
      break;
    case 'coverage':
      await handleCoverage(framework, args.slice(1));
      break;
    case 'help':
      showUsage();
      break;
    default:
      console.error(`Unknown command: ${command}`);
      showUsage();
      process.exit(1);
  }
}

async function handleTest(framework, args) {
  const extensionPath = args[0] || '.';
  const options = parseTestOptions(args.slice(1));

  try {
    const results = await framework.runTests(extensionPath, options);

    if (results.failed > 0) {
      process.exit(1);
    }
  } catch (error) {
    console.error(`Test execution failed: ${error.message}`);
    process.exit(1);
  }
}

async function handleBenchmark(framework, args) {
  const extensionPath = args[0] || '.';

  try {
    await framework.runBenchmarks(extensionPath);
  } catch (error) {
    console.error(`Benchmark execution failed: ${error.message}`);
    process.exit(1);
  }
}

async function handleCoverage(framework, args) {
  const extensionPath = args[0] || '.';
  const options = { ...parseTestOptions(args.slice(1)), coverage: true };

  try {
    await framework.runTests(extensionPath, options);
  } catch (error) {
    console.error(`Coverage analysis failed: ${error.message}`);
    process.exit(1);
  }
}

function parseTestOptions(args) {
  const options = {};

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];

    switch (arg) {
      case '--verbose':
        options.verbose = true;
        break;
      case '--coverage':
        options.coverage = true;
        break;
      case '--parallel':
        options.parallel = true;
        break;
      case '--timeout':
        options.timeout = parseInt(args[++i]) || 30000;
        break;
      case '--retries':
        options.retries = parseInt(args[++i]) || 0;
        break;
    }
  }

  return options;
}

function showUsage() {
  console.log(`
🧪 PromptSpaghetti Extension Test Framework

Usage:
  extension-test test [extension-path] [options]
  extension-test benchmark [extension-path]
  extension-test coverage [extension-path] [options]
  extension-test help

Commands:
  test [path]           Run extension tests
  benchmark [path]      Run performance benchmarks
  coverage [path]       Run tests with coverage analysis
  help                  Show this help message

Options:
  --verbose             Show detailed output
  --coverage            Generate coverage report
  --parallel            Run tests in parallel
  --timeout <ms>        Set test timeout (default: 30000)
  --retries <n>         Set retry count (default: 0)

Test Discovery:
  Automatically discovers test files in:
  - test/
  - tests/
  - __tests__/
  - src/__tests__/

Supported test frameworks:
  - Jest
  - Mocha
  - Custom (with runTests export)

Examples:
  extension-test test ./my-extension/
  extension-test test --verbose --coverage
  extension-test benchmark ./my-extension/

For more information, visit: https://docs.prompt-spaghetti.dev/extensions/testing/
`);
}

// Export for testing
if (require.main === module) {
  main();
}

module.exports = { ExtensionTestFramework };

#!/usr/bin/env node

/**
 * Extension Validator - Epic 8.4 Story 8.4.6
 * Validation utilities for extension development
 */

const fs = require('fs');
const path = require('path');

class ExtensionValidator {
  constructor() {
    this.errors = [];
    this.warnings = [];
    this.info = [];
  }

  async validateExtension(manifestPath) {
    console.log(`🔍 Validating extension: ${manifestPath}`);

    this.errors = [];
    this.warnings = [];
    this.info = [];

    try {
      // Load and validate manifest
      const manifest = this.loadManifest(manifestPath);

      // Run validation checks
      this.validateManifestStructure(manifest);
      this.validateDependencies(manifest, manifestPath);
      this.validatePermissions(manifest);
      this.validateSecurity(manifest);
      this.validateFiles(manifest, manifestPath);

      // Generate report
      this.generateReport(manifest);

      return {
        valid: this.errors.length === 0,
        errors: this.errors,
        warnings: this.warnings,
        info: this.info
      };

    } catch (error) {
      this.errors.push(`Failed to validate extension: ${error.message}`);
      return {
        valid: false,
        errors: this.errors,
        warnings: this.warnings,
        info: this.info
      };
    }
  }

  loadManifest(manifestPath) {
    if (!fs.existsSync(manifestPath)) {
      throw new Error(`Manifest file not found: ${manifestPath}`);
    }

    try {
      const content = fs.readFileSync(manifestPath, 'utf8');
      return JSON.parse(content);
    } catch (error) {
      throw new Error(`Invalid JSON in manifest: ${error.message}`);
    }
  }

  validateManifestStructure(manifest) {
    // Required fields
    const requiredFields = ['manifest_version', 'id', 'name', 'version', 'extension_type'];

    for (const field of requiredFields) {
      if (!manifest[field]) {
        this.errors.push(`Missing required field: ${field}`);
      }
    }

    // Validate manifest version
    if (manifest.manifest_version !== '1.0') {
      this.errors.push(`Unsupported manifest version: ${manifest.manifest_version}`);
    }

    // Validate extension ID
    if (manifest.id && !/^[a-z0-9-]+$/.test(manifest.id)) {
      this.errors.push('Extension ID must contain only lowercase letters, numbers, and hyphens');
    }

    // Validate version format (semantic versioning)
    if (manifest.version && !/^\d+\.\d+\.\d+/.test(manifest.version)) {
      this.errors.push('Version must follow semantic versioning (e.g., 1.0.0)');
    }

    // Validate extension type
    const validTypes = ['node', 'ui', 'transform', 'storage'];
    if (manifest.extension_type && !validTypes.includes(manifest.extension_type)) {
      this.errors.push(`Invalid extension type: ${manifest.extension_type}. Valid types: ${validTypes.join(', ')}`);
    }

    // Validate runtime configuration
    if (manifest.runtime) {
      if (!manifest.runtime.entry_point) {
        this.errors.push('Runtime entry_point is required');
      }

      if (manifest.extension_type === 'node' && !manifest.runtime.node_types) {
        this.warnings.push('Node extensions should specify node_types');
      }
    }

    // Validate UI configuration
    if (manifest.extension_type === 'ui' && !manifest.ui) {
      this.warnings.push('UI extensions should include ui configuration');
    }
  }

  validateDependencies(manifest, manifestPath) {
    if (manifest.dependencies) {
      // Check system version
      if (manifest.dependencies.system_version) {
        if (!/^[\^~]?\d+\.\d+\.\d+/.test(manifest.dependencies.system_version)) {
          this.warnings.push('System version should use semantic versioning with range indicators');
        }
      }

      // Check extension dependencies
      if (manifest.dependencies.extensions) {
        for (const [depId, version] of Object.entries(manifest.dependencies.extensions)) {
          if (!/^[\^~]?\d+\.\d+\.\d+/.test(version)) {
            this.warnings.push(`Extension dependency ${depId} should use semantic versioning`);
          }
        }
      }
    }

    // Check package.json consistency
    const packageJsonPath = path.join(path.dirname(manifestPath), 'package.json');
    if (fs.existsSync(packageJsonPath)) {
      try {
        const packageJson = JSON.parse(fs.readFileSync(packageJsonPath, 'utf8'));

        if (packageJson.name !== manifest.id) {
          this.warnings.push('package.json name should match manifest id');
        }

        if (packageJson.version !== manifest.version) {
          this.warnings.push('package.json version should match manifest version');
        }
      } catch (error) {
        this.warnings.push('Failed to read package.json for consistency check');
      }
    }
  }

  validatePermissions(manifest) {
    if (manifest.permissions) {
      const validPermissions = [
        'data-processing',
        'file-system-read',
        'file-system-write',
        'network',
        'ui-components',
        'extensions-api',
        'system-info',
        'data-storage'
      ];

      const dangerousPermissions = [
        'file-system-write',
        'network',
        'extensions-api',
        'system-info'
      ];

      for (const permission of manifest.permissions) {
        if (!validPermissions.includes(permission)) {
          this.warnings.push(`Unknown permission: ${permission}`);
        }

        if (dangerousPermissions.includes(permission)) {
          this.warnings.push(`Dangerous permission requested: ${permission}`);
        }
      }
    }
  }

  validateSecurity(manifest) {
    if (manifest.security) {
      // Validate CSP
      if (manifest.security.content_security_policy) {
        const csp = manifest.security.content_security_policy;

        if (csp.includes("'unsafe-eval'")) {
          this.warnings.push('Content Security Policy allows unsafe-eval');
        }

        if (csp.includes("'unsafe-inline'")) {
          this.warnings.push('Content Security Policy allows unsafe-inline');
        }

        if (!csp.includes('default-src') && !csp.includes('script-src')) {
          this.warnings.push('Content Security Policy should include default-src or script-src');
        }
      }

      // Validate sandbox
      if (manifest.security.sandbox) {
        if (!manifest.security.sandbox.enabled) {
          this.warnings.push('Sandbox is disabled - consider enabling for security');
        }
      } else {
        this.info.push('No sandbox configuration specified');
      }

      // Validate trusted domains
      if (manifest.security.trusted_domains) {
        for (const domain of manifest.security.trusted_domains) {
          if (domain === '*') {
            this.warnings.push('Wildcard trusted domain (*) is not recommended');
          }

          if (!this.isValidDomain(domain)) {
            this.warnings.push(`Invalid trusted domain format: ${domain}`);
          }
        }
      }
    } else {
      this.info.push('No security configuration specified');
    }
  }

  validateFiles(manifest, manifestPath) {
    const extensionDir = path.dirname(manifestPath);

    // Check if entry point exists
    if (manifest.runtime && manifest.runtime.entry_point) {
      const entryPointPath = path.join(extensionDir, manifest.runtime.entry_point);

      if (!fs.existsSync(entryPointPath)) {
        this.errors.push(`Entry point file not found: ${manifest.runtime.entry_point}`);
      }
    }

    // Check for TypeScript configuration
    const tsconfigPath = path.join(extensionDir, 'tsconfig.json');
    if (!fs.existsSync(tsconfigPath)) {
      this.warnings.push('No tsconfig.json found - TypeScript development recommended');
    }

    // Check for tests
    const testDirs = ['test', 'tests', '__tests__', 'src/__tests__'];
    const hasTests = testDirs.some(dir => 
      fs.existsSync(path.join(extensionDir, dir))
    );

    if (!hasTests) {
      this.warnings.push('No test directory found - testing is recommended');
    }

    // Check for README
    const readmeFiles = ['README.md', 'readme.md', 'README.txt'];
    const hasReadme = readmeFiles.some(file => 
      fs.existsSync(path.join(extensionDir, file))
    );

    if (!hasReadme) {
      this.warnings.push('No README file found - documentation is recommended');
    }
  }

  isValidDomain(domain) {
    // Basic domain validation
    const domainRegex = /^([a-zA-Z0-9-]+\.)*[a-zA-Z0-9-]+\.[a-zA-Z]{2,}$|^localhost$|^\d+\.\d+\.\d+\.\d+$/;
    return domainRegex.test(domain);
  }

  generateReport(manifest) {
    console.log('\n📊 Validation Report');
    console.log('='.repeat(50));

    console.log(`Extension: ${manifest.name || 'Unknown'}`);
    console.log(`ID: ${manifest.id || 'Unknown'}`);
    console.log(`Version: ${manifest.version || 'Unknown'}`);
    console.log(`Type: ${manifest.extension_type || 'Unknown'}`);

    console.log('\n🔍 Results:');

    if (this.errors.length === 0) {
      console.log('✅ No errors found');
    } else {
      console.log(`❌ ${this.errors.length} error(s) found:`);
      this.errors.forEach(error => console.log(`   • ${error}`));
    }

    if (this.warnings.length > 0) {
      console.log(`\n⚠️ ${this.warnings.length} warning(s):`);
      this.warnings.forEach(warning => console.log(`   • ${warning}`));
    }

    if (this.info.length > 0) {
      console.log(`\nℹ️ ${this.info.length} info item(s):`);
      this.info.forEach(info => console.log(`   • ${info}`));
    }

    // Security assessment
    this.generateSecurityAssessment(manifest);

    // Recommendations
    this.generateRecommendations(manifest);
  }

  generateSecurityAssessment(manifest) {
    console.log('\n🔒 Security Assessment:');

    let securityScore = 100;
    const securityIssues = [];

    // Check permissions
    if (manifest.permissions) {
      const dangerousPerms = manifest.permissions.filter(p => 
        ['file-system-write', 'network', 'extensions-api', 'system-info'].includes(p)
      );

      if (dangerousPerms.length > 0) {
        securityScore -= dangerousPerms.length * 15;
        securityIssues.push(`Requests ${dangerousPerms.length} dangerous permission(s)`);
      }
    }

    // Check CSP
    if (!manifest.security?.content_security_policy) {
      securityScore -= 20;
      securityIssues.push('No Content Security Policy defined');
    }

    // Check sandbox
    if (!manifest.security?.sandbox?.enabled) {
      securityScore -= 10;
      securityIssues.push('Sandbox not enabled');
    }

    // Check trusted domains
    if (manifest.security?.trusted_domains?.includes('*')) {
      securityScore -= 25;
      securityIssues.push('Uses wildcard trusted domain');
    }

    const securityLevel = securityScore >= 80 ? 'Good' : 
                         securityScore >= 60 ? 'Moderate' : 'Poor';

    console.log(`   Security Score: ${securityScore}/100 (${securityLevel})`);

    if (securityIssues.length > 0) {
      console.log('   Issues:');
      securityIssues.forEach(issue => console.log(`     • ${issue}`));
    }
  }

  generateRecommendations(manifest) {
    console.log('\n💡 Recommendations:');

    const recommendations = [];

    // Type-specific recommendations
    switch (manifest.extension_type) {
      case 'node':
        if (!manifest.runtime?.node_types) {
          recommendations.push('Specify node_types in runtime configuration');
        }
        break;
      case 'ui':
        if (!manifest.ui) {
          recommendations.push('Add ui configuration with themes or components');
        }
        break;
    }

    // Security recommendations
    if (!manifest.security?.sandbox?.enabled) {
      recommendations.push('Enable sandbox for enhanced security');
    }

    if (!manifest.security?.content_security_policy) {
      recommendations.push('Add Content Security Policy');
    }

    // Development recommendations
    if (!manifest.description) {
      recommendations.push('Add description to manifest');
    }

    if (!manifest.author) {
      recommendations.push('Add author information to manifest');
    }

    if (recommendations.length === 0) {
      console.log('   No recommendations - looks good! 🎉');
    } else {
      recommendations.forEach(rec => console.log(`   • ${rec}`));
    }
  }
}

// Performance profiler for extensions
class ExtensionProfiler {
  constructor() {
    this.metrics = {
      loadTime: null,
      initTime: null,
      activationTime: null,
      memoryUsage: null,
      performance: []
    };
  }

  async profileExtension(extensionPath) {
    console.log(`📊 Profiling extension: ${extensionPath}`);

    const startTime = performance.now();

    try {
      // Simulate extension loading
      const loadStart = performance.now();
      await this.simulateLoad(extensionPath);
      this.metrics.loadTime = performance.now() - loadStart;

      // Simulate initialization
      const initStart = performance.now();
      await this.simulateInit();
      this.metrics.initTime = performance.now() - initStart;

      // Simulate activation
      const activationStart = performance.now();
      await this.simulateActivation();
      this.metrics.activationTime = performance.now() - activationStart;

      // Memory usage
      this.metrics.memoryUsage = process.memoryUsage();

      const totalTime = performance.now() - startTime;

      this.generatePerformanceReport(totalTime);

    } catch (error) {
      console.error('Profiling failed:', error.message);
    }
  }

  async simulateLoad(extensionPath) {
    // Simulate file loading delay
    await new Promise(resolve => setTimeout(resolve, Math.random() * 100));
  }

  async simulateInit() {
    // Simulate initialization delay
    await new Promise(resolve => setTimeout(resolve, Math.random() * 50));
  }

  async simulateActivation() {
    // Simulate activation delay
    await new Promise(resolve => setTimeout(resolve, Math.random() * 30));
  }

  generatePerformanceReport(totalTime) {
    console.log('\n⚡ Performance Report');
    console.log('='.repeat(30));

    console.log(`Total Time: ${totalTime.toFixed(2)}ms`);
    console.log(`Load Time: ${this.metrics.loadTime.toFixed(2)}ms`);
    console.log(`Init Time: ${this.metrics.initTime.toFixed(2)}ms`);
    console.log(`Activation Time: ${this.metrics.activationTime.toFixed(2)}ms`);

    console.log('\n💾 Memory Usage:');
    console.log(`RSS: ${(this.metrics.memoryUsage.rss / 1024 / 1024).toFixed(2)} MB`);
    console.log(`Heap Used: ${(this.metrics.memoryUsage.heapUsed / 1024 / 1024).toFixed(2)} MB`);
    console.log(`Heap Total: ${(this.metrics.memoryUsage.heapTotal / 1024 / 1024).toFixed(2)} MB`);

    // Performance recommendations
    console.log('\n📈 Performance Recommendations:');

    if (this.metrics.loadTime > 100) {
      console.log('   • Load time is high - consider code splitting');
    }

    if (this.metrics.initTime > 50) {
      console.log('   • Initialization time is high - defer heavy operations');
    }

    if (this.metrics.activationTime > 30) {
      console.log('   • Activation time is high - optimize startup code');
    }

    if (this.metrics.memoryUsage.heapUsed > 50 * 1024 * 1024) {
      console.log('   • High memory usage detected - check for memory leaks');
    }
  }
}

// CLI Implementation
function main() {
  const args = process.argv.slice(2);

  if (args.length === 0) {
    showUsage();
    return;
  }

  const command = args[0];

  switch (command) {
    case 'validate':
      handleValidate(args.slice(1));
      break;
    case 'profile':
      handleProfile(args.slice(1));
      break;
    case 'help':
      showUsage();
      break;
    default:
      console.error(`Unknown command: ${command}`);
      showUsage();
      process.exit(1);
  }
}

async function handleValidate(args) {
  if (args.length === 0) {
    console.error('Usage: extension-validator validate <manifest.json>');
    process.exit(1);
  }

  const manifestPath = args[0];
  const validator = new ExtensionValidator();

  try {
    const result = await validator.validateExtension(manifestPath);

    if (!result.valid) {
      process.exit(1);
    }
  } catch (error) {
    console.error(`Validation failed: ${error.message}`);
    process.exit(1);
  }
}

async function handleProfile(args) {
  if (args.length === 0) {
    console.error('Usage: extension-validator profile <extension-path>');
    process.exit(1);
  }

  const extensionPath = args[0];
  const profiler = new ExtensionProfiler();

  try {
    await profiler.profileExtension(extensionPath);
  } catch (error) {
    console.error(`Profiling failed: ${error.message}`);
    process.exit(1);
  }
}

function showUsage() {
  console.log(`
🔍 PromptSpaghetti Extension Validator

Usage:
  extension-validator validate <manifest.json>
  extension-validator profile <extension-path>
  extension-validator help

Commands:
  validate <manifest>    Validate extension manifest and structure
  profile <path>         Profile extension performance
  help                   Show this help message

Examples:
  extension-validator validate ./manifest.json
  extension-validator profile ./my-extension/

Validation checks:
  ✓ Manifest structure and required fields
  ✓ Dependency specifications
  ✓ Permission usage
  ✓ Security configuration
  ✓ File structure
  ✓ Best practices compliance

For more information, visit: https://docs.prompt-spaghetti.dev/extensions/
`);
}

// Export for testing
if (require.main === module) {
  main();
}

module.exports = { ExtensionValidator, ExtensionProfiler };
